INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (420, 318, 20, 'Can you help me log on to my computer?', 'Sorry, you''ll need to call Technical Support.', 'A password with both letters and numbers.', 'That''s a useful software program.', NULL, 'A', 'Câu hỏi: Bạn có thể giúp tôi đăng nhập vào máy tính không?
