INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (421, 319, 21, 'What time do you think we''ll leave the Zoo?', 'Please go through the west gate.', 'Fifteen dollars for adults.', 'Some of the exhibit lines are quite long•', NULL, 'C', 'Câu hỏi: Bạn nghĩ chúng ta sẽ rời Sở thú lúc mấy giờ?
