INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (609, 456, 9, 'Who''s in charge of training the new salesperson?', 'Mr. Lee''s responsible for that.', 'Can I pay with my credit card?', 'There''s a sales event at the store.', NULL, 'A', 'Ai chịu trách nhiệm đào tạo nhân viên bán hàng mới?
