INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (619, 466, 19, 'Why haven''t the budget adjustments been made yet?', 'Because the accountant is on vacation.', 'I''ll update the event calendar.', 'How do I adjust the chair height?', NULL, 'A', 'Tại sao các điều chỉnh ngân sách vẫn chưa được thực hiện?
