INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (626, 473, 26, 'When will you be available to start the position?', 'I still have a month left of school.', 'It''s been here since last winter.', 'Of course I''d be willing to do that.', NULL, 'A', 'Khi nào bạn sẽ có thời gian để bắt đầu vị trí?
