INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (627, 474, 27, 'Isn''t tomorrow''s seminar about time management?', 'I hired a property manager.', 'Sure, we have plenty of time.', 'No, that one''s scheduled for next week.', NULL, 'C', 'Buổi hội thảo ngày mai không phải về quản lý thời gian sao?
