INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (810, 606, 10, 'What are they building near the shopping center?', 'On the eighteenth floor.', 'An apartment complex.', 'I shop there on the weekends.', NULL, 'B', 'Họ đang xây dựng gì gần trung tâm mua sắm?
