INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1211, 905, 11, 'Where is this shipment of supplies going?', 'Not until five o''clock.', 'It''s going to Texas.', 'We met on the ship.', NULL, 'B', 'Lô hàng vật tư này đang được vận chuyển đi đâu?
