INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1212, 906, 12, 'The new Peruvian restaurant is great isn''t it?', 'No it''s at gate eighteen.', 'Yeah the food is delicious.', 'A table for two please.', NULL, 'B', 'Nhà hàng Peru mới rất tuyệt phải không?
