INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1213, 907, 13, 'How did your presentation for the client go?', 'Our biggest customers.', 'Can I join you?', 'It went very well.', NULL, 'C', 'Bài thuyết trình của bạn cho khách hàng diễn ra như thế nào?
