INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1215, 909, 15, 'Do you want to talk after your conference call?', 'Actually, my call was canceled.', 'Some new employees.', 'The client in Chicago.', NULL, 'A', 'Bạn có muốn nói chuyện sau cuộc gọi hội nghị không?
