INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1219, 913, 19, 'Why don''t we invite an author to speak at our bookstore?', 'I''ll check the storage room.', 'Some microphones and loudspeakers.', 'My friend just had a novel published.', NULL, 'C', 'Tại sao chúng ta không mời một tác giả nói chuyện tại cửa hàng sách của chúng ta?
