INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1051, 51, '2022/test8/audio/test8_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1408, 1051, 8, 'Would you like to meet the new clients?', 'It was made of wood.', 'The new setup process.', 'Sure, I have some time right now.', NULL, 'C', 'Bạn có muốn gặp các khách hàng mới không?
A. Nó được làm bằng gỗ.
B. Quy trình thiết lập mới.
C. Chắc chắn, tôi có chút thời gian ngay bây giờ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1052, 51, '2022/test8/audio/test8_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1409, 1052, 9, 'Here''s my presentation proposal.', 'About an hour ago.', 'Thanks, I''ll look over it shortly.', 'Did you like your present?', NULL, 'B', 'Đây là đề xuất thuyết trình của tôi.
A. Khoảng một giờ trước.
B. Cảm ơn, tôi sẽ xem qua nó ngay.
C. Bạn có thích món quà của bạn không?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1053, 51, '2022/test8/audio/test8_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1410, 1053, 10, 'Do the city buses stop in the front or the back of the city hall building?', 'A city council meeting.', 'There''s a stop in the front.', 'A monthly bus pass.', NULL, 'B', 'Xe buýt thành phố dừng ở phía trước hay phía sau tòa nhà hội đồng thành phố?
A. Một cuộc họp hội đồng thành phố.
B. Có một điểm dừng ở phía trước.
C. Một thẻ xe buýt hàng tháng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1054, 51, '2022/test8/audio/test8_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1411, 1054, 11, 'Why is the ceremony being moved indoors?', 'It was nice seeing her there.', 'Because there''s rain in the forecast.', 'I''ll hold the door for you.', NULL, 'B', 'Tại sao buổi lễ lại được chuyển vào trong nhà?
A. Thật vui khi được gặp cô ấy ở đó.
B. Bởi vì có mưa trong dự báo.
C. Tôi sẽ giữ cửa cho bạn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1055, 51, '2022/test8/audio/test8_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1412, 1055, 12, 'I just love the taste of coffee, don''t you?', 'About five minutes ago.', 'A teaspoon of sugar.', 'I always drink tea.', NULL, 'C', 'Tôi chỉ yêu thích hương vị của cà phê, bạn không?
A. Khoảng năm phút trước.
B. Một thìa cà phê đường.
C. Tôi luôn uống trà.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1056, 51, '2022/test8/audio/test8_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1413, 1056, 13, 'Are you interested in a freelance translation job?', 'An interest-free loan.', 'Please don''t touch the walls.', 'No, I''m too busy these days.', NULL, 'C', 'Bạn có quan tâm đến một công việc dịch thuật tự do không?
A. Một khoản vay không lãi.
B. Xin đừng chạm vào các bức tường.
C. Không, tôi quá bận những ngày này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1057, 51, '2022/test8/audio/test8_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1414, 1057, 14, 'Could you send me this month''s maintenance schedule?', 'I''d be happy to.', 'No, he left in January.', 'You should use the stairs.', NULL, 'A', 'Bạn có thể gửi cho tôi lịch bảo trì của tháng này không?
A. Tôi rất sẵn lòng.
B. Không, anh ấy đã rời đi vào tháng Giêng.
C. Bạn nên sử dụng cầu thang.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1058, 51, '2022/test8/audio/test8_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1415, 1058, 15, 'Doesn''t our firm reimburse travel expenses?', 'Yes, but only flight and hotel.', 'No, Friday doesn''t work.', 'It''s arriving at Gate 206.', NULL, 'A', 'Công ty chúng ta không hoàn trả chi phí đi lại sao?
A. Vâng, nhưng chỉ có vé máy bay và khách sạn.
B. Không, thứ Sáu thì không phù hợp.
C. Nó đang đến cổng 206.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1059, 51, '2022/test8/audio/test8_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1416, 1059, 16, 'I need to stop at the pharmacy on my way to work.', 'It''s a large dairy farm.', 'Her résumé was very impressive.', 'Oh, could you buy something for me?', NULL, 'C', 'Tôi cần dừng lại ở hiệu thuốc trên đường đến chỗ làm.
A. Đó là một trang trại sữa lớn.
B. Hồ sơ xin việc của cô ấy rất ấn tượng.
C. Ồ, bạn có thể mua thứ gì đó cho tôi không?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1060, 51, '2022/test8/audio/test8_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1417, 1060, 17, 'Why are we meeting to discuss the budget?', 'Have you seen last quarter''s sales figures?', 'Next Tuesday at two o''clock.', 'I''d like to, but it''s expensive.', NULL, 'A', 'Tại sao chúng ta lại gặp nhau để thảo luận về ngân sách?
A. Bạn đã xem số liệu bán hàng quý trước chưa?
B. Thứ Ba tới lúc hai giờ.
C. Tôi muốn, nhưng nó đắt quá.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1061, 51, '2022/test8/audio/test8_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1418, 1061, 18, 'When does your flight land in Los Angeles?', 'Yes, it''s finished.', 'I''m flying into San Francisco.', 'They bought a plot of land.', NULL, 'B', 'Chuyến bay của bạn hạ cánh ở Los Angeles khi nào?
A. Vâng, nó đã hoàn thành.
B. Tôi đang bay đến San Francisco.
C. Họ đã mua một mảnh đất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1062, 51, '2022/test8/audio/test8_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1419, 1062, 19, 'How do I sign up for the accounting webinar?', 'You can do that online.', 'No, it''s not too far.', 'I like the Web design.', NULL, 'A', 'Làm thế nào để tôi đăng ký tham gia hội thảo trên web về kế toán?
A. Bạn có thể làm điều đó trực tuyến.
B. Không, nó không quá xa.
C. Tôi thích thiết kế Web.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1063, 51, '2022/test8/audio/test8_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1420, 1063, 20, 'What kind of food should I bring to the company picnic?', 'They hired a catering service this year.', 'Yes, Barbara will be at the meeting.', 'A part on Grand Street.', NULL, 'A', 'Tôi nên mang loại thức ăn nào đến buổi dã ngoại công ty?
A. Họ đã thuê một dịch vụ ăn uống năm nay.
B. Vâng, Barbara sẽ tham gia cuộc họp.
C. Một phần trên phố Grand.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1064, 51, '2022/test8/audio/test8_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1421, 1064, 21, 'Where did you put my copy of our project proposal?', 'Actually, only the chairs are in color.', 'It''s in the file cabinet.', 'The company newsletter.', NULL, 'B', 'Bạn đã để bản sao đề xuất dự án của tôi ở đâu?
A. Thực ra, chỉ có ghế được màu.
B. Nó ở trong tủ hồ sơ.
C. Bản tin công ty.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1065, 51, '2022/test8/audio/test8_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1422, 1065, 22, 'How many more deliveries are we expecting today?', 'It was a great turnout.', 'I can wait for them if you need to leave.', 'No, it should be less than that.', NULL, 'B', 'Chúng ta đang mong đợi bao nhiêu lô hàng nữa hôm nay?
A. Đó là một lượng người tham gia tuyệt vời.
B. Tôi có thể đợi họ nếu bạn cần rời đi.
C. Không, nó nên ít hơn như vậy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1066, 51, '2022/test8/audio/test8_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1423, 1066, 23, 'When are we handing out the employee survey?', 'On a scale of one to ten.', 'Have a seat in the front row.', 'Probably at the end of the quarter.', NULL, 'C', 'Khi nào chúng ta sẽ phát bảng khảo sát nhân viên?
A. Trên thang đo từ một đến mười.
B. Hãy ngồi ở hàng ghế đầu.
C. Có lẽ vào cuối quý.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1067, 51, '2022/test8/audio/test8_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1424, 1067, 24, 'Would you like to send your sample of the fabrics we have available?', 'The hotel room is available.', 'They built a brick wall around the garden.', 'I saw the pictures on your Web site.', NULL, 'C', 'Bạn có muốn gửi mẫu vải mà chúng tôi có sẵn không?
A. Phòng khách sạn có sẵn.
B. Họ đã xây một bức tường gạch xung quanh khu vườn.
C. Tôi đã thấy các bức ảnh trên trang Web của bạn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1068, 51, '2022/test8/audio/test8_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1425, 1068, 25, 'Her contract ends next month, doesn''t it?', 'I''m sure it will get renewed.', 'Please sign at the bottom.', 'The employee orientation.', NULL, 'A', 'Hợp đồng của cô ấy kết thúc vào tháng tới, phải không?
A. Tôi chắc chắn nó sẽ được gia hạn.
B. Xin vui lòng ký ở dưới.
C. Định hướng nhân viên.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1069, 51, '2022/test8/audio/test8_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1426, 1069, 26, 'Should we open the store at eight thirty or nine on Saturday?', 'Since it''s a holiday, let''s open later.', 'I''ve never been there before.', 'That sign on the door.', NULL, 'A', 'Chúng ta có nên mở cửa hàng vào tám giờ rưỡi hay chín giờ vào thứ Bảy không?
A. Vì là ngày lễ, hãy mở cửa muộn hơn.
B. Tôi chưa bao giờ đến đó trước đây.
C. Dấu hiệu đó trên cửa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1070, 51, '2022/test8/audio/test8_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1427, 1070, 27, 'What kinds of audiobooks do you listen to?', 'Could you turn the volume down please?', 'Yes, an auto repair shop.', 'I like mystery novels.', NULL, 'C', 'Bạn nghe những loại sách nói nào?
A. Bạn có thể giảm âm lượng xuống được không?
B. Vâng, một cửa hàng sửa chữa ô tô.
C. Tôi thích tiểu thuyết trinh thám.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1071, 51, '2022/test8/audio/test8_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1428, 1071, 28, 'How long will it take to receive a confirmation e-mail?', 'It should take more than a few minutes.', 'The construction noise is getting worse.', 'The color will fade in direct sunlight.', NULL, 'A', 'Sẽ mất bao lâu để nhận được email xác nhận?
A. Nó nên mất hơn vài phút.
B. Tiếng ồn xây dựng đang trở nên tồi tệ hơn.
C. Màu sẽ phai dưới ánh sáng mặt trời trực tiếp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1072, 51, '2022/test8/audio/test8_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1429, 1072, 29, 'Where should I have the workers stack the cases when they arrive?', 'Tomorrow at the latest.', 'I''ll be there to supervise.', 'It was a challenging legal case.', NULL, 'B', 'Tôi nên để công nhân xếp các thùng khi chúng đến ở đâu?
A. Ngày mai là muộn nhất.
B. Tôi sẽ ở đó để giám sát.
C. Đó là một vụ án pháp lý đầy thách thức.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1073, 51, '2022/test8/audio/test8_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1430, 1073, 30, 'Would offering more special breads attract more customers?', 'Please turn off the lights.', 'No thanks, I''ve already eaten.', 'That could get expensive.', NULL, 'C', 'Việc cung cấp nhiều loại bánh đặc biệt hơn có thu hút thêm khách hàng không?
A. Xin hãy tắt đèn.
B. Không cảm ơn, tôi đã ăn rồi.
C. Điều đó có thể trở nên đắt đỏ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1074, 51, '2022/test8/audio/test8_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1431, 1074, 31, 'Who''s going with you to the technology convention?', 'Thanks, I''d appreciate that.', 'Management budgeted for only one attendee.', 'It''s a great product.', NULL, 'B', 'Ai sẽ đi cùng bạn đến hội nghị công nghệ?
A. Cảm ơn, tôi rất trân trọng điều đó.
B. Ban quản lý chỉ dự tính cho một người tham dự.
C. Nó là một sản phẩm tuyệt vời.');;

