INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1603, 1195, 3, NULL, 'One of the women is leaning over a trash can.', 'One of the women is looking at a post on a bulletin board.', 'One of the women is standing next to an entrance.', 'One of the women is counting money from a machine.', 'B', 'A. Một trong những phụ nữ đang nghiêng người qua thùng rác.
B. Một trong những phụ nữ đang nhìn vào một bài đăng trên bảng thông báo.
C. Một trong những phụ nữ đang đứng bên cạnh một lối vào.
D. Một trong những phụ nữ đang đếm tiền từ một máy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1196, 57, '2022/test9/audio/test9_question_4.mp3', '2022/test9/image/test9-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1604, 1196, 4, NULL, 'A car has been parked beside a building.', 'A door has been propped open.', 'There''s a sign posted on a fence.', 'Some plants have been arranged in a row.', 'A', 'A. Một chiếc ô tô đã được đậu bên cạnh một tòa nhà.
B. Một cánh cửa đã được để mở.
C. Có một biển hiệu đã được đăng trên hàng rào.
D. Một số cây đã được sắp xếp thành hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1197, 57, '2022/test9/audio/test9_question_5.mp3', '2022/test9/image/test9-image-5.jpg', NULL, NULL);;
