INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1606, 1198, 6, NULL, 'A vehicle is covered in snow.', 'Some equipment is leaning against a truck.', 'He''s driving a vehicle through some snow.', 'He''s closing the back of a truck.', 'B', 'A. Một phương tiện đang bị phủ đầy tuyết.
