INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1625, 1217, 25, 'Don''t you want to come with us to the art gallery opening tonight?', 'I have a presentation tomorrow morning.', 'The prices are marked on the frames.', 'Leave it closed, please.', NULL, 'A', 'Bạn không muốn đi cùng chúng tôi đến buổi khai trương phòng triển lãm nghệ thuật tối nay sao?
