INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1354, 65, '2022/test10/audio/test10_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1813, 1354, 13, 'Why are you still at the office?', 'Because my meeting ran late.', 'Please leave it with my assistant.', 'The room at the end of the hall.', NULL, 'A', 'Tại sao bạn vẫn ở văn phòng?
A. Bởi vì cuộc họp của tôi bị trễ.
B. Xin vui lòng để nó với trợ lý của tôi.
C. Phòng ở cuối hành lang.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1355, 65, '2022/test10/audio/test10_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1814, 1355, 14, 'Doesn''t the art exhibit open today?', 'No, not until next week.', 'Sure, you can leave it open.', 'Many local artists.', NULL, 'A', 'Triển lãm nghệ thuật không mở cửa hôm nay sao?
A. Không, chưa đến tuần tới.
B. Chắc chắn, bạn có thể để mở cửa.
C. Nhiều nghệ sĩ địa phương.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1356, 65, '2022/test10/audio/test10_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1815, 1356, 15, 'When did Takumi start working here?', 'I think it was a year ago.', 'Since my computer isn''t working.', 'No, he retired last month.', NULL, 'A', 'Khi nào Takumi bắt đầu làm việc ở đây?
A. Tôi nghĩ là một năm trước.
B. Kể từ khi máy tính của tôi không hoạt động.
C. Không, anh ấy đã nghỉ hưu tháng trước.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1357, 65, '2022/test10/audio/test10_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1816, 1357, 16, 'We still sell this brand of washing machine, don''t we?', 'I appreciate the help.', 'Yes, there are some in stock.', 'Adjust the temperature setting.', NULL, 'B', 'Chúng tôi vẫn bán thương hiệu máy giặt này, phải không?
A. Tôi đánh giá cao sự giúp đỡ.
B. Vâng, có một số hàng trong kho.
C. Điều chỉnh cài đặt nhiệt độ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1358, 65, '2022/test10/audio/test10_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1817, 1358, 17, 'Haven''t you finished the report yet?', 'The deadline''s been extended.', 'Usually once a week.', 'That would help, thanks.', NULL, 'A', 'Bạn vẫn chưa hoàn thành báo cáo phải không?
A. Hạn chót đã được gia hạn.
B. Thường là một lần một tuần.
C. Điều đó sẽ giúp ích, cảm ơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1359, 65, '2022/test10/audio/test10_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1818, 1359, 18, 'Do you want to fly or drive to the trade show?', 'The new French film is showing tonight.', 'That''s a positive trend.', 'Where is it this year?', NULL, 'C', 'Bạn muốn bay hay lái xe đến triển lãm thương mại?
A. Bộ phim Pháp mới đang chiếu tối nay.
B. Đó là một xu hướng tích cực.
C. Năm nay nó ở đâu?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1360, 65, '2022/test10/audio/test10_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1819, 1360, 19, 'Who''s leading the focus group meeting on Friday?', 'In the second-floor conference room.', 'John is making those assignments.', 'At the management seminar.', NULL, 'B', 'Ai đang dẫn dắt cuộc họp nhóm trọng điểm vào thứ Sáu?
A. Trong phòng họp tầng hai.
B. John đang thực hiện những phân công đó.
C. Tại hội thảo quản lý.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1361, 65, '2022/test10/audio/test10_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1820, 1361, 20, 'Why don''t we create some videos for interns?', 'It was very creative.', 'Sure, let''s work on that.', 'A review of our television show.', NULL, 'B', 'Tại sao chúng ta không tạo một số video cho thực tập sinh?
A. Nó rất sáng tạo.
B. Chắc chắn, hãy cùng làm việc đó.
C. Một bài đánh giá về chương trình truyền hình của chúng ta.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1362, 65, '2022/test10/audio/test10_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1821, 1362, 21, 'Prackwood Bank has extended business hours today, doesn''t it?', 'My extension is 204.', 'Small business loans.', 'Only at the Main Street location.', NULL, 'C', 'Ngân hàng Prackwood đã mở rộng giờ làm việc hôm nay, phải không?
A. Phòng mở rộng của tôi là 204.
B. Các khoản vay kinh doanh nhỏ.
C. Chỉ tại địa điểm Main Street.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1363, 65, '2022/test10/audio/test10_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1822, 1363, 22, 'When do concert tickets go on sale?', 'They''re already sold out.', 'At the ticket office.', 'That''s a good price.', NULL, 'A', 'Vé hòa nhạc được bán ra khi nào?
A. Chúng đã hết hàng rồi.
B. Tại phòng vé.
C. Đó là một mức giá tốt.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1364, 65, '2022/test10/audio/test10_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1823, 1364, 23, 'Has anyone volunteered to organize the reception?', 'The event''s been canceled.', 'Sorry, I don''t have a receipt.', 'It is a well-known organization.', NULL, 'A', 'Có ai tình nguyện tổ chức buổi tiếp tân không?
A. Sự kiện đã bị hủy.
B. Xin lỗi, tôi không có biên lai.
C. Nó là một tổ chức nổi tiếng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1365, 65, '2022/test10/audio/test10_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1824, 1365, 24, 'How do I turn off the copy machine?', 'I still need to make a few copies.', 'At the traffic light.', 'Yes, the machine is new.', NULL, 'A', 'Làm thế nào để tắt máy photocopy?
A. Tôi vẫn cần làm vài bản sao.
B. Tại đèn giao thông.
C. Vâng, máy mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1366, 65, '2022/test10/audio/test10_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1825, 1366, 25, 'I am calling to make an appointment with a physical therapist.', 'Yes, that is my home address.', 'A lot of exercise.', 'OK - your options are next Monday or Tuesday.', NULL, 'C', 'Tôi đang gọi để đặt cuộc hẹn với một nhà vật lý trị liệu.
A. Vâng, đó là địa chỉ nhà của tôi.
B. Nhiều bài tập.
C. OK - lựa chọn của bạn là thứ Hai hoặc thứ Ba tuần tới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1367, 65, '2022/test10/audio/test10_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1826, 1367, 26, 'Our fabric shipment hasn''t arrived yet, has it?', 'A large number of orders.', 'There''s a printer on my desk.', 'I''ll call our supplier now.', NULL, 'C', 'Lô hàng vải của chúng tôi vẫn chưa đến, phải không?
A. Một số lượng lớn đơn đặt hàng.
B. Có một máy in trên bàn làm việc của tôi.
C. Tôi sẽ gọi cho nhà cung cấp của chúng tôi ngay bây giờ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1368, 65, '2022/test10/audio/test10_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1827, 1368, 27, 'Did you send all staff the revised vacation policy?', 'You''ll need a visitor badge to enter the building.', 'Our computer has been down all morning.', 'A two-week trip to Boston.', NULL, 'B', 'Bạn đã gửi chính sách nghỉ phép đã được sửa đổi cho tất cả nhân viên chưa?
A. Bạn sẽ cần một thẻ khách để vào tòa nhà.
B. Máy tính của chúng tôi đã bị hỏng suốt cả buổi sáng.
C. Một chuyến đi hai tuần đến Boston.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1369, 65, '2022/test10/audio/test10_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1828, 1369, 28, 'What''s the telephone number for Primavera restaurant?', 'It''s closed for renovations.', 'Chicken or pasta?', 'Our supervisor is expecting his call.', NULL, 'A', 'Số điện thoại của nhà hàng Primavera là gì?
A. Nó đang đóng cửa để sửa chữa.
B. Gà hay mì?
C. Giám sát của chúng tôi đang chờ cuộc gọi của anh ấy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1370, 65, '2022/test10/audio/test10_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1829, 1370, 29, 'Could you represent our company at the recruitment fair this week?', 'Five new interns.', 'Thomas said not to get him any presents.', 'I always enjoy meeting new people.', NULL, 'C', 'Bạn có thể đại diện cho công ty chúng tôi tại hội chợ tuyển dụng tuần này không?
A. Năm thực tập sinh mới.
B. Thomas nói đừng mua quà cho anh ấy.
C. Tôi luôn thích gặp gỡ những người mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1371, 65, '2022/test10/audio/test10_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1830, 1371, 30, 'The engine''s been making a strange noise for the past hour.', 'We''d better go find some oil.', 'No, I''m not going to make anything for the party.', 'Let''s turn down the volume on the TV.', NULL, 'A', 'Động cơ đã phát ra tiếng ồn lạ trong giờ qua.
A. Chúng ta nên đi tìm dầu.
B. Không, tôi sẽ không làm gì cả cho bữa tiệc.
C. Hãy giảm âm lượng trên TV.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1372, 65, '2022/test10/audio/test10_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1831, 1372, 31, 'Where can we buy a microwave oven for the office kitchen?', 'Yes, I really like cooking.', 'My office is located near the kitchen.', 'There''s one in the storage area.', NULL, 'C', 'Chúng ta có thể mua lò vi sóng cho nhà bếp văn phòng ở đâu?
A. Vâng, tôi thực sự thích nấu ăn.
B. Văn phòng của tôi nằm gần nhà bếp.
C. Có một cái trong khu vực lưu trữ.');;

-- Data for 2022 Test10 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1373, 66, '2022/test10/audio/test10_question_32_34.mp3', NULL, '**W**: Jung Soo, are you ready for your conference in Greenville Shores? **M **: Yes, I''m leaving tomorrow morning.
**W**: That''s a great city. Are you doing any sightseeing before the conference?
**M**: Actually, I''ve been so busy finishing my presentation that I haven''t looked at what there is to do.
**W**: Last time, I did a walking tour of the historic district.
**M**: That sounds interesting.
**W**: It was! I used Greenville Guides - I can pass on their Web site. Just don''t wait too long before booking - slots fill up quickly.', '"**W**: Jung Soo, bạn đã sẵn sàng cho hội nghị tại Greenville Shores chưa?
**M**: Vâng, tôi sẽ đi vào sáng mai.
**W**: Đó là một thành phố tuyệt vời. Bạn có lên kế hoạch tham quan trước hội nghị không?
**M**: Thật ra, tôi đã quá bận hoàn thành bài thuyết trình mà chưa xem có gì để làm.
**W**: Lần trước, tôi đã tham gia một tour đi bộ khu phố lịch sử.
**M**: Nghe có vẻ thú vị đấy.
**W**: Thật vậy! Tôi đã sử dụng dịch vụ Greenville Guides - tôi có thể chuyển cho bạn trang web của họ. Chỉ cần đừng chờ quá lâu trước khi đặt chỗ - các suất nhanh chóng đầy."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1832, 1373, 32, 'What is the conversation mainly about?', 'A product launch', 'A grand opening', 'Some investment options', 'Some travel plans', 'D', 'Đáp án đúng là D. Cuộc hội thoại chủ yếu xoay quanh chuyến đi công tác của Jung Soo đến Greenville Shores, bao gồm cả việc sắp xếp tham quan thành phố.
Dịch câu hỏi và đáp án:
Câu hỏi: Cuộc hội thoại chủ yếu nói về điều gì?
A. Một buổi ra mắt sản phẩm
B. Một buổi khai trương
C. Một số lựa chọn đầu tư
D. Một số kế hoạch du lịch');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1374, 66, '2022/test10/audio/test10_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1833, 1374, 33, 'Why has the man been busy?', 'He has been working on a presentation.', 'He has just returned from a family vacation.', 'He is organizing a conference.', 'He has been assigned a new client account.', 'A', 'Đáp án đúng là A. Người đàn ông nói: "I''ve been so busy finishing my presentation", cho thấy anh ta đã bận rộn chuẩn bị bài thuyết trình.
Dịch câu hỏi và đáp án:
Câu hỏi: Tại sao người đàn ông đã bận rộn?
A. Anh ấy đã đang làm việc trên một bài thuyết trình.
B. Anh ấy vừa mới trở về từ kỳ nghỉ gia đình.
C. Anh ấy đang tổ chức một hội nghị.
D. Anh ấy vừa được giao một tài khoản khách hàng mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1375, 66, '2022/test10/audio/test10_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1834, 1375, 34, 'What does the woman suggest that the man do soon?', 'Make a reservation', 'Review some sales data', 'Use a voucher before it expires', 'Speak with an adviser', 'A', 'Đáp án đúng là A. Người phụ nữ nói: "Just don''t wait too long before booking - slots fill up quickly", gợi ý rằng người đàn ông nên đặt chỗ sớm cho tour tham quan.
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ gợi ý người đàn ông nên làm gì sớm?
A. Đặt chỗ
B. Xem xét một số dữ liệu bán hàng
C. Sử dụng một phiếu giảm giá trước khi hết hạn
D. Nói chuyện với một cố vấn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1376, 66, '2022/test10/audio/test10_question_35_37.mp3', NULL, '**M**: Welcome to Patterson Bakery. How can I help you?
**W**: Actually, I noticed the sign in your window advertising a temporary job for a baker.
**M**: Right - we always need extra help during the summer months because many employees go on vacation.
**W**: I see. How can I apply?
**M**: Let me get you an application form. You can fill out the form here if you''d like. Just remember to e-mail us your résumé later. **W**: All right, thanks!', '"**M**: Chào mừng đến với Patterson Bakery. Tôi có thể giúp gì cho bạn?
**W**: Thật ra, tôi đã chú ý thấy biển hiệu trên cửa sổ quảng cáo một công việc tạm thời cho thợ làm bánh.
**M**: Đúng rồi - chúng tôi luôn cần thêm nhân lực trong những tháng mùa hè vì nhiều nhân viên đi nghỉ.
**W**: Tôi hiểu. Làm thế nào để tôi có thể nộp đơn?
**M**: Để tôi lấy cho bạn một mẫu đơn xin việc. Bạn có thể điền vào mẫu ở đây nếu muốn. Chỉ cần nhớ gửi email sơ yếu lý lịch của bạn sau đó.
**W**: Được rồi, cảm ơn!"');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1835, 1376, 35, 'Where is the conversation taking place?', 'At a bakery', 'At an employment agency', 'At a farmers market', 'At a restaurant', 'A', 'Đáp án đúng là A. Cuộc hội thoại bắt đầu với "Welcome to Patterson Bakery", cho thấy rõ ràng địa điểm là một tiệm bánh.
Dịch câu hỏi và đáp án:
Câu hỏi: Cuộc hội thoại diễn ra ở đâu?
A. Tại một tiệm bánh
B. Tại một cơ quan tuyển dụng
C. Tại một chợ nông sản
D. Tại một nhà hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1377, 66, '2022/test10/audio/test10_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1836, 1377, 36, 'What does the woman ask about?', 'An upcoming event', 'A project deadline', 'A delivery service', 'A job opening', 'D', 'Đáp án đúng là D. Người phụ nữ hỏi về "the sign in your window advertising a temporary job for a baker", cho thấy cô ấy đang hỏi về một vị trí công việc đang mở.
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ hỏi về điều gì?
A. Một sự kiện sắp tới
B. Thời hạn của một dự án
C. Một dịch vụ giao hàng
D. Một vị trí công việc đang mở');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1378, 66, '2022/test10/audio/test10_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1837, 1378, 37, 'What does the man remind the woman to do?', 'Register on a Web site', 'Send a document', 'Update a budget', 'Change an address', 'B', 'Đáp án đúng là B. Người đàn ông nhắc người phụ nữ: "Just remember to e-mail us your résumé later", yêu cầu cô ấy gửi một tài liệu (sơ yếu lý lịch) qua email.
Dịch câu hỏi và đáp án:
Câu hỏi: Người đàn ông nhắc người phụ nữ làm gì?
A. Đăng ký trên một trang web
B. Gửi một tài liệu
C. Cập nhật ngân sách
D. Thay đổi địa chỉ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1379, 66, '2022/test10/audio/test10_question_38_40.mp3', NULL, '**M**: Thank you for hiring me as a business consultant. What sort of advice are you looking for? I know your bookstore is already well- known in the community.
**W**: But a lot of people are shopping online these days, and we''re worried about our ability to compete.
**W**: Yes, we think that''s why fewer people are coming into the bookstore these days.
**M**: I see. Have you considered making a significant change to the store-like adding a café?
**W**: Interesting. We probably have enough space in the back of the store for that.
**M**: That way customers could come in to browse and have a cup of coffee.', '"**M**: Cảm ơn bạn đã thuê tôi làm tư vấn kinh doanh. Bạn đang tìm kiếm loại lời khuyên nào? Tôi biết cửa hàng sách của bạn đã nổi tiếng trong cộng đồng.
**W**: Nhưng rất nhiều người đang mua sắm trực tuyến ngày nay, và chúng tôi lo lắng về khả năng cạnh tranh của mình.
**W**: Vâng, chúng tôi nghĩ đó là lý do tại sao ít người đến cửa hàng sách hơn những ngày này.
**M**: Tôi hiểu. Bạn đã từng nghĩ đến việc thực hiện một sự thay đổi đáng kể cho cửa hàng - như thêm một quán cà phê?
**W**: Thú vị đấy. Chúng tôi có lẽ có đủ không gian ở phía sau cửa hàng để làm điều đó.
**M**: Bằng cách đó, khách hàng có thể vào tham quan và thưởng thức một tách cà phê."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1838, 1379, 38, 'Where do the women work?', 'At a bookstore', 'At a computer store', 'At a food market', 'At a publishing company', 'A', 'Đáp án đúng là A. Cuộc hội thoại đề cập đến "your bookstore" và thảo luận về việc cạnh tranh với các cửa hàng trực tuyến, cho thấy họ làm việc tại một hiệu sách.
Dịch câu hỏi và đáp án:
Câu hỏi: Những người phụ nữ làm việc ở đâu?
A. Tại một hiệu sách
B. Tại một cửa hàng máy tính
C. Tại một chợ thực phẩm
D. Tại một công ty xuất bản');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1380, 66, '2022/test10/audio/test10_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1839, 1380, 39, 'What are the women worried about?', 'Opening a branch office', 'Competing with online stores', 'Finding a new supplier', 'Hiring enough delivery drivers', 'B', 'Đáp án đúng là B. Người phụ nữ nói: "a lot of people are shopping online these days, and we''re worried about our ability to compete", cho thấy họ lo lắng về việc cạnh tranh với các cửa hàng trực tuyến.
Dịch câu hỏi và đáp án:
Câu hỏi: Những người phụ nữ lo lắng về điều gì?
A. Mở một văn phòng chi nhánh
B. Cạnh tranh với các cửa hàng trực tuyến
C. Tìm một nhà cung cấp mới
D. Thuê đủ tài xế giao hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1381, 66, '2022/test10/audio/test10_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1840, 1381, 40, 'What does the man recommend?', 'Advertising online', 'Attending a trade show', 'Adding food service', 'Offering a home repair service', 'C', 'Đáp án đúng là C. Người đàn ông đề xuất: "Have you considered making a significant change to the store-like adding a café?", gợi ý việc thêm dịch vụ ăn uống vào cửa hàng.
Dịch câu hỏi và đáp án:
Câu hỏi: Người đàn ông đề xuất điều gì?
A. Quảng cáo trực tuyến
B. Tham dự một hội chợ thương mại
C. Thêm dịch vụ ăn uống
D. Cung cấp dịch vụ sửa chữa tại nhà');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1382, 66, '2022/test10/audio/test10_question_41_43.mp3', NULL, '**W**: Hey, Taro. A customer just bought five bags of our Super Boost potting soil. Could you carry them to his car for him?
**M**: Can I finish organizing the flower seeds on this display first? I''ll be done in a minute.
**W**: He''s probably waiting outside. I told him to pull his car up by the entrance.
**M**: Oh, OK. And he already paid, right?
**W **Yes. Just be sure to sign your initials on his receipt once you''re done. It''s something we keep forgetting to do.', '"**W**: Này, Taro. Một khách hàng vừa mua năm túi đất trồng cây Super Boost của chúng ta. Bạn có thể mang chúng đến xe của anh ấy giúp không?
**M**: Tôi có thể hoàn thành việc sắp xếp hạt giống hoa trên kệ trưng bày này trước không? Tôi sẽ xong trong một phút.
**W**: Có lẽ anh ấy đang đợi ở ngoài. Tôi đã bảo anh ấy đỗ xe gần lối vào.
**M**: Ồ, được rồi. Và anh ấy đã thanh toán rồi phải không?
**W**: Vâng. Chỉ cần đảm bảo ký tên tắt của bạn lên hóa đơn khi bạn xong. Đó là điều chúng ta thường quên làm."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1841, 1382, 41, 'What kind of products do the speakers sell?', 'Cleaning products', 'Car accessories', 'Kitchen tools', 'Garden supplies', 'D', 'Đáp án đúng là D. Cuộc hội thoại đề cập đến "Super Boost potting soil" và "flower seeds", cho thấy họ bán các sản phẩm làm vườn.
Dịch câu hỏi và đáp án:
Câu hỏi: Những người nói bán loại sản phẩm gì?
A. Sản phẩm làm sạch
B. Phụ kiện xe hơi
C. Dụng cụ nhà bếp
D. Vật dụng làm vườn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1383, 66, '2022/test10/audio/test10_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1842, 1383, 42, 'What does the woman mean when she says, "He''s probably waiting outside"?', 'A customer needs help immediately.', 'A manager wants to discuss a complaint.', 'A store is unusually crowded.', 'Some instructions were confusing.', 'A', 'Đáp án đúng là A. Khi người phụ nữ nói "He''s probably waiting outside", cô ấy ngụ ý rằng khách hàng đang đợi và cần được giúp đỡ ngay lập tức.
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ có ý gì khi nói "Anh ấy có lẽ đang đợi bên ngoài"?
A. Một khách hàng cần giúp đỡ ngay lập tức.
B. Một quản lý muốn thảo luận về một khiếu nại.
C. Một cửa hàng đang đông khách một cách bất thường.
D. Một số hướng dẫn gây nhầm lẫn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1384, 66, '2022/test10/audio/test10_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1843, 1384, 43, 'What do the staff sometimes forget to do?', 'Restock inventory', 'Sign receipts', 'Hand out flyers', 'Mention an upcoming sale', 'B', 'Đáp án đúng là B. Người phụ nữ nói: "Just be sure to sign your initials on his receipt once you''re done. It''s something we keep forgetting to do", cho thấy nhân viên thường quên ký vào biên lai.
Dịch câu hỏi và đáp án:
Câu hỏi: Nhân viên đôi khi quên làm gì?
A. Bổ sung hàng tồn kho
B. Ký biên lai
C. Phát tờ rơi
D. Đề cập đến một đợt giảm giá sắp tới');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1385, 66, '2022/test10/audio/test10_question_44_46.mp3', NULL, '**W**: Hi, Paul and Mark. Uh, you''ve already installed the electrical wiring in the new classrooms on the west end of the building, right?
**M**: Yes, we''re almost finished. Is there a problem?
**W**: Well... there''s just a last-minute change. The school district has decided that each classroom should have a projector mounted on the ceiling.
**M**: That''s really frustrating. We''ll have to redo some of the connections so that we can run wiring through the ceilings.
**M**: That''s going to take more time. Maybe another week or so.
**W**: That''s OK. Here are the new blueprints for the classroom design. I''d like you to look them over and let me know if you have any questions.', '"**W**: Chào, Paul và Mark. Ờ, các bạn đã lắp đặt hệ thống dây điện trong các lớp học mới ở phía tây của tòa nhà chưa?
**M**: Vâng, chúng tôi gần hoàn thành. Có vấn đề gì không?
**W**: Thực ra... có một sự thay đổi vào phút cuối. Khu học chánh đã quyết định mỗi lớp học nên có một máy chiếu được gắn trên trần.
**M**: Thật là bực mình. Chúng tôi sẽ phải làm lại một số kết nối để có thể chạy dây điện qua trần nhà.
**M**: Điều đó sẽ mất thêm thời gian. Có lẽ thêm một tuần nữa.
**W**: Được rồi. Đây là các bản thiết kế mới cho thiết kế lớp học. Tôi muốn các bạn xem qua và cho tôi biết nếu có câu hỏi nào."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1844, 1385, 44, 'Who most likely are the men?', 'Teachers', 'Bakers', 'Electricians', 'Doctors', 'C', 'Đáp án đúng là C. Cuộc hội thoại đề cập đến việc lắp đặt dây điện và kết nối, cho thấy những người đàn ông là thợ điện.
Dịch câu hỏi và đáp án:
Câu hỏi: Những người đàn ông nhiều khả năng là ai?
A. Giáo viên
B. Thợ làm bánh
C. Thợ điện
D. Bác sĩ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1386, 66, '2022/test10/audio/test10_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1845, 1386, 45, 'Why are the men frustrated?', 'Some work will have to be redone.', 'Some tools have been misplaced.', 'Some staff members are unavailable.', 'Some supplies have run out.', 'A', 'Đáp án đúng là A. Người đàn ông nói: "We''ll have to redo some of the connections", cho thấy họ thất vọng vì phải làm lại một số công việc.
Dịch câu hỏi và đáp án:
Câu hỏi: Tại sao những người đàn ông thất vọng?
A. Một số công việc sẽ phải làm lại.
B. Một số công cụ đã bị thất lạc.
C. Một số nhân viên không có sẵn.
D. Một số vật tư đã hết.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1387, 66, '2022/test10/audio/test10_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1846, 1387, 46, 'What does the woman want the men to review?', 'A revised budget', 'A meeting agenda', 'Some design plans', 'Some contract terms', 'C', 'Đáp án đúng là C. Người phụ nữ nói: "Here are the new blueprints for the classroom design. I''d like you to look them over", cho thấy cô ấy muốn họ xem xét các bản thiết kế mới.
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ muốn những người đàn ông xem xét điều gì?
A. Một ngân sách đã được sửa đổi
B. Một chương trình họp
C. Một số bản thiết kế
D. Một số điều khoản hợp đồng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1388, 66, '2022/test10/audio/test10_question_47_49.mp3', NULL, '**M**: Thanks for agreeing to meet with me, Mayor Jackson. I wanted to discuss the possibility of creating a community garden in my neighborhood. It would be a space where we could grow flowers and vegetables.
**W**: Great idea. But finding a place for it could be a problem.
**M**: Not necessarily. There''s a vacant lot on the corner of Main Street and Linwood Avenue. It''s city property, and it''s been empty for years.
**W **Well, you''ll need to have the city council approve a request like that. I suggest you start a neighborhood petition. If you get enough signatures, you can bring it to the city council.', '"**M**: Cảm ơn bạn đã đồng ý gặp gỡ với tôi, Thị trưởng Jackson. Tôi muốn thảo luận về khả năng tạo ra một khu vườn cộng đồng trong khu phố của tôi. Đây sẽ là một không gian nơi chúng ta có thể trồng hoa và rau quả.
**W**: Ý tưởng tuyệt vời. Nhưng tìm một nơi cho nó có thể là một vấn đề.
**M**: Không nhất thiết. Có một mảnh đất trống ở góc phố Main và Đại lộ Linwood. Đó là tài sản của thành phố, và nó đã trống trong nhiều năm.
**W**: Vậy, bạn sẽ cần có sự chấp thuận của hội đồng thành phố cho một yêu cầu như vậy. Tôi gợi ý bạn bắt đầu một cuộc kiến nghị trong khu phố. Nếu bạn thu thập đủ chữ ký, bạn có thể đưa nó đến hội đồng thành phố."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1847, 1388, 47, 'What does the man want to do?', 'Renovate a building', 'Create a community garden', 'Install some new road signs', 'Move a business to a new location', 'B', 'Đáp án đúng là B. Người đàn ông nói rõ: "I wanted to discuss the possibility of creating a community garden in my neighborhood".
Dịch câu hỏi và đáp án:
Câu hỏi: Người đàn ông muốn làm gì?
A. Cải tạo một tòa nhà
B. Tạo một khu vườn cộng đồng
C. Lắp đặt một số biển báo đường mới
D. Chuyển một doanh nghiệp đến địa điểm mới');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1389, 66, '2022/test10/audio/test10_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1848, 1389, 48, 'What problem does the woman mention about a project?', 'It will be noisy.', 'It will be expensive.', 'Finding available space may be difficult.', 'The approval process may take a long time.', 'C', 'Đáp án đúng là C. Người phụ nữ nói: "But finding a place for it could be a problem", chỉ ra rằng việc tìm không gian có sẵn có thể khó khăn.
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ đề cập đến vấn đề gì về dự án?
A. Nó sẽ gây ồn ào.
B. Nó sẽ tốn kém.
C. Việc tìm không gian có sẵn có thể khó khăn.
D. Quá trình phê duyệt có thể mất nhiều thời gian.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1390, 66, '2022/test10/audio/test10_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1849, 1390, 49, 'What does the woman suggest the man do?', 'Apply for a loan', 'Check a city map', 'Collect some signatures', 'Post an announcement online', 'C', 'Đáp án đúng là C. Người phụ nữ gợi ý: "I suggest you start a neighborhood petition. If you get enough signatures, you can bring it to the city council".
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ gợi ý người đàn ông làm gì?
A. Nộp đơn xin vay
B. Kiểm tra bản đồ thành phố
C. Thu thập chữ ký
D. Đăng một thông báo trực tuyến');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1391, 66, '2022/test10/audio/test10_question_50_52.mp3', NULL, '**M**: It''s been great speaking with you on our radio program today. So I''m sure our listeners enjoyed hearing about your career in finance.
**W**: Thanks for having me! I especially enjoyed sharing passages from the book I recently published, *Choosing the Right Finance Career*.
**M: **I''m glad you did. Actually, a listener just sent in one more question for you. Let''s see...Isabel from Rhode Island would like to know your tips for choosing the right finance degree program. Any advice?', '"**M**: Thật tuyệt khi được nói chuyện với bạn trong chương trình phát thanh hôm nay. Vì vậy, tôi chắc chắn rằng thính giả của chúng ta đã thích nghe về sự nghiệp của bạn trong lĩnh vực tài chính.
**W**: Cảm ơn đã mời tôi! Tôi đặc biệt thích chia sẻ những đoạn trích từ cuốn sách mà tôi vừa xuất bản, *Chọn Ngành Tài Chính Phù Hợp*.
**M**: Tôi rất vui vì bạn đã làm điều đó. Thật ra, một thính giả vừa gửi thêm một câu hỏi nữa cho bạn. Hãy xem nào... Isabel từ Rhode Island muốn biết những mẹo của bạn để chọn chương trình đại học ngành tài chính phù hợp. Bạn có lời khuyên nào không?"');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1850, 1391, 50, 'What industry does the woman work in?', 'Finance', 'Farming', 'Advertising', 'Hospitality', 'A', 'Đáp án đúng là A. Cuộc hội thoại đề cập đến "your career in finance" và cuốn sách của người phụ nữ về sự nghiệp tài chính, cho thấy cô ấy làm việc trong ngành tài chính.
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ làm việc trong ngành nào?
A. Tài chính
B. Nông nghiệp
C. Quảng cáo
D. Khách sạn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1392, 66, '2022/test10/audio/test10_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1851, 1392, 51, 'What did the woman do recently?', 'She received an award.', 'She opened a new business.', 'She invented a new product.', 'She published a book.', 'D', 'Đáp án đúng là D. Người phụ nữ nói: "I especially enjoyed sharing passages from the book I recently published".
Dịch câu hỏi và đáp án:
Câu hỏi: Gần đây người phụ nữ đã làm gì?
A. Cô ấy nhận được một giải thưởng.
B. Cô ấy mở một doanh nghiệp mới.
C. Cô ấy phát minh ra một sản phẩm mới.
D. Cô ấy xuất bản một cuốn sách.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1393, 66, '2022/test10/audio/test10_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1852, 1393, 52, 'What will the woman most likely discuss next?', 'Choosing an appropriate software program', 'Preparing for a job interview', 'Deciding on a program of study', 'Improving networking skills', 'C', 'Đáp án đúng là C. Người đàn ông nói: "Isabel from Rhode Island would like to know your tips for choosing the right finance degree program", cho thấy chủ đề tiếp theo sẽ là về việc chọn chương trình học.
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ có khả năng sẽ thảo luận về điều gì tiếp theo?
A. Chọn một chương trình phần mềm phù hợp
B. Chuẩn bị cho một cuộc phỏng vấn việc làm
C. Quyết định về một chương trình học
D. Cải thiện kỹ năng networking');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1394, 66, '2022/test10/audio/test10_question_53_55.mp3', NULL, '**M**: Priyanka, are you looking forward to the new restaurant opening next month?
**W**: Definitely. It''s about time we opened a second location.
**M**: Yes! I was looking at the layout again, and I think we should order three more sets of tables and benches for the outdoor patio.
**W**: Good idea.
**M**: But I''m worried about placing the order right away. I know our bank account was used for payroll earlier today, so we may not have enough funds in that account to cover the costs.
**W**: I just checked the account balance an hour ago - OK, I''ll go ahead and place the order.', '"**M**: Priyanka, bạn có mong chờ việc nhà hàng mới mở cửa vào tháng tới không?
**W**: Chắc chắn rồi. Đã đến lúc chúng ta mở thêm một địa điểm thứ hai.
**M**: Vâng! Tôi đã xem lại bố cục lần nữa, và tôi nghĩ chúng ta nên đặt thêm ba bộ bàn và ghế cho sân hiên ngoài.
**W**: Ý hay đấy.
**M**: Nhưng tôi lo lắng về việc đặt hàng ngay lập tức. Tôi biết tài khoản ngân hàng của chúng ta đã được sử dụng để trả lương hôm nay, vì vậy chúng ta có thể không có đủ quỹ trong tài khoản đó để trang trải chi phí.
**W**: Tôi vừa kiểm tra số dư tài khoản một giờ trước - Được rồi, tôi sẽ tiến hành đặt hàng."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1853, 1394, 53, 'What kind of business do the speakers most likely own?', 'An architecture studio', 'A restaurant', 'A real estate agency', 'An accounting firm', 'B', 'Đáp án đúng là B. Cuộc hội thoại đề cập đến việc mở một nhà hàng mới: "the new restaurant opening next month" và "we opened a second location".
Dịch câu hỏi và đáp án:
Câu hỏi: Những người nói nhiều khả năng sở hữu loại doanh nghiệp gì?
A. Một studio kiến trúc
B. Một nhà hàng
C. Một công ty bất động sản
D. Một công ty kế toán');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1395, 66, '2022/test10/audio/test10_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1854, 1395, 54, 'What does the man want to order?', 'Furniture', 'Office supplies', 'Food', 'Lighting fixtures', 'A', 'Đáp án đúng là A. Người đàn ông nói: "I think we should order three more sets of tables and benches for the outdoor patio", cho thấy anh ta muốn đặt mua nội thất.
Dịch câu hỏi và đáp án:
Câu hỏi: Người đàn ông muốn đặt hàng gì?
A. Nội thất
B. Văn phòng phẩm
C. Thức ăn
D. Đèn chiếu sáng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1396, 66, '2022/test10/audio/test10_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1855, 1396, 55, 'Why does the woman say, "I just checked the account balance an hour ago"?', 'To offer an excuse', 'To make a complaint', 'To provide reassurance', 'To express surprise', 'C', 'Đáp án đúng là C. Người phụ nữ nói điều này để trấn an người đàn ông rằng có đủ tiền trong tài khoản để đặt hàng.
Dịch câu hỏi và đáp án:
Câu hỏi: Tại sao người phụ nữ nói "Tôi vừa kiểm tra số dư tài khoản một giờ trước"?
A. Để đưa ra một lý do
B. Để phàn nàn
C. Để trấn an
D. Để bày tỏ sự ngạc nhiên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1397, 66, '2022/test10/audio/test10_question_56_58.mp3', NULL, '**W**: Hello, Gerard. This is Patricia Santos calling
**M**: Patricia, I haven''t talked to you since your lease ended last year. How are you?
**W**: I''m doing well, thanks. I''ve been staying with my parents in London, but I''m about to start trade school in Glasgow
**M**: Oh, congratulations!
**W **Actually, that''s why I''m calling - I found a new apartment that I''d like, and the rental application requires a letter from a previous landlord. Could you write that for me?
**M**: Yes, of course. What should I say?
**W**: It can be short - just say that I''m a quiet, clean tenant who paid rent on time.
**M**: No problem. Just text me the contact information.', '"**W**: Xin chào, Gerard. Đây là Patricia Santos gọi.
**M**: Patricia, tôi chưa nói chuyện với bạn kể từ khi hợp đồng thuê nhà của bạn kết thúc năm ngoái. Bạn khỏe không?
**W**: Tôi khỏe, cảm ơn. Tôi đã ở lại với bố mẹ ở London, nhưng tôi sắp bắt đầu học nghề ở Glasgow.
**M**: Ồ, chúc mừng!
**W**: Thực ra, đó là lý do tôi gọi - tôi đã tìm được một căn hộ mới mà tôi thích, và đơn xin thuê yêu cầu một lá thư từ chủ nhà trước đây. Bạn có thể viết lá thư đó cho tôi được không?
**M**: Vâng, tất nhiên rồi. Tôi nên viết gì?
**W**: Nó có thể ngắn gọn - chỉ cần nói rằng tôi là một người thuê nhà yên tĩnh, sạch sẽ và đã trả tiền thuê đúng hạn.
**M**: Không vấn đề gì. Chỉ cần nhắn tin cho tôi thông tin liên lạc."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1856, 1397, 56, 'Who most likely is the man?', 'The woman''s former landlord', 'The woman''s professor', 'The woman''s relative', 'The woman''s previous employer', 'A', 'Đáp án đúng là A. Người đàn ông nói: "I haven''t talked to you since your lease ended last year", và người phụ nữ yêu cầu "a letter from a previous landlord", cho thấy người đàn ông là chủ nhà cũ của cô ấy.
Dịch câu hỏi và đáp án:
Câu hỏi: Người đàn ông nhiều khả năng là ai?
A. Chủ nhà cũ của người phụ nữ
B. Giáo sư của người phụ nữ
C. Người thân của người phụ nữ
D. Người chủ cũ của người phụ nữ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1398, 66, '2022/test10/audio/test10_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1857, 1398, 57, 'What does the woman say she will do soon?', 'Return to her parents'' house', 'Apply for a job', 'Pick up her belongings', 'Begin coursework at school', 'D', 'Đáp án đúng là D. Người phụ nữ nói: "I''m about to start trade school in Glasgow".
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ nói cô ấy sẽ làm gì sắp tới?
A. Trở về nhà bố mẹ
B. Nộp đơn xin việc
C. Lấy đồ đạc của mình
D. Bắt đầu khóa học ở trường');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1399, 66, '2022/test10/audio/test10_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1858, 1399, 58, 'What does the woman ask for?', 'A house key', 'A copy of a certificate', 'A reference letter', 'A colleague''s e-mail address', 'C', 'Đáp án đúng là C. Người phụ nữ yêu cầu một lá thư giới thiệu từ chủ nhà cũ: "the rental application requires a letter from a previous landlord. Could you write that for me?"
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ yêu cầu điều gì?
A. Một chìa khóa nhà
B. Một bản sao chứng chỉ
C. Một thư giới thiệu
D. Địa chỉ email của một đồng nghiệp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1400, 66, '2022/test10/audio/test10_question_59_61.mp3', NULL, '**W**: Thank you for listening to Channel Three news this morning. It''s time to go to Hao Nan with our traffic report.
**M**: Thanks, Sameera. While most commuters are seeing a fairly smooth ride this morning, crews have begun repairs to the Lansing Bridge, and it''s closed to all traffic. Drivers can take a detour on Canal Road.
**W**: And when is construction expected to be completed?
**M**: It''s scheduled to wrap up by November seventh. Head to our Web site at NewsThree.com to learn more about the progress of the repairs.', '"**W**: Cảm ơn bạn đã nghe tin tức kênh Ba hôm nay. Đã đến lúc chuyển sang Hao Nan với báo cáo giao thông của chúng tôi.
**M**: Cảm ơn, Sameera. Trong khi hầu hết các người đi làm đang có chuyến đi khá suôn sẻ sáng nay, các đội sửa chữa đã bắt đầu sửa chữa cầu Lansing, và nó đã bị đóng cho tất cả phương tiện giao thông. Lái xe có thể đi vòng qua đường Canal.
**W**: Và việc xây dựng dự kiến sẽ hoàn thành khi nào?
**M**: Nó dự kiến sẽ hoàn tất vào ngày 7 tháng Mười Một. Truy cập trang web của chúng tôi tại NewsThree.com để tìm hiểu thêm về tiến độ sửa chữa."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1859, 1400, 59, 'Where most likely are the speakers?', 'In a government office', 'In a television studio', 'At a bus terminal', 'At a construction site', 'B', 'Đáp án đúng là B. Cuộc hội thoại bắt đầu với "Thank you for listening to Channel Three news this morning", cho thấy họ đang ở trong một studio truyền hình.
Dịch câu hỏi và đáp án:
Câu hỏi: Những người nói nhiều khả năng đang ở đâu?
A. Trong một văn phòng chính phủ
B. Trong một studio truyền hình
C. Tại một bến xe buýt
D. Tại một công trường xây dựng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1401, 66, '2022/test10/audio/test10_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1860, 1401, 60, 'What does the man mention about the Lansing Bridge?', 'There is a lot of traffic on it today.', 'There is a beautiful view from it.', 'It now has a walkway.', 'It is temporarily closed.', 'D', 'Đáp án đúng là D. Người đàn ông nói: "crews have begun repairs to the Lansing Bridge, and it''s closed to all traffic".
Dịch câu hỏi và đáp án:
Câu hỏi: Người đàn ông đề cập điều gì về cầu Lansing?
A. Hôm nay có nhiều xe cộ trên đó.
B. Có một cảnh đẹp từ đó.
C. Nó giờ có một lối đi bộ.
D. Nó tạm thời bị đóng cửa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1402, 66, '2022/test10/audio/test10_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1861, 1402, 61, 'How can the listeners find out more information?', 'By visiting an information desk', 'By requesting a brochure', 'By checking a Web site', 'By calling a help line', 'C', 'Đáp án đúng là C. Người đàn ông nói: "Head to our Web site at NewsThree.com to learn more about the progress of the repairs", cho thấy người nghe có thể tìm hiểu thêm thông tin bằng cách truy cập trang web.
Dịch câu hỏi và đáp án:
Câu hỏi: Làm thế nào người nghe có thể tìm hiểu thêm thông tin?
A. Bằng cách đến quầy thông tin
B. Bằng cách yêu cầu một tờ rơi
C. Bằng cách kiểm tra một trang web
D. Bằng cách gọi đường dây trợ giúp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1403, 66, '2022/test10/audio/test10_question_62_64.mp3', '2022/test10/image/test10-p3-image-62.jpg', '**W**: Hello, Elmbrook Community Center.
**M**: Hi, I''ll be attending the class that starts on Friday this week, and I''m wondering what to bring. Details weren''t listed in the class description.
**W**: Oh, the materials are always provided. But please note that classes don''t start until next week
**M**: Really? I''ll be in Chicago next week - my son''s getting married. I''m afraid I''m going to have to miss the first class, then', '"**W**: Xin chào, Trung tâm Cộng đồng Elmbrook.
**M**: Chào, tôi sẽ tham gia lớp học bắt đầu vào thứ Sáu tuần này, và tôi đang thắc mắc nên mang gì. Chi tiết không được liệt kê trong mô tả lớp học.
**W**: Ồ, tài liệu luôn được cung cấp. Nhưng xin lưu ý rằng các lớp học sẽ không bắt đầu cho đến tuần sau.
**M**: Thật sao? Tôi sẽ ở Chicago tuần tới - con trai tôi đang tổ chức đám cưới. Tôi e rằng tôi sẽ phải bỏ lỡ buổi học đầu tiên."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1862, 1403, 62, 'Why is the man calling?', 'To confirm he will teach a class', 'To complain about a recent class', 'To inquire about class supplies', 'To request directions to a community center', 'C', 'Đáp án đúng là C. Người đàn ông gọi để hỏi về vật dụng cần mang theo cho lớp học: "I''m wondering what to bring. Details weren''t listed in the class description".
Dịch câu hỏi và đáp án:
Câu hỏi: Tại sao người đàn ông gọi điện?
A. Để xác nhận anh ấy sẽ dạy một lớp
B. Để phàn nàn về một lớp học gần đây
C. Để hỏi về vật dụng cho lớp học
D. Để yêu cầu chỉ dẫn đến trung tâm cộng đồng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1404, 66, '2022/test10/audio/test10_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1863, 1404, 63, 'Look at the graphic. Which class are the speakers discussing?', 'Knitting', 'Painting', 'Sculpture', 'Drawing', 'D', 'Đáp án đúng là D. Người đàn ông nói về lớp học bắt đầu vào thứ Sáu, và theo lịch trong hình, lớp học vào thứ Sáu là Drawing (Vẽ).
Dịch câu hỏi và đáp án:
Câu hỏi: Nhìn vào hình. Những người nói đang thảo luận về lớp học nào?
A. Đan len
B. Vẽ tranh
C. Điêu khắc
D. Vẽ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1405, 66, '2022/test10/audio/test10_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1864, 1405, 64, 'What does the man plan to do in Chicago?', 'Go to a graduation ceremony', 'Attend a wedding', 'Complete a certification', 'See an art exhibit', 'B', 'Đáp án đúng là B. Người đàn ông nói: "I''ll be in Chicago next week - my son''s getting married", cho thấy anh ấy sẽ tham dự đám cưới của con trai.
Dịch câu hỏi và đáp án:
Câu hỏi: Người đàn ông dự định làm gì ở Chicago?
A. Đi dự lễ tốt nghiệp
B. Tham dự một đám cưới
C. Hoàn thành một chứng chỉ
D. Xem một triển lãm nghệ thuật');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1406, 66, '2022/test10/audio/test10_question_65_67.mp3', '2022/test10/image/test10-p3-image-65.jpg', '**M**: Thanks for attending this planning meeting. As I explained in my e-mail, since the company''s expanding its fleet of trucks, we need to figure out how to recruit more truck drivers. Any ideas?
**W**: I did some research. This graph shows where people most frequently search for jobs online.
**M**: Hmm, eighty-four percent use job search engines, so it''s good we already post our job openings on those. But, look at the next-highest category. At sixty-six percent, it''d be worth investing in.
**W**: I thought so, too. We''d need to increase our recruitment budget, though.
**M**: I''m meeting with the rest of the management team later today. I''ll mention our need for extra funds.', '"**M**: Cảm ơn bạn đã tham gia cuộc họp hoạch định này. Như tôi đã giải thích trong email của mình, vì công ty đang mở rộng đội xe tải, chúng ta cần tìm cách tuyển thêm tài xế xe tải. Bạn có ý tưởng nào không?
**W**: Tôi đã thực hiện một số nghiên cứu. Biểu đồ này cho thấy nơi mọi người thường tìm kiếm việc làm trực tuyến nhất.
**M**: Hmm, tám mươi tư phần trăm sử dụng các công cụ tìm kiếm việc làm, vì vậy thật tốt khi chúng ta đã đăng tin tuyển dụng trên đó. Nhưng, hãy nhìn vào danh mục cao thứ hai. Tại sáu mươi sáu phần trăm, sẽ đáng để đầu tư.
**W**: Tôi cũng nghĩ vậy. Tuy nhiên, chúng ta cần tăng ngân sách tuyển dụng.
**M**: Tôi sẽ gặp lại đội ngũ quản lý còn lại vào cuối ngày hôm nay. Tôi sẽ đề cập đến nhu cầu về thêm quỹ."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1865, 1406, 65, 'Where do the speakers most likely work?', 'At a car rental service', 'At a market research firm', 'At an electronics store', 'At a trucking company', 'D', 'Đáp án đúng là D. Cuộc hội thoại đề cập đến việc mở rộng đội xe tải và tuyển dụng tài xế xe tải, cho thấy họ làm việc tại một công ty vận tải.
Dịch câu hỏi và đáp án:
Câu hỏi: Những người nói nhiều khả năng làm việc ở đâu?
A. Tại một dịch vụ cho thuê xe hơi
B. Tại một công ty nghiên cứu thị trường
C. Tại một cửa hàng điện tử
D. Tại một công ty vận tải');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1407, 66, '2022/test10/audio/test10_question_65_67.mp3', '2022/test10/image/Image 2', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1866, 1407, 66, 'Look at the graphic. Where do the speakers plan to start advertising job openings?', 'On job-related search engines', 'On social media sites', 'On company Web sites', 'In online newspapers', 'B', 'Đáp án đúng là B. Người đàn ông nói về việc đầu tư vào "the next-highest category", mà theo biểu đồ là social media sites với 66%.
Dịch câu hỏi và đáp án:
Câu hỏi: Nhìn vào hình. Những người nói dự định bắt đầu quảng cáo việc làm ở đâu?
A. Trên các công cụ tìm kiếm việc làm
B. Trên các trang mạng xã hội
C. Trên các trang web của công ty
D. Trên các báo trực tuyến');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1408, 66, '2022/test10/audio/test10_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1867, 1408, 67, 'What does the man say he will do later today?', 'Propose a budget adjustment', 'Attend a training session', 'Write a letter of recommendation', 'Approve a timeline', 'A', 'Đáp án đúng là A. Người đàn ông nói: "I''m meeting with the rest of the management team later today. I''ll mention our need for extra funds", ngụ ý rằng anh ấy sẽ đề xuất điều chỉnh ngân sách.
Dịch câu hỏi và đáp án:
Câu hỏi: Người đàn ông nói anh ấy sẽ làm gì vào cuối ngày hôm nay?
A. Đề xuất điều chỉnh ngân sách
B. Tham dự một buổi đào tạo
C. Viết một thư giới thiệu
D. Phê duyệt một lịch trình');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1409, 66, '2022/test10/audio/test10_question_68_70.mp3', '2022/test10/image/test10-p3-image-68.jpg', '**M**: The design for next season''s backpack looks nice! What materials will you use?
**W**: Well, polyester for the body of the bag, but it''s hard to decide what to use for the straps. Any suggestions?
**M**: How about cotton canvas?
**W**: Hmm. Yes, OK. That would create an interesting texture contrast. Perfect!
**M**: By the way, remember how we commissioned an artist to redesign our logo in honor of our company''s fifty years in business? Well, the new logo is ready. Where would you like it to go?
**W: **Last year the logo went on the left side punched. But for this model I''d like to do something different, so put it on the top flap.
**M**: No problem.', '"**M**: Thiết kế ba lô mùa giải tới trông đẹp đấy! Bạn sẽ sử dụng chất liệu gì?
**W**: Thường là polyester cho thân ba lô, nhưng khó để quyết định dùng gì cho dây đeo. Bạn có gợi ý nào không?
**M**: Thế nào về vải bông?
**W**: Hmm. Vâng, được rồi. Điều đó sẽ tạo ra một sự tương phản kết cấu thú vị. Hoàn hảo!
**M**: Nhân tiện, nhớ cách chúng ta đã ủy thác cho một nghệ sĩ thiết kế lại logo của chúng ta để tôn vinh năm mươi năm kinh doanh của công ty không? Thế thì, logo mới đã sẵn sàng. Bạn muốn nó được đặt ở đâu?
**W**: Năm ngoái, logo được đặt ở phía bên trái của nắp. Nhưng đối với mẫu này, tôi muốn làm điều gì đó khác, nên hãy đặt nó ở mũi túi trên cùng.
**M**: Không vấn đề gì."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1868, 1409, 68, 'What is the woman having difficulty deciding', 'A color', 'A fabric', 'Storage capacity', 'Strap placement', 'B', 'Đáp án đúng là B. Người phụ nữ nói: "it''s hard to decide what to use for the straps", cho thấy cô ấy đang gặp khó khăn trong việc quyết định chất liệu (vải) cho dây đeo.
Dịch câu hỏi và đáp án:
Câu hỏi: Người phụ nữ đang gặp khó khăn trong việc quyết định điều gì?
A. Một màu sắc
B. Một loại vải
C. Khả năng lưu trữ
D. Vị trí đặt dây đeo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1410, 66, '2022/test10/audio/test10_question_68_70.mp3', '2022/test10/image/Image 3', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1869, 1410, 69, 'Why was the company''s logo redesigned?', 'To reflect design trends', 'To celebrate an anniversary', 'To appeal to a wider audience', 'To avoid a copyright problem', 'B', 'Đáp án đúng là B. Người đàn ông nói: "we commissioned an artist to redesign our logo in honor of our company''s fifty years in business", cho thấy logo được thiết kế lại để kỷ niệm một cột mốc quan trọng.
Dịch câu hỏi và đáp án:
Câu hỏi: Tại sao logo của công ty được thiết kế lại?
A. Để phản ánh xu hướng thiết kế
B. Để kỷ niệm một cột mốc
C. Để thu hút đối tượng rộng hơn
D. Để tránh vấn đề bản quyền');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1411, 66, '2022/test10/audio/test10_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1870, 1411, 70, 'Look at the graphic. Where will the company''s logo be placed?', 'Location 1', 'Location 2', 'Location 3', 'Location 4', 'A', 'Đáp án đúng là A. Người phụ nữ nói: "put it on the top flap", và trong hình, Location 1 chỉ vào nắp trên của ba lô.
Dịch câu hỏi và đáp án:
Câu hỏi: Nhìn vào hình. Logo của công ty sẽ được đặt ở đâu?
A. Vị trí 1
B. Vị trí 2
C. Vị trí 3
D. Vị trí 4');;

-- Data for 2022 Test10 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1412, 67, '2022/test10/audio/test10_question_71_73.mp3', NULL, '**M**: Hello, I recently ordered a pair of reading glasses from your Web site. I chose blue frames, but when the package arrived, the glasses had black frames instead. I''m going to send these back to you now to be exchanged for the correct color. But I wanted to ask how long it''ll take for the blue pair to arrive. The original shipment took about three weeks, and I''d like to get the replacement sooner. My number''s **555**-**0156**. Thanks.', '**M**: Xin chào, gần đây tôi đã đặt mua một cặp kính đọc sách từ trang web của bạn. Tôi đã chọn gọng màu xanh lam, nhưng khi gói hàng đến, kính có gọng màu đen thay vào đó. Tôi sẽ gửi lại những thứ này cho bạn ngay bây giờ để đổi lấy đúng màu. Nhưng tôi muốn hỏi sẽ mất bao lâu để đôi màu xanh đến nơi. Lô hàng ban đầu mất khoảng ba tuần và tôi muốn nhận hàng thay thế sớm hơn. Số của tôi là **555**-**0156**. Cảm ơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1871, 1412, 71, 'What kind of product did the speaker order?', 'Printer ink', 'Eyeglasses', 'Picture frames', 'Furniture', 'B', 'Đáp án đúng là B. Người nói đề cập rõ ràng rằng anh ta đã đặt mua "a pair of reading glasses" (một cặp kính đọc sách).
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói đã đặt mua loại sản phẩm gì?
A. Mực in
B. Kính mắt
C. Khung ảnh
D. Đồ nội thất');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1413, 67, '2022/test10/audio/test10_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1872, 1413, 72, 'What problem does the speaker mention?', 'A package was not received.', 'An invoice is missing.', 'A product is the wrong color.', 'A Web site is down.', 'C', 'Đáp án đúng là C. Người nói cho biết anh ta đã đặt mua kính có gọng màu xanh, nhưng khi nhận được thì lại là gọng màu đen: "I chose blue frames, but when the package arrived, the glasses had black frames instead".
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói đề cập đến vấn đề gì?
A. Một gói hàng không được nhận.
B. Một hóa đơn bị thiếu.
C. Một sản phẩm có màu sắc sai.
D. Một trang web bị hỏng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1414, 67, '2022/test10/audio/test10_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1873, 1414, 73, 'What does the speaker ask about?', 'A refund policy', 'A delivery fee', 'A shipping time', 'A mailing address', 'C', 'Đáp án đúng là C. Người nói hỏi về thời gian giao hàng cho đơn hàng thay thế: "I wanted to ask how long it''ll take for the blue pair to arrive".
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói hỏi về điều gì?
A. Chính sách hoàn tiền
B. Phí giao hàng
C. Thời gian vận chuyển
D. Địa chỉ gửi thư');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1415, 67, '2022/test10/audio/test10_question_74_76.mp3', NULL, '**W**: Good afternoon, everyone. As you know, it''s time to announce our newest employee of the month, and it goes to Haru Watanabe. Congratulations! Haru did outstanding work this month securing the Thompson Limited account. He also volunteers in the community. As our winner, Haru will receive a preferred parking space right outside the building for the next **30 **days. Haru, please come up here to have your picture taken. Like all our employees of the month, your photo will be featured on the company Web site.', '**W**: Chào buổi chiều, mọi người. Như bạn đã biết, đã đến lúc công bố nhân viên mới nhất của tháng của chúng tôi, và nó thuộc về Haru Watanabe. Xin chúc mừng! Haru đã làm công việc xuất sắc trong tháng này để đảm bảo tài khoản Thompson Limited. Anh ấy cũng tình nguyện trong cộng đồng. Là người chiến thắng của chúng tôi, Haru sẽ nhận được một chỗ đậu xe ưu tiên ngay bên ngoài tòa nhà trong **30 **ngày tới. Haru, vui lòng lên đây để chụp ảnh của bạn. Giống như tất cả các nhân viên của chúng tôi trong tháng, ảnh của bạn sẽ được giới thiệu trên trang web của công ty.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1874, 1415, 74, 'What award is being announced?', 'Best design', 'Top salesperson', 'Employee of the month', 'Excellence in research', 'C', 'Đáp án đúng là C. Người nói đang công bố giải thưởng "employee of the month" (nhân viên của tháng).
Dịch câu hỏi và đáp án:
Câu hỏi: Giải thưởng nào đang được công bố?
A. Thiết kế xuất sắc nhất
B. Nhân viên bán hàng hàng đầu
C. Nhân viên của tháng
D. Xuất sắc trong nghiên cứu');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1416, 67, '2022/test10/audio/test10_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1875, 1416, 75, 'According to the speaker, what will the winner receive?', 'A commemorative plaque', 'A parking space', 'A gift certificate', 'A recognition dinner', 'B', 'Đáp án đúng là B. Người nói cho biết người thắng giải sẽ nhận được một chỗ đỗ xe ưu tiên: "Haru will receive a preferred parking space right outside the building for the next 30 days".
Dịch câu hỏi và đáp án:
Câu hỏi: Theo người nói, người thắng cuộc sẽ nhận được gì?
A. Một tấm bảng kỷ niệm
B. Một chỗ đỗ xe
C. Một phiếu quà tặng
D. Một bữa tối công nhận thành tích');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1417, 67, '2022/test10/audio/test10_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1876, 1417, 76, 'What does the speaker say will be published on a Web site?', 'A photograph', 'A biography', 'Professional accomplishments', 'Company event details', 'A', 'Đáp án đúng là A. Người nói cho biết ảnh của người thắng giải sẽ được đăng trên trang web công ty: "your photo will be featured on the company Web site".
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói cho biết điều gì sẽ được đăng trên trang web?
A. Một bức ảnh
B. Một tiểu sử
C. Thành tích chuyên môn
D. Chi tiết sự kiện công ty');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1418, 67, '2022/test10/audio/test10_question_77_79.mp3', NULL, '**M**: Hi, everyone! My name is Sanjeep Gupta. We''re excited to have so many new people working at our bicycle stores. During the week, you will learn how to repair bicycles and scooters for our customers. Before we begin your training. I''m going to show you around this model facility, which has been built to simulate the repair shop in the back of every one of our stores. Oh - a couple of you asked about your schedule this week. I''ll be overseeing your work, and I come in at eight.', '**M**: Xin chào mọi người! Tên tôi là Sanjeep Gupta. Chúng tôi rất vui khi có rất nhiều người mới làm việc tại các cửa hàng xe đạp của chúng tôi. Trong tuần, bạn sẽ học cách sửa chữa xe đạp và xe tay ga cho khách hàng của chúng tôi. Trước khi chúng tôi bắt đầu đào tạo của bạn. Tôi sẽ chỉ cho bạn xung quanh cơ sở mô hình này, được xây dựng để mô phỏng cửa hàng sửa chữa ở phía sau mỗi cửa hàng của chúng tôi. Ồ - một vài người trong số các bạn đã hỏi về lịch trình của bạn trong tuần này. Tôi sẽ giám sát công việc của bạn, và tôi đến lúc tám giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1877, 1418, 77, 'What kind of product does the speaker''s company sell?', 'Bicycles', 'Tools', 'Cars', 'Toys', 'A', 'Đáp án đúng là A. Người nói đề cập đến "our bicycle stores" và việc sửa chữa xe đạp và xe scooter, cho thấy công ty bán xe đạp.
Dịch câu hỏi và đáp án:
Câu hỏi: Công ty của người nói bán loại sản phẩm gì?
A. Xe đạp
B. Công cụ
C. Ô tô
D. Đồ chơi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1419, 67, '2022/test10/audio/test10_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1878, 1419, 78, 'What will the listeners do next?', 'Watch a video', 'Vote on a policy', 'Inspect a brochure', 'Tour a facility', 'D', 'Đáp án đúng là D. Người nói cho biết: "I''m going to show you around this model facility", nghĩa là họ sẽ tham quan một cơ sở mô hình.
Dịch câu hỏi và đáp án:
Câu hỏi: Người nghe sẽ làm gì tiếp theo?
A. Xem một video
B. Bỏ phiếu về một chính sách
C. Kiểm tra một tờ rơi
D. Tham quan một cơ sở');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1420, 67, '2022/test10/audio/test10_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1879, 1420, 79, 'What does the speaker mean when he says, "I come in at eight"?', 'He is very busy this week.', 'A store usually opens early.', 'The listeners should arrive at that time.', 'The listeners should prepare a shipment.', 'C', 'Đáp án đúng là C. Khi nói "I come in at eight", người nói ngụ ý rằng người nghe nên đến vào lúc 8 giờ, vì đó là thời gian ông ấy bắt đầu làm việc và giám sát công việc của họ.
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói có ý gì khi nói "Tôi đến lúc 8 giờ"?
A. Anh ấy rất bận trong tuần này.
B. Một cửa hàng thường mở cửa sớm.
C. Người nghe nên đến vào thời điểm đó.
D. Người nghe nên chuẩn bị một lô hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1421, 67, '2022/test10/audio/test10_question_80_82.mp3', NULL, '**M**: A new report shows that customers prefer sustainable packaging in the products they buy. In order to expand our customer base, we''ve decided to look into using biodegradable packaging for the personal care products we make. Just last month, we hired a packaging consultant to develop environmentally friendly packaging for our products. Now we need to set up a committee to oversee the project. If you''re interested in participating, contact your manager by the end of the week.', '**M**: Một báo cáo mới cho thấy khách hàng thích bao bì bền vững hơn trong các sản phẩm họ mua. Để mở rộng cơ sở khách hàng của mình, chúng tôi đã quyết định xem xét sử dụng bao bì có thể phân hủy sinh học cho các sản phẩm chăm sóc cá nhân mà chúng tôi sản xuất. Mới tháng trước, chúng tôi đã thuê một nhà tư vấn đóng gói để phát triển bao bì thân thiện với môi trường cho các sản phẩm của chúng tôi. Bây giờ chúng ta cần thành lập một ủy ban để giám sát dự án. Nếu bạn muốn tham gia, hãy liên hệ với người quản lý của bạn vào cuối tuần.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1880, 1421, 80, 'What does the speaker mainly discuss?', 'Offering training opportunities', 'Changing product packaging', 'Updating safety regulations', 'Revising an advertising strategy', 'B', 'Đáp án đúng là B. Người nói chủ yếu thảo luận về việc thay đổi bao bì sản phẩm sang loại thân thiện với môi trường.
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói chủ yếu thảo luận về điều gì?
A. Cung cấp cơ hội đào tạo
B. Thay đổi bao bì sản phẩm
C. Cập nhật quy định an toàn
D. Sửa đổi chiến lược quảng cáo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1422, 67, '2022/test10/audio/test10_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1881, 1422, 81, 'What did the company do last month?', 'It expanded its social media presence.', 'It agreed to organize a conference.', 'It published a training manual.', 'It hired an outside consultant.', 'D', 'Đáp án đúng là D. Người nói cho biết: "Just last month, we hired a packaging consultant to develop environmentally friendly packaging for our products".
Dịch câu hỏi và đáp án:
Câu hỏi: Công ty đã làm gì vào tháng trước?
A. Mở rộng sự hiện diện trên mạng xã hội.
B. Đồng ý tổ chức một hội nghị.
C. Xuất bản một sổ tay đào tạo.
D. Thuê một chuyên gia tư vấn bên ngoài.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1423, 67, '2022/test10/audio/test10_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1882, 1423, 82, 'What should interested listeners do?', 'Contact their managers', 'Recruit some volunteers', 'Answer a survey', 'Watch a video', 'A', 'Đáp án đúng là A. Người nói hướng dẫn: "If you''re interested in participating, contact your manager by the end of the week".
Dịch câu hỏi và đáp án:
Câu hỏi: Những người nghe quan tâm nên làm gì?
A. Liên hệ với quản lý của họ
B. Tuyển một số tình nguyện viên
C. Trả lời một cuộc khảo sát
D. Xem một video');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1424, 67, '2022/test10/audio/test10_question_83_85.mp3', NULL, '**W**: Thank you all for attending the thirtieth annual Dental Healthcare Conference. We have six sessions planned on the latest advances in tooth restoration. As a reminder, if you''d like to receive continuing education credit for attending the conference, you''ll have to complete additional paperwork. Some of you may want to hear more details about that. I''ll be at the booth in the lobby until noon. And finally, just a reminder that you are all invited to attend a dinner reception tonight starting right after the last presentation session.', '**W**: Cảm ơn tất cả các bạn đã tham dự Hội nghị Chăm sóc Sức khỏe Nha khoa thường niên lần thứ ba mươi. Chúng tôi có sáu phiên được lên kế hoạch về những tiến bộ mới nhất trong phục hồi răng. Xin nhắc lại, nếu bạn muốn nhận tín chỉ giáo dục thường xuyên khi tham dự hội nghị, bạn sẽ phải hoàn thành các thủ tục giấy tờ bổ sung. Một số bạn có thể muốn nghe thêm chi tiết về điều đó. Tôi sẽ ở gian hàng ở sảnh cho đến trưa. Và cuối cùng, chỉ là một lời nhắc nhở rằng tất cả các bạn đều được mời tham dự tiệc tối tối nay bắt đầu ngay sau buổi thuyết trình cuối cùng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1883, 1424, 83, 'Who most likely are the listeners?', 'Engineers', 'Dentists', 'Educators', 'Architects', 'B', 'Đáp án đúng là B. Người nói đang phát biểu tại "Dental Healthcare Conference" (Hội nghị Chăm sóc Sức khỏe Răng miệng), nên người nghe nhiều khả năng là các nha sĩ.
Dịch câu hỏi và đáp án:
Câu hỏi: Người nghe nhiều khả năng là ai?
A. Kỹ sư
B. Nha sĩ
C. Nhà giáo dục
D. Kiến trúc sư');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1425, 67, '2022/test10/audio/test10_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1884, 1425, 84, 'Why does the speaker say, "I''ll be at the booth in the lobby until noon"?', 'To request volunteers for the afternoon', 'To explain that a booth location has changed', 'To apologize for a scheduling conflict', 'To indicate availability to answer questions', 'D', 'Đáp án đúng là D. Người nói đề cập đến việc ở tại quầy trong sảnh để trả lời thêm các câu hỏi về giấy tờ cần thiết để nhận tín chỉ giáo dục liên tục.
Dịch câu hỏi và đáp án:
Câu hỏi: Tại sao người nói nói "Tôi sẽ ở quầy trong sảnh cho đến trưa"?
A. Để yêu cầu tình nguyện viên cho buổi chiều
B. Để giải thích rằng vị trí quầy đã thay đổi
C. Để xin lỗi về một xung đột lịch trình
D. Để chỉ ra sự sẵn sàng trả lời câu hỏi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1426, 67, '2022/test10/audio/test10_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1885, 1426, 85, 'What does the speaker say will happen tonight?', 'A book signing', 'A photo shoot', 'A dinner reception', 'An award ceremony', 'C', 'Đáp án đúng là C. Người nói nhắc nhở về một buổi tiệc tối: "you are all invited to attend a dinner reception tonight".
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói cho biết điều gì sẽ diễn ra tối nay?
A. Một buổi ký tặng sách
B. Một buổi chụp ảnh
C. Một bữa tiệc tối
D. Một buổi lễ trao giải');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1427, 67, '2022/test10/audio/test10_question_86_88.mp3', NULL, '**W** Welcome to this episode of our radio show, Research Now. On every show we talk to a different scientist about their work. Today''s guest is Geeta Prasad. She''s a scientist at McMillan Shoe Manufacturers. Her job is to research how people move their feet when they exercise. She then provides that data to the design team, who use it to design new shoes. In fact, her team is looking for participants to take part in their next study. To sign up, visit McMillan Shoe Manufacturers'' Web site.', '**W** Chào mừng bạn đến với tập này của chương trình phát thanh của chúng tôi, Research Now. Trong mỗi chương trình, chúng tôi nói chuyện với một nhà khoa học khác nhau về công việc của họ. Khách mời hôm nay là Geeta Prasad. Cô ấy là một nhà khoa học tại McMillan Shoe Manufacturers. Công việc của cô ấy là nghiên cứu cách mọi người di chuyển chân khi tập thể dục. Sau đó, cô ấy cung cấp dữ liệu đó cho nhóm thiết kế, họ sử dụng nó để thiết kế những đôi giày mới. Trên thực tế, nhóm của cô ấy đang tìm kiếm những người tham gia để tham gia vào nghiên cứu tiếp theo của họ. Để đăng ký, hãy truy cập trang web của McMillan Shoe Manufacturers.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1886, 1427, 86, 'What is Geeta Prasad''s profession?', 'Research scientist', 'Medical doctor', 'University professor', 'Government official', 'A', 'Đáp án đúng là A. Geeta Prasad được giới thiệu là một nhà khoa học làm việc tại McMillan Shoe Manufacturers.
Dịch câu hỏi và đáp án:
Câu hỏi: Nghề nghiệp của Geeta Prasad là gì?
A. Nhà khoa học nghiên cứu
B. Bác sĩ y khoa
C. Giáo sư đại học
D. Viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1428, 67, '2022/test10/audio/test10_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1887, 1428, 87, 'According to the speaker, what are some data used for?', 'To evaluate a budget', 'To design new products', 'To make hiring decisions', 'To develop an exercise program', 'B', 'Đáp án đúng là B. Người nói cho biết dữ liệu được cung cấp cho nhóm thiết kế để thiết kế giày mới: "She then provides that data to the design team, who use it to design new shoes".
Dịch câu hỏi và đáp án:
Câu hỏi: Theo người nói, một số dữ liệu được sử dụng để làm gì?
A. Để đánh giá ngân sách
B. Để thiết kế sản phẩm mới
C. Để đưa ra quyết định tuyển dụng
D. Để phát triển chương trình tập luyện');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1429, 67, '2022/test10/audio/test10_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1888, 1429, 88, 'Why should the listeners visit a Web site?', 'To download a manual', 'To read a report', 'To register for a study', 'To provide some feedback', 'C', 'Đáp án đúng là C. Người nói hướng dẫn người nghe truy cập trang web để đăng ký tham gia nghiên cứu: "To sign up, visit McMillan Shoe Manufacturers'' Web site".
Dịch câu hỏi và đáp án:
Câu hỏi: Tại sao người nghe nên truy cập một trang web?
A. Để tải xuống một hướng dẫn sử dụng
B. Để đọc một báo cáo
C. Để đăng ký tham gia một nghiên cứu
D. Để cung cấp phản hồi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1430, 67, '2022/test10/audio/test10_question_89_91.mp3', NULL, '**M**: Thanks for attending this management meeting. As you know, despite our strategy of positioning ourselves as a seller of high-quality furniture, we''ve been losing business to several secondhand stores selling used furniture in the area. There''s one thing that we can start doing that many other furniture stores aren''t: "offering free assembly". By developing cross-functional delivery teams, we''ll be able to gain a competitive edge. So next month, all of our delivery teams will attend sessions where they''ll learn how to assemble our products in customers'' homes.', '**M**: Cảm ơn bạn đã tham dự cuộc họp quản lý này. Như bạn đã biết, bất chấp chiến lược định vị mình là người bán đồ nội thất chất lượng cao, chúng tôi đã mất kinh doanh vào tay một số cửa hàng đồ cũ bán đồ nội thất đã qua sử dụng trong khu vực. Có một điều mà chúng ta có thể bắt đầu làm mà nhiều cửa hàng đồ nội thất khác không làm được: "cung cấp lắp ráp miễn phí". Bằng cách phát triển các nhóm phân phối đa chức năng, chúng tôi sẽ có thể đạt được lợi thế cạnh tranh. Vì vậy, vào tháng tới, tất cả các nhóm giao hàng của chúng tôi sẽ tham dự các phiên, nơi họ sẽ tìm hiểu cách lắp ráp sản phẩm của chúng tôi tại nhà của khách hàng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1889, 1430, 89, 'Where do the listeners most likely work?', 'At a home appliance store', 'At a hardware store', 'At a shipping company', 'At a furniture store', 'D', 'Đáp án đúng là D. Cuộc họp đề cập đến việc bán đồ nội thất chất lượng cao và cạnh tranh với các cửa hàng đồ nội thất khác, cho thấy người nghe làm việc tại một cửa hàng đồ nội thất.
Dịch câu hỏi và đáp án:
Câu hỏi: Những người nghe nhiều khả năng làm việc ở đâu?
A. Tại một cửa hàng thiết bị gia dụng
B. Tại một cửa hàng phần cứng
C. Tại một công ty vận chuyển
D. Tại một cửa hàng đồ nội thất');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1431, 67, '2022/test10/audio/test10_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1890, 1431, 90, 'According to the speaker, what has caused a problem?', 'Low-quality merchandise', 'Competition from other businesses', 'Increased rental costs', 'Poor customer service', 'B', 'Đáp án đúng là B. Người nói đề cập đến việc mất khách hàng cho các cửa hàng đồ cũ trong khu vực: "we''ve been losing business to several secondhand stores selling used furniture in the area".
Dịch câu hỏi và đáp án:
Câu hỏi: Theo người nói, điều gì đã gây ra vấn đề?
A. Hàng hóa chất lượng thấp
B. Cạnh tranh từ các doanh nghiệp khác
C. Chi phí thuê tăng
D. Dịch vụ khách hàng kém');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1432, 67, '2022/test10/audio/test10_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1891, 1432, 91, 'What will happen next month?', 'A focus group will be assembled.', 'A customer loyalty program will be introduced.', 'Some employees will receive training.', 'New advertisements will be designed.', 'C', 'Đáp án đúng là C. Người nói cho biết: "So next month, all of our delivery teams will attend sessions where they''ll learn how to assemble our products in customers'' homes".
Dịch câu hỏi và đáp án:
Câu hỏi: Điều gì sẽ xảy ra vào tháng tới?
A. Một nhóm tập trung sẽ được thành lập.
B. Một chương trình khách hàng thân thiết sẽ được giới thiệu.
C. Một số nhân viên sẽ được đào tạo.
D. Các quảng cáo mới sẽ được thiết kế.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1433, 67, '2022/test10/audio/test10_question_92_94.mp3', NULL, '**W**: Hello everyone. Thanks for coming to this press conference. On behalf of the City of Sommerville, I want to sincerely apologize to all community members affected by this week''s train delays. My department has received reports of delays averaging an hour at peak periods. It has become clear that the ongoing track and wire repair work has become far too disruptive for city commuters. With this week''s unacceptable delays in mind, my department, the city transportation office, is negotiating with the contractor, National Rail. That''s the company that owns the tracks and runs the trains for Sommerville. To be clear, the tracks and trains are not city property. OK, now I can take some questions.', '**W**: Xin chào mọi người. Cảm ơn vì đã đến cuộc họp báo này. Thay mặt Thành phố Sommerville, tôi muốn gửi lời xin lỗi chân thành đến tất cả các thành viên cộng đồng bị ảnh hưởng bởi sự chậm trễ của chuyến tàu trong tuần này. Bộ phận của tôi đã nhận được báo cáo về sự chậm trễ trung bình một giờ vào giờ cao điểm. Rõ ràng là công việc sửa chữa đường ray và dây điện đang diễn ra đã trở nên quá gián đoạn đối với những người đi làm trong thành phố. Với sự chậm trễ không thể chấp nhận được trong tuần này, bộ phận của tôi, văn phòng giao thông thành phố, đang đàm phán với nhà thầu, Đường sắt Quốc gia. Đó là công ty sở hữu đường ray và điều hành các chuyến tàu đến Sommerville. Để rõ ràng, đường ray và tàu hỏa không phải là tài sản của thành phố. Được rồi, bây giờ tôi có thể trả lời một số câu hỏi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1892, 1433, 92, 'Where is the speech being given?', 'At a training session', 'At a press conference', 'At a job fair', 'At a store grand opening', 'B', 'Đáp án đúng là B. Người nói bắt đầu bằng cách cảm ơn mọi người đã đến tham dự cuộc họp báo: "Thanks for coming to this press conference".
Dịch câu hỏi và đáp án:
Câu hỏi: Bài phát biểu được đưa ra ở đâu?
A. Tại một buổi đào tạo
B. Tại một cuộc họp báo
C. Tại một hội chợ việc làm
D. Tại buổi khai trương một cửa hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1434, 67, '2022/test10/audio/test10_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1893, 1434, 93, 'Why does the speaker apologize?', 'Some repair work has caused delays.', 'Some employees have been transferred.', 'Some materials have not arrived.', 'Some businesses have been temporarily closed.', 'A', 'Đáp án đúng là A. Người nói xin lỗi vì sự chậm trễ của tàu do công việc sửa chữa đường ray và dây điện: "the ongoing track and wire repair work has become far too disruptive for city commuters".
Dịch câu hỏi và đáp án:
Câu hỏi: Tại sao người nói xin lỗi?
A. Một số công việc sửa chữa đã gây ra sự chậm trễ.
B. Một số nhân viên đã được chuyển đi.
C. Một số vật liệu chưa đến.
D. Một số doanh nghiệp đã tạm thời đóng cửa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1435, 67, '2022/test10/audio/test10_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1894, 1435, 94, 'What does the speaker mean when she says, "the tracks and trains are not city property"?', 'She did not follow a recommendation.', 'She is not responsible for a problem.', 'Some directions were misleading.', 'A contract contained errors.', 'B', 'Đáp án đúng là B. Khi nói rằng đường ray và tàu không phải là tài sản của thành phố, người nói ngụ ý rằng thành phố không chịu trách nhiệm trực tiếp về vấn đề này.
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói có ý gì khi cô ấy nói "các đường ray và tàu không phải là tài sản của thành phố"?
A. Cô ấy đã không tuân theo một khuyến nghị.
B. Cô ấy không chịu trách nhiệm về một vấn đề.
C. Một số hướng dẫn đã gây hiểu lầm.
D. Một hợp đồng có chứa lỗi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1436, 67, '2022/test10/audio/test10_question_95_97.mp3', '2022/test10/image/test10-p4-image-95.jpg', '**W**: Hi, Susan. It''s Maria. You asked me to suggest a new hairstyle for your appointment tomorrow. I''d recommend something cut all the way up to your chin. I think that a style like this would give you a very professional look. I''ll show you the picture from my hairstyle catalog when you come in. If you''d like me to blow-dry your hair during your appointment, that''s included in the price. Oh, and by the way, yesterday we got a shipment in of the Hydro Five hair moisturizer that always sells out. I know you like to use it. so I thought you might want to know.', '**W**: Chào, Susan. Đó là Maria. Bạn đã yêu cầu tôi đề xuất một kiểu tóc mới cho cuộc hẹn của bạn vào ngày mai. Tôi khuyên bạn nên cắt thứ gì đó đến tận cằm của bạn. Tôi nghĩ rằng một phong cách như thế này sẽ mang lại cho bạn một cái nhìn rất chuyên nghiệp. Tôi sẽ cho bạn xem bức ảnh từ danh mục kiểu tóc của tôi khi bạn vào. Nếu bạn muốn tôi sấy tóc cho bạn trong cuộc hẹn của bạn, điều đó đã được bao gồm trong giá. Ồ, và nhân tiện, hôm qua chúng tôi đã nhận được một lô hàng kem dưỡng tóc Hydro Five luôn bán hết. Tôi biết bạn thích sử dụng nó. vì vậy tôi nghĩ bạn có thể muốn biết.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1895, 1436, 95, 'Look at the graphic. Which hairstyle does the speaker recommend?', 'Style 1', 'Style 2', 'Style 3', 'Style 4', 'C', 'Đáp án đúng là C. Người nói đề xuất một kiểu tóc cắt đến cằm: "I''d recommend something cut all the way up to your chin". Trong hình, Style 3 là kiểu tóc ngắn đến cằm.
Dịch câu hỏi và đáp án:
Câu hỏi: Nhìn vào hình. Người nói đề xuất kiểu tóc nào?
A. Kiểu 1
B. Kiểu 2
C. Kiểu 3
D. Kiểu 4');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1437, 67, '2022/test10/audio/test10_question_95_97.mp3', '2022/test10/image/Image 1', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1896, 1437, 96, 'What does the speaker say is included in the price?', 'A comb', 'A beverage', 'Blow-drying', 'Hair care instructions', 'C', 'Đáp án đúng là C. Người nói cho biết: "If you''d like me to blow-dry your hair during your appointment, that''s included in the price".
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói nói điều gì được bao gồm trong giá?
A. Một cái lược
B. Một đồ uống
C. Sấy tóc
D. Hướng dẫn chăm sóc tóc');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1438, 67, '2022/test10/audio/test10_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1897, 1438, 97, 'What does the speaker say happened yesterday?', 'A photo shoot was held.', 'A popular product arrived.', 'A new hairstylist was hired.', 'A product demonstration was conducted.', 'B', 'Đáp án đúng là B. Người nói đề cập đến việc nhận được một lô hàng sản phẩm dưỡng ẩm tóc phổ biến: "yesterday we got a shipment in of the Hydro Five hair moisturizer that always sells out".
Dịch câu hỏi và đáp án:
Câu hỏi: Người nói nói điều gì đã xảy ra hôm qua?
A. Một buổi chụp ảnh đã được tổ chức.
B. Một sản phẩm phổ biến đã đến.
C. Một nhà tạo mẫu tóc mới đã được thuê.
D. Một buổi trình diễn sản phẩm đã được thực hiện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1439, 67, '2022/test10/audio/test10_question_98_100.mp3', '2022/test10/image/test10-p4-image-98.jpg', '**M**: Our first topic is an update on the data analytic software we installed last week to identify problems with our plastic molding machines. As I''m sure you''re aware, we''ve missed our production targets for the last two quarters. That means we''re spending too much time assembling our products. As you can see on this chart, the data show that one of our machines is running a very slow production cycle at an average of six minutes, twenty-two seconds per cycle. We''ve already flagged it for repair by a technician. By next week, that machine should be at normal output. We''re very optimistic about the impact the new analytic software will have on next quarter''s targets.', '**M**: Chủ đề đầu tiên của chúng tôi là bản cập nhật về phần mềm phân tích dữ liệu mà chúng tôi đã cài đặt vào tuần trước để xác định các vấn đề với máy đúc nhựa của chúng tôi. Như tôi chắc rằng bạn đã biết, chúng tôi đã bỏ lỡ các mục tiêu sản xuất của mình trong hai quý qua. Điều đó có nghĩa là chúng tôi đang dành quá nhiều thời gian để lắp ráp các sản phẩm của mình. Như bạn có thể thấy trên biểu đồ này, dữ liệu cho thấy một trong những máy của chúng tôi đang chạy chu kỳ sản xuất rất chậm với trung bình sáu phút, hai mươi hai giây mỗi chu kỳ. Chúng tôi đã gắn cờ thiết bị để kỹ thuật viên sửa chữa. Đến tuần tới, máy đó sẽ ở mức đầu ra bình thường. Chúng tôi rất lạc quan về tác động của phần mềm phân tích mới đối với các mục tiêu của quý tới.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1898, 1439, 98, 'According to the speaker, what did the company do last week?', 'It installed software to monitor machines.', 'It added a new machine to an assembly line.', 'It hired some expert technicians.', 'It reorganized a production team.', 'A', 'Đáp án đúng là A. Người nói đề cập đến việc cài đặt phần mềm phân tích dữ liệu tuần trước: "the data analytic software we installed last week".
Dịch câu hỏi và đáp án:
Câu hỏi: Theo người nói, công ty đã làm gì vào tuần trước?
A. Nó đã cài đặt phần mềm để giám sát máy móc.
B. Nó đã thêm một máy mới vào dây chuyền lắp ráp.
C. Nó đã thuê một số kỹ thuật viên chuyên gia.
D. Nó đã tổ chức lại một đội sản xuất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1440, 67, '2022/test10/audio/test10_question_98_100.mp3', NULL, 'Image 2', NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1899, 1440, 99, 'Look at the graphic. Which machine will a technician look at?', 'Machine 1', 'Machine 2', 'Machine 3', 'Machine 4', 'B', 'Đáp án đúng là B. Người nói đề cập đến một máy có chu kỳ sản xuất chậm với thời gian trung bình là 6 phút 22 giây mỗi chu kỳ. Trong bảng, Machine 2 có Cycle Duration là 6:22.
Dịch câu hỏi và đáp án:
Câu hỏi: Nhìn vào hình. Kỹ thuật viên sẽ kiểm tra máy nào?
A. Máy 1
B. Máy 2
C. Máy 3
D. Máy 4');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1441, 67, '2022/test10/audio/test10_question_98_100.mp3', '2022/test10/image/Image 2', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1900, 1441, 100, 'What does the company hope to do next quarter?', 'Update their logo', 'Meet their production targets', 'Purchase similar technologies', 'Begin replacing outdated computers', 'B', 'Đáp án đúng là B. Người nói đề cập đến việc lạc quan về tác động của phần mềm phân tích mới đối với mục tiêu của quý tiếp theo, ngụ ý rằng họ hy vọng sẽ đạt được mục tiêu sản xuất.
Dịch câu hỏi và đáp án:
Câu hỏi: Công ty hy vọng sẽ làm gì vào quý tới?
A. Cập nhật logo của họ
B. Đạt mục tiêu sản xuất của họ
C. Mua các công nghệ tương tự
D. Bắt đầu thay thế các máy tính lỗi thời');;

-- Data for 2022 Test10 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1442, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1901, 1442, 101, 'A ----- salesperson assisted Ms. Han with choosing a new computer.', 'help', 'helpfully', 'helpful', 'helped', 'C', 'Đáp án đúng là (C) helpful. Tính từ "helpful" (hữu ích) phù hợp nhất để mô tả người bán hàng. Cấu trúc "a + adjective + noun" được sử dụng để mô tả đặc điểm của một người. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Một nhân viên bán hàng -- đã giúp cô Han chọn một máy tính mới.
A. giúp đỡ (động từ)
B. một cách hữu ích (trạng từ)
C. hữu ích (tính từ)
D. đã giúp (động từ quá khứ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1443, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1902, 1443, 102, 'Author Daniel Aiduk ----- gives talks at national writing conferences.', 'gradually', 'longer', 'together', 'regularly', 'D', 'Đáp án đúng là (D) regularly. Trạng từ "regularly" (thường xuyên) phù hợp nhất để mô tả tần suất của hoạt động. Cấu trúc "subject + adverb + verb" được sử dụng để mô tả cách thức một hành động được thực hiện. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Tác giả Daniel Aiduk -- - thuyết trình tại các hội nghị viết lách quốc gia.
A. dần dần (trạng từ)
B. lâu hơn (trạng từ so sánh)
C. cùng nhau (trạng từ)
D. thường xuyên (trạng từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1444, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1903, 1444, 103, 'Mr. Kohl has a great deal of ----- performing cost analysis tasks.', 'experience', 'experienced', 'experiencing', 'experiencer', 'A', 'Đáp án đúng là (A) experience. Danh từ "experience" (kinh nghiệm) phù hợp nhất để hoàn thành cụm từ "a great deal of" (rất nhiều). Cấu trúc "a great deal of + noun" được sử dụng để chỉ một lượng lớn. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Ông Kohl có rất nhiều - trong việc thực hiện các nhiệm vụ phân tích chi phí.
A. kinh nghiệm (danh từ)
B. có kinh nghiệm (tính từ)
C. đang trải nghiệm (động từ hiện tại phân từ)
D. người trải nghiệm (danh từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1445, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1904, 1445, 104, 'To make an -----, clients can click on "Schedule" at the top right corner of the home page.', 'example', 'option', 'individual', 'appointment', 'D', 'Đáp án đúng là (D) appointment. Danh từ "appointment" (cuộc hẹn) phù hợp nhất trong ngữ cảnh về việc đặt lịch. Cấu trúc "make an + noun" được sử dụng để chỉ việc tạo ra hoặc sắp xếp một điều gì đó. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Để tạo một -., khách hàng có thể nhấp vào "Lịch" ở góc trên bên phải của trang chủ.
A. ví dụ (danh từ)
B. lựa chọn (danh từ)
C. cá nhân (danh từ)
D. cuộc hẹn (danh từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1446, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1905, 1446, 105, 'The used coffee grounds should be disposed of at the end of ------ business day.', 'now', 'each', 'whose', 'and', 'B', 'Đáp án đúng là (B) each. Từ hạn định "each" (mỗi) phù hợp nhất để chỉ ra rằng hành động cần được thực hiện vào cuối mỗi ngày làm việc. Cấu trúc "each + noun" được sử dụng để chỉ mọi thành viên trong một nhóm. Các đáp án khác không phù hợp về nghĩa hoặc ngữ pháp trong ngữ cảnh này.
Dịch: Bã cà phê đã sử dụng nên được vứt bỏ vào cuối -- ngày làm việc.
A. bây giờ (trạng từ)
B. mỗi (từ hạn định)
C. của ai (đại từ nghi vấn)
D. và (liên từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1447, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1906, 1447, 106, 'Our company''s efforts to hire new workers have intensified --- So many employees have recently retired.', 'because', 'although', 'instead', 'unless', 'A', 'Đáp án đúng là (A) because. Liên từ "because" (bởi vì) phù hợp nhất để giải thích lý do cho việc tăng cường tuyển dụng. Cấu trúc "because + clause" được sử dụng để đưa ra lý do cho một hành động hoặc tình huống. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Nỗ lực tuyển dụng nhân viên mới của công ty chúng tôi đã tăng cường --- Rất nhiều nhân viên gần đây đã nghỉ hưu.
A. bởi vì (liên từ)
B. mặc dù (liên từ)
C. thay vào đó (trạng từ)
D. trừ khi (liên từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1448, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1907, 1448, 107, 'The occurrence of heavy rains during the month of May is fairly ----.', 'predict', 'predicts', 'predicting', 'predictable', 'D', 'Đáp án đúng là (D) predictable. Tính từ "predictable" (có thể dự đoán được) phù hợp nhất để mô tả khả năng dự báo của hiện tượng thời tiết. Cấu trúc "is + adverb + adjective" được sử dụng để mô tả một đặc điểm. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Sự xuất hiện của mưa lớn trong tháng Năm là khá ----.
A. dự đoán (động từ nguyên mẫu)
B. dự đoán (động từ ngôi thứ 3 số ít)
C. đang dự đoán (động từ hiện tại phân từ)
D. có thể dự đoán được (tính từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1449, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1908, 1449, 108, 'Remind customers to return their rental car ----- a full tank of fuel.', 'with', 'from', 'except', 'toward', 'A', 'Đáp án đúng là (A) with. Giới từ "with" (với) phù hợp nhất để chỉ ra điều kiện trả xe. Cấu trúc "with + noun phrase" được sử dụng để chỉ ra một trạng thái hoặc điều kiện kèm theo. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Nhắc nhở khách hàng trả xe thuê ----- một bình xăng đầy.
A. với (giới từ)
B. từ (giới từ)
C. ngoại trừ (giới từ)
D. hướng tới (giới từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1450, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1909, 1450, 109, '---- the winter season, Serina Builders will once again offer roof installations and repairs.', 'Such as', 'Moreover', 'After', 'Whereas', 'C', 'Đáp án đúng là (C) After. Giới từ "After" (Sau) phù hợp nhất để chỉ ra thời điểm công ty sẽ cung cấp dịch vụ. Cấu trúc "After + noun phrase, clause" được sử dụng để chỉ ra một chuỗi sự kiện theo thời gian. Các đáp án khác không phù hợp về nghĩa hoặc cấu trúc trong ngữ cảnh này.
Dịch: ---- mùa đông, Serina Builders sẽ một lần nữa cung cấp dịch vụ lắp đặt và sửa chữa mái nhà.
A. Chẳng hạn như (cụm từ)
B. Hơn nữa (liên từ)
C. Sau (giới từ)
D. Trong khi (liên từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1451, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1910, 1451, 110, 'The lights in the cinema --- before a movie begins.', 'dim', 'dimming', 'dimmer', 'dims', 'A', 'Đáp án đúng là (A) dim. Động từ "dim" (làm mờ đi) ở dạng nguyên mẫu phù hợp nhất để mô tả hành động thường xuyên xảy ra. Cấu trúc "subject + verb" được sử dụng để diễn tả một thực tế hoặc thói quen. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Đèn trong rạp chiếu phim --- trước khi một bộ phim bắt đầu.
A. làm mờ đi (động từ nguyên mẫu)
B. đang làm mờ đi (động từ hiện tại phân từ)
C. mờ hơn (tính từ so sánh)
D. làm mờ đi (động từ ngôi thứ 3 số ít)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1452, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1911, 1452, 111, 'When scheduling a meeting, please be ---- of colleagues in other time zones.', 'significant', 'mindful', 'exclusive', 'serious', 'B', 'Đáp án đúng là (B) mindful. Tính từ "mindful" (chú ý) phù hợp nhất để khuyên người đặt lịch họp cân nhắc đến đồng nghiệp ở các múi giờ khác. Cấu trúc "be + adjective + of" được sử dụng để chỉ ra sự quan tâm hoặc chú ý đến điều gì đó. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Khi lên lịch họp, vui lòng ---- đến các đồng nghiệp ở các múi giờ khác.
A. quan trọng (tính từ)
B. chú ý (tính từ)
C. độc quyền (tính từ)
D. nghiêm túc (tính từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1453, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1912, 1453, 112, 'Greentrim''s product sales rose ---- following the introduction of its new shipping policy.', 'sharp', 'sharper', 'sharply', 'sharpest', 'C', 'Đáp án đúng là (C) sharply. Trạng từ "sharply" (đột ngột) phù hợp nhất để mô tả cách thức doanh số tăng. Cấu trúc "verb + adverb" được sử dụng để mô tả cách thức một hành động diễn ra. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Doanh số sản phẩm của Greentrim tăng ---- sau khi giới thiệu chính sách vận chuyển mới.
A. sắc nét (tính từ)
B. sắc nét hơn (tính từ so sánh)
C. đột ngột (trạng từ)
D. sắc nét nhất (tính từ so sánh nhất)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1454, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1913, 1454, 113, 'Please ----- Hearnshaw for all your home appliance needs.', 'assemble', 'balance', 'share', 'consider', 'D', 'Đáp án đúng là (D) consider. Động từ "consider" (xem xét) phù hợp nhất trong ngữ cảnh về việc chọn một công ty cho nhu cầu thiết bị gia dụng. Cấu trúc "verb + noun" được sử dụng để chỉ ra một hành động đối với một đối tượng. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Vui lòng -- Hearnshaw cho tất cả nhu cầu thiết bị gia dụng của bạn.
A. lắp ráp (động từ)
B. cân bằng (động từ)
C. chia sẻ (động từ)
D. xem xét (động từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1455, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1914, 1455, 114, 'Monday will be the best day for —--- to clean the carpet in the lobby.', 'we', 'us', 'ours', 'ourselves', 'B', 'Đáp án đúng là (B) us. Đại từ tân ngữ "us" (chúng tôi) phù hợp nhất sau giới từ "for". Cấu trúc "for + object pronoun" được sử dụng để chỉ ra đối tượng hưởng lợi hoặc thực hiện một hành động. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Thứ Hai sẽ là ngày tốt nhất cho —- để làm sạch thảm ở sảnh.
A. chúng tôi (đại từ chủ ngữ)
B. chúng tôi (đại từ tân ngữ)
C. của chúng tôi (đại từ sở hữu)
D. chính chúng tôi (đại từ phản thân)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1456, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1915, 1456, 115, 'Hikers, ----- to explore the newly opened trails, have been visiting Millar Nature Reserve in record numbers.', 'tender', 'bright', 'vast', 'eager', 'D', 'Đáp án đúng là (D) eager. Tính từ "eager" (háo hức) phù hợp nhất để mô tả thái độ của những người đi bộ đường dài. Cấu trúc "adjective + to + verb" được sử dụng để chỉ ra mong muốn làm một điều gì đó. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Những người đi bộ đường dài, --- khám phá những con đường mòn mới mở, đã đến thăm Khu Bảo tồn Thiên nhiên Millar với số lượng kỷ lục.
A. mềm mại (tính từ)
B. sáng sủa (tính từ)
C. rộng lớn (tính từ)
D. háo hức (tính từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1457, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1916, 1457, 116, 'KOHW ----- Jenae Johnson will be promoted to news anchor when Dana Wagner retires.', 'reporter', 'reporting', 'to report', 'will report', 'A', 'Đáp án đúng là (A) reporter. Danh từ "reporter" (phóng viên) phù hợp nhất để mô tả vị trí hiện tại của Jenae Johnson. Cấu trúc này là một mệnh đề độc lập, và danh từ được sử dụng như một từ bổ nghĩa cho tên riêng. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Phóng viên KOHW Jenae Johnson sẽ được thăng chức lên vị trí dẫn chương trình tin tức khi Dana Wagner nghỉ hưu.
A. phóng viên (danh từ)
B. đang báo cáo (động từ hiện tại phân từ)
C. để báo cáo (động từ nguyên mẫu)
D. sẽ báo cáo (động từ tương lai)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1458, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1917, 1458, 117, 'Residents ---- raised concerns about the project''s impact on traffic congestion.', 'extremely', 'unlikely', 'densely', 'primarily', 'D', 'Đáp án đúng là (D) primarily. Trạng từ "primarily" (chủ yếu) phù hợp nhất để chỉ ra mối quan tâm chính của cư dân. Cấu trúc "adverb + verb" được sử dụng để mô tả cách thức một hành động được thực hiện. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Cư dân - - đã nêu lên những lo ngại về tác động của dự án đối với tình trạng tắc nghẽn giao thông.
A. cực kỳ (trạng từ)
B. không chắc (tính từ)
C. dày đặc (trạng từ)
D. chủ yếu (trạng từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1459, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1918, 1459, 118, '---- your Fromo grocery order is placed before 10:00 A.M., it will be delivered the same day.', 'That', 'Such', 'As long as', 'In spite of', 'C', 'Đáp án đúng là (C) As long as. Cụm từ nối "As long as" (Miễn là) phù hợp nhất để chỉ ra điều kiện cho việc giao hàng cùng ngày. Cấu trúc "As long as + clause, main clause" được sử dụng để chỉ ra một điều kiện. Các đáp án khác không phù hợp về nghĩa hoặc cấu trúc trong ngữ cảnh này.
Dịch: - đơn hàng tạp hóa Fromo của bạn được đặt trước 10:00 sáng, nó sẽ được giao trong cùng ngày.
A. Điều đó (đại từ chỉ định)
B. Như vậy (từ chỉ định)
C. Miễn là (cụm từ nối)
D. Mặc dù (cụm từ nối)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1460, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1919, 1460, 119, 'The finance department will be ---- a lunch-and-learn session on Wednesday.', 'contacting', 'collecting', 'meeting', 'holding', 'D', 'Đáp án đúng là (D) holding. Động từ "holding" (tổ chức) phù hợp nhất để mô tả việc diễn ra một buổi học. Cấu trúc "will be + verb-ing" được sử dụng để diễn tả một hành động đã được lên kế hoạch trong tương lai. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Phòng tài chính sẽ - một buổi học kết hợp ăn trưa vào thứ Tư.
A. liên hệ (động từ)
B. thu thập (động từ)
C. gặp gỡ (động từ)
D. tổ chức (động từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1461, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1920, 1461, 120, '---- clothing must be worn by all personnel entering the construction zone.', 'Protective', 'Protecting', 'Protect', 'Protects', 'A', 'Đáp án đúng là (A) Protective. Tính từ "Protective" (bảo hộ) phù hợp nhất để mô tả loại quần áo cần thiết. Cấu trúc "adjective + noun" được sử dụng để mô tả đặc điểm của một đối tượng. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Quần áo ---- phải được mặc bởi tất cả nhân viên khi vào khu vực xây dựng.
A. bảo hộ (tính từ)
B. đang bảo vệ (động từ hiện tại phân từ)
C. bảo vệ (động từ nguyên mẫu)
D. bảo vệ (động từ ngôi thứ 3 số ít)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1462, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1921, 1462, 121, 'At the Star Elite membership level, most flight changes can be made --- incurring a rebooking fee.', 'along', 'without', 'until', 'inside', 'B', 'Đáp án đúng là (B) without. Giới từ "without" (mà không) phù hợp nhất để chỉ ra việc không phải trả phí đổi vé. Cấu trúc "without + verb-ing" được sử dụng để chỉ ra một hành động không xảy ra. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Ở cấp độ thành viên Star Elite, hầu hết các thay đổi chuyến bay có thể được thực hiện --- phải trả phí đặt lại vé.
A. dọc theo (giới từ)
B. mà không (giới từ)
C. cho đến khi (giới từ)
D. bên trong (giới từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1463, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1922, 1463, 122, 'Any letter ----- sensitive information should be sent using a courier service.', 'contains', 'containing', 'will contain', 'has contained', 'B', 'Đáp án đúng là (B) containing. Động từ hiện tại phân từ "containing" (chứa) phù hợp nhất để mô tả nội dung của thư. Cấu trúc "noun + verb-ing" được sử dụng để mô tả đặc điểm của một đối tượng. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Bất kỳ lá thư nào --- thông tin nhạy cảm nên được gửi bằng dịch vụ chuyển phát nhanh.
A. chứa (động từ hiện tại)
B. chứa (động từ hiện tại phân từ)
C. sẽ chứa (động từ tương lai)
D. đã chứa (động từ hiện tại hoàn thành)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1464, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1923, 1464, 123, 'Abelos Café sources its vegetables and fruit from local farms ----- possible.', 'anyhow', 'whenever', 'once', 'very', 'B', 'Đáp án đúng là (B) whenever. Trạng từ "whenever" (bất cứ khi nào) phù hợp nhất để chỉ ra tần suất của hành động. Cấu trúc "whenever + possible" là một cụm từ phổ biến có nghĩa là "càng thường xuyên càng tốt". Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Abelos Café lấy nguồn rau và trái cây từ các trang trại địa phương ----- có thể.
A. dù sao đi nữa (trạng từ)
B. bất cứ khi nào (trạng từ)
C. một khi (liên từ)
D. rất (trạng từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1465, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1924, 1465, 124, 'Demand for the Waterlace running shoes was so high that the store owner set a ----- of two pairs per customer.', 'limit', 'price', 'supply', 'procedure', 'A', 'Đáp án đúng là (A) limit. Danh từ "limit" (giới hạn) phù hợp nhất trong ngữ cảnh về việc hạn chế số lượng mua. Cấu trúc "set a + noun" được sử dụng để chỉ ra việc thiết lập một quy định hoặc giới hạn. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Nhu cầu đối với giày chạy bộ Waterlace cao đến mức chủ cửa hàng đã đặt ra một -- hai đôi cho mỗi khách hàng.
A. giới hạn (danh từ)
B. giá (danh từ)
C. nguồn cung (danh từ)
D. quy trình (danh từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1466, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1925, 1466, 125, 'The new security camera adjusts —--- in such a way that it can record quality video at night.', 'himself', 'oneself', 'itself', 'herself', 'C', 'Đáp án đúng là (C) itself. Đại từ phản thân "itself" (chính nó) phù hợp nhất để chỉ ra rằng camera tự điều chỉnh. Cấu trúc "verb + reflexive pronoun" được sử dụng khi chủ thể thực hiện hành động đối với chính mình. Các đáp án khác không phù hợp về mặt ngữ pháp hoặc nghĩa trong ngữ cảnh này.
Dịch: Camera an ninh mới điều chỉnh —--- theo cách có thể ghi hình chất lượng vào ban đêm.
A. chính anh ấy (đại từ phản thân)
B. chính mình (đại từ phản thân)
C. chính nó (đại từ phản thân)
D. chính cô ấy (đại từ phản thân)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1467, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1926, 1467, 126, 'Contact Ms. Meyer if you would like a hard copy of the budget analysis --- during the president''s presentation.', 'occurred', 'mentioned', 'learned', 'served', 'B', 'Đáp án đúng là (B) mentioned. Động từ quá khứ phân từ "mentioned" (được đề cập) phù hợp nhất để mô tả thông tin đã được trình bày. Cấu trúc "noun + past participle" được sử dụng để mô tả một đối tượng đã trải qua một hành động. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Liên hệ với cô Meyer nếu bạn muốn có bản cứng của bản phân tích ngân sách --- trong bài thuyết trình của chủ tịch.
A. đã xảy ra (động từ quá khứ)
B. được đề cập (động từ quá khứ phân từ)
C. đã học (động từ quá khứ)
D. đã phục vụ (động từ quá khứ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1468, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1927, 1468, 127, 'Saul''s Pizzeria changed its menu options after receiving ----- negative customer feedback.', 'increase', 'increases', 'to increase', 'increasingly', 'D', 'Đáp án đúng là (D) increasingly. Trạng từ "increasingly" (ngày càng) phù hợp nhất để mô tả mức độ tăng của phản hồi tiêu cực. Cấu trúc "adverb + adjective" được sử dụng để mô tả mức độ của một tính chất. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Tiệm pizza của Saul đã thay đổi các lựa chọn trong thực đơn sau khi nhận được phản hồi tiêu cực -- từ khách hàng.
A. tăng (động từ)
B. tăng (động từ ngôi thứ 3 số ít)
C. để tăng (động từ nguyên mẫu)
D. ngày càng (trạng từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1469, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1928, 1469, 128, 'Topticolor produces devices intended for use by ----- photographers.', 'visible', 'eventual', 'amateur', 'necessary', 'C', 'Đáp án đúng là (C) amateur. Tính từ "amateur" (nghiệp dư) phù hợp nhất để mô tả loại nhiếp ảnh gia mà sản phẩm nhắm đến. Cấu trúc "adjective + noun" được sử dụng để mô tả đặc điểm của một đối tượng. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Topticolor sản xuất các thiết bị dành cho ----- nhiếp ảnh gia sử dụng.
A. có thể nhìn thấy (tính từ)
B. cuối cùng (tính từ)
C. nghiệp dư (tính từ)
D. cần thiết (tính từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1470, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1929, 1470, 129, 'The study of consumer behavior will be repeated in order to ensure the ---- of the results.', 'rely', 'relies', 'reliable', 'reliability', 'D', 'Đáp án đúng là (D) reliability. Danh từ "reliability" (độ tin cậy) phù hợp nhất để chỉ ra mục đích của việc lặp lại nghiên cứu. Cấu trúc "the + noun" được sử dụng để chỉ một khái niệm cụ thể. Các đáp án khác không phù hợp về mặt ngữ pháp trong cấu trúc này.
Dịch: Nghiên cứu về hành vi người tiêu dùng sẽ được lặp lại để đảm bảo ---- của kết quả.
A. tin cậy (động từ)
B. tin cậy (động từ ngôi thứ 3 số ít)
C. đáng tin cậy (tính từ)
D. độ tin cậy (danh từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1471, 68, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1930, 1471, 130, 'Check e-mail ----- throughout the day to make sure important client communications are not overlooked.', 'artificially', 'periodically', 'reluctantly', 'simultaneously', 'B', 'Đáp án đúng là (B) periodically. Trạng từ "periodically" (định kỳ) phù hợp nhất để mô tả tần suất kiểm tra email. Cấu trúc "verb + adverb" được sử dụng để mô tả cách thức thực hiện một hành động. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này.
Dịch: Kiểm tra e-mail ----- trong suốt ngày để đảm bảo không bỏ sót các thông tin liên lạc quan trọng của khách hàng.
A. một cách giả tạo (trạng từ)
B. định kỳ (trạng từ)
C. miễn cưỡng (trạng từ)
D. đồng thời (trạng từ)');;

-- Data for 2022 Test10 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1472, 69, NULL, NULL, 'Hemel Bookstore is seeking temporary store associates 131--- the upcoming holiday season. Duties will include greeting customers and answering questions. 132--- In addition, associates will Shelve, clean, and organize merchandise. We want to hire friendly and 133--- candidates. To apply, please fill out an online job application at www.hemelbookstore.com/application. The 134--- is October 21.', 'Hiệu sách Hemel đang tìm kiếm nhân viên cửa hàng tạm thời 131--- trong kỳ nghỉ lễ sắp tới. Nhiệm vụ sẽ bao gồm chào hỏi khách hàng và trả lời các câu hỏi. 132--- Ngoài ra, các cộng sự sẽ xếp hàng, dọn dẹp và sắp xếp hàng hóa. Chúng tôi muốn tuyển dụng các ứng viên thân thiện và 133---. Để nộp đơn, vui lòng điền vào đơn xin việc trực tuyến tại www.hemelbookstore.com/application. 134--- là ngày 21 tháng 10.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1931, 1472, 131, NULL, 'about', 'on', 'to', 'for', 'D', 'Đáp án D "for" là đúng vì nó phù hợp với ngữ cảnh tìm kiếm nhân viên cho mùa lễ hội sắp tới.

Dịch các đáp án:
A. about (giới từ): về
B. on (giới từ): vào
C. to (giới từ): đến
D. for (giới từ): cho');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1932, 1472, 132, NULL, 'The job also involves processing sales transactions.', 'We stay open until midnight during the holidays.', 'Our bookstore carries art supplies as well.', 'The café is on the first floor of the store.', 'A', 'Đáp án A "The job also involves processing sales transactions." là đúng vì nó bổ sung thông tin về nhiệm vụ của nhân viên.

Dịch các đáp án:
A. The job also involves processing sales transactions. (Công việc cũng bao gồm xử lý các giao dịch bán hàng.)
B. We stay open until midnight during the holidays. (Chúng tôi mở cửa đến nửa đêm trong những ngày lễ.)
C. Our bookstore carries art supplies as well. (Hiệu sách của chúng tôi cũng bán đồ dùng mỹ thuật.)
D. The café is on the first floor of the store. (Quán cà phê nằm ở tầng một của cửa hàng.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1933, 1472, 133, NULL, 'energetic', 'energy', 'energize', 'energizer', 'A', 'Đáp án A "energetic" là đúng vì nó là một tính từ phù hợp để mô tả ứng viên họ muốn thuê.

Dịch các đáp án:
A. energetic (tính từ): năng động
B. energy (danh từ): năng lượng
C. energize (động từ): làm tăng sinh lực
D. energizer (danh từ): người/vật làm tăng sinh lực');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1934, 1472, 134, NULL, 'celebration', 'release', 'deadline', 'meeting', 'C', 'Đáp án C "deadline" là đúng vì nó phù hợp với ngữ cảnh về hạn chót nộp đơn.

Dịch các đáp án:
A. celebration (danh từ): lễ kỷ niệm
B. release (danh từ): sự phát hành
C. deadline (danh từ): hạn chót
D. meeting (danh từ): cuộc họp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1473, 69, NULL, NULL, 'Fishing Village to Become Bustling Port
DODOMA (14 April)-The unassuming town of Kikole, on the Tanzanian coast, is set to become a fully equipped port after an increase in 135--- in the region. The government has recently
designated the area as a business district. This 136--- attract new busnesses and further spur economic growth. One firm, Marina International Shipping, has already announced plans to open a hub there. 137---.
A number of government officials have recently expressed opposition to the plan. 138--- with the needed finances already secured, it seems certain that the project will move forward.', 'Làng chài trở thành cảng nhộn Nhịp
DODOMA (14 tháng 4)-Thị trấn khiêm tốn Kikole, trên bờ biển Tanzania, được thiết lập để trở thành một cảng được trang bị đầy đủ sau khi tăng 135 --- trong khu vực. Chính phủ gần đây đã
chỉ định khu vực này là một khu thương mại. 136--- này thu hút các doanh nghiệp mới và thúc đẩy tăng trưởng kinh tế hơn nữa. Một công ty, Marina International Shipping, đã công bố kế hoạch mở một trung tâm ở đó. 137---.
Một số quan chức chính phủ gần đây đã bày tỏ sự phản đối đối với kế hoạch. 138--- với nguồn tài chính cần thiết đã được đảm bảo, có vẻ như chắc chắn rằng dự án sẽ tiến lên phía trước.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1935, 1473, 135, NULL, 'security', 'tourism', 'investment', 'fishing', 'C', 'Đáp án C "investment" là đúng vì nó phù hợp với ngữ cảnh về sự phát triển kinh tế trong khu vực.

Dịch các đáp án:
A. security (danh từ): an ninh
B. tourism (danh từ): du lịch
C. investment (danh từ): đầu tư
D. fishing (danh từ): đánh bắt cá');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1936, 1473, 136, NULL, 'is meant to', 'means to', 'meaning to', 'is meant for', 'A', 'Đáp án A "is meant to" là đúng vì nó là cụm từ phù hợp để diễn đạt mục đích hoặc ý định.

Dịch các đáp án:
A. is meant to (cụm động từ): được dự định để
B. means to (động từ): có nghĩa là
C. meaning to (cụm động từ): có ý định
D. is meant for (cụm động từ): được dành cho');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1937, 1473, 137, NULL, 'Some believe it would be better to make improvements to other ports.', 'The Tanzanian government has promised to fund the new port.', 'Developers hope to complete Kikole''s transformation within ten years.', 'This would be the shipping company''s first major presence in East Africa.', 'D', 'Đáp án D "This would be the shipping company''s first major presence in East Africa." là đúng vì nó cung cấp thông tin thêm về ý nghĩa của việc Marina International Shipping mở trung tâm tại đây.

Dịch các đáp án:
A. Some believe it would be better to make improvements to other ports. (Một số người tin rằng sẽ tốt hơn nếu cải thiện các cảng khác.)
B. The Tanzanian government has promised to fund the new port. (Chính phủ Tanzania đã hứa tài trợ cho cảng mới.)
C. Developers hope to complete Kikole''s transformation within ten years. (Các nhà phát triển hy vọng hoàn thành việc chuyển đổi Kikole trong vòng mười năm.)
D. This would be the shipping company''s first major presence in East Africa. (Đây sẽ là sự hiện diện lớn đầu tiên của công ty vận tải biển này ở Đông Phi.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1938, 1473, 138, NULL, 'Nonetheless', 'Therefore', 'In case', 'Equally as', 'A', 'Đáp án A "Nonetheless" là đúng vì nó tạo ra sự tương phản giữa sự phản đối của một số quan chức chính phủ và việc dự án vẫn tiến hành.

Dịch các đáp án:
A. Nonetheless (liên từ): Tuy nhiên
B. Therefore (liên từ): Do đó
C. In case (cụm từ): Trong trường hợp
D. Equally as (cụm từ): Cũng như vậy');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1474, 69, NULL, NULL, 'Mark your calendars for this year''s Family Fun Fair at Delray! Join us from June 20 to June 26 for seven days of summer fun. You will find not only fantastic food, rides, and games, 139--- exciting shows for all ages. And make sure not to miss our newest 140---. The Crazy Cowboy Train is a thrilling journey through the Wild West!
This year''s shows include the Bicycle Circus, the Dinosaur Show, and Walter the Magician. Please note that all basic admission ticket holders will need to pay additional fees to gain entrance to shows. 141---.
We also 142--- a VIP Family Fun pass for 595. This pass provides free admission to all shows plus unlimited free amusement rides.', 'Đánh dấu lịch của bạn cho Hội chợ Vui chơi Gia đình năm nay tại Delray! Tham gia cùng chúng tôi từ ngày 20 tháng 6 đến ngày 26 tháng 6 trong bảy ngày vui chơi mùa hè. Bạn sẽ tìm thấy không chỉ những món ăn, trò chơi và trò chơi tuyệt vời, 139--- chương trình thú vị dành cho mọi lứa tuổi. Và hãy chắc chắn không bỏ lỡ 140 mới nhất của chúng tôi---. Chuyến tàu cao bồi điên rồ là một cuộc hành trình ly kỳ qua miền Tây hoang dã! 
Các chương trình năm nay bao gồm Rạp xiếc xe đạp, Chương trình khủng long và Walter the Magician. Xin lưu ý rằng tất cả những người có vé vào cửa cơ bản sẽ cần phải trả thêm phí để được vào cửa chương trình. 141---.
Chúng tôi cũng 142--- một thẻ VIP Family Fun với giá 595. Thẻ này cung cấp vé vào cửa miễn phí cho tất cả các chương trình cộng với các trò chơi giải trí miễn phí không giới hạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1939, 1474, 139, NULL, 'if only', 'or else', 'so that', 'but also', 'D', 'Đáp án D "but also" là đúng vì nó hoàn thành cấu trúc "not only ... but also" để liệt kê các hoạt động tại hội chợ.

Dịch các đáp án:
A. if only (cụm từ): giá mà
B. or else (cụm từ): nếu không thì
C. so that (cụm từ): để mà
D. but also (cụm từ): mà còn');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1940, 1474, 140, NULL, 'shop', 'member', 'attraction', 'refreshment', 'C', 'Đáp án C "attraction" là đúng vì nó phù hợp với ngữ cảnh giới thiệu một điểm thu hút mới tại hội chợ.

Dịch các đáp án:
A. shop (danh từ): cửa hàng
B. member (danh từ): thành viên
C. attraction (danh từ): điểm thu hút
D. refreshment (danh từ): đồ giải khát');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1941, 1474, 141, NULL, 'There are over twenty different food vendors at the fair.', 'There is an age requirement for most rides at the fair.', 'Refer to the entertainment schedule for show times and prices.', 'Visit our Web site to see whether you are eligible.', 'C', 'Đáp án C "Refer to the entertainment schedule for show times and prices." là đúng vì nó cung cấp thông tin hữu ích về lịch trình và giá vé cho các show.

Dịch các đáp án:
A. There are over twenty different food vendors at the fair. (Có hơn hai mươi quầy ẩm thực khác nhau tại hội chợ.)
B. There is an age requirement for most rides at the fair. (Có yêu cầu về độ tuổi đối với hầu hết các trò chơi tại hội chợ.)
C. Refer to the entertainment schedule for show times and prices. (Tham khảo lịch trình giải trí để biết thời gian và giá vé các show.)
D. Visit our Web site to see whether you are eligible. (Truy cập trang web của chúng tôi để xem liệu bạn có đủ điều kiện không.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1942, 1474, 142, NULL, 'offer', 'offered', 'were offering', 'will be offered', 'A', 'Đáp án A "offer" là đúng vì nó phù hợp với thì hiện tại đơn để mô tả một dịch vụ đang được cung cấp.

Dịch các đáp án:
A. offer (động từ): cung cấp
B. offered (quá khứ): đã cung cấp
C. were offering (quá khứ tiếp diễn): đang cung cấp (trong quá khứ)
D. will be offered (tương lai bị động): sẽ được cung cấp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1475, 69, NULL, NULL, 'Brightman Heating and Cooling
16 Primrose Way
Sydney NSW 2146
(02) 5550 8899
www.brightmanheatingandcooling.com.au
15 May
Alia Bajpa
422 Hudson St.
Sydney NSW 2000
Dear Ms. Bajpa:
We have some important news to share with you. We 143--- to retire and close the company after 40 years in the business. 144--
-, we want to make sure that you do not experience any disruption
to your service. For that reason, we have arranged for Kondo''s Heating and Air to begin providing service to you effective on 1 June. I''m certain you will be pleased with 145--- service.
Kondo''s is a wonderful company with experienced, highly skilled technicians. 146---. If you have any questions, please do not hesitate to call.
Sincerely,
Nathaniel and Constance Brightman', 'Brightman Heating and Cooling
16 Primrose Way
Sydney NSW 2146
(02) 5550 8899
www.brightmanheatingandcooling.com.au
15 tháng 5
Alia Bajpa
422 Hudson St.
Sydney NSW 2000
Kính gửi cô Bajpa:
Chúng tôi có một số tin tức quan trọng muốn chia sẻ với bạn. Chúng tôi 143--- nghỉ hưu và đóng cửa công ty sau 40 năm kinh doanh. 144--
-, chúng tôi muốn đảm bảo rằng bạn không gặp phải bất kỳ sự gián đoạn nào
to dịch vụ của bạn. Vì lý do đó, chúng tôi đã sắp xếp để Kondo''s Heating and Air bắt đầu cung cấp dịch vụ cho bạn có hiệu lực từ ngày 1 tháng Sáu. Tôi chắc chắn rằng bạn sẽ hài lòng với dịch vụ 145---.
Kondo''s là một công ty tuyệt vời với các kỹ thuật viên giàu kinh nghiệm, có tay nghề cao. 146---. Nếu bạn có bất kỳ câu hỏi nào, xin đừng ngần ngại gọi.
Trân trọng,
Nathaniel và Constance Brightman');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1943, 1475, 143, NULL, 'decide', 'were deciding', 'could decide', 'have decided', 'D', 'Đáp án D "have decided" là đúng vì nó diễn tả một quyết định đã được đưa ra và có ảnh hưởng đến hiện tại.

Dịch các đáp án:
A. decide (động từ): quyết định
B. were deciding (quá khứ tiếp diễn): đang quyết định
C. could decide (khả năng trong quá khứ): có thể quyết định
D. have decided (hiện tại hoàn thành): đã quyết định');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1944, 1475, 144, NULL, 'Similarly', 'However', 'In general', 'At that time', 'B', 'Đáp án B "However" là đúng vì nó tạo ra sự tương phản giữa việc đóng cửa công ty và việc đảm bảo dịch vụ không bị gián đoạn.

Dịch các đáp án:
A. Similarly (trạng từ): Tương tự
B. However (liên từ): Tuy nhiên
C. In general (cụm từ): Nói chung
D. At that time (cụm từ): Vào lúc đó');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1945, 1475, 145, NULL, 'our', 'their', 'whose', 'his', 'B', 'Đáp án B "their" là đúng vì nó đề cập đến dịch vụ của công ty Kondo''s Heating and Air.

Dịch các đáp án:
A. our (tính từ sở hữu): của chúng tôi
B. their (tính từ sở hữu): của họ
C. whose (đại từ nghi vấn): của ai
D. his (tính từ sở hữu): của anh ấy');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1946, 1475, 146, NULL, 'Building a strong customer base can take years.', 'We will be holding a grand reopening event', 'You should be receiving a letter from them soon.', 'Many jobs in heating and air-conditioning are available.', 'C', 'Đáp án C "You should be receiving a letter from them soon." là đúng vì nó cung cấp thông tin hữu ích về việc liên lạc từ công ty mới.

Dịch các đáp án:
A. Building a strong customer base can take years. (Xây dựng một cơ sở khách hàng vững mạnh có thể mất nhiều năm.)
B. We will be holding a grand reopening event (Chúng tôi sẽ tổ chức một sự kiện khai trương lớn)
C. You should be receiving a letter from them soon. (Bạn sẽ sớm nhận được thư từ họ.)
D. Many jobs in heating and air-conditioning are available. (Có nhiều công việc trong lĩnh vực sưởi ấm và điều hòa không khí.)');;

-- Data for 2022 Test10 Part 7
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1476, 70, NULL, NULL, 'Hi, Avichai. I finished the upholstery on the sofa and chairs for Ms. Levin. They look great! It''s such a nice fabric. Which order should I work on next?
Glad to hear it. I promised the Chens their dining chairs by Saturday. By the way, the Metropolitan Design Show on June 14 has been postponed to July 7.
Oh, then I can''t make it.
That''s too bad. I''ll need at least two employees to come help. We''ll be showing our office desks and bookshelves.
I''ll ask Rita and Tom if they are available on that day. Unfortunately, I have a family commitment out of town that day. ''ll get started on the Chens'' order now.
Sounds good. Thank you!', 'Xin chào, Avichai. Tôi đã hoàn thành việc bọc ghế sofa và ghế cho cô Levin. Chúng trông thật tuyệt! Đó là một loại vải đẹp. Tôi nên làm theo thứ tự nào tiếp theo? 
Rất vui khi nghe điều đó. Tôi đã hứa với Chens những chiếc ghế ăn của họ vào thứ Bảy. Nhân tiện, Triển lãm Thiết kế Metropolitan vào ngày 14 tháng 6 đã bị hoãn lại đến ngày 7 tháng 7.
Ồ, vậy thì tôi không thể đến được.
Thật tệ. Tôi sẽ cần ít nhất hai nhân viên đến giúp đỡ. Chúng tôi sẽ trưng bày bàn làm việc và giá sách của chúng tôi.
Tôi sẽ hỏi Rita và Tom xem họ có rảnh vào ngày hôm đó không. Thật không may, tôi có một cam kết gia đình ở ngoài thị trấn vào ngày hôm đó. ''sẽ bắt đầu theo đơn đặt hàng của Chens ngay bây giờ.
Nghe hay đấy. Cảm ơn bạn!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1947, 1476, 147, 'What will Mr. Bodine most likely work on next?', 'A sofa', 'An office desk', 'A bookshelf', 'A set of chairs', 'D', 'Đáp án đúng là D (A set of chairs - Một bộ ghế). Trong đoạn hội thoại, Avichai nói "I promised the Chens their dining chairs by Saturday" (Tôi đã hứa với nhà Chen sẽ có ghế ăn vào thứ Bảy), và Brycen trả lời "I''ll get started on the Chens'' order now" (Tôi sẽ bắt đầu làm đơn hàng của nhà Chen ngay bây giờ). Điều này cho thấy công việc tiếp theo của Brycen là làm bộ ghế ăn cho nhà Chen.
A. A sofa (Một chiếc ghế sofa)
B. An office desk (Một bàn làm việc)
C. A bookshelf (Một kệ sách)
D. A set of chairs (Một bộ ghế)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1948, 1476, 148, 'At 1:19 P.M., what does Mr. Bodine mean when he writes, "I can''t make it"?', 'He will not be seeing Rita or Tom.', 'He will not be able to attend an event.', 'He will not be able to meet a deadline.', 'He does not know how to build a piece of furniture.', 'B', 'Đáp án đúng là B (He will not be able to attend an event - Anh ấy sẽ không thể tham dự một sự kiện). Trong đoạn hội thoại, Avichai thông báo rằng "the Metropolitan Design Show on June 14 has been postponed to July 7" (Triển lãm Thiết kế Metropolitan vào ngày 14 tháng 6 đã được dời sang ngày 7 tháng 7). Brycen trả lời "Oh, then I can''t make it" (Ồ, vậy thì tôi không thể đến được), ý nói anh ấy không thể tham dự sự kiện vào ngày mới.
A. He will not be seeing Rita or Tom. (Anh ấy sẽ không gặp Rita hoặc Tom.)
B. He will not be able to attend an event. (Anh ấy sẽ không thể tham dự một sự kiện.)
C. He will not be able to meet a deadline. (Anh ấy sẽ không thể đáp ứng thời hạn.)
D. He does not know how to build a piece of furniture. (Anh ấy không biết cách làm một món đồ nội thất.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1477, 70, NULL, NULL, 'Thank you for downloading the Spumoni mobile phone app!
At your current basic membership level, your ability to save recipes is limited to five per day. If you would like the freedom to save unlimited recipes daily, automatically generate shopping lists, create weekly meal plans, and track nutritional data, you can become a premium member for just $2.99 a month.
Many users find this small fee to be money well spent, as the premium features save them time and enable them to make healthier meal choices. Visit our "PM Community" Web page to view real testimonials from our premium members.', 'Cảm ơn bạn đã tải xuống ứng dụng điện thoại di động Spumoni! 
Ở cấp độ thành viên cơ bản hiện tại, khả năng lưu công thức nấu ăn của bạn được giới hạn ở mức năm công thức mỗi ngày. Nếu bạn muốn tự do lưu các công thức nấu ăn không giới hạn hàng ngày, tự động tạo danh sách mua sắm, tạo kế hoạch bữa ăn hàng tuần và theo dõi dữ liệu dinh dưỡng, bạn có thể trở thành thành viên cao cấp chỉ với 2,99 đô la một tháng.
Nhiều người dùng thấy khoản phí nhỏ này là số tiền được chi tiêu tốt, vì các tính năng cao cấp giúp họ tiết kiệm thời gian và cho phép họ lựa chọn bữa ăn lành mạnh hơn. Truy cập trang web "Cộng đồng PM" của chúng tôi để xem lời chứng thực thực từ các thành viên cao cấp của chúng tôi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1949, 1477, 149, 'What does the notice encourage users to do?', 'Share their own recipes', 'Submit their own testimonials', 'Upgrade their membership status', 'Download a recent software update', 'C', 'Đáp án đúng là C (Upgrade their membership status - Nâng cấp tình trạng thành viên của họ). Thông báo khuyến khích người dùng nâng cấp lên tài khoản premium để có thêm các tính năng như lưu công thức không giới hạn, tạo danh sách mua sắm tự động, lập kế hoạch bữa ăn hàng tuần và theo dõi dữ liệu dinh dưỡng. Cụ thể, thông báo nêu rõ "you can become a premium member for just $2.99 a month" (bạn có thể trở thành thành viên premium chỉ với 2,99 đô la một tháng).
A. Share their own recipes (Chia sẻ công thức nấu ăn của riêng họ)
B. Submit their own testimonials (Gửi những lời chứng thực của riêng họ)
C. Upgrade their membership status (Nâng cấp tình trạng thành viên của họ)
D. Download a recent software update (Tải xuống bản cập nhật phần mềm gần đây)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1950, 1477, 150, 'According to the notice, why should users go to a Web page?', 'To take a virtual tour', 'To see a sample meal plan', 'To compare ingredients from similar recipes', 'To find out about people''s experiences', 'D', 'Đáp án đúng là D (To find out about people''s experiences - Để tìm hiểu về trải nghiệm của mọi người). Thông báo khuyến khích người dùng truy cập trang web "PM Community" để xem các lời chứng thực thực tế từ các thành viên premium. Cụ thể, thông báo nêu rõ "Visit our "PM Community" Web page to view real testimonials from our premium members" (Truy cập trang web "PM Community" của chúng tôi để xem các lời chứng thực thực tế từ các thành viên premium của chúng tôi).
A. To take a virtual tour (Để tham quan ảo)
B. To see a sample meal plan (Để xem một kế hoạch bữa ăn mẫu)
C. To compare ingredients from similar recipes (Để so sánh nguyên liệu từ các công thức tương tự)
D. To find out about people''s experiences (Để tìm hiểu về trải nghiệm của mọi người)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1478, 70, NULL, NULL, 'We are glad you have chosen Kerwine Cleaning Services for your office cleaning needs.
Our janitors will arrive at your facility with the commercial-grade equipment, tools, and products needed to complete all cleaning tasks quickly and effectively. You have already confirmed a starting date of 30 October. However, you have not yet confirmed whether you will use our services weekly or biweekly. As soon as you let us know, we will draw up a contract for you. Please note that we are currently running a special promotion. If you sign up for six months of service by 31 October, your first two cleanings are free.', 'Chúng tôi rất vui vì bạn đã chọn Dịch vụ Vệ sinh Kerwine cho nhu cầu vệ sinh văn phòng của bạn.
Người gác cổng của chúng tôi sẽ đến cơ sở của bạn với các thiết bị, công cụ và sản phẩm cấp thương mại cần thiết để hoàn thành tất cả các nhiệm vụ dọn dẹp một cách nhanh chóng và hiệu quả. Bạn đã xác nhận ngày bắt đầu là ngày 30 tháng Mười. Tuy nhiên, bạn vẫn chưa xác nhận xem bạn sẽ sử dụng dịch vụ của chúng tôi hàng tuần hay hai tuần một lần. Ngay khi bạn cho chúng tôi biết, chúng tôi sẽ soạn thảo hợp đồng cho bạn. Xin lưu ý rằng chúng tôi hiện đang thực hiện một chương trình khuyến mãi đặc biệt. Nếu bạn đăng ký sáu tháng dịch vụ trước ngày 31 tháng 10, hai lần dọn dẹp đầu tiên của bạn là miễn phí.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1951, 1478, 151, 'What does Mr. Winters ask Ms. Prigarina to confirm?', 'How often to clean her office', 'When he should arrive at her facility', 'Where her office is located', 'What products she prefers', 'A', 'Đáp án đúng là A (How often to clean her office - Tần suất dọn dẹp văn phòng của cô ấy). Trong email, Mr. Winters nói rõ: "However, you have not yet confirmed whether you will use our services weekly or biweekly" (Tuy nhiên, bạn vẫn chưa xác nhận liệu bạn sẽ sử dụng dịch vụ của chúng tôi hàng tuần hay hai tuần một lần). Đây chính là thông tin mà ông ấy yêu cầu Ms. Prigarina xác nhận.
A. How often to clean her office (Tần suất dọn dẹp văn phòng của cô ấy)
B. When he should arrive at her facility (Khi nào ông ấy nên đến cơ sở của cô ấy)
C. Where her office is located (Văn phòng của cô ấy ở đâu)
D. What products she prefers (Cô ấy thích sản phẩm nào)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1952, 1478, 152, 'How can Ms. Prigarina receive two free cleanings?', 'By prepaying for services', 'By signing a contract for six months', 'By changing her starting date', 'By using a discount code', 'B', 'Đáp án đúng là B (By signing a contract for six months - Bằng cách ký hợp đồng 6 tháng). Trong email, Mr. Winters đề cập đến một chương trình khuyến mãi đặc biệt: "If you sign up for six months of service by 31 October, your first two cleanings are free" (Nếu bạn đăng ký dịch vụ 6 tháng trước ngày 31 tháng 10, hai lần dọn dẹp đầu tiên của bạn sẽ được miễn phí). Đây chính là cách để Ms. Prigarina nhận được hai lần dọn dẹp miễn phí.
A. By prepaying for services (Bằng cách trả trước cho dịch vụ)
B. By signing a contract for six months (Bằng cách ký hợp đồng 6 tháng)
C. By changing her starting date (Bằng cách thay đổi ngày bắt đầu)
D. By using a discount code (Bằng cách sử dụng mã giảm giá)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1479, 70, NULL, NULL, 'Unfortunately, I have to cancel our planned afternoon phone call at the last minute—1 hope you get this e-mail in time. Could we please reschedule? This was my mistake, as I somehow double-booked our appointment time. In fact, I am on my way out the door right now to keep the other appointment—a meeting with a high-priority client. I apologize.
Would teleconferencing on Monday at noon work for you? Also, prior to our meeting, could you look further into any grant opportunities that might be available for the current project? Meanwhile, I will ask Leona to calculate more accurate budgets for some future initiatives that will need funding. That will allow us to be more productive when we meet next week.', 'Thật không may, tôi phải hủy cuộc gọi điện thoại buổi chiều đã lên kế hoạch của chúng tôi vào phút cuối—1 hy vọng bạn nhận được e-mail này kịp thời. Chúng ta có thể vui lòng lên lịch lại được không? Đây là sai lầm của tôi, vì bằng cách nào đó tôi đã đặt gấp đôi thời gian hẹn của chúng tôi. Trên thực tế, tôi đang trên đường ra khỏi cửa ngay bây giờ để giữ cuộc hẹn khác - một cuộc họp với một khách hàng ưu tiên cao. Tôi xin lỗi.
Hội nghị từ xa vào trưa thứ Hai có phù hợp với bạn không? Ngoài ra, trước cuộc họp của chúng ta, bạn có thể xem xét thêm bất kỳ cơ hội tài trợ nào có thể có sẵn cho dự án hiện tại không? Trong khi đó, tôi sẽ yêu cầu Leona tính toán ngân sách chính xác hơn cho một số sáng kiến trong tương lai sẽ cần tài trợ. Điều đó sẽ cho phép chúng ta làm việc hiệu quả hơn khi chúng ta gặp nhau vào tuần tới.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1953, 1479, 153, 'Why does Mr. Keller say he cannot meet as planned?', 'He anticipates a late return from a trip.', 'He has no new information to report.', 'He decided to take the afternoon off.', 'He discovered a scheduling conflict.', 'D', 'Đáp án đúng là D (He discovered a scheduling conflict - Anh ấy phát hiện ra xung đột lịch trình). Trong email, Mr. Keller giải thích rằng: "This was my mistake, as I somehow double-booked our appointment time" (Đây là lỗi của tôi, vì không hiểu sao tôi đã đặt lịch trùng giờ cuộc hẹn của chúng ta). Điều này cho thấy anh ấy đã phát hiện ra một xung đột lịch trình.
A. He anticipates a late return from a trip. (Anh ấy dự đoán sẽ trở về muộn từ một chuyến đi.)
B. He has no new information to report. (Anh ấy không có thông tin mới để báo cáo.)
C. He decided to take the afternoon off. (Anh ấy quyết định nghỉ buổi chiều.)
D. He discovered a scheduling conflict. (Anh ấy phát hiện ra xung đột lịch trình.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1954, 1479, 154, 'What will most likely be done before the meeting?', 'More financial information will be gathered.', 'The meeting location will be changed.', 'Another person will be invited to attend.', 'A marketing plan will be modified.', 'A', 'Đáp án đúng là A (More financial information will be gathered - Thêm thông tin tài chính sẽ được thu thập). Trong email, Mr. Keller yêu cầu Angela tìm hiểu thêm về các cơ hội tài trợ cho dự án hiện tại và nói rằng ông sẽ yêu cầu Leona tính toán ngân sách chính xác hơn cho một số sáng kiến trong tương lai. Điều này cho thấy trước cuộc họp, họ sẽ thu thập thêm thông tin tài chính.
A. More financial information will be gathered. (Thêm thông tin tài chính sẽ được thu thập.)
B. The meeting location will be changed. (Địa điểm cuộc họp sẽ được thay đổi.)
C. Another person will be invited to attend. (Một người khác sẽ được mời tham dự.)
D. A marketing plan will be modified. (Một kế hoạch tiếp thị sẽ được sửa đổi.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1480, 70, NULL, NULL, 'Gracio Store Comment Card
Gracio Store is seeking to make your visit with us a better experience. Tell us about your visit to our store today so we can improve the way we serve you.
And each week, one comment card will be drawn from those submitted to earn the customer a $50 store coupon!
Customer name: Huy Nguyen
E-mail contact: hnguyen@brightmail.co.nz
Date: 4 May
Reason for your visit today: Shopping for a gift
Comment: I was shopping for a friend''s birthday. Ms. Davie, a sales associate in Accessories, greeted me and asked me questions to narrow down my gift search. She even offered to hold some of my bags so that I could shop more easily. She directed me to a colourful display of silk scarves and told me about the various places they were produced. The one I chose ended up in my planned price range too.', 'Thẻ Nhận xét của Cửa hàng Gracio
Cửa hàng Gracio đang tìm cách làm cho chuyến thăm của bạn với chúng tôi trở thành một trải nghiệm tốt hơn. Hãy cho chúng tôi biết về chuyến thăm của bạn đến cửa hàng của chúng tôi hôm nay để chúng tôi có thể cải thiện cách chúng tôi phục vụ bạn.
Và mỗi tuần, một thẻ nhận xét sẽ được rút ra từ những người đã gửi để kiếm được phiếu giảm giá cửa hàng trị giá 50 đô la cho khách hàng! 
Tên khách hàng: Huy Nguyen
Email liên hệ: hnguyen@brightmail.co.nz
Ngày: 4 tháng 5
L lý do bạn đến thăm hôm nay: Mua sắm quà tặng
Nhận xét: Tôi đang mua sắm cho sinh nhật của một người bạn. Cô Davie, một nhân viên bán hàng trong lĩnh vực Phụ kiện, đã chào đón tôi và hỏi tôi những câu hỏi để thu hẹp tìm kiếm quà tặng của tôi. Cô ấy thậm chí còn đề nghị giữ một số túi của tôi để tôi có thể mua sắm dễ dàng hơn. Cô ấy hướng dẫn tôi đến một màn trình diễn đầy màu sắc của những chiếc khăn lụa và kể cho tôi nghe về những nơi khác nhau mà chúng được sản xuất. Cái tôi đã chọn cũng nằm trong phạm vi giá dự kiến của tôi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1955, 1480, 155, 'What is indicated about Gracio Store?', 'It has recently opened.', 'It is training new sales associates.', 'It wants to improve its customer service.', 'It has organized a competition.', 'C', 'Đáp án đúng là C (It wants to improve its customer service - Nó muốn cải thiện dịch vụ khách hàng). Thông tin này được thể hiện rõ ở đầu phiếu góp ý: "Gracio Store is seeking to make your visit with us a better experience. Tell us about your visit to our store today so we can improve the way we serve you" (Cửa hàng Gracio đang tìm cách làm cho trải nghiệm của bạn với chúng tôi tốt hơn. Hãy cho chúng tôi biết về chuyến thăm cửa hàng của bạn hôm nay để chúng tôi có thể cải thiện cách phục vụ bạn).
A. It has recently opened. (Nó mới được mở gần đây.)
B. It is training new sales associates. (Nó đang đào tạo các nhân viên bán hàng mới.)
C. It wants to improve its customer service. (Nó muốn cải thiện dịch vụ khách hàng.)
D. It has organized a competition. (Nó đã tổ chức một cuộc thi.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1956, 1480, 156, 'The word "drawn" in paragraph 1, line 3, is closest in meaning to', 'sketched', 'picked', 'attracted', 'described', 'B', 'Đáp án đúng là B (picked - chọn). Trong ngữ cảnh này, "drawn" được sử dụng trong cụm "one comment card will be drawn from those submitted", có nghĩa là một phiếu góp ý sẽ được chọn ra từ những phiếu đã được gửi đến. Vì vậy, "drawn" ở đây có nghĩa gần nhất với "picked" (chọn).
A. sketched (phác họa)
B. picked (chọn)
C. attracted (thu hút)
D. described (mô tả)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1957, 1480, 157, 'What does Mr. Nguyen write about his experience?', 'He bought several different accessories.', 'It took him a long time to find a gift.', 'A manager answered his questions.', 'He was able to stay within his gift budget.', 'D', 'Đáp án đúng là D (He was able to stay within his gift budget - Anh ấy đã có thể giữ trong phạm vi ngân sách quà tặng). Trong phần bình luận, Mr. Nguyen viết: "The one I chose ended up in my planned price range too" (Cái tôi chọn cuối cùng cũng nằm trong phạm vi giá dự kiến của tôi). Điều này cho thấy anh ấy đã có thể mua một món quà trong phạm vi ngân sách đã định.
A. He bought several different accessories. (Anh ấy đã mua nhiều phụ kiện khác nhau.)
B. It took him a long time to find a gift. (Anh ấy mất nhiều thời gian để tìm một món quà.)
C. A manager answered his questions. (Một người quản lý đã trả lời câu hỏi của anh ấy.)
D. He was able to stay within his gift budget. (Anh ấy đã có thể giữ trong phạm vi ngân sách quà tặng.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1481, 70, NULL, NULL, 'From: Icho@cuvacorporatetraining.com
To: all_staff@cuvacorporatetraining.com
Date: Monday, April 12, 10:53 A.M.
Subject: Special notice
Dear colleagues,
Please be advised that the Customer Security System (CSS) installed on your computer will be automatically updated this weekend. Specifically, the update will be taking place from midnight, Saturday, April 17, to midnight, Sunday, April 18, - [1] —. Your device will restart after the update has been completed.
The purpose of the update is twofold. First, it will increase the security of our client information. Moreover, it will improve overall system performance. - [2] - As a result, you should notice improved processing speeds and less unplanned system downtime.
Please note that following the update there will be a change in the appearance of the CSS log-in screen, but this change will not affect the log-in procedures.
The tech support team will be available to answer any questions you may have before and after the update. — [3] —. By Thursday, you will receive a link to a training video with explanations of the new features that will become available with the update. - [4] -', 'Từ: Icho@cuvacorporatetraining.com
Gửi đến: all_staff@cuvacorporatetraining.com
Ngày: Thứ Hai, ngày 12 tháng 4, 10:53 sáng
Chủ đề: Thông báo đặc biệt
Các đồng nghiệp thân mến,
Xin lưu ý rằng Hệ thống bảo mật khách hàng (CSS) được cài đặt trên máy tính của bạn sẽ được tự động cập nhật vào cuối tuần này. Cụ thể, bản cập nhật sẽ diễn ra từ nửa đêm, Thứ Bảy, ngày 17 tháng Tư, đến nửa đêm, Chủ Nhật, ngày 18 tháng Tư, - [1] —. Thiết bị của bạn sẽ khởi động lại sau khi quá trình cập nhật hoàn tất.
Mục đích của bản cập nhật có hai phần. Đầu tiên, nó sẽ tăng tính bảo mật cho thông tin khách hàng của chúng tôi. Hơn nữa, nó sẽ cải thiện hiệu suất tổng thể của hệ thống. - [2] - Do đó, bạn sẽ nhận thấy tốc độ xử lý được cải thiện và giảm thời gian ngừng hoạt động hệ thống ngoài kế hoạch.
Xin lưu ý rằng sau khi cập nhật sẽ có sự thay đổi về giao diện của màn hình đăng nhập CSS, nhưng thay đổi này sẽ không ảnh hưởng đến quy trình đăng nhập.
Nhóm hỗ trợ kỹ thuật sẽ sẵn sàng trả lời bất kỳ câu hỏi nào bạn có thể có trước và sau khi cập nhật. — [3] —. Vào thứ Năm, bạn sẽ nhận được một liên kết đến một video đào tạo với các giải thích về các tính năng mới sẽ có sẵn với bản cập nhật. - [4] -');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1958, 1481, 158, 'Why was the e-mail sent?', 'To motivate employees to increase their performance', 'To instruct employees how to install a computer program update', 'To obtain feedback about some new security procedures', 'To alert employees about upcoming changes to some software', 'D', 'Đáp án đúng là D (To alert employees about upcoming changes to some software - Để thông báo cho nhân viên về những thay đổi sắp tới đối với một số phần mềm). Email này được gửi để thông báo cho nhân viên về việc cập nhật tự động Hệ thống An ninh Khách hàng (CSS) sẽ diễn ra vào cuối tuần. Nó cung cấp thông tin về thời gian cập nhật, mục đích của việc cập nhật, và những thay đổi mà nhân viên có thể nhận thấy sau khi cập nhật.
A. To motivate employees to increase their performance (Để thúc đẩy nhân viên tăng hiệu suất làm việc)
B. To instruct employees how to install a computer program update (Để hướng dẫn nhân viên cách cài đặt bản cập nhật chương trình máy tính)
C. To obtain feedback about some new security procedures (Để nhận phản hồi về một số thủ tục bảo mật mới)
D. To alert employees about upcoming changes to some software (Để thông báo cho nhân viên về những thay đổi sắp tới đối với một số phần mềm)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1959, 1481, 159, 'According to the e-mail, what will employees experience after April 18 ?', 'Better quality Web cameras', 'A different CSS log-in screen', 'Faster technical support service', 'More comfortable keyboards', 'B', 'Đáp án đúng là B (A different CSS log-in screen - Một màn hình đăng nhập CSS khác). Trong email có đoạn: "Please note that following the update there will be a change in the appearance of the CSS log-in screen, but this change will not affect the log-in procedures" (Xin lưu ý rằng sau khi cập nhật sẽ có sự thay đổi trong giao diện của màn hình đăng nhập CSS, nhưng thay đổi này sẽ không ảnh hưởng đến quy trình đăng nhập).
A. Better quality Web cameras (Webcam chất lượng tốt hơn)
B. A different CSS log-in screen (Một màn hình đăng nhập CSS khác)
C. Faster technical support service (Dịch vụ hỗ trợ kỹ thuật nhanh hơn)
D. More comfortable keyboards (Bàn phím thoải mái hơn)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1960, 1481, 160, 'In which of the positions marked [11. [2], [3], and (4] does the following sentence best belong? "During this period, some functions will be limited or unavailable."', '[1]', '[2]', '[3]', '[4]', 'A', 'Đáp án đúng là A ([1]). Câu "During this period, some functions will be limited or unavailable" (Trong thời gian này, một số chức năng sẽ bị hạn chế hoặc không khả dụng) phù hợp nhất ở vị trí [1]. Vị trí này nằm ngay sau thông tin về thời gian cập nhật và trước khi đề cập đến việc thiết bị sẽ khởi động lại sau khi cập nhật hoàn tất. Đặt câu này ở đây sẽ cung cấp thông tin quan trọng về tác động của việc cập nhật đối với người dùng trong thời gian diễn ra cập nhật.
A. [1] (Vị trí sau thông tin về thời gian cập nhật)
B. [2] (Vị trí trong phần mô tả mục đích của cập nhật)
C. [3] (Vị trí sau thông tin về sự hỗ trợ của đội ngũ kỹ thuật)
D. [4] (Vị trí cuối cùng của email)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1482, 70, NULL, NULL, 'Electronics Plus Express Return Policy
All returns require prior authorization. Please call during business hours (Monday-Friday 9:00 A.M. to 7:00 P.M. and weekends
10:00 A.M. to 5:00 P.M.) or e-mail Customer Service with your return request to receive a return authorization code.
Defective merchandise may be returned within 30 days of purchase date. Any new merchandise may be returned within 14 days of purchase date. The original box and packaging materials must be included. If you need to return the item by post, the store will issue and e-mail a postage-paid shipping label for you to print at home and attach to your parcel. The cost of your item will be refunded once it has been received.
Customer Service contact information is as follows:
Phone: 1-800-555-0176
E-mail: cs@electronicsplusexpress.com', 'Chính sách đổi trả nhanh Electronics Plus
Tất cả các đơn hàng trả lại đều cần được ủy quyền trước. Vui lòng gọi trong giờ làm việc (Thứ Hai-Thứ Sáu 9:00 sáng đến 7:00 tối và cuối tuần
10:00 sáng đến 5:00 chiều) hoặc gửi email cho Dịch vụ khách hàng với yêu cầu trả lại của bạn để nhận mã ủy quyền trả lại.
Hàng hóa bị lỗi có thể được trả lại trong vòng 30 ngày kể từ ngày mua. Bất kỳ hàng hóa mới nào cũng có thể được trả lại trong vòng 14 ngày kể từ ngày mua. Hộp gốc và vật liệu đóng gói phải được bao gồm. Nếu bạn cần trả lại mặt hàng qua đường bưu điện, cửa hàng sẽ cấp và gửi qua email nhãn vận chuyển đã thanh toán bưu phí để bạn in tại nhà và đính kèm vào bưu kiện của mình. Chi phí cho mặt hàng của bạn sẽ được hoàn lại sau khi nhận được.
Thông tin liên hệ Dịch vụ khách hàng như sau:
Điện thoại: 1-800-555-0176
E-mail: cs@electronicsplusexpress.com');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1961, 1482, 161, 'For whom is the information most likely intended?', 'Customers of Electronics Plus Express', 'Customer service representatives', 'Repair technicians', 'Shipping department employees', 'A', 'Đáp án đúng là A (Customers of Electronics Plus Express - Khách hàng của Electronics Plus Express). Thông tin này được thiết kế chủ yếu cho khách hàng của Electronics Plus Express. Nó cung cấp hướng dẫn chi tiết về cách thức trả lại hàng, thời hạn trả hàng, và thông tin liên hệ của dịch vụ khách hàng. Những chi tiết này chủ yếu hữu ích cho khách hàng muốn trả lại sản phẩm.
A. Customers of Electronics Plus Express (Khách hàng của Electronics Plus Express)
B. Customer service representatives (Đại diện dịch vụ khách hàng)
C. Repair technicians (Kỹ thuật viên sửa chữa)
D. Shipping department employees (Nhân viên bộ phận vận chuyển)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1962, 1482, 162, 'What is indicated about all returns?', 'They are only received at store locations.', 'They cannot be processed on weekends.', 'They require an authorization code.', 'They are not accepted after 14 days.', 'C', 'Đáp án đúng là C (They require an authorization code - Chúng yêu cầu một mã ủy quyền). Câu đầu tiên của chính sách trả hàng nêu rõ: "All returns require prior authorization" (Tất cả các lần trả hàng đều yêu cầu ủy quyền trước). Sau đó, nó hướng dẫn khách hàng liên hệ với dịch vụ khách hàng "to receive a return authorization code" (để nhận mã ủy quyền trả hàng).
A. They are only received at store locations. (Chúng chỉ được nhận tại các địa điểm cửa hàng.)
B. They cannot be processed on weekends. (Chúng không thể được xử lý vào cuối tuần.)
C. They require an authorization code. (Chúng yêu cầu một mã ủy quyền.)
D. They are not accepted after 14 days. (Chúng không được chấp nhận sau 14 ngày.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1963, 1482, 163, 'What is mentioned about return shipping fees?', 'They are calculated based on the weight of the package.', 'They are listed on the company''s Web site.', 'They will be refunded to the customer within 30 days.', 'They are paid for by the company.', 'D', 'Đáp án đúng là D (They are paid for by the company - Chúng được công ty thanh toán). Chính sách trả hàng nêu rõ: "If you need to return the item by post, the store will issue and e-mail a postage-paid shipping label for you to print at home and attach to your parcel" (Nếu bạn cần trả lại món hàng qua đường bưu điện, cửa hàng sẽ phát hành và gửi email một nhãn vận chuyển đã trả cước để bạn in tại nhà và gắn vào bưu kiện của bạn). Điều này cho thấy công ty sẽ thanh toán phí vận chuyển trả hàng.
A. They are calculated based on the weight of the package. (Chúng được tính dựa trên trọng lượng của gói hàng.)
B. They are listed on the company''s Web site. (Chúng được liệt kê trên trang web của công ty.)
C. They will be refunded to the customer within 30 days. (Chúng sẽ được hoàn lại cho khách hàng trong vòng 30 ngày.)
D. They are paid for by the company. (Chúng được công ty thanh toán.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1483, 70, NULL, NULL, 'Kelli Wethers [2:15 P.M.] Hi, Mr. Easton. I want to remind you about the dinner meeting with your client, Mr. Kasai, at the Magnolia Grill this evening. Mr. Kasai will be coming directly from the airport. Anna Kwon from our marketing department will be joining both of you.
Adam Easton [2:31 P.M.] Thanks, Ms. Wethers. It occurs to me, if he is coming straight from the airport, what will he do with his luggage?
Kelli Wethers [2:33 P.M.] Don''t worry. Kyle Friedman is picking Mr. Kasai up at the airport and dropping the bags off at the hotel. I''m adding Kyle to this message now in case you two need to communicate.
Adam Easton [2:34 P.M.] Sounds great. I can drive Mr. Kasai back to his hotel following our meeting. It would be a nice gesture for such a key client.
Kyle Friedman [2:36 P.M.] Heading to the airport soon, Ms. Wethers. Just text me later if I need to know anything more.
Kelli Wethers [2:40 P.M.] Good idea, Mr. Easton. A taxi for after the dinner will not be necessary then.', 'Kelli Wethers [2:15 chiều] Xin chào, ông Easton. Tôi muốn nhắc bạn về cuộc họp ăn tối với khách hàng của bạn, ông Kasai, tại Magnolia Grill tối nay. Ông Kasai sẽ đến trực tiếp từ sân bay. Anna Kwon từ bộ phận tiếp thị của chúng tôi sẽ tham gia cùng cả hai bạn.
Adam Easton [2:31 chiều] Cảm ơn cô Wethers. Nó xảy ra với tôi, nếu anh ấy đến thẳng từ sân bay, anh ấy sẽ làm gì với hành lý của mình? 
Kelli Wethers [2:33 Chiều] Đừng lo lắng. Kyle Friedman đang đón ông Kasai tại sân bay và trả hành lý tại khách sạn. Tôi đang thêm Kyle vào tin nhắn này ngay bây giờ trong trường hợp hai bạn cần giao tiếp.
Adam Easton [2:34 P.M.] Nghe hay đấy. Tôi có thể chở ông Kasai trở lại khách sạn của ông ấy sau cuộc họp của chúng ta. Đó sẽ là một cử chỉ tốt đẹp cho một khách hàng quan trọng như vậy.
Kyle Friedman [2:36 P.M.] Sắp tới sân bay rồi, cô Wethers. Chỉ cần nhắn tin cho tôi sau nếu tôi cần biết thêm bất cứ điều gì.
Kelli Wethers [2:40 P.M.] Ý kiến hay, ông Easton. Sau bữa tối sẽ không cần thiết phải đi taxi sau bữa tối.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1964, 1483, 164, 'What is the purpose of the online chat discussion?', 'To review arrangements for a client visit', 'To choose a location for a company celebration', 'To give invitations to a dinner event', 'To arrange a taxi for some traveling colleagues', 'A', 'Đáp án đúng là A (To review arrangements for a client visit - Để xem xét các sắp xếp cho chuyến thăm của khách hàng). Cuộc trò chuyện trực tuyến này tập trung vào việc thảo luận và xác nhận các chi tiết liên quan đến chuyến thăm của Mr. Kasai, bao gồm cuộc họp ăn tối, việc đón từ sân bay, xử lý hành lý và sắp xếp đi lại.
A. To review arrangements for a client visit (Để xem xét các sắp xếp cho chuyến thăm của khách hàng)
B. To choose a location for a company celebration (Để chọn địa điểm cho buổi lễ kỷ niệm của công ty)
C. To give invitations to a dinner event (Để đưa ra lời mời cho một sự kiện ăn tối)
D. To arrange a taxi for some traveling colleagues (Để sắp xếp taxi cho một số đồng nghiệp đi công tác)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1965, 1483, 165, 'Who will go to the airport?', 'Ms. Wethers', 'Mr. Easton', 'Mr. Friedman', 'Ms. Kwon', 'C', 'Đáp án đúng là C (Mr. Friedman). Trong cuộc trò chuyện, Kelli Wethers nói: "Kyle Friedman is picking Mr. Kasai up at the airport" (Kyle Friedman sẽ đón Mr. Kasai tại sân bay). Sau đó, Kyle Friedman xác nhận: "Heading to the airport soon, Ms. Wethers" (Sắp đi đến sân bay, Ms. Wethers).
A. Ms. Wethers
B. Mr. Easton
C. Mr. Friedman
D. Ms. Kwon');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1966, 1483, 166, 'What is indicated about Mr. Kasai?', 'He prefers to dine at the Magnolia Grill.', 'He is an important customer.', 'He wants to get to his hotel on time.', 'He is confused about driving directions.', 'B', 'Đáp án đúng là B (He is an important customer - Anh ấy là một khách hàng quan trọng). Điều này được ngụ ý khi Adam Easton nói: "I can drive Mr. Kasai back to his hotel following our meeting. It would be a nice gesture for such a key client" (Tôi có thể lái xe đưa Mr. Kasai trở lại khách sạn sau cuộc họp của chúng tôi. Đó sẽ là một cử chỉ đẹp đối với một khách hàng quan trọng như vậy).
A. He prefers to dine at the Magnolia Grill. (Anh ấy thích ăn tối tại Magnolia Grill.)
B. He is an important customer. (Anh ấy là một khách hàng quan trọng.)
C. He wants to get to his hotel on time. (Anh ấy muốn đến khách sạn đúng giờ.)
D. He is confused about driving directions. (Anh ấy bối rối về chỉ đường.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1967, 1483, 167, 'At 2:40 p.M., what does Ms. Wethers most likely mean when she writes, "Good idea, Mr. Easton"?', 'She thinks that a dinner meeting should be informal.', 'She believes that a hotel selection is appropriate.', 'She does not think that a client has a driver''s license.', 'She agrees that a client should be offered a ride to a hotel.', 'D', 'Đáp án đúng là D (She agrees that a client should be offered a ride to a hotel - Cô ấy đồng ý rằng nên đề nghị đưa khách hàng đến khách sạn). Ms. Wethers nói "Good idea, Mr. Easton" (Ý kiến hay, ông Easton) sau khi Mr. Easton đề xuất lái xe đưa Mr. Kasai trở lại khách sạn sau cuộc họp. Cô ấy tiếp tục nói "A taxi for after the dinner will not be necessary then" (Vậy thì không cần taxi sau bữa tối nữa), cho thấy cô ấy đồng ý với đề xuất của Mr. Easton.
A. She thinks that a dinner meeting should be informal. (Cô ấy nghĩ rằng một cuộc họp ăn tối nên mang tính không chính thức.)
B. She believes that a hotel selection is appropriate. (Cô ấy tin rằng việc lựa chọn khách sạn là phù hợp.)
C. She does not think that a client has a driver''s license. (Cô ấy không nghĩ rằng khách hàng có bằng lái xe.)
D. She agrees that a client should be offered a ride to a hotel. (Cô ấy đồng ý rằng nên đề nghị đưa khách hàng đến khách sạn.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1484, 70, NULL, NULL, 'To: staff@rindersbusiness.co.ke
From: deloeten@rindersbusiness.co.ke
Subject: Information
Date: 25 October
Dear Rinders Staff:
Our company is growing, and I am pleased to welcome new staff members! Those in our Marabi tice, bill nine no Move Girl Sive of yell She her late the new en she visied
the office. She will be replacing David Alberts.
Anila Pillai will also be a new face in our Nairobi office. Ms. Pillai will be an administrative assistant, and she will greet visitors, answer the phone, and perform office duties. She will work on Wednesdays, Thursdays, and Fridays from 10:00 A.M. to
3:00 P.M.
Mark Karunga, who has worked in the Nairobi office for the past fifteen years, is being promoted to senior accountant and will work in our new Mombasa office beginning on
15 November.
I will soon be sending another e-mail alerting you to more new faces in our offices since we are still hiring personnel for the Mombasa location. We hope to have all positions filled there before the grand opening in November.', 'Gửi đến: staff@rindersbusiness.co.ke
Từ: deloeten@rindersbusiness.co.ke
Chủ đề: Thông tin
Ngày: 25 tháng 10
Nhân viên Rinders thân mến:
Công ty chúng tôi đang phát triển, và tôi rất vui mừng được chào đón các nhân viên mới! Những người trong Marabi tice của chúng tôi, hóa đơn chín không di chuyển cô gái Sive của hét lên She her late the new en she visied
the office. Cô ấy sẽ thay thế David Alberts. Anila Pillai cũng sẽ là một gương mặt mới trong văn phòng Nairobi của chúng tôi. Cô Pillai sẽ là một trợ lý hành chính, và cô ấy sẽ chào đón du khách, trả lời điện thoại và thực hiện các nhiệm vụ văn phòng. Cô ấy sẽ làm việc vào các ngày thứ Tư, thứ Năm và thứ Sáu từ 10:00 sáng đến 3:00 chiều. Mark Karunga, người đã làm việc tại văn phòng Nairobi trong mười lăm năm qua, đang được thăng chức lên kế toán cao cấp và sẽ làm việc tại văn phòng Mombasa mới của chúng tôi bắt đầu từ ngày 15 tháng 11. Tôi sẽ sớm gửi một e-mail khác để thông báo cho bạn về những gương mặt mới hơn trong văn phòng của chúng tôi vì chúng tôi vẫn đang tuyển dụng nhân sự cho địa điểm Mombasa. Chúng tôi hy vọng sẽ có tất cả các vị trí được lấp đầy ở đó trước khi khai trương vào tháng Mười Một.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1968, 1484, 168, 'What is the main purpose of the e-mail?', 'To describe some staff changes', 'To discuss some new office procedures', 'To contrast two company locations', 'To report on recent office visitors', 'A', 'Đáp án đúng là A (To describe some staff changes - Để mô tả một số thay đổi nhân sự). Email này chủ yếu thông báo về các thay đổi nhân sự trong công ty, bao gồm việc chào đón nhân viên mới, thông báo về việc thuyên chuyển và thăng chức của nhân viên hiện tại, cũng như đề cập đến việc tuyển dụng đang diễn ra cho văn phòng mới ở Mombasa.
A. To describe some staff changes (Để mô tả một số thay đổi nhân sự)
B. To discuss some new office procedures (Để thảo luận về một số thủ tục văn phòng mới)
C. To contrast two company locations (Để so sánh hai địa điểm công ty)
D. To report on recent office visitors (Để báo cáo về những khách thăm văn phòng gần đây)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1969, 1484, 169, 'Who will be working part-time at Rinders Business Systems?', 'Ms. Gichuki', 'Mr. Alberts', 'Ms. Pillai', 'Ms. Cloeten', 'C', 'Đáp án đúng là C (Ms. Pillai). Email cho biết: "Anila Pillai will also be a new face in our Nairobi office. Ms. Pillai will be an administrative assistant, and she will greet visitors, answer the phone, and perform office duties. She will work on Wednesdays, Thursdays, and Fridays from 10:00 A.M. to 3:00 P.M." Lịch làm việc này cho thấy Ms. Pillai sẽ làm việc bán thời gian.
A. Ms. Gichuki
B. Mr. Alberts
C. Ms. Pillai
D. Ms. Cloeten');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1970, 1484, 170, 'What is NOT indicated about Mr. Karunga?', 'He is an accountant.', 'He is a recent hire.', 'He is being promoted.', 'He is being transferred.', 'B', 'Đáp án đúng là B (He is a recent hire - Anh ấy là một nhân viên mới được tuyển dụng). Email không cho biết Mr. Karunga là một nhân viên mới được tuyển dụng. Ngược lại, nó nói rằng anh ấy đã làm việc tại văn phòng Nairobi trong 15 năm qua. Email cũng cho biết anh ấy là một kế toán viên (được thăng chức lên kế toán trưởng), đang được thăng chức và chuyển đến văn phòng mới ở Mombasa.
A. He is an accountant. (Anh ấy là một kế toán viên.)
B. He is a recent hire. (Anh ấy là một nhân viên mới được tuyển dụng.)
C. He is being promoted. (Anh ấy đang được thăng chức.)
D. He is being transferred. (Anh ấy đang được chuyển công tác.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1971, 1484, 171, 'What does Ms. Cloeten indicate about the Mombasa location?', 'It is her new workplace.', 'It has not yet opened.', 'It is fully staffed.', 'It is larger than the Nairobi office.', 'B', 'Đáp án đúng là B (It has not yet opened - Nó chưa mở cửa). Ms. Cloeten nói: "We hope to have all positions filled there before the grand opening in November" (Chúng tôi hy vọng sẽ tuyển đủ nhân sự cho tất cả các vị trí trước khi khai trương vào tháng 11). Điều này cho thấy địa điểm Mombasa chưa mở cửa và đang chuẩn bị cho buổi khai trương.
A. It is her new workplace. (Đó là nơi làm việc mới của cô ấy.)
B. It has not yet opened. (Nó chưa mở cửa.)
C. It is fully staffed. (Nó đã đủ nhân sự.)
D. It is larger than the Nairobi office. (Nó lớn hơn văn phòng Nairobi.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1485, 70, NULL, NULL, 'The Finnerton Theater
The Finnerton Theater is Grenville''s premier cinema for independent movies, documentaries, and film classics. — [1] —. Locally owned and operated for over 50 years, the theater retains its strong connection to the city. Once a top entertainment destination, it later persisted through years of economic stagnation and urban decline. - [2] -. An anchor for neighborhood revitalization and growth, the Finnerton Theater now serves as the backbone of the city''s thriving Riverside Arts District.
In the last half century, the Finnerton Theater has become a destination for film lovers from throughout the region. Attendees from cities as far away as Nesterport and Belmere come regularly to enjoy the theater''s unique ambiance. Over the theater''s history, more than 1,000 movies have been screened and dozens of others have premiered. - [3] -. The Finnerton Theater has hosted events with critically acclaimed directors and served as the stage for renowned public speakers. In the past decade, it has served as the host for the Greater Cincinnati Film Festival, the Midwest Documentary Fest, and the annual Clearacre Conference, which is sponsored by the city''s largest employer, Clearacre Tech. Five years ago, the theater was added to the state''s register of historic places.
To this day, filmgoers continue to frequent the Finnerton Theater whenever film releases are screened. - [4] —. And despite the ever-increasing popularity of online film-streaming services, ticket sales at the Finnerton Theater have risen continuously since its listing in the state''s register. It is a true cultural gem and a source of civic pride for local residents.', 'Nhà hát Finnerton
Nhà hát Finnerton là rạp chiếu phim hàng đầu của Grenville dành cho các bộ phim độc lập, phim tài liệu và phim kinh điển. — [1] —. Được sở hữu và vận hành tại địa phương trong hơn 50 năm, nhà hát vẫn giữ được mối liên hệ chặt chẽ với thành phố. Từng là điểm đến giải trí hàng đầu, sau đó nó vẫn tồn tại qua nhiều năm trì trệ kinh tế và suy giảm đô thị. - [2] -. Là mỏ neo cho sự hồi sinh và phát triển của khu phố, Nhà hát Finnerton hiện đóng vai trò là xương sống của Khu Nghệ thuật Riverside thịnh vượng của thành phố.
Trong nửa thế kỷ qua, Nhà hát Finnerton đã trở thành điểm đến cho những người yêu điện ảnh từ khắp khu vực. Những người tham dự từ các thành phố xa xôi như Nesterport và Belmere thường xuyên đến để tận hưởng bầu không khí độc đáo của nhà hát. Trong lịch sử của nhà hát, hơn 1.000 bộ phim đã được chiếu và hàng chục bộ phim khác đã được công chiếu. - [3] -. Nhà hát Finnerton đã tổ chức các sự kiện với các đạo diễn được giới phê bình đánh giá cao và đóng vai trò là sân khấu cho các diễn giả nổi tiếng. Trong thập kỷ qua, nó đã từng là chủ nhà của Liên hoan phim Greater Cincinnati, Liên hoan phim tài liệu Trung Tây và Hội nghị Clearacre hàng năm, được tài trợ bởi nhà tuyển dụng lớn nhất của thành phố, Clearacre Tech. Năm năm trước, nhà hát đã được thêm vào sổ đăng ký các địa điểm lịch sử của tiểu bang.
Cho đến ngày nay, những người xem phim vẫn tiếp tục thường xuyên đến Nhà hát Finnerton bất cứ khi nào các bộ phim được chiếu. - [4] —. Và bất chấp sự phổ biến ngày càng tăng của các dịch vụ phát trực tuyến phim trực tuyến, doanh số bán vé tại Nhà hát Finnerton đã tăng liên tục kể từ khi được liệt kê trong sổ đăng ký của tiểu bang. Đó là một viên ngọc văn hóa thực sự và là nguồn tự hào công dân cho người dân địa phương.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1972, 1485, 172, 'What is the purpose of the Web page?', 'To announce an upcoming film festival', 'To discuss the opening of a new theater', 'To promote a recent film release', 'To profile a local movie theater', 'D', 'Đáp án đúng là D (To profile a local movie theater - Để giới thiệu một rạp chiếu phim địa phương). Trang web này cung cấp một bản mô tả chi tiết về Rạp chiếu phim Finnerton, bao gồm lịch sử của nó, vai trò trong cộng đồng, các sự kiện nó tổ chức, và tầm quan trọng văn hóa của nó đối với thành phố Grenville. Đây là một bản hồ sơ toàn diện về rạp chiếu phim này.
A. To announce an upcoming film festival (Để thông báo về một liên hoan phim sắp tới)
B. To discuss the opening of a new theater (Để thảo luận về việc mở một rạp chiếu phim mới)
C. To promote a recent film release (Để quảng bá một bộ phim mới phát hành)
D. To profile a local movie theater (Để giới thiệu một rạp chiếu phim địa phương)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1973, 1485, 173, 'In what city is the Finnerton Theater located?', 'Grenville', 'Nesterport', 'Belmere', 'Cincinnati', 'A', 'Đáp án đúng là A (Grenville). Câu đầu tiên của đoạn văn nêu rõ: "The Finnerton Theater is Grenville''s premier cinema for independent movies, documentaries, and film classics" (Rạp chiếu phim Finnerton là rạp chiếu phim hàng đầu của Grenville cho các bộ phim độc lập, phim tài liệu và phim kinh điển).
A. Grenville
B. Nesterport
C. Belmere
D. Cincinnati');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1974, 1485, 174, 'What is indicated about the Finnerton Theater?', 'It will move to a new building soon.', 'It has expanded its concession menu.', 'It is where a yearly conference is held.', 'It is the city''s largest employer.', 'C', 'Đáp án đúng là C (It is where a yearly conference is held - Nó là nơi tổ chức một hội nghị hàng năm). Đoạn văn cho biết: "In the past decade, it has served as the host for the Greater Cincinnati Film Festival, the Midwest Documentary Fest, and the annual Clearacre Conference, which is sponsored by the city''s largest employer, Clearacre Tech" (Trong thập kỷ qua, nó đã là nơi tổ chức Liên hoan phim Greater Cincinnati, Liên hoan phim tài liệu Midwest, và Hội nghị Clearacre thường niên, được tài trợ bởi nhà tuyển dụng lớn nhất của thành phố, Clearacre Tech).
A. It will move to a new building soon. (Nó sẽ chuyển đến một tòa nhà mới sớm.)
B. It has expanded its concession menu. (Nó đã mở rộng thực đơn đồ ăn vặt.)
C. It is where a yearly conference is held. (Nó là nơi tổ chức một hội nghị hàng năm.)
D. It is the city''s largest employer. (Nó là nhà tuyển dụng lớn nhất của thành phố.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1975, 1485, 175, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "Amid a changing cityscape, it continued to evolve with the neighborhood around it."', '[1]', '[2]', '[3]', '[4]', 'B', 'Đáp án đúng là B ([2]). Câu "Amid a changing cityscape, it continued to evolve with the neighborhood around it" (Giữa cảnh quan thành phố đang thay đổi, nó tiếp tục phát triển cùng với khu phố xung quanh) phù hợp nhất ở vị trí [2]. Vị trí này nằm sau đoạn mô tả về lịch sử của rạp chiếu phim, bao gồm cả thời kỳ suy thoái kinh tế và đô thị, và trước khi đề cập đến vai trò hiện tại của nó trong khu vực Riverside Arts District. Câu này sẽ tạo ra một sự chuyển tiếp tự nhiên giữa quá khứ và hiện tại của rạp chiếu phim.
A. [1]
B. [2]
C. [3]
D. [4]');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1486, 70, NULL, NULL, 'Here at Hapler''s Landscape Company, we believe that landscape design does not have to be challenging. Our goal is to design unique, beautiful gardens that meet our clients'' specifications and require minimal care once they have been planted. We also care deeply about reducing air, soil, and water pollution. For more information about how we achieve this, visit haplers.co.uk.
Our process is implemented in four phases. This is how it works:
Phase 1 - One of our consultants will call you and discuss your goals and vision for your property.
Phase 2 - We will conduct a thorough survey of your land to collect information on water level, elevation, soil type, and sun patterns. Note that we work on many projects at once and may not complete the survey until up to a month after your initial consultation call.
Phase 3 - Our design specialists will present you with a proposed design to suit your existing landscape. We will discuss adjustments until you are satisfied with every aspect of the plan.
Phase 4 - We will implement the design per approved project specifications.
Are you ready to get this process started and watch your land change before your eyes? Contact Hapler''s at 01632 960255.
=====
To: melinda_grotenhuis@charmail.net.uk
From: martin.sampsell@haplers.co.uk
Date: 22 February
Subject: Proposal
Attachment: haplers-draft l.org
Dear Ms. Grotenhuis,
I have attached an initial draft of a landscape design for you to consider. In our property walk-through, you indicated where you want to have a walkway from the parking area to your office. However, we are proposing something slightly different for you to consider.
Experience has taught us to make pathways in commercial settings as direct as possible.
Otherwise, people often walk through the grass anyway. You also mentioned wanting year-round flowers, so we have incorporated a variety of native plants with different blooming seasons into the design.
Please give me a call once you''ve had a chance to look at this design and I''ll walk you through the details.', 'Tại Công ty Cảnh quan của Hapler, chúng tôi tin rằng thiết kế cảnh quan không nhất thiết phải là thách thức. Mục tiêu của chúng tôi là thiết kế những khu vườn độc đáo, đẹp đẽ đáp ứng các thông số kỹ thuật của khách hàng và yêu cầu chăm sóc tối thiểu sau khi chúng đã được trồng. Chúng tôi cũng quan tâm sâu sắc đến việc giảm ô nhiễm không khí, đất và nước. Để biết thêm thông tin về cách chúng tôi đạt được điều này, hãy truy cập haplers.co.uk.
Quy trình của chúng tôi được thực hiện theo bốn giai đoạn. Đây là cách nó hoạt động:
Giai đoạn 1 - Một trong những chuyên gia tư vấn của chúng tôi sẽ gọi cho bạn và thảo luận về mục tiêu và tầm nhìn của bạn đối với tài sản của bạn.
Giai đoạn 2 - Chúng tôi sẽ tiến hành khảo sát kỹ lưỡng đất của bạn để thu thập thông tin về mực nước, độ cao, loại đất và kiểu nắng mặt trời. Lưu ý rằng chúng tôi làm việc trên nhiều dự án cùng một lúc và có thể không hoàn thành khảo sát cho đến một tháng sau cuộc gọi tư vấn ban đầu của bạn.
Giai đoạn 3 - Các chuyên gia thiết kế của chúng tôi sẽ trình bày cho bạn một thiết kế được đề xuất để phù hợp với cảnh quan hiện có của bạn. Chúng tôi sẽ thảo luận về các điều chỉnh cho đến khi bạn hài lòng với mọi khía cạnh của kế hoạch.
Giai đoạn 4 - Chúng tôi sẽ thực hiện thiết kế theo các thông số kỹ thuật dự án đã được phê duyệt.
Bạn đã sẵn sàng để bắt đầu quá trình này và xem đất của bạn thay đổi trước mắt chưa? Liên hệ với Hapler''s theo số 01632 960255.
======
Gửi: melinda_grotenhuis@charmail.net.uk
Từ: martin.sampsell@haplers.co.uk
Ngày: 22 tháng 2
Chủ đề: Đề xuất
Đính kèm: haplers-draft l.org
Kính gửi cô Grotenhuis,
Tôi đã đính kèm bản dự thảo ban đầu về thiết kế cảnh quan để bạn xem xét. Trong phần đi bộ qua tài sản của chúng tôi, bạn đã chỉ ra nơi bạn muốn có lối đi từ khu vực đỗ xe đến văn phòng của mình. Tuy nhiên, chúng tôi đang đề xuất một cái gì đó hơi khác một chút để bạn xem xét.
Kinh nghiệm đã dạy chúng tôi làm cho các lối đi trong môi trường thương mại càng trực tiếp càng tốt.
Nếu không, mọi người thường đi bộ qua bãi cỏ. Bạn cũng đã đề cập đến việc muốn hoa quanh năm, vì vậy chúng tôi đã kết hợp nhiều loại thực vật bản địa với các mùa nở khác nhau vào thiết kế.
Vui lòng gọi cho tôi khi bạn có cơ hội xem xét thiết kế này và tôi sẽ hướng dẫn bạn chi tiết.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1976, 1486, 176, 'What does the brochure indicate about the company''s designs?', 'They are colorful.', 'They are easy to maintain.', 'They make use of vacant areas.', 'They incorporate old structures.', 'B', 'Đáp án đúng là B (They are easy to maintain - Chúng dễ bảo trì). Trong đoạn đầu tiên của brochure, công ty nói rõ: "Our goal is to design unique, beautiful gardens that meet our clients'' specifications and require minimal care once they have been planted" (Mục tiêu của chúng tôi là thiết kế những khu vườn độc đáo, đẹp mắt đáp ứng yêu cầu của khách hàng và cần ít chăm sóc sau khi đã được trồng). Điều này cho thấy các thiết kế của họ dễ bảo trì.
A. They are colorful. (Chúng đầy màu sắc.)
B. They are easy to maintain. (Chúng dễ bảo trì.)
C. They make use of vacant areas. (Chúng tận dụng các khu vực trống.)
D. They incorporate old structures. (Chúng kết hợp các cấu trúc cũ.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1977, 1486, 177, 'Why are readers directed to Hapler''s Web site?', 'To understand its environmental practices', 'To view its staff''s credentials', 'To explore design ideas', 'To view testimonials from previous clients', 'A', 'Đáp án đúng là A (To understand its environmental practices - Để hiểu về các thực hành môi trường của công ty). Brochure nêu rõ: "We also care deeply about reducing air, soil, and water pollution. For more information about how we achieve this, visit haplers.co.uk" (Chúng tôi cũng rất quan tâm đến việc giảm ô nhiễm không khí, đất và nước. Để biết thêm thông tin về cách chúng tôi đạt được điều này, hãy truy cập haplers.co.uk).
A. To understand its environmental practices (Để hiểu về các thực hành môi trường của công ty)
B. To view its staff''s credentials (Để xem thông tin về bằng cấp của nhân viên)
C. To explore design ideas (Để khám phá các ý tưởng thiết kế)
D. To view testimonials from previous clients (Để xem lời chứng thực từ các khách hàng trước đây)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1978, 1486, 178, 'What is indicated about Hapler''s?', 'It provides services to multiple clients at the same time.', 'It bills all of its clients on an hourly basis.', 'It works with residential clients only.', 'It is recommended by most of its clients.', 'A', 'Đáp án đúng là A (It provides services to multiple clients at the same time - Nó cung cấp dịch vụ cho nhiều khách hàng cùng một lúc). Trong phần mô tả Giai đoạn 2, brochure nêu rõ: "Note that we work on many projects at once and may not complete the survey until up to a month after your initial consultation call" (Lưu ý rằng chúng tôi làm việc trên nhiều dự án cùng một lúc và có thể không hoàn thành khảo sát cho đến một tháng sau cuộc gọi tư vấn ban đầu của bạn).
A. It provides services to multiple clients at the same time. (Nó cung cấp dịch vụ cho nhiều khách hàng cùng một lúc.)
B. It bills all of its clients on an hourly basis. (Nó tính phí tất cả khách hàng theo giờ.)
C. It works with residential clients only. (Nó chỉ làm việc với khách hàng cá nhân.)
D. It is recommended by most of its clients. (Nó được hầu hết khách hàng giới thiệu.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1979, 1486, 179, 'At which phase of the process is Ms. Grotenhuis'' project?', 'Phase 1', 'Phase 2', 'Phase 3', 'Phase 4', 'C', 'Đáp án đúng là C (Phase 3). Dựa vào nội dung email, dự án của Ms. Grotenhuis đang ở Giai đoạn 3. Ông Sampsell đã gửi cho cô ấy một bản thiết kế ban đầu để xem xét và thảo luận, điều này phù hợp với mô tả của Giai đoạn 3 trong brochure: "Our design specialists will present you with a proposed design to suit your existing landscape. We will discuss adjustments until you are satisfied with every aspect of the plan."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1980, 1486, 180, 'Why does Mr. Sampsell suggest changing the location of a pathway?', 'To avoid a potential hazard', 'To provide the most efficient option', 'To take advantage of the shade available', 'To show the most attractive side of a building', 'B', 'Đáp án đúng là B (To provide the most efficient option - Để cung cấp lựa chọn hiệu quả nhất). Ông Sampsell giải thích: "Experience has taught us to make pathways in commercial settings as direct as possible. Otherwise, people often walk through the grass anyway." (Kinh nghiệm đã dạy chúng tôi rằng nên làm các lối đi trong môi trường thương mại càng trực tiếp càng tốt. Nếu không, mọi người thường sẽ đi qua cỏ dù sao đi nữa.) Điều này cho thấy ông đang đề xuất thay đổi vị trí lối đi để cung cấp lựa chọn hiệu quả nhất cho người sử dụng.
A. To avoid a potential hazard (Để tránh một mối nguy hiểm tiềm tàng)
B. To provide the most efficient option (Để cung cấp lựa chọn hiệu quả nhất)
C. To take advantage of the shade available (Để tận dụng bóng râm có sẵn)
D. To show the most attractive side of a building (Để cho thấy mặt đẹp nhất của tòa nhà)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1487, 70, NULL, NULL, 'Merenville Regional Bus Authority
Notice to the Public
In response to its recently conducted passenger survey, the Merenville Regional Bus Authority (MRBA) will be adjusting its Saturday and Sunday service between Merenville Central Station (MCS) and Louberg. The following schedule changes will be in effect as of May 1.
* ﻿﻿Bus 36, in service on Saturdays only, will be departing MCS every hour on the hour, with the first departure scheduled for 6:00 A.M. and the last to take place at midnight. This adjustment is intended to provide passengers with more departure options.
* ﻿﻿Bus 47, which runs on both days, will now be departing MCS at 7:00 A.M. in addition to its regularly scheduled departure times of 12:15 P.M. and 6:15 P.M.
* ﻿﻿Bus 51, which runs on both days, will continue to have three departures from MCS. However, they are now scheduled to take place at 7:30 A.M., 1:30 P.M., and 4:30 P.M.
* ﻿﻿Bus 65, in service on Sundays only, will now be departing MCS at 10:00 A.M. instead of 8:00 A.M. Departures scheduled for 1:00 P.M., 3:00 P.M., and 5:00 P.M. remain unchanged.
=====
To: Adriano Martinez <amartinez@mrba.com>
From: Claire Brunkhorst <ebrunkhorst@mrba.com>
Date: May 14
Re: Switch shift request
Hi Adriano,
Regarding your request, I can take over your late-night bus driving shift on Saturday, May 22. I realize that I''ll have to be alert, so I''ll make sure to get plenty of rest.
In return, could you possibly take over my day shift on Tuesday, May 25? A friend of mine, who works for the same Chicago-based company that I used to work for, will be visiting me that day.
Thanks in advance for your assistance.
Claire Brunkhorst, MRBA Associate', 'Hội thảo Sửa chữa Nhanh
Tham gia cùng cư dân Hagerstown tại trung tâm cộng đồng vào ngày 15 tháng 1 cho chuỗi hội thảo Sửa chữa Nhanh của chúng tôi. Chắc chắn sẽ có ít nhất một chủ đề mà bạn sẽ quan tâm. Ví dụ: bạn có thể học cách tiết kiệm tài chính mà không hạn chế lối sống của mình hoặc khám phá các cách giảm tác động của bạn đến môi trường bằng cách sống thông minh hơn. Ngoài ra, bằng cách tham dự một hội thảo, bạn có thể tìm thấy nguồn cảm hứng để cải thiện sức khỏe và hạnh phúc của gia đình mình. Grant Cardwell của chúng tôi, cư dân Hagerstown nổi tiếng và lâu năm, sẽ dẫn dắt một phiên về thời tiết hóa ngôi nhà của bạn. Đến sớm để đảm bảo chỗ ngồi cho người đó vì gần như tất cả mọi người đều háo hức học cách cắt giảm hóa đơn sưởi ấm và làm mát của họ.
Không cần đăng ký, mặc dù chúng tôi sẽ ghi lại sự tham dự. Nếu có thắc mắc, hãy liên hệ với Mike Greenly tại m.greenly@hagerstown.gov.
=====
Dòng hội thảo sửa chữa nhanh - Lịch trình
10:00 sáng
Thời tiết hóa - Làm cho ngôi nhà của bạn tiết kiệm năng lượng hơn bằng cách học hỏi từ một chuyên gia từ Sáng kiến thời tiết hóa khu vực hạt Marion (MCRWI).
Tiết kiệm nước và ví của bạn - Tìm hiểu về nguồn cung cấp nước Hagerstown và nhận các mẹo để hạn chế tiêu thụ và giảm hóa đơn tiện ích nước hàng tháng của bạn.
11:00 sáng
Sản phẩm chăm sóc cá nhân tự làm - Tự làm các sản phẩm chăm sóc cá nhân hàng ngày của riêng bạn, chẳng hạn như chất khử mùi, xà phòng và kem dưỡng ẩm cho da:
1:00 chiều
Tạo không gian tự nhiên - Trồng cây bản địa và tìm hiểu về cách nuôi dưỡng hệ sinh Giúp xây dựng một môi trường sống tự nhiên bền vững ngay trong khu vườn hoặc sân của riêng bạn.
2:00 P.
Một năm mới, một bạn khỏe mạnh hơn - Xem các minh họa về cách tạo ra những bữa ăn ngon và lành mạnh cho gia đình bạn. Các mẫu sẽ được cung cấp.
Bảo trì thiết yếu - Giữ cho chiếc xe của bạn trong tình trạng lái xe tốt nhất bất chấp thời tiết mùa đông khắc nghiệt.
====
Gửi: Mike Greenly
Từ: Antonio Perkins
Ngày: 12 tháng 1
Chủ đề: Yêu cầu
Thưa ông Greenly,
Gần đây tôi đã chuyển đến Hagerstown và tôi muốn tìm hiểu về thảm thực vật bản địa trong khu vực. Tôi có rất nhiều kinh nghiệm trồng cây và thực vật ở quê hương cũ của mình, nhưng các giống được trồng ở đây hoàn toàn khác. Một người hàng xóm đã đề cập rằng sẽ có một buổi học liên quan đến làm vườn, nhưng có hội thảo nào giải quyết mối quan tâm cụ thể của tôi trong việc tìm hiểu về hệ động thực vật bản địa không? 
Trân trọng,
Antonio Perkins');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1981, 1487, 181, 'What is the purpose of the notice?', 'To introduce a new bus route', 'To report on the closing of a bus station', 'To announce transportation-service improvements', 'To invite comments about proposed schedule changes', 'C', 'Đáp án đúng là C (To announce transportation-service improvements - Để thông báo về các cải tiến dịch vụ vận chuyển). Thông báo này chủ yếu tập trung vào việc thông báo các thay đổi lịch trình xe buýt, được mô tả là "adjusting its Saturday and Sunday service" (điều chỉnh dịch vụ vào thứ Bảy và Chủ nhật). Những thay đổi này được thực hiện dựa trên một cuộc khảo sát hành khách gần đây, cho thấy đây là nỗ lực cải thiện dịch vụ.
A. To introduce a new bus route (Để giới thiệu một tuyến xe buýt mới)
B. To report on the closing of a bus station (Để báo cáo về việc đóng cửa một trạm xe buýt)
C. To announce transportation-service improvements (Để thông báo về các cải tiến dịch vụ vận chuyển)
D. To invite comments about proposed schedule changes (Để mời góp ý về các thay đổi lịch trình được đề xuất)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1982, 1487, 182, 'What is suggested in the notice about Bus 47 ?', 'It has new stops on its route.', 'It has the earliest departure time.', 'It used to depart only in the afternoon.', 'It is in service on only one day of the week.', 'C', 'Đáp án đúng là C (It used to depart only in the afternoon - Nó trước đây chỉ khởi hành vào buổi chiều). Thông báo nêu rõ: "Bus 47, which runs on both days, will now be departing MCS at 7:00 A.M. in addition to its regularly scheduled departure times of 12:15 P.M. and 6:15 P.M." (Xe buýt 47, chạy cả hai ngày, giờ đây sẽ khởi hành từ MCS lúc 7:00 sáng ngoài các thời điểm khởi hành thường xuyên là 12:15 chiều và 6:15 tối). Điều này ngụ ý rằng trước đây, xe buýt 47 chỉ khởi hành vào buổi chiều (12:15) và tối (6:15).
A. It has new stops on its route. (Nó có các điểm dừng mới trên tuyến đường.)
B. It has the earliest departure time. (Nó có thời gian khởi hành sớm nhất.)
C. It used to depart only in the afternoon. (Nó trước đây chỉ khởi hành vào buổi chiều.)
D. It is in service on only one day of the week. (Nó chỉ hoạt động một ngày trong tuần.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1983, 1487, 183, 'What bus will Ms. Brunkhorst most likely drive on May 22 ?', 'Bus 36', 'Bus 47', 'Bus 51', 'Bus 65', 'A', 'Đáp án đúng là A (Bus 36). Trong email, Ms. Brunkhorst nói rằng cô ấy sẽ "take over your late-night bus driving shift on Saturday, May 22" (đảm nhận ca lái xe buýt đêm khuya của bạn vào thứ Bảy, ngày 22 tháng 5). Theo thông báo, Bus 36 là xe buýt duy nhất hoạt động vào thứ Bảy và có chuyến cuối cùng vào lúc nửa đêm, phù hợp với mô tả "late-night shift" (ca đêm khuya).
A. Bus 36
B. Bus 47
C. Bus 51
D. Bus 65');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1984, 1487, 184, 'In the e-mail, the word "realize" in paragraph 1, line 2, is closest in meaning to', 'earn', 'comprehend', 'exchange', 'achieve', 'B', 'Đáp án đúng là B (comprehend - hiểu). Trong ngữ cảnh của email, "I realize that I''ll have to be alert" có nghĩa là "Tôi hiểu rằng tôi sẽ phải tỉnh táo". Ở đây, "realize" được sử dụng với nghĩa là nhận thức hoặc hiểu rõ về một tình huống.
A. earn (kiếm được)
B. comprehend (hiểu)
C. exchange (trao đổi)
D. achieve (đạt được)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1985, 1487, 185, 'What does Ms. Brunkhorst indicate in the e-mail?', 'She plans to take a new job in Chicago.', 'She does not have time to visit Mr. Martinez.', 'She prefers to work the early shift on Tuesday.', 'She would like to spend time with an old friend.', 'D', 'Đáp án đúng là D (She would like to spend time with an old friend - Cô ấy muốn dành thời gian với một người bạn cũ). Ms. Brunkhorst nói: "A friend of mine, who works for the same Chicago-based company that I used to work for, will be visiting me that day" (Một người bạn của tôi, làm việc cho cùng công ty ở Chicago mà tôi đã từng làm việc, sẽ đến thăm tôi vào ngày đó). Điều này cho thấy cô ấy muốn dành thời gian với một người bạn cũ.
A. She plans to take a new job in Chicago. (Cô ấy dự định nhận một công việc mới ở Chicago.)
B. She does not have time to visit Mr. Martinez. (Cô ấy không có thời gian để thăm ông Martinez.)
C. She prefers to work the early shift on Tuesday. (Cô ấy thích làm ca sớm vào thứ Ba.)
D. She would like to spend time with an old friend. (Cô ấy muốn dành thời gian với một người bạn cũ.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1488, 70, NULL, NULL, 'Quick Fix Workshops
Join Hagerstown residents at the community center on January 15 for our Quick Fix workshop series. There is sure to be at least one topic that will interest you. For example, you might learn how to economize financially without inhibiting your lifestyle or to discover ways of reducing your impact on the environment by living smarter. Alternatively, by attending a workshop, you may find inspiration for improving the health and well-being of your family. Our own Grant Cardwell, prominent and long-time Hagerstown resident, will be leading a session on weatherizing your home. Arrive early to secure a seat for that one since nearly everyone is eager to learn how to trim their heating and cooling bills.
Registration is not required, although we will record attendance. For questions, contact Mike Greenly at m.greenly@hagerstown.gov.
=====
Quick Fix Workshop Series - Schedule
10:00 A.M.
Weatherization - Make your home more energy efficient by learning from an expert from the Marion County Regional Weatherization Initiative (MCRWI).
Save Water and Your Wallet - Find out about the Hagerstown water supply and get tips for limiting consumption and reducing your monthly water utility bills.
11:00 A.M.
DIY Personal Care Products - Make your own everyday personal care products, such as deodorant, soap, and skin moisturizer:
1:00 P.M.
Creating Natural Spaces - Grow native plants and learn about nurturing the local ecosystem. Help build a naturally sustainable habitat right in your own garden or yard.
2:00 P.M.
A New Year, a Healthier You - See demonstrations on creating delicious and healthy meals for your family. Samples will be provided.
Essential Maintenance - Keep your vehicle in top driving condition despite harsh winter weather.
====
To: Mike Greenly
From: Antonio Perkins
Date: January 12
Subject: Inquiry
Dear Mr. Greenly,
I recently moved to Hagerstown, and I am interested in learning about the native vegetation in the area. I have a lot of experience growing trees and plants in my former hometown, but the varieties that grow here are completely different. A neighbor mentioned that there would be a session related to gardening, but do any of the workshops address my specific interest in learning about the native flora and fauna?
Sincerely,
Antonio Perkins', 'Hội thảo Sửa chữa Nhanh
Tham gia cùng cư dân Hagerstown tại trung tâm cộng đồng vào ngày 15 tháng 1 cho chuỗi hội thảo Sửa chữa Nhanh của chúng tôi. Chắc chắn sẽ có ít nhất một chủ đề mà bạn sẽ quan tâm. Ví dụ: bạn có thể học cách tiết kiệm tài chính mà không hạn chế lối sống của mình hoặc khám phá các cách giảm tác động của bạn đến môi trường bằng cách sống thông minh hơn. Ngoài ra, bằng cách tham dự một hội thảo, bạn có thể tìm thấy nguồn cảm hứng để cải thiện sức khỏe và hạnh phúc của gia đình mình. Grant Cardwell của chúng tôi, cư dân Hagerstown nổi tiếng và lâu năm, sẽ dẫn dắt một phiên về thời tiết hóa ngôi nhà của bạn. Đến sớm để đảm bảo chỗ ngồi cho người đó vì gần như tất cả mọi người đều háo hức học cách cắt giảm hóa đơn sưởi ấm và làm mát của họ.
Không cần đăng ký, mặc dù chúng tôi sẽ ghi lại sự tham dự. Nếu có thắc mắc, hãy liên hệ với Mike Greenly tại m.greenly@hagerstown.gov.
=====
Dòng hội thảo sửa chữa nhanh - Lịch trình
10:00 sáng
Thời tiết hóa - Làm cho ngôi nhà của bạn tiết kiệm năng lượng hơn bằng cách học hỏi từ một chuyên gia từ Sáng kiến thời tiết hóa khu vực hạt Marion (MCRWI).
Tiết kiệm nước và ví của bạn - Tìm hiểu về nguồn cung cấp nước Hagerstown và nhận các mẹo để hạn chế tiêu thụ và giảm hóa đơn tiện ích nước hàng tháng của bạn.
11:00 sáng
Sản phẩm chăm sóc cá nhân tự làm - Tự làm các sản phẩm chăm sóc cá nhân hàng ngày của riêng bạn, chẳng hạn như chất khử mùi, xà phòng và kem dưỡng ẩm cho da:
1:00 chiều
Tạo không gian tự nhiên - Trồng cây bản địa và tìm hiểu về cách nuôi dưỡng hệ sinh Giúp xây dựng một môi trường sống tự nhiên bền vững ngay trong khu vườn hoặc sân của riêng bạn.
2:00 P.
Một năm mới, một bạn khỏe mạnh hơn - Xem các minh họa về cách tạo ra những bữa ăn ngon và lành mạnh cho gia đình bạn. Các mẫu sẽ được cung cấp.
Bảo trì thiết yếu - Giữ cho chiếc xe của bạn trong tình trạng lái xe tốt nhất bất chấp thời tiết mùa đông khắc nghiệt.
====
Gửi: Mike Greenly
Từ: Antonio Perkins
Ngày: 12 tháng 1
Chủ đề: Yêu cầu
Thưa ông Greenly,
Gần đây tôi đã chuyển đến Hagerstown và tôi muốn tìm hiểu về thảm thực vật bản địa trong khu vực. Tôi có rất nhiều kinh nghiệm trồng cây và thực vật ở quê hương cũ của mình, nhưng các giống được trồng ở đây hoàn toàn khác. Một người hàng xóm đã đề cập rằng sẽ có một buổi học liên quan đến làm vườn, nhưng có hội thảo nào giải quyết mối quan tâm cụ thể của tôi trong việc tìm hiểu về hệ động thực vật bản địa không? 
Trân trọng,
Antonio Perkins');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1986, 1488, 186, 'According to the flyer, what topic will be addressed in the workshops?', 'Beautifying a home', 'Saving money', 'Caring for pets', 'Using city recycling services', 'B', 'Đáp án đúng là B (Saving money - Tiết kiệm tiền). Trong tờ rơi có đề cập đến việc tiết kiệm tiền ở nhiều nơi. Ví dụ: "you might learn how to economize financially without inhibiting your lifestyle" (bạn có thể học cách tiết kiệm tài chính mà không ảnh hưởng đến lối sống của mình) và "nearly everyone is eager to learn how to trim their heating and cooling bills" (hầu hết mọi người đều mong muốn học cách cắt giảm hóa đơn sưởi ấm và làm mát).
A. Beautifying a home (Làm đẹp ngôi nhà)
B. Saving money (Tiết kiệm tiền)
C. Caring for pets (Chăm sóc thú cưng)
D. Using city recycling services (Sử dụng dịch vụ tái chế của thành phố)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1987, 1488, 187, 'What is most likely true about Mr. Cardwell?', 'He is a professional weather forecaster.', 'He is a member of the MCRWI organization.', 'He is a university professor.', 'He is in charge of organizing the Quick Fix workshop series.', 'B', 'Đáp án đúng là B (He is a member of the MCRWI organization - Ông ấy là thành viên của tổ chức MCRWI). Mặc dù không được nêu rõ, nhưng có thể suy luận rằng Mr. Cardwell có liên quan đến MCRWI. Tờ rơi mô tả ông là "prominent and long-time Hagerstown resident" (cư dân nổi tiếng và lâu năm của Hagerstown) và sẽ dẫn dắt một buổi học về cách chống thấm cho nhà. Lịch trình sau đó cho thấy buổi học về chống thấm được dẫn dắt bởi "an expert from the Marion County Regional Weatherization Initiative (MCRWI)" (một chuyên gia từ Sáng kiến Chống thấm Khu vực Quận Marion).
A. He is a professional weather forecaster. (Ông ấy là một nhà dự báo thời tiết chuyên nghiệp.)
B. He is a member of the MCRWI organization. (Ông ấy là thành viên của tổ chức MCRWI.)
C. He is a university professor. (Ông ấy là một giáo sư đại học.)
D. He is in charge of organizing the Quick Fix workshop series. (Ông ấy phụ trách tổ chức chuỗi hội thảo Quick Fix.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1988, 1488, 188, 'At what time is a session offered about working on cars?', '10:00 A.M.', '11:00 А.м.', '1:00 P.M.', '2:00 P.M.', 'D', 'Đáp án đúng là D (2:00 P.M.). Theo lịch trình, buổi học "Essential Maintenance - Keep your vehicle in top driving condition despite harsh winter weather" (Bảo trì thiết yếu - Giữ xe của bạn trong tình trạng lái xe tốt nhất bất chấp thời tiết mùa đông khắc nghiệt) được tổ chức lúc 2:00 P.M.
A. 10:00 A.M.
B. 11:00 А.м.
C. 1:00 P.M.
D. 2:00 P.M.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1989, 1488, 189, 'What does Mr. Perkins want information about?', 'Event topics', 'Event registration', 'Event location', 'Event scheduling', 'A', 'Đáp án đúng là A (Event topics - Chủ đề sự kiện). Trong email của mình, Mr. Perkins hỏi: "do any of the workshops address my specific interest in learning about the native flora and fauna?" (có hội thảo nào đề cập đến mối quan tâm cụ thể của tôi về việc tìm hiểu hệ thực vật và động vật bản địa không?). Điều này cho thấy ông đang tìm kiếm thông tin về chủ đề của các hội thảo.
A. Event topics (Chủ đề sự kiện)
B. Event registration (Đăng ký sự kiện)
C. Event location (Địa điểm sự kiện)
D. Event scheduling (Lịch trình sự kiện)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1990, 1488, 190, 'What workshop will Mr. Perkins likely attend?', 'Weatherization', 'DIY Personal Care Products', 'Creating Natural Spaces', 'Essential Maintenance', 'C', 'Đáp án đúng là C (Creating Natural Spaces - Tạo không gian tự nhiên). Dựa trên mối quan tâm của Mr. Perkins về hệ thực vật bản địa, hội thảo "Creating Natural Spaces" có vẻ phù hợp nhất với nhu cầu của ông. Mô tả của hội thảo này bao gồm "Grow native plants and learn about nurturing the local ecosystem" (Trồng cây bản địa và tìm hiểu về việc nuôi dưỡng hệ sinh thái địa phương), điều này trực tiếp đáp ứng mối quan tâm của ông về thực vật bản địa.
A. Weatherization (Chống thấm)
B. DIY Personal Care Products (Sản phẩm chăm sóc cá nhân tự làm)
C. Creating Natural Spaces (Tạo không gian tự nhiên)
D. Essential Maintenance (Bảo trì thiết yếu)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1489, 70, NULL, NULL, '*E-mail*
To: Rowan''s Playland management staff
From: Henry Louis
Date: 12 April
Subject: Update
Dear All,
It was a pleasure to see everyone at yesterday''s management meeting. Please note that we will not be able to meet the next two Mondays, since I will be out of town. That means we will not meet again until next month. If there is an urgent issue that needs attention in the meantime, please contact Lydia Chang.
For now, we will move forward with plans for installing a climbing wall in the Runabout Room. Kelly Mulgrew has agreed to send us the names of some companies that can do the work, along with their availability and prices.
Tom Holden will research a new vendor for the sandwiches and snacks we sell at the Little Engineer Café.
Thank you,
Henry Louis
Rowan''s Playland
=====
CLIMBING WALL OPTIONS
Company                        Total Cost                 Earliest Installation Date
Rick''s Walls of Fun              $1450                       29 May
Climbing Walls Galore       $1300                        18 May
Pru''s Climbing Walls          $1350                          3 June
Wethersfield Walls and Playgrounds  $1450       10 June
Note: Rick''s, Pru''s and Wethersfield offer green and black climbing walls.
Climbing Walls Galore offers many colors and mix-and-match options.
=====
5 Stars
22 May
Yesterday I returned to Rowan''s Playland with my two children. As always, they had a great time, but this time was extra special. They spent most of the time on the new climbing wall in the Runabout Room. Many places have climbing walls, but this one included many more colors than any we had seen before. The new menu at the Little Engineer Café is also nice. In addition to the usual child-friendly food, they now offer more choices for adults. I highly recommend Rowan''s Playland. You won''t be disappointed.
John Rawlston
East Lindstrom Village', '*E-mail*
Gửi đến: Nhân viên quản lý Playland của Rowan
Từ: Henry Louis
Ngày: 12 tháng 4
Chủ đề: Cập nhật
Thưa tất cả mọi người,
Rất vui được gặp mọi người tại cuộc họp quản lý ngày hôm qua. Xin lưu ý rằng chúng ta sẽ không thể gặp nhau vào hai ngày thứ Hai tới, vì tôi sẽ ra khỏi thị trấn. Điều đó có nghĩa là chúng ta sẽ không gặp lại nhau cho đến tháng sau. Nếu có một vấn đề khẩn cấp cần được chú ý trong thời gian chờ đợi, vui lòng liên hệ với Lydia Chang.
Hiện tại, chúng tôi sẽ tiếp tục với kế hoạch lắp đặt một bức tường leo núi trong Phòng Runabout. Kelly Mulgrew đã đồng ý gửi cho chúng tôi tên của một số công ty có thể thực hiện công việc, cùng với tính khả dụng và giá cả của họ.
Tom Holden sẽ nghiên cứu một nhà cung cấp mới cho bánh mì kẹp và đồ ăn nhẹ mà chúng tôi bán tại Little Engineer Café.
Cảm ơn bạn,
Henry Louis
Rowan''s Playland
=====
CLIMBING WALL OPTIONS
Tổng chi phí của công ty Ngày lắp đặt sớm nhất
Rick''s Walls of Fun $1450 29 tháng 5
Tường leo núi Galore $1300 18 tháng 5
Tường leo núi của Pru $1350 Ngày 3 tháng 6
Wethersfield Walls and Playgrounds $1450 ngày 10 tháng 6
Lưu ý: Rick''s, Pru''s và Wethersfield cung cấp các bức tường leo núi màu xanh lá cây và đen.
Climbing Walls Galore cung cấp nhiều màu sắc và các tùy chọn kết hợp.
======
5 Sao
Ngày 22 tháng 5
Hôm qua tôi đã trở lại Rowan''s Playland với hai đứa con của mình. Như mọi khi, họ đã có một khoảng thời gian tuyệt vời, nhưng lần này thật đặc biệt. Họ dành phần lớn thời gian trên bức tường leo núi mới trong Phòng Runabout. Nhiều nơi có tường leo núi, nhưng bức tường này bao gồm nhiều màu sắc hơn bất kỳ nơi nào chúng tôi đã thấy trước đây. Thực đơn mới tại Little Engineer Café cũng rất ngon. Ngoài các loại thực phẩm thân thiện với trẻ em thông thường, giờ đây họ cung cấp nhiều lựa chọn hơn cho người lớn. Tôi thực sự giới thiệu Rowan''s Playland. Bạn sẽ không thất vọng đâu.
John Rawlston
Làng East Lindstrom');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1991, 1489, 191, 'According to the e-mail, how often do management meetings usually take place?', 'Twice a week', 'Once a week', 'Twice a month', 'Once a month', 'B', 'Đáp án đúng là B (Once a week - Một lần một tuần). Trong email, Henry Louis viết: "we will not be able to meet the next two Mondays" (chúng ta sẽ không thể gặp nhau hai thứ Hai tới). Điều này ngụ ý rằng các cuộc họp quản lý thường diễn ra vào thứ Hai hàng tuần.
A. Twice a week (Hai lần một tuần)
B. Once a week (Một lần một tuần)
C. Twice a month (Hai lần một tháng)
D. Once a month (Một lần một tháng)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1992, 1489, 192, 'What does the e-mail indicate about the Runabout Room?', 'It will undergo some changes.', 'It will be hosting a special event.', 'It was recently opened.', 'It was featured in a recent publication.', 'A', 'Đáp án đúng là A (It will undergo some changes - Nó sẽ trải qua một số thay đổi). Email nêu rõ: "we will move forward with plans for installing a climbing wall in the Runabout Room" (chúng ta sẽ tiến hành kế hoạch lắp đặt một bức tường leo núi trong Phòng Runabout). Điều này chỉ ra rằng Phòng Runabout sẽ trải qua một số thay đổi với việc lắp đặt bức tường leo núi mới.
A. It will undergo some changes. (Nó sẽ trải qua một số thay đổi.)
B. It will be hosting a special event. (Nó sẽ tổ chức một sự kiện đặc biệt.)
C. It was recently opened. (Nó mới được mở gần đây.)
D. It was featured in a recent publication. (Nó được đề cập trong một ấn phẩm gần đây.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1993, 1489, 193, 'Who most likely created the chart?', 'Mr. Louis', 'Ms. Chang', 'Ms. Mulgrew', 'Mr. Holden', 'C', 'Đáp án đúng là C (Ms. Mulgrew). Trong email, Henry Louis nói: "Kelly Mulgrew has agreed to send us the names of some companies that can do the work, along with their availability and prices" (Kelly Mulgrew đã đồng ý gửi cho chúng tôi tên của một số công ty có thể thực hiện công việc, cùng với khả năng và giá cả của họ). Biểu đồ cung cấp chính xác những thông tin này, vì vậy có khả năng nhất là do Ms. Mulgrew tạo ra.
A. Mr. Louis
B. Ms. Chang
C. Ms. Mulgrew
D. Mr. Holden');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1994, 1489, 194, 'According to the online review, what is true about the café?', 'Its prices have been reduced.', 'Its hours have been extended.', 'Its menu includes new items.', 'Its interior was redecorated.', 'C', 'Đáp án đúng là C (Its menu includes new items - Thực đơn của nó bao gồm các món mới). Trong đánh giá trực tuyến, John Rawlston viết: "The new menu at the Little Engineer Café is also nice. In addition to the usual child-friendly food, they now offer more choices for adults" (Thực đơn mới tại Quán cà phê Little Engineer cũng rất tuyệt. Ngoài những món ăn thân thiện với trẻ em thông thường, họ giờ đây còn cung cấp nhiều lựa chọn hơn cho người lớn). Điều này chỉ ra rằng thực đơn đã được cập nhật với các món mới.
A. Its prices have been reduced. (Giá của nó đã được giảm.)
B. Its hours have been extended. (Giờ mở cửa của nó đã được kéo dài.)
C. Its menu includes new items. (Thực đơn của nó bao gồm các món mới.)
D. Its interior was redecorated. (Nội thất của nó đã được trang trí lại.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1995, 1489, 195, 'What company most likely installed the climbing wall at Rowan''s Playland?', 'Rick''s Walls of Fun', 'Climbing Walls Galore', 'Pru''s Climbing Walls', 'Wethersfield Walls and Playgrounds', 'B', 'Đáp án đúng là B (Climbing Walls Galore). Trong đánh giá trực tuyến, John Rawlston nhận xét rằng bức tường leo núi mới "included many more colors than any we had seen before" (bao gồm nhiều màu sắc hơn bất kỳ bức tường nào chúng tôi từng thấy trước đây). Trong biểu đồ, chỉ có Climbing Walls Galore được mô tả là "offers many colors and mix-and-match options" (cung cấp nhiều màu sắc và tùy chọn kết hợp). Hơn nữa, Climbing Walls Galore có ngày lắp đặt sớm nhất (18 tháng 5), phù hợp với thời gian của đánh giá (22 tháng 5).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1490, 70, NULL, NULL, 'Dublin in the Sun with Donovan Tour Operators
The following tours run from 1 April to 30 August. Please visit our headquarters or phone us at +353 22 455 0827 for tour start times each day.
Dublin Castle-3 hours, €15 per person
Guided tour of Dublin''s thirteenth-century castle led by experts in its history. Price includes entry to the castle. Starts and finishes at the castle''s main visitor entrance.
Secrets of Dublin- 2 hours, €12 per person
Walking tour around Dublin. Discover its untold stories. Starts and finishes at Donovan''s headquarters.
Garden of Ireland-5 hours, €30 per person
Half-day excursion to the mountains south of Dublin and the old city of Kilkenny. Starts and finishes at Gardiner Street Coach Station.
Galway Mini Cruise-9 hours, €70 per person
Full-day excursion to the Atlantic coast for a mini cruise beside the magnificent Cliffs of Moher. Includes lunch. Starts and finishes at Gardiner Street Coach Station.
=====
Donovan Tour Operators: July Summary/ Tour Name /ours per day/ Average profit per tour (€)/ Average profit per day (€)/
Average customer review (/5)
Dublin Castle 8/ 41/  328/ 4.8
Secrets of Dublin 6/ 58/ 348/ 3.3
Garden of Ireland 2/ 124/ 248/ 4.5
Galway Mini Cruise 1/ -297/ -297/ 4.6
=====
To: agupta @donovantouroperators.ie somalley 
From: @donovantouroperators.ie
Date: 13 August
Subject: 13 August
Dear Mr. Gupta,
As you know, we will be reducing our tour offerings as we move into the less busy months for tourism. I was thinking we should discontinue the tour to the Cliffs of Moher, as we have not profited from it. But I would like to get confirmation from you on this before I inform the designers of the new brochure about this decision.
I know you are busy this week with tour guide recruitment for our new October Magic tour, so we can meet on Monday. Would 2 P.M. work?
Regards,
Sarah O''Malley', 'Dublin in the Sun với các nhà điều hành tour du lịch Donovan
Các tour du lịch sau đây diễn ra từ ngày 1 tháng 4 đến ngày 30 tháng 8. Vui lòng ghé thăm trụ sở chính của chúng tôi hoặc gọi cho chúng tôi theo số +353 22 455 0827 để biết thời gian bắt đầu chuyến tham quan mỗi ngày.
Lâu đài Dublin-3 giờ, 15 euro mỗi người
Tham quan có hướng dẫn viên đến lâu đài thế kỷ mười ba của Dublin được dẫn dắt bởi các chuyên gia về lịch sử của nó. Giá đã bao gồm vé vào lâu đài. Bắt đầu và kết thúc tại lối vào du khách chính của lâu đài.
Bí mật của Dublin- 2 giờ, €12 mỗi người
Tham quan đi bộ quanh Dublin. Khám phá những câu chuyện chưa được kể của nó. Bắt đầu và kết thúc tại trụ sở của Donovan.
Vườn Ireland-5 giờ, €30 mỗi người
Nửa ngày tham quan những ngọn núi phía nam Dublin và thành phố cổ Kilkenny. Bắt đầu và kết thúc tại Trạm xe khách Gardiner Street.
Du thuyền nhỏ Galway-9 giờ, €70 mỗi người
Tham quan cả ngày đến bờ biển Đại Tây Dương cho một chuyến du thuyền nhỏ bên cạnh Vách đá Moher tráng lệ. Bao gồm bữa trưa. Bắt đầu và kết thúc tại Ga xe khách đường phố Gardiner.
=====
Nhà điều hành tour du lịch Donovan: Tóm tắt tháng 7/ Tên tour /của chúng tôi mỗi ngày/ Lợi nhuận trung bình mỗi tour (€)/ Lợi nhuận trung bình mỗi ngày (€)/
Đánh giá trung bình của khách hàng (/5)
Lâu đài Dublin 8/ 41/ 328/ 4.8
Bí mật của Dublin 6/ 58/ 348/ 3.3
Vườn Ireland 2/ 124/ 248/ 4.5
Du thuyền nhỏ Galway 1/ -297/ -297/ 4.6
=====
Gửi: agupta @donovantouroperators.ie somalley 
Từ: @donovantouroperators.ie
Ngày: 13 tháng 8
Chủ đề: 13 tháng 8
Kính gửi ông Gupta,
Như bạn đã biết, chúng tôi Tôi đã nghĩ rằng chúng ta nên ngừng chuyến tham quan đến Vách đá Moher, vì chúng ta đã không thu được lợi nhuận từ nó. Nhưng tôi muốn nhận được xác nhận từ bạn về điều này trước khi tôi thông báo cho các nhà thiết kế của tài liệu quảng cáo mới về quyết định này.
Tôi biết bạn bận rộn trong tuần này với việc tuyển dụng hướng dẫn viên du lịch cho chuyến tham quan October Magic mới của chúng tôi, vì vậy chúng ta có thể gặp nhau vào thứ Hai. 2 giờ chiều có được không? 
K Trân trọng,
Sarah O''Malley');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1996, 1490, 196, 'According to the brochure, what do all of the tours have in common?', 'They last the same number of hours.', 'They start from the same place.', 'They are offered during the same months.', 'They cost the same per person.', 'C', 'Đáp án đúng là C (They are offered during the same months - Chúng được cung cấp trong cùng những tháng). Brochure nêu rõ: "The following tours run from 1 April to 30 August" (Các tour sau đây chạy từ ngày 1 tháng 4 đến ngày 30 tháng 8). Đây là điểm chung duy nhất được đề cập cho tất cả các tour.
A. They last the same number of hours. (Chúng kéo dài cùng số giờ.)
B. They start from the same place. (Chúng bắt đầu từ cùng một địa điểm.)
C. They are offered during the same months. (Chúng được cung cấp trong cùng những tháng.)
D. They cost the same per person. (Chúng có cùng giá cho mỗi người.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1997, 1490, 197, 'What does the chart indicate about the Dublin Castle tour?', 'It is the most highly rated.', 'It runs less often than the Secrets of Dublin tour.', 'It makes the most profit per day of all the tours.', 'It makes more profit per tour than the Garden of Ireland tour.', 'A', 'Đáp án đúng là A (It is the most highly rated - Nó được đánh giá cao nhất). Theo biểu đồ, tour Dublin Castle có điểm đánh giá trung bình của khách hàng là 4.8/5, cao nhất trong số các tour được liệt kê.
A. It is the most highly rated. (Nó được đánh giá cao nhất.)
B. It runs less often than the Secrets of Dublin tour. (Nó chạy ít thường xuyên hơn tour Secrets of Dublin.)
C. It makes the most profit per day of all the tours. (Nó mang lại lợi nhuận mỗi ngày cao nhất trong tất cả các tour.)
D. It makes more profit per tour than the Garden of Ireland tour. (Nó mang lại lợi nhuận mỗi tour nhiều hơn tour Garden of Ireland.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1998, 1490, 198, 'How many tours to Kilkenny does Donovan Tour Operators run each day?', 'One', 'Two', 'Six', 'Eight', 'B', 'Đáp án đúng là B (Two - Hai). Theo biểu đồ, tour Garden of Ireland, là tour duy nhất đề cập đến Kilkenny, chạy 2 lần mỗi ngày.
A. One (Một)
B. Two (Hai)
C. Six (Sáu)
D. Eight (Tám)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (1999, 1490, 199, 'What is the purpose of the e-mail?', 'To place an order for brochures', 'To explain policies to a new tour guide', 'To schedule a meeting with a colleague', 'To respond to a customer complaint', 'C', 'Đáp án đúng là C (To schedule a meeting with a colleague - Để lên lịch một cuộc họp với đồng nghiệp). Email này được gửi từ Sarah O''Malley đến Mr. Gupta để thảo luận về việc ngừng một tour và đề xuất thời gian họp: "we can meet on Monday. Would 2 P.M. work?" (chúng ta có thể gặp nhau vào thứ Hai. 2 giờ chiều có được không?)
A. To place an order for brochures (Để đặt hàng brochure)
B. To explain policies to a new tour guide (Để giải thích chính sách cho một hướng dẫn viên mới)
C. To schedule a meeting with a colleague (Để lên lịch một cuộc họp với đồng nghiệp)
D. To respond to a customer complaint (Để trả lời khiếu nại của khách hàng)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2000, 1490, 200, 'According to Ms. O''Malley, what tour will most likely be discontinued?', 'Dublin Castle', 'Secrets of Dublin', 'Garden of Ireland', 'Galway Mini Cruise', 'D', 'Đáp án đúng là D (Galway Mini Cruise). Trong email, Ms. O''Malley viết: "I was thinking we should discontinue the tour to the Cliffs of Moher, as we have not profited from it" (Tôi đang nghĩ chúng ta nên ngừng tour đến Vách đá Moher, vì chúng ta không có lợi nhuận từ nó). Tour Galway Mini Cruise là tour duy nhất đề cập đến Vách đá Moher và cũng là tour duy nhất có lợi nhuận âm theo biểu đồ.
A. Dublin Castle
B. Secrets of Dublin
C. Garden of Ireland
D. Galway Mini Cruise');;

