INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1511, 72, '2023/test1/audio/test1_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2021, 1511, 21, 'How was your business trip?', 'They found some just in time.', 'I like that idea.', 'It was very productive.', NULL, 'C', 'Chuyến công tác của bạn thế nào?
A: Họ đã tìm thấy một số vừa kịp thời.
B: Tôi thích ý tưởng đó.
C: Nó rất hiệu quả.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1512, 72, '2023/test1/audio/test1_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2022, 1512, 22, 'Why did Chae-Won hire an assistant?', 'She will submit an estimate in September.', 'Anyway, they thought I was late.', 'Haven''t you noticed how busy she is?', NULL, 'C', 'Tại sao Chae-Won lại thuê trợ lý?
A: Cô ấy sẽ nộp báo giá vào tháng Chín.
B: Dù sao, họ nghĩ tôi đã trễ.
C: Bạn chưa nhận thấy cô ấy bận rộn như thế nào?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1513, 72, '2023/test1/audio/test1_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2023, 1513, 23, 'Would you mind showing me the new office space?', 'I think that''s correct.', 'Sure—it won''t take long.', 'Everyone available participated', NULL, 'B', 'Bạn có thể cho tôi xem không gian văn phòng mới không?
A: Tôi nghĩ điều đó đúng.
B: Chắc rồi—nó sẽ không mất nhiều thời gian.
C: Mọi người đều có thể tham gia');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1514, 72, '2023/test1/audio/test1_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2024, 1514, 24, 'We''re trying to decide where to order from for lunch.', 'I loved those sandwiches from Gino''s last week.', 'My brother''s friend was there.', 'I remember that song very well.', NULL, 'A', 'Chúng ta đang cố gắng quyết định xem sẽ đặt hàng ăn trưa ở đâu.
A: Tôi đã yêu thích những chiếc sandwich từ Gino''s tuần trước.
B: Bạn trai anh ấy đã có mặt ở đó.
C: Tôi nhớ bài hát đó rất rõ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1515, 72, '2023/test1/audio/test1_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2025, 1515, 25, 'When do you plan to finish the advertising campaign?', 'Next to Irina''s office.', 'By Monday morning at the latest.', 'Because it didn''t make sense to me.', NULL, 'B', 'Bạn dự định kết thúc chiến dịch quảng cáo khi nào?
A: Bên cạnh văn phòng của Irina.
B: Trước thứ Hai sáng muộn nhất.
C: Bởi vì nó không có ý nghĩa với tôi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1516, 72, '2023/test1/audio/test1_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2026, 1516, 26, 'Where will the guest speaker be joining us from?', 'Nobody shared the details with me.', 'He wasn''t gone too long.', 'First thing in the morning, I believe.', NULL, 'A', 'Diễn giả khách mời sẽ tham gia cùng chúng ta từ đâu?
A: Không ai đã chia sẻ chi tiết với tôi.
B: Anh ấy không đi quá lâu.
C: Đầu tiên vào buổi sáng, tôi tin rằng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1517, 72, '2023/test1/audio/test1_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2027, 1517, 27, 'Wouldn''t you prefer that Mi-Sun lead the training?', 'No, I filed it three months ago.', 'I just gave them to the director.', 'I don''t think she works here anymore.', NULL, 'C', 'Bạn không muốn Mi-Sun dẫn dắt buổi đào tạo sao?
A: Không, tôi đã nộp nó ba tháng trước.
B: Tôi vừa đưa chúng cho giám đốc.
C: Tôi không nghĩ cô ấy còn làm việc ở đây nữa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1518, 72, '2023/test1/audio/test1_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2028, 1518, 28, 'We should get some feedback on this book cover design.', 'Ahmed has a visual arts degree.', 'They probably skipped a week.', 'It was really hard to hear.', NULL, 'A', 'Chúng ta nên nhận được một số phản hồi về thiết kế bìa sách này.
A: Ahmed có bằng nghệ thuật thị giác.
B: Có lẽ họ đã bỏ qua một tuần.
C: Nó thực sự khó để nghe.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1519, 72, '2023/test1/audio/test1_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2029, 1519, 29, 'Would you be able to delay the meeting?', 'How much storage does it have?', 'Most people seemed to enjoy it.', 'Tatyana needs to leave for the airport in an hour.', NULL, 'C', 'Bạn có thể hoãn cuộc họp được không?
A: Nó có bao nhiêu bộ nhớ?
B: Hầu hết mọi người dường như thích nó.
C: Tatyana cần rời đi đến sân bay trong một giờ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1520, 72, '2023/test1/audio/test1_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2030, 1520, 30, 'Will you rent a car or take the train while you''re visiting?', 'They found some near the coast.', 'I don''t like driving in the city.', 'Mostly some old desks.', NULL, 'B', 'Bạn sẽ thuê xe hay đi tàu trong khi bạn đến thăm?
A: Họ đã tìm thấy một số gần bờ.
B: Tôi không thích lái xe trong thành phố.
C: Chủ yếu là một số bàn cũ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1521, 72, '2023/test1/audio/test1_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2031, 1521, 31, 'Seven thirty at night is rather late for a meeting, isn''t it?', 'If people agree on it, I will.', 'I promise I''ll keep it short.', 'I am not sure who he meant.', NULL, 'B', 'Bảy giờ ba mươi tối là khá muộn cho một cuộc họp, phải không?
A: Nếu mọi người đồng ý về điều đó, tôi sẽ.
B: Tôi hứa sẽ giữ nó ngắn gọn.
C: Tôi không chắc anh ấy nói về ai.');;

-- Data for 2023 Test1 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1522, 73, '2023/test1/audio/test1_question_32_34.mp3', NULL, 'W-Am Hello. I''m calling about my tickets for tonight''s baseball game. I''m hoping to upgrade my seats so we can sit closer to the field. The reservation is under my name: Joanna Reynolds.
M-Cn Let me take a look. Hmm. I''m sorry, Ms. Reynolds, but our system seems to be down at the moment. I can do the exchange manually, but it''ll take a little longer.
W-Am No problem. I have time.
M-Cn Thanks. Oh, and just a reminder that better seats will cost more-you''ll need to pay about 15 dollars more per seat.', 'W-Nữ: Xin chào. Tôi gọi về vé xem trận bóng chày tối nay của tôi. Tôi hy vọng có thể nâng cấp chỗ ngồi để chúng tôi có thể ngồi gần sân hơn. Đặt chỗ dưới tên tôi: Joanna Reynolds.
M-Nam: Để tôi xem nào. Hmm. Tôi xin lỗi, cô Reynolds, nhưng hệ thống của chúng tôi có vẻ đang bị lỗi vào lúc này. Tôi có thể thực hiện việc đổi vé thủ công, nhưng sẽ mất nhiều thời gian hơn một chút.
W-Nữ: Không sao. Tôi có thời gian.
M-Nam: Cảm ơn cô. À, và chỉ nhắc lại rằng chỗ ngồi tốt hơn sẽ đắt hơn - cô sẽ cần trả thêm khoảng 15 đô la cho mỗi chỗ ngồi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2032, 1522, 32, 'Why is the woman calling?', 'To request a ticket change', 'To make a dinner reservation', 'To order merchandise', 'To plan a vacation', 'A', 'Đáp án A là chính xác. Người phụ nữ gọi để yêu cầu thay đổi vé. Cụ thể, cô ấy nói: "I''m hoping to upgrade my seats so we can sit closer to the field" (Tôi hy vọng có thể nâng cấp chỗ ngồi để chúng tôi có thể ngồi gần sân hơn).
Dịch câu hỏi: Tại sao người phụ nữ gọi điện?
Dịch các đáp án:
A. Để yêu cầu thay đổi vé
B. Để đặt chỗ ăn tối
C. Để đặt hàng
D. Để lên kế hoạch cho kỳ nghỉ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1523, 73, '2023/test1/audio/test1_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2033, 1523, 33, 'Why does the man apologize?', 'An event was canceled.', 'A line is very long.', 'A payment option is unavailable.', 'A computer program is not working.', 'D', 'Đáp án D là chính xác. Người đàn ông xin lỗi vì hệ thống máy tính đang không hoạt động. Cụ thể, anh ta nói: "I''m sorry, Ms. Reynolds, but our system seems to be down at the moment" (Tôi xin lỗi, cô Reynolds, nhưng hệ thống của chúng tôi có vẻ đang bị lỗi vào lúc này).
Dịch câu hỏi: Tại sao người đàn ông xin lỗi?
Dịch các đáp án:
A. Một sự kiện đã bị hủy.
B. Một hàng đợi rất dài.
C. Một phương thức thanh toán không khả dụng.
D. Một chương trình máy tính không hoạt động.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1524, 73, '2023/test1/audio/test1_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2034, 1524, 34, 'What does the man remind the woman about?', 'A meal voucher', 'Some free souvenirs', 'An increase in price', 'A refund policy', 'C', 'Đáp án C là chính xác. Người đàn ông nhắc nhở người phụ nữ về việc tăng giá. Cụ thể, anh ta nói: "Oh, and just a reminder that better seats will cost more-you''ll need to pay about 15 dollars more per seat" (À, và chỉ nhắc lại rằng chỗ ngồi tốt hơn sẽ đắt hơn - cô sẽ cần trả thêm khoảng 15 đô la cho mỗi chỗ ngồi).
Dịch câu hỏi: Người đàn ông nhắc nhở người phụ nữ về điều gì?
Dịch các đáp án:
A. Một phiếu ăn
B. Một số quà tặng miễn phí
C. Một sự tăng giá
D. Một chính sách hoàn tiền');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1525, 73, '2023/test1/audio/test1_question_35_37.mp3', NULL, 'W-Am Thilo, are you going to the company lunch later this morning at Sullivan Bistro? I''m not sure how to get there.
M-Au Well, the train stops right near it on Hanover Street, but you''d have to transfer a few times. You know, I''m getting a ride with Farida, and she has a van.
W-Am Oh, that would be convenient! Do you know where her desk is?
M-Au Yes. She has the cubicle closest to the stairs.', 'W-Nữ: Thilo, anh có đi ăn trưa cùng công ty vào sáng nay tại Sullivan Bistro không? Tôi không chắc làm thế nào để đến đó.
M-Nam: Ừm, tàu dừng ngay gần đó trên đường Hanover, nhưng bạn sẽ phải chuyển tàu vài lần. Bạn biết đấy, tôi sẽ đi xe cùng Farida, và cô ấy có một chiếc xe van.
W-Nữ: Ồ, điều đó sẽ thuận tiện đấy! Anh có biết bàn làm việc của cô ấy ở đâu không?
M-Nam: Có. Cô ấy có vách ngăn gần cầu thang nhất.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2035, 1525, 35, 'What event will the speakers be attending later today?', 'A job fair', 'A film screening', 'A lunch', 'A conference', 'C', 'Đáp án C là chính xác. Người nói sẽ tham dự bữa trưa công ty sau đó trong ngày. Điều này được đề cập trực tiếp trong câu đầu tiên của đoạn hội thoại: "are you going to the company lunch later this morning at Sullivan Bistro?" (anh có đi ăn trưa cùng công ty vào sáng nay tại Sullivan Bistro không?)
Dịch câu hỏi: Sự kiện nào mà những người nói sẽ tham dự sau đó trong ngày?
Dịch các đáp án:
A. Một hội chợ việc làm
B. Một buổi chiếu phim
C. Một bữa trưa
D. Một hội nghị');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1526, 73, '2023/test1/audio/test1_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2036, 1526, 36, 'Why does the man say, "she has a van"?', 'To suggest inquiring about a ride', 'To express surprise at a coworker''s choice of vehicle', 'To explain why a coworker was late', 'To clarify that a coworker helped him move', 'A', 'Đáp án A là chính xác. Người đàn ông nói "she has a van" để gợi ý hỏi về việc đi nhờ xe. Điều này được ngầm hiểu từ ngữ cảnh, khi anh ta nói: "You know, I''m getting a ride with Farida, and she has a van" (Bạn biết đấy, tôi sẽ đi xe cùng Farida, và cô ấy có một chiếc xe van), gợi ý rằng người phụ nữ cũng có thể hỏi về việc đi nhờ xe.
Dịch câu hỏi: Tại sao người đàn ông nói "cô ấy có một chiếc xe van"?
Dịch các đáp án:
A. Để gợi ý hỏi về việc đi nhờ xe
B. Để bày tỏ sự ngạc nhiên về lựa chọn phương tiện của đồng nghiệp
C. Để giải thích tại sao một đồng nghiệp đến muộn
D. Để làm rõ rằng một đồng nghiệp đã giúp anh ta chuyển nhà');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1527, 73, '2023/test1/audio/test1_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2037, 1527, 37, 'What will the woman most likely do next?', 'Reschedule an event', 'Talk to another coworker', 'Request time off', 'Make a phone call', 'B', 'Đáp án B là chính xác. Người phụ nữ có khả năng sẽ nói chuyện với một đồng nghiệp khác (Farida) tiếp theo. Điều này được suy ra từ cuộc trò chuyện, khi người phụ nữ hỏi về vị trí bàn làm việc của Farida: "Do you know where her desk is?" (Anh có biết bàn làm việc của cô ấy ở đâu không?), cho thấy ý định tìm và nói chuyện với Farida.
Dịch câu hỏi: Người phụ nữ có khả năng sẽ làm gì tiếp theo?
Dịch các đáp án:
A. Lên lịch lại một sự kiện
B. Nói chuyện với một đồng nghiệp khác
C. Yêu cầu nghỉ phép
D. Thực hiện một cuộc gọi điện thoại');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1528, 73, '2023/test1/audio/test1_question_38_40.mp3', NULL, 'M-Au Hi, Sarika. We need a new assistant manager here at Jeera Groceries. You''ve been one of our best cashiers for two years now. Are you interested in the position?
W-Br Wow. I definitely am. My one concern is the working hours. Would my schedule change significantly?
M-Au You might have to work overtime once in a while, like when food deliveries arrive late, but that doesn''t happen often. Why don''t you think about it for a few days? Let me know what you decide.', 'M-Nam: Chào Sarika. Chúng ta cần một trợ lý quản lý mới ở đây tại Jeera Groceries. Cô đã là một trong những thu ngân giỏi nhất của chúng ta trong hai năm qua. Cô có quan tâm đến vị trí này không?
W-Nữ: Wow. Tôi chắc chắn quan tâm. Điều duy nhất tôi lo lắng là giờ làm việc. Lịch làm việc của tôi sẽ thay đổi đáng kể chứ?
M-Nam: Cô có thể phải làm thêm giờ thỉnh thoảng, như khi các đơn hàng thực phẩm đến muộn, nhưng điều đó không xảy ra thường xuyên. Tại sao cô không suy nghĩ về nó trong vài ngày? Hãy cho tôi biết quyết định của cô.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2038, 1528, 38, 'Where do the speakers work?', 'At a grocery store', 'At a shipping facility', 'At a restaurant', 'At a doctor''s office', 'A', 'Đáp án A là chính xác. Người nói làm việc tại một cửa hàng tạp hóa. Điều này được đề cập trực tiếp trong câu "We need a new assistant manager here at Jeera Groceries" (Chúng ta cần một trợ lý quản lý mới ở đây tại Jeera Groceries).
Dịch câu hỏi: Những người nói làm việc ở đâu?
Dịch các đáp án:
A. Tại một cửa hàng tạp hóa
B. Tại một cơ sở vận chuyển
C. Tại một nhà hàng
D. Tại một phòng khám bác sĩ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1529, 73, '2023/test1/audio/test1_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2039, 1529, 39, 'What does the woman say she is concerned about?', 'Fuel prices', 'Her work hours', 'A staff shortage', 'An inventory process', 'B', 'Đáp án B là chính xác. Người phụ nữ nói rằng cô ấy lo lắng về giờ làm việc. Cụ thể, cô ấy nói: "My one concern is the working hours. Would my schedule change significantly?" (Điều duy nhất tôi lo lắng là giờ làm việc. Lịch làm việc của tôi sẽ thay đổi đáng kể chứ?)
Dịch câu hỏi: Người phụ nữ nói cô ấy lo lắng về điều gì?
Dịch các đáp án:
A. Giá nhiên liệu
B. Giờ làm việc của cô ấy
C. Thiếu nhân viên
D. Quy trình kiểm kê');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1530, 73, '2023/test1/audio/test1_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2040, 1530, 40, 'What does the man suggest that the woman do?', 'Complete a training program', 'Order extra equipment', 'Hire a consultant', 'Take time to make a decision', 'D', 'Đáp án D là chính xác. Người đàn ông gợi ý rằng người phụ nữ nên dành thời gian để đưa ra quyết định. Cụ thể, anh ta nói: "Why don''t you think about it for a few days? Let me know what you decide." (Tại sao cô không suy nghĩ về nó trong vài ngày? Hãy cho tôi biết quyết định của cô.)
Dịch câu hỏi: Người đàn ông gợi ý người phụ nữ nên làm gì?
Dịch các đáp án:
A. Hoàn thành một chương trình đào tạo
B. Đặt thêm thiết bị
C. Thuê một nhà tư vấn
D. Dành thời gian để đưa ra quyết định');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1531, 73, '2023/test1/audio/test1_question_41_43.mp3', NULL, 'M-Cn Good morning. This is Westerly Travel''s customer service. How may I help you?
W-Br Yes, I was supposed to take the two P.M. from Denver to Colorado Springs, but it was canceled. I need to book a different train. I''m presenting at a trade show first thing in the morning, so I''m hoping you can get me on another train today.
M-Cn The four p.m. departure gets you in by six thirty, and there are plenty of seats available.
W-Br That sounds great.
M-Cn And to apologize for the inconvenience, I''ve upgraded you to business class at no extra charge.', 'M-Nam: Chào buổi sáng. Đây là dịch vụ khách hàng của Westerly Travel. Tôi có thể giúp gì cho bạn?
W-Nữ: Vâng, tôi đáng lẽ phải bắt chuyến tàu lúc 2 giờ chiều từ Denver đến Colorado Springs, nhưng nó đã bị hủy. Tôi cần đặt một chuyến tàu khác. Tôi sẽ thuyết trình tại một hội chợ thương mại vào sáng sớm mai, vì vậy tôi hy vọng anh có thể đặt cho tôi một chuyến tàu khác ngày hôm nay.
M-Nam: Chuyến khởi hành lúc 4 giờ chiều sẽ đưa bạn đến nơi lúc 6 giờ 30, và còn nhiều chỗ ngồi.
W-Nữ: Nghe tuyệt đấy.
M-Nam: Và để xin lỗi vì sự bất tiện, tôi đã nâng cấp cho bạn lên hạng thương gia mà không tính thêm phí.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2041, 1531, 41, 'Why is the woman calling?', 'Her taxi never arrived.', 'Her luggage is missing.', 'Her train was canceled.', 'Her ticket is lost.', 'C', 'Đáp án C là chính xác. Người phụ nữ gọi vì chuyến tàu của cô ấy đã bị hủy. Cô ấy nói: "I was supposed to take the two P.M. from Denver to Colorado Springs, but it was canceled. I need to book a different train." (Tôi đáng lẽ phải bắt chuyến tàu lúc 2 giờ chiều từ Denver đến Colorado Springs, nhưng nó đã bị hủy. Tôi cần đặt một chuyến tàu khác.)
Dịch câu hỏi: Tại sao người phụ nữ gọi điện?
Dịch các đáp án:
A. Taxi của cô ấy không bao giờ đến.
B. Hành lý của cô ấy bị mất.
C. Chuyến tàu của cô ấy bị hủy.
D. Vé của cô ấy bị mất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1532, 73, '2023/test1/audio/test1_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2042, 1532, 42, 'What event is the woman planning to attend?', 'An awards ceremony', 'A trade show', 'An art exhibit opening', 'A building inspection', 'B', 'Đáp án B là chính xác. Người phụ nữ dự định tham dự một hội chợ thương mại. Cô ấy nói: "I''m presenting at a trade show first thing in the morning" (Tôi sẽ thuyết trình tại một hội chợ thương mại vào sáng sớm mai).
Dịch câu hỏi: Sự kiện nào mà người phụ nữ dự định tham dự?
Dịch các đáp án:
A. Một buổi lễ trao giải
B. Một hội chợ thương mại
C. Một buổi khai mạc triển lãm nghệ thuật
D. Một cuộc kiểm tra tòa nhà');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1533, 73, '2023/test1/audio/test1_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2043, 1533, 43, 'What does the man give the woman as an apology?', 'A partial discount', 'Vouchers for future travel', 'A full refund', 'A better seat', 'D', 'Đáp án D là chính xác. Người đàn ông đã nâng cấp chỗ ngồi cho người phụ nữ để xin lỗi. Anh ta nói: "And to apologize for the inconvenience, I''ve upgraded you to business class at no extra charge." (Và để xin lỗi vì sự bất tiện, tôi đã nâng cấp cho bạn lên hạng thương gia mà không tính thêm phí.)
Dịch câu hỏi: Người đàn ông đã cho người phụ nữ cái gì để xin lỗi?
Dịch các đáp án:
A. Một khoản giảm giá một phần
B. Phiếu giảm giá cho chuyến đi trong tương lai
C. Hoàn tiền đầy đủ
D. Một chỗ ngồi tốt hơn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1534, 73, '2023/test1/audio/test1_question_44_46.mp3', NULL, 'W-Am This is Marcy Ardmore at Sladen Motors. Some automotive parts we ordered from your factory haven''t arrived at our dealership yet.
M-Au I''m sorry to hear that. We sent your order over a week ago, but the shipping company has been experiencing delays. Unfortunately, the tracking e-mails they sent us don''t contain enough detail to determine when the parts will get to you.
W-Am I see. Do you have contact information for the shipping company? I''d like to see what I can find out.
M-Au Yes, I can give you their phone number. But I''ll also call them. Hopefully the more inquiries they get, the more seriously they''ll take the issue.', 'W-Nữ: Đây là Marcy Ardmore từ Sladen Motors. Một số phụ tùng ô tô chúng tôi đặt từ nhà máy của bạn vẫn chưa đến đại lý của chúng tôi.
M-Nam: Tôi rất tiếc khi nghe điều đó. Chúng tôi đã gửi đơn hàng của bạn hơn một tuần trước, nhưng công ty vận chuyển đang gặp sự cố chậm trễ. Không may là, các email theo dõi họ gửi cho chúng tôi không chứa đủ thông tin chi tiết để xác định khi nào các phụ tùng sẽ đến chỗ bạn.
W-Nữ: Tôi hiểu rồi. Anh có thông tin liên lạc của công ty vận chuyển không? Tôi muốn tìm hiểu thêm thông tin.
M-Nam: Có, tôi có thể cho bạn số điện thoại của họ. Nhưng tôi cũng sẽ gọi cho họ. Hy vọng rằng càng nhiều yêu cầu họ nhận được, họ sẽ càng coi trọng vấn đề này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2044, 1534, 44, 'Where does the woman work?', 'At a distribution center', 'At a conference center', 'At a car dealership', 'At a real estate agency', 'C', 'Đáp án C là chính xác. Người phụ nữ làm việc tại một đại lý ô tô. Điều này được thể hiện khi cô ấy nói: "This is Marcy Ardmore at Sladen Motors. Some automotive parts we ordered from your factory haven''t arrived at our dealership yet." (Đây là Marcy Ardmore từ Sladen Motors. Một số phụ tùng ô tô chúng tôi đặt từ nhà máy của bạn vẫn chưa đến đại lý của chúng tôi.)
Dịch câu hỏi: Người phụ nữ làm việc ở đâu?
Dịch các đáp án:
A. Tại một trung tâm phân phối
B. Tại một trung tâm hội nghị
C. Tại một đại lý ô tô
D. Tại một công ty bất động sản');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1535, 73, '2023/test1/audio/test1_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2045, 1535, 45, 'What problem with some e-mails does the man mention?', 'Confusion about the intended recipients', 'A delay in message delivery', 'An incorrectly typed word', 'Lack of information', 'D', 'Đáp án D là chính xác. Người đàn ông đề cập đến vấn đề thiếu thông tin trong các email. Cụ thể, anh ta nói: "Unfortunately, the tracking e-mails they sent us don''t contain enough detail to determine when the parts will get to you." (Không may là, các email theo dõi họ gửi cho chúng tôi không chứa đủ thông tin chi tiết để xác định khi nào các phụ tùng sẽ đến chỗ bạn.)
Dịch câu hỏi: Người đàn ông đề cập đến vấn đề gì với một số email?
Dịch các đáp án:
A. Nhầm lẫn về người nhận dự định
B. Sự chậm trễ trong việc gửi tin nhắn
C. Một từ được đánh máy không chính xác
D. Thiếu thông tin');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1536, 73, '2023/test1/audio/test1_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2046, 1536, 46, 'What will the woman most likely do next?', 'Arrange a meeting', 'Make a phone call', 'Speak to her employees', 'Review an invoice', 'B', 'Đáp án B là chính xác. Người phụ nữ có khả năng sẽ thực hiện một cuộc gọi điện thoại tiếp theo. Điều này được suy ra từ việc cô ấy hỏi thông tin liên lạc của công ty vận chuyển và nói: "I''d like to see what I can find out." (Tôi muốn tìm hiểu thêm thông tin.)
Dịch câu hỏi: Người phụ nữ có khả năng sẽ làm gì tiếp theo?
Dịch các đáp án:
A. Sắp xếp một cuộc họp
B. Thực hiện một cuộc gọi điện thoại
C. Nói chuyện với nhân viên của cô ấy
D. Xem xét một hóa đơn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1537, 73, '2023/test1/audio/test1_question_47_49.mp3', NULL, 'M-Au Amina, how are plans progressing for the September release of our new model of mobile phone?
W-Br Good. Right now, the marketing department is looking at advertising options and thinking about the best way to get maximum exposure in the media.
M-Au Great. And what''s the update from our manufacturer about when they''ll begin production? Last time we spoke, you mentioned that the factory was at full capacity with other projects, and I''m worried that''ll affect our timeline.
W-Br I just spoke with them, and they''ll free up room for us soon.', 'M-Nam: Amina, kế hoạch cho việc phát hành mẫu điện thoại di động mới của chúng ta vào tháng 9 đang tiến triển như thế nào?
W-Nữ: Tốt. Hiện tại, bộ phận tiếp thị đang xem xét các lựa chọn quảng cáo và suy nghĩ về cách tốt nhất để có được sự chú ý tối đa trên các phương tiện truyền thông.
M-Nam: Tuyệt. Và có cập nhật gì từ nhà sản xuất của chúng ta về thời điểm họ sẽ bắt đầu sản xuất không? Lần trước chúng ta nói chuyện, bạn đã đề cập rằng nhà máy đang hoạt động hết công suất với các dự án khác, và tôi lo lắng điều đó sẽ ảnh hưởng đến tiến độ của chúng ta.
W-Nữ: Tôi vừa nói chuyện với họ, và họ sẽ sớm sắp xếp chỗ cho chúng ta.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2047, 1537, 47, 'What is the conversation mainly about?', 'A policy change', 'A product launch', 'Some customer feedback', 'A scheduled maintenance visit', 'B', 'Đáp án B là chính xác. Cuộc trò chuyện chủ yếu về việc ra mắt sản phẩm. Điều này được thể hiện ngay từ đầu khi người đàn ông hỏi về kế hoạch cho việc phát hành mẫu điện thoại di động mới vào tháng 9.
Dịch câu hỏi: Cuộc trò chuyện chủ yếu về điều gì?
Dịch các đáp án:
A. Một thay đổi chính sách
B. Một buổi ra mắt sản phẩm
C. Một số phản hồi từ khách hàng
D. Một chuyến thăm bảo trì theo lịch trình');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1538, 73, '2023/test1/audio/test1_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2048, 1538, 48, 'What does the woman say people at the company are currently working on?', 'Exploring publicity options', 'Finding a new vendor', 'Assembling a sales team', 'Negotiating a monthly fee', 'A', 'Đáp án A là chính xác. Người phụ nữ nói rằng nhân viên công ty hiện đang tìm hiểu các lựa chọn quảng cáo. Cụ thể, cô ấy nói: "Right now, the marketing department is looking at advertising options and thinking about the best way to get maximum exposure in the media." (Hiện tại, bộ phận tiếp thị đang xem xét các lựa chọn quảng cáo và suy nghĩ về cách tốt nhất để có được sự chú ý tối đa trên các phương tiện truyền thông.)
Dịch câu hỏi: Người phụ nữ nói rằng nhân viên công ty hiện đang làm gì?
Dịch các đáp án:
A. Khám phá các lựa chọn quảng bá
B. Tìm kiếm một nhà cung cấp mới
C. Tập hợp một đội ngũ bán hàng
D. Đàm phán một khoản phí hàng tháng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1539, 73, '2023/test1/audio/test1_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2049, 1539, 49, 'Why is the man concerned?', 'Customers have complained.', 'Price estimates are high.', 'Some changes require approval.', 'A plan may be delayed.', 'D', 'Đáp án D là chính xác. Người đàn ông lo lắng rằng kế hoạch có thể bị trì hoãn. Anh ta nói: "Last time we spoke, you mentioned that the factory was at full capacity with other projects, and I''m worried that''ll affect our timeline." (Lần trước chúng ta nói chuyện, bạn đã đề cập rằng nhà máy đang hoạt động hết công suất với các dự án khác, và tôi lo lắng điều đó sẽ ảnh hưởng đến tiến độ của chúng ta.)
Dịch câu hỏi: Tại sao người đàn ông lo lắng?
Dịch các đáp án:
A. Khách hàng đã phàn nàn.
B. Ước tính giá cao.
C. Một số thay đổi cần phê duyệt.
D. Một kế hoạch có thể bị trì hoãn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1540, 73, '2023/test1/audio/test1_question_50_52.mp3', NULL, 'W-Br Hi, Luca. Is the restaurant almost ready for this afternoon''s awards dinner?
M-Au Actually, now that the room''s been set up, I see that we''re short a few tables and chairs.
W-Br Oh, I''ve already taken care of that. I called a rental company, and they''ll be delivering the furniture we need in an hour.
M-Au Thanks for doing that. Did you also look over the final guest list? I haven''t had time to do that yet.
W-Br No, I haven''t. Why don''t we do that together now?', 'W-Nữ: Chào Luca. Nhà hàng đã gần sẵn sàng cho bữa tối trao giải chiều nay chưa?
M-Nam: Thực ra, bây giờ khi phòng đã được sắp xếp, tôi thấy chúng ta thiếu một vài bàn và ghế.
W-Nữ: Ồ, tôi đã lo liệu việc đó rồi. Tôi đã gọi cho một công ty cho thuê, và họ sẽ giao đồ nội thất chúng ta cần trong vòng một giờ nữa.
M-Nam: Cảm ơn bạn đã làm điều đó. Bạn cũng đã xem qua danh sách khách mời cuối cùng chưa? Tôi chưa có thời gian để làm việc đó.
W-Nữ: Không, tôi chưa. Tại sao chúng ta không làm việc đó cùng nhau ngay bây giờ?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2050, 1540, 50, 'What are the speakers preparing for?', 'An interview', 'A food delivery', 'A special event', 'An inspection', 'C', 'Đáp án C là chính xác. Những người nói đang chuẩn bị cho một sự kiện đặc biệt, cụ thể là bữa tối trao giải. Điều này được đề cập ngay từ đầu cuộc trò chuyện: "Is the restaurant almost ready for this afternoon''s awards dinner?" (Nhà hàng đã gần sẵn sàng cho bữa tối trao giải chiều nay chưa?)
Dịch câu hỏi: Những người nói đang chuẩn bị cho điều gì?
Dịch các đáp án:
A. Một cuộc phỏng vấn
B. Một đơn giao thức ăn
C. Một sự kiện đặc biệt
D. Một cuộc kiểm tra');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1541, 73, '2023/test1/audio/test1_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2051, 1541, 51, 'What does the woman say will be delivered in an hour?', 'Some flower arrangements', 'Some gifts for attendees', 'Some audio equipment', 'Some tables and chairs', 'D', 'Đáp án D là chính xác. Người phụ nữ nói rằng một số bàn và ghế sẽ được giao trong vòng một giờ. Cụ thể, cô ấy nói: "I called a rental company, and they''ll be delivering the furniture we need in an hour." (Tôi đã gọi cho một công ty cho thuê, và họ sẽ giao đồ nội thất chúng ta cần trong vòng một giờ nữa.)
Dịch câu hỏi: Người phụ nữ nói cái gì sẽ được giao trong vòng một giờ?
Dịch các đáp án:
A. Một số bố trí hoa
B. Một số quà tặng cho người tham dự
C. Một số thiết bị âm thanh
D. Một số bàn và ghế');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1542, 73, '2023/test1/audio/test1_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2052, 1542, 52, 'What will the speakers most likely do next?', 'Review a guest list', 'Meet with a photographer', 'Take a break', 'Taste some food', 'A', 'Đáp án A là chính xác. Những người nói có khả năng sẽ xem xét danh sách khách mời tiếp theo. Điều này được đề xuất vào cuối cuộc trò chuyện khi người phụ nữ nói: "Why don''t we do that together now?" (Tại sao chúng ta không làm việc đó cùng nhau ngay bây giờ?) sau khi người đàn ông hỏi về việc xem xét danh sách khách mời cuối cùng.
Dịch câu hỏi: Những người nói có khả năng sẽ làm gì tiếp theo?
(A) Xem lại danh sách khách mời
(B) Gặp gỡ nhiếp ảnh gia
(C) Nghỉ ngơi
(D) Nếm thử một số món ăn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1543, 73, '2023/test1/audio/test1_question_53_55.mp3', NULL, 'M-Cn Marcella, we have a problem with the business conference we''re hosting next week. I just got a call from the conference center, and they said there''s been water damage to three of the meeting rooms.
W-Am Oh no! But the rooms will be repaired in time for our conference, right?
M-Cn They said there''s a lot of damage.
W-Am OK. Well, the weather''s supposed to be nice, so we could host some of the seminars outdoors. It''s a little unconventional, but there''s plenty of space surrounding the conference center.', 'M-Nam: Marcella, chúng ta có vấn đề với hội nghị kinh doanh mà chúng ta tổ chức vào tuần tới. Tôi vừa nhận được cuộc gọi từ trung tâm hội nghị, và họ nói rằng có ba phòng họp bị hư hỏng do nước.
W-Nữ: Ôi không! Nhưng các phòng sẽ được sửa chữa kịp thời cho hội nghị của chúng ta, đúng không?
M-Nam: Họ nói rằng có rất nhiều thiệt hại.
W-Nữ: OK. Vậy thì, thời tiết được dự báo là sẽ đẹp, vì vậy chúng ta có thể tổ chức một số buổi hội thảo ngoài trời. Nó hơi không theo quy ước, nhưng có rất nhiều không gian xung quanh trung tâm hội nghị.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2053, 1543, 53, 'What event are the speakers discussing?', 'A bank opening', 'A contest', 'A business conference', 'A company anniversary', 'C', 'Đáp án C là chính xác. Những người nói đang thảo luận về một hội nghị kinh doanh. Điều này được đề cập rõ ràng ngay từ đầu cuộc trò chuyện: "we have a problem with the business conference we''re hosting next week" (chúng ta có vấn đề với hội nghị kinh doanh mà chúng ta tổ chức vào tuần tới).
Dịch câu hỏi: Những người nói đang thảo luận về sự kiện gì?
Dịch các đáp án:
A. Lễ khai trương ngân hàng
B. Một cuộc thi
C. Một hội nghị kinh doanh
D. Kỷ niệm thành lập công ty');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1544, 73, '2023/test1/audio/test1_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2054, 1544, 54, 'What does the man mean when he says, "there''s a lot of damage"?', 'He finally fully understands a problem.', 'The woman should expect a bill in the mail.', 'The woman''s assumption is incorrect.', 'A schedule needs to be adjusted.', 'C', 'Đáp án C là chính xác. Khi người đàn ông nói "there''s a lot of damage" (có rất nhiều thiệt hại), ý anh ta là giả định của người phụ nữ về việc các phòng sẽ được sửa chữa kịp thời là không chính xác. Điều này được ngụ ý từ cuộc trao đổi trước đó, khi người phụ nữ hỏi "But the rooms will be repaired in time for our conference, right?" (Nhưng các phòng sẽ được sửa chữa kịp thời cho hội nghị của chúng ta, đúng không?)
Dịch câu hỏi: Người đàn ông có ý gì khi anh ta nói "có rất nhiều thiệt hại"?
Dịch các đáp án:
A. Anh ta cuối cùng đã hiểu đầy đủ một vấn đề.
B. Người phụ nữ nên mong đợi một hóa đơn trong thư.
C. Giả định của người phụ nữ là không chính xác.
D. Một lịch trình cần được điều chỉnh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1545, 73, '2023/test1/audio/test1_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2055, 1545, 55, 'What does the woman recommend?', 'Using an outdoor area', 'Arranging technical support', 'Confirming a catering menu', 'Interviewing some job applicants', 'A', 'Đáp án A là chính xác. Người phụ nữ đề xuất sử dụng khu vực ngoài trời. Cô ấy nói: "Well, the weather''s supposed to be nice, so we could host some of the seminars outdoors. It''s a little unconventional, but there''s plenty of space surrounding the conference center." (Vậy thì, thời tiết được dự báo là sẽ đẹp, vì vậy chúng ta có thể tổ chức một số buổi hội thảo ngoài trời. Nó hơi không theo quy ước, nhưng có rất nhiều không gian xung quanh trung tâm hội nghị.)
Dịch câu hỏi: Người phụ nữ đề xuất điều gì?
Dịch các đáp án:
A. Sử dụng khu vực ngoài trời
B. Sắp xếp hỗ trợ kỹ thuật
C. Xác nhận thực đơn ăn uống
D. Phỏng vấn một số ứng viên công việc');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1546, 73, '2023/test1/audio/test1_question_56_58.mp3', NULL, 'M-Au OK, Marion, the new health-care software is all set up on your computer. It should be pretty straightforward to use. But call technology support if you run into any issues.
W-Am Great. I hear a lot of health-care providers are switching to this same software.
M-Au Yes. It''s becoming popular because it retains all of a patient''s medical records from different providers in one central system.
W-Br Excuse me. Sorry to interrupt.
M-Au No problem, Francesca. What''s up?
W-Br I overheard what you said, and just to clarify, the program can only collect and retain records from providers who use the same software, so Marion may find she still has to call around to obtain all the patient records she needs.', 'M-Nam: OK, Marion, phần mềm chăm sóc sức khỏe mới đã được cài đặt trên máy tính của bạn. Nó nên khá dễ sử dụng. Nhưng hãy gọi hỗ trợ kỹ thuật nếu bạn gặp bất kỳ vấn đề nào.
W-Nữ: Tuyệt. Tôi nghe nói nhiều nhà cung cấp dịch vụ chăm sóc sức khỏe đang chuyển sang sử dụng phần mềm này.
M-Nam: Đúng vậy. Nó đang trở nên phổ biến vì nó lưu giữ tất cả hồ sơ y tế của bệnh nhân từ các nhà cung cấp khác nhau trong một hệ thống trung tâm.
W-Nữ: Xin lỗi. Xin lỗi vì đã ngắt lời.
M-Nam: Không sao, Francesca. Có chuyện gì vậy?
W-Nữ: Tôi nghe được những gì anh nói, và chỉ để làm rõ, chương trình chỉ có thể thu thập và lưu giữ hồ sơ từ các nhà cung cấp sử dụng cùng một phần mềm, vì vậy Marion có thể thấy rằng cô ấy vẫn phải gọi điện xung quanh để lấy tất cả hồ sơ bệnh nhân cô ấy cần.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2056, 1546, 56, 'What industry do the speakers most likely work in?', 'Medicine', 'Music', 'Publishing', 'Finance', 'A', 'Đáp án A là chính xác. Những người nói có khả năng làm việc trong ngành y tế. Điều này được suy ra từ cuộc trò chuyện về phần mềm chăm sóc sức khỏe và hồ sơ y tế của bệnh nhân.
Dịch câu hỏi: Những người nói có khả năng làm việc trong ngành nào?
Dịch các đáp án:
A. Y tế
B. Âm nhạc
C. Xuất bản
D. Tài chính');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1547, 73, '2023/test1/audio/test1_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2057, 1547, 57, 'According to the man, why has a software program become popular?', 'It is less expensive than similar products.', 'It makes information more accessible.', 'It reduces environmental impact.', 'It comes with customer support.', 'B', 'Đáp án B là chính xác. Theo người đàn ông, phần mềm trở nên phổ biến vì nó làm cho thông tin dễ truy cập hơn. Anh ta nói: "It''s becoming popular because it retains all of a patient''s medical records from different providers in one central system." (Nó đang trở nên phổ biến vì nó lưu giữ tất cả hồ sơ y tế của bệnh nhân từ các nhà cung cấp khác nhau trong một hệ thống trung tâm.)
Dịch câu hỏi: Theo người đàn ông, tại sao một chương trình phần mềm trở nên phổ biến?
Dịch các đáp án:
A. Nó rẻ hơn các sản phẩm tương tự.
B. Nó làm cho thông tin dễ truy cập hơn.
C. Nó giảm tác động môi trường.
D. Nó đi kèm với hỗ trợ khách hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1548, 73, '2023/test1/audio/test1_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2058, 1548, 58, 'What might Marion still need to do?', 'Contact some service providers', 'Sign a release form', 'Check some financial information', 'Repair some equipment', 'A', 'Đáp án A là chính xác. Marion có thể vẫn cần liên hệ với một số nhà cung cấp dịch vụ. Francesca nói: "Marion may find she still has to call around to obtain all the patient records she needs." (Marion có thể thấy rằng cô ấy vẫn phải gọi điện xung quanh để lấy tất cả hồ sơ bệnh nhân cô ấy cần.)
Dịch câu hỏi: Marion có thể vẫn cần làm gì?
Dịch các đáp án:
A. Liên hệ với một số nhà cung cấp dịch vụ
B. Ký một mẫu đơn cho phép
C. Kiểm tra một số thông tin tài chính
D. Sửa chữa một số thiết bị');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1549, 73, '2023/test1/audio/test1_question_59_61.mp3', NULL, 'W-Am Let''s get this product-innovation meeting started. Sales of our fruit-and-nut bars have been strong, so we''d like to develop some other types of snack bars. What do you recommend, Stan?
M-Cn Well, we know that many people are allergic to nuts, so we should develop some snack bars without nuts. The only thing is, we''d need a separate set of equipment to avoid contamination between the two production areas.
W-Am We don''t have room at this facility for that. Pedro, you''ve been to our new production facility in Glenview, right? Is there space there for new equipment?
M-Au I think there''s extra space there. I''ll check with the facility manager to make sure, though.', 'W-Nữ: Hãy bắt đầu cuộc họp đổi mới sản phẩm này. Doanh số bán thanh bánh trái cây và hạt của chúng ta đã mạnh mẽ, vì vậy chúng tôi muốn phát triển một số loại thanh snack khác. Anh đề xuất gì, Stan?
M-Nam: Vâng, chúng ta biết rằng nhiều người bị dị ứng với các loại hạt, vì vậy chúng ta nên phát triển một số thanh snack không có hạt. Điều duy nhất là, chúng ta sẽ cần một bộ thiết bị riêng biệt để tránh nhiễm bẩn giữa hai khu vực sản xuất.
W-Nữ: Chúng ta không có đủ chỗ ở cơ sở này cho việc đó. Pedro, anh đã đến cơ sở sản xuất mới của chúng ta ở Glenview, phải không? Có không gian cho thiết bị mới ở đó không?
M-Nam: Tôi nghĩ có không gian thừa ở đó. Tuy nhiên, tôi sẽ kiểm tra với quản lý cơ sở để chắc chắn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2059, 1549, 59, 'What are the speakers discussing?', 'Proposing a business merger', 'Relocating a company''s headquarters', 'Developing additional products', 'Hiring more employees', 'C', 'Đáp án C là chính xác. Những người nói đang thảo luận về việc phát triển thêm sản phẩm. Điều này được đề cập rõ ràng ngay từ đầu cuộc trò chuyện: "Sales of our fruit-and-nut bars have been strong, so we''d like to develop some other types of snack bars." (Doanh số bán thanh bánh trái cây và hạt của chúng ta đã mạnh mẽ, vì vậy chúng tôi muốn phát triển một số loại thanh snack khác.)
Dịch câu hỏi: Những người nói đang thảo luận về điều gì?
Dịch các đáp án:
A. Đề xuất sáp nhập doanh nghiệp
B. Di dời trụ sở công ty
C. Phát triển thêm sản phẩm
D. Thuê thêm nhân viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1550, 73, '2023/test1/audio/test1_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2060, 1550, 60, 'What challenge does Stan mention?', 'A profit margin will decrease.', 'Additional equipment will be needed.', 'There are not enough job applicants.', 'There are delays in production.', 'B', 'Đáp án B là chính xác. Stan đề cập đến thách thức là cần thêm thiết bị. Anh ta nói: "The only thing is, we''d need a separate set of equipment to avoid contamination between the two production areas." (Điều duy nhất là, chúng ta sẽ cần một bộ thiết bị riêng biệt để tránh nhiễm bẩn giữa hai khu vực sản xuất.)
Dịch câu hỏi: Stan đề cập đến thách thức gì?
Dịch các đáp án:
A. Biên lợi nhuận sẽ giảm.
B. Cần thêm thiết bị.
C. Không có đủ ứng viên cho công việc.
D. Có sự chậm trễ trong sản xuất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1551, 73, '2023/test1/audio/test1_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2061, 1551, 61, 'What does Pedro say he will do?', 'Contact a facility manager', 'Adjust a budget', 'Change a work schedule', 'Research a product', 'A', 'Đáp án A là chính xác. Pedro nói rằng anh ấy sẽ liên hệ với quản lý cơ sở. Cụ thể, anh ta nói: "I''ll check with the facility manager to make sure, though." (Tuy nhiên, tôi sẽ kiểm tra với quản lý cơ sở để chắc chắn.)
Dịch câu hỏi: Pedro nói anh ấy sẽ làm gì?
Dịch các đáp án:
A. Liên hệ với quản lý cơ sở
B. Điều chỉnh ngân sách
C. Thay đổi lịch làm việc
D. Nghiên cứu một sản phẩm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1552, 73, '2023/test1/audio/test1_question_62_64.mp3', '2023/test1/image/test1-p3-image-62.jpg', 'V-Au Welcome to The Boat Center. How may I help you?
W-Am Hi. Do you have any tickets for the Sea-Ride Special tour today? I was hoping to catch a last-minute tour.
M-Au Sorry, We''re sold out. It''s a really popular tour this time of year because the penguins are migrating through the area.
W-Am Oh, too bad. I''m leaving tomorrow morning, and I was really hoping to take one of your tours.
M-Au Well, the Island Exploration tour still has a couple of spots left.
W-Am Great! And that''ll give me time to get something to eat before it starts. I see there''s a coffee shop just down the street.', 'V-Nam: Chào mừng đến với Trung tâm Thuyền. Tôi có thể giúp gì cho bạn?
W-Nữ: Xin chào. Bạn có vé nào cho tour Sea-Ride Special hôm nay không? Tôi hy vọng có thể bắt kịp một tour vào phút chót.
M-Nam: Xin lỗi, chúng tôi đã bán hết. Đây là một tour rất phổ biến vào thời điểm này trong năm vì chim cánh cụt đang di cư qua khu vực này.
W-Nữ: Ồ, thật tệ. Tôi sẽ rời đi vào sáng mai, và tôi thực sự hy vọng được tham gia một trong các tour của bạn.
M-Nam: Vâng, tour Khám phá Đảo vẫn còn một vài chỗ trống.
W-Nữ: Tuyệt! Và điều đó sẽ cho tôi thời gian để ăn một chút trước khi nó bắt đầu. Tôi thấy có một quán cà phê ngay dưới đường.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2062, 1552, 62, 'According to the man, why is today''s Sea-Ride Special tour popular?', 'It offers a chance to see migrating birds.', 'Water conditions are likely to be favorable.', 'A guest chef is preparing lunch.', 'Someone special will be guiding the tour.', 'A', 'Đáp án A là chính xác. Theo người đàn ông, tour Sea-Ride Special hôm nay phổ biến vì nó cung cấp cơ hội xem chim di cư (cụ thể là chim cánh cụt). Anh ta nói: "It''s a really popular tour this time of year because the penguins are migrating through the area." (Đây là một tour rất phổ biến vào thời điểm này trong năm vì chim cánh cụt đang di cư qua khu vực này.)
Dịch câu hỏi: Theo người đàn ông, tại sao tour Sea-Ride Special hôm nay lại phổ biến?
Dịch các đáp án:
A. Nó cung cấp cơ hội xem chim di cư.
B. Điều kiện nước có khả năng thuận lợi.
C. Một đầu bếp khách mời đang chuẩn bị bữa trưa.
D. Một người đặc biệt sẽ hướng dẫn tour.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1553, 73, '2023/test1/audio/test1_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2063, 1553, 63, 'Look at the graphic. What time will the woman depart on a tour?', 'At 9 A.M.', 'At 10 A.M.', 'At 11 A.M.', 'At 12 P.M.', 'D', 'Đáp án D là chính xác. Theo hình ảnh, tour Khám phá Đảo (Island Exploration) mà người phụ nữ sẽ tham gia diễn ra lúc 12 P.M.
Dịch câu hỏi: Nhìn vào hình ảnh. Người phụ nữ sẽ khởi hành tour lúc mấy giờ?
Dịch các đáp án:
A. Lúc 9 giờ sáng
B. Lúc 10 giờ sáng
C. Lúc 11 giờ sáng
D. Lúc 12 giờ trưa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1554, 73, '2023/test1/audio/test1_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2064, 1554, 64, 'What will the woman most likely do next?', 'Return to her hotel', 'Visit a cafe', 'Call a friend', 'Store her bags in a locker', 'B', 'Đáp án B là chính xác. Người phụ nữ có khả năng sẽ ghé thăm một quán cà phê tiếp theo. Cô ấy nói: "And that''ll give me time to get something to eat before it starts. I see there''s a coffee shop just down the street." (Và điều đó sẽ cho tôi thời gian để ăn một chút trước khi nó bắt đầu. Tôi thấy có một quán cà phê ngay dưới đường.)
Dịch câu hỏi: Người phụ nữ có khả năng sẽ làm gì tiếp theo?
Dịch các đáp án:
A. Quay trở lại khách sạn của cô ấy
B. Ghé thăm một quán cà phê
C. Gọi điện cho một người bạn
D. Cất túi của cô ấy vào tủ khóa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1555, 73, '2023/test1/audio/test1_question_65_67.mp3', '2023/test1/image/test1-p3-image-65.jpg', 'M-Cn Hi. I''m here for the health and wellness conference. I parked in the event center parking area. I was wondering, is parking free for conference attendees?
W-Br No. I''m sorry. We don''t provide any reimbursements for parking. But if you''re willing to move your car, there''s a cheaper parking area at Seventh Avenue and Vine Street. It''s about a block away.
M-Cn Oh, unfortunately, I don''t have time. I''m scheduled to attend the strength-training seminar that starts in fifteen minutes. But tomorrow I''ll get here earlier and park at the other lot. Seventh and Vine, you said. Right?
W-Br That''s correct.', 'M-Nam: Xin chào. Tôi đến đây để tham dự hội nghị sức khỏe và wellness. Tôi đã đỗ xe ở khu vực đỗ xe của trung tâm sự kiện. Tôi tự hỏi, việc đỗ xe có miễn phí cho người tham dự hội nghị không?
W-Nữ: Không. Tôi xin lỗi. Chúng tôi không cung cấp bất kỳ khoản hoàn trả nào cho việc đỗ xe. Nhưng nếu bạn sẵn sàng di chuyển xe của mình, có một khu vực đỗ xe rẻ hơn ở góc Đại lộ Seventh và Phố Vine. Nó cách đây khoảng một dãy nhà.
M-Nam: Ồ, tiếc là tôi không có thời gian. Tôi có lịch tham dự hội thảo tập luyện sức mạnh bắt đầu trong mười lăm phút nữa. Nhưng ngày mai tôi sẽ đến đây sớm hơn và đỗ xe ở bãi đỗ kia. Seventh và Vine, bạn nói vậy phải không?
W-Nữ: Đúng vậy.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2065, 1555, 65, 'Why does the woman apologize?', 'A conference session is full.', 'An elevator is not working.', 'A workshop has changed locations.', 'Parking is not free.', 'D', 'Đáp án D là chính xác. Người phụ nữ xin lỗi vì bãi đỗ xe không miễn phí. Cô ấy nói: "No. I''m sorry. We don''t provide any reimbursements for parking." (Không. Tôi xin lỗi. Chúng tôi không cung cấp bất kỳ khoản hoàn trả nào cho việc đỗ xe.)
Dịch câu hỏi: Tại sao người phụ nữ xin lỗi?
Dịch các đáp án:
A. Một phiên hội nghị đã đầy.
B. Một thang máy không hoạt động.
C. Một hội thảo đã thay đổi địa điểm.
D. Bãi đỗ xe không miễn phí.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1556, 73, '2023/test1/audio/test1_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2066, 1556, 66, 'Look at the graphic. Which location does the woman recommend?', 'Area 1', 'Area 2', 'Area 3', 'Area 4', 'C', 'Đáp án C là chính xác. Người phụ nữ đề xuất khu vực đỗ xe ở góc Đại lộ Seventh và Phố Vine, tương ứng với Khu vực 3 trong hình ảnh.
Dịch câu hỏi: Nhìn vào hình ảnh. Địa điểm nào người phụ nữ đề xuất?
Dịch các đáp án:
A. Khu vực 1
B. Khu vực 2
C. Khu vực 3
D. Khu vực 4');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1557, 73, '2023/test1/audio/test1_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2067, 1557, 67, 'Why is the man in a hurry?', 'A workshop is starting soon.', 'A parking pass is about to expire.', 'A shuttle is running late.', 'A friend is waiting outside.', 'A', 'Đáp án A là chính xác. Người đàn ông đang vội vì một hội thảo sắp bắt đầu. Anh ta nói: "I''m scheduled to attend the strength-training seminar that starts in fifteen minutes." (Tôi có lịch tham dự hội thảo tập luyện sức mạnh bắt đầu trong mười lăm phút nữa.)
Dịch câu hỏi: Tại sao người đàn ông đang vội?
Dịch các đáp án:
A. Một hội thảo sắp bắt đầu.
B. Một vé đỗ xe sắp hết hạn.
C. Một xe đưa đón đang chạy trễ.
D. Một người bạn đang đợi bên ngoài.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1558, 73, '2023/test1/audio/test1_question_68_70.mp3', '2023/test1/image/test1-p3-image-68.jpg', 'M-Cn Molina''s Office Store. How can I help?
W-Am Hi. I''ve been trying to order a product on your Web site, but every time I get to the checkout screen, everything freezes, and I can''t place the order.
M-Cn What are you trying to buy?
W-Am The Enzo 5000 scanner.
M-Cn Hmm. That product''s currently out of stock. Can I recommend the Rhenium 60 instead? It''s a popular model.
W-Am I really need the Enzo 5000-I''m an artist and I make my own prints, so I need a model that produces top-quality images.
M-Cn I see. Well, we''re expecting a shipment tomorrow. If it includes the model you''re looking for, I can reserve it for you.', 'Cửa hàng văn phòng của M-Cn Molina. Tôi có thể giúp gì? 
W-Am Xin chào. Tôi đã cố gắng đặt hàng một sản phẩm trên trang web của bạn, nhưng mỗi khi tôi đến màn hình thanh toán, mọi thứ đều bị đóng băng và tôi không thể đặt hàng.
M-Cn Bạn đang cố gắng mua gì? 
W-Là Máy quét Enzo 5000.
M-Cn Hmm. Sản phẩm đó hiện đã hết hàng. Thay vào đó, tôi có thể giới thiệu Rhenium 60 không? Đó là một mô hình phổ biến.
W-Tôi thực sự cần Enzo 5000-Tôi là một nghệ sĩ và tôi tự tạo ra các bản in của mình, vì vậy tôi cần một mô hình tạo ra hình ảnh chất lượng hàng đầu.
M-Cn Tôi thấy. Chà, chúng tôi đang mong đợi một lô hàng vào ngày mai. Nếu nó bao gồm mô hình bạn đang tìm kiếm, tôi có thể đặt nó cho bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2068, 1558, 68, 'Why does the woman call?', 'She wants to request a refund.', 'She is unable to place an order online.', 'She wants to extend a deadline.', 'She is unhappy with a product purchased recently.', 'B', 'Đáp án B là chính xác. Người phụ nữ gọi điện vì cô ấy không thể đặt hàng trực tuyến. Cô ấy nói: "I''ve been trying to order a product on your Web site, but every time I get to the checkout screen, everything freezes, and I can''t place the order." (Tôi đã cố gắng đặt hàng một sản phẩm trên trang web của bạn, nhưng mỗi lần tôi đến màn hình thanh toán, mọi thứ đều đóng băng, và tôi không thể đặt hàng được.)
Dịch câu hỏi: Tại sao người phụ nữ gọi điện?
Dịch các đáp án:
A. Cô ấy muốn yêu cầu hoàn tiền.
B. Cô ấy không thể đặt hàng trực tuyến.
C. Cô ấy muốn gia hạn một thời hạn.
D. Cô ấy không hài lòng với một sản phẩm đã mua gần đây.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1559, 73, '2023/test1/audio/test1_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2069, 1559, 69, 'Look at the graphic. What is the price of the item the woman wants to buy?', '$169.99', '$149.99', '$129.99', '$179.99', 'D', 'Đáp án D là chính xác. Theo hình ảnh, giá của máy quét Enzo 5000 mà người phụ nữ muốn mua là $179.99.
Dịch câu hỏi: Nhìn vào hình ảnh. Giá của món hàng mà người phụ nữ muốn mua là bao nhiêu?
Dịch các đáp án:
A. $169.99
B. $149.99
C. $129.99
D. $179.99');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1560, 73, '2023/test1/audio/test1_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2070, 1560, 70, 'What will the man most likely do tomorrow?', 'Update a Web site', 'Search a storage area', 'Contact another store location', 'Check an incoming shipment', 'D', 'Đáp án D là chính xác. Người đàn ông có khả năng sẽ kiểm tra lô hàng đến vào ngày mai. Anh ta nói: "Well, we''re expecting a shipment tomorrow. If it includes the model you''re looking for, I can reserve it for you." (Vâng, chúng tôi đang chờ một lô hàng vào ngày mai. Nếu nó bao gồm mẫu bạn đang tìm kiếm, tôi có thể đặt trước cho bạn.)
Dịch câu hỏi: Người đàn ông có khả năng sẽ làm gì vào ngày mai?
Dịch các đáp án:
A. Cập nhật trang web
B. Tìm kiếm trong khu vực lưu trữ
C. Liên hệ với một địa điểm cửa hàng khác
D. Kiểm tra lô hàng đến');;

-- Data for 2023 Test1 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1561, 74, '2023/test1/audio/test1_question_71_73.mp3', NULL, 'W-Am Attention all film lovers! The Braddon Cinema has just opened. Its interior is designed to resemble the classic cinemas from the 1920s. It offers comfortable, reclining seats and individual tray tables for food and drinks. The grand opening is next week and will feature showings of classic films from different eras! And here''s good advice: to avoid traffic in the city center, the Braddon Cinema is easily reached by riding the train to Center Station.', 'W-Nữ: Chú ý tất cả những người yêu phim! Rạp chiếu phim Braddon vừa mới khai trương. Nội thất của nó được thiết kế để giống với các rạp chiếu phim cổ điển từ những năm 1920. Nó cung cấp ghế ngồi thoải mái, có thể ngả lưng và bàn đựng thức ăn và đồ uống riêng. Lễ khai trương chính thức sẽ diễn ra vào tuần tới và sẽ chiếu các bộ phim cổ điển từ các thời đại khác nhau! Và đây là lời khuyên hữu ích: để tránh tắc nghẽn giao thông ở trung tâm thành phố, bạn có thể dễ dàng đến Rạp chiếu phim Braddon bằng cách đi tàu đến Ga Trung tâm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2071, 1561, 71, 'What feature of a business does the speaker emphasize?', 'The quality of its food', 'The extended hours it is open', 'The style of its decor', 'The affordable prices it offers', 'C', 'Đáp án C là chính xác. Người nói nhấn mạnh vào phong cách trang trí của rạp chiếu phim. Cụ thể, họ nói: "Its interior is designed to resemble the classic cinemas from the 1920s." (Nội thất của nó được thiết kế để giống với các rạp chiếu phim cổ điển từ những năm 1920.)
Dịch câu hỏi: Người nói nhấn mạnh đặc điểm nào của doanh nghiệp?
Dịch các đáp án:
A. Chất lượng thức ăn của nó
B. Giờ mở cửa kéo dài
C. Phong cách trang trí của nó
D. Giá cả phải chăng mà nó cung cấp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1562, 74, '2023/test1/audio/test1_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2072, 1562, 72, 'What can attendees do at the grand opening event?', 'Go on a tour', 'Get a free gift', 'Talk to an actor', 'Watch some movies', 'D', 'Đáp án D là chính xác. Tại sự kiện khai trương, người tham dự có thể xem một số bộ phim. Cụ thể, thông báo nói: "The grand opening is next week and will feature showings of classic films from different eras!" (Lễ khai trương chính thức sẽ diễn ra vào tuần tới và sẽ chiếu các bộ phim cổ điển từ các thời đại khác nhau!)
Dịch câu hỏi: Người tham dự có thể làm gì tại sự kiện khai trương?
Dịch các đáp án:
A. Đi tham quan
B. Nhận một món quà miễn phí
C. Nói chuyện với một diễn viên
D. Xem một số bộ phim');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1563, 74, '2023/test1/audio/test1_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2073, 1563, 73, 'What does the speaker advise event attendees to do?', 'Arrive early', 'Use public transportation', 'Order tickets in advance', 'Purchase a membership', 'B', 'Đáp án B là chính xác. Người nói khuyên người tham dự sự kiện sử dụng phương tiện giao thông công cộng. Cụ thể, họ nói: "to avoid traffic in the city center, the Braddon Cinema is easily reached by riding the train to Center Station." (để tránh tắc nghẽn giao thông ở trung tâm thành phố, bạn có thể dễ dàng đến Rạp chiếu phim Braddon bằng cách đi tàu đến Ga Trung tâm.)
Dịch câu hỏi: Người nói khuyên người tham dự sự kiện nên làm gì?
Dịch các đáp án:
A. Đến sớm
B. Sử dụng phương tiện giao thông công cộng
C. Đặt vé trước
D. Mua thẻ thành viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1564, 74, '2023/test1/audio/test1_question_74_76.mp3', NULL, 'M-Cn Hi. This is Abdi calling from the Springtown Hotel reservation desk. We received your e-mail regarding your upcoming reservation. I see that you asked to move to a room facing the ocean. We make every effort to accommodate such requests, but those rooms are always booked far in advance. Your current room, though, has a lovely view of our garden, which we think you will quite enjoy this time of year. And don''t forget to bring your swimming suit! Our new pool will be open for the first time this weekend.', 'M-Nam: Xin chào. Đây là Abdi gọi từ quầy đặt phòng Khách sạn Springtown. Chúng tôi đã nhận được email của bạn về việc đặt phòng sắp tới. Tôi thấy rằng bạn đã yêu cầu chuyển đến một phòng hướng ra biển. Chúng tôi cố gắng hết sức để đáp ứng những yêu cầu như vậy, nhưng những phòng đó luôn được đặt trước rất lâu. Tuy nhiên, phòng hiện tại của bạn có tầm nhìn đẹp ra khu vườn của chúng tôi, mà chúng tôi nghĩ bạn sẽ khá thích vào thời điểm này trong năm. Và đừng quên mang theo đồ bơi của bạn! Hồ bơi mới của chúng tôi sẽ mở cửa lần đầu tiên vào cuối tuần này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2074, 1564, 74, 'What does the listener want to do?', 'Request shuttle service', 'Extend a hotel stay', 'Change a room assignment', 'Cancel a reservation', 'C', 'Đáp án C là chính xác. Người nghe muốn thay đổi phòng được chỉ định. Điều này được thể hiện qua câu: "I see that you asked to move to a room facing the ocean." (Tôi thấy rằng bạn đã yêu cầu chuyển đến một phòng hướng ra biển.)
Dịch câu hỏi: Người nghe muốn làm gì?
Dịch các đáp án:
A. Yêu cầu dịch vụ đưa đón
B. Gia hạn thời gian lưu trú tại khách sạn
C. Thay đổi phòng được chỉ định
D. Hủy đặt phòng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1565, 74, '2023/test1/audio/test1_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2075, 1565, 75, 'Why does the speaker say, "those rooms are always booked far in advance"?', 'To express approval for a room design', 'To explain why a hotel is successful', 'To indicate his disbelief', 'To deny the listener''s request', 'D', 'Đáp án D là chính xác. Người nói đưa ra câu nói này để từ chối yêu cầu của người nghe. Anh ta đang giải thích lý do tại sao không thể đáp ứng yêu cầu chuyển đến phòng hướng ra biển.
Dịch câu hỏi: Tại sao người nói nói "những phòng đó luôn được đặt trước rất lâu"?
Dịch các đáp án:
A. Để bày tỏ sự tán thành đối với thiết kế phòng
B. Để giải thích tại sao một khách sạn thành công
C. Để chỉ ra sự không tin của anh ta
D. Để từ chối yêu cầu của người nghe');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1566, 74, '2023/test1/audio/test1_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2076, 1566, 76, 'According to the speaker, what should the listener bring?', 'Some warm clothes', 'Some swimwear', 'A credit card', 'A copy of a key', 'B', 'Đáp án B là chính xác. Theo người nói, người nghe nên mang theo đồ bơi. Anh ta nói: "And don''t forget to bring your swimming suit!" (Và đừng quên mang theo đồ bơi của bạn!)
Dịch câu hỏi: Theo người nói, người nghe nên mang theo gì?
Dịch các đáp án:
A. Một số quần áo ấm
B. Một số đồ bơi
C. Một thẻ tín dụng
D. Một bản sao của chìa khóa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1567, 74, '2023/test1/audio/test1_question_77_79.mp3', NULL, 'W-Am Good morning, volunteers. My name is Lisa Campbell. Thank you for coming today to help us maintain the natural habitat here at the Blue Mountain Forest Preserve. Forest conservation is so important! Since this is your first day, I''ll cover some of the basics. I advise you to always carry water with you. We have refillable bottles, and everyone is welcome to take one as a gift from us at the forest preserve. It can get hot in the afternoon, so staying hydrated is important. Now, if you''ll follow me, I''ll show you the steps for planting young tree saplings to support biodiversity.', 'W-Nữ: Chào buổi sáng, các tình nguyện viên. Tôi tên là Lisa Campbell. Cảm ơn các bạn đã đến hôm nay để giúp chúng tôi duy trì môi trường sống tự nhiên ở đây tại Khu Bảo tồn Rừng Blue Mountain. Bảo tồn rừng rất quan trọng! Vì đây là ngày đầu tiên của các bạn, tôi sẽ đề cập đến một số điều cơ bản. Tôi khuyên các bạn nên luôn mang theo nước. Chúng tôi có những chai nước có thể đổ đầy lại, và mọi người đều được chào đón để lấy một chai làm quà từ chúng tôi tại khu bảo tồn rừng. Trời có thể nóng vào buổi chiều, vì vậy việc giữ đủ nước rất quan trọng. Bây giờ, nếu các bạn theo tôi, tôi sẽ chỉ cho các bạn các bước để trồng cây non để hỗ trợ đa dạng sinh học.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2077, 1567, 77, 'Who most likely is the speaker?', 'An archaeologist', 'A marine biologist', 'A conservation expert', 'An athletic trainer', 'C', 'Đáp án C là chính xác. Người nói có khả năng là một chuyên gia bảo tồn. Điều này được suy ra từ nội dung bài phát biểu của cô ấy về bảo tồn rừng và duy trì môi trường sống tự nhiên.
Dịch câu hỏi: Người nói có khả năng là ai?
Dịch các đáp án:
A. Một nhà khảo cổ học
B. Một nhà sinh vật học biển
C. Một chuyên gia bảo tồn
D. Một huấn luyện viên thể thao');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1568, 74, '2023/test1/audio/test1_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2078, 1568, 78, 'What does the speaker advise the listeners to do?', 'Take a water bottle', 'Consult a site map', 'Apply sunscreen regularly', 'Write careful notes', 'A', 'Đáp án A là chính xác. Người nói khuyên người nghe nên lấy một chai nước. Cô ấy nói: "We have refillable bottles, and everyone is welcome to take one as a gift from us at the forest preserve." (Chúng tôi có những chai nước có thể đổ đầy lại, và mọi người đều được chào đón để lấy một chai làm quà từ chúng tôi tại khu bảo tồn rừng.)
Dịch câu hỏi: Người nói khuyên người nghe nên làm gì?
Dịch các đáp án:
A. Lấy một chai nước
B. Tham khảo bản đồ khu vực
C. Thoa kem chống nắng thường xuyên
D. Ghi chú cẩn thận');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1569, 74, '2023/test1/audio/test1_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2079, 1569, 79, 'What does the speaker say she is going to do next?', 'Answer some questions', 'Demonstrate a process', 'Introduce a colleague', 'Take the listeners to lunch', 'B', 'Đáp án B là chính xác. Người nói nói rằng cô ấy sẽ minh họa một quy trình tiếp theo. Cụ thể, cô ấy nói: "Now, if you''ll follow me, I''ll show you the steps for planting young tree saplings to support biodiversity." (Bây giờ, nếu các bạn theo tôi, tôi sẽ chỉ cho các bạn các bước để trồng cây non để hỗ trợ đa dạng sinh học.)
Dịch câu hỏi: Người nói nói rằng cô ấy sẽ làm gì tiếp theo?
Dịch các đáp án:
A. Trả lời một số câu hỏi
B. Minh họa một quy trình
C. Giới thiệu một đồng nghiệp
D. Đưa người nghe đi ăn trưa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1570, 74, '2023/test1/audio/test1_question_80_82.mp3', NULL, 'W-Br Hello. I''m calling about the financial-management workshop that your company is hosting later this week. I''m with the Archton Group; we registered for the workshop over a month ago. I realized that we never received the meal vouchers that are supposed to be part of the workshop package. We need these because we have ten people attending, and we are traveling long-distance to attend the conference. Would you please send me an e-mail with the meal vouchers included as an attachment as soon as you can? Thank you.', 'W-Nữ: Xin chào. Tôi gọi về hội thảo quản lý tài chính mà công ty của bạn tổ chức vào cuối tuần này. Tôi đến từ Tập đoàn Archton; chúng tôi đã đăng ký hội thảo cách đây hơn một tháng. Tôi nhận ra rằng chúng tôi chưa bao giờ nhận được phiếu ăn mà lẽ ra phải là một phần của gói hội thảo. Chúng tôi cần những phiếu này vì chúng tôi có mười người tham dự, và chúng tôi đang di chuyển từ xa để tham dự hội nghị. Bạn có thể gửi cho tôi một email với phiếu ăn được đính kèm càng sớm càng tốt không? Cảm ơn bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2080, 1570, 80, 'Why will the speaker be traveling?', 'To inspect a factory', 'To repair a product', 'To perform in a concert', 'To attend a workshop', 'D', 'Đáp án D là chính xác. Người nói sẽ đi du lịch để tham dự một hội thảo. Cô ấy nói: "I''m calling about the financial-management workshop that your company is hosting later this week." (Tôi gọi về hội thảo quản lý tài chính mà công ty của bạn tổ chức vào cuối tuần này.)
Dịch câu hỏi: Tại sao người nói sẽ đi du lịch?
Dịch các đáp án:
A. Để kiểm tra một nhà máy
B. Để sửa chữa một sản phẩm
C. Để biểu diễn trong một buổi hòa nhạc
D. Để tham dự một hội thảo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1571, 74, '2023/test1/audio/test1_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2081, 1571, 81, 'Why is the speaker concerned?', 'A seating arrangement is wrong.', 'A company credit card was not charged.', 'Some meal tickets were not sent.', 'Her taxi driver is unable to find a hotel.', 'C', 'Đáp án C là chính xác. Người nói lo lắng vì một số phiếu ăn đã không được gửi. Cô ấy nói: "I realized that we never received the meal vouchers that are supposed to be part of the workshop package." (Tôi nhận ra rằng chúng tôi chưa bao giờ nhận được phiếu ăn mà lẽ ra phải là một phần của gói hội thảo.)
Dịch câu hỏi: Tại sao người nói lo lắng?
Dịch các đáp án:
A. Một sắp xếp chỗ ngồi bị sai.
B. Một thẻ tín dụng công ty không được tính phí.
C. Một số phiếu ăn đã không được gửi.
D. Tài xế taxi của cô ấy không thể tìm thấy khách sạn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1572, 74, '2023/test1/audio/test1_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2082, 1572, 82, 'What does the speaker ask the listener to do?', 'Send an e-mail', 'Meet at an office', 'Confirm a schedule', 'Look up an account number', 'A', 'Đáp án A là chính xác. Người nói yêu cầu người nghe gửi một email. Cô ấy nói: "Would you please send me an e-mail with the meal vouchers included as an attachment as soon as you can?" (Bạn có thể gửi cho tôi một email với phiếu ăn được đính kèm càng sớm càng tốt không?)
Dịch câu hỏi: Người nói yêu cầu người nghe làm gì?
Dịch các đáp án:
A. Gửi một email
B. Gặp tại một văn phòng
C. Xác nhận một lịch trình
D. Tìm kiếm một số tài khoản');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1573, 74, '2023/test1/audio/test1_question_83_85.mp3', NULL, 'M-Au This is the end of our tour. Thank you for coming to the Oakton Garden Collective. I hope you''ve learned a lot about urban gardening. Feel free to spend more time looking around. Don''t forget to pick up your free vegetable seedling before you leave. You can choose a cucumber plant or a tomato plant. Also, if you''d like to have your own garden plot next spring, applications are now available. You''ll get a plot for just a small fee. We have many other fun activities listed in our monthly newsletter. Consider joining our e-mail list to receive these monthly updates about upcoming events.', 'M-Nam: Đây là phần kết thúc của chuyến tham quan của chúng ta. Cảm ơn các bạn đã đến với Tập thể Vườn Oakton. Tôi hy vọng các bạn đã học được nhiều về làm vườn đô thị. Hãy tự nhiên dành thêm thời gian để nhìn xung quanh. Đừng quên lấy cây giống rau miễn phí của bạn trước khi bạn rời đi. Bạn có thể chọn một cây dưa chuột hoặc một cây cà chua. Ngoài ra, nếu bạn muốn có mảnh vườn riêng của mình vào mùa xuân năm sau, đơn đăng ký hiện đã có sẵn. Bạn sẽ nhận được một mảnh đất với một khoản phí nhỏ. Chúng tôi có nhiều hoạt động thú vị khác được liệt kê trong bản tin hàng tháng của chúng tôi. Hãy cân nhắc tham gia danh sách email của chúng tôi để nhận những cập nhật hàng tháng này về các sự kiện sắp tới.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2083, 1573, 83, 'What does the speaker remind the listeners to do?', 'Keep a gate closed', 'Return equipment to a shed', 'Check a list of supplies', 'Select a free gift', 'D', 'Đáp án D là chính xác. Người nói nhắc nhở người nghe chọn một món quà miễn phí. Cụ thể, anh ta nói: "Don''t forget to pick up your free vegetable seedling before you leave. You can choose a cucumber plant or a tomato plant." (Đừng quên lấy cây giống rau miễn phí của bạn trước khi bạn rời đi. Bạn có thể chọn một cây dưa chuột hoặc một cây cà chua.)
Dịch câu hỏi: Người nói nhắc nhở người nghe làm gì?
Dịch các đáp án:
A. Giữ cổng đóng
B. Trả thiết bị vào nhà kho
C. Kiểm tra danh sách vật tư
D. Chọn một món quà miễn phí');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1574, 74, '2023/test1/audio/test1_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2084, 1574, 84, 'According to the speaker, what can the listeners apply for?', 'A garden plot', 'A volunteer opportunity', 'A gardening workshop', 'A farmers market table', 'A', 'Đáp án A là chính xác. Theo người nói, người nghe có thể đăng ký một mảnh vườn. Anh ta nói: "if you''d like to have your own garden plot next spring, applications are now available." (nếu bạn muốn có mảnh vườn riêng của mình vào mùa xuân năm sau, đơn đăng ký hiện đã có sẵn.)
Dịch câu hỏi: Theo người nói, người nghe có thể đăng ký cái gì?
Dịch các đáp án:
A. Một mảnh vườn
B. Một cơ hội tình nguyện
C. Một hội thảo làm vườn
D. Một gian hàng chợ nông sản');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1575, 74, '2023/test1/audio/test1_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2085, 1575, 85, 'How can the listeners get information about future events?', 'By signing up for a newsletter', 'By joining a membership program', 'By looking at a Web site', 'By attending weekly meetings', 'A', 'Đáp án A là chính xác. Người nghe có thể nhận thông tin về các sự kiện trong tương lai bằng cách đăng ký nhận bản tin. Người nói gợi ý: "Consider joining our e-mail list to receive these monthly updates about upcoming events." (Hãy cân nhắc tham gia danh sách email của chúng tôi để nhận những cập nhật hàng tháng này về các sự kiện sắp tới.)
Dịch câu hỏi: Làm thế nào người nghe có thể nhận thông tin về các sự kiện trong tương lai?
Dịch các đáp án:
A. Bằng cách đăng ký nhận bản tin
B. Bằng cách tham gia chương trình thành viên
C. Bằng cách xem trang web
D. Bằng cách tham dự các cuộc họp hàng tuần');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1576, 74, '2023/test1/audio/test1_question_86_88.mp3', NULL, 'W-Br Have you developed the perfect product but are unsure how to reach more customers? At Whole Planet Marketing, our team of expert digital marketers is ready to help you reach your target audience. Unlike other marketing firms, we''ll connect you with a digital marketer who''ll work with you individually. During your one-on-one meetings, you''ll develop a marketing plan that will draw in customers. Just go to wholeplanetmarketing.com today to complete a brief questionnaire. Then, one of our specialists will contact you to make an appointment for a free proposal. Let Whole Planet Marketing bring customers to you!', 'W-Nữ: Bạn đã phát triển sản phẩm hoàn hảo nhưng không chắc chắn làm thế nào để tiếp cận nhiều khách hàng hơn? Tại Whole Planet Marketing, đội ngũ các chuyên gia tiếp thị kỹ thuật số của chúng tôi sẵn sàng giúp bạn tiếp cận đối tượng mục tiêu. Không giống như các công ty tiếp thị khác, chúng tôi sẽ kết nối bạn với một chuyên gia tiếp thị kỹ thuật số sẽ làm việc với bạn một cách cá nhân. Trong các cuộc họp một-đối-một của bạn, bạn sẽ phát triển một kế hoạch tiếp thị sẽ thu hút khách hàng. Chỉ cần truy cập wholeplanetmarketing.com ngay hôm nay để hoàn thành một bảng câu hỏi ngắn. Sau đó, một trong những chuyên gia của chúng tôi sẽ liên hệ với bạn để đặt lịch hẹn cho một đề xuất miễn phí. Hãy để Whole Planet Marketing mang khách hàng đến với bạn!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2086, 1576, 86, 'What service does the business offer?', 'Financial planning', 'Digital marketing', 'Real estate sales', 'International shipping', 'B', 'Đáp án B là chính xác. Doanh nghiệp cung cấp dịch vụ tiếp thị kỹ thuật số. Điều này được thể hiện rõ trong câu: "At Whole Planet Marketing, our team of expert digital marketers is ready to help you reach your target audience." (Tại Whole Planet Marketing, đội ngũ các chuyên gia tiếp thị kỹ thuật số của chúng tôi sẵn sàng giúp bạn tiếp cận đối tượng mục tiêu.)
Dịch câu hỏi: Doanh nghiệp cung cấp dịch vụ gì?
Dịch các đáp án:
A. Lập kế hoạch tài chính
B. Tiếp thị kỹ thuật số
C. Bán bất động sản
D. Vận chuyển quốc tế');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1577, 74, '2023/test1/audio/test1_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2087, 1577, 87, 'According to the speaker, how is the business different from its competitors?', 'It has several local offices.', 'It offers a money-back guarantee.', 'Its employees have industry certification.', 'Its employees work one-on-one with clients.', 'D', 'Đáp án D là chính xác. Theo người nói, doanh nghiệp khác biệt vì nhân viên của họ làm việc một-đối-một với khách hàng. Cô ấy nói: "Unlike other marketing firms, we''ll connect you with a digital marketer who''ll work with you individually." (Không giống như các công ty tiếp thị khác, chúng tôi sẽ kết nối bạn với một chuyên gia tiếp thị kỹ thuật số sẽ làm việc với bạn một cách cá nhân.)
Dịch câu hỏi: Theo người nói, doanh nghiệp khác biệt với đối thủ cạnh tranh như thế nào?
Dịch các đáp án:
A. Nó có nhiều văn phòng địa phương.
B. Nó cung cấp bảo đảm hoàn tiền.
C. Nhân viên của nó có chứng chỉ ngành.
D. Nhân viên của nó làm việc một-đối-một với khách hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1578, 74, '2023/test1/audio/test1_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2088, 1578, 88, 'How can the listeners make an appointment?', 'By sending an e-mail', 'By calling customer service', 'By filling out a questionnaire', 'By sending a text message', 'C', 'Đáp án C là chính xác. Người nghe có thể đặt lịch hẹn bằng cách điền vào một bảng câu hỏi. Người nói hướng dẫn: "Just go to wholeplanetmarketing.com today to complete a brief questionnaire. Then, one of our specialists will contact you to make an appointment for a free proposal." (Chỉ cần truy cập wholeplanetmarketing.com ngay hôm nay để hoàn thành một bảng câu hỏi ngắn. Sau đó, một trong những chuyên gia của chúng tôi sẽ liên hệ với bạn để đặt lịch hẹn cho một đề xuất miễn phí.)
Dịch câu hỏi: Làm thế nào người nghe có thể đặt lịch hẹn?
Dịch các đáp án:
A. Bằng cách gửi email
B. Bằng cách gọi dịch vụ khách hàng
C. Bằng cách điền vào một bảng câu hỏi
D. Bằng cách gửi tin nhắn văn bản');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1579, 74, '2023/test1/audio/test1_question_89_91.mp3', NULL, 'M-Au Hello, everyone. There''s very exciting news for all of us here at the Ziegler Research Institute. We''ve just been awarded the Sugiyama Grant to support our research into aquatic ecosystems. We can now invest in state-of-the-art equipment to study the biodiversity of coral reefs. As you may know, the Sugiyama Foundation offers a variety of substantial grants each year. It''s notable, though, that for this particular award, they received over 200 applications. Our work at the reefs will probably not begin for several months. We still need to order the equipment. But I want to thank you for your efforts on the application.', 'M-Nam: Xin chào mọi người. Có tin rất thú vị cho tất cả chúng ta ở đây tại Viện Nghiên cứu Ziegler. Chúng ta vừa được trao Khoản tài trợ Sugiyama để hỗ trợ nghiên cứu của chúng ta về hệ sinh thái dưới nước. Bây giờ chúng ta có thể đầu tư vào thiết bị hiện đại để nghiên cứu đa dạng sinh học của các rạn san hô. Như các bạn có thể biết, Quỹ Sugiyama cung cấp nhiều khoản tài trợ đáng kể mỗi năm. Đáng chú ý là, đối với giải thưởng cụ thể này, họ đã nhận được hơn 200 đơn đăng ký. Công việc của chúng ta tại các rạn san hô có thể sẽ không bắt đầu trong vài tháng tới. Chúng ta vẫn cần đặt hàng thiết bị. Nhưng tôi muốn cảm ơn các bạn vì những nỗ lực của các bạn trong việc nộp đơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2089, 1579, 89, 'Who most likely are the listeners?', 'Marine biologists', 'Museum directors', 'Rare-book librarians', 'Agricultural engineers', 'A', 'Đáp án A là chính xác. Người nghe có khả năng là các nhà sinh vật học biển. Điều này được suy ra từ nội dung bài phát biểu về nghiên cứu hệ sinh thái dưới nước và đa dạng sinh học của các rạn san hô.
Dịch câu hỏi: Người nghe có khả năng là ai?
Dịch các đáp án:
A. Các nhà sinh vật học biển
B. Các giám đốc bảo tàng
C. Các thủ thư sách quý hiếm
D. Các kỹ sư nông nghiệp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1580, 74, '2023/test1/audio/test1_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2090, 1580, 90, 'What does the speaker mean when he says, "they received over 200 applications"?', 'An opportunity is unlikely to occur.', 'An award is impressive.', 'A decision will take longer than usual.', 'A competitor has been very successful.', 'B', 'Đáp án B là chính xác. Khi người nói đề cập đến việc họ nhận được hơn 200 đơn đăng ký, ý của anh ta là giải thưởng này rất ấn tượng. Điều này ngụ ý rằng có nhiều ứng viên cạnh tranh cho giải thưởng, làm cho việc giành được nó trở nên đáng kể hơn.
Dịch câu hỏi: Người nói có ý gì khi anh ta nói "họ nhận được hơn 200 đơn đăng ký"?
Dịch các đáp án:
A. Một cơ hội khó có thể xảy ra.
B. Một giải thưởng ấn tượng.
C. Một quyết định sẽ mất nhiều thời gian hơn bình thường.
D. Một đối thủ cạnh tranh đã rất thành công.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1581, 74, '2023/test1/audio/test1_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2091, 1581, 91, 'Why does the speaker say that work cannot begin right away?', 'Additional funds are needed.', 'Some special training is required.', 'An application has to be approved.', 'Some equipment needs to be ordered.', 'D', 'Đáp án D là chính xác. Người nói nói rằng công việc không thể bắt đầu ngay lập tức vì cần phải đặt hàng một số thiết bị. Anh ta nói: "Our work at the reefs will probably not begin for several months. We still need to order the equipment." (Công việc của chúng ta tại các rạn san hô có thể sẽ không bắt đầu trong vài tháng tới. Chúng ta vẫn cần đặt hàng thiết bị.)
Dịch câu hỏi: Tại sao người nói nói rằng công việc không thể bắt đầu ngay lập tức?
Dịch các đáp án:
A. Cần thêm kinh phí.
B. Cần một số đào tạo đặc biệt.
C. Một đơn đăng ký phải được phê duyệt.
D. Cần phải đặt hàng một số thiết bị.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1582, 74, '2023/test1/audio/test1_question_92_94.mp3', NULL, 'W-Am On behalf of Onetech Solar, I''d like to welcome you to our manufacturing facility and congratulate you on your employment here. I''m Yuri Yamakawa, and today I''ll be leading this orientation for new hires. We''ll start with a video that provides an overview of the production process for the solar panels we make. Then we''ll tour the various areas of the factory, including the assembly line and the quality-control inspection center. After lunch, my colleague Mariko Hara will join you. I have a consultation with a client. And now, let''s get started with the video.', 'W-Nữ: Thay mặt Onetech Solar, tôi xin chào mừng các bạn đến với cơ sở sản xuất của chúng tôi và chúc mừng các bạn về việc làm của mình tại đây. Tôi là Yuri Yamakawa, và hôm nay tôi sẽ hướng dẫn buổi định hướng này cho những nhân viên mới. Chúng ta sẽ bắt đầu với một video cung cấp tổng quan về quy trình sản xuất các tấm pin mặt trời mà chúng tôi làm. Sau đó, chúng ta sẽ tham quan các khu vực khác nhau của nhà máy, bao gồm dây chuyền lắp ráp và trung tâm kiểm tra kiểm soát chất lượng. Sau bữa trưa, đồng nghiệp của tôi là Mariko Hara sẽ tham gia cùng các bạn. Tôi có một cuộc tư vấn với khách hàng. Và bây giờ, hãy bắt đầu với video.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2092, 1582, 92, 'What is the purpose of the talk?', 'To recognize outstanding achievements', 'To introduce new products to the public', 'To announce a manager''s retirement', 'To provide new employees with information', 'D', 'Đáp án D là chính xác. Mục đích của bài nói là để cung cấp thông tin cho nhân viên mới. Người nói nói rõ: "today I''ll be leading this orientation for new hires" (hôm nay tôi sẽ hướng dẫn buổi định hướng này cho những nhân viên mới).
Dịch câu hỏi: Mục đích của bài nói là gì?
Dịch các đáp án:
A. Để ghi nhận những thành tích nổi bật
B. Để giới thiệu sản phẩm mới ra công chúng
C. Để thông báo về việc nghỉ hưu của một quản lý
D. Để cung cấp thông tin cho nhân viên mới');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1583, 74, '2023/test1/audio/test1_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2093, 1583, 93, 'Where is the talk taking place?', 'At a banquet hall', 'At a government building', 'At a factory', 'At a construction site', 'C', 'Đáp án C là chính xác. Bài nói đang diễn ra tại một nhà máy. Người nói chào mừng người nghe đến "our manufacturing facility" (cơ sở sản xuất của chúng tôi) và đề cập đến việc tham quan "various areas of the factory" (các khu vực khác nhau của nhà máy).
Dịch câu hỏi: Bài nói đang diễn ra ở đâu?
Dịch các đáp án:
A. Tại một phòng tiệc
B. Tại một tòa nhà chính phủ
C. Tại một nhà máy
D. Tại một công trường xây dựng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1584, 74, '2023/test1/audio/test1_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2094, 1584, 94, 'What does the speaker mean when she says, "I have a consultation with a client"?', 'She needs to reschedule a meeting.', 'She will not be with the listeners in the afternoon.', 'A customer has just placed a large order.', 'A marketing campaign will begin soon.', 'B', 'Đáp án B là chính xác. Khi người nói nói "I have a consultation with a client", cô ấy có ý là cô ấy sẽ không ở cùng người nghe vào buổi chiều. Điều này được ngụ ý từ việc cô ấy nói rằng đồng nghiệp của cô ấy sẽ tham gia với người nghe sau bữa trưa.
Dịch câu hỏi: Người nói có ý gì khi cô ấy nói "Tôi có một cuộc tư vấn với khách hàng"?
Dịch các đáp án:
A. Cô ấy cần sắp xếp lại một cuộc họp.
B. Cô ấy sẽ không ở cùng người nghe vào buổi chiều.
C. Một khách hàng vừa đặt một đơn hàng lớn.
D. Một chiến dịch tiếp thị sẽ sớm bắt đầu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1585, 74, '2023/test1/audio/test1_question_95_97.mp3', '2023/test1/image/test1-p4-image-95.jpg', 'M-Cn Hi. This is Vinod Singh. I was in your store on Monday looking at refrigerators for my apartment. One of your employees showed me what you have in stock. I''ve decided to go with the extra-large refrigerator-the one with the stainless-steel finish, because it''ll match the other appliances in my apartment. Oh, also, is there an additional charge for delivering outside of the downtown area? Please call me at 555-0130 so we can finalize the details.', 'M-Nam: Xin chào. Đây là Vinod Singh. Tôi đã đến cửa hàng của bạn vào thứ Hai để xem tủ lạnh cho căn hộ của tôi. Một trong những nhân viên của bạn đã cho tôi xem những gì bạn có trong kho. Tôi đã quyết định chọn tủ lạnh cỡ lớn đặc biệt - cái có lớp hoàn thiện bằng thép không gỉ, vì nó sẽ phù hợp với các thiết bị khác trong căn hộ của tôi. Ồ, ngoài ra, có phụ phí nào cho việc giao hàng ngoài khu vực trung tâm thành phố không? Vui lòng gọi cho tôi theo số 555-0130 để chúng ta có thể hoàn tất các chi tiết.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2095, 1585, 95, 'What is the main purpose of the call?', 'To place an order', 'To dispute a charge', 'To arrange a meeting', 'To check a store''s inventory', 'A', 'Đáp án A là chính xác. Mục đích chính của cuộc gọi là để đặt hàng. Người gọi đã quyết định chọn một tủ lạnh cụ thể và đang hỏi về chi phí giao hàng, cho thấy anh ta đang trong quá trình đặt hàng.
Dịch câu hỏi: Mục đích chính của cuộc gọi là gì?
Dịch các đáp án:
A. Để đặt hàng
B. Để tranh cãi về một khoản phí
C. Để sắp xếp một cuộc gặp
D. Để kiểm tra hàng tồn kho của cửa hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1586, 74, '2023/test1/audio/test1_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2096, 1586, 96, 'Look at the graphic. Which model does the speaker prefer?', 'SG-200', 'SG-250', 'XG-300', 'XG-350', 'D', 'Đáp án D là chính xác. Theo hình ảnh và thông tin từ cuộc gọi, người nói ưa thích mẫu XG-350. Đây là mẫu duy nhất có cả tính năng cỡ lớn đặc biệt (Extra Large) và lớp hoàn thiện bằng thép không gỉ (Stainless Steel), phù hợp với mô tả của người gọi.
Dịch câu hỏi: Nhìn vào hình ảnh. Mẫu nào người nói ưa thích?
Dịch các đáp án:
A. SG-200
B. SG-250
C. XG-300
D. XG-350');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1587, 74, '2023/test1/audio/test1_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2097, 1587, 97, 'What does the speaker ask about?', 'A warranty', 'A return process', 'A delivery fee', 'Product availability', 'C', 'Đáp án C là chính xác. Người nói hỏi về phí giao hàng. Cụ thể, anh ta hỏi: "is there an additional charge for delivering outside of the downtown area?" (có phụ phí nào cho việc giao hàng ngoài khu vực trung tâm thành phố không?)
Dịch câu hỏi: Người nói hỏi về điều gì?
Dịch các đáp án:
A. Một bảo hành
B. Một quy trình trả lại
C. Một khoản phí giao hàng
D. Tình trạng có sẵn của sản phẩm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1588, 74, '2023/test1/audio/test1_question_98_100.mp3', '2023/test1/image/test1-p4-image-98.jpg', 'W-Am Good afternoon, everyone. I''d like to go over the product tests for our laptop-computer backpack, because they will require some design changes. As you know, we hired a marketing firm to test the prototype you designed among consumers. Now, we received very positive feedback overall. Consumers liked the separate computer compartment. However, many people felt that the shoulder straps were uncomfortable when the bag was full. It''s important that the backpack have comfortable shoulder straps, since its purpose is to carry heavy equipment. We need to revise the design as quickly as possible, since we''re scheduled to have our official product release early next year.', 'W-Nữ: Chào buổi chiều mọi người. Tôi muốn xem xét lại các bài kiểm tra sản phẩm cho ba lô máy tính xách tay của chúng ta, vì chúng sẽ yêu cầu một số thay đổi trong thiết kế. Như các bạn đã biết, chúng tôi đã thuê một công ty tiếp thị để kiểm tra nguyên mẫu mà các bạn đã thiết kế giữa người tiêu dùng. Bây giờ, chúng tôi đã nhận được phản hồi tích cực tổng thể. Người tiêu dùng thích ngăn chứa máy tính riêng biệt. Tuy nhiên, nhiều người cảm thấy rằng dây đeo vai không thoải mái khi túi đầy. Điều quan trọng là ba lô phải có dây đeo vai thoải mái, vì mục đích của nó là để mang thiết bị nặng. Chúng ta cần sửa đổi thiết kế càng nhanh càng tốt, vì chúng ta đã lên lịch ra mắt sản phẩm chính thức vào đầu năm sau.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2098, 1588, 98, 'Who most likely are the listeners?', 'Marketing experts', 'Product testers', 'Product designers', 'Audio engineers', 'C', 'Đáp án C là chính xác. Người nghe có khả năng là các nhà thiết kế sản phẩm. Điều này được suy ra từ câu: "As you know, we hired a marketing firm to test the prototype you designed among consumers" (Như các bạn đã biết, chúng tôi đã thuê một công ty tiếp thị để kiểm tra nguyên mẫu mà các bạn đã thiết kế giữa người tiêu dùng).
Dịch câu hỏi: Người nghe có khả năng là ai?
Dịch các đáp án:
A. Các chuyên gia tiếp thị
B. Người kiểm tra sản phẩm
C. Nhà thiết kế sản phẩm
D. Kỹ sư âm thanh');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1589, 74, '2023/test1/audio/test1_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2099, 1589, 99, 'Look at the graphic. What was the approval rating of the feature that will be improved?', '40 percent', '50 percent', '60 percent', '80 percent', 'B', 'Đáp án A là chính xác. Theo hình ảnh, tính năng cần được cải thiện là dây đeo vai (Shoulder Straps), và nó có mức đánh giá chấp thuận là 50%.
Dịch câu hỏi: Nhìn vào hình ảnh. Tỷ lệ chấp thuận của tính năng sẽ được cải thiện là bao nhiêu?
Dịch các đáp án:
A. 40 phần trăm
B. 50 phần trăm
C. 60 phần trăm
D. 80 phần trăm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1590, 74, '2023/test1/audio/test1_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2100, 1590, 100, 'According to the speaker, why is a revision urgent?', 'A competitor is making a similar product.', 'A product will be offered for sale soon.', 'A product will be introduced at a trade show.', 'The cost of a product''s materials will rise soon.', 'B', 'Đáp án B là chính xác. Theo người nói, việc sửa đổi là cấp bách vì sản phẩm sẽ sớm được bán ra. Cụ thể, cô ấy nói: "We need to revise the design as quickly as possible, since we''re scheduled to have our official product release early next year." (Chúng ta cần sửa đổi thiết kế càng nhanh càng tốt, vì chúng ta đã lên lịch ra mắt sản phẩm chính thức vào đầu năm sau.)
Dịch câu hỏi: Theo người nói, tại sao việc sửa đổi lại cấp bách?
Dịch các đáp án:
A. Một đối thủ cạnh tranh đang làm một sản phẩm tương tự.
B. Một sản phẩm sẽ sớm được bán ra.
C. Một sản phẩm sẽ được giới thiệu tại một hội chợ thương mại.
D. Chi phí vật liệu của một sản phẩm sẽ sớm tăng lên.');;

-- Data for 2023 Test1 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1591, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2101, 1591, 101, 'When she held her last meeting, Ms. Toba ---- her sales staff to perform even better next quarter.', 'encourage', 'is encouraging', 'encouraged', 'was encouraged', 'C', 'Đáp án C (encouraged) là đúng. Đây là câu điều kiện loại 2 với mệnh đề thời gian trong quá khứ. Cấu trúc: "When + S + V-ed, S + V-ed". Khi mệnh đề chính "When she held her last meeting" ở quá khứ đơn, động từ trong mệnh đề chính cũng phải ở quá khứ đơn để diễn tả hành động xảy ra đồng thời hoặc ngay sau đó. Do đó, "encouraged" là dạng quá khứ đơn phù hợp.
Dịch câu hỏi: Khi cô ấy tổ chức cuộc họp cuối cùng, cô Toba ---- nhân viên bán hàng của mình thực hiện tốt hơn nữa trong quý tới.
Dịch đáp án:
A. encourage (động từ nguyên thể)
B. is encouraging (động từ hiện tại tiếp diễn)
C. encouraged (động từ quá khứ đơn)
D. was encouraged (động từ quá khứ bị động)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1592, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2102, 1592, 102, 'All staff have been informed ------ the proposed partnership with ERI Finance.', 'for', 'about', 'to', 'at', 'B', 'Đáp án B (about) là đúng. Đây là cấu trúc cố định "inform somebody about something" (thông báo cho ai đó về điều gì). Sau động từ "inform" ở dạng bị động, ta dùng giới từ "about" để giới thiệu chủ đề của thông tin. Các giới từ khác không phù hợp trong ngữ cảnh này.
Dịch câu hỏi: Tất cả nhân viên đã được thông báo ------ về đề xuất hợp tác với ERI Finance.
Dịch đáp án:
A. for (giới từ)
B. about (giới từ)
C. to (giới từ)
D. at (giới từ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1593, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2103, 1593, 103, 'On Friday, Mr. Nakamura will discuss ------ideas for supporting busy waiters.', 'his', 'him', 'himself', 'he', 'A', 'Đáp án A (his) là đúng. Đây là vị trí cần một tính từ sở hữu (possessive adjective) để chỉ quyền sở hữu của ý tưởng. Cấu trúc: "possessive adjective + noun". "His" là tính từ sở hữu cho ngôi thứ ba số ít nam giới, phù hợp với "Mr. Nakamura". Các đáp án khác không phải là tính từ sở hữu.
Dịch câu hỏi: Vào thứ Sáu, ông Nakamura sẽ thảo luận ------ ý tưởng để hỗ trợ các nhân viên phục vụ bận rộn.
Dịch đáp án:
A. his (tính từ sở hữu)
B. him (đại từ tân ngữ)
C. himself (đại từ phản thân)
D. he (đại từ chủ ngữ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1594, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2104, 1594, 104, 'The Forestry Commission was created to ----- the state''s natural resources and wildlife.', 'allow', 'manage', 'succeed', 'finish', 'B', 'Đáp án B (manage) là đúng. Câu này sử dụng cấu trúc "be created to + V" (được tạo ra để làm gì), trong đó V là một động từ nguyên thể thể hiện mục đích. "Manage" (quản lý) phù hợp nhất với vai trò của Ủy ban Lâm nghiệp trong việc chăm sóc tài nguyên thiên nhiên và động vật hoang dã.
Dịch câu hỏi: Ủy ban Lâm nghiệp được thành lập để -- tài nguyên thiên nhiên và động vật hoang dã của tiểu bang.
Dịch đáp án:
A. allow (động từ: cho phép)
B. manage (động từ: quản lý)
C. succeed (động từ: thành công)
D. finish (động từ: hoàn thành)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1595, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2105, 1595, 105, 'By following established guidelines, construction workers will be able to complete their tasks ------.', 'safety', 'safe', 'safeness', 'safely', 'D', 'Đáp án D (safely) là đúng. Câu này cần một trạng từ (adverb) để mô tả cách thức hoàn thành công việc. Trạng từ thường được tạo ra bằng cách thêm "-ly" vào tính từ. Cấu trúc: "verb + adverb". "Safely" là trạng từ chỉ cách thức, có nghĩa là "một cách an toàn".
Dịch câu hỏi: Bằng cách tuân theo các hướng dẫn đã được thiết lập, công nhân xây dựng sẽ có thể hoàn thành nhiệm vụ của họ -----.
Dịch đáp án:
A. safety (danh từ: sự an toàn)
B. safe (tính từ: an toàn)
C. safeness (danh từ: tính an toàn)
D. safely (trạng từ: một cách an toàn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1596, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2106, 1596, 106, 'With her numerous credentials, Dr. Kwan is highly ----- to teach medieval history at Maston University.', 'arranged', 'ready', 'available', 'qualified', 'D', 'Đáp án D (qualified) là đúng. Câu này sử dụng cấu trúc "be + adverb + adjective" để mô tả khả năng của một người. "Qualified" (có đủ khả năng) là tính từ phù hợp nhất để diễn tả một người có đủ điều kiện cho một công việc, đặc biệt khi đi kèm với "highly" (rất).
Dịch câu hỏi: Với nhiều bằng cấp của mình, Tiến sĩ Kwan rất -- để giảng dạy lịch sử trung cổ tại Đại học Maston.
Dịch đáp án:
A. arranged (động từ quá khứ: sắp xếp)
B. ready (tính từ: sẵn sàng)
C. available (tính từ: có sẵn)
D. qualified (tính từ: đủ điều kiện)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1597, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2107, 1597, 107, '------ at the annual technology conference is mandatory for all engineers at the Treemont Corporation.', 'Attendance', 'Attend', 'Attends', 'Attended', 'A', 'Đáp án A (Attendance) là đúng. Câu này cần một danh từ làm chủ ngữ. Cấu trúc: "Noun + is + adjective". "Attendance" (sự tham dự) là danh từ, phù hợp làm chủ ngữ của câu. Các đáp án khác là các dạng của động từ "attend" không phù hợp làm chủ ngữ.
Dịch câu hỏi: ------ tại hội nghị công nghệ hàng năm là bắt buộc đối với tất cả kỹ sư tại Tập đoàn Treemont.
Dịch đáp án:
A. Attendance (danh từ: sự tham dự)
B. Attend (động từ nguyên thể: tham dự)
C. Attends (động từ ngôi thứ 3 số ít: tham dự)
D. Attended (động từ quá khứ: đã tham dự)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1598, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2108, 1598, 108, 'The café --- features poets, folk singers, and drama groups on its stage.', 'tightly', 'occasionally', 'vaguely', 'realistically', 'B', 'Đáp án B (occasionally) là đúng. Câu này cần một trạng từ tần suất (adverb of frequency) để mô tả mức độ thường xuyên của hành động. "Occasionally" (thỉnh thoảng) phù hợp nhất với ngữ cảnh về việc tổ chức các buổi biểu diễn không thường xuyên. Vị trí của trạng từ tần suất thường là trước động từ chính (features).
Dịch câu hỏi: Quán cà phê --- giới thiệu các nhà thơ, ca sĩ dân ca và các nhóm kịch trên sân khấu của mình.
Dịch đáp án:
A. tightly (trạng từ: chặt chẽ)
B. occasionally (trạng từ: thỉnh thoảng)
C. vaguely (trạng từ: mơ hồ)
D. realistically (trạng từ: thực tế)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1599, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2109, 1599, 109, 'Before the seminar began, attendees were assured ----- all scheduled presenters would appear.', 'who', 'around', 'that', 'therefore', 'C', 'Đáp án C (that) là đúng. Đây là cấu trúc "assure somebody that + clause" (đảm bảo với ai đó rằng). Sau động từ "assure" ở dạng bị động, chúng ta cần một mệnh đề bổ sung (noun clause) được giới thiệu bởi liên từ "that". "That" đóng vai trò liên từ kết nối mệnh đề chính với mệnh đề phụ.
Dịch câu hỏi: Trước khi hội thảo bắt đầu, những người tham dự được đảm bảo ----- tất cả các diễn giả đã lên lịch sẽ xuất hiện.
Dịch đáp án:
A. who (đại từ quan hệ: người mà)
B. around (giới từ/trạng từ: xung quanh)
C. that (liên từ: rằng)
D. therefore (trạng từ: do đó)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1600, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2110, 1600, 110, 'Forever Pet has been a leader in bringing new products, ----- Fun Bone and Chew Right, to the market.', 'however', 'furthermore', 'as if', 'such as', 'D', 'Đáp án D (such as) là đúng. Cấu trúc "such as + examples" được sử dụng để đưa ra ví dụ cụ thể. Trong câu này, "Fun Bone" và "Chew Right" là ví dụ về các sản phẩm mới của Forever Pet. "Such as" đóng vai trò giới thiệu các ví dụ cụ thể cho khái niệm chung được đề cập trước đó (new products).
Dịch câu hỏi: Forever Pet đã là nhà lãnh đạo trong việc đưa các sản phẩm mới, ----- Fun Bone và Chew Right, ra thị trường.
Dịch đáp án:
A. however (liên từ: tuy nhiên)
B. furthermore (trạng từ: hơn nữa)
C. as if (cụm liên từ: như thể)
D. such as (cụm từ: chẳng hạn như)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1601, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2111, 1601, 111, 'Ms. Turner is in charge of ---- the organization of records in the human services department.', 'improve', 'improved', 'improving', 'improvement', 'C', 'Đáp án C (improving) là đúng. Đây là cấu trúc "be in charge of + V-ing" (phụ trách việc gì đó). Sau giới từ "of", chúng ta cần một danh động từ (gerund). "Improving" là dạng V-ing của động từ "improve", phù hợp với cấu trúc ngữ pháp này và diễn tả hành động đang diễn ra.
Dịch câu hỏi: Cô Turner phụ trách ---- tổ chức hồ sơ trong phòng dịch vụ nhân sự.
Dịch đáp án:
A. improve (động từ nguyên thể: cải thiện)
B. improved (động từ quá khứ/tính từ: đã cải thiện)
C. improving (danh động từ: việc cải thiện)
D. improvement (danh từ: sự cải thiện)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1602, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2112, 1602, 112, 'Sheefon Bank clients always receive an e-mail or text --- following any change to their account password.', 'issue', 'alert', 'claim', 'member', 'B', 'Đáp án B (alert) là đúng. Câu này cần một danh từ để chỉ loại thông báo mà khách hàng nhận được. "Alert" (cảnh báo, thông báo) phù hợp nhất với ngữ cảnh về việc thông báo thay đổi mật khẩu. Cấu trúc: "receive + noun" (nhận được cái gì).
Dịch câu hỏi: Khách hàng của Ngân hàng Sheefon luôn nhận được một email hoặc tin nhắn --- sau bất kỳ thay đổi nào đối với mật khẩu tài khoản của họ.
Dịch đáp án:
A. issue (danh từ: vấn đề)
B. alert (danh từ: cảnh báo)
C. claim (danh từ: yêu cầu)
D. member (danh từ: thành viên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1603, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2113, 1603, 113, 'A drop in consumer demand has led to a ---- decrease in the production of large pickup trucks.', 'remark', 'remarked', 'remarking', 'remarkable', 'D', 'Đáp án D (remarkable) là đúng. Câu này cần một tính từ (adjective) để mô tả danh từ "decrease". Cấu trúc: "adjective + noun". "Remarkable" (đáng kể, đáng chú ý) là tính từ phù hợp để mô tả mức độ giảm sút lớn. Các đáp án khác không phải là tính từ hoặc không phù hợp về nghĩa.
Dịch câu hỏi: Sự sụt giảm trong nhu cầu của người tiêu dùng đã dẫn đến sự giảm ---- trong sản xuất xe bán tải cỡ lớn.
Dịch đáp án:
A. remark (danh từ: nhận xét)
B. remarked (động từ quá khứ: đã nhận xét)
C. remarking (danh động từ: việc nhận xét)
D. remarkable (tính từ: đáng kể, đáng chú ý)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1604, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2114, 1604, 114, 'After coating the potatoes in flour and spices, chefs should place them ----- into the deep fryer.', 'rarely', 'honestly', 'doubtfully', 'directly', 'D', 'Đáp án D (directly) là đúng. Câu này cần một trạng từ (adverb) để mô tả cách thức thực hiện hành động. Cấu trúc: "verb + adverb". "Directly" (trực tiếp, ngay lập tức) phù hợp nhất với quy trình nấu ăn được mô tả, chỉ ra rằng hành động nên được thực hiện ngay sau bước trước đó.
Dịch câu hỏi: Sau khi phủ khoai tây trong bột và gia vị, các đầu bếp nên đặt chúng --_- vào chảo chiên sâu.
Dịch đáp án:
A. rarely (trạng từ: hiếm khi)
B. honestly (trạng từ: thành thực)
C. doubtfully (trạng từ: nghi ngờ)
D. directly (trạng từ: trực tiếp, ngay lập tức)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1605, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2115, 1605, 115, 'Several banks have released applications that allow ------ customers to pay bills easily by phone.', 'their', 'they', 'them', 'themselves', 'A', 'Đáp án A (their) là đúng. Câu này cần một tính từ sở hữu (possessive adjective) để chỉ quyền sở hữu của khách hàng đối với các ngân hàng. Cấu trúc: "possessive adjective + noun". "Their" là tính từ sở hữu phù hợp cho danh từ số nhiều "customers".
Dịch câu hỏi: Một số ngân hàng đã phát hành các ứng dụng cho phép ------ khách hàng thanh toán hóa đơn dễ dàng qua điện thoại.
Dịch đáp án:
A. their (tính từ sở hữu: của họ)
B. they (đại từ chủ ngữ: họ)
C. them (đại từ tân ngữ: họ)
D. themselves (đại từ phản thân: bản thân họ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1606, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2116, 1606, 116, 'The personnel department will ------ only those applicants who have five or more years of experience for the position.', 'participate', 'consider', 'grant', 'make', 'B', 'Đáp án B (consider) là đúng. Câu này cần một động từ chỉ hành động xem xét hoặc đánh giá ứng viên. "Consider" (xem xét, cân nhắc) phù hợp nhất với ngữ cảnh về quá trình tuyển dụng. Cấu trúc: "will + verb" (thì tương lai đơn).
Dịch câu hỏi: Phòng nhân sự sẽ ------ chỉ những ứng viên có từ năm năm kinh nghiệm trở lên cho vị trí này.
Dịch đáp án:
A. participate (động từ: tham gia)
B. consider (động từ: xem xét, cân nhắc)
C. grant (động từ: cấp, cho phép)
D. make (động từ: làm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1607, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2117, 1607, 117, 'Employees of Belfore Electronics Ltd. are ----- involved in community-assistance programs.', 'active', 'actively', 'activate', 'activity', 'B', 'Đáp án B (actively) là đúng. Câu này cần một trạng từ (adverb) để mô tả cách thức nhân viên tham gia vào các chương trình. Cấu trúc: "be + adverb + past participle". "Actively" (tích cực) là trạng từ phù hợp để mô tả mức độ tham gia.
Dịch câu hỏi: Nhân viên của Belfore Electronics Ltd. __--- tham gia vào các chương trình hỗ trợ cộng đồng.
Dịch đáp án:
A. active (tính từ: tích cực)
B. actively (trạng từ: tích cực)
C. activate (động từ: kích hoạt)
D. activity (danh từ: hoạt động)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1608, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2118, 1608, 118, 'The executives at Macalter Equipment decided they would not ----- the contract without major changes.', 'renew', 'consume', 'identify', 'resemble', 'A', 'Đáp án A (renew) là đúng. Câu này cần một động từ liên quan đến việc tiếp tục hoặc gia hạn hợp đồng. "Renew" (gia hạn, làm mới) phù hợp nhất với ngữ cảnh về hợp đồng. Cấu trúc: "would not + verb" (thì tương lai trong quá khứ, dạng phủ định).
Dịch câu hỏi: Các giám đốc điều hành tại Macalter Equipment quyết định họ sẽ không ----- hợp đồng mà không có những thay đổi lớn.
Dịch đáp án:
A. renew (động từ: gia hạn, làm mới)
B. consume (động từ: tiêu thụ)
C. identify (động từ: nhận diện)
D. resemble (động từ: giống)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1609, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2119, 1609, 119, 'Wet suits are made with a --- layer of rubber that traps heat and keeps divers warm.', 'protect', 'protects', 'protective', 'protectively', 'C', 'Đáp án C (protective) là đúng. Câu này cần một tính từ (adjective) để mô tả danh từ "layer". Cấu trúc: "adjective + noun". "Protective" (bảo vệ) là tính từ phù hợp để mô tả chức năng của lớp cao su.
Dịch câu hỏi: Bộ đồ lặn được làm với một lớp cao su --- giữ nhiệt và giữ ấm cho thợ lặn.
Dịch đáp án:
A. protect (động từ: bảo vệ)
B. protects (động từ, ngôi thứ ba số ít: bảo vệ)
C. protective (tính từ: bảo vệ)
D. protectively (trạng từ: một cách bảo vệ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1610, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2120, 1610, 120, 'Newcamp Services managers will meet to discuss the proposed --- of three smaller branches into one large branch.', 'security', 'bracket', 'connector', 'merger', 'D', 'Đáp án D (merger) là đúng. Câu này cần một danh từ chỉ hành động hợp nhất hoặc sáp nhập. "Merger" (sự sáp nhập) phù hợp nhất với ngữ cảnh về việc kết hợp các chi nhánh nhỏ thành một chi nhánh lớn.
Dịch câu hỏi: Các quản lý của Newcamp Services sẽ họp để thảo luận về đề xuất --- ba chi nhánh nhỏ hơn thành một chi nhánh lớn.
Dịch đáp án:
A. security (danh từ: an ninh)
B. bracket (danh từ: dấu ngoặc)
C. connector (danh từ: đầu nối)
D. merger (danh từ: sự sáp nhập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1611, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2121, 1611, 121, 'At Yarzen Technology, clients'' records are ----- and can only be accessed by a small group of fund managers.', 'confide', 'confidential', 'confidentially', 'confidentiality', 'B', 'Đáp án B (confidential) là đúng. Câu này cần một tính từ (adjective) để mô tả tính chất của hồ sơ khách hàng. Cấu trúc: "be + adjective". "Confidential" (bảo mật, kín đáo) phù hợp nhất để mô tả tính chất của hồ sơ chỉ được truy cập bởi một nhóm nhỏ.
Dịch câu hỏi: Tại Yarzen Technology, hồ sơ của khách hàng là - và chỉ có thể được truy cập bởi một nhóm nhỏ các nhà quản lý quỹ.
Dịch đáp án:
A. confide (động từ: tin tưởng)
B. confidential (tính từ: bảo mật, kín đáo)
C. confidentially (trạng từ: một cách bảo mật)
D. confidentiality (danh từ: tính bảo mật)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1612, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2122, 1612, 122, 'The featured panel at the NHJ Medical Conference will discuss recent ------- in online health-care services.', 'memories', 'varieties', 'trends', 'rehearsals', 'C', 'Đáp án C (trends) là đúng. Câu này cần một danh từ chỉ xu hướng hoặc sự phát triển mới. "Trends" (xu hướng) phù hợp nhất với ngữ cảnh về thảo luận các phát triển gần đây trong dịch vụ chăm sóc sức khỏe trực tuyến.
Dịch câu hỏi: Hội đồng chuyên gia tại Hội nghị Y tế NHJ sẽ thảo luận về những ------- gần đây trong các dịch vụ chăm sóc sức khỏe trực tuyến.
Dịch đáp án:
A. memories (danh từ: ký ức)
B. varieties (danh từ: sự đa dạng)
C. trends (danh từ: xu hướng)
D. rehearsals (danh từ: buổi diễn tập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1613, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2123, 1613, 123, 'All of Millville''s restaurants ------ several times a year by the city health department.', 'inspect', 'inspected', 'are inspecting', 'are inspected', 'D', 'Đáp án D (are inspected) là đúng. Câu này yêu cầu một động từ ở thể bị động, thì hiện tại đơn. Cấu trúc bị động: "be + past participle". "Are inspected" (được kiểm tra) phù hợp với ngữ cảnh về việc các nhà hàng được kiểm tra định kỳ bởi cơ quan y tế.
Dịch câu hỏi: Tất cả các nhà hàng ở Millville ------ nhiều lần trong năm bởi sở y tế thành phố.
Dịch đáp án:
A. inspect (động từ nguyên thể: kiểm tra)
B. inspected (động từ quá khứ: đã kiểm tra)
C. are inspecting (hiện tại tiếp diễn: đang kiểm tra)
D. are inspected (hiện tại đơn bị động: được kiểm tra)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1614, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2124, 1614, 124, 'Sweet Sunlight Bakery has steadily built a ----- base of customers with its delicious cookies and cakes.', 'brief', 'loyal', 'strict', 'careful', 'B', 'Đáp án B (loyal) là đúng. Câu này cần một tính từ (adjective) để mô tả đặc điểm của cơ sở khách hàng. "Loyal" (trung thành) phù hợp nhất với ngữ cảnh về việc xây dựng một cơ sở khách hàng ổn định dựa trên chất lượng sản phẩm.
Dịch câu hỏi: Tiệm bánh Sweet Sunlight đã dần dần xây dựng được một cơ sở khách hàng ----- với những chiếc bánh quy và bánh ngọt ngon lành của mình.
Dịch đáp án:
A. brief (tính từ: ngắn gọn)
B. loyal (tính từ: trung thành)
C. strict (tính từ: nghiêm ngặt)
D. careful (tính từ: cẩn thận)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1615, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2125, 1615, 125, 'According to financial analysts, ---- in medical technology companies are expected to increase in value.', 'invest', 'investing', 'invested', 'investments', 'D', 'Đáp án D (investments) là đúng. Câu này cần một danh từ làm chủ ngữ của câu. "Investments" (các khoản đầu tư) phù hợp nhất với ngữ cảnh về việc dự đoán giá trị tăng của các khoản đầu tư.
Dịch câu hỏi: Theo các nhà phân tích tài chính, ---- vào các công ty công nghệ y tế được dự đoán sẽ tăng giá trị.
Dịch đáp án:
A. invest (động từ nguyên thể: đầu tư)
B. investing (danh động từ: việc đầu tư)
C. invested (động từ quá khứ: đã đầu tư)
D. investments (danh từ số nhiều: các khoản đầu tư)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1616, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2126, 1616, 126, 'The city''s harbor is ---- to container ships and fishing vessels of all sizes.', 'accessible', 'formal', 'reasonable', 'likely', 'A', 'Đáp án A (accessible) là đúng. Câu này cần một tính từ (adjective) để mô tả đặc điểm của cảng. Cấu trúc: "be + adjective + to". "Accessible" (có thể tiếp cận được) phù hợp nhất với ngữ cảnh về khả năng tiếp nhận các loại tàu khác nhau.
Dịch câu hỏi: Cảng của thành phố ---- đối với tàu container và tàu đánh cá thuộc mọi kích cỡ.
Dịch đáp án:
A. accessible (tính từ: có thể tiếp cận được)
B. formal (tính từ: chính thức)
C. reasonable (tính từ: hợp lý)
D. likely (tính từ: có khả năng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1617, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2127, 1617, 127, 'Maya''s Dancewear expanded its advertising markets, and sales have ----- increased.', 'controlling', 'consequently', 'beneath', 'even though', 'B', 'Đáp án B (consequently) là đúng. Câu này cần một trạng từ (adverb) để chỉ mối quan hệ nhân quả giữa hai mệnh đề. "Consequently" (do đó, vì vậy) phù hợp nhất để liên kết việc mở rộng thị trường quảng cáo với sự tăng trưởng doanh số.
Dịch câu hỏi: Maya''s Dancewear đã mở rộng thị trường quảng cáo của mình, và doanh số đã ----- tăng lên.
Dịch đáp án:
A. controlling (động từ -ing: kiểm soát)
B. consequently (trạng từ: do đó, vì vậy)
C. beneath (giới từ: bên dưới)
D. even though (cụm liên từ: mặc dù)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1618, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2128, 1618, 128, 'Dobson Ice Cream will not introduce any new flavors ----- the customer survey results are analyzed.', 'around', 'until', 'despite', 'past', 'B', 'Đáp án B (until) là đúng. Câu này cần một liên từ thời gian để chỉ mốc thời điểm trong tương lai. Cấu trúc: "will not + verb + until + clause". "Until" (cho đến khi) phù hợp nhất để chỉ ra rằng hành động sẽ không xảy ra trước một điều kiện nhất định.
Dịch câu hỏi: Dobson Ice Cream sẽ không giới thiệu bất kỳ hương vị mới nào ----- kết quả khảo sát khách hàng được phân tích.
Dịch đáp án:
A. around (giới từ: xung quanh)
B. until (liên từ: cho đến khi)
C. despite (giới từ: mặc dù)
D. past (giới từ/tính từ: quá khứ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1619, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2129, 1619, 129, 'The renovated company gym —-- with free weights and exercise machines.', 'will equip', 'to equip', 'has been equipped', 'is equipping', 'C', 'Đáp án C (has been equipped) là đúng. Câu này yêu cầu một động từ ở thì hiện tại hoàn thành bị động để chỉ kết quả của một hành động đã hoàn thành. Cấu trúc: "have/has + been + past participle". "Has been equipped" (đã được trang bị) phù hợp nhất để mô tả trạng thái hiện tại của phòng tập sau khi được trang bị.
Dịch câu hỏi: Phòng tập thể dục của công ty sau khi được cải tạo —-- với tạ tự do và các máy tập thể dục.
Dịch đáp án:
A. will equip (tương lai đơn: sẽ trang bị)
B. to equip (động từ nguyên thể: để trang bị)
C. has been equipped (hiện tại hoàn thành bị động: đã được trang bị)
D. is equipping (hiện tại tiếp diễn: đang trang bị)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1620, 75, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2130, 1620, 130, '----- driving their cars, workers who travel to the town center should use the bus lines.', 'Because of', 'Instead of', 'Whenever', 'Although', 'B', 'Đáp án B (Instead of) là đúng. Câu này cần một cụm giới từ để chỉ sự thay thế hoặc lựa chọn thay thế. "Instead of" (thay vì) phù hợp nhất để đề xuất một phương án thay thế cho việc lái xe.
Dịch câu hỏi: ----- lái xe của họ, những công nhân đi đến trung tâm thành phố nên sử dụng các tuyến xe buýt.
Dịch đáp án:
A. Because of (cụm giới từ: bởi vì)
B. Instead of (cụm giới từ: thay vì)
C. Whenever (liên từ: bất cứ khi nào)
D. Although (liên từ: mặc dù)');;

-- Data for 2023 Test1 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1621, 76, NULL, NULL, 'Local Barbershop Wins State Competition
By Miranda Warren
MALENDA COUNTY (January 12) -Pat and Kenny''s Barbershop, 131...... at 3949 Grand Street, has been named the best barbershop in the state by the Barber and Hairdresser''s Coalition. The criteria for selection include reputation, affordability, professionalism, and accreditations. 132..... .
Founders and owners Kenneth Webber and Patrick Miller have been best friends since childhood. 133..... opened the shop 34 years ago. 134..... the shop retains its old-fashioned charm, the barbers have mastered the latest styles, not just the more traditional ones. People of all ages seeking a haircut or a new style should try Pat and Kenny''s Barbershop.', 'Tiệm cắt tóc địa phương giành giải thưởng của tiểu bang
Bởi Miranda Warren
QUẬN MALENDA (Ngày 12 tháng 1) - Tiệm cắt tóc Pat and Kenny, 131...... tại 3949 Đại lộ Grand, đã được Liên đoàn Thợ cắt tóc và Làm tóc bình chọn là tiệm cắt tóc tốt nhất trong tiểu bang. Tiêu chí lựa chọn bao gồm danh tiếng, giá cả phải chăng, tính chuyên nghiệp và chứng nhận. 132..... .
Những người sáng lập và chủ sở hữu Kenneth Webber và Patrick Miller đã là bạn thân từ thời thơ ấu. 133..... đã mở tiệm cách đây 34 năm. 134..... tiệm vẫn giữ được nét quyến rũ kiểu cũ, các thợ cắt tóc đã thành thạo các kiểu tóc mới nhất, không chỉ những kiểu truyền thống. Mọi người ở mọi lứa tuổi muốn cắt tóc hoặc tạo kiểu mới nên thử tiệm cắt tóc Pat and Kenny.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2131, 1621, 131, NULL, 'locate', 'located', 'locates', 'location', 'B', 'Đáp án đúng là B (located - động từ quá khứ phân từ). Giải thích: Cần một động từ ở dạng quá khứ phân từ để mô tả vị trí của tiệm cắt tóc. "Located at" là cụm từ phổ biến để chỉ địa chỉ.
A. locate (động từ): định vị
B. located (động từ quá khứ phân từ): được đặt tại
C. locates (động từ, ngôi thứ 3 số ít): định vị
D. location (danh từ): vị trí');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1622, 76, NULL, NULL, NULL, 'Tiệm cắt tóc địa phương giành giải thưởng của tiểu bang
Bởi Miranda Warren
QUẬN MALENDA (Ngày 12 tháng 1) - Tiệm cắt tóc Pat and Kenny, 131...... tại 3949 Đại lộ Grand, đã được Liên đoàn Thợ cắt tóc và Làm tóc bình chọn là tiệm cắt tóc tốt nhất trong tiểu bang. Tiêu chí lựa chọn bao gồm danh tiếng, giá cả phải chăng, tính chuyên nghiệp và chứng nhận. 132..... .
Những người sáng lập và chủ sở hữu Kenneth Webber và Patrick Miller đã là bạn thân từ thời thơ ấu. 133..... đã mở tiệm cách đây 34 năm. 134..... tiệm vẫn giữ được nét quyến rũ kiểu cũ, các thợ cắt tóc đã thành thạo các kiểu tóc mới nhất, không chỉ những kiểu truyền thống. Mọi người ở mọi lứa tuổi muốn cắt tóc hoặc tạo kiểu mới nên thử tiệm cắt tóc Pat and Kenny.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2132, 1622, 132, NULL, 'The results will be announced later this month.', 'We are proud to serve our community with excellence.', 'Pat and Kenny''s shop excelled in all four categories.', 'Please call in advance to schedule an appointment.', 'C', 'Đáp án đúng là C (Pat and Kenny''s shop excelled in all four categories). Giải thích: Câu này cần một thông tin liên quan đến tiêu chí đánh giá đã đề cập trước đó. Đáp án C phù hợp nhất vì nó nói về việc tiệm cắt tóc đạt xuất sắc trong tất cả bốn hạng mục.
A. The results will be announced later this month. (Kết quả sẽ được công bố vào cuối tháng này.)
B. We are proud to serve our community with excellence. (Chúng tôi tự hào phục vụ cộng đồng của mình một cách xuất sắc.)
C. Pat and Kenny''s shop excelled in all four categories. (Tiệm của Pat và Kenny đạt xuất sắc trong cả bốn hạng mục.)
D. Please call in advance to schedule an appointment. (Vui lòng gọi trước để đặt lịch hẹn.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1623, 76, NULL, NULL, NULL, 'Tiệm cắt tóc địa phương giành giải thưởng của tiểu bang
Bởi Miranda Warren
QUẬN MALENDA (Ngày 12 tháng 1) - Tiệm cắt tóc Pat and Kenny, 131...... tại 3949 Đại lộ Grand, đã được Liên đoàn Thợ cắt tóc và Làm tóc bình chọn là tiệm cắt tóc tốt nhất trong tiểu bang. Tiêu chí lựa chọn bao gồm danh tiếng, giá cả phải chăng, tính chuyên nghiệp và chứng nhận. 132..... .
Những người sáng lập và chủ sở hữu Kenneth Webber và Patrick Miller đã là bạn thân từ thời thơ ấu. 133..... đã mở tiệm cách đây 34 năm. 134..... tiệm vẫn giữ được nét quyến rũ kiểu cũ, các thợ cắt tóc đã thành thạo các kiểu tóc mới nhất, không chỉ những kiểu truyền thống. Mọi người ở mọi lứa tuổi muốn cắt tóc hoặc tạo kiểu mới nên thử tiệm cắt tóc Pat and Kenny.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2133, 1623, 133, NULL, 'I', 'They', 'We', 'He', 'B', 'Đáp án đúng là B (They). Giải thích: Cần một đại từ số nhiều để chỉ Kenneth Webber và Patrick Miller. "They" (Họ) phù hợp nhất trong ngữ cảnh này.
A. I (Tôi)
B. They (Họ)
C. We (Chúng tôi)
D. He (Anh ấy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1624, 76, NULL, NULL, NULL, 'Tiệm cắt tóc địa phương giành giải thưởng của tiểu bang
Bởi Miranda Warren
QUẬN MALENDA (Ngày 12 tháng 1) - Tiệm cắt tóc Pat and Kenny, 131...... tại 3949 Đại lộ Grand, đã được Liên đoàn Thợ cắt tóc và Làm tóc bình chọn là tiệm cắt tóc tốt nhất trong tiểu bang. Tiêu chí lựa chọn bao gồm danh tiếng, giá cả phải chăng, tính chuyên nghiệp và chứng nhận. 132..... .
Những người sáng lập và chủ sở hữu Kenneth Webber và Patrick Miller đã là bạn thân từ thời thơ ấu. 133..... đã mở tiệm cách đây 34 năm. 134..... tiệm vẫn giữ được nét quyến rũ kiểu cũ, các thợ cắt tóc đã thành thạo các kiểu tóc mới nhất, không chỉ những kiểu truyền thống. Mọi người ở mọi lứa tuổi muốn cắt tóc hoặc tạo kiểu mới nên thử tiệm cắt tóc Pat and Kenny.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2134, 1624, 134, NULL, 'While', 'Despite', 'Even', 'Yet', 'A', 'Đáp án đúng là A (While). Giải thích: Cần một liên từ chỉ sự đối lập giữa phong cách cũ và kỹ năng mới. "While" (Trong khi) phù hợp nhất để diễn đạt ý này.
A. While (Trong khi)
B. Despite (Mặc dù)
C. Even (Thậm chí)
D. Yet (Tuy nhiên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1625, 76, NULL, NULL, 'Gasgo Propane Tank Exchange
You have chosen a safe and 135..... way to obtain fuel for your stoves, grills, heaters, fireplaces, or other devices. Simply follow the directions 136.....
When your tank runs out of propane, take it to our store and leave it on one of the clearly marked green shelves outside the store. 137..... Then, pay the cashier inside the store for a fresh tank of propane. Next, the cashier or another staff member will accompany you to the outdoor exchange
area. The staff person will give you a full tank to take home and provide help if you have multiple tanks to carry. Follow the instructions on the tank to connect it to your device. Be sure to visit us again when you need a 138.....', 'Trao đổi bình gas propane Gasgo
Bạn đã chọn một cách an toàn và 135..... để lấy nhiên liệu cho bếp, lò nướng, lò sưởi, lò sưởi, hoặc các thiết bị khác của bạn. Chỉ cần làm theo hướng dẫn 136.....
Khi bình của bạn hết gas propane, hãy mang nó đến cửa hàng của chúng tôi và để nó trên một trong những kệ xanh được đánh dấu rõ ràng bên ngoài cửa hàng. 137..... Sau đó, thanh toán cho thu ngân bên trong cửa hàng để lấy một bình propane mới. Tiếp theo, thu ngân hoặc một nhân viên khác sẽ đi cùng bạn đến khu vực trao đổi ngoài trời. Nhân viên sẽ đưa cho bạn một bình đầy để mang về nhà và giúp đỡ nếu bạn có nhiều bình cần mang. Làm theo hướng dẫn trên bình để kết nối nó với thiết bị của bạn. Hãy nhớ ghé thăm chúng tôi lần nữa khi bạn cần 138.....');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2135, 1625, 135, NULL, 'economy', 'economics', 'economize', 'economical', 'D', 'Đáp án đúng là D (economical - tính từ). Giải thích: Cần một tính từ mô tả cách thức lấy nhiên liệu. "Economical" (tiết kiệm) phù hợp nhất trong ngữ cảnh này.
A. economy (danh từ): nền kinh tế
B. economics (danh từ): kinh tế học
C. economize (động từ): tiết kiệm
D. economical (tính từ): tiết kiệm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2136, 1625, 136, NULL, 'below', 'finally', 'sometimes', 'hourly', 'A', 'Đáp án đúng là A (below). Giải thích: Cần một từ chỉ vị trí của hướng dẫn. "Below" (dưới đây) phù hợp nhất trong ngữ cảnh này.
A. below (trạng từ/giới từ): dưới đây
B. finally (trạng từ): cuối cùng
C. sometimes (trạng từ): đôi khi
D. hourly (trạng từ): hàng giờ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2137, 1625, 137, NULL, 'Come again very soon.', 'It is warmer in the store.', 'Do not take it inside.', 'The tank is prefilled.', 'C', 'Đáp án đúng là C (Do not take it inside). Giải thích: Cần một hướng dẫn liên quan đến việc để bình gas bên ngoài cửa hàng. "Do not take it inside" (Đừng mang nó vào trong) phù hợp nhất.
A. Come again very soon. (Hãy quay lại sớm.)
B. It is warmer in the store. (Bên trong cửa hàng ấm hơn.)
C. Do not take it inside. (Đừng mang nó vào trong.)
D. The tank is prefilled. (Bình đã được nạp sẵn.)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2138, 1625, 138, NULL, 'model', 'version', 'heater', 'replacement', 'D', 'Đáp án đúng là D (replacement). Giải thích: Cần một từ chỉ việc thay thế bình gas khi cần. "Replacement" (thay thế) phù hợp nhất trong ngữ cảnh này.
A. model (danh từ): mô hình
B. version (danh từ): phiên bản
C. heater (danh từ): lò sưởi
D. replacement (danh từ): thay thế');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1626, 76, NULL, NULL, 'To: Technicarn Enterprises Customers
From: Technicarn Enterprises Customer Service
Date: 10 September
Subject: Serving You
Dear Valued Customer:
We want your 139....... with Technicarn Enterprises to be easy and enjoyable. To that end, we are pleased to announce our newly designed Web site, with enhanced customer-friendly features. Our new Web site provides answers to your questions 24 hours a day, every day of the year. On our home page, you can get information about system setup, or you can troubleshoot by
visiting 140....... the Internet Issues or TV and Streaming Issues pages. 141......, you can find detailed information concerning account management, access, billing, and payment. 142..... . Please explore the new Web site at your earliest convenience: www.technicarnenterprises.com. As always, thank you for allowing us to serve you.
Best regards,
The Technicarn Enterprises Customer Service Team', 'Gửi: Khách hàng của Technicarn Enterprises
Từ: Dịch vụ Khách hàng Technicarn Enterprises
Ngày: 10 tháng 9
Chủ đề: Phục vụ Quý khách
Kính gửi Quý Khách hàng:
Chúng tôi muốn 139....... của bạn với Technicarn Enterprises trở nên dễ dàng và thú vị. Để đạt được điều đó, chúng tôi vui mừng thông báo về trang web mới được thiết kế của chúng tôi, với các tính năng thân thiện với khách hàng được nâng cao. Trang web mới của chúng tôi cung cấp câu trả lời cho các câu hỏi của bạn 24 giờ một ngày, mỗi ngày trong năm. Trên trang chủ của chúng tôi, bạn có thể nhận thông tin về cài đặt hệ thống, hoặc bạn có thể khắc phục sự cố bằng cách
truy cập 140....... trang Vấn đề Internet hoặc Vấn đề TV và Phát trực tuyến. 141......, bạn có thể tìm thấy thông tin chi tiết về quản lý tài khoản, truy cập, lập hóa đơn và thanh toán. 142..... . Vui lòng khám phá trang web mới khi có cơ hội: www.technicarnenterprises.com. Như mọi khi, cảm ơn bạn đã cho phép chúng tôi phục vụ bạn.
Trân trọng,
Nhóm Dịch vụ Khách hàng Technicarn Enterprises');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2139, 1626, 139, NULL, 'experience', 'experienced', 'experiencing', 'experiential', 'A', 'Đáp án đúng là A (experience - danh từ). Giải thích: Cần một danh từ để hoàn thành câu "We want your ... with Technicarn Enterprises to be easy and enjoyable". "Experience" (trải nghiệm) phù hợp nhất trong ngữ cảnh này.
A. experience (danh từ): trải nghiệm
B. experienced (tính từ): có kinh nghiệm
C. experiencing (động từ hiện tại phân từ): đang trải nghiệm
D. experiential (tính từ): thuộc về trải nghiệm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2140, 1626, 140, NULL, 'either', 'both', 'rather', 'each', 'A', 'Đáp án đúng là A (either). Giải thích: Cần một từ để chỉ sự lựa chọn giữa hai trang web. "Either" (một trong hai) phù hợp nhất trong ngữ cảnh này.
A. either (từ xác định): một trong hai
B. both (từ xác định): cả hai
C. rather (trạng từ): thay vào đó
D. each (từ xác định): mỗi');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2141, 1626, 141, NULL, 'Therefore', 'Regardless', 'For example', 'Moreover', 'D', 'Đáp án đúng là D (Moreover). Giải thích: Cần một liên từ để thêm thông tin. "Moreover" (Hơn nữa) phù hợp nhất để giới thiệu thông tin bổ sung.
A. Therefore (Vì vậy)
B. Regardless (Bất kể)
C. For example (Ví dụ)
D. Moreover (Hơn nữa)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2142, 1626, 142, NULL, 'We also need to inform you that your payment is five days past due.', 'We recommend that you purchase all related accessories in our retail store.', 'If you get an error message, disconnect from the Internet and try again.', 'If you cannot find what you need online, simply call our support number.', 'D', 'Đáp án đúng là D (If you cannot find what you need online, simply call our support number). Giải thích: Cần một câu liên quan đến việc hỗ trợ khách hàng. Đáp án D phù hợp nhất vì nó cung cấp một giải pháp thay thế khi không tìm thấy thông tin trên trang web.
A. We also need to inform you that your payment is five days past due. (Chúng tôi cũng cần thông báo rằng khoản thanh toán của bạn đã quá hạn năm ngày.)
B. We recommend that you purchase all related accessories in our retail store. (Chúng tôi khuyến nghị bạn mua tất cả các phụ kiện liên quan tại cửa hàng bán lẻ của chúng tôi.)
C. If you get an error message, disconnect from the Internet and try again. (Nếu bạn nhận được thông báo lỗi, hãy ngắt kết nối Internet và thử lại.)
D. If you cannot find what you need online, simply call our support number. (Nếu bạn không thể tìm thấy những gì bạn cần trực tuyến, chỉ cần gọi số hỗ trợ của chúng tôi.)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1627, 76, NULL, NULL, 'Garner City Transport Cares About the Environment
Beginning May 1, the sale and use of paper tickets and transit passes will be 143---- on all Garner City Transport bus and subway lines. This change applies to single-ride tickets 144....... to weekly and monthly passes. Eliminating paper benefits the environment and leads to less litter.
Riders can download the free Garner City Transport app. With the app, they can add money their accounts, purchase tickets, plan 145....... , and track arrival and departure times.
Alternatively, passengers can purchase a rechargeable transit card at any station. 146...... .Value can be added to the card via the Garner City Transport Web site at www.garnercitytransport.org.', 'Garner City Transport Quan tâm đến Môi trường
Bắt đầu từ ngày 1 tháng 5, việc bán và sử dụng vé giấy và thẻ đi lại sẽ bị 143---- trên tất cả các tuyến xe buýt và tàu điện ngầm của Garner City Transport. Thay đổi này áp dụng cho vé đi một lượt 144....... vé tuần và vé tháng. Việc loại bỏ giấy có lợi cho môi trường và dẫn đến ít rác thải hơn.
Người đi xe có thể tải ứng dụng Garner City Transport miễn phí. Với ứng dụng, họ có thể nạp tiền vào tài khoản, mua vé, lập kế hoạch 145....... , và theo dõi thời gian đến và đi.
Ngoài ra, hành khách có thể mua thẻ đi lại có thể nạp tiền tại bất kỳ trạm nào. 146...... .Có thể nạp tiền vào thẻ qua trang web của Garner City Transport tại www.garnercitytransport.org.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2143, 1627, 143, NULL, 'enlarged', 'discontinued', 'accessible', 'refreshed', 'B', 'Đáp án đúng là B (discontinued - động từ quá khứ phân từ). Giải thích: Cần một từ chỉ việc ngừng sử dụng vé giấy. "Discontinued" (ngừng) phù hợp nhất trong ngữ cảnh này.
A. enlarged (động từ quá khứ/tính từ): mở rộng
B. discontinued (động từ quá khứ phân từ): ngừng
C. accessible (tính từ): có thể tiếp cận
D. refreshed (động từ quá khứ/tính từ): làm mới');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2144, 1627, 144, NULL, 'sharing', 'but', 'except', 'as well as', 'D', 'Đáp án đúng là D (as well as - cụm từ). Giải thích: Cần một cụm từ để thêm thông tin về các loại vé bị ảnh hưởng. "As well as" (cũng như) phù hợp nhất để kết nối "single-ride tickets" với "weekly and monthly passes".
A. sharing (động từ): chia sẻ
B. but (liên từ): nhưng
C. except (giới từ): ngoại trừ
D. as well as (cụm từ): cũng như');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2145, 1627, 145, NULL, 'routes', 'responses', 'software', 'careers', 'A', 'Đáp án đúng là A (routes - danh từ). Giải thích: Cần một danh từ chỉ điều mà người dùng có thể lập kế hoạch trên ứng dụng. "Routes" (tuyến đường) phù hợp nhất trong ngữ cảnh giao thông công cộng.
A. routes (danh từ): tuyến đường
B. responses (danh từ): phản hồi
C. software (danh từ): phần mềm
D. careers (danh từ): sự nghiệp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2146, 1627, 146, NULL, 'People often use credit cards to purchase meals during the flight.', 'Many people like public transportation because it is inexpensive.', 'The durable cards are made from recycled materials.', 'There was a small price increase last month.', 'C', 'Đáp án đúng là C (The durable cards are made from recycled materials). Giải thích: Cần một câu bổ sung thông tin về thẻ đi lại. Đáp án C phù hợp nhất vì nó cung cấp thông tin về chất liệu của thẻ, liên quan đến chủ đề bảo vệ môi trường đã đề cập trước đó.
A. People often use credit cards to purchase meals during the flight. (Mọi người thường sử dụng thẻ tín dụng để mua bữa ăn trong chuyến bay.) - Không liên quan đến chủ đề.
B. Many people like public transportation because it is inexpensive. (Nhiều người thích giao thông công cộng vì nó rẻ.) - Không cung cấp thông tin mới về thẻ đi lại.
C. The durable cards are made from recycled materials. (Các thẻ bền được làm từ vật liệu tái chế.) - Phù hợp với chủ đề bảo vệ môi trường và cung cấp thông tin về thẻ.
D. There was a small price increase last month. (Đã có một sự tăng giá nhỏ vào tháng trước.) - Không liên quan trực tiếp đến thẻ đi lại hoặc chủ đề bảo vệ môi trường.;');;

-- Data for 2023 Test1 Part 7
