INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1644, 78, '2023/test2/audio/test2_question_2.mp3', '2023/test2/image/test2-image-2.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2202, 1644, 2, NULL, 'Plants are on top of a cart.', 'A watering can is next to some trees.', 'A man is digging in a garden.', 'A man is near a display of potted plants.', 'D', 'A: Cây cối đang ở trên đỉnh một xe đẩy.
B: Một chiếc xô tưới nước đang nằm cạnh vài cây.
C: Một người đàn ông đang đào trong khu vườn.
D: Một người đàn ông đang gần một trưng bày cây trong chậu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1645, 78, '2023/test2/audio/test2_question_3.mp3', '2023/test2/image/test2-image-3.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2203, 1645, 3, NULL, 'The man is fixing a machine.', 'The man is buying some equipment.', 'The man is lifting a weight.', 'The man is looking at the ceiling.', 'C', 'A: Người đàn ông đang sửa chữa một cỗ máy.
B: Người đàn ông đang mua một số thiết bị.
C: Người đàn ông đang nâng một trọng lượng.
D: Người đàn ông đang nhìn lên trần nhà.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1646, 78, '2023/test2/audio/test2_question_4.mp3', '2023/test2/image/test2-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2204, 1646, 4, NULL, 'A wall is decorated with various items.', 'Two chairs are blocking a doorway.', 'A door has been propped open with a statue.', 'A painting is hanging next to a window.', 'A', 'A: Một bức tường được trang trí với nhiều vật dụng khác nhau.
B: Hai chiếc ghế đang chặn một cửa đi.
C: Một cánh cửa đã được chống mở bằng một bức tượng.
D: Một bức tranh đang treo bên cạnh một cửa sổ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1647, 78, '2023/test2/audio/test2_question_5.mp3', '2023/test2/image/test2-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2205, 1647, 5, NULL, 'Some people are browsing in a shop.', 'Some people are exchanging gifts.', 'A customer is paying for some goods.', 'Some salespeople are preparing a display.', 'A', 'A: Một số người đang lướt qua trong cửa hàng.
B: Một số người đang trao đổi quà.
C: Một khách hàng đang thanh toán cho một số hàng hóa.
D: Một số nhân viên bán hàng đang chuẩn bị một trưng bày.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1648, 78, '2023/test2/audio/test2_question_6.mp3', '2023/test2/image/test2-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2206, 1648, 6, NULL, 'Cones are blocking access to a road.', 'Some soil is in a pile on the ground.', 'Some bushes have been planted in front of a building.', 'A tree is lying in the roadway.', 'B', 'A: Các nón đang chặn đường tiếp cận đến một con đường.
B: Một số đất đã được đổ thành đống trên mặt đất.
C: Một số bụi cây đã được trồng trước mặt một tòa nhà.
D: Một cây đang nằm trong đường giao thông.');;

