INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1649, 79, '2023/test2/audio/test2_question_7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2207, 1649, 7, 'Who''s responsible for hiring at our fitness center?', 'Mr. Gonzalez is going to get a membership.', 'I forgot to sign in at reception.', 'Mr. Lin and Ms. Weiss are.', NULL, 'C', 'Ai chịu trách nhiệm tuyển dụng tại trung tâm thể dục của chúng tôi?
A: Ông Gonzalez sẽ đăng ký thành viên.
B: Tôi đã quên ký tên tại lễ tân.
C: Ông Lin và bà Weiss là người.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1650, 79, '2023/test2/audio/test2_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2208, 1650, 8, 'Where do you usually purchase office supplies?', 'We put them in the hallway cabinets.', 'At the store on Maple Avenue.', 'A manager''s approval.', NULL, 'B', 'Bạn thường mua đồ dùng văn phòng ở đâu?
A: Chúng tôi đặt chúng trong các tủ hành lang.
B: Tại cửa hàng trên Đại lộ Maple.
C: Sự chấp thuận của quản lý.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1651, 79, '2023/test2/audio/test2_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2209, 1651, 9, 'What time does Mr. Park usually leave?', 'Around six o''clock in the evening.', 'He left everything we need.', 'We''ve had many interns over the years.', NULL, 'A', 'Ông Park thường rời đi lúc mấy giờ?
A: Khoảng sáu giờ chiều.
B: Anh ấy đã để lại mọi thứ chúng tôi cần.
C: Chúng tôi đã có nhiều thực tập sinh qua các năm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1652, 79, '2023/test2/audio/test2_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2210, 1652, 10, 'Do you want to present your research to the marketing team?', 'That''s what I''ve heard as well.', 'If we can find the time for it.', 'Yes, I received the gift.', NULL, 'B', 'Bạn có muốn trình bày nghiên cứu của mình với nhóm tiếp thị không?
A: Đó cũng là điều tôi đã nghe.
B: Nếu chúng ta có thể tìm thấy thời gian cho nó.
C: Vâng, tôi đã nhận được món quà.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1653, 79, '2023/test2/audio/test2_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2211, 1653, 11, 'Our company picnic is on Friday, isn''t it?', 'Those times are both booked.', 'Only if you can find them easily.', 'Right-in two days.', NULL, 'C', 'Buổi dã ngoại của công ty chúng tôi diễn ra vào thứ Sáu, phải không?
A: Những thời gian đó đều đã được đặt.
B: Chỉ khi bạn có thể tìm thấy chúng một cách dễ dàng.
C: Đúng rồi—trong hai ngày nữa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1654, 79, '2023/test2/audio/test2_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2212, 1654, 12, 'Isn''t the bus supposed to stop here?', 'Yes, according to the schedule.', 'I''m on my way now.', 'It listed several potential clients.', NULL, 'A', 'Xe buýt không phải dừng ở đây sao?
A: Vâng, theo lịch trình.
B: Tôi đang trên đường rồi.
C: Nó đã liệt kê một số khách hàng tiềm năng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1655, 79, '2023/test2/audio/test2_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2213, 1655, 13, 'We should fill this order quickly, shouldn''t we?', 'No, I haven''t yet.', 'Yes, it''s for an important client.', 'Try using this key.', NULL, 'B', 'Chúng ta nên nhanh chóng hoàn thành đơn hàng này, phải không?
A: Không, tôi chưa làm.
B: Vâng, nó dành cho một khách hàng quan trọng.
C: Hãy thử sử dụng chìa khóa này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1656, 79, '2023/test2/audio/test2_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2214, 1656, 14, 'How do you like your new job?', 'I can work from home quite often.', 'A career in electrical engineering.', 'My sister helped me apply.', NULL, 'A', 'Bạn thấy công việc mới của mình thế nào?
A: Tôi có thể làm việc tại nhà khá thường xuyên.
B: Một sự nghiệp trong kỹ thuật điện.
C: Chị gái tôi đã giúp tôi nộp đơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1657, 79, '2023/test2/audio/test2_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2215, 1657, 15, 'Let''s go to the cafeteria for lunch today.', 'There should be one in the filing cabinet.', 'Which local restaurant do you prefer?', 'I don''t think I can take a break.', NULL, 'C', 'Hôm nay chúng ta hãy đến căng tin để ăn trưa.
(A) Chắc sẽ có một cái trong tủ hồ sơ.
(B) Bạn thích nhà hàng địa phương nào hơn?
(C) Tôi không nghĩ mình có thể nghỉ ngơi .');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1658, 79, '2023/test2/audio/test2_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2216, 1658, 16, 'When will we hire the new interns?', 'Mr. Wyeth is handling that.', 'With more time to spare than usual.', 'The highest available salary.', NULL, 'A', 'Khi nào chúng ta sẽ tuyển dụng thực tập sinh mới?
A: Ông Wyeth đang xử lý việc đó.
B: Với nhiều thời gian rảnh hơn bình thường.
C: Mức lương cao nhất có thể.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1659, 79, '2023/test2/audio/test2_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2217, 1659, 17, 'How often should I mail these statements?', 'Yes, you can buy one online.', 'The post office on Grant Street.', 'We send them out once a month.', NULL, 'C', 'Tôi nên gửi những báo cáo này bao lâu một lần?
A: Vâng, bạn có thể mua một cái trực tuyến.
B: Bưu điện trên phố Grant.
C: Chúng tôi gửi chúng một lần mỗi tháng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1660, 79, '2023/test2/audio/test2_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2218, 1660, 18, 'Why did you put that food in the freezer?', 'It''s not working well currently.', 'I meant to put it in the refrigerator.', 'Let''s start making dinner soon.', NULL, 'B', 'Tại sao bạn lại để đồ ăn đó trong tủ đông?
A: Nó hiện tại không hoạt động tốt.
B: Tôi định để nó vào tủ lạnh.
C: Hãy bắt đầu nấu bữa tối sớm thôi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1661, 79, '2023/test2/audio/test2_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2219, 1661, 19, 'Could you print the agenda for the meeting?', 'It''s already on your desk.', 'No, the other printer.', 'Was that a client?', NULL, 'A', 'Bạn có thể in chương trình nghị sự cho cuộc họp không?
A: Nó đã có trên bàn của bạn.
B: Không, máy in khác.
C: Đó có phải là một khách hàng không?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1662, 79, '2023/test2/audio/test2_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2220, 1662, 20, 'How far are you from the clinic?', 'I''m close enough to walk.', 'I need to see the doctor.', 'It''s a well-known clinic.', NULL, 'A', 'Bạn cách phòng khám bao xa?
A: Tôi gần đủ để đi bộ.
B: Tôi cần gặp bác sĩ.
C: Nó là một phòng khám nổi tiếng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1663, 79, '2023/test2/audio/test2_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2221, 1663, 21, 'Didn''t you get a printout of the company newsletter from Emiko?', 'She started working here three years ago.', 'I was out of town last week.', 'Yes, I do like to write.', NULL, 'B', 'Bạn không nhận được bản in bản tin của công ty từ Emiko sao?
A: Cô ấy bắt đầu làm việc ở đây ba năm trước.
B: Tôi đã ra ngoài thành phố tuần trước.
C: Vâng, tôi thích viết.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1664, 79, '2023/test2/audio/test2_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2222, 1664, 22, 'When do you need to renew your passport?', 'Be careful not to lose your tickets.', 'A brand-new type of microchip.', 'Soon, because it''s about to expire.', NULL, 'C', 'Khi nào bạn cần gia hạn hộ chiếu?
A: Hãy cẩn thận không để mất vé của bạn.
B: Một loại vi mạch hoàn toàn mới.
C: Sớm thôi, vì nó sắp hết hạn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1665, 79, '2023/test2/audio/test2_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2223, 1665, 23, 'Who can help me find replacement parts for my computer?', 'Here are all the latest statements.', 'I can help you look through the inventory.', 'Put these on that shelf.', NULL, 'B', 'Ai có thể giúp tôi tìm linh kiện thay thế cho máy tính của tôi?
A: Đây là tất cả các bản kê khai mới nhất.
B: Tôi có thể giúp bạn xem qua hàng tồn kho.
C: Đặt những cái này lên kệ đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1666, 79, '2023/test2/audio/test2_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2224, 1666, 24, 'I can''t make it to the company dinner tonight.', 'Managers expect everyone to be there.', 'A buffet-style restaurant.', 'A meeting once a week.', NULL, 'A', 'Tôi không thể đến dự bữa tối của công ty tối nay.
(A) Các nhà quản lý mong đợi mọi người đều có mặt ở đó.
(B) Một nhà hàng kiểu tự chọn.
(C) Một cuộc họp mỗi tuần một lần.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1667, 79, '2023/test2/audio/test2_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2225, 1667, 25, 'Do you work in this neighborhood?', 'Yes, I''d like to.', 'No, my office isn''t nearby.', 'There aren''t any of those here.', NULL, 'B', 'Bạn có làm việc ở khu vực lân cận này không?
(A) Có, tôi muốn.
(B) Không, văn phòng của tôi không ở gần đây.
(C) Không có văn phòng nào như vậy ở đây.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1668, 79, '2023/test2/audio/test2_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2226, 1668, 26, 'It''s time for our quarterly earnings report, isn''t it?', 'Was there an e-mail reminder about it?', 'To pay for a new advertising campaign.', 'No, a different pair of earrings.', NULL, 'A', 'Đã đến lúc báo cáo thu nhập hàng quý của chúng ta, phải không?
A: Có email nhắc nhở về nó không?
B: Để trả tiền cho một chiến dịch quảng cáo mới.
C: Không, một đôi hoa tai khác.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1669, 79, '2023/test2/audio/test2_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2227, 1669, 27, 'What did you do with the guest list that I sent you?', 'After everyone received it.', 'I passed it along to everyone who needed it.', 'We''re supposed to leave soon.', NULL, 'B', 'Bạn đã làm gì với danh sách khách mời mà tôi gửi cho bạn?
A: Sau khi mọi người đã nhận được nó.
B: Tôi đã chuyển nó cho tất cả mọi người cần nó.
C: Chúng ta nên rời đi sớm thôi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1670, 79, '2023/test2/audio/test2_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2228, 1670, 28, 'Did you see the announcement about Emily''s promotion?', 'All the technology''s been upgraded.', 'Perhaps a good career counselor.', 'I''ve been busy all morning.', NULL, 'C', 'Bạn đã thấy thông báo về việc thăng chức của Emily chưa?
A: Tất cả công nghệ đã được nâng cấp.
B: Có lẽ một nhà tư vấn sự nghiệp tốt.
C: Tôi đã bận cả sáng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1671, 79, '2023/test2/audio/test2_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2229, 1671, 29, 'Let''s try our best to finish the project on time.', 'All except the first one.', 'We may need a few more days.', 'I think over time it will.', NULL, 'B', 'Chúng ta hãy cố gắng hết sức để hoàn thành dự án đúng hạn.
A: Tất cả trừ cái đầu tiên.
B: Chúng ta có thể cần thêm vài ngày nữa.
C: Tôi nghĩ theo thời gian nó sẽ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1672, 79, '2023/test2/audio/test2_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2230, 1672, 30, 'Where''s the store manager?', 'A recent hiring decision.', 'I enjoy shopping at that store.', 'She went out for lunch.', NULL, 'C', 'Người quản lý cửa hàng đâu rồi?
A: Một quyết định tuyển dụng gần đây.
B: Tôi thích mua sắm ở cửa hàng đó.
C: Cô ấy đã đi ăn trưa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1673, 79, '2023/test2/audio/test2_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2231, 1673, 31, 'The software you''re using isn''t very reliable.', 'These chairs aren''t very comfortable.', 'I''ve been using it for years with no problems.', 'I saw that computer at the store.', NULL, 'B', 'Phần mềm bạn đang sử dụng không đáng tin cậy lắm.
A: Những chiếc ghế này không rất thoải mái.
B: Tôi đã sử dụng nó trong nhiều năm mà không gặp vấn đề gì.
C: Tôi đã thấy chiếc máy tính đó ở cửa hàng.');;

-- Data for 2023 Test2 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1674, 80, '2023/test2/audio/test2_question_32_34.mp3', NULL, 'W-Am Hello, Forest Grove Photography Services. How can I help you?
M-Cn Hi, I''d like to get a photographer to cover our event. It''s a charity basketball game next Tuesday night. I was hoping to get Thomas Zukowski. He works for you, right?
W-Am Yes, but unfortunately, Thomas doesn''t usually work evenings.
M-Cn Oh, too bad. Could you recommend somebody else?
W-Am Before I do that, let me talk to him. He might make an exception. Tom does love basketball.', 'W-Nữ: Xin chào, Dịch vụ Nhiếp ảnh Forest Grove. Tôi có thể giúp gì cho bạn?
M-Nam: Chào, tôi muốn thuê một nhiếp ảnh gia để chụp sự kiện của chúng tôi. Đó là một trận đấu bóng rổ từ thiện vào tối thứ Ba tới. Tôi hy vọng có thể thuê Thomas Zukowski. Anh ấy làm việc cho bạn, phải không?
W-Nữ: Đúng vậy, nhưng đáng tiếc là Thomas thường không làm việc vào buổi tối.
M-Nam: Ồ, thật đáng tiếc. Bạn có thể giới thiệu ai khác không?
W-Nữ: Trước khi làm điều đó, để tôi nói chuyện với anh ấy. Anh ấy có thể sẽ làm ngoại lệ. Tom rất thích bóng rổ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2232, 1674, 32, 'Why is the man calling?', 'To rent a facility', 'To hire a photographer', 'To request a price list', 'To schedule a repair', 'B', 'Đáp án B là chính xác. Người đàn ông gọi điện để thuê một nhiếp ảnh gia. Anh ta nói: "I''d like to get a photographer to cover our event." (Tôi muốn thuê một nhiếp ảnh gia để chụp sự kiện của chúng tôi.)
Dịch câu hỏi: Tại sao người đàn ông gọi điện?
Dịch các đáp án:
A. Để thuê một cơ sở
B. Để thuê một nhiếp ảnh gia
C. Để yêu cầu một bảng giá
D. Để lên lịch sửa chữa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1675, 80, '2023/test2/audio/test2_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2233, 1675, 33, 'What problem does the woman mention?', 'Her employee does not have transportation.', 'Her service does not cover sports events.', 'The weather will be bad on Tuesday.', 'The time the man requested is too late.', 'D', 'Đáp án D là chính xác. Vấn đề mà người phụ nữ đề cập là thời gian người đàn ông yêu cầu quá muộn. Cô ấy nói: "Thomas doesn''t usually work evenings." (Thomas thường không làm việc vào buổi tối.)
Dịch câu hỏi: Vấn đề gì người phụ nữ đề cập đến?
Dịch các đáp án:
A. Nhân viên của cô ấy không có phương tiện đi lại.
B. Dịch vụ của cô ấy không bao gồm các sự kiện thể thao.
C. Thời tiết sẽ xấu vào thứ Ba.
D. Thời gian người đàn ông yêu cầu quá muộn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1676, 80, '2023/test2/audio/test2_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2234, 1676, 34, 'What does the woman say she will do?', 'Issue a refund', 'Cancel an order', 'Talk to an employee', 'E-mail her manager', 'C', 'Đáp án C là chính xác. Người phụ nữ nói rằng cô ấy sẽ nói chuyện với một nhân viên. Cụ thể, cô ấy nói: "Before I do that, let me talk to him." (Trước khi làm điều đó, để tôi nói chuyện với anh ấy.)
Dịch câu hỏi: Người phụ nữ nói cô ấy sẽ làm gì?
Dịch các đáp án:
A. Hoàn tiền
B. Hủy đơn hàng
C. Nói chuyện với một nhân viên
D. Gửi email cho quản lý của cô ấy');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1677, 80, '2023/test2/audio/test2_question_35_37.mp3', NULL, 'M-Cn Good morning. It looks like we received a lot of new orders online last night.
W-Br Yes, I saw that when I got in this morning. Can you package all of them by yourself?
M-Cn Well, there are so many, I may not be able to finish everything today.
W-Br OK. I''ll call Maria Jeong and ask if she can come in early today to help.
M-Cn That''d be great. We also have to pack that big shipment for the Henderson order. We finally got all of the items in.
W-Br Oh, yes, do that first.', 'M-Nam: Chào buổi sáng. Có vẻ như chúng ta đã nhận được rất nhiều đơn đặt hàng mới trực tuyến tối qua.
W-Nữ: Vâng, tôi đã thấy điều đó khi tôi đến sáng nay. Anh có thể đóng gói tất cả chúng một mình không?
M-Nam: Chà, có quá nhiều, tôi có thể không thể hoàn thành mọi thứ hôm nay.
W-Nữ: Được rồi. Tôi sẽ gọi cho Maria Jeong và hỏi xem cô ấy có thể đến sớm hôm nay để giúp đỡ không.
M-Nam: Tuyệt quá. Chúng ta cũng phải đóng gói lô hàng lớn cho đơn hàng Henderson. Cuối cùng chúng ta đã có đủ tất cả các mặt hàng.
W-Nữ: Ồ, vâng, hãy làm việc đó trước.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2235, 1677, 35, 'Where most likely are the speakers?', 'In a restaurant', 'In a school', 'In a warehouse', 'In a library', 'C', 'Đáp án C là chính xác. Những người nói có khả năng đang ở trong một nhà kho. Điều này được suy ra từ cuộc trò chuyện về việc đóng gói đơn hàng và chuẩn bị lô hàng lớn.
Dịch câu hỏi: Người nói có khả năng đang ở đâu nhất?
Dịch các đáp án:
A. Trong một nhà hàng
B. Trong một trường học
C. Trong một nhà kho
D. Trong một thư viện');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1678, 80, '2023/test2/audio/test2_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2236, 1678, 36, 'Why do the speakers mention Maria Jeong?', 'She placed a very large order.', 'She wants to replace a product.', 'She is unable to work today.', 'She may be able to help with a task.', 'D', 'Đáp án D là chính xác. Những người nói đề cập đến Maria Jeong vì cô ấy có thể giúp đỡ với một nhiệm vụ. Người phụ nữ nói: "I''ll call Maria Jeong and ask if she can come in early today to help." (Tôi sẽ gọi cho Maria Jeong và hỏi xem cô ấy có thể đến sớm hôm nay để giúp đỡ không.)
Dịch câu hỏi: Tại sao những người nói đề cập đến Maria Jeong?
Dịch các đáp án:
A. Cô ấy đã đặt một đơn hàng rất lớn.
B. Cô ấy muốn thay thế một sản phẩm.
C. Cô ấy không thể làm việc hôm nay.
D. Cô ấy có thể giúp đỡ với một nhiệm vụ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1679, 80, '2023/test2/audio/test2_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2237, 1679, 37, 'What will the man probably do next?', 'Pack an order', 'Call a colleague', 'Process a refund', 'Write to a customer', 'A', 'Đáp án A là chính xác. Người đàn ông có khả năng sẽ đóng gói một đơn hàng tiếp theo. Điều này được suy ra từ cuộc trò chuyện về việc đóng gói đơn hàng và từ câu nói cuối cùng của người phụ nữ: "Oh, yes, do that first." (Ồ, vâng, hãy làm việc đó trước.)
Dịch câu hỏi: Người đàn ông có khả năng sẽ làm gì tiếp theo?
Dịch các đáp án:
A. Đóng gói một đơn hàng
B. Gọi điện cho một đồng nghiệp
C. Xử lý hoàn tiền
D. Viết thư cho một khách hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1680, 80, '2023/test2/audio/test2_question_38_40.mp3', NULL, 'M-Au Haruna, we''ve planned most of the details for the corporate retreat, including housing and most activities, but we still need to decide where to go for Saturday''s closing dinner.
W-Am Yes, I sent you several menus. Did you like any of the places? McNally''s is close by.
M-Au Yes, that would be convenient. We could even walk there from the hotel. But the prices are a little high.
W-Am I agree. But I could see if they can offer us a reduced catering rate, rather than ordering off the regular menu.', 'M-Nam: Haruna, chúng ta đã lên kế hoạch cho hầu hết các chi tiết của kỳ nghỉ dưỡng công ty, bao gồm chỗ ở và hầu hết các hoạt động, nhưng chúng ta vẫn cần quyết định đi đâu cho bữa tối bế mạc vào thứ Bảy.
W-Nữ: Vâng, tôi đã gửi cho anh một vài thực đơn. Anh có thích bất kỳ địa điểm nào không? McNally''s ở gần đây.
M-Nam: Đúng vậy, điều đó sẽ thuận tiện. Chúng ta thậm chí có thể đi bộ đến đó từ khách sạn. Nhưng giá cả hơi cao.
W-Nữ: Tôi đồng ý. Nhưng tôi có thể xem liệu họ có thể cung cấp cho chúng ta một mức giá ăn uống giảm giá, thay vì đặt từ thực đơn thông thường.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2238, 1680, 38, 'What do the speakers need to choose?', 'An introductory activity for a retreat', 'A residential site for a retreat', 'Decorations for a party', 'A location for a dinner', 'D', 'Đáp án D là chính xác. Những người nói cần chọn một địa điểm cho bữa tối. Điều này được thể hiện rõ trong câu đầu tiên: "we still need to decide where to go for Saturday''s closing dinner." (chúng ta vẫn cần quyết định đi đâu cho bữa tối bế mạc vào thứ Bảy.)
Dịch câu hỏi: Những người nói cần chọn cái gì?
Dịch các đáp án:
A. Một hoạt động giới thiệu cho một kỳ nghỉ dưỡng
B. Một địa điểm lưu trú cho một kỳ nghỉ dưỡng
C. Trang trí cho một bữa tiệc
D. Một địa điểm cho một bữa tối');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1681, 80, '2023/test2/audio/test2_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2239, 1681, 39, 'What do the speakers like about McNally''s?', 'It is nearby.', 'It is open late.', 'It is highly recommended.', 'It has been remodeled.', 'A', 'Đáp án A là chính xác. Những người nói thích McNally''s vì nó ở gần. Người phụ nữ nói: "McNally''s is close by." (McNally''s ở gần đây.), và người đàn ông đồng ý: "Yes, that would be convenient. We could even walk there from the hotel." (Đúng vậy, điều đó sẽ thuận tiện. Chúng ta thậm chí có thể đi bộ đến đó từ khách sạn.)
Dịch câu hỏi: Những người nói thích điều gì về McNally''s?
Dịch các đáp án:
A. Nó ở gần đó.
B. Nó mở cửa muộn.
C. Nó được đánh giá cao.
D. Nó đã được cải tạo.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1682, 80, '2023/test2/audio/test2_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2240, 1682, 40, 'What does the woman offer to do?', 'See what the retreat attendees prefer', 'Find an alternative site', 'Discuss pricing options', 'Contact a hotel', 'C', 'Đáp án C là chính xác. Người phụ nữ đề nghị thảo luận các lựa chọn về giá cả. Cô ấy nói: "But I could see if they can offer us a reduced catering rate, rather than ordering off the regular menu." (Nhưng tôi có thể xem liệu họ có thể cung cấp cho chúng ta một mức giá ăn uống giảm giá, thay vì đặt từ thực đơn thông thường.)
Dịch câu hỏi: Người phụ nữ đề nghị làm gì?
Dịch các đáp án:
A. Xem những người tham dự kỳ nghỉ dưỡng thích gì
B. Tìm một địa điểm thay thế
C. Thảo luận các lựa chọn về giá cả
D. Liên hệ với một khách sạn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1683, 80, '2023/test2/audio/test2_question_41_43.mp3', NULL, 'W-Am Janelle and Rico, could you give me an update on how our new medical records software is coming?
W-Br Sure. Per the customer''s request, I''ve updated the logo and changed the font.
M-Cn The customer has communicated with us a lot on this project. Having their feedback at every stage of the process has been helpful.
W-Am Excellent. It sounds like we''re on schedule for completing our beta version. Then we can hand it off to our marketing team.', 'W-Nữ: Janelle và Rico, các bạn có thể cho tôi một cập nhật về tiến độ của phần mềm hồ sơ y tế mới của chúng ta không?
W-Nữ: Chắc chắn rồi. Theo yêu cầu của khách hàng, tôi đã cập nhật logo và thay đổi phông chữ.
M-Nam: Khách hàng đã liên lạc với chúng ta rất nhiều về dự án này. Việc có phản hồi của họ ở mọi giai đoạn của quá trình đã rất hữu ích.
W-Nữ: Tuyệt vời. Có vẻ như chúng ta đang đúng tiến độ để hoàn thành phiên bản beta. Sau đó chúng ta có thể chuyển nó cho đội tiếp thị của chúng ta.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2241, 1683, 41, 'What does the speakers'' company produce?', 'Computers', 'Software', 'Web sites', 'Medical equipment', 'B', 'Đáp án B là chính xác. Công ty của những người nói sản xuất phần mềm. Điều này được thể hiện rõ trong câu đầu tiên khi họ nói về "our new medical records software" (phần mềm hồ sơ y tế mới của chúng ta).
Dịch câu hỏi: Công ty của những người nói sản xuất cái gì?
Dịch các đáp án:
A. Máy tính
B. Phần mềm
C. Trang web
D. Thiết bị y tế');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1684, 80, '2023/test2/audio/test2_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2242, 1684, 42, 'What does the man say has been helpful?', 'Focus group data', 'An engineering consultant', 'A search engine', 'Customer feedback', 'D', 'Đáp án D là chính xác. Người đàn ông nói rằng phản hồi của khách hàng đã rất hữu ích. Cụ thể, anh ta nói: "Having their feedback at every stage of the process has been helpful." (Việc có phản hồi của họ ở mọi giai đoạn của quá trình đã rất hữu ích.)
Dịch câu hỏi: Người đàn ông nói điều gì đã hữu ích?
Dịch các đáp án:
A. Dữ liệu nhóm tập trung
B. Một tư vấn kỹ thuật
C. Một công cụ tìm kiếm
D. Phản hồi của khách hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1685, 80, '2023/test2/audio/test2_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2243, 1685, 43, 'What is the next step in the project that the speakers are discussing?', 'Giving a presentation to the client', 'Sending a product to another group in the company', 'Creating a schedule for the next phase of development', 'Determining the price of a product', 'B', 'Đáp án B là chính xác. Bước tiếp theo trong dự án mà những người nói đang thảo luận là gửi sản phẩm cho một nhóm khác trong công ty. Điều này được thể hiện trong câu cuối cùng: "Then we can hand it off to our marketing team." (Sau đó chúng ta có thể chuyển nó cho đội tiếp thị của chúng ta.)
Dịch câu hỏi: Bước tiếp theo trong dự án mà những người nói đang thảo luận là gì?
Dịch các đáp án:
A. Thuyết trình cho khách hàng
B. Gửi sản phẩm cho một nhóm khác trong công ty
C. Tạo lịch trình cho giai đoạn phát triển tiếp theo
D. Xác định giá của sản phẩm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1686, 80, '2023/test2/audio/test2_question_44_46.mp3', NULL, 'M-Co Hello, this is Ian Nelson from Regal Bathrooms. I''m following up to make sure that you''re pleased with the job our workers did in your house.
W-Am Thank you for calling. Yes. They did a great job. The bathroom floor was replaced, and the new tile looks great. I''m very happy with the job.
M-Cn That''s good to hear. If there are other jobs you need done, I hope you''ll reach out to us again.
W-Am That reminds me. I was thinking of replacing my kitchen cabinets. Is that something you''d possibly do?
M-Cn We don''t, but I can recommend a company I often work with. Their customers have been very satisfied. Let me get their phone number. One second.
W-Am Thanks.', 'M-Nam: Xin chào, đây là Ian Nelson từ Regal Bathrooms. Tôi đang theo dõi để đảm bảo rằng bạn hài lòng với công việc mà công nhân của chúng tôi đã làm trong nhà bạn.
W-Nữ: Cảm ơn anh đã gọi. Vâng. Họ đã làm rất tốt. Sàn phòng tắm đã được thay thế, và gạch mới trông rất đẹp. Tôi rất hài lòng với công việc.
M-Nam: Thật tốt khi nghe điều đó. Nếu có công việc khác bạn cần làm, tôi hy vọng bạn sẽ liên hệ lại với chúng tôi.
W-Nữ: Điều đó nhắc tôi nhớ. Tôi đang nghĩ đến việc thay thế tủ bếp của mình. Đó có phải là điều mà các anh có thể làm không?
M-Nam: Chúng tôi không làm, nhưng tôi có thể giới thiệu một công ty mà tôi thường xuyên làm việc cùng. Khách hàng của họ rất hài lòng. Để tôi lấy số điện thoại của họ. Một giây nhé.
W-Nữ: Cảm ơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2244, 1686, 44, 'What is the purpose of the phone call?', 'To help a customer choose a product', 'To check on a customer''s satisfaction', 'To inform a customer of a price estimate', 'To advertise a special offer', 'B', 'Đáp án B là chính xác. Mục đích của cuộc gọi điện thoại là để kiểm tra sự hài lòng của khách hàng. Điều này được thể hiện rõ trong câu đầu tiên: "I''m following up to make sure that you''re pleased with the job our workers did in your house." (Tôi đang theo dõi để đảm bảo rằng bạn hài lòng với công việc mà công nhân của chúng tôi đã làm trong nhà bạn.)
Dịch câu hỏi: Mục đích của cuộc gọi điện thoại là gì?
Dịch các đáp án:
A. Để giúp khách hàng chọn một sản phẩm
B. Để kiểm tra sự hài lòng của khách hàng
C. Để thông báo cho khách hàng về một ước tính giá
D. Để quảng cáo một ưu đãi đặc biệt');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1687, 80, '2023/test2/audio/test2_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2245, 1687, 45, 'What does the man say about replacing kitchen cabinets?', 'He guarantees his company will do a good job.', 'His company is too busy to do the work.', 'His company does not do that type of work.', 'He thinks it will be an expensive job.', 'C', 'Đáp án C là chính xác. Người đàn ông nói rằng công ty của anh ta không làm loại công việc đó (thay thế tủ bếp). Anh ta nói: "We don''t, but I can recommend a company I often work with." (Chúng tôi không làm, nhưng tôi có thể giới thiệu một công ty mà tôi thường xuyên làm việc cùng.)
Dịch câu hỏi: Người đàn ông nói gì về việc thay thế tủ bếp?
Dịch các đáp án:
A. Anh ta đảm bảo công ty của mình sẽ làm tốt công việc.
B. Công ty của anh ta quá bận rộn để làm công việc đó.
C. Công ty của anh ta không làm loại công việc đó.
D. Anh ta nghĩ rằng đó sẽ là một công việc đắt tiền.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1688, 80, '2023/test2/audio/test2_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2246, 1688, 46, 'What will the man most likely do next?', 'Send workers to the woman''s house', 'Find a telephone number for the woman', 'Check kitchen cabinet prices', 'Discuss a new product with some workers', 'B', 'Đáp án B là chính xác. Người đàn ông có khả năng sẽ tìm số điện thoại cho người phụ nữ tiếp theo. Anh ta nói: "Let me get their phone number. One second." (Để tôi lấy số điện thoại của họ. Một giây nhé.)
Dịch câu hỏi: Người đàn ông có khả năng sẽ làm gì tiếp theo?
Dịch các đáp án:
A. Gửi công nhân đến nhà người phụ nữ
B. Tìm số điện thoại cho người phụ nữ
C. Kiểm tra giá tủ bếp
D. Thảo luận về một sản phẩm mới với một số công nhân');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1689, 80, '2023/test2/audio/test2_question_47_49.mp3', NULL, 'W-Br My name is Laura. I refill my medication here at this pharmacy once a month. But on Monday I''m going to travel abroad for work for two months, and I wonder if I can get a two-month refill this time.
M-Cn It shouldn''t be a problem. However, your doctor must send us the two-month prescription, so you need to contact her first.
W-Br Oh, I see. I''ll give her a call during my lunch break today. When are you open until today?
M-Cn Until nine p.m. But once we receive your doctor''s prescription, we can deliver the medication directly to your home.', 'W-Nữ: Tên tôi là Laura. Tôi bổ sung thuốc của mình ở hiệu thuốc này một lần mỗi tháng. Nhưng vào thứ Hai tôi sẽ đi công tác nước ngoài trong hai tháng, và tôi tự hỏi liệu tôi có thể nhận được lượng thuốc bổ sung cho hai tháng lần này không.
M-Nam: Không nên có vấn đề gì. Tuy nhiên, bác sĩ của bạn phải gửi cho chúng tôi đơn thuốc cho hai tháng, vì vậy bạn cần liên hệ với cô ấy trước.
W-Nữ: Ồ, tôi hiểu rồi. Tôi sẽ gọi cho cô ấy trong giờ nghỉ trưa hôm nay. Hôm nay các anh mở cửa đến mấy giờ?
M-Nam: Đến 9 giờ tối. Nhưng một khi chúng tôi nhận được đơn thuốc từ bác sĩ của bạn, chúng tôi có thể giao thuốc trực tiếp đến nhà bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2247, 1689, 47, 'Where is the conversation taking place?', 'At a travel agency', 'At a pharmacy', 'At a mobile phone store', 'At a hotel', 'B', 'Đáp án B là chính xác. Cuộc trò chuyện đang diễn ra tại một hiệu thuốc. Điều này được thể hiện rõ khi người phụ nữ nói: "I refill my medication here at this pharmacy once a month." (Tôi bổ sung thuốc của mình ở hiệu thuốc này một lần mỗi tháng.)
Dịch câu hỏi: Cuộc trò chuyện đang diễn ra ở đâu?
Dịch các đáp án:
A. Tại một đại lý du lịch
B. Tại một hiệu thuốc
C. Tại một cửa hàng điện thoại di động
D. Tại một khách sạn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1690, 80, '2023/test2/audio/test2_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2248, 1690, 48, 'What does the woman say she will do at lunch today?', 'Go to the airport', 'Print out a ticket', 'Register for a giveaway', 'Call a doctor', 'D', 'Đáp án D là chính xác. Người phụ nữ nói rằng cô ấy sẽ gọi cho bác sĩ trong giờ nghỉ trưa hôm nay. Cô ấy nói: "I''ll give her a call during my lunch break today." (Tôi sẽ gọi cho cô ấy trong giờ nghỉ trưa hôm nay.)
Dịch câu hỏi: Người phụ nữ nói cô ấy sẽ làm gì vào bữa trưa hôm nay?
Dịch các đáp án:
A. Đi đến sân bay
B. In ra một vé
C. Đăng ký cho một chương trình tặng quà
D. Gọi cho bác sĩ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1691, 80, '2023/test2/audio/test2_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2249, 1691, 49, 'What does the man offer to do?', 'Arrange a delivery', 'Postpone an appointment', 'Check a discount rate', 'Download an application', 'A', 'Đáp án A là chính xác. Người đàn ông đề nghị sắp xếp việc giao hàng. Anh ta nói: "But once we receive your doctor''s prescription, we can deliver the medication directly to your home." (Nhưng một khi chúng tôi nhận được đơn thuốc từ bác sĩ của bạn, chúng tôi có thể giao thuốc trực tiếp đến nhà bạn.)
Dịch câu hỏi: Người đàn ông đề nghị làm gì?
Dịch các đáp án:
A. Sắp xếp việc giao hàng
B. Hoãn một cuộc hẹn
C. Kiểm tra tỷ lệ giảm giá
D. Tải xuống một ứng dụng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1692, 80, '2023/test2/audio/test2_question_50_52.mp3', NULL, 'M-Au Miller''s Sporting Goods. Joey speaking.
W-Am Hello, I''m calling from West End High School. We''re looking to make a big purchase for our student baseball teams. Our equipment is getting old, and we would like to get new uniforms too. We have budget restrictions, though.
M-Au Well, we do offer discounts for bulk purchases. And we have a number of price ranges for uniforms; many are very reasonable. Let me get the manager on the phone, and you can discuss the specifics.', 'M-Nam: Cửa hàng Đồ thể thao Miller. Joey xin nghe.
W-Nữ: Xin chào, tôi gọi từ Trường Trung học West End. Chúng tôi đang muốn mua một lô lớn cho các đội bóng chày học sinh của chúng tôi. Thiết bị của chúng tôi đang cũ đi, và chúng tôi cũng muốn có đồng phục mới. Tuy nhiên, chúng tôi có hạn chế về ngân sách.
M-Nam: Vâng, chúng tôi có cung cấp giảm giá cho mua số lượng lớn. Và chúng tôi có một số mức giá cho đồng phục; nhiều cái rất hợp lý. Để tôi gọi quản lý lên điện thoại, và bạn có thể thảo luận chi tiết.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2250, 1692, 50, 'Where does the woman work?', 'At a baseball stadium', 'At a fitness center', 'At a shipping warehouse', 'At a school', 'D', 'Đáp án D là chính xác. Người phụ nữ làm việc tại một trường học. Cô ấy nói: "I''m calling from West End High School." (Tôi gọi từ Trường Trung học West End.)
Dịch câu hỏi: Người phụ nữ làm việc ở đâu?
Dịch các đáp án:
A. Tại một sân vận động bóng chày
B. Tại một trung tâm thể dục
C. Tại một kho vận chuyển
D. Tại một trường học');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1693, 80, '2023/test2/audio/test2_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2251, 1693, 51, 'What is the woman concerned about?', 'A store''s closing time', 'Overall costs', 'When an order will be received', 'The color of some uniforms', 'B', 'Đáp án B là chính xác. Người phụ nữ lo lắng về tổng chi phí. Cô ấy đề cập đến "budget restrictions" (hạn chế về ngân sách), cho thấy mối quan tâm về chi phí tổng thể.
Dịch câu hỏi: Người phụ nữ lo lắng về điều gì?
Dịch các đáp án:
A. Giờ đóng cửa của cửa hàng
B. Tổng chi phí
C. Khi nào đơn hàng sẽ được nhận
D. Màu sắc của một số đồng phục');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1694, 80, '2023/test2/audio/test2_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2252, 1694, 52, 'What will the man do next?', 'Look up some prices', 'Package an order', 'Call a manager', 'Check the store''s inventory', 'C', 'Đáp án C là chính xác. Người đàn ông sẽ gọi cho quản lý tiếp theo. Anh ta nói: "Let me get the manager on the phone, and you can discuss the specifics." (Để tôi gọi quản lý lên điện thoại, và bạn có thể thảo luận chi tiết.)
Dịch câu hỏi: Người đàn ông sẽ làm gì tiếp theo?
Dịch các đáp án:
A. Tra cứu một số giá
B. Đóng gói một đơn hàng
C. Gọi cho quản lý
D. Kiểm tra hàng tồn kho của cửa hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1695, 80, '2023/test2/audio/test2_question_53_55.mp3', NULL, 'W-Br Hi, this is Gemini Flowers. I''m calling about the order you placed for your award luncheon on July twelfth. Unfortunately, our supplier is out of pink roses.
M-Cn Oh, no! Pink matches our corporate logo! I ordered them especially for this occasion!
W-Br I understand your disappointment, sir. I can offer a ten percent discount on the total cost of your order and replace the pink roses with yellow ones.
M-Cn Well, I didn''t tell anyone about the roses. I suppose no one will really be disappointed.', 'W-Nữ: Xin chào, đây là Gemini Flowers. Tôi gọi về đơn hàng bạn đã đặt cho bữa trưa trao giải vào ngày 12 tháng 7. Thật không may, nhà cung cấp của chúng tôi đã hết hoa hồng màu hồng.
M-Nam: Ồ, không! Màu hồng phù hợp với logo công ty của chúng tôi! Tôi đã đặt chúng đặc biệt cho dịp này!
W-Nữ: Tôi hiểu sự thất vọng của ông, thưa ông. Tôi có thể đề nghị giảm giá 10% trên tổng chi phí đơn hàng của ông và thay thế hoa hồng hồng bằng hoa hồng vàng.
M-Nam: Ừm, tôi đã không nói với ai về hoa hồng. Tôi nghĩ không ai sẽ thực sự thất vọng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2253, 1695, 53, 'What problem does the woman mention?', 'There is no time to create centerpieces.', 'The shop never received the man''s order.', 'A supplier cannot fulfill an order.', 'The wrong date is on the order form.', 'C', 'Đáp án C là chính xác. Người phụ nữ đề cập đến vấn đề là nhà cung cấp không thể thực hiện đơn hàng. Cô ấy nói: "Unfortunately, our supplier is out of pink roses." (Thật không may, nhà cung cấp của chúng tôi đã hết hoa hồng màu hồng.)
Dịch câu hỏi: Vấn đề gì người phụ nữ đề cập đến?
Dịch các đáp án:
A. Không có thời gian để tạo ra các bình hoa trung tâm.
B. Cửa hàng chưa bao giờ nhận được đơn đặt hàng của người đàn ông.
C. Một nhà cung cấp không thể thực hiện đơn hàng.
D. Ngày tháng sai trên mẫu đơn đặt hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1696, 80, '2023/test2/audio/test2_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2254, 1696, 54, 'What does the man say about his company''s logo?', 'It was designed many years ago.', 'It contains the color pink.', 'It won an award.', 'It features a drawing of flowers.', 'B', 'Đáp án B là chính xác. Người đàn ông nói rằng logo của công ty ông chứa màu hồng. Ông nói: "Pink matches our corporate logo!" (Màu hồng phù hợp với logo công ty của chúng tôi!)
Dịch câu hỏi: Người đàn ông nói gì về logo của công ty ông?
Dịch các đáp án:
A. Nó được thiết kế nhiều năm trước.
B. Nó chứa màu hồng.
C. Nó đã giành được một giải thưởng.
D. Nó có một bức vẽ hoa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1697, 80, '2023/test2/audio/test2_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2255, 1697, 55, 'What does the man mean when he says, "I suppose no one will really be disappointed"?', 'He will postpone the luncheon.', 'He will accept the woman''s offer.', 'He will find a replacement award.', 'He will modify the company''s logo.', 'B', 'Đáp án B là chính xác. Khi người đàn ông nói "I suppose no one will really be disappointed" (Tôi nghĩ không ai sẽ thực sự thất vọng), ý của ông là ông sẽ chấp nhận đề nghị của người phụ nữ. Ông đang ngụ ý rằng việc thay đổi màu hoa sẽ không gây ra vấn đề lớn.
Dịch câu hỏi: Người đàn ông có ý gì khi nói "Tôi nghĩ không ai sẽ thực sự thất vọng"?
Dịch các đáp án:
A. Ông sẽ hoãn bữa trưa.
B. Ông sẽ chấp nhận đề nghị của người phụ nữ.
C. Ông sẽ tìm một giải thưởng thay thế.
D. Ông sẽ sửa đổi logo của công ty.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1698, 80, '2023/test2/audio/test2_question_56_58.mp3', NULL, 'W-Br Unfortunately, our development team has some bad news. It turns out we''ll need to push back the shipment of the prototype motor we''ve been developing for our client.
M-Cn Uh-oh. Why will there be a delay?
W-Br Well, some of the components we received to build the prototype are failing initial tests, so we won''t be able to make the delivery deadline. Janet, could you let the client know?
W-Am Yes, I''ll contact them right away.
M-Cn And I''d like the development team to start giving me daily briefings about progress on this issue.', 'W-Nữ: Thật không may, đội phát triển của chúng ta có tin xấu. Hóa ra chúng ta sẽ cần phải lùi lại việc vận chuyển động cơ nguyên mẫu mà chúng ta đang phát triển cho khách hàng.
M-Nam: Ồ không. Tại sao sẽ có sự chậm trễ?
W-Nữ: Vâng, một số thành phần chúng ta nhận được để xây dựng nguyên mẫu đang thất bại trong các bài kiểm tra ban đầu, vì vậy chúng ta sẽ không thể đáp ứng thời hạn giao hàng. Janet, cô có thể thông báo cho khách hàng biết không?
W-Nữ: Vâng, tôi sẽ liên hệ với họ ngay lập tức.
M-Nam: Và tôi muốn đội phát triển bắt đầu cung cấp cho tôi các bản tóm tắt hàng ngày về tiến độ của vấn đề này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2256, 1698, 56, 'What kind of company do the speakers most likely work for?', 'Manufacturing', 'Financial', 'Publishing', 'Educational', 'A', 'Đáp án A là chính xác. Những người nói có khả năng làm việc cho một công ty sản xuất. Điều này được suy ra từ việc họ đang thảo luận về việc phát triển và vận chuyển một động cơ nguyên mẫu.
Dịch câu hỏi: Những người nói có khả năng làm việc cho loại công ty nào?
Dịch các đáp án:
A. Sản xuất
B. Tài chính
C. Xuất bản
D. Giáo dục');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1699, 80, '2023/test2/audio/test2_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2257, 1699, 57, 'What problem are the speakers discussing?', 'A pause while more funding is obtained', 'A delay in making a delivery', 'A need for the company to relocate', 'The loss of some experienced staff', 'B', 'Đáp án B là chính xác. Những người nói đang thảo luận về vấn đề chậm trễ trong việc giao hàng. Điều này được nêu rõ trong câu: "It turns out we''ll need to push back the shipment of the prototype motor" (Hóa ra chúng ta sẽ cần phải lùi lại việc vận chuyển động cơ nguyên mẫu).
Dịch câu hỏi: Vấn đề gì những người nói đang thảo luận?
Dịch các đáp án:
A. Một sự tạm dừng trong khi nhận thêm tài trợ
B. Một sự chậm trễ trong việc giao hàng
C. Một nhu cầu để công ty di dời
D. Sự mất mát một số nhân viên có kinh nghiệm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1700, 80, '2023/test2/audio/test2_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2258, 1700, 58, 'What does the man request?', 'A report from the client', 'A faster pace of work', 'Additional employees', 'Daily updates from the team', 'D', 'Đáp án D là chính xác. Người đàn ông yêu cầu cập nhật hàng ngày từ đội ngũ. Ông nói: "And I''d like the development team to start giving me daily briefings about progress on this issue." (Và tôi muốn đội phát triển bắt đầu cung cấp cho tôi các bản tóm tắt hàng ngày về tiến độ của vấn đề này.)
Dịch câu hỏi: Người đàn ông yêu cầu điều gì?
Dịch các đáp án:
A. Một báo cáo từ khách hàng
B. Một nhịp độ làm việc nhanh hơn
C. Thêm nhân viên
D. Cập nhật hàng ngày từ đội ngũ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1701, 80, '2023/test2/audio/test2_question_59_61.mp3', NULL, 'W-Br Good evening. Legend Hotel. How may I help you?
M-Au Hello. I''m at the local airport. Does the hotel run shuttle buses to here?
W-Br We usually don''t, but... was your flight originally scheduled for Central Airport?
M-Au It was, but apparently Sothere''s a problem at Central.
W-Br Yes, there''s a personnel shortage, but several flights have been rerouted to the local airport. We have started running an airport shuttle this morning.
M-Au OK. That''s good news. When is the next shuttle?
W-Br Buses run every half hour. What''s your reservation number? I''ll ensure that your room is ready for you when you arrive.', 'W-Nữ: Chào buổi tối. Khách sạn Legend. Tôi có thể giúp gì cho bạn?
M-Nam: Xin chào. Tôi đang ở sân bay địa phương. Khách sạn có chạy xe buýt đưa đón đến đây không?
W-Nữ: Chúng tôi thường không làm vậy, nhưng... chuyến bay của bạn ban đầu được lên lịch đến Sân bay Trung tâm phải không?
M-Nam: Đúng vậy, nhưng dường như có vấn đề ở Sân bay Trung tâm.
W-Nữ: Vâng, có thiếu nhân sự, nhưng một số chuyến bay đã được chuyển hướng đến sân bay địa phương. Chúng tôi đã bắt đầu chạy xe đưa đón sân bay sáng nay.
M-Nam: OK. Đó là tin tốt. Khi nào có xe đưa đón tiếp theo?
W-Nữ: Xe buýt chạy mỗi nửa giờ. Số đặt phòng của bạn là gì? Tôi sẽ đảm bảo rằng phòng của bạn đã sẵn sàng khi bạn đến.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2259, 1701, 59, 'What does the woman say about Central Airport?', 'The airport operates two shuttles.', 'There are not enough people working there.', 'It is not far from the Legend Hotel.', 'It is more modern than the local airport.', 'B', 'Đáp án B là chính xác. Người phụ nữ nói rằng có thiếu nhân sự ở Sân bay Trung tâm. Cụ thể, cô ấy nói: "Yes, there''s a personnel shortage" (Vâng, có thiếu nhân sự).
Dịch câu hỏi: Người phụ nữ nói gì về Sân bay Trung tâm?
Dịch các đáp án:
A. Sân bay vận hành hai xe đưa đón.
B. Không có đủ người làm việc ở đó.
C. Nó không xa khách sạn Legend.
D. Nó hiện đại hơn sân bay địa phương.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1702, 80, '2023/test2/audio/test2_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2260, 1702, 60, 'Why does the man say, "That''s good news"?', 'He will be able to take a shuttle to the hotel.', 'His flight was rescheduled', 'Central Airport will reopen soon.', 'He will be able to change his hotel reservation.', 'A', 'Đáp án A là chính xác. Người đàn ông nói "That''s good news" (Đó là tin tốt) vì anh ta sẽ có thể đi xe đưa đón đến khách sạn. Điều này được suy ra từ phản ứng của anh ta sau khi người phụ nữ thông báo rằng khách sạn đã bắt đầu chạy xe đưa đón sân bay.
Dịch câu hỏi: Tại sao người đàn ông nói "Đó là tin tốt"?
Dịch các đáp án:
A. Anh ta sẽ có thể đi xe đưa đón đến khách sạn.
B. Chuyến bay của anh ta đã được lên lịch lại.
C. Sân bay Trung tâm sẽ sớm mở cửa trở lại.
D. Anh ta sẽ có thể thay đổi đặt phòng khách sạn của mình.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1703, 80, '2023/test2/audio/test2_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2261, 1703, 61, 'What will the woman do for the man?', 'Give him the shuttle company''s phone number', 'Find information about Central Airport', 'Give him a discount on his reservation', 'Make sure that his room has been prepared', 'D', 'Đáp án D là chính xác. Người phụ nữ sẽ đảm bảo rằng phòng của người đàn ông đã được chuẩn bị. Cô ấy nói: "I''ll ensure that your room is ready for you when you arrive." (Tôi sẽ đảm bảo rằng phòng của bạn đã sẵn sàng khi bạn đến.)
Dịch câu hỏi: Người phụ nữ sẽ làm gì cho người đàn ông?
Dịch các đáp án:
A. Cung cấp cho anh ta số điện thoại của công ty xe đưa đón
B. Tìm thông tin về Sân bay Trung tâm
C. Giảm giá cho đặt phòng của anh ta
D. Đảm bảo rằng phòng của anh ta đã được chuẩn bị');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1704, 80, '2023/test2/audio/test2_question_62_64.mp3', '2023/test2/image/test2-p3-image-62.jpg', 'M-Au Hi, Marla. I''m calling to check whether you received my outline of the design project for your apartment remodeling. I e-mailed it to you yesterday.
W-Am Yes. Thank you for doing such a great job. I really liked your idea of opening up the kitchen and creating an open space with the living room.
M-Au Great. If everything looks good to you, I can start ordering the supplies tomorrow.
W-Am Actually, I don''t like the ceramic tiles you picked for the kitchen. I like the marble ones much better. I know they are more expensive, but it''s a small space.', 'M-Nam: Chào Marla. Tôi gọi để kiểm tra xem bạn đã nhận được bản phác thảo của tôi về dự án thiết kế cho việc cải tạo căn hộ của bạn chưa. Tôi đã gửi email cho bạn ngày hôm qua.
W-Nữ: Vâng. Cảm ơn anh đã làm một công việc tuyệt vời. Tôi thực sự thích ý tưởng của anh về việc mở rộng nhà bếp và tạo ra một không gian mở với phòng khách.
M-Nam: Tuyệt. Nếu mọi thứ trông ổn với bạn, tôi có thể bắt đầu đặt hàng vật tư vào ngày mai.
W-Nữ: Thực ra, tôi không thích những viên gạch ceramic mà anh chọn cho nhà bếp. Tôi thích những viên đá cẩm thạch hơn nhiều. Tôi biết chúng đắt hơn, nhưng đó là một không gian nhỏ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2262, 1704, 62, 'What did the man do yesterday?', 'He visited a property.', 'He contacted a supplier.', 'He sent a plan.', 'He took some measurements.', 'C', 'Đáp án C là chính xác. Người đàn ông đã gửi một bản kế hoạch ngày hôm qua. Anh ta nói: "I e-mailed it to you yesterday." (Tôi đã gửi email cho bạn ngày hôm qua.)
Dịch câu hỏi: Người đàn ông đã làm gì ngày hôm qua?
Dịch các đáp án:
A. Anh ta đã thăm một bất động sản.
B. Anh ta đã liên hệ với một nhà cung cấp.
C. Anh ta đã gửi một bản kế hoạch.
D. Anh ta đã đo đạc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1705, 80, '2023/test2/audio/test2_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2263, 1705, 63, 'What does the woman say she likes?', 'The cost the man has estimated', 'The open-space design', 'The colors the man has selected', 'The remodeling timeline', 'B', 'Đáp án B là chính xác. Người phụ nữ nói rằng cô ấy thích thiết kế không gian mở. Cô ấy nói: "I really liked your idea of opening up the kitchen and creating an open space with the living room." (Tôi thực sự thích ý tưởng của anh về việc mở rộng nhà bếp và tạo ra một không gian mở với phòng khách.)
Dịch câu hỏi: Người phụ nữ nói cô ấy thích gì?
Dịch các đáp án:
A. Chi phí mà người đàn ông đã ước tính
B. Thiết kế không gian mở
C. Màu sắc mà người đàn ông đã chọn
D. Lịch trình cải tạo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1706, 80, '2023/test2/audio/test2_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2264, 1706, 64, 'Look at the graphic. How much will the woman pay for each tile?', '$12.00', '$6.50', '$4.99', '$2.50', 'B', 'Đáp án B là chính xác. Theo hình ảnh và cuộc trò chuyện, người phụ nữ sẽ trả $6.50 cho mỗi viên gạch. Cô ấy nói rằng cô ấy thích gạch đá cẩm thạch hơn, và theo hình ảnh, gạch đá cẩm thạch có giá $6.50.
Dịch câu hỏi: Nhìn vào hình ảnh. Người phụ nữ sẽ trả bao nhiêu cho mỗi viên gạch?
Dịch các đáp án:
A. $12.00
B. $6.50
C. $4.99
D. $2.50');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1707, 80, '2023/test2/audio/test2_question_65_67.mp3', '2023/test2/image/test2-p3-image-65.jpg', 'M-Cn Hi. I''d like to make a reservation for a group of clients that will be visiting our company from the first to the sixth of June. I need eight rooms.
W-Br We do have availability for that period. The type of room I recommend for you is normally 99 euros per night, but we can offer a group discount.
M-Cn That''ll work. Also, on June fifth, we want to take our clients on a tour of the local attractions. Could you help arrange that?
W-Br We have an event planner here who''ll be able to help you. His name is Pablo Gonzales. I''ll connect you to his office once I''ve completed your reservation.', 'M-Nam: Xin chào. Tôi muốn đặt phòng cho một nhóm khách hàng sẽ đến thăm công ty chúng tôi từ ngày 1 đến ngày 6 tháng 6. Tôi cần tám phòng.
W-Nữ: Chúng tôi có phòng trống cho thời gian đó. Loại phòng tôi đề xuất cho bạn thường có giá 99 euro mỗi đêm, nhưng chúng tôi có thể đề nghị giảm giá cho nhóm.
M-Nam: Điều đó sẽ phù hợp. Ngoài ra, vào ngày 5 tháng 6, chúng tôi muốn đưa khách hàng đi tham quan các điểm du lịch địa phương. Bạn có thể giúp sắp xếp điều đó không?
W-Nữ: Chúng tôi có một nhà lập kế hoạch sự kiện ở đây sẽ có thể giúp bạn. Tên anh ấy là Pablo Gonzales. Tôi sẽ kết nối bạn với văn phòng của anh ấy sau khi tôi hoàn thành đặt phòng của bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2265, 1707, 65, 'Why is the man calling?', 'To request a room change', 'To make a group reservation', 'To order room service', 'To complain about noise', 'B', 'Đáp án B là chính xác. Người đàn ông đang gọi để đặt phòng cho một nhóm. Anh ta nói: "I''d like to make a reservation for a group of clients" (Tôi muốn đặt phòng cho một nhóm khách hàng).
Dịch câu hỏi: Tại sao người đàn ông gọi điện?
Dịch các đáp án:
A. Để yêu cầu thay đổi phòng
B. Để đặt phòng cho một nhóm
C. Để đặt dịch vụ phòng
D. Để phàn nàn về tiếng ồn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1708, 80, '2023/test2/audio/test2_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2266, 1708, 66, 'Look at the graphic. Which room type does the woman mention?', 'Executive suite', 'Deluxe double', 'Standard king', 'Single basic', 'C', 'Đáp án C là chính xác. Theo hình ảnh và cuộc trò chuyện, người phụ nữ đề cập đến loại phòng Standard king. Cô ấy nói rằng loại phòng cô ấy đề xuất thường có giá 99 euro mỗi đêm, và theo hình ảnh, phòng Standard king có giá 99 euro.
Dịch câu hỏi: Nhìn vào hình ảnh. Người phụ nữ đề cập đến loại phòng nào?
Dịch các đáp án:
A. Phòng hạng sang
B. Phòng đôi hạng sang
C. Phòng chuẩn king
D. Phòng đơn cơ bản');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1709, 80, '2023/test2/audio/test2_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2267, 1709, 67, 'Who is Pablo Gonzales?', 'An accountant', 'A client', 'A bus driver', 'An event planner', 'D', 'Đáp án D là chính xác. Pablo Gonzales là một nhà lập kế hoạch sự kiện. Người phụ nữ nói: "We have an event planner here who''ll be able to help you. His name is Pablo Gonzales." (Chúng tôi có một nhà lập kế hoạch sự kiện ở đây sẽ có thể giúp bạn. Tên anh ấy là Pablo Gonzales.)
Dịch câu hỏi: Pablo Gonzales là ai?
Dịch các đáp án:
A. Một kế toán viên
B. Một khách hàng
C. Một tài xế xe buýt
D. Một nhà lập kế hoạch sự kiện');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1710, 80, '2023/test2/audio/test2_question_68_70.mp3', '2023/test2/image/test2-p3-image-68.jpg', 'M-Au Hi, Joanna. The management group needs to submit nominees for this year''s award for outstanding employee. My supervisor wants to know if any managers have nominated anyone yet.
W-Br Not yet, Charles. I e-mailed everyone about it a week ago, but I haven''t heard anything yet. I''ll have to follow up with the managers and let them know the deadline is coming up.
M-Au OK, well, I printed out a breakdown of the customer service representatives with the most five-star reviews from customers last year. We had someone who was really outstanding.
W-Br Those are excellent numbers. Could you go ahead and submit a nomination?', 'M-Nam: Chào Joanna. Nhóm quản lý cần đề cử ứng viên cho giải thưởng nhân viên xuất sắc năm nay. Giám sát của tôi muốn biết liệu có quản lý nào đã đề cử ai chưa.
W-Nữ: Chưa, Charles. Tôi đã gửi email cho mọi người về việc đó một tuần trước, nhưng tôi vẫn chưa nghe được gì. Tôi sẽ phải theo dõi với các quản lý và cho họ biết thời hạn đang đến gần.
M-Nam: OK, vậy, tôi đã in ra một bảng phân tích về các đại diện dịch vụ khách hàng có nhiều đánh giá năm sao nhất từ khách hàng năm ngoái. Chúng ta có một người thực sự xuất sắc.
W-Nữ: Đó là những con số xuất sắc. Anh có thể tiến hành đề cử không?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2268, 1710, 68, 'What is the conversation mainly about?', 'A sales strategy', 'An improvement in customer service', 'A new manager', 'An award', 'D', 'Đáp án D là chính xác. Cuộc trò chuyện chủ yếu về một giải thưởng, cụ thể là giải thưởng cho nhân viên xuất sắc. Điều này được đề cập ngay từ đầu cuộc trò chuyện: "The management group needs to submit nominees for this year''s award for outstanding employee."
Dịch câu hỏi: Cuộc trò chuyện chủ yếu về điều gì?
Dịch các đáp án:
A. Một chiến lược bán hàng
B. Một cải tiến trong dịch vụ khách hàng
C. Một quản lý mới
D. Một giải thưởng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1711, 80, '2023/test2/audio/test2_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2269, 1711, 69, 'Who does the woman say she will send a reminder to?', 'The management team', 'The customer service representatives', 'A magazine editor', 'A repair technician', 'A', 'Đáp án A là chính xác. Người phụ nữ nói rằng cô ấy sẽ gửi lời nhắc nhở cho nhóm quản lý. Cô ấy nói: "I''ll have to follow up with the managers and let them know the deadline is coming up." (Tôi sẽ phải theo dõi với các quản lý và cho họ biết thời hạn đang đến gần.)
Dịch câu hỏi: Người phụ nữ nói cô ấy sẽ gửi lời nhắc nhở cho ai?
Dịch các đáp án:
A. Nhóm quản lý
B. Các đại diện dịch vụ khách hàng
C. Một biên tập viên tạp chí
D. Một kỹ thuật viên sửa chữa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1712, 80, '2023/test2/audio/test2_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2270, 1712, 70, 'Look at the graphic. Which representative is the man most likely talking about?', 'Jorge', 'Rebecca', 'Jada', 'Kent', 'B', 'Đáp án B là chính xác. Dựa vào biểu đồ, Rebecca có số lượng đánh giá năm sao cao nhất, vì vậy người đàn ông có khả năng đang nói về cô ấy khi anh ta đề cập đến "someone who was really outstanding" (một người thực sự xuất sắc).
Dịch câu hỏi: Nhìn vào hình ảnh. Đại diện nào mà người đàn ông có khả năng đang nói đến?
Dịch các đáp án:
A. Jorge
B. Rebecca
C. Jada
D. Kent');;

-- Data for 2023 Test2 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1713, 81, '2023/test2/audio/test2_question_71_73.mp3', NULL, 'W-Br Looking for an interesting activity to celebrate the coming of spring? Winford Gardens offers an escape filled with calm, peace, and quiet just a few miles from the downtown area. Winford Gardens has acres of outdoor gardens filled with plants you won''t typically find anywhere near here. This weekend we will have an exhibition of Mexican blue palms. If you have never seen these striking and unique plants, now is your chance! Winford''s café is a converted building that used to be a greenhouse. The surrounding tropical plants and flowers help make dining there a pleasure.', 'W-Nữ: Đang tìm kiếm một hoạt động thú vị để chào đón mùa xuân? Vườn Winford mang đến một nơi trốn tránh đầy bình yên, tĩnh lặng chỉ cách khu trung tâm vài dặm. Vườn Winford có hàng mẫu vườn ngoài trời đầy những loài thực vật mà bạn thường không thể tìm thấy ở đâu gần đây. Cuối tuần này chúng tôi sẽ có một cuộc triển lãm cây cọ xanh Mexico. Nếu bạn chưa bao giờ nhìn thấy những cây độc đáo và ấn tượng này, giờ là cơ hội của bạn! Quán café của Winford là một tòa nhà được chuyển đổi từ một nhà kính cũ. Những cây và hoa nhiệt đới xung quanh giúp việc ăn uống ở đó trở nên thú vị.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2271, 1713, 71, 'What is being advertised?', 'A trip to Mexico', 'A city tour', 'A farm visit', 'A botanical garden', 'D', 'Đáp án D là chính xác. Quảng cáo đang nói về một vườn thực vật có tên Winford Gardens. Nó được mô tả là có "acres of outdoor gardens filled with plants" (hàng mẫu vườn ngoài trời đầy những loài thực vật) và có một cuộc triển lãm cây cọ xanh Mexico.
Dịch câu hỏi: Điều gì đang được quảng cáo?
Dịch các đáp án:
A. Một chuyến đi đến Mexico
B. Một tour tham quan thành phố
C. Một chuyến thăm nông trại
D. Một vườn thực vật');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1714, 81, '2023/test2/audio/test2_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2272, 1714, 72, 'What event is happening this weekend?', 'A competition will be held.', 'Special plants will be on display.', 'Crops will be planted.', 'A special sale will take place.', 'B', 'Đáp án B là chính xác. Sự kiện diễn ra cuối tuần này là một cuộc triển lãm cây cọ xanh Mexico đặc biệt. Cụ thể, quảng cáo nói: "This weekend we will have an exhibition of Mexican blue palms." (Cuối tuần này chúng tôi sẽ có một cuộc triển lãm cây cọ xanh Mexico.)
Dịch câu hỏi: Sự kiện gì đang diễn ra vào cuối tuần này?
Dịch các đáp án:
A. Một cuộc thi sẽ được tổ chức.
B. Những cây đặc biệt sẽ được trưng bày.
C. Cây trồng sẽ được trồng.
D. Một đợt bán hàng đặc biệt sẽ diễn ra.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1715, 81, '2023/test2/audio/test2_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2273, 1715, 73, 'What does the speaker say about a café building?', 'It will soon be repainted.', 'It was once a greenhouse.', 'It is located near public transportation.', 'It is closed this spring.', 'B', 'Đáp án B là chính xác. Người nói cho biết tòa nhà quán café từng là một nhà kính. Cụ thể, họ nói: "Winford''s café is a converted building that used to be a greenhouse." (Quán café của Winford là một tòa nhà được chuyển đổi từ một nhà kính cũ.)
Dịch câu hỏi: Người nói nói gì về tòa nhà quán café?
Dịch các đáp án:
A. Nó sẽ sớm được sơn lại.
B. Nó từng là một nhà kính.
C. Nó nằm gần phương tiện giao thông công cộng.
D. Nó đóng cửa mùa xuân này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1716, 81, '2023/test2/audio/test2_question_74_76.mp3', NULL, 'M-Au Good afternoon. Welcome to this week''s managers'' meeting here at South Truck Deliveries. As you know, we''ve always written performance evaluations for our drivers and other employees on paper. I am pleased to announce some important changes. Beginning this year, we will use a software application called Personnel Profile to enter performance appraisals. Let me introduce Ms. Hwa Young Lee, the head of our IT department. She will walk you through how to enroll in a training course on using Personnel Profile, and you will complete your enrollment by the end of this meeting.', 'M-Nam: Chào buổi chiều. Chào mừng đến với cuộc họp quản lý tuần này tại South Truck Deliveries. Như các bạn đã biết, chúng ta luôn viết đánh giá hiệu suất cho các tài xế và nhân viên khác trên giấy. Tôi vui mừng thông báo một số thay đổi quan trọng. Bắt đầu từ năm nay, chúng ta sẽ sử dụng một ứng dụng phần mềm có tên Personnel Profile để nhập đánh giá hiệu suất. Hãy để tôi giới thiệu cô Hwa Young Lee, trưởng phòng IT của chúng ta. Cô ấy sẽ hướng dẫn các bạn cách đăng ký khóa đào tạo sử dụng Personnel Profile, và các bạn sẽ hoàn thành việc đăng ký vào cuối cuộc họp này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2274, 1716, 74, 'Who most likely is the speaker?', 'A salesperson', 'A manager', 'A safety inspector', 'A software developer', 'B', 'Đáp án B là chính xác. Người nói có khả năng là một quản lý. Điều này được suy ra từ việc họ đang chủ trì cuộc họp của các quản lý ("Welcome to this week''s managers'' meeting") và đang thông báo về những thay đổi quan trọng trong công ty.
Dịch câu hỏi: Người nói có khả năng là ai?
Dịch các đáp án:
A. Một nhân viên bán hàng
B. Một quản lý
C. Một thanh tra an toàn
D. Một nhà phát triển phần mềm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1717, 81, '2023/test2/audio/test2_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2275, 1717, 75, 'What is the main topic of the talk?', 'A delivery route', 'A corporate merger', 'Performance reviews', 'Hiring procedures', 'C', 'Đáp án C là chính xác. Chủ đề chính của bài nói là về đánh giá hiệu suất. Người nói thông báo về việc chuyển từ đánh giá hiệu suất trên giấy sang sử dụng phần mềm Personnel Profile để nhập đánh giá hiệu suất.
Dịch câu hỏi: Chủ đề chính của bài nói là gì?
Dịch các đáp án:
A. Một tuyến đường giao hàng
B. Một vụ sáp nhập doanh nghiệp
C. Đánh giá hiệu suất
D. Quy trình tuyển dụng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1718, 81, '2023/test2/audio/test2_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2276, 1718, 76, 'What does the speaker ask the listeners to do?', 'Pass along some information to workers', 'Sign up for a training course', 'Get some information from customers', 'Talk with employees about their goals for the year', 'B', 'Đáp án B là chính xác. Người nói yêu cầu người nghe đăng ký một khóa đào tạo. Cụ thể, họ nói rằng Ms. Hwa Young Lee "will walk you through how to enroll in a training course on using Personnel Profile, and you will complete your enrollment by the end of this meeting." (sẽ hướng dẫn các bạn cách đăng ký khóa đào tạo sử dụng Personnel Profile, và các bạn sẽ hoàn thành việc đăng ký vào cuối cuộc họp này.)
Dịch câu hỏi: Người nói yêu cầu người nghe làm gì?
Dịch các đáp án:
A. Chuyển một số thông tin cho công nhân
B. Đăng ký một khóa đào tạo
C. Lấy một số thông tin từ khách hàng
D. Nói chuyện với nhân viên về mục tiêu của họ trong năm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1719, 81, '2023/test2/audio/test2_question_77_79.mp3', NULL, 'W-Br Hi. This is Ms. Mitra. You''re scheduled to move my furniture to my new apartment tomorrow morning at eight. I''m calling because I just learned that the freight elevator in my building is broken, and my apartment is on a very high floor. I will check first thing tomorrow morning to see what the situation is. But please give me a call as soon as you can. I have an overseas trip coming up next week, so this work will have to happen soon.', 'W-Nữ: Xin chào. Đây là cô Mitra. Các bạn được lên lịch chuyển đồ đạc của tôi đến căn hộ mới vào sáng mai lúc 8 giờ. Tôi gọi vì tôi vừa biết rằng thang máy chở hàng trong tòa nhà của tôi bị hỏng, và căn hộ của tôi ở tầng rất cao. Tôi sẽ kiểm tra đầu tiên vào sáng mai để xem tình hình thế nào. Nhưng xin vui lòng gọi cho tôi ngay khi có thể. Tôi có một chuyến đi nước ngoài vào tuần tới, vì vậy công việc này sẽ phải diễn ra sớm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2277, 1719, 77, 'Who is the speaker most likely calling?', 'A real estate firm', 'A moving company', 'A travel agency', 'A furniture store', 'B', 'Đáp án B là chính xác. Người nói có khả năng đang gọi cho một công ty chuyển nhà. Điều này được suy ra từ việc cô ấy nói về việc di chuyển đồ đạc của mình đến căn hộ mới.
Dịch câu hỏi: Người nói có khả năng đang gọi cho ai?
Dịch các đáp án:
A. Một công ty bất động sản
B. Một công ty chuyển nhà
C. Một đại lý du lịch
D. Một cửa hàng đồ nội thất');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1720, 81, '2023/test2/audio/test2_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2278, 1720, 78, 'Why does the speaker say, "my apartment is on a very high floor"?', 'To correct a misunderstanding', 'To negotiate a price', 'To ask about a property''s value', 'To warn about a situation', 'D', 'Đáp án D là chính xác. Người nói đề cập đến việc căn hộ của cô ấy ở tầng rất cao để cảnh báo về một tình huống. Cô ấy đang thông báo cho công ty chuyển nhà về khó khăn tiềm ẩn trong việc di chuyển đồ đạc do thang máy chở hàng bị hỏng.
Dịch câu hỏi: Tại sao người nói nói "căn hộ của tôi ở tầng rất cao"?
Dịch các đáp án:
A. Để sửa một sự hiểu lầm
B. Để thương lượng giá
C. Để hỏi về giá trị của một bất động sản
D. Để cảnh báo về một tình huống');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1721, 81, '2023/test2/audio/test2_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2279, 1721, 79, 'What will the speaker do next week?', 'Host an event', 'Make a payment', 'Travel abroad', 'Begin a new job', 'C', 'Đáp án C là chính xác. Người nói sẽ đi du lịch nước ngoài vào tuần tới. Cô ấy nói: "I have an overseas trip coming up next week" (Tôi có một chuyến đi nước ngoài vào tuần tới).
Dịch câu hỏi: Người nói sẽ làm gì vào tuần tới?
Dịch các đáp án:
A. Tổ chức một sự kiện
B. Thực hiện một khoản thanh toán
C. Du lịch nước ngoài
D. Bắt đầu một công việc mới');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1722, 81, '2023/test2/audio/test2_question_80_82.mp3', NULL, 'M-Cn Good evening, everyone! Welcome to a new season of City Opera. I bring some bad news, I''m afraid. Soprano Lisa Gornicka informed me earlier today that she will not be able to perform tonight. I know how disappointing this is. But I also have good news! Soprano Rita Marks is in town and has agreed to step in for Ms. Gornicka. Not only is Ms. Marks familiar with the role of Laura, but she also knows the choreography, since she worked with our director when this production premiered in Toronto. Wondering what her voice is like? Well, judge for yourself, but I saw the reviews from Toronto. I can guarantee that we are in for a treat!', 'M-Cn Chào buổi tối, mọi người! Chào mừng bạn đến với mùa mới của City Opera. Tôi mang đến một số tin xấu, tôi e rằng. Soprano Lisa Gornicka đã thông báo với tôi vào đầu ngày hôm nay rằng cô ấy sẽ không thể biểu diễn tối nay. Tôi biết điều này đáng thất vọng như thế nào. Nhưng tôi cũng có tin tốt! Soprano Rita Marks đang ở trong thị trấn và đã đồng ý bước vào bà Gornicka. Cô Marks không chỉ quen thuộc với vai Laura mà còn biết vũ đạo, vì cô ấy đã làm việc với đạo diễn của chúng tôi khi tác phẩm này được công chiếu tại Toronto. Tự hỏi giọng nói của cô ấy như thế nào? Chà, hãy tự đánh giá, nhưng tôi đã xem các bài đánh giá từ Toronto. Tôi có thể đảm bảo rằng chúng ta đang ở trong một điều trị!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2280, 1722, 80, 'Why might the listeners be disappointed?', 'A performance has been canceled.', 'A performer will not be appearing.', 'A new production will be delayed.', 'A production is not new.', 'B', 'Đáp án B là chính xác. Người nghe có thể thất vọng vì một nghệ sĩ biểu diễn sẽ không xuất hiện. Cụ thể, người nói thông báo rằng "Soprano Lisa Gornicka informed me earlier today that she will not be able to perform tonight." (Nữ ca sĩ soprano Lisa Gornicka đã thông báo cho tôi sớm hôm nay rằng cô ấy sẽ không thể biểu diễn tối nay.)
Dịch câu hỏi: Tại sao người nghe có thể thất vọng?
Dịch các đáp án:
A. Một buổi biểu diễn đã bị hủy.
B. Một nghệ sĩ biểu diễn sẽ không xuất hiện.
C. Một vở diễn mới sẽ bị trì hoãn.
D. Một vở diễn không mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1723, 81, '2023/test2/audio/test2_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2281, 1723, 81, 'What does the speaker indicate about Rita Marks?', 'She has flown in from Toronto.', 'She taught the speaker.', 'She has experience with a role.', 'She is a good friend of the speaker''s.', 'C', 'Đáp án C là chính xác. Người nói chỉ ra rằng Rita Marks có kinh nghiệm với vai diễn. Cụ thể, họ nói: "Not only is Ms. Marks familiar with the role of Laura, but she also knows the choreography" (Không chỉ Ms. Marks quen thuộc với vai Laura, mà cô ấy còn biết vũ đạo).
Dịch câu hỏi: Người nói chỉ ra điều gì về Rita Marks?
Dịch các đáp án:
A. Cô ấy đã bay từ Toronto đến.
B. Cô ấy đã dạy người nói.
C. Cô ấy có kinh nghiệm với một vai diễn.
D. Cô ấy là một người bạn tốt của người nói.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1724, 81, '2023/test2/audio/test2_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2282, 1724, 82, 'What does the speaker imply when he says, "I saw the reviews from Toronto"?', 'He attended the opera in Toronto.', 'An audience disliked Lisa Gornicka.', 'Critics disagree about Rita Marks''s performance.', 'Rita Marks has been praised for her singing.', 'D', 'Đáp án D là chính xác. Khi người nói nói "I saw the reviews from Toronto" (Tôi đã xem các bài đánh giá từ Toronto), họ ngụ ý rằng Rita Marks đã được khen ngợi về giọng hát của cô ấy. Điều này được củng cố bởi câu tiếp theo: "I can guarantee that we are in for a treat!" (Tôi có thể đảm bảo rằng chúng ta sẽ được thưởng thức một điều tuyệt vời!)
Dịch câu hỏi: Người nói ngụ ý gì khi anh ta nói "Tôi đã xem các bài đánh giá từ Toronto"?
Dịch các đáp án:
A. Anh ta đã tham dự buổi opera ở Toronto.
B. Khán giả không thích Lisa Gornicka.
C. Các nhà phê bình không đồng ý về buổi biểu diễn của Rita Marks.
D. Rita Marks đã được khen ngợi về giọng hát của cô ấy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1725, 81, '2023/test2/audio/test2_question_83_85.mp3', NULL, 'W-Am Thank you for inviting me and other members of the marketing department to this meeting of the research and development team. We always welcome the opportunity to share customer information about our toys with you. I''d like to start off with some information about the remote-control car that we launched in department stores and toy stores one month ago. It''s been a mixed bag. Customers love the smooth action of the car and the high speed it can achieve. However, they are somewhat disappointed with the rechargeable battery the car comes with. I encourage your team to find ways to make the battery charge faster and last longer.', 'W-Nữ: Cảm ơn vì đã mời tôi và các thành viên khác của phòng tiếp thị đến cuộc họp này của đội nghiên cứu và phát triển. Chúng tôi luôn hoan nghênh cơ hội được chia sẻ thông tin khách hàng về đồ chơi của chúng tôi với các bạn. Tôi muốn bắt đầu với một số thông tin về chiếc xe điều khiển từ xa mà chúng ta đã ra mắt tại các cửa hàng bách hóa và cửa hàng đồ chơi một tháng trước. Nó đã nhận được phản hồi trái chiều. Khách hàng yêu thích sự di chuyển mượt mà của chiếc xe và tốc độ cao mà nó có thể đạt được. Tuy nhiên, họ hơi thất vọng với pin sạc đi kèm với chiếc xe. Tôi khuyến khích đội của các bạn tìm cách để làm cho pin sạc nhanh hơn và dùng được lâu hơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2283, 1725, 83, 'Where does the speaker most likely work?', 'At an automobile company', 'At a data analysis company', 'At a toy manufacturer', 'At a department store', 'C', 'Đáp án C là chính xác. Người nói có khả năng làm việc tại một công ty sản xuất đồ chơi. Điều này được suy ra từ việc cô ấy đề cập đến "our toys" (đồ chơi của chúng tôi) và nói về việc ra mắt một chiếc xe điều khiển từ xa.
Dịch câu hỏi: Người nói có khả năng làm việc ở đâu?
Dịch các đáp án:
A. Tại một công ty ô tô
B. Tại một công ty phân tích dữ liệu
C. Tại một nhà sản xuất đồ chơi
D. Tại một cửa hàng bách hóa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1726, 81, '2023/test2/audio/test2_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2284, 1726, 84, 'What does the speaker mean when she says, "It''s been a mixed bag"?', 'The product she is discussing cannot be returned for a refund.', 'Customers often purchase more than one of the product.', 'A competitor has developed a similar product.', 'A product has had both positive and negative reviews.', 'D', 'Đáp án D là chính xác. Khi người nói nói "It''s been a mixed bag" (Nó đã nhận được phản hồi trái chiều), cô ấy có ý rằng sản phẩm đã nhận được cả đánh giá tích cực và tiêu cực. Điều này được minh họa bởi việc cô ấy đề cập đến cả những điểm mà khách hàng yêu thích và những điểm họ thất vọng về sản phẩm.
Dịch câu hỏi: Người nói có ý gì khi cô ấy nói "Nó đã nhận được phản hồi trái chiều"?
Dịch các đáp án:
A. Sản phẩm mà cô ấy đang thảo luận không thể được hoàn trả để nhận lại tiền.
B. Khách hàng thường mua nhiều hơn một sản phẩm.
C. Một đối thủ cạnh tranh đã phát triển một sản phẩm tương tự.
D. Một sản phẩm đã nhận được cả đánh giá tích cực và tiêu cực.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1727, 81, '2023/test2/audio/test2_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2285, 1727, 85, 'What does the speaker ask the listeners to do?', 'Try using the product she is discussing', 'Improve one part of the product', 'Get more information from customers', 'Collaborate with the marketing team', 'B', 'Đáp án B là chính xác. Người nói yêu cầu người nghe cải thiện một phần của sản phẩm. Cụ thể, cô ấy nói: "I encourage your team to find ways to make the battery charge faster and last longer." (Tôi khuyến khích đội của các bạn tìm cách để làm cho pin sạc nhanh hơn và dùng được lâu hơn.)
Dịch câu hỏi: Người nói yêu cầu người nghe làm gì?
Dịch các đáp án:
A. Thử sử dụng sản phẩm mà cô ấy đang thảo luận
B. Cải thiện một phần của sản phẩm
C. Lấy thêm thông tin từ khách hàng
D. Hợp tác với đội tiếp thị');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1728, 81, '2023/test2/audio/test2_question_86_88.mp3', NULL, 'W-Br Attention, Shopsmart shoppers! in case you didn''t pick up our flyer, we are kicking of a Shopsmart giveaway event. For every two cans of Shopsmart soup or vegetables that you buy, you will be entered in a drawing to win a gift certificate that can be used at any Shopsmart location. Gift certificates worth $100 each will be awarded to three lucky shoppers on May first. This offer is good only for Shopsmart-brand canned goods. Act now! Stock up and join the giveaway! The more you buy, the more chances you have to win!', 'W-Nữ: Chú ý, khách hàng Shopsmart! Trong trường hợp bạn chưa nhận được tờ rơi của chúng tôi, chúng tôi đang khởi động một sự kiện tặng quà Shopsmart. Với mỗi hai lon súp hoặc rau củ Shopsmart mà bạn mua, bạn sẽ được tham gia vào một cuộc rút thăm để giành một phiếu quà tặng có thể sử dụng tại bất kỳ địa điểm Shopsmart nào. Phiếu quà tặng trị giá 100 đô la mỗi cái sẽ được trao cho ba khách hàng may mắn vào ngày 1 tháng 5. Ưu đãi này chỉ áp dụng cho hàng đóng hộp mang thương hiệu Shopsmart. Hãy hành động ngay! Hãy tích trữ và tham gia sự kiện tặng quà! Bạn mua càng nhiều, cơ hội trúng thưởng càng cao!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2286, 1728, 86, 'Where is the announcement most likely being made?', 'At a supermarket', 'At a community center', 'At a restaurant', 'At a shopping mall', 'A', 'Đáp án A là chính xác. Thông báo có khả năng đang được đưa ra tại một siêu thị. Điều này được suy ra từ việc thông báo đề cập đến "Shopsmart shoppers" (khách hàng Shopsmart) và nói về việc mua các sản phẩm đóng hộp.
Dịch câu hỏi: Thông báo có khả năng đang được đưa ra ở đâu?
Dịch các đáp án:
A. Tại một siêu thị
B. Tại một trung tâm cộng đồng
C. Tại một nhà hàng
D. Tại một trung tâm mua sắm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1729, 81, '2023/test2/audio/test2_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2287, 1729, 87, 'What is the main topic of the announcement?', 'A discount offer', 'A new product', 'A giveaway', 'A volunteer opportunity', 'C', 'Đáp án C là chính xác. Chủ đề chính của thông báo là một sự kiện tặng quà. Thông báo mở đầu bằng việc nói "we are kicking of a Shopsmart giveaway event" (chúng tôi đang khởi động một sự kiện tặng quà Shopsmart).
Dịch câu hỏi: Chủ đề chính của thông báo là gì?
Dịch các đáp án:
A. Một ưu đãi giảm giá
B. Một sản phẩm mới
C. Một sự kiện tặng quà
D. Một cơ hội tình nguyện');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1730, 81, '2023/test2/audio/test2_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2288, 1730, 88, 'What does the speaker say about some Shopsmart products?', 'They are not available at all Shopsmart locations.', 'They are acquired from overseas distributors.', 'They are currently on sale.', 'They are the only products that qualify for an event.', 'D', 'Đáp án D là chính xác. Người nói cho biết rằng chỉ có các sản phẩm mang thương hiệu Shopsmart mới đủ điều kiện tham gia sự kiện. Cụ thể, họ nói: "This offer is good only for Shopsmart-brand canned goods." (Ưu đãi này chỉ áp dụng cho hàng đóng hộp mang thương hiệu Shopsmart.)
Dịch câu hỏi: Người nói nói gì về một số sản phẩm Shopsmart?
Dịch các đáp án:
A. Chúng không có sẵn tại tất cả các địa điểm Shopsmart.
B. Chúng được mua từ các nhà phân phối nước ngoài.
C. Chúng hiện đang được giảm giá.
D. Chúng là những sản phẩm duy nhất đủ điều kiện cho một sự kiện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1731, 81, '2023/test2/audio/test2_question_89_91.mp3', NULL, 'M-Au Hi, Mr. Collins. I''m calling from Silva''s Flooring. I was about to place your order for the maple floors that you wanted me to put in, but I decided to call you first. I just found out that the hardwood distributor has lowered the price of the oak flooring. I think you originally preferred oak but decided it was too expensive.
The reduction looks to be about fifteen percent. Please call me back and let me know if I should still order the maple for you or if you would prefer that I order the oak.', 'M-Nam: Xin chào, ông Collins. Tôi gọi từ Silva''s Flooring. Tôi đang định đặt hàng sàn gỗ phong mà ông muốn tôi lắp đặt, nhưng tôi quyết định gọi cho ông trước. Tôi vừa phát hiện ra rằng nhà phân phối gỗ cứng đã giảm giá sàn gỗ sồi. Tôi nghĩ ban đầu ông thích gỗ sồi nhưng quyết định nó quá đắt.
Mức giảm có vẻ khoảng mười lăm phần trăm. Vui lòng gọi lại cho tôi và cho tôi biết liệu tôi vẫn nên đặt hàng gỗ phong cho ông hay ông muốn tôi đặt hàng gỗ sồi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2289, 1731, 89, 'What work was the speaker hired to do?', 'Deliver firewood', 'Repair a roof', 'Install flooring', 'Complete a landscaping job', 'C', 'Đáp án C là chính xác. Người nói được thuê để lắp đặt sàn nhà. Điều này được thể hiện rõ khi anh ta nói về việc đặt hàng sàn gỗ phong và sàn gỗ sồi.
Dịch câu hỏi: Người nói được thuê để làm công việc gì?
Dịch các đáp án:
A. Giao củi đốt
B. Sửa chữa mái nhà
C. Lắp đặt sàn nhà
D. Hoàn thành một công việc cảnh quan');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1732, 81, '2023/test2/audio/test2_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2290, 1732, 90, 'What does the speaker say about the distributor?', 'It lowered a price.', 'It is no longer in business.', 'It expects a delay.', 'It has not responded to his request.', 'A', 'Đáp án A là chính xác. Người nói cho biết nhà phân phối đã giảm giá. Cụ thể, anh ta nói: "I just found out that the hardwood distributor has lowered the price of the oak flooring." (Tôi vừa phát hiện ra rằng nhà phân phối gỗ cứng đã giảm giá sàn gỗ sồi.)
Dịch câu hỏi: Người nói nói gì về nhà phân phối?
Dịch các đáp án:
A. Nó đã giảm giá.
B. Nó không còn hoạt động kinh doanh nữa.
C. Nó dự kiến sẽ có sự chậm trễ.
D. Nó chưa phản hồi yêu cầu của anh ta.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1733, 81, '2023/test2/audio/test2_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2291, 1733, 91, 'Why did the speaker wait to place an order?', 'He is not sure what quantity is needed.', 'He wants a customer to reconsider a decision.', 'He forgot what the customer requested.', 'He learned that a product is no longer available.', 'B', 'Đáp án B là chính xác. Người nói chờ đợi để đặt hàng vì anh ta muốn khách hàng xem xét lại quyết định. Anh ta gọi cho khách hàng để thông báo về việc giảm giá sàn gỗ sồi và hỏi xem khách hàng có muốn thay đổi lựa chọn từ gỗ phong sang gỗ sồi không.
Dịch câu hỏi: Tại sao người nói chờ đợi để đặt hàng?
Dịch các đáp án:
A. Anh ta không chắc cần bao nhiêu số lượng.
B. Anh ta muốn khách hàng xem xét lại một quyết định.
C. Anh ta quên những gì khách hàng yêu cầu.
D. Anh ta biết rằng một sản phẩm không còn sẵn có nữa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1734, 81, '2023/test2/audio/test2_question_92_94.mp3', NULL, 'W-Am Welcome to the Central Valley Environmental Center. We''re so grateful to all of you, our volunteers, for coming out today to help with this project to install bluebird nest boxes. The Eastern bluebird is a native species that plays an important role in our environment, but it''s threatened by habitat loss and predation. We have numerous donated nest boxes here that will help protect our local bluebird population.
Remember that bluebirds prefer open woodlands and grasslands with scattered trees. Some suitable locations are already identified on the maps you''ve received.', 'W-Nữ: Chào mừng đến với Trung tâm Môi trường Central Valley. Chúng tôi rất biết ơn tất cả các bạn, những tình nguyện viên của chúng tôi, đã đến đây hôm nay để giúp đỡ dự án lắp đặt hộp tổ cho chim xanh. Chim xanh phía Đông là một loài bản địa đóng vai trò quan trọng trong môi trường của chúng ta, nhưng nó đang bị đe dọa bởi mất môi trường sống và săn bắt. Chúng tôi có nhiều hộp tổ được quyên góp ở đây sẽ giúp bảo vệ quần thể chim xanh địa phương của chúng ta.
Hãy nhớ rằng chim xanh thích những khu rừng thưa và đồng cỏ có cây rải rác. Một số vị trí phù hợp đã được xác định trên bản đồ mà các bạn đã nhận được.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2292, 1734, 92, 'Who most likely is the speaker?', 'A teacher in a classroom', 'A worker at an environmental center', 'A salesperson in a sporting goods store', 'A guide in a natural history museum', 'B', 'Đáp án B là chính xác. Người nói có khả năng là một nhân viên tại một trung tâm môi trường. Điều này được suy ra từ việc họ chào mừng mọi người đến Trung tâm Môi trường Central Valley và đang hướng dẫn các tình nguyện viên về một dự án bảo vệ môi trường.
Dịch câu hỏi: Người nói có khả năng là ai?
Dịch các đáp án:
A. Một giáo viên trong lớp học
B. Một nhân viên tại một trung tâm môi trường
C. Một nhân viên bán hàng trong cửa hàng đồ thể thao
D. Một hướng dẫn viên trong bảo tàng lịch sử tự nhiên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1735, 81, '2023/test2/audio/test2_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2293, 1735, 93, 'What is the purpose of the project?', 'To recruit volunteers', 'To release bluebirds into the wild', 'To provide shelter for bluebirds', 'To educate people about bluebirds', 'C', 'Đáp án C là chính xác. Mục đích của dự án là cung cấp nơi trú ẩn cho chim xanh. Điều này được thể hiện rõ khi người nói đề cập đến việc lắp đặt hộp tổ cho chim xanh để bảo vệ quần thể chim xanh địa phương.
Dịch câu hỏi: Mục đích của dự án là gì?
Dịch các đáp án:
A. Để tuyển tình nguyện viên
B. Để thả chim xanh vào tự nhiên
C. Để cung cấp nơi trú ẩn cho chim xanh
D. Để giáo dục mọi người về chim xanh');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1736, 81, '2023/test2/audio/test2_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2294, 1736, 94, 'What is marked on some maps?', 'Locations where work can be done', 'Flight patterns of bluebirds', 'The location of nearby attractions', 'Directions to the environmental center', 'A', 'Đáp án A là chính xác. Trên một số bản đồ đã đánh dấu các vị trí có thể thực hiện công việc. Người nói đề cập: "Some suitable locations are already identified on the maps you''ve received." (Một số vị trí phù hợp đã được xác định trên bản đồ mà các bạn đã nhận được.)
Dịch câu hỏi: Điều gì được đánh dấu trên một số bản đồ?
Dịch các đáp án:
A. Các vị trí có thể thực hiện công việc
B. Mô hình bay của chim xanh
C. Vị trí của các điểm thu hút gần đó
D. Chỉ đường đến trung tâm môi trường');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1737, 81, '2023/test2/audio/test2_question_95_97.mp3', '2023/test2/image/test2-p4-image-95.jpg', 'W-Br Hi, everyone! I want to update you on sales of our lines of dishware after the introduction of our holiday-themed patterns. Our everyday dishware continues to perform as expected. Also, I am pleased to report that our New Year plates are a resounding success: total wholesale orders have outpaced those of our popular Dawn series of fine china. We spent a lot on the design for New Year, so our CEO will be happy to learn that the investment has paid off. Looks like we will need to rethink the Harvest Festival brand, though. Unless total sales reach those of our Café series by next year, we may even discontinue it.', 'W-Nữ: Chào mọi người! Tôi muốn cập nhật cho các bạn về doanh số bán các dòng đồ dùng bàn ăn của chúng ta sau khi giới thiệu các mẫu theo chủ đề ngày lễ. Đồ dùng bàn ăn hàng ngày của chúng ta tiếp tục hoạt động như mong đợi. Ngoài ra, tôi vui mừng báo cáo rằng đĩa Năm Mới của chúng ta là một thành công vang dội: tổng đơn đặt hàng bán buôn đã vượt qua dòng sản phẩm Dawn phổ biến của chúng ta. Chúng ta đã chi rất nhiều cho thiết kế Năm Mới, vì vậy CEO của chúng ta sẽ rất vui khi biết rằng khoản đầu tư đã được đền đáp. Có vẻ như chúng ta sẽ cần phải suy nghĩ lại về thương hiệu Lễ hội Mùa gặt. Trừ khi tổng doanh số đạt được như dòng Café của chúng ta vào năm tới, chúng ta thậm chí có thể ngừng sản xuất nó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2295, 1737, 95, 'What product does the speaker''s company sell?', 'Bath towels', 'Dishware', 'Tablecloths', 'Drinking glasses', 'B', 'Đáp án B là chính xác. Công ty của người nói bán đồ dùng bàn ăn (dishware). Điều này được thể hiện rõ trong câu đầu tiên khi người nói đề cập đến "sales of our lines of dishware" (doanh số bán các dòng đồ dùng bàn ăn của chúng tôi).
Dịch câu hỏi: Công ty của người nói bán sản phẩm gì?
Dịch các đáp án:
A. Khăn tắm
B. Đồ dùng bàn ăn
C. Khăn trải bàn
D. Ly uống nước');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1738, 81, '2023/test2/audio/test2_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2296, 1738, 96, 'Why will the CEO be pleased?', 'The company bought a new warehouse.', 'Customer reviews have been positive.', 'Shipping costs have gone down.', 'An investment was successful.', 'D', 'Đáp án D là chính xác. CEO sẽ hài lòng vì một khoản đầu tư đã thành công. Người nói đề cập: "We spent a lot on the design for New Year, so our CEO will be happy to learn that the investment has paid off." (Chúng ta đã chi rất nhiều cho thiết kế Năm Mới, vì vậy CEO của chúng ta sẽ rất vui khi biết rằng khoản đầu tư đã được đền đáp.)
Dịch câu hỏi: Tại sao CEO sẽ hài lòng?
Dịch các đáp án:
A. Công ty đã mua một kho hàng mới.
B. Đánh giá của khách hàng đã tích cực.
C. Chi phí vận chuyển đã giảm.
D. Một khoản đầu tư đã thành công.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1739, 81, '2023/test2/audio/test2_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2297, 1739, 97, 'Look at the graphic. What number of orders does the speaker say the Harvest Festival pattern must reach?', '5,000', '2,000', '6,000', '200', 'B', 'Đáp án B là chính xác. Theo hình ảnh và nội dung của người nói, mẫu Harvest Festival phải đạt được số lượng đơn hàng của dòng Café, là 2,000. Người nói đề cập: "Unless total sales reach those of our Café series by next year, we may even discontinue it." (Trừ khi tổng doanh số đạt được như dòng Café của chúng ta vào năm tới, chúng ta thậm chí có thể ngừng sản xuất nó.)
Dịch câu hỏi: Nhìn vào hình ảnh. Người nói cho biết mẫu Harvest Festival phải đạt được số lượng đơn hàng là bao nhiêu?
Dịch các đáp án:
A. 5,000
B. 2,000
C. 6,000
D. 200');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1740, 81, '2023/test2/audio/test2_question_98_100.mp3', '2023/test2/image/test2-p4-image-98.jpg', 'M-Au I''d like to welcome all of you to your first day of work at the Wildcats customer service office. Baseball season starts in exactly one month. We expect ticket sales to be very good because the Wildcats had such a great season last year. As you can see on the chart, we have four packages. Make sure you let our customers know about the new Sunday package. It includes tickets for every Sunday home game throughout the season. Our Friday night package, holiday package, and discount package were available last year and should remain popular.', 'M-Nam: Tôi xin chào mừng tất cả các bạn đến ngày làm việc đầu tiên tại văn phòng dịch vụ khách hàng của Wildcats. Mùa bóng chày bắt đầu trong đúng một tháng nữa. Chúng tôi kỳ vọng doanh số bán vé sẽ rất tốt vì Wildcats đã có một mùa giải tuyệt vời năm ngoái. Như các bạn có thể thấy trên biểu đồ, chúng ta có bốn gói. Hãy đảm bảo rằng các bạn thông báo cho khách hàng về gói Chủ nhật mới. Nó bao gồm vé cho mọi trận đấu sân nhà vào Chủ nhật trong suốt mùa giải. Gói tối thứ Sáu, gói ngày lễ và gói giảm giá của chúng ta đã có sẵn năm ngoái và nên vẫn sẽ được ưa chuộng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2298, 1740, 98, 'Who most likely is the speaker?', 'A baseball player', 'A travel agent', 'A new job applicant', 'A customer service trainer', 'D', 'Đáp án D là chính xác. Người nói có khả năng là một huấn luyện viên dịch vụ khách hàng. Điều này được suy ra từ việc họ đang chào đón nhân viên mới vào ngày làm việc đầu tiên và đang hướng dẫn về các gói vé và cách bán hàng.
Dịch câu hỏi: Người nói có khả năng là ai?
Dịch các đáp án:
A. Một cầu thủ bóng chày
B. Một đại lý du lịch
C. Một ứng viên công việc mới
D. Một huấn luyện viên dịch vụ khách hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1741, 81, '2023/test2/audio/test2_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2299, 1741, 99, 'Why are ticket sales expected to be good?', 'The prices have been reduced.', 'The team''s previous season was successful.', 'There is a new advertising campaign.', 'The team has many new players.', 'B', 'Đáp án B là chính xác. Doanh số bán vé được kỳ vọng sẽ tốt vì đội bóng đã có một mùa giải thành công trước đó. Người nói đề cập: "We expect ticket sales to be very good because the Wildcats had such a great season last year." (Chúng tôi kỳ vọng doanh số bán vé sẽ rất tốt vì Wildcats đã có một mùa giải tuyệt vời năm ngoái.)
Dịch câu hỏi: Tại sao doanh số bán vé được kỳ vọng sẽ tốt?
Dịch các đáp án:
A. Giá đã được giảm.
B. Mùa giải trước của đội bóng đã thành công.
C. Có một chiến dịch quảng cáo mới.
D. Đội bóng có nhiều cầu thủ mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1742, 81, '2023/test2/audio/test2_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2300, 1742, 100, 'Look at the graphic. How many games are included in the new ticket package that the speaker describes?', '6', '16', '19', '36', 'B', 'Đáp án B là chính xác. Theo hình ảnh, gói vé mới mà người nói mô tả (gói Sunday) bao gồm 16 trận đấu.
Dịch câu hỏi: Nhìn vào hình ảnh. Có bao nhiêu trận đấu được bao gồm trong gói vé mới mà người nói mô tả?
Dịch các đáp án:
A. 6
B. 16
C. 19
D. 36');;

-- Data for 2023 Test2 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1743, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2301, 1743, 101, 'Last week, three staff members ----- at the local library''s book sale.', 'volunteer', 'voluntary', 'volunteered', 'volunteering', 'C', 'Đáp án C (volunteered) là đúng. Câu này yêu cầu một động từ ở thì quá khứ đơn để phù hợp với "Last week". "Volunteered" là dạng quá khứ của động từ "volunteer", phù hợp với ngữ cảnh về hành động tình nguyện trong quá khứ.
Dịch câu hỏi: Tuần trước, ba nhân viên đã —- tại buổi bán sách của thư viện địa phương.
Dịch đáp án:
A. volunteer (động từ nguyên thể: tình nguyện)
B. voluntary (tính từ: tự nguyện)
C. volunteered (động từ quá khứ: đã tình nguyện)
D. volunteering (danh động từ: việc tình nguyện)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1744, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2302, 1744, 102, 'In April, prices are expected to drop ------ 20 percent.', 'with', 'on', 'since', 'by', 'D', 'Đáp án D (by) là đúng. Khi nói về mức độ giảm giá hoặc thay đổi, ta sử dụng "by" trước con số phần trăm. Cấu trúc: "drop/increase by + percentage".
Dịch câu hỏi: Vào tháng Tư, giá cả được dự kiến sẽ giảm ------ 20 phần trăm.
Dịch đáp án:
A. with (giới từ: với)
B. on (giới từ: trên)
C. since (giới từ/liên từ: từ khi)
D. by (giới từ: bởi, khoảng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1745, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2303, 1745, 103, 'The project management software allows staff to handle many tasks by ------.', 'themselves', 'them', 'they', 'theirs', 'A', 'Đáp án A (themselves) là đúng. Sau giới từ "by", ta cần một đại từ phản thân để chỉ chủ thể thực hiện hành động. "Themselves" là đại từ phản thân số nhiều, phù hợp với "staff".
Dịch câu hỏi: Phần mềm quản lý dự án cho phép nhân viên xử lý nhiều nhiệm vụ bằng ------.
Dịch đáp án:
A. themselves (đại từ phản thân: chính họ)
B. them (đại từ tân ngữ: họ)
C. they (đại từ chủ ngữ: họ)
D. theirs (đại từ sở hữu: của họ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1746, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2304, 1746, 104, 'Local manufacturers have ----- shipping times by hiring external shipping companies.', 'attempted', 'reduced', 'weakened', 'finished', 'B', 'Đáp án B (reduced) là đúng. Trong ngữ cảnh này, "reduced" (giảm) phù hợp nhất để mô tả việc cắt giảm thời gian vận chuyển. Cấu trúc: "have + past participle" (thì hiện tại hoàn thành).
Dịch câu hỏi: Các nhà sản xuất địa phương đã - thời gian vận chuyển bằng cách thuê các công ty vận chuyển bên ngoài.
Dịch đáp án:
A. attempted (động từ quá khứ: đã cố gắng)
B. reduced (động từ quá khứ: đã giảm)
C. weakened (động từ quá khứ: đã làm yếu đi)
D. finished (động từ quá khứ: đã hoàn thành)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1747, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2305, 1747, 105, 'Gramwell Corporation may charge an -—-----fee for last month''s work.', 'add', 'adding', 'additionally', 'additional', 'D', 'Đáp án D (additional) là đúng. Câu này cần một tính từ để mô tả danh từ "fee". "Additional" (thêm, bổ sung) là tính từ phù hợp để mô tả một khoản phí bổ sung.
Dịch câu hỏi: Công ty Gramwell có thể tính một khoản phí -—----- cho công việc của tháng trước.
Dịch đáp án:
A. add (động từ: thêm vào)
B. adding (động từ -ing: đang thêm)
C. additionally (trạng từ: thêm nữa)
D. additional (tính từ: thêm, bổ sung)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1748, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2306, 1748, 106, 'Ms. Kang prefers to complete ----- current project before transferring to the finance department.', 'herself', 'she', 'her', 'hers', 'C', 'Đáp án C (her) là đúng. Câu này cần một tính từ sở hữu để chỉ quyền sở hữu của dự án. "Her" là tính từ sở hữu phù hợp cho ngôi thứ ba số ít nữ.
Dịch câu hỏi: Cô Kang muốn hoàn thành ----- dự án hiện tại trước khi chuyển sang bộ phận tài chính.
Dịch đáp án:
A. herself (đại từ phản thân: chính cô ấy)
B. she (đại từ chủ ngữ: cô ấy)
C. her (tính từ sở hữu: của cô ấy)
D. hers (đại từ sở hữu: của cô ấy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1749, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2307, 1749, 107, 'There are --- criteria that must be met for a password to be changed successfully.', 'specific', 'to specify', 'specify', 'specifies', 'A', 'Đáp án A (specific) là đúng. Câu này cần một tính từ để mô tả danh từ "criteria". "Specific" (cụ thể) là tính từ phù hợp để mô tả các tiêu chí.
Dịch câu hỏi: Có --- tiêu chí phải được đáp ứng để mật khẩu được thay đổi thành công.
Dịch đáp án:
A. specific (tính từ: cụ thể)
B. to specify (động từ nguyên mẫu: để chỉ rõ)
C. specify (động từ nguyên thể: chỉ rõ)
D. specifies (động từ ngôi thứ 3 số ít: chỉ rõ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1750, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2308, 1750, 108, 'To assist the costume designers in preparing for the film, fabric samples can be sent to the ----- designer.', 'leader', 'leads', 'led', 'lead', 'D', 'Đáp án D (lead) là đúng. Trong ngữ cảnh này, "lead" được sử dụng như một tính từ có nghĩa là "chính, hàng đầu". Cấu trúc: "lead + noun".
Dịch câu hỏi: Để hỗ trợ các nhà thiết kế trang phục chuẩn bị cho bộ phim, các mẫu vải có thể được gửi đến nhà thiết kế --.
Dịch đáp án:
A. leader (danh từ: người lãnh đạo)
B. leads (động từ ngôi thứ 3 số ít: dẫn đầu)
C. led (động từ quá khứ: đã dẫn đầu)
D. lead (tính từ: chính, hàng đầu)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1751, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2309, 1751, 109, 'The product presentation has been fully rehearsed, so it can be --- any day next week.', 'film', 'filmed', 'films', 'to film', 'B', 'Đáp án B (filmed) là đúng. Câu này yêu cầu một động từ ở dạng bị động. Cấu trúc: "can be + past participle". "Filmed" là dạng quá khứ phân từ của động từ "film", phù hợp để tạo thành cấu trúc bị động.
Dịch câu hỏi: Bài thuyết trình sản phẩm đã được tập dợt đầy đủ, vì vậy nó có thể được --- vào bất kỳ ngày nào trong tuần tới.
Dịch đáp án:
A. film (động từ nguyên thể: quay phim)
B. filmed (động từ quá khứ phân từ: được quay)
C. films (động từ ngôi thứ 3 số ít: quay phim)
D. to film (động từ nguyên mẫu: để quay phim)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1752, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2310, 1752, 110, 'The new logo is part of a comprehensive effort to ----- the brand''s identity and appeal to younger consumers.', 'remind', 'refer', 'refresh', 'repeat', 'C', 'Đáp án C (refresh) là đúng. Trong ngữ cảnh này, "refresh" (làm mới) phù hợp nhất để mô tả việc cải thiện và làm mới lại nhận diện thương hiệu.
Dịch câu hỏi: Logo mới là một phần của nỗ lực toàn diện nhằm ----- nhận diện thương hiệu và thu hút người tiêu dùng trẻ tuổi hơn.
Dịch đáp án:
A. remind (động từ: nhắc nhở)
B. refer (động từ: tham khảo)
C. refresh (động từ: làm mới)
D. repeat (động từ: lặp lại)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1753, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2311, 1753, 111, 'The latest sport utility vehicle from Bondon Automotive can carry eight people ----.', 'comfortable', 'comfort', 'comfortably', 'comforting', 'C', 'Đáp án C (comfortably) là đúng. Câu này cần một trạng từ để mô tả cách thức mà xe có thể chở người. "Comfortably" (một cách thoải mái) là trạng từ phù hợp để mô tả cách thức này.
Dịch câu hỏi: Xe thể thao đa dụng mới nhất từ Bondon Automotive có thể chở tám người ----.
Dịch đáp án:
A. comfortable (tính từ: thoải mái)
B. comfort (danh từ: sự thoải mái)
C. comfortably (trạng từ: một cách thoải mái)
D. comforting (tính từ: an ủi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1754, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2312, 1754, 112, '----- deciding to replace the food-service provider, the management team conducted a survey of all employees.', 'Before', 'Unless', 'Whether', 'Except', 'A', 'Đáp án A (Before) là đúng. Câu này cần một liên từ thời gian để chỉ ra hành động xảy ra trước khi quyết định được đưa ra. "Before" (trước khi) là liên từ phù hợp trong ngữ cảnh này.
Dịch câu hỏi: -- quyết định thay thế nhà cung cấp dịch vụ thực phẩm, đội ngũ quản lý đã tiến hành một cuộc khảo sát với tất cả nhân viên.
Dịch đáp án:
A. Before (liên từ: trước khi)
B. Unless (liên từ: trừ phi)
C. Whether (liên từ: liệu rằng)
D. Except (giới từ: ngoại trừ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1755, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2313, 1755, 113, 'Although Mr. Cho was ------ about transferring to the Houston office, he is now working there confidently and productively.', 'hesitate', 'hesitant', 'hesitation', 'hesitated', 'B', 'Đáp án B (hesitant) là đúng. Câu này cần một tính từ để mô tả trạng thái tâm lý của Mr. Cho. "Hesitant" (do dự) là tính từ phù hợp để mô tả cảm xúc của ông ấy về việc chuyển công tác.
Dịch câu hỏi: Mặc dù ông Cho đã ------ về việc chuyển đến văn phòng Houston, giờ đây ông ấy đang làm việc ở đó một cách tự tin và hiệu quả.
Dịch đáp án:
A. hesitate (động từ: do dự)
B. hesitant (tính từ: do dự)
C. hesitation (danh từ: sự do dự)
D. hesitated (động từ quá khứ: đã do dự)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1756, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2314, 1756, 114, 'The personnel office should be contacted about unpaid leave ----- supervisors cannot approve it.', 'as', 'either', 'like', 'instead', 'A', 'Đáp án A (as) là đúng. Trong ngữ cảnh này, "as" được sử dụng như một liên từ để giới thiệu lý do. Cấu trúc: "as + clause" (vì, bởi vì).
Dịch câu hỏi: Văn phòng nhân sự nên được liên hệ về việc nghỉ không lương ----- các giám sát viên không thể phê duyệt nó.
Dịch đáp án:
A. as (liên từ: vì)
B. either (liên từ: hoặc)
C. like (giới từ: như)
D. instead (trạng từ: thay vào đó)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1757, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2315, 1757, 115, 'Yesterday the board voted to ----- with discussions about acquiring Atlasburg Financial.', 'proceed', 'proceeded', 'proceeding', 'proceeds', 'A', 'Đáp án A (proceed) là đúng. Câu này yêu cầu một động từ nguyên thể sau "to". "Proceed" (tiến hành) là động từ nguyên thể phù hợp trong ngữ cảnh này.
Dịch câu hỏi: Hôm qua hội đồng quản trị đã bỏ phiếu để -- với các cuộc thảo luận về việc mua lại Atlasburg Financial.
Dịch đáp án:
A. proceed (động từ nguyên thể: tiến hành)
B. proceeded (động từ quá khứ: đã tiến hành)
C. proceeding (danh động từ: việc tiến hành)
D. proceeds (động từ ngôi thứ 3 số ít: tiến hành)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1758, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2316, 1758, 116, 'Robles Corporation encourages employees to work toward a ---- goal, rather than pursuing individual interests.', 'common', 'regular', 'usual', 'plain', 'A', 'Đáp án A (common) là đúng. Trong ngữ cảnh này, "common" (chung) phù hợp nhất để mô tả một mục tiêu được chia sẻ bởi tất cả nhân viên, trái ngược với lợi ích cá nhân.
Dịch câu hỏi: Công ty Robles khuyến khích nhân viên làm việc hướng tới một mục tiêu ----, thay vì theo đuổi lợi ích cá nhân.
Dịch đáp án:
A. common (tính từ: chung)
B. regular (tính từ: thường xuyên)
C. usual (tính từ: thông thường)
D. plain (tính từ: đơn giản)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1759, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2317, 1759, 117, 'The ----- in the brochure are an accurate representation of what guests staying at the resort can expect to find.', 'image', 'images', 'imaged', 'imaging', 'B', 'Đáp án B (images) là đúng. Câu này yêu cầu một danh từ số nhiều làm chủ ngữ để phù hợp với động từ số nhiều "are". "Images" (hình ảnh) là dạng số nhiều phù hợp.
Dịch câu hỏi: Những ----- trong tờ rơi là đại diện chính xác cho những gì khách lưu trú tại khu nghỉ dưỡng có thể mong đợi tìm thấy.
Dịch đáp án:
A. image (danh từ số ít: hình ảnh)
B. images (danh từ số nhiều: hình ảnh)
C. imaged (động từ quá khứ: đã hình dung)
D. imaging (danh động từ: việc tạo hình ảnh)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1760, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2318, 1760, 118, 'Current employees interested in the new managerial position should ----- about the internal hiring process.', 'provide', 'inquire', 'evaluate', 'control', 'B', 'Đáp án B (inquire) là đúng. Trong ngữ cảnh này, "inquire" (hỏi thông tin) phù hợp nhất để mô tả hành động tìm hiểu về quy trình tuyển dụng nội bộ.
Dịch câu hỏi: Nhân viên hiện tại quan tâm đến vị trí quản lý mới nên ----- về quy trình tuyển dụng nội bộ.
Dịch đáp án:
A. provide (động từ: cung cấp)
B. inquire (động từ: hỏi thông tin)
C. evaluate (động từ: đánh giá)
D. control (động từ: kiểm soát)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1761, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2319, 1761, 119, 'Colleagues in the accounting department consider the matter closed and -----cannot provide more input.', 'large', 'consequently', 'very', 'anyone', 'B', 'Đáp án B (consequently) là đúng. Từ này được sử dụng như một liên từ để kết nối hai mệnh đề và chỉ ra mối quan hệ nhân quả. "Consequently" (do đó) phù hợp để liên kết việc vấn đề đã được giải quyết với kết quả là không thể cung cấp thêm ý kiến.
Dịch câu hỏi: Các đồng nghiệp trong phòng kế toán coi vấn đề đã được giải quyết và ----- không thể cung cấp thêm ý kiến.
Dịch đáp án:
A. large (tính từ: lớn)
B. consequently (liên từ: do đó)
C. very (trạng từ: rất)
D. anyone (đại từ: bất kỳ ai)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1762, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2320, 1762, 120, 'The CEO hopes that the consultant''s advice will ultimately --- higher profits for the company.', 'yield', 'submit', 'invent', 'resolve', 'A', 'Đáp án A (yield) là đúng. Trong ngữ cảnh này, "yield" (mang lại, tạo ra) phù hợp nhất để mô tả kết quả mong đợi từ lời khuyên của chuyên gia tư vấn.
Dịch câu hỏi: CEO hy vọng rằng lời khuyên của chuyên gia tư vấn cuối cùng sẽ --- lợi nhuận cao hơn cho công ty.
Dịch đáp án:
A. yield (động từ: mang lại, tạo ra)
B. submit (động từ: nộp, đệ trình)
C. invent (động từ: phát minh)
D. resolve (động từ: giải quyết)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1763, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2321, 1763, 121, 'A team of experts is reviewing the contract from a financial --- so please do not share it with the client yet.', 'perspective', 'belief', 'movement', 'proportion', 'A', 'Đáp án A (perspective) là đúng. "Perspective" (quan điểm, góc nhìn) phù hợp nhất trong ngữ cảnh này, chỉ ra rằng hợp đồng đang được xem xét từ góc độ tài chính.
Dịch câu hỏi: Một nhóm chuyên gia đang xem xét hợp đồng từ --- tài chính, vì vậy vui lòng chưa chia sẻ nó với khách hàng.
Dịch đáp án:
A. perspective (danh từ: quan điểm, góc nhìn)
B. belief (danh từ: niềm tin)
C. movement (danh từ: sự chuyển động)
D. proportion (danh từ: tỷ lệ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1764, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2322, 1764, 122, 'To prevent noise that is distracting to performers, the lobby gift shop is ------ open during performances.', 'almost', 'even', 'never', 'soon', 'C', 'Đáp án C (never) là đúng. Trong ngữ cảnh này, "never" (không bao giờ) phù hợp nhất để chỉ ra rằng cửa hàng quà tặng không mở cửa trong suốt thời gian biểu diễn để tránh gây ồn.
Dịch câu hỏi: Để ngăn chặn tiếng ồn gây mất tập trung cho các nghệ sĩ biểu diễn, cửa hàng quà tặng ở sảnh ------- mở cửa trong thời gian biểu diễn.
Dịch đáp án:
A. almost (trạng từ: gần như)
B. even (trạng từ: thậm chí)
C. never (trạng từ: không bao giờ)
D. soon (trạng từ: sớm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1765, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2323, 1765, 123, 'Zuper Brite lightbulbs ----- reduce energy consumption when compared with standard incandescent lightbulbs.', 'great', 'greater', 'greatest', 'greatly', 'D', 'Đáp án D (greatly) là đúng. Câu này cần một trạng từ để mô tả mức độ giảm tiêu thụ năng lượng. "Greatly" (rất nhiều, đáng kể) là trạng từ phù hợp để mô tả mức độ giảm.
Dịch câu hỏi: Bóng đèn Zuper Brite -- giảm tiêu thụ năng lượng khi so sánh với bóng đèn sợi đốt tiêu chuẩn.
Dịch đáp án:
A. great (tính từ: tuyệt vời)
B. greater (tính từ so sánh: lớn hơn)
C. greatest (tính từ so sánh nhất: lớn nhất)
D. greatly (trạng từ: rất nhiều, đáng kể)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1766, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2324, 1766, 124, 'The airport''s proposed --- project will include two remodeled terminals and an updated transportation system.', 'encouragement', 'modernization', 'assistant', 'importance', 'B', 'Đáp án B (modernization) là đúng. "Modernization" (hiện đại hóa) phù hợp nhất để mô tả dự án cải tạo và cập nhật cơ sở hạ tầng sân bay.
Dịch câu hỏi: Dự án --- đề xuất của sân bay sẽ bao gồm hai nhà ga được cải tạo và hệ thống giao thông được cập nhật.
Dịch đáp án:
A. encouragement (danh từ: sự khuyến khích)
B. modernization (danh từ: sự hiện đại hóa)
C. assistant (danh từ: trợ lý)
D. importance (danh từ: tầm quan trọng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1767, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2325, 1767, 125, 'Market Research is the ----- of the company concerned with better understanding our clients'' needs.', 'divisional', 'divisible', 'division', 'divide', 'C', 'Đáp án C (division) là đúng. Câu này cần một danh từ để chỉ một bộ phận của công ty. "Division" (phòng ban, bộ phận) là danh từ phù hợp trong ngữ cảnh này.
Dịch câu hỏi: Nghiên cứu thị trường là — - của công ty liên quan đến việc hiểu rõ hơn nhu cầu của khách hàng.
Dịch đáp án:
A. divisional (tính từ: thuộc về bộ phận)
B. divisible (tính từ: có thể chia)
C. division (danh từ: phòng ban, bộ phận)
D. divide (động từ: chia)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1768, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2326, 1768, 126, 'Mr. Tanaka was so pleased by the quarterly performance report ---- he canceled the weekly updates.', 'in case', 'which', 'that', 'seldom', 'C', 'Đáp án C (that) là đúng. Câu này sử dụng cấu trúc "so + adjective + that + clause" để chỉ kết quả. "That" là liên từ phù hợp để kết nối hai mệnh đề trong cấu trúc này.
Dịch câu hỏi: Ông Tanaka rất hài lòng với báo cáo hiệu suất hàng quý ---- ông đã hủy bỏ các cập nhật hàng tuần.
Dịch đáp án:
A. in case (cụm từ: trong trường hợp)
B. which (đại từ quan hệ: cái mà)
C. that (liên từ: đến nỗi mà)
D. seldom (trạng từ: hiếm khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1769, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2327, 1769, 127, 'Quincycom''s price increase is justifiable ----- there is an improvement in the quality of the Internet service we receive.', 'whereas', 'likewise', 'because of', 'only if', 'D', 'Đáp án D (only if) là đúng. Cụm từ "only if" được sử dụng để chỉ ra một điều kiện cần thiết. Trong ngữ cảnh này, nó phù hợp để liên kết việc tăng giá với điều kiện cải thiện chất lượng dịch vụ.
Dịch câu hỏi: Việc tăng giá của Quincycom là hợp lý ----- có sự cải thiện trong chất lượng dịch vụ Internet mà chúng ta nhận được.
Dịch đáp án:
A. whereas (liên từ: trong khi)
B. likewise (trạng từ: tương tự)
C. because of (cụm từ: bởi vì)
D. only if (cụm từ: chỉ khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1770, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2328, 1770, 128, 'The chart attached to this e-mail presents a ----- of Vivasyco''s latest smartphone with a model from Eustace Tech.', 'comparison', 'pronouncement', 'guideline', 'publicity', 'A', 'Đáp án A (comparison) là đúng. "Comparison" (sự so sánh) phù hợp nhất trong ngữ cảnh về việc đối chiếu hai mẫu điện thoại thông minh từ các công ty khác nhau.
Dịch câu hỏi: Biểu đồ đính kèm email này trình bày một ----- giữa điện thoại thông minh mới nhất của Vivasyco với một mẫu từ Eustace Tech.
Dịch đáp án:
A. comparison (danh từ: sự so sánh)
B. pronouncement (danh từ: tuyên bố)
C. guideline (danh từ: hướng dẫn)
D. publicity (danh từ: sự quảng bá)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1771, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2329, 1771, 129, 'It is the catering director''s ---- to inform the chef of the intended menu well in advance of the event.', 'obliged', 'obligated', 'obligatory', 'obligation', 'D', 'Đáp án D (obligation) là đúng. Câu này cần một danh từ để chỉ trách nhiệm hoặc nghĩa vụ. "Obligation" (nghĩa vụ) là danh từ phù hợp trong ngữ cảnh này.
Dịch câu hỏi: Đó là ---- của giám đốc ẩm thực để thông báo cho đầu bếp về thực đơn dự kiến trước sự kiện.
Dịch đáp án:
A. obliged (tính từ: bắt buộc)
B. obligated (tính từ: có nghĩa vụ)
C. obligatory (tính từ: bắt buộc)
D. obligation (danh từ: nghĩa vụ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1772, 82, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2330, 1772, 130, 'Given her experience in health care, Ms. Chung is --- well suited to manage the company''s wellness program.', 'formerly', 'expectantly', 'particularly', 'avoidably', 'C', 'Đáp án C (particularly) là đúng. "Particularly" (đặc biệt) là trạng từ phù hợp nhất để nhấn mạnh sự phù hợp của Ms. Chung với vị trí quản lý chương trình sức khỏe.
Dịch câu hỏi:Với kinh nghiệm của mình trong lĩnh vực chăm sóc sức khỏe, cô Chung si - phù hợp với việc quản lý chương trình chăm sóc sức khỏe của công ty.
(A) trước đây
(B) mong đợi
(C) đặc biệt
(D) có thể tránh được');;

