INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2349, 1779, 149, 'What is indicated about Clean House Janitorial Services?', 'It was founded in 1972.', 'It specializes in office cleaning.', 'It offers a discount on carpet cleaning.', 'It prefers online communication.', 'A', 'Đáp án đúng là A. Quảng cáo cho biết Clean House Janitorial Services được thành lập vào năm 1972. Điều này được nêu rõ trong dòng "Copper County''s trustworthy and efficient cleaning solution since 1972".
