INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2402, 1794, 2, NULL, 'There''s long grass behind a fence.', 'There''s a door open beneath a light.', 'There''s a pot with flowers by the door.', 'There''s a window overlooking a garden.', 'D', 'A: Có cỏ dài phía sau hàng rào.
