INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2405, 1797, 5, NULL, 'A tablecloth is folded on a chair.', 'A dining area is prepared for a meal.', 'Some chairs are being moved to a different room.', 'Cups and plates are being filled.', 'B', 'A: Một tấm khăn trải bàn được gấp trên một chiếc ghế.
