INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2406, 1798, 6, NULL, 'Some people have gathered in an outdoor seating area.', 'Umbrellas are covering a buffet counter.', 'Some chairs are stacked on the lawn.', 'Some people are laughing at a performance.', 'A', 'A: Một số người đã tụ tập trong khu vực ngồi ngoài trời.
