INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2408, 1800, 8, 'What dinner specials do you have today?', 'We have baked salmon.', 'For the first time.', 'No, I haven''t.', NULL, 'A', 'Hôm nay các món đặc biệt cho bữa tối là gì?
