INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2409, 1801, 9, 'When will the order be delivered?', 'Not until Wednesday afternoon.', 'It''s time to put them away.', 'The light is on in the mail room.', NULL, 'A', 'Khi nào đơn hàng sẽ được giao?
