INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2410, 1802, 10, 'What''s the monthly membership fee for that service?', 'Twenty euros.', 'Next month.', 'Don''t let me forget.', NULL, 'A', 'Phí thành viên hàng tháng cho dịch vụ đó là bao nhiêu?
