INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2411, 1803, 11, 'Did you receive the e-mail I sent?', 'I need a receipt for that.', 'Call a delivery service.', 'I haven''t looked at my computer today.', NULL, 'C', 'Bạn đã nhận được e-mail tôi gửi chưa?
