INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2412, 1804, 12, 'Why don''t you have the meeting this afternoon?', 'Just past the library and across the street.', 'Otherwise, I think it''s fine.', 'Because we have a lot to do today.', NULL, 'C', 'Tại sao chiều nay bạn không họp?
