INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2413, 1805, 13, 'Where did you post the schedule?', 'I hung a copy on the conference room door.', 'In a few hours.', 'Are you sure you submitted it?', NULL, 'A', 'Bạn đã đăng lịch trình ở đâu?
