INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2414, 1806, 14, 'Who is leading the safety seminar?', 'That''s what he said.', 'Elizabeth will do it.', 'Whenever management prefers.', NULL, 'B', 'Ai đang dẫn dắt buổi hội thảo về an toàn?
