INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2417, 1809, 17, 'I''d like to schedule your performance review meeting.', 'That is a high-performing team.', 'The food here is very good.', 'OK, let me look at my calendar.', NULL, 'C', 'Tôi muốn lên lịch cuộc họp đánh giá hiệu suất của bạn.
