INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2422, 1814, 22, 'Do you take the bus or train to work?', 'love to travel.', 'I prefer to drive.', 'I only work on Tuesdays.', NULL, 'B', 'Bạn đi xe buýt hay tàu điện đến nơi làm việc?
