INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2423, 1815, 23, 'Would you like me to make the reservation for you?', 'The hotel has a fitness club.', 'No, I haven''t heard of it.', 'Sure, let me find the form.', NULL, 'C', 'Bạn có muốn tôi đặt chỗ cho bạn không?
