INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2425, 1817, 25, 'What do you think of the highlighted paragraphs in this document?', 'I think they need further revisions.', 'There''s some storage space upstairs.', 'This room has very good lighting.', NULL, 'A', 'Bạn nghĩ gì về các đoạn được đánh dấu trong tài liệu này?
