INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2426, 1818, 26, 'Who''s going to receive the final delivery?', 'When everyone leaves the office.', 'I can wait for it.', 'Yes, but only on Fridays.', NULL, 'B', 'Ai sẽ nhận được đơn hàng cuối cùng?
