INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2427, 1819, 27, 'I could book our flights now, right?', 'It''s a long flight.', 'The trade show hasn''t been confirmed.', 'It''s in the other room.', NULL, 'B', 'Tôi có thể đặt vé máy bay cho chúng ta bây giờ, đúng không?
A: Đây là một chuyến bay dài.
B: Triển lãm thương mại chưa được xác nhận.
C: Nó ở trong phòng khác.');;
