INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2428, 1820, 28, 'Why do we have to reschedule this event?', 'This weekend or maybe early next week.', 'I will do it as soon as possible.', 'My doctor''s appointment couldn''t be moved.', NULL, 'C', 'Tại sao chúng ta phải dời lịch sự kiện này?
A: Cuối tuần này hoặc có thể đầu tuần tới.
B: Tôi sẽ làm nó càng sớm càng tốt.
C: Cuộc hẹn với bác sĩ của tôi không thể di chuyển được.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1821, 86, '2023/test3/audio/test3_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2429, 1821, 29, 'We should really consider expanding our storefront.', 'Didn''t you see the contract for the work?', 'I don''t know how far it is.', 'We could borrow one for you.', NULL, 'A', 'Chúng ta thực sự nên xem xét việc mở rộng mặt tiền cửa hàng của mình.
(A) Bạn không thấy hợp đồng làm việc à?
(B) Tôi không biết nó cách đây bao xa.
(C) Chúng tôi có thể mượn một cái cho bạn .');;
