INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2430, 1822, 30, 'Do you know whose jacket that is in the conference room?', 'Sure, if they''re already planning to go.', 'A few people have blue ones like that.', 'Yes, Janelle usually orders them for us.', NULL, 'B', 'Bạn có biết chiếc áo khoác trong phòng họp của ai không?
(A) Chắc chắn rồi, nếu họ đã định đi.
(B) Một số người có chiếc áo khoác màu xanh như vậy.
(C) Vâng, Janelle thường đặt hàng chúng cho chúng tôi.');;
