INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2601, 1942, 1, NULL, 'A man is looking out a window.', 'A man is fixing a ceiling tile.', 'A man is reaching for a coat.', 'A man is installing a wooden floor.', 'C', 'A: Một người đàn ông đang nhìn ra cửa sổ.
B: Một người đàn ông đang sửa chữa một tấm ngói trần.
C: Một người đàn ông đang vươn tay lấy áo khoác.
