INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (1943, 92, '2023/test4/audio/test4_question_2.mp3', '2023/test4/image/test4-image-2.jpg', NULL, NULL);;
