INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2801, 2091, 1, NULL, 'He''s working on a puzzle.', 'He''s lying on a sofa.', 'He''s reaching for a book.', 'He''s putting on a sweater.', 'A', 'A: Anh ấy đang giải một câu đố.
