INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2802, 2092, 2, NULL, 'She''s organizing some books.', 'She''s buying a toothbrush.', 'She''s holding some products.', 'She''s talking to a store employee.', 'C', 'A: Cô ấy đang sắp xếp một số cuốn sách.
