INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2803, 2093, 3, NULL, 'He''s wearing safety glasses.', 'He''s cleaning some equipment.', 'He''s picking up a hammer.', 'He''s laying stones on a driveway.', 'A', 'A: Anh ấy đang đeo kính bảo hộ.
