INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2804, 2094, 4, NULL, 'Some flowerpots have been placed along a walkway.', 'The gate of a fence was left open.', 'Some stairway railings are being installed.', 'The building entrance has columns.', 'D', 'A: Một số chậu hoa đã được đặt dọc theo lối đi.
B: Cổng của hàng rào đã được để mở.
