INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2095, 99, '2023/test5/audio/test5_question_5.mp3', '2023/test5/image/test5-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2805, 2095, 5, NULL, 'Two people are standing around a buffet counter.', 'Two people are having a meal together.', 'A server is bringing dishes to a customer.', 'A server is pouring water into glasses.', 'B', 'A: Hai người đang đứng quanh quầy tiệc.
B: Hai người đang ăn một bữa ăn cùng nhau.
