INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2806, 2096, 6, NULL, 'Electrical cables have been stacked on the floor.', 'Stools have been placed around the room.', 'Cabinets are being emptied.', 'The floor of the workshop is being swept.', 'B', 'A: Dây cáp điện đã được xếp trên sàn.
