INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2827, 2117, 27, 'Could you show me how to transfer funds?', 'No, it''s the other one.', 'Let me just finish this first.', 'Sure, that seems like a reasonable price.', NULL, 'B', 'Bạn có thể chỉ cho tôi cách chuyển tiền không?
