INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2830, 2120, 30, 'Do you have all the ingredients for the recipe?', 'We will plant a garden soon.', 'Yes, my oven is working again.', 'I need to buy some onions.', NULL, 'C', 'Bạn có đầy đủ các nguyên liệu cho công thức nấu ăn không?
