INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (2831, 2121, 31, 'You''re in charge of the supplier discount program, right?', 'The coupons are on the kitchen counter.', 'We have all the supplies we need.', 'Horatio is the one you want to talk to.', NULL, 'C', 'Bạn chịu trách nhiệm về chương trình giảm giá nhà cung cấp đúng không?
Các phiếu giảm giá ở trên quầy bếp.
