INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3227, 2415, 27, 'I don''t think Mr. Beck will like the new production plan.', 'You don''t think so?', 'To visit the plant tomorrow.', 'About an hour on Tuesday.', NULL, 'A', 'Tôi không nghĩ ông Beck sẽ thích kế hoạch sản xuất mới.
Bạn không nghĩ vậy à?
Để thăm nhà máy vào ngày mai.
Khoảng một giờ vào thứ Ba.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2416, 114, '2023/test7/audio/test7_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3228, 2416, 28, 'Shouldn''t we discuss the advertising campaign now?', 'On the radio.', 'A roundtable discussion.', 'No, we have other priorities.', NULL, 'C', 'Chúng ta không nên thảo luận về chiến dịch quảng cáo ngay bây giờ sao?
Trên đài phát thanh.
Một cuộc thảo luận bàn tròn.
Không, chúng ta có các ưu tiên khác.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2417, 114, '2023/test7/audio/test7_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3229, 2417, 29, 'Where should I put this box of report binders?', 'The delivery truck is late.', 'Our team report contains a lot of interesting data.', 'The cabinet in my office is full.', NULL, 'C', 'Tôi nên đặt hộp đựng bìa báo cáo này ở đâu?
Xe tải giao hàng đang trễ.
Báo cáo nhóm của chúng tôi chứa rất nhiều dữ liệu thú vị.
Tủ trong văn phòng của tôi đã đầy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2418, 114, '2023/test7/audio/test7_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3230, 2418, 30, 'Have you seen our orientation video for new employees?', 'Seven new employees.', 'Yes, I watched it this morning.', 'We still haven''t met.', NULL, 'B', 'Bạn đã xem video định hướng của chúng tôi dành cho nhân viên mới chưa?
(A) Bảy nhân viên mới.
(B) Có, tôi đã xem video này sáng nay.
(C) Chúng ta vẫn chưa gặp nhau.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2419, 114, '2023/test7/audio/test7_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3231, 2419, 31, 'When are you planning to take a vacation?', 'She planned the event herself.', 'I''m working on three projects.', 'Could you take our picture, please?', NULL, 'B', 'Khi nào bạn dự định đi nghỉ?
(A) Cô ấy đã tự mình lên kế hoạch cho sự kiện.
(B) Tôi đang thực hiện ba dự án.
(C) Bạn có thể chụp ảnh cho chúng tôi được không?');;

-- Data for 2023 Test7 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2420, 115, '2023/test7/audio/test7_question_32_34.mp3', NULL, 'M-Au Fernanda, l know we were hoping to have the walls in the office repainted next month. But do you think it''ll be too much of a disruption for the employees?
W-Br I think it''ll be fine asked the team when they''d like to work from home the next few months. Most people prefer Mondays and Fridays, so we could have the painters come on those days.
M-Au Sounds good. I''ll reach out to some companies to see who''s available to do the work.', 'M-Au Fernanda, tôi biết chúng ta đã hy vọng sẽ sơn lại các bức tường trong văn phòng vào tháng tới. Nhưng bạn có nghĩ rằng nó sẽ gây ra quá nhiều xáo trộn cho nhân viên không?
W-Br Tôi nghĩ sẽ ổn thôi. Tôi đã hỏi nhóm khi nào họ muốn làm việc tại nhà trong vài tháng tới. Hầu hết mọi người thích thứ Hai và thứ Sáu, vì vậy chúng ta có thể cho thợ sơn đến vào những ngày đó.
M-Au Nghe có vẻ tốt. Tôi sẽ liên hệ với một số công ty để xem ai có sẵn để làm công việc này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3232, 2420, 32, 'What are the speakers discussing?', 'Moving to a new office', 'Painting some walls', 'Purchasing some furniture', 'Raising employee salaries', 'B', 'Đáp án đúng là B. Các người nói đang thảo luận về việc sơn lại một số bức tường. Điều này được nêu rõ khi người đàn ông nói: "we were hoping to have the walls in the office repainted next month" (chúng ta đã hy vọng sẽ sơn lại các bức tường trong văn phòng vào tháng tới).
Dịch câu hỏi và các đáp án:
Câu hỏi: Các người nói đang thảo luận về điều gì?
A. Chuyển đến một văn phòng mới
B. Sơn một số bức tường
C. Mua một số đồ nội thất
D. Tăng lương nhân viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2421, 115, '2023/test7/audio/test7_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3233, 2421, 33, 'What did the woman ask a team about?', 'Group assignments', 'Vacation schedules', 'Software preferences', 'Work-from-home dates', 'D', 'Đáp án đúng là D. Người phụ nữ đã hỏi nhóm về ngày làm việc tại nhà. Cô ấy nói: "I asked the team when they''d like to work from home the next few months." (Tôi đã hỏi nhóm khi nào họ muốn làm việc tại nhà trong vài tháng tới.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người phụ nữ đã hỏi một nhóm về điều gì?
A. Phân công nhóm
B. Lịch nghỉ phép
C. Sở thích phần mềm
D. Ngày làm việc tại nhà');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2422, 115, '2023/test7/audio/test7_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3234, 2422, 34, 'What does the man offer to do?', 'Contact some businesses', 'Get a manager''s approval', 'Calculate some costs', 'Send a notification e-mail', 'A', 'Đáp án đúng là A. Người đàn ông đề nghị liên hệ với một số doanh nghiệp. Anh ta nói: "I''ll reach out to some companies to see who''s available to do the work." (Tôi sẽ liên hệ với một số công ty để xem ai có sẵn để làm công việc này.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông đề nghị làm gì?
A. Liên hệ với một số doanh nghiệp
B. Xin phê duyệt của người quản lý
C. Tính toán một số chi phí
D. Gửi email thông báo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2423, 115, '2023/test7/audio/test7_question_35_37.mp3', NULL, 'W-Br Hi, Gregor. The customers at table 23 wanted to let you know they really enjoyed their meal. They had the vegetable stew.
M-Au Thanks for letting me know. Unfortunately, Rajeev just informed me that he has to leave early. We won''t have enough cooks to cover the evening rush.
W-Br Oh. I''ll let the customers know that some of their food might take longer than usual to come out.
M-Au That''s a good idea.', 'W-Br Chào Gregor. Khách hàng ở bàn 23 muốn cho anh biết họ rất thích bữa ăn của họ. Họ đã ăn món hầm rau.
M-Au Cảm ơn bạn đã cho tôi biết. Thật không may, Rajeev vừa thông báo với tôi rằng anh ấy phải về sớm. Chúng ta sẽ không có đủ đầu bếp để phục vụ giờ cao điểm buổi tối.
W-Br Ồ. Tôi sẽ thông báo cho khách hàng biết rằng một số món ăn của họ có thể mất nhiều thời gian hơn bình thường để ra món.
M-Au Đó là một ý kiến hay.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3235, 2423, 35, 'Where do the speakers most likely work?', 'At an appliance store', 'At a restaurant', 'At a food-manufacturing plant', 'At a cooking school', 'B', 'Đáp án đúng là B. Các người nói rất có thể làm việc tại một nhà hàng. Điều này được suy ra từ việc đề cập đến khách hàng tại một bàn cụ thể, món ăn, đầu bếp và giờ cao điểm buổi tối.
Dịch câu hỏi và các đáp án:
Câu hỏi: Các người nói rất có thể làm việc ở đâu?
A. Tại một cửa hàng thiết bị
B. Tại một nhà hàng
C. Tại một nhà máy sản xuất thực phẩm
D. Tại một trường dạy nấu ăn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2424, 115, '2023/test7/audio/test7_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3236, 2424, 36, 'What problem does the man mention?', 'Some uniforms have not been delivered.', 'Some paperwork was misfiled.', 'A business will be understaffed.', 'A permit has not been approved.', 'C', 'Đáp án đúng là C. Người đàn ông đề cập đến vấn đề là doanh nghiệp sẽ thiếu nhân viên. Anh ta nói: "We won''t have enough cooks to cover the evening rush." (Chúng ta sẽ không có đủ đầu bếp để phục vụ giờ cao điểm buổi tối.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Vấn đề gì mà người đàn ông đề cập đến?
A. Một số đồng phục chưa được giao.
B. Một số giấy tờ đã bị sắp xếp sai.
C. Một doanh nghiệp sẽ thiếu nhân viên.
D. Một giấy phép chưa được phê duyệt.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2425, 115, '2023/test7/audio/test7_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3237, 2425, 37, 'What does the woman say she will do?', 'Schedule an upcoming training session', 'Inform customers of a potential delay', 'Work an extra shift', 'Contact a vendor', 'B', 'Đáp án đúng là B. Người phụ nữ nói rằng cô ấy sẽ thông báo cho khách hàng về một sự chậm trễ tiềm ẩn. Cô ấy nói: "I''ll let the customers know that some of their food might take longer than usual to come out." (Tôi sẽ thông báo cho khách hàng biết rằng một số món ăn của họ có thể mất nhiều thời gian hơn bình thường để ra món.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người phụ nữ nói cô ấy sẽ làm gì?
A. Lên lịch một buổi đào tạo sắp tới
B. Thông báo cho khách hàng về một sự chậm trễ tiềm ẩn
C. Làm thêm một ca
D. Liên hệ với một nhà cung cấp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2426, 115, '2023/test7/audio/test7_question_38_40.mp3', NULL, 'N-Au Thank you, Amany, for agreeing to come in and test out our new video game. Given your expertise in the field, we''re excited for you to play it and let us know what you think.
W-Am It''s my pleasure. I love playing games that are in development and sharing ideas for improvements. I heard that this game was designed to be used as a training tool for delivery drivers, right?
M-Au Correct. It''s designed to teach drivers to choose the most efficient routes. Oh, and by the way, tit''s nearly lunchtime would you like me to take you over to the cafeteria before you get started? All the food is complimentary.', 'N-Au Cảm ơn Amany đã đồng ý đến và thử nghiệm trò chơi video mới của chúng tôi. Với chuyên môn của bạn trong lĩnh vực này, chúng tôi rất mong được bạn chơi nó và cho chúng tôi biết bạn nghĩ gì.
W-Am Đó là niềm vui của tôi. Tôi thích chơi những trò chơi đang trong quá trình phát triển và chia sẻ ý tưởng để cải thiện. Tôi nghe nói rằng trò chơi này được thiết kế để sử dụng như một công cụ đào tạo cho các tài xế giao hàng, phải không?
M-Au Đúng vậy. Nó được thiết kế để dạy các tài xế chọn các tuyến đường hiệu quả nhất. À, và nhân tiện, đã gần đến giờ ăn trưa rồi, bạn có muốn tôi đưa bạn đến căng tin trước khi bắt đầu không? Tất cả thức ăn đều miễn phí.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3238, 2426, 38, 'What was the woman hired to do for a video game?', 'Provide feedback', 'Create some animations', 'Compose a musical score', 'Write a script', 'A', 'Đáp án đúng là A. Người phụ nữ được thuê để cung cấp phản hồi cho một trò chơi video. Điều này được suy ra từ việc người đàn ông nói: "we''re excited for you to play it and let us know what you think" (chúng tôi rất mong được bạn chơi nó và cho chúng tôi biết bạn nghĩ gì).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người phụ nữ được thuê để làm gì cho một trò chơi video?
A. Cung cấp phản hồi
B. Tạo một số hoạt ảnh
C. Sáng tác một bản nhạc nền
D. Viết một kịch bản');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2427, 115, '2023/test7/audio/test7_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3239, 2427, 39, 'According to the man, who has a video game been designed for?', 'Medical personnel', 'Human resource specialists', 'Delivery drivers', 'Assembly-line workers', 'C', 'Đáp án đúng là C. Theo người đàn ông, trò chơi video đã được thiết kế cho các tài xế giao hàng. Anh ta xác nhận: "It''s designed to teach drivers to choose the most efficient routes." (Nó được thiết kế để dạy các tài xế chọn các tuyến đường hiệu quả nhất.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Theo người đàn ông, trò chơi video đã được thiết kế cho ai?
A. Nhân viên y tế
B. Chuyên gia nhân sự
C. Tài xế giao hàng
D. Công nhân dây chuyền lắp ráp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2428, 115, '2023/test7/audio/test7_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3240, 2428, 40, 'What does the man invite the woman to do?', 'Store her items in a locker', 'Tour a building', 'Choose a place to work', 'Get some food', 'D', 'Đáp án đúng là D. Người đàn ông mời người phụ nữ ăn một chút. Anh ta hỏi: "would you like me to take you over to the cafeteria before you get started? All the food is complimentary." (bạn có muốn tôi đưa bạn đến căng tin trước khi bắt đầu không? Tất cả thức ăn đều miễn phí.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông mời người phụ nữ làm gì?
A. Cất đồ đạc của cô ấy vào tủ khóa
B. Tham quan một tòa nhà
C. Chọn một nơi để làm việc
D. Ăn một chút');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2429, 115, '2023/test7/audio/test7_question_41_43.mp3', NULL, 'W-Br I really appreciate you coming to my office to help fix my printer, Malik. I tried going through the troubleshooting steps on my own, but it still jams up on me every time I try to print double-sided copies.
M-Cn No problem. I can help you. Can you try printing a test document for me so l can see what''s happening?
W-Br Sure. I''ll print the first two pages of the budget report I''m working on.
M-Cn Hmm. It looks like you''re using paper that''s a nonstandard size. That may be why it''s not going through smoothly, but I''ll take a closer look to see what else could be wrong.', 'W-Br Tôi thực sự đánh giá cao việc bạn đến văn phòng của tôi để giúp sửa máy in của tôi, Malik. Tôi đã cố gắng tự mình thực hiện các bước khắc phục sự cố, nhưng nó vẫn bị kẹt mỗi khi tôi cố in hai mặt.
M-Cn Không vấn đề gì. Tôi có thể giúp bạn. Bạn có thể thử in một tài liệu kiểm tra cho tôi để tôi có thể xem điều gì đang xảy ra không?
W-Br Được. Tôi sẽ in hai trang đầu tiên của báo cáo ngân sách mà tôi đang làm việc.
M-Cn Hmm. Có vẻ như bạn đang sử dụng giấy có kích thước không chuẩn. Đó có thể là lý do tại sao nó không chạy qua một cách suôn sẻ, nhưng tôi sẽ xem xét kỹ hơn để xem còn gì khác có thể sai.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3241, 2429, 41, 'Why did the man come to the woman''s office?', 'To discuss a report', 'To deliver some tools', 'To review job applications', 'To make a repair', 'D', 'Đáp án đúng là D. Người đàn ông đến văn phòng của người phụ nữ để sửa chữa. Điều này được nêu rõ khi người phụ nữ nói: "I really appreciate you coming to my office to help fix my printer" (Tôi thực sự đánh giá cao việc bạn đến văn phòng của tôi để giúp sửa máy in của tôi).
Dịch câu hỏi và các đáp án:
Câu hỏi: Tại sao người đàn ông đến văn phòng của người phụ nữ?
A. Để thảo luận về một báo cáo
B. Để giao một số công cụ
C. Để xem xét các đơn xin việc
D. Để sửa chữa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2430, 115, '2023/test7/audio/test7_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3242, 2430, 42, 'What does the man ask the woman to do?', 'Provide a signature', 'Confirm a budget', 'Print a document', 'Clear a work space', 'C', 'Đáp án đúng là C. Người đàn ông yêu cầu người phụ nữ in một tài liệu. Anh ta hỏi: "Can you try printing a test document for me so l can see what''s happening?" (Bạn có thể thử in một tài liệu kiểm tra cho tôi để tôi có thể xem điều gì đang xảy ra không?)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông yêu cầu người phụ nữ làm gì?
A. Cung cấp chữ ký
B. Xác nhận ngân sách
C. In một tài liệu
D. Dọn dẹp không gian làm việc');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2431, 115, '2023/test7/audio/test7_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3243, 2431, 43, 'What does the man notice?', 'An item is not a standard size.', 'Some information is missing.', 'A cord is unplugged.', 'A manual is not accurate.', 'A', 'Đáp án đúng là A. Người đàn ông nhận thấy một vật phẩm không có kích thước tiêu chuẩn. Anh ta nói: "It looks like you''re using paper that''s a nonstandard size." (Có vẻ như bạn đang sử dụng giấy có kích thước không chuẩn.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông nhận thấy điều gì?
A. Một vật phẩm không có kích thước tiêu chuẩn.
B. Một số thông tin bị thiếu.
C. Một dây cáp bị rút ra.
D. Một hướng dẫn sử dụng không chính xác.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2432, 115, '2023/test7/audio/test7_question_44_46.mp3', NULL, 'M-Cn Elson Electric Service. How can I help you?
W-Br Hi. My name''s Kriti Bora. I''m calling because I received an electricity bill from your company in the mail. But I don''t understand why, since my bills are paid automatically through my bank account.
M-Cn Let me check your customer account, Ms. Bora. Hmm... It looks like the payment didn''t go through. Have you changed anything recently?
w-Br Well, I changed banks about a month ago, but I thought that l''d informed you about it.
M-Cn I don''t see any recent updates here. So, I''m sorry, but f''ll need you to update your bank account information on our Web site. I''ll send you the link to the form.', 'M-Cn Dịch vụ Điện Elson. Tôi có thể giúp gì cho bạn?
W-Br Xin chào. Tên tôi là Kriti Bora. Tôi gọi vì tôi đã nhận được một hóa đơn tiền điện từ công ty của bạn qua thư. Nhưng tôi không hiểu tại sao, vì hóa đơn của tôi được thanh toán tự động qua tài khoản ngân hàng của tôi.
M-Cn Để tôi kiểm tra tài khoản khách hàng của bạn, cô Bora. Hmm... Có vẻ như khoản thanh toán không được thực hiện. Gần đây bạn có thay đổi gì không?
W-Br À, tôi đã đổi ngân hàng khoảng một tháng trước, nhưng tôi nghĩ rằng tôi đã thông báo cho bạn về điều đó.
M-Cn Tôi không thấy bất kỳ cập nhật gần đây nào ở đây. Vì vậy, tôi xin lỗi, nhưng bạn sẽ cần cập nhật thông tin tài khoản ngân hàng của bạn trên trang web của chúng tôi. Tôi sẽ gửi cho bạn liên kết đến biểu mẫu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3244, 2432, 44, 'Why is the woman calling?', 'To report a power outage', 'To inquire about a bill', 'To get advice about energy savings', 'To transfer a service to a new location', 'B', 'Đáp án đúng là B. Người phụ nữ gọi điện để hỏi về một hóa đơn. Cô ấy nói: "I''m calling because I received an electricity bill from your company in the mail. But I don''t understand why, since my bills are paid automatically through my bank account." (Tôi gọi vì tôi đã nhận được một hóa đơn tiền điện từ công ty của bạn qua thư. Nhưng tôi không hiểu tại sao, vì hóa đơn của tôi được thanh toán tự động qua tài khoản ngân hàng của tôi.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Tại sao người phụ nữ gọi điện?
A. Để báo cáo về mất điện
B. Để hỏi về một hóa đơn
C. Để nhận lời khuyên về tiết kiệm năng lượng
D. Để chuyển dịch vụ đến một địa điểm mới');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2433, 115, '2023/test7/audio/test7_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3245, 2433, 45, 'What did the woman do a month ago?', 'She had solar panels installed.', 'She changed banks.', 'She took a vacation.', 'She opened a business.', 'B', 'Đáp án đúng là B. Người phụ nữ đã thay đổi ngân hàng một tháng trước. Cô ấy nói: "Well, I changed banks about a month ago" (À, tôi đã đổi ngân hàng khoảng một tháng trước).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người phụ nữ đã làm gì một tháng trước?
A. Cô ấy đã lắp đặt pin mặt trời.
B. Cô ấy đã thay đổi ngân hàng.
C. Cô ấy đã đi nghỉ.
D. Cô ấy đã mở một doanh nghiệp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2434, 115, '2023/test7/audio/test7_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3246, 2434, 46, 'What does the man say the woman needs to do?', 'Schedule an inspection', 'Talk to a building manager', 'Complete an online form', 'Pay an extra fee', 'C', 'Đáp án đúng là C. Người đàn ông nói rằng người phụ nữ cần hoàn thành một biểu mẫu trực tuyến. Anh ta nói: "I''ll need you to update your bank account information on our Web site. I''ll send you the link to the form." (Bạn sẽ cần cập nhật thông tin tài khoản ngân hàng của bạn trên trang web của chúng tôi. Tôi sẽ gửi cho bạn liên kết đến biểu mẫu.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông nói người phụ nữ cần làm gì?
A. Lên lịch kiểm tra
B. Nói chuyện với người quản lý tòa nhà
C. Hoàn thành một biểu mẫu trực tuyến
D. Trả thêm phí');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2435, 115, '2023/test7/audio/test7_question_47_49.mp3', NULL, 'M-Au Hi, Dr. Patel. Thanks for contacting us for a second meeting.
w-Br Good to see you both again. As you know, my dental practice has been growing, so l''ve decided to purchase the latest carbon dioxide dental laser your company makes.
M-Au Excellent news!
W-Br But I do have a question. While I''m convinced of the benefits of this machine for my dental patients, this is a huge financial commitment. Do you offer any payment plans?
M-Au Yes, and Mr. Kim here can help you with that.
M-Cn Sure. Just give me a minute to bring up the relevant information on my tablet. I''ll go over each option with you in detail.', 'M-Au Xin chào, Bác sĩ Patel. Cảm ơn bác sĩ đã liên hệ với chúng tôi cho cuộc họp thứ hai.
W-Br Rất vui được gặp lại cả hai. Như các bạn biết, phòng khám nha khoa của tôi đã phát triển, vì vậy tôi đã quyết định mua máy laser nha khoa carbon dioxide mới nhất mà công ty của các bạn sản xuất.
M-Au Tin tuyệt vời!
W-Br Nhưng tôi có một câu hỏi. Trong khi tôi tin tưởng vào lợi ích của máy này cho bệnh nhân nha khoa của tôi, đây là một cam kết tài chính lớn. Các bạn có cung cấp kế hoạch thanh toán nào không?
M-Au Có, và ông Kim ở đây có thể giúp bạn với điều đó.
M-Cn Chắc chắn rồi. Chỉ cần cho tôi một phút để hiển thị thông tin liên quan trên máy tính bảng của tôi. Tôi sẽ xem xét từng lựa chọn với bạn một cách chi tiết.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3247, 2435, 47, 'Who most likely is the woman?', 'A research scientist', 'An advertising executive', 'A software engineer', 'A dentist', 'D', 'Đáp án đúng là D. Người phụ nữ rất có thể là một nha sĩ. Điều này được suy ra từ việc cô ấy được gọi là "Dr. Patel", đề cập đến "my dental practice" (phòng khám nha khoa của tôi) và "my dental patients" (bệnh nhân nha khoa của tôi).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người phụ nữ rất có thể là ai?
A. Một nhà khoa học nghiên cứu
B. Một giám đốc điều hành quảng cáo
C. Một kỹ sư phần mềm
D. Một nha sĩ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2436, 115, '2023/test7/audio/test7_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3248, 2436, 48, 'What does the woman say she has decided to do?', 'Accept a job offer', 'Purchase some equipment', 'Move to a new office', 'Take a training course', 'B', 'Đáp án đúng là B. Người phụ nữ nói rằng cô ấy đã quyết định mua một số thiết bị. Cụ thể, cô ấy nói: "I''ve decided to purchase the latest carbon dioxide dental laser your company makes." (Tôi đã quyết định mua máy laser nha khoa carbon dioxide mới nhất mà công ty của các bạn sản xuất.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người phụ nữ nói cô ấy đã quyết định làm gì?
A. Chấp nhận một đề nghị công việc
B. Mua một số thiết bị
C. Chuyển đến một văn phòng mới
D. Tham gia một khóa đào tạo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2437, 115, '2023/test7/audio/test7_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3249, 2437, 49, 'What do the men say are available?', 'Some preliminary sketches', 'Some consultation services', 'Payment plans', 'User manuals', 'C', 'Đáp án đúng là C. Các người đàn ông nói rằng có sẵn các kế hoạch thanh toán. Khi người phụ nữ hỏi về kế hoạch thanh toán, một trong những người đàn ông trả lời: "Yes, and Mr. Kim here can help you with that." (Có, và ông Kim ở đây có thể giúp bạn với điều đó.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Các người đàn ông nói có sẵn những gì?
A. Một số bản phác thảo sơ bộ
B. Một số dịch vụ tư vấn
C. Các kế hoạch thanh toán
D. Các hướng dẫn sử dụng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2438, 115, '2023/test7/audio/test7_question_50_52.mp3', NULL, 'M-Au I''ve had a chance to look at your commercial dishwasher. Unfortunately, the drain pump needs to be replaced, and I don''t have the part on hand.
W-Am But we''re about to open for dinner, and all our tables are booked this evening. There''s nothing you can do now?
M-Au I''m afraid not. I''ll request that the replacement part be sent by express shipping, but it could still take a couple of hours to complete the repair.
W-Am All right-but please let me know as soon as you get the part. We''re really going to be busy this evening, and I''m concerned we won''t have enough tableware to last the whole evening.', 'M-Au Tôi đã có cơ hội xem xét máy rửa bát thương mại của bạn. Thật không may, bơm thoát nước cần được thay thế, và tôi không có sẵn bộ phận đó.
W-Am Nhưng chúng tôi sắp mở cửa phục vụ bữa tối, và tất cả các bàn của chúng tôi đã được đặt tối nay. Không có gì bạn có thể làm bây giờ sao?
M-Au Tôi e là không. Tôi sẽ yêu cầu gửi bộ phận thay thế bằng chuyển phát nhanh, nhưng nó vẫn có thể mất vài giờ để hoàn thành việc sửa chữa.
W-Am Được rồi - nhưng làm ơn cho tôi biết ngay khi bạn nhận được bộ phận. Chúng tôi sẽ rất bận rộn tối nay, và tôi lo lắng rằng chúng tôi sẽ không có đủ bộ đồ ăn để kéo dài cả buổi tối.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3250, 2438, 50, 'Who most likely is the man?', 'A sales representative', 'A restaurant chef', 'A repair technician', 'A health inspector', 'C', 'Đáp án đúng là C. Người đàn ông rất có thể là một kỹ thuật viên sửa chữa. Điều này được suy ra từ việc anh ta đang kiểm tra và sửa chữa một máy rửa bát thương mại.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông rất có thể là ai?
A. Một đại diện bán hàng
B. Một đầu bếp nhà hàng
C. Một kỹ thuật viên sửa chữa
D. Một thanh tra y tế');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2439, 115, '2023/test7/audio/test7_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3251, 2439, 51, 'What does the man offer to do?', 'Reduce a price', 'Expedite an order', 'Post an online notice', 'Photograph some items', 'B', 'Đáp án đúng là B. Người đàn ông đề nghị đẩy nhanh một đơn hàng. Anh ta nói: "I''ll request that the replacement part be sent by express shipping" (Tôi sẽ yêu cầu gửi bộ phận thay thế bằng chuyển phát nhanh).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông đề nghị làm gì?
A. Giảm giá
B. Đẩy nhanh một đơn hàng
C. Đăng một thông báo trực tuyến
D. Chụp ảnh một số vật dụng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2440, 115, '2023/test7/audio/test7_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3252, 2440, 52, 'Why does the woman say she is concerned?', 'Profits have decreased.', 'A competitor has recently opened.', 'Some supplies may run out.', 'Her business Web site is down.', 'C', 'Đáp án đúng là C. Người phụ nữ nói rằng cô ấy lo lắng vì một số vật dụng có thể hết. Cô ấy nói: "I''m concerned we won''t have enough tableware to last the whole evening." (Tôi lo lắng rằng chúng tôi sẽ không có đủ bộ đồ ăn để kéo dài cả buổi tối.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Tại sao người phụ nữ nói cô ấy lo lắng?
A. Lợi nhuận đã giảm.
B. Một đối thủ cạnh tranh gần đây đã mở cửa.
C. Một số vật dụng có thể hết.
D. Trang web kinh doanh của cô ấy bị hỏng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2441, 115, '2023/test7/audio/test7_question_53_55.mp3', NULL, 'M-Cn Good morning, Ms. Phillips. We''re glad to be working with you. ls this the space that you want us to redesign?
W-Br Yes, this is it-the waiting room. We want patients to relax while they wait here. We''d like the space to have soothing colors and comfortable furniture.
M-Au You know, Stone thing that''s been very popular in health-care facilities is aquariums.
M-Cn Children especially enjoy watching fish swim around in the tank.
W-Br That''d be great-if| can afford it.
M-Au We''ll need to know the size of the space before we can tell you how much it''ll cost. Let''s start by measuring the room.', 'M-Cn Chào buổi sáng, cô Phillips. Chúng tôi rất vui được làm việc với cô. Đây có phải là không gian mà cô muốn chúng tôi thiết kế lại không?
W-Br Vâng, đúng là nó - phòng chờ. Chúng tôi muốn bệnh nhân thư giãn khi họ chờ đợi ở đây. Chúng tôi muốn không gian có màu sắc dịu nhẹ và nội thất thoải mái.
M-Au Bạn biết đấy, một thứ đã rất phổ biến trong các cơ sở y tế là bể cá.
M-Cn Đặc biệt là trẻ em rất thích xem cá bơi lội trong bể.
W-Br Điều đó sẽ rất tuyệt - nếu tôi có thể chi trả được.
M-Au Chúng tôi cần biết kích thước của không gian trước khi có thể nói cho bạn biết nó sẽ tốn bao nhiêu. Hãy bắt đầu bằng việc đo phòng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3253, 2441, 53, 'Where does the woman most likely work?', 'At an elementary school', 'At a pet store', 'At a medical clinic', 'At a department store', 'C', 'Đáp án đúng là C. Người phụ nữ rất có thể làm việc tại một phòng khám y tế. Điều này được suy ra từ việc đề cập đến "waiting room" (phòng chờ) và "patients" (bệnh nhân).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người phụ nữ rất có thể làm việc ở đâu?
A. Tại một trường tiểu học
B. Tại một cửa hàng thú cưng
C. Tại một phòng khám y tế
D. Tại một cửa hàng bách hóa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2442, 115, '2023/test7/audio/test7_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3254, 2442, 54, 'What do the men suggest doing?', 'Upgrading a sound system', 'Installing a fish tank', 'Changing a color scheme', 'Replacing some flooring', 'B', 'Đáp án đúng là B. Các người đàn ông đề xuất lắp đặt một bể cá. Một trong số họ nói: "You know, Stone thing that''s been very popular in health-care facilities is aquariums." (Bạn biết đấy, một thứ đã rất phổ biến trong các cơ sở y tế là bể cá.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Các người đàn ông đề xuất làm gì?
A. Nâng cấp hệ thống âm thanh
B. Lắp đặt một bể cá
C. Thay đổi bảng màu
D. Thay thế một số sàn nhà');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2443, 115, '2023/test7/audio/test7_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3255, 2443, 55, 'How will some measurements be used?', 'To draft a cost estimate', 'To purchase some bookshelves', 'To decide what materials to use', 'To apply for a building permit', 'A', 'Đáp án đúng là A. Các phép đo sẽ được sử dụng để lập dự toán chi phí. Một người đàn ông nói: "We''ll need to know the size of the space before we can tell you how much it''ll cost." (Chúng tôi cần biết kích thước của không gian trước khi có thể nói cho bạn biết nó sẽ tốn bao nhiêu.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Một số phép đo sẽ được sử dụng như thế nào?
A. Để lập dự toán chi phí
B. Để mua một số kệ sách
C. Để quyết định sử dụng vật liệu gì
D. Để xin giấy phép xây dựng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2444, 115, '2023/test7/audio/test7_question_56_58.mp3', NULL, 'W-Br Welcome to our career-fair booth. Can I answer any questions for you?
M-Cn Yes, thank you. What sort of jobs do you have available?
W-Br We have several open positions for graphic designers and related jobs.
M-Cn Great. I''d like to learn more.
W-Br Do you have a background in graphic design?
M-Cn Um, I''m very interested in learning.
w-Br I see. Well, we do have a few entry-level positions for people like yourself. And we cover tuition costs for people who need job-related schooling. Here''s a brochure with some information about our company.', 'W-Br Chào mừng đến gian hàng hội chợ việc làm của chúng tôi. Tôi có thể trả lời bất kỳ câu hỏi nào cho bạn không?
M-Cn Vâng, cảm ơn. Bạn có những loại công việc nào?
W-Br Chúng tôi có một số vị trí còn trống cho các nhà thiết kế đồ họa và các công việc liên quan.
M-Cn Tuyệt. Tôi muốn tìm hiểu thêm.
W-Br Bạn có nền tảng về thiết kế đồ họa không?
M-Cn Ừm, tôi rất quan tâm đến việc học hỏi.
W-Br Tôi hiểu rồi. Chà, chúng tôi có một vài vị trí cấp thấp cho những người như bạn. Và chúng tôi trang trải chi phí học tập cho những người cần đào tạo liên quan đến công việc. Đây là một tờ rơi với một số thông tin về công ty chúng tôi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3256, 2444, 56, 'Where most likely are the speakers?', 'At a car show', 'At a job fair', 'At a training workshop', 'At a product launch', 'B', 'Đáp án đúng là B. Các người nói rất có thể đang ở tại một hội chợ việc làm. Điều này được suy ra từ việc đề cập đến "career-fair booth" (gian hàng hội chợ việc làm) và thảo luận về các vị trí công việc có sẵn.
Dịch câu hỏi và các đáp án:
Câu hỏi: Các người nói rất có thể đang ở đâu?
A. Tại một triển lãm ô tô
B. Tại một hội chợ việc làm
C. Tại một hội thảo đào tạo
D. Tại một buổi ra mắt sản phẩm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2445, 115, '2023/test7/audio/test7_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3257, 2445, 57, 'What does the man imply when he says, "I''m very interested in learning"?', 'He met a deadline earlier than expected.', 'He requires more product information.', 'He has many hobbies.', 'He lacks experience.', 'D', 'Đáp án đúng là D. Khi người đàn ông nói "I''m very interested in learning" (Tôi rất quan tâm đến việc học hỏi), anh ta ngụ ý rằng anh ta thiếu kinh nghiệm. Đây là cách anh ta gián tiếp thừa nhận rằng anh ta không có nền tảng về thiết kế đồ họa.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông ngụ ý gì khi anh ta nói, "Tôi rất quan tâm đến việc học hỏi"?
A. Anh ta đã hoàn thành một hạn chót sớm hơn dự kiến.
B. Anh ta cần thêm thông tin về sản phẩm.
C. Anh ta có nhiều sở thích.
D. Anh ta thiếu kinh nghiệm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2446, 115, '2023/test7/audio/test7_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3258, 2446, 58, 'What does the woman give the man?', 'A brochure', 'A business card', 'A company T-shirt', 'An event schedule', 'A', 'Đáp án đúng là A. Người phụ nữ đưa cho người đàn ông một tờ rơi. Cô ấy nói: "Here''s a brochure with some information about our company." (Đây là một tờ rơi với một số thông tin về công ty chúng tôi.)
Người phụ nữ cho người đàn ông cái gì?
(A) Tài liệu quảng cáo
(B) Danh thiếp
(C) Áo phông công ty
(D) Lịch sự kiện');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2447, 115, '2023/test7/audio/test7_question_59_61.mp3', NULL, 'W-Am Tarrington Events. Silvia speaking.
M-Cn Hello. This is Marcel Breton. 59l''d like to inquire about hosting a company gathering at your lakeside resort.
W-Am Great. Can you tell me how many people would be attending, Mr. Breton?
M-Cn We''d have about 50 employees there. I specifically selected your venue because I saw that you''ve received excellent reviews.
W-Am I''m glad to hear that! 61And what dates were you thinking of?
M-Cn Maybe the first week of April?
W-Am Ah, that could be a problem. We book at least six months in advance.', 'W-Am Tarrington Events. Silvia xin nghe.
M-Cn Xin chào. Đây là Marcel Breton. Tôi muốn hỏi về việc tổ chức một cuộc gặp gỡ công ty tại khu nghỉ dưỡng bên hồ của bạn.
W-Am Tuyệt. Ông có thể cho tôi biết có bao nhiêu người sẽ tham dự không, ông Breton?
M-Cn Chúng tôi sẽ có khoảng 50 nhân viên ở đó. Tôi đã chọn địa điểm của bạn cụ thể vì tôi thấy rằng bạn đã nhận được những đánh giá xuất sắc.
W-Am Tôi rất vui khi nghe điều đó! Và ông đang nghĩ đến những ngày nào?
M-Cn Có lẽ là tuần đầu tiên của tháng Tư?
W-Am À, điều đó có thể là một vấn đề. Chúng tôi đặt chỗ ít nhất sáu tháng trước.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3259, 2447, 59, 'What is the man organizing?', 'A client meeting', 'A trade show', 'An awards banquet', 'A company outing', 'D', 'Đáp án đúng là D. Người đàn ông đang tổ chức một chuyến đi công ty. Anh ta nói rằng anh ta muốn "inquire about hosting a company gathering" (hỏi về việc tổ chức một cuộc gặp gỡ công ty) và đề cập đến "50 employees" (50 nhân viên) sẽ tham dự.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông đang tổ chức gì?
A. Một cuộc họp với khách hàng
B. Một hội chợ thương mại
C. Một buổi tiệc trao giải
D. Một chuyến đi công ty');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2448, 115, '2023/test7/audio/test7_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3260, 2448, 60, 'What factor influenced the man''s selection?', 'Affordability', 'Proximity', 'Positive reviews', 'Catering options', 'C', 'Đáp án đúng là C. Yếu tố ảnh hưởng đến sự lựa chọn của người đàn ông là những đánh giá tích cực. Anh ta nói: "I specifically selected your venue because I saw that you''ve received excellent reviews." (Tôi đã chọn địa điểm của bạn cụ thể vì tôi thấy rằng bạn đã nhận được những đánh giá xuất sắc.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Yếu tố nào đã ảnh hưởng đến sự lựa chọn của người đàn ông?
A. Khả năng chi trả
B. Vị trí gần
C. Đánh giá tích cực
D. Các lựa chọn ẩm thực');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2449, 115, '2023/test7/audio/test7_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3261, 2449, 61, 'What does the woman imply when she says, "We book at least six months in advance"?', 'A colleague is mistaken about a date.', 'A request might not be accommodated.', 'A decision needs to be made soon.', 'A cancellation will not be possible.', 'B', 'Đáp án đúng là B. Khi người phụ nữ nói "We book at least six months in advance" (Chúng tôi đặt chỗ ít nhất sáu tháng trước), cô ấy ngụ ý rằng yêu cầu của người đàn ông có thể không được đáp ứng. Cô ấy đang gợi ý rằng việc đặt chỗ cho tuần đầu tiên của tháng Tư (chỉ còn vài tháng nữa) có thể không khả thi vì họ thường đặt chỗ trước ít nhất 6 tháng.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người phụ nữ ngụ ý gì khi cô ấy nói, "Chúng tôi đặt chỗ ít nhất sáu tháng trước"?
A. Một đồng nghiệp đã nhầm lẫn về một ngày.
B. Một yêu cầu có thể không được đáp ứng.
C. Một quyết định cần được đưa ra sớm.
D. Một việc hủy bỏ sẽ không thể thực hiện được.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2450, 115, '2023/test7/audio/test7_question_62_64.mp3', '2023/test7/image/test7-p3-image-62.jpg', 'W-Br A friend of mine recommended your business and said you''re the best. But I''m not sure if you clean on the weekends.
M-Au I have staff available seven days a week. Tell me a little about what you need.
W-Br Well, my store is about 300 square meters. That includes the storage room.
M-Au OK. So you''d like the fixtures dusted and the floors cleaned?
W-Br That''s right. And there are three fitting rooms with mirrors that need cleaning and some large display windows at the front of the store.
M-Au We''ll clean the mirrors, but we don''t do exterior work. You''ll have to get a specialist for the outside of your windows. I''d recommend Star Services.', 'W-Br Một người bạn của tôi đã giới thiệu doanh nghiệp của bạn và nói rằng bạn là tốt nhất. Nhưng tôi không chắc liệu bạn có làm vệ sinh vào cuối tuần không.
M-Au Tôi có nhân viên làm việc bảy ngày một tuần. Hãy cho tôi biết một chút về những gì bạn cần.
W-Br À, cửa hàng của tôi rộng khoảng 300 mét vuông. Điều đó bao gồm cả phòng kho.
M-Au OK. Vậy bạn muốn các đồ đạc được lau bụi và sàn nhà được làm sạch?
W-Br Đúng vậy. Và có ba phòng thử đồ với gương cần được làm sạch và một số cửa sổ trưng bày lớn ở mặt tiền cửa hàng.
M-Au Chúng tôi sẽ lau gương, nhưng chúng tôi không làm việc bên ngoài. Bạn sẽ phải tìm một chuyên gia cho phần bên ngoài cửa sổ của bạn. Tôi khuyên bạn nên dùng dịch vụ của Star Services.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3262, 2450, 62, 'What was the woman uncertain about?', 'Transportation costs', 'Weekend availability', 'A company''s reputation', 'Membership fees', 'B', 'Đáp án đúng là B. Người phụ nữ không chắc chắn về việc có dịch vụ vào cuối tuần hay không. Cô ấy nói: "But I''m not sure if you clean on the weekends." (Nhưng tôi không chắc liệu bạn có làm vệ sinh vào cuối tuần không.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Điều gì mà người phụ nữ không chắc chắn về?
A. Chi phí vận chuyển
B. Có dịch vụ vào cuối tuần
C. Danh tiếng của một công ty
D. Phí thành viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2451, 115, '2023/test7/audio/test7_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3263, 2451, 63, 'Look at the graphic. How much will the woman be charged?', '$70', '$140', '$200', '$300', 'C', 'Đáp án đúng là C. Nhìn vào hình ảnh, người phụ nữ sẽ bị tính phí $200. Cô ấy nói rằng cửa hàng của cô ấy rộng khoảng 300 mét vuông, và theo bảng giá trong hình ảnh, chi phí cho 300 mét vuông là $200.
Dịch câu hỏi và các đáp án:
Câu hỏi: Nhìn vào hình ảnh. Người phụ nữ sẽ bị tính phí bao nhiêu?
A. $70
B. $140
C. $200
D. $300');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2452, 115, '2023/test7/audio/test7_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3264, 2452, 64, 'What does the man recommend Star Services to do?', 'Manage payroll', 'Install mirrors', 'Shampoo the carpets', 'Clean the windows', 'D', 'Đáp án đúng là D. Người đàn ông khuyên dùng Star Services để làm sạch cửa sổ. Anh ta nói: "You''ll have to get a specialist for the outside of your windows. I''d recommend Star Services." (Bạn sẽ phải tìm một chuyên gia cho phần bên ngoài cửa sổ của bạn. Tôi khuyên bạn nên dùng dịch vụ của Star Services.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông khuyên Star Services làm gì?
A. Quản lý tiền lương
B. Lắp đặt gương
C. Giặt thảm
D. Lau cửa sổ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2453, 115, '2023/test7/audio/test7_question_65_67.mp3', '2023/test7/image/test7-p3-image-65.jpg', 'M-Au Hi. I''d like to have a frame made for a vintage family photograph. I was wondering if you could help me select something that would be appropriate for an old photo.
W-Br Sure- let''s see the photo. Wow, it''s not very often that we see this type of round shape.
M-Au Yes, it''s quite unique. I''d like to give it to my mother for her birthday next Friday.
W-Br Since it''s a birthday present, I can wrap it for you free of charge.', 'M-Au Xin chào. Tôi muốn làm một khung cho một bức ảnh gia đình cổ. Tôi tự hỏi liệu bạn có thể giúp tôi chọn thứ gì đó phù hợp cho một bức ảnh cũ không.
W-Br Chắc chắn rồi - hãy xem bức ảnh. Wow, không thường xuyên chúng tôi thấy loại hình dạng tròn này.
M-Au Vâng, nó khá độc đáo. Tôi muốn tặng nó cho mẹ tôi nhân sinh nhật của bà vào thứ Sáu tới.
W-Br Vì đây là một món quà sinh nhật, tôi có thể gói nó cho bạn miễn phí.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3265, 2453, 65, 'What is the man having framed?', 'An invitation', 'A photograph', 'A diploma', 'A painting', 'B', 'Đáp án đúng là B. Người đàn ông đang cho khung một bức ảnh. Anh ta nói: "I''d like to have a frame made for a vintage family photograph." (Tôi muốn làm một khung cho một bức ảnh gia đình cổ.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người đàn ông đang cho khung cái gì?
A. Một lời mời
B. Một bức ảnh
C. Một bằng tốt nghiệp
D. Một bức tranh');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2454, 115, '2023/test7/audio/test7_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3266, 2454, 66, 'Look at the graphic. Which frame will the man most likely select?', 'Frame 1', 'Frame 2', 'Frame 3', 'Frame 4', 'B', 'Đáp án đúng là B. Nhìn vào hình ảnh, người đàn ông rất có thể sẽ chọn Khung 2. Người phụ nữ đề cập rằng bức ảnh có "round shape" (hình dạng tròn), và trong hình ảnh, Khung 2 là khung duy nhất có hình tròn.
Dịch câu hỏi và các đáp án:
Câu hỏi: Nhìn vào hình ảnh. Người đàn ông rất có thể sẽ chọn khung nào?
A. Khung 1
B. Khung 2
C. Khung 3
D. Khung 4');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2455, 115, '2023/test7/audio/test7_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3267, 2455, 67, 'What is included in the price?', 'Delivery', 'Labor', 'Gift wrapping', 'UV glass', 'C', 'Đáp án đúng là C. Gói quà được bao gồm trong giá. Người phụ nữ nói: "Since it''s a birthday present, I can wrap it for you free of charge." (Vì đây là một món quà sinh nhật, tôi có thể gói nó cho bạn miễn phí.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Điều gì được bao gồm trong giá?
A. Giao hàng
B. Công lao động
C. Gói quà
D. Kính chống tia UV');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2456, 115, '2023/test7/audio/test7_question_68_70.mp3', '2023/test7/image/test7-p3-image-68.jpg', 'W-Br Jinyu, I''m sorry I missed your update on the sales of our air-conditioner models.
I was busy leading the new-employee training.
M-Cn Oh, yeah. That''s OK-I heard the training went really well. But the main takeaway from my update was that our newest air-conditioner model was this month''s top seller.
W-Br A lot of customers have mentioned they prefer that model because it''s affordable, so I''m not surprised it was our best-selling product.', 'W-Br Jinyu, tôi xin lỗi đã bỏ lỡ bản cập nhật của anh về doanh số bán các mẫu máy điều hòa của chúng ta.
Tôi đã bận dẫn đầu khóa đào tạo nhân viên mới.
M-Cn Ồ, vâng. Không sao - tôi nghe nói khóa đào tạo đã diễn ra rất tốt. Nhưng điểm chính từ bản cập nhật của tôi là mẫu máy điều hòa mới nhất của chúng ta là sản phẩm bán chạy nhất tháng này.
W-Br Nhiều khách hàng đã đề cập rằng họ thích mẫu đó vì nó có giá phải chăng, vì vậy tôi không ngạc nhiên khi nó là sản phẩm bán chạy nhất của chúng ta.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3268, 2456, 68, 'Why did the woman miss an update?', 'She was on vacation.', 'She was meeting with clients.', 'She was training new employees.', 'She was at a medical appointment.', 'C', 'Đáp án đúng là C. Người phụ nữ đã bỏ lỡ bản cập nhật vì cô ấy đang đào tạo nhân viên mới. Cô ấy nói: "I was busy leading the new-employee training." (Tôi đã bận dẫn đầu khóa đào tạo nhân viên mới.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Tại sao người phụ nữ đã bỏ lỡ một bản cập nhật?
A. Cô ấy đang đi nghỉ.
B. Cô ấy đang gặp gỡ khách hàng.
C. Cô ấy đang đào tạo nhân viên mới.
D. Cô ấy đang ở một cuộc hẹn y tế.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2457, 115, '2023/test7/audio/test7_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3269, 2457, 69, 'Look at the graphic. Which model are the speakers discussing?', 'Model ZQ-C', 'Model HL-B', 'Model SN-V', 'Model CL-G', 'A', 'Đáp án đúng là A. Nhìn vào hình ảnh, các người nói đang thảo luận về Model ZQ-C. Họ nói về mẫu máy điều hòa mới nhất và bán chạy nhất, và trong biểu đồ, Model ZQ-C chiếm phần trăm lớn nhất (38%).
Dịch câu hỏi và các đáp án:
Câu hỏi: Nhìn vào hình ảnh. Các người nói đang thảo luận về mẫu nào?
A. Mẫu ZQ-C
B. Mẫu HL-B
C. Mẫu SN-V
D. Mẫu CL-G');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2458, 115, '2023/test7/audio/test7_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3270, 2458, 70, 'According to the woman, what do customers like about an air-conditioner model?', 'It is quiet.', 'It is easy to install.', 'It is energy efficient.', 'It is inexpensive.', 'D', 'Đáp án đúng là D. Theo người phụ nữ, khách hàng thích mẫu máy điều hòa vì nó có giá phải chăng. Cô ấy nói: "A lot of customers have mentioned they prefer that model because it''s affordable" (Nhiều khách hàng đã đề cập rằng họ thích mẫu đó vì nó có giá phải chăng).
Dịch câu hỏi và các đáp án:
Câu hỏi: Theo người phụ nữ, khách hàng thích điều gì về một mẫu máy điều hòa?
A. Nó yên tĩnh.
B. Nó dễ lắp đặt.
C. Nó tiết kiệm năng lượng.
D. Nó có giá phải chăng.');;

-- Data for 2023 Test7 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2459, 116, '2023/test7/audio/test7_question_71_73.mp3', NULL, 'M-Au I called this special meeting because I have some great news to share with everyone. As you know, we''ve been wanting to do some renovation work for the city government. The bidding process was competitive, but I was just told our firm has been awarded a large contract for work on city offices and courtrooms. This is a big deal for us! Our first move will be adding staff and workers in anticipation of these projects. I will be posting job listings on the company Web site later this week.', 'M-Au Tôi đã gọi cuộc họp đặc biệt này vì tôi có một số tin tức tuyệt vời để chia sẻ với mọi người. Như các bạn biết, chúng ta đã muốn thực hiện một số công việc cải tạo cho chính quyền thành phố. Quá trình đấu thầu rất cạnh tranh, nhưng tôi vừa được thông báo rằng công ty của chúng ta đã được trao một hợp đồng lớn để làm việc trên các văn phòng và phòng xử án của thành phố. Đây là một thương vụ lớn đối với chúng ta! Bước đi đầu tiên của chúng ta sẽ là bổ sung thêm nhân viên và công nhân để chuẩn bị cho những dự án này. Tôi sẽ đăng các danh sách công việc trên trang web của công ty vào cuối tuần này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3271, 2459, 71, 'What type of company does the speaker work for?', 'A technology consulting firm', 'A landscaping company', 'A construction company', 'A law firm', 'C', 'Đáp án đúng là C. Người nói làm việc cho một công ty xây dựng. Điều này được suy ra từ việc họ đề cập đến "renovation work" (công việc cải tạo) và "adding staff and workers" (thêm nhân viên và công nhân) cho các dự án xây dựng.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói làm việc cho loại công ty nào?
A. Một công ty tư vấn công nghệ
B. Một công ty cảnh quan
C. Một công ty xây dựng
D. Một công ty luật');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2460, 116, '2023/test7/audio/test7_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3272, 2460, 72, 'What good news does the speaker share about the company?', 'It won a city contract.', 'It will expand its headquarters.', 'It has won an industry award.', 'Its profits have increased', 'A', 'Đáp án đúng là A. Tin tốt mà người nói chia sẻ là công ty đã giành được một hợp đồng của thành phố. Anh ta nói: "our firm has been awarded a large contract for work on city offices and courtrooms" (công ty của chúng ta đã được trao một hợp đồng lớn để làm việc trên các văn phòng và phòng xử án của thành phố).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói chia sẻ tin tốt gì về công ty?
A. Nó đã giành được một hợp đồng của thành phố.
B. Nó sẽ mở rộng trụ sở chính.
C. Nó đã giành được một giải thưởng trong ngành.
D. Lợi nhuận của nó đã tăng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2461, 116, '2023/test7/audio/test7_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3273, 2461, 73, 'What does the speaker say he will do later this week?', 'Purchase new equipment', 'Update some software', 'Contact an advertising agency', 'Post some job openings', 'D', 'Đáp án đúng là D. Người nói nói rằng anh ta sẽ đăng một số cơ hội việc làm vào cuối tuần này. Anh ta nói: "I will be posting job listings on the company Web site later this week" (Tôi sẽ đăng các danh sách công việc trên trang web của công ty vào cuối tuần này).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói nói anh ta sẽ làm gì vào cuối tuần này?
A. Mua thiết bị mới
B. Cập nhật một số phần mềm
C. Liên hệ với một công ty quảng cáo
D. Đăng một số cơ hội việc làm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2462, 116, '2023/test7/audio/test7_question_74_76.mp3', NULL, 'W-Br I hope you''re all enjoying this year''s Gamesfest event! Thanks for stopping by our booth for this product demo. I''m really excited to share the updated version of our video game, Lively Pilot. Previous versions were available only on computers, but we redesigned Lively Pilot so that it''s compatible with your smartphone. Now you can play it anywhere you go! In fact, following this presentation, you can download the new version to your phones for a limited- time free trial. I''ll give you an access code to get started.', 'W-Br Tôi hy vọng tất cả các bạn đang thưởng thức sự kiện Gamesfest năm nay! Cảm ơn các bạn đã ghé qua gian hàng của chúng tôi cho buổi demo sản phẩm này. Tôi thực sự rất hào hứng được chia sẻ phiên bản cập nhật của trò chơi video của chúng tôi, Lively Pilot. Các phiên bản trước chỉ có sẵn trên máy tính, nhưng chúng tôi đã thiết kế lại Lively Pilot để nó tương thích với điện thoại thông minh của bạn. Bây giờ bạn có thể chơi nó ở bất cứ đâu bạn đi! Thực tế, sau bài thuyết trình này, bạn có thể tải phiên bản mới về điện thoại của mình để dùng thử miễn phí trong thời gian giới hạn. Tôi sẽ cung cấp cho bạn một mã truy cập để bắt đầu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3274, 2462, 74, 'Where does the talk most likely take place?', 'At a press conference', 'At a trade show', 'At an award ceremony', 'At a sports competition', 'B', 'Đáp án đúng là B. Cuộc nói chuyện rất có thể diễn ra tại một hội chợ thương mại. Điều này được suy ra từ việc đề cập đến "Gamesfest event" và "our booth for this product demo" (gian hàng của chúng tôi cho buổi demo sản phẩm này).
Dịch câu hỏi và các đáp án:
Câu hỏi: Cuộc nói chuyện rất có thể diễn ra ở đâu?
A. Tại một cuộc họp báo
B. Tại một hội chợ thương mại
C. Tại một buổi lễ trao giải
D. Tại một cuộc thi đấu thể thao');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2463, 116, '2023/test7/audio/test7_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3275, 2463, 75, 'What aspect of a product does the speaker mention?', 'Its improved graphics', 'Its fast download speeds', 'Its high-quality audio', 'Its smartphone compatibility', 'D', 'Đáp án đúng là D. Người nói đề cập đến khía cạnh tương thích với điện thoại thông minh của sản phẩm. Cô ấy nói: "we redesigned Lively Pilot so that it''s compatible with your smartphone" (chúng tôi đã thiết kế lại Lively Pilot để nó tương thích với điện thoại thông minh của bạn).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói đề cập đến khía cạnh nào của một sản phẩm?
A. Đồ họa được cải thiện của nó
B. Tốc độ tải xuống nhanh của nó
C. Âm thanh chất lượng cao của nó
D. Khả năng tương thích với điện thoại thông minh của nó');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2464, 116, '2023/test7/audio/test7_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3276, 2464, 76, 'What does the speaker say the listeners can do after the talk?', 'Start a free trial', 'Speak to a representative', 'Enjoy some refreshments', 'Enter a contest', 'A', 'Đáp án đúng là A. Người nói nói rằng người nghe có thể bắt đầu một bản dùng thử miễn phí sau cuộc nói chuyện. Cô ấy nói: "you can download the new version to your phones for a limited-time free trial" (bạn có thể tải phiên bản mới về điện thoại của mình để dùng thử miễn phí trong thời gian giới hạn).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói nói người nghe có thể làm gì sau cuộc nói chuyện?
A. Bắt đầu một bản dùng thử miễn phí
B. Nói chuyện với một đại diện
C. Thưởng thức một số đồ giải khát
D. Tham gia một cuộc thi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2465, 116, '2023/test7/audio/test7_question_77_79.mp3', NULL, 'M-n Thank you for attending. I know that all the forklift operators and shipping clerks are quite busy, so I''ll keep this meeting short. We need to ensure that warehouse employees practice safe measures while working. Management would like me to remind you to always wear the mandatory attire while at work, including gloves and nonslip shoes. One other thing: this week it has come to my attention that some of you are taking breaks that are longer than scheduled. Please be sure to return promptly from your 30-minute breaks, as it gets hectic around here.', 'M-n Cảm ơn các bạn đã tham dự. Tôi biết rằng tất cả các nhân viên vận hành xe nâng và nhân viên vận chuyển đều rất bận rộn, vì vậy tôi sẽ giữ cuộc họp này ngắn gọn. Chúng ta cần đảm bảo rằng nhân viên kho hàng thực hiện các biện pháp an toàn trong khi làm việc. Ban quản lý muốn tôi nhắc nhở các bạn luôn mặc trang phục bắt buộc khi làm việc, bao gồm găng tay và giày chống trượt. Một điều khác: tuần này tôi đã nhận thấy rằng một số bạn đang nghỉ giải lao lâu hơn so với lịch trình. Vui lòng đảm bảo quay trở lại đúng giờ từ giờ nghỉ 30 phút của bạn, vì ở đây trở nên bận rộn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3277, 2465, 77, 'Where is the meeting most likely taking place?', 'At a farm', 'At a cafeteria', 'At a warehouse', 'At a grocery store', 'C', 'Đáp án đúng là C. Cuộc họp rất có thể đang diễn ra tại một kho hàng. Điều này được suy ra từ việc đề cập đến "forklift operators" (người vận hành xe nâng), "shipping clerks" (nhân viên vận chuyển), và "warehouse employees" (nhân viên kho hàng).
Dịch câu hỏi và các đáp án:
Câu hỏi: Cuộc họp rất có thể đang diễn ra ở đâu?
A. Tại một trang trại
B. Tại một căng tin
C. Tại một kho hàng
D. Tại một cửa hàng tạp hóa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2466, 116, '2023/test7/audio/test7_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3278, 2466, 78, 'What does the speaker say is required?', 'Requesting vacation time in advance', 'Updating employee contact information', 'Wearing the appropriate clothing', 'Completing some employee training', 'C', 'Đáp án đúng là C. Người nói nói rằng việc mặc quần áo thích hợp là bắt buộc. Anh ta nói: "Management would like me to remind you to always wear the mandatory attire while at work, including gloves and nonslip shoes" (Ban quản lý muốn tôi nhắc nhở các bạn luôn mặc trang phục bắt buộc khi làm việc, bao gồm găng tay và giày chống trượt).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói nói điều gì là bắt buộc?
A. Yêu cầu thời gian nghỉ phép trước
B. Cập nhật thông tin liên lạc của nhân viên
C. Mặc quần áo thích hợp
D. Hoàn thành một số khóa đào tạo nhân viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2467, 116, '2023/test7/audio/test7_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3279, 2467, 79, 'What did the speaker find out about this week?', 'Business has been slower than usual.', 'Inventory has been running low.', 'Employees have been missing meetings.', 'Workers have been taking extended breaks.', 'D', 'Đáp án đúng là D. Người nói phát hiện ra rằng công nhân đã nghỉ giải lao kéo dài. Anh ta nói: "this week it has come to my attention that some of you are taking breaks that are longer than scheduled" (tuần này tôi đã nhận thấy rằng một số bạn đang nghỉ giải lao lâu hơn so với lịch trình).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói đã phát hiện ra điều gì về tuần này?
A. Công việc kinh doanh đã chậm hơn bình thường.
B. Hàng tồn kho đã sắp hết.
C. Nhân viên đã bỏ lỡ các cuộc họp.
D. Công nhân đã nghỉ giải lao kéo dài.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2468, 116, '2023/test7/audio/test7_question_80_82.mp3', NULL, 'W-Am And now for the local business news. Electronics manufacturer Chelan Systems has announced it will be opening a new manufacturing facility here in the region. It will employ an estimated five thousand people. ﻿﻿﻿Company executives chose the area due to its proximity to the local technical school. Chelan Systems will be partnering with the school to create internships and jobs for students and graduates. An information session where attendees can learn about available positions is scheduled to take place at the Front Street Hotel at the end of the month.', 'W-Am Và bây giờ là tin tức kinh doanh địa phương. Nhà sản xuất thiết bị điện tử Chelan Systems đã thông báo sẽ mở một cơ sở sản xuất mới ở khu vực này. Nó sẽ tuyển dụng khoảng năm nghìn người. Các giám đốc điều hành công ty đã chọn khu vực này do gần với trường kỹ thuật địa phương. Chelan Systems sẽ hợp tác với trường để tạo ra các chương trình thực tập và việc làm cho sinh viên và cựu sinh viên. Một buổi thông tin nơi người tham dự có thể tìm hiểu về các vị trí có sẵn được lên lịch diễn ra tại Khách sạn Front Street vào cuối tháng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3280, 2468, 80, 'What type of business is coming to an area?', 'A research facility', 'A delivery service', 'A computer repair company', 'An electronics manufacturer', 'D', 'Đáp án đúng là D. Loại hình kinh doanh đang đến khu vực là một nhà sản xuất thiết bị điện tử. Điều này được nêu rõ ngay từ đầu khi người nói đề cập đến "Electronics manufacturer Chelan Systems" (Nhà sản xuất thiết bị điện tử Chelan Systems).
Dịch câu hỏi và các đáp án:
Câu hỏi: Loại hình kinh doanh nào đang đến khu vực?
A. Một cơ sở nghiên cứu
B. Một dịch vụ giao hàng
C. Một công ty sửa chữa máy tính
D. Một nhà sản xuất thiết bị điện tử');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2469, 116, '2023/test7/audio/test7_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3281, 2469, 81, 'Why was a specific location chosen?', 'It is near public transportation.', 'It is affordable.', 'It is near an educational institution.', 'It will attract a lot of customers.', 'C', 'Đáp án đúng là C. Một địa điểm cụ thể được chọn vì nó gần một cơ sở giáo dục. Đoạn văn nói: "Company executives chose the area due to its proximity to the local technical school." (Các giám đốc điều hành công ty đã chọn khu vực này do gần với trường kỹ thuật địa phương.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Tại sao một địa điểm cụ thể được chọn?
A. Nó gần phương tiện giao thông công cộng.
B. Nó có giá phải chăng.
C. Nó gần một cơ sở giáo dục.
D. Nó sẽ thu hút nhiều khách hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2470, 116, '2023/test7/audio/test7_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3282, 2470, 82, 'How can the listeners find out more information?', 'By attending an event', 'By visiting a Web site', 'By contacting a city official', 'By subscribing to a newsletter', 'A', 'Đáp án đúng là A. Người nghe có thể tìm hiểu thêm thông tin bằng cách tham dự một sự kiện. Đoạn văn nói: "An information session where attendees can learn about available positions is scheduled to take place at the Front Street Hotel at the end of the month." (Một buổi thông tin nơi người tham dự có thể tìm hiểu về các vị trí có sẵn được lên lịch diễn ra tại Khách sạn Front Street vào cuối tháng.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Làm thế nào người nghe có thể tìm hiểu thêm thông tin?
A. Bằng cách tham dự một sự kiện
B. Bằng cách truy cập một trang web
C. Bằng cách liên hệ với một quan chức thành phố
D. Bằng cách đăng ký nhận bản tin');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2471, 116, '2023/test7/audio/test7_question_83_85.mp3', NULL, 'M-Au The cross-harbor tunnel building project is scheduled for completion today, and the tunnel will be open for travel this weekend. The tunnel will link Springfield Island to the mainland. This will reduce reliance on the Springfield ferry, which has been the only means of transportation for island residents. This tunnel will also make it possible for more people to attend the yearly island musical festival. Good news for local tourism: the fee for using the tunnel is fifteen dollars. Now that may seem like a steep price-but remember, that''s less than taking the ferry.', 'M-Au Dự án xây dựng đường hầm qua cảng dự kiến sẽ hoàn thành hôm nay, và đường hầm sẽ mở cửa cho giao thông vào cuối tuần này. Đường hầm sẽ nối Đảo Springfield với đất liền. Điều này sẽ giảm sự phụ thuộc vào phà Springfield, vốn là phương tiện giao thông duy nhất cho cư dân đảo. Đường hầm này cũng sẽ tạo điều kiện cho nhiều người hơn tham dự lễ hội âm nhạc hàng năm trên đảo. Tin tốt cho du lịch địa phương: phí sử dụng đường hầm là mười lăm đô la. Bây giờ điều đó có vẻ như là một mức giá cao - nhưng hãy nhớ rằng, nó ít hơn việc đi phà.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3283, 2471, 83, 'What is the broadcast mainly about?', 'The announcement of a sporting competition', 'The completion of a construction project', 'The closing of a local business', 'The election of a city official', 'B', 'Đáp án đúng là B. Bản tin chủ yếu nói về việc hoàn thành một dự án xây dựng. Cụ thể, nó đề cập đến việc hoàn thành dự án xây dựng đường hầm qua cảng và việc nó sẽ mở cửa cho giao thông vào cuối tuần này.
Dịch câu hỏi và các đáp án:
Câu hỏi: Bản tin chủ yếu nói về điều gì?
A. Thông báo về một cuộc thi thể thao
B. Việc hoàn thành một dự án xây dựng
C. Việc đóng cửa một doanh nghiệp địa phương
D. Việc bầu cử một quan chức thành phố');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2472, 116, '2023/test7/audio/test7_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3284, 2472, 84, 'According to the speaker, which industry will benefit from an event?', 'Technology', 'Manufacturing', 'Fishing', 'Tourism', 'D', 'Đáp án đúng là D. Theo người nói, ngành du lịch sẽ được hưởng lợi từ một sự kiện. Điều này được thể hiện khi người nói đề cập: "Good news for local tourism: the fee for using the tunnel is fifteen dollars." (Tin tốt cho du lịch địa phương: phí sử dụng đường hầm là mười lăm đô la.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Theo người nói, ngành nào sẽ được hưởng lợi từ một sự kiện?
A. Công nghệ
B. Sản xuất
C. Đánh bắt cá
D. Du lịch');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2473, 116, '2023/test7/audio/test7_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3285, 2473, 85, 'Why does the speaker say, "that''s less than taking the ferry''?', 'To show surprise', 'To stress a disadvantage', 'To acknowledge a mistake', 'To offer a counterargument', 'D', 'Đáp án đúng là D. Người nói nói "that''s less than taking the ferry" (điều đó ít hơn việc đi phà) để đưa ra một lập luận phản bác. Anh ta đang đưa ra một lập luận để chứng minh rằng mặc dù phí sử dụng đường hầm có vẻ cao, nhưng thực tế nó vẫn thấp hơn so với việc đi phà.
Dịch câu hỏi và các đáp án:
Câu hỏi: Tại sao người nói nói, "điều đó ít hơn việc đi phà"?
A. Để thể hiện sự ngạc nhiên
B. Để nhấn mạnh một bất lợi
C. Để thừa nhận một sai lầm
D. Để đưa ra một lập luận phản bác');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2474, 116, '2023/test7/audio/test7_question_86_88.mp3', NULL, 'W-Br Starting next year, plastic shopping bags will no longer be used in grocery stores like ours, as a new regulation takes effect nationwide. We need to come up with a plan to phase them out. Now, perhaps there''s a business opportunity for us in this. There''ll always be people who don''t bring their own bags. We could put a modest price tag on reusable canvas tote bags of our own and display them near the checkout counter. If so, we could have our logo on them, which would get us free publicity as a side benefit. Who would like to reach out to our marketing department and ask them to come up with design ideas?', 'W-Br Bắt đầu từ năm tới, túi mua sắm bằng nhựa sẽ không còn được sử dụng trong các cửa hàng tạp hóa như của chúng ta nữa, khi một quy định mới có hiệu lực trên toàn quốc. Chúng ta cần đưa ra một kế hoạch để loại bỏ dần chúng. Bây giờ, có lẽ có một cơ hội kinh doanh cho chúng ta trong việc này. Sẽ luôn có những người không mang theo túi của riêng họ. Chúng ta có thể đặt một mức giá khiêm tốn cho những chiếc túi tote vải canvas có thể tái sử dụng của riêng chúng ta và trưng bày chúng gần quầy thanh toán. Nếu vậy, chúng ta có thể có logo của mình trên đó, điều này sẽ mang lại cho chúng ta quảng cáo miễn phí như một lợi ích phụ. Ai muốn liên hệ với bộ phận tiếp thị của chúng ta và yêu cầu họ đưa ra ý tưởng thiết kế?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3286, 2474, 86, 'What kind of business does the speaker work for?', 'A publicity agency', 'A plastic bag manufacturer', 'An accounting firm', 'A grocery store', 'D', 'Đáp án đúng là D. Người nói làm việc cho một cửa hàng tạp hóa. Điều này được suy ra từ câu đầu tiên khi cô ấy nói "plastic shopping bags will no longer be used in grocery stores like ours" (túi mua sắm bằng nhựa sẽ không còn được sử dụng trong các cửa hàng tạp hóa như của chúng ta nữa).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói làm việc cho loại hình kinh doanh nào?
A. Một công ty quảng cáo
B. Một nhà sản xuất túi nhựa
C. Một công ty kế toán
D. Một cửa hàng tạp hóa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2475, 116, '2023/test7/audio/test7_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3287, 2475, 87, 'What does the speaker mainly discuss?', 'Upgrading the bookkeeping system', 'Preparing for a new regulation', 'Revising a company logo', 'Increasing online advertising', 'B', 'Đáp án đúng là B. Người nói chủ yếu thảo luận về việc chuẩn bị cho một quy định mới. Cô ấy đề cập đến việc túi nhựa sẽ bị cấm theo quy định mới và thảo luận về cách cửa hàng có thể chuẩn bị cho điều này.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói chủ yếu thảo luận về điều gì?
A. Nâng cấp hệ thống kế toán
B. Chuẩn bị cho một quy định mới
C. Sửa đổi logo công ty
D. Tăng cường quảng cáo trực tuyến');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2476, 116, '2023/test7/audio/test7_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3288, 2476, 88, 'What does the speaker expect one of the listeners to do?', 'Contact another department', 'Draft a timeline', 'Find a new supplier', 'Design a showroom layout', 'A', 'Đáp án đúng là A. Người nói mong đợi một trong những người nghe liên hệ với một bộ phận khác. Cô ấy hỏi: "Who would like to reach out to our marketing department and ask them to come up with design ideas?" (Ai muốn liên hệ với bộ phận tiếp thị của chúng ta và yêu cầu họ đưa ra ý tưởng thiết kế?)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói mong đợi một trong những người nghe làm gì?
A. Liên hệ với một bộ phận khác
B. Soạn thảo một lịch trình
C. Tìm một nhà cung cấp mới
D. Thiết kế bố cục phòng trưng bày');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2477, 116, '2023/test7/audio/test7_question_89_91.mp3', NULL, 'W-Am Hi, Luis. This is Claudia from Barton Services. As requested, I''ve created a spreadsheet to help you track the monthly expenses at your catering company and make sure you''re staying within your budget. just need you to do one thing - if you can scan all of the receipts of your company''s expenditures moving forward, I''ll be able to include links to those receipts right in the spreadsheet. Oh, and before I forget, you mentioned recently that you don''t know much about cash flow forecasting and wanted to know the best way to learn more. Well, were offering a workshop on that topic next month. All the information is on our Web site.', 'W-Am Xin chào, Luis. Đây là Claudia từ Barton Services. Theo yêu cầu, tôi đã tạo một bảng tính để giúp bạn theo dõi chi phí hàng tháng tại công ty ẩm thực của bạn và đảm bảo bạn đang ở trong ngân sách. Tôi chỉ cần bạn làm một việc - nếu bạn có thể quét tất cả các biên lai chi tiêu của công ty từ bây giờ trở đi, tôi sẽ có thể bao gồm các liên kết đến những biên lai đó ngay trong bảng tính. Ồ, và trước khi tôi quên, gần đây bạn đã đề cập rằng bạn không biết nhiều về dự báo dòng tiền và muốn biết cách tốt nhất để tìm hiểu thêm. Vâng, chúng tôi đang cung cấp một hội thảo về chủ đề đó vào tháng tới. Tất cả thông tin đều có trên trang web của chúng tôi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3289, 2477, 89, 'Who most likely is the speaker?', 'A journalist', 'An accountant', 'A restaurant owner', 'A customer service representative', 'B', 'Đáp án đúng là B. Người nói rất có thể là một kế toán viên. Điều này được suy ra từ việc cô ấy đang tạo bảng tính để theo dõi chi phí, thảo luận về ngân sách và đề cập đến dự báo dòng tiền, tất cả đều là các nhiệm vụ liên quan đến kế toán.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói rất có thể là ai?
A. Một nhà báo
B. Một kế toán viên
C. Một chủ nhà hàng
D. Một đại diện dịch vụ khách hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2478, 116, '2023/test7/audio/test7_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3290, 2478, 90, 'What does the speaker say she needs the listener to do?', 'Contact some clients', 'Check an inventory list', 'Create a marketing campaign', 'Scan some information', 'D', 'Đáp án đúng là D. Người nói nói rằng cô ấy cần người nghe quét một số thông tin. Cụ thể, cô ấy nói: "if you can scan all of the receipts of your company''s expenditures moving forward" (nếu bạn có thể quét tất cả các biên lai chi tiêu của công ty từ bây giờ trở đi).
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói nói cô ấy cần người nghe làm gì?
A. Liên hệ với một số khách hàng
B. Kiểm tra danh sách hàng tồn kho
C. Tạo một chiến dịch tiếp thị
D. Quét một số thông tin');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2479, 116, '2023/test7/audio/test7_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3291, 2479, 91, 'Why does the speaker say, "we''re offering a workshop on that topic next month"?', 'To reject an invitation', 'To explain a delay', 'To make a recommendation', 'To ask for help', 'C', 'Đáp án đúng là C. Người nói nói "we''re offering a workshop on that topic next month" (chúng tôi đang cung cấp một hội thảo về chủ đề đó vào tháng tới) để đưa ra một khuyến nghị. Cô ấy đang đề xuất một cách để người nghe học hỏi thêm về dự báo dòng tiền.
Dịch câu hỏi và các đáp án:
Câu hỏi: Tại sao người nói nói, "chúng tôi đang cung cấp một hội thảo về chủ đề đó vào tháng tới"?
A. Để từ chối một lời mời
B. Để giải thích một sự chậm trễ
C. Để đưa ra một khuyến nghị
D. Để yêu cầu giúp đỡ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2480, 116, '2023/test7/audio/test7_question_92_94.mp3', NULL, 'M-Cn We''re in the process of ordering supplies we''ll need for the next fiscal year. Some of our members have complained about poor ventilation by the treadmills, so we''ll be getting additional fans. We should also replace our old exercise mats and balance balls. We need to place that order soon. Tunji, I think you have a free hour tomorrow morning. Once that order is placed, all of our new supplies will be on their way!', 'M-Cn Chúng ta đang trong quá trình đặt hàng vật tư cần thiết cho năm tài chính tới. Một số thành viên của chúng ta đã phàn nàn về việc thông gió kém gần máy chạy bộ, vì vậy chúng ta sẽ mua thêm quạt. Chúng ta cũng nên thay thế các thảm tập và bóng cân bằng cũ. Chúng ta cần đặt hàng đó sớm. Tunji, tôi nghĩ bạn có một giờ rảnh vào sáng mai. Khi đơn hàng đó được đặt, tất cả vật tư mới của chúng ta sẽ được gửi đến!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3292, 2480, 92, 'What is the speaker discussing?', 'Updating a database', 'Hiring more staff', 'Revising safety guidelines', 'Purchasing supplies', 'D', 'Đáp án đúng là D. Người nói đang thảo luận về việc mua vật tư. Điều này được thể hiện rõ qua việc đề cập đến việc đặt hàng quạt, thảm tập và bóng cân bằng.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói đang thảo luận về điều gì?
A. Cập nhật cơ sở dữ liệu
B. Tuyển thêm nhân viên
C. Sửa đổi hướng dẫn an toàn
D. Mua vật tư');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2481, 116, '2023/test7/audio/test7_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3293, 2481, 93, 'Where does the speaker most likely work?', 'At a warehouse', 'At a fitness center', 'At a home-improvement store', 'At a cleaning service', 'B', 'Đáp án đúng là B. Người nói rất có thể làm việc tại một trung tâm thể dục. Điều này được suy ra từ việc đề cập đến máy chạy bộ, thảm tập và bóng cân bằng, tất cả đều là thiết bị phổ biến trong các trung tâm thể dục.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói rất có thể làm việc ở đâu?
A. Tại một kho hàng
B. Tại một trung tâm thể dục
C. Tại một cửa hàng cải thiện nhà cửa
D. Tại một dịch vụ vệ sinh');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2482, 116, '2023/test7/audio/test7_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3294, 2482, 94, 'What does the speaker imply when he says, "Tunji, I think you have a free hour tomorrow morning"?', 'Tunji should complete the task.', 'Tunji can attend the client meeting.', 'Tunji''s schedule needs to be corrected.', 'Tunji can leave work early.', 'A', 'Đáp án đúng là A. Khi người nói nói "Tunji, I think you have a free hour tomorrow morning", anh ta ngụ ý rằng Tunji nên hoàn thành nhiệm vụ (đặt hàng) trong giờ rảnh đó.
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói ngụ ý gì khi anh ta nói, "Tunji, tôi nghĩ bạn có một giờ rảnh vào sáng mai"?
A. Tunji nên hoàn thành nhiệm vụ.
B. Tunji có thể tham dự cuộc họp với khách hàng.
C. Lịch trình của Tunji cần được chỉnh sửa.
D. Tunji có thể rời công việc sớm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2483, 116, '2023/test7/audio/test7_question_95_97.mp3', '2023/test7/image/test7-p4-image-95.jpg', 'W-Am Hello. I''m calling from Baxter''s Car Repair. We rented some toy-vending machines from your company, and I''m pleased to say, they''ve been a big success! Some have completely sold out! Today I''m calling to order a box of toy cars. We''d like to get the mixed colors this time, instead of all red cars. I''m sure l''ll be calling again soon to order key chains-we have plenty now, but they''re also very popular. Finally, do you supply other types of vending machines? We''re thinking of installing a cold-drink machine next to the toy machines."', 'W-Am Xin chào. Tôi đang gọi từ Tiệm sửa xe Baxter. Chúng tôi đã thuê một số máy bán đồ chơi tự động từ công ty của bạn, và tôi rất vui khi nói rằng chúng đã rất thành công! Một số đã bán hết hoàn toàn! Hôm nay tôi gọi để đặt hàng một hộp xe đồ chơi. Chúng tôi muốn lấy màu hỗn hợp lần này, thay vì tất cả là xe màu đỏ. Tôi chắc chắn sẽ gọi lại sớm để đặt hàng móc khóa - chúng tôi hiện có nhiều, nhưng chúng cũng rất phổ biến. Cuối cùng, bạn có cung cấp các loại máy bán hàng tự động khác không? Chúng tôi đang nghĩ đến việc lắp đặt một máy bán đồ uống lạnh bên cạnh các máy bán đồ chơi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3295, 2483, 95, 'Where does the speaker work?', 'At a community center', 'At a car repair shop', 'At a supermarket', 'At a department store', 'B', 'Đáp án đúng là B. Người nói làm việc tại một tiệm sửa xe. Cô ấy nói rõ: "I''m calling from Baxter''s Car Repair." (Tôi đang gọi từ Tiệm sửa xe Baxter.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói làm việc ở đâu?
A. Tại một trung tâm cộng đồng
B. Tại một tiệm sửa xe
C. Tại một siêu thị
D. Tại một cửa hàng bách hóa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2484, 116, '2023/test7/audio/test7_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3296, 2484, 96, 'Look at the graphic. How much will the speaker pay for today''s order?', '$15', '$17', '$18', '$14', 'B', 'Đáp án đúng là B. Nhìn vào hình ảnh, người nói sẽ trả $17 cho đơn hàng hôm nay. Cô ấy đang đặt hàng xe đồ chơi màu hỗn hợp, và theo bảng giá, giá cho một hộp xe đồ chơi màu hỗn hợp là $17.
Dịch câu hỏi và các đáp án:
Câu hỏi: Nhìn vào hình ảnh. Người nói sẽ trả bao nhiêu tiền cho đơn hàng hôm nay?
A. $15
B. $17
C. $18
D. $14');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2485, 116, '2023/test7/audio/test7_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3297, 2485, 97, 'What does the speaker want to install?', 'A beverage vending machine', 'An air-conditioning unit', 'Some security cameras', 'Some carpeting', 'A', 'Đáp án đúng là A. Người nói muốn lắp đặt một máy bán đồ uống tự động. Cô ấy nói: "We''re thinking of installing a cold-drink machine next to the toy machines." (Chúng tôi đang nghĩ đến việc lắp đặt một máy bán đồ uống lạnh bên cạnh các máy bán đồ chơi.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói muốn lắp đặt cái gì?
A. Một máy bán đồ uống tự động
B. Một máy điều hòa không khí
C. Một số camera an ninh
D. Một số thảm trải sàn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2486, 116, '2023/test7/audio/test7_question_98_100.mp3', '2023/test7/image/test7-p4-image-98.jpg', 'M-Au First, I''d like to remind everyone about our company''s new health initiative. I sent out an e-mail this morning with detailed information about the fitness program and instructions for setting your fitness goals. If you haven''t seen the e-mail yet, please check your inbox after this meeting. This year, employees will be rewarded for meeting their goals. Employees who achieve three or more of their personal goals will get two extra days off work this year, with pay. Now, let''s go over a few examples of goals that you can set for yourself in your employee portal.', 'M-Au Đầu tiên, tôi muốn nhắc nhở mọi người về sáng kiến sức khỏe mới của công ty chúng ta. Tôi đã gửi một email sáng nay với thông tin chi tiết về chương trình tập thể dục và hướng dẫn để đặt mục tiêu tập thể dục của bạn. Nếu bạn chưa thấy email, vui lòng kiểm tra hộp thư đến của bạn sau cuộc họp này. Năm nay, nhân viên sẽ được thưởng khi đạt được mục tiêu của họ. Nhân viên đạt được ba hoặc nhiều hơn mục tiêu cá nhân của họ sẽ được nghỉ thêm hai ngày có lương trong năm nay. Bây giờ, hãy cùng xem qua một vài ví dụ về mục tiêu mà bạn có thể đặt ra cho mình trong cổng thông tin nhân viên.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3298, 2486, 98, 'Look at the graphic. Who is the speaker?', 'Takanori Kimura', 'Ozan Demir', 'Robert Wilson', 'Ivan Stepanov', 'D', 'Đáp án đúng là D. Nhìn vào hình ảnh, người nói là Ivan Stepanov. Email của anh ta đề cập đến "Create your fitness plan" (Tạo kế hoạch tập thể dục của bạn), phù hợp với nội dung của đoạn văn về chương trình sức khỏe mới của công ty.
Dịch câu hỏi và các đáp án:
Câu hỏi: Nhìn vào hình ảnh. Ai là người nói?
A. Takanori Kimura
B. Ozan Demir
C. Robert Wilson
D. Ivan Stepanov');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2487, 116, '2023/test7/audio/test7_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3299, 2487, 99, 'How is the company trying to increase participation in a program?', 'By offering free snacks', 'By providing paid time off', 'By awarding a salary increase', 'By giving away a free trip', 'B', 'Đáp án đúng là B. Công ty đang cố gắng tăng sự tham gia vào chương trình bằng cách cung cấp thời gian nghỉ có lương. Người nói nói: "Employees who achieve three or more of their personal goals will get two extra days off work this year, with pay." (Nhân viên đạt được ba hoặc nhiều hơn mục tiêu cá nhân của họ sẽ được nghỉ thêm hai ngày có lương trong năm nay.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Công ty đang cố gắng tăng sự tham gia vào một chương trình như thế nào?
A. Bằng cách cung cấp đồ ăn nhẹ miễn phí
B. Bằng cách cung cấp thời gian nghỉ có lương
C. Bằng cách thưởng tăng lương
D. Bằng cách tặng một chuyến đi miễn phí');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2488, 116, '2023/test7/audio/test7_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3300, 2488, 100, 'What will the speaker do next?', 'Introduce some committee members', 'Review some sales figures', 'Pass out tickets to an upcoming event', 'Give examples of employee goals', 'D', 'Đáp án đúng là D. Người nói sẽ đưa ra ví dụ về các mục tiêu của nhân viên tiếp theo. Anh ta nói: "Now, let''s go over a few examples of goals that you can set for yourself in your employee portal." (Bây giờ, hãy cùng xem qua một vài ví dụ về mục tiêu mà bạn có thể đặt ra cho mình trong cổng thông tin nhân viên.)
Dịch câu hỏi và các đáp án:
Câu hỏi: Người nói sẽ làm gì tiếp theo?
A. Giới thiệu một số thành viên ủy ban
B. Xem xét một số số liệu bán hàng
C. Phát vé cho một sự kiện sắp tới
D. Đưa ra ví dụ về các mục tiêu của nhân viên');;

-- Data for 2023 Test7 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2489, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3301, 2489, 101, 'The Sandville Community Center received ----- of art supplies.', 'donating', 'donated', 'donations', 'donate', 'C', 'Đáp án đúng là C (donations - danh từ số nhiều). Giải thích: Câu này cần một danh từ chỉ sự quyên góp. "Donations" (những sự quyên góp) phù hợp nhất trong ngữ cảnh này.
Dịch: Trung tâm Cộng đồng Sandville đã nhận được những sự quyên góp về vật liệu nghệ thuật.
A. donating (động từ hiện tại phân từ): đang quyên góp
B. donated (động từ quá khứ phân từ): đã quyên góp
C. donations (danh từ số nhiều): những sự quyên góp
D. donate (động từ): quyên góp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2490, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3302, 2490, 102, 'The sales associates often ----- potential client accounts at the weekly meeting.', 'discusses', 'discuss', 'discussion', 'discussing', 'B', 'Đáp án đúng là B (discuss - động từ). Giải thích: Câu này cần một động từ ở thì hiện tại đơn, số nhiều để phù hợp với chủ ngữ số nhiều "sales associates". "Discuss" (thảo luận) phù hợp nhất trong ngữ cảnh này.
Dịch: Các nhân viên bán hàng thường thảo luận về các tài khoản khách hàng tiềm năng trong cuộc họp hàng tuần.
A. discusses (động từ, ngôi thứ 3 số ít): thảo luận
B. discuss (động từ số nhiều): thảo luận
C. discussion (danh từ): cuộc thảo luận
D. discussing (động từ hiện tại phân từ): đang thảo luận');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2491, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3303, 2491, 103, 'Ravelia Hotels is building a hotel ------- Wingate Mall.', 'up to', 'since', 'next to', 'throughout', 'C', 'Đáp án đúng là C (next to - cụm giới từ). Giải thích: Câu này cần một cụm giới từ chỉ vị trí. "Next to" (bên cạnh) phù hợp nhất để chỉ ra vị trí của khách sạn mới.
Dịch: Ravelia Hotels đang xây dựng một khách sạn bên cạnh Trung tâm mua sắm Wingate.
A. up to (cụm giới từ): lên đến
B. since (giới từ): từ khi
C. next to (cụm giới từ): bên cạnh
D. throughout (giới từ): khắp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2492, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3304, 2492, 104, 'Starting this Thursday, all Tenacore employees will be required to wear ------ official uniforms.', 'their', 'themselves', 'they', 'them', 'A', 'Đáp án đúng là A (their - tính từ sở hữu). Giải thích: Câu này cần một tính từ sở hữu để chỉ đồng phục của nhân viên. "Their" (của họ) phù hợp nhất trong ngữ cảnh này.
Dịch: Bắt đầu từ thứ Năm này, tất cả nhân viên Tenacore sẽ được yêu cầu mặc đồng phục chính thức của họ.
A. their (tính từ sở hữu): của họ
B. themselves (đại từ phản thân): bản thân họ
C. they (đại từ chủ ngữ): họ
D. them (đại từ tân ngữ): họ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2493, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3305, 2493, 105, 'Mr. Kwon ---- guided the proposal through the difficult approval process.', 'skillful', 'skilled', 'skill', 'skillfully', 'D', 'Đáp án đúng là D (skillfully - trạng từ). Giải thích: Câu này cần một trạng từ mô tả cách thức ông Kwon hướng dẫn đề xuất. "Skillfully" (khéo léo) phù hợp nhất trong ngữ cảnh này.
Dịch: Ông Kwon đã khéo léo hướng dẫn đề xuất thông qua quá trình phê duyệt khó khăn.
A. skillful (tính từ): khéo léo
B. skilled (tính từ): có kỹ năng
C. skill (danh từ): kỹ năng
D. skillfully (trạng từ): một cách khéo léo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2494, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3306, 2494, 106, 'The Standbridge Company —---- its staff to work remotely one or two days each week.', 'understands', 'participates', 'encourages', 'remembers', 'C', 'Đáp án đúng là C (encourages - động từ). Giải thích: Câu này cần một động từ chỉ sự khuyến khích. "Encourages" (khuyến khích) phù hợp nhất trong ngữ cảnh công ty cho phép nhân viên làm việc từ xa.
Dịch: Công ty Standbridge khuyến khích nhân viên của mình làm việc từ xa một hoặc hai ngày mỗi tuần.
A. understands (động từ): hiểu
B. participates (động từ): tham gia
C. encourages (động từ): khuyến khích
D. remembers (động từ): nhớ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2495, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3307, 2495, 107, 'Please arrive ten minutes before your appointment to allow enough —--- to fill out some paperwork.', 'time', 'staff', 'seats', 'funds', 'A', 'Đáp án đúng là A (time - danh từ). Giải thích: Câu này cần một danh từ chỉ thời gian. "Time" (thời gian) phù hợp nhất trong ngữ cảnh này để hoàn thành giấy tờ.
Dịch: Vui lòng đến trước cuộc hẹn của bạn mười phút để có đủ thời gian điền một số giấy tờ.
A. time (danh từ): thời gian
B. staff (danh từ): nhân viên
C. seats (danh từ): chỗ ngồi
D. funds (danh từ): tiền');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2496, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3308, 2496, 108, '----- you have any questions about the updated contract, please contact Human Resources.', 'If', 'Though', 'Either', 'Beyond', 'A', 'Đáp án đúng là A (If - liên từ). Giải thích: Câu này cần một liên từ điều kiện. "If" (nếu) phù hợp nhất để bắt đầu một câu điều kiện.
Dịch: Nếu bạn có bất kỳ câu hỏi nào về hợp đồng đã cập nhật, vui lòng liên hệ với bộ phận Nhân sự.
A. If (liên từ): nếu
B. Though (liên từ): mặc dù
C. Either (liên từ/đại từ): hoặc là
D. Beyond (giới từ): ngoài');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2497, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3309, 2497, 109, 'The printed --- for the upcoming musical are kept in the theater director''s office.', 'advertisements', 'advertises', 'advertised', 'advertise', 'A', 'Đáp án đúng là A (advertisements - danh từ số nhiều). Giải thích: Câu này cần một danh từ số nhiều chỉ các quảng cáo in. "Advertisements" (các quảng cáo) phù hợp nhất trong ngữ cảnh này.
Dịch: Các quảng cáo in cho vở nhạc kịch sắp tới được giữ trong văn phòng của giám đốc nhà hát.
A. advertisements (danh từ số nhiều): các quảng cáo
B. advertises (động từ, ngôi thứ 3 số ít): quảng cáo
C. advertised (động từ quá khứ/tính từ): đã quảng cáo
D. advertise (động từ): quảng cáo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2498, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3310, 2498, 110, 'Laboratory chemicals should be stored no ---- than eye level and never on top of a tall cabinet.', 'upper', 'further', 'longer', 'higher', 'D', 'Đáp án đúng là D (higher - tính từ so sánh). Giải thích: Câu này cần một tính từ so sánh chỉ độ cao. "Higher" (cao hơn) phù hợp nhất trong ngữ cảnh này để chỉ ra giới hạn độ cao cho việc lưu trữ hóa chất.
Dịch: Hóa chất trong phòng thí nghiệm không nên được lưu trữ cao hơn tầm mắt và không bao giờ được đặt trên đỉnh của tủ cao.
A. upper (tính từ): trên
B. further (tính từ so sánh): xa hơn
C. longer (tính từ so sánh): dài hơn
D. higher (tính từ so sánh): cao hơn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2499, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3311, 2499, 111, 'According to Reilly''s vehicle fleet manager, ---- company delivery vans will be serviced in August.', 'much', 'total', 'all', 'highly', 'C', 'Đáp án đúng là C (all - từ xác định). Giải thích: Câu này cần một từ xác định chỉ toàn bộ. "All" (tất cả) phù hợp nhất để chỉ ra rằng mọi xe van giao hàng đều sẽ được bảo dưỡng.
Dịch: Theo quản lý đội xe của Reilly, tất cả xe van giao hàng của công ty sẽ được bảo dưỡng vào tháng Tám.
A. much (từ xác định): nhiều
B. total (tính từ): tổng
C. all (từ xác định): tất cả
D. highly (trạng từ): rất');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2500, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3312, 2500, 112, 'Because airlines ----- revise baggage-check policies, passengers should check for updates before a flight.', 'occasion', 'occasional', 'occasions', 'occasionally', 'D', 'Đáp án đúng là D (occasionally - trạng từ). Giải thích: Câu này cần một trạng từ chỉ tần suất. "Occasionally" (thỉnh thoảng) phù hợp nhất để mô tả việc các hãng hàng không thường xuyên thay đổi chính sách.
Dịch: Vì các hãng hàng không thỉnh thoảng sửa đổi chính sách kiểm tra hành lý, hành khách nên kiểm tra các cập nhật trước chuyến bay.
A. occasion (danh từ): dịp
B. occasional (tính từ): thỉnh thoảng
C. occasions (danh từ số nhiều): các dịp
D. occasionally (trạng từ): thỉnh thoảng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2501, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3313, 2501, 113, 'Contracts for the Queen''s Landing project should be placed in an ------ stack on the supervisor''s desk.', 'organize', 'organizer', 'organized', 'organizing', 'C', 'Đáp án đúng là C (organized - tính từ). Giải thích: Câu này cần một tính từ mô tả cách sắp xếp các hợp đồng. "Organized" (có tổ chức) phù hợp nhất trong ngữ cảnh này.
Dịch: Các hợp đồng cho dự án Queen''s Landing nên được đặt trong một chồng có tổ chức trên bàn của người giám sát.
A. organize (động từ): tổ chức
B. organizer (danh từ): người tổ chức
C. organized (tính từ): có tổ chức
D. organizing (động từ hiện tại phân từ): đang tổ chức');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2502, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3314, 2502, 114, 'Some board members ----- that Mr. Saito''s sales forecasts are too optimistic.', 'need', 'pause', 'refuse', 'suspect', 'D', 'Đáp án đúng là D (suspect - động từ). Giải thích: Câu này cần một động từ chỉ sự nghi ngờ hoặc hoài nghi. "Suspect" (nghi ngờ) phù hợp nhất trong ngữ cảnh này.
Dịch: Một số thành viên hội đồng quản trị nghi ngờ rằng dự báo doanh số của ông Saito quá lạc quan.
A. need (động từ): cần
B. pause (động từ): tạm dừng
C. refuse (động từ): từ chối
D. suspect (động từ): nghi ngờ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2503, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3315, 2503, 115, 'Ms. Koffler is confident --- the new manager will improve the department''s productivity.', 'in', 'well', 'that', 'both', 'C', 'Đáp án đúng là C (that - liên từ). Giải thích: Câu này cần một liên từ để nối mệnh đề chính với mệnh đề phụ. "That" phù hợp nhất trong cấu trúc "be confident that" (tin tưởng rằng).
Dịch: Bà Koffler tin tưởng rằng người quản lý mới sẽ cải thiện năng suất của bộ phận.
A. in (giới từ): trong
B. well (trạng từ): tốt
C. that (liên từ): rằng
D. both (từ xác định): cả hai');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2504, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3316, 2504, 116, 'The wooden barn on the Eastwood property is so ----- deteriorated that it is unlikely to be salvaged.', 'formerly', 'badly', 'briefly', 'exactly', 'B', 'Đáp án đúng là B (badly - trạng từ). Giải thích: Câu này cần một trạng từ mô tả mức độ hư hỏng. "Badly" (nghiêm trọng) phù hợp nhất trong cấu trúc "so ... that" (quá ... đến nỗi).
Dịch: Chuồng gỗ trên khu đất Eastwood bị hư hỏng quá nghiêm trọng đến nỗi không thể khôi phục được.
A. formerly (trạng từ): trước đây
(B) tệ
(C) ngắn gọ
(D) chính xác');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2505, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3317, 2505, 117, 'Roseville Resort is offering discounted accommodations ------ its first month of operation.', 'during', 'among', 'in front of', 'away from', 'A', 'Đáp án đúng là A (during - giới từ). Giải thích: Câu này cần một giới từ chỉ thời gian. "During" (trong suốt) phù hợp nhất để chỉ ra khoảng thời gian của ưu đãi.
Dịch: Khu nghỉ dưỡng Roseville đang cung cấp chỗ ở giảm giá trong tháng đầu tiên hoạt động.
A. during (giới từ): trong suốt
B. among (giới từ): giữa
C. in front of (cụm giới từ): trước
D. away from (cụm giới từ): cách xa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2506, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3318, 2506, 118, 'Although the look of the new mobile phone model is ---- the previous one, the call quality is much improved.', 'similar to', 'involved in', 'happy with', 'occupied by', 'A', 'Đáp án đúng là A (similar to - cụm từ). Giải thích: Câu này cần một cụm từ chỉ sự tương đồng. "Similar to" (giống với) phù hợp nhất để so sánh hai mẫu điện thoại.
Dịch: Mặc dù vẻ ngoài của mẫu điện thoại di động mới giống với mẫu trước đó, chất lượng cuộc gọi đã được cải thiện nhiều.
A. similar to (cụm từ): giống với
B. involved in (cụm từ): tham gia vào
C. happy with (cụm từ): hài lòng với
D. occupied by (cụm từ): bị chiếm bởi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2507, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3319, 2507, 119, 'Dr. Simone Beaumont ----- to head of Research and Development at Brodeur Technology last week.', 'promoted', 'was promoted', 'promotes', 'is promoting', 'B', 'Đáp án đúng là B (was promoted - động từ bị động quá khứ). Giải thích: Câu này cần một động từ ở thì quá khứ bị động để chỉ sự thăng chức đã xảy ra. "Was promoted" (đã được thăng chức) phù hợp nhất trong ngữ cảnh này.
Dịch: Tiến sĩ Simone Beaumont đã được thăng chức lên vị trí trưởng bộ phận Nghiên cứu và Phát triển tại Brodeur Technology vào tuần trước.
A. promoted (động từ quá khứ): đã thăng chức
B. was promoted (động từ bị động quá khứ): đã được thăng chức
C. promotes (động từ hiện tại): thăng chức
D. is promoting (động từ hiện tại tiếp diễn): đang thăng chức');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2508, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3320, 2508, 120, 'Enertek Industries is developing an ----- safe method for refining lithium.', 'environmentalist', 'environments', 'environmental', 'environmentally', 'D', 'Đáp án đúng là D (environmentally - trạng từ). Giải thích: Câu này cần một trạng từ bổ nghĩa cho tính từ "safe". "Environmentally safe" (an toàn về mặt môi trường) là cụm từ phổ biến trong ngữ cảnh này.
Dịch: Enertek Industries đang phát triển một phương pháp an toàn về mặt môi trường để tinh chế lithium.
A. environmentalist (danh từ): nhà môi trường học
B. environments (danh từ số nhiều): môi trường
C. environmental (tính từ): thuộc về môi trường
D. environmentally (trạng từ): về mặt môi trường');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2509, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3321, 2509, 121, 'Before starting the motor, make sure the brake is -------.', 'engage', 'engages', 'engagement', 'engaged', 'D', 'Đáp án đúng là D (engaged - tính từ/động từ quá khứ phân từ). Giải thích: Câu này cần một tính từ hoặc động từ quá khứ phân từ để mô tả trạng thái của phanh. "Engaged" (được gài) phù hợp nhất trong ngữ cảnh này.
Dịch: Trước khi khởi động động cơ, hãy đảm bảo phanh được gài.
A. engage (động từ): gài
B. engages (động từ, ngôi thứ 3 số ít): gài
C. engagement (danh từ): sự gài
D. engaged (tính từ/động từ quá khứ phân từ): được gài');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2510, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3322, 2510, 122, 'Henderson Technical College offers introductory computer ------ for free to community members.', 'purchases', 'lessons', 'graphics', 'users', 'B', 'Đáp án đúng là B (lessons - danh từ). Giải thích: Câu này cần một danh từ chỉ các bài học. "Lessons" (bài học) phù hợp nhất trong ngữ cảnh của khóa học máy tính.
Dịch: Trường Cao đẳng Kỹ thuật Henderson cung cấp miễn phí các bài học máy tính cơ bản cho các thành viên cộng đồng.
A. purchases (danh từ): mua sắm
B. lessons (danh từ): bài học
C. graphics (danh từ): đồ họa
D. users (danh từ): người dùng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2511, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3323, 2511, 123, 'No fees will be charged for the time the agency ---- to search for records.', 'looks', 'examines', 'takes', 'inspects', 'C', 'Đáp án đúng là C (takes - động từ). Giải thích: Câu này cần một động từ chỉ việc sử dụng thời gian. "Takes" (mất) phù hợp nhất trong cụm "take time to do something" (mất thời gian để làm gì).
Dịch: Sẽ không tính phí cho thời gian mà cơ quan mất để tìm kiếm hồ sơ.
A. looks (động từ): nhìn
B. examines (động từ): kiểm tra
C. takes (động từ): mất
D. inspects (động từ): kiểm tra');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2512, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3324, 2512, 124, 'The Durand Concert Hall, ----- was built 80 years ago, has undergone a complete renovation.', 'where', 'each', 'there', 'which', 'D', 'Đáp án đúng là D (which - đại từ quan hệ). Giải thích: Câu này cần một đại từ quan hệ để giới thiệu thông tin bổ sung về Concert Hall. "Which" phù hợp nhất để chỉ vật trong mệnh đề quan hệ không giới hạn.
Dịch: Nhà hát Durand, vốn được xây dựng cách đây 80 năm, đã trải qua một cuộc đại tu hoàn toàn.
A. where (trạng từ quan hệ): nơi mà
B. each (đại từ): mỗi
C. there (trạng từ): ở đó
D. which (đại từ quan hệ): cái mà');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2513, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3325, 2513, 125, 'There may be flaws in the computer code that we are not ------ aware of.', 'yet', 'soon', 'far', 'lately', 'A', 'Đáp án đúng là A (yet - trạng từ). Giải thích: Câu này cần một trạng từ chỉ thời gian để nhấn mạnh sự chưa nhận biết. "Yet" (còn) phù hợp nhất trong cấu trúc phủ định "not ... yet" (chưa).
Dịch: Có thể có những lỗi trong mã máy tính mà chúng ta còn chưa nhận thức được.
A. yet (trạng từ): còn
B. soon (trạng từ): sớm
C. far (trạng từ): xa
D. lately (trạng từ): gần đây');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2514, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3326, 2514, 126, '------ who wishes to make a monetary gift to the Voltra Museum should fill out the form at the back of the brochure.', 'Anyone', 'Whichever', 'Each other', 'Those', 'A', 'Đáp án đúng là A (Anyone - đại từ). Giải thích: Câu này cần một đại từ không xác định chỉ bất kỳ người nào. "Anyone" (bất kỳ ai) phù hợp nhất trong ngữ cảnh này.
Dịch: Bất kỳ ai muốn tặng quà bằng tiền cho Bảo tàng Voltra nên điền vào mẫu đơn ở mặt sau của tờ rơi.
A. Anyone (đại từ): bất kỳ ai
B. Whichever (đại từ): bất kỳ cái nào
C. Each other (cụm đại từ): lẫn nhau
D. Those (đại từ): những người đó');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2515, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3327, 2515, 127, 'Companies that seek a stable workforce should focus on employee ---- as well as recruitment.', 'agents', 'coverage', 'retention', 'authentication', 'C', 'Đáp án đúng là C (retention - danh từ). Giải thích: Câu này cần một danh từ chỉ việc giữ chân nhân viên. "Retention" (sự giữ chân) phù hợp nhất trong ngữ cảnh quản lý nhân sự.
Dịch: Các công ty tìm kiếm lực lượng lao động ổn định nên tập trung vào việc giữ chân nhân viên cũng như tuyển dụng.
A. agents (danh từ): đại lý
B. coverage (danh từ): phạm vi bảo hiểm
C. retention (danh từ): sự giữ chân
D. authentication (danh từ): xác thực');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2516, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3328, 2516, 128, '---- a new user-friendly interface on its Web site, the Kramer-Lee Company reported improved customer satisfaction.', 'Furthermore', 'Owing to', 'Subsequently', 'At one time', 'B', 'Đáp án đúng là B (Owing to - cụm giới từ). Giải thích: Câu này cần một cụm từ chỉ nguyên nhân. "Owing to" (nhờ vào) phù hợp nhất để giải thích lý do sự hài lòng của khách hàng tăng lên.
Dịch: Nhờ vào giao diện thân thiện với người dùng mới trên trang web của mình, công ty Kramer-Lee báo cáo sự hài lòng của khách hàng đã được cải thiện.
A. Furthermore (liên từ): hơn nữa
B. Owing to (cụm giới từ): nhờ vào
C. Subsequently (trạng từ): sau đó
D. At one time (cụm từ): một thời');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2517, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3329, 2517, 129, 'Chef Wingert is reluctant to open a second location of Antoine''s Pizza ---- interest from many of his customers.', 'overall', 'in addition to', 'despite', 'on the whole', 'C', 'Đáp án đúng là C (despite - giới từ). Giải thích: Câu này cần một giới từ chỉ sự đối lập. "Despite" (mặc dù) phù hợp nhất để chỉ ra sự mâu thuẫn giữa sự miễn cưỡng của đầu bếp và sự quan tâm của khách hàng.
Dịch: Đầu bếp Wingert miễn cưỡng mở địa điểm thứ hai của Antoine''s Pizza mặc dù có sự quan tâm từ nhiều khách hàng của ông.
A. overall (trạng từ): nói chung
B. in addition to (cụm giới từ): bên cạnh
C. despite (giới từ): mặc dù
D. on the whole (cụm từ): nhìn chung');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2518, 117, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3330, 2518, 130, '—-- thinking by Ms. Blakely''s marketing team helped increase sales of the Mindi motorcycle.', 'Relative', 'Potential', 'Distant', 'Creative', 'D', 'Đáp án đúng là D (Creative - tính từ). Giải thích: Câu này cần một tính từ mô tả cách suy nghĩ của đội marketing. "Creative" (sáng tạo) phù hợp nhất trong ngữ cảnh của việc tăng doanh số.
Dịch: Tư duy sáng tạo của đội marketing của bà Blakely đã giúp tăng doanh số bán xe máy Mindi.
A. Relative (tính từ): tương đối
B. Potential (tính từ): tiềm năng
C. Distant (tính từ): xa xôi
D. Creative (tính từ): sáng tạo');;

