INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3401, 2538, 1, NULL, 'She''s writing on a document.', 'She''s looking at some framed artwork.', 'She''s opening a folder.', 'She''s organizing a desk drawer.', 'A', 'A: Cô ấy đang viết trên một tài liệu.
