INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3404, 2541, 4, NULL, 'A walkway is being swept clean.', 'Some people are walking through an intersection.', 'One of the people is leaning against a wall.', 'One of the people is fixing a bicycle tire.', 'C', 'A: Một lối đi đang được quét sạch.
