INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3405, 2542, 5, NULL, 'A customer is loading items into a shopping bag.', 'Some products have been set out under tents.', 'A bowl has been filled with water.', 'Some baskets are hanging from a post.', 'B', 'A: Một khách hàng đang xếp hàng hóa vào túi mua sắm.
