INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3414, 2551, 14, 'When do you need a copy of the contract?', 'As soon as possible.', 'A savings account at the bank.', 'Sure-here''s my contact information.', NULL, 'A', 'Bạn cần bản sao hợp đồng khi nào?
