INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3418, 2555, 18, 'Are you looking for a one-bedroom or a two-bedroom apartment?', 'No, I''ve had enough coffee today.', 'A two-bedroom apartment with a balcony.', 'At the home-improvement store.', NULL, 'B', 'Bạn đang tìm kiếm căn hộ một phòng ngủ hay hai phòng ngủ?
