INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2556, 121, '2023/test8/audio/test8_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3419, 2556, 19, 'You should include an image on each page of the book.', 'The bookstore is closed.', 'Yes, that''s a good idea.', 'A job as a graphic designer.', NULL, 'B', 'Bạn nên bao gồm hình ảnh trên mỗi trang của cuốn sách.
Hiệu sách đang đóng cửa.
Vâng, đó là một ý tưởng hay.
Một công việc như nhà thiết kế đồ họa.');;
