INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3420, 2557, 20, 'How do I make changes to this section of the Web site?', 'Only five more times.', 'Let me show you.', 'Can I preorder my meal?', NULL, 'B', 'Tôi làm thế nào để thay đổi phần này của trang web?
Chỉ còn năm lần nữa.
Để tôi chỉ cho bạn.
