INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3421, 2558, 21, 'Will you be working a half day or a full day?', 'My project deadline is tomorrow.', 'Here''s an empty glass.', 'About 73 euros.', NULL, 'A', 'Bạn sẽ làm việc nửa ngày hay cả ngày?
