INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3422, 2559, 22, 'There''s an opening in my department for an accountant.', 'I have some experience with that.', 'They agreed to participate.', 'No, the store is closed.', NULL, 'A', 'Có một vị trí trống trong phòng ban của tôi cho một kế toán.
Tôi có một số kinh nghiệm về điều đó.
