INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3425, 2562, 25, 'Why don''t we rent a bigger booth at this year''s conference?', 'The conference call went really well.', 'Our budget is very tight.', 'I think the vent on the dryer is clogged.', NULL, 'B', 'Tại sao chúng ta không thuê một gian hàng lớn hơn tại hội nghị năm nay?
Cuộc gọi hội nghị đã diễn ra rất tốt.
Ngân sách của chúng ta rất eo hẹp.
Tôi nghĩ ống thông hơi trên máy sấy bị tắc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2563, 121, '2023/test8/audio/test8_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3426, 2563, 26, 'Carmen''s computer needs to be repaired, doesn''t it?', 'She bought a new one.', 'I''ll bring a pair of gloves on the hike.', 'A degree in computer science.', NULL, 'A', 'Máy tính của Carmen cần được sửa chữa, phải không?
Cô ấy đã mua một cái mới.
Tôi sẽ mang theo một đôi găng tay trong chuyến đi bộ đường dài.
Một bằng cấp về khoa học máy tính.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2564, 121, '2023/test8/audio/test8_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3427, 2564, 27, 'Who are the candidates for new branch manager?', 'Yes, I do like my new office.', 'No, I''m not available at that time.', 'We''re still accepting applications.', NULL, 'C', 'Ai là các ứng viên cho quản lý chi nhánh mới?
Vâng, tôi thực sự thích văn phòng mới của mình.
Không, tôi không có mặt vào thời gian đó.
Chúng tôi vẫn đang nhận đơn đăng ký.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2565, 121, '2023/test8/audio/test8_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3428, 2565, 28, 'Did the focus group like the advertisement we designed?', 'Some well-known magazines.', 'We''ll need to make some changes.', 'Turn left at the stop sign.', NULL, 'B', 'Nhóm tập trung có thích quảng cáo mà chúng ta thiết kế không?
Một số tạp chí nổi tiếng.
Chúng ta sẽ cần thực hiện một số thay đổi.
Rẽ trái tại biển báo dừng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2566, 121, '2023/test8/audio/test8_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3429, 2566, 29, 'Please let me know when you arrive in Osaka.', 'The clients are great to work with.', 'How many did you buy?', 'I always carry my smartphone with me.', NULL, 'C', 'Vui lòng cho tôi biết khi bạn đến Osaka.
Khách hàng rất tuyệt để làm việc cùng.
Bạn đã mua bao nhiêu?
Tôi luôn mang theo điện thoại thông minh của mình.');;
