INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2638, 124, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3501, 2638, 101, 'The building contract was —- awarded to Zhong Builders of Manchester.', 'slowly', 'exactly', 'greatly', 'recently', 'D', 'Đáp án đúng là D (recently - trạng từ). Giải thích: Câu này cần một trạng từ chỉ thời gian gần đây. "Recently" (gần đây) phù hợp nhất trong ngữ cảnh này.
Dịch: Hợp đồng xây dựng gần đây đã được trao cho Zhong Builders của Manchester.
A. slowly (trạng từ): chậm rãi
B. exactly (trạng từ): chính xác
C. greatly (trạng từ): rất
D. recently (trạng từ): gần đây');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2639, 124, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3502, 2639, 102, 'A small salad is included with the lunch special ----- Wednesday.', 'as', 'every', 'eventually', 'those', 'B', 'Đáp án đúng là B (every - tính từ). Giải thích: Câu này cần một từ chỉ tần suất. "Every" (mỗi) phù hợp nhất để chỉ ra rằng salad được bao gồm vào mỗi thứ Tư.
Dịch: Một món salad nhỏ được bao gồm trong bữa trưa đặc biệt mỗi thứ Tư.
A. as (liên từ): như
B. every (tính từ): mỗi
C. eventually (trạng từ): cuối cùng
D. those (đại từ chỉ định): những');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2640, 124, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3503, 2640, 103, 'Mapsoar Airways redesigned its seats to make it much ----- to recline them.', 'easy', 'easily', 'easier', 'ease', 'C', 'Đáp án đúng là C (easier - tính từ so sánh). Giải thích: Câu này cần một tính từ so sánh sau "much". "Easier" (dễ dàng hơn) phù hợp nhất trong ngữ cảnh này.
Dịch: Mapsoar Airways đã thiết kế lại ghế ngồi để làm cho việc ngả lưng ghế dễ dàng hơn nhiều.
A. easy (tính từ): dễ dàng
B. easily (trạng từ): một cách dễ dàng
C. easier (tính từ so sánh): dễ dàng hơn
D. ease (danh từ): sự dễ dàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2641, 124, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3504, 2641, 104, 'Employees may visit the company cafeteria on weekday evenings ---- 8:00 P.M.', 'since', 'until', 'along', 'over', 'B', 'Đáp án đúng là B (until - giới từ). Giải thích: Câu này cần một giới từ chỉ thời gian. "Until" (cho đến) phù hợp nhất để chỉ ra thời điểm kết thúc.
Dịch: Nhân viên có thể đến căn tin công ty vào các buổi tối ngày thường cho đến 8:00 tối.
A. since (giới từ): từ khi
B. until (giới từ): cho đến
C. along (giới từ): dọc theo
D. over (giới từ): trên');;
