INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3509, 2646, 109, 'Lucior Shoes saw a ----- in expenses after adjusting its production processes.', 'drop', 'drops', 'dropped', 'to drop', 'A', 'Đáp án đúng là A (drop - danh từ). Giải thích: Câu này cần một danh từ chỉ sự giảm sút. "Drop" (sự sụt giảm) phù hợp nhất trong ngữ cảnh này.
