INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3518, 2655, 118, 'Mr. Melo argued that Vantimore''s inventory tracking system is too ------.', 'complexes', 'complex', 'complexity', 'complexness', 'B', 'Đáp án đúng là B (complex - tính từ). Giải thích: Câu này cần một tính từ sau "too". "Complex" (phức tạp) phù hợp nhất trong ngữ cảnh này.
