INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3581, 2706, 181, 'What does Mr. Landis think about the restaurant''s menu?', 'There are too few vegetarian options.', 'He preferred the restaurant''s previous menu.', 'The dessert pizzas are too expensive.', 'He does not care for the taste of the signature pizzas.', 'D', 'Đáp án đúng là D vì trong bài đánh giá, Mr. Landis nói "I personally did not like the maple-flavored pizza at all", cho thấy ông không thích mùi vị của các loại pizza đặc trưng (signature pizzas) của nhà hàng.
A. Có quá ít lựa chọn cho người ăn chay: Không được đề cập trong bài đánh giá.
B. Ông thích thực đơn trước đây của nhà hàng hơn: Không được đề cập, đây là một nhà hàng mới.
C. Các pizza tráng miệng quá đắt: Không được đề cập trong bài đánh giá.
D. Ông không thích mùi vị của các loại pizza đặc trưng: Đúng, phù hợp với nhận xét của Mr. Landis trong bài đánh giá.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2707, 126, NULL, NULL, NULL, '-');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3582, 2707, 182, 'In the review, the word "sweet" in paragraph 1, line 5, is closest in meaning to', 'moderate', 'pleasing', 'sugary', 'dear', 'C', 'Đáp án đúng là C vì trong ngữ cảnh này, "sweet" được sử dụng để mô tả hương vị của pizza tráng miệng, và "sugary" (ngọt như đường) là từ đồng nghĩa gần nhất với ý nghĩa này.
A. moderate (vừa phải): Không phù hợp với ngữ cảnh, vì tác giả mô tả nó là "overly sweet" (quá ngọt).
B. pleasing (dễ chịu): Không phù hợp với ngữ cảnh, vì tác giả không thích món pizza này.
C. sugary (ngọt như đường): Đúng, phù hợp nhất với ý nghĩa của "sweet" trong ngữ cảnh này.
D. dear (đắt): Không phù hợp với ngữ cảnh, vì từ "sweet" ở đây đang mô tả hương vị, không phải giá cả.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2708, 126, NULL, NULL, NULL, '-');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3583, 2708, 183, 'How much was the pizza that Mr. Landis'' group ordered for their main course?', '£5,00', '£11,00', '£13,00', '£17,00', 'D', 'Đáp án đúng là D (£17) vì bài đánh giá đề cập rằng nhóm của Mr. Landis đã thưởng thức "a large maple-ham pizza as a main course". Theo menu, pizza phong-giăm bông (maple ham) cỡ lớn có giá £17.
A. £5: Đây là giá của pizza phong-giăm bông cỡ cá nhân, không phải cỡ lớn.
B. £11: Đây là giá của pizza tráng miệng, không phải pizza chính.
C. £13: Đây là giá của pizza truyền thống cỡ lớn, không phải pizza phong-giăm bông.
D. £17: Đúng, đây là giá của pizza phong-giăm bông cỡ lớn mà nhóm đã gọi làm món chính.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2709, 126, NULL, NULL, NULL, '-');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3584, 2709, 184, 'Which pizza is available with a white sauce?', 'Maple ham', 'Pineapple', 'Meatball', 'Cinnamon maple', 'C', 'Đáp án đúng là C vì theo menu, pizza thịt viên (Meatball) nằm trong danh mục "Traditional Pizzas" và có ghi chú "(select red or white sauce)", nghĩa là có thể chọn sốt đỏ hoặc trắng.
A. Maple ham: Chỉ có sốt đỏ theo menu.
B. Pineapple: Chỉ có sốt đỏ theo menu.
C. Meatball: Đúng, có thể chọn sốt đỏ hoặc trắng.
D. Cinnamon maple: Chỉ có sốt bơ nâu theo menu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2710, 126, NULL, NULL, NULL, '-');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3585, 2710, 185, 'What is suggested about the restaurant?', 'It prepares dessert pizza in only one size.', 'It accepts payments in cash only.', 'It makes home deliveries.', 'It has moved to a larger location.', 'A', 'Đáp án đúng là A vì theo menu, các pizza tráng miệng chỉ được liệt kê với một mức giá, không như các loại pizza khác có cả giá cho cỡ cá nhân và cỡ lớn. Điều này gợi ý rằng nhà hàng chỉ chuẩn bị pizza tráng miệng với một kích cỡ.
A. Nó chuẩn bị pizza tráng miệng chỉ với một kích cỡ: Đúng, phù hợp với thông tin trong menu.
B. Nó chỉ chấp nhận thanh toán bằng tiền mặt: Không đúng, nhà hàng có ghi "We now accept credit cards" (Chúng tôi hiện chấp nhận thẻ tín dụng).
C. Nó có dịch vụ giao hàng tận nhà: Không được đề cập trong thông tin cung cấp.
D. Nó đã chuyển đến một địa điểm lớn hơn: Không được đề cập trong thông tin cung cấp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2711, 126, NULL, NULL, 'Questions 186-190 refer to the following Web page, contact form, and e-mail.

