INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2726, 127, '2023/test9/audio/test9_question_1.mp3', '2023/test9/image/test9-image-1.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3601, 2726, 1, NULL, 'She''s stepping off a curb.', 'She''s walking down a hallway.', 'She''s waiting in line for a bus.', 'She''s wearing a backpack.', 'D', 'A: Cô ấy đang bước xuống vỉa hè.
B: Cô ấy đang đi dọc theo hành lang.
C: Cô ấy đang đợi xếp hàng cho một chiếc xe buýt.
D: Cô ấy đang đeo một chiếc ba lô.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2727, 127, '2023/test9/audio/test9_question_2.mp3', '2023/test9/image/test9-image-2.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3602, 2727, 2, NULL, 'Some clothing has fallen off a counter.', 'Clothes are on display on a rack.', 'The man is putting an item into a cart.', 'The man is folding jackets in a store.', 'B', 'A: Một số quần áo đã rơi khỏi quầy.
B: Quần áo được trưng bày trên một giá.
C: Người đàn ông đang đặt một món đồ vào xe đẩy.
D: Người đàn ông đang gấp áo khoác trong cửa hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2728, 127, '2023/test9/audio/test9_question_3.mp3', '2023/test9/image/test9-image-3.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3603, 2728, 3, NULL, 'One of the people is putting on sunglasses.', 'One of the people is climbing some stairs.', 'One of the people is posing for a photograph.', 'One of the people is opening a gate.', 'C', 'A: Một trong những người đang đeo kính râm.
B: Một trong những người đang leo một vài bậc thang.
C: Một trong những người đang tạo dáng cho một bức ảnh.
D: Một trong những người đang mở một cổng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2729, 127, '2023/test9/audio/test9_question_4.mp3', '2023/test9/image/test9-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3604, 2729, 4, NULL, 'A floor is covered with boxes.', 'A sign is leaning against a wall.', 'Some pillows are organized on shelves.', 'Some lamps have been placed on the floor.', 'C', 'A: Sàn nhà được phủ đầy hộp.
B: Một biển hiệu đang nghiêng về phía tường.
C: Một số gối được sắp xếp trên kệ.
D: Một số đèn đã được đặt trên sàn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2730, 127, '2023/test9/audio/test9_question_5.mp3', '2023/test9/image/test9-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3605, 2730, 5, NULL, 'She''s lifting a bag of groceries.', 'She''s talking on a mobile phone.', 'She''s standing on a stepladder.', 'She''s reaching for a light switch.', 'C', 'A: Cô ấy đang nâng một túi hàng tạp hóa.
B: Cô ấy đang nói chuyện trên điện thoại di động.
C: Cô ấy đang đứng trên một thang đẩy.
D: Cô ấy đang vươn tay để bật công tắc đèn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (2731, 127, '2023/test9/audio/test9_question_6.mp3', '2023/test9/image/test9-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3606, 2731, 6, NULL, 'He''s planting some bushes.', 'He''s weeding a flower bed.', 'He''s installing a door.', 'He''s holding a hammer.', 'D', 'A: Anh ấy đang trồng một số bụi cây.
B: Anh ấy đang nhổ cỏ trong một luống hoa.
C: Anh ấy đang lắp đặt một cánh cửa.
D: Anh ấy đang cầm một cái búa.');;

