INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3816, 2890, 16, 'How will we get this order filled in time?', 'Would you like soup or salad?', 'Maria goes there, too.', 'We''ll have to work extra hours.', NULL, 'C', 'Chúng ta sẽ làm sao để đơn hàng này được hoàn thành đúng hạn?
