INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3817, 2891, 17, 'Do you have the gate code, or should I look it up?', 'It was recently painted.', 'I have the number.', 'A two-year lease.', NULL, 'B', 'Bạn có mã cổng không, hay tôi nên tra cứu?
