INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (3915, 2989, 115, 'Last July, Rojas Rieper LLC ----- a grand opening celebration.', 'hosts', 'hosted', 'will host', 'is hosting', 'B', 'Đáp án đúng là B (hosted - động từ quá khứ). Giải thích: Câu này có từ chỉ thời gian quá khứ "Last July" nên cần một động từ ở thì quá khứ đơn.
