INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3024, 141, '2024/test1/audio/test1-audio-1.mp3', '2024/test1/image/test1-image-1.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4001, 3024, 1, 'Look at the picture marked number one in your test book.', 'She''s eating in a picnic area.', 'She''s waiting in line at a food truck.', 'She''s wiping off a bench.', 'She''s throwing away a plate.', 'A', 'A: Cô ấy đang ăn ở khu vực dã ngoại là mô tả đúng nhất.
B: Cô ấy đang xếp hàng tại xe bán thức ăn không phù hợp.
C: Cô ấy đang lau ghế không phải là hình ảnh đúng.
D: Cô ấy đang vứt bỏ đĩa không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3025, 141, '2024/test1/audio/test1-audio-2.mp3', '2024/test1/image/test1-image-2.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4002, 3025, 2, 'Look at the picture marked number two in your test book.', 'The man is brushing snow off the roof of a car.', 'The man is standing in the snow beside a car.', 'The man is shoveling snow from a walkway.', 'The man is running through the snow.', 'B', 'A: Người đàn ông đang quét tuyết trên mái xe không đúng.
B: Người đàn ông đứng cạnh chiếc xe trong tuyết là mô tả đúng nhất.
C: Người đàn ông đang xúc tuyết không phải là hình ảnh đúng.
D: Người đàn ông chạy trong tuyết không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3026, 141, '2024/test1/audio/test1-audio-3.mp3', '2024/test1/image/test1-image-3.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4003, 3026, 3, 'Look at the picture marked number three in your test book.', 'Some workers are hanging art in a gallery.', 'Two of the people are having a conversation.', 'One of the men is rearranging cushions on a sofa.', 'One of the men is painting a picture.', 'B', 'A: Một số công nhân đang treo tranh không phải là mô tả đúng.
B: Hai người đang trò chuyện là mô tả đúng nhất.
C: Một trong những người đàn ông sắp xếp lại đệm không phù hợp.
D: Một trong những người đàn ông đang vẽ tranh không phải là hình ảnh đúng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3027, 141, '2024/test1/audio/test1-audio-4.mp3', '2024/test1/image/test1-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4004, 3027, 4, 'Look at the picture marked number four in your test book.', 'Vehicles are entering a parking garage.', 'Clothes hangers are scattered on the ground.', 'Empty racks are lined up next to a building.', 'Clothing is being displayed under a tent.', 'D', 'A: Các phương tiện đang đi vào nhà để xe không phù hợp.
B: Móc áo bị vương vãi trên mặt đất không phải là mô tả đúng.
C: Giá trống được xếp hàng cạnh tòa nhà không đúng.
D: Quần áo đang được trưng bày dưới lều là mô tả đúng nhất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3028, 141, '2024/test1/audio/test1-audio-5.mp3', '2024/test1/image/test1-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4005, 3028, 5, 'Look at the picture marked number five in your test book.', 'Potted plants have been suspended from a ceiling.', 'Chairs have been stacked in front of an entryway.', 'A computer station has been set up on a desk.', 'A rug has been rolled up against a wall.', 'C', 'A: Các chậu cây được treo từ trần nhà không phù hợp.
B: Ghế xếp chồng trước lối vào không phải là hình ảnh đúng.
C: Máy tính được thiết lập trên bàn là mô tả đúng nhất.
D: Thảm cuộn lại không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3029, 141, '2024/test1/audio/test1-audio-6.mp3', '2024/test1/image/test1-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4006, 3029, 6, 'Look at the picture marked number six in your test book.', 'One of the men is sweeping a patio.', 'One of the men is replacing some flooring.', 'A door has been taken off its frame.', 'A light fixture has been left on the ground.', 'C', 'A: Một người đàn ông đang quét sân không đúng.
B: Một người đàn ông thay thế sàn không phù hợp.
C: Cánh cửa bị tháo ra khỏi khung là mô tả đúng nhất.
D: Đèn chiếu sáng bị bỏ lại trên mặt đất không phù hợp.');;

