INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3030, 142, '2024/test1/audio/test1-audio-7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4007, 3030, 7, 'How old is this building?', 'To ship some materials.', 'About ten years old.', 'Company offices, I think.', NULL, 'B', '7,Câu hỏi: Tòa nhà này bao nhiêu tuổi?
