INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4008, 3031, 8, 'Can you come to my jazz performance tonight?', 'I''m sorry I was late for the meeting.', 'Mostly just local musicians.', 'Sure, I''ll be there.', NULL, 'C', '8,Câu hỏi: Bạn có thể đến buổi biểu diễn jazz của tôi tối nay không?
A. Tôi xin lỗi vì đã đến muộn cho cuộc họp.
B. Chủ yếu chỉ là các nhạc sĩ địa phương.
C. Chắc chắn, tôi sẽ đến.
Đáp án đúng là: C.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3032, 142, '2024/test1/audio/test1-audio-9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4009, 3032, 9, 'Which apartment submitted a work order?', 'It''s what you did for a living.', 'Submit your assignment here.', 'It came from the tenants in B23.', NULL, 'C', '9,Câu hỏi: Căn hộ nào đã gửi đơn yêu cầu?
A. Đó là công việc bạn đã làm.
B. Gửi bài tập của bạn ở đây.
C. Nó đến từ các cư dân trong B23.
Đáp án đúng là: C.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3033, 142, '2024/test1/audio/test1-audio-10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4010, 3033, 10, 'Will you contact the vendor about changing our delivery date?', 'Of course, I''ll take care of it.', 'An email receipt.', 'Could I get change for a dollar?', NULL, 'A', '10,Câu hỏi: Bạn có liên hệ với nhà cung cấp về việc thay đổi ngày giao hàng không?
A. Tất nhiên, tôi sẽ lo liệu điều đó.
B. Một biên lai qua email.
C. Tôi có thể nhận được tiền lẻ cho một đồng không?
Đáp án đúng là: A.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3034, 142, '2024/test1/audio/test1-audio-11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4011, 3034, 11, 'Why was the maintenance worker here?', 'No, he didn''t.', 'From 3 o''clock until 4.', 'Because a light needed to be fixed.', NULL, 'C', '11,Câu hỏi: Tại sao công nhân bảo trì lại ở đây?
A. Không, anh ấy không.
B. Từ 3 giờ đến 4 giờ.
C. Bởi vì một cái đèn cần được sửa.
Đáp án đúng là: C.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3035, 142, '2024/test1/audio/test1-audio-12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4012, 3035, 12, 'Did management make a hiring decision yet?', 'Put it on the highest shelf.', 'The personnel department.', 'Yes, they chose Jacob Borgman.', NULL, 'C', '12,Câu hỏi: Ban quản lý đã đưa ra quyết định tuyển dụng chưa?
A. Đặt nó trên kệ cao nhất.
B. Bộ phận nhân sự.
C. Có, họ đã chọn Jacob Borgman.
Đáp án đúng là: C.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3036, 142, '2024/test1/audio/test1-audio-13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4013, 3036, 13, 'Do you want to eat here in our cafeteria or go out?', 'He went there yesterday.', 'Well, maybe a sandwich.', 'Let''s eat here.', NULL, 'C', '13,Câu hỏi: Bạn muốn ăn ở căng tin của chúng tôi hay ra ngoài?
A. Anh ấy đã đi đến đó hôm qua.
B. Chà, có thể là một cái bánh sandwich.
C. Hãy ăn ở đây.
Đáp án đúng là: C.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3037, 142, '2024/test1/audio/test1-audio-14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4014, 3037, 14, 'Didn''t you email the employment contract to Mr. Patel yesterday?', 'Yes, I would agree.', 'No, I''ll send it now.', 'Check the employee manual.', NULL, 'B', '14,Câu hỏi: Bạn đã gửi hợp đồng lao động cho ông Patel chưa?
A. Vâng, tôi đồng ý.
B. Không, tôi sẽ gửi ngay bây giờ.
C. Kiểm tra sổ tay nhân viên.
Đáp án đúng là: B.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3038, 142, '2024/test1/audio/test1-audio-15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4015, 3038, 15, 'Our division''s picnic is this Saturday, right?', 'There''s a lot of rain in the forecast.', 'Sure, I like salad.', 'At the end of this corridor.', NULL, 'A', '15,Câu hỏi: Buổi picnic của bộ phận chúng ta vào thứ Bảy này đúng không?
A. Có nhiều mưa trong dự báo.
B. Chắc chắn, tôi thích salad.
C. Ở cuối hành lang này.
Đáp án đúng là: A.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3039, 142, '2024/test1/audio/test1-audio-16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4016, 3039, 16, 'Would you like coffee or tea?', 'Just water, please.', 'For a few dollars more.', 'A 15-minute break.', NULL, 'A', '16,Câu hỏi: Bạn muốn uống cà phê hay trà?
A. Chỉ nước, làm ơn.
B. Với một vài đô la nữa.
C. Một khoảng nghỉ 15 phút.
Đáp án đúng là: A.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3040, 142, '2024/test1/audio/test1-audio-17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4017, 3040, 17, 'We achieved our sales targets this month.', 'That''s excellent news.', 'A few times a day.', 'To the end of April.', NULL, 'A', '17,Câu hỏi: Chúng ta đã đạt được mục tiêu doanh số trong tháng này.
A. Đó là tin tuyệt vời.
B. Một vài lần một ngày.
C. Đến cuối tháng Tư.
Đáp án đúng là: A.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3041, 142, '2024/test1/audio/test1-audio-18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4018, 3041, 18, 'How often do you travel for your job?', 'A few times a day.', 'It turned out well.', 'About once a month.', NULL, 'C', '18,Câu hỏi: Bạn thường xuyên đi công tác bao lâu một lần?
A. Một vài lần một ngày.
B. Nó đã diễn ra tốt đẹp.
C. Khoảng một lần một tháng.
Đáp án đúng là: C.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3042, 142, '2024/test1/audio/test1-audio-19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4019, 3042, 19, 'We should hike the Wildflower Trail today.', 'This seat is available.', 'I didn''t bring boots.', 'At the visitor''s center.', NULL, 'B', '19,Câu hỏi: Hôm nay chúng ta nên đi bộ đường Wildflower Trail.
A. Ghế này có sẵn.
B. Tôi không mang giày.
C. Tại trung tâm du khách.
Đáp án đúng là: B.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3043, 142, '2024/test1/audio/test1-audio-20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4020, 3043, 20, 'You''ve booked a hotel in London, haven''t you?', 'Very enjoyable, thanks.', 'He usually takes the train.', 'Yes, I made a reservation last week.', NULL, 'C', '20,Câu hỏi: Bạn đã đặt phòng khách sạn ở London, phải không?
A. Rất thú vị, cảm ơn.
B. Anh ấy thường đi bằng tàu.
C. Có, tôi đã đặt phòng tuần trước.
Đáp án đúng là: C.');;
