INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4026, 3049, 26, 'This film has been nominated for several awards.', 'Why don''t we go see it?', 'After the announcement.', 'He made a great speech.', NULL, 'A', '26,Câu hỏi: Bộ phim này đã được đề cử cho nhiều giải thưởng.
