INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4027, 3050, 27, 'Who''s interested in starting a carpool program?', 'Thanks, but I can''t swim.', 'Clara''s already organizing one.', 'It''s a very interesting article.', NULL, 'B', '27,Câu hỏi: Ai quan tâm đến việc bắt đầu một chương trình đi chung xe?
