INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4101, 3124, 101, 'Former Sendai Company CEO Ken Nakata spoke about ------- career experiences.', 'he', 'his', 'him', 'himself', 'B', 'Ken Nakata, cựu CEO của Công ty Sendai, đã nói về ------- kinh nghiệm sự nghiệp.
(A) he: đại từ chủ ngữ
(B) his: tính từ sở hữu
(C) him: đại từ tân ngữ
(D) himself: đại từ phản thân
Đáp án đúng là ''his'', vì đại từ sở hữu ''his'' phù hợp với danh từ ''career experiences''. Các lựa chọn khác không phù hợp với ngữ pháp và ngữ cảnh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3125, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4102, 3125, 102, 'Passengers who will be taking a ------- domestic flight should go to Terminal A.', 'connectivity', 'connects', 'connect', 'connecting', 'D', 'Hành khách sẽ bay chuyến bay ------- nội địa nên đi đến nhà ga A.
(A) connectivity: danh từ (sự kết nối)
(B) connects: động từ (kết nối)
(C) connect: động từ (kết nối)
(D) connecting: tính từ (kết nối, nối tiếp)
Đáp án đúng là ''connecting'', vì tính từ ''connecting'' phù hợp với danh từ ''flight''. Các lựa chọn khác không phù hợp với ngữ pháp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3126, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4103, 3126, 103, 'Fresh and ------- apple-cider donuts are available at Oakcrest Orchard''s retail shop for £6 per dozen.', 'eaten', 'open', 'tasty', 'free', 'C', 'Những chiếc bánh donut táo tươi và ------- có sẵn tại cửa hàng bán lẻ của Oakcrest Orchard với giá £6 mỗi tá.
(A) eaten: tính từ (có thể ăn được)
(B) open: tính từ (mở, không bị đóng)
(C) tasty: tính từ (ngon, hấp dẫn)
(D) free: tính từ (miễn phí, tự do)
Đáp án đúng là ''tasty'', vì tính từ ''tasty'' mô tả chính xác về chiếc bánh. Các lựa chọn khác không phù hợp với ngữ cảnh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3127, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4104, 3127, 104, 'Zahn Flooring has the widest selection of ------- in the United Kingdom.', 'paints', 'tiles', 'furniture', 'curtains', 'B', 'Zahn Flooring có sự lựa chọn ------- lớn nhất ở Vương quốc Anh.
(A) paints: danh từ (sơn, màu sắc)
(B) tiles: danh từ (gạch, ngói)
(C) furniture: danh từ (đồ nội thất)
(D) curtains: danh từ (rèm cửa, màn)
Đáp án đúng là ''tiles'', vì danh từ ''tiles'' phù hợp với ngữ cảnh cụ thể là phải liên quan đến “Zahn Flooring” - một công ty chuyên về sàn nhà. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3128, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4105, 3128, 105, 'One responsibility of the IT department is to ensure that the company is using ------- software.', 'update', 'updating', 'updates', 'updated', 'D', 'Một trong những trách nhiệm của bộ phận IT là đảm bảo rằng công ty đang sử dụng phần mềm ———.
(A) update: động từ (cập nhật)
(B) updating: động từ tiếp diễn (đang cập nhật)
(C) updates: danh từ (bản cập nhật)
(D) updated: tính từ (đã được cập nhật)
Đáp án đúng là ''updated'', vì tính từ ''updated'' mô tả phần mềm đã được cập nhật. Các lựa chọn khác không phù hợp với ngữ pháp và ngữ cảnh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3129, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4106, 3129, 106, 'It is wise to check a company''s dress code ------- visiting its head office.', 'so', 'how', 'like', 'before', 'D', 'Nên kiểm tra quy định về trang phục của công ty ------- khi đến thăm văn phòng chính của họ.
(A) so: vì thế, cho nên
(B) how: như thế nào, bằng cách nào
(C) like: giống như
(D) before: trước khi
Đáp án đúng là ''before'', vì giới từ ''before'' phù hợp với ngữ cảnh chỉ thời gian. Các lựa chọn khác không phù hợp với ngữ pháp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3130, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4107, 3130, 107, 'Wexler Store''s management team expects that employees will ------- support any new hires.', 'enthusiastically', 'enthusiasm', 'enthusiastic', 'enthused', 'A', 'Ban quản lý của Wexler Store mong rằng nhân viên sẽ ------- hỗ trợ bất kỳ nhân viên mới nào.
(A) enthusiastically: trạng từ (một cách nhiệt tình)
(B) enthusiasm: danh từ (sự nhiệt tình, hăng hái)
(C) enthusiastic: tính từ (nhiệt tình, hăng hái)
(D) enthused: động từ quá khứ (làm cho nhiệt tình, hăng hái)
Đáp án đúng là ''enthusiastically'', vì trạng từ ''enthusiastically'' mô tả cách thức hỗ trợ. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3131, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4108, 3131, 108, 'Wheel alignments and brake system ------- are part of our vehicle service plan.', 'inspects', 'inspector', 'inspected', 'inspections', 'D', 'Cân chỉnh bánh xe và hệ thống phanh ------- là một phần của kế hoạch dịch vụ xe của chúng tôi.
(A) inspects: động từ chia theo thì hiện tại đơn (kiểm tra)
(B) inspector: danh từ (người kiểm tra, thanh tra viên)
(C) inspected: động từ quá khứ hoặc phân từ quá khứ (đã kiểm tra, được kiểm tra)
(D) inspections: danh từ số nhiều (việc kiểm tra, sự thanh tra)
Đáp án đúng là ''inspections'', vì danh từ số nhiều ''inspections'' phù hợp với ngữ cảnh. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3132, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4109, 3132, 109, 'Registration for the Marketing Coalition Conference is now open ------- September 30.', 'until', 'into', 'yet', 'while', 'A', 'Đăng ký cho Hội nghị Marketing Coalition hiện đang mở ------- ngày 30 tháng 9.
(A) until: giới từ mang nghĩa “đến khi”
(B) into: giới từ mang nghĩa “vào trong”
(C) yet: trạng từ mang nghĩa “chưa”
(D) while: liên từ mang nghĩa “trong khi”
Đáp án đúng là ''until'', vì giới từ ''until'' phù hợp với ngữ cảnh chỉ thời gian kết thúc. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3133, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4110, 3133, 110, 'Growth in the home entertainment industry has been ------- this quarter.', 'separate', 'limited', 'willing', 'assorted', 'B', 'Sự tăng trưởng trong ngành giải trí gia đình đã bị ------- trong quý này.
(A) separate: tính từ (riêng biệt, tách rời)
(B) limited: động từ ở thể quá khứ phân từ.(hạn chế, có giới hạn)
(C) willing: tính từ (sẵn sàng, tự nguyện)
(D) assorted: tính từ (đa dạng, phong phú)
Đáp án đúng là ''limited'', vì tính từ ''limited'' mô tả sự tăng trưởng bị hạn chế. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3134, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4111, 3134, 111, 'Hawson Furniture will be making ------- on the east side of town on Thursday.', 'deliveries', 'delivered', 'deliver', 'deliverable', 'A', 'Hawson Furniture sẽ thực hiện ------- ở phía đông thị trấn vào thứ Năm.
(A) deliveries: danh từ số nhiều (việc giao hàng, sự phân phát)
(B) delivered: động từ quá khứ hoặc phân từ quá khứ (đã giao hàng, được giao hàng)
(C) deliver: động từ (giao hàng, phân phát)
(D) deliverable: tính từ (có thể giao hàng, có thể phân phát)
Đáp án đúng là ''deliveries'', vì danh từ số nhiều ''deliveries'' mô tả hành động giao hàng. Các lựa chọn khác không phù hợp với ngữ pháp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3135, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4112, 3135, 112, 'The Marlton City Council does not have the authority to ------- parking on city streets.', 'drive', 'prohibit', 'bother', 'travel', 'B', 'Hội đồng Thành phố Marlton không có quyền ------- việc đỗ xe trên các đường phố thành phố.
(A) drive: lái xe
(B) prohibit: cấm
(C) bother: làm phiền
(D) travel: du lịch
Đáp án đúng là ''prohibit'', vì động từ ''prohibit'' có nghĩa là cấm, phù hợp với ngữ cảnh. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3136, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4113, 3136, 113, 'Project Earth Group is ------- for ways to reduce transport-related greenhouse gas emissions.', 'looking', 'seeing', 'driving', 'leaning', 'A', 'Dự án Earth Group đang ------- tìm kiếm các cách giảm phát thải khí nhà kính liên quan đến vận tải.
(A) looking: tìm kiếm
(B) seeing: nhìn thấy
(C) driving: lái xe
(D) leaning: nghiêng
Đáp án đúng là ''looking'', vì động từ ''looking'' phù hợp với ngữ cảnh tìm kiếm. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3137, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4114, 3137, 114, 'Our skilled tailors are happy to design a custom-made suit that fits your style and budget -------.', 'perfect', 'perfects', 'perfectly', 'perfection', 'C', 'Thợ may lành nghề của chúng tôi rất vui khi thiết kế một bộ đồ may đo phù hợp với phong cách và ngân sách của bạn ———.
	(A) perfect: tính từ (hoàn hảo, tuyệt vời)
(B) perfects: động từ chia theo thì hiện tại đơn (hoàn thiện, làm cho hoàn hảo)
(C) perfectly: trạng từ (một cách hoàn hảo, tuyệt vời)
(D) perfection: danh từ (sự hoàn hảo)
Đáp án đúng là ''perfectly'', vì trạng từ ''perfectly'' bổ nghĩa cho động từ ''fits''. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3138, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4115, 3138, 115, 'Project manager Hannah Chung has proved to be very ------- with completing company projects.', 'helpfulness', 'help', 'helpfully', 'helpful', 'D', 'Quản lý dự án Hannah Chung đã chứng tỏ rất ------- trong việc hoàn thành các dự án của công ty.
(A) helpfulness: danh từ (sự hữu ích, sự giúp đỡ)
(B) help: danh từ hoặc động từ (sự giúp đỡ, giúp đỡ)
(C) helpfully: trạng từ (một cách hữu ích, giúp đỡ)
(D) helpful: tính từ (hữu ích, giúp đỡ)
Đáp án đúng là ''helpful'', vì tính từ ''helpful'' mô tả đúng bản chất của người quản lý. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3139, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4116, 3139, 116, 'Lehua Vacation Club members will receive double points ------- the month of August at participating hotels.', 'onto', 'above', 'during', 'between', 'C', 'Các thành viên của Lehua Vacation Club sẽ nhận được gấp đôi điểm ------- tháng 8 tại các khách sạn tham gia.
(A) onto: giới từ mang nghĩa “lên trên”
(B) above: giới từ mang nghĩa “ở trên”
(C) during: giới từ mang nghĩa “trong suốt”
(D) between: giới từ mang nghĩa “giữa”
Đáp án đúng là ''during'', vì giới từ ''during'' phù hợp với ngữ cảnh thời gian. Các lựa chọn khác không phù hợp với ngữ pháp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3140, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4117, 3140, 117, 'The costumes were not received ------- enough to be used in the first dress rehearsal.', 'far', 'very', 'almost', 'soon', 'D', 'Những bộ trang phục đã không được nhận ------- đủ để sử dụng trong buổi diễn tập đầu tiên.
(A) far: trạng từ (xa, rất)
(B) very: trạng từ (rất, lắm)
(C) almost: trạng từ (gần như, suýt)
(D) soon: trạng từ (sớm, chẳng bao lâu)
Đáp án đúng là ''soon'', vì từ ''soon'' mô tả thời gian cần thiết trước buổi diễn tập. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3141, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4118, 3141, 118, 'As a former publicist for several renowned orchestras, Mr. Wu would excel in the role of event -------.', 'organized', 'organizer', 'organizes', 'organizational', 'B', 'Là một cựu nhân viên công chúng cho một số dàn nhạc nổi tiếng, ông Wu sẽ xuất sắc trong vai trò của một người tổ chức sự kiện.
(A) organized: động từ quá khứ hoặc phân từ quá khứ (đã tổ chức, được tổ chức)
(B) organizer: danh từ (người tổ chức, nhà tổ chức)
(C) organizes: động từ chia theo thì hiện tại đơn (tổ chức)
(D) organizational: tính từ (thuộc về tổ chức)
Đáp án đúng là ''organizer'', vì danh từ ''organizer'' phù hợp với ngữ cảnh nghề nghiệp. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3142, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4119, 3142, 119, 'The northbound lane on Davis Street will be ------- closed because of the city''s bridge reinforcement project.', 'temporarily', 'competitively', 'recently', 'collectively', 'A', 'Làn đường hướng Bắc trên đường Davis sẽ được đóng cửa tạm thời do dự án củng cố cầu của thành phố.
(A) temporarily: tạm thời, nhất thời
(B) competitively: cạnh tranh, đua tranh
(C) recently: gần đây, mới đây
(D) collectively: tập thể, chung
Đáp án đúng là ''temporarily'', vì trạng từ ''temporarily'' mô tả chính xác việc đóng cửa tạm thời. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3143, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4120, 3143, 120, 'Airline representatives must handle a wide range of passenger issues, ------- missed connections to lost luggage.', 'from', 'under', 'on', 'against', 'A', 'Các đại diện hãng hàng không phải xử lý một loạt các vấn đề của hành khách, từ các kết nối bị mất đến hành lý bị mất.
(A) from: giới từ mang nghĩa “từ” (đi kèm (cụm) danh từ)
(B) under: giới từ mang nghĩa “dưới” (đi kèm (cụm) danh từ)
(C) on: giới từ mang nghĩa “trên” (đi kèm (cụm) danh từ)
(D) against: giới từ mang nghĩa “chống lại” (đi kèm (cụm) danh từ)
Đáp án đúng là ''from'', vì giới từ ''from'' phù hợp với ngữ cảnh chỉ nguồn gốc của các vấn đề. Phía sau chỗ trống là hai cụm danh từ “missed connections” và “lost luggage”, kết hợp với nhau bởi “to”. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3144, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4121, 3144, 121, 'The meeting notes were ------- deleted, but Mr. Hahm was able to recreate them from memory.', 'accident', 'accidental', 'accidents', 'accidentally', 'D', 'Ghi chú cuộc họp đã bị xóa -------, nhưng ông Hahm đã có thể tái tạo chúng từ trí nhớ.
(A) accident: danh từ (tai nạn, sự cố)
(B) accidental: tính từ (tình cờ, vô ý)
(C) accidents: danh từ số nhiều (tai nạn, sự cố)
(D) accidentally: trạng từ (tình cờ, vô ý
)Đáp án đúng là ''accidentally'', vì trạng từ ''accidentally'' mô tả hành động xóa nhầm. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3145, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4122, 3145, 122, 'The current issue of Farming Scene magazine predicts that the price of corn will rise 5 percent over the ------- year.', 'next', 'with', 'which', 'now', 'A', 'Số báo hiện tại của tạp chí Farming Scene dự đoán rằng giá ngô sẽ tăng 5% trong năm tới.
(A) next: tính từ (tiếp theo, kế tiếp)
(B) with: giới từ (với, cùng)
(C) which: đại từ quan hệ (mà, cái mà)
(D) now: trạng từ (bây giờ, hiện tại)
Đáp án đúng là ''next'', vì tính từ ''next'' phù hợp với ngữ cảnh chỉ năm sau. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3146, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4123, 3146, 123, 'Anyone who still ------- to take the fire safety training should do so before the end of the month.', 'needing', 'needs', 'has needed', 'were needing', 'B', 'Bất kỳ ai vẫn còn cần tham gia đào tạo an toàn cháy nổ nên làm điều đó trước khi hết tháng.
(A) needing: động từ nguyên thể thêm “_ing”
(B) needs: động từ chia theo thì hiện tại đơn
(C) has needed: động từ chia theo thì hiện tại hoàn thành
(D) were needing: động từ chia theo thì quá khứ tiếp diễn
Đáp án đúng là ‘needs''. Từ cần điền đóng vai trò là động từ chính trong mệnh đề quan hệ “who still … to take the fire safety training”. Từ này phải đi chung với đại từ quan hệ “who” và động từ “to take”. Nghĩa câu miêu tả một yêu cầu hay lời khuyên trong hiện tại.
→ Đáp án là động từ chia theo thì hiện tại đơn chỉ nhu cầu hay yêu cầu.
Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3147, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4124, 3147, 124, 'Emerging technologies have ------- begun to transform the shipping industry in ways that were once unimaginable.', 'already', 'exactly', 'hardly', 'closely', 'A', 'Các công nghệ mới nổi đã bắt đầu chuyển đổi ngành vận tải theo những cách không thể tưởng tượng được trước đây.
(A) already: trạng từ (đã, rồi)
(B) exactly: trạng từ (chính xác, đúng)
(C) hardly: trạng từ (hầu như không, khó khăn)
(D) closely: trạng từ (gần, chặt chẽ)
Đáp án đúng là ''already'', vì trạng từ ''already'' mô tả hành động đã bắt đầu. Từ cần điền đứng trước động từ “begun”, đóng vai trò là bổ nghĩa cho động từ đó. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3148, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4125, 3148, 125, 'The company handbook outlines the high ------- that employees are expected to meet every day.', 'experts', 'accounts', 'recommendations', 'standards', 'D', 'Sổ tay công ty nêu rõ các tiêu chuẩn cao mà nhân viên phải đạt được mỗi ngày.
(A) experts: chuyên gia
(B) accounts: tài khoản
(C) recommendations: khuyến nghị
(D) standards: tiêu chuẩn
Đáp án đúng là ''standards'', vì danh từ ''standards'' phù hợp với ngữ cảnh chỉ các tiêu chuẩn. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3149, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4126, 3149, 126, 'Because ------- of the board members have scheduling conflicts, the board meeting will be moved to a date when all can attend.', 'any', 'everybody', 'those', 'some', 'D', 'Vì một số thành viên hội đồng quản trị có xung đột lịch trình, cuộc họp hội đồng sẽ được dời lại vào một ngày khi tất cả có thể tham dự.
(A) any: đại từ chỉ bất kỳ
(B) everybody: đại từ chỉ mọi người
(C) those: đại từ chỉ những người đang đứng ở phía xa
(D) some: đại từ chỉ một số
Đáp án đúng là ‘some’- đại từ chỉ số lượng. Từ cần điền đứng trước giới từ “of”, đóng vai trò là chủ ngữ của mệnh đề “_______ of the board members have scheduling conflicts”.Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3150, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4127, 3150, 127, 'The project ------- the collaboration of several teams across the company.', 'passed', 'decided', 'required', 'performed', 'C', 'Dự án này yêu cầu sự hợp tác của một số nhóm trong toàn công ty.
(A) passed: vượt qua
(B) decided: quyết định
(C) required: yêu cầu
(D) performed: thực hiện
Đáp án đúng là ''required'', vì động từ ''required'' mô tả chính xác nhu cầu hợp tác. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3151, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4128, 3151, 128, 'We cannot send the store''s coupon booklet to the printers until it ------- by Ms. Jeon.', 'is approving', 'approves', 'has been approved', 'will be approved', 'C', 'Chúng tôi không thể gửi tập sách phiếu giảm giá của cửa hàng đến nhà in cho đến khi nó được phê duyệt bởi bà Jeon.
(A) is approving: động từ chia theo thì hiện tại tiếp diễn ở thể chủ động
(B) approves: động từ chia theo thì hiện tại đơn ở thể chủ động
(C) has been approved: động từ chia theo thì hiện tại hoàn thành ở thể bị động
(D) will be approved: động từ chia theo thì tương lai đơn ở thể bị động
Đáp án đúng là ''has been approved'', vì thì hiện tại hoàn thành phù hợp với ngữ cảnh, là động từ chia theo thì hiện tại hoàn thành ở thể bị động.Lựa. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3152, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4129, 3152, 129, '----- the closure of Verdigold Transport Services, we are looking for a new shipping company.', 'In spite of', 'Just as', 'In light of', 'According to', 'C', 'Do việc đóng cửa của Verdigold Transport Services, chúng tôi đang tìm kiếm một công ty vận chuyển mới.
(A) In spite of: cụm giới từ (mặc dù)
(B) Just as: cụm liên từ (ngay khi)
(C) In light of: cụm giới từ (vì, xét theo)
(D) According to: cụm giới từ (theo)
Đáp án đúng là ''In light of'', vì cụm từ này phù hợp với ngữ cảnh chỉ nguyên nhân. Các lựa chọn khác không phù hợp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3153, 145, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4130, 3153, 130, 'The ------- information provided by Uniss Bank''s brochure helps applicants understand the terms of their loans.', 'arbitrary', 'supplemental', 'superfluous', 'potential', 'B', 'Thông tin bổ sung được cung cấp bởi tài liệu quảng cáo của Ngân hàng Uniss giúp người nộp đơn hiểu các điều khoản của khoản vay của họ.
(A) arbitrary: tính từ (tùy ý, tùy tiện)
(B) supplemental: tính từ (bổ sung, thêm vào)
(C) superfluous: tính từ (dư thừa, thừa thãi)
(D) potential: tính từ (tiềm năng, có khả năng)
Đáp án đúng là ''supplemental'', vì tính từ ''supplemental'' phù hợp với ngữ cảnh chỉ thông tin bổ sung. Các lựa chọn khác không phù hợp.');;

-- Data for 2024 Test1 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3154, 146, NULL, NULL, 'Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business 131 ———. We will teach you how to plant a rain garden, which is simply a shallow sunken garden 132——— a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops. These gardens can be landscaped with native plants and flowers.133———, rain gardens are always beneficial to the local environment. Among other things, 134 ———, improve drainage and protect rivers and streams.To register, visit www.maxley-horticulture.org.', 'Hãy đến với Trung tâm Làm vườn Maxley Heights và tìm hiểu cách tạo ra một khu vườn đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn 131 ———. Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa, chỉ đơn giản là một khu vườn cạn chìm 132——— một hỗn hợp đất đặc biệt để lọc các chất ô nhiễm từ nước mưa chảy từ các con đường và mái nhà gần đó. Những khu vườn này có thể được làm cảnh bằng các loại cây và hoa bản địa.133———, vườn mưa luôn có lợi cho môi trường địa phương. Trong số những thứ khác, 134 ———, cải thiện hệ thống thoát nước và bảo vệ sông suối. Để đăng ký, hãy truy cập www.maxley-horticulture.org.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4131, 3154, 131, NULL, 'Children of all ages will enjoy the new exhibits.', 'Learn about rainfall patterns across the region.', 'Build a set of simple patio furniture with easy-to-acquire materials.', 'Next Saturday at 4 P.M., we are hosting a free workshop for the public.', 'D', 'Câu trước chỗ trống đề cập đến việc học cách tạo ra một khu vườn thân thiện với môi trường, và câu sau chỗ trống, tức đáp án D, cung cấp thông tin về hội thảo miễn phí sẽ dạy cho công chúng về cách tạo ra một khu vườn như thế.
(A) Trẻ em ở mọi lứa tuổi sẽ thích thú với những cuộc triển lãm mới.
(B) Tìm hiểu về lượng mưa trên toàn khu vực.
(C) Làm một bộ bàn ghế sân hiên đơn giản bằng những vật liệu dễ kiếm.
(D) Thứ bảy tuần sau lúc 4 giờ chiều, chúng tôi sẽ tổ chức một hội thảo miễn phí cho công chúng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3155, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4132, 3155, 132, NULL, 'to use', 'used to', 'by using', 'that uses', 'D', 'Chỗ trống cần một cấu trúc giúp bổ ngữ cho khu vườn ở ngay trước chỗ trống, nhằm mô tả tính năng là giúp lọc các chất độc hại từ nước mưa chảy từ các con đường và mái nhà gần đó.
 Đáp án là mệnh đề quan hệ giúp bổ sung thông tin cho danh từ đứng trước.
(A) to use: thể hiện mục đích sử dụng thứ gì đó
(B) used to: biểu thị một hành động đã từng xảy ra trong quá khứ
(C) by using: thể hiện một việc gì đó đạt được bằng cách sử dụng phương pháp nào đó
(D) that uses: mệnh đề quan hệ liên kết với danh từ trước đó và giúp giải thích thêm về nó');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3156, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4133, 3156, 133, NULL, 'Best of all', 'For example', 'In any event', 'As a matter of fact', 'A', 'Điều tuyệt vời nhất là các khu vườn mưa luôn có lợi cho môi trường địa phương. Đáp án đúng là ''Best of all'', vì cụm từ này phù hợp với ngữ cảnh chỉ những lợi ích lớn nhất.
(A) Best of all (trạng từ): làm nổi bật một điểm mạnh hoặc một lợi ích chính
(B) For example (liên từ): đưa ra ví dụ
(C) In any event (liên từ): đưa ra điều gì đó là quan trọng hoặc xảy ra bất kể tình huống nào, không phụ thuộc vào điều gì khác
(D) As a matter of fact (trạng từ): đưa ra sự thật tổng quan hay phản ánh sự chắc chắn về điều gì.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3157, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4134, 3157, 134, NULL, 'we', 'they', 'both', 'yours', 'B', 'Ngoài những thứ khác, ------- cải thiện thoát nước và bảo vệ sông ngòi. Ở câu trước, đoạn văn nhắc tới “rain gardens” và lợi ích của chúng.
Đáp án là đại từ chủ ngữ, thay thế cho đối tượng ở ngôi thứ ba, số nhiều, là ''they'', vì đại từ ''they'' phù hợp với ngữ cảnh chỉ các khu vườn. Các lựa chọn khác không phù hợp.
(A) we (đại từ chủ ngữ): thay thế cho đối tượng ở ngôi thứ nhất, số nhiều
(B) they (đại từ chủ ngữ): thay thế cho đối tượng ở ngôi thứ ba, số nhiều
(C) both (đại từ): chỉ cả hai (ai đó, thứ gì đó)
(D) yours (đại từ sở hữu): thay thế cho (cái gì đó) của bạn/các bạn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3158, 146, NULL, NULL, '31 July
Akwasi Dombo Fourth Avenue GA 105 Accra, Ghana
Dear M.r Dombo,
Thank you for your 135——— support in helping me to plan  the opening gala for Tokyo’s fashion week. The event was a huge success, and I was honored to work with you. I know that our attendees follow your work closely, and they loved the designs you contributed for this event. Your designs received a lot of 136——— on social media. Shows like this will keep Tokyo on the map as a premier fashion centre. 137———. I realize that the multiple delays made het planing on easy task. The auction 138 ——— our Young Designers Award program is coming up soon and Iook forward to working with you on that as well.', 'Ngày 31 tháng 7
Akwasi Dombo Fourth Avenue GA 105 Accra, Ghana
Kính gửi Mr.r Dombo,
Cảm ơn sự hỗ trợ 135———— của bạn trong việc giúp tôi lên kế hoạch cho buổi dạ tiệc khai mạc cho tuần lễ thời trang Tokyo. Sự kiện này là một thành công lớn, và tôi rất vinh dự được làm việc với bạn. Tôi biết rằng những người tham dự của chúng tôi theo dõi chặt chẽ công việc của bạn và họ yêu thích các thiết kế mà bạn đã đóng góp cho sự kiện này. Các thiết kế của bạn đã nhận được rất nhiều 136——— trên mạng xã hội. Các chương trình như thế này sẽ giữ Tokyo trên bản đồ như một trung tâm thời trang hàng đầu. 137———. Tôi nhận ra rằng nhiều lần trì hoãn khiến việc lập kế hoạch trở nên dễ dàng. Cuộc đấu giá 138 ——— Chương trình Giải thưởng Nhà thiết kế trẻ của chúng tôi sắp ra mắt và tôi cũng mong được làm việc với bạn về điều đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4135, 3158, 135, NULL, 'amazed', 'amazement', 'amazing', 'amazingly', 'C', 'Từ cần điền đứng trước danh từ “support” nên đây sẽ là một tính từ chỉ tính chất của sự hỗ trợ.
 Đáp án là một tính từ chỉ tính chất của sự vật, hành động, bổ nghĩa cho “support.” Là C.
(A) amazed (tính từ, quá khứ phân từ): mô tả trạng thái ngạc nhiên, kinh ngạc của một người
(B) amazement (danh từ): chỉ sự ngạc nhiên, kinh ngạc
(C) amazing (tính từ, hiện tại phân từ): mô tả điều gì đó đáng ngạc nhiên hay tuyệt vời
(D) amazingly (trạng từ): một cách kinh ngạc, tuyệt vời');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3159, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4136, 3159, 136, NULL, 'attention', 'proposals', 'innovation', 'criticism', 'A', 'Thiết kế của bạn đã nhận được rất nhiều ------- trên mạng xã hội. Đáp án đúng là ''attention'', vì đây là danh từ chỉ sự chú ý. Các lựa chọn khác đều không phù hợp với ngữ cảnh.
(A) attention (n): sự chú ý
(B) proposals (n): đề xuất
(C) innovation (n): sự đổi mới
(D) criticism (n): sự chỉ trích');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3160, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4137, 3160, 137, NULL, 'Several other events have gone surprisingly well.', 'Thank you also for your flexibility in planning the event.', 'Please stop by our office the next time you are in the city.', 'Tokyo is a top tourism destination for many reasons.', 'B', 'Ðáp án B là câu trước, người viết gửi lời cảm ơn vì sự hỗ trợ trong việc lên kế hoạch và câu sau nối tiếp bằng cách thấu hiểu những khó khăn trong việc lên kế hoạch đó (khiến cho sự linh hoạt của nhà thiết kế trở nên ý nghĩa và là lý do cho lời cảm ơn).
(A) Một số sự kiện khác đã diễn ra tốt đẹp một cách đáng ngạc nhiên.
(B) Cũng cảm ơn ông vì sự linh hoạt trong việc lên kế hoạch cho sự kiện.
(C) Vui lòng ghé qua văn phòng của chúng tôi vào lần tới khi ông ở thành phố.
(D) Tokyo là điểm đến du lịch hàng đầu vì nhiều lý do.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3161, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4138, 3161, 138, NULL, 'wil benefit', 'to benefit', 'has benefited', 'benefits', 'B', 'Đáp án B sẽ bổ ngữ cho danh từ “auction” đứng trước nó, có thể nói về mục tiêu đem đến lợi ích cho giải thưởng nhà thiết kế trẻ.
(A) will benefit (động từ ở thì tương lai): sẽ mang lợi ích nào đó
(B) to benefit (động từ nguyên thể có to): chỉ mục tiêu sự kiện
(C) has benefited (động từ ở thì quá khứ hoàn thành): đã và đang mang lại lợi ích nào đó
(D) benefits (động từ ở thì hiện tại đơn): mang lại lợi ích nào đó');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3162, 146, NULL, NULL, 'From: Patron Services <patronservices@menachinlibrary.org> To: Edgar Hughes <hughese98@villachesta.com>
Subject: Card expiration date approaching
Date: December 3
Dear Mr. Hughes,
Please be advised that your Mena Chin Library card will expire one month from today. 139———must be renewed if you intend to keep your membership for the coming year. 140———.This can be done at the information desk at any branch location. 141———you decide to close your account, on action is necessary. Failure to complete your renewal by the 142——— date will result in the expiration of your library privileges.
If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.
Sincerely,
Patron Services', 'Từ: Dịch vụ người bảo trợ <patronservices@menachinlibrary.org> Gửi đến: Edgar Hughes <hughese98@villachesta.com>
Chủ đề: Ngày hết hạn thẻ đang đến gần
Ngày: 3 tháng 12
Kính gửi ông Hughes,
Xin lưu ý rằng thẻ Thư viện Mena Chin của bạn sẽ hết hạn một tháng kể từ hôm nay. 139——phải được gia hạn nếu bạn có ý định giữ tư cách thành viên của mình trong năm tới. 140———. Điều này có thể được thực hiện tại quầy thông tin tại bất kỳ địa điểm chi nhánh nào. 141———bạn quyết định đóng tài khoản của mình, hành động là cần thiết. Việc không hoàn thành việc gia hạn của bạn trước ngày 142——— sẽ dẫn đến việc các đặc quyền thư viện của bạn hết hạn.
Nếu bạn có bất kỳ câu hỏi nào về thông báo này hoặc về các dịch vụ thư viện chung, bạn có thể trả lời trực tiếp email này.
Trân trọng,
Dịch vụ Patron');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4139, 3162, 139, NULL, 'It', 'You', 'Our', 'Each', 'A', 'Xin lưu ý rằng thẻ thư viện Mena Chin của bạn sẽ hết hạn sau một tháng kể từ hôm nay. Đáp án đúng là ‘It'' là đại từ số ít thay thế cho thẻ thư viện nhắc đến trước đó.
(A) It (đại từ chủ ngữ): thay thế cho đối tượng ở ngôi thứ ba, số ít
(B) You (đại từ chủ ngữ): nói tới đối tượng ở ngôi thứ hai
(C) Our (đại từ sở hữu): của chúng ta
(D) Each (từ hạn định/trạng từ): mỗi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3163, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4140, 3163, 140, NULL, 'To sign up for a card, visit your local library branch.', 'For questions about library membership, please visit our Web site.', 'Renewal must be completed at least one week before your card expires.', 'You may opt out of this program at any time.', 'C', 'Việc gia hạn phải được hoàn thành ít nhất một tuần trước khi thẻ của bạn hết hạn. Đáp án đúng là ''Renewal must be completed at least one week before your card expires.'', vì đây là câu hoàn chỉnh hợp lý. Các lựa chọn khác: (A) ''For questions about library membership, please visit our Web site.'', (B) ''Renewal must be completed at least one week before your card expires.'', (D) ''You may opt out of this program at any time.'' đều không phù hợp.
(A) Để đăng ký thẻ, hãy đến chi nhánh thư viện địa phương của bạn.
(B) Nếu có thắc mắc về tư cách thành viên thư viện, vui lòng truy cập trang Web của chúng tôi.
(C) Việc gia hạn phải được hoàn tất ít nhất một tuần trước khi thẻ của bạn hết hạn.
(D) Bạn có thể chọn không tham gia chương trình này bất cứ lúc nào.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3164, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4141, 3164, 141, NULL, 'Also', 'Should', 'Because', 'Although', 'B', 'Nếu bạn quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ hành động nào. Đáp án đúng là ''Should'', vì đây là cấu trúc đảo ngữ phù hợp để đưa ra điều kiện.
(A) Also: trạng từ, cũng/thêm vào đó
(B) Should: động từ tình thái, được sử dụng để đưa ra điều kiện trong câu điều kiện
(C) Because: liên từ, bởi vì
(D) Although: liên từ, mặc dù');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3165, 146, NULL, NULL, NULL, '—');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4142, 3165, 142, NULL, 'specifically', 'specifics', 'specified', 'specificity', 'C', 'Việc không hoàn thành gia hạn của bạn trước ------- ngày được chỉ định sẽ dẫn đến việc hết hạn quyền lợi thư viện của bạn. Đáp án đúng là ''specified'',Từ cần điền đứng trước danh từ “date” để bổ ngữ cho danh từ này, là ngày cụ thể hoặc ngày được xác định trước để hoàn thành việc gia hạn cần một tính từ.
(A) specifically: trạng từ, một cách cụ thể
(B) specifics: danh từ, chi tiết cụ thể
(C) specified: tính từ, được xác định
(D) specificity: danh từ, sự cụ thể');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3166, 146, NULL, NULL, 'April 7
Naomi Burwell
43 Waymire Road
South Portland, ME 04109
Dear Ms. Burwell,
I am Omar Ridha, the manager of Droplight Studio. 143———. We offer a full range of photography services for real estate professionals like you. We take pride in composing interior and exterior shots that make a property look its best. Droplight Studio spares on effort in 144 ——— Superior digital images. 145 ———, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property. And once the photo shoot si over, every image 146 ——— expert editing. All these services come standard in every package.
Please visit our Web site to view our work as well as our pricing and scheduling information. We are happy to work with you to customize orders.
Sincerely,
Omar Ridha, Droplight Studio', 'Ngày 7 tháng 4
Naomi Burwell
43 Waymire Road
South Portland, ME 04109
Bà Burwell thân mến,
Tôi là Omar Ridha, quản lý của Droplight Studio. 143———. Chúng tôi cung cấp đầy đủ các dịch vụ chụp ảnh cho các chuyên gia bất động sản như bạn. Chúng tôi tự hào trong việc sáng tác các bức ảnh nội thất và ngoại thất làm cho bất động sản trông đẹp nhất. Droplight Studio dành cho nỗ lực trong 144 ——— Hình ảnh kỹ thuật số vượt trội. 145 ———, thiết bị, ánh sáng và kỹ thuật dàn dựng cấp chuyên nghiệp của chúng tôi cho phép chúng tôi làm nổi bật các tính năng tốt nhất của một tài sản. Và sau khi buổi chụp hình kết thúc, mọi hình ảnh 146 ——— chuyên gia chỉnh sửa. Tất cả các dịch vụ này đều có tiêu chuẩn trong mọi gói.
Vui lòng truy cập trang web của chúng tôi để xem công việc của chúng tôi cũng như thông tin về giá cả và lịch trình của chúng tôi. Chúng tôi rất vui khi được làm việc với bạn để tùy chỉnh các đơn đặt hàng.
Trân trọng,
Omar Ridha, Droplight Studio');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4143, 3166, 143, NULL, 'I would like to introduce you to our business.', 'Great photographs can make your property stand out.', 'We are looking forward to your visit.', 'It was the first studio of its kind to open in this area.', 'A', 'Tôi muốn giới thiệu bạn với doanh nghiệp của chúng tôi. Đáp án đúng là ''I would like to introduce you to our business.'', vì đây là cách giới thiệu phổ biến. Đáp án A,
(A) Tôi muốn giới thiệu với bạn về doanh nghiệp của chúng tôi.
(B) Những bức ảnh đẹp có thể làm cho cơ sở kinh doanh của bạn nổi bật.
(C) Chúng tôi rất mong chờ chuyến thăm của bạn.
(D) Đây là studio đầu tiên thuộc loại này được mở ở khu vực này.');;
