INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4144, 3167, 144, NULL, 'researching', 'creating', 'purchasing', 'displaying', 'B', 'Droplight Studio không tiết kiệm bất kỳ nỗ lực nào trong việc ------- hình ảnh kỹ thuật số vượt trội. Đáp án đúng là ''creating'', vì động từ ''creating'' phù hợp nhất với ngữ cảnh tạo ra hình ảnh.
(A) researching (gerund): nghiên cứu
(B) creating (gerund): tạo ra 
C) purchasing (gerund): mua
(D) displaying (gerund): trung bày');;
