INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4146, 3169, 146, NULL, 'receives', 'is receiving', 'had received', 'had to receive', 'A', 'Và khi buổi chụp hình kết thúc, mọi hình ảnh đều ------- chỉnh sửa chuyên nghiệp. Đáp án đúng là ''receives'', vì đây động từ ở thì hiện tại đơn phù hợp với chủ ngữ số ít ''every image’.
(A) receives (động từ ở thì hiện tại đơn): nhận
(B) is receiving (động từ ở thì hiện tại tiếp diễn): đang nhận
(C) had received (động từ ở thì quá khứ hoàn thành): đã nhận
(D) had to receive: phải nhận');;

