INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4211, 3234, 11, 'I''m going to try to fix this printer', 'You''re right, it doesn''t fit', 'Double-sided copies', 'Are you sure it can be repaired?', NULL, 'C', 'Câu này là một tuyên bố về việc sẽ cố gắng sửa máy in.
A. Bạn đúng, nó không vừa
B. Bản sao hai mặt
C. Bạn có chắc nó có thể sửa được không?
Đáp án C là phù hợp nhất vì nó đặt câu hỏi về khả năng sửa chữa máy in, phản hồi trực tiếp với tuyên bố ban đầu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3235, 149, '2024/test2/audio/test2_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4212, 3235, 12, 'What should we do with these brochures?', 'A trip to the seashore', 'Yes, I found it already', 'I''ll leave them at the front desk', NULL, 'C', 'Câu hỏi hỏi về cách xử lý các tờ rơi.
A. Một chuyến đi đến bờ biển
B. Vâng, tôi đã tìm thấy nó rồi
C. Tôi sẽ để chúng ở quầy lễ tân
Đáp án C là phù hợp nhất vì nó đề xuất một hành động cụ thể để xử lý các tờ rơi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3236, 149, '2024/test2/audio/test2_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4213, 3236, 13, 'Has the policy meeting been rescheduled?', 'We have lots of desk calendar designs', 'Yes, it''s happening tomorrow instead', 'This soup I ordered is delicious', NULL, 'B', 'Câu hỏi hỏi về việc cuộc họp chính sách có được lên lịch lại không.
A. Chúng tôi có nhiều mẫu lịch bàn
B. Vâng, nó sẽ diễn ra vào ngày mai thay vì hôm nay
C. Món súp tôi gọi rất ngon
Đáp án B là phù hợp nhất vì nó xác nhận rằng cuộc họp đã được lên lịch lại và cung cấp thông tin về thời gian mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3237, 149, '2024/test2/audio/test2_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4214, 3237, 14, 'Why don''t we stop by the office cafeteria on our way to the workshop?', 'Sure, we have time for that.', 'A full-service buffet.', 'The topic is professional networking.', NULL, 'A', 'Câu hỏi đề xuất ghé qua căng tin văn phòng trên đường đến hội thảo.
A. Chắc chắn rồi, chúng ta có thời gian cho việc đó
B. Một bữa tiệc buffet đầy đủ dịch vụ
C. Chủ đề là kết nối chuyên nghiệp
Đáp án A là phù hợp nhất vì nó đồng ý với đề xuất và xác nhận có đủ thời gian.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3238, 149, '2024/test2/audio/test2_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4215, 3238, 15, 'Have you tried our famous pasta dish?', 'We need a table for five.', 'Yes, it was delicious.', 'I''ll try to make it on time.', NULL, 'B', 'Câu hỏi hỏi về việc đã thử món mỳ Ý nổi tiếng chưa.
A. Chúng tôi cần một bàn cho năm người
B. Vâng, nó rất ngon
C. Tôi sẽ cố gắng đến đúng giờ
Đáp án B là phù hợp nhất vì nó xác nhận đã thử món ăn và đưa ra đánh giá.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3239, 149, '2024/test2/audio/test2_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4216, 3239, 16, 'Who''s the opening act at tonight''s concert?', 'Could you turn up the volume?', 'A jazz singer from France.', 'The position has been filled.', NULL, 'B', 'Câu hỏi hỏi về tiết mục mở đầu trong buổi hòa nhạc tối nay.
A. Bạn có thể tăng âm lượng lên không?
B. Một ca sĩ nhạc jazz từ Pháp
C. Vị trí đã được lấp đầy
Đáp án B là phù hợp nhất vì nó cung cấp thông tin cụ thể về người biểu diễn mở đầu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3240, 149, '2024/test2/audio/test2_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4217, 3240, 17, 'When do the product demonstrations start?', 'The schedule was emailed last Friday', 'Some innovative features', 'In room 202, I think', NULL, 'A', 'Câu hỏi hỏi về thời gian bắt đầu các buổi trình diễn sản phẩm.
A. Lịch trình đã được gửi email vào thứ Sáu tuần trước
B. Một số tính năng sáng tạo
C. Trong phòng 202, tôi nghĩ vậy
Đáp án A là phù hợp nhất vì nó đề cập đến việc lịch trình đã được gửi, ngụ ý rằng thông tin về thời gian bắt đầu có trong đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3241, 149, '2024/test2/audio/test2_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4218, 3241, 18, 'I tried updating the website, but it didn''t work.', 'That date works for me.', 'Usually our online reviews.', 'Just send me the changes you want.', NULL, 'C', 'Câu này là một tuyên bố về việc cố gắng cập nhật trang web nhưng không thành công.
A. Ngày đó phù hợp với tôi
B. Thường là các đánh giá trực tuyến của chúng tôi
C. Chỉ cần gửi cho tôi những thay đổi bạn muốn
Đáp án C là phù hợp nhất vì nó đề xuất một giải pháp cho vấn đề cập nhật trang web.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3242, 149, '2024/test2/audio/test2_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4219, 3242, 19, 'Did you hire a new welding specialist?', 'The part''s back-ordered.', 'Yes, he starts tomorrow.', 'No, it should be higher.', NULL, 'B', 'Câu hỏi hỏi về việc có thuê chuyên gia hàn mới không.
A. Bộ phận đó đang được đặt hàng lại
B. Vâng, anh ấy bắt đầu làm việc vào ngày mai
C. Không, nó nên cao hơn
Đáp án B là phù hợp nhất vì nó xác nhận việc thuê và cung cấp thông tin về ngày bắt đầu làm việc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3243, 149, '2024/test2/audio/test2_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4220, 3243, 20, 'How was the color palette for the lobby chosen?', 'Blue and orange.', 'It was fine, thanks.', 'I wasn''t involved.', NULL, 'C', 'Câu hỏi hỏi về cách chọn bảng màu cho sảnh.
A. Màu xanh và cam
B. Nó ổn, cảm ơn
C. Tôi không tham gia vào việc đó
Đáp án C là phù hợp nhất vì nó cho biết người trả lời không tham gia vào quá trình chọn màu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3244, 149, '2024/test2/audio/test2_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4221, 3244, 21, 'When are we ordering more supplies for the office?', 'In the storage closet', 'Next week on Monday', 'The new desk looks great', NULL, 'B', 'Câu hỏi hỏi về thời điểm đặt thêm vật tư cho văn phòng.
A. Trong tủ đựng đồ
B. Thứ Hai tuần sau
C. Cái bàn mới trông rất đẹp
Đáp án B là phù hợp nhất vì nó cung cấp một thời điểm cụ thể cho việc đặt hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3245, 149, '2024/test2/audio/test2_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4222, 3245, 22, 'The battery for the water pump is going to be solar-powered, right?', 'We''re still in the planning stages.', '$140 per year.', 'Yes, I''d love a glass of water.', NULL, 'A', 'Câu hỏi xác nhận về việc pin cho máy bơm nước sẽ được cung cấp năng lượng bằng năng lượng mặt trời.
A. Chúng tôi vẫn đang trong giai đoạn lên kế hoạch
B. 140 đô la một năm
C. Vâng, tôi muốn một ly nước
Đáp án A là phù hợp nhất vì nó cho thấy quyết định cuối cùng chưa được đưa ra.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3246, 149, '2024/test2/audio/test2_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4223, 3246, 23, 'Where can I buy a charger for this laptop?', 'Around 3 o''clock.', 'I can order one for you.', 'A limited return policy.', NULL, 'B', 'Câu hỏi hỏi về nơi mua bộ sạc cho laptop.
A. Khoảng 3 giờ
B. Tôi có thể đặt hàng một cái cho bạn
C. Chính sách đổi trả hạn chế
Đáp án B là phù hợp nhất vì nó đề xuất một giải pháp trực tiếp để có được bộ sạc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3247, 149, '2024/test2/audio/test2_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4224, 3247, 24, 'Do I need to reserve a meeting room?', 'Yes, let me show you how.', 'The service is good.', 'My slide presentation.', NULL, 'A', 'Câu hỏi hỏi về việc có cần đặt phòng họp không.
A. Vâng, để tôi chỉ cho bạn cách làm
B. Dịch vụ rất tốt
C. Bài thuyết trình slide của tôi
Đáp án A là phù hợp nhất vì nó xác nhận việc cần đặt phòng và đề nghị hướng dẫn cách thực hiện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3248, 149, '2024/test2/audio/test2_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4225, 3248, 25, 'When''s the new department director supposed to start?', 'It''s an hour long', 'Ms. Pavlova isn''t retiring for several weeks', 'No, that department''s upstairs', NULL, 'B', 'Câu hỏi hỏi về thời điểm giám đốc phòng ban mới bắt đầu làm việc.
A. Nó kéo dài một giờ
B. Bà Pavlova sẽ không nghỉ hưu trong vài tuần nữa
C. Không, phòng ban đó ở tầng trên
Đáp án B là phù hợp nhất vì nó ngụ ý rằng giám đốc mới sẽ bắt đầu sau khi bà Pavlova nghỉ hưu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3249, 149, '2024/test2/audio/test2_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4226, 3249, 26, 'Should I deliver these pizzas, or will you?', 'No thanks, I''m not hungry.', 'Ten dollars for two.', 'They''re being picked up.', NULL, 'C', 'Câu hỏi hỏi về việc ai sẽ giao pizza.
A. Không, cảm ơn, tôi không đói
B. Mười đô la cho hai cái
C. Chúng đang được lấy đi
Đáp án C là phù hợp nhất vì nó cho biết pizza sẽ được khách hàng tự đến lấy, không cần giao hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3250, 149, '2024/test2/audio/test2_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4227, 3250, 27, 'This month''s shipment schedule has been revised.', 'I couldn''t find them either.', 'Which dates have been changed?', 'Two dollars per pound.', NULL, 'B', 'Câu này là một tuyên bố về việc lịch trình vận chuyển tháng này đã được sửa đổi.
A. Tôi cũng không tìm thấy chúng
B. Những ngày nào đã được thay đổi?
C. Hai đô la mỗi pound
Đáp án B là phù hợp nhất vì nó yêu cầu thông tin cụ thể về những thay đổi trong lịch trình.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3251, 149, '2024/test2/audio/test2_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4228, 3251, 28, 'How much will the repairs cost?', 'The work is covered under the warranty plan.', 'Yes, it''s also available in red.', 'In about two weeks.', NULL, 'A', 'Câu hỏi hỏi về chi phí sửa chữa.
A. Công việc được bảo hành theo kế hoạch bảo hành
B. Vâng, nó cũng có sẵn màu đỏ
C. Trong khoảng hai tuần nữa
Đáp án A là phù hợp nhất vì nó trả lời trực tiếp về chi phí, cho biết rằng việc sửa chữa được bảo hành.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3252, 149, '2024/test2/audio/test2_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4229, 3252, 29, 'Why don''t we provide more samples of the wallpaper patterns?', 'The newspaper is delivered daily', 'An interior design course', 'There are plenty in the binders', NULL, 'C', 'Câu hỏi hỏi về lý do không cung cấp thêm mẫu hoa văn giấy dán tường.
A. Báo được giao hàng ngày
B. Một khóa học thiết kế nội thất
C. Có rất nhiều trong các tập tài liệu
Đáp án C là phù hợp nhất vì nó chỉ ra rằng đã có sẵn nhiều mẫu trong các tập tài liệu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3253, 149, '2024/test2/audio/test2_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4230, 3253, 30, 'Can you give me a tour of the property this afternoon?', 'Sorry, I won''t have time until tomorrow.', 'It has a very modern design.', 'A house on Maple Street.', NULL, 'A', 'Câu hỏi yêu cầu tham quan bất động sản vào chiều nay.
A. Xin lỗi, tôi sẽ không có thời gian cho đến ngày mai
B. Nó có thiết kế rất hiện đại
C. Một ngôi nhà trên đường Maple
Đáp án A là phù hợp nhất vì nó trả lời trực tiếp về khả năng tham quan, mặc dù là từ chối và đề xuất thời gian khác.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3254, 149, '2024/test2/audio/test2_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4231, 3254, 31, 'Who''s scheduled to test the product today?', 'We''re waiting for confirmation.', 'It''s a great album, right?', 'About six weeks ago.', NULL, 'A', 'Câu hỏi hỏi về người được lên lịch kiểm tra sản phẩm hôm nay.
A. Chúng tôi đang chờ xác nhận
B. Đó là một album tuyệt vời, phải không?
C. Khoảng sáu tuần trước
Đáp án A là phù hợp nhất vì nó cho thấy lịch kiểm tra chưa được xác nhận chắc chắn.');;

