INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3294, 151, '2024/test2/audio/test2_question_71_73.mp3', NULL, 'w-Br Hi, Amina. This is Sabine calling from Blue Drop Creations. " just put the earrings and necklaces that you ordered from me in the mail. Because you''ve been a customer for over ten years, I''ve also included a special gift in the package for you. It''s a case for your jewelry. This is a new product that I''m starting to offer, so please call me back after you receive it. I''d really like to hear your thoughts on it.', 'w-Br Xin chào, Amina. Đây là Sabine gọi từ Blue Drop Creations. " chỉ cần đặt bông tai và vòng cổ mà bạn đã đặt hàng từ tôi trong thư. Bởi vì bạn đã là khách hàng trong hơn mười năm, tôi cũng đã bao gồm một món quà đặc biệt trong gói cho bạn. Đó là một trường hợp cho đồ trang sức của bạn. Đây là một sản phẩm mới mà tôi đang bắt đầu cung cấp, vì vậy vui lòng gọi lại cho tôi sau khi bạn nhận được nó. Tôi thực sự muốn nghe suy nghĩ của bạn về nó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4271, 3294, 71, 'Who most likely is the speaker?', 'An art gallery owner', 'A hairstylist', 'A clothing designer', 'A jewelry maker', 'D', 'Đáp án đúng là D. A jewelry maker (Một người làm đồ trang sức).
Người nói giới thiệu mình là Sabine từ Blue Drop Creations và đề cập đến việc gửi hoa tai và vòng cổ, cho thấy cô ấy là một người làm đồ trang sức.
Dịch các phương án:
A. Chủ một phòng trưng bày nghệ thuật
B. Một nhà tạo mẫu tóc
C. Một nhà thiết kế quần áo
D. Một người làm đồ trang sức');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3295, 151, '2024/test2/audio/test2_question_71_73.mp3', NULL, NULL, '-');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4272, 3295, 72, 'Why did the speaker include a special gift?', 'Because the listener is a new customer', 'Because the listener is celebrating a special occasion', 'Because the listener is a loyal customer', 'Because the listener placed a large order', 'C', 'Đáp án đúng là C. Because the listener is a loyal customer (Bởi vì người nghe là một khách hàng trung thành).
Người nói đề cập: "Because you''ve been a customer for over 10 years, I''ve also included a special gift in the package for you."
