INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3354, 153, NULL, NULL, 'To: Myung-Hee Hahn
From: Dellwyn Home Store
Date: January 15
Subject: Order update
Dear Ms. Hahn,
Your 131......order of a red oak dining table and six matching chairs arrived at our store this morning. We would now like to arrange for the delivery of the 132.....Please call us at 517-555-0188 and ask 133.....to Coleman Cobb, our delivery manager. 134........', NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4331, 3354, 131, NULL, 'specially', 'specialize', 'special', 'specializing', 'C', 'C. ''special'' là đúng vì danh từ ''order'' cần được bổ nghĩa bởi một tính từ.
’special’ có nghĩa là ''đặc biệt’.
Các lựa chọn khác là không hợp lý:
’specially'' là trạng từ,
’specialize'' là động từ,
’specializing'' cũng là động từ ở dạng hiện tại tiếp diễn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4332, 3354, 132, NULL, 'furniture', 'appliances', 'refund', 'tools', 'A', 'A. ''furniture'' là đúng vì nó phù hợp với bối cảnh giao hàng đồ nội thất (bàn ghế).
’appliances’ là các thiết bị, ''refund'' là tiền hoàn lại, và ''tools'' là dụng cụ, đều không liên quan ở đây.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4333, 3354, 133, NULL, 'speak', 'spoken', 'is speaking', 'to speak', 'D', 'D. ''to speak'' là đúng vì cụm ''ask to speak to someone'' là một cách nói lịch sự trong giao tiếp.
Các lựa chọn khác như ''speak'' không đúng ngữ pháp trong trường hợp này, ''spoken'' là thì quá khứ, và ''is speaking'' là thì hiện tại tiếp diễn, không phù hợp ở đây.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4334, 3354, 134, NULL, 'He can schedule a convenient time.', 'He began working here yesterday.', 'He can meet you at 11:00 Α.Μ.', 'He recently moved to Dellwyn.', 'A', 'A. ''He can schedule a convenient time.'' là đúng vì phù hợp với ngữ cảnh hẹn thời gian giao hàng.
’He began working here yesterday.'' không liên quan,
’He can meet you at 11:00 Α.Μ.'' không hợp lý vì không có thông tin trước đó,
’He recently moved to Dellwyn.'' không liên quan đến chủ đề giao hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3355, 153, NULL, NULL, 'Keep Cool Service Contractors:
67 Main Road, Edinburgh Village Chaguanas,
Trinidad and Tobago
Keep Cool Service Contractors can bring you peace of mind. As part of an annual contract, we will service your air-conditioning system, ensuring your 135.....and comfort. This includes inspecting the system, making repairs as needed, and professionally cleaning your air ducts. 136....., if necessary, we can replace your old air-conditioning system with a new, cost-efficient one.
Our workers are highly qualified licensed technicians who stay up-to-date with ongoing training.137..... We promise you fair prices and professional work,138.... by our Keep Cool guarantee.', NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4335, 3355, 135, NULL, 'safe', 'safely', 'safest', 'safety', 'D', 'D. ''safety'' dịch là ''sự an toàn'', là danh từ phù hợp để điền vào chỗ trống, vì ngữ cảnh đang nói về việc đảm bảo sự an toàn và thoải mái của khách hàng.
’safe'' (an toàn) là tính từ,
’safely'' (một cách an toàn) là trạng từ,
’safest’ (an toàn nhất) là tính từ so sánh nhất, nên không phù hợp với cấu trúc cần danh từ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4336, 3355, 136, NULL, 'On one hand', 'Nonetheless', 'Furthermore', 'And yet', 'C', 'C. ''Furthermore'' dịch là ''Hơn nữa'' là đáp án đúng vì từ này bổ sung thông tin về việc thay thế hệ thống điều hòa.
’On one hand'' (Một mặt) thường được dùng khi có sự so sánh giữa hai ý tưởng đối lập,
’Nonetheless'' (Tuy nhiên)
’And yet'' (Vậy mà) chỉ ra sự trái ngược, nên không phù hợp với ngữ cảnh.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4337, 3355, 137, NULL, 'Take advantage of dozens of useful online tools.', 'Moreover, the air conditioner you chose is very popular.', 'Plus, they are friendly, clean, and knowledgeable.', 'Thank you for visiting our contractor showroom.', 'C', 'C. ''Plus, they are friendly, clean, and knowledgeable.'' dịch là ''Ngoài ra, họ thân thiện, sạch sẽ và hiểu biết.'' là đúng vì câu này bổ sung mô tả về nhân viên.
Các lựa chọn khác như ''Take advantage of dozens of useful online tools.'' (Tận dụng hàng chục công cụ trực tuyến hữu ích)
’Moreover, the air conditioner you chose is very popular.'' (Hơn nữa, máy điều hòa bạn chọn rất phổ biến.) không liên quan đến nhân viên.
’Thank you for visiting our contractor showroom.'' (Cảm ơn bạn đã ghé thăm phòng trưng bày nhà thầu của chúng tôi) cũng không phù hợp.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4338, 3355, 138, NULL, 'backed', 'backs', 'backing', 'back', 'A', 'A. ''backed'' dịch là ''được hỗ trợ'' là đúng vì cụm ''backed by'' có nghĩa là ''được hỗ trợ bởi'', diễn tả rằng cam kết được bảo đảm bởi sự đảm bảo của công ty.
Các lựa chọn khác như ''backs'' (hỗ trợ), ''backing'' (đang hỗ trợ), và ''back'' (hỗ trợ) không phù hợp với cấu trúc của câu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3356, 153, NULL, NULL, 'To: All Customers
From: asquires@lightidea.com
Date: March 6
Subject: Information
Dear Light Idea Customers,
Light Idea is enacting a price increase on select energy-efficient products, effective April 17. Specific product pricing will 139.... Please contact your sales representative for details and questions.
The last date for ordering at current prices is April 16. All orders 140.... after this date will follow the new price list.141..... Customers will be able to find this on our Web site.
We will continue to provide quality products and 142.... service to our valued customers. Thank you for your business.
Sincerely,
Arvin Squires Head of Sales, Light Idea', NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4339, 3356, 139, NULL, 'agree', 'vary', 'wait', 'decline', 'B', 'B. ''vary'' dịch là ''thay đổi'', là động từ phù hợp trong ngữ cảnh này vì giá cả của các sản phẩm khác nhau sẽ thay đổi.
’agree'' (đồng ý),
’wait'' (chờ đợi)
’decline’ (giảm) không phù hợp với ngữ cảnh nói về giá cả thay đổi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4340, 3356, 140, NULL, 'receiving', 'having received', 'received', 'will be received', 'C', 'C. ''received'' dịch là ''đã nhận'', là đáp án đúng vì cấu trúc ngữ pháp đòi hỏi quá khứ phân từ để diễn tả các đơn hàng được nhận sau ngày quy định.
’receiving'' (đang nhận),
’having received'' (đã nhận),
’will be received'' (sẽ được nhận) không phù hợp với ngữ cảnh về đơn hàng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4341, 3356, 141, NULL, 'The updated price list will be available on March 20.', 'We apologize for this inconvenience.', 'Your orders will be shipped after April 17.', 'We are increasing prices because of rising costs.', 'A', 'A. ''The updated price list will be available on March 20.'' dịch là ''Danh sách giá mới sẽ có vào ngày 20 tháng 3.'' là đúng vì nó cung cấp thông tin rõ ràng về ngày cụ thể cho danh sách giá cập nhật.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4342, 3356, 142, NULL, 'exceptionally', 'exception', 'exceptional', 'exceptionalism', 'C', 'C. ''exceptional'' dịch là ''đặc biệt'', là tính từ phù hợp để mô tả dịch vụ.
’exceptionally'' (một cách đặc biệt),
’exception'' (ngoại lệ),
’exceptionalism’ (chủ nghĩa đặc biệt) không phù hợp với ngữ pháp và ngữ cảnh trong câu này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3357, 153, NULL, NULL, 'To: Jang-Ho Kwon <jkwon@newart.nz>
From: Kenneth Okim <k.okim@okimjewelry.nz>
