INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4405, 3416, 5, NULL, 'A railing is being removed.', 'A roof is under construction.', 'Some workers are carrying a ladder.', 'Some workers are holding sheets of metal.', 'B', 'Một lan can đang bị tháo ra.
