INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4406, 3417, 6, NULL, 'A ladder has been leaned against a tree.', 'There are piles of tree branches discarded in a field.', 'Wooden benches have been arranged in a circle.', 'A wooden structure has been built near some trees.', 'D', 'Một chiếc thang đã được dựa vào cây.
