INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4407, 3418, 7, 'Why are there no flowers in the shop?', 'Because it''s out of stock.', 'Those roses smell nice.', 'No, the other cake.', NULL, 'A', 'Câu hỏi: Tại sao không có hoa trong cửa hàng?
