INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4408, 3419, 8, 'When will the catering company arrive?', 'At 4 o''clock.', 'That''s a delicious flavor.', 'Many vegetarian options.', NULL, 'A', 'Câu hỏi: Khi nào công ty cung cấp đồ ăn sẽ đến?
