INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4409, 3420, 9, 'When''s the meeting scheduled to start?', 'At a networking event.', 'I started this job six years ago.', 'Right after lunch.', NULL, 'C', 'Câu hỏi: Cuộc họp được lên lịch bắt đầu khi nào?
A. Tại một sự kiện kết nối.
B. Tôi bắt đầu công việc này sáu năm trước.
