INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4411, 3422, 11, 'You went to the dentist this morning, didn''t you?', 'Oh, I''ve already had breakfast.', 'Yes, for an annual check-up.', 'Let''s take the bus.', NULL, 'B', 'Câu hỏi: Sáng nay bạn đã đi khám nha sĩ, phải không?
A. Ồ, tôi đã ăn sáng rồi.
B. Vâng, để kiểm tra sức khỏe hàng năm.
