INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4412, 3423, 12, 'Where should we put the new printer?', 'In the corner by the stairs.', 'The third page of the document.', 'A reusable ink cartridge.', NULL, 'A', 'Câu hỏi: Chúng ta nên đặt máy in mới ở đâu?
