INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4413, 3424, 13, 'What type of plant do you have in your office?', 'Whenever I sit at my desk', 'Thanks, I just bought it', 'One that doesn''t require much water', NULL, 'C', 'Câu hỏi: Bạn có loại cây gì trong văn phòng của mình?
