INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4414, 3425, 14, 'There was a sale at the furniture store.', 'No, it wasn''t in storage.', 'Did you buy anything?', 'Some old receipts.', NULL, 'B', 'Câu hỏi: Có một đợt giảm giá ở cửa hàng nội thất.
