INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4605, 3616, 5, NULL, 'Some people are riding bicycles through a field.', 'Some people are moving a picnic table.', 'There are some mountains in the distance.', 'A bicycle has fallen over on the ground.', 'C', 'Một số người đang đạp xe qua cánh đồng.
Một số người đang di chuyển bàn dã ngoại.
Có một số ngọn núi ở phía xa.
Một chiếc xe đạp đã ngã xuống đất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3617, 162, '2024/test4/audio/test4_question_6.mp3', '2024/test4/image/test4-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4606, 3617, 6, NULL, 'Some couches have been pushed against a wall.', 'Some lights have been hung from the ceiling.', 'Some cushions have been stacked on the floor.', 'Some flowers have been arranged in a vase.', 'D', 'Một số ghế sofa đã được đẩy sát vào tường.
Một số đèn đã được treo lên trần nhà.
Một số đệm đã được xếp chồng lên sàn.
Một số hoa đã được sắp xếp trong bình.');;

-- Data for 2024 Test4 Part 2
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3618, 163, '2024/test4/audio/test4_question_7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4607, 3618, 7, 'Does the shop open on Sundays?', 'Yes, at one o''clock.', 'Because we drove.', 'I''d like to return this item, please.', NULL, 'A', 'Đáp án A là hợp lý nhất vì nó trả lời trực tiếp câu hỏi về thời gian mở cửa của cửa hàng vào Chủ nhật.
Dịch câu hỏi: Cửa hàng có mở cửa vào Chủ nhật không?
Dịch đáp án:
A. Có, lúc 1 giờ.
B. Bởi vì chúng tôi đã lái xe đến.
C. Tôi muốn trả lại món hàng này, làm ơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3619, 163, '2024/test4/audio/test4_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4608, 3619, 8, 'Where did these oranges come from?', 'Here''s a basket you can use.', 'From a supplier in California.', 'That umbrella is a nice color.', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về nguồn gốc của những quả cam.
Dịch câu hỏi: Những quả cam này đến từ đâu?
Dịch đáp án:
A. Đây là một cái giỏ bạn có thể sử dụng.
B. Từ một nhà cung cấp ở California.
C. Cái ô đó có màu đẹp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3620, 163, '2024/test4/audio/test4_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4609, 3620, 9, 'Should I make the dinner reservation for Friday or Saturday?', 'The Beachside Bistro.', 'Saturday is better.', 'A large plate of pasta.', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về việc nên đặt chỗ vào ngày nào.
Dịch câu hỏi: Tôi nên đặt chỗ ăn tối cho thứ Sáu hay thứ Bảy?
Dịch đáp án:
A. Nhà hàng Beachside Bistro.
B. Thứ Bảy thì tốt hơn.
C. Một đĩa lớn mì ống.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3621, 163, '2024/test4/audio/test4_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4610, 3621, 10, 'Will Dr. Evenover be late today?', 'No, you shouldn''t have to wait long.', 'It''s just under the desk.', 'Sure, I can do that for you.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về việc liệu bác sĩ có đến muộn hay không.
Dịch câu hỏi: Bác sĩ Evenover có đến muộn hôm nay không?
Dịch đáp án:
A. Không, bạn không phải đợi lâu đâu.
B. Nó ở ngay dưới bàn.
C. Được, tôi có thể làm điều đó cho bạn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3622, 163, '2024/test4/audio/test4_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4611, 3622, 11, 'Aren''t there locker rooms at this gym?', 'These socks are quite comfortable.', 'She teaches an exercise class.', 'Yes, they''re on the lower floor.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về vị trí của phòng thay đồ trong phòng tập.
Dịch câu hỏi: Không phải có phòng thay đồ ở phòng tập gym này sao?
Dịch đáp án:
A. Những đôi tất này khá thoải mái.
B. Cô ấy dạy một lớp thể dục.
C. Có, chúng ở tầng dưới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3623, 163, '2024/test4/audio/test4_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4612, 3623, 12, 'Who needs a copy of my safety training certificate?', 'Maxime does.', 'You can hang your vest on that hook.', 'No, I''m certain about that.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về người cần bản sao chứng chỉ an toàn.
Dịch câu hỏi: Ai cần một bản sao chứng chỉ đào tạo an toàn của tôi?
Dịch đáp án:
A. Maxime cần.
B. Bạn có thể treo áo ghi-lê của bạn lên móc đó.
C. Không, tôi chắc chắn về điều đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3624, 163, '2024/test4/audio/test4_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4613, 3624, 13, 'Could you phone Mr. Farras and let him know we''re in the hotel lobby?', 'Thank you. It was just renovated', 'A free continental breakfast', 'Yes, of course', NULL, 'C', 'Đáp án C trực tiếp trả lời yêu cầu gọi điện cho Mr. Farras.
Dịch câu hỏi: Bạn có thể gọi điện cho ông Farras và cho ông ấy biết chúng tôi đang ở sảnh khách sạn được không?
Dịch đáp án:
A. Cảm ơn. Nó vừa được tu sửa.
B. Một bữa sáng kiểu lục địa miễn phí.
C. Vâng, tất nhiên rồi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3625, 163, '2024/test4/audio/test4_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4614, 3625, 14, 'Where does she sell her handmade jewellery?', 'They''ll give you a discount.', 'A pair of earrings.', 'At a store in the city centre.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về nơi bán đồ trang sức thủ công.
Dịch câu hỏi: Cô ấy bán đồ trang sức thủ công ở đâu?
Dịch đáp án:
A. Họ sẽ cho bạn giảm giá.
B. Một đôi hoa tai.
C. Tại một cửa hàng ở trung tâm thành phố.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3626, 163, '2024/test4/audio/test4_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4615, 3626, 15, 'You''re taking a business class in the afternoon, aren''t you?', 'Actually, it''s in the morning.', 'That office is on the corner.', 'I have the train schedule here.', NULL, 'A', 'Đáp án A trực tiếp sửa lại thông tin về thời gian của lớp học kinh doanh.
Dịch câu hỏi: Bạn đang học lớp kinh doanh vào buổi chiều, phải không?
Dịch đáp án:
A. Thực ra, nó vào buổi sáng.
B. Văn phòng đó ở góc đường.
C. Tôi có lịch tàu ở đây.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3627, 163, '2024/test4/audio/test4_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4616, 3627, 16, 'Could I see some sample floral arrangements before I order?', 'It''s for an award ceremony.', 'A charge for expedited delivery.', 'Certainly. I have some right here.', NULL, 'C', 'Đáp án C trực tiếp đáp ứng yêu cầu xem mẫu cách cắm hoa.
Dịch câu hỏi: Tôi có thể xem một số mẫu cách cắm hoa trước khi đặt hàng được không?
Dịch đáp án:
A. Nó dành cho một buổi lễ trao giải.
B. Một khoản phí cho giao hàng nhanh.
C. Chắc chắn rồi. Tôi có một số mẫu ngay đây.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3628, 163, '2024/test4/audio/test4_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4617, 3628, 17, 'Don''t you want to buy the black sofa?', 'Some customer reviews', 'We already have one', 'I take my coffee with sugar', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về việc mua ghế sofa đen.
Dịch câu hỏi: Bạn không muốn mua ghế sofa đen sao?
Dịch đáp án:
A. Một số đánh giá của khách hàng
B. Chúng tôi đã có một cái rồi
C. Tôi uống cà phê với đường');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3629, 163, '2024/test4/audio/test4_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4618, 3629, 18, 'Do you have this jacket in a larger size?', 'Oh, I''m not a sales associate.', 'I''ve read the information packet.', 'A very large uniform.', NULL, 'A', 'Đáp án A giải thích lý do người trả lời không thể giúp đỡ về kích cỡ áo khoác.
Dịch câu hỏi: Bạn có áo khoác này với kích cỡ lớn hơn không?
Dịch đáp án:
A. Ồ, tôi không phải là nhân viên bán hàng.
B. Tôi đã đọc gói thông tin.
C. Một bộ đồng phục rất lớn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3630, 163, '2024/test4/audio/test4_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4619, 3630, 19, 'Where did you first learn about the job opening?', 'Are there any outdoor tables available?', 'The door to the building is still open.', 'I read an online newspaper every morning.', NULL, 'C', 'Đáp án C gợi ý rằng người trả lời có thể đã biết về việc mở vị trí công việc từ việc đọc báo trực tuyến.
Dịch câu hỏi: Bạn lần đầu biết về vị trí công việc này ở đâu?
Dịch đáp án:
A. Có bàn ngoài trời nào còn trống không?
B. Cửa tòa nhà vẫn còn mở.
C. Tôi đọc một tờ báo trực tuyến mỗi sáng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3631, 163, '2024/test4/audio/test4_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4620, 3631, 20, 'Should I bring anything to the meeting?', 'Probably in the conference room.', 'They were hired by our manager.', 'Do we have enough handouts?', NULL, 'C', 'Đáp án C gợi ý rằng người trả lời đang nghĩ về tài liệu phát tay cho cuộc họp, liên quan đến câu hỏi về việc mang theo thứ gì đó.
Dịch câu hỏi: Tôi có nên mang gì đến cuộc họp không?
Dịch đáp án:
A. Có lẽ trong phòng hội nghị.
B. Họ được thuê bởi quản lý của chúng ta.
C. Chúng ta có đủ tài liệu phát tay không?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3632, 163, '2024/test4/audio/test4_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4621, 3632, 21, 'What was the total charge for the hotel stay?', 'I''d have to look at the receipt.', 'The fitness center is across from the reception desk.', 'I''ll be eating breakfast in my room.', NULL, 'A', 'Đáp án A trực tiếp đề cập đến việc cần kiểm tra hóa đơn để biết tổng chi phí.
Dịch câu hỏi: Tổng chi phí cho việc lưu trú tại khách sạn là bao nhiêu?
Dịch đáp án:
A. Tôi sẽ phải xem lại hóa đơn.
B. Trung tâm thể dục nằm đối diện quầy lễ tân.
C. Tôi sẽ ăn sáng trong phòng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3633, 163, '2024/test4/audio/test4_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4622, 3633, 22, 'Why did you pursue a career in video game design?', 'Because I have a talent for it.', 'This is my new laptop.', 'It''s on the other shelf.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về lý do chọn nghề thiết kế trò chơi điện tử.
Dịch câu hỏi: Tại sao bạn theo đuổi sự nghiệp trong lĩnh vực thiết kế trò chơi điện tử?
Dịch đáp án:
A. Bởi vì tôi có tài năng về nó.
B. Đây là laptop mới của tôi.
C. Nó ở trên kệ khác.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3634, 163, '2024/test4/audio/test4_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4623, 3634, 23, 'I''d like to attend the job fair next month.', 'The speech was inspiring.', 'Tunji updated the memo.', 'Registration closed yesterday.', NULL, 'C', 'Đáp án C cho biết thông tin về việc đăng ký tham dự hội chợ việc làm đã kết thúc.
Dịch câu hỏi: Tôi muốn tham dự hội chợ việc làm tháng sau.
Dịch đáp án:
A. Bài phát biểu rất truyền cảm hứng.
B. Tunji đã cập nhật bản ghi nhớ.
C. Đăng ký đã kết thúc ngày hôm qua.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3635, 163, '2024/test4/audio/test4_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4624, 3635, 24, 'Hasn''t anyone called you back for the second interview yet?', 'A new phone number', 'Yes, any available position', 'I''m still waiting', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về việc chưa nhận được cuộc gọi cho cuộc phỏng vấn thứ hai.
Dịch câu hỏi: Chưa ai gọi lại cho bạn về cuộc phỏng vấn thứ hai sao?
Dịch đáp án:
A. Một số điện thoại mới
B. Vâng, bất kỳ vị trí nào còn trống
C. Tôi vẫn đang chờ đợi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3636, 163, '2024/test4/audio/test4_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4625, 3636, 25, 'How many tickets do we need for tonight''s concert?', 'The theater is on Johnson Avenue', 'At 730 Sharp', 'I''ll buy mine at the door', NULL, 'C', 'Đáp án C ngụ ý rằng người nói sẽ mua vé riêng, giúp người hỏi biết số lượng vé cần mua.
Dịch câu hỏi: Chúng ta cần bao nhiêu vé cho buổi hòa nhạc tối nay?
Dịch đáp án:
A. Nhà hát ở trên đại lộ Johnson
B. Lúc 7:30 đúng
C. Tôi sẽ mua vé của mình tại cửa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3637, 163, '2024/test4/audio/test4_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4626, 3637, 26, 'When are they going to decide who to hire?', 'A much higher salary', 'A lot of good resumes have come in', 'In the building across the street', NULL, 'B', 'Đáp án B gợi ý rằng quá trình tuyển dụng đang diễn ra và có nhiều ứng viên tốt, liên quan đến thời gian quyết định tuyển dụng.
Dịch câu hỏi: Khi nào họ sẽ quyết định thuê ai?
Dịch đáp án:
A. Một mức lương cao hơn nhiều
B. Có rất nhiều hồ sơ tốt đã được gửi đến
C. Trong tòa nhà đối diện');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3638, 163, '2024/test4/audio/test4_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4627, 3638, 27, 'I had a chance to look over the contract this morning', 'Their contact information', 'Early next week', 'What did you think of it?', NULL, 'C', 'Đáp án C là câu hỏi phù hợp nhất để đáp lại thông tin về việc đã xem xét hợp đồng.
Dịch câu hỏi: Tôi đã có cơ hội xem qua hợp đồng sáng nay.
Dịch đáp án:
A. Thông tin liên lạc của họ
B. Đầu tuần sau
C. Bạn nghĩ gì về nó?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3639, 163, '2024/test4/audio/test4_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4628, 3639, 28, 'How are the database updates coming along?', 'I''ve been really busy with the Williams account.', 'Some customer addresses.', 'She arrives on Wednesday.', NULL, 'A', 'Đáp án A gián tiếp giải thích lý do tại sao công việc cập nhật cơ sở dữ liệu có thể bị chậm trễ.
