INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4630, 3641, 30, 'The market on Fifth Street is closed for a week.', 'Some new clothes.', 'Is there another one nearby?', 'The price has been marked down.', NULL, 'B', 'Đáp án B là phản ứng hợp lý nhất khi biết một cửa hàng đóng cửa, hỏi về địa điểm thay thế.
