INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4655, 3666, 55, 'What will the woman do on Tuesday?', 'Wash her car', 'Close her store', 'Take some measurements', 'Look at some material samples', 'B', 'Đáp án đúng là B.
