INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4802, 3813, 2, NULL, 'Some of the people are pulling suitcases.', 'Some of the people are relaxing on benches.', 'Some of the people are putting luggage onto a rack.', 'Some of the people are waiting in line to purchase a ticket.', 'A', 'Một số người đang kéo vali.
Một số người đang thư giãn trên ghế dài.
Một số người đang đặt hành lý lên giá.
Một số người đang xếp hàng mua vé.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3814, 169, '2024/test5/audio/test5_question_3.mp3', '2024/test5/image/test5-image-3.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4803, 3814, 3, NULL, 'She''s looking into her backpack.', 'She''s tying the laces of her boots.', 'She''s hiking on an outdoor path.', 'She''s walking out of a tunnel.', 'C', 'Cô ấy đang nhìn vào ba lô của mình.
Cô ấy đang buộc dây giày của mình.
Cô ấy đang đi bộ trên một con đường ngoài trời.
Cô ấy đang đi ra khỏi một đường hầm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3815, 169, '2024/test5/audio/test5_question_4.mp3', '2024/test5/image/test5-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4804, 3815, 4, NULL, 'He''s holding the handle of a shopping cart.', 'He''s plugging a cord into a wall outlet.', 'He''s looking into a kitchen cupboard.', 'He''s kneeling down on a tile floor.', 'D', 'Anh ấy đang cầm tay cầm của một xe đẩy mua sắm.
Anh ấy đang cắm dây điện vào ổ cắm tường.
Anh ấy đang nhìn vào một tủ bếp.
Anh ấy đang quỳ trên sàn gạch.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3816, 169, '2024/test5/audio/test5_question_5.mp3', '2024/test5/image/test5-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4805, 3816, 5, NULL, 'Seats have been arranged under some umbrellas.', 'Some street signs are being taken down.', 'Some bushes are being trimmed.', 'Some chairs are being folded and stacked.', 'A', 'Ghế đã được sắp xếp dưới một số ô dù.
Một số biển báo đường phố đang được tháo xuống.
Một số bụi cây đang được cắt tỉa.
Một số ghế đang được gấp và xếp chồng lên nhau.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3817, 169, '2024/test5/audio/test5_question_6.mp3', '2024/test5/image/test5-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4806, 3817, 6, NULL, 'Some cushions have been laid on the floor.', 'Books have been piled up by a glass door.', 'A light fixture is suspended from the ceiling.', 'A rug has been rolled up against a wall.', 'B', 'Một số đệm đã được đặt trên sàn.
Sách đã được chất đống cạnh cửa kính.
Một thiết bị chiếu sáng được treo từ trần nhà.
Một tấm thảm đã được cuộn lại và đặt dựa vào tường.');;

