INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3818, 170, '2024/test5/audio/test5_question_7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4807, 3818, 7, 'There''s a meeting in the conference room soon, right?', 'Yes, it''s for the whole department.', 'No, put it in the closet.', 'The rent is too high.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về cuộc họp sắp diễn ra.
Dịch câu hỏi: Sắp có một cuộc họp trong phòng hội nghị, phải không?
Dịch đáp án:
A. Đúng, nó dành cho toàn bộ phòng ban.
B. Không, hãy để nó trong tủ.
C. Tiền thuê quá cao.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3819, 170, '2024/test5/audio/test5_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4808, 3819, 8, 'Why hasn''t the mural in the lobby been painted yet?', 'Red and yellow.', 'Please pick up the ladder.', 'Because the artist is out of town.', NULL, 'C', 'Đáp án C giải thích lý do tại sao bức tranh tường chưa được vẽ.
Dịch câu hỏi: Tại sao bức tranh tường ở sảnh vẫn chưa được vẽ?
Dịch đáp án:
A. Màu đỏ và vàng.
B. Vui lòng nhặt cái thang lên.
C. Bởi vì nghệ sĩ đang đi vắng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3820, 170, '2024/test5/audio/test5_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4809, 3820, 9, 'Do you prefer writing in the morning or the afternoon?', 'My publisher requested edits.', 'Thanks for providing a solution.', 'Mornings are usually better for me.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về thời gian viết ưa thích.
Dịch câu hỏi: Bạn thích viết vào buổi sáng hay buổi chiều hơn?
Dịch đáp án:
A. Nhà xuất bản của tôi yêu cầu chỉnh sửa.
B. Cảm ơn vì đã cung cấp giải pháp.
C. Buổi sáng thường tốt hơn cho tôi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3821, 170, '2024/test5/audio/test5_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4810, 3821, 10, 'I suggest we paint the waiting room light blue', 'Dr. Park has an opening at 3', 'That''s a good idea', 'I prefer the red jacket', NULL, 'B', 'Đáp án B là phản hồi phù hợp nhất cho đề xuất về màu sơn.
Dịch câu hỏi: Tôi đề nghị chúng ta sơn phòng chờ màu xanh nhạt.
Dịch đáp án:
A. Bác sĩ Park có lịch trống lúc 3 giờ.
B. Đó là một ý kiến hay.
C. Tôi thích cái áo khoác màu đỏ hơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3822, 170, '2024/test5/audio/test5_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4811, 3822, 11, 'Did you know that the music school is closed on Sundays?', 'Forty dollars an hour.', 'No, I didn''t know that.', 'I saw the piano recital.', NULL, 'B', 'Đáp án B là phản hồi trực tiếp cho câu hỏi về việc biết thông tin đóng cửa của trường âm nhạc.
Dịch câu hỏi: Bạn có biết rằng trường âm nhạc đóng cửa vào Chủ nhật không?
Dịch đáp án:
A. Bốn mươi đô la một giờ.
B. Không, tôi không biết điều đó.
C. Tôi đã xem buổi biểu diễn piano.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3823, 170, '2024/test5/audio/test5_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4812, 3823, 12, 'How do I find the office manager?', 'The receptionist would know.', 'Desk lamps and headsets.', 'Twelve euros.', NULL, 'A', 'Đáp án A cung cấp thông tin hữu ích về cách tìm người quản lý văn phòng.
Dịch câu hỏi: Làm thế nào để tôi tìm người quản lý văn phòng?
Dịch đáp án:
A. Lễ tân sẽ biết.
B. Đèn bàn và tai nghe.
C. Mười hai euro.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3824, 170, '2024/test5/audio/test5_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4813, 3824, 13, 'When did you place the order for the lumber?', 'Yes, it''s a great place for hiking.', 'It''s out of stock right now.', 'The warehouse on William Street.', NULL, 'B', 'Đáp án B, mặc dù không trực tiếp trả lời câu hỏi về thời gian đặt hàng, nhưng ngụ ý rằng đơn hàng chưa được đặt vì hàng đang hết.
Dịch câu hỏi: Khi nào bạn đặt hàng gỗ?
Dịch đáp án:
A. Vâng, đó là một nơi tuyệt vời để đi bộ đường dài.
B. Hiện tại đang hết hàng.
C. Kho hàng trên đường William.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3825, 170, '2024/test5/audio/test5_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4814, 3825, 14, 'Where is the new packaging machine?', 'Ten packages a minute', 'We met last Thursday', 'We decided to keep the old one', NULL, 'C', 'Đáp án C ngụ ý rằng không có máy đóng gói mới vì họ quyết định giữ lại máy cũ.
Dịch câu hỏi: Máy đóng gói mới ở đâu?
Dịch đáp án:
A. Mười gói một phút.
B. Chúng ta đã gặp nhau vào thứ Năm tuần trước.
C. Chúng tôi quyết định giữ lại cái cũ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3826, 170, '2024/test5/audio/test5_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4815, 3826, 15, 'I''ll be out of the office this afternoon', 'An awfully long commute', 'Okay, I''ll update your schedule', 'It''s right down the hallway', NULL, 'B', 'Đáp án B là phản hồi phù hợp nhất cho thông báo về việc vắng mặt.
Dịch câu hỏi: Tôi sẽ không có mặt ở văn phòng chiều nay.
Dịch đáp án:
A. Một chuyến đi làm dài đáng sợ.
B. Được, tôi sẽ cập nhật lịch trình của bạn.
C. Nó ở ngay cuối hành lang.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3827, 170, '2024/test5/audio/test5_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4816, 3827, 16, 'Are you taking a vacation once this project is over?', 'Yes, I''m planning a trip to Barcelona', 'This is your second time, isn''t it?', 'Blueprints for a high-rise building.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về kế hoạch nghỉ phép.
Dịch câu hỏi: Bạn có đi nghỉ sau khi dự án này kết thúc không?
Dịch đáp án:
A. Vâng, tôi đang lên kế hoạch cho một chuyến đi đến Barcelona.
B. Đây là lần thứ hai của bạn, phải không?
C. Bản vẽ thiết kế cho một tòa nhà cao tầng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3828, 170, '2024/test5/audio/test5_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4817, 3828, 17, 'Let''s post the sales report to our team''s web page.', 'We''re sharing a taxi to the airport.', 'I can do that.', 'A recent hiring decision.', NULL, 'B', 'Đáp án B là phản hồi phù hợp nhất cho đề xuất đăng báo cáo bán hàng.
Dịch câu hỏi: Hãy đăng báo cáo bán hàng lên trang web của đội chúng ta.
Dịch đáp án:
A. Chúng tôi đang chia sẻ một chuyến taxi đến sân bay.
B. Tôi có thể làm điều đó.
C. Một quyết định tuyển dụng gần đây.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3829, 170, '2024/test5/audio/test5_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4818, 3829, 18, 'Which airline are you planning on using?', 'The usual one.', 'A one-way ticket.', 'Yes, you can use mine.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về hãng hàng không được chọn.
Dịch câu hỏi: Bạn dự định sử dụng hãng hàng không nào?
Dịch đáp án:
A. Hãng thường dùng.
B. Một vé một chiều.
C. Vâng, bạn có thể sử dụng cái của tôi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3830, 170, '2024/test5/audio/test5_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4819, 3830, 19, 'Where''s this shipment of parts being sent?', 'Around five thirty this evening.', 'To the assembly plant in Dublin.', 'Just half the order.', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về địa điểm gửi hàng.
Dịch câu hỏi: Lô hàng linh kiện này đang được gửi đi đâu?
Dịch đáp án:
A. Khoảng 5h30 tối.
B. Đến nhà máy lắp ráp ở Dublin.
C. Chỉ một nửa đơn hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3831, 170, '2024/test5/audio/test5_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4820, 3831, 20, 'Who paid for lunch?', 'I just ate.', 'It closes at 5.', 'Alberto did.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về người đã trả tiền ăn trưa.
Dịch câu hỏi: Ai đã trả tiền cho bữa trưa?
Dịch đáp án:
A. Tôi vừa ăn xong.
B. Nó đóng cửa lúc 5 giờ.
C. Alberto đã trả.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3832, 170, '2024/test5/audio/test5_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4821, 3832, 21, 'How many employees work in your department?', 'I don''t mind taking notes at the meeting', 'A couple dozen, I think', 'It''s seven meters long', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về số lượng nhân viên.
Dịch câu hỏi: Có bao nhiêu nhân viên làm việc trong phòng ban của bạn?
Dịch đáp án:
A. Tôi không phiền khi ghi chép trong cuộc họp.
B. Tôi nghĩ khoảng vài chục người.
C. Nó dài bảy mét.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3833, 170, '2024/test5/audio/test5_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4822, 3833, 22, 'We should leave for our training course soon, shouldn''t we?', 'We still have a few minutes.', 'There''s a map on the wall.', 'Two sessions per day.', NULL, 'A', 'Đáp án A là phản hồi hợp lý nhất cho câu hỏi về thời gian rời đi.
Dịch câu hỏi: Chúng ta nên sớm rời đi để đến khóa đào tạo, phải không?
Dịch đáp án:
A. Chúng ta vẫn còn vài phút.
B. Có một bản đồ trên tường.
C. Hai buổi mỗi ngày.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3834, 170, '2024/test5/audio/test5_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4823, 3834, 23, 'Isn''t there a limit on travel expenses?', 'To fix the vending machine.', '$100 per day.', 'Next to the travel agency.', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về giới hạn chi phí đi lại.
Dịch câu hỏi: Không phải có giới hạn cho chi phí đi lại sao?
Dịch đáp án:
A. Để sửa máy bán hàng tự động.
B. 100 đô la mỗi ngày.
C. Bên cạnh đại lý du lịch.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3835, 170, '2024/test5/audio/test5_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4824, 3835, 24, 'When should I tell the director that I''m interested in the management position?', 'Yes, we''re extending our business hours.', 'Didn''t Andre direct the play?', 'I''m not on the hiring team.', NULL, 'C', 'Đáp án C, mặc dù không trực tiếp trả lời câu hỏi, nhưng ngụ ý rằng người nói không phải là người phù hợp để hỏi về vấn đề này.
Dịch câu hỏi: Khi nào tôi nên nói với giám đốc rằng tôi quan tâm đến vị trí quản lý?
Dịch đáp án:
A. Vâng, chúng tôi đang mở rộng giờ làm việc.
B. Andre không phải đạo diễn vở kịch sao?
C. Tôi không thuộc đội tuyển dụng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3836, 170, '2024/test5/audio/test5_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4825, 3836, 25, 'The layout of the footwear department has changed.', 'There''s a charging station in the cafe.', 'Yes, a three-bedroom apartment.', 'The store has a new manager.', NULL, 'C', 'Đáp án C gợi ý lý do có thể dẫn đến sự thay đổi bố trí của bộ phận giày dép.
Dịch câu hỏi: Bố trí của bộ phận giày dép đã thay đổi.
Dịch đáp án:
A. Có một trạm sạc trong quán cà phê.
B. Vâng, một căn hộ ba phòng ngủ.
C. Cửa hàng có một người quản lý mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3837, 170, '2024/test5/audio/test5_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4826, 3837, 26, 'Can you look at this month''s revenue report?', 'The news program is informative.', 'I have some free time tomorrow afternoon.', 'He started that position in July.', NULL, 'B', 'Đáp án B là phản hồi phù hợp nhất cho yêu cầu xem xét báo cáo doanh thu.
Dịch câu hỏi: Bạn có thể xem báo cáo doanh thu tháng này không?
Dịch đáp án:
A. Chương trình tin tức rất bổ ích.
B. Tôi có một chút thời gian rảnh vào chiều mai.
C. Anh ấy bắt đầu vị trí đó vào tháng Bảy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3838, 170, '2024/test5/audio/test5_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4827, 3838, 27, 'Why haven''t the windows been replaced yet?', 'Not too much wind, no.', 'Look in the filing cabinet.', 'Did you see the cost estimate?', NULL, 'C', 'Đáp án C gợi ý rằng chi phí có thể là lý do cho việc chậm trễ thay cửa sổ.
Dịch câu hỏi: Tại sao các cửa sổ vẫn chưa được thay thế?
Dịch đáp án:
A. Không có nhiều gió lắm, không.
B. Hãy nhìn trong tủ hồ sơ.
C. Bạn đã xem bản ước tính chi phí chưa?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3839, 170, '2024/test5/audio/test5_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4828, 3839, 28, 'Isn''t your suitcase going to be heavier than the permitted weight?', 'The building permit arrived today.', 'There are seats in the lobby.', 'I''ll have to pay a little bit extra.', NULL, 'C', 'Đáp án C ngụ ý rằng vali có thể nặng quá mức cho phép và sẽ phải trả thêm phí.
Dịch câu hỏi: Vali của bạn sẽ không nặng hơn trọng lượng cho phép sao?
Dịch đáp án:
A. Giấy phép xây dựng đã đến hôm nay.
B. Có ghế ngồi ở sảnh.
C. Tôi sẽ phải trả thêm một chút tiền.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3840, 170, '2024/test5/audio/test5_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4829, 3840, 29, 'Who manufactures the engines for our machines?', 'Koji is in charge of supplier contracts', 'I''m sorry, the storage room is full', 'That''s a cargo airplane', NULL, 'A', 'Đáp án A gợi ý rằng Koji, người phụ trách hợp đồng nhà cung cấp, có thể biết thông tin về nhà sản xuất động cơ.
Dịch câu hỏi: Ai sản xuất động cơ cho máy móc của chúng ta?
Dịch đáp án:
A. Koji phụ trách các hợp đồng nhà cung cấp.
B. Tôi xin lỗi, phòng kho đã đầy.
C. Đó là một máy bay chở hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3841, 170, '2024/test5/audio/test5_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4830, 3841, 30, 'Should we meet at the department store on 5th Street or the one on Grover Lane?', 'Let''s ask Patricia first.', 'No, I don''t mind.', 'How much does it cost?', NULL, 'A', 'Đáp án A đề xuất hỏi ý kiến của Patricia trước khi quyết định địa điểm gặp.
Dịch câu hỏi: Chúng ta nên gặp nhau ở cửa hàng bách hóa trên Đường 5 hay cái trên Đường Grover?
Dịch đáp án:
A. Hãy hỏi Patricia trước đã.
B. Không, tôi không phiền.
C. Nó tốn bao nhiêu tiền?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (3842, 170, '2024/test5/audio/test5_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4831, 3842, 31, 'Which band is playing at the club tonight?', 'There''s always a comedy show on Thursday nights.', 'Yes, I''ve played the piano for many years', 'Their number one hit', NULL, 'A', 'Đáp án A, mặc dù không trực tiếp trả lời câu hỏi về ban nhạc, nhưng cho biết thông tin về chương trình thường diễn ra vào tối thứ Năm.
Dịch câu hỏi: Ban nhạc nào đang biểu diễn ở câu lạc bộ tối nay?
Dịch đáp án:
A. Luôn có một buổi biểu diễn hài kịch vào tối thứ Năm.
B. Vâng, tôi đã chơi piano nhiều năm rồi.
C. Bài hit số một của họ.');;

