INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4839, 3850, 39, 'What does the man offer to do?', 'Authorize free shipping', 'Apply a discount', 'Provide a sample', 'Make a recommendation', 'D', 'Đáp án đúng là D.
