INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4840, 3851, 40, 'What does the woman ask about?', 'An expiration date', 'A manufacturer''s guarantee', 'The origin of a product', 'The cost of a product', 'A', 'Đáp án đúng là A.
