INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4843, 3854, 43, 'What does the woman say her company can provide?', 'A new client discount', 'A training video', 'An extended warranty', 'Customer testimonials', 'B', 'Đáp án đúng là B.
