INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4846, 3857, 46, 'What does the man say he will do?', 'Ask for a refund', 'Take a different route', 'Postpone a trip', 'File a complaint', 'B', 'Đáp án đúng là B.
