INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4849, 3860, 49, 'According to the man, what is the Renova Hotel offering this month?', 'A new shuttle service', 'A discount for businesses', 'A flexible cancellation policy', 'Complimentary meals', 'B', 'Đáp án đúng là B.
