INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4875, 3886, 75, 'Why are the listeners at Osterwind Estate?', 'To attend an awards ceremony', 'To apply for landscaping jobs', 'To take a tour of a building', 'To clean up some gardens', 'D', 'Đáp án đúng là D.
