INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4940, 3951, 140, NULL, 'asked', 'is asking', 'has asked', 'will ask', 'D', 'D. will ask (sẽ hỏi):n’Will ask'' là thì tương lai phù hợp với ngữ cảnh mô tả việc nhân viên sẽ yêu cầu số hóa đơn.
Các lựa chọn khác không đúng thì hoặc ngữ cảnh.
