INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (4980, 3991, 180, 'According to the Web page, what is NOT part of the Clary Clinic?', 'A medical laboratory', 'A pharmacy', 'Medical imaging equipment', 'Offices for clinicians', 'B', 'Đáp án: B.
