INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5001, 4012, 1, NULL, 'She''s shoveling snow from a walkway.', 'She''s using walking sticks.', 'She''s removing her cap.', 'She''s drinking from a water bottle.', 'B', 'Cô ấy đang xúc tuyết trên lối đi.
