INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5003, 4014, 3, NULL, 'The man is holding a bucket of water.', 'The man is replacing a tire.', 'The man is watering a tree.', 'The man is scrubbing the front of a car.', 'D', 'Người đàn ông đang cầm một xô nước.
