INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5004, 4015, 4, NULL, 'Some tiles are being installed on a roof.', 'An outdoor dining area is unoccupied.', 'Flowers have been placed on tables.', 'Some chairs have been arranged around a fountain.', 'B', 'Một số ngói đang được lắp đặt trên mái nhà.
