INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5005, 4016, 5, NULL, 'Some people are gathered on top of a building.', 'Some trees are blocking the entrance to a stairway.', 'A woman is taking some stairs to a lower level.', 'A woman is walking across a pedestrian bridge.', 'C', 'Một số người đang tụ tập trên nóc một tòa nhà.
