INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5006, 4017, 6, NULL, 'Some wooden planter boxes have been set next to each other.', 'Some wood logs have been piled in a corner.', 'The outside walls of a house are made of bricks.', 'Some windows are being installed.', 'A', 'Một số hộp trồng cây bằng gỗ đã được đặt cạnh nhau.
