INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4018, 177, '2024/test6/audio/test6_question_7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5007, 4018, 7, 'Who''s going to take home the leftover cake?', 'Marcel said he would.', 'A lovely selection of desserts.', 'No, I thought it started at noon.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về người sẽ mang bánh thừa về nhà.
Dịch câu hỏi: Ai sẽ mang bánh thừa về nhà?
Dịch đáp án:
A. Marcel nói anh ấy sẽ mang về.
B. Một lựa chọn tuyệt vời các món tráng miệng.
C. Không, tôi nghĩ nó bắt đầu lúc trưa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4019, 177, '2024/test6/audio/test6_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5008, 4019, 8, 'Can you tell me where the security office is?', 'Today''s my first day here.', 'A photograph for the badge.', 'Because it''s after lunch.', NULL, 'A', 'Đáp án A giải thích lý do người nói không biết vị trí văn phòng an ninh.
Dịch câu hỏi: Bạn có thể cho tôi biết văn phòng an ninh ở đâu không?
Dịch đáp án:
A. Hôm nay là ngày đầu tiên của tôi ở đây.
B. Một tấm ảnh cho thẻ.
C. Bởi vì đó là sau bữa trưa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4020, 177, '2024/test6/audio/test6_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5009, 4020, 9, 'What''s the best way to contact you?', 'On my mobile phone.', 'No, I have to wear glasses.', 'This resume is better.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về cách liên lạc tốt nhất.
Dịch câu hỏi: Cách tốt nhất để liên lạc với bạn là gì?
Dịch đáp án:
A. Qua điện thoại di động của tôi.
B. Không, tôi phải đeo kính.
C. Bản sơ yếu lý lịch này tốt hơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4021, 177, '2024/test6/audio/test6_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5010, 4021, 10, 'Who''s joining us for the waterfront boat ride?', 'Conference Room 3.', 'The admission fee is reasonable.', 'Everybody on our team is coming.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về người sẽ tham gia chuyến đi thuyền.
Dịch câu hỏi: Ai sẽ tham gia chúng ta trong chuyến đi thuyền dọc bờ biển?
Dịch đáp án:
A. Phòng họp số 3.
B. Phí vào cửa là hợp lý.
C. Mọi người trong đội của chúng ta đều đến.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4022, 177, '2024/test6/audio/test6_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5011, 4022, 11, 'Could you request a technician to repair the packaging machine?', 'Three years of technical school', 'Sure, I''ll do that', 'The blue one with gold trim', NULL, 'B', 'Đáp án B là phản hồi phù hợp nhất cho yêu cầu gọi kỹ thuật viên.
Dịch câu hỏi: Bạn có thể yêu cầu một kỹ thuật viên đến sửa máy đóng gói không?
Dịch đáp án:
A. Ba năm trường kỹ thuật
B. Chắc chắn rồi, tôi sẽ làm điều đó
C. Cái màu xanh với viền vàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4023, 177, '2024/test6/audio/test6_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5012, 4023, 12, 'How many copies of the proposal should I make?', 'There''s blue paper in the cabinet.', 'Yes, it was my idea.', 'Fifty should be enough for everyone.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về số lượng bản sao cần làm.
Dịch câu hỏi: Tôi nên làm bao nhiêu bản sao của đề xuất?
Dịch đáp án:
A. Có giấy màu xanh trong tủ.
B. Vâng, đó là ý tưởng của tôi.
C. Năm mươi bản nên đủ cho mọi người.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4024, 177, '2024/test6/audio/test6_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5013, 4024, 13, 'Why is Jonathan leaving early?', 'To catch the six o''clock train.', 'On the early morning news.', 'That''s where he lives now.', NULL, 'A', 'Đáp án A trực tiếp giải thích lý do Jonathan rời đi sớm.
Dịch câu hỏi: Tại sao Jonathan rời đi sớm?
Dịch đáp án:
A. Để kịp chuyến tàu lúc 6 giờ.
B. Trên bản tin sáng sớm.
C. Đó là nơi anh ấy sống bây giờ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4025, 177, '2024/test6/audio/test6_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5014, 4025, 14, 'Where''s the company party being held?', 'It''s a publishing firm.', 'Party of five at the table in the corner.', 'At the Chesterville Hotel.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về địa điểm tổ chức tiệc công ty.
Dịch câu hỏi: Tiệc công ty được tổ chức ở đâu?
Dịch đáp án:
A. Đó là một công ty xuất bản.
B. Nhóm năm người ở bàn góc.
C. Tại Khách sạn Chesterville.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4026, 177, '2024/test6/audio/test6_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5015, 4026, 15, 'Did you want to sign up for a one-year magazine subscription?', 'How much will it cost?', 'Near the service center.', 'Archie Co. works at the front desk.', NULL, 'A', 'Đáp án A là phản hồi hợp lý nhất cho câu hỏi về đăng ký tạp chí.
Dịch câu hỏi: Bạn có muốn đăng ký tạp chí trong một năm không?
Dịch đáp án:
A. Nó sẽ tốn bao nhiêu tiền?
B. Gần trung tâm dịch vụ.
C. Archie Co. làm việc ở quầy lễ tân.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4027, 177, '2024/test6/audio/test6_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5016, 4027, 16, 'Does this pasta come with a side salad?', 'We do have a tablecloth.', 'No, I''m afraid not.', 'I like it too.', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về món ăn kèm.
Dịch câu hỏi: Món mì ống này có kèm theo salad không?
Dịch đáp án:
A. Chúng tôi có khăn trải bàn.
B. Không, tôi e là không.
C. Tôi cũng thích nó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4028, 177, '2024/test6/audio/test6_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5017, 4028, 17, 'When can we meet about the invoices?', 'Supplies for the office.', 'I''m free after two.', 'Probably on Harold''s desk.', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về thời gian có thể gặp.
Dịch câu hỏi: Khi nào chúng ta có thể gặp nhau về các hóa đơn?
Dịch đáp án:
A. Vật tư cho văn phòng.
B. Tôi rảnh sau 2 giờ.
C. Có lẽ trên bàn của Harold.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4029, 177, '2024/test6/audio/test6_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5018, 4029, 18, 'Would you like me to help you open a savings account?', 'I''ve already counted them.', 'That''d be great.', '50 euros each.', NULL, 'B', 'Đáp án B là phản hồi phù hợp nhất cho đề nghị giúp đỡ mở tài khoản tiết kiệm.
Dịch câu hỏi: Bạn có muốn tôi giúp bạn mở một tài khoản tiết kiệm không?
Dịch đáp án:
A. Tôi đã đếm chúng rồi.
B. Điều đó thật tuyệt.
C. 50 euro mỗi cái.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4030, 177, '2024/test6/audio/test6_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5019, 4030, 19, 'When did you post the job opening?', 'On the bulletin board in the hallway.', 'It''s been on the website for a month.', 'Can you close the door?', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về thời gian đăng tin tuyển dụng.
Dịch câu hỏi: Khi nào bạn đăng tin tuyển dụng?
Dịch đáp án:
A. Trên bảng thông báo ở hành lang.
B. Nó đã được đăng trên trang web một tháng rồi.
C. Bạn có thể đóng cửa không?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4031, 177, '2024/test6/audio/test6_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5020, 4031, 20, 'Are you applying for the manager position?', 'About 16 more employees.', 'I''ll check her schedule again.', 'Yes, I hope I get it.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về việc ứng tuyển vị trí quản lý.
Dịch câu hỏi: Bạn có đang ứng tuyển vào vị trí quản lý không?
Dịch đáp án:
A. Khoảng 16 nhân viên nữa.
B. Tôi sẽ kiểm tra lịch của cô ấy lại.
C. Vâng, tôi hy vọng mình sẽ được nhận.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4032, 177, '2024/test6/audio/test6_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5021, 4032, 21, 'Are you traveling in business class or economy?', 'My flight was just cancelled.', 'My focus is history.', 'London, then New York.', NULL, 'A', 'Đáp án A, mặc dù không trực tiếp trả lời câu hỏi, nhưng ngụ ý rằng người nói không còn đi chuyến bay nào nữa.
Dịch câu hỏi: Bạn đi hạng thương gia hay hạng phổ thông?
Dịch đáp án:
A. Chuyến bay của tôi vừa bị hủy.
B. Tôi tập trung vào lịch sử.
C. London, sau đó là New York.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4033, 177, '2024/test6/audio/test6_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5022, 4033, 22, 'The number of subscribers for our magazine has decreased recently.', 'There''s room in the budget for more advertising.', 'An annual membership fee.', 'There are six folders on the table.', NULL, 'A', 'Đáp án A đề xuất một giải pháp có thể giúp tăng số lượng người đăng ký.
Dịch câu hỏi: Số lượng người đăng ký tạp chí của chúng ta đã giảm gần đây.
Dịch đáp án:
A. Có chỗ trong ngân sách cho việc quảng cáo nhiều hơn.
B. Một khoản phí thành viên hàng năm.
C. Có sáu tập hồ sơ trên bàn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4034, 177, '2024/test6/audio/test6_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5023, 4034, 23, 'How do you clean the solar panels without damaging them?', 'The glass can be any color you want.', 'No, the sun isn''t out today.', 'I pay a company to do all the maintenance.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về cách làm sạch các tấm pin mặt trời.
Dịch câu hỏi: Làm thế nào bạn làm sạch các tấm pin mặt trời mà không làm hỏng chúng?
Dịch đáp án:
A. Kính có thể là bất kỳ màu nào bạn muốn.
B. Không, hôm nay trời không nắng.
C. Tôi trả tiền cho một công ty để làm tất cả việc bảo trì.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4035, 177, '2024/test6/audio/test6_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5024, 4035, 24, 'When will I receive my certificate in the mail?', 'I''ll have to check with the office.', 'Turn left at the light.', 'No, thank you.', NULL, 'A', 'Đáp án A là phản hồi phù hợp nhất cho câu hỏi về thời gian nhận chứng chỉ.
Dịch câu hỏi: Khi nào tôi sẽ nhận được chứng chỉ qua đường bưu điện?
Dịch đáp án:
A. Tôi sẽ phải kiểm tra với văn phòng.
B. Rẽ trái ở đèn giao thông.
C. Không, cảm ơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4036, 177, '2024/test6/audio/test6_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5025, 4036, 25, 'Don''t we sell Ramirez lawnmowers?', 'The plants need more water', 'Sorry, refunds are not allowed', 'I work in the home decor area', NULL, 'C', 'Đáp án C ngụ ý rằng người nói không biết về việc bán máy cắt cỏ vì họ làm việc ở khu vực khác.
Dịch câu hỏi: Chúng ta không bán máy cắt cỏ Ramirez sao?
Dịch đáp án:
A. Cây cối cần thêm nước
B. Xin lỗi, không cho phép hoàn tiền
C. Tôi làm việc ở khu vực trang trí nội thất');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4037, 177, '2024/test6/audio/test6_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5026, 4037, 26, 'Should we meet to discuss our research project?', 'A publishing manual', 'Put something on my calendar', 'Alphabetical order is fine, I think', NULL, 'B', 'Đáp án B là phản hồi phù hợp nhất cho đề xuất gặp mặt thảo luận.
Dịch câu hỏi: Chúng ta có nên gặp nhau để thảo luận về dự án nghiên cứu không?
Dịch đáp án:
A. Một cuốn sổ tay xuất bản
B. Hãy đặt lịch cho tôi
C. Tôi nghĩ thứ tự bảng chữ cái là được');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4038, 177, '2024/test6/audio/test6_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5027, 4038, 27, 'When does the cleaning staff leave for the day?', 'A supply closet in the hall', 'By 6 o''clock, usually', 'The leaves come out in the spring', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về thời gian nhân viên vệ sinh rời đi.
Dịch câu hỏi: Nhân viên vệ sinh rời đi lúc mấy giờ?
Dịch đáp án:
A. Một tủ đựng vật tư ở hành lang
B. Thường là vào lúc 6 giờ
C. Lá cây mọc ra vào mùa xuân');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4039, 177, '2024/test6/audio/test6_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5028, 4039, 28, 'How would you like to pay for these shoes today?', 'With a store gift card', 'I wear a size 38', 'A friend recommended them', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về phương thức thanh toán.
Dịch câu hỏi: Hôm nay bạn muốn thanh toán cho đôi giày này bằng cách nào?
Dịch đáp án:
A. Bằng thẻ quà tặng của cửa hàng
B. Tôi mang size 38
C. Một người bạn đã giới thiệu chúng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4040, 177, '2024/test6/audio/test6_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5029, 4040, 29, 'It''s an effective advertisement, isn''t it?', 'I''ve heard that sales have increased', 'The next issue of the magazine', 'Isn''t the policy in effect already?', NULL, 'A', 'Đáp án A ngụ ý rằng quảng cáo có hiệu quả bằng cách đề cập đến việc tăng doanh số.
Dịch câu hỏi: Đó là một quảng cáo hiệu quả, phải không?
Dịch đáp án:
A. Tôi nghe nói doanh số đã tăng
B. Số tạp chí tiếp theo
C. Chính sách đó chưa có hiệu lực rồi sao?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4041, 177, '2024/test6/audio/test6_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5030, 4041, 30, 'Why don''t we take a walk after lunch?', 'The sales report is due at one o''clock.', 'No, in parking area B.', 'I''ll have spaghetti, please.', NULL, 'A', 'Đáp án A gián tiếp từ chối đề xuất đi dạo bằng cách đề cập đến một nhiệm vụ cần hoàn thành.
Dịch câu hỏi: Tại sao chúng ta không đi dạo sau bữa trưa?
Dịch đáp án:
A. Báo cáo doanh số phải nộp lúc 1 giờ.
B. Không, ở khu vực đỗ xe B.
C. Tôi sẽ dùng mì Ý, làm ơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4042, 177, '2024/test6/audio/test6_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5031, 4042, 31, 'I decided to move the seasonal merchandise to the front of the store.', 'Did you put some of it in the window display?', 'For our summer clothing collection.', 'The moving van is coming tomorrow', NULL, 'A', 'Đáp án A là câu hỏi phù hợp nhất liên quan đến việc di chuyển hàng hóa theo mùa.
Dịch câu hỏi: Tôi đã quyết định chuyển hàng hóa theo mùa ra phía trước cửa hàng.
Dịch đáp án:
A. Bạn có đặt một số trong cửa sổ không?
B. Cho bộ sưu tập quần áo mùa hè của chúng ta.
C. Xe tải chuyển đồ sẽ đến vào ngày mai');;

