INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5039, 4050, 39, 'Who most likely is the man?', 'A baker', 'A musician', 'A gardener', 'A teacher', 'A', 'Đáp án đúng là A.
