INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5042, 4053, 42, 'What does the man say is wrong with his mobile phone?', 'It has a short battery life.', 'The screen is damaged.', 'A cable is missing.', 'It has limited storage space.', 'A', 'Đáp án đúng là A.
