INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5076, 4087, 76, 'What information will the speaker share?', 'Application instructions', 'Retail locations', 'Names of instructors', 'User reviews', 'A', 'Đáp án đúng là A.
