INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5078, 4089, 78, 'What does the speaker request that the listeners do?', 'Take safety precautions', 'Sign a registration sheet', 'Wear name tags', 'Move their vehicles', 'A', 'Đáp án đúng là A.
