INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4090, 179, '2024/test6/audio/test6_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5079, 4090, 79, 'What will take place in the evening?', 'A debate', 'An award ceremony', 'A film screening', 'A reception', 'D', 'Đáp án đúng là D.
