INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4150, 181, NULL, NULL, 'To: Thao Pham <thaopham@amail.com>
From: Leena Montoya <imontoya@academemedia.com>
