INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5150, 4161, 150, 'What will happen at the time selected by Ms. Duberville?', 'She will pick up some equipment at an office.', 'She will receive a new Global Tech mobile phone.', 'She will be visited by a Global Tech representative.', 'She will be e-mailed a customer satisfaction survey.', 'C', 'Đáp án: C.nĐại diện của Global Tech sẽ đến thăm bà Duberville vào thời gian bà đã chọn.
