INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5157, 4168, 157, 'How can a prospective resident learn more about Homestead at Eston?', 'By viewing a model home online.', 'By requesting a brochure.', 'By visiting the community.', 'By calling a current homeowner.', 'C', 'Đáp án: C.
