INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5163, 4174, 163, 'What is mentioned about the training workshop?', 'It is offered three times a year.', 'It is led by an experienced election official.', 'It is required for all election workers.', 'It is available both online and in person.', 'C', 'Đáp án: C.
