INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4225, 184, '2024/test7/audio/test7_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5214, 4225, 14, 'When will we mention our budgetary needs to the outreach coordinator?', 'I can''t quite reach the top shelf.', 'We''re fully funded through the end of the year.', 'Because our accountant is on vacation.', NULL, 'B', 'Đáp án B gián tiếp trả lời câu hỏi bằng cách cho biết không cần thảo luận về nhu cầu ngân sách.
Dịch câu hỏi: Khi nào chúng ta sẽ đề cập đến nhu cầu ngân sách với điều phối viên tiếp cận?
Dịch đáp án:
A. Tôi không thể với tới kệ trên cùng.
B. Chúng ta đã có đủ ngân sách đến cuối năm.
C. Bởi vì kế toán của chúng ta đang đi nghỉ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4226, 184, '2024/test7/audio/test7_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5215, 4226, 15, 'My appointment is with Dr. Hamdi today, right?', 'Usually an annual check-up', 'No, parking is not free', 'Yes, and she''ll see you in a minute', NULL, 'C', 'Đáp án C trực tiếp xác nhận cuộc hẹn và cung cấp thông tin thêm.
Dịch câu hỏi: Cuộc hẹn của tôi là với Bác sĩ Hamdi hôm nay, đúng không?
Dịch đáp án:
A. Thường là kiểm tra sức khỏe hàng năm
B. Không, bãi đỗ xe không miễn phí
C. Đúng vậy, và cô ấy sẽ gặp bạn trong một phút nữa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4227, 184, '2024/test7/audio/test7_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5216, 4227, 16, 'Where should I store this shipment of paper?', 'The store closes at 4.', 'By express delivery.', 'Well, the supply room is full.', NULL, 'C', 'Đáp án C gián tiếp trả lời câu hỏi bằng cách chỉ ra rằng nơi thường dùng để lưu trữ đã đầy.
Dịch câu hỏi: Tôi nên lưu trữ lô hàng giấy này ở đâu?
Dịch đáp án:
A. Cửa hàng đóng cửa lúc 4 giờ.
B. Bằng chuyển phát nhanh.
C. À, phòng vật tư đã đầy rồi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4228, 184, '2024/test7/audio/test7_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5217, 4228, 17, 'Would you be able to reschedule my haircut for Monday?', 'No, we''re fully booked that day.', 'I''ll open a window to let in some fresh air.', 'The grass needs cutting.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về việc đổi lịch cắt tóc.
Dịch câu hỏi: Bạn có thể sắp xếp lại lịch cắt tóc của tôi vào thứ Hai được không?
Dịch đáp án:
A. Không, chúng tôi đã kín lịch ngày đó rồi.
B. Tôi sẽ mở cửa sổ để lấy không khí trong lành.
C. Cỏ cần được cắt.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4229, 184, '2024/test7/audio/test7_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5218, 4229, 18, 'Should I take the train or the bus to the airport?', 'The bus stop is five kilometers away.', 'There are enough for all of us.', 'No, I went to a training session.', NULL, 'A', 'Đáp án A cung cấp thông tin về vị trí bến xe buýt, gián tiếp gợi ý rằng tàu hỏa có thể là lựa chọn tốt hơn.
Dịch câu hỏi: Tôi nên đi tàu hay xe buýt đến sân bay?
Dịch đáp án:
A. Bến xe buýt cách đây năm kilômét.
B. Có đủ cho tất cả chúng ta.
C. Không, tôi đã đi dự một buổi đào tạo.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4230, 184, '2024/test7/audio/test7_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5219, 4230, 19, 'How long will the online course take?', 'You can finish it in a few hours.', 'Forty dollars a month.', 'I''ll take the blue jacket.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về thời gian hoàn thành khóa học trực tuyến.
Dịch câu hỏi: Khóa học trực tuyến sẽ mất bao lâu?
Dịch đáp án:
A. Bạn có thể hoàn thành nó trong vài giờ.
B. Bốn mươi đô la một tháng.
C. Tôi sẽ lấy áo khoác màu xanh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4231, 184, '2024/test7/audio/test7_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5220, 4231, 20, 'Will this month''s company gathering be held in Benson Park?', 'I usually park by the fountain.', 'It''s still cold outside most days.', 'Those should be printed in color.', NULL, 'B', 'Đáp án B gián tiếp gợi ý rằng buổi gặp mặt có thể không được tổ chức ở công viên do thời tiết lạnh.
Dịch câu hỏi: Buổi gặp mặt công ty tháng này sẽ được tổ chức ở Công viên Benson phải không?
Dịch đáp án:
A. Tôi thường đỗ xe gần đài phun nước.
B. Hầu hết các ngày vẫn còn lạnh bên ngoài.
C. Những cái đó nên được in màu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4232, 184, '2024/test7/audio/test7_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5221, 4232, 21, 'When will the tickets for the performance be ready to pick up?', 'We should get them by the end of the week', 'A famous director', '25 euros', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về thời gian nhận vé.
Dịch câu hỏi: Khi nào vé cho buổi biểu diễn sẽ sẵn sàng để nhận?
Dịch đáp án:
A. Chúng ta nên nhận được chúng vào cuối tuần
B. Một đạo diễn nổi tiếng
C. 25 euro');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4233, 184, '2024/test7/audio/test7_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5222, 4233, 22, 'I don''t know if the packaging materials were ordered already.', 'I saw some boxes on the loading dock.', 'She''s wearing a red hat.', 'A lunch appointment at 12.30.', NULL, 'A', 'Đáp án A gián tiếp gợi ý rằng vật liệu đóng gói có thể đã được đặt hàng.
Dịch câu hỏi: Tôi không biết liệu vật liệu đóng gói đã được đặt hàng chưa.
Dịch đáp án:
A. Tôi thấy một số hộp ở bến bốc dỡ hàng.
B. Cô ấy đang đội một chiếc mũ đỏ.
C. Một cuộc hẹn ăn trưa lúc 12:30.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4234, 184, '2024/test7/audio/test7_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5223, 4234, 23, 'Could you please send me the sales report?', '50% off last season''s merchandise.', 'Of course, I''ll do it now.', 'Did you check the weather report?', NULL, 'B', 'Đáp án B trực tiếp đáp ứng yêu cầu gửi báo cáo bán hàng.
Dịch câu hỏi: Bạn có thể gửi cho tôi báo cáo bán hàng được không?
Dịch đáp án:
A. Giảm giá 50% hàng hóa mùa trước.
B. Tất nhiên, tôi sẽ làm ngay bây giờ.
C. Bạn đã kiểm tra dự báo thời tiết chưa?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4235, 184, '2024/test7/audio/test7_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5224, 4235, 24, 'What type of view will your apartment have?', 'The kitchen lighting looks great.', 'I haven''t signed a lease yet.', 'We''re in complete agreement on that.', NULL, 'B', 'Đáp án B gián tiếp trả lời câu hỏi bằng cách chỉ ra rằng người nói chưa thuê căn hộ.
Dịch câu hỏi: Căn hộ của bạn sẽ có tầm nhìn như thế nào?
Dịch đáp án:
A. Ánh sáng nhà bếp trông rất tuyệt.
B. Tôi chưa ký hợp đồng thuê.
C. Chúng ta hoàn toàn đồng ý về điều đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4236, 184, '2024/test7/audio/test7_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5225, 4236, 25, 'How much oil does your heater use in the winter?', 'We may need to stop for gas on our trip.', 'That recipe calls for butter.', 'We only use electric appliances.', NULL, 'C', 'Đáp án C gián tiếp trả lời câu hỏi bằng cách chỉ ra rằng họ không sử dụng lò sưởi dầu.
Dịch câu hỏi: Lò sưởi của bạn sử dụng bao nhiêu dầu vào mùa đông?
Dịch đáp án:
A. Chúng ta có thể cần dừng lại để đổ xăng trong chuyến đi.
B. Công thức đó cần dùng bơ.
C. Chúng tôi chỉ sử dụng các thiết bị điện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4237, 184, '2024/test7/audio/test7_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5226, 4237, 26, 'Where can I find the vitamins?', 'In aisle 6.', 'That''s a really healthy recipe.', 'The library is closed on Sundays.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về vị trí của vitamin.
Dịch câu hỏi: Tôi có thể tìm vitamin ở đâu?
Dịch đáp án:
A. Ở lối đi số 6.
B. Đó là một công thức rất lành mạnh.
C. Thư viện đóng cửa vào Chủ nhật.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4238, 184, '2024/test7/audio/test7_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5227, 4238, 27, 'Thank you for helping me create a survey.', 'The software did most of the work.', 'Our loyal customers.', 'The crates are still in the warehouse.', NULL, 'A', 'Đáp án A là phản hồi khiêm tốn và phù hợp nhất cho lời cảm ơn.
Dịch câu hỏi: Cảm ơn bạn đã giúp tôi tạo một cuộc khảo sát.
Dịch đáp án:
A. Phần mềm đã làm phần lớn công việc.
B. Những khách hàng trung thành của chúng ta.
C. Những thùng hàng vẫn còn trong kho.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4239, 184, '2024/test7/audio/test7_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5228, 4239, 28, 'When will you be done testing the new mobile app?', 'No, just an older laptop model.', 'I''m almost finished.', 'It''s about a two-hour drive from here.', NULL, 'B', 'Đáp án B trực tiếp trả lời câu hỏi về thời gian hoàn thành việc kiểm tra ứng dụng.
Dịch câu hỏi: Khi nào bạn sẽ hoàn thành việc kiểm tra ứng dụng di động mới?
Dịch đáp án:
A. Không, chỉ là một mẫu laptop cũ hơn.
B. Tôi gần xong rồi.
C. Nó cách đây khoảng hai giờ lái xe.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4240, 184, '2024/test7/audio/test7_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5229, 4240, 29, 'Don''t forget to turn off the projector after your presentation.', 'I don''t have a summary.', 'Should I return it to the supply closet?', 'Please distribute these handouts.', NULL, 'B', 'Đáp án B là phản hồi phù hợp nhất, hỏi về việc cất máy chiếu sau khi tắt.
Dịch câu hỏi: Đừng quên tắt máy chiếu sau bài thuyết trình của bạn.
Dịch đáp án:
A. Tôi không có bản tóm tắt.
B. Tôi có nên trả nó về tủ đựng đồ không?
C. Vui lòng phát những tài liệu này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4241, 184, '2024/test7/audio/test7_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5230, 4241, 30, 'Didn''t there used to be a parking garage on this street?', 'Yes, but it''s been torn down.', 'You can hang your keys on this hook.', 'My car has a flat tire.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về sự tồn tại trước đây của bãi đỗ xe.
Dịch câu hỏi: Trước đây không có một bãi đỗ xe trên con đường này sao?
Dịch đáp án:
A. Có, nhưng nó đã bị phá hủy rồi.
B. Bạn có thể treo chìa khóa của bạn lên móc này.
C. Xe của tôi bị xẹp lốp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4242, 184, '2024/test7/audio/test7_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5231, 4242, 31, 'Will you be available to work on Thursday or Friday?', 'There''s mandatory training on Friday', 'Yes, it was a good show', 'A daily schedule', NULL, 'A', 'Đáp án A gián tiếp trả lời câu hỏi bằng cách chỉ ra rằng thứ Sáu không khả dụng do có đào tạo bắt buộc.
Dịch câu hỏi: Bạn có rảnh để làm việc vào thứ Năm hoặc thứ Sáu không?
Dịch đáp án:
A. Có đào tạo bắt buộc vào thứ Sáu
B. Vâng, đó là một buổi biểu diễn hay
C. Một lịch trình hàng ngày');;

