INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5237, 4248, 37, 'What does the man say he will do?', 'Look up some information', 'Print a document', 'Check on a machine', 'Update an account', 'C', 'Đáp án đúng là C.
