INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5239, 4250, 39, 'Why was a change made at the last minute?', 'An area is too noisy.', 'Some participants are delayed.', 'A room was already taken.', 'Some revisions were requested.', 'C', 'Đáp án đúng là C.
