INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4361, 190, '2024/test8/audio/test8_question_1.mp3', '2024/test8/image/test8-image-1.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5401, 4361, 1, NULL, 'She''s taking off her badge.', 'She''s leaning over a desk.', 'She''s locking a door.', 'She''s lifting a bin.', 'D', 'Dịch các đáp án:
A. Cô ấy đang tháo thẻ nhân viên.
B. Cô ấy đang cúi người qua bàn.
C. Cô ấy đang khóa cửa.
D. Cô ấy đang nâng một thùng rác.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4362, 190, '2024/test8/audio/test8_question_2.mp3', '2024/test8/image/test8-image-2.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5402, 4362, 2, NULL, 'A man is repairing a railing.', 'A man is climbing some stairs.', 'A man is carrying a ladder.', 'A man is looking up at a roof.', 'B', 'Dịch các đáp án:
