INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4364, 190, '2024/test8/audio/test8_question_4.mp3', '2024/test8/image/test8-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5404, 4364, 4, NULL, 'One of the workers is opening a display case.', 'One of the workers is tying a necktie.', 'The workers are behind a counter.', 'The workers are greeting some customers.', 'C', 'Dịch các đáp án:
A. Một trong những nhân viên đang mở tủ trưng bày.
B. Một trong những nhân viên đang thắt cà vạt.
