INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4365, 190, '2024/test8/audio/test8_question_5.mp3', '2024/test8/image/test8-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5405, 4365, 5, NULL, 'Some rocks are piled in a wheelbarrow', 'Some telephone wires are suspended over a road', 'Some benches are occupied', 'Some trees are shading a picnic table', 'B', 'Dịch các đáp án:
A. Một số đá được chất đống trong xe cút kít.
B. Một số dây điện thoại được treo qua đường.
