INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4366, 190, '2024/test8/audio/test8_question_6.mp3', '2024/test8/image/test8-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5406, 4366, 6, NULL, 'Some papers have been pinned to a bulletin board.', 'A clock has been set on a bedside table.', 'A painting has been propped against a chair.', 'Some medical equipment has been placed on a shelf.', 'A', 'Dịch các đáp án:
A. Một số giấy tờ đã được ghim lên bảng thông báo.
B. Một đồng hồ đã được đặt trên bàn cạnh giường.
C. Một bức tranh được dựa vào ghế.
D. Một số thiết bị y tế đã được đặt trên kệ.');;

