INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4370, 191, '2024/test8/audio/test8_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5410, 4370, 10, 'What do you think I should take to the conference?', 'In the lobby', 'Just your laptop', 'A three o''clock shift', NULL, 'B', 'Đáp án B đưa ra gợi ý về việc mang theo gì đến hội nghị.
Dịch câu hỏi: Bạn nghĩ tôi nên mang gì đến hội nghị?
