INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5411, 4371, 11, 'Where''s the festival being held?', 'A music concert', 'Probably sometime in December', 'In the town centre', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về địa điểm tổ chức lễ hội.
