INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5423, 4383, 23, 'Let''s talk about your project after lunch.', 'Because her microphone is broken.', 'I''m leaving work early today.', 'I have two pairs of shoes.', NULL, 'B', 'Đáp án B gián tiếp từ chối đề xuất nói chuyện sau bữa trưa.
Dịch câu hỏi: Hãy nói về dự án của bạn sau bữa trưa.
Dịch đáp án:
