INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5425, 4385, 25, 'Would it be cheaper to ship by express mail or overnight delivery?', 'Express mail is less expensive', 'I''d like a large', 'It''s in the next shipment', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về phương thức vận chuyển rẻ hơn.
Dịch câu hỏi: Gửi bằng thư nhanh hay giao hàng qua đêm sẽ rẻ hơn?
Dịch đáp án:
A. Thư nhanh ít tốn kém hơn
B. Tôi muốn một cái lớn
C. Nó ở trong lô hàng tiếp theo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4386, 191, '2024/test8/audio/test8_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5426, 4386, 26, 'How do I turn on the air conditioner in this office?', 'The temperature is controlled automatically.', 'Turn left after the post office.', 'No, I shut off all the lights.', NULL, 'A', 'Đáp án A giải thích rằng không cần bật điều hòa vì nhiệt độ được kiểm soát tự động.
Dịch câu hỏi: Làm thế nào để tôi bật điều hòa trong văn phòng này?
Dịch đáp án:
A. Nhiệt độ được kiểm soát tự động.
B. Rẽ trái sau bưu điện.
C. Không, tôi đã tắt tất cả đèn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4387, 191, '2024/test8/audio/test8_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5427, 4387, 27, 'Have you trained Hikaru to use the new microscope?', 'I have my own car.', 'That''s enough, thanks.', 'I misplaced the instruction manual.', NULL, 'C', 'Đáp án C gián tiếp trả lời câu hỏi bằng cách chỉ ra lý do chưa đào tạo Hikaru.
Dịch câu hỏi: Bạn đã đào tạo Hikaru sử dụng kính hiển vi mới chưa?
Dịch đáp án:
A. Tôi có xe riêng.
B. Đủ rồi, cảm ơn.
C. Tôi đã làm mất sách hướng dẫn sử dụng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4388, 191, '2024/test8/audio/test8_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5428, 4388, 28, 'We''re meeting this week to discuss the upcoming merger.', 'I have it on my calendar.', 'Please merge onto the highway.', 'A law firm in Glenview.', NULL, 'A', 'Đáp án A xác nhận việc đã lên lịch cuộc họp.
