INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5601, 4510, 1, NULL, 'He''s standing on a rug.', 'He''s turning a doorknob.', 'He''s climbing a ladder.', 'He''s painting a wall.', 'C', 'Dịch các đáp án:
