INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4511, 197, '2024/test9/audio/test9_question_2.mp3', '2024/test9/image/test9-image-2.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5602, 4511, 2, NULL, 'Some shirts have been hung on a clothing rack.', 'A light fixture is attached to a column.', 'Some boxes of clothing have been set on the floor.', 'Some merchandise is on display in a store.', 'D', 'Dịch các đáp án:
