INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4512, 197, '2024/test9/audio/test9_question_3.mp3', '2024/test9/image/test9-image-3.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5603, 4512, 3, NULL, 'The woman is putting some papers into a file folder', 'The woman is typing on a keyboard', 'The woman is seated in front of a computer', 'The woman is holding a cup', 'C', 'Dịch các đáp án:
