INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4513, 197, '2024/test9/audio/test9_question_4.mp3', '2024/test9/image/test9-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5604, 4513, 4, NULL, 'Some employees are washing some windows', 'A shopper is carrying a package', 'Some shopping carts have been lined up in a row', 'Some products have fallen on the ground', 'B', 'Dịch các đáp án:
A. Một số nhân viên đang rửa cửa sổ.
B. Một người mua sắm đang mang một gói hàng.
