INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4514, 197, '2024/test9/audio/test9_question_5.mp3', '2024/test9/image/test9-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5605, 4514, 5, NULL, 'Snow is being cleared away.', 'Bricks are being arranged on a walkway.', 'Tree branches are being trimmed.', 'A shovel is leaning against a flower pot.', 'A', 'Dịch các đáp án:
