INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5608, 4517, 8, 'Where is the fashion seminar?', 'It''s in room 235.', 'No, the black one.', 'Just some blouses.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về địa điểm của buổi hội thảo thời trang.
