INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5609, 4518, 9, 'Why do we have to put on safety goggles?', 'No, the door on your left.', 'Because of safety regulations.', 'A hat and a scarf.', NULL, 'B', 'Đáp án B trực tiếp giải thích lý do phải đeo kính bảo hộ.
