INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4519, 198, '2024/test9/audio/test9_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5610, 4519, 10, 'What did you do for Mr. Sugiyama''s retirement party?', 'I helped decorate the room.', 'He''s not tired.', 'Try the file cabinet.', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về việc đã làm cho bữa tiệc nghỉ hưu.
Dịch câu hỏi: Bạn đã làm gì cho bữa tiệc nghỉ hưu của ông Sugiyama?
Dịch đáp án:
A. Tôi đã giúp trang trí phòng.
B. Ông ấy không mệt.
C. Hãy thử tủ hồ sơ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4520, 198, '2024/test9/audio/test9_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5611, 4520, 11, 'Can I take another bottle of water?', 'If there are any left', 'An old refrigerator', 'No, the clock is fast', NULL, 'A', 'Đáp án A trực tiếp trả lời câu hỏi về việc lấy thêm nước.
