INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5612, 4521, 12, 'Isn''t this the last train out?', 'A round-trip ticket to New York.', 'The office next door.', 'No, there''s one more.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về chuyến tàu cuối cùng.
