INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5811, 4668, 11, 'The project proposal still needs work.', 'The other office.', 'No, it''s still not working.', 'I can help you with it.', NULL, 'C', 'Đáp án C là phản hồi phù hợp nhất cho nhận xét về đề xuất dự án.
