INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5812, 4669, 12, 'Where do you plan to stay during your visit to the city?', 'I thought the building had 12 floors.', 'Oh, just to present at a conference.', 'At a friend''s house.', NULL, 'C', 'Đáp án C trực tiếp trả lời câu hỏi về nơi ở trong chuyến thăm.
