INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4730, 207, '2024/test10/audio/test10_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5873, 4730, 73, 'What does the speaker say he will do?', 'Sign a contract', 'Mail an invoice', 'Edit a document', 'Change a schedule', 'C', 'Đáp án đúng là C (Edit a document) vì người nói nói "I''ll make the necessary revisions to it" khi đề cập đến danh sách kiểm tra.
Dịch câu hỏi: Người nói nói anh ấy sẽ làm gì?
