INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (5922, 4779, 122, 'Ms. Miller ------ welcomed the speakers who will be leading the workshops.', 'accessibly', 'abundantly', 'briefly', 'momentarily', 'C', 'Đáp án đúng là C. briefly (ngắn gọn). Giải thích: "Briefly" là trạng từ phù hợp nhất trong ngữ cảnh này.
