INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6001, 4808, 1, 'Look at the picture marked number one in your test book.', 'He''s looking at a mobile phone.', 'He''s boarding a train.', 'He''s putting on his glasses.', 'He''s placing his bag under a seat.', 'A', 'A Anh ấy đang nhìn vào một chiếc điện thoại di động.
