INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6002, 4809, 2, 'Look at the picture marked number two in your test book.', 'She''s kneeling to check an oven.', 'She''s washing some baking pans.', 'She''s cutting a piece of bread.', 'She''s sliding a tray into a rack.', 'D', 'A Cô ấy đang quỳ để kiểm tra lò nướng.
B Cô ấy đang rửa một số khay nướng.
C Cô ấy đang cắt một miếng bánh mì.
