INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4810, 211, '2025/test1/audio/test1-audio-3.mp3', '2025/test1/image/test1-image-3.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6003, 4810, 3, 'Look at the picture marked number three in your test book.', 'Bricks are piled in the back of a truck.', 'A man is emptying a wheelbarrow.', 'Poles are being taken out of the ground.', 'A man is holding a power tool.', 'B', 'A Gạch được chất đống ở phía sau xe tải.
B Một người đàn ông đang làm trống một chiếc xe cút kít.
C Các cột đang được nhổ ra khỏi mặt đất.
D Một người đàn ông đang cầm một công cụ điện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4811, 211, '2025/test1/audio/test1-audio-4.mp3', '2025/test1/image/test1-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6004, 4811, 4, 'Look at the picture marked number four in your test book.', 'The woman is hanging up an apron.', 'The man is pushing a shopping cart.', 'The man is entering a grocery store.', 'The woman is helping a customer.', 'D', 'A Người phụ nữ đang treo một chiếc tạp dề.
B Người đàn ông đang đẩy một chiếc xe đẩy mua sắm.
C Người đàn ông đang bước vào cửa hàng tạp hóa.
D Người phụ nữ đang giúp đỡ một khách hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4812, 211, '2025/test1/audio/test1-audio-5.mp3', '2025/test1/image/test1-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6005, 4812, 5, 'Look at the picture marked number five in your test book.', 'A woman is strolling along the pier.', 'Tourists are posing for a photograph.', 'Some boats are docked in a harbor.', 'Some awnings extend over a canal.', 'C', 'A Một người phụ nữ đang dạo bước dọc theo bến tàu.
B Khách du lịch đang tạo dáng để chụp ảnh.
C Một số thuyền đang neo đậu trong bến cảng.
D Một số mái hiên trải dài qua một con kênh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4813, 211, '2025/test1/audio/test1-audio-6.mp3', '2025/test1/image/test1-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6006, 4813, 6, 'Look at the picture marked number six in your test book.', 'A fan is hanging from the ceiling.', 'Two chairs are positioned side by side.', 'A table has been moved next to a window.', 'A rug has been unrolled on the floor.', 'D', 'A Một chiếc quạt đang treo trên trần nhà.
B Hai chiếc ghế được đặt cạnh nhau.
C Một chiếc bàn đã được di chuyển cạnh cửa sổ.
D Một tấm thảm đã được trải trên sàn nhà.');;

-- Data for 2025 Test1 Part 2
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4814, 212, '2025/test1/audio/test1-audio-7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6007, 4814, 7, 'Where are the recycling bins located?', 'In the hallway', 'Every weekday', 'Just paper and glass', NULL, 'A', 'Câu hỏi: "Thùng rác tái chế được đặt ở đâu?"
A: "Ở hành lang"
B: "Mỗi ngày trong tuần"
C: "Chỉ giấy và thủy tinh"
Giải thích: Đáp án A đúng vì câu hỏi đang hỏi về vị trí, và chỉ có đáp án A đề cập đến địa điểm cụ thể. Đáp án B nói về thời gian, đáp án C nói về loại rác có thể tái chế, không liên quan đến câu hỏi về vị trí.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4815, 212, '2025/test1/audio/test1-audio-8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6008, 4815, 8, 'Why are you returning this sweater?', 'The returns and exchanges counter', 'It''s my sister''s birthday', 'Because there''s a stain on it', NULL, 'C', 'Câu hỏi: "Tại sao bạn trả lại chiếc áo len này?"
A: "Quầy đổi trả"
B: "Đó là sinh nhật chị gái tôi"
C: "Vì có vết bẩn trên áo"
Giải thích: Đáp án C đúng vì câu hỏi hỏi về lý do trả lại áo len. Chỉ có đáp án C đưa ra lý do hợp lý - có vết bẩn trên áo. Đáp án A nói về địa điểm và đáp án B đề cập đến một sự kiện không liên quan.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4816, 212, '2025/test1/audio/test1-audio-9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6009, 4816, 9, 'Do you want me to call a taxi for you?', 'I''m sure some of them do', 'That would be great, thanks', 'A more important phone call', NULL, 'B', 'Câu hỏi: "Bạn có muốn tôi gọi taxi cho bạn không?"
A: "Tôi chắc một số người làm thế"
B: "Tốt quá, cảm ơn"
C: "Một cuộc gọi quan trọng hơn"
Giải thích: Đáp án B đúng vì đây là câu trả lời phù hợp nhất cho một lời đề nghị giúp đỡ, thể hiện sự đồng ý và biết ơn. Các đáp án khác không phải là phản hồi hợp lý cho câu hỏi này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4817, 212, '2025/test1/audio/test1-audio-10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6010, 4817, 10, 'When will the Dubai trade show take place?', 'At a large hotel', 'In November', 'The marketing team', NULL, 'B', 'Câu hỏi: "Triển lãm thương mại Dubai sẽ diễn ra khi nào?"
A: "Tại một khách sạn lớn"
B: "Vào tháng 11"
C: "Đội marketing"
Giải thích: Đáp án B đúng vì câu hỏi hỏi về thời gian (when/khi nào), và chỉ có đáp án B đưa ra thông tin về thời gian (tháng 11). Đáp án A nói về địa điểm và đáp án C nói về người, không liên quan đến thời gian.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4818, 212, '2025/test1/audio/test1-audio-11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6011, 4818, 11, 'Who''s going to cover Emiko''s shift this weekend?', 'They''re hardcover books', 'A part-time worker volunteered', 'At the service desk', NULL, 'B', 'Câu hỏi: "Ai sẽ thay ca làm việc của Emiko cuối tuần này?"
A: "Đó là những cuốn sách bìa cứng"
B: "Một nhân viên bán thời gian đã tình nguyện"
C: "Tại quầy dịch vụ"
Giải thích: Đáp án B đúng vì câu hỏi hỏi về người sẽ thay ca, và đáp án B trả lời trực tiếp bằng cách cho biết một nhân viên bán thời gian đã tình nguyện. Các đáp án khác không liên quan đến việc thay ca.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4819, 212, '2025/test1/audio/test1-audio-12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6012, 4819, 12, 'Which kind of sandwich do you want?', 'I''d like ham-and-cheese, please', 'Yes, at lunchtime', 'The customer over there', NULL, 'A', 'Câu hỏi: "Bạn muốn loại bánh sandwich nào?"
A: "Tôi muốn sandwich thịt nguội và phô mai"
B: "Vâng, vào giờ ăn trưa"
C: "Khách hàng ở đằng kia"
Giải thích: Đáp án A đúng vì câu hỏi hỏi về loại sandwich và đáp án A trực tiếp nêu rõ loại sandwich mong muốn (ham-and-cheese). Các đáp án khác không trả lời về loại sandwich.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4820, 212, '2025/test1/audio/test1-audio-13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6013, 4820, 13, 'You don''t offer boat tours at this time of year, do you?', 'No, not during the winter', 'An experienced guide', 'What an incredible view!', NULL, 'A', 'Câu hỏi: "Các bạn không tổ chức tour thuyền vào thời điểm này trong năm, phải không?"
A: "Không, không có trong mùa đông"
B: "Một hướng dẫn viên có kinh nghiệm"
C: "Thật là một quang cảnh tuyệt vời!"
Giải thích: Đáp án A đúng vì câu hỏi là câu hỏi xác nhận về việc không có tour thuyền, và đáp án A trực tiếp xác nhận điều này, đồng thời giải thích lý do (vì đang là mùa đông).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4821, 212, '2025/test1/audio/test1-audio-14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6014, 4821, 14, 'Where''s the new warehouse?', 'I wear this outfit all the time', 'The low housing prices', 'A few miles outside of town', NULL, 'C', 'Câu hỏi: "Nhà kho mới ở đâu?"
A: "Tôi luôn mặc bộ đồ này"
B: "Giá nhà ở thấp"
C: "Cách thị trấn vài dặm"
Giải thích: Đáp án C đúng vì câu hỏi hỏi về vị trí và chỉ có đáp án C cung cấp thông tin về địa điểm cụ thể của nhà kho. Các đáp án khác không liên quan đến vị trí nhà kho.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4822, 212, '2025/test1/audio/test1-audio-15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6015, 4822, 15, 'Who got the promotion to vice president?', 'The card was very kind of you', 'For increasing sales last year', 'It should be announced today', NULL, 'C', 'Câu hỏi: "Ai được thăng chức lên phó chủ tịch?"
A: "Tấm thiệp của bạn thật tốt bụng"
B: "Vì tăng doanh số năm ngoái"
C: "Sẽ được thông báo hôm nay"
Giải thích: Đáp án C đúng vì nó cho biết thông tin về việc thăng chức sẽ được công bố trong ngày hôm nay. Mặc dù không trực tiếp nêu tên người được thăng chức, nhưng đây là câu trả lời hợp lý nhất trong tình huống này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4823, 212, '2025/test1/audio/test1-audio-16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6016, 4823, 16, 'There''s a fitness center in this hotel, right?', 'No, I help guests check in', 'Yes, it''s next to the swimming pool', 'He''s a certified trainer', NULL, 'B', 'Câu hỏi: "Khách sạn này có trung tâm thể dục, đúng không?"
A: "Không, tôi giúp khách làm thủ tục"
B: "Có, nó ở cạnh hồ bơi"
C: "Anh ấy là một huấn luyện viên được chứng nhận"
Giải thích: Đáp án B đúng vì câu hỏi yêu cầu xác nhận về sự tồn tại của trung tâm thể dục, và B không chỉ xác nhận điều này mà còn cung cấp thêm thông tin về vị trí của nó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4824, 212, '2025/test1/audio/test1-audio-17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6017, 4824, 17, 'How did you like the seminar?', 'She took it home', 'Some special software', 'I learned a lot', NULL, 'C', 'Câu hỏi: "Bạn thấy buổi hội thảo thế nào?"
A: "Cô ấy mang nó về nhà"
B: "Một số phần mềm đặc biệt"
C: "Tôi học được nhiều điều"
Giải thích: Đáp án C đúng vì câu hỏi hỏi về đánh giá cá nhân về buổi hội thảo, và C đưa ra phản hồi tích cực, cho thấy người nói đã có trải nghiệm học tập hữu ích.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4825, 212, '2025/test1/audio/test1-audio-18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6018, 4825, 18, 'Does your company let office staff wear headphones?', 'Oh, I work from home', 'The open floor plan', 'Did you listen to music or podcasts?', NULL, 'A', 'Câu hỏi: "Công ty của bạn có cho phép nhân viên văn phòng đeo tai nghe không?"
A: "Ồ, tôi làm việc tại nhà"
B: "Kế hoạch sàn mở"
C: "Bạn có nghe nhạc hay podcast không?"
Giải thích: Đáp án A đúng vì người trả lời cho biết họ làm việc tại nhà, ngầm giải thích rằng chính sách về tai nghe ở văn phòng không áp dụng cho họ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4826, 212, '2025/test1/audio/test1-audio-19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6019, 4826, 19, 'What''s the name of this dish?', 'Let me check the menu card', 'Robert Wilson, I believe', 'It comes with a piece of bread', NULL, 'A', 'Câu hỏi: "Món ăn này tên là gì?"
A: "Để tôi kiểm tra thực đơn"
B: "Tôi nghĩ là Robert Wilson"
C: "Nó đi kèm với một miếng bánh mì"
Giải thích: Đáp án A đúng vì khi được hỏi tên món ăn, người trả lời muốn kiểm tra thực đơn để đảm bảo cung cấp thông tin chính xác, đây là phản hồi hợp lý nhất trong tình huống này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4827, 212, '2025/test1/audio/test1-audio-20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6020, 4827, 20, 'This road leads to the highway, doesn''t it?', 'Yes, the pay is quite high.', 'I think we should have turned left earlier.', 'A reliable online map.', NULL, 'B', 'Câu hỏi: "Con đường này dẫn đến đường cao tốc, phải không?"
A: "Vâng, mức lương khá cao"
B: "Tôi nghĩ chúng ta nên rẽ trái sớm hơn"
C: "Một bản đồ trực tuyến đáng tin cậy"
Giải thích: Đáp án B đúng vì người trả lời gián tiếp cho biết họ đã đi sai đường, ngụ ý rằng con đường này không dẫn đến đường cao tốc và họ đáng lẽ phải rẽ trái sớm hơn để đến đường cao tốc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4828, 212, '2025/test1/audio/test1-audio-21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6021, 4828, 21, 'Could you show me how to use the packaging machine?', 'Sure, I''ll take it to the post office.', 'Have you finished reading the manual?', 'That show received poor reviews.', NULL, 'B', 'Câu hỏi: "Bạn có thể chỉ cho tôi cách sử dụng máy đóng gói không?"
A: "Được, tôi sẽ mang nó đến bưu điện"
B: "Bạn đã đọc xong hướng dẫn sử dụng chưa?"
C: "Chương trình đó nhận được đánh giá kém"
Giải thích: Đáp án B đúng vì người trả lời muốn kiểm tra xem người hỏi đã đọc hướng dẫn sử dụng chưa trước khi hướng dẫn trực tiếp, đây là phản ứng hợp lý trong tình huống này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4829, 212, '2025/test1/audio/test1-audio-22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6022, 4829, 22, 'Which notebook do you like better, the gray one or the brown one?', 'It''s several pages long.', 'The gray one is on sale.', 'I have to notify the attendees.', NULL, 'B', 'Câu hỏi: "Bạn thích quyển sổ nào hơn, quyển màu xám hay quyển màu nâu?"
A: "Nó dài vài trang"
B: "Quyển màu xám đang được giảm giá"
C: "Tôi phải thông báo cho những người tham dự"
Giải thích: Đáp án B đúng vì người trả lời đã gián tiếp chọn quyển màu xám bằng cách đề cập đến việc nó đang được giảm giá, ngụ ý đây là lựa chọn tốt hơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4830, 212, '2025/test1/audio/test1-audio-23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6023, 4830, 23, 'Would printing these handouts in color cost much more?', 'No, the training budget.', 'I enjoyed the presentation.', 'The price list is on the wall.', NULL, 'C', 'Câu hỏi: "In những tài liệu phát tay này bằng màu có tốn kém hơn nhiều không?"
A: "Không, ngân sách đào tạo"
B: "Tôi thích bài thuyết trình"
C: "Bảng giá được dán trên tường"
Giải thích: Đáp án C đúng vì người trả lời hướng dẫn người hỏi xem bảng giá trên tường để biết chi phí in màu, đây là cách trả lời thực tế và hữu ích nhất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4831, 212, '2025/test1/audio/test1-audio-24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6024, 4831, 24, 'The air conditioner in the waiting room isn''t working.', 'There''s a fan in the supply closet.', 'Here''re your patient records.', 'Right, he''s on his break.', NULL, 'A', 'Câu hỏi: "Máy điều hòa trong phòng chờ không hoạt động"
A: "Có một cái quạt trong tủ đồ"
B: "Đây là hồ sơ bệnh nhân của bạn"
C: "Đúng vậy, anh ấy đang nghỉ giải lao"
Giải thích: Đáp án A đúng vì khi được thông báo về máy điều hòa không hoạt động, người trả lời đề xuất giải pháp tạm thời bằng cách sử dụng quạt từ tủ đồ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4832, 212, '2025/test1/audio/test1-audio-25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6025, 4832, 25, 'These focus group results are promising.', 'The design options are in this file.', 'The feedback was very positive.', 'No, the inspector''s still here.', NULL, 'B', 'Câu hỏi: "Những kết quả từ nhóm tập trung này rất hứa hẹn"
A: "Các lựa chọn thiết kế nằm trong file này"
B: "Phản hồi rất tích cực"
C: "Không, thanh tra vẫn còn ở đây"
Giải thích: Đáp án B đúng vì người trả lời đồng ý và nhấn mạnh tính tích cực của kết quả, phù hợp với nhận xét ban đầu về kết quả hứa hẹn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4833, 212, '2025/test1/audio/test1-audio-26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6026, 4833, 26, 'Let''s get coffee before we go back to the office.', 'I have a deadline this afternoon.', 'No, I haven''t been there.', 'The machine in the breakroom.', NULL, 'A', 'Câu hỏi: "Hãy đi uống cà phê trước khi quay lại văn phòng"
A: "Tôi có deadline chiều nay"
B: "Không, tôi chưa từng đến đó"
C: "Máy ở phòng nghỉ giải lao"
Giải thích: Đáp án A đúng vì người trả lời từ chối lời mời đi cà phê bằng cách đưa ra lý do hợp lý là có deadline cần hoàn thành vào buổi chiều.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4834, 212, '2025/test1/audio/test1-audio-27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6027, 4834, 27, 'Where should I park when I arrive at the venue?', 'In a couple of minutes.', 'The catering van.', 'At the loading dock.', NULL, 'C', 'Câu hỏi: "Tôi nên đỗ xe ở đâu khi đến địa điểm?"
A: "Trong vài phút nữa"
B: "Xe cung cấp thức ăn"
C: "Ở khu vực bốc dỡ hàng"
Giải thích: Đáp án C đúng vì câu hỏi hỏi về vị trí đỗ xe và đáp án C cung cấp một địa điểm cụ thể (khu vực bốc dỡ hàng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4835, 212, '2025/test1/audio/test1-audio-28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6028, 4835, 28, 'When will you begin advertising the conference?', 'The newspaper runs job advertisements.', 'Yes, it was interesting.', 'We don''t have a keynote speaker yet.', NULL, 'C', 'Câu hỏi: "Khi nào bạn sẽ bắt đầu quảng cáo về hội nghị?"
A: "Báo đăng quảng cáo tuyển dụng"
B: "Vâng, nó rất thú vị"
C: "Chúng tôi vẫn chưa có diễn giả chính"
Giải thích: Đáp án C đúng vì người trả lời gián tiếp cho biết họ chưa thể bắt đầu quảng cáo vì còn thiếu một yếu tố quan trọng là diễn giả chính.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4836, 212, '2025/test1/audio/test1-audio-29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6029, 4836, 29, 'Does anyone have extra tickets for tonight''s charity concert?', 'I only have a one-way ticket.', 'Do you know your seat number?', 'The concert is tomorrow evening.', NULL, 'C', 'Câu hỏi: "Ai có vé thừa cho buổi hòa nhạc từ thiện tối nay không?"
A: "Tôi chỉ có vé một chiều"
B: "Bạn có biết số ghế của mình không?"
C: "Buổi hòa nhạc là vào tối mai"
Giải thích: Đáp án C đúng vì người trả lời đính chính thông tin về thời gian của buổi hòa nhạc, cho thấy người hỏi đã nhầm ngày.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4837, 212, '2025/test1/audio/test1-audio-30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6030, 4837, 30, 'How much training is required to become a nurse?', 'Are you thinking about changing careers?', 'She was hired last month.', 'An annual medical checkup.', NULL, 'A', 'Câu hỏi: "Cần đào tạo bao lâu để trở thành y tá?"
A: "Bạn đang nghĩ đến việc chuyển nghề phải không?"
B: "Cô ấy được tuyển tháng trước"
C: "Khám sức khỏe hàng năm"
Giải thích: Đáp án A đúng vì thay vì trả lời trực tiếp về thời gian đào tạo, người trả lời muốn xác nhận xem người hỏi có đang cân nhắc chuyển sang nghề y tá không, đây là cách phản hồi hợp lý để hiểu rõ hơn về mục đích của câu hỏi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4838, 212, '2025/test1/audio/test1-audio-31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6031, 4838, 31, 'Doesn''t the big conference room have a better projector?', 'Yes, this gear will protect her.', 'Some managers are meeting in there.', 'Eric is bringing more chairs.', NULL, 'B', 'Câu hỏi: "Phòng họp lớn không có máy chiếu tốt hơn sao?"
A: "Vâng, thiết bị này sẽ bảo vệ cô ấy"
B: "Một số quản lý đang họp trong đó"
C: "Eric đang mang thêm ghế"
Giải thích: Đáp án B đúng vì thay vì trả lời trực tiếp về máy chiếu, người trả lời cho biết phòng họp lớn đang được sử dụng cho cuộc họp của các quản lý, ngụ ý rằng họ không thể sử dụng phòng đó và máy chiếu của nó.');;

-- Data for 2025 Test1 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4839, 213, '2025/test1/audio/test1-audio-32-34.mp3', NULL, 'W-Am Sorry to bother you, Carl, but do you know where Rodney is? l was supposed to show him these sales figures for our new tablet computer as soon as they came in, but he''s not in his office.
M-Cn He''s at a doctor''s appointment, and he won''t be back today. But if you give that paper to me, I''ll pass it on to him tomorrow.
W-Am Thank you, I''d appreciate that. l''ll be conducting job interviews all day tomorrow.', 'W-Am Xin lỗi đã làm phiền anh, Carl, nhưng anh có biết Rodney đang ở đâu không? Tôi đáng lẽ phải cho anh ấy xem những số liệu bán hàng về máy tính bảng mới của chúng ta ngay khi có, nhưng anh ấy không có trong văn phòng.
M-Cn Anh ấy đang ở cuộc hẹn với bác sĩ, và hôm nay sẽ không quay lại. Nhưng nếu chị đưa giấy đó cho tôi, tôi sẽ chuyển cho anh ấy vào ngày mai.
W-Am Cảm ơn anh, tôi rất cảm kích điều đó. Tôi sẽ tiến hành phỏng vấn việc làm cả ngày mai.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6032, 4839, 32, 'Why did the woman go to Rodney''s office?', 'To repair a computer', 'To drop off a package', 'To negotiate a deadline', 'To present some data', 'D', 'Question: Why did the woman go to Rodney''s office? (Tại sao người phụ nữ đến văn phòng của Rodney?)
A: To repair a computer (Để sửa máy tính)
B: To drop off a package (Để gửi một gói hàng)
C: To negotiate a deadline (Để thương lượng thời hạn)
D: To present some data (Để trình bày một số dữ liệu)

Giải thích: Đáp án D là chính xác vì người phụ nữ nói rằng cô ấy phải cho Rodney xem số liệu bán hàng về máy tính bảng mới của họ ngay khi có (I was supposed to show him these sales figures for our new tablet computer as soon as they came in).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4840, 213, '2025/test1/audio/test1-audio-32-34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6033, 4840, 33, 'Why is Rodney unavailable?', 'He is out for lunch', 'He is seeing a doctor', 'He is at a trade show', 'He is leading a facility tour', 'B', 'Question: Why is Rodney unavailable? (Tại sao Rodney không có mặt?)
A: He is out for lunch (Anh ấy đang đi ăn trưa)
B: He is seeing a doctor (Anh ấy đang gặp bác sĩ)
C: He is at a trade show (Anh ấy đang ở hội chợ thương mại)
D: He is leading a facility tour (Anh ấy đang dẫn một tour tham quan cơ sở)

Giải thích: Đáp án B là chính xác vì Carl nói rằng Rodney đang ở cuộc hẹn với bác sĩ (He''s at a doctor''s appointment).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4841, 213, '2025/test1/audio/test1-audio-32-34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6034, 4841, 34, 'What will the woman most likely do tomorrow?', 'Hold some job interviews', 'Work from a different location', 'Install some electronics', 'Finalize a sales report', 'A', 'Question: What will the woman most likely do tomorrow? (Người phụ nữ nhiều khả năng sẽ làm gì vào ngày mai?)
A: Hold some job interviews (Tổ chức một số cuộc phỏng vấn việc làm)
B: Work from a different location (Làm việc từ một địa điểm khác)
C: Install some electronics (Lắp đặt một số thiết bị điện tử)
D: Finalize a sales report (Hoàn thiện một báo cáo bán hàng)

Giải thích: Đáp án A là chính xác vì người phụ nữ nói rằng cô ấy sẽ tiến hành phỏng vấn việc làm cả ngày mai (I''ll be conducting job interviews all day tomorrow).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4842, 213, '2025/test1/audio/test1-audio-35-37.mp3', NULL, 'W-Am Wilmoth Theater box office. How can I assist you today?
M-Au Hi, I have tickets for the August eighth performance of Two Villages, but I''d like to go on a later date. I understand that you allow free exchanges?
W-Am Actually, that policy only applies to theater members. Are you a member of our theater?
M-Au Oh... no, I''m not.
W-Am OK, then the exchanges will cost you eight dollars per ticket. However, if you buy a membership today, I could waive those charges.
M-Au Thanks, but I''ll just take the exchanges. I don''t live in the city, so it would be hard for me to come to your theater regularly.', 'W-Am Phòng vé Nhà hát Wilmoth. Tôi có thể giúp gì cho anh hôm nay?
M-Au Chào, tôi có vé cho buổi biểu diễn Two Villages ngày 8 tháng 8, nhưng tôi muốn đổi sang một ngày sau. Tôi hiểu rằng các chị cho phép đổi vé miễn phí?
W-Am Thực ra, chính sách đó chỉ áp dụng cho thành viên nhà hát. Anh có phải là thành viên của nhà hát chúng tôi không?
M-Au À... không, tôi không phải.
W-Am OK, vậy việc đổi vé sẽ tốn của anh 8 đô la mỗi vé. Tuy nhiên, nếu anh mua thẻ thành viên hôm nay, tôi có thể miễn những khoản phí đó.
M-Au Cảm ơn, nhưng tôi sẽ chỉ đổi vé thôi. Tôi không sống trong thành phố, nên sẽ khó cho tôi để thường xuyên đến nhà hát của các chị.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6035, 4842, 35, 'Why is the man calling?', 'To confirm a requirement', 'To exchange some tickets', 'To purchase a membership', 'To inquire about volunteering', 'B', 'Question: Why is the man calling? (Tại sao người đàn ông gọi điện?)
A: To confirm a requirement (Để xác nhận một yêu cầu)
B: To exchange some tickets (Để đổi một số vé)
C: To purchase a membership (Để mua thẻ thành viên)
D: To inquire about volunteering (Để hỏi về việc tình nguyện)

Giải thích: Đáp án B là chính xác vì người đàn ông gọi để đổi vé buổi biểu diễn của anh ấy sang một ngày khác (I have tickets for the August eighth performance of Two Villages, but I''d like to go on a later date).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4843, 213, '2025/test1/audio/test1-audio-35-37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6036, 4843, 36, 'What does the woman explain to the man?', 'A performance is sold out', 'A computer service is down', 'A neighborhood is usually busy', 'A policy does not apply to everyone', 'D', 'Question: What does the woman explain to the man? (Người phụ nữ giải thích điều gì cho người đàn ông?)
A: A performance is sold out (Một buổi biểu diễn đã hết vé)
B: A computer service is down (Một dịch vụ máy tính đang gặp sự cố)
C: A neighborhood is usually busy (Một khu vực thường rất đông đúc)
D: A policy does not apply to everyone (Một chính sách không áp dụng cho tất cả mọi người)

Giải thích: Đáp án D là chính xác vì người phụ nữ giải thích rằng chính sách đổi vé miễn phí chỉ áp dụng cho thành viên nhà hát (that policy only applies to theater members).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4844, 213, '2025/test1/audio/test1-audio-35-37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6037, 4844, 37, 'What does the man decide to do?', 'Pay some additional fees', 'Arrive early at a location', 'Have his name put on a list', 'Gather opinions from others', 'A', 'Question: What does the man decide to do? (Người đàn ông quyết định làm gì?)
A: Pay some additional fees (Trả thêm một số phí)
B: Arrive early at a location (Đến sớm tại một địa điểm)
C: Have his name put on a list (Đưa tên mình vào danh sách)
D: Gather opinions from others (Thu thập ý kiến từ người khác)

Giải thích: Đáp án A là chính xác vì người đàn ông quyết định chỉ đổi vé (I''ll just take the exchanges) và chấp nhận trả phí đổi vé 8 đô la mỗi vé thay vì mua thẻ thành viên.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4845, 213, '2025/test1/audio/test1-audio-38-40.mp3', NULL, 'M-Au Hi. I need a photograph of myself for a travel visa application. Does your studio do that kind of thing?
W-Br Absolutely. I can take that for you right away. Did the application instructions mention any special requirements for the photo?
M-Au Oh, yes, actually. It''s supposed to be a certain size... I forgot to bring that information, though.
w-Br Don''t worry. I can look it up online for you on this computer. What country are you trying to go to?', 'M-Au Xin chào. Tôi cần một tấm ảnh của mình cho đơn xin thị thực du lịch. Studio của chị có làm loại việc đó không?
W-Br Tất nhiên rồi. Tôi có thể chụp cho anh ngay. Hướng dẫn trong đơn có đề cập đến yêu cầu đặc biệt nào về ảnh không?
M-Au Ồ, có, thực ra. Nó phải có kích thước nhất định... Tuy nhiên, tôi quên mang thông tin đó theo.
W-Br Đừng lo. Tôi có thể tra cứu online cho anh trên máy tính này. Anh đang định đi đến nước nào?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6038, 4845, 38, 'What is the man trying to do?', 'Buy a guidebook', 'Store some luggage', 'Have his picture taken', 'Pick up an application', 'C', 'Question: What is the man trying to do? (Người đàn ông đang cố làm gì?)
A: Buy a guidebook (Mua sách hướng dẫn)
B: Store some luggage (Gửi hành lý)
C: Have his picture taken (Chụp ảnh)
D: Pick up an application (Lấy đơn đăng ký)

Giải thích: Đáp án C là chính xác vì người đàn ông nói rằng anh ấy cần một tấm ảnh của mình cho đơn xin thị thực du lịch (I need a photograph of myself for a travel visa application).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4846, 213, '2025/test1/audio/test1-audio-38-40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6039, 4846, 39, 'What did the man forget to bring?', 'A travel itinerary', 'A carrier bag', 'Some clothing', 'Some size information', 'D', 'Question: What did the man forget to bring? (Người đàn ông đã quên mang theo gì?)
A: A travel itinerary (Lịch trình du lịch)
B: A carrier bag (Túi xách)
C: Some clothing (Quần áo)
D: Some size information (Thông tin về kích thước)

Giải thích: Đáp án D là chính xác vì người đàn ông nói rằng ảnh phải có kích thước nhất định nhưng anh ấy đã quên mang thông tin đó theo (It''s supposed to be a certain size... I forgot to bring that information).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4847, 213, '2025/test1/audio/test1-audio-38-40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6040, 4847, 40, 'What does the woman offer to do?', 'Search the Internet', 'Wait for the man to return', 'Consult with a manager', 'Lend an item', 'A', 'Question: What does the woman offer to do? (Người phụ nữ đề nghị làm gì?)
A: Search the Internet (Tìm kiếm trên Internet)
B: Wait for the man to return (Đợi người đàn ông quay lại)
C: Consult with a manager (Tham khảo ý kiến quản lý)
D: Lend an item (Cho mượn một vật dụng)

Giải thích: Đáp án A là chính xác vì người phụ nữ nói rằng cô ấy có thể tra cứu thông tin kích thước ảnh online cho anh ấy trên máy tính (I can look it up online for you on this computer).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4848, 213, '2025/test1/audio/test1-audio-41-43.mp3', NULL, 'M-Au Tina, I just saw your announcement about the company moving offices-how exciting! It looks like the new space has more square footage, so well finally have room to expand our workforce.
W-Am Yes, and the transportation situation in that neighborhood is also better. Well have access to a bigger parking area.
M-Au That''s great. Umm... I''m concerned about the timing of the move, though. Couldn''t you postpone it by a few weeks? The end of this month will be a busy time for my team.
W-Am I mean, that was the president''s decision.
M-Au Oh, I see. Then I guess l''ll discuss the problem with the team and figure out how we can rearrange our work schedule.
W-Am Good idea. Let me know if I can help.', 'M-Au Tina, tôi vừa thấy thông báo của chị về việc công ty chuyển văn phòng - thật thú vị! Có vẻ như không gian mới có diện tích lớn hơn, vì vậy cuối cùng chúng ta sẽ có chỗ để mở rộng lực lượng lao động.
W-Am Vâng, và tình hình giao thông ở khu vực đó cũng tốt hơn. Chúng ta sẽ có quyền sử dụng bãi đỗ xe lớn hơn.
M-Au Tuyệt quá. Ừm... tuy nhiên tôi lo lắng về thời điểm chuyển văn phòng. Chị không thể hoãn lại vài tuần sao? Cuối tháng này sẽ là thời gian bận rộn cho nhóm của tôi.
W-Am Ý tôi là, đó là quyết định của chủ tịch.
M-Au Ồ, tôi hiểu rồi. Vậy tôi đoán tôi sẽ thảo luận vấn đề này với nhóm và tìm ra cách chúng tôi có thể sắp xếp lại lịch làm việc.
W-Am Ý kiến hay. Hãy cho tôi biết nếu tôi có thể giúp gì.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6041, 4848, 41, 'What is the conversation about?', 'An advertising campaign', 'A product design', 'A hiring committee', 'A business relocation', 'D', 'Question: What is the conversation about? (Cuộc trò chuyện nói về cái gì?)
A: An advertising campaign (Một chiến dịch quảng cáo)
B: A product design (Một thiết kế sản phẩm)
C: A hiring committee (Một ủy ban tuyển dụng)
D: A business relocation (Việc di dời doanh nghiệp)

Giải thích: Đáp án D là chính xác vì cuộc trò chuyện xoay quanh thông báo về việc công ty chuyển văn phòng (announcement about the company moving offices) và các vấn đề liên quan đến việc di dời này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4849, 213, '2025/test1/audio/test1-audio-41-43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6042, 4849, 42, 'What does the woman imply when she says, ''that was the president''s decision''?', 'It is not possible to change a plan', 'Some contract terms are acceptable', 'An executive has returned from a trip', 'An announcement gave incorrect information', 'A', 'Question: What does the woman imply when she says, ''that was the president''s decision''? (Người phụ nữ ngụ ý gì khi nói ''đó là quyết định của chủ tịch''?)
A: It is not possible to change a plan (Không thể thay đổi kế hoạch)
B: Some contract terms are acceptable (Một số điều khoản hợp đồng có thể chấp nhận được)
C: An executive has returned from a trip (Một giám đốc đã trở về từ chuyến đi)
D: An announcement gave incorrect information (Một thông báo đã đưa thông tin không chính xác)

Giải thích: Đáp án A là chính xác vì khi nói ''đó là quyết định của chủ tịch'', người phụ nữ ngụ ý rằng không thể thay đổi thời điểm chuyển văn phòng vì đây là quyết định từ cấp cao nhất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4850, 213, '2025/test1/audio/test1-audio-41-43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6043, 4850, 43, 'What does the man say he will do?', 'Visit a building site', 'Save some paperwork', 'Provide a price estimate', 'Speak with some employees', 'D', 'Question: What does the man say he will do? (Người đàn ông nói anh ấy sẽ làm gì?)
A: Visit a building site (Thăm một công trường)
B: Save some paperwork (Lưu một số giấy tờ)
C: Provide a price estimate (Cung cấp báo giá)
D: Speak with some employees (Nói chuyện với một số nhân viên)

Giải thích: Đáp án D là chính xác vì người đàn ông nói rằng anh ấy sẽ thảo luận vấn đề này với nhóm của mình (I''ll discuss the problem with the team) về việc sắp xếp lại lịch làm việc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4851, 213, '2025/test1/audio/test1-audio-44-46.mp3', NULL, 'W-Br Hi, Tim and Rafael. I heard that we''ve been unable to prepare the soil in the carrot field for planting. What''s going on?
M-Au The special fertilizer we ordered hasn''t arrived. Rafael just called the supplier, but they couldn''t help.
M-cn Right-their records show the shipment was completed, even though it wasn''t. It might take a while to figure out what went wrong.
w-Br Well, we need to get the carrots planted. Why don''t you take the truck over to pick up fertilizer from the local farm supply store?', 'W-Br Chào Tim và Rafael. Tôi nghe nói chúng ta không thể chuẩn bị đất ở cánh đồng cà rốt để trồng trọt. Chuyện gì đang xảy ra vậy?
M-Au Phân bón đặc biệt chúng ta đặt vẫn chưa đến. Rafael vừa gọi cho nhà cung cấp, nhưng họ không thể giúp được.
M-cn Đúng vậy - hồ sơ của họ cho thấy lô hàng đã được hoàn thành, mặc dù thực tế thì không. Có thể phải mất một thời gian để tìm ra điều gì đã sai.
W-Br À, chúng ta cần phải trồng cà rốt. Sao các anh không lái xe tải đến lấy phân bón từ cửa hàng vật tư nông nghiệp địa phương?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6044, 4851, 44, 'Where do the speakers most likely work?', 'At a supermarket', 'At a restaurant', 'At a vegetable farm', 'At a catering company', 'C', 'Question: Where do the speakers most likely work? (Những người nói chuyện nhiều khả năng làm việc ở đâu?)
A: At a supermarket (Tại một siêu thị)
B: At a restaurant (Tại một nhà hàng)
C: At a vegetable farm (Tại một trang trại rau)
D: At a catering company (Tại một công ty cung cấp thực phẩm)

Giải thích: Đáp án C là chính xác vì họ đang thảo luận về việc chuẩn bị đất để trồng cà rốt (prepare the soil in the carrot field for planting), cho thấy họ làm việc tại một trang trại rau.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4852, 213, '2025/test1/audio/test1-audio-44-46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6045, 4852, 45, 'According to the men, what is causing a problem?', 'An appliance is not working', 'An event was canceled', 'Some food has gone bad', 'A shipment has not arrived', 'D', 'Question: According to the men, what is causing a problem? (Theo những người đàn ông, điều gì đang gây ra vấn đề?)
A: An appliance is not working (Một thiết bị không hoạt động)
B: An event was canceled (Một sự kiện đã bị hủy)
C: Some food has gone bad (Một số thực phẩm đã hỏng)
D: A shipment has not arrived (Một lô hàng chưa đến)

Giải thích: Đáp án D là chính xác vì những người đàn ông nói rằng phân bón đặc biệt họ đặt vẫn chưa đến (The special fertilizer we ordered hasn''t arrived), mặc dù hồ sơ của nhà cung cấp cho thấy lô hàng đã được hoàn thành.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4853, 213, '2025/test1/audio/test1-audio-44-46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6046, 4853, 46, 'What does the woman suggest doing?', 'Revising a menu', 'Driving to a store', 'Putting up a sign', 'Postponing a task', 'B', 'Question: What does the woman suggest doing? (Người phụ nữ đề xuất làm gì?)
A: Revising a menu (Sửa đổi thực đơn)
B: Driving to a store (Lái xe đến cửa hàng)
C: Putting up a sign (Dựng một biển hiệu)
D: Postponing a task (Hoãn một nhiệm vụ)

Giải thích: Đáp án B là chính xác vì người phụ nữ đề xuất họ nên lái xe tải đến lấy phân bón từ cửa hàng vật tư nông nghiệp địa phương (Why don''t you take the truck over to pick up fertilizer from the local farm supply store?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4854, 213, '2025/test1/audio/test1-audio-47-49.mp3', NULL, 'M-Cn OK, ma am, we''ve figured out what''s wrong with your car. The fuel filter needs to be replaced. We can do that for you right away for two hundred dollars.
w-Br Oh, that''s a lot. I''ve done some basic repairs in the past. Could I buy the part from you, and handle the replacement myself?
M-Cn Hmm... with the way your car is designed, it wouldn''t be an easy job. There are a lot of steps. It would take us over an hour.
w-Br OK, then I guess you should do it. I''ll go out and get something to eat while I wait. Uh, I''ve never been to this area before...
M-Cn There''s a great diner over that way.', 'M-Cn OK, thưa bà, chúng tôi đã tìm ra vấn đề với xe của bà. Bộ lọc nhiên liệu cần được thay thế. Chúng tôi có thể làm điều đó ngay cho bà với giá hai trăm đô la.
W-Br Ồ, cái đó nhiều đấy. Tôi đã từng tự sửa một số thứ cơ bản trước đây. Tôi có thể mua linh kiện từ các anh và tự thay không?
M-Cn Hmm... với cách thiết kế xe của bà, nó sẽ không phải là một công việc dễ dàng. Có rất nhiều bước. Chúng tôi sẽ mất hơn một giờ.
W-Br OK, vậy tôi đoán các anh nên làm việc đó. Tôi sẽ đi ra ngoài và ăn một chút trong khi đợi. À, tôi chưa bao giờ đến khu vực này trước đây...
M-Cn Có một quán ăn ngon theo hướng đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6047, 4854, 47, 'Where does the conversation most likely take place?', 'At an outdoor market', 'At an auto repair shop', 'At a subway station', 'At a parking garage', 'B', 'Question: Where does the conversation most likely take place? (Cuộc trò chuyện nhiều khả năng diễn ra ở đâu?)
A: At an outdoor market (Tại một chợ ngoài trời)
B: At an auto repair shop (Tại một tiệm sửa xe)
C: At a subway station (Tại một ga tàu điện ngầm)
D: At a parking garage (Tại một bãi đỗ xe)

Giải thích: Đáp án B là chính xác vì cuộc trò chuyện diễn ra giữa thợ sửa xe và khách hàng về việc thay bộ lọc nhiên liệu của xe.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4855, 213, '2025/test1/audio/test1-audio-47-49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6048, 4855, 48, 'Why is the man unsure about the woman''s idea?', 'Bad weather is predicted', 'A destination is far away', 'A process is complicated', 'A warranty is strict', 'C', 'Question: Why is the man unsure about the woman''s idea? (Tại sao người đàn ông không chắc chắn về ý tưởng của người phụ nữ?)
A: Bad weather is predicted (Thời tiết xấu được dự báo)
B: A destination is far away (Điểm đến ở xa)
C: A process is complicated (Một quy trình phức tạp)
D: A warranty is strict (Bảo hành nghiêm ngặt)

Giải thích: Đáp án C là chính xác vì người đàn ông nói rằng với cách thiết kế xe của người phụ nữ, việc thay thế không dễ dàng và có nhiều bước (it wouldn''t be an easy job. There are a lot of steps).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4856, 213, '2025/test1/audio/test1-audio-47-49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6049, 4856, 49, 'Why does the woman say, ''I''ve never been to this area before''?', 'To express enthusiasm', 'To ask for a recommendation', 'To refuse an assignment', 'To explain a mistake', 'B', 'Question: Why does the woman say, ''I''ve never been to this area before''? (Tại sao người phụ nữ nói ''Tôi chưa bao giờ đến khu vực này trước đây''?)
A: To express enthusiasm (Để bày tỏ sự hào hứng)
B: To ask for a recommendation (Để xin một gợi ý)
C: To refuse an assignment (Để từ chối một nhiệm vụ)
D: To explain a mistake (Để giải thích một lỗi)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói điều này để ngầm xin gợi ý về nơi có thể ăn uống trong khi đợi, và người đàn ông đã gợi ý một quán ăn ngon gần đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4857, 213, '2025/test1/audio/test1-audio-50-52.mp3', NULL, 'W-Am Sung-ho, didn''t I see your name on the list of this year''s employee award winners?
M-n Yes, I won a prize for streamlining our customer support processes.
w-Am Ah, I heard about the improvements to our workflow in that area. So those were your ideas?
M-Cn Actually, I got most of them from a workshop I went to earlier this year.
w-Am Well, you still deserve credit for bringing them to the company. So, do you know what the prize will be?
M-Cn It''s three hundred dollars.
W-Am Wow! What are you going to do with it?
M-Cn I''m going to set it aside for now. I''d like to make a down payment on a house someday.', 'W-Am Sung-ho, tôi có thấy tên anh trong danh sách những người thắng giải thưởng nhân viên năm nay phải không?
M-n Vâng, tôi đã giành giải thưởng cho việc cải tiến quy trình hỗ trợ khách hàng của chúng ta.
W-Am À, tôi đã nghe về những cải tiến trong quy trình làm việc ở lĩnh vực đó. Vậy đó là những ý tưởng của anh?
M-Cn Thực ra, tôi lấy hầu hết chúng từ một hội thảo mà tôi đã tham dự đầu năm nay.
W-Am À, anh vẫn xứng đáng được ghi nhận vì đã mang chúng đến cho công ty. Vậy, anh có biết giải thưởng sẽ là gì không?
M-Cn Đó là ba trăm đô la.
W-Am Wow! Anh sẽ làm gì với số tiền đó?
M-Cn Tôi sẽ để dành nó lại. Tôi muốn có một khoản đặt cọc mua nhà trong tương lai.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6050, 4857, 50, 'What did the man win a prize for?', 'Improving the workflow for a service', 'Receiving high ratings from customers', 'Reaching a special work anniversary', 'Finding a use for some waste', 'A', 'Question: What did the man win a prize for? (Người đàn ông đã giành giải thưởng cho việc gì?)
A: Improving the workflow for a service (Cải thiện quy trình làm việc cho một dịch vụ)
B: Receiving high ratings from customers (Nhận đánh giá cao từ khách hàng)
C: Reaching a special work anniversary (Đạt được một cột mốc công việc đặc biệt)
D: Finding a use for some waste (Tìm ra cách sử dụng một số chất thải)

Giải thích: Đáp án A là chính xác vì người đàn ông nói rằng anh ấy đã giành giải thưởng cho việc cải tiến quy trình hỗ trợ khách hàng (I won a prize for streamlining our customer support processes).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4858, 213, '2025/test1/audio/test1-audio-50-52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6051, 4858, 51, 'What did the man do earlier in the year?', 'He read an advice book', 'He distributed a survey', 'He attended a workshop', 'He started a new hobby', 'C', 'Question: What did the man do earlier in the year? (Người đàn ông đã làm gì vào đầu năm nay?)
A: He read an advice book (Anh ấy đọc một cuốn sách tư vấn)
B: He distributed a survey (Anh ấy phát một bản khảo sát)
C: He attended a workshop (Anh ấy tham dự một hội thảo)
D: He started a new hobby (Anh ấy bắt đầu một sở thích mới)

Giải thích: Đáp án C là chính xác vì người đàn ông nói rằng anh ấy lấy hầu hết các ý tưởng từ một hội thảo mà anh ấy đã tham dự đầu năm nay (I got most of them from a workshop I went to earlier this year).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4859, 213, '2025/test1/audio/test1-audio-50-52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6052, 4859, 52, 'What does the man say he will do with the prize money?', 'Take a short vacation', 'Contribute to his savings', 'Treat coworkers to a meal', 'Make a donation to a charity', 'B', 'Question: What does the man say he will do with the prize money? (Người đàn ông nói anh ấy sẽ làm gì với tiền thưởng?)
A: Take a short vacation (Đi nghỉ ngắn ngày)
B: Contribute to his savings (Đóng góp vào tiền tiết kiệm của anh ấy)
C: Treat coworkers to a meal (Đãi đồng nghiệp một bữa ăn)
D: Make a donation to a charity (Quyên góp cho từ thiện)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng anh ấy sẽ để dành số tiền đó (I''m going to set it aside) vì muốn có một khoản đặt cọc mua nhà trong tương lai (I''d like to make a down payment on a house someday).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4860, 213, '2025/test1/audio/test1-audio-53-55.mp3', NULL, 'W-Br Mr. Ramsay, can we talk for a minute about the summer internships? The program has been going differently from what we''d hoped...
M-Cn Oh, really? I''ve been checking in with the interns regularly, and their feedback has been positive so far. They say the experience has been very educational.
w-Br Well, the main problem is that the project of managing the two of them is interfering with our team''s regular duties. We''ve been spending hours each day on it.
M-Cn I see. Then let''s include this issue on the agenda for tomorrow''s staff meeting so that we can brainstorm possible solutions together.
w-Br That would be great.', 'W-Br Ông Ramsay, chúng ta có thể nói chuyện một chút về chương trình thực tập mùa hè không? Chương trình đang diễn ra khác với những gì chúng ta mong đợi...
M-Cn Ồ, thật sao? Tôi đã thường xuyên kiểm tra với các thực tập sinh, và phản hồi của họ cho đến nay rất tích cực. Họ nói rằng trải nghiệm rất bổ ích.
W-Br À, vấn đề chính là việc quản lý hai người họ đang ảnh hưởng đến công việc thường ngày của đội chúng tôi. Chúng tôi đã phải dành nhiều giờ mỗi ngày cho việc đó.
M-Cn Tôi hiểu rồi. Vậy hãy đưa vấn đề này vào chương trình họp nhân viên ngày mai để chúng ta có thể cùng nhau động não tìm giải pháp.
W-Br Điều đó thật tuyệt.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6053, 4860, 53, 'What are the speakers discussing?', 'Office furniture', 'Budget allocations', 'An internship program', 'A departmental reorganization', 'C', 'Question: What are the speakers discussing? (Những người nói chuyện đang thảo luận về điều gì?)
A: Office furniture (Đồ nội thất văn phòng)
B: Budget allocations (Phân bổ ngân sách)
C: An internship program (Một chương trình thực tập)
D: A departmental reorganization (Việc tổ chức lại phòng ban)

Giải thích: Đáp án C là chính xác vì họ đang thảo luận về chương trình thực tập mùa hè (summer internships) và các vấn đề liên quan đến việc quản lý thực tập sinh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4861, 213, '2025/test1/audio/test1-audio-53-55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6054, 4861, 54, 'According to the woman, what is the main problem?', 'Her team is unhappy with a seating arrangement', 'Some applicants are not qualified for a position', 'A cost estimate was calculated incorrectly', 'A project has been very time-consuming', 'D', 'Question: According to the woman, what is the main problem? (Theo người phụ nữ, vấn đề chính là gì?)
A: Her team is unhappy with a seating arrangement (Đội của cô ấy không hài lòng với cách sắp xếp chỗ ngồi)
B: Some applicants are not qualified for a position (Một số ứng viên không đủ điều kiện cho vị trí)
C: A cost estimate was calculated incorrectly (Một ước tính chi phí đã được tính toán sai)
D: A project has been very time-consuming (Một dự án đã tiêu tốn rất nhiều thời gian)

Giải thích: Đáp án D là chính xác vì người phụ nữ nói rằng việc quản lý hai thực tập sinh đang chiếm nhiều thời gian của đội, họ phải dành nhiều giờ mỗi ngày cho việc đó (We''ve been spending hours each day on it).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4862, 213, '2025/test1/audio/test1-audio-53-55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6055, 4862, 55, 'What will the speakers most likely do?', 'Distribute a questionnaire', 'Spend some extra money', 'Add an item to a meeting agenda', 'Clear out an unused room', 'C', 'Question: What will the speakers most likely do? (Những người nói chuyện nhiều khả năng sẽ làm gì?)
A: Distribute a questionnaire (Phát một bản câu hỏi)
B: Spend some extra money (Chi thêm tiền)
C: Add an item to a meeting agenda (Thêm một mục vào chương trình họp)
D: Clear out an unused room (Dọn dẹp một phòng không sử dụng)

Giải thích: Đáp án C là chính xác vì người đàn ông đề xuất đưa vấn đề này vào chương trình họp nhân viên ngày mai (let''s include this issue on the agenda for tomorrow''s staff meeting).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4863, 213, '2025/test1/audio/test1-audio-56-58.mp3', NULL, 'W-Br Welcome, Mr. Alvarado. I''m Ellen Browder, the CEO of Browder Holdings. This is our director of business development, Kayoko Tokachi.
W-Am Hello, Mr. Alvarado. Thank you for coming in to talk about our proposal to acquire your game studio.
M-u It''s a very exciting possibility. Browder''s customer base is so large. I would love for our video games to reach a wider audience.
W-Br That''s what we want as well.
M-Au Wonderful. But... I am concerned about how becoming part of Browder might affect our game development process.
W-Am Tell us more about that.
M-Au Well, I know that companies like yours value efficiency. But for us, the more important goal is coming up with unique ideas for games. We spend a lot of time and effort on that.', 'W-Br Chào mừng, ông Alvarado. Tôi là Ellen Browder, CEO của Browder Holdings. Đây là giám đốc phát triển kinh doanh của chúng tôi, Kayoko Tokachi.
W-Am Xin chào, ông Alvarado. Cảm ơn ông đã đến để nói về đề xuất mua lại studio game của ông.
M-u Đó là một khả năng rất thú vị. Cơ sở khách hàng của Browder rất lớn. Tôi muốn các trò chơi video của chúng tôi tiếp cận được nhiều khán giả hơn.
W-Br Đó cũng là điều chúng tôi muốn.
M-Au Tuyệt vời. Nhưng... tôi lo lắng về việc trở thành một phần của Browder có thể ảnh hưởng đến quy trình phát triển game của chúng tôi như thế nào.
W-Am Hãy cho chúng tôi biết thêm về điều đó.
M-Au À, tôi biết rằng các công ty như của các bà coi trọng hiệu quả. Nhưng đối với chúng tôi, mục tiêu quan trọng hơn là đưa ra những ý tưởng độc đáo cho trò chơi. Chúng tôi dành rất nhiều thời gian và công sức cho điều đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6056, 4863, 56, 'Why is the man at Browder Holdings?', 'To hold a client consultation', 'To conduct research for an article', 'To tour an available property', 'To discuss a business deal', 'D', 'Question: Why is the man at Browder Holdings? (Tại sao người đàn ông đến Browder Holdings?)
A: To hold a client consultation (Để tổ chức tư vấn khách hàng)
B: To conduct research for an article (Để thực hiện nghiên cứu cho một bài báo)
C: To tour an available property (Để tham quan một bất động sản đang có sẵn)
D: To discuss a business deal (Để thảo luận một thương vụ)

Giải thích: Đáp án D là chính xác vì người đàn ông đến để thảo luận về đề xuất mua lại studio game của anh ấy (to talk about our proposal to acquire your game studio).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4864, 213, '2025/test1/audio/test1-audio-56-58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6057, 4864, 57, 'What does the man mention about Browder Holdings?', 'It has a large customer base', 'It was founded a long time ago', 'It is involved in the local community', 'It has an experienced management team', 'A', 'Question: What does the man mention about Browder Holdings? (Người đàn ông đề cập điều gì về Browder Holdings?)
A: It has a large customer base (Nó có cơ sở khách hàng lớn)
B: It was founded a long time ago (Nó được thành lập từ lâu)
C: It is involved in the local community (Nó tham gia vào cộng đồng địa phương)
D: It has an experienced management team (Nó có đội ngũ quản lý giàu kinh nghiệm)

Giải thích: Đáp án A là chính xác vì người đàn ông nói rằng cơ sở khách hàng của Browder rất lớn (Browder''s customer base is so large).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4865, 213, '2025/test1/audio/test1-audio-56-58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6058, 4865, 58, 'What does the man say his company puts effort into?', 'Designing efficient work spaces', 'Improving businesses'' public images', 'Producing creative ideas for products', 'Following industry regulations strictly', 'C', 'Question: What does the man say his company puts effort into? (Người đàn ông nói công ty của anh ấy dành công sức cho việc gì?)
A: Designing efficient work spaces (Thiết kế không gian làm việc hiệu quả)
B: Improving businesses'' public images (Cải thiện hình ảnh công khai của doanh nghiệp)
C: Producing creative ideas for products (Tạo ra ý tưởng sáng tạo cho sản phẩm)
D: Following industry regulations strictly (Tuân thủ nghiêm ngặt quy định ngành)

Giải thích: Đáp án C là chính xác vì người đàn ông nói rằng mục tiêu quan trọng của họ là đưa ra những ý tưởng độc đáo cho trò chơi và họ dành rất nhiều thời gian và công sức cho điều đó (the more important goal is coming up with unique ideas for games. We spend a lot of time and effort on that).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4866, 213, '2025/test1/audio/test1-audio-59-61.mp3', NULL, 'W-Am Greg-good news! The assembly line is about to finish making the mountain bikes for Kellum Sporting Goods. We''ll be able to ship the order out as scheduled after all.
M-Au Excellent. The next order to fulfill is another set of mountain bikes for a different dealer, right?
W-Am Yes, but... that one isn''t urgent, and the workers are tired from the overtime they''ve done for the Kellum order. What do you think about shutting down early and giving them the afternoon off?
M-Au Hmm... OK. I''ll make an announcement over the loudspeakers now. Thanks for the idea, Marisa.', 'W-Am Greg - tin tốt! Dây chuyền lắp ráp sắp hoàn thành việc làm xe đạp leo núi cho Kellum Sporting Goods. Chúng ta sẽ có thể gửi đơn hàng đúng lịch trình sau tất cả.
M-Au Tuyệt vời. Đơn hàng tiếp theo cần thực hiện là một bộ xe đạp leo núi khác cho một đại lý khác, phải không?
W-Am Vâng, nhưng... đơn hàng đó không khẩn cấp, và công nhân đã mệt mỏi vì làm thêm giờ cho đơn hàng của Kellum. Anh nghĩ sao về việc đóng cửa sớm và cho họ nghỉ buổi chiều?
M-Au Hmm... OK. Tôi sẽ thông báo qua loa ngay. Cảm ơn ý tưởng của chị, Marisa.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6059, 4866, 59, 'Which industry do the speakers most likely work in?', 'Manufacturing', 'Tourism', 'Health care', 'Information technology', 'A', 'Question: Which industry do the speakers most likely work in? (Những người nói chuyện nhiều khả năng làm việc trong ngành nào?)
A: Manufacturing (Sản xuất)
B: Tourism (Du lịch)
C: Health care (Chăm sóc sức khỏe)
D: Information technology (Công nghệ thông tin)

Giải thích: Đáp án A là chính xác vì họ đang thảo luận về dây chuyền lắp ráp (assembly line) đang hoàn thành việc sản xuất xe đạp leo núi (making the mountain bikes), cho thấy họ làm việc trong ngành sản xuất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4867, 213, '2025/test1/audio/test1-audio-59-61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6060, 4867, 60, 'What does the woman suggest?', 'Ordering extra materials', 'Closing a business early', 'Issuing some safety reminders', 'Double-checking some specifications', 'B', 'Question: What does the woman suggest? (Người phụ nữ đề xuất điều gì?)
A: Ordering extra materials (Đặt thêm vật liệu)
B: Closing a business early (Đóng cửa doanh nghiệp sớm)
C: Issuing some safety reminders (Đưa ra một số nhắc nhở về an toàn)
D: Double-checking some specifications (Kiểm tra lại một số thông số kỹ thuật)

Giải thích: Đáp án B là chính xác vì người phụ nữ đề xuất đóng cửa sớm và cho công nhân nghỉ buổi chiều (shutting down early and giving them the afternoon off).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4868, 213, '2025/test1/audio/test1-audio-59-61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6061, 4868, 61, 'What will the man do next?', 'Print a set of handouts', 'Submit a budget document', 'Cancel some appointments', 'Use a public address system', 'D', 'Question: What will the man do next? (Người đàn ông sẽ làm gì tiếp theo?)
A: Print a set of handouts (In một bộ tài liệu phát tay)
B: Submit a budget document (Nộp một tài liệu ngân sách)
C: Cancel some appointments (Hủy một số cuộc hẹn)
D: Use a public address system (Sử dụng hệ thống phát thanh công cộng)

Giải thích: Đáp án D là chính xác vì người đàn ông nói rằng anh ấy sẽ thông báo qua loa ngay (I''ll make an announcement over the loudspeakers now).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4869, 213, '2025/test1/audio/test1-audio-62-64.mp3', '2025/test1/image/test1-p3-image-62.jpg', 'M-Cn Oh hi, Sachiko! I didn''t know you were seeing this play this evening, too.
w-Br Yes, I''m here with lan. We wanted to catch the production one more time before it goes on tour next month. Had you seen it before as well?
M-cn No, and I loved it! Hugh Macdonald was wonderful. It''s too bad that Purva Shah was sick, though. Her replacement gave a good performance, but l''ve heard that Shah''s really great in the role.
w-Br That''s true. Hey, lan and I are planning to grab dinner nearby. Do you want to join us?
M-Cn Sure! I just have to keep an eye on the time. The parking garage where I left my car closes at ten.', 'M-Cn Ồ chào Sachiko! Tôi không biết chị cũng xem vở kịch này tối nay.
W-Br Vâng, tôi đến đây với Ian. Chúng tôi muốn xem vở diễn thêm một lần nữa trước khi nó đi lưu diễn vào tháng sau. Anh cũng đã xem nó trước đây phải không?
M-cn Không, và tôi rất thích nó! Hugh Macdonald thật tuyệt vời. Thật đáng tiếc là Purva Shah bị ốm. Người thay thế cô ấy diễn tốt, nhưng tôi nghe nói Shah thực sự rất xuất sắc trong vai này.
W-Br Đúng vậy. Này, Ian và tôi định đi ăn tối gần đây. Anh có muốn tham gia không?
M-Cn Được chứ! Tôi chỉ cần để ý giờ giấc thôi. Bãi đỗ xe nơi tôi để xe đóng cửa lúc 10 giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6062, 4869, 62, 'What does the woman say about the production?', 'It is hard to get tickets for', 'It is about to begin a tour', 'It has been running for a month', 'It has new cast members', 'B', 'Question: What does the woman say about the production? (Người phụ nữ nói gì về vở kịch?)
A: It is hard to get tickets for (Khó kiếm được vé)
B: It is about to begin a tour (Sắp bắt đầu một chuyến lưu diễn)
C: It has been running for a month (Đã diễn được một tháng)
D: It has new cast members (Có các diễn viên mới)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói họ muốn xem vở kịch thêm một lần nữa trước khi nó đi lưu diễn vào tháng sau (We wanted to catch the production one more time before it goes on tour next month).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4870, 213, '2025/test1/audio/test1-audio-62-64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6063, 4870, 63, 'Look at the graphic. Which role was played by a different performer this evening?', 'Nadia', 'Rick', 'Jasmine', 'Shane', 'A', 'Question: Look at the graphic. Which role was played by a different performer this evening? (Nhìn vào hình đồ họa. Vai nào được một diễn viên khác thể hiện tối nay?)
A: Nadia (Nadia)
B: Rick (Rick)
C: Jasmine (Jasmine)
D: Shane (Shane)

Giải thích: Đáp án A là chính xác vì theo cuộc trò chuyện, Purva Shah (người thường đóng vai này) bị ốm và có người thay thế (Purva Shah was sick... Her replacement gave a good performance). Trong hình đồ họa cho thấy Purva Shah đóng vai Nadia.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4871, 213, '2025/test1/audio/test1-audio-62-64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6064, 4871, 64, 'Where will the speakers most likely go next?', 'To a parking structure', 'To the theater office', 'To a restaurant', 'To a conference center', 'C', 'Question: Where will the speakers most likely go next? (Những người nói chuyện nhiều khả năng sẽ đi đâu tiếp theo?)
A: To a parking structure (Đến bãi đỗ xe)
B: To the theater office (Đến văn phòng nhà hát)
C: To a restaurant (Đến nhà hàng)
D: To a conference center (Đến trung tâm hội nghị)

Giải thích: Đáp án C là chính xác vì Ian và người phụ nữ dự định đi ăn tối gần đó và mời người đàn ông cùng đi (Ian and I are planning to grab dinner nearby. Do you want to join us?) và anh ấy đã đồng ý.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4872, 213, '2025/test1/audio/test1-audio-65-67.mp3', '2025/test1/image/test1-p3-image-65.jpg', 'M-Au Camila, the shipment from Gillespie Office Supplies arrived
W-Am Oh good! We need those binders. Ms. Chen is going to use them when she presents the housing department''s budget to the city administrators.
M-Au Let''s get everything unpacked.
w-Am I''ll check the invoice... Wait, this isn''t right. I''m sure l ordered more sticky notes than this.
M-Au Can I take a look at the invoice? Ah, there''s a note here at the bottom. It says the manufacturer is behind on production, so this is all that Gillespie had in stock. They''ll send the rest to us by the end of the month.
W-Am OK. That should be fine.
M-Au Good. So, should we take these boxes of binders to Ms. Chen''s office?', 'M-Au Camila, lô hàng từ Gillespie Office Supplies đã đến
W-Am Ồ tốt quá! Chúng ta cần những cái bìa đó. Bà Chen sẽ dùng chúng khi trình bày ngân sách của phòng nhà ở cho các quản trị viên thành phố.
M-Au Hãy mở tất cả ra.
W-Am Tôi sẽ kiểm tra hóa đơn... Khoan, cái này không đúng. Tôi chắc chắn tôi đã đặt nhiều giấy note dính hơn thế này.
M-Au Tôi có thể xem hóa đơn không? À, có một ghi chú ở dưới cùng. Nó nói rằng nhà sản xuất đang bị chậm sản xuất, vì vậy đây là tất cả những gì Gillespie có trong kho. Họ sẽ gửi phần còn lại cho chúng ta vào cuối tháng.
W-Am OK. Như vậy cũng được.
M-Au Tốt. Vậy, chúng ta nên mang những hộp bìa này đến văn phòng bà Chen chứ?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6065, 4872, 65, 'Where does the conversation most likely take place?', 'At a government office', 'At a print shop', 'At a law firm', 'At a marketing agency', 'A', 'Question: Where does the conversation most likely take place? (Cuộc trò chuyện nhiều khả năng diễn ra ở đâu?)
A: At a government office (Tại một văn phòng chính phủ)
B: At a print shop (Tại một cửa hàng in ấn)
C: At a law firm (Tại một công ty luật)
D: At a marketing agency (Tại một công ty marketing)

Giải thích: Đáp án A là chính xác vì cuộc trò chuyện đề cập đến việc Ms. Chen sẽ trình bày ngân sách của phòng nhà ở cho các quản trị viên thành phố (Ms. Chen is going to use them when she presents the housing department''s budget to the city administrators), cho thấy đây là một văn phòng chính phủ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4873, 213, '2025/test1/audio/test1-audio-65-67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6066, 4873, 66, 'Look at the graphic. Which quantity does the woman say is incorrect?', '3 boxes', '5 boxes', '7 boxes', '4 boxes', 'B', 'Question: Look at the graphic. Which quantity does the woman say is incorrect? (Nhìn vào hình đồ họa. Người phụ nữ nói số lượng nào không chính xác?)
A: 3 boxes (3 hộp)
B: 5 boxes (5 hộp)
C: 7 boxes (7 hộp)
D: 4 boxes (4 hộp)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói rằng cô ấy chắc chắn đã đặt nhiều giấy note dính hơn thế này (I''m sure I ordered more sticky notes than this), và trong hình đồ họa cho thấy số lượng sticky notes là 5 hộp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4874, 213, '2025/test1/audio/test1-audio-65-67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6067, 4874, 67, 'What does the man ask about?', 'Placing another order', 'Informing some coworkers', 'Testing some of the products', 'Moving some of the boxes', 'D', 'Question: What does the man ask about? (Người đàn ông hỏi về điều gì?)
A: Placing another order (Đặt một đơn hàng khác)
B: Informing some coworkers (Thông báo cho một số đồng nghiệp)
C: Testing some of the products (Kiểm tra một số sản phẩm)
D: Moving some of the boxes (Di chuyển một số hộp)

Giải thích: Đáp án D là chính xác vì cuối cuộc trò chuyện, người đàn ông hỏi liệu họ có nên mang những hộp bìa đến văn phòng bà Chen không (should we take these boxes of binders to Ms. Chen''s office?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4875, 213, '2025/test1/audio/test1-audio-68-70.mp3', '2025/test1/image/test1-p3-image-68.jpg', 'M-Cn Hi, Ivy. It''s Craig. Are you at the gate already?
I''m still waiting to get through the security screening. I''ve never seen lines this long at this terminal before.
w-Br Yeah, I was surprised by that too. I just arrived at our gate. But-the departure board now says our flight is delayed by forty minutes.
So you have time.
M-cn I''m glad to hear that. That does mean that we''ll land too late to catch the last shuttle bus, though. Could you look into other options for getting to the convention center?', 'M-Cn Chào Ivy. Craig đây. Chị đã ở cổng chưa?
Tôi vẫn đang đợi để qua kiểm tra an ninh. Tôi chưa bao giờ thấy hàng người dài như thế này ở terminal này trước đây.
W-Br Vâng, tôi cũng ngạc nhiên về điều đó. Tôi vừa đến cổng của chúng ta. Nhưng - bảng khởi hành bây giờ nói rằng chuyến bay của chúng ta bị trễ 40 phút.
Vậy anh còn thời gian.
M-Cn Tôi rất vui khi nghe điều đó. Tuy nhiên điều đó có nghĩa là chúng ta sẽ hạ cánh quá muộn để bắt kịp chuyến xe buýt cuối cùng. Chị có thể tìm hiểu các phương án khác để đến trung tâm hội nghị không?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6068, 4875, 68, 'What problem does the man mention?', 'There is a mistake on a schedule', 'A facility is unusually busy', 'An airport''s layout is confusing', 'He forgot to bring a travel document', 'B', 'Question: What problem does the man mention? (Người đàn ông đề cập đến vấn đề gì?)
A: There is a mistake on a schedule (Có một lỗi trên lịch trình)
B: A facility is unusually busy (Một cơ sở đặc biệt đông đúc)
C: An airport''s layout is confusing (Bố cục sân bay gây nhầm lẫn)
D: He forgot to bring a travel document (Anh ấy quên mang giấy tờ đi lại)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng anh ấy chưa bao giờ thấy hàng người dài như vậy ở terminal này trước đây (I''ve never seen lines this long at this terminal before).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4876, 213, '2025/test1/audio/test1-audio-68-70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6069, 4876, 69, 'Look at the graphic. Where are the speakers flying to?', 'Montreal', 'Winnipeg', 'Toronto', 'Calgary', 'A', 'Question: Look at the graphic. Where are the speakers flying to? (Nhìn vào hình đồ họa. Những người nói chuyện sẽ bay đến đâu?)
A: Montreal (Montreal)
B: Winnipeg (Winnipeg)
C: Toronto (Toronto)
D: Calgary (Calgary)

Giải thích: Đáp án A là chính xác vì trong cuộc trò chuyện họ nói về chuyến bay bị trễ 40 phút, và trong bảng thông tin cho thấy chuyến bay đến Montreal bị trì hoãn 40 phút (Delayed - 40 minutes).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4877, 213, '2025/test1/audio/test1-audio-68-70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6070, 4877, 70, 'What does the man ask the woman to do?', 'Check a weather forecast', 'Notify an event organizer', 'Research transportation options', 'Ask about an airline policy', 'C', 'Question: What does the man ask the woman to do? (Người đàn ông yêu cầu người phụ nữ làm gì?)
A: Check a weather forecast (Kiểm tra dự báo thời tiết)
B: Notify an event organizer (Thông báo cho người tổ chức sự kiện)
C: Research transportation options (Tìm hiểu các phương án di chuyển)
D: Ask about an airline policy (Hỏi về chính sách hãng hàng không)

Giải thích: Đáp án C là chính xác vì người đàn ông yêu cầu người phụ nữ tìm hiểu các phương án khác để đến trung tâm hội nghị (Could you look into other options for getting to the convention center?) sau khi biết họ sẽ không bắt kịp chuyến xe buýt cuối.');;

-- Data for 2025 Test1 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4878, 214, '2025/test1/audio/test1-audio-71-73.mp3', NULL, 'Hello, this is Na-Rim from the culinary school''s administration. I''m calling to let you know that Terrence Hill, who''s enrolled in your food history course, won''t be able to attend the next two sessions. He phoned this morning and notified me that he has an urgent family matter to deal with. We''ll excuse these absences, and we don''t want him to fall behind in the course. Could you e-mail him any slides or handouts you''ll be using in those sessions? Thank you.', 'Xin chào, đây là Na-Rim từ ban quản lý trường dạy nấu ăn. Tôi gọi để thông báo cho bạn biết rằng Terrence Hill, người đang theo học khóa học lịch sử ẩm thực của bạn, sẽ không thể tham dự hai buổi học tới. Anh ấy đã gọi điện sáng nay và thông báo với tôi rằng anh ấy có việc gia đình khẩn cấp cần giải quyết. Chúng tôi sẽ cho phép nghỉ những buổi vắng mặt này, và chúng tôi không muốn anh ấy bị tụt hậu trong khóa học. Bạn có thể gửi email cho anh ấy bất kỳ slide hoặc tài liệu nào bạn sẽ sử dụng trong những buổi học đó không? Cảm ơn bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6071, 4878, 71, 'What is the main purpose of the message?', 'To congratulate the listener on some exam results', 'To describe a career opportunity', 'To inform the listener of an attendance issue', 'To suggest a classroom activity', 'C', '[Dịch] Câu hỏi: Mục đích chính của thông điệp là gì?
A: Để chúc mừng người nghe về kết quả thi
B: Để mô tả cơ hội nghề nghiệp
C: Để thông báo về vấn đề điểm danh
D: Để đề xuất một hoạt động trong lớp học

Đáp án C là chính xác vì thông điệp chính của cuộc gọi là thông báo về vấn đề nghỉ học của sinh viên Terrence Hill. Điều này được thể hiện rõ qua câu ''Terrence Hill... won''t be able to attend the next two sessions''. Người gọi muốn thông báo rằng học sinh sẽ vắng mặt trong hai buổi học tới do có việc gia đình khẩn cấp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4879, 214, '2025/test1/audio/test1-audio-71-73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6072, 4879, 72, 'What does the speaker say she did this morning?', 'She watched a demonstration.', 'She reviewed some school records.', 'She ordered some supplies.', 'She received a call from a student.', 'D', '[Dịch] Câu hỏi: Người nói cho biết cô ấy đã làm gì sáng nay?
A: Cô ấy đã xem một bài thuyết trình
B: Cô ấy đã xem xét một số hồ sơ trường học
C: Cô ấy đã đặt một số vật tư
D: Cô ấy đã nhận được cuộc gọi từ một học sinh

Đáp án D là chính xác vì trong đoạn hội thoại có đề cập ''He phoned this morning'', cho thấy người nói đã nhận được cuộc gọi từ sinh viên Terrence Hill vào buổi sáng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4880, 214, '2025/test1/audio/test1-audio-71-73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6073, 4880, 73, 'What is the listener asked to do?', 'Postpone a class session', 'Send some teaching materials', 'Visit a business''s Web site', 'Meet with a supervisor', 'B', '[Dịch] Câu hỏi: Người nghe được yêu cầu làm gì?
A: Hoãn một buổi học
B: Gửi một số tài liệu giảng dạy
C: Truy cập trang web của doanh nghiệp
D: Gặp người giám sát

Đáp án B là chính xác vì cuối đoạn hội thoại, người nói yêu cầu ''Could you e-mail him any slides or handouts you''ll be using in those sessions?'', nghĩa là gửi tài liệu giảng dạy cho học sinh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4881, 214, '2025/test1/audio/test1-audio-74-76.mp3', NULL, 'In local cultural news, the Mayhew Museum of Art has announced plans to update and expand its downtown home. The renovation will be the first major initiative undertaken by Victor Hook since his appointment as the Mayhew''s director earlier this year. The work will mainly involve making the museum more accessible and adding a five-thousand-square-foot gallery to be used for short-term exhibitions. The Eddix Foundation has already agreed to sponsor the first show in the new space-an overview of contemporary Haitian art. If construction is completed on schedule, it will begin in March.', 'Trong tin tức văn hóa địa phương, Bảo tàng Nghệ thuật Mayhew đã công bố kế hoạch nâng cấp và mở rộng cơ sở ở trung tâm thành phố. Việc cải tạo sẽ là sáng kiến lớn đầu tiên được thực hiện bởi Victor Hook kể từ khi ông được bổ nhiệm làm giám đốc Mayhew vào đầu năm nay. Công việc chủ yếu sẽ liên quan đến việc làm cho bảo tàng dễ tiếp cận hơn và thêm một phòng trưng bày rộng năm nghìn feet vuông để sử dụng cho các cuộc triển lãm ngắn hạn. Quỹ Eddix đã đồng ý tài trợ cho buổi triển lãm đầu tiên trong không gian mới - một tổng quan về nghệ thuật đương đại Haiti. Nếu việc xây dựng hoàn thành đúng tiến độ, nó sẽ bắt đầu vào tháng Ba.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6074, 4881, 74, 'What is the main topic of the broadcast?', 'A famous resident of a city', 'The renovation of a building', 'The creation of some public art', 'A new educational program', 'B', '[Dịch] Câu hỏi: Chủ đề chính của bản tin là gì?
A: Một cư dân nổi tiếng của thành phố
B: Việc cải tạo một tòa nhà
C: Việc tạo ra một số tác phẩm nghệ thuật công cộng
D: Một chương trình giáo dục mới

Đáp án B là chính xác vì tin tức chính đề cập đến việc Bảo tàng Nghệ thuật Mayhew thông báo kế hoạch cải tạo và mở rộng (update and expand) cơ sở của họ ở trung tâm thành phố. Điều này được nhấn mạnh ngay từ đầu đoạn tin với câu ''the Mayhew Museum of Art has announced plans to update and expand its downtown home''.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4882, 214, '2025/test1/audio/test1-audio-74-76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6075, 4882, 75, 'According to the speaker, who is Victor Hook?', 'A painter', 'An architect', 'A museum director', 'A local historian', 'C', '[Dịch] Câu hỏi: Theo người nói, Victor Hook là ai?
A: Một họa sĩ
B: Một kiến trúc sư
C: Giám đốc bảo tàng
D: Một sử gia địa phương

Đáp án C là chính xác vì trong đoạn văn có đề cập rõ ràng ''Victor Hook since his appointment as the Mayhew''s director earlier this year'', nghĩa là Victor Hook đã được bổ nhiệm làm giám đốc Mayhew vào đầu năm nay.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4883, 214, '2025/test1/audio/test1-audio-74-76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6076, 4883, 76, 'What is the Eddix Foundation planning to do?', 'Fund an exhibition', 'Hire more personnel', 'Purchase a piece of land', 'Host an outdoor celebration', 'A', '[Dịch] Câu hỏi: Quỹ Eddix dự định làm gì?
A: Tài trợ một cuộc triển lãm
B: Tuyển thêm nhân sự
C: Mua một mảnh đất
D: Tổ chức một lễ kỷ niệm ngoài trời

Đáp án A là chính xác vì đoạn văn nêu rõ ''The Eddix Foundation has already agreed to sponsor the first show in the new space'', nghĩa là Quỹ Eddix đã đồng ý tài trợ cho buổi triển lãm đầu tiên trong không gian mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4884, 214, '2025/test1/audio/test1-audio-77-79.mp3', NULL, 'Hi, everyone. I''m excited to announce that our station has bought new portable news cameras. We looked into the display screens for the studio that some of you suggested, but they were over our budget. Now, the great thing about the new cameras is that they aren''t heavy like our current ones. Our news teams are going to be able to move around more easily when reporting on live events. Uh, for our camera operators- Omar is familiar with this model, but he''ll be out in the field when they arrive. I''ll make sure you each get a user manual along with the camera, though.', 'Xin chào mọi người. Tôi rất vui mừng thông báo rằng đài của chúng ta đã mua máy quay tin tức di động mới. Chúng tôi đã xem xét các màn hình hiển thị cho studio mà một số bạn đề xuất, nhưng chúng vượt quá ngân sách của chúng ta. Điều tuyệt vời về những máy quay mới là chúng không nặng như những chiếc hiện tại của chúng ta. Các đội tin tức của chúng ta sẽ có thể di chuyển dễ dàng hơn khi đưa tin về các sự kiện trực tiếp. À, đối với các người quay phim của chúng ta - Omar đã quen với model này, nhưng anh ấy sẽ đi công tác khi chúng được giao tới. Tuy nhiên, tôi sẽ đảm bảo mỗi người đều nhận được hướng dẫn sử dụng kèm theo máy quay.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6077, 4884, 77, 'What kind of equipment has been purchased?', 'Display screens', 'Microphones', 'Lighting', 'Video cameras', 'D', '[Dịch] Câu hỏi: Loại thiết bị gì đã được mua?
A: Màn hình hiển thị
B: Micrô
C: Đèn
D: Máy quay video

Đáp án D là chính xác vì ngay từ đầu đoạn thông báo có đề cập ''our station has bought new portable news cameras''. Đây là máy quay video di động mới cho đài.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4885, 214, '2025/test1/audio/test1-audio-77-79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6078, 4885, 78, 'What does the speaker emphasize about the products?', 'They have many features.', 'They are lightweight.', 'They are inexpensive.', 'They will last a long time.', 'B', '[Dịch] Câu hỏi: Người nói nhấn mạnh điều gì về các sản phẩm?
A: Chúng có nhiều tính năng
B: Chúng nhẹ
C: Chúng rẻ tiền
D: Chúng sẽ bền lâu

Đáp án B là chính xác vì người nói nhấn mạnh ''they aren''t heavy like our current ones'', nghĩa là máy quay mới không nặng như những chiếc hiện tại. Điều này sẽ giúp đội tin tức di chuyển dễ dàng hơn khi đưa tin trực tiếp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4886, 214, '2025/test1/audio/test1-audio-77-79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6079, 4886, 79, 'Why does the speaker say, "but he''ll be out in the field when they arrive"?', 'To indicate that training will not be available', 'To question a staffing decision', 'To request help unloading the equipment', 'To explain an expected delay', 'A', '[Dịch] Câu hỏi: Tại sao người nói nói "nhưng anh ấy sẽ đi công tác khi chúng được giao tới"?
A: Để cho biết việc đào tạo sẽ không có sẵn
B: Để đặt câu hỏi về quyết định nhân sự
C: Để yêu cầu giúp đỡ dỡ thiết bị
D: Để giải thích về sự chậm trễ dự kiến

Đáp án A là chính xác vì ngữ cảnh cho thấy Omar là người duy nhất quen thuộc với model máy quay mới (''Omar is familiar with this model''), nhưng anh ấy sẽ vắng mặt khi thiết bị được giao, nghĩa là sẽ không có người để đào tạo cho các nhân viên khác. Để bù đắp điều này, người nói đảm bảo sẽ cung cấp hướng dẫn sử dụng cho mọi người.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4887, 214, '2025/test1/audio/test1-audio-80-82.mp3', NULL, 'Hello, you have reached the desk of Kevin Greco, senior business analyst at Dorsey Electric Company. I am currently unable to take your call. Also, please note that due to a shift in my duties toward our renewable energy projects, I no longer manage our vendor invoices. However, if you need to speak with me regarding another matter, please leave a message after the tone that includes your name and contact information. I will get back to you within two business days. Thank you.', 'Xin chào, bạn đã kết nối với máy nhánh của Kevin Greco, chuyên viên phân tích kinh doanh cấp cao tại Công ty Điện lực Dorsey. Hiện tại tôi không thể nghe máy. Ngoài ra, xin lưu ý rằng do có sự thay đổi trong nhiệm vụ của tôi về các dự án năng lượng tái tạo, tôi không còn quản lý hóa đơn của nhà cung cấp nữa. Tuy nhiên, nếu bạn cần nói chuyện với tôi về vấn đề khác, vui lòng để lại tin nhắn sau tiếng bíp bao gồm tên và thông tin liên hệ của bạn. Tôi sẽ liên hệ lại với bạn trong vòng hai ngày làm việc. Xin cảm ơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6080, 4887, 80, 'What type of business does the speaker work for?', 'At a car dealership', 'At a utility company', 'At a recruiting agency', 'At a newspaper office', 'B', '[Dịch] Câu hỏi: Người nói làm việc cho loại doanh nghiệp nào?
A: Tại một đại lý ô tô
B: Tại một công ty tiện ích
C: Tại một công ty tuyển dụng
D: Tại một văn phòng báo chí

Đáp án B là chính xác vì người nói làm việc tại Dorsey Electric Company (một công ty điện lực). Điều này được khẳng định thêm khi đề cập đến các dự án năng lượng tái tạo (''renewable energy projects''), điều này phổ biến trong các công ty tiện ích.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4888, 214, '2025/test1/audio/test1-audio-80-82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6081, 4888, 81, 'What does the speaker say about himself?', 'He has moved offices.', 'He is on a business trip.', 'He is preparing some documents.', 'His job duties have changed.', 'D', '[Dịch] Câu hỏi: Người nói nói gì về bản thân?
A: Anh ấy đã chuyển văn phòng
B: Anh ấy đang đi công tác
C: Anh ấy đang chuẩn bị một số tài liệu
D: Nhiệm vụ công việc của anh ấy đã thay đổi

Đáp án D là chính xác vì trong tin nhắn có đề cập ''due to a shift in my duties toward our renewable energy projects'', nghĩa là nhiệm vụ của anh ấy đã thay đổi sang các dự án năng lượng tái tạo và không còn quản lý hóa đơn nhà cung cấp nữa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4889, 214, '2025/test1/audio/test1-audio-80-82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6082, 4889, 82, 'What is the listener instructed to do?', 'Call another person', 'Review a list of suggestions', 'Leave a voice message', 'Complete an online form', 'C', '[Dịch] Câu hỏi: Người nghe được hướng dẫn làm gì?
A: Gọi cho người khác
B: Xem xét danh sách đề xuất
C: Để lại tin nhắn thoại
D: Điền vào mẫu đơn trực tuyến

Đáp án C là chính xác vì trong tin nhắn có yêu cầu ''please leave a message after the tone that includes your name and contact information'', nghĩa là người nghe được hướng dẫn để lại tin nhắn thoại sau tiếng bíp, kèm theo tên và thông tin liên hệ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4890, 214, '2025/test1/audio/test1-audio-83-85.mp3', NULL, 'Thank you all for coming to this meeting. As you know, the volume of books that we publish has grown rapidly over the past year. We''ve always outsourced our design tasks to freelancers, but I believe there''s now enough work that it makes more sense financially to have a book designer on staff. So, we''re now seeking to hire someone for a full-time position. I posted a listing online this morning, and notified our freelancers about it. I''m going to e-mail the job ad to you all as well. Please send it around to anyone you think might be interested.', 'Cảm ơn tất cả các bạn đã đến cuộc họp này. Như các bạn đã biết, số lượng sách chúng ta xuất bản đã tăng nhanh chóng trong năm qua. Chúng ta luôn thuê ngoài các công việc thiết kế cho các cộng tác viên tự do, nhưng tôi tin rằng hiện tại có đủ công việc để việc có một nhà thiết kế sách trong đội ngũ nhân viên chính thức sẽ hợp lý hơn về mặt tài chính. Vì vậy, chúng tôi đang tìm kiếm người để tuyển dụng cho vị trí toàn thời gian. Tôi đã đăng tin tuyển dụng trực tuyến sáng nay và thông báo cho các cộng tác viên tự do của chúng tôi về việc này. Tôi cũng sẽ gửi email quảng cáo việc làm cho tất cả các bạn. Vui lòng gửi nó cho bất kỳ ai mà bạn nghĩ có thể quan tâm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6083, 4890, 83, 'What industry does the speaker most likely work in?', 'Finance', 'Marketing', 'Hospitality', 'Publishing', 'D', '[Dịch] Câu hỏi: Người nói có khả năng làm việc trong ngành nào?
A: Tài chính
B: Tiếp thị
C: Khách sạn
D: Xuất bản

Đáp án D là chính xác vì trong đoạn hội thoại đề cập đến việc xuất bản sách (''the volume of books that we publish'') và cần thuê nhà thiết kế sách (''book designer''), điều này rõ ràng cho thấy đây là một công ty xuất bản.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4891, 214, '2025/test1/audio/test1-audio-83-85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6084, 4891, 84, 'What is the speaker mainly discussing?', 'A job opening', 'A company celebration', 'Technology upgrades', 'Survey results', 'A', '[Dịch] Câu hỏi: Người nói chủ yếu đang thảo luận về điều gì?
A: Một vị trí tuyển dụng
B: Một lễ kỷ niệm công ty
C: Nâng cấp công nghệ
D: Kết quả khảo sát

Đáp án A là chính xác vì toàn bộ đoạn hội thoại tập trung vào việc công ty đang tìm kiếm người để tuyển dụng cho vị trí thiết kế sách toàn thời gian (''seeking to hire someone for a full-time position''). Người nói cũng đề cập đến việc đã đăng tin tuyển dụng và thông báo cho mọi người về vị trí này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4892, 214, '2025/test1/audio/test1-audio-83-85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6085, 4892, 85, 'What does the speaker ask the listeners to do?', 'Share an announcement', 'Collaborate on a report', 'Revise a budget', 'Indicate a preference', 'A', '[Dịch] Câu hỏi: Người nói yêu cầu người nghe làm gì?
A: Chia sẻ một thông báo
B: Hợp tác viết một báo cáo
C: Sửa đổi ngân sách
D: Chỉ ra sự ưu tiên

Đáp án A là chính xác vì cuối đoạn hội thoại, người nói yêu cầu ''Please send it around to anyone you think might be interested'', nghĩa là yêu cầu người nghe chia sẻ thông báo tuyển dụng cho những người có thể quan tâm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4893, 214, '2025/test1/audio/test1-audio-86-88.mp3', NULL, 'OK, now that I''ve shown you how our gym expects you to format your client workout plans, let''s talk about actually implementing them. We believe your first task is to make sure that the client understands what they''re supposed to do. For example, when you ask them to use something like the leg press machine, be aware that many people are not familiar with this equipment. You may even want to demonstrate how to use it yourself. It''s important that the client feel confident about what they''re doing. It will make them want to keep scheduling sessions with you— which is your main goal.', 'OK, bây giờ khi tôi đã chỉ cho các bạn cách phòng tập của chúng ta mong đợi bạn định dạng kế hoạch tập luyện cho khách hàng như thế nào, hãy nói về việc thực hiện chúng. Chúng tôi tin rằng nhiệm vụ đầu tiên của bạn là đảm bảo khách hàng hiểu những gì họ cần làm. Ví dụ, khi bạn yêu cầu họ sử dụng một thứ như máy đạp chân, hãy nhận thức rằng nhiều người không quen với thiết bị này. Bạn thậm chí có thể muốn tự mình thị phạm cách sử dụng nó. Điều quan trọng là khách hàng cảm thấy tự tin về những gì họ đang làm. Điều này sẽ khiến họ muốn tiếp tục đặt lịch các buổi tập với bạn - đó là mục tiêu chính của bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6086, 4893, 86, 'Who most likely are the listeners?', 'Technical support agents', 'Personal trainers', 'Factory workers', 'Construction supervisors', 'B', '[Dịch] Câu hỏi: Người nghe có khả năng là ai?
A: Nhân viên hỗ trợ kỹ thuật
B: Huấn luyện viên cá nhân
C: Công nhân nhà máy
D: Giám sát xây dựng

Đáp án B là chính xác vì nội dung đề cập đến phòng tập (''gym''), kế hoạch tập luyện cho khách hàng (''client workout plans''), và thiết bị tập luyện (''leg press machine''). Đây rõ ràng là một buổi đào tạo dành cho các huấn luyện viên cá nhân.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4894, 214, '2025/test1/audio/test1-audio-86-88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6087, 4894, 87, 'What does the speaker imply when he says, "many people are not familiar with this equipment"?', 'An achievement is surprising.', 'It is difficult to find qualified staff.', 'A clear explanation should be given.', 'It is not necessary to keep the equipment.', 'C', '[Dịch] Câu hỏi: Người nói ngụ ý điều gì khi anh ấy nói "nhiều người không quen với thiết bị này"?
A: Một thành tích đáng ngạc nhiên
B: Khó tìm nhân viên đủ tiêu chuẩn
C: Cần đưa ra lời giải thích rõ ràng
D: Không cần thiết phải giữ thiết bị

Đáp án C là chính xác vì sau khi đề cập rằng nhiều người không quen với thiết bị, người nói gợi ý rằng huấn luyện viên nên thị phạm cách sử dụng (''demonstrate how to use it yourself''). Điều này ngụ ý rằng cần phải có sự hướng dẫn và giải thích rõ ràng cho khách hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4895, 214, '2025/test1/audio/test1-audio-86-88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6088, 4895, 88, 'According to the speaker, what is the listeners'' main goal?', 'To retain customers', 'To finish a project on schedule', 'To resolve a safety issue', 'To simplify a process', 'A', '[Dịch] Câu hỏi: Theo người nói, mục tiêu chính của người nghe là gì?
A: Giữ chân khách hàng
B: Hoàn thành dự án đúng lịch trình
C: Giải quyết vấn đề an toàn
D: Đơn giản hóa quy trình

Đáp án A là chính xác vì người nói nêu rõ ràng rằng mục tiêu chính là làm cho khách hàng ''want to keep scheduling sessions with you'', nghĩa là tiếp tục đặt lịch các buổi tập, hay nói cách khác là giữ chân khách hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4896, 214, '2025/test1/audio/test1-audio-89-91.mp3', NULL, 'Next, I have an update on the project to increase customer engagement with our athletic shoe line. As you may remember, we added a pop-up advertisement to our Web site in order to encourage visitors to subscribe to our mailing list. Well, after one week, we have over ten thousand new subscribers-well over the goal we set! It seems that a lot of people want the giveaway poster of our spokesperson playing basketball in our shoes. I know there was some concern about the cost of offering this incentive, but I think these results show that it''s worth it. We now have a direct channel of communication with many more potential customers.', 'Tiếp theo, tôi có một cập nhật về dự án tăng cường sự tham gia của khách hàng với dòng giày thể thao của chúng ta. Như các bạn có thể nhớ, chúng ta đã thêm một quảng cáo pop-up vào trang web của mình để khuyến khích khách truy cập đăng ký vào danh sách gửi thư. Chà, sau một tuần, chúng ta đã có hơn mười nghìn người đăng ký mới - vượt xa mục tiêu đã đề ra! Có vẻ như nhiều người muốn có poster tặng kèm của người đại diện của chúng ta đang chơi bóng rổ trong giày của chúng ta. Tôi biết đã có một số lo ngại về chi phí của việc đưa ra ưu đãi này, nhưng tôi nghĩ những kết quả này cho thấy nó đáng giá. Giờ đây chúng ta có một kênh liên lạc trực tiếp với nhiều khách hàng tiềm năng hơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6089, 4896, 89, 'Where does the speaker most likely work?', 'At a footwear company', 'At a video game developer', 'At a beverage manufacturer', 'At a sports team organization', 'A', '[Dịch] Câu hỏi: Người nói có khả năng làm việc ở đâu?
A: Tại một công ty giày dép
B: Tại một nhà phát triển trò chơi điện tử
C: Tại một nhà sản xuất đồ uống
D: Tại một tổ chức đội thể thao

Đáp án A là chính xác vì đoạn văn đề cập đến dòng giày thể thao (''athletic shoe line'') và poster quảng cáo có người đại diện đang chơi bóng rổ trong giày của công ty (''spokesperson playing basketball in our shoes''), cho thấy đây là một công ty sản xuất giày dép.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4897, 214, '2025/test1/audio/test1-audio-89-91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6090, 4897, 90, 'What does the business want people to do?', 'Join a loyalty program', 'Sign up for a mailing list', 'Write a product review', 'Follow a social media account', 'B', '[Dịch] Câu hỏi: Doanh nghiệp muốn mọi người làm gì?
A: Tham gia chương trình khách hàng thân thiết
B: Đăng ký vào danh sách gửi thư
C: Viết đánh giá sản phẩm
D: Theo dõi tài khoản mạng xã hội

Đáp án B là chính xác vì đoạn văn nêu rõ công ty đã thêm quảng cáo pop-up để ''encourage visitors to subscribe to our mailing list'', nghĩa là khuyến khích khách truy cập đăng ký vào danh sách gửi thư.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4898, 214, '2025/test1/audio/test1-audio-89-91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6091, 4898, 91, 'What incentive is being offered?', 'A discount code', 'Entry in a prize drawing', 'Tickets to a virtual event', 'A promotional poster', 'D', '[Dịch] Câu hỏi: Ưu đãi nào đang được cung cấp?
A: Mã giảm giá
B: Tham gia rút thăm trúng thưởng
C: Vé sự kiện trực tuyến
D: Poster quảng cáo

Đáp án D là chính xác vì đoạn văn đề cập đến ''the giveaway poster of our spokesperson playing basketball in our shoes'', nghĩa là poster tặng kèm có hình người đại diện đang chơi bóng rổ trong giày của công ty.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4899, 214, '2025/test1/audio/test1-audio-92-94.mp3', NULL, 'Can I have everyone''s attention, please? I know you have a lot of patient samples to perform tests on today, but this will just take a moment. I have an announcement about our benefits for employees. Several of you have expressed frustration that there hasn''t been a clear overview of the retirement savings plans, insurance coverage, and everything else that the lab offers its workers. Until now, the information was scattered throughout different documents or was only made available to human resources staff. Now, there''s a single file on our shared network. In addition, I promise to provide a prompt response to any questions you have about this information.', 'Xin mọi người chú ý? Tôi biết hôm nay các bạn có nhiều mẫu bệnh phẩm cần xét nghiệm, nhưng việc này sẽ chỉ mất một chút thời gian thôi. Tôi có thông báo về phúc lợi cho nhân viên. Một số bạn đã bày tỏ sự thất vọng vì chưa có cái nhìn tổng quan rõ ràng về các kế hoạch tiết kiệm hưu trí, bảo hiểm và những thứ khác mà phòng thí nghiệm cung cấp cho nhân viên. Cho đến nay, thông tin được phân tán trong các tài liệu khác nhau hoặc chỉ được cung cấp cho nhân viên phòng nhân sự. Giờ đây, có một tập tin duy nhất trên mạng chia sẻ của chúng ta. Ngoài ra, tôi hứa sẽ phản hồi nhanh chóng mọi câu hỏi của bạn về thông tin này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6092, 4899, 92, 'Where do the listeners most likely work?', 'At a real estate firm', 'At a community center', 'At a medical laboratory', 'At a business school', 'C', '[Dịch] Câu hỏi: Người nghe có khả năng làm việc ở đâu?
A: Tại một công ty bất động sản
B: Tại một trung tâm cộng đồng
C: Tại một phòng thí nghiệm y tế
D: Tại một trường kinh doanh

Đáp án C là chính xác vì đoạn văn đề cập đến việc xét nghiệm mẫu bệnh nhân (''patient samples to perform tests'') và nhắc đến phòng thí nghiệm (''the lab''), cho thấy đây là một phòng thí nghiệm y tế.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4900, 214, '2025/test1/audio/test1-audio-92-94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6093, 4900, 93, 'What does the speaker imply when he says, "Now, there''s a single file on our shared network"?', 'A task has not been finished.', 'There is space to save more data.', 'Some complaints have been addressed.', 'A security rule is not being followed.', 'C', '[Dịch] Câu hỏi: Người nói ngụ ý điều gì khi anh ấy nói "Giờ đây, có một tập tin duy nhất trên mạng chia sẻ của chúng ta"?
A: Một nhiệm vụ chưa hoàn thành
B: Có không gian để lưu thêm dữ liệu
C: Một số khiếu nại đã được giải quyết
D: Một quy tắc bảo mật không được tuân thủ

Đáp án C là chính xác vì trước đó đoạn văn đề cập đến việc nhân viên đã phàn nàn về việc thông tin bị phân tán (''information was scattered throughout different documents''). Việc tạo một tập tin duy nhất trên mạng chia sẻ cho thấy công ty đã giải quyết những khiếu nại này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4901, 214, '2025/test1/audio/test1-audio-92-94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6094, 4901, 94, 'What does the speaker say he will do quickly?', 'Draft a timeline', 'Respond to inquiries', 'Update some software', 'Issue log-in credentials', 'B', '[Dịch] Câu hỏi: Người nói cho biết anh ấy sẽ làm gì một cách nhanh chóng?
A: Soạn thảo một mốc thời gian
B: Phản hồi các thắc mắc
C: Cập nhật phần mềm
D: Cấp thông tin đăng nhập

Đáp án B là chính xác vì người nói hứa ''to provide a prompt response to any questions'', nghĩa là sẽ phản hồi nhanh chóng các câu hỏi về thông tin phúc lợi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4902, 214, '2025/test1/audio/test1-audio-95-97.mp3', '2025/test1/image/test1-p4-image-95.jpg', 'OK, team. Your first job today is taking a shipment of desks to Augustine Industries. Make sure to put the protective mats down before you move them in-the company''s very worried about damage to their floors. Uh... the office manager''s going to keep a parking space open for you near the entrance-specifically, the spot at the bottom of the ramp, so you won''t have to navigate the stairs. And you have another job scheduled for eleven A.M., so come straight back here when you''re done.', 'OK, đội ngũ. Công việc đầu tiên của các bạn hôm nay là chuyển một lô bàn đến Công ty Augustine. Hãy đảm bảo đặt thảm bảo vệ trước khi chuyển chúng vào - công ty rất lo lắng về việc làm hỏng sàn nhà của họ. À... người quản lý văn phòng sẽ giữ một chỗ đỗ xe cho các bạn gần lối vào - cụ thể là chỗ ở cuối dốc, vì vậy các bạn sẽ không phải đi qua cầu thang. Và các bạn có một công việc khác được lên lịch vào 11 giờ sáng, vì vậy hãy quay thẳng về đây khi hoàn thành.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6095, 4902, 95, 'What type of business do the listeners most likely work for?', 'A flooring contractor', 'A plumbing service', 'A delivery company', 'An Internet service provider', 'C', '[Dịch] Câu hỏi: Người nghe có khả năng làm việc cho loại doanh nghiệp nào?
A: Một nhà thầu sàn nhà
B: Một dịch vụ đường ống nước
C: Một công ty vận chuyển
D: Một nhà cung cấp dịch vụ Internet

Đáp án C là chính xác vì nội dung đoạn hội thoại đề cập đến việc vận chuyển lô bàn (''taking a shipment of desks''), sử dụng thảm bảo vệ khi di chuyển đồ, và có nhiều công việc giao hàng được lên lịch trong ngày. Những hoạt động này điển hình của một công ty vận chuyển.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4903, 214, '2025/test1/audio/test1-audio-95-97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6096, 4903, 96, 'Look at the graphic. Which parking space will be reserved for the listeners?', 'Space 1', 'Space 2', 'Space 3', 'Space 4', 'A', '[Dịch] Câu hỏi: Nhìn vào hình. Chỗ đỗ xe nào sẽ được dành riêng cho người nghe?
A: Chỗ số 1
B: Chỗ số 2
C: Chỗ số 3
D: Chỗ số 4

Đáp án A là chính xác vì trong đoạn hội thoại người nói đề cập rằng chỗ đỗ xe sẽ ở ''the spot at the bottom of the ramp''. Nhìn vào hình vẽ, Space 1 nằm ở cuối dốc (ramp), đúng với mô tả trong đoạn hội thoại.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4904, 214, '2025/test1/audio/test1-audio-95-97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6097, 4904, 97, 'What should the listeners do after a job is completed?', 'Return to their current location', 'Send a message to a supervisor', 'Check an electronic schedule', 'Take a required meal break', 'A', '[Dịch] Câu hỏi: Người nghe nên làm gì sau khi hoàn thành công việc?
A: Quay về vị trí hiện tại
B: Gửi tin nhắn cho người giám sát
C: Kiểm tra lịch trình điện tử
D: Nghỉ ăn theo quy định

Đáp án A là chính xác vì người nói yêu cầu rõ ràng ''come straight back here when you''re done'', nghĩa là quay thẳng về địa điểm hiện tại sau khi hoàn thành công việc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4905, 214, '2025/test1/audio/test1-audio-98-100.mp3', '2025/test1/image/test1-p4-image-98.jpg', 'Hi, it''s Cory Watkins. I just looked over the initial floor plan you designed for my flower shop. Overall, I''m quite happy with it. I like that you included so much display shelving. That will let us feature a wide assortment of our floral arrangements at one time. However, I''ll need you to make one change to the plan. The staff workbench in the back room will have to be shortened to make space for a storage cooler. I forgot to include that piece of equipment in my list of required features-sorry.', 'Xin chào, tôi là Cory Watkins. Tôi vừa xem qua bản thiết kế sơ bộ bạn làm cho cửa hàng hoa của tôi. Nhìn chung, tôi khá hài lòng với nó. Tôi thích việc bạn đã bao gồm nhiều kệ trưng bày. Điều đó sẽ cho phép chúng tôi trưng bày đồng thời nhiều loại bó hoa khác nhau. Tuy nhiên, tôi sẽ cần bạn thực hiện một thay đổi trong bản thiết kế. Bàn làm việc của nhân viên ở phòng sau sẽ phải được rút ngắn lại để tạo không gian cho tủ lạnh bảo quản. Tôi đã quên đưa thiết bị đó vào danh sách các tính năng yêu cầu - xin lỗi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6098, 4905, 98, 'Who most likely is the listener?', 'An interior designer', 'An event coordinator', 'A delivery person', 'A cleaner', 'A', '[Dịch] Câu hỏi: Người nghe có khả năng là ai?
A: Một nhà thiết kế nội thất
B: Một điều phối viên sự kiện
C: Một người giao hàng
D: Một người dọn dẹp

Đáp án A là chính xác vì người nói đang thảo luận về bản thiết kế sơ bộ (''initial floor plan'') cho cửa hàng hoa của mình và yêu cầu thực hiện thay đổi trong thiết kế. Đây là công việc điển hình của một nhà thiết kế nội thất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4906, 214, '2025/test1/audio/test1-audio-98-100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6099, 4906, 99, 'What does the speaker say about flower arrangements?', 'They were just delivered.', 'They are difficult to care for.', 'There will be a variety of them.', 'They can be moved out of the way.', 'C', '[Dịch] Câu hỏi: Người nói nói gì về các bó hoa?
A: Chúng vừa được giao đến
B: Chúng khó chăm sóc
C: Sẽ có nhiều loại khác nhau
D: Chúng có thể được di chuyển ra chỗ khác

Đáp án C là chính xác vì người nói đề cập đến ''wide assortment of our floral arrangements'', nghĩa là sẽ có nhiều loại bó hoa đa dạng được trưng bày cùng một lúc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4907, 214, '2025/test1/audio/test1-audio-98-100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6100, 4907, 100, 'Look at the graphic. Which feature will have to be changed?', 'Feature 1', 'Feature 2', 'Feature 3', 'Feature 4', 'D', '[Dịch] Câu hỏi: Nhìn vào hình. Đặc điểm nào sẽ phải thay đổi?
A: Đặc điểm 1
B: Đặc điểm 2
C: Đặc điểm 3
D: Đặc điểm 4

Đáp án D là chính xác vì trong đoạn hội thoại, người nói yêu cầu rút ngắn bàn làm việc của nhân viên (''staff workbench'') để có chỗ cho tủ lạnh bảo quản. Nhìn vào bản vẽ, Feature 4 được đánh dấu là ''Staff Workbench'', chính là khu vực cần được thay đổi.');;

-- Data for 2025 Test1 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4908, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6101, 4908, 101, 'The town council must be given advance notice of ------ to official historic structures.', 'modifications', 'modifying', 'modified', 'modifies', 'A', 'Đáp án A (modifications) là đúng vì nhiều lý do:
1. Sau giới từ "of", chúng ta cần một danh từ. "Modifications" là danh từ số nhiều, phù hợp về mặt ngữ pháp.
2. Cấu trúc "advance notice of something" là cấu trúc cố định, trong đó "something" phải là danh từ.
3. Trong ngữ cảnh này, cần dùng danh từ số nhiều vì đề cập đến nhiều sự thay đổi khác nhau đối với các công trình.
4. Các đáp án khác không phù hợp vì: "modifying" là danh động từ, "modified" là tính từ, "modifies" là động từ ngôi thứ 3 số ít.
5. Cấu trúc "notice of + noun" là cấu trúc phổ biến trong tiếng Anh hành chính.
Dịch câu hỏi: Hội đồng thành phố phải được thông báo trước về những thay đổi đối với các công trình lịch sử chính thức.
Dịch đáp án:
A. modifications (danh từ số nhiều: những sự thay đổi)
B. modifying (danh động từ: việc thay đổi)
C. modified (tính từ: đã được thay đổi)
D. modifies (động từ ngôi thứ 3 số ít: thay đổi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4909, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6102, 4909, 102, 'Upon its founder''s retirement, the magazine published a special article on ---- achievements.', 'he', 'him', 'his', 'himself', 'C', 'Đáp án C (his) là đúng vì các lý do sau:
1. Trong cấu trúc này, chúng ta cần một tính từ sở hữu để chỉ thành tựu của người sáng lập.
2. "His" là tính từ sở hữu của đại từ nhân xưng "he", dùng để chỉ sự sở hữu của founder (nam giới).
3. Vị trí này cần một từ bổ nghĩa cho danh từ "achievements" (thành tựu).
4. Đây là cấu trúc "article on + tính từ sở hữu + danh từ".
5. Các đáp án khác không phù hợp vì: "he" là đại từ chủ ngữ, "him" là đại từ tân ngữ, "himself" là đại từ phản thân.
6. Trong tiếng Anh, khi nói về sở hữu, ta luôn dùng tính từ sở hữu trước danh từ, không dùng đại từ nhân xưng.
Dịch câu hỏi: Khi người sáng lập nghỉ hưu, tạp chí đã xuất bản một bài báo đặc biệt về những thành tựu của ông ấy.
Dịch đáp án:
A. he (đại từ nhân xưng chủ ngữ: anh ấy)
B. him (đại từ nhân xưng tân ngữ: anh ấy)
C. his (tính từ sở hữu: của anh ấy)
D. himself (đại từ phản thân: chính anh ấy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4910, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6103, 4910, 103, 'Many restaurants have --- been using mobile apps to manage their staff work schedules.', 'successfully', 'succeeding', 'succeeded', 'successes', 'A', 'Đáp án A (successfully) là đúng vì các lý do sau:
1. Trong cấu trúc này, ta cần một trạng từ để bổ nghĩa cho cả cụm động từ hoàn thành tiếp diễn "have been using".
2. Trạng từ thường được đặt giữa trợ động từ (have) và động từ chính (been) trong thì hoàn thành tiếp diễn.
3. Cấu trúc "have + trạng từ + been + V-ing" là cấu trúc chuẩn trong tiếng Anh.
4. "Successfully" được tạo thành bằng cách thêm đuôi -ly vào tính từ "successful", là cách thông thường để tạo trạng từ trong tiếng Anh.
5. Các đáp án khác không phù hợp vì: "succeeding" là động từ hiện tại phân từ, "succeeded" là động từ quá khứ phân từ, "successes" là danh từ số nhiều.
Dịch câu hỏi: Nhiều nhà hàng đã sử dụng ứng dụng di động một cách thành công để quản lý lịch làm việc của nhân viên.
Dịch đáp án:
A. successfully (trạng từ: một cách thành công)
B. succeeding (động từ hiện tại phân từ: đang thành công)
C. succeeded (động từ quá khứ phân từ: đã thành công)
D. successes (danh từ số nhiều: những thành công)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4911, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6104, 4911, 104, 'Mena Hotel has prospered mainly because its management understands --- to create comfortable spaces for guests.', 'yet', 'how', 'about', 'that', 'B', 'Đáp án B (how) là đúng vì các lý do sau:
1. Sau động từ "understand" khi muốn nói về cách thức làm gì đó, ta dùng "how + to-infinitive".
2. Cấu trúc "understand how to do something" là cấu trúc phổ biến để diễn tả việc hiểu cách thực hiện một hành động.
3. "How" trong trường hợp này đóng vai trò như một liên từ, dẫn dắt mệnh đề chỉ cách thức.
4. Đây là câu phức với mệnh đề chính "Mena Hotel has prospered" và mệnh đề phụ lý do "because its management understands how to create...".
5. Các đáp án khác không phù hợp vì: "yet" là liên từ chỉ sự tương phản, "about" là giới từ, "that" không phù hợp với cấu trúc ngữ pháp này.
Dịch câu hỏi: Khách sạn Mena đã phát triển thịnh vượng chủ yếu vì ban quản lý hiểu cách tạo ra không gian thoải mái cho khách.
Dịch đáp án:
A. yet (liên từ/trạng từ: tuy nhiên/còn)
B. how (trạng từ: cách thức/làm thế nào)
C. about (giới từ: về)
D. that (đại từ chỉ định: điều đó)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4912, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6105, 4912, 105, 'Ms. Cox''s computer is --—- old that it cannot run the new teleconferencing software.', 'too', 'soon', 'enough', 'so', 'D', 'Đáp án D (so) là đúng vì các lý do sau:
1. Đây là cấu trúc "so + tính từ/trạng từ + that + mệnh đề" dùng để diễn tả kết quả của một tình trạng.
2. Cấu trúc này khác với "too + tính từ + to-infinitive" (quá... để) và "tính từ + enough + to-infinitive" (đủ... để).
3. "So old that" là cách diễn đạt chuẩn để nói về mức độ của tính từ "old" dẫn đến một kết quả.
4. Sau "that" là một mệnh đề hoàn chỉnh chỉ kết quả "it cannot run the new teleconferencing software".
5. Các đáp án khác không phù hợp vì: "too" cần đi với "to-infinitive", "soon" là trạng từ chỉ thời gian, "enough" cần đi sau tính từ.
Dịch câu hỏi: Máy tính của cô Cox quá cũ đến nỗi không thể chạy phần mềm hội nghị truyền hình mới.
Dịch đáp án:
A. too (trạng từ: quá)
B. soon (trạng từ: sớm)
C. enough (trạng từ: đủ)
D. so (trạng từ: quá/rất)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4913, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6106, 4913, 106, 'Focus group participants are instructed --- the group''s discussions confidential.', 'keeping', 'keeps', 'to keep', 'having kept', 'C', 'Đáp án C (to keep) là đúng vì các lý do sau:
1. Sau động từ "instruct" ở thể bị động, ta dùng động từ nguyên mẫu có "to" (to-infinitive).
2. Cấu trúc "be instructed to do something" là cấu trúc chuẩn để diễn đạt việc được chỉ dẫn làm gì.
3. "To keep" trong trường hợp này là động từ nguyên mẫu đóng vai trò bổ ngữ cho động từ "instruct".
4. "Keep" được theo sau bởi tân ngữ (the group''s discussions) và tính từ bổ ngữ (confidential), tạo thành cấu trúc "keep something + tính từ".
5. Các đáp án khác không phù hợp vì: "keeping" là danh động từ, "keeps" là động từ ngôi thứ 3 số ít, "having kept" là phân từ hoàn thành.
Dịch câu hỏi: Những người tham gia nhóm thảo luận được chỉ dẫn giữ bí mật các cuộc thảo luận của nhóm.
Dịch đáp án:
A. keeping (danh động từ: việc giữ)
B. keeps (động từ ngôi thứ 3 số ít: giữ)
C. to keep (động từ nguyên mẫu có to: để giữ)
D. having kept (động từ hoàn thành: đã giữ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4914, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6107, 4914, 107, 'Visit our Web site to learn the sources of the ingredients used ----- our products.', 'from', 'to', 'in', 'up', 'C', 'Đáp án C (in) là đúng vì các lý do sau:
1. Đây là cấu trúc "be used in something" (được sử dụng trong cái gì), là cấu trúc cố định trong tiếng Anh.
2. Động từ "use" khi đi với giới từ "in" có nghĩa là "được sử dụng như một phần/thành phần của cái gì".
3. Trong ngữ cảnh này, các thành phần nguyên liệu được sử dụng như một phần của sản phẩm.
4. Câu này sử dụng cấu trúc bị động "be used" và cần một giới từ phù hợp để kết nối với "our products".
5. Các đáp án khác không phù hợp vì: "from" chỉ nguồn gốc, "to" chỉ hướng đến, "up" không phù hợp với ngữ cảnh.
Dịch câu hỏi: Hãy truy cập trang web của chúng tôi để tìm hiểu nguồn gốc của các thành phần được sử dụng trong các sản phẩm của chúng tôi.
Dịch đáp án:
A. from (giới từ: từ)
B. to (giới từ: đến)
C. in (giới từ: trong)
D. up (giới từ: lên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4915, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6108, 4915, 108, 'Donors to nonprofit organizations receive ---- tax benefits under the province''s new tax policy.', 'dominant', 'generous', 'enthusiastic', 'respective', 'B', 'Đáp án B (generous) là đúng vì các lý do sau:
1. Chúng ta cần một tính từ mang tính chất đánh giá để bổ nghĩa cho cụm danh từ "tax benefits".
2. "Generous" (hào phóng) là tính từ phù hợp về nghĩa để mô tả các lợi ích thuế đáng kể.
3. Trong ngữ cảnh chính sách thuế, "generous benefits" là cụm từ thường được sử dụng để chỉ những ưu đãi thuế lớn.
4. Vị trí của tính từ này là trước danh từ "benefits", tuân theo quy tắc về trật tự từ trong tiếng Anh.
5. Các đáp án khác không phù hợp vì: "dominant" (chiếm ưu thế) không phù hợp với ngữ cảnh ưu đãi thuế, "enthusiastic" (nhiệt tình) không phù hợp để mô tả lợi ích, "respective" (tương ứng) không phù hợp với ngữ cảnh.
Dịch câu hỏi: Những nhà tài trợ cho các tổ chức phi lợi nhuận nhận được những lợi ích thuế hào phóng theo chính sách thuế mới của tỉnh.
Dịch đáp án:
A. dominant (tính từ: chiếm ưu thế)
B. generous (tính từ: hào phóng)
C. enthusiastic (tính từ: nhiệt tình)
D. respective (tính từ: tương ứng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4916, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6109, 4916, 109, '----- the renovation of its office is completed, most Montes Corporation employees will be working remotely.', 'Finally', 'During', 'Around', 'Until', 'D', 'Đáp án D (Until) là đúng vì các lý do sau:
1. Đây là câu phức với hai mệnh đề, cần một liên từ thời gian để kết nối.
2. "Until" (cho đến khi) là liên từ thời gian phù hợp để diễn tả một hành động sẽ tiếp tục cho đến khi một điều kiện nào đó được hoàn thành.
3. Cấu trúc "until + mệnh đề" được sử dụng để chỉ thời điểm kết thúc của một hành động.
4. Trong ngữ cảnh này, nhân viên sẽ làm việc từ xa cho đến khi việc cải tạo văn phòng hoàn thành.
5. Các đáp án khác không phù hợp vì: "Finally" là trạng từ chỉ kết thúc, "During" là giới từ chỉ thời gian đang diễn ra, "Around" là giới từ chỉ xung quanh hoặc khoảng thời gian.
Dịch câu hỏi: Cho đến khi việc cải tạo văn phòng hoàn thành, hầu hết nhân viên của Tập đoàn Montes sẽ làm việc từ xa.
Dịch đáp án:
A. Finally (trạng từ: cuối cùng)
B. During (giới từ: trong khi)
C. Around (giới từ: xung quanh)
D. Until (liên từ: cho đến khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4917, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6110, 4917, 110, 'The Steppville Star Award honors citizens who have made ----- contributions to the community.', 'meaningful', 'mean', 'meaning', 'meaningfully', 'A', 'Đáp án A (meaningful) là đúng vì các lý do sau:
1. Ta cần một tính từ để bổ nghĩa cho danh từ "contributions".
2. "Meaningful" là tính từ được tạo thành từ danh từ "meaning" + hậu tố "-ful", có nghĩa là "có ý nghĩa".
3. Trong cấu trúc này, tính từ đứng trước danh từ để mô tả tính chất của danh từ đó.
4. Vị trí này cần một từ miêu tả chất lượng hay bản chất của đóng góp.
5. Các đáp án khác không phù hợp vì: "mean" là động từ hoặc tính từ (có nghĩa khác), "meaning" là danh từ hoặc phân từ hiện tại, "meaningfully" là trạng từ.
Dịch câu hỏi: Giải thưởng Ngôi sao Steppville vinh danh những công dân đã có những đóng góp có ý nghĩa cho cộng đồng.
Dịch đáp án:
A. meaningful (tính từ: có ý nghĩa)
B. mean (động từ/tính từ: nghĩa là/keo kiệt)
C. meaning (danh từ: ý nghĩa)
D. meaningfully (trạng từ: một cách có ý nghĩa)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4918, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6111, 4918, 111, 'The Drayton supermarket chain claims that the ------ of its frozen foods is carried out via state-of-the-art refrigerated trucks.', 'variety', 'transport', 'appraisal', 'freshness', 'B', 'Đáp án B (transport) là đúng vì các lý do sau:
1. Ngữ cảnh đề cập đến việc sử dụng xe tải đông lạnh hiện đại, liên quan đến việc vận chuyển.
2. "Transport" là danh từ chỉ hoạt động vận chuyển, phân phối hàng hóa.
3. Cấu trúc "be carried out" (được thực hiện) thường đi với danh từ chỉ hoạt động hoặc quy trình.
4. Cụm từ "via state-of-the-art refrigerated trucks" (thông qua xe tải đông lạnh hiện đại) phù hợp với ngữ cảnh vận chuyển.
5. Các đáp án khác không phù hợp về nghĩa: "variety" (sự đa dạng), "appraisal" (sự đánh giá), "freshness" (độ tươi) không thể "được thực hiện qua xe tải".
Dịch câu hỏi: Chuỗi siêu thị Drayton tuyên bố rằng việc vận chuyển thực phẩm đông lạnh của họ được thực hiện thông qua các xe tải đông lạnh hiện đại nhất.
Dịch đáp án:
A. variety (danh từ: sự đa dạng)
B. transport (danh từ: sự vận chuyển)
C. appraisal (danh từ: sự đánh giá)
D. freshness (danh từ: độ tươi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4919, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6112, 4919, 112, 'The Lytleton Historical Archives prohibits the ----- of its collection by visitors.', 'photocopier', 'photocopying', 'photocopied', 'photocopy', 'B', 'Đáp án B (photocopying) là đúng vì các lý do sau:
1. Sau mạo từ "the", ta cần một danh từ hoặc danh động từ.
2. "Photocopying" là danh động từ (gerund) được tạo từ động từ "photocopy", chỉ hành động sao chép.
3. Trong ngữ cảnh này, cần một từ chỉ hoạt động/hành động bị cấm.
4. Cấu trúc "prohibit the + gerund" là cấu trúc phổ biến để diễn tả việc cấm một hành động.
5. Các đáp án khác không phù hợp vì: "photocopier" là danh từ chỉ máy photo, "photocopied" là quá khứ phân từ, "photocopy" là danh từ hoặc động từ nguyên mẫu.
Dịch câu hỏi: Kho lưu trữ Lịch sử Lytleton cấm việc sao chép bộ sưu tập của nó bởi khách tham quan.
Dịch đáp án:
A. photocopier (danh từ: máy photocopy)
B. photocopying (danh động từ: việc photocopy)
C. photocopied (quá khứ phân từ: đã được photocopy)
D. photocopy (danh từ/động từ: bản photocopy/photocopy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4920, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6113, 4920, 113, 'Even though the company has been outperformed by competitors in recent years, it is still -----.', 'profit', 'profited', 'profitably', 'profitable', 'D', 'Đáp án D (profitable) là đúng vì các lý do sau:
1. Sau động từ "be" (is), ta cần một tính từ để bổ nghĩa cho chủ ngữ "it" (công ty).
2. "Profitable" là tính từ có nghĩa "có lợi nhuận", phù hợp để mô tả tình trạng tài chính của công ty.
3. Cấu trúc "be + tính từ" là cấu trúc phổ biến để diễn tả trạng thái.
4. Các từ khác không phù hợp vì: "profit" là danh từ hoặc động từ, "profited" là động từ quá khứ, "profitably" là trạng từ.
5. Về ngữ nghĩa, câu này diễn tả mặc dù công ty bị cạnh tranh vượt trội nhưng vẫn có lợi nhuận.
Dịch câu hỏi: Mặc dù công ty đã bị các đối thủ cạnh tranh vượt trội trong những năm gần đây, nó vẫn có lợi nhuận.
Dịch đáp án:
A. profit (danh từ/động từ: lợi nhuận/sinh lời)
B. profited (động từ quá khứ: đã sinh lời)
C. profitably (trạng từ: một cách có lợi nhuận)
D. profitable (tính từ: có lợi nhuận)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4921, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6114, 4921, 114, 'Market research shows that most people ---- Hardwood Gym''s membership fee pricing very reasonable.', 'appreciate', 'consider', 'agree', 'view', 'B', 'Đáp án B (consider) là đúng vì các lý do sau:
1. Cấu trúc "consider something + tính từ" được dùng để diễn tả ý kiến/đánh giá về một điều gì đó.
2. Động từ "consider" có thể được theo sau bởi tân ngữ (membership fee pricing) và tính từ bổ ngữ (reasonable).
3. Trong ngữ cảnh này, ta cần một động từ chỉ sự đánh giá, nhận định.
4. Các đáp án khác không phù hợp vì không thể kết hợp trực tiếp với tính từ "reasonable": "appreciate" cần tân ngữ, "agree" cần giới từ "with", "view" thường đi với "as".
Dịch câu hỏi: Nghiên cứu thị trường cho thấy hầu hết mọi người cho rằng giá phí thành viên của phòng tập Hardwood rất hợp lý.
Dịch đáp án:
A. appreciate (động từ: đánh giá cao)
B. consider (động từ: cho rằng)
C. agree (động từ: đồng ý)
D. view (động từ: xem xét)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4922, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6115, 4922, 115, 'Regardless of ---- goods are being stored there at the moment, the warehouse must be secured at night.', 'either', 'while', 'whether', 'following', 'C', 'Đáp án C (whether) là đúng vì các lý do sau:
1. "Regardless of" là một thành ngữ mang nghĩa "bất kể", thường được theo sau bởi "whether" khi dẫn dắt một mệnh đề.
2. Cấu trúc "regardless of whether + mệnh đề" được dùng để diễn tả một điều kiện không ảnh hưởng đến kết quả.
3. "Whether" là liên từ thích hợp để diễn đạt sự lựa chọn hoặc khả năng.
4. Các đáp án khác không phù hợp về mặt ngữ pháp và ngữ nghĩa: "either" cần "or", "while" chỉ thời gian, "following" là trạng từ/giới từ chỉ sự tiếp theo.
Dịch câu hỏi: Bất kể hiện tại đang lưu trữ hàng hóa gì, kho hàng phải được bảo vệ an toàn vào ban đêm.
Dịch đáp án:
A. either (đại từ: một trong hai)
B. while (liên từ: trong khi)
C. whether (liên từ: có... hay không)
D. following (trạng từ/giới từ: tiếp theo)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4923, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6116, 4923, 116, 'The social media platform Connectra deletes all of the data associated with ------ user accounts after one year.', 'inactive', 'indirect', 'unlikely', 'unmistakable', 'A', 'Đáp án A (inactive) là đúng vì các lý do sau:
1. Ta cần một tính từ để bổ nghĩa cho cụm danh từ "user accounts".
2. "Inactive" (không hoạt động) là tính từ phù hợp về nghĩa để mô tả tài khoản người dùng không còn sử dụng.
3. Tiền tố "in-" được thêm vào "active" để tạo nghĩa phủ định, chỉ trạng thái không hoạt động.
4. Về ngữ nghĩa, việc xóa dữ liệu của các tài khoản không hoạt động là một chính sách phổ biến.
5. Các đáp án khác không phù hợp về nghĩa: "indirect" (gián tiếp), "unlikely" (không chắc xảy ra), "unmistakable" (không thể nhầm lẫn).
Dịch câu hỏi: Nền tảng mạng xã hội Connectra xóa tất cả dữ liệu liên quan đến các tài khoản người dùng không hoạt động sau một năm.
Dịch đáp án:
A. inactive (tính từ: không hoạt động)
B. indirect (tính từ: gián tiếp)
C. unlikely (tính từ: không chắc xảy ra)
D. unmistakable (tính từ: không thể nhầm lẫn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4924, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6117, 4924, 117, 'The ability to broadcast live video through Showvia is the platform''s most ---- requested feature.', 'potentially', 'sharply', 'perfectly', 'heavily', 'D', 'Đáp án D (heavily) là đúng vì các lý do sau:
1. Ta cần một trạng từ để bổ nghĩa cho phân từ "requested" (được yêu cầu).
2. "Heavily" (nhiều/mạnh mẽ) kết hợp với "requested" tạo thành cụm từ "được yêu cầu nhiều nhất".
3. Cụm từ "most heavily requested" là một cách diễn đạt phổ biến để chỉ tính năng được người dùng yêu cầu nhiều nhất.
4. Các đáp án khác không phù hợp về nghĩa trong ngữ cảnh này: "potentially" (tiềm năng), "sharply" (sắc nét), "perfectly" (hoàn hảo).
5. Khi nói về mức độ yêu cầu hoặc sử dụng, "heavily" là trạng từ thích hợp nhất.
Dịch câu hỏi: Khả năng phát video trực tiếp qua Showvia là tính năng được yêu cầu nhiều nhất của nền tảng này.
Dịch đáp án:
A. potentially (trạng từ: tiềm năng)
B. sharply (trạng từ: sắc nét)
C. perfectly (trạng từ: hoàn hảo)
D. heavily (trạng từ: nặng nề/nhiều)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4925, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6118, 4925, 118, 'An efficiency consultant could help us ---- parts of our production process that should be simplified.', 'identify', 'prevent', 'ensure', 'excel', 'A', 'Đáp án A (identify) là đúng vì các lý do sau:
1. Ta cần một động từ chỉ hành động xác định/nhận diện các phần cần được đơn giản hóa.
2. "Identify" có nghĩa là nhận diện, xác định - phù hợp với vai trò của một chuyên gia tư vấn hiệu quả.
3. Cấu trúc ngữ pháp: "identify + (danh từ) + that should be + (quá khứ phân từ)".
4. Về ngữ nghĩa, việc xác định các phần cần cải thiện là bước đầu tiên trong quá trình tối ưu hóa.
5. Các đáp án khác không phù hợp về nghĩa: "prevent" (ngăn chặn), "ensure" (đảm bảo), "excel" (vượt trội).
Dịch câu hỏi: Một chuyên gia tư vấn hiệu quả có thể giúp chúng tôi xác định những phần trong quy trình sản xuất cần được đơn giản hóa.
Dịch đáp án:
A. identify (động từ: xác định, nhận diện)
B. prevent (động từ: ngăn chặn)
C. ensure (động từ: đảm bảo)
D. excel (động từ: vượt trội)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4926, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6119, 4926, 119, 'There is ---- more skilled at attracting positive media attention than our new head of public relations.', 'other', 'anyone', 'whoever', 'no one', 'D', 'Đáp án D (no one) là đúng vì các lý do sau:
1. Đây là cấu trúc so sánh nhất với dạng phủ định "There is no one more... than..." (Không có ai... hơn...).
2. "No one" là đại từ phủ định, được sử dụng để chỉ không có người nào.
3. Cấu trúc này nhấn mạnh rằng người đứng đầu quan hệ công chúng mới có kỹ năng thu hút sự chú ý của truyền thông tốt nhất.
4. Các đáp án khác không phù hợp về ngữ pháp và ngữ nghĩa: "other" cần mạo từ, "anyone" thường dùng trong câu hỏi/phủ định, "whoever" dùng trong mệnh đề quan hệ.
Dịch câu hỏi: Không có ai giỏi thu hút sự chú ý tích cực của truyền thông hơn trưởng bộ phận quan hệ công chúng mới của chúng tôi.
Dịch đáp án:
A. other (tính từ/đại từ: khác)
B. anyone (đại từ: bất kỳ ai)
C. whoever (đại từ quan hệ: bất cứ ai)
D. no one (đại từ phủ định: không ai)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4927, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6120, 4927, 120, '---- the projector in the conference room broke down, the IT team was able to fix it before the meeting was scheduled to start.', 'Unless', 'Besides', 'Although', 'Amid', 'C', 'Đáp án C (Although) là đúng vì các lý do sau:
1. Ta cần một liên từ chỉ sự nhượng bộ/tương phản giữa hai sự việc.
2. "Although" (mặc dù) là liên từ thích hợp để diễn tả một tình huống trái ngược với kỳ vọng.
3. Cấu trúc "Although + mệnh đề, + mệnh đề chính" diễn tả sự tương phản giữa sự cố và khả năng giải quyết kịp thời.
4. Các đáp án khác không phù hợp: "Unless" (trừ khi) dùng cho điều kiện, "Besides" (bên cạnh đó) là phó từ, "Amid" (giữa) là giới từ.
Dịch câu hỏi: Mặc dù máy chiếu trong phòng họp bị hỏng, đội IT đã có thể sửa nó trước khi cuộc họp được lên lịch bắt đầu.
Dịch đáp án:
A. Unless (liên từ: trừ khi)
B. Besides (phó từ/giới từ: bên cạnh đó)
C. Although (liên từ: mặc dù)
D. Amid (giới từ: giữa)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4928, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6121, 4928, 121, 'Ms. Cardenas is trying to improve her career —-- by earning additional qualifications.', 'intentions', 'prospects', 'selections', 'obstacles', 'B', 'Đáp án B (prospects) là đúng vì các lý do sau:
1. Ta cần một danh từ để hoàn thành cụm từ "career prospects" (triển vọng nghề nghiệp).
2. "Prospects" là danh từ chỉ khả năng/triển vọng trong tương lai, phù hợp với ngữ cảnh cải thiện sự nghiệp.
3. Cụm từ "career prospects" là một collocation (kết hợp từ) phổ biến trong tiếng Anh.
4. Việc học thêm bằng cấp nhằm cải thiện triển vọng nghề nghiệp là logic về mặt ngữ nghĩa.
5. Các đáp án khác không phù hợp: "intentions" (ý định), "selections" (sự lựa chọn), "obstacles" (trở ngại).
Dịch câu hỏi: Cô Cardenas đang cố gắng cải thiện triển vọng nghề nghiệp của mình bằng cách đạt thêm các bằng cấp.
Dịch đáp án:
A. intentions (danh từ: ý định)
B. prospects (danh từ: triển vọng)
C. selections (danh từ: sự lựa chọn)
D. obstacles (danh từ: trở ngại)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4929, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6122, 4929, 122, 'Many reviews of Silver Sword give special praise to its director for the thrilling action scene --- the end of the film.', 'near', 'except', 'like', 'upon', 'A', 'Đáp án A (near) là đúng vì các lý do sau:
1. Ta cần một giới từ chỉ vị trí/thời điểm để mô tả vị trí của cảnh hành động trong phim.
2. "Near" (gần) là giới từ thích hợp để chỉ vị trí gần cuối phim.
3. Cụm "near the end" là cách diễn đạt phổ biến để chỉ thời điểm gần kết thúc của một sự kiện/tác phẩm.
4. Các đáp án khác không phù hợp: "except" (ngoại trừ), "like" (giống như), "upon" (ngay khi) không phù hợp về ngữ nghĩa.
Dịch câu hỏi: Nhiều bài đánh giá về phim Silver Sword đặc biệt khen ngợi đạo diễn về cảnh hành động gay cấn gần cuối phim.
Dịch đáp án:
A. near (giới từ: gần)
B. except (giới từ: ngoại trừ)
C. like (giới từ/động từ: giống như/thích)
D. upon (giới từ: ngay khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4930, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6123, 4930, 123, 'The interior decorator explained that measuring the lobby''s dimensions ---- was an important part of her planning process.', 'highly', 'precisely', 'extremely', 'identically', 'B', 'Đáp án B (precisely) là đúng vì các lý do sau:
1. Ta cần một trạng từ bổ nghĩa cho động từ "measuring", chỉ cách thức đo đạc.
2. "Precisely" (chính xác) là trạng từ phù hợp với công việc đo đạc kích thước.
3. Trong thiết kế nội thất, độ chính xác của phép đo là yếu tố quan trọng.
4. Các đáp án khác không phù hợp về ngữ nghĩa: "highly" (cao độ), "extremely" (cực kỳ), "identically" (giống hệt nhau).
Dịch câu hỏi: Nhà thiết kế nội thất giải thích rằng việc đo đạc kích thước sảnh một cách chính xác là một phần quan trọng trong quá trình lập kế hoạch của cô ấy.
Dịch đáp án:
A. highly (trạng từ: cao độ)
B. precisely (trạng từ: chính xác)
C. extremely (trạng từ: cực kỳ)
D. identically (trạng từ: giống hệt nhau)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4931, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6124, 4931, 124, '---- its limited collection of artworks, the Zielinski Museum consistently attracts remarkable numbers of visitors.', 'Among', 'Along with', 'In spite of', 'Rather than', 'C', 'Đáp án C (In spite of) là đúng vì các lý do sau:
1. Ta cần một cụm giới từ chỉ sự nhượng bộ giữa bộ sưu tập hạn chế và số lượng khách tham quan ấn tượng.
2. "In spite of" (mặc dù) là cụm giới từ thích hợp để diễn tả điều trái ngược với kỳ vọng.
3. Cấu trúc "In spite of + cụm danh từ" được dùng để diễn đạt sự tương phản.
4. Các đáp án khác không phù hợp: "Among" (giữa), "Along with" (cùng với), "Rather than" (thay vì) không diễn tả được ý nghĩa nhượng bộ.
Dịch câu hỏi: Mặc dù có bộ sưu tập tác phẩm nghệ thuật hạn chế, Bảo tàng Zielinski vẫn liên tục thu hút số lượng khách tham quan đáng kể.
Dịch đáp án:
A. Among (giới từ: giữa)
B. Along with (cụm giới từ: cùng với)
C. In spite of (cụm giới từ: mặc dù)
D. Rather than (cụm liên từ: thay vì)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4932, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6125, 4932, 125, 'Now that Mr. Jo —--- from the firm, another attorney at South Bay Law Group is overseeing our legal affairs.', 'departing', 'has departed', 'to depart', 'depart', 'B', 'Đáp án B (has departed) là đúng vì các lý do sau:
1. Sau "Now that" (bây giờ khi mà), ta cần một mệnh đề hoàn chỉnh với động từ ở thì thích hợp.
2. Thì hiện tại hoàn thành "has departed" được dùng để chỉ một hành động đã hoàn thành và có ảnh hưởng đến hiện tại.
3. Cấu trúc "Now that + mệnh đề" chỉ một tình huống hiện tại là kết quả của một hành động đã xảy ra.
4. Các đáp án khác không phù hợp về thì và dạng động từ: "departing" là hiện tại phân từ, "to depart" là động từ nguyên mẫu, "depart" là động từ nguyên thể.
Dịch câu hỏi: Giờ đây khi ông Jo đã rời khỏi công ty, một luật sư khác tại Tập đoàn Luật South Bay đang phụ trách các vấn đề pháp lý của chúng tôi.
Dịch đáp án:
A. departing (hiện tại phân từ: đang rời khỏi)
B. has departed (hiện tại hoàn thành: đã rời khỏi)
C. to depart (động từ nguyên mẫu có to: rời khỏi)
D. depart (động từ nguyên thể: rời khỏi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4933, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6126, 4933, 126, 'The state environmental agency has made ----- progress in reducing air pollution.', 'impressively', 'impressed', 'impressive', 'impressions', 'C', 'Đáp án C (impressive) là đúng vì các lý do sau:
1. Ta cần một tính từ để bổ nghĩa cho danh từ "progress".
2. "Impressive" (ấn tượng) là tính từ thích hợp để mô tả sự tiến bộ đáng kể.
3. Cấu trúc "make + tính từ + progress" là cấu trúc phổ biến để diễn tả sự tiến bộ.
4. Các đáp án khác không phù hợp về ngữ pháp: "impressively" là trạng từ, "impressed" là quá khứ phân từ, "impressions" là danh từ số nhiều.
5. Về ngữ nghĩa, "impressive progress" diễn tả sự tiến bộ đáng kể trong việc giảm ô nhiễm không khí.
Dịch câu hỏi: Cơ quan môi trường nhà nước đã đạt được tiến bộ ấn tượng trong việc giảm ô nhiễm không khí.
Dịch đáp án:
A. impressively (trạng từ: một cách ấn tượng)
B. impressed (quá khứ phân từ: đã ấn tượng)
C. impressive (tính từ: ấn tượng)
D. impressions (danh từ số nhiều: những ấn tượng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4934, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6127, 4934, 127, 'Please draw up a list of alternative dinner venues ----- the clients do not want to go to the Italian restaurant.', 'after all', 'apart from', 'which', 'in case', 'D', 'Đáp án D (in case) là đúng vì các lý do sau:
1. Ta cần một cụm từ chỉ mục đích phòng ngừa cho một tình huống có thể xảy ra.
2. "In case" (phòng trường hợp) là cụm từ thích hợp để diễn tả việc chuẩn bị cho một khả năng.
3. Cấu trúc "in case + mệnh đề" được dùng để nói về việc chuẩn bị cho một tình huống có thể xảy ra.
4. Các đáp án khác không phù hợp: "after all" (dù sao), "apart from" (ngoài ra), "which" (đại từ quan hệ) không diễn tả được ý nghĩa phòng ngừa.
Dịch câu hỏi: Hãy lập danh sách các địa điểm ăn tối thay thế phòng trường hợp khách hàng không muốn đến nhà hàng Ý.
Dịch đáp án:
A. after all (cụm từ: dù sao)
B. apart from (cụm từ: ngoài ra)
C. which (đại từ quan hệ: cái mà)
D. in case (cụm từ: phòng trường hợp)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4935, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6128, 4935, 128, '----- the popularity of the résumé writing workshop, the library will decide whether to hold other events for job seekers.', 'Depending on', 'Just as', 'Not only', 'Provided that', 'A', 'Đáp án A (Depending on) là đúng vì các lý do sau:
1. Ta cần một cụm từ chỉ sự phụ thuộc vào một điều kiện để ra quyết định.
2. "Depending on" (tùy thuộc vào) là cụm từ thích hợp để diễn tả việc quyết định dựa trên một yếu tố.
3. Cấu trúc "Depending on + danh từ" được dùng để chỉ một điều kiện ảnh hưởng đến kết quả.
4. Các đáp án khác không phù hợp: "Just as" (giống như), "Not only" (không chỉ), "Provided that" (với điều kiện là) không diễn tả được ý nghĩa phụ thuộc.
Dịch câu hỏi: Tùy thuộc vào mức độ phổ biến của hội thảo viết sơ yếu lý lịch, thư viện sẽ quyết định có tổ chức các sự kiện khác cho người tìm việc hay không.
Dịch đáp án:
A. Depending on (cụm từ: tùy thuộc vào)
B. Just as (cụm từ: giống như)
C. Not only (cụm từ: không chỉ)
D. Provided that (cụm từ: với điều kiện là)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4936, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6129, 4936, 129, 'No other salesperson at Jinkwang Laboratories can speak ----- about the advantages of its medical devices than Vincent Cobb.', 'persuasive', 'persuasively', 'most persuasive', 'more persuasively', 'D', 'Đáp án D (more persuasively) là đúng vì các lý do sau:
1. Đây là cấu trúc so sánh hơn với "No other... than" (Không ai... hơn).
2. Ta cần một trạng từ ở dạng so sánh hơn để bổ nghĩa cho động từ "speak".
3. "More persuasively" là dạng so sánh hơn của trạng từ "persuasively", diễn tả cách nói thuyết phục hơn.
4. Các đáp án khác không phù hợp: "persuasive" là tính từ, "persuasively" là trạng từ thường, "most persuasive" là dạng so sánh nhất.
Dịch câu hỏi: Không có nhân viên bán hàng nào khác tại Phòng thí nghiệm Jinkwang có thể nói thuyết phục hơn về những ưu điểm của các thiết bị y tế của công ty so với Vincent Cobb.
Dịch đáp án:
A. persuasive (tính từ: thuyết phục)
B. persuasively (trạng từ: một cách thuyết phục)
C. most persuasive (tính từ so sánh nhất: thuyết phục nhất)
D. more persuasively (trạng từ so sánh hơn: thuyết phục hơn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4937, 215, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6130, 4937, 130, 'Whitlow Engineering ---- a summer internship program for university students for the past five years.', 'is conducting', 'will be conducting', 'has been conducting', 'would have been conducting', 'C', 'Đáp án C (has been conducting) là đúng vì các lý do sau:
1. Cụm "for the past five years" (trong 5 năm qua) là dấu hiệu của thì hiện tại hoàn thành tiếp diễn.
2. Thì này diễn tả một hành động bắt đầu trong quá khứ, tiếp tục đến hiện tại và có thể tiếp tục trong tương lai.
3. "Has been conducting" là động từ ở thì hiện tại hoàn thành tiếp diễn, phù hợp với ngữ cảnh.
4. Các đáp án khác không phù hợp: "is conducting" (hiện tại tiếp diễn), "will be conducting" (tương lai tiếp diễn), "would have been conducting" (điều kiện hoàn thành tiếp diễn).
Dịch câu hỏi: Công ty Whitlow Engineering đã tổ chức chương trình thực tập hè cho sinh viên đại học trong 5 năm qua.
Dịch đáp án:
A. is conducting (hiện tại tiếp diễn: đang tổ chức)
B. will be conducting (tương lai tiếp diễn: sẽ tổ chức)
C. has been conducting (hiện tại hoàn thành tiếp diễn: đã và đang tổ chức)
D. would have been conducting (điều kiện hoàn thành tiếp diễn: hẳn đã tổ chức)');;

-- Data for 2025 Test1 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4938, 216, NULL, NULL, '(May 19) - Meat substitutes, which are plant-based foods with meat-like tastes and textures, are currently enjoying a boom nationwide. The market for such products grew nearly 50% in the past year, and they can now be found in a 131....... lange of settings, from supermarket shelves to fast-food restaurants.
A major reason for this trend is changing consumer 132...... affected by concern about the environmental impact of livestock farming. According to Ivan Ortega, spokesperson for the Plant Based Food Association, the lower prices and better taste of newer meat substitutes have contributed 133........ . Mr. Ortega believes that this sector of the industry will only continue to grow in the future. 134........... .', '(Ngày 19 tháng 5) - Các sản phẩm thay thế thịt, là thực phẩm có nguồn gốc thực vật với hương vị và kết cấu giống thịt, hiện đang được ưa chuộng trên toàn quốc. Thị trường cho những sản phẩm như vậy đã tăng trưởng gần 50% trong năm qua, và hiện chúng có thể được tìm thấy ở nhiều môi trường khác nhau, từ các kệ siêu thị đến nhà hàng đồ ăn nhanh.
Một lý do chính cho xu hướng này là sự thay đổi sở thích của người tiêu dùng bị ảnh hưởng bởi mối quan tâm về tác động môi trường của việc chăn nuôi gia súc. Theo Ivan Ortega, người phát ngôn của Hiệp hội Thực phẩm Thực vật, giá thành thấp hơn và hương vị ngon hơn của các sản phẩm thay thế thịt mới đã góp phần vào điều này. Ông Ortega tin rằng lĩnh vực này của ngành công nghiệp sẽ tiếp tục phát triển trong tương lai.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6131, 4938, 131, NULL, 'total', 'broad', 'constant', 'numerous', 'B', 'A. total (tổng số)
B. broad (rộng rãi)
C. constant (liên tục)
D. numerous (nhiều)
Đáp án đúng là B (broad).
Giải thích:
''Broad range'' là cụm từ phổ biến trong tiếng Anh, có nghĩa là ''phạm vi rộng rãi''.
Từ ''broad'' (tính từ) kết hợp với ''range'' tạo thành cụm từ diễn tả sự đa dạng và phổ biến của sản phẩm thay thế thịt.
Ngữ cảnh của câu nói về việc sản phẩm có mặt ở nhiều nơi (''various settings''), từ siêu thị đến nhà hàng đồ ăn nhanh.
Các đáp án khác không phù hợp:
''Total'' không đi với ''range'' trong ngữ cảnh này.
''Constant'' không phù hợp vì đang nói về phạm vi không gian.
''Numerous'' không kết hợp với ''range'' để diễn tả phạm vi rộng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6132, 4938, 132, NULL, 'to prefer', 'preferably', 'preferring', 'preferences', 'D', 'A. to prefer (để thích)
B. preferably (tốt hơn hết là)
C. preferring (đang thích)
D. preferences (sở thích)
Đáp án đúng là D (preferences).
Giải thích:
Cấu trúc câu cần một danh từ (noun) để làm chủ ngữ sau ''consumer''.
''Consumer preferences'' (sở thích của người tiêu dùng) là cụm danh từ phổ biến trong tiếng Anh.
Ngữ cảnh nói về sự thay đổi trong sở thích của người tiêu dùng (''changing consumer preferences'').
Các đáp án khác không phù hợp:
''To prefer'' là động từ nguyên mẫu, không phù hợp làm tính từ bổ nghĩa.
''Preferably'' là trạng từ, không thể làm danh từ.
''Preferring'' là động từ dạng -ing, không phù hợp trong ngữ cảnh này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6133, 4938, 133, NULL, 'as well', 'already', 'so far', 'mainly', 'A', 'A. as well (cũng như)
B. already (đã rồi)
C. so far (cho đến nay)
D. mainly (chủ yếu)
Đáp án đúng là A (as well).
Giải thích:
''As well'' là cụm từ dùng để thêm thông tin, có nghĩa là ''cũng như vậy, cũng thế''.
Câu văn nói về các yếu tố góp phần vào xu hướng này, sau khi đã đề cập đến giá thành thấp hơn.
Cấu trúc ''have contributed as well'' là cách tự nhiên để thêm thông tin.
Các đáp án khác không phù hợp:
''Already'' không phù hợp vì không nói về việc đã xảy ra.
''So far'' không phù hợp với cấu trúc của câu.
''Mainly'' không phù hợp vì đang liệt kê các yếu tố ngang bằng nhau.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6134, 4938, 134, NULL, 'Furthermore, his health has improved since the removal of meat from his diet.', 'His association also includes makers of dairy alternatives such as soy milk.', 'Therefore, he feels the process for making meat substitutes is too complex.', 'In fact, he predicts that substitutes will equal meat in popularity within 15 years.', 'D', 'A. Furthermore, his health has improved since the removal of meat from his diet. (Hơn nữa, sức khỏe của ông ấy đã cải thiện kể từ khi loại bỏ thịt khỏi chế độ ăn)
B. His association also includes makers of dairy alternatives such as soy milk. (Hiệp hội của ông ấy cũng bao gồm các nhà sản xuất các sản phẩm thay thế sữa như sữa đậu nành)
C. Therefore, he feels the process for making meat substitutes is too complex. (Do đó, ông ấy cảm thấy quá trình sản xuất các sản phẩm thay thế thịt quá phức tạp)
D. In fact, he predicts that substitutes will equal meat in popularity within 15 years. (Thực tế, ông ấy dự đoán rằng các sản phẩm thay thế sẽ ngang bằng với thịt về độ phổ biến trong vòng 15 năm)
Đáp án đúng là D.
Giải thích:
Câu D phù hợp nhất với ngữ cảnh và logic của đoạn văn:
- Liên quan đến chủ đề chính về sự phát triển của thị trường thay thế thịt
- Kết nối với câu trước về niềm tin của ông Ortega về sự phát triển trong tương lai
- Cụm ''In fact'' (thực tế) phù hợp để đưa ra một dự đoán cụ thể
Các đáp án khác không phù hợp:
A: Đề cập đến sức khỏe cá nhân, không liên quan đến xu hướng thị trường
B: Chuyển sang chủ đề khác (sữa thay thế)
C: Mâu thuẫn với tone tích cực của đoạn văn về sự phát triển ngành');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4939, 216, NULL, NULL, '5 February
Lou Spellman
Senior Project Manager
North Perth Developers
349 Doyle Street
North Perth WA 6006
Dear Mr. Spellman,
Thank you for your invitation to bid for the contract for Stonefield Apartments. Enclosed you will find our bid, which 135....... the price for which we could install the desired plumbing and a prospective timeline. I believe you will find it to be a very attractive 136........ .
137......... . We are currently finishing up the installation of all plumbing in the four-story Nowlin Hotel on schedule and under budget. 138........ that, we equipped all 32 restrooms of the Rishley Center with reliable touchless sinks and toilets.
It would be my pleasure to speak with you about our bid or the Packard & Bowers crew. I can be reached at 9291 4998.
Sincerely,
Bella Packard
Packard & Bowers Plumbing
Encl.', 'Ngày 5 tháng 2
Lou Spellman
Giám đốc Dự án Cấp cao
North Perth Developers
349 Doyle Street
North Perth WA 6006
Kính gửi ông Spellman,
Cảm ơn ông đã mời chúng tôi tham gia đấu thầu hợp đồng cho Chung cư Stonefield. Đính kèm là hồ sơ thầu của chúng tôi, trong đó chỉ rõ giá cả cho việc lắp đặt hệ thống ống nước theo yêu cầu và khung thời gian dự kiến. Tôi tin rằng ông sẽ thấy đây là một đề xuất rất hấp dẫn.
Chúng tôi hiện đang hoàn thiện việc lắp đặt toàn bộ hệ thống ống nước trong khách sạn Nowlin bốn tầng đúng tiến độ và dưới ngân sách. Trước đó, chúng tôi đã trang bị cho tất cả 32 phòng tắm của Trung tâm Rishley với bồn rửa và nhà vệ sinh cảm ứng đáng tin cậy.
Tôi rất sẵn lòng trao đổi với ông về hồ sơ thầu hoặc đội ngũ Packard & Bowers. Ông có thể liên hệ với tôi theo số 9291 4998.
Trân trọng,
Bella Packard
Packard & Bowers Plumbing
Đính kèm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6135, 4939, 135, NULL, 'specify', 'specified', 'specifies', 'is specifying', 'C', 'A. specify (chỉ định)
B. specified (đã chỉ định)
C. specifies (chỉ định - chia động từ số ít)
D. is specifying (đang chỉ định)
Đáp án đúng là C (specifies).
Giải thích:
Cấu trúc câu yêu cầu động từ chia ở ngôi thứ 3 số ít để phù hợp với chủ ngữ ''which'' (đại diện cho ''bid'').
''Which specifies'' là mệnh đề quan hệ bổ nghĩa cho danh từ ''bid''.
Thì hiện tại đơn được sử dụng vì đây là một sự thật hiện tại.
Các đáp án khác không phù hợp:
''Specify'' là động từ nguyên mẫu, chưa chia.
''Specified'' là quá khứ phân từ, không phù hợp làm động từ chính.
''Is specifying'' là hiện tại tiếp diễn, không phù hợp với ngữ cảnh thông tin trong hồ sơ dự thầu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6136, 4939, 136, NULL, 'design', 'proposal', 'building', 'appliance', 'B', 'A. design (thiết kế)
B. proposal (đề xuất)
C. building (tòa nhà)
D. appliance (thiết bị)
Đáp án đúng là B (proposal).
Giải thích:
''Proposal'' phù hợp với ngữ cảnh của một lá thư đấu thầu.
Cụm từ ''attractive proposal'' (đề xuất hấp dẫn) là cách diễn đạt chuyên nghiệp trong kinh doanh.
Nội dung thư đang đề cập đến một hồ sơ dự thầu.
Các đáp án khác không phù hợp:
''Design'' không phù hợp vì đang nói về đề xuất giá cả và thời gian.
''Building'' không phù hợp vì đang nói về tài liệu đề xuất.
''Appliance'' không phù hợp với ngữ cảnh của câu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6137, 4939, 137, NULL, 'The bid invitation said that the deadline for submissions is 6 February.', 'The computer-generated image of the complex on your Web site is stunning.', 'I would also like to highlight our recent work on similar projects.', 'My business partner is familiar with your company.', 'C', 'A. The bid invitation said that the deadline for submissions is 6 February. (Thư mời thầu nói rằng hạn chót nộp hồ sơ là ngày 6 tháng 2)
B. The computer-generated image of the complex on your Web site is stunning. (Hình ảnh 3D của khu phức hợp trên trang web của bạn thật ấn tượng)
C. I would also like to highlight our recent work on similar projects. (Tôi cũng muốn nhấn mạnh các công trình gần đây tương tự của chúng tôi)
D. My business partner is familiar with your company. (Đối tác kinh doanh của tôi quen thuộc với công ty của ông)
Đáp án đúng là C.
Giải thích:
Câu C phù hợp nhất vì:
- Liên kết logic với đoạn sau về kinh nghiệm làm việc (khách sạn Nowlin và Trung tâm Rishley)
- Phù hợp với mục đích thuyết phục của lá thư đấu thầu
- Cách chuyển ý tự nhiên để giới thiệu năng lực của công ty
Các đáp án khác không phù hợp:
A: Không cần thiết nhắc lại thông tin có trong thư mời thầu
B: Không liên quan đến mục đích chính của lá thư
D: Thông tin không chuyên nghiệp và không liên quan');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6138, 4939, 138, NULL, 'Prior to', 'After', 'Instead of', 'Concerning', 'A', 'A. Prior to (Trước đó)
B. After (Sau đó)
C. Instead of (Thay vì)
D. Concerning (Về việc)
Đáp án đúng là A (Prior to).
Giải thích:
''Prior to'' là cụm giới từ chỉ thời gian, có nghĩa là ''trước đó''.
Cấu trúc câu cần một cụm từ chỉ thứ tự thời gian để liên kết hai dự án.
Văn cảnh đang liệt kê các dự án theo thứ tự thời gian: dự án hiện tại (Nowlin Hotel) và dự án trước đó (Rishley Center).
Các đáp án khác không phù hợp:
''After'' không phù hợp vì thứ tự thời gian sẽ bị đảo ngược.
''Instead of'' không phù hợp vì không có sự thay thế giữa hai dự án.
''Concerning'' không phù hợp vì không phải là quan hệ về chủ đề mà là về thời gian.;');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4940, 216, NULL, NULL, 'To: Nate Hopkins <nate.hopkins@genmail.com>
From: Akari Kaneko <a.kaneko@flurry.com>
Date: July 27
Subject: Announcement
Dear Mr. Hopkins,
I am sorry to announce that the Flurry app will cease 139...... on September 1. From that date, it will not be possible to stream, download, or listen to podcasts through Flurry. Also, you will no longer have access to data associated with 140....... Flurry account, such as downloaded episodes, lists of favorite shows, and listening preferences. If you would like to save this information and export it to another podcast app, please 141........ the instructions at www.flurry.com/help/394. 142........ .. Questions may be directed to the Flurry customer service center, which will remain open through September 1. We apologize again, and thank you for using Flurry until now.
Sincerely,
Akari Kaneko
President, Flurry, Inc.', 'Gửi: Nate Hopkins <nate.hopkins@genmail.com>
Từ: Akari Kaneko <a.kaneko@flurry.com>
Ngày: 27 tháng 7
Chủ đề: Thông báo
Kính gửi ông Hopkins,
Tôi rất tiếc phải thông báo rằng ứng dụng Flurry sẽ chấm dứt hoạt động vào ngày 1 tháng 9. Kể từ ngày đó, sẽ không thể phát trực tuyến, tải xuống hoặc nghe podcast thông qua Flurry. Ngoài ra, bạn sẽ không còn quyền truy cập vào dữ liệu liên quan đến tài khoản Flurry của mình, chẳng hạn như các tập đã tải xuống, danh sách chương trình yêu thích và tùy chọn nghe. Nếu bạn muốn lưu thông tin này và xuất sang ứng dụng podcast khác, vui lòng tham khảo hướng dẫn tại www.flurry.com/help/394. Nếu không, bạn không cần thực hiện thêm bất kỳ hành động nào. Các câu hỏi có thể được gửi đến trung tâm dịch vụ khách hàng của Flurry, sẽ tiếp tục mở cửa đến ngày 1 tháng 9. Chúng tôi xin lỗi một lần nữa và cảm ơn bạn đã sử dụng Flurry cho đến nay.
Trân trọng,
Akari Kaneko
Chủ tịch, Flurry, Inc.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6139, 4940, 139, NULL, 'operate', 'operated', 'operative', 'operations', 'D', 'A. operate (hoạt động - động từ)
B. operated (đã hoạt động - quá khứ phân từ)
C. operative (có hiệu lực - tính từ)
D. operations (hoạt động - danh từ số nhiều)
Đáp án đúng là D (operations).
Giải thích:
''Cease'' (chấm dứt) là động từ cần một danh từ làm tân ngữ.
Cụm từ ''cease operations'' (chấm dứt hoạt động) là cụm từ phổ biến trong thông báo kinh doanh.
Danh từ số nhiều ''operations'' phù hợp vì đề cập đến nhiều hoạt động khác nhau của ứng dụng.
Các đáp án khác không phù hợp:
''Operate'' là động từ, không thể làm tân ngữ.
''Operated'' là động từ quá khứ, không phù hợp làm tân ngữ.
''Operative'' là tính từ, không thể làm tân ngữ sau ''cease''.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6140, 4940, 140, NULL, 'my', 'their', 'your', 'our', 'C', 'A. my (của tôi)
B. their (của họ)
C. your (của bạn)
D. our (của chúng tôi)
Đáp án đúng là C (your).
Giải thích:
Trong thư gửi cho khách hàng, ''your'' là tính từ sở hữu phù hợp nhất vì:
- Đang đề cập đến tài khoản của người nhận thư (Mr. Hopkins)
- Phù hợp với ngữ cảnh thư thông báo cho khách hàng
- Nhất quán với việc sử dụng ''you'' trong các câu trước và sau
Các đáp án khác không phù hợp:
''My'' không hợp lý vì không phải tài khoản của người viết
''Their'' không phù hợp vì đang nói trực tiếp với người nhận
''Our'' không đúng vì đang nói về tài khoản của khách hàng');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6141, 4940, 141, NULL, 'unveil', 'consult', 'refer', 'contact', 'B', 'A. unveil (tiết lộ)
B. consult (tham khảo)
C. refer (tham chiếu)
D. contact (liên hệ)
Đáp án đúng là B (consult).
Giải thích:
''Consult the instructions'' (tham khảo hướng dẫn) là cách diễn đạt phù hợp nhất khi:
- Đề cập đến việc đọc và làm theo hướng dẫn
- Thường được sử dụng trong ngữ cảnh kỹ thuật và hướng dẫn người dùng
- Mang tính chính thức và chuyên nghiệp
Các đáp án khác không phù hợp:
''Unveil'' không phù hợp với ''instructions''
''Refer'' thường đi với ''to'' và ít dùng trực tiếp với ''instructions''
''Contact'' không dùng với ''instructions''');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6142, 4940, 142, NULL, 'Otherwise, no action is necessary on your part.', 'Afterward, Flurry should run more smoothly.', 'Our new parent company offers its own podcast app.', 'We see you have not downloaded the most recent update.', 'A', 'A. Otherwise, no action is necessary on your part. (Nếu không, bạn không cần thực hiện thêm bất kỳ hành động nào)
B. Afterward, Flurry should run more smoothly. (Sau đó, Flurry sẽ chạy mượt mà hơn)
C. Our new parent company offers its own podcast app. (Công ty mẹ mới của chúng tôi cung cấp ứng dụng podcast riêng)
D. We see you have not downloaded the most recent update. (Chúng tôi thấy bạn chưa tải bản cập nhật mới nhất)
Đáp án đúng là A.
Giải thích:
Lựa chọn A phù hợp nhất vì:
- Nối tiếp logic với câu trước về việc lưu và xuất dữ liệu
- ''Otherwise'' (nếu không) là liên từ phù hợp để chỉ ra phương án thay thế
- Phù hợp với tính chất thông báo chính thức
Các đáp án khác không phù hợp:
B: Không hợp lý vì ứng dụng sẽ ngừng hoạt động
C: Không liên quan đến nội dung thông báo về việc ngừng hoạt động
D: Không phù hợp với ngữ cảnh thông báo đóng cửa');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4941, 216, NULL, NULL, 'OAKRIDGE (November 22) - Oakridge authorities were notified yesterday that intercity express bus operator Swiftbus 143....... service to its stop in the city. The company specified December 1 as the effective date of the change. Located in front of Oakridge Plaza, the soon-to-be 144........ stop was added to the line running between Bealett and Knappton earlier this year. 145........ . In the notice, Swiftbus cited low ridership as the reason for the decision. 146...... also expressed a willingness to reestablish service to the city if there is an increase in demand in the future.', 'OAKRIDGE (22 tháng 11) - Chính quyền Oakridge đã được thông báo hôm qua rằng nhà điều hành xe buýt liên thành phố Swiftbus sẽ dừng dịch vụ tại điểm dừng trong thành phố. Công ty đã chỉ định ngày 1 tháng 12 là ngày có hiệu lực của thay đổi này. Nằm trước Oakridge Plaza, điểm dừng sắp bị ngừng hoạt động đã được thêm vào tuyến chạy giữa Bealett và Knappton vào đầu năm nay. Tuyến đường này đã phục vụ tới hai chuyến mỗi ngày, tùy thuộc vào ngày. Trong thông báo, Swiftbus đã nêu lý do của quyết định là lượng hành khách thấp. Công ty cũng bày tỏ sự sẵn sàng thiết lập lại dịch vụ cho thành phố nếu có sự gia tăng nhu cầu trong tương lai.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6143, 4941, 143, NULL, 'will be halting', 'has been halting', 'has halted', 'is halted', 'A', 'A. will be halting (sẽ dừng)
B. has been halting (đã và đang dừng)
C. has halted (đã dừng)
D. is halted (bị dừng)
Đáp án đúng là A (will be halting).
Giải thích:
''Will be halting'' là hình thức tương lai tiếp diễn phù hợp vì:
- Thông báo về một quyết định sẽ có hiệu lực trong tương lai (December 1)
- Phù hợp với ngữ cảnh thông báo chính thức về thay đổi dịch vụ
- Thể hiện kế hoạch đã được xác định
Các đáp án khác không phù hợp:
''Has been halting'' không đúng vì việc dừng chưa xảy ra
''Has halted'' không đúng vì dịch vụ vẫn đang hoạt động
''Is halted'' không phù hợp vì là thụ động và chưa xảy ra');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6144, 4941, 144, NULL, 'granted', 'inspected', 'expanded', 'discontinued', 'D', 'A. granted (được cấp)
B. inspected (được kiểm tra)
C. expanded (được mở rộng)
D. discontinued (bị ngừng)
Đáp án đúng là D (discontinued).
Giải thích:
''Soon-to-be discontinued'' (sắp bị ngừng) phù hợp nhất vì:
- Phù hợp với ngữ cảnh về việc dừng dịch vụ
- ''Soon-to-be'' kết hợp với ''discontinued'' chỉ một sự thay đổi sắp xảy ra
- Thể hiện tính chính thức của thông báo
Các đáp án khác không phù hợp:
''Granted'' không phù hợp với ngữ cảnh dừng dịch vụ
''Inspected'' không liên quan đến nội dung
''Expanded'' mâu thuẫn với việc dừng dịch vụ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6145, 4941, 145, NULL, 'The route has been served up to twice daily, depending on the day.', 'Oakridge officials are seeking more ways to improve its transit services.', 'The plaza has since become the cultural center of Oakridge.', 'Both destinations have strong manufacturing industries.', 'A', 'A. The route has been served up to twice daily, depending on the day. (Tuyến đường này đã phục vụ tới hai chuyến mỗi ngày, tùy thuộc vào ngày)
B. Oakridge officials are seeking more ways to improve its transit services. (Các quan chức Oakridge đang tìm kiếm thêm cách để cải thiện dịch vụ vận chuyển)
C. The plaza has since become the cultural center of Oakridge. (Plaza đã trở thành trung tâm văn hóa của Oakridge)
D. Both destinations have strong manufacturing industries. (Cả hai điểm đến đều có ngành công nghiệp sản xuất mạnh)
Đáp án đúng là A.
Giải thích:
Lựa chọn A phù hợp nhất vì:
- Cung cấp thông tin bổ sung về tần suất hoạt động của tuyến đường
- Liên quan trực tiếp đến chủ đề chính của thông báo
- Giúp người đọc hiểu rõ hơn về dịch vụ sắp bị ngừng
Các đáp án khác không phù hợp:
B: Không liên quan đến nội dung thông báo về việc ngừng dịch vụ
C: Đề cập đến thông tin không liên quan về plaza
D: Không liên quan đến việc ngừng dịch vụ xe buýt');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6146, 4941, 146, NULL, 'He', 'It', 'Some', 'We', 'B', 'A. He (anh ấy)
B. It (nó - công ty)
C. Some (một số)
D. We (chúng tôi)
Đáp án đúng là B (It).
Giải thích:
''It'' phù hợp nhất vì:
- Đề cập đến công ty Swiftbus (một tổ chức)
- Trong tiếng Anh, tổ chức thường được thay thế bằng đại từ ''it''
- Phù hợp với phong cách viết tin tức chính thức
Các đáp án khác không phù hợp:
''He'' không phù hợp vì đang nói về công ty, không phải cá nhân
''Some'' không phù hợp vì đang đề cập đến một chủ thể cụ thể (công ty Swiftbus)
''We'' không phù hợp vì đây là tin tức khách quan, không phải thông báo từ công ty
Ngoài ra, từ ''it'' còn duy trì tính nhất quán với câu trước đó đã đề cập đến Swiftbus như chủ ngữ của câu.');;

-- Data for 2025 Test1 Part 7
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4942, 217, NULL, NULL, 'STATON GRILL CORPORATE HEADQUARTERS
UPCOMING WEBINAR
Topic: Customer Satisfaction
Speaker: Manuel Rios, founder of Rios Restaurant Consulting and author of Front of House: The Importance of Hospitality in Restaurants
Date: 19 September, 10:00 A.M.
Venue: www.v-meet.co.uk (Event ID: 093 657 893)
This Webinar is mandatory for Staton Grill employees who interact directly with patrons. Computer access is required. Please join by 9:55 to prevent delays.', 'TRUNG TÂM ĐIỀU HÀNH STATON GRILL
HỘI THẢO TRỰC TUYẾN SẮP TỚI
Chủ đề: Sự hài lòng của khách hàng
Diễn giả: Manuel Rios, người sáng lập Rios Restaurant Consulting và tác giả cuốn Front of House: The Importance of Hospitality in Restaurants
Ngày: 19 Tháng 9, 10:00 sáng
Địa điểm: www.v-meet.co.uk (ID Sự kiện: 093 657 893)
Hội thảo này bắt buộc đối với nhân viên Staton Grill trực tiếp tương tác với khách hàng. Yêu cầu có máy tính. Vui lòng tham gia trước 9:55 để tránh chậm trễ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6147, 4942, 147, 'Who will most likely attend the Webinar?', 'Kitchen staff', 'Menu developers', 'Servers and cashiers', 'Potential franchise owners', 'C', 'Đáp án đúng là C.
Giải thích:
Theo thông báo, "This Webinar is mandatory for Staton Grill employees who interact directly with patrons" (Buổi hội thảo này bắt buộc đối với nhân viên Staton Grill trực tiếp tương tác với khách hàng). Nhân viên phục vụ và thu ngân là những người thường xuyên tiếp xúc trực tiếp với khách hàng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ai là người có khả năng tham dự Webinar nhất?
A. Nhân viên nhà bếp (Kitchen staff)
B. Người phát triển thực đơn (Menu developers)
C. Nhân viên phục vụ và thu ngân (Servers and cashiers)
D. Chủ nhượng quyền tiềm năng (Potential franchise owners)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6148, 4942, 148, 'What are attendees asked to do?', 'Use a company computer', 'Read a book beforehand', 'Provide a personal ID code', 'Enter the Web venue early', 'D', 'Đáp án đúng là D.
Giải thích:
Thông báo có ghi rõ "Please join by 9:55 to prevent delays" (Vui lòng tham gia trước 9:55 để tránh chậm trễ). Điều này yêu cầu người tham dự vào sớm trước giờ bắt đầu.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Người tham dự được yêu cầu làm gì?
A. Sử dụng máy tính công ty
B. Đọc sách trước
C. Cung cấp mã ID cá nhân
D. Vào địa điểm Web sớm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4943, 217, NULL, NULL, 'E-Mail message
From: Niran Chaiya
To: Rebecca Briggs
Subject: Information
Date: January 25
Attachment:  List
Dear Ms. Briggs,
As I promised in our phone conversation, attached you will find a list of available houses and apartments in Bangkok. All of the properties fit the criteria you provided and are priced within your company''s rental allowance for relocated executives. I have included details such as square footage and amenities, as well as interior photos and neighborhood maps.
Please review the list and tell me which property you prefer so that I can begin preparing the necessary paperwork. Some of these places are quite desirable, so I recommend acting quickly.
Please call me if any questions come up.
Sincerely,
Niran Chaiya
Corporate Relocation Specialist
Chao Phraya Services', 'Tin nhắn email
Từ: Niran Chaiya
Đến: Rebecca Briggs
Chủ đề: Thông tin
Ngày: 25 tháng 1
Tệp đính kèm: Danh sách
Kính gửi cô Briggs,
Như tôi đã hứa trong cuộc điện thoại của chúng ta, đính kèm bạn sẽ tìm thấy danh sách các căn nhà và căn hộ có sẵn ở Bangkok. Tất cả các bất động sản đều phù hợp với tiêu chí bạn đưa ra và có giá nằm trong phạm vi trợ cấp thuê nhà của công ty dành cho các giám đốc điều hành được điều chuyển. Tôi đã bao gồm các chi tiết như diện tích và tiện nghi, cũng như hình ảnh nội thất và bản đồ khu vực.
Vui lòng xem xét danh sách và cho tôi biết bất động sản nào bạn thích để tôi có thể bắt đầu chuẩn bị các giấy tờ cần thiết. Một số địa điểm này khá đáng mong muốn, vì vậy tôi khuyên bạn nên hành động nhanh chóng.
Vui lòng gọi cho tôi nếu có bất kỳ câu hỏi nào.
Trân trọng,
Niran Chaiya
Chuyên gia Di chuyển Doanh nghiệp
Dịch vụ Chao Phraya');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6149, 4943, 149, 'What is one purpose of the e-mail?', 'To describe some of the difficulties of relocation', 'To promote a new benefit for executives', 'To arrange payment of an allowance', 'To supply information on housing options', 'D', 'Đáp án đúng là D.
Giải thích:
Email có mục đích cung cấp thông tin về các lựa chọn nhà ở, được thể hiện qua câu "attached you will find a list of available houses and apartments in Bangkok" (đính kèm bạn sẽ tìm thấy danh sách các căn nhà và căn hộ có sẵn ở Bangkok).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Một trong những mục đích của email là gì?
A. Mô tả một số khó khăn của việc di chuyển
B. Quảng bá một phúc lợi mới cho các giám đốc
C. Sắp xếp việc thanh toán trợ cấp
D. Cung cấp thông tin về các lựa chọn nhà ở');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6150, 4943, 150, 'What is Ms. Briggs asked to do?', 'Confirm a timeline', 'Communicate a preference', 'Visit some properties', 'Collect some documents', 'B', 'Đáp án đúng là B.
Giải thích:
Trong email có yêu cầu "Please review the list and tell me which property you prefer" (Vui lòng xem xét danh sách và cho tôi biết bất động sản nào bạn thích), điều này yêu cầu cô Briggs thông báo sự lựa chọn của mình.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Cô Briggs được yêu cầu làm gì?
A. Xác nhận thời gian biểu
B. Thông báo sự ưa thích
C. Đến thăm một số bất động sản
D. Thu thập một số tài liệu');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4944, 217, NULL, NULL, 'Don''t have time to go to your local Songmin clinic for a minor medical issue?
E-visits are a convenient way to get help wherever you are. Simply follow these steps:
1. Go to our Web site (www.songminhealth.com) and sign in.
2. Hover your mouse over the "E-visits" tab and select "Start an E-visit" from the drop-down menu.
3. Answer the questions on the resulting form about your symptoms and concerns. Be as clear and specific as possible. Submit the form.
4. Check your e-mail inbox for the response from a Songmin doctor. It may include advice, a referral for testing, or a prescription for medication.
5. If you do not receive a response within two business hours, or if there is a change in your symptoms, please call our assistance line at 1-800-555-0138.
SONGMIN HEALTH', 'Không có thời gian đến phòng khám Songmin tại địa phương của bạn cho một vấn đề y tế nhỏ?
Thăm khám điện tử (E-visits) là một cách thuận tiện để nhận được sự giúp đỡ ở bất cứ đâu. Chỉ cần làm theo các bước sau:
1. Truy cập trang web của chúng tôi (www.songminhealth.com) và đăng nhập.
2. Di chuột qua tab "E-visits" và chọn "Start an E-visit" từ menu thả xuống.
3. Trả lời các câu hỏi trong biểu mẫu về các triệu chứng và mối quan tâm của bạn. Hãy trình bày rõ ràng và cụ thể nhất có thể. Gửi biểu mẫu.
4. Kiểm tra hộp thư email của bạn để nhận phản hồi từ bác sĩ Songmin. Nó có thể bao gồm lời khuyên, giấy giới thiệu xét nghiệm, hoặc đơn thuốc.
5. Nếu bạn không nhận được phản hồi trong vòng hai giờ làm việc, hoặc nếu có thay đổi về triệu chứng của bạn, vui lòng gọi đường dây hỗ trợ của chúng tôi theo số 1-800-555-0138.
SONGMIN HEALTH');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6151, 4944, 151, 'Who are the instructions most likely intended for?', 'Healthcare patients', 'Clinical doctors', 'Medical records clerks', 'Technical support providers', 'A', 'Đáp án đúng là A.
Giải thích:
Hướng dẫn này dành cho bệnh nhân vì:
1. Câu hỏi mở đầu "Don''t have time to go to your local Songmin clinic for a minor medical issue?" nhắm đến người cần khám bệnh.
2. Hướng dẫn mô tả cách bệnh nhân có thể nhận được sự giúp đỡ y tế thông qua E-visit.
3. Các bước hướng dẫn về cách điền form triệu chứng và chờ phản hồi từ bác sĩ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Hướng dẫn này có khả năng dành cho ai nhất?
A. Bệnh nhân chăm sóc sức khỏe
B. Bác sĩ lâm sàng
C. Nhân viên hồ sơ y tế
D. Nhà cung cấp hỗ trợ kỹ thuật');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6152, 4944, 152, 'What is the reader asked to do?', 'Give clear recommendations', 'Respond to an e-mail message', 'Fill out a document online', 'Make an appointment in advance', 'C', 'Đáp án đúng là C.
Giải thích:
Theo hướng dẫn bước 3: "Answer the questions on the resulting form about your symptoms and concerns" (Trả lời các câu hỏi trong biểu mẫu về các triệu chứng và mối quan tâm của bạn), người đọc được yêu cầu điền vào một biểu mẫu trực tuyến.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Người đọc được yêu cầu làm gì?
A. Đưa ra khuyến nghị rõ ràng
B. Trả lời email
C. Điền vào tài liệu trực tuyến
D. Đặt lịch hẹn trước');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4945, 217, NULL, NULL, 'Yi-Seul Kwak [1:16 p.M.]
Stacy, are you back from lunch yet?
Stacy Ulrich [1:17 P.M.]
Yes, I''m at my desk. What''s up?
Yi-Seul Kwak [1:18 P.M.]
I''m at the store picking up supplies for the office, and I need a favor. You know those yellow notepads that the lawyers like to use?
I just realized I''m not sure how many of them we have left.
Stacy Ulrich [1:19 p.M.]
OK, I''ll find out. Where should I look?
Yi-Seul Kwak 11:20 P.M
They''re in a box in the supply room.
Stacy Ulrich [1:22 P.M.]
The supply room is full of boxes.
Yi-Seul Kwak [1:23 P.M.]
Oh, right. It''s on a bottom shelf near the door, and "Bynum, Inc." is printed on the sides.
Stacy Ulrich [1:24 p.M.]
I found it. There''s only one notepad in here.
Yi-Seul Kwak [1:25 p.M.]
That''s definitely not enough! I''m glad I checked.
Thank you, Stacy!', 'Yi-Seul Kwak [1:16 chiều]
Stacy, bạn đã đi ăn trưa về chưa?
Stacy Ulrich [1:17 chiều]
Vâng, tôi đang ở bàn làm việc. Có chuyện gì vậy?
Yi-Seul Kwak [1:18 chiều]
Tôi đang ở cửa hàng mua đồ dùng cho văn phòng, và tôi cần nhờ một việc. Bạn biết những tập giấy màu vàng mà các luật sư thích dùng không?
Tôi vừa nhận ra là không chắc còn bao nhiêu cái.
Stacy Ulrich [1:19 chiều]
OK, tôi sẽ kiểm tra. Tôi nên tìm ở đâu?
Yi-Seul Kwak [11:20 chiều]
Chúng ở trong một hộp trong phòng vật tư.
Stacy Ulrich [1:22 chiều]
Phòng vật tư đầy những hộp.
Yi-Seul Kwak [1:23 chiều]
À, phải rồi. Nó ở kệ dưới cùng gần cửa, và có in "Bynum, Inc." ở các cạnh.
Stacy Ulrich [1:24 chiều]
Tôi đã tìm thấy. Chỉ còn một tập giấy trong này.
Yi-Seul Kwak [1:25 chiều]
Chắc chắn là không đủ rồi! May là tôi đã kiểm tra.
Cảm ơn bạn, Stacy!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6153, 4945, 153, 'What problem does Ms. Kwak have?', 'She will be unavailable to accept a delivery.', 'She is uncertain about an inventory level.', 'She cannot locate some supplies.', 'She is unable to use her desk.', 'B', 'Đáp án đúng là B.
Giải thích:
Ms. Kwak nói "I just realized I''m not sure how many of them we have left" (Tôi vừa nhận ra là không chắc còn bao nhiêu cái), thể hiện cô ấy không chắc chắn về số lượng tồn kho của notepads.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Vấn đề của cô Kwak là gì?
A. Cô ấy sẽ không có mặt để nhận hàng
B. Cô ấy không chắc chắn về mức tồn kho
C. Cô ấy không thể tìm thấy một số vật tư
D. Cô ấy không thể sử dụng bàn làm việc');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6154, 4945, 154, 'At 1:22 P.M., what does Ms. Ulrich imply when she writes, "The supply room is full of boxes"?', 'She needs a more detailed description.', 'Ms. Kwak should not make a purchase.', 'She cannot find space for some objects.', 'Ms. Kwak will have to organize the room.', 'A', 'Đáp án đúng là A.
Giải thích:
Khi Stacy Ulrich nói "The supply room is full of boxes", cô ấy ngầm ý rằng cần được mô tả chi tiết hơn để tìm được đúng hộp, vì có quá nhiều hộp trong phòng. Điều này được chứng minh khi sau đó Yi-Seul Kwak phải cung cấp thêm thông tin chi tiết về vị trí và đặc điểm của hộp.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 1:22 chiều, cô Ulrich ngụ ý gì khi viết "Phòng vật tư đầy những hộp"?
A. Cô ấy cần mô tả chi tiết hơn
B. Cô Kwak không nên mua hàng
C. Cô ấy không thể tìm thấy chỗ cho một số vật dụng
D. Cô Kwak sẽ phải sắp xếp lại phòng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4946, 217, NULL, NULL, 'Trail Ride Associate Needed
Morris Falls Guest Ranch is seeking a horseback riding enthusiast to assist with our popular trail ride program for guests. Duties of this full-time position include teaching guests how to prepare horses for rides, leading small groups of riders along trails on and near the ranch, and handling general horse-care tasks in our barn.
Applicants must be able to demonstrate high-level horseback riding skills. Other qualifications include having done at least six months of paid or volunteer work in a horse barn and possession of a cheerful, friendly personality. Weekend availability is a must, and the successful candidate should expect to be scheduled for at least one weekend shift per week.
To apply, send an e-mail entitled "Trail Ride Associate Application - (your name)" to contact@morrisfalls.com with your résumé and a short cover letter attached.
For details and photographs of our horse barn and horseback-riding trails, visit www.morrisfalls.com/riding.', 'Cần Cộng Tác Viên Cưỡi Ngựa Đường Mòn
Morris Falls Guest Ranch đang tìm kiếm một người đam mê cưỡi ngựa để hỗ trợ chương trình cưỡi ngựa đường mòn phổ biến của chúng tôi dành cho khách. Nhiệm vụ của vị trí toàn thời gian này bao gồm hướng dẫn khách chuẩn bị ngựa để cưỡi, dẫn dắt các nhóm nhỏ người cưỡi ngựa dọc theo các đường mòn trong và gần trang trại, và thực hiện các công việc chăm sóc ngựa nói chung trong chuồng ngựa của chúng tôi.
Ứng viên phải có khả năng thể hiện kỹ năng cưỡi ngựa cấp cao. Các yêu cầu khác bao gồm có ít nhất sáu tháng làm việc có lương hoặc tình nguyện trong chuồng ngựa và có tính cách vui vẻ, thân thiện. Khả năng làm việc cuối tuần là bắt buộc, và ứng viên được chọn nên chuẩn bị làm việc ít nhất một ca cuối tuần mỗi tuần.
Để ứng tuyển, gửi email có tiêu đề "Trail Ride Associate Application - (tên của bạn)" đến contact@morrisfalls.com với sơ yếu lý lịch và thư xin việc ngắn gọn đính kèm.
Để biết chi tiết và xem ảnh về chuồng ngựa và đường mòn cưỡi ngựa của chúng tôi, hãy truy cập www.morrisfalls.com/riding.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6155, 4946, 155, 'The word "handling" in paragraph 1, line 4, is closest in meaning to', 'touching', 'performing', 'training', 'selling', 'B', 'Đáp án đúng là B.
Giải thích:
Trong ngữ cảnh "handling general horse-care tasks", từ "handling" có nghĩa là "thực hiện" các nhiệm vụ chăm sóc ngựa nói chung, không chỉ đơn thuần là "chạm vào", "huấn luyện" hay "bán".

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Từ "handling" trong đoạn 1, dòng 4, có nghĩa gần nhất với?
A. Chạm vào
B. Thực hiện
C. Huấn luyện
D. Bán');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6156, 4946, 156, 'What is NOT mentioned as a requirement for the job?', 'A special physical ability', 'Familiarity with a certain region', 'Experience with some of its duties', 'Specific character traits', 'B', 'Đáp án đúng là B.
Giải thích:
Các yêu cầu được đề cập trong bài bao gồm:
- Khả năng thể hiện kỹ năng cưỡi ngựa cấp cao (special physical ability)
- Kinh nghiệm làm việc trong chuồng ngựa (experience)
- Tính cách vui vẻ, thân thiện (specific character traits)
Không có yêu cầu nào về việc quen thuộc với khu vực nào đó.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG được đề cập như một yêu cầu cho công việc?
A. Một khả năng thể chất đặc biệt
B. Sự quen thuộc với một khu vực nhất định
C. Kinh nghiệm với một số nhiệm vụ của nó
D. Những đặc điểm tính cách cụ thể');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6157, 4946, 157, 'According to the job posting, why should readers visit the ranch''s Web site?', 'To learn about its facilities', 'To submit an application', 'To see other job listings', 'To read about its history', 'A', 'Đáp án đúng là A.
Giải thích:
Theo bài đăng tuyển dụng: "For details and photographs of our horse barn and horseback-riding trails, visit www.morrisfalls.com/riding" (Để biết chi tiết và xem ảnh về chuồng ngựa và đường mòn cưỡi ngựa của chúng tôi, hãy truy cập www.morrisfalls.com/riding). Điều này cho thấy mục đích là để tìm hiểu về cơ sở vật chất của trang trại.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo bài đăng tuyển dụng, tại sao độc giả nên truy cập trang web của trang trại?
A. Để tìm hiểu về cơ sở vật chất
B. Để nộp đơn ứng tuyển
C. Để xem các vị trí tuyển dụng khác
D. Để đọc về lịch sử của nó');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4947, 217, NULL, NULL, 'RESERVATION CONFIRMATION
