INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6203, 4959, 3, 'Look at the picture marked number three in your test book.', 'The men are on opposite sides of a table.', 'One of the men is wrapping a box in plastic.', 'The men are moving some shelving.', 'One of the men is unpacking some stationery supplies.', 'A', 'A Những người đàn ông đang ở hai bên đối diện của một cái bàn.
