INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6208, 4964, 8, 'Where can I find art supplies?', 'Three types of paint.', 'In aisle seven.', 'To pass the time.', NULL, 'B', 'Câu hỏi: "Tôi có thể tìm đồ dùng mỹ thuật ở đâu?"
A: "Ba loại sơn"
B: "Ở lối đi số bảy"
C: "Để giết thời gian"
Giải thích: Đáp án B đúng vì câu hỏi hỏi về vị trí và đáp án B cung cấp vị trí cụ thể là lối đi số bảy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4965, 219, '2025/test2/audio/test2_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6209, 4965, 9, 'Who waters the plants in the lobby?', 'We can take the elevator.', 'Gerald does.', 'I''m not thirsty right now.', NULL, 'B', 'Câu hỏi: "Ai tưới cây ở sảnh?"
A: "Chúng ta có thể đi thang máy"
B: "Gerald làm việc đó"
C: "Bây giờ tôi không khát"
Giải thích: Đáp án B đúng vì câu hỏi hỏi về người chịu trách nhiệm tưới cây và đáp án B trả lời trực tiếp rằng Gerald là người làm việc này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4966, 219, '2025/test2/audio/test2_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6210, 4966, 10, 'Do you have a phone I could use?', 'Who was it?', 'Try this coupon.', 'I''m expecting a call.', NULL, 'C', 'Câu hỏi: "Bạn có điện thoại nào cho tôi mượn không?"
A: "Ai vậy?"
B: "Thử phiếu giảm giá này"
C: "Tôi đang đợi một cuộc gọi"
Giải thích: Đáp án C đúng vì người trả lời gián tiếp từ chối cho mượn điện thoại bằng cách giải thích họ đang đợi một cuộc gọi quan trọng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4967, 219, '2025/test2/audio/test2_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6211, 4967, 11, 'How can we welcome our summer interns?', 'We have air conditioning', 'She''s graduating in spring.', 'The team could go out to lunch together.', NULL, 'C', 'Câu hỏi: "Chúng ta có thể chào đón các thực tập sinh mùa hè như thế nào?"
A: "Chúng ta có điều hòa"
B: "Cô ấy sẽ tốt nghiệp vào mùa xuân"
C: "Cả nhóm có thể đi ăn trưa cùng nhau"
Giải thích: Đáp án C đúng vì đề xuất cả nhóm đi ăn trưa cùng nhau là cách phù hợp và thân thiện để chào đón thực tập sinh mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4968, 219, '2025/test2/audio/test2_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6212, 4968, 12, 'When will the product testing start?', 'My coworker Flora would know.', 'The third page of our report.', 'From a special laboratory.', NULL, 'A', 'Câu hỏi: "Khi nào việc kiểm tra sản phẩm sẽ bắt đầu?"
A: "Đồng nghiệp Flora của tôi sẽ biết"
B: "Trang thứ ba của báo cáo chúng ta"
C: "Từ một phòng thí nghiệm đặc biệt"
Giải thích: Đáp án A đúng vì người trả lời chuyển hướng câu hỏi đến người có thông tin chính xác là Flora, thay vì đưa ra thông tin không chắc chắn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4969, 219, '2025/test2/audio/test2_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6213, 4969, 13, 'Do you know the deadline for that project?', 'I met him at a workshop.', 'A new projector.', 'It''s not urgent.', NULL, 'C', 'Câu hỏi: "Bạn có biết thời hạn cho dự án đó không?"
A: "Tôi gặp anh ấy tại một hội thảo"
B: "Một máy chiếu mới"
C: "Nó không khẩn cấp"
Giải thích: Đáp án C đúng vì mặc dù không đưa ra thời hạn cụ thể, người trả lời cho biết dự án không khẩn cấp, ngụ ý rằng thời hạn còn dài.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4970, 219, '2025/test2/audio/test2_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6214, 4970, 14, 'What did you think of the job candidate?', 'At a recent job fair.', 'It tastes delicious.', 'I thought he was impressive.', NULL, 'C', 'Câu hỏi: "Bạn nghĩ gì về ứng viên công việc?"
A: "Tại một hội chợ việc làm gần đây"
B: "Nó có vị ngon"
C: "Tôi nghĩ anh ấy rất ấn tượng"
Giải thích: Đáp án C đúng vì câu hỏi yêu cầu ý kiến về ứng viên và đáp án C đưa ra đánh giá tích cực, trực tiếp về ứng viên.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4971, 219, '2025/test2/audio/test2_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6215, 4971, 15, 'Did you find a buyer for the Maple Street house?', 'No, it''s still on the market.', 'Yes, a sign in the front yard.', 'Twelve hundred square feet.', NULL, 'A', 'Câu hỏi: "Bạn đã tìm được người mua cho ngôi nhà ở đường Maple chưa?"
A: "Chưa, nó vẫn đang rao bán"
B: "Có, một biển hiệu ở sân trước"
C: "Một nghìn hai trăm feet vuông"
Giải thích: Đáp án A đúng vì câu trả lời cho biết rõ ràng rằng ngôi nhà vẫn chưa có người mua và đang còn rao bán trên thị trường.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4972, 219, '2025/test2/audio/test2_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6216, 4972, 16, 'What do we have to wear for the company photo shoot?', 'I''m aware of them.', 'Didn''t you read the memo?', 'Yes, he''s popular on social media.', NULL, 'B', 'Câu hỏi: "Chúng ta phải mặc gì cho buổi chụp ảnh công ty?"
A: "Tôi biết về họ"
B: "Bạn không đọc bản ghi nhớ sao?"
C: "Vâng, anh ấy nổi tiếng trên mạng xã hội"
Giải thích: Đáp án B đúng vì người trả lời gợi ý rằng thông tin về trang phục đã được gửi trong bản ghi nhớ và người hỏi nên đọc nó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4973, 219, '2025/test2/audio/test2_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6217, 4973, 17, 'That gallery''s been closed for months.', 'I hope the renovations end soon.', 'Yes, the drawer is open.', 'We''ll probably visit one.', NULL, 'A', 'Câu hỏi: "Phòng trưng bày đó đã đóng cửa nhiều tháng rồi"
A: "Tôi hy vọng việc cải tạo sẽ sớm kết thúc"
B: "Vâng, ngăn kéo đang mở"
C: "Chúng tôi có thể sẽ ghé thăm một cái"
Giải thích: Đáp án A đúng vì người trả lời giải thích lý do phòng trưng bày đóng cửa là do đang cải tạo và hy vọng sẽ sớm hoàn thành.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4974, 219, '2025/test2/audio/test2_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6218, 4974, 18, 'Could you design the event invitations?', 'A soft color scheme.', 'They''re excited to attend.', 'My vacation starts tomorrow.', NULL, 'C', 'Câu hỏi: "Bạn có thể thiết kế thiệp mời sự kiện không?"
A: "Một bảng màu nhẹ nhàng"
B: "Họ rất háo hức tham dự"
C: "Kỳ nghỉ của tôi bắt đầu vào ngày mai"
Giải thích: Đáp án C đúng vì người trả lời gián tiếp từ chối yêu cầu bằng cách cho biết họ sắp đi nghỉ, ngụ ý không thể nhận công việc này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4975, 219, '2025/test2/audio/test2_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6219, 4975, 19, 'This author''s last book was nominated for a Voss Award, right?', 'No, for some other award.', 'The top shelf.', 'A few films.', NULL, 'A', 'Câu hỏi: "Cuốn sách gần đây nhất của tác giả này được đề cử giải Voss, đúng không?"
A: "Không, là một giải thưởng khác"
B: "Kệ trên cùng"
C: "Một vài bộ phim"
Giải thích: Đáp án A đúng vì người trả lời đính chính thông tin, cho biết cuốn sách được đề cử một giải thưởng khác, không phải giải Voss.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4976, 219, '2025/test2/audio/test2_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6220, 4976, 20, 'When will the roadwork end?', 'Oh, did he?', 'More than 60 workers.', 'They''re making good progress.', NULL, 'C', 'Câu hỏi: "Khi nào công trình đường sẽ hoàn thành?"
A: "Ồ, anh ấy vậy sao?"
B: "Hơn 60 công nhân"
C: "Họ đang tiến triển tốt"
Giải thích: Đáp án C đúng vì mặc dù không đưa ra thời gian cụ thể, người trả lời cho biết công việc đang tiến triển tốt, ngụ ý công trình sẽ sớm hoàn thành.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4977, 219, '2025/test2/audio/test2_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6221, 4977, 21, 'Would you like that shirt in a larger size?', 'Thanks, it is a bit tight.', 'That''s good to know.', 'I''ll print out the sales data.', NULL, 'A', 'Câu hỏi: "Bạn có muốn áo này với kích cỡ lớn hơn không?"
A: "Cảm ơn, nó hơi chật"
B: "Tốt khi biết điều đó"
C: "Tôi sẽ in dữ liệu bán hàng"
Giải thích: Đáp án A đúng vì người trả lời đồng ý rằng họ cần size lớn hơn và giải thích lý do là vì áo hiện tại hơi chật.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4978, 219, '2025/test2/audio/test2_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6222, 4978, 22, 'There are a lot of empty seats in the theater today, aren''t there?', 'Just some soft drinks.', 'Weekdays are always quiet.', 'Here''s my ticket.', NULL, 'B', 'Câu hỏi: "Hôm nay có nhiều ghế trống trong rạp nhỉ?"
A: "Chỉ một vài đồ uống"
B: "Ngày trong tuần luôn vắng vẻ"
C: "Đây là vé của tôi"
Giải thích: Đáp án B đúng vì người trả lời giải thích lý do có nhiều ghế trống là vì đây là ngày trong tuần, thường ít khán giả hơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4979, 219, '2025/test2/audio/test2_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6223, 4979, 23, 'When can I visit the factory to see the production samples?', 'Make sure you purchase apples at the store.', 'Come by anytime next week.', 'No, that''s not the only factor.', NULL, 'B', 'Câu hỏi: "Khi nào tôi có thể đến thăm nhà máy để xem các mẫu sản xuất?"
A: "Hãy chắc chắn mua táo ở cửa hàng"
B: "Ghé qua bất cứ lúc nào trong tuần tới"
C: "Không, đó không phải là yếu tố duy nhất"
Giải thích: Đáp án B đúng vì người trả lời đưa ra thời gian cụ thể và linh hoạt cho việc thăm quan nhà máy - có thể đến bất cứ lúc nào trong tuần tới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4980, 219, '2025/test2/audio/test2_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6224, 4980, 24, 'Didn''t Ms. Oba tell us to call her when the printer was repaired?', 'Yes-we''d better call her now.', 'We sell office equipment.', 'No, that belongs to the technician.', NULL, 'A', 'Câu hỏi: "Ms. Oba không bảo chúng ta gọi cho cô ấy khi máy in được sửa sao?"
A: "Đúng vậy - chúng ta nên gọi cho cô ấy ngay"
B: "Chúng tôi bán thiết bị văn phòng"
C: "Không, cái đó thuộc về kỹ thuật viên"
Giải thích: Đáp án A đúng vì người trả lời xác nhận yêu cầu của Ms. Oba và đề xuất hành động phù hợp là gọi cho cô ấy ngay lập tức.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4981, 219, '2025/test2/audio/test2_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6225, 4981, 25, 'Will the keynote speaker arrive today, or is she flying in tomorrow?', 'They''re first-time attendees.', 'Possible speech topics.', 'She''ll get here this evening.', NULL, 'C', 'Câu hỏi: Diễn giả chính sẽ đến hôm nay, hay cô ấy sẽ bay vào ngày mai?
(A) Họ là những người tham dự lần đầu.
(B) Các chủ đề bài phát biểu có thể.
(C) Cô ấy sẽ đến đây vào tối nay.
Giải thích: Đáp án đúng là C trả lời trực tiếp rằng diễn giả sẽ đến trong hôm nay cụ thể là tối hôm nay.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4982, 219, '2025/test2/audio/test2_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6226, 4982, 26, 'What kinds of articles do you write for the magazine?', 'Through a news magazine', 'I mostly do editing', 'Thanks, we''re proud of it', NULL, 'B', 'Câu hỏi: "Bạn viết những loại bài báo gì cho tạp chí?"
A: "Thông qua một tạp chí tin tức"
B: "Tôi chủ yếu làm biên tập"
C: "Cảm ơn, chúng tôi tự hào về điều đó"
Giải thích: Đáp án B đúng vì người trả lời nói rằng họ chủ yếu làm công việc biên tập, đây là câu trả lời trực tiếp về vai trò của họ tại tạp chí.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4983, 219, '2025/test2/audio/test2_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6227, 4983, 27, 'How did you like Monday''s class?', 'I was traveling for work', 'Yes, definitely', 'A different instructor', NULL, 'A', 'Câu hỏi: "Bạn thấy lớp học hôm thứ Hai thế nào?"
A: "Tôi đang đi công tác"
B: "Vâng, chắc chắn rồi"
C: "Một giảng viên khác"
Giải thích: Đáp án A đúng vì người trả lời cho biết họ đang đi công tác, cho thấy họ không thể tham dự lớp học vào ngày hôm đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4984, 219, '2025/test2/audio/test2_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6228, 4984, 28, 'Do you want to have dinner at the restaurant in our hotel?', 'No, eight P.M. at the latest', 'Some members of the tour group', 'Does it have vegetarian options?', NULL, 'C', 'Câu hỏi: "Bạn có muốn ăn tối tại nhà hàng trong khách sạn của chúng ta không?"
A: "Không, trễ nhất là 8 giờ tối"
B: "Một số thành viên trong đoàn tham quan"
C: "Nó có các món chay không?"
Giải thích: Đáp án C đúng vì người được hỏi quan tâm đến việc nhà hàng có món chay hay không, đây là câu hỏi hợp lý trước khi quyết định đi ăn tại một nhà hàng mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4985, 219, '2025/test2/audio/test2_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6229, 4985, 29, 'If the conference room''s taken, where can we hold a meeting?', 'Half an hour ago', 'My new office is pretty big', 'The rescheduled directors'' meeting', NULL, 'B', 'Câu hỏi: "Nếu phòng họp đã có người sử dụng, chúng ta có thể tổ chức cuộc họp ở đâu?"
A: "Nửa giờ trước"
B: "Văn phòng mới của tôi khá rộng"
C: "Cuộc họp ban giám đốc đã được sắp xếp lại"
Giải thích: Đáp án B đúng vì người trả lời đề xuất một địa điểm thay thế phù hợp là văn phòng mới rộng rãi của họ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4986, 219, '2025/test2/audio/test2_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6230, 4986, 30, 'I''m not sure we''re ready to play this song at the concert', 'Let''s rehearse it some more', 'No, the venue''s on the right', 'The lead guitarist', NULL, 'A', 'Câu hỏi: "Tôi không chắc chúng ta đã sẵn sàng để trình diễn bài hát này tại buổi hòa nhạc"
A: "Hãy tập thêm nữa"
B: "Không, địa điểm ở bên phải"
C: "Người chơi guitar chính"
Giải thích: Đáp án A đúng vì khi có người bày tỏ lo ngại về sự chuẩn bị, đề xuất tập thêm là giải pháp hợp lý và xây dựng nhất.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4987, 219, '2025/test2/audio/test2_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6231, 4987, 31, 'Why don''t you load up the packages so we can deliver them?', 'There was plenty of space before', 'Most of us enjoyed it', 'They''re already in the truck', NULL, 'C', 'Câu hỏi: "Sao bạn không chất các gói hàng lên để chúng ta có thể giao chúng?"
A: "Trước đây có nhiều chỗ"
B: "Hầu hết chúng tôi đều thích nó"
C: "Chúng đã được chất lên xe tải rồi"
Giải thích: Đáp án C đúng vì người trả lời cho biết các gói hàng đã được chất lên xe tải, ngụ ý công việc đã được hoàn thành.');;

-- Data for 2025 Test2 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4988, 220, '2025/test2/audio/test2_question_32_34.mp3', NULL, 'M-Au Hi, Nancy. I just saw you through the window, so I thought l''d stop in. As a fellow Main Street business owner, I''m glad to see you''re getting the bookstore ready for reopening.
w-Am Yes, we''ll finally reopen this weekend. What do you think of the changes to the layout? We''ll have staff selling coffee and tea from that counter, and customers will be able to relax at the tables with their drinks and books.
M-Au Sounds nice. Will you serve snacks too, or just drinks?
w-Am We''ll sell a few baked goods. Oh, that reminds me I need to head out now to buy the plates and silverware we''ll need.', 'M-Au Chào Nancy. Tôi vừa nhìn thấy chị qua cửa sổ, nên tôi nghĩ mình sẽ ghé vào. Là một đồng nghiệp chủ doanh nghiệp trên phố Main, tôi rất vui khi thấy chị đang chuẩn bị mở cửa lại hiệu sách.
W-Am Vâng, cuối cùng chúng tôi sẽ mở cửa lại vào cuối tuần này. Anh nghĩ sao về những thay đổi trong cách bố trí? Chúng tôi sẽ có nhân viên bán cà phê và trà từ quầy đó, và khách hàng có thể thư giãn tại các bàn với đồ uống và sách của họ.
M-Au Nghe hay đấy. Chị sẽ phục vụ đồ ăn nhẹ nữa, hay chỉ có đồ uống?
W-Am Chúng tôi sẽ bán một số đồ nướng. Ồ, điều đó nhắc tôi nhớ là tôi cần đi mua đĩa và dao kéo chúng tôi sẽ cần.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6232, 4988, 32, 'What is the woman getting ready for?', 'A seasonal sale', 'A business''s reopening', 'A book''s publication', 'A local festival', 'B', 'Question: What is the woman getting ready for? (Người phụ nữ đang chuẩn bị cho điều gì?)
A: A seasonal sale (Đợt giảm giá theo mùa)
B: A business''s reopening (Việc mở cửa lại doanh nghiệp)
C: A book''s publication (Việc xuất bản một cuốn sách)
D: A local festival (Một lễ hội địa phương)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói rằng họ sẽ mở cửa lại vào cuối tuần này (we''ll finally reopen this weekend), và cuộc trò chuyện đề cập đến việc thay đổi cách bố trí để chuẩn bị cho việc mở cửa lại hiệu sách.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4989, 220, '2025/test2/audio/test2_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6233, 4989, 33, 'What new feature of the bookstore does the woman point out?', 'Its search kiosks', 'Its gift certificates', 'Its author readings', 'Its in-store café', 'D', 'Question: What new feature of the bookstore does the woman point out? (Tính năng mới nào của hiệu sách mà người phụ nữ chỉ ra?)
A: Its search kiosks (Các quầy tìm kiếm)
B: Its gift certificates (Phiếu quà tặng)
C: Its author readings (Các buổi đọc sách của tác giả)
D: Its in-store café (Quán cà phê trong cửa hàng)

Giải thích: Đáp án D là chính xác vì người phụ nữ nói về việc họ sẽ có nhân viên bán cà phê và trà, và khách hàng có thể thư giãn tại các bàn với đồ uống và sách (We''ll have staff selling coffee and tea from that counter, and customers will be able to relax at the tables with their drinks and books).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4990, 220, '2025/test2/audio/test2_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6234, 4990, 34, 'What will the woman most likely do next?', 'Purchase some supplies', 'Start a cleaning process', 'Hang up some signs', 'Write a job posting', 'A', 'Question: What will the woman most likely do next? (Người phụ nữ nhiều khả năng sẽ làm gì tiếp theo?)
A: Purchase some supplies (Mua một số vật dụng)
B: Start a cleaning process (Bắt đầu quá trình dọn dẹp)
C: Hang up some signs (Treo một số biển hiệu)
D: Write a job posting (Viết thông báo tuyển dụng)

Giải thích: Đáp án A là chính xác vì cuối đoạn hội thoại, người phụ nữ nói rằng cô ấy cần đi mua đĩa và dao kéo (I need to head out now to buy the plates and silverware we''ll need).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4991, 220, '2025/test2/audio/test2_question_35_37.mp3', NULL, 'M-Cn Hi, this is Marco Amato. I''m a new member at the gym. Uh, I was supposed to have a personal training session with Tim yesterday at seven, but I missed it because of rush-hour traffic.
W-Am I see. Well, I''m sorry, but our gym doesn''t issue refunds for missed sessions.
M-cn Oh, I know. I was wondering if I could move my future sessions later so that this doesn''t happen again.
W-Am Tim isn''t available later. I could schedule you with Derek, though. He has openings at eight.
M-Cn Perfect-that will give me enough time to get there after finishing work.', 'M-Cn Xin chào, tôi là Marco Amato. Tôi là thành viên mới tại phòng tập. Ừm, tôi đáng lẽ phải có một buổi tập luyện cá nhân với Tim hôm qua lúc 7 giờ, nhưng tôi đã lỡ nó vì tắc đường giờ cao điểm.
W-Am Tôi hiểu. Vâng, tôi xin lỗi, nhưng phòng tập của chúng tôi không hoàn tiền cho các buổi tập bị lỡ.
M-cn Ồ, tôi biết. Tôi tự hỏi liệu tôi có thể dời các buổi tập trong tương lai muộn hơn để điều này không xảy ra nữa không.
W-Am Tim không có lịch trống muộn hơn. Tuy nhiên, tôi có thể sắp xếp cho anh với Derek. Anh ấy có lịch trống lúc 8 giờ.
M-Cn Hoàn hảo - điều đó sẽ cho tôi đủ thời gian để đến đó sau khi tan làm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6235, 4991, 35, 'Where most likely does the woman work?', 'At a bank', 'At a medical clinic', 'At a real estate agency', 'At a fitness center', 'D', 'Question: Where most likely does the woman work? (Người phụ nữ nhiều khả năng làm việc ở đâu?)
A: At a bank (Tại ngân hàng)
B: At a medical clinic (Tại phòng khám)
C: At a real estate agency (Tại công ty bất động sản)
D: At a fitness center (Tại trung tâm thể dục)

Giải thích: Đáp án D là chính xác vì cuộc trò chuyện diễn ra tại một phòng tập gym (our gym), nơi có các buổi tập luyện cá nhân với huấn luyện viên (personal training session).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4992, 220, '2025/test2/audio/test2_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6236, 4992, 36, 'What was the man unable to do yesterday?', 'Locate a building', 'Keep an appointment', 'Transfer a payment', 'Arrange transportation', 'B', 'Question: What was the man unable to do yesterday? (Hôm qua người đàn ông đã không thể làm gì?)
A: Locate a building (Tìm một tòa nhà)
B: Keep an appointment (Giữ một cuộc hẹn)
C: Transfer a payment (Chuyển một khoản thanh toán)
D: Arrange transportation (Sắp xếp phương tiện đi lại)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng anh ấy đã lỡ buổi tập luyện cá nhân với Tim hôm qua lúc 7 giờ (I missed it) vì tắc đường giờ cao điểm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4993, 220, '2025/test2/audio/test2_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6237, 4993, 37, 'What does the man like about the woman''s suggestion?', 'It suits his schedule', 'It is good for his health', 'It will be more enjoyable', 'It will reduce a fee', 'A', 'Question: What does the man like about the woman''s suggestion? (Người đàn ông thích điều gì về đề xuất của người phụ nữ?)
A: It suits his schedule (Nó phù hợp với lịch trình của anh ấy)
B: It is good for his health (Nó tốt cho sức khỏe của anh ấy)
C: It will be more enjoyable (Nó sẽ thú vị hơn)
D: It will reduce a fee (Nó sẽ giảm phí)

Giải thích: Đáp án A là chính xác vì khi người phụ nữ đề xuất tập với Derek lúc 8 giờ, người đàn ông nói rằng điều đó hoàn hảo vì sẽ cho anh ấy đủ thời gian để đến đó sau khi tan làm (Perfect-that will give me enough time to get there after finishing work).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4994, 220, '2025/test2/audio/test2_question_38_40.mp3', NULL, 'w-Br Jutaro, this invoice from Turnbull Appliances just arrived in the mail. It''s for the installation of our new office fridge last month.
M-cn That wasn''t free?
w-Br The technicians had to do some extra work to set up the wiring. That isn''t part of the standard installation, so it cost extra.
M-cn Oh, that''s not good. The price of the fridge was close to the limit Ms. Brent approved for the replacement. With this charge, we''ve exceeded the budget.
w-Br I see. l''ll let Ms. Brent know about the situation.', 'W-Br Jutaro, hóa đơn từ Turnbull Appliances vừa đến qua thư. Nó là cho việc lắp đặt tủ lạnh văn phòng mới của chúng ta tháng trước.
M-cn Điều đó không miễn phí sao?
W-Br Các kỹ thuật viên đã phải làm thêm một số công việc để thiết lập hệ thống dây điện. Điều đó không phải là một phần của việc lắp đặt tiêu chuẩn, nên nó tốn thêm chi phí.
M-cn Ồ, điều đó không tốt. Giá của tủ lạnh đã gần đến giới hạn mà bà Brent đã phê duyệt cho việc thay thế. Với khoản phí này, chúng ta đã vượt quá ngân sách.
W-Br Tôi hiểu. Tôi sẽ thông báo cho bà Brent về tình hình.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6238, 4994, 38, 'Why does the man say, ''That wasn''t free''?', 'To show surprise', 'To explain a refusal', 'To request reimbursement', 'To emphasize an item''s value', 'A', 'Question: Why does the man say, ''That wasn''t free''? (Tại sao người đàn ông nói ''Điều đó không miễn phí''?)
A: To show surprise (Để thể hiện sự ngạc nhiên)
B: To explain a refusal (Để giải thích một sự từ chối)
C: To request reimbursement (Để yêu cầu hoàn tiền)
D: To emphasize an item''s value (Để nhấn mạnh giá trị của một món hàng)

Giải thích: Đáp án A là chính xác vì người đàn ông ngạc nhiên khi nhận được hóa đơn cho việc lắp đặt tủ lạnh, cho thấy anh ấy đã nghĩ rằng việc lắp đặt này là miễn phí.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4995, 220, '2025/test2/audio/test2_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6239, 4995, 39, 'What problem does the man report?', 'An appliance has broken down', 'Some paperwork is missing', 'Some technicians are unavailable', 'A budget has been exceeded', 'D', 'Question: What problem does the man report? (Người đàn ông báo cáo vấn đề gì?)
A: An appliance has broken down (Một thiết bị đã hỏng)
B: Some paperwork is missing (Một số giấy tờ bị mất)
C: Some technicians are unavailable (Một số kỹ thuật viên không có mặt)
D: A budget has been exceeded (Một ngân sách đã bị vượt quá)

Giải thích: Đáp án D là chính xác vì người đàn ông nói rằng với khoản phí lắp đặt bổ sung này, họ đã vượt quá ngân sách mà bà Brent đã phê duyệt (With this charge, we''ve exceeded the budget).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4996, 220, '2025/test2/audio/test2_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6240, 4996, 40, 'What does the woman say she will do?', 'Look for a manual', 'Cancel an order', 'Make some copies', 'Speak with a manager', 'D', 'Question: What does the woman say she will do? (Người phụ nữ nói cô ấy sẽ làm gì?)
A: Look for a manual (Tìm một cuốn sổ tay)
B: Cancel an order (Hủy một đơn hàng)
C: Make some copies (Tạo một số bản sao)
D: Speak with a manager (Nói chuyện với người quản lý)

Giải thích: Đáp án D là chính xác vì người phụ nữ nói rằng cô ấy sẽ thông báo cho bà Brent về tình hình (I''ll let Ms. Brent know about the situation).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4997, 220, '2025/test2/audio/test2_question_41_43.mp3', NULL, 'w-Am Hi, I''m hoping to find out how much it would cost to rent one of your buses for an event next month. It''s a two-day company retreat for the pharmacy I own. We''ll need transportation to and from a resort on Garris Mountain.
M-Cn Sure. I''ll just need a few more details. But first-did you know you can request a quote through our Web site? Many customers prefer to do that.
w-Am Oh, I tried to use the service on your Web site, but I couldn''t. I couldn''t understand how to fill out the request form.', 'W-Am Xin chào, tôi hy vọng tìm hiểu chi phí thuê một trong những xe buýt của các anh cho một sự kiện tháng sau sẽ là bao nhiêu. Đó là một chuyến nghỉ dưỡng công ty hai ngày cho hiệu thuốc mà tôi sở hữu. Chúng tôi sẽ cần phương tiện đi lại đến và từ khu nghỉ dưỡng trên núi Garris.
M-Cn Được. Tôi chỉ cần thêm một vài chi tiết. Nhưng trước tiên - chị có biết là chị có thể yêu cầu báo giá qua trang web của chúng tôi không? Nhiều khách hàng thích làm như vậy hơn.
W-Am Ồ, tôi đã cố gắng sử dụng dịch vụ trên trang web của các anh, nhưng tôi không thể. Tôi không hiểu cách điền mẫu yêu cầu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6241, 4997, 41, 'Why is the woman calling?', 'To check on an order', 'To receive a cost estimate', 'To reserve an event venue', 'To ask for a change to a route', 'B', 'Question: Why is the woman calling? (Tại sao người phụ nữ gọi điện?)
A: To check on an order (Để kiểm tra một đơn hàng)
B: To receive a cost estimate (Để nhận báo giá)
C: To reserve an event venue (Để đặt địa điểm sự kiện)
D: To ask for a change to a route (Để yêu cầu thay đổi lộ trình)

Giải thích: Đáp án B là chính xác vì ngay đầu cuộc gọi, người phụ nữ nói rằng cô ấy muốn tìm hiểu chi phí thuê xe buýt sẽ là bao nhiêu (hoping to find out how much it would cost to rent one of your buses).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4998, 220, '2025/test2/audio/test2_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6242, 4998, 42, 'What kind of business does the woman own?', 'A tour company', 'A ski resort', 'An insurance agency', 'A pharmacy', 'D', 'Question: What kind of business does the woman own? (Người phụ nữ sở hữu loại doanh nghiệp gì?)
A: A tour company (Một công ty du lịch)
B: A ski resort (Một khu nghỉ dưỡng trượt tuyết)
C: An insurance agency (Một công ty bảo hiểm)
D: A pharmacy (Một hiệu thuốc)

Giải thích: Đáp án D là chính xác vì người phụ nữ nói rằng đây là chuyến nghỉ dưỡng công ty cho hiệu thuốc mà cô ấy sở hữu (It''s a two-day company retreat for the pharmacy I own).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (4999, 220, '2025/test2/audio/test2_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6243, 4999, 43, 'Why was the woman unable to use the online service?', 'A form is confusing', 'She was not aware of it', 'A Web site was down', 'Her computer is outdated', 'A', 'Question: Why was the woman unable to use the online service? (Tại sao người phụ nữ không thể sử dụng dịch vụ trực tuyến?)
A: A form is confusing (Một mẫu đơn gây nhầm lẫn)
B: She was not aware of it (Cô ấy không biết về nó)
C: A Web site was down (Trang web bị hỏng)
D: Her computer is outdated (Máy tính của cô ấy đã cũ)

Giải thích: Đáp án A là chính xác vì người phụ nữ nói rằng cô ấy không hiểu cách điền mẫu yêu cầu (I couldn''t understand how to fill out the request form).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5000, 220, '2025/test2/audio/test2_question_44_46.mp3', NULL, 'M-Cn Hi, Tamara. Oh, I see you''re reading the new issue of the company newsletter. What''s it about?
w-Br The main feature is an announcement about a contest to design a new company logo. Any employee can submit a design, and the CEO''s going to pick the winning logo next month.
M-n How interesting! I''d like to enter.
w-Br Well, the announcement includes instructions for participants. You should take a look at them.', 'M-Cn Chào Tamara. Ồ, tôi thấy chị đang đọc số mới của bản tin công ty. Nó nói về cái gì vậy?
W-Br Nội dung chính là một thông báo về cuộc thi thiết kế logo công ty mới. Bất kỳ nhân viên nào cũng có thể gửi một thiết kế, và CEO sẽ chọn logo chiến thắng vào tháng sau.
M-n Thú vị quá! Tôi muốn tham gia.
W-Br À, thông báo có bao gồm hướng dẫn cho người tham gia. Anh nên xem qua chúng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6244, 5000, 44, 'What does the man ask the woman about?', 'Who will lead a meeting', 'Why a report is not finished', 'What topics a newsletter covers', 'When an executive will visit', 'C', 'Question: What does the man ask the woman about? (Người đàn ông hỏi người phụ nữ về điều gì?)
A: Who will lead a meeting (Ai sẽ chủ trì cuộc họp)
B: Why a report is not finished (Tại sao một báo cáo chưa hoàn thành)
C: What topics a newsletter covers (Bản tin đề cập đến những chủ đề gì)
D: When an executive will visit (Khi nào một giám đốc sẽ đến thăm)

Giải thích: Đáp án C là chính xác vì người đàn ông thấy người phụ nữ đang đọc bản tin công ty mới và hỏi nó nói về điều gì (What''s it about?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5001, 220, '2025/test2/audio/test2_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6245, 5001, 45, 'What will happen next month?', 'A new logo will be chosen', 'A parking area will be expanded', 'A department will be restructured', 'A review will be published', 'A', 'Question: What will happen next month? (Điều gì sẽ xảy ra vào tháng sau?)
A: A new logo will be chosen (Một logo mới sẽ được chọn)
B: A parking area will be expanded (Một bãi đỗ xe sẽ được mở rộng)
C: A department will be restructured (Một phòng ban sẽ được tái cơ cấu)
D: A review will be published (Một bài đánh giá sẽ được xuất bản)

Giải thích: Đáp án A là chính xác vì người phụ nữ nói rằng CEO sẽ chọn logo chiến thắng vào tháng sau (the CEO''s going to pick the winning logo next month).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5002, 220, '2025/test2/audio/test2_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6246, 5002, 46, 'What does the woman say the man should look at?', 'A revised list of names', 'Guidelines for a competition', 'Blueprints for a building', 'A budget proposal', 'B', 'Question: What does the woman say the man should look at? (Người phụ nữ nói người đàn ông nên xem gì?)
A: A revised list of names (Một danh sách tên đã được sửa đổi)
B: Guidelines for a competition (Hướng dẫn cho một cuộc thi)
C: Blueprints for a building (Bản vẽ cho một tòa nhà)
D: A budget proposal (Một đề xuất ngân sách)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói rằng thông báo có bao gồm hướng dẫn cho người tham gia và anh ấy nên xem qua chúng (the announcement includes instructions for participants. You should take a look at them).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5003, 220, '2025/test2/audio/test2_question_47_49.mp3', NULL, 'M-Au Excuse me. I''m not sure which product to buy. My bathroom drain is clogged, and I need something that can clear it. What do you recommend?
w-Br Almost any of these products would probably work, but if you want to make sure the job gets done, I''d recommend Purifine. Purifine''s the strongest drain cleaner on the market.
M-Au Got it. Thank you! Is there anything I should know before using it on my drain?
w-Br Yes-these kinds of chemicals can be dangerous. Make sure to look over the safety information printed on the back of the bottle before you open it up.', 'M-Au Xin lỗi. Tôi không chắc nên mua sản phẩm nào. Ống thoát nước trong phòng tắm của tôi bị tắc, và tôi cần thứ gì đó có thể thông nó. Chị gợi ý gì?
W-Br Gần như bất kỳ sản phẩm nào trong số này cũng có thể hiệu quả, nhưng nếu anh muốn chắc chắn công việc sẽ hoàn thành, tôi khuyên dùng Purifine. Purifine là chất thông tắc ống mạnh nhất trên thị trường.
M-Au Hiểu rồi. Cảm ơn! Có điều gì tôi nên biết trước khi sử dụng nó cho ống thoát nước không?
W-Br Có - những loại hóa chất này có thể nguy hiểm. Hãy chắc chắn xem kỹ thông tin an toàn được in ở mặt sau của chai trước khi mở nó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6247, 5003, 47, 'What does the man want to do?', 'Clear a drain', 'Remove a stain', 'Protect some flooring', 'Improve a room''s odor', 'A', 'Question: What does the man want to do? (Người đàn ông muốn làm gì?)
A: Clear a drain (Thông ống thoát nước)
B: Remove a stain (Loại bỏ vết bẩn)
C: Protect some flooring (Bảo vệ một số sàn nhà)
D: Improve a room''s odor (Cải thiện mùi của một phòng)

Giải thích: Đáp án A là chính xác vì người đàn ông nói rằng ống thoát nước trong phòng tắm của anh ấy bị tắc và anh ấy cần thứ gì đó có thể thông nó (My bathroom drain is clogged, and I need something that can clear it).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5004, 220, '2025/test2/audio/test2_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6248, 5004, 48, 'Why does the woman recommend a product?', 'It is environmentally friendly', 'It has a variety of uses', 'It is powerful', 'It is inexpensive', 'C', 'Question: Why does the woman recommend a product? (Tại sao người phụ nữ giới thiệu một sản phẩm?)
A: It is environmentally friendly (Nó thân thiện với môi trường)
B: It has a variety of uses (Nó có nhiều cách sử dụng)
C: It is powerful (Nó mạnh)
D: It is inexpensive (Nó rẻ)

Giải thích: Đáp án C là chính xác vì người phụ nữ giới thiệu Purifine vì nó là chất thông tắc ống mạnh nhất trên thị trường (Purifine''s the strongest drain cleaner on the market).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5005, 220, '2025/test2/audio/test2_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6249, 5005, 49, 'What does the woman tell the man to do?', 'Leave some windows open', 'Watch some videos', 'Wear a pair of gloves', 'Read a product label', 'D', 'Question: What does the woman tell the man to do? (Người phụ nữ bảo người đàn ông làm gì?)
A: Leave some windows open (Để cửa sổ mở)
B: Watch some videos (Xem một số video)
C: Wear a pair of gloves (Đeo một đôi găng tay)
D: Read a product label (Đọc nhãn sản phẩm)

Giải thích: Đáp án D là chính xác vì người phụ nữ bảo người đàn ông chắc chắn xem kỹ thông tin an toàn được in ở mặt sau của chai trước khi mở nó (Make sure to look over the safety information printed on the back of the bottle before you open it up).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5006, 220, '2025/test2/audio/test2_question_50_52.mp3', NULL, 'w-Br Hi, Tanya and George. Welcome to the team here at Pritchard Airport. We''re so glad to have two more baggage handlers with our busy season coming soon. OK, do you have any questions before I begin your orientation?
w-Am Yes, I do. Are there lockers where we can leave our belongings during our shifts?
w-Br There are. You''ll see them when we visit the staff breakroom later this morning.
M-Cn And we''re supposed to wear a reflective vest and black pants, right? Where do we get those from?
w-Br We supply the vest, but you''ll need to wear your own pants.
W-Am Oh, OK.', 'W-Br Chào Tanya và George. Chào mừng đến với đội ngũ ở sân bay Pritchard. Chúng tôi rất vui khi có thêm hai nhân viên khuân vác hành lý với mùa bận rộn sắp đến. OK, các bạn có câu hỏi gì trước khi tôi bắt đầu định hướng không?
W-Am Vâng, tôi có. Có tủ khóa nào để chúng tôi có thể để đồ đạc trong ca làm việc không?
W-Br Có. Các bạn sẽ thấy chúng khi chúng ta đến thăm phòng nghỉ của nhân viên sau này trong buổi sáng.
M-Cn Và chúng tôi phải mặc áo phản quang và quần đen, đúng không? Chúng tôi lấy những thứ đó ở đâu?
W-Br Chúng tôi cung cấp áo phản quang, nhưng bạn sẽ cần mặc quần của riêng mình.
W-Am Ồ, OK.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6250, 5006, 50, 'Where is the conversation taking place?', 'At an appliance store', 'At a movie theater', 'At an airport', 'At a school', 'C', 'Question: Where is the conversation taking place? (Cuộc trò chuyện diễn ra ở đâu?)
A: At an appliance store (Tại cửa hàng thiết bị)
B: At a movie theater (Tại rạp chiếu phim)
C: At an airport (Tại sân bay)
D: At a school (Tại trường học)

Giải thích: Đáp án C là chính xác vì cuộc trò chuyện diễn ra tại sân bay Pritchard (Pritchard Airport), nơi những người mới được chào đón vào đội ngũ nhân viên khuân vác hành lý (baggage handlers).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5007, 220, '2025/test2/audio/test2_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6251, 5007, 51, 'Where will the speakers go later in the morning?', 'To a staff break area', 'To a cafeteria', 'To a loading zone', 'To a conference room', 'A', 'Question: Where will the speakers go later in the morning? (Những người nói chuyện sẽ đi đâu sau trong buổi sáng?)
A: To a staff break area (Đến khu vực nghỉ của nhân viên)
B: To a cafeteria (Đến căng tin)
C: To a loading zone (Đến khu vực bốc dỡ)
D: To a conference room (Đến phòng họp)

Giải thích: Đáp án A là chính xác vì người phụ nữ nói rằng họ sẽ thấy tủ khóa khi họ đến thăm phòng nghỉ của nhân viên sau này trong buổi sáng (You''ll see them when we visit the staff breakroom later this morning).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5008, 220, '2025/test2/audio/test2_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6252, 5008, 52, 'What does the man ask about?', 'Who is part of a team', 'How long a certain shift is', 'Where to submit a document', 'How to obtain a uniform', 'D', 'Question: What does the man ask about? (Người đàn ông hỏi về điều gì?)
A: Who is part of a team (Ai là thành viên của một đội)
B: How long a certain shift is (Ca làm việc kéo dài bao lâu)
C: Where to submit a document (Nộp tài liệu ở đâu)
D: How to obtain a uniform (Làm thế nào để có đồng phục)

Giải thích: Đáp án D là chính xác vì người đàn ông hỏi về việc lấy áo phản quang và quần đen từ đâu (Where do we get those from?) khi đề cập đến trang phục đồng phục họ phải mặc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5009, 220, '2025/test2/audio/test2_question_53_55.mp3', NULL, 'M-Au Hi, Lori. Did Dean let you know that I''ll be giving the interview that Tech News Weekly asked for? He''s quite busy this week, and I also know a lot about the products the interviewer wants to discuss.
W-Br Really? Last time we spoke, he said that he would come here to the public relations department so we could prepare him for it. That was this morning.
M-Au Well, I spoke with him after lunch. You can call him to confirm if you''d like.', 'M-Au Chào Lori. Dean có cho chị biết là tôi sẽ thực hiện cuộc phỏng vấn mà Tech News Weekly yêu cầu không? Anh ấy khá bận tuần này, và tôi cũng biết nhiều về những sản phẩm mà người phỏng vấn muốn thảo luận.
W-Br Thật sao? Lần cuối chúng tôi nói chuyện, anh ấy nói rằng anh ấy sẽ đến đây, phòng quan hệ công chúng để chúng tôi có thể chuẩn bị cho anh ấy. Đó là sáng nay.
M-Au À, tôi đã nói chuyện với anh ấy sau bữa trưa. Chị có thể gọi cho anh ấy để xác nhận nếu chị muốn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6253, 5009, 53, 'What is the conversation about?', 'A company policy', 'A production delay', 'A damaged machine', 'An upcoming interview', 'D', 'Question: What is the conversation about? (Cuộc trò chuyện nói về điều gì?)
A: A company policy (Một chính sách công ty)
B: A production delay (Sự chậm trễ trong sản xuất)
C: A damaged machine (Một máy móc bị hỏng)
D: An upcoming interview (Một cuộc phỏng vấn sắp tới)

Giải thích: Đáp án D là chính xác vì cuộc trò chuyện xoay quanh việc ai sẽ thực hiện cuộc phỏng vấn mà Tech News Weekly đã yêu cầu, với sự thay đổi từ Dean sang người đàn ông trong đoạn hội thoại.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5010, 220, '2025/test2/audio/test2_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6254, 5010, 54, 'What department does the woman most likely work for?', 'Security', 'Accounting', 'Public Relations', 'Human Resources', 'C', 'Question: What department does the woman most likely work for? (Người phụ nữ nhiều khả năng làm việc cho phòng ban nào?)
A: Security (An ninh)
B: Accounting (Kế toán)
C: Public Relations (Quan hệ công chúng)
D: Human Resources (Nhân sự)

Giải thích: Đáp án C là chính xác vì trong đoạn hội thoại đề cập đến việc Dean sẽ đến phòng quan hệ công chúng (public relations department) nơi người phụ nữ làm việc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5011, 220, '2025/test2/audio/test2_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6255, 5011, 55, 'What does the man imply when he says, ''I spoke with him after lunch''?', 'He missed a group outing', 'He already received some instructions', 'A plan changed a short time ago', 'A task has been completed', 'C', 'Question: What does the man imply when he says, ''I spoke with him after lunch''? (Người đàn ông ngụ ý gì khi nói ''Tôi đã nói chuyện với anh ấy sau bữa trưa''?)
A: He missed a group outing (Anh ấy đã bỏ lỡ một chuyến đi nhóm)
B: He already received some instructions (Anh ấy đã nhận được một số hướng dẫn)
C: A plan changed a short time ago (Một kế hoạch đã thay đổi cách đây không lâu)
D: A task has been completed (Một nhiệm vụ đã hoàn thành)

Giải thích: Đáp án C là chính xác vì khi nói anh ấy đã nói chuyện với Dean sau bữa trưa, người đàn ông ngụ ý rằng kế hoạch đã thay đổi kể từ cuộc nói chuyện buổi sáng của Dean với người phụ nữ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5012, 220, '2025/test2/audio/test2_question_56_58.mp3', NULL, 'M-Au Scott, what do you think of the company''s new internal Web site? To me, it seems to have a lot of helpful features.
M-Cn Yes, I like it. I was especially happy to see that we can share documents through it. That should make it easier for teams to collaborate.
M-Au I agree. And the companywide forum page is going to improve collaboration, too. I wonder how they thought of including that in the Web site.
M-cn Well, Alexis might know, since she works for the IT department.
M-Au Hey, Alexis? Scott and I are curious-where did the inspiration for the new Web site''s forum page come from?
W-Am I think it was proposed by Courtney Gray in Human Resources. She had a lot of good suggestions, actually.', 'M-Au Scott, anh nghĩ gì về trang web nội bộ mới của công ty? Với tôi, nó có vẻ có nhiều tính năng hữu ích.
M-Cn Vâng, tôi thích nó. Tôi đặc biệt vui khi thấy rằng chúng ta có thể chia sẻ tài liệu qua đó. Điều đó sẽ giúp các nhóm dễ dàng hợp tác hơn.
M-Au Tôi đồng ý. Và trang diễn đàn toàn công ty cũng sẽ cải thiện sự hợp tác. Tôi tự hỏi làm sao họ nghĩ ra việc đưa nó vào trang web.
M-cn À, Alexis có thể biết, vì cô ấy làm việc cho phòng IT.
M-Au Này, Alexis? Scott và tôi tò mò - cảm hứng cho trang diễn đàn của trang web mới đến từ đâu?
W-Am Tôi nghĩ nó được đề xuất bởi Courtney Gray ở phòng Nhân sự. Thực ra cô ấy có nhiều gợi ý tốt.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6256, 5012, 56, 'What did the speakers'' company recently do?', 'It launched a Web site', 'It renovated its office', 'It hired a spokesperson', 'It introduced a new policy', 'A', 'Question: What did the speakers'' company recently do? (Công ty của những người nói chuyện gần đây đã làm gì?)
A: It launched a Web site (Nó đã ra mắt một trang web)
B: It renovated its office (Nó đã cải tạo văn phòng)
C: It hired a spokesperson (Nó đã thuê người phát ngôn)
D: It introduced a new policy (Nó đã giới thiệu một chính sách mới)

Giải thích: Đáp án A là chính xác vì họ đang thảo luận về trang web nội bộ mới của công ty (the company''s new internal Web site) và các tính năng của nó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5013, 220, '2025/test2/audio/test2_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6257, 5013, 57, 'What do the men say is a benefit of the change?', 'It will attract new customers', 'It will lower maintenance costs', 'It will improve staff collaboration', 'It will make some travel unnecessary', 'C', 'Question: What do the men say is a benefit of the change? (Những người đàn ông nói lợi ích của sự thay đổi là gì?)
A: It will attract new customers (Nó sẽ thu hút khách hàng mới)
B: It will lower maintenance costs (Nó sẽ giảm chi phí bảo trì)
C: It will improve staff collaboration (Nó sẽ cải thiện sự hợp tác của nhân viên)
D: It will make some travel unnecessary (Nó sẽ làm cho một số chuyến đi trở nên không cần thiết)

Giải thích: Đáp án C là chính xác vì cả hai người đàn ông đều nói rằng việc chia sẻ tài liệu và trang diễn đàn sẽ giúp cải thiện sự hợp tác giữa các nhóm (That should make it easier for teams to collaborate, And the companywide forum page is going to improve collaboration).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5014, 220, '2025/test2/audio/test2_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6258, 5014, 58, 'What do the men ask the woman about?', 'The reaction to an announcement', 'The quality of a service', 'The origin of an idea', 'The status of a project', 'C', 'Question: What do the men ask the woman about? (Những người đàn ông hỏi người phụ nữ về điều gì?)
A: The reaction to an announcement (Phản ứng với một thông báo)
B: The quality of a service (Chất lượng của một dịch vụ)
C: The origin of an idea (Nguồn gốc của một ý tưởng)
D: The status of a project (Tình trạng của một dự án)

Giải thích: Đáp án C là chính xác vì họ hỏi Alexis về nguồn gốc ý tưởng cho trang diễn đàn của trang web mới đến từ đâu (where did the inspiration for the new Web site''s forum page come from?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5015, 220, '2025/test2/audio/test2_question_59_61.mp3', NULL, 'W-Br Louis, I heard that you''re going to be posting about our work on social media. I think that''s smart. A lot of people don''t know about the services that a tailor shop like this provides.
M-Au Right! Ms. Lam made the decision when she found out that I''m active on social media. She''d been wanting to increase the shop''s Internet presence. So now one of my duties will be managing our accounts on social media sites.
w-Br That''s great. What kinds of content are you going to post?
M-Au Well, I definitely want to show pictures of clothes before and after tailoring. But I''m not sure what else yet. If you have any ideas, please let me know!', 'W-Br Louis, tôi nghe nói rằng anh sẽ đăng về công việc của chúng ta trên mạng xã hội. Tôi nghĩ điều đó thông minh đấy. Nhiều người không biết về các dịch vụ mà một tiệm may như thế này cung cấp.
M-Au Đúng vậy! Cô Lam đã đưa ra quyết định khi cô ấy phát hiện ra rằng tôi tích cực trên mạng xã hội. Cô ấy đã muốn tăng sự hiện diện của cửa hàng trên Internet. Vì vậy bây giờ một trong những nhiệm vụ của tôi sẽ là quản lý các tài khoản của chúng ta trên các trang mạng xã hội.
W-Br Tuyệt quá. Anh sẽ đăng những loại nội dung gì?
M-Au À, tôi chắc chắn muốn cho xem hình ảnh quần áo trước và sau khi may. Nhưng tôi vẫn chưa chắc về những thứ khác. Nếu chị có ý tưởng gì, hãy cho tôi biết nhé!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6259, 5015, 59, 'Where do the speakers work?', 'At a fashion magazine', 'At a restaurant', 'At a Web development firm', 'At a tailor shop', 'D', 'Question: Where do the speakers work? (Những người nói chuyện làm việc ở đâu?)
A: At a fashion magazine (Tại một tạp chí thời trang)
B: At a restaurant (Tại một nhà hàng)
C: At a Web development firm (Tại một công ty phát triển web)
D: At a tailor shop (Tại một tiệm may)

Giải thích: Đáp án D là chính xác vì trong đoạn hội thoại đề cập đến dịch vụ mà một tiệm may như này cung cấp (the services that a tailor shop like this provides) và nói về việc chụp ảnh quần áo trước và sau khi may (pictures of clothes before and after tailoring).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5016, 220, '2025/test2/audio/test2_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6260, 5016, 60, 'What has the man been assigned to do?', 'Mentor some colleagues', 'Oversee social media accounts', 'Organize a storage space', 'Research a competitor', 'B', 'Question: What has the man been assigned to do? (Người đàn ông đã được giao làm gì?)
A: Mentor some colleagues (Hướng dẫn một số đồng nghiệp)
B: Oversee social media accounts (Quản lý các tài khoản mạng xã hội)
C: Organize a storage space (Sắp xếp không gian lưu trữ)
D: Research a competitor (Nghiên cứu đối thủ cạnh tranh)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng một trong những nhiệm vụ của anh ấy sẽ là quản lý các tài khoản của cửa hàng trên các trang mạng xã hội (one of my duties will be managing our accounts on social media sites).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5017, 220, '2025/test2/audio/test2_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6261, 5017, 61, 'What does the man ask the woman to do?', 'Review a presentation', 'Make some suggestions', 'Take some pictures', 'Pick up some food', 'B', 'Question: What does the man ask the woman to do? (Người đàn ông yêu cầu người phụ nữ làm gì?)
A: Review a presentation (Xem xét một bài thuyết trình)
B: Make some suggestions (Đưa ra một số gợi ý)
C: Take some pictures (Chụp một số ảnh)
D: Pick up some food (Lấy một số thức ăn)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng anh ấy chưa chắc về những nội dung khác sẽ đăng và yêu cầu nếu người phụ nữ có ý tưởng gì thì hãy cho anh ấy biết (If you have any ideas, please let me know!).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5018, 220, '2025/test2/audio/test2_question_62_64.mp3', '2025/test2/image/test2-p3-image-62.jpg', 'w-Br Welcome to the Beldwin Ferry East Terminal. Would you like to purchase a ticket?
M-cn Yes, for the next ferry. I''m a photographer, and I''m planning to spend the day taking pictures of the plant life on Beldwin Island. I''ve heard it''s beautiful.
W-Br Yes, very! Four dollars, please.
M-cn Oh, I thought the fare was higher than that... Ah, I see.
W-Br Yes. Here''s your ticket. As you can see, the next ferry departs in about half an hour.
M-Cn Hmm... In that case, is there a restaurant or cafeteria around here? I''d like to grab a bite to eat before getting on the ferry.
w-Br Yes, there''s a place around that corner.', 'W-Br Chào mừng đến Trạm Phà Đông Beldwin. Anh có muốn mua vé không?
M-cn Vâng, cho chuyến phà tiếp theo. Tôi là nhiếp ảnh gia, và tôi dự định dành cả ngày để chụp ảnh thực vật trên đảo Beldwin. Tôi nghe nói nó rất đẹp.
W-Br Vâng, rất đẹp! Bốn đô la, làm ơn.
M-cn Ồ, tôi nghĩ giá vé cao hơn thế... À, tôi hiểu rồi.
W-Br Vâng. Đây là vé của anh. Như anh thấy, chuyến phà tiếp theo khởi hành trong khoảng nửa giờ nữa.
M-Cn Hmm... Trong trường hợp đó, có nhà hàng hay căng tin nào quanh đây không? Tôi muốn ăn một chút trước khi lên phà.
W-Br Có, có một chỗ ở quanh góc đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6262, 5018, 62, 'What is the purpose of the man''s trip?', 'To get exercise outdoors', 'To create artworks', 'To collect samples of plants', 'To repair electronics', 'B', 'Question: What is the purpose of the man''s trip? (Mục đích chuyến đi của người đàn ông là gì?)
A: To get exercise outdoors (Để tập thể dục ngoài trời)
B: To create artworks (Để tạo tác phẩm nghệ thuật)
C: To collect samples of plants (Để thu thập mẫu thực vật)
D: To repair electronics (Để sửa chữa thiết bị điện tử)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng anh ấy là nhiếp ảnh gia và dự định dành cả ngày để chụp ảnh thực vật trên đảo Beldwin (I''m a photographer, and I''m planning to spend the day taking pictures of the plant life on Beldwin Island).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5019, 220, '2025/test2/audio/test2_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6263, 5019, 63, 'Look at the graphic. Why does the man receive a discount?', 'It is after 6 P.M.', 'It is a weekend day', 'He is a senior', 'He has a pass', 'B', 'Question: Look at the graphic. Why does the man receive a discount? (Nhìn vào hình đồ họa. Tại sao người đàn ông được giảm giá?)
A: It is after 6 P.M. (Đã sau 6 giờ chiều)
B: It is a weekend day (Đó là ngày cuối tuần)
C: He is a senior (Anh ấy là người cao tuổi)
D: He has a pass (Anh ấy có thẻ)

Giải thích: Đáp án B là chính xác vì giá vé người đàn ông phải trả là 4 đô la, và trong hình đồ họa cho thấy giá vé 4 đô la áp dụng vào các ngày cuối tuần (Discounted Fares: $4 on weekends).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5020, 220, '2025/test2/audio/test2_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6264, 5020, 64, 'What will the man most likely do next?', 'Have a small meal', 'Board a passenger ferry', 'Shop for souvenirs', 'Retrieve his bicycle', 'A', 'Question: What will the man most likely do next? (Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?)
A: Have a small meal (Ăn một bữa nhẹ)
B: Board a passenger ferry (Lên phà)
C: Shop for souvenirs (Mua đồ lưu niệm)
D: Retrieve his bicycle (Lấy xe đạp)

Giải thích: Đáp án A là chính xác vì người đàn ông muốn ăn một chút trước khi lên phà (I''d like to grab a bite to eat before getting on the ferry) và được chỉ dẫn đến một địa điểm ăn uống ở gần đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5021, 220, '2025/test2/audio/test2_question_65_67.mp3', '2025/test2/image/test2-p3-image-65.jpg', 'W-Br Thanks for helping me with the charity drive to collect gently used items. Our patients have donated a lot, right?
M-Au Yes. Someone''s just dropped off all of these board games, dolls, and blocks. They''re in great condition. And the medical staff and visitors have also been bringing things in.
W-Br Wonderful! The collection boxes are in the hall by the administration office. But don''t put them in all together, as the pieces may get mixed up. I brought some plastic bags to separate each item.', 'W-Br Cảm ơn anh đã giúp tôi với chiến dịch từ thiện thu thập các đồ vật đã qua sử dụng còn tốt. Bệnh nhân của chúng ta đã quyên góp nhiều, phải không?
M-Au Vâng. Ai đó vừa mới gửi tất cả những trò chơi board game, búp bê và khối xếp hình này. Chúng trong tình trạng rất tốt. Và nhân viên y tế cùng khách thăm cũng đã mang đồ đến.
W-Br Tuyệt quá! Các hộp thu gom ở trong hành lang gần văn phòng hành chính. Nhưng đừng bỏ tất cả chúng vào cùng nhau, vì các mảnh có thể bị trộn lẫn. Tôi đã mang một số túi nhựa để tách riêng từng món.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6265, 5021, 65, 'Where most likely are the speakers?', 'At a travel agency', 'At a school', 'At a hospital', 'At a bank', 'C', 'Question: Where most likely are the speakers? (Những người nói chuyện nhiều khả năng đang ở đâu?)
A: At a travel agency (Tại một đại lý du lịch)
B: At a school (Tại một trường học)
C: At a hospital (Tại một bệnh viện)
D: At a bank (Tại một ngân hàng)

Giải thích: Đáp án C là chính xác vì cuộc trò chuyện đề cập đến bệnh nhân (patients) và nhân viên y tế (medical staff), cho thấy họ đang ở trong bệnh viện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5022, 220, '2025/test2/audio/test2_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6266, 5022, 66, 'Look at the graphic. Which box will the man use?', 'Box 1', 'Box 2', 'Box 3', 'Box 4', 'B', 'Question: Look at the graphic. Which box will the man use? (Nhìn vào hình đồ họa. Người đàn ông sẽ sử dụng hộp nào?)
A: Box 1 (Hộp 1)
B: Box 2 (Hộp 2)
C: Box 3 (Hộp 3)
D: Box 4 (Hộp 4)

Giải thích: Đáp án B là chính xác vì người đàn ông đang có các món đồ chơi như board game, búp bê và khối xếp hình, và trong hình đồ họa, Box 2 được dán nhãn Toys" (Đồ chơi)."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5023, 220, '2025/test2/audio/test2_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6267, 5023, 67, 'What does the woman suggest doing?', 'Assessing the value of the contents', 'Printing some new labels for the boxes', 'Placing some items in individual bags', 'Checking to see if there are missing pieces', 'C', 'Question: What does the woman suggest doing? (Người phụ nữ đề xuất làm gì?)
A: Assessing the value of the contents (Đánh giá giá trị của các món đồ)
B: Printing some new labels for the boxes (In nhãn mới cho các hộp)
C: Placing some items in individual bags (Đặt các món đồ vào túi riêng)
D: Checking to see if there are missing pieces (Kiểm tra xem có mảnh nào bị thiếu không)

Giải thích: Đáp án C là chính xác vì người phụ nữ nói rằng cô ấy đã mang một số túi nhựa để tách riêng từng món đồ (I brought some plastic bags to separate each item) để tránh các mảnh bị trộn lẫn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5024, 220, '2025/test2/audio/test2_question_68_70.mp3', '2025/test2/image/test2-p3-image-68.jpg', 'M-Au Hi, could you help me?
W-Am Absolutely. What brings you to the Randholm Building today?
M-Au l''m looking for the convenience store. I have a job interview there in a few minutes.
W-Am OK. Here''s the floor plan for the ground floor. You''re here, at the information desk. Just walk around the potted trees there. The convenience store is across from Uncle Freddie''s.
M-Au I see. Thank you.
W-Am Sure. Oh, and afterwards, come back out this way. The other entrance is closed today.
M-Au That''s good to know.', 'M-Au Chào, chị có thể giúp tôi không?
W-Am Được chứ. Điều gì đưa anh đến Tòa nhà Randholm hôm nay?
M-Au Tôi đang tìm cửa hàng tiện lợi. Tôi có một cuộc phỏng vấn việc làm ở đó trong vài phút nữa.
W-Am OK. Đây là sơ đồ tầng trệt. Anh đang ở đây, tại quầy thông tin. Chỉ cần đi vòng qua những cây cảnh trong chậu kia. Cửa hàng tiện lợi nằm đối diện với Uncle Freddie''s.
M-Au Tôi hiểu rồi. Cảm ơn chị.
W-Am Không có gì. À, và sau đó, hãy quay ra lối này nhé. Lối vào kia đang đóng cửa hôm nay.
M-Au Biết thế thật tốt.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6268, 5024, 68, 'What does the man plan to do?', 'Make a purchase', 'Meet a friend', 'Deliver a package', 'Attend a job interview', 'D', 'Question: What does the man plan to do? (Người đàn ông dự định làm gì?)
A: Make a purchase (Mua sắm)
B: Meet a friend (Gặp bạn)
C: Deliver a package (Giao một gói hàng)
D: Attend a job interview (Tham dự phỏng vấn việc làm)

Giải thích: Đáp án D là chính xác vì người đàn ông nói rằng anh ấy có một cuộc phỏng vấn việc làm ở cửa hàng tiện lợi trong vài phút nữa (I have a job interview there in a few minutes).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5025, 220, '2025/test2/audio/test2_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6269, 5025, 69, 'Look at the graphic. Where will the man most likely go?', 'To the Information Desk', 'To The Full Basket', 'To Quality Spot', 'To Uncle Freddie''s', 'C', 'Question: Look at the graphic. Where will the man most likely go? (Nhìn vào hình đồ họa. Người đàn ông nhiều khả năng sẽ đi đến đâu?)
A: To the Information Desk (Đến Quầy thông tin)
B: To The Full Basket (Đến The Full Basket)
C: To Quality Spot (Đến Quality Spot)
D: To Uncle Freddie''s (Đến Uncle Freddie''s)

Giải thích: Đáp án C là chính xác vì trong bản đồ, Quality Spot là cửa hàng tiện lợi nằm đối diện với Uncle Freddie''s, và người phụ nữ nói rằng cửa hàng tiện lợi nằm đối diện với Uncle Freddie''s.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5026, 220, '2025/test2/audio/test2_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6270, 5026, 70, 'What does the woman inform the man about?', 'An elevator skips some floors', 'A parking space has a time limit', 'A sales event is happening', 'An entrance is closed', 'D', 'Question: What does the woman inform the man about? (Người phụ nữ thông báo cho người đàn ông về điều gì?)
A: An elevator skips some floors (Một thang máy bỏ qua một số tầng)
B: A parking space has a time limit (Một chỗ đỗ xe có giới hạn thời gian)
C: A sales event is happening (Một sự kiện bán hàng đang diễn ra)
D: An entrance is closed (Một lối vào đang đóng cửa)

Giải thích: Đáp án D là chính xác vì người phụ nữ thông báo cho người đàn ông rằng lối vào kia đang đóng cửa hôm nay (The other entrance is closed today).');;

-- Data for 2025 Test2 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5027, 221, '2025/test2/audio/test2_question_71_73.mp3', NULL, 'Welcome to Prescott Science Museum. I''m Hans Ulrich, the institution''s volunteer program coordinator. I''ll be giving you a general orientation before you''re split into smaller groups for training in your specific duties. Now, the museum building is massive, at over 20,000 square meters-so we don''t expect you to learn everything about its contents. However, we do want volunteers to have some familiarity with them. I''ll start today by showing you around the entire facility. This is meant to be a quick overview, so please hold your questions until we''re finished.', 'Chào mừng đến với Bảo tàng Khoa học Prescott. Tôi là Hans Ulrich, điều phối viên chương trình tình nguyện viên của tổ chức. Tôi sẽ cung cấp cho các bạn một buổi định hướng chung trước khi các bạn được chia thành các nhóm nhỏ hơn để đào tạo về nhiệm vụ cụ thể của mình. Bây giờ, tòa nhà bảo tàng rất lớn, hơn 20.000 mét vuông - vì vậy chúng tôi không mong đợi các bạn học hết mọi thứ về nội dung của nó. Tuy nhiên, chúng tôi muốn các tình nguyện viên có một số hiểu biết về chúng. Hôm nay tôi sẽ bắt đầu bằng việc đưa các bạn đi tham quan toàn bộ cơ sở. Đây được xem là một cái nhìn tổng quan nhanh, vì vậy vui lòng giữ câu hỏi của bạn cho đến khi chúng ta hoàn thành.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6271, 5027, 71, 'Where most likely are the listeners?', 'At a university', 'At a sports arena', 'At a national park', 'At a science museum', 'D', '[Dịch] Câu hỏi: Người nghe có khả năng đang ở đâu?
A: Tại một trường đại học
B: Tại một sân vận động
C: Tại một công viên quốc gia
D: Tại một bảo tàng khoa học

Đáp án D là chính xác vì ngay từ đầu đoạn văn đã xác định rõ địa điểm là "Prescott Science Museum" và người nói giới thiệu mình là điều phối viên chương trình tình nguyện viên của bảo tàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5028, 221, '2025/test2/audio/test2_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6272, 5028, 72, 'What does the speaker emphasize about an institution?', 'It has won awards.', 'It has a large facility.', 'It runs many programs.', 'It uses new technology.', 'B', '[Dịch] Câu hỏi: Người nói nhấn mạnh điều gì về tổ chức?
A: Nó đã giành được giải thưởng
B: Nó có một cơ sở lớn
C: Nó điều hành nhiều chương trình
D: Nó sử dụng công nghệ mới

Đáp án B là chính xác vì người nói nhấn mạnh về kích thước của tòa nhà bảo tàng bằng cách mô tả nó là "massive, at over 20,000 square meters" (rất lớn, hơn 20.000 mét vuông).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5029, 221, '2025/test2/audio/test2_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6273, 5029, 73, 'What will the listeners do next?', 'Take a tour', 'Fill out forms', 'Introduce themselves', 'Put on special clothing', 'A', '[Dịch] Câu hỏi: Người nghe sẽ làm gì tiếp theo?
A: Đi tham quan
B: Điền vào các mẫu đơn
C: Tự giới thiệu bản thân
D: Mặc trang phục đặc biệt

Đáp án A là chính xác vì người nói tuyên bố "I''ll start today by showing you around the entire facility", nghĩa là người nói sẽ đưa người nghe đi tham quan toàn bộ cơ sở.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5030, 221, '2025/test2/audio/test2_question_74_76.mp3', NULL, 'Can I have everyone''s attention for a moment? I''m Cynthia Hughes from the IT department. Thank you for your cooperation in using the second-floor copy machine over the last few days. Tomorrow, the new copier for this floor will finally be delivered and set up. The installation may be a little noisy, but we don''t expect it to take very long. Uh, once it''s complete, you''ll each be assigned a four-digit code. You''ll have to enter that code in order to use the new copier.', 'Tôi có thể xin sự chú ý của mọi người một chút không? Tôi là Cynthia Hughes từ phòng IT. Cảm ơn sự hợp tác của các bạn trong việc sử dụng máy photocopy tầng hai trong những ngày qua. Ngày mai, máy photocopy mới cho tầng này cuối cùng sẽ được giao và lắp đặt. Việc lắp đặt có thể hơi ồn ào, nhưng chúng tôi không mong đợi nó sẽ kéo dài. À, một khi hoàn thành, mỗi người sẽ được cấp một mã số bốn chữ số. Bạn sẽ phải nhập mã đó để sử dụng máy photocopy mới.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6274, 5030, 74, 'Who most likely is the speaker?', 'A technical support provider', 'A marketing manager', 'A legal advisor', 'A product development specialist', 'A', '[Dịch] Câu hỏi: Người nói có khả năng là ai?
A: Một người cung cấp hỗ trợ kỹ thuật
B: Một giám đốc tiếp thị
C: Một cố vấn pháp lý
D: Một chuyên gia phát triển sản phẩm

Đáp án A là chính xác vì người nói giới thiệu mình là Cynthia Hughes from the IT department và đang xử lý các vấn đề liên quan đến thiết bị (máy photocopy) và cài đặt mã truy cập, đây là công việc điển hình của nhân viên hỗ trợ kỹ thuật.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5031, 221, '2025/test2/audio/test2_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6275, 5031, 75, 'What does the speaker say will take place tomorrow?', 'A welcome reception', 'An equipment installation', 'A photography session', 'An online seminar', 'B', '[Dịch] Câu hỏi: Người nói cho biết điều gì sẽ diễn ra vào ngày mai?
A: Một buổi tiếp đón chào mừng
B: Lắp đặt thiết bị
C: Một buổi chụp ảnh
D: Một hội thảo trực tuyến

Đáp án B là chính xác vì trong đoạn hội thoại nêu rõ "Tomorrow, the new copier for this floor will finally be delivered and set up", nghĩa là ngày mai máy photocopy mới sẽ được giao và lắp đặt.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5032, 221, '2025/test2/audio/test2_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6276, 5032, 76, 'According to the speaker, why will the listeners need a number code?', 'To receive a discount', 'To operate a machine', 'To log in to a Web site', 'To enter a building', 'B', '[Dịch] Câu hỏi: Theo người nói, tại sao người nghe sẽ cần một mã số?
A: Để nhận giảm giá
B: Để vận hành một máy
C: Để đăng nhập vào một trang web
D: Để vào một tòa nhà

Đáp án B là chính xác vì người nói cho biết "You''ll have to enter that code in order to use the new copier", nghĩa là người nghe sẽ cần nhập mã để sử dụng máy photocopy mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5033, 221, '2025/test2/audio/test2_question_77_79.mp3', NULL, 'In local news, there is a lot of excitement for the Kiva Bledsoe concert that will be held tonight in the stadium downtown. Ms. Bledsoe, a pop singer, is on a tour that is getting glowing reviews from attendees. Many of them have posted smartphone video footage online, revealing that the concert features incredible costumes and sets. Tonight''s show is sold out, which means that traffic around the venue will be heavy. If you''re looking for an easier way to get to and from the stadium, the subways run until midnight.', 'Trong tin tức địa phương, có rất nhiều sự hào hứng cho buổi hòa nhạc của Kiva Bledsoe sẽ được tổ chức tối nay tại sân vận động trung tâm thành phố. Cô Bledsoe, một ca sĩ nhạc pop, đang trong chuyến lưu diễn nhận được những đánh giá tuyệt vời từ khán giả. Nhiều người trong số họ đã đăng tải video quay bằng điện thoại thông minh lên mạng, cho thấy buổi hòa nhạc có trang phục và bối cảnh ấn tượng. Buổi biểu diễn tối nay đã bán hết vé, điều này có nghĩa là giao thông xung quanh địa điểm sẽ rất đông đúc. Nếu bạn đang tìm kiếm một cách dễ dàng hơn để đến và về từ sân vận động, tàu điện ngầm chạy đến nửa đêm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6277, 5033, 77, 'What is the main topic of the report?', 'A music concert', 'A sports tournament', 'A transportation project', 'An approaching storm', 'A', '[Dịch] Câu hỏi: Chủ đề chính của bản tin là gì?
A: Một buổi hòa nhạc
B: Một giải đấu thể thao
C: Một dự án giao thông
D: Một cơn bão đang đến

Đáp án A là chính xác vì toàn bộ bản tin tập trung vào buổi hòa nhạc của ca sĩ nhạc pop Kiva Bledsoe sẽ diễn ra tối nay tại sân vận động trung tâm thành phố. Bản tin mô tả về các đánh giá tốt, trang phục và bối cảnh ấn tượng của buổi biểu diễn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5034, 221, '2025/test2/audio/test2_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6278, 5034, 78, 'According to the speaker, what has been posted online?', 'A list of road closures', 'Contact information', 'Video footage', 'A technical drawing', 'C', '[Dịch] Câu hỏi: Theo người nói, điều gì đã được đăng tải trực tuyến?
A: Danh sách các con đường bị đóng
B: Thông tin liên hệ
C: Đoạn video
D: Một bản vẽ kỹ thuật

Đáp án C là chính xác vì trong bản tin có đề cập "Many of them have posted smartphone video footage online", nghĩa là nhiều người đã đăng tải video quay bằng điện thoại thông minh lên mạng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5035, 221, '2025/test2/audio/test2_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6279, 5035, 79, 'What does the speaker mean when he says, "the subways run until midnight"?', 'Subway schedules have changed recently.', 'Attendees of an event should use the subway.', 'Some work must take place after midnight.', 'A city''s transit services are well-funded.', 'B', '[Dịch] Câu hỏi: Người nói có ý gì khi anh ấy nói "tàu điện ngầm chạy đến nửa đêm"?
A: Lịch trình tàu điện ngầm gần đây đã thay đổi
B: Những người tham dự sự kiện nên sử dụng tàu điện ngầm
C: Một số công việc phải diễn ra sau nửa đêm
D: Dịch vụ vận chuyển của thành phố được tài trợ tốt

Đáp án B là chính xác vì người nói đề nghị sử dụng tàu điện ngầm như một cách dễ dàng hơn để đi lại ("an easier way to get to and from the stadium"), đặc biệt khi giao thông sẽ rất đông đúc do buổi hòa nhạc bán hết vé.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5036, 221, '2025/test2/audio/test2_question_80_82.mp3', NULL, 'Hello, Mr. Yates. This is Mi-Hwa Park from Wilkett Public Radio, calling about your application for the producer position at our station. Your résumé is very impressive. In particular, I noticed that you''re currently working as a producer on the podcast Culture Week. I''d be very interested in learning more about your contributions to the making of that show. Uh, Human Resources handles our interview scheduling, so expect a call from them soon. I''m going to send your application materials on to them now.', 'Xin chào, ông Yates. Tôi là Mi-Hwa Park từ Đài Phát thanh Công cộng Wilkett, gọi điện về đơn ứng tuyển vào vị trí nhà sản xuất tại đài của chúng tôi. Sơ yếu lý lịch của ông rất ấn tượng. Đặc biệt, tôi nhận thấy ông hiện đang làm nhà sản xuất cho podcast Culture Week. Tôi rất muốn tìm hiểu thêm về những đóng góp của ông cho việc sản xuất chương trình đó. À, phòng Nhân sự sẽ xử lý việc lên lịch phỏng vấn của chúng tôi, vì vậy hãy chờ cuộc gọi từ họ sớm. Tôi sẽ gửi tài liệu ứng tuyển của ông cho họ ngay bây giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6280, 5036, 80, 'What job has the listener applied for?', 'Film critic', 'Radio producer', 'Event coordinator', 'Book editor', 'B', '[Dịch] Câu hỏi: Người nghe đã ứng tuyển vào vị trí gì?
A: Nhà phê bình phim
B: Nhà sản xuất radio
C: Điều phối viên sự kiện
D: Biên tập viên sách

Đáp án B là chính xác vì đoạn hội thoại đề cập người nghe đã nộp đơn ứng tuyển vào vị trí producer (nhà sản xuất) tại Wilkett Public Radio (đài phát thanh công cộng Wilkett).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5037, 221, '2025/test2/audio/test2_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6281, 5037, 81, 'What does the speaker say she wants to discuss?', 'A writing style', 'A training process', 'A company''s goals', 'A podcast''s creation', 'D', '[Dịch] Câu hỏi: Người nói cho biết cô ấy muốn thảo luận về điều gì?
A: Một phong cách viết
B: Một quy trình đào tạo
C: Mục tiêu của công ty
D: Việc tạo ra một podcast

Đáp án D là chính xác vì người nói bày tỏ muốn tìm hiểu thêm về "your contributions to the making of that show", nghĩa là những đóng góp của ứng viên trong việc sản xuất podcast Culture Week.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5038, 221, '2025/test2/audio/test2_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6282, 5038, 82, 'What does the speaker say she will do next?', 'Forward some documents', 'Leave for a business trip', 'Confirm a pay rate', 'Update a job advertisement', 'A', '[Dịch] Câu hỏi: Người nói cho biết cô ấy sẽ làm gì tiếp theo?
A: Chuyển tiếp một số tài liệu
B: Đi công tác
C: Xác nhận mức lương
D: Cập nhật quảng cáo việc làm

Đáp án A là chính xác vì người nói tuyên bố "I''m going to send your application materials on to them now", nghĩa là cô ấy sẽ chuyển tài liệu ứng tuyển cho phòng Nhân sự.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5039, 221, '2025/test2/audio/test2_question_83_85.mp3', NULL, 'Hello. My name is Norman Quinn, and I''m trying to reach the manager of Penver Inn and Suites. I visited your inn last week to pick up a friend who was staying there, and I noticed that you display art in the lobby. I''m an artist-I paint colorful landscapes and portraits. They re similar to the pieces I saw in the inn. And I live nearby, in Sundale. So I thought I''d ask... do you show works by local artists? If so, I can e-mail you some high-quality images of my work. Just call me back at this number, 555-0167.', 'Xin chào. Tôi tên là Norman Quinn, và tôi đang cố gắng liên lạc với người quản lý Khách sạn Penver Inn and Suites. Tôi đã ghé thăm khách sạn của bạn tuần trước để đón một người bạn đang ở đó, và tôi nhận thấy bạn trưng bày nghệ thuật ở sảnh. Tôi là một nghệ sĩ - tôi vẽ phong cảnh và chân dung nhiều màu sắc. Chúng tương tự như những tác phẩm tôi thấy trong khách sạn. Và tôi sống gần đây, ở Sundale. Vì vậy tôi nghĩ tôi sẽ hỏi... bạn có trưng bày tác phẩm của các nghệ sĩ địa phương không? Nếu có, tôi có thể gửi email cho bạn một số hình ảnh chất lượng cao về tác phẩm của tôi. Chỉ cần gọi lại cho tôi theo số này, 555-0167.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6283, 5039, 83, 'Who is the message intended for?', 'A hotel manager', 'A café owner', 'A city official', 'A gallery curator', 'A', '[Dịch] Câu hỏi: Tin nhắn này dành cho ai?
A: Một người quản lý khách sạn
B: Một chủ quán café
C: Một viên chức thành phố
D: Một người phụ trách phòng trưng bày

Đáp án A là chính xác vì người nói đang cố gắng liên hệ với "the manager of Penver Inn and Suites", nghĩa là người quản lý của khách sạn Penver Inn and Suites.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5040, 221, '2025/test2/audio/test2_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6284, 5040, 84, 'What does the speaker mean when he says, "do you show works by local artists"?', 'He wants to buy art that was made nearby.', 'He hopes to learn about regional trends.', 'He thinks a museum exhibit is incomplete.', 'He wants the listener to display his work.', 'D', '[Dịch] Câu hỏi: Người nói có ý gì khi anh ấy nói "bạn có trưng bày tác phẩm của các nghệ sĩ địa phương không"?
A: Anh ấy muốn mua tác phẩm nghệ thuật được làm gần đó
B: Anh ấy hy vọng tìm hiểu về xu hướng khu vực
C: Anh ấy nghĩ một triển lãm bảo tàng chưa hoàn chỉnh
D: Anh ấy muốn người nghe trưng bày tác phẩm của mình

Đáp án D là chính xác vì ngữ cảnh cho thấy người nói là một nghệ sĩ địa phương đang tìm cách có được cơ hội trưng bày tác phẩm của mình tại khách sạn. Điều này được thể hiện qua việc anh ấy đề cập đến việc sống gần đó và sẵn sàng gửi hình ảnh tác phẩm của mình.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5041, 221, '2025/test2/audio/test2_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6285, 5041, 85, 'What does the speaker offer to do?', 'Send some electronic files', 'Answer the listener''s questions', 'Pay to use some images', 'Give some driving directions', 'A', '[Dịch] Câu hỏi: Người nói đề nghị làm gì?
A: Gửi một số tệp điện tử
B: Trả lời câu hỏi của người nghe
C: Trả tiền để sử dụng một số hình ảnh
D: Cung cấp chỉ đường

Đáp án A là chính xác vì người nói đề nghị "I can e-mail you some high-quality images of my work", nghĩa là gửi email một số hình ảnh chất lượng cao về tác phẩm của mình.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5042, 221, '2025/test2/audio/test2_question_86_88.mp3', NULL, 'Good morning, everyone. In this seminar, I''ll be teaching you how to lead meetings confidently and effectively. By the time were finished, you''ll know how to smoothly manage difficulties ranging from technical problems to late participants. I have conducted this seminar for businesses all over the country, and as you can see on my Web site, many of them say it has helped them succeed. Now, I''d like to start by telling you a few rules for the day. I believe that seminars, like meetings, go better when the participants have clear guidelines to follow.', 'Chào buổi sáng mọi người. Trong hội thảo này, tôi sẽ dạy các bạn cách điều hành cuộc họp một cách tự tin và hiệu quả. Đến khi kết thúc, các bạn sẽ biết cách xử lý trôi chảy các khó khăn từ vấn đề kỹ thuật đến người tham gia đến muộn. Tôi đã tổ chức hội thảo này cho các doanh nghiệp trên khắp đất nước, và như các bạn có thể thấy trên trang web của tôi, nhiều người trong số họ nói rằng nó đã giúp họ thành công. Bây giờ, tôi muốn bắt đầu bằng việc nói với các bạn một vài quy tắc cho ngày hôm nay. Tôi tin rằng các hội thảo, giống như các cuộc họp, sẽ diễn ra tốt hơn khi người tham gia có hướng dẫn rõ ràng để tuân theo.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6286, 5042, 86, 'What is the focus of the seminar?', 'Meeting management', 'Cost-reduction ideas', 'Staff recruitment', 'Data organization', 'A', '[Dịch] Câu hỏi: Trọng tâm của hội thảo là gì?
A: Quản lý cuộc họp
B: Ý tưởng giảm chi phí
C: Tuyển dụng nhân viên
D: Tổ chức dữ liệu

Đáp án A là chính xác vì người nói tuyên bố rõ ràng rằng họ sẽ dạy "how to lead meetings confidently and effectively" (cách điều hành cuộc họp một cách tự tin và hiệu quả).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5043, 221, '2025/test2/audio/test2_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6287, 5043, 87, 'According to the speaker, what can be found on a Web site?', 'A trial version of some software', 'A calendar of events', 'Sample contracts', 'Client testimonials', 'D', '[Dịch] Câu hỏi: Theo người nói, điều gì có thể được tìm thấy trên trang web?
A: Một phiên bản dùng thử của phần mềm nào đó
B: Một lịch sự kiện
C: Các mẫu hợp đồng
D: Lời chứng thực của khách hàng

Đáp án D là chính xác vì người nói đề cập rằng trên trang web của họ "many of them say it has helped them succeed", nghĩa là có nhiều lời chứng thực từ các doanh nghiệp đã tham gia hội thảo.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5044, 221, '2025/test2/audio/test2_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6288, 5044, 88, 'What will the listeners most likely do next?', 'Talk with a partner', 'Watch a short film', 'Listen to some rules', 'Get some refreshments', 'C', '[Dịch] Câu hỏi: Người nghe có khả năng sẽ làm gì tiếp theo?
A: Nói chuyện với một đối tác
B: Xem một bộ phim ngắn
C: Nghe một số quy tắc
D: Nhận một số đồ giải khát

Đáp án C là chính xác vì người nói tuyên bố "I''d like to start by telling you a few rules for the day", nghĩa là họ sẽ bắt đầu bằng việc nói về một số quy tắc cho ngày hôm đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5045, 221, '2025/test2/audio/test2_question_89_91.mp3', NULL, 'I called this meeting to announce an upgrade to our laboratory facility. The keypads on the doors will be replaced with keycard readers. This means that you will no longer need to memorize key codes to unlock the doors. Instead, everyone will be issued a scannable badge with their name and picture on it. The changeover will take place this weekend, so everyone needs to visit Information Technology before then to register for a badge. I''ve already done it, and the process only takes a few minutes.', 'Tôi đã gọi cuộc họp này để thông báo về việc nâng cấp cơ sở phòng thí nghiệm của chúng ta. Các bàn phím trên cửa sẽ được thay thế bằng máy đọc thẻ. Điều này có nghĩa là bạn sẽ không còn cần phải nhớ mã để mở cửa nữa. Thay vào đó, mọi người sẽ được cấp một thẻ có thể quét với tên và ảnh của họ trên đó. Việc chuyển đổi sẽ diễn ra vào cuối tuần này, vì vậy mọi người cần đến phòng Công nghệ Thông tin trước đó để đăng ký làm thẻ. Tôi đã làm rồi, và quy trình chỉ mất vài phút.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6289, 5045, 89, 'What is the speaker mainly discussing?', 'A facility tour', 'A security upgrade', 'An employee orientation', 'A cleaning requirement', 'B', '[Dịch] Câu hỏi: Người nói chủ yếu đang thảo luận về điều gì?
A: Một chuyến tham quan cơ sở
B: Nâng cấp an ninh
C: Định hướng nhân viên
D: Yêu cầu vệ sinh

Đáp án B là chính xác vì người nói đang thông báo về việc nâng cấp hệ thống an ninh của phòng thí nghiệm, cụ thể là thay thế bàn phím nhập mã bằng đầu đọc thẻ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5046, 221, '2025/test2/audio/test2_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6290, 5046, 90, 'What will the listeners receive?', 'An identification badge', 'A safety helmet', 'A floor plan', 'A computer program', 'A', '[Dịch] Câu hỏi: Người nghe sẽ nhận được gì?
A: Một thẻ nhận dạng
B: Một mũ bảo hiểm
C: Một bản vẽ mặt bằng
D: Một chương trình máy tính

Đáp án A là chính xác vì người nói cho biết "everyone will be issued a scannable badge with their name and picture on it", nghĩa là mọi người sẽ được cấp một thẻ có thể quét với tên và ảnh của họ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5047, 221, '2025/test2/audio/test2_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6291, 5047, 91, 'What does the speaker mean when he says, "the process only takes a few minutes"?', 'To express concern', 'To correct a scheduling mistake', 'To reassure the listeners', 'To ask for assistance', 'C', '[Dịch] Câu hỏi: Người nói có ý gì khi anh ấy nói "quy trình chỉ mất vài phút"?
A: Để bày tỏ sự lo lắng
B: Để sửa lỗi lên lịch
C: Để trấn an người nghe
D: Để yêu cầu hỗ trợ

Đáp án C là chính xác vì người nói đang cố gắng trấn an nhân viên rằng việc đăng ký làm thẻ sẽ không mất nhiều thời gian, bằng cách chia sẻ trải nghiệm cá nhân của mình.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5048, 221, '2025/test2/audio/test2_question_92_94.mp3', NULL, 'OK, let''s move on to the next part of today''s workshop. This part is very important for those of you whose duties include moving inventory by hand when it''s too small for the forklifts. When you''re lifting loads off of the ground, you must use the technique my colleague is demonstrating. Use it even when handling empty boxes. Remember, lifting many light loads throughout the day can be as hard on your body as picking up one heavy load. This technique has been proven to lower its users'' risk of suffering an injury.', 'Được rồi, hãy chuyển sang phần tiếp theo của buổi hội thảo hôm nay. Phần này rất quan trọng đối với những người trong số các bạn có nhiệm vụ di chuyển hàng tồn kho bằng tay khi chúng quá nhỏ để sử dụng xe nâng. Khi bạn nâng hàng từ mặt đất, bạn phải sử dụng kỹ thuật mà đồng nghiệp của tôi đang thị phạm. Sử dụng nó ngay cả khi xử lý các thùng rỗng. Hãy nhớ rằng, việc nâng nhiều vật nhẹ trong suốt cả ngày có thể khó khăn với cơ thể bạn như việc nâng một vật nặng. Kỹ thuật này đã được chứng minh là làm giảm nguy cơ chấn thương cho người sử dụng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6292, 5048, 92, 'Where do the listeners most likely work?', 'At a commercial laundry facility', 'At an auto repair shop', 'At a warehouse', 'At a moving company', 'C', '[Dịch] Câu hỏi: Người nghe có khả năng làm việc ở đâu?
A: Tại một cơ sở giặt là thương mại
B: Tại một tiệm sửa xe
C: Tại một kho hàng
D: Tại một công ty chuyển nhà

Đáp án C là chính xác vì nội dung đề cập đến việc di chuyển hàng tồn kho (moving inventory), sử dụng xe nâng (forklifts), và kỹ thuật nâng hàng, đây là những hoạt động điển hình trong một kho hàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5049, 221, '2025/test2/audio/test2_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6293, 5049, 93, 'What should the listeners use a certain technique for?', 'Storing chemicals', 'Lifting loads', 'Packing boxes', 'Folding fabric items', 'B', '[Dịch] Câu hỏi: Người nghe nên sử dụng một kỹ thuật nhất định để làm gì?
A: Lưu trữ hóa chất
B: Nâng hàng
C: Đóng gói thùng
D: Gấp các vật dụng bằng vải

Đáp án B là chính xác vì người nói hướng dẫn rõ ràng về việc sử dụng kỹ thuật khi "lifting loads off of the ground" (nâng hàng từ mặt đất) và nhấn mạnh tầm quan trọng của việc sử dụng kỹ thuật này ngay cả khi nâng các thùng rỗng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5050, 221, '2025/test2/audio/test2_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6294, 5050, 94, 'What benefit of the technique does the speaker mention?', 'Less wasting of supplies', 'Fewer complaints from customers', 'Increased productivity', 'Lower risk of injury', 'D', '[Dịch] Câu hỏi: Người nói đề cập đến lợi ích gì của kỹ thuật này?
A: Giảm lãng phí vật tư
B: Ít khiếu nại từ khách hàng hơn
C: Tăng năng suất
D: Giảm nguy cơ chấn thương

Đáp án D là chính xác vì cuối đoạn hội thoại nêu rõ "This technique has been proven to lower its users'' risk of suffering an injury", nghĩa là kỹ thuật này đã được chứng minh là làm giảm nguy cơ chấn thương cho người sử dụng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5051, 221, '2025/test2/audio/test2_question_95_97.mp3', '2025/test2/image/test2-p4-image-95.jpg', 'This is Ha-Yoon Sohn from WRN News. I''m here at the Malley Station bus stop for those traveling east on Roper Street, where the first of Oakford City''s state-of-the-art bus shelters has been built. As you can see, the shelter is enclosed on all sides and includes seating. However, the city''s primary reason for constructing these shelters is the powerful air purification system in its roof. This filters out car exhaust and dust so that transit users can breathe clean air while waiting for their bus. The Oakford Department of Transportation intends to put shelters at one hundred stops in the next two years. Visit the department''s Web site to see the planned construction dates for each site.', 'Đây là Ha-Yoon Sohn từ WRN News. Tôi đang ở điểm dừng xe buýt Malley Station dành cho những người đi về hướng đông trên đường Roper Street, nơi đã xây dựng trạm chờ xe buýt hiện đại đầu tiên của thành phố Oakford. Như bạn có thể thấy, trạm chờ được bao kín tất cả các mặt và có chỗ ngồi. Tuy nhiên, lý do chính của thành phố xây dựng những trạm chờ này là hệ thống lọc không khí mạnh mẽ trên mái. Hệ thống này lọc khí thải xe hơi và bụi để người sử dụng phương tiện công cộng có thể hít thở không khí sạch trong khi chờ xe buýt. Sở Giao thông Vận tải Oakford dự định đặt các trạm chờ tại một trăm điểm dừng trong hai năm tới. Truy cập trang web của sở để xem lịch trình xây dựng dự kiến cho từng địa điểm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6295, 5051, 95, 'Look at the graphic. Where is the speaker?', 'At Stop A', 'At Stop B', 'At Stop C', 'At Stop D', 'C', '[Dịch] Câu hỏi: Nhìn vào hình. Người nói đang ở đâu?
A: Tại Điểm dừng A
B: Tại Điểm dừng B
C: Tại Điểm dừng C
D: Tại Điểm dừng D

Đáp án C là chính xác vì trong đoạn hội thoại người nói cho biết họ đang ở điểm dừng xe buýt tại Malley Station dành cho những người đi về hướng đông trên đường Roper Street ("those traveling east on Roper Street"). Nhìn vào sơ đồ, Stop C nằm về phía đông của Malley Station trên đường Roper Street.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5052, 221, '2025/test2/audio/test2_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6296, 5052, 96, 'According to the speaker, what is the main reason for building the shelters?', 'To give people a place to sit while waiting', 'To keep people comfortable despite bad weather', 'To protect people from air pollution', 'To prevent traffic accidents', 'C', '[Dịch] Câu hỏi: Theo người nói, lý do chính để xây dựng các trạm chờ là gì?
A: Để cho mọi người có chỗ ngồi trong khi chờ đợi
B: Để giữ cho mọi người thoải mái bất chấp thời tiết xấu
C: Để bảo vệ mọi người khỏi ô nhiễm không khí
D: Để ngăn ngừa tai nạn giao thông

Đáp án C là chính xác vì người nói nêu rõ "the city''s primary reason for constructing these shelters is the powerful air purification system" và giải thích rằng hệ thống này lọc khí thải xe hơi và bụi để người chờ xe buýt có thể hít thở không khí sạch.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5053, 221, '2025/test2/audio/test2_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6297, 5053, 97, 'What is available online?', 'A virtual tour', 'Some statistics', 'A feedback form', 'A project schedule', 'D', '[Dịch] Câu hỏi: Điều gì có sẵn trực tuyến?
A: Một chuyến tham quan ảo
B: Một số thống kê
C: Một mẫu phản hồi
D: Lịch trình dự án

Đáp án D là chính xác vì cuối đoạn hội thoại, người nói hướng dẫn "Visit the department''s Web site to see the planned construction dates for each site", nghĩa là truy cập trang web của sở để xem lịch trình xây dựng dự kiến cho từng địa điểm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5054, 221, '2025/test2/audio/test2_question_98_100.mp3', '2025/test2/image/test2-p4-image-98.jpg', 'Attention, customers. If you love fruit-based desserts, you''ll want to stop by the bakery section this afternoon. Our supermarket is celebrating spring with daily specials on desserts made with fresh seasonal fruit. Yesterday''s cherry pie sold out well before closing time, and today our bakers have prepared a cool treat perfect for the warm weather. Samples are available at the bakery counter, so why not head over and try some? lf you decide to make a purchase, our staff will be happy to provide you with forks or spoons so that you can enjoy your dessert anywhere.', 'Chú ý, quý khách hàng. Nếu bạn yêu thích các món tráng miệng làm từ trái cây, bạn sẽ muốn ghé qua khu vực bánh ngọt chiều nay. Siêu thị của chúng tôi đang chào đón mùa xuân với các món tráng miệng đặc biệt hàng ngày được làm từ trái cây tươi theo mùa. Bánh pie cherry hôm qua đã bán hết trước giờ đóng cửa, và hôm nay các thợ làm bánh của chúng tôi đã chuẩn bị một món tráng miệng mát lạnh hoàn hảo cho thời tiết ấm áp. Các mẫu thử có sẵn tại quầy bánh, vậy tại sao không ghé qua và thử một chút? Nếu bạn quyết định mua, nhân viên của chúng tôi sẽ rất vui lòng cung cấp cho bạn dĩa hoặc thìa để bạn có thể thưởng thức món tráng miệng của mình ở bất kỳ đâu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6298, 5054, 98, 'Where does the announcement most likely take place?', 'At a coffee shop', 'At a fruit orchard', 'At a grocery store', 'At a cooking school', 'C', '[Dịch] Câu hỏi: Thông báo có khả năng diễn ra ở đâu?
A: Tại một quán cà phê
B: Tại một vườn cây ăn quả
C: Tại một cửa hàng tạp hóa
D: Tại một trường dạy nấu ăn

Đáp án C là chính xác vì thông báo đề cập đến "Our supermarket" (siêu thị của chúng tôi) và nói về khu vực bánh ngọt trong siêu thị (bakery section), cho thấy đây là một thông báo trong cửa hàng tạp hóa/siêu thị.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5055, 221, '2025/test2/audio/test2_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6299, 5055, 99, 'Look at the graphic. What is today''s special?', 'Cheesecake', 'Pie', 'Pudding', 'Tarts', 'C', '[Dịch] Câu hỏi: Nhìn vào hình. Món đặc biệt hôm nay là gì?
A: Bánh phô mai
B: Bánh pie
C: Bánh pudding xoài
D: Bánh tart

Đáp án C là chính xác vì trong đoạn hội thoại đề cập đến món tráng miệng hôm qua là bánh pie cherry, và nhìn vào menu "Spring Dessert Event Specials", món đặc biệt cho ngày tiếp theo (today) là Mango Pudding (bánh pudding xoài).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5056, 221, '2025/test2/audio/test2_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6300, 5056, 100, 'What is offered with a purchase?', 'A coupon', 'Eating utensils', 'Gift wrapping', 'Storage instructions', 'B', '[Dịch] Câu hỏi: Điều gì được cung cấp kèm theo khi mua hàng?
A: Một phiếu giảm giá
B: Dụng cụ ăn uống
C: Gói quà
D: Hướng dẫn bảo quản

Đáp án B là chính xác vì cuối đoạn hội thoại có đề cập "our staff will be happy to provide you with forks or spoons", nghĩa là nhân viên sẽ cung cấp dĩa hoặc thìa cho khách hàng khi mua bánh.');;

-- Data for 2025 Test2 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5057, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6301, 5057, 101, 'If you are not ---- with the service you receive at Luxe Salon, let our manager know.', 'pleased', 'pleasure', 'pleasing', 'please', 'A', 'Đáp án A (pleased) là đúng vì các lý do sau:
1. Cấu trúc "be pleased with something" là một cấu trúc cố định trong tiếng Anh, chỉ sự hài lòng với điều gì đó.
2. "Pleased" là tính từ (dạng quá khứ phân từ của động từ "please") được dùng sau động từ "be".
3. Cần một tính từ để diễn tả cảm xúc/trạng thái của chủ ngữ "you".
4. Các đáp án khác không phù hợp: "pleasure" là danh từ, "pleasing" là tính từ chỉ tính chất gây hài lòng, "please" là động từ.
Dịch câu hỏi: Nếu bạn không hài lòng với dịch vụ bạn nhận được tại Luxe Salon, hãy cho quản lý của chúng tôi biết.
Dịch đáp án:
A. pleased (tính từ: hài lòng)
B. pleasure (danh từ: niềm vui)
C. pleasing (tính từ: gây hài lòng)
D. please (động từ: làm hài lòng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5058, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6302, 5058, 102, 'When searching for an auto glass repair shop, make sure to choose one that has certified technicians like -----.', 'we', 'our', 'ours', 'ourselves', 'C', 'Đáp án C (ours) là đúng vì các lý do sau:
1. Trong câu này cần một đại từ sở hữu để thay thế cho "our technicians".
2. "Ours" là đại từ sở hữu độc lập, có thể đứng một mình thay thế cho danh từ được sở hữu.
3. Cấu trúc so sánh "like + đại từ" yêu cầu dùng đại từ sở hữu độc lập khi đề cập đến sở hữu.
4. Các đáp án khác không phù hợp: "we" là đại từ chủ ngữ, "our" là tính từ sở hữu cần danh từ theo sau, "ourselves" là đại từ phản thân.
Dịch câu hỏi: Khi tìm kiếm một cửa hàng sửa chữa kính ô tô, hãy chắc chắn chọn một cửa hàng có kỹ thuật viên được chứng nhận như của chúng tôi.
Dịch đáp án:
A. we (đại từ nhân xưng: chúng tôi)
B. our (tính từ sở hữu: của chúng tôi)
C. ours (đại từ sở hữu: cái của chúng tôi)
D. ourselves (đại từ phản thân: chính chúng tôi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5059, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6303, 5059, 103, 'Ms. Chin ----- Mr. Stepp''s duties while he is at a weeklong marketing seminar.', 'assumed', 'to assume', 'is assumed', 'will assume', 'D', 'Đáp án D (will assume) là đúng vì các lý do sau:
1. Ngữ cảnh câu chỉ một hành động sẽ xảy ra trong tương lai (trong khi ông Stepp tham dự hội thảo).
2. "Will assume" là thì tương lai đơn, diễn tả một hành động sẽ xảy ra.
3. Mệnh đề phụ "while he is at..." ở thì hiện tại đơn, thường đi kèm với thì tương lai ở mệnh đề chính trong trường hợp này.
4. Các đáp án khác không phù hợp: "assumed" là quá khứ, "to assume" là động từ nguyên mẫu, "is assumed" là bị động hiện tại.
Dịch câu hỏi: Cô Chin sẽ đảm nhận nhiệm vụ của ông Stepp trong khi ông ấy tham dự hội thảo marketing kéo dài một tuần.
Dịch đáp án:
A. assumed (động từ quá khứ: đã đảm nhận)
B. to assume (động từ nguyên mẫu: đảm nhận)
C. is assumed (bị động hiện tại: được đảm nhận)
D. will assume (tương lai đơn: sẽ đảm nhận)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5060, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6304, 5060, 104, 'After accepting a delivery from a frozen food supplier, —--- transfer the items to the restaurant''s freezer.', 'quickly', 'enough', 'closely', 'partly', 'A', 'Đáp án A (quickly) là đúng vì các lý do sau:
1. Câu cần một trạng từ chỉ cách thức để bổ nghĩa cho hành động "transfer".
2. "Quickly" (nhanh chóng) là trạng từ phù hợp về nghĩa khi xử lý thực phẩm đông lạnh.
3. Việc chuyển thực phẩm đông lạnh cần được thực hiện nhanh chóng để đảm bảo chất lượng.
4. Các đáp án khác không phù hợp về nghĩa: "enough" (đủ), "closely" (chặt chẽ), "partly" (một phần).
Dịch câu hỏi: Sau khi nhận hàng từ nhà cung cấp thực phẩm đông lạnh, hãy nhanh chóng chuyển các món hàng vào tủ đông của nhà hàng.
Dịch đáp án:
A. quickly (trạng từ: nhanh chóng)
B. enough (trạng từ: đủ)
C. closely (trạng từ: chặt chẽ)
D. partly (trạng từ: một phần)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5061, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6305, 5061, 105, 'Snap Sauces handed out all of its product samples to trade show attendees ----- 11 A.M. on the first day.', 'about', 'by', 'for', 'in', 'B', 'Đáp án B (by) là đúng vì các lý do sau:
1. Giới từ "by" được dùng để chỉ thời điểm một việc đã hoàn thành.
2. Cấu trúc "by + thời gian cụ thể" diễn tả việc gì đó được hoàn thành trước hoặc vào thời điểm đó.
3. Ngữ cảnh câu chỉ việc phát hết mẫu sản phẩm vào một thời điểm cụ thể.
4. Các đáp án khác không phù hợp: "about" (khoảng), "for" (cho), "in" (trong) không diễn tả được ý nghĩa hoàn thành.
Dịch câu hỏi: Snap Sauces đã phát hết tất cả các mẫu sản phẩm cho người tham dự hội chợ thương mại vào lúc 11 giờ sáng ngày đầu tiên.
Dịch đáp án:
A. about (giới từ: khoảng)
B. by (giới từ: vào lúc)
C. for (giới từ: cho)
D. in (giới từ: trong)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5062, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6306, 5062, 106, 'The Foy County Parks Department has compiled a list of hiking trails ---- by bus.', 'accessibility', 'accessible', 'accessibly', 'access', 'B', 'Đáp án B (accessible) là đúng vì các lý do sau:
1. Cần một tính từ để bổ nghĩa cho cụm danh từ "hiking trails".
2. "Accessible" là tính từ chỉ tính chất "có thể tiếp cận được".
3. Cấu trúc "accessible by + phương tiện" là cách diễn đạt chuẩn để chỉ khả năng tiếp cận bằng một phương tiện.
4. Các đáp án khác không phù hợp: "accessibility" là danh từ, "accessibly" là trạng từ, "access" là danh từ hoặc động từ.
Dịch câu hỏi: Sở Công viên Quận Foy đã tổng hợp danh sách các đường mòn đi bộ có thể tiếp cận bằng xe buýt.
Dịch đáp án:
A. accessibility (danh từ: khả năng tiếp cận)
B. accessible (tính từ: có thể tiếp cận)
C. accessibly (trạng từ: một cách có thể tiếp cận)
D. access (danh từ/động từ: sự tiếp cận/tiếp cận)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5063, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6307, 5063, 107, 'Nia Aldridge has shown ----- for learning the skills needed to become a software engineer.', 'enthusiast', 'enthusiastic', 'enthusiastically', 'enthusiasm', 'D', 'Đáp án D (enthusiasm) là đúng vì các lý do sau:
1. Sau động từ "show" cần một danh từ làm tân ngữ.
2. "Enthusiasm" là danh từ chỉ sự nhiệt tình, hứng thú.
3. Cấu trúc "show enthusiasm for something" là cách diễn đạt chuẩn để chỉ sự nhiệt tình với điều gì đó.
4. Các đáp án khác không phù hợp: "enthusiast" là danh từ chỉ người, "enthusiastic" là tính từ, "enthusiastically" là trạng từ.
Dịch câu hỏi: Nia Aldridge đã thể hiện sự nhiệt tình trong việc học các kỹ năng cần thiết để trở thành kỹ sư phần mềm.
Dịch đáp án:
A. enthusiast (danh từ: người nhiệt tình)
B. enthusiastic (tính từ: nhiệt tình)
C. enthusiastically (trạng từ: một cách nhiệt tình)
D. enthusiasm (danh từ: sự nhiệt tình)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5064, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6308, 5064, 108, 'In accordance with company policy, incomplete requests for reimbursement will not be -----.', 'approved', 'achieved', 'decided', 'increased', 'A', 'Đáp án A (approved) là đúng vì các lý do sau:
1. Câu ở dạng bị động phủ định (will not be + quá khứ phân từ).
2. "Approve" là động từ phù hợp về nghĩa với việc chấp thuận/phê duyệt yêu cầu hoàn tiền.
3. "Approved" là quá khứ phân từ dùng trong cấu trúc bị động.
4. Các đáp án khác không phù hợp về nghĩa với "requests for reimbursement": "achieved" (đạt được), "decided" (quyết định), "increased" (tăng lên).
Dịch câu hỏi: Theo chính sách công ty, các yêu cầu hoàn tiền không đầy đủ sẽ không được phê duyệt.
Dịch đáp án:
A. approved (quá khứ phân từ: được phê duyệt)
B. achieved (quá khứ phân từ: đạt được)
C. decided (quá khứ phân từ: được quyết định)
D. increased (quá khứ phân từ: được tăng lên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5065, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6309, 5065, 109, 'Sonia Ray was the lead singer of the band Indigo Mist for several years ----- becoming a solo act.', 'before', 'except', 'then', 'yet', 'A', 'Đáp án A (before) là đúng vì các lý do sau:
1. Cần một liên từ chỉ thời gian để kết nối hai sự kiện.
2. "Before" (trước khi) là liên từ thích hợp để chỉ sự kiện xảy ra trước một sự kiện khác.
3. Cấu trúc "before + V-ing" diễn tả một hành động xảy ra trước hành động được chỉ bởi V-ing.
4. Các đáp án khác không phù hợp: "except" (ngoại trừ), "then" (sau đó), "yet" (tuy nhiên) không diễn tả được trình tự thời gian rõ ràng.
Dịch câu hỏi: Sonia Ray là ca sĩ chính của ban nhạc Indigo Mist trong nhiều năm trước khi trở thành nghệ sĩ solo.
Dịch đáp án:
A. before (liên từ: trước khi)
B. except (giới từ/liên từ: ngoại trừ)
C. then (phó từ: sau đó)
D. yet (liên từ: tuy nhiên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5066, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6310, 5066, 110, 'The employee picnic celebrating the start of summer may need to be postponed if the rain -----.', 'continue', 'continues', 'had continued', 'continuing', 'B', 'Đáp án B (continues) là đúng vì các lý do sau:
1. Đây là câu điều kiện loại 1 diễn tả điều kiện có thể xảy ra ở hiện tại hoặc tương lai.
2. Trong mệnh đề if, ta dùng động từ ở thì hiện tại đơn.
3. "Rain" là danh từ số ít nên động từ phải chia ở ngôi thứ 3 số ít (thêm -s).
4. Các đáp án khác không phù hợp: "continue" thiếu -s, "had continued" là quá khứ hoàn thành, "continuing" là hiện tại phân từ.
Dịch câu hỏi: Bữa picnic của nhân viên chào mừng mùa hè có thể cần được hoãn lại nếu trời tiếp tục mưa.
Dịch đáp án:
A. continue (động từ nguyên thể: tiếp tục)
B. continues (động từ thì hiện tại đơn, ngôi 3 số ít: tiếp tục)
C. had continued (động từ quá khứ hoàn thành: đã tiếp tục)
D. continuing (hiện tại phân từ: đang tiếp tục)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5067, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6311, 5067, 111, 'Ever since the Dwyerton Building''s construction, its architecture has been considered the most ----- in the city.', 'beauty', 'beauties', 'beautiful', 'beautifully', 'C', 'Đáp án C (beautiful) là đúng vì các lý do sau:
1. Ta cần một tính từ ở dạng so sánh nhất (most + tính từ) để diễn tả mức độ cao nhất.
2. "Beautiful" là tính từ, có thể dùng với "most" để tạo thành dạng so sánh nhất.
3. Vị trí này cần một tính từ để bổ nghĩa cho "architecture" (kiến trúc).
4. Cấu trúc "be considered + the most + tính từ" là cấu trúc chuẩn để diễn tả đánh giá ở mức độ cao nhất.
5. Các đáp án khác không phù hợp: "beauty" là danh từ số ít, "beauties" là danh từ số nhiều, "beautifully" là trạng từ.
Dịch câu hỏi: Kể từ khi xây dựng, kiến trúc của tòa nhà Dwyerton đã được coi là đẹp nhất trong thành phố.
Dịch đáp án:
A. beauty (danh từ số ít: vẻ đẹp)
B. beauties (danh từ số nhiều: những vẻ đẹp)
C. beautiful (tính từ: đẹp)
D. beautifully (trạng từ: một cách đẹp đẽ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5068, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6312, 5068, 112, 'UBN Tours will offer daily walking tours of downtown Peralt ----- this week onward.', 'among', 'from', 'over', 'toward', 'B', 'Đáp án B (from) là đúng vì các lý do sau:
1. Cần một giới từ chỉ điểm bắt đầu của một khoảng thời gian.
2. "From" được dùng trong cụm "from... onward" để chỉ thời điểm bắt đầu của một hoạt động sẽ tiếp tục.
3. Cấu trúc "from + thời điểm + onward" là cách diễn đạt chuẩn để chỉ một hoạt động bắt đầu từ một thời điểm và tiếp tục.
4. Các đáp án khác không phù hợp: "among" (giữa), "over" (qua), "toward" (hướng về) không thể kết hợp với "onward".
Dịch câu hỏi: UBN Tours sẽ tổ chức các tour đi bộ hàng ngày ở trung tâm Peralt từ tuần này trở đi.
Dịch đáp án:
A. among (giới từ: giữa)
B. from (giới từ: từ)
C. over (giới từ: qua)
D. toward (giới từ: hướng về)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5069, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6313, 5069, 113, 'The management team of Shelzan Pharmaceuticals has developed a ----- for expanding its operations into China within a few years.', 'meeting', 'benefit', 'strategy', 'recognition', 'C', 'Đáp án C (strategy) là đúng vì các lý do sau:
1. Ta cần một danh từ chỉ kế hoạch/chiến lược phát triển kinh doanh.
2. "Strategy" (chiến lược) là danh từ phù hợp với ngữ cảnh mở rộng hoạt động kinh doanh.
3. Cụm từ "develop a strategy" là collocation (kết hợp từ) phổ biến trong ngữ cảnh kinh doanh.
4. Các đáp án khác không phù hợp về nghĩa: "meeting" (cuộc họp), "benefit" (lợi ích), "recognition" (sự công nhận) không phù hợp với ngữ cảnh mở rộng hoạt động.
Dịch câu hỏi: Đội ngũ quản lý của Shelzan Pharmaceuticals đã phát triển một chiến lược để mở rộng hoạt động sang Trung Quốc trong vài năm tới.
Dịch đáp án:
A. meeting (danh từ: cuộc họp)
B. benefit (danh từ: lợi ích)
C. strategy (danh từ: chiến lược)
D. recognition (danh từ: sự công nhận)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5070, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6314, 5070, 114, 'By conducting extensive marketing -----, RIV Associates can produce crucial insights into your target consumers.', 'research', 'researched', 'researching', 'researchers', 'A', 'Đáp án A (research) là đúng vì các lý do sau:
1. Cần một danh từ để làm tân ngữ của cụm "conducting marketing ___".
2. "Research" là danh từ không đếm được, chỉ hoạt động nghiên cứu, khảo sát.
3. Cụm từ "conduct research" là collocation phổ biến trong tiếng Anh.
4. Các đáp án khác không phù hợp: "researched" là động từ quá khứ/tính từ, "researching" là động từ dạng -ing, "researchers" là danh từ chỉ người nghiên cứu.
Dịch câu hỏi: Bằng cách tiến hành nghiên cứu tiếp thị rộng rãi, RIV Associates có thể đưa ra những hiểu biết quan trọng về khách hàng mục tiêu của bạn.
Dịch đáp án:
A. research (danh từ: nghiên cứu)
B. researched (động từ quá khứ/tính từ: đã nghiên cứu)
C. researching (động từ dạng -ing: đang nghiên cứu)
D. researchers (danh từ số nhiều: các nhà nghiên cứu)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5071, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6315, 5071, 115, '---- the old lighting has been replaced with more efficient fixtures, the office''s electricity bills will be lower.', 'Unless', 'At once', 'Now that', 'Although', 'C', 'Đáp án C (Now that) là đúng vì các lý do sau:
1. Ta cần một cụm từ nối chỉ mối quan hệ nhân quả giữa hai sự việc.
2. "Now that" dùng để chỉ một điều gì đó vừa xảy ra và dẫn đến kết quả tức thì.
3. Cấu trúc "Now that + mệnh đề, + kết quả" diễn tả kết quả trực tiếp của một hành động vừa hoàn thành.
4. Các đáp án khác không phù hợp: "Unless" (trừ khi) chỉ điều kiện, "At once" (ngay lập tức) là trạng từ, "Although" (mặc dù) chỉ sự nhượng bộ.
Dịch câu hỏi: Giờ đây khi hệ thống đèn cũ đã được thay thế bằng các thiết bị hiệu quả hơn, hóa đơn điện của văn phòng sẽ thấp hơn.
Dịch đáp án:
A. Unless (liên từ: trừ khi)
B. At once (cụm trạng từ: ngay lập tức)
C. Now that (cụm liên từ: giờ đây khi)
D. Although (liên từ: mặc dù)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5072, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6316, 5072, 116, 'For the premiere of its new film, Lofton Studios''s publicity team has been instructed to reserve the largest theater -----.', 'secure', 'certain', 'welcome', 'available', 'D', 'Đáp án D (available) là đúng vì các lý do sau:
1. Cần một tính từ bổ nghĩa cho "largest theater".
2. "Available" (có sẵn) là tính từ phù hợp để chỉ rạp lớn nhất còn trống/có thể đặt được.
3. Cấu trúc "the largest theater available" là cách diễn đạt phổ biến trong việc mô tả không gian có thể sử dụng.
4. Các đáp án khác không phù hợp về nghĩa: "secure" (an toàn), "certain" (chắc chắn), "welcome" (được chào đón).
Dịch câu hỏi: Cho buổi công chiếu bộ phim mới, đội quảng bá của Lofton Studios đã được chỉ đạo đặt rạp lớn nhất còn trống.
Dịch đáp án:
A. secure (tính từ: an toàn)
B. certain (tính từ: chắc chắn)
C. welcome (tính từ: được chào đón)
D. available (tính từ: có sẵn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5073, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6317, 5073, 117, 'The company encourages customers to review its products ----- on shopping Web sites.', 'favorable', 'favorably', 'favorite', 'favor', 'B', 'Đáp án B (favorably) là đúng vì các lý do sau:
1. Cần một trạng từ bổ nghĩa cho động từ "review" (đánh giá).
2. "Favorably" (một cách thuận lợi/tích cực) là trạng từ mô tả cách thức đánh giá.
3. Trạng từ kết thúc bằng -ly này được tạo từ tính từ "favorable".
4. Các đáp án khác không phù hợp: "favorable" là tính từ, "favorite" là tính từ ưa thích, "favor" là danh từ/động từ.
Dịch câu hỏi: Công ty khuyến khích khách hàng đánh giá sản phẩm một cách tích cực trên các trang web mua sắm.
Dịch đáp án:
A. favorable (tính từ: thuận lợi)
B. favorably (trạng từ: một cách thuận lợi)
C. favorite (tính từ: ưa thích)
D. favor (danh từ/động từ: ưu ái)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5074, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6318, 5074, 118, '----- the next few weeks, the CEO of Serna Mining will announce her successor.', 'Until', 'Provided', 'Within', 'Involving', 'C', 'Đáp án C (Within) là đúng vì các lý do sau:
1. Cần một giới từ chỉ khoảng thời gian để một việc sẽ xảy ra.
2. "Within" (trong vòng) là giới từ thích hợp để chỉ một việc sẽ xảy ra trong một khoảng thời gian.
3. Cấu trúc "within + khoảng thời gian" là cách diễn đạt chuẩn để chỉ thời hạn.
4. Các đáp án khác không phù hợp: "Until" (cho đến), "Provided" (với điều kiện), "Involving" (liên quan đến).
Dịch câu hỏi: Trong vòng vài tuần tới, CEO của Serna Mining sẽ công bố người kế nhiệm của bà ấy.
Dịch đáp án:
A. Until (giới từ: cho đến)
B. Provided (liên từ: với điều kiện)
C. Within (giới từ: trong vòng)
D. Involving (động từ -ing: liên quan đến)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5075, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6319, 5075, 119, 'Planning committee members were proud that the final cost of the project matched their initial estimate -----.', 'occasionally', 'briefly', 'lately', 'exactly', 'D', 'Đáp án D (exactly) là đúng vì các lý do sau:
1. Cần một trạng từ bổ nghĩa cho động từ "matched" để chỉ mức độ chính xác của sự trùng khớp.
2. "Exactly" (chính xác) là trạng từ phù hợp để chỉ sự trùng khớp hoàn toàn giữa chi phí cuối và dự toán ban đầu.
3. Về nghĩa, trong ngữ cảnh này cần nhấn mạnh độ chính xác của ước tính.
4. Các đáp án khác không phù hợp: "occasionally" (thỉnh thoảng), "briefly" (ngắn gọn), "lately" (gần đây).
Dịch câu hỏi: Các thành viên ủy ban kế hoạch tự hào rằng chi phí cuối cùng của dự án trùng khớp chính xác với dự toán ban đầu của họ.
Dịch đáp án:
A. occasionally (trạng từ: thỉnh thoảng)
B. briefly (trạng từ: ngắn gọn)
C. lately (trạng từ: gần đây)
D. exactly (trạng từ: chính xác)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5076, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6320, 5076, 120, 'The catalogue should include the information that dishwashers described as "compact" are ----- 18 inches wide.', 'normal', 'normally', 'normalize', 'normalization', 'B', 'Đáp án B (normally) là đúng vì các lý do sau:
1. Cần một trạng từ để bổ nghĩa cho thông tin về kích thước.
2. "Normally" (thông thường) là trạng từ phù hợp để chỉ kích thước tiêu chuẩn.
3. Cấu trúc này diễn tả một sự thật phổ biến về thông số sản phẩm.
4. Các đáp án khác không phù hợp: "normal" là tính từ, "normalize" là động từ, "normalization" là danh từ.
Dịch câu hỏi: Danh mục cần bao gồm thông tin rằng các máy rửa bát được mô tả là "nhỏ gọn" thường rộng 18 inch.
Dịch đáp án:
A. normal (tính từ: bình thường)
B. normally (trạng từ: thông thường)
C. normalize (động từ: chuẩn hóa)
D. normalization (danh từ: sự chuẩn hóa)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5077, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6321, 5077, 121, 'After considering sites around the country, Noitech —--- built its new factory in Murin.', 'intensely', 'ultimately', 'concisely', 'already', 'B', 'Đáp án B (ultimately) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ kết quả cuối cùng sau quá trình cân nhắc.
2. "Ultimately" (cuối cùng) là trạng từ phù hợp để chỉ quyết định sau cùng.
3. Từ này thường được dùng sau một quá trình xem xét kỹ lưỡng.
4. Các đáp án khác không phù hợp về nghĩa: "intensely" (mạnh mẽ), "concisely" (ngắn gọn), "already" (đã).
Dịch câu hỏi: Sau khi cân nhắc các địa điểm trên khắp đất nước, cuối cùng Noitech đã xây nhà máy mới của họ ở Murin.
Dịch đáp án:
A. intensely (trạng từ: mạnh mẽ)
B. ultimately (trạng từ: cuối cùng)
C. concisely (trạng từ: ngắn gọn)
D. already (trạng từ: đã)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5078, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6322, 5078, 122, 'Clury Insurance made a ----- donation to charity on its tenth anniversary in business.', 'wide', 'primary', 'sizable', 'severe', 'C', 'Đáp án C (sizable) là đúng vì các lý do sau:
1. Cần một tính từ để mô tả quy mô của khoản quyên góp.
2. "Sizable" (đáng kể) là tính từ thích hợp để chỉ một khoản tiền lớn.
3. Collocation "sizable donation" (khoản quyên góp đáng kể) là cụm từ phổ biến.
4. Các đáp án khác không phù hợp: "wide" (rộng), "primary" (chính), "severe" (nghiêm trọng).
Dịch câu hỏi: Clury Insurance đã thực hiện một khoản quyên góp đáng kể cho từ thiện nhân kỷ niệm 10 năm hoạt động kinh doanh.
Dịch đáp án:
A. wide (tính từ: rộng)
B. primary (tính từ: chính)
C. sizable (tính từ: đáng kể)
D. severe (tính từ: nghiêm trọng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5079, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6323, 5079, 123, 'Bullard Park Hotel has ---- to upgrade its business facilities in preparation for the upcoming trade convention.', 'since', 'shortly', 'whereas', 'attempted', 'D', 'Đáp án D (attempted) là đúng vì các lý do sau:
1. Cần một động từ ở quá khứ phân từ để kết hợp với trợ động từ "has".
2. "Attempted" (đã cố gắng) là động từ phù hợp để chỉ nỗ lực nâng cấp cơ sở vật chất.
3. Cấu trúc "has attempted to + động từ nguyên mẫu" diễn tả một hành động cố gắng thực hiện.
4. Các đáp án khác không phù hợp: "since" (kể từ), "shortly" (chẳng bao lâu), "whereas" (trong khi).
Dịch câu hỏi: Khách sạn Bullard Park đã cố gắng nâng cấp các cơ sở vật chất phục vụ kinh doanh để chuẩn bị cho hội nghị thương mại sắp tới.
Dịch đáp án:
A. since (liên từ/giới từ: kể từ)
B. shortly (trạng từ: chẳng bao lâu)
C. whereas (liên từ: trong khi)
D. attempted (động từ quá khứ phân từ: đã cố gắng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5080, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6324, 5080, 124, 'Throughout his career as an artist, Mr. Lipscomb has ---- in creating intricate sculptures out of recycled materials.', 'specialized', 'distinguished', 'approached', 'committed', 'A', 'Đáp án A (specialized) là đúng vì các lý do sau:
1. Cần một động từ chỉ sự tập trung vào một lĩnh vực cụ thể.
2. "Specialize" (chuyên môn hóa) là động từ thích hợp để chỉ việc tập trung vào một kỹ năng/lĩnh vực cụ thể.
3. Cấu trúc "specialize in + V-ing" là cấu trúc chuẩn để chỉ lĩnh vực chuyên môn.
4. Các đáp án khác không phù hợp về nghĩa và cấu trúc: "distinguished" (nổi bật), "approached" (tiếp cận), "committed" (cam kết).
Dịch câu hỏi: Trong suốt sự nghiệp với tư cách là một nghệ sĩ, ông Lipscomb đã chuyên về việc tạo ra các tác phẩm điêu khắc phức tạp từ vật liệu tái chế.
Dịch đáp án:
A. specialized (động từ quá khứ: chuyên môn hóa)
B. distinguished (động từ quá khứ: nổi bật)
C. approached (động từ quá khứ: tiếp cận)
D. committed (động từ quá khứ: cam kết)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5081, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6325, 5081, 125, 'A newspaper article on the ----- of public transportation in Laes City led to calls for fare decreases.', 'afforded', 'affordably', 'affordability', 'affordable', 'C', 'Đáp án C (affordability) là đúng vì các lý do sau:
1. Cần một danh từ (sau mạo từ "the") để chỉ tính có thể chi trả được của giao thông công cộng.
2. "Affordability" là danh từ được tạo từ tính từ "affordable" bằng cách thêm hậu tố "-ity".
3. Đây là một danh từ trừu tượng chỉ chất lượng hoặc trạng thái của việc có thể chi trả được.
4. Các đáp án khác không phù hợp: "afforded" là động từ quá khứ, "affordably" là trạng từ, "affordable" là tính từ.
Dịch câu hỏi: Một bài báo về khả năng chi trả cho giao thông công cộng ở thành phố Laes đã dẫn đến những yêu cầu giảm giá vé.
Dịch đáp án:
A. afforded (động từ quá khứ: đã có khả năng chi trả)
B. affordably (trạng từ: một cách có thể chi trả)
C. affordability (danh từ: khả năng chi trả)
D. affordable (tính từ: có thể chi trả được)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5082, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6326, 5082, 126, 'Poulik Enterprises'' stock prices rose upon the news of its proposed ----- of a competitor.', 'investment', 'acquisition', 'agenda', 'vision', 'B', 'Đáp án B (acquisition) là đúng vì các lý do sau:
1. Cần một danh từ chỉ hành động mua lại/tiếp quản một công ty khác.
2. "Acquisition" là thuật ngữ kinh doanh chính xác để chỉ việc một công ty mua lại công ty khác.
3. Cụm từ "proposed acquisition" (kế hoạch mua lại) là thuật ngữ phổ biến trong tin tức kinh doanh.
4. Các đáp án khác không phù hợp về nghĩa: "investment" (đầu tư), "agenda" (chương trình nghị sự), "vision" (tầm nhìn).
Dịch câu hỏi: Giá cổ phiếu của Poulik Enterprises tăng sau tin tức về kế hoạch mua lại một đối thủ cạnh tranh.
Dịch đáp án:
A. investment (danh từ: sự đầu tư)
B. acquisition (danh từ: sự mua lại)
C. agenda (danh từ: chương trình nghị sự)
D. vision (danh từ: tầm nhìn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5083, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6327, 5083, 127, 'Croft Fitness Center has state-of-the-art equipment but a ----- relaxed atmosphere.', 'remark', 'remarks', 'remarking', 'remarkably', 'D', 'Đáp án D (remarkably) là đúng vì các lý do sau:
1. Cần một trạng từ để bổ nghĩa cho tính từ "relaxed".
2. "Remarkably" (đáng chú ý/đặc biệt) là trạng từ thích hợp để nhấn mạnh mức độ của tính từ.
3. Cấu trúc "remarkably + tính từ" là cách diễn đạt phổ biến để nhấn mạnh một đặc điểm.
4. Các đáp án khác không phù hợp: "remark" là danh từ/động từ, "remarks" là danh từ số nhiều, "remarking" là động từ -ing.
Dịch câu hỏi: Trung tâm thể dục Croft có thiết bị hiện đại nhưng lại có bầu không khí đặc biệt thoải mái.
Dịch đáp án:
A. remark (danh từ/động từ: nhận xét/nhận xét)
B. remarks (danh từ số nhiều: những nhận xét)
C. remarking (động từ -ing: đang nhận xét)
D. remarkably (trạng từ: đặc biệt/đáng chú ý)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5084, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6328, 5084, 128, 'The warranty expires when five years have passed since purchase or the tractor has been driven for 5,000 hours, ----- occurs first.', 'anything', 'whose', 'however', 'whichever', 'D', 'Đáp án D (whichever) là đúng vì các lý do sau:
1. Cần một đại từ quan hệ để chỉ việc chọn một trong hai điều kiện xảy ra trước.
2. "Whichever" (cái nào...thì) là đại từ quan hệ thích hợp để chỉ sự lựa chọn giữa hai hay nhiều khả năng.
3. Cấu trúc "whichever occurs first" là cách diễn đạt chuẩn trong các điều khoản bảo hành.
4. Các đáp án khác không phù hợp: "anything" (bất cứ điều gì), "whose" (của ai), "however" (tuy nhiên).
Dịch câu hỏi: Bảo hành hết hạn khi năm năm đã trôi qua kể từ khi mua hoặc máy kéo đã được sử dụng trong 5.000 giờ, tùy điều kiện nào đến trước.
Dịch đáp án:
A. anything (đại từ: bất cứ điều gì)
B. whose (đại từ quan hệ: của ai)
C. however (phó từ: tuy nhiên)
D. whichever (đại từ quan hệ: cái nào)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5085, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6329, 5085, 129, '----- the feedback from the focus group, we should choose a more readable font for the product label.', 'Because', 'Whether', 'Considering', 'Alongside', 'C', 'Đáp án C (Considering) là đúng vì các lý do sau:
1. Cần một phân từ hiện tại để mở đầu mệnh đề phân từ chỉ sự cân nhắc.
2. "Considering" là phân từ hiện tại của động từ "consider", dùng để chỉ việc xem xét thông tin để ra quyết định.
3. Cấu trúc "Considering + danh từ" là cách diễn đạt phổ biến để chỉ việc dựa vào thông tin nào đó để đưa ra kết luận.
4. Các đáp án khác không phù hợp: "Because" (bởi vì) cần mệnh đề đầy đủ, "Whether" (liệu rằng), "Alongside" (bên cạnh).
Dịch câu hỏi: Xét đến phản hồi từ nhóm nghiên cứu trọng tâm, chúng ta nên chọn một phông chữ dễ đọc hơn cho nhãn sản phẩm.
Dịch đáp án:
A. Because (liên từ: bởi vì)
B. Whether (liên từ: liệu rằng)
C. Considering (phân từ hiện tại: xét đến)
D. Alongside (giới từ: bên cạnh)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5086, 222, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6330, 5086, 130, 'Following Thursday''s training, Ms. Adkins ----- the advantages of the new database software.', 'acknowledged', 'nominated', 'belonged', 'permitted', 'A', 'Đáp án A (acknowledged) là đúng vì các lý do sau:
1. Cần một động từ ở thì quá khứ đơn để diễn tả hành động đã hoàn thành.
2. "Acknowledge" (công nhận/thừa nhận) là động từ phù hợp với ngữ cảnh nhận ra ưu điểm của phần mềm.
3. Collocation "acknowledge advantages" (công nhận ưu điểm) là cụm từ phổ biến và phù hợp về nghĩa.
4. Các đáp án khác không phù hợp về nghĩa: "nominated" (đề cử), "belonged" (thuộc về), "permitted" (cho phép).
Dịch câu hỏi: Sau buổi đào tạo hôm thứ Năm, cô Adkins đã công nhận những ưu điểm của phần mềm cơ sở dữ liệu mới.
Dịch đáp án:
A. acknowledged (động từ quá khứ: đã công nhận)
B. nominated (động từ quá khứ: đã đề cử)
C. belonged (động từ quá khứ: đã thuộc về)
D. permitted (động từ quá khứ: đã cho phép)');;

-- Data for 2025 Test2 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5087, 223, NULL, NULL, 'From: customerservice@office-loft.com
To: jahan.soltani@iux-mail.com
Subject: Re: Order #7823
Date: July 21
Attachment: Coupon
Dear Mr. Soltani,
We are sorry to hear that Order #7823 arrived at your business after the promised date of July 14. It appears that the order 131 ...... later than scheduled due to a problem with our shipping provider. We will refund the shipping charge to your account. In addition, please accept the attached coupon as compensation for the 132...... . It will give you a 30% discount on your next order from our Web site. 133....... . You may also print out the coupon and use it at 134....... of our offline stores.
Sincerely,
Scott Conrad
Office Loft Customer Service', 'Từ: customerservice@office-loft.com
Đến: jahan.soltani@iux-mail.com
Chủ đề: Trả lời: Đơn hàng #7823
Ngày: 21 tháng 7
Tệp đính kèm: Phiếu giảm giá
Kính gửi ông Soltani,
Chúng tôi rất tiếc khi biết rằng Đơn hàng #7823 đã đến doanh nghiệp của ông sau ngày hẹn 14 tháng 7. Có vẻ như đơn hàng đã được giao muộn hơn dự kiến do sự cố với nhà cung cấp dịch vụ vận chuyển của chúng tôi. Chúng tôi sẽ hoàn lại phí vận chuyển vào tài khoản của ông. Ngoài ra, vui lòng nhận phiếu giảm giá đính kèm để bồi thường cho sự chậm trễ này. Phiếu giảm giá sẽ cho ông giảm 30% cho đơn hàng tiếp theo từ trang web của chúng tôi. Chỉ cần nhập mã ở trên cùng khi thanh toán. Ông cũng có thể in phiếu giảm giá và sử dụng tại một trong các cửa hàng trực tiếp của chúng tôi.
Trân trọng,
Scott Conrad
Dịch vụ Khách hàng Office Loft');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6331, 5087, 131, NULL, 'will be delivered', 'had to deliver', 'was delivered', 'is delivering', 'C', 'A. will be delivered (sẽ được giao)
B. had to deliver (đã phải giao)
C. was delivered (đã được giao)
D. is delivering (đang giao)
Đáp án đúng là C (was delivered).
Giải thích:
Cấu trúc câu cần một động từ ở thể bị động, thì quá khứ đơn vì:
- Sự việc đã xảy ra trong quá khứ (đơn hàng đã đến muộn)
- Thư đang xin lỗi về việc giao hàng trễ đã xảy ra
- ''Was delivered'' phù hợp với ngữ cảnh về một hành động đã hoàn thành
Các đáp án khác không phù hợp:
''Will be delivered'' - thì tương lai không phù hợp vì đang nói về sự việc đã xảy ra
''Had to deliver'' - không phù hợp về nghĩa và cấu trúc câu
''Is delivering'' - thì hiện tại tiếp diễn không phù hợp với sự việc đã hoàn thành');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6332, 5087, 132, NULL, 'delay', 'work', 'loss', 'risk', 'A', 'A. delay (sự chậm trễ)
B. work (công việc)
C. loss (sự mất mát)
D. risk (rủi ro)
Đáp án đúng là A (delay).
Giải thích:
''Delay'' là từ phù hợp nhất vì:
- Ngữ cảnh đang đề cập đến việc giao hàng trễ hạn
- Công ty đang xin lỗi và bồi thường cho sự chậm trễ này
- ''Compensation for the delay'' là cụm từ phổ biến trong giao tiếp business
Các đáp án khác không phù hợp:
''Work'' không liên quan đến vấn đề đang đề cập
''Loss'' không phù hợp vì khách hàng không bị mất mát gì
''Risk'' không phù hợp vì sự việc đã xảy ra, không phải rủi ro');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6333, 5087, 133, NULL, 'Thank you again for the feedback.', 'Your user account will be restored soon.', 'We hope you found the items satisfactory.', 'Simply enter the code at the top at checkout.', 'D', 'A. Thank you again for the feedback. (Cảm ơn phản hồi của ông một lần nữa)
B. Your user account will be restored soon. (Tài khoản của ông sẽ sớm được khôi phục)
C. We hope you found the items satisfactory. (Chúng tôi hy vọng ông hài lòng với các mặt hàng)
D. Simply enter the code at the top at checkout. (Chỉ cần nhập mã ở trên cùng khi thanh toán)
Đáp án đúng là D.
Giải thích:
Câu D phù hợp nhất vì:
- Tiếp nối thông tin về phiếu giảm giá và cách sử dụng
- Hướng dẫn cụ thể cách sử dụng mã giảm giá khi mua hàng
- Phù hợp với ngữ cảnh của email
Các đáp án khác không phù hợp:
A: Không liên quan đến nội dung về phiếu giảm giá
B: Không đề cập đến vấn đề tài khoản trong email
C: Không phù hợp với nội dung đang bàn về bồi thường');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6334, 5087, 134, NULL, 'each', 'one', 'that', 'which', 'B', 'A. each (mỗi)
B. one (một)
C. that (đó)
D. which (cái mà)
Đáp án đúng là B (one).
Giải thích:
''One'' phù hợp nhất trong ngữ cảnh này:
- ''One of + danh từ số nhiều'' là cấu trúc phổ biến chỉ ''một trong số''
- Phù hợp khi nói về việc sử dụng phiếu giảm giá tại một cửa hàng bất kỳ
- Cách diễn đạt tự nhiên trong tiếng Anh
Các đáp án khác không phù hợp:
''Each'' không phù hợp với ''of'' trong cấu trúc này
''That'' không phù hợp về ngữ pháp trong cấu trúc này
''Which'' không được dùng sau ''at'' trong ngữ cảnh này');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5088, 223, NULL, NULL, 'From: Clarence Tibbetts
To: Banuelos Financial staff
Date: March 8
Subject: Carpeting work
As you all have probably noticed, the carpet in our reception area is quite 135....... . It no longer makes a good impression on visitors. So, I am happy to announce that the office 136....... on Friday, March 17 as that section of carpet is replaced. I have found new carpeting of the same color but made of a more durable material and have hired a contractor to perform the removal and installation.
137....... the office is closed, all Banuelos Financial employees must either work from home or use a paid vacation day. 138........ . If you have any questions or concerns about this situation, you may raise them at Monday''s staff meeting.', 'Từ: Clarence Tibbetts
Đến: Nhân viên Banuelos Financial
Ngày: 8 tháng 3
Chủ đề: Công việc thay thảm
Như tất cả các bạn có lẽ đã nhận thấy, thảm ở khu vực lễ tân khá cũ mòn. Nó không còn tạo ấn tượng tốt với khách đến thăm nữa. Vì vậy, tôi vui mừng thông báo rằng văn phòng sẽ đóng cửa vào thứ Sáu, ngày 17 tháng 3 khi phần thảm đó được thay thế. Tôi đã tìm được thảm mới cùng màu nhưng được làm từ chất liệu bền hơn và đã thuê nhà thầu để thực hiện việc tháo dỡ và lắp đặt.
Trong thời gian văn phòng đóng cửa, tất cả nhân viên Banuelos Financial phải làm việc tại nhà hoặc sử dụng ngày nghỉ phép có lương. Vui lòng sắp xếp lại lịch hẹn với khách hàng cho phù hợp. Nếu bạn có bất kỳ câu hỏi hoặc thắc mắc nào về tình huống này, bạn có thể nêu ra trong cuộc họp nhân viên vào thứ Hai.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6335, 5088, 135, NULL, 'thick', 'beautiful', 'similar', 'worn', 'D', 'A. thick (dày)
B. beautiful (đẹp)
C. similar (tương tự)
D. worn (cũ mòn)
Đáp án đúng là D (worn).
Giải thích:
''Worn'' phù hợp nhất vì:
- Chỉ trạng thái cũ, mòn của thảm
- Phù hợp với ngữ cảnh về việc thảm cần được thay thế
- Liên kết với câu tiếp theo về việc không tạo ấn tượng tốt với khách
Các đáp án khác không phù hợp:
''Thick'' không liên quan đến vấn đề về chất lượng thảm
''Beautiful'' trái ngược với ngữ cảnh thảm cần thay thế
''Similar'' không phù hợp với việc mô tả tình trạng thảm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6336, 5088, 136, NULL, 'had been closed', 'was closing', 'close', 'will be closed', 'D', 'A. had been closed (đã được đóng cửa)
B. was closing (đang đóng cửa)
C. close (đóng cửa)
D. will be closed (sẽ được đóng cửa)
Đáp án đúng là D (will be closed).
Giải thích:
''Will be closed'' phù hợp nhất vì:
- Diễn tả một kế hoạch trong tương lai
- Cấu trúc thể bị động, thì tương lai phù hợp với thông báo về việc sẽ xảy ra
- Ngày đóng cửa cụ thể được đề cập (March 17)
Các đáp án khác không phù hợp:
''Had been closed'' - quá khứ hoàn thành không phù hợp với sự kiện tương lai
''Was closing'' - quá khứ tiếp diễn không phù hợp
''Close'' - động từ nguyên thể không phù hợp với cấu trúc câu');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6337, 5088, 137, NULL, 'Throughout', 'Often', 'While', 'At first', 'C', 'A. Throughout (trong suốt)
B. Often (thường xuyên)
C. While (trong khi)
D. At first (lúc đầu)
Đáp án đúng là C (While).
Giải thích:
''While'' phù hợp nhất vì:
- Diễn tả thời gian đồng thời: trong thời gian văn phòng đóng cửa
- Liên kết logic giữa việc đóng cửa và yêu cầu nhân viên làm việc tại nhà
- Cấu trúc ''While + mệnh đề'' phù hợp về ngữ pháp
Các đáp án khác không phù hợp:
''Throughout'' không phù hợp với cấu trúc câu
''Often'' không phù hợp vì đây là sự kiện một lần
''At first'' không phù hợp vì không phải giai đoạn đầu của sự việc');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6338, 5088, 138, NULL, 'The reception desk must be kept neat.', 'Please reschedule client appointments accordingly.', 'The executive team is still considering the timeline.', 'The contractor is a well-respected local firm.', 'B', 'A. The reception desk must be kept neat. (Bàn lễ tân phải được giữ gọn gàng)
B. Please reschedule client appointments accordingly. (Vui lòng sắp xếp lại lịch hẹn với khách hàng cho phù hợp)
C. The executive team is still considering the timeline. (Ban lãnh đạo vẫn đang xem xét lịch trình)
D. The contractor is a well-respected local firm. (Nhà thầu là một công ty địa phương có uy tín)
Đáp án đúng là B.
Giải thích:
Câu B phù hợp nhất vì:
- Liên quan trực tiếp đến việc văn phòng đóng cửa
- Hướng dẫn cụ thể cho nhân viên về việc xử lý lịch hẹn với khách
- Là thông tin quan trọng cần thiết cho hoạt động kinh doanh
Các đáp án khác không phù hợp:
A: Không liên quan đến việc đóng cửa văn phòng
C: Mâu thuẫn với việc đã có kế hoạch cụ thể
D: Không quan trọng trong ngữ cảnh này');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5089, 223, NULL, NULL, 'To: Grace Vaughn
From: Sergio Fonseca
Subject: Dennis-Lindstrom wedding
Date: June 3
Hi Grace,
Here are the details of the wedding we will be photographing on Saturday. The ceremony will start at 4 p.m. at Zeller Inn. 139......, please arrive a full two hours beforehand to help me with photographing the preparations. After the ceremony, you can take candid shots of the reception during the time I''m taking the composed family pictures. We are then scheduled to stay until the cake is cut, which may mean quite a long evening. 140........ .
Thank you again for agreeing to 141...... me with this. It is quite a high-profile event, and it will give me 142...... to be supported by an experienced photographer like you.
Sergio', 'Gửi: Grace Vaughn
Từ: Sergio Fonseca
Chủ đề: Đám cưới Dennis-Lindstrom
Ngày: 3 tháng 6
Chào Grace,
Đây là chi tiết về đám cưới mà chúng ta sẽ chụp vào thứ Bảy. Lễ cưới sẽ bắt đầu lúc 4 giờ chiều tại Zeller Inn. Nếu có thể, hãy đến trước hai tiếng để giúp tôi chụp ảnh chuẩn bị. Sau lễ cưới, bạn có thể chụp ảnh chân dung của tiệc trong khi tôi chụp ảnh gia đình theo bố cục. Sau đó chúng ta được lên lịch ở lại cho đến khi cắt bánh, điều này có thể có nghĩa là một buổi tối khá dài.
Cảm ơn bạn một lần nữa đã đồng ý hỗ trợ tôi với việc này. Đây là một sự kiện khá quan trọng, và nó sẽ cho tôi sự tự tin khi được hỗ trợ bởi một nhiếp ảnh gia có kinh nghiệm như bạn.
Sergio');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6339, 5089, 139, NULL, 'Likewise', 'If possible', 'Before long', 'Rather', 'B', 'A. Likewise (tương tự)
B. If possible (nếu có thể)
C. Before long (chẳng bao lâu nữa)
D. Rather (thay vào đó)
Đáp án đúng là B (If possible).
Giải thích:
''If possible'' phù hợp nhất vì:
- Đây là một yêu cầu lịch sự về thời gian đến
- Phù hợp với ngữ cảnh đưa ra yêu cầu chuyên nghiệp
- Thể hiện sự tôn trọng đối với đồng nghiệp
Các đáp án khác không phù hợp:
''Likewise'' không phù hợp vì không có sự so sánh nào
''Before long'' không phù hợp với yêu cầu về thời gian cụ thể
''Rather'' không phù hợp với mục đích đưa ra yêu cầu');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6340, 5089, 140, NULL, 'Luckily, I have an extra camera you can use.', 'We would get extra pay after 8 P.M., though.', 'The venue offers some lovely backdrops.', 'All of the guests will be dressed in formal wear.', 'B', 'A. Luckily, I have an extra camera you can use. (May mắn thay, tôi có một máy ảnh phụ bạn có thể dùng)
B. We would get extra pay after 8 P.M., though. (Tuy nhiên, chúng ta sẽ được trả thêm tiền sau 8 giờ tối)
C. The venue offers some lovely backdrops. (Địa điểm có một số phông nền đẹp)
D. All of the guests will be dressed in formal wear. (Tất cả khách mời sẽ mặc trang phục chính thức)
Đáp án đúng là B.
Giải thích:
Câu B phù hợp nhất vì:
- Liên quan trực tiếp đến việc phải làm việc muộn được đề cập trước đó
- Cung cấp thông tin quan trọng về thù lao
- ''Though'' cho thấy sự bù đắp cho việc phải làm tới khuya
Các đáp án khác không phù hợp:
A: Không liên quan đến vấn đề thời gian làm việc
C: Không liên quan đến ngữ cảnh về thời gian làm việc dài
D: Không liên quan đến vấn đề đang thảo luận');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6341, 5089, 141, NULL, 'assist', 'feature', 'provide', 'refer', 'A', 'A. assist (hỗ trợ)
B. feature (giới thiệu)
C. provide (cung cấp)
D. refer (giới thiệu)
Đáp án đúng là A (assist).
Giải thích:
''Assist'' là động từ phù hợp nhất:
- Phù hợp với ngữ cảnh về việc giúp đỡ chụp ảnh
- Cấu trúc ''assist someone with something'' là cụm từ phổ biến
- Thể hiện mối quan hệ hợp tác chuyên nghiệp
Các đáp án khác không phù hợp:
''Feature'' không phù hợp với ngữ cảnh giúp đỡ
''Provide'' không đi với ''with'' trong ngữ cảnh này
''Refer'' không phù hợp với ý nghĩa câu');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6342, 5089, 142, NULL, 'confide', 'confided', 'confiding', 'confidence', 'D', 'A. confide (tâm sự)
B. confided (đã tâm sự)
C. confiding (đang tâm sự)
D. confidence (sự tự tin)
Đáp án đúng là D (confidence).
Giải thích:
''Confidence'' phù hợp nhất vì:
- Cần một danh từ sau ''give me''
- Phù hợp với ngữ cảnh về sự hỗ trợ từ một người có kinh nghiệm
- ''Give someone confidence'' là cụm từ thông dụng
Các đáp án khác không phù hợp:
''Confide'' là động từ, không phù hợp sau ''give me''
''Confided'' là động từ quá khứ, không phù hợp
''Confiding'' là động từ dạng -ing, không phù hợp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5090, 223, NULL, NULL, '(October 23)-Law firm Malley Turnbull Partners is proud to announce that Soo-Yeon Ko has been promoted to the rank of senior partner. She 143...... managing partner Gerald Malley and four other senior partners as a partial owner of the firm.
"This recognition is well deserved," said Mr. Malley. "Ms. Ko has made 144....... contributions to our success over the past several years."
Malley Turnbull Partners hired Ms. Ko five years ago as a senior associate concentrating on environmental law. 145......., the firm has won some important cases in that area.
"Ms. Ko possesses not only a very sharp legal mind but also an inspiring dedication to helping our junior lawyers grow professionally," said Mr. Malley." 146........ "', 'Ngày 23 tháng 10 - Công ty luật Malley Turnbull Partners tự hào thông báo rằng Soo-Yeon Ko đã được thăng chức lên vị trí đối tác cấp cao. Cô ấy tham gia cùng đối tác quản lý Gerald Malley và bốn đối tác cấp cao khác với tư cách là chủ sở hữu một phần của công ty.
"Sự công nhận này là hoàn toàn xứng đáng," ông Malley nói. "Cô Ko đã có những đóng góp quan trọng cho sự thành công của chúng tôi trong vài năm qua."
Malley Turnbull Partners đã thuê cô Ko năm năm trước với vị trí luật sư cao cấp chuyên về luật môi trường. Kết quả là, công ty đã thắng một số vụ kiện quan trọng trong lĩnh vực đó.
"Cô Ko không chỉ có một tư duy pháp lý rất sắc sảo mà còn có sự tận tâm truyền cảm hứng trong việc giúp các luật sư trẻ của chúng tôi phát triển chuyên môn," ông Malley nói.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6343, 5090, 143, NULL, 'joins', 'was joining', 'has been joined', 'would have joined', 'A', 'A. joins (tham gia)
B. was joining (đã đang tham gia)
C. has been joined (đã được tham gia)
D. would have joined (đã có thể tham gia)
Đáp án đúng là A (joins).
Giải thích:
''Joins'' phù hợp nhất vì:
- Thì hiện tại đơn phù hợp với thông báo về một sự thay đổi hiện tại
- Động từ chủ động phù hợp với chủ ngữ là người thực hiện hành động
- Diễn tả một sự kiện xảy ra tại thời điểm hiện tại
Các đáp án khác không phù hợp:
''Was joining'' - quá khứ tiếp diễn không phù hợp với sự kiện hiện tại
''Has been joined'' - thể bị động không phù hợp với ngữ cảnh
''Would have joined'' - điều kiện quá khứ không phù hợp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6344, 5090, 144, NULL, 'entire', 'possible', 'sturdy', 'major', 'D', 'A. entire (toàn bộ)
B. possible (có thể)
C. sturdy (vững chắc)
D. major (quan trọng)
Đáp án đúng là D (major).
Giải thích:
''Major'' phù hợp nhất vì:
- Diễn tả mức độ quan trọng của các đóng góp
- ''Major contributions'' là cụm từ phổ biến trong ngữ cảnh chuyên nghiệp
- Phản ánh thành tích xứng đáng với việc thăng chức
Các đáp án khác không phù hợp:
''Entire'' không phù hợp vì đóng góp không thể là toàn bộ
''Possible'' không phù hợp vì đóng góp đã thực tế
''Sturdy'' thường dùng cho vật thể, không phù hợp với ''contributions''');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6345, 5090, 145, NULL, 'Instead', 'Similarly', 'Consequently', 'In short', 'C', 'A. Instead (thay vào đó)
B. Similarly (tương tự)
C. Consequently (kết quả là)
D. In short (tóm lại)
Đáp án đúng là C (Consequently).
Giải thích:
''Consequently'' phù hợp nhất vì:
- Chỉ ra mối quan hệ nhân quả giữa việc thuê cô Ko và thắng các vụ kiện
- Liên kết logic giữa chuyên môn của cô Ko và thành công của công ty
- Phù hợp với việc trình bày kết quả tích cực
Các đáp án khác không phù hợp:
''Instead'' không phù hợp vì không có sự thay thế
''Similarly'' không phù hợp vì không có sự so sánh
''In short'' không phù hợp vì không phải tóm tắt');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6346, 5090, 146, NULL, 'We expect a good outcome to the case.', 'More workshops will be organized soon.', 'We welcome her to the leadership team.', 'The position will not be open for long.', 'C', 'A. We expect a good outcome to the case. (Chúng tôi kỳ vọng một kết quả tốt cho vụ án)
B. More workshops will be organized soon. (Nhiều hội thảo sẽ sớm được tổ chức)
C. We welcome her to the leadership team. (Chúng tôi chào đón cô ấy vào đội ngũ lãnh đạo)
D. The position will not be open for long. (Vị trí này sẽ không mở lâu)
Đáp án đúng là C.
Giải thích:
Câu C phù hợp nhất vì:
- Kết thúc thông báo về việc thăng chức một cách chính thức
- Phù hợp với tông giọng chúc mừng của toàn bài
- Là câu kết phù hợp sau khi liệt kê thành tích và phẩm chất của cô Ko
Các đáp án khác không phù hợp:
A: Không liên quan đến nội dung thăng chức
B: Không phù hợp với việc kết thúc thông báo
D: Không phù hợp với ngữ cảnh chúc mừng thăng chức');;

-- Data for 2025 Test2 Part 7
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5091, 224, NULL, NULL, 'Deftlee
More than a decade of helping start-ups take flight
What we offer:
Convenient outsourcing of human resources tasks
Project-based consulting on personnel issues
Full-service HR technology platform for long-term clients
Areas of expertise include recruiting, training, payroll, and much more. Visit www.deftlee.com to schedule a consultation.
Client testimonials:
"I highly recommend Deftlee. Their HR platform alone is worth the prices they charge. Our managers love how it has simplified tasks like tracking time off and performance evaluations."
—Ryan Maas, Aurora Logistics
"My business has grown from four employees to more than 50, and Deftlee has been there every step of the way. I''m always impressed by their ability to adapt to our changing needs."
—Kasumi Tanaka, TBR Solutions', 'Deftlee
Hơn một thập kỷ giúp các công ty khởi nghiệp cất cánh
Chúng tôi cung cấp:
Dịch vụ thuê ngoài nhân sự tiện lợi
Tư vấn nhân sự theo dự án
Nền tảng công nghệ HR đầy đủ dịch vụ cho khách hàng dài hạn
Các lĩnh vực chuyên môn bao gồm tuyển dụng, đào tạo, tiền lương và nhiều thứ khác. Truy cập www.deftlee.com để đặt lịch tư vấn.
Nhận xét của khách hàng:
"Tôi rất giới thiệu Deftlee. Riêng nền tảng HR của họ đã xứng đáng với giá họ tính. Các quản lý của chúng tôi rất thích cách nó đơn giản hóa các công việc như theo dõi nghỉ phép và đánh giá hiệu suất."
—Ryan Maas, Aurora Logistics
"Doanh nghiệp của tôi đã phát triển từ bốn nhân viên lên hơn 50 người, và Deftlee đã đồng hành cùng chúng tôi trong suốt chặng đường. Tôi luôn ấn tượng với khả năng thích ứng với nhu cầu thay đổi của chúng tôi."
—Kasumi Tanaka, TBR Solutions');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6347, 5091, 147, 'What is most likely true about Deftlee?', 'It offers to handle employee compensation for its clients.', 'It advises businesses on environmental issues.', 'It has grown rapidly in a short time.', 'It develops project management software.', 'A', 'Đáp án đúng là A.
Giải thích:
Trong văn bản có nhiều bằng chứng cho thấy Deftlee xử lý vấn đề lương cho khách hàng:
1. "Areas of expertise include recruiting, training, payroll, and much more" - từ khóa "payroll" (tiền lương) trực tiếp chỉ ra dịch vụ này
2. "Convenient outsourcing of human resources tasks" - dịch vụ thuê ngoài HR bao gồm cả quản lý lương
3. "Full-service HR technology platform" - nền tảng HR đầy đủ dịch vụ ngầm định có tính năng quản lý lương
Phân tích các đáp án:
A. Công ty cung cấp dịch vụ xử lý lương cho nhân viên của khách hàng ✓ (được chứng minh qua nhiều bằng chứng trên)
B. Công ty tư vấn về các vấn đề môi trường × (hoàn toàn không được đề cập)
C. Công ty phát triển nhanh chóng trong thời gian ngắn × (chỉ đề cập "more than a decade" - hơn một thập kỷ)
D. Công ty phát triển phần mềm quản lý dự án × (chỉ đề cập đến HR platform, không phải project management)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6348, 5091, 148, 'What does Ms. Tanaka appreciate about Deftlee?', 'Its pricing', 'Its flexibility', 'Its technology', 'Its confidentiality', 'B', 'Đáp án đúng là B.
Giải thích:
1. Trong lời chứng thực của Ms. Tanaka có câu: "I''m always impressed by their ability to adapt to our changing needs" (Tôi luôn ấn tượng với khả năng thích ứng với nhu cầu thay đổi của chúng tôi)
2. Cụm từ "adapt to changing needs" (thích ứng với nhu cầu thay đổi) trực tiếp thể hiện tính linh hoạt (flexibility)
3. Ms. Tanaka cũng đề cập việc công ty phát triển từ 4 lên 50 nhân viên, và Deftlee đã thích ứng được với sự phát triển này
Phân tích các đáp án:
A. Giá cả của công ty × (Ms. Tanaka không đề cập đến giá cả)
B. Tính linh hoạt của công ty ✓ (thể hiện qua khả năng thích ứng với nhu cầu thay đổi)
C. Công nghệ của công ty × (không được đề cập trong lời chứng thực của bà)
D. Tính bảo mật của công ty × (không được đề cập trong văn bản)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5092, 224, NULL, NULL, 'CONOVER''S
Dear Customers:
Since our opening nearly 30 years ago, Conover''s has been proud to equip Mandeville residents for a wide range of indoor and outdoor sports. However, we have recently made the difficult decision to remove fishing gear, supplies, and equipment from our inventory due to poor sales.
The floor space this stock used to occupy will instead be used to display additional workout apparel. This step will help Conover''s remain profitable so that we can continue supporting Mandeville''s athletes for many years to come. Still, we apologize for the inconvenience this will cause for the fishing enthusiasts among our customers.
—Conover''s Management', 'CONOVER''S
Kính gửi Quý khách hàng:
Kể từ khi khai trương cách đây gần 30 năm, Conover''s tự hào trang bị cho cư dân Mandeville các môn thể thao trong nhà và ngoài trời. Tuy nhiên, gần đây chúng tôi đã đưa ra quyết định khó khăn là loại bỏ dụng cụ câu cá, vật tư và thiết bị khỏi kho hàng do doanh số kém.
Không gian trưng bày những mặt hàng này trước đây sẽ được sử dụng để trưng bày thêm quần áo tập luyện. Bước này sẽ giúp Conover''s duy trì lợi nhuận để chúng tôi có thể tiếp tục hỗ trợ các vận động viên Mandeville trong nhiều năm tới. Tuy nhiên, chúng tôi xin lỗi vì sự bất tiện này sẽ gây ra cho những khách hàng đam mê câu cá.
—Ban Quản lý Conover''s');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6349, 5092, 149, 'What does Conover''s sell?', 'Groceries', 'Electronics', 'Art supplies', 'Sporting goods', 'D', 'Đáp án đúng là D.
Giải thích:
Nhiều bằng chứng trong văn bản cho thấy Conover''s bán đồ thể thao:
1. "equip Mandeville residents for a wide range of indoor and outdoor sports" - trang bị cho cư dân các môn thể thao trong nhà và ngoài trời
2. "fishing gear, supplies, and equipment" - thiết bị và dụng cụ câu cá
3. "workout apparel" - quần áo tập luyện
4. "supporting Mandeville''s athletes" - hỗ trợ các vận động viên
Phân tích các đáp án:
A. Tạp hóa × (không liên quan đến mặt hàng của cửa hàng)
B. Thiết bị điện tử × (không được đề cập)
C. Đồ dùng nghệ thuật × (không được đề cập)
D. Đồ thể thao ✓ (được chứng minh qua nhiều bằng chứng về các mặt hàng thể thao)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6350, 5092, 150, 'What is the notice about?', 'A change in inventory', 'An anniversary celebration', 'A temporary store closure', 'A fund-raising event', 'A', 'Đáp án đúng là A.
Giải thích:
1. Thông báo nói về việc loại bỏ một mặt hàng: "remove fishing gear, supplies, and equipment from our inventory" (loại bỏ dụng cụ câu cá khỏi kho hàng)
2. Thay thế bằng mặt hàng khác: "floor space... will instead be used to display additional workout apparel" (không gian sẽ được dùng để trưng bày thêm quần áo tập luyện)
Phân tích các đáp án:
A. Thay đổi trong kho hàng ✓ (trực tiếp thể hiện qua việc bỏ đồ câu cá và thêm quần áo tập luyện)
B. Kỷ niệm thành lập × (dù có đề cập 30 năm nhưng không phải là thông báo về kỷ niệm)
C. Đóng cửa tạm thời × (không được đề cập)
D. Sự kiện gây quỹ × (không được đề cập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5093, 224, NULL, NULL, 'E-Mail message
From: customerservice@irishair.com
To: Kevin Reilly
Subject: Emerald Club
Date: 4 October
Dear Mr. Reilly,
We received your request to let your sister use your excess frequent-flyer miles. This is only possible after connecting your Emerald Club accounts, which must be done through our Web site. Please follow these steps.
1. Log in to your Emerald Club member page. Select "Add a Family Member" from the sidebar.
2. Enter the requested information about your relative.
3. After reviewing the guidelines on documents that we will accept as proof of your relationship, upload eligible documents.
4. Click "Submit" at the bottom of the page. Within five business days, you will receive an e-mail confirming the connection or requesting additional documentation.
Please let us know if you encounter difficulties with this process.
Orla Collins
Irish Air Customer Service', 'Tin nhắn E-Mail
Từ: customerservice@irishair.com
Gửi: Kevin Reilly
Chủ đề: Emerald Club
Ngày: 4 tháng 10
Thưa ông Reilly,
Chúng tôi đã nhận được yêu cầu của bạn để em gái bạn sử dụng số dặm bay thường xuyên dư thừa của bạn. Điều này chỉ có thể thực hiện được sau khi kết nối tài khoản Emerald Club của bạn, điều này phải được thực hiện thông qua trang web của chúng tôi. Vui lòng làm theo các bước sau.
1. Đăng nhập vào trang thành viên Emerald Club của bạn. Chọn "Thêm thành viên gia đình" từ thanh bên.
2. Nhập thông tin được yêu cầu về người thân của bạn.
3. Sau khi xem xét các hướng dẫn về tài liệu mà chúng tôi sẽ chấp nhận làm bằng chứng về mối quan hệ của bạn, hãy tải lên các tài liệu đủ điều kiện.
4. Nhấp vào "Gửi" ở cuối trang. Trong vòng năm ngày làm việc, bạn sẽ nhận được một e-mail xác nhận kết nối hoặc yêu cầu tài liệu bổ sung.
Vui lòng cho chúng tôi biết nếu bạn gặp khó khăn với quy trình này.
Orla Collins
Dịch vụ khách hàng của Irish Air');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6351, 5093, 151, 'What is suggested about Mr. Reilly?', 'He reported a security issue with his account.', 'He is a travel agent.', 'He often flies with Irish Air.', 'A member of his family works for Irish Air.', 'C', 'Đáp án đúng là C.
Giải thích:
1. Email đề cập đến "excess frequent-flyer miles" (dặm bay thường xuyên dư thừa) của Mr. Reilly
2. Từ "frequent-flyer" và việc có dặm bay dư thừa ngụ ý ông thường xuyên sử dụng dịch vụ của Irish Air
3. Ông là thành viên Emerald Club - chương trình khách hàng thân thiết của hãng
Phân tích các đáp án:
A. Báo cáo vấn đề bảo mật × (không liên quan đến nội dung email)
B. Là đại lý du lịch × (không có thông tin này)
C. Thường xuyên bay với Irish Air ✓ (thể hiện qua việc có nhiều dặm bay thường xuyên)
D. Có người nhà làm việc cho Irish Air × (chỉ đề cập đến việc muốn cho em gái dùng dặm bay)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6352, 5093, 152, 'What is Mr. Reilly instructed to do?', 'Change his log-in credentials', 'Provide some documents by mail', 'Check his member page for updates', 'Verify a relationship online', 'D', 'Đáp án đúng là D.
Giải thích:
1. Email hướng dẫn Mr. Reilly xác minh quan hệ với em gái qua các bước:
- "After reviewing the guidelines on documents... upload eligible documents" (tải lên tài liệu chứng minh mối quan hệ)
- "must be done through our Web site" (phải thực hiện qua trang web)
2. Toàn bộ quy trình được thực hiện trực tuyến, không yêu cầu gửi tài liệu qua đường bưu điện
Phân tích các đáp án:
A. Thay đổi thông tin đăng nhập × (không được yêu cầu)
B. Cung cấp tài liệu qua bưu điện × (yêu cầu tải lên online)
C. Kiểm tra trang thành viên để cập nhật × (không phải mục đích chính)
D. Xác minh một mối quan hệ trực tuyến ✓ (được chứng minh qua các bước hướng dẫn cụ thể trong email)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5094, 224, NULL, NULL, 'Tyrone Belton, 7:14 P.M.
Hi, Nadia. I just noticed we have a problem with some promotional materials 1 packed for the trade show. They have our Stahl Street address on them.
Nadia Guseva, 7:15 P.M.
Which ones?
Tyrone Belton, 7:16 P.M.
The brochures for our Nimble line of power tools. I guess we never had them reprinted with our new address after the move.
Nadia Guseva, 7:17 P.M.
Well, there are print shops near the convention center, right? You could go to one tonight or early tomorrow morning, and ask them to print correction stickers for you to put on the brochures.
Tyrone Belton, 7:18 P.M.
That should work! Thanks for your help.', 'Tyrone Belton, 7:14 tối
Chào Nadia. Tôi vừa nhận thấy chúng ta có vấn đề với một số tài liệu quảng cáo đã đóng gói cho triển lãm thương mại. Chúng có địa chỉ đường Stahl Street của chúng ta trên đó.
Nadia Guseva, 7:15 tối
Cái nào vậy?
Tyrone Belton, 7:16 tối
Các tờ rơi cho dòng công cụ điện Nimble của chúng ta. Tôi đoán chúng ta chưa bao giờ in lại chúng với địa chỉ mới sau khi chuyển đi.
Nadia Guseva, 7:17 tối
Vậy, có các cửa hiệu in ấn gần trung tâm hội nghị, phải không? Anh có thể đến một cửa hiệu tối nay hoặc sáng sớm mai, và yêu cầu họ in nhãn dán điều chỉnh để dán lên tờ rơi.
Tyrone Belton, 7:18 tối
Cách đó có thể được! Cảm ơn sự giúp đỡ của bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6353, 5094, 153, 'What problem does Mr. Belton have?', 'He misplaced some posters.', 'He was mistaken about a venue''s address.', 'He is unable to use a power tool.', 'He has outdated brochures.', 'D', 'Đáp án đúng là D.
Giải thích:
1. Mr. Belton phát hiện vấn đề với tài liệu quảng cáo: "have our Stahl Street address on them" (có địa chỉ đường Stahl Street trên đó)
2. Ông giải thích: "never had them reprinted with our new address after the move" (chưa bao giờ in lại với địa chỉ mới sau khi chuyển đi)
Phân tích các đáp án:
A. Làm mất một số áp phích × (không phải vấn đề về mất tài liệu)
B. Nhầm địa chỉ địa điểm × (vấn đề là địa chỉ cũ trên tờ rơi)
C. Không thể sử dụng công cụ điện × (không liên quan)
D. Có tờ rơi lỗi thời ✓ (tờ rơi có địa chỉ cũ, cần cập nhật)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6354, 5094, 154, 'At 7:18 P.M., what does Mr. Belton mean when he writes, "That should work"?', 'A device seems to have been repaired.', 'The proposed plan is likely to succeed.', 'He is surprised that a promotional effort is unpopular.', 'An announcement could resolve a misunderstanding.', 'B', 'Đáp án đúng là B.
Giải thích:
1. "That should work" là phản ứng của Mr. Belton với đề xuất của Nadia về việc in nhãn dán để sửa địa chỉ: "print correction stickers for you to put on the brochures"
2. Cụm từ này thể hiện ông đồng ý rằng giải pháp được đề xuất có thể giải quyết được vấn đề
Phân tích các đáp án:
A. Một thiết bị dường như đã được sửa chữa × (không liên quan đến nội dung)
B. Kế hoạch được đề xuất có khả năng thành công ✓ (phản ứng trực tiếp với đề xuất của Nadia)
C. Anh ấy ngạc nhiên vì nỗ lực quảng cáo không được ưa chuộng × (không liên quan)
D. Một thông báo có thể giải quyết sự hiểu lầm × (không có hiểu lầm nào cần giải quyết)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5095, 224, NULL, NULL, 'Carder Bay Automotive Seeks
Electric Auto Mechanic
To keep up with changes in consumer preferences, Carder Bay Automotive will begin providing maintenance and repair services for electric automobiles.
Therefore, we are seeking an auto mechanic with knowledge of this area.
Candidates must possess at least two years of work experience in maintaining, diagnosing problems with, and repairing electric vehicles.
Carder Bay Automotive requires all employees to be punctual, well-organized, and able to work well as part of a team. Mechanics must also be licensed to operate commercial vehicles. Candidates invited to interview for this position should expect to be asked a variety of questions intended to assess their technical skills. Those interested should visit www.carderbayauto.com/jobs/326
to fill out an electronic application.', 'Carder Bay Automotive Tuyển dụng
Thợ máy Ô tô Điện
Để theo kịp những thay đổi trong sở thích của người tiêu dùng, Carder Bay Automotive sẽ bắt đầu cung cấp dịch vụ bảo trì và sửa chữa cho xe hơi điện.
Do đó, chúng tôi đang tìm kiếm một thợ máy ô tô có kiến thức trong lĩnh vực này.
Ứng viên phải có ít nhất hai năm kinh nghiệm làm việc trong việc bảo trì, chẩn đoán vấn đề và sửa chữa xe điện.
Carder Bay Automotive yêu cầu tất cả nhân viên phải đúng giờ, có tổ chức tốt và có khả năng làm việc tốt trong nhóm. Thợ máy cũng phải có giấy phép điều khiển xe thương mại. Các ứng viên được mời phỏng vấn cho vị trí này nên chuẩn bị trả lời nhiều câu hỏi nhằm đánh giá kỹ năng kỹ thuật của họ. Những người quan tâm nên truy cập www.carderbayauto.com/jobs/326
để điền đơn ứng tuyển điện tử.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6355, 5095, 155, 'Why is the mechanic position being offered?', 'Business hours have been extended.', 'A new type of vehicle will be serviced.', 'An additional location is opening.', 'New regulations will go into effect.', 'B', 'Đáp án đúng là B.
Giải thích:
Văn bản nêu rõ: "will begin providing maintenance and repair services for electric automobiles" (sẽ bắt đầu cung cấp dịch vụ bảo trì và sửa chữa cho xe điện). Điều này cho thấy công ty sẽ phục vụ một loại xe mới - xe điện.
Phân tích các đáp án:
A. Giờ làm việc được kéo dài × (không được đề cập)
B. Một loại xe mới sẽ được phục vụ ✓ (xe điện - loại xe mới)
C. Một địa điểm bổ sung đang mở × (không được đề cập)
D. Quy định mới sẽ có hiệu lực × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6356, 5095, 156, 'What is NOT a stated requirement of the position?', 'Teamwork skills', 'Repair experience', 'A maintenance certification', 'A driver''s license', 'C', 'Đáp án đúng là C.
Giải thích:
Văn bản liệt kê các yêu cầu sau:
1. "work well as part of a team" (kỹ năng làm việc nhóm)
2. "two years of work experience in... repairing" (kinh nghiệm sửa chữa)
3. "licensed to operate commercial vehicles" (giấy phép lái xe)
Không hề đề cập đến yêu cầu về chứng chỉ bảo trì.
Phân tích các đáp án:
A. Kỹ năng làm việc nhóm × (được yêu cầu rõ ràng)
B. Kinh nghiệm sửa chữa × (yêu cầu 2 năm kinh nghiệm)
C. Chứng chỉ bảo trì ✓ (không được đề cập trong yêu cầu)
D. Giấy phép lái xe × (yêu cầu có giấy phép xe thương mại)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6357, 5095, 157, 'According to the job advertisement, what will candidates be asked to do during interviews?', 'Discuss automotive technology', 'Take an online proficiency test', 'Assess the condition of an automobile', 'Provide documents proving their qualifications', 'A', 'Đáp án đúng là A.
Giải thích:
Theo thông báo: "expect to be asked a variety of questions intended to assess their technical skills" (dự kiến sẽ được hỏi nhiều câu hỏi nhằm đánh giá kỹ năng kỹ thuật). Điều này cho thấy ứng viên sẽ thảo luận về công nghệ ô tô.
Phân tích các đáp án:
A. Thảo luận về công nghệ ô tô ✓ (thông qua các câu hỏi đánh giá kỹ thuật)
B. Làm bài kiểm tra trực tuyến × (không được đề cập)
C. Đánh giá tình trạng của một chiếc xe × (không được đề cập)
D. Cung cấp tài liệu chứng minh trình độ × (không được đề cập trong phần phỏng vấn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5096, 224, NULL, NULL, 'Housing Prices on the Rise
By Yong-Joon Wang
DROSSER (May 6)-Housing prices in Drosser continue to increase, according to data from Turfle.com, the online real estate marketplace. The average home price for the area jumped 5.2% from last year to $392,500.
"Higher home values mean more revenue from property taxes," commented Ada Ferrell, chair of the Drosser Housing Authority Board. "The city will be able to generate extra funding for its social services." However, Ms. Ferrell pointed out that the trend also poses problems for individual households.
"Some homeowners will struggle to pay their higher property tax bill," she said. "Moreover, we know that rent prices have risen correspondingly in the past year, increasing the burden on rental tenants.
Rent is becoming an increasingly large share of their living costs."
Residents experiencing financial difficulties due to housing can find a variety of resources on the Drosser Housing Authority Board''s Web site, www.drossercity.org/dhab.', 'Giá Nhà ở Tăng cao
Tác giả Yong-Joon Wang
DROSSER (6/5) - Giá nhà ở tại Drosser tiếp tục tăng, theo số liệu từ Turfle.com, thị trường bất động sản trực tuyến. Giá nhà trung bình trong khu vực đã tăng 5,2% so với năm ngoái lên 392.500 đô la.
"Giá trị nhà cao hơn đồng nghĩa với nhiều thu nhập từ thuế bất động sản hơn," Ada Ferrell, chủ tịch Hội đồng Quản lý Nhà ở Drosser nhận xét. "Thành phố sẽ có thể tạo ra nguồn quỹ bổ sung cho các dịch vụ xã hội." Tuy nhiên, bà Ferrell chỉ ra rằng xu hướng này cũng gây ra vấn đề cho các hộ gia đình.
"Một số chủ nhà sẽ gặp khó khăn trong việc trả hóa đơn thuế bất động sản cao hơn," bà nói. "Hơn nữa, chúng tôi biết rằng giá thuê nhà đã tăng tương ứng trong năm qua, tăng gánh nặng cho người thuê nhà.
Tiền thuê nhà đang chiếm tỷ trọng ngày càng lớn trong chi phí sinh hoạt của họ."
Cư dân gặp khó khăn tài chính do nhà ở có thể tìm thấy nhiều nguồn lực trên trang web của Hội đồng Quản lý Nhà ở Drosser, www.drossercity.org/dhab.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6358, 5096, 158, 'Who most likely is Ms. Ferrell?', 'A tax accountant', 'The manager of a rental property', 'A real estate agent', 'A housing official', 'D', 'Đáp án đúng là D.
Giải thích:
Văn bản giới thiệu: "Ada Ferrell, chair of the Drosser Housing Authority Board" (Ada Ferrell, chủ tịch Hội đồng Quản lý Nhà ở Drosser). Đây là một vị trí chính thức trong cơ quan quản lý nhà ở.
Phân tích các đáp án:
A. Kế toán thuế × (không phải vai trò của bà)
B. Người quản lý bất động sản cho thuê × (không phải)
C. Đại lý bất động sản × (không phải)
D. Viên chức nhà ở ✓ (chủ tịch Hội đồng Quản lý Nhà ở là một viên chức nhà ở)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6359, 5096, 159, 'The word "poses" in paragraph 3, line 2, is closest in meaning to', 'pretends', 'models', 'presents', 'states', 'C', 'Đáp án đúng là C.
Giải thích:
Từ "poses" trong câu "the trend also poses problems for individual households" có nghĩa là "presents" (đặt ra, tạo ra). Trong ngữ cảnh này, xu hướng tăng giá nhà đang tạo ra/đặt ra các vấn đề cho các hộ gia đình.
Phân tích các đáp án:
A. pretends (giả vờ) × (không phù hợp ngữ cảnh)
B. models (tạo mẫu) × (không phù hợp)
C. presents (đặt ra, tạo ra) ✓ (phù hợp với ngữ cảnh - một xu hướng tạo ra vấn đề)
D. states (phát biểu) × (không phù hợp với cách dùng trong câu)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6360, 5096, 160, 'What does Ms. Ferrell mention about the rise in housing prices?', 'It has a downside for some homeowners.', 'A city organization is seeking ways to reverse it.', 'It has caused more people to choose to rent housing.', 'It is the result of the city''s popular tax policies.', 'A', 'Đáp án đúng là A.
Giải thích:
Ms. Ferrell đề cập đến mặt tiêu cực của việc tăng giá nhà: "Some homeowners will struggle to pay their higher property tax bill" (Một số chủ nhà sẽ gặp khó khăn trong việc trả hóa đơn thuế bất động sản cao hơn)
Phân tích các đáp án:
A. Có mặt trái đối với một số chủ nhà ✓ (được đề cập rõ qua việc khó trả thuế cao hơn)
B. Tổ chức thành phố đang tìm cách đảo ngược × (không được đề cập)
C. Khiến nhiều người chọn thuê nhà × (không được đề cập)
D. Là kết quả của chính sách thuế phổ biến × (không được đề cập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5097, 224, NULL, NULL, 'E-Mail message
To: Bridget Deng
From: Candice Holt
Subject: Information
Date: August 27
Attachment: Holt_Aug27
Dear Bridget,
As you requested, this is your reminder that I''m starting my two-week medical leave on Monday. — [1] —. Attached you''ll find the list of marketing campaigns that I''m currently working on, with details about the status of each. I''ve also notified the other employees involved in each campaign about my absence. - [2] -. In most cases, it will not be difficult for one of them to take over my duties for those two weeks.
The only task left is to meet with Jonathan to hand over the digital promotion plans for the launch of Yancey Cosmetic''s new nail polish line. I haven''t been able to do that yet because I needed to make some last-minute changes that the client requested. — [3] -. I''ll make sure Jonathan is ready to update Yancey''s social media accounts at the appropriate times with the posts I''ve created.
Finally, while I''ll be unavailable during the first week of my leave, please feel free to contact me if necessary during the second. — [4] —', 'E-Mail
Đến: Bridget Deng
Từ: Candice Holt
Chủ đề: Thông tin
Ngày: 27 tháng 8
Tệp đính kèm: Holt_Aug27
Chào Bridget,
Như bạn yêu cầu, đây là lời nhắc nhở rằng tôi sẽ bắt đầu nghỉ phép y tế hai tuần vào thứ Hai. — [1] —. Đính kèm bạn sẽ thấy danh sách các chiến dịch marketing mà tôi đang thực hiện, với chi tiết về trạng thái của từng chiến dịch. Tôi cũng đã thông báo cho các nhân viên khác tham gia mỗi chiến dịch về việc vắng mặt của tôi. - [2] -. Trong hầu hết các trường hợp, sẽ không khó khăn để một trong số họ đảm nhận nhiệm vụ của tôi trong hai tuần đó.
Nhiệm vụ duy nhất còn lại là gặp Jonathan để bàn giao kế hoạch quảng bá kỹ thuật số cho việc ra mắt dòng sơn móng tay mới của Yancey Cosmetic. Tôi chưa thể làm điều đó vì tôi cần thực hiện một số thay đổi vào phút cuối theo yêu cầu của khách hàng. — [3] -. Tôi sẽ đảm bảo Jonathan sẵn sàng cập nhật tài khoản mạng xã hội của Yancey vào thời điểm thích hợp với các bài đăng tôi đã tạo.
Cuối cùng, mặc dù tôi sẽ không liên lạc được trong tuần đầu tiên nghỉ phép, nhưng xin vui lòng liên hệ với tôi nếu cần thiết trong tuần thứ hai. — [4] —');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6361, 5097, 161, 'For what type of business does Ms. Holt most likely work?', 'An online news platform', 'An advertising agency', 'A cosmetics company', 'A medical clinic', 'B', 'Đáp án đúng là B.
Giải thích:
Có nhiều bằng chứng cho thấy Ms. Holt làm việc cho công ty quảng cáo:
1. "marketing campaigns" - làm việc với các chiến dịch marketing
2. "digital promotion plans" - kế hoạch quảng bá kỹ thuật số
3. "Yancey Cosmetic''s new nail polish line" - làm việc cho khách hàng là công ty mỹ phẩm
4. "update social media accounts" - quản lý tài khoản mạng xã hội cho khách hàng
Phân tích các đáp án:
A. Nền tảng tin tức trực tuyến × (không phù hợp với công việc được mô tả)
B. Công ty quảng cáo ✓ (phù hợp với việc làm marketing cho khách hàng khác)
C. Công ty mỹ phẩm × (Yancey Cosmetics là khách hàng, không phải công ty của cô)
D. Phòng khám y tế × (không liên quan đến công việc được mô tả)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6362, 5097, 162, 'What will Ms. Holt prepare Jonathan to do?', 'Post on social media', 'Attend a launch event', 'Maintain a database', 'Meet with a client', 'A', 'Đáp án đúng là A.
Giải thích:
Theo email: "I''ll make sure Jonathan is ready to update Yancey''s social media accounts at the appropriate times with the posts I''ve created" (Tôi sẽ đảm bảo Jonathan sẵn sàng cập nhật tài khoản mạng xã hội của Yancey vào thời điểm thích hợp với các bài đăng tôi đã tạo)
Phân tích các đáp án:
A. Đăng trên mạng xã hội ✓ (được nêu rõ trong email)
B. Tham dự sự kiện ra mắt × (không được đề cập)
C. Duy trì cơ sở dữ liệu × (không được đề cập)
D. Gặp gỡ khách hàng × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6363, 5097, 163, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "Now that they''re finished, we''ve scheduled a meeting for this afternoon."', '[1]', '[2]', '[3]', '[4]', 'C', 'Đáp án đúng là C.
Giải thích:
Câu "Now that they''re finished, we''ve scheduled a meeting for this afternoon" phù hợp nhất ở vị trí [3] vì:
1. Ngay trước [3] nói về việc cần thực hiện các thay đổi phút chót theo yêu cầu của khách hàng
2. Câu này cho biết các thay đổi đã hoàn thành và đã sắp xếp cuộc họp
3. Sau đó là thông tin về việc đảm bảo Jonathan sẽ sẵn sàng cập nhật mạng xã hội
Phân tích các vị trí:
A. [1] × (không liên quan đến nội dung trước và sau)
B. [2] × (không phù hợp với ngữ cảnh)
C. [3] ✓ (phù hợp với việc hoàn thành thay đổi và chuẩn bị bàn giao)
D. [4] × (không phù hợp với phần kết email)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5098, 224, NULL, NULL, 'The Sounds of Brilliance
Wednesday, May 28
4:30 р.м.-9:00 р.м.
The Rendon University Department of Music invites all members of the campus and local community to attend its yearly recital celebrating excellence among our students. Join us in Steen Music Center''s Cho Recital Hall for an afternoon and evening of superb vocal, piano, cello, saxophone, and violin music.
All performers on the program are winners of the department''s performance awards. Among the honorees this year is Felicia Logan, who recently reached the semifinal round of the popular singing competition TV show Top Vocalist.
The full recital program, with details about the performers and pieces, is available at www.rendon.edu/music/soe.
The program will run from 4:30 p.M. to 6:00 P.M. and 7:30 p.M. to 9:00 P.M.
There is no fee for admission, and seating is first-come, first-served. Please note that seats cannot be saved during the intermission.
Steen Music Center is located at 640 Millard Avenue. Street parking on campus is free after 4:00 p.M., and paid parking is available in the Camacho Lot directly west of the music center.', 'The Sounds of Brilliance
Thứ Tư, ngày 28 tháng 5
4:30 chiều-9:00 tối
Khoa Âm nhạc Đại học Rendon mời tất cả các thành viên trong khuôn viên trường và cộng đồng địa phương tham dự buổi biểu diễn thường niên tôn vinh sự xuất sắc của sinh viên chúng tôi. Hãy tham gia cùng chúng tôi tại Phòng hòa nhạc Cho thuộc Trung tâm Âm nhạc Steen cho một buổi chiều và tối với âm nhạc tuyệt vời từ giọng hát, piano, cello, saxophone và violin.
Tất cả nghệ sĩ biểu diễn trong chương trình đều là người chiến thắng giải thưởng biểu diễn của khoa. Trong số những người được vinh danh năm nay có Felicia Logan, người gần đây đã vào đến vòng bán kết của chương trình truyền hình cuộc thi ca hát nổi tiếng Top Vocalist.
Chương trình biểu diễn đầy đủ, với thông tin chi tiết về các nghệ sĩ biểu diễn và tác phẩm, có tại www.rendon.edu/music/soe.
Chương trình sẽ diễn ra từ 4:30 chiều đến 6:00 tối và 7:30 tối đến 9:00 tối.
Vào cửa miễn phí và chỗ ngồi theo thứ tự đến trước. Xin lưu ý rằng không thể giữ chỗ ngồi trong giờ giải lao.
Trung tâm Âm nhạc Steen nằm tại 640 Đại lộ Millard. Đỗ xe trên đường trong khuôn viên trường miễn phí sau 4:00 chiều, và có bãi đỗ xe trả phí tại Bãi Camacho ngay phía tây của trung tâm âm nhạc.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6364, 5098, 164, 'Why was the notice written?', 'To advertise an annual concert', 'To attract students for a music class', 'To announce an upcoming competition', 'To celebrate the release of an album', 'A', 'Đáp án đúng là A.
Giải thích:
Thông báo được viết để quảng cáo buổi biểu diễn hàng năm, được chứng minh qua:
1. "yearly recital celebrating excellence" (buổi biểu diễn thường niên)
2. "afternoon and evening of superb vocal, piano, cello, saxophone, and violin music" (buổi chiều và tối với âm nhạc tuyệt vời)
3. Thông tin chi tiết về thời gian, địa điểm và cách đặt chỗ cho buổi hòa nhạc
Phân tích các đáp án:
A. Quảng cáo một buổi hòa nhạc thường niên ✓ (khớp với nội dung thông báo)
B. Thu hút sinh viên cho lớp âm nhạc × (không được đề cập)
C. Thông báo một cuộc thi sắp tới × (không phải mục đích của thông báo)
D. Kỷ niệm việc phát hành album × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6365, 5098, 165, 'What is indicated about the musicians?', 'They all play the same instrument.', 'They are visiting from abroad.', 'They are the recipients of awards.', 'They will graduate from university this year.', 'C', 'Đáp án đúng là C.
Giải thích:
Theo thông báo: "All performers on the program are winners of the department''s performance awards" (Tất cả nghệ sĩ biểu diễn trong chương trình đều là người chiến thắng giải thưởng biểu diễn của khoa).
Phân tích các đáp án:
A. Tất cả chơi cùng một nhạc cụ × (thông báo liệt kê nhiều loại nhạc cụ khác nhau)
B. Họ đến từ nước ngoài × (không được đề cập)
C. Họ là người nhận giải thưởng ✓ (được nêu rõ trong thông báo)
D. Họ sẽ tốt nghiệp đại học năm nay × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6366, 5098, 166, 'Why most likely does the notice mention a television program?', 'To explain the inspiration for an activity', 'To specify that an event will be filmed', 'To highlight the ability of a performer', 'To indicate that a song is well-known', 'C', 'Đáp án đúng là C.
Giải thích:
Thông báo đề cập đến chương trình truyền hình để nêu bật khả năng của Felicia Logan: "who recently reached the semifinal round of the popular singing competition TV show Top Vocalist" (người gần đây đã vào đến vòng bán kết của chương trình truyền hình cuộc thi ca hát nổi tiếng Top Vocalist).
Phân tích các đáp án:
A. Giải thích nguồn cảm hứng cho một hoạt động × (không phải mục đích)
B. Chỉ ra rằng sự kiện sẽ được quay phim × (không được đề cập)
C. Nêu bật khả năng của một người biểu diễn ✓ (thông qua thành tích trong cuộc thi)
D. Chỉ ra rằng một bài hát nổi tiếng × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6367, 5098, 167, 'What is NOT suggested about the event?', 'It will be split into two parts.', 'It will be broadcast over the Internet.', 'It will take place on campus.', 'It will be free to attend.', 'B', 'Đáp án đúng là B.
Giải thích:
Thông báo không hề đề cập đến việc sự kiện sẽ được phát trực tuyến. Trong khi đó:
1. "4:30 P.M. to 6:00 P.M. and 7:30 P.M. to 9:00 P.M." - chia làm hai phần
2. "Steen Music Center is located at 640 Millard Avenue" - diễn ra trong khuôn viên trường
3. "There is no fee for admission" - miễn phí vào cửa
Phân tích các đáp án:
A. Sẽ được chia thành hai phần × (có đề cập)
B. Sẽ được phát trực tuyến ✓ (không được đề cập)
C. Sẽ diễn ra trong khuôn viên trường × (có đề cập)
D. Sẽ được miễn phí vào cửa × (có đề cập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5099, 224, NULL, NULL, 'Ellen Chambers [2:17 P.M.]
The president wants to meet on Wednesday to talk about how we can get higher-quality job candidates for openings in our labs. Do you two have any ideas?
Arjun Malhotra [2:19 P.M.]
The company could offer a referral bonus to employees. Some other biotechnology firms do that.
Juana Amado [2:20 p.M.]
Tlike that idea. We can take advantage of employees'' networks.
Ellen Chambers [2:21 P.M.]
Won''t that require a lot of effort from the employees? And how would we ensure that they don''t refer poor candidates just to get the bonus?
Arjun Malhotra [2:22 P.M.]
All the employee would have to do is provide our department with the person''s contact information.
Juana Amado [2:23 P.M.]
Yes, we would handle the rest, as usual. And maybe the company would only pay the full bonus if the referred person ends up both being hired and staying for a while.
Arjun Malhotra [2:24 P.M.]
Precisely. We could pay half upon hiring and the other half after six months of work.
Ellen Chambers [2:25 P.M.]
OK. Let''s put this plan forward at the meeting.', 'Ellen Chambers [2:17 chiều]
Chủ tịch muốn họp vào thứ Tư để nói về cách chúng ta có thể có được các ứng viên chất lượng cao hơn cho các vị trí trống trong phòng thí nghiệm của chúng ta. Hai bạn có ý tưởng gì không?
Arjun Malhotra [2:19 chiều]
Công ty có thể đưa ra tiền thưởng giới thiệu cho nhân viên. Một số công ty công nghệ sinh học khác làm vậy.
Juana Amado [2:20 chiều]
Tôi thích ý tưởng đó. Chúng ta có thể tận dụng mạng lưới của nhân viên.
Ellen Chambers [2:21 chiều]
Liệu điều đó có đòi hỏi nhiều nỗ lực từ nhân viên không? Và làm thế nào chúng ta đảm bảo họ không giới thiệu ứng viên kém chỉ để nhận thưởng?
Arjun Malhotra [2:22 chiều]
Tất cả những gì nhân viên phải làm là cung cấp cho bộ phận chúng ta thông tin liên hệ của người đó.
Juana Amado [2:23 chiều]
Vâng, chúng ta sẽ xử lý phần còn lại, như thường lệ. Và có lẽ công ty sẽ chỉ trả đầy đủ tiền thưởng nếu người được giới thiệu cuối cùng được thuê và ở lại một thời gian.
Arjun Malhotra [2:24 chiều]
Chính xác. Chúng ta có thể trả một nửa khi tuyển dụng và nửa còn lại sau sáu tháng làm việc.
Ellen Chambers [2:25 chiều]
OK. Hãy đưa kế hoạch này ra tại cuộc họp.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6368, 5099, 168, 'What is mainly being discussed?', 'Expanding into a new industry', 'Finding skilled workers', 'Soliciting client referrals', 'Increasing employee satisfaction', 'B', 'Đáp án đúng là B.
Giải thích:
Cuộc thảo luận tập trung vào việc tìm cách thu hút ứng viên chất lượng cao: "how we can get higher-quality job candidates for openings in our labs". Họ thảo luận về việc sử dụng chương trình giới thiệu nhân viên để tìm người tài.
Phân tích các đáp án:
A. Mở rộng sang ngành công nghiệp mới × (không được đề cập)
B. Tìm kiếm nhân viên có kỹ năng ✓ (chủ đề chính của cuộc thảo luận)
C. Thu thập giới thiệu từ khách hàng × (là về giới thiệu ứng viên, không phải khách hàng)
D. Tăng sự hài lòng của nhân viên × (không phải mục đích chính)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6369, 5099, 169, 'What is most likely true about the writers?', 'They recently went to a networking event together.', 'They work in different departments.', 'They have been given a limited budget.', 'They oversee a hiring process.', 'D', 'Đáp án đúng là D.
Giải thích:
1. Họ thảo luận về quy trình tuyển dụng và cách cải thiện nó
2. "we would handle the rest, as usual" - cho thấy họ thường xuyên xử lý các vấn đề tuyển dụng
3. Họ có quyền đề xuất và thực hiện các chính sách tuyển dụng
Phân tích các đáp án:
A. Họ gần đây đã cùng tham dự sự kiện networking × (không được đề cập)
B. Họ làm việc ở các phòng ban khác nhau × (dường như cùng một phòng tuyển dụng)
C. Họ được cấp ngân sách hạn chế × (không được đề cập)
D. Họ giám sát quy trình tuyển dụng ✓ (rõ ràng từ nội dung thảo luận)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6370, 5099, 170, 'At 2:24 p.M., what does Mr. Malhotra most likely mean when he writes, "Precisely"?', 'Ms. Amado has made a helpful suggestion.', 'They must follow a company policy carefully.', 'Some measurements must be accurate.', 'A project is proceeding on schedule.', 'A', 'Đáp án đúng là A.
Giải thích:
"Precisely" (Chính xác) được Mr. Malhotra dùng để đồng ý với đề xuất của Ms. Amado về việc chia tiền thưởng giới thiệu thành hai phần. Ông tiếp tục phát triển ý tưởng này bằng cách đề xuất cụ thể "pay half upon hiring and the other half after six months".
Phân tích các đáp án:
A. Ms. Amado đã đưa ra một đề xuất hữu ích ✓ (thể hiện sự đồng ý với ý tưởng của cô)
B. Họ phải tuân theo chính sách công ty cẩn thận × (không phải ngữ cảnh này)
C. Một số phép đo phải chính xác × (không liên quan)
D. Một dự án đang tiến hành đúng lịch trình × (không liên quan)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6371, 5099, 171, 'What will the writers most likely do on Wednesday?', 'Determine the recipient of a bonus', 'Describe an idea to an executive', 'Participate in some job interviews', 'Show some equipment to laboratory staff', 'B', 'Đáp án đúng là B.
Giải thích:
Theo cuộc thảo luận:
1. Họ sẽ gặp chủ tịch vào thứ Tư
2. "Let''s put this plan forward at the meeting" - họ sẽ trình bày kế hoạch tiền thưởng giới thiệu
Phân tích các đáp án:
A. Xác định người nhận tiền thưởng × (chưa đến giai đoạn này)
B. Mô tả một ý tưởng với một giám đốc ✓ (họ sẽ trình bày kế hoạch với chủ tịch)
C. Tham gia một số cuộc phỏng vấn việc làm × (không phải mục đích cuộc họp)
D. Giới thiệu thiết bị cho nhân viên phòng thí nghiệm × (không liên quan)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5100, 224, NULL, NULL, 'E-Mail message
From: Rosemary Wolfe
To: Orisa Muyiwa
Subject: RRVK care system
Date: 16 Jul
Attachment: ORRVKC
Dear Ms. Muyiwa,
Thank you for writing to express your interest in the RRVK care system. As you requested, I have attached our brochure detailing the product''s features, specifications, and pricing. — [1] —.
You mention that your hospital''s management wants you to streamline the facility''s operations. — [2] —. The RRVK care system consists of kiosks loaded with specialized software designed to do just that. Your patients can use the system to check themselves in for appointments instead of waiting in line at the hospital''s front desk. This allows your staff to focus on more complex tasks. — [3] —.
If you are interested, I would be happy to give a demonstration of the system at our office. — [4] —. Simply let me know when you are available.
Sincerely,
Rosemary Wolfe', 'Thư điện tử
Từ: Rosemary Wolfe
Đến: Orisa Muyiwa
Chủ đề: Hệ thống chăm sóc RRVK
Ngày: 16/7
Tệp đính kèm: ORRVKC
Kính gửi cô Muyiwa,
Cảm ơn vì đã viết thư bày tỏ sự quan tâm đến hệ thống chăm sóc RRVK. Theo yêu cầu của bạn, tôi đã đính kèm tờ rơi chi tiết về các tính năng, thông số kỹ thuật và giá cả của sản phẩm. — [1] —.
Bạn đề cập rằng ban quản lý bệnh viện của bạn muốn bạn hợp lý hóa hoạt động của cơ sở. — [2] —. Hệ thống chăm sóc RRVK bao gồm các kiosk được tải sẵn phần mềm chuyên dụng được thiết kế để làm điều đó. Bệnh nhân của bạn có thể sử dụng hệ thống để tự đăng ký cho các cuộc hẹn thay vì xếp hàng tại quầy lễ tân của bệnh viện. Điều này cho phép nhân viên của bạn tập trung vào các nhiệm vụ phức tạp hơn. — [3] —.
Nếu bạn quan tâm, tôi rất vui được demo hệ thống tại văn phòng của chúng tôi. — [4] —. Chỉ cần cho tôi biết khi nào bạn rảnh.
Trân trọng,
Rosemary Wolfe');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6372, 5100, 172, 'What is one purpose of the e-mail?', 'To report on an off-site demonstration', 'To correct some out-of-date information', 'To share some customer testimonials', 'To respond to a product inquiry', 'D', 'Đáp án đúng là D.
Giải thích:
Email này là phản hồi cho một yêu cầu thông tin về sản phẩm, thể hiện qua:
1. "Thank you for writing to express your interest" (Cảm ơn vì đã viết thư bày tỏ sự quan tâm)
2. "As you requested, I have attached our brochure" (Theo yêu cầu của bạn, tôi đã đính kèm tờ rơi)
Phân tích các đáp án:
A. Báo cáo về một buổi demo bên ngoài × (chưa có demo nào)
B. Sửa thông tin cũ × (không phải mục đích)
C. Chia sẻ phản hồi của khách hàng × (không được đề cập)
D. Phản hồi yêu cầu về sản phẩm ✓ (mục đích chính của email)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6373, 5100, 173, 'What is suggested about Ms. Muyiwa?', 'She is employed in the healthcare field.', 'She was asked to research self-service kiosks.', 'She is usually stationed at a front desk.', 'She uses customized scheduling software.', 'A', 'Đáp án đúng là A.
Giải thích:
Ms. Muyiwa làm việc trong lĩnh vực y tế, được thể hiện qua:
1. "your hospital''s management" - quản lý bệnh viện của bạn
2. "your patients" - bệnh nhân của bạn
Phân tích các đáp án:
A. Làm việc trong lĩnh vực chăm sóc sức khỏe ✓ (rõ ràng từ ngữ cảnh)
B. Được yêu cầu nghiên cứu kiosk tự phục vụ × (không được nêu rõ)
C. Thường làm việc tại quầy lễ tân × (không được đề cập)
D. Sử dụng phần mềm lập lịch tùy chỉnh × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6374, 5100, 174, 'According to the e-mail, what can the RRVK care system do?', 'Manage inventory', 'Send appointment reminders', 'Track visitors'' arrivals', 'Process payments', 'C', 'Đáp án đúng là C.
Giải thích:
Email đề cập: "patients can use the system to check themselves in for appointments" (bệnh nhân có thể sử dụng hệ thống để tự đăng ký cho các cuộc hẹn). Điều này cho thấy hệ thống có thể theo dõi việc đến của khách.
Phân tích các đáp án:
A. Quản lý kho × (không được đề cập)
B. Gửi lời nhắc cuộc hẹn × (không được đề cập)
C. Theo dõi việc đến của khách ✓ (thông qua tính năng tự đăng ký)
D. Xử lý thanh toán × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6375, 5100, 175, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?
"Reading over it should make it very clear how the RRVK can help your organization."', '[1]', '[2]', '[3]', '[4]', 'A', 'Đáp án đúng là A.
Giải thích:
Câu này phù hợp nhất ở vị trí [1] vì:
1. Ngay trước đó đề cập đến tờ rơi đính kèm về tính năng sản phẩm
2. Câu này nói về việc đọc tài liệu sẽ giúp hiểu rõ cách RRVK có thể giúp tổ chức
3. Tạo liên kết tự nhiên với phần tiếp theo về cụ thể cách hệ thống giúp ích
Phân tích các vị trí:
A. [1] ✓ (phù hợp nhất, tiếp nối việc gửi tờ rơi)
B. [2] × (ngắt mạch thông tin)
C. [3] × (không phù hợp với ngữ cảnh)
D. [4] × (không phù hợp với phần kết thư)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5101, 224, NULL, NULL, 'http://www.lockehanley.com/authors/wendell-green
Wendell Green has been represented by Locke and Hanley Literary Agents since his debut.
His first full-length work, Race Against Time, was included in the SLP 10, the Society of Library Professionals'' yearly list of the best novels aimed at teenagers. He now writes in a variety of genres. Before becoming a full-time author, Mr. Green taught history to high school students. He lives in Armenta with his wite.
Recent Works by Wendell Green
In Wylie Cove
Adventurous journalist Tony Bradley learns a startling secret while investigating strange occurrences in his small coastal town. Over two million copies sold!
Swing Away
The players on the Spriggs Academy baseball team have very different personalities. Can they figure out how to work together before the season ends? Fraser''s Quarterly called this "a must-read for young baseball fans."
Sarah Saves the World
Middle-school student Sarah Fitch tries to keep her new superpowers a secret from her friends and family. A fun and touching graphic novel featuring illustrations by Eva Pineda.
Nails on a Chalkboard
Teaching may be difficult, but it is never boring! This collection of essays about the profession touches on its humorous, frustrating, and heartbreaking aspects.
==========
E-Mail
To: Wendell Green
From: Katherine Hanley
Subject: Exciting news
Date: March 2
Hi Wendell,
I got a call this week from a producer at Hickson Media about developing a film based on your latest book. Her name is Maura Dayton, and she seemed very enthusiastic about the project. She said that Tony Bradley is a great character and they could probably attract a top actor for the part.
Ms. Dayton would like to meet with both of us to present her idea for the adaptation. Could you come in to our office for that sometime this month? Let me know.
Best,
Katherine Hanley, Literary Agent', 'http://www.lockehanley.com/authors/wendell-green
Wendell Green đã được đại diện bởi Locke và Hanley Literary Agents kể từ khi ra mắt.
Tác phẩm dài đầu tiên của anh, Race Against Time, đã được đưa vào SLP 10, danh sách hàng năm của Hiệp hội Chuyên gia Thư viện về những cuốn tiểu thuyết hay nhất dành cho thanh thiếu niên. Hiện tại anh ấy viết ở nhiều thể loại khác nhau. Trước khi trở thành một tác giả toàn thời gian, ông Green đã dạy lịch sử cho học sinh trung học. Anh ấy sống ở Armenta với wite của mình.
Các tác phẩm gần đây của Wendell Green
Ở Wylie Cove
Nhà báo phiêu lưu Tony Bradley biết được một bí mật đáng ngạc nhiên trong khi điều tra những sự kiện kỳ lạ ở thị trấn nhỏ ven biển của mình. Hơn hai triệu bản đã được bán ra! 
Swing Away
Các cầu thủ trong đội bóng chày của Học viện Spriggs có tính cách rất khác nhau. Họ có thể tìm ra cách làm việc cùng nhau trước khi mùa giải kết thúc không? Fraser''s Quarterly gọi đây là "một cuốn sách phải đọc đối với những người hâm mộ bóng chày trẻ tuổi."
Sarah Saves the World
Học sinh trung học cơ sở Sarah Fitch cố gắng giữ bí mật về siêu năng lực mới của mình với bạn bè và gia đình. Một cuốn tiểu thuyết đồ họa vui nhộn và cảm động có hình minh họa của Eva Pineda.
Nails on a Chalkboard
Dạy có thể khó khăn, nhưng nó không bao giờ nhàm chán! Bộ sưu tập các bài luận về nghề nghiệp này đề cập đến những khía cạnh hài hước, bực bội và đau lòng của nó.
============
E-Mail
Gửi đến: Wendell Green
Từ: Katherine Hanley
Chủ đề: Tin tức thú vị
Ngày: 2 tháng 3
Xin chào Wendell,
Tôi nhận được cuộc gọi trong tuần này từ một nhà sản xuất tại Hickson Media về việc phát triển một bộ phim dựa trên cuốn sách mới nhất của bạn. Tên cô ấy là Maura Dayton, và cô ấy có vẻ rất nhiệt tình với dự án. Cô ấy nói rằng Tony Bradley là một nhân vật tuyệt vời và họ có thể thu hút một diễn viên hàng đầu cho vai diễn này.
Cô Dayton muốn gặp cả hai chúng tôi để trình bày ý tưởng của cô ấy cho bộ phim chuyển thể. Bạn có thể đến văn phòng của chúng tôi vào một lúc nào đó trong tháng này không? Hãy cho tôi biết.
Tốt nhất,
Katherine Hanley, Đại lý Văn học');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6376, 5101, 176, 'What is the SLP 10 a list of?', 'Fictional characters', 'First-time authors', 'Books for youth', 'Public libraries', 'C', 'Đáp án đúng là C.
Giải thích:
Theo văn bản: "SLP 10, the Society of Library Professionals'' yearly list of the best novels aimed at teenagers" - rõ ràng đây là danh sách sách dành cho giới trẻ/thiếu niên.
Phân tích các đáp án:
A. Nhân vật hư cấu × (không phải là danh sách nhân vật)
B. Tác giả lần đầu × (không phải danh sách tác giả mới)
C. Sách cho giới trẻ ✓ (được nêu rõ là "novels aimed at teenagers")
D. Thư viện công cộng × (SLP là tổ chức lập danh sách, không phải danh sách thư viện)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6377, 5101, 177, 'What is indicated about Mr. Green?', 'He lives near the ocean.', 'He collaborates with a family member.', 'He has written about his previous career.', 'He sometimes contributes to Fraser''s Quarterly.', 'C', 'Đáp án đúng là C.
Giải thích:
Mr. Green đã viết về nghề dạy học trước đây của mình trong cuốn "Nails on a Chalkboard" - một tập tiểu luận về nghề giảng dạy. Điều này được thể hiện qua:
1. "Before becoming a full-time author, Mr. Green taught history" - ông từng là giáo viên
2. "Nails on a Chalkboard" là cuốn sách về nghề dạy học
Phân tích các đáp án:
A. Sống gần biển × (chỉ đề cập sống ở Armenta)
B. Cộng tác với thành viên gia đình × (Eva Pineda là họa sĩ minh họa, không phải người thân)
C. Viết về nghề nghiệp trước đây ✓ (qua cuốn Nails on a Chalkboard)
D. Đóng góp cho Fraser''s Quarterly × (tạp chí này chỉ đánh giá sách của ông)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6378, 5101, 178, 'In the e-mail, the word "part" in paragraph 1, line 4, is closest in meaning to', 'component', 'section', 'portion', 'role', 'D', 'Đáp án đúng là D.
Giải thích:
Trong email có câu: "they could probably attract a top actor for the part" - trong ngữ cảnh này, "part" được dùng để chỉ vai diễn (role) mà một diễn viên sẽ đóng trong bộ phim chuyển thể từ sách.
Phân tích các đáp án:
A. component (thành phần) × (không phù hợp ngữ cảnh về đóng phim)
B. section (phần) × (không phù hợp)
C. portion (phần) × (không phù hợp)
D. role (vai diễn) ✓ (hoàn toàn phù hợp với ngữ cảnh casting diễn viên)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6379, 5101, 179, 'According to the e-mail, which book may be adapted into a film?', 'In Wylie Cove', 'Swing Away', 'Sarah Saves the World', 'Nails on a Chalkboard', 'A', 'Đáp án đúng là A.
Giải thích:
Email nói về việc chuyển thể "your latest book" (cuốn sách mới nhất) và nhắc đến nhân vật Tony Bradley. Trong danh sách tác phẩm, Tony Bradley là nhân vật chính trong "In Wylie Cove". Email cũng đề cập đến việc tìm diễn viên để đóng vai này.
Phân tích các đáp án:
A. In Wylie Cove ✓ (cuốn sách có nhân vật Tony Bradley)
B. Swing Away × (không phải sách được đề cập)
C. Sarah Saves the World × (không phải)
D. Nails on a Chalkboard × (không phải)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6380, 5101, 180, 'What does Ms. Hanley ask Mr. Green to do in March?', 'Determine the recipient of a bonus', 'Listen to a proposal', 'Make an announcement', 'Edit some writing', 'B', 'Đáp án đúng là B.
Giải thích:
Ms. Hanley yêu cầu Mr. Green đến văn phòng trong tháng 3 để gặp Ms. Dayton: "present her idea for the adaptation" - nghe đề xuất về việc chuyển thể sách thành phim.
Phân tích các đáp án:
A. Xác định người nhận thưởng × (không liên quan)
B. Nghe một đề xuất ✓ (về chuyển thể phim)
C. Đưa ra thông báo × (không được yêu cầu)
D. Chỉnh sửa bài viết × (không được đề cập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5102, 224, NULL, NULL, 'To: Member list
From: Otis Community Center
Date: February 3
Subject: Cooking classes
Attachment: Flyer
As part of our ongoing efforts to celebrate cultural diversity, Otis Community Center will hold a series of one-time cooking classes on Asian dishes this spring. The classes will be held on the first Wednesday evening of each month from March through June. In order, the dishes covered will be Vietnamese chicken curry, Korean kimchi stew, Thai spring rolls, and Cantonese stir-fry beef.
Guest instructors from Roark Culinary Academy will teach the classes in our dedicated cooking classroom. Advance registration and payment are required, and participants will be asked to show proof of registration to their instructor. Registration can be completed at our front desk from February 15 for all classes. Those who are not members of Otis Community Center will be required to pay a $5 registration fee.
Please see the attached flyer for details including materials fees, which vary by class. Questions about the classes may be directed to Heather Tate, our programming specialist.
Akio Hayashi, Director
==========
Otis Community Center
CLASS REGISTRATION CONFIRMATION FORM
Name: Kayla Shull
Membership Number: 499560
Class Title: Thai Spring Rolls
Instructor: David Somsri
Date & Time: May 6, 5 P.M.
Registration Fee: WAIVED
Materials Fee: $15 Paid
Processed by: Eric Woodard
Note:
Refunds of class fees are only issued for cancellations made at least one week before the class date. To cancel your registration, please visit the center or call our front desk at 555-0195.', 'Gửi đến: Danh sách thành viên
Từ: Trung tâm cộng đồng Otis
Ngày: 3 tháng 2
Chủ đề: Lớp học nấu ăn
Đính kèm: Tờ rơi
Là một phần trong nỗ lực không ngừng của chúng tôi để tôn vinh sự đa dạng văn hóa, Trung tâm Cộng đồng Otis sẽ tổ chức một loạt các lớp học nấu ăn một lần về các món ăn châu Á vào mùa xuân này. Các lớp học sẽ được tổ chức vào tối thứ Tư đầu tiên của mỗi tháng từ tháng Ba đến tháng Sáu. Theo thứ tự, các món ăn được bao gồm sẽ là cà ri gà Việt Nam, món hầm kim chi Hàn Quốc, chả giò Thái Lan và thịt bò xào Quảng Đông.
Các giảng viên khách mời từ Học viện Ẩm thực Roark sẽ dạy các lớp học trong lớp học nấu ăn chuyên dụng của chúng tôi. Yêu cầu đăng ký và thanh toán trước, và người tham gia sẽ được yêu cầu xuất trình bằng chứng đăng ký cho người hướng dẫn của họ. Việc đăng ký có thể được hoàn thành tại quầy lễ tân của chúng tôi từ ngày 15 tháng 2 cho tất cả các lớp học. Những người không phải là thành viên của Trung tâm Cộng đồng Otis sẽ phải trả phí đăng ký 5 đô la.
Vui lòng xem tờ rơi đính kèm để biết chi tiết bao gồm phí vật liệu, khác nhau tùy theo lớp. Các câu hỏi về các lớp học có thể được chuyển đến Heather Tate, chuyên gia lập trình của chúng tôi.
Akio Hayashi, Giám đốc
============
Trung tâm cộng đồng Otis
MẪU XÁC NHẬN ĐĂNG KÝ LỚP HỌC
Tên: Kayla Shull
Số thành viên: 499560
Tiêu đề lớp học: Chả giò Thái
Người hướng dẫn: David Somsri
Ngày & Giờ: 5 giờ chiều ngày 6 tháng 5
Phí đăng ký: MIỄN PHÍ
Phí vật liệu: 15 đô la Đã thanh toán
Được xử lý bởi: Eric Woodard
Lưu ý:
Hoàn tiền học chỉ được hoàn lại cho việc hủy bỏ được thực hiện ít nhất một tuần trước ngày học. Để hủy đăng ký của bạn, vui lòng đến trung tâm hoặc gọi cho quầy lễ tân của chúng tôi theo số 555-0195.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6381, 5102, 181, 'Why was the e-mail written?', 'To recruit volunteer workers', 'To issue invitations to special dinners', 'To ask for feedback about a program', 'To publicize some learning opportunities', 'D', 'Đáp án đúng là D.
Giải thích:
Email được viết để quảng bá các lớp học nấu ăn mới:
1. "will hold a series of one-time cooking classes" - tổ chức chuỗi lớp học nấu ăn
2. Chi tiết về thời gian, địa điểm, cách đăng ký
3. Thông tin về phí và cách thức tham gia
Phân tích các đáp án:
A. Tuyển tình nguyện viên × (không đề cập)
B. Phát hành lời mời đến bữa tối đặc biệt × (là lớp học nấu ăn, không phải bữa tối)
C. Yêu cầu phản hồi về chương trình × (không có yêu cầu phản hồi)
D. Quảng bá cơ hội học tập ✓ (đúng với mục đích email)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6382, 5102, 182, 'Where will a community activity take place?', 'On a city street', 'At Otis Community Center', 'At several local restaurants', 'At Roark Culinary Academy', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email, các lớp học sẽ diễn ra tại Otis Community Center: "in our dedicated cooking classroom" (trong lớp học nấu ăn chuyên dụng của chúng tôi). Mọi hoạt động đăng ký và tham gia đều diễn ra tại đây.
Phân tích các đáp án:
A. Trên đường phố × (không phải địa điểm)
B. Tại Trung tâm Cộng đồng Otis ✓ (được nêu rõ trong email)
C. Tại nhiều nhà hàng địa phương × (không phải địa điểm)
D. Tại Học viện Ẩm thực Roark × (chỉ là nơi cung cấp giảng viên)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6383, 5102, 183, 'What dish will be cooked in March?', 'Vietnamese chicken curry', 'Korean kimchi stew', 'Thai spring rolls', 'Cantonese stir-fry beef', 'A', 'Đáp án đúng là A.
Giải thích:
Email nêu rõ thứ tự các món ăn sẽ được dạy từ tháng 3 đến tháng 6: "In order, the dishes covered will be Vietnamese chicken curry, Korean kimchi stew, Thai spring rolls, and Cantonese stir-fry beef". Tháng 3 là tháng đầu tiên, nên sẽ học món cà ri gà Việt Nam.
Phân tích các đáp án:
A. Cà ri gà Việt Nam ✓ (món đầu tiên, tháng 3)
B. Canh kimchi Hàn Quốc × (tháng 4)
C. Gỏi cuốn Thái × (tháng 5)
D. Thịt bò xào Quảng Đông × (tháng 6)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6384, 5102, 184, 'Why was a fee waived for Ms. Shull?', 'She will provide some materials herself.', 'She is a community center member.', 'She registered before a certain date.', 'She attended each session of a class.', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email, những người không phải thành viên phải trả phí đăng ký $5. Trong form đăng ký của Ms. Shull có Membership Number (số thành viên) 499560 và Registration Fee: WAIVED (phí đăng ký: miễn). Điều này cho thấy cô được miễn phí vì là thành viên.
Phân tích các đáp án:
A. Cô ấy sẽ tự cung cấp nguyên liệu × (vẫn phải trả phí nguyên liệu $15)
B. Cô ấy là thành viên trung tâm cộng đồng ✓ (có số thành viên)
C. Cô ấy đăng ký trước một ngày nhất định × (không được đề cập)
D. Cô ấy tham dự mỗi buổi học × (chưa diễn ra lớp học)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6385, 5102, 185, 'To whom should Ms. Shull show her confirmation form?', 'Ms. Tate', 'Mr. Hayashi', 'Mr. Somsri', 'Mr. Woodard', 'C', 'Đáp án đúng là C.
Giải thích:
Theo email: "participants will be asked to show proof of registration to their instructor" (học viên sẽ được yêu cầu trình giấy tờ đăng ký cho giảng viên). Trong form đăng ký, Mr. Somsri là giảng viên của lớp học.
Phân tích các đáp án:
A. Ms. Tate × (là chuyên viên chương trình)
B. Mr. Hayashi × (là giám đốc trung tâm)
C. Mr. Somsri ✓ (là giảng viên của lớp)
D. Mr. Woodard × (là người xử lý đăng ký)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5103, 224, NULL, NULL, 'E-Mail message
To: Ingram Group staff
From: James Buckley
Subject: Upcoming software training
Date: May 14
Attachment: Training Schedule
Hello everyone,
In the next few weeks, we will have training sessions for two software programs that are important to our business.
First, all employees must attend a 90-minute training on Skeddit, the scheduling software we will switch over to in June. The training session will be held multiple times before the transition to the new system.
Second, a two-hour online training session on Calacad will be required only for engineering department staff. The developer created the training to publicize new functions that have been added to the software, and it will benefit all members of the department to learn about them.
The full schedule for the trainings is attached to this e-mail. Registration can be completed on the "Training" page of the employee Web site.
Sincerely,
James Buckley
Ingram Group
==========
Training Schedule
Date       Software        Time                                         Location
May 26      Calacad      9:00 A.M.–11:00 A.M.         Online
May 30      Skeddit      9:00 A.M.–10:30 A.M.         Conference Room A
June 1        Skeddit      1:00 P.M.–2:30 P.M.             Conference Room A
June 5      Calacad       2:00 P.M.–4:00 P.M.            Online
June 7      Skeddit       10:00 A.M.–11:30 A.M.         Conference Room A
June 12    Skeddit       3:30 P.M.–5:00 P.M.             Conference Room A
*The Web link for the online training will be sent to participants upon registration.*
============
E-Mail message
To: James Buckley
From: Lisa Chang
Subject: Re: Upcoming software training
Date: May 15
Hi James,
I''ll need to take both of those trainings, but I have a meeting on the morning of May 26.
It''s with important external partners and I can''t move it. Then I''ll be out of the country on vacation from May 29 through June 9. In this situation, what do you recommend I do about the Calacad training?
Thanks,
Lisa', 'Thư điện tử
Gửi đến: Nhân viên Ingram Group
Từ: James Buckley
Chủ đề: Đào tạo phần mềm sắp tới
Ngày: 14 tháng 5
Đính kèm: Lịch đào tạo
Xin chào mọi người,
Trong vài tuần tới, chúng tôi sẽ có các buổi đào tạo về hai chương trình phần mềm quan trọng đối với doanh nghiệp của chúng tôi.
Đầu tiên, tất cả nhân viên phải tham gia khóa đào tạo 90 phút về Skeddit, phần mềm lập lịch trình mà chúng tôi sẽ chuyển sang vào tháng Sáu. Buổi đào tạo sẽ được tổ chức nhiều lần trước khi chuyển sang hệ thống mới.
Thứ hai, một buổi đào tạo trực tuyến kéo dài hai giờ về Calacad sẽ chỉ được yêu cầu cho nhân viên bộ phận kỹ thuật. Nhà phát triển đã tạo ra khóa đào tạo để công khai các chức năng mới đã được thêm vào phần mềm và nó sẽ mang lại lợi ích cho tất cả các thành viên của bộ phận để tìm hiểu về chúng.
Lịch trình đầy đủ cho các khóa đào tạo được đính kèm trong e-mail này. Bạn có thể hoàn tất đăng ký trên trang "Đào tạo" của trang web của nhân viên.
Trân trọng,
James Buckley
Ingram Group
=========
Lịch đào tạo
Ngày Phần mềm Giờ Địa điểm
Ngày 26 tháng 5 Calacad 9:00 sáng–11:00 sáng Trực tuyến
Ngày 30 tháng 5 Skeddit 9:00 sáng đến 10:30 sáng Phòng Hội Nghị A
Ngày 1 Tháng 6 Skeddit 1:00 P.M.–2:30 P.M. Phòng Hội Nghị A
Ngày 5 Tháng 6 Calacad 2:00 P.M.–4:00 P.M. Trực tuyến
Ngày 7 tháng 6 Skeddit 10:00 sáng đến 11:30 sáng Phòng Hội Nghị A
Ngày 12 Tháng 6 Skeddit 3:30 P.M.–5:00 P.M. Phòng hội nghị A
*Liên kết Web cho khóa đào tạo trực tuyến sẽ được gửi cho người tham gia khi đăng ký.*
============
Tin nhắn E-Mail
Gửi: James Buckley
Từ: Lisa Chang
Chủ đề: Re: Đào tạo phần mềm sắp tới
Ngày: 15 tháng 5
Xin chào James,
Tôi sẽ cần tham gia cả hai khóa đào tạo đó, nhưng tôi có một cuộc họp vào sáng ngày 26 tháng 5.
Đó là với các đối tác bên ngoài quan trọng và tôi không thể di chuyển nó. Sau đó, tôi sẽ ra khỏi đất nước trong kỳ nghỉ từ ngày 29 tháng 5 đến ngày 9 tháng 6. Trong tình huống này, bạn khuyên tôi nên làm gì về khóa đào tạo Calacad? 
Cảm ơn,
Lisa');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6386, 5103, 186, 'What does the first e-mail mention about Calacad?', 'It has acquired new capabilities.', 'It was developed specifically for the company.', 'It can be downloaded from the employee Web site.', 'It is the subject of regular trainings.', 'A', 'Đáp án đúng là A.
Giải thích:
Email đầu tiên đề cập: "The developer created the training to publicize new functions that have been added to the software" - nhà phát triển tạo khóa đào tạo để giới thiệu các chức năng mới đã được thêm vào phần mềm.
Phân tích các đáp án:
A. Đã có thêm các chức năng mới ✓ (được đề cập trực tiếp)
B. Được phát triển riêng cho công ty × (không đề cập)
C. Có thể tải về từ trang web nhân viên × (chỉ đề cập đến việc đăng ký)
D. Là chủ đề của các khóa đào tạo thường xuyên × (chỉ có 2 buổi đào tạo)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6387, 5103, 187, 'What is NOT true about the schedule for Skeddit training sessions?', 'It includes both morning and afternoon sessions.', 'It spans a period of more than one month.', 'All of the sessions will be held in the same location.', 'The person who will conduct the training is not specified.', 'B', 'Đáp án đúng là B.
Giải thích:
Lịch đào tạo Skeddit:
- Các buổi sáng (9:00, 10:00) và chiều (1:00, 3:30) ✓
- Từ 30/5 đến 12/6 (chưa đến một tháng) ✗
- Tất cả đều tại Conference Room A ✓
- Không đề cập người đào tạo ✓
Phân tích các đáp án:
A. Có cả buổi sáng và chiều × (đúng)
B. Kéo dài hơn một tháng ✓ (sai - chỉ trong vòng 2 tuần)
C. Tất cả các buổi học ở cùng địa điểm × (đúng - Conference Room A)
D. Không nêu rõ người đào tạo × (đúng)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6388, 5103, 188, 'Why did Ms. Chang write to Mr. Buckley?', 'To ask for confirmation of a registration', 'To request advice about a scheduling difficulty', 'To inform him of a change to her vacation plans', 'To express concern about some technology', 'B', 'Đáp án đúng là B.
Giải thích:
Ms. Chang viết email để hỏi ý kiến về vấn đề lịch học: "what do you recommend I do about the Calacad training?" vì cô ấy bận họp vào buổi sáng 26/5 và đi nghỉ từ 29/5 đến 9/6.
Phân tích các đáp án:
A. Yêu cầu xác nhận đăng ký × (không phải)
B. Hỏi ý kiến về khó khăn lịch trình ✓ (đúng mục đích email)
C. Thông báo thay đổi kế hoạch nghỉ × (chỉ thông báo lịch nghỉ)
D. Bày tỏ lo ngại về công nghệ × (không đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6389, 5103, 189, 'What is suggested about Ms. Chang?', 'She travels frequently for work.', 'She fulfilled a training requirement.', 'She is a member of the engineering department.', 'She is glad that a software program will be replaced.', 'C', 'Đáp án đúng là C.
Giải thích:
Ms. Chang phải là thành viên phòng kỹ thuật vì:
1. "I''ll need to take both of those trainings" - cô ấy cần tham gia cả hai khóa học
2. Theo email đầu, khóa học Calacad "will be required only for engineering department staff" - chỉ bắt buộc với nhân viên phòng kỹ thuật
Phân tích các đáp án:
A. Thường xuyên đi công tác × (chỉ đề cập một kỳ nghỉ)
B. Đã hoàn thành yêu cầu đào tạo × (chưa tham gia)
C. Là thành viên phòng kỹ thuật ✓ (vì phải học Calacad)
D. Vui vì một phần mềm sẽ được thay thế × (không đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6390, 5103, 190, 'On what date will Ms. Chang most likely undergo some training?', 'May 26', 'June 1', 'June 7', 'June 12', 'D', 'Đáp án đúng là D.
Giải thích:
Ms. Chang không thể tham gia các buổi:
- 26/5: bận họp buổi sáng
- 29/5-9/6: đi nghỉ (loại các ngày 30/5, 1/6, 5/6, 7/6)
Do đó chỉ còn buổi học ngày 12/6 là khả dụng.
Phân tích các đáp án:
A. 26/5 × (bận họp)
B. 1/6 × (đang đi nghỉ)
C. 7/6 × (đang đi nghỉ)
D. 12/6 ✓ (ngày duy nhất có thể tham gia)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5104, 224, NULL, NULL, 'E-Mail
To: shinju.kaneko@zipmail.com
From: s.armstrong@oknet.com
Date: October 14
Subject: RE: Visit
Dear Ms. Kaneko,
My family would be delighted to welcome you into 195 Strickland Boulevard. We are indeed quite proud to live in one of the few residences designed by Basma Itani. It would be a pleasure to share our home''s unique beauty with others through the photographs in your book.
It is easy to reach 195 Strickland Boulevard by public transportation from Harrington Airport. You simply take either Bus 412 or Bus 462 and get off at the final stop. The house is about one block back in the direction the bus came from. In fact, you are quite likely to see it from the window shortly before arriving. If you have any problems finding it, you can call me at 555-0185.
I look forward to meeting you next week.
Best,
Shane Armstrong
==========
Harrington Airport Bus Schedule
Seven days per week, year-round
#             Route                                                                     First Bus             Last Bus
410.       Airport ➝ Downtown                                           6:20 A.M.            9:50 P.M.
412        Airport ➝ Downtown ➝ Belmont                     6:05 A.M.           10:05 P.M.
437       Airport ➝ Riverfront ➝ Abbott Heights        6:25 A.M.            9:55 P.M.
450      Airport ➝ Edgewood                                             6:15 A.M.             9:45 P.M.
462      Airport ➝ Market District ➝ Belmont            6:10 A.M.              10:10 P.M.
470      Airport ➝ Abbott Heights                                   6:30 A.M.             10:00 P.M.
===========
HARRINGTON AIRPORT BUSES
Today (October 19), the airport bus to Edgewood will stop on Bishop Street instead of Yeager Avenue. This change is necessary because of road closures for the Fall Festival. For details, visit the tourism desk.
All bus passengers should be advised that, as always, your baggage cannot be placed on a seat unless you have bought the ticket for that specific seat. Otherwise, the baggage must be stored underneath the bus. The bus driver will help you load and unload it safely.', 'E-Mail
To: shinju.kaneko@zipmail.com
From: s.armstrong@oknet.com
Ngày: 14 tháng 10
Chủ đề: RE: Tham quan
Thưa cô Kaneko,
Gia đình tôi rất vui mừng được chào đón bạn đến với 195 Đại lộ Strickland. Chúng tôi thực sự khá tự hào khi sống trong một trong số ít các khu dân cư được thiết kế bởi Basma Itani. Thật vui khi được chia sẻ vẻ đẹp độc đáo của ngôi nhà của chúng tôi với những người khác thông qua những bức ảnh trong cuốn sách của bạn.
Thật dễ dàng để đến 195 Đại lộ Strickland bằng phương tiện giao thông công cộng từ Sân bay Harrington. Bạn chỉ cần đi xe buýt 412 hoặc xe buýt 462 và xuống ở trạm dừng cuối cùng. Ngôi nhà cách hướng xe buýt đến khoảng một dãy nhà. Trên thực tế, bạn rất có thể nhìn thấy nó từ cửa sổ ngay trước khi đến nơi. Nếu bạn gặp bất kỳ khó khăn nào khi tìm kiếm nó, bạn có thể gọi cho tôi theo số 555-0185.
Tôi mong được gặp bạn vào tuần tới.
Tốt nhất,
Shane Armstrong
============
Lịch trình xe buýt sân bay Harrington
Bảy ngày mỗi tuần, quanh năm
# Tuyến đường Xe buýt đầu tiên Xe buýt cuối cùng
410. Sân Bay ➝ Trung Tâm Thành Phố 6:20 Sáng 9:50 P.M.
412 Sân bay ➝ Trung tâm thành phố ➝ Belmont 6:05 sáng 10:05 P.M.
437 Sân bay ➝ Bờ sông ➝ Abbott Heights 6:25 sáng 9:55 P.M.
450 Sân Bay ➝ Edgewood 6:15 S.M. 9:45 P.M.
462 Sân bay ➝ Market District ➝ Belmont 6:10 A.M. 10:10 P.M.
470 Sân bay ➝ Abbott Heights 6:30 A.M. 10:00 P.M.
============
XE BUÝT SÂN BAY HARRINGTON
Hôm nay (19 tháng 10), xe buýt sân bay đến Edgewood sẽ dừng ở Phố Bishop thay vì Đại lộ Yeager. Sự thay đổi này là cần thiết vì các con đường bị đóng cửa cho Lễ hội mùa thu. Để biết thêm chi tiết, hãy truy cập bàn du lịch.
Tất cả hành khách xe buýt nên được thông báo rằng, như mọi khi, hành lý của bạn không thể được đặt trên ghế trừ khi bạn đã mua vé cho chỗ ngồi cụ thể đó. Nếu không, hành lý phải được cất bên dưới xe buýt. Tài xế xe buýt sẽ giúp bạn bốc xếp nó một cách an toàn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6391, 5104, 191, 'Why most likely is Ms. Kaneko traveling to Mr. Armstrong''s area?', 'To attend a design exhibition', 'To take pictures of a property', 'To conduct an interview for a publication', 'To advise him on a renovation project', 'B', 'Đáp án đúng là B.
Giải thích:
Email đề cập: "share our home''s unique beauty with others through the photographs in your book" - chia sẻ vẻ đẹp độc đáo của ngôi nhà qua những bức ảnh trong cuốn sách của bạn. Điều này cho thấy Ms. Kaneko đến để chụp ảnh ngôi nhà.
Phân tích các đáp án:
A. Tham dự triển lãm thiết kế × (không được đề cập)
B. Chụp ảnh một bất động sản ✓ (để đưa vào sách)
C. Thực hiện phỏng vấn cho một ấn phẩm × (không đề cập việc phỏng vấn)
D. Tư vấn về dự án cải tạo × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6392, 5104, 192, 'In his e-mail, what information does Mr. Armstrong indicate that Ms. Kaneko is already aware of?', 'The composition of his family', 'The architect of his house', 'The location of his workplace', 'The results of a building inspection', 'B', 'Đáp án đúng là B.
Giải thích:
Trong email, ông Armstrong viết "We are indeed quite proud to live in one of the few residences designed by Basma Itani". Cụm từ "indeed" (quả thực) cho thấy đây là thông tin xác nhận lại điều Ms. Kaneko đã biết về kiến trúc sư của ngôi nhà.
Phân tích các đáp án:
A. Thành phần gia đình × (không thể hiện là thông tin đã biết)
B. Kiến trúc sư của ngôi nhà ✓ (được ngụ ý qua từ "indeed")
C. Vị trí nơi làm việc × (không được đề cập)
D. Kết quả kiểm tra tòa nhà × (không được đề cập)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6393, 5104, 193, 'In what neighborhood is 195 Strickland Boulevard located?', 'Downtown', 'Belmont', 'Abbott Heights', 'Edgewood', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email, để đến nhà có thể đi bus 412 hoặc 462. Xem lịch trình bus:
- Bus 412: Airport ➝ Downtown ➝ Belmont
- Bus 462: Airport ➝ Market District ➝ Belmont
Cả hai tuyến đều kết thúc ở Belmont, và nhà cách điểm cuối một block, nên địa chỉ nằm ở khu Belmont.
Phân tích các đáp án:
A. Downtown × (chỉ là điểm trung gian)
B. Belmont ✓ (điểm cuối của cả hai tuyến bus được đề xuất)
C. Abbott Heights × (không phải điểm đến)
D. Edgewood × (không phải điểm đến)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6394, 5104, 194, 'Which bus''s route has temporarily changed?', '410', '437', '450', '470', 'C', 'Đáp án đúng là C.
Giải thích:
Theo thông báo: "Today (October 19), the airport bus to Edgewood will stop on Bishop Street instead of Yeager Avenue". Theo lịch trình, bus 450 là tuyến đi Edgewood (Airport ➝ Edgewood).
Phân tích các đáp án:
A. 410 × (không phải tuyến thay đổi)
B. 437 × (không phải tuyến thay đổi)
C. 450 ✓ (tuyến đi Edgewood bị thay đổi lộ trình)
D. 470 × (không phải tuyến thay đổi)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6395, 5104, 195, 'What does the notice indicate about Harrington Airport buses?', 'They have assigned seating.', 'Tickets can be bought from their drivers.', 'They have overhead baggage compartments.', 'Their passengers may have to stand during the ride.', 'A', 'Đáp án đúng là A.
Giải thích:
Thông báo nêu: "baggage cannot be placed on a seat unless you have bought the ticket for that specific seat" - không được đặt hành lý lên ghế trừ khi bạn đã mua vé cho chính ghế đó. Điều này ngụ ý rằng các xe bus có chỗ ngồi được chỉ định.
Phân tích các đáp án:
A. Có chỗ ngồi được chỉ định ✓ (thể hiện qua việc mua vé cho ghế cụ thể)
B. Có thể mua vé từ tài xế × (không được đề cập)
C. Có ngăn hành lý trên cao × (chỉ đề cập chứa dưới xe)
D. Hành khách có thể phải đứng × (không được đề cập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5105, 224, NULL, '2025/test2/image/test2-p7-image-196.jpg', 'Clemente Street Lot
HAYWARD (March 2)-The Hayward City Council is exploring various options for the future of a 5-acre city-owned lot located on Clemente Street. Bids and proposals are being accepted at this time, with the Greenway Collaborative, a local environmental group, advocating for leaving the lot empty and in the city''s possession. Hillview Property Development is interested in purchasing the lot. It intends to build Marshall Plaza, a small building with space for retail business, and establish a courtyard and a small green area with trees, benches, and flower gardens that would be designated for public use.
"Our planned combination of retail units and green space is a viable solution for this neighborhood, which is in critical need of revitalization," said Luoyang Meng, a Hillview Property Development representative. "Our company has the resources to create an attractive and thriving retail center as well as the expertise to minimize disruptions to wildlife habitats. We hope to have the opportunity to showcase our skills."
===========
E-Mail message
From: Clifford Mullen < clifford@busybbakery.com>
To: Racquel Shaw <r_shaw@hillviewprop.com>
Date: November 18
Subject: Rental inquiry
Dear Ms. Shaw,
I own the Busy Bee Bakery downtown, and I am interested in renting a second location to sell my baked goods. Marshall Plaza would be ideal for my business because of the anticipated foot traffic. I am also drawn to the convenience of the easy access to public transportation and the unloading area in the back. I need at least three hundred square meters of space, but I do not want cooking facilities, as our staff will bake at our main site and just deliver the goods to the secondary site. I''m also wondering if you could tell me the average rates for water, electricity, and gas. I know that these are not included in the monthly rental fee.
Thanks for the information,
Clifford Mullen.', 'Clemente Street Lot
HAYWARD (ngày 2 tháng 3)-Hội đồng thành phố Hayward đang khám phá nhiều lựa chọn khác nhau cho tương lai của một lô đất thuộc sở hữu của thành phố rộng 5 mẫu Anh nằm trên Phố Clemente. Các giá thầu và đề xuất đang được chấp nhận vào thời điểm này, với Greenway Collaborative, một nhóm môi trường địa phương, ủng hộ việc để lại lô đất trống và thuộc quyền sở hữu của thành phố. Hillview Property Development quan tâm đến việc mua lô đất này. Nó dự định xây dựng Marshall Plaza, một tòa nhà nhỏ có không gian cho kinh doanh bán lẻ, và thiết lập một sân trong và một khu vực xanh nhỏ với cây cối, ghế dài và vườn hoa sẽ được chỉ định để sử dụng công cộng.
"Sự kết hợp theo kế hoạch của chúng tôi giữa các đơn vị bán lẻ và không gian xanh là một giải pháp khả thi cho khu phố này, nơi đang rất cần được hồi sinh," Luoyang Meng, một đại diện của Hillview Property Development cho biết. "Công ty chúng tôi có các nguồn lực để tạo ra một trung tâm bán lẻ hấp dẫn và phát triển mạnh cũng như chuyên môn để giảm thiểu sự gián đoạn đối với môi trường sống của động vật hoang dã. Chúng tôi hy vọng sẽ có cơ hội thể hiện kỹ năng của mình."
=========
Tin nhắn E-Mail
Từ: Clifford Mullen < clifford@busybakery.com>
Gửi: Racquel Shaw <r_shaw@hillviewprop.com>
Ngày: 18 tháng 11
Chủ đề: Yêu cầu cho thuê
Kính gửi cô Shaw,
Tôi sở hữu tiệm bánh Busy Bee Bakery ở trung tâm thành phố và tôi muốn thuê một địa điểm thứ hai để bán bánh của mình. Marshall Plaza sẽ là nơi lý tưởng cho doanh nghiệp của tôi vì lưu lượng người đi bộ dự kiến. Tôi cũng bị thu hút bởi sự tiện lợi của việc dễ dàng tiếp cận phương tiện giao thông công cộng và khu vực dỡ hàng ở phía sau. Tôi cần ít nhất ba trăm mét vuông không gian, nhưng tôi không muốn thiết bị nấu ăn, vì nhân viên của chúng tôi sẽ nướng bánh tại địa điểm chính của chúng tôi và chỉ giao hàng đến địa điểm phụ. Tôi cũng đang tự hỏi liệu bạn có thể cho tôi biết mức giá trung bình cho nước, điện và gas không. Tôi biết rằng những thứ này không được bao gồm trong phí thuê hàng tháng.
Cảm ơn vì thông tin,
Clifford Mullen
[Hình ảnh sơ đồ Đơn vị bán lẻ Marshall Plaza:
ĐơnĐơn vị 101: 225m2 Có sẵn
Đơn vị 102: 320m2Có sẵn
Đơnh 103: 270m2Có sẵn
ĐơnĐơn 104: 350m2 Benny''s Sweet Shop
Đơn vị 105: 315m2 Có sẵn Bao gồm nhà bếp
Sân trong giữa]');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6396, 5105, 196, 'What is the purpose of the article?', 'To give an update about public land', 'To notify local residents of a closure', 'To promote the sale of an unused lot', 'To elicit aid for a park upgrade', 'A', 'Đáp án đúng là A.
Giải thích:
Bài báo cập nhật về việc Hội đồng thành phố Hayward đang xem xét các phương án cho khu đất công 5 mẫu Anh trên đường Clemente:
- Đang nhận đề xuất và đấu thầu
- Greenway Collaborative muốn giữ đất trống
- Hillview Property Development muốn mua để xây Marshall Plaza
Phân tích đáp án:
A. Cập nhật về đất công ✓ (mục đích chính của bài)
B. Thông báo đóng cửa × (không đề cập)
C. Quảng bá bán lô đất × (chỉ thông tin về các phương án đang xem xét)
D. Kêu gọi hỗ trợ nâng cấp công viên × (không phải mục đích)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6397, 5105, 197, 'What beneficial aspect of Hillview Property Development does Mr. Meng mention?', 'Its intention to create more jobs in the city of Hayward', 'Its experience with keeping building expenditures under control', 'Its use of environmentally friendly construction materials', 'Its ability to preserve spaces where animals live', 'D', 'Đáp án đúng là D.
Giải thích:
Mr. Meng đề cập đặc biệt về: "expertise to minimize disruptions to wildlife habitats" - chuyên môn để giảm thiểu tác động đến môi trường sống của động vật.
Phân tích đáp án:
A. Ý định tạo việc làm × (không đề cập)
B. Kinh nghiệm kiểm soát chi phí × (không đề cập)
C. Sử dụng vật liệu thân thiện môi trường × (không đề cập)
D. Khả năng bảo tồn nơi sống của động vật ✓ (được nêu trực tiếp trong phát biểu của Mr. Meng)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6398, 5105, 198, 'What is suggested about Hillview Property Development in Mr. Mullen''s e-mail?', 'It constructed the building where his bakery is.', 'It is awaiting the final building permits.', 'Its proposal was accepted by city officials.', 'Its staff usually uses public transportation.', 'C', 'Đáp án đúng là C.
Giải thích:
Trong email của Mr. Mullen, việc ông đang hỏi thuê mặt bằng tại Marshall Plaza và thảo luận chi tiết về không gian, tiện ích ngụ ý rằng dự án của Hillview đã được chấp thuận và đang trong quá trình triển khai.
Phân tích đáp án:
A. Xây dựng tiệm bánh hiện tại của ông × (tiệm bánh ở downtown)
B. Đang chờ giấy phép × (đã qua giai đoạn này)
C. Đề xuất được chấp thuận ✓ (thể hiện qua việc đang cho thuê mặt bằng)
D. Nhân viên dùng phương tiện công cộng × (không liên quan)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6399, 5105, 199, 'What information about Marshall Plaza does Mr. Mullen request?', 'The security measures for the building', 'The cost of utilities at a site', 'The due date for monthly fees', 'The size of an unloading area', 'B', 'Đáp án đúng là B.
Giải thích:
Trong email, Mr. Mullen yêu cầu thông tin về: "average rates for water, electricity, and gas" (chi phí trung bình cho nước, điện và gas).
Phân tích đáp án:
A. Biện pháp an ninh × (không hỏi)
B. Chi phí tiện ích ✓ (hỏi rõ về giá nước, điện, gas)
C. Ngày đến hạn phí hàng tháng × (không hỏi)
D. Kích thước khu vực dỡ hàng × (chỉ đề cập có khu vực này)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6400, 5105, 200, 'Which unit would Mr. Mullen most likely be interested in?', 'Unit 101', 'Unit 102', 'Unit 103', 'Unit 105', 'B', 'Đáp án đúng là B.
Giải thích:
Yêu cầu của Mr. Mullen:
1. "need at least three hundred square meters" - cần ít nhất 300m2
2. "do not want cooking facilities" - không cần thiết bị nấu nướng
Xem xét các unit:
- Unit 101: 225m2 (quá nhỏ)
- Unit 102: 320m2 (đủ rộng, không có bếp)
- Unit 103: 270m2 (quá nhỏ)
- Unit 104: 350m2 (đã có người thuê)
- Unit 105: 315m2 includes kitchen (có bếp - không phù hợp)
Unit 102 phù hợp nhất vì đủ diện tích và không có bếp.');;

