INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6407, 5112, 7, 'When did you last restart your computer?', 'A few hours ago', 'Because of a software update', 'Today''s my last day', NULL, 'A', 'Câu hỏi: "Lần cuối bạn khởi động lại máy tính là khi nào?"
A: "Vài giờ trước"
B: "Vì một bản cập nhật phần mềm"
C: "Hôm nay là ngày cuối cùng của tôi"
Giải thích: Đáp án A đúng vì câu hỏi hỏi về thời gian, và "vài giờ trước" là câu trả lời trực tiếp về thời điểm khởi động lại máy tính');;
