INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6411, 5116, 11, 'Have you received the new work uniforms?', 'Once every two years', 'There''s been a shipping delay', 'To the maintenance department', NULL, 'B', 'Câu hỏi: "Bạn đã nhận được đồng phục mới chưa?"
A: "Hai năm một lần"
B: "Có sự chậm trễ trong vận chuyển"
C: "Đến phòng bảo trì"
Giải thích: Đáp án B đúng vì người trả lời giải thích lý do chưa nhận được đồng phục là do có sự chậm trễ trong vận chuyển');;
