INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6412, 5117, 12, 'How will the applicants'' résumés be screened?', 'He went to a public university', 'Is it in the conference room?', 'We''ve already started interviews', NULL, 'C', 'Câu hỏi: "Hồ sơ của ứng viên sẽ được sàng lọc như thế nào?"
A: "Anh ấy học ở một trường đại học công"
B: "Nó có ở trong phòng họp không?"
C: "Chúng tôi đã bắt đầu phỏng vấn"
Giải thích: Đáp án C đúng vì câu trả lời cho thấy quá trình sàng lọc đã tiến triển đến giai đoạn phỏng vấn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5118, 226, '2025/test3/audio/test3_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6413, 5118, 13, 'When should I expect the new sofa to arrive?', 'Within three business days', 'Some quality control checks', 'Yes, it''s really comfortable', NULL, 'A', 'Câu hỏi: "Khi nào tôi có thể nhận được chiếc ghế sofa mới?"
A: "Trong vòng ba ngày làm việc"
B: "Một số kiểm tra chất lượng"
C: "Vâng, nó thực sự thoải mái"
Giải thích: Đáp án A đúng vì câu trả lời cung cấp một khung thời gian cụ thể cho việc giao hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5119, 226, '2025/test3/audio/test3_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6414, 5119, 14, 'Why don''t you join us for dinner on Friday?', 'A table by the windows', 'I just made plans with a friend', 'The famous Italian restaurant', NULL, 'B', 'Câu hỏi: "Sao bạn không tham gia bữa tối với chúng tôi vào thứ Sáu?"
A: "Một bàn cạnh cửa sổ"
B: "Tôi vừa có kế hoạch với một người bạn"
C: "Nhà hàng Ý nổi tiếng"
Giải thích: Đáp án B đúng vì người trả lời từ chối lời mời một cách lịch sự bằng cách giải thích rằng họ đã có kế hoạch khác');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5120, 226, '2025/test3/audio/test3_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6415, 5120, 15, 'Tickets for the comedy show have been selling really well.', 'In the first row of the balcony', 'We prefer not to', 'It seems we''ll make a good profit', NULL, 'C', 'Câu hỏi: "Vé cho buổi biểu diễn hài kịch đang bán rất chạy."
A: "Ở hàng đầu tiên của ban công"
B: "Chúng tôi không thích điều đó"
C: "Có vẻ chúng ta sẽ có lợi nhuận tốt"
Giải thích: Đáp án C đúng vì người trả lời đưa ra kết luận hợp lý về lợi nhuận dựa trên thông tin về doanh số bán vé tốt');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5121, 226, '2025/test3/audio/test3_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6416, 5121, 16, 'Have you found a suitable venue for our awards banquet?', 'I''m visiting some places this week', 'Congratulations on your achievement!', 'The friendly staff', NULL, 'A', 'Câu hỏi: "Bạn đã tìm được địa điểm phù hợp cho buổi tiệc trao giải của chúng ta chưa?"
A: "Tôi đang đi xem một số địa điểm tuần này"
B: "Chúc mừng thành tích của bạn!"
C: "Nhân viên thân thiện"
Giải thích: Đáp án A đúng vì người trả lời cho biết họ đang trong quá trình tìm kiếm địa điểm phù hợp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5122, 226, '2025/test3/audio/test3_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6417, 5122, 17, 'Nicholas plans to work overtime today, doesn''t he?', 'Alright, I can help you', 'Over time it might', 'Yes, that''s what he said', NULL, 'C', 'Câu hỏi: "Nicholas dự định làm thêm giờ hôm nay, phải không?"
A: "Được rồi, tôi có thể giúp bạn"
B: "Theo thời gian nó có thể"
C: "Vâng, anh ấy đã nói vậy"
Giải thích: Đáp án C đúng vì người trả lời xác nhận thông tin về kế hoạch làm thêm giờ của Nicholas');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5123, 226, '2025/test3/audio/test3_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6418, 5123, 18, 'Where can I find the lunch specials?', 'I''ll probably be late', 'They''re on the notice board', 'Until one o''clock', NULL, 'B', 'Câu hỏi: "Tôi có thể tìm thấy các món đặc biệt cho bữa trưa ở đâu?"
A: "Tôi có thể sẽ đến muộn"
B: "Chúng được dán trên bảng thông báo"
C: "Đến một giờ"
Giải thích: Đáp án B đúng vì người trả lời chỉ ra vị trí cụ thể nơi có thông tin về các món đặc biệt');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5124, 226, '2025/test3/audio/test3_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6419, 5124, 19, 'What airline will you fly to the trade fair?', 'Amy flew to her hometown', 'My travel agent''s taking care of that', 'I usually prefer a window seat', NULL, 'B', 'Câu hỏi: "Bạn sẽ bay hãng hàng không nào đến hội chợ thương mại?"
A: "Amy đã bay về quê"
B: "Đại lý du lịch của tôi đang lo việc đó"
C: "Tôi thường thích ghế cạnh cửa sổ"
Giải thích: Đáp án B đúng vì người trả lời cho biết đại lý du lịch đang sắp xếp chuyến bay cho họ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5125, 226, '2025/test3/audio/test3_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6420, 5125, 20, 'Didn''t we repair this heater last week?', 'Several complex components', 'Three or more workers', 'That was on the fifth floor', NULL, 'C', 'Câu hỏi: "Chúng ta đã không sửa máy sưởi này tuần trước sao?"
A: "Một số linh kiện phức tạp"
B: "Ba hoặc nhiều công nhân hơn"
C: "Đó là ở tầng năm"
Giải thích: Đáp án C đúng vì người trả lời làm rõ rằng máy sưởi được sửa tuần trước là ở tầng năm, không phải máy sưởi này');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5126, 226, '2025/test3/audio/test3_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6421, 5126, 21, 'When am I meeting with the bank about our loan application?', 'Apply it daily for best results', 'Those books aren''t out on loan', 'I e-mailed you the details', NULL, 'C', 'Câu hỏi: "Khi nào tôi gặp ngân hàng về đơn xin vay của chúng ta?"
A: "Áp dụng hàng ngày để có kết quả tốt nhất"
B: "Những cuốn sách đó không được cho mượn"
C: "Tôi đã gửi chi tiết qua email cho bạn"
Giải thích: Đáp án C đúng vì người trả lời cho biết họ đã gửi thông tin chi tiết về cuộc họp qua email');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5127, 226, '2025/test3/audio/test3_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6422, 5127, 22, 'I was surprised by Mr. Seger''s announcement about retiring', 'I''m feeling rather tired', 'Yes, he''s still quite young', 'Please leave them in the packaging', NULL, 'B', 'Câu hỏi: "Tôi đã ngạc nhiên về thông báo nghỉ hưu của ông Seger"
A: "Tôi cảm thấy khá mệt mỏi"
B: "Vâng, ông ấy vẫn còn khá trẻ"
C: "Vui lòng để chúng trong bao bì"
Giải thích: Đáp án B đúng vì người trả lời đồng cảm với sự ngạc nhiên và giải thích lý do - ông Seger vẫn còn khá trẻ để nghỉ hưu');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5128, 226, '2025/test3/audio/test3_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6423, 5128, 23, 'Why were extra staff called to the factory?', 'Did you see the size of the order?', 'When we need new machinery', 'Yes, a call from the client', NULL, 'A', 'Câu hỏi: "Tại sao nhân viên phụ được gọi đến nhà máy?"
A: "Bạn đã thấy quy mô đơn hàng chưa?"
B: "Khi chúng ta cần máy móc mới"
C: "Vâng, một cuộc gọi từ khách hàng"
Giải thích: Đáp án A đúng vì người trả lời ngụ ý rằng quy mô lớn của đơn hàng là lý do cần thêm nhân viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5129, 226, '2025/test3/audio/test3_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6424, 5129, 24, 'Has the theme for the photography contest been decided?', 'Yes, it''s "Natural Landscapes"', 'We make a good team', 'No, I''m not certified', NULL, 'A', 'Câu hỏi: "Chủ đề cho cuộc thi nhiếp ảnh đã được quyết định chưa?"
A: "Vâng, đó là ''Phong cảnh Thiên nhiên''"
B: "Chúng ta là một đội tốt"
C: "Không, tôi không có chứng chỉ"
Giải thích: Đáp án A đúng vì người trả lời xác nhận và cung cấp chủ đề cụ thể đã được chọn cho cuộc thi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5130, 226, '2025/test3/audio/test3_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6425, 5130, 25, 'Let''s hold the event on the patio instead of in the dining hall.', 'Through the rear entrance', 'A luncheon for marketers', 'But it''s supposed to be windy', NULL, 'C', 'Câu hỏi: "Hãy tổ chức sự kiện ở sân hiên thay vì trong phòng ăn."
A: "Qua lối vào phía sau"
B: "Một bữa trưa cho các nhà tiếp thị"
C: "Nhưng dự báo sẽ có gió"
Giải thích: Đáp án C đúng vì người trả lời nêu lên một vấn đề thời tiết hợp lý khi tổ chức sự kiện ngoài trời - gió có thể ảnh hưởng đến việc tổ chức sự kiện ở sân hiên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5131, 226, '2025/test3/audio/test3_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6426, 5131, 26, 'How long does it take to complete this survey?', 'You can skip some questions if you''re in a hurry', 'We''ll need at least thirty participants', 'With a black pen, please', NULL, 'A', 'Câu hỏi: "Mất bao lâu để hoàn thành bản khảo sát này?"
A: "Bạn có thể bỏ qua một số câu hỏi nếu đang vội"
B: "Chúng tôi cần ít nhất ba mươi người tham gia"
C: "Vui lòng dùng bút màu đen"
Giải thích: Đáp án A đúng vì người trả lời gợi ý có thể rút ngắn thời gian bằng cách bỏ qua một số câu hỏi nếu người làm khảo sát đang vội');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5132, 226, '2025/test3/audio/test3_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6427, 5132, 27, 'We should leave these boxes in the hallway.', 'There''s space in the storage closet', 'Yes, by an expert', 'Cosmetics samples, I think', NULL, 'A', 'Câu hỏi: "Chúng ta nên để những hộp này ở hành lang."
A: "Có chỗ trong tủ kho"
B: "Vâng, bởi một chuyên gia"
C: "Tôi nghĩ là các mẫu mỹ phẩm"
Giải thích: Đáp án A đúng vì người trả lời đề xuất một giải pháp tốt hơn - để các hộp trong tủ kho thay vì để ở hành lang');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5133, 226, '2025/test3/audio/test3_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6428, 5133, 28, 'We can park here overnight, can''t we?', 'The office parking area', 'I don''t want to get a fine', 'I''m free tomorrow', NULL, 'B', 'Câu hỏi: "Chúng ta có thể đậu xe ở đây qua đêm, đúng không?"
A: "Khu vực đậu xe văn phòng"
B: "Tôi không muốn bị phạt"
C: "Ngày mai tôi rảnh"
Giải thích: Đáp án B đúng vì người trả lời ngụ ý rằng việc đậu xe qua đêm ở đây có thể bị phạt, do đó không nên đậu xe');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5134, 226, '2025/test3/audio/test3_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6429, 5134, 29, 'Can employees bring their families to the picnic, or is that not allowed?', 'It doesn''t seem loud to me', 'Marigold Park is a good choice', 'We''ll have plenty of food', NULL, 'C', 'Câu hỏi: "Nhân viên có thể đem gia đình đến dã ngoại không, hay điều đó không được phép?"
A: "Tôi thấy không ồn lắm"
B: "Công viên Marigold là một lựa chọn tốt"
C: "Chúng ta sẽ có nhiều thức ăn"
Giải thích: Đáp án C đúng vì người trả lời ngụ ý rằng gia đình nhân viên được phép tham gia vì họ đã chuẩn bị đủ thức ăn cho mọi người');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5135, 226, '2025/test3/audio/test3_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6430, 5135, 30, 'Where did you live when you first moved to Boston?', 'Is it next to the side entrance?', 'The building''s not there anymore.', 'About three years ago.', NULL, 'B', 'Câu hỏi: "Bạn sống ở đâu khi mới chuyển đến Boston?"
A: "Nó có nằm cạnh lối vào bên cạnh không?"
B." Tòa nhà không còn ở đó nữa."
C. "Khoảng ba năm trước."
Giải thích: đáp án B trả lời cho câu hỏi ở đâu, A, C không phù hợp ngữ cảnh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5136, 226, '2025/test3/audio/test3_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6431, 5136, 31, 'Have you received the memo about the new layout for the Web site?', 'Yes, and I made an extra copy.', 'A top graphic designer.', 'I have a few notepads.', NULL, 'A', 'Câu hỏi: "Bạn đã nhận được bản ghi nhớ về bố cục mới cho trang web chưa?"
A. "Vâng, và tôi đã tạo thêm một bản sao."
B. "Một nhà thiết kế đồ họa hàng đầu".
C. "Tôi có một vài cuốn sổ tay."
Giải thích: Đáp án A đúng trả lời trực tiếp cho câu hỏi yes/no. B,C không phù hợp.');;

-- Data for 2025 Test3 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5137, 227, '2025/test3/audio/test3_question_32_34.mp3', NULL, 'W-Am Hi, Brandon. Thanks for coming in on your day off. Two of the staff members on this shift have called in sick, and we have a lot of dry cleaning to finish.
M-Cn No problem. The only thing is that I forgot to bring my name tag with me.
W-Am That''s fine. You''ll mostly be working in the back anyway.
M-Cn All right. Is there anything in particular that you want me to start on first?
W-Am Yes-the pillows from Jenkins Hotel. It''s essential that we do a good job on that order, as they''re considering giving us a permanent contract.', 'W-Am Chào Brandon. Cảm ơn anh đã đến làm vào ngày nghỉ của mình. Hai nhân viên trong ca này đã gọi báo ốm, và chúng ta có nhiều đồ giặt khô cần hoàn thành.
M-Cn Không sao. Chỉ là tôi quên mang thẻ tên của mình theo.
W-Am Không sao đâu. Dù sao anh cũng sẽ làm việc ở phía sau.
M-Cn Được rồi. Có việc gì cụ thể chị muốn tôi bắt đầu trước không?
W-Am Có - những chiếc gối từ Khách sạn Jenkins. Quan trọng là chúng ta phải làm tốt đơn hàng đó, vì họ đang cân nhắc ký hợp đồng lâu dài với chúng ta.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6432, 5137, 32, 'Where do the speakers most likely work?', 'At a manufacturing plant', 'At a department store', 'At a restaurant', 'At a dry cleaner', 'D', 'Question: Where do the speakers most likely work? (Những người nói chuyện nhiều khả năng làm việc ở đâu?)
A: At a manufacturing plant (Tại một nhà máy sản xuất)
B: At a department store (Tại một cửa hàng bách hóa)
C: At a restaurant (Tại một nhà hàng)
D: At a dry cleaner (Tại một tiệm giặt khô)

Giải thích: Đáp án D là chính xác vì trong đoạn hội thoại, họ nói về việc có nhiều đồ giặt khô cần hoàn thành (a lot of dry cleaning to finish) và về đơn đặt hàng giặt gối từ khách sạn Jenkins.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5138, 227, '2025/test3/audio/test3_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6433, 5138, 33, 'What does the man say he forgot?', 'A handout', 'Some safety equipment', 'Some identification', 'A key card', 'C', 'Question: What does the man say he forgot? (Người đàn ông nói anh ấy đã quên gì?)
A: A handout (Một tài liệu phát tay)
B: Some safety equipment (Một số thiết bị an toàn)
C: Some identification (Một số giấy tờ nhận dạng)
D: A key card (Thẻ chìa khóa)

Giải thích: Đáp án C là chính xác vì người đàn ông nói rằng anh ấy đã quên mang theo thẻ tên của mình (I forgot to bring my name tag with me).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5139, 227, '2025/test3/audio/test3_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6434, 5139, 34, 'According to the woman, why is an order important?', 'It could result in long-term business', 'It is for a local charity event', 'It is for a renowned company', 'It will be featured in a magazine', 'A', 'Question: According to the woman, why is an order important? (Theo người phụ nữ, tại sao một đơn hàng lại quan trọng?)
A: It could result in long-term business (Nó có thể dẫn đến hợp đồng kinh doanh lâu dài)
B: It is for a local charity event (Nó dành cho một sự kiện từ thiện địa phương)
C: It is for a renowned company (Nó dành cho một công ty nổi tiếng)
D: It will be featured in a magazine (Nó sẽ được giới thiệu trên tạp chí)

Giải thích: Đáp án A là chính xác vì người phụ nữ nói rằng đơn hàng đó quan trọng vì khách sạn Jenkins đang cân nhắc ký hợp đồng lâu dài với họ (they''re considering giving us a permanent contract).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5140, 227, '2025/test3/audio/test3_question_35_37.mp3', NULL, 'M-Cn Danielle, I had a chance to look over your design for the promotional flyers we''re passing out at next week''s festival. They look great. But I saw the price estimate you got from the print shop. It''s a bit high, isn''t it?
w-Br Well, I can ask them for a discount. It''s quite a large order, so I''m sure there''s room to negotiate.
M-Cn That would be great, thanks. Oh, and I liked the photos that you chose, but some of them are outdated. After lunch, I''ll send you the ones from our dance studio''s show last week. You can use a couple of those instead.', 'M-Cn Danielle, tôi đã có cơ hội xem qua thiết kế tờ rơi quảng cáo mà chúng ta sẽ phát tại lễ hội tuần tới của bạn. Chúng trông rất tốt. Nhưng tôi đã thấy báo giá bạn nhận được từ cửa hàng in. Nó hơi cao, phải không?
W-Br À, tôi có thể yêu cầu họ giảm giá. Đây là một đơn hàng khá lớn, nên tôi chắc có thể thương lượng.
M-Cn Tuyệt vời, cảm ơn. À, và tôi thích những bức ảnh bạn đã chọn, nhưng một số trong đó đã cũ. Sau bữa trưa, tôi sẽ gửi cho bạn những bức từ buổi biểu diễn của studio khiêu vũ tuần trước. Bạn có thể sử dụng một vài bức đó thay thế.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6435, 5140, 35, 'What is the conversation mainly about?', 'A training session', 'An event registration', 'Some promotional materials', 'Some festival booths', 'C', 'Question: What is the conversation mainly about? (Cuộc trò chuyện chủ yếu nói về điều gì?)
A: A training session (Một buổi đào tạo)
B: An event registration (Một đăng ký sự kiện)
C: Some promotional materials (Một số tài liệu quảng cáo)
D: Some festival booths (Một số gian hàng lễ hội)

Giải thích: Đáp án C là chính xác vì cuộc trò chuyện xoay quanh việc thiết kế tờ rơi quảng cáo (design for the promotional flyers), chi phí in ấn và việc cập nhật hình ảnh cho tài liệu quảng cáo này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5141, 227, '2025/test3/audio/test3_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6436, 5141, 36, 'What does the woman offer to do?', 'Check a Web site', 'Request a price reduction', 'Proofread a document', 'Research other businesses', 'B', 'Question: What does the woman offer to do? (Người phụ nữ đề nghị làm gì?)
A: Check a Web site (Kiểm tra một trang web)
B: Request a price reduction (Yêu cầu giảm giá)
C: Proofread a document (Đọc soát lỗi một tài liệu)
D: Research other businesses (Nghiên cứu các doanh nghiệp khác)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói rằng cô ấy có thể yêu cầu họ giảm giá (I can ask them for a discount) vì đây là đơn hàng lớn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5142, 227, '2025/test3/audio/test3_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6437, 5142, 37, 'What will the man send this afternoon?', 'Schedules for upcoming shows', 'Images of a recent event', 'A sample contract', 'A mailing address', 'B', 'Question: What will the man send this afternoon? (Người đàn ông sẽ gửi gì vào buổi chiều?)
A: Schedules for upcoming shows (Lịch trình cho các buổi biểu diễn sắp tới)
B: Images of a recent event (Hình ảnh của một sự kiện gần đây)
C: A sample contract (Một mẫu hợp đồng)
D: A mailing address (Một địa chỉ gửi thư)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng sau bữa trưa anh ấy sẽ gửi những bức ảnh từ buổi biểu diễn của studio khiêu vũ tuần trước (After lunch, I''ll send you the ones from our dance studio''s show last week).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5143, 227, '2025/test3/audio/test3_question_38_40.mp3', NULL, 'W-Br Good morning. This is Michelle from Reynolds Appliances. I just wanted to remind you that your washing machine will be delivered today between one and two o''clock.
M-Au Thank you. I''ll be here. Actually, I originally requested delivery only, but I''m wondering if I can have the machine installed as well.
W-Br Let me see ... Yes, there''s time in the schedule for that. I''ll let our crew know.
M-Au Thank you. And please tell them they should take Lang Avenue to get here, as Patterson Street is currently closed for repairs.', 'W-Br Chào buổi sáng. Đây là Michelle từ Reynolds Appliances. Tôi chỉ muốn nhắc nhở rằng máy giặt của anh sẽ được giao hôm nay từ một đến hai giờ.
M-Au Cảm ơn. Tôi sẽ có mặt ở đây. Thực ra, ban đầu tôi chỉ yêu cầu giao hàng, nhưng tôi đang tự hỏi liệu tôi có thể được lắp đặt máy luôn không.
W-Br Để tôi xem... Vâng, lịch trình còn thời gian cho việc đó. Tôi sẽ thông báo cho đội của chúng tôi.
M-Au Cảm ơn. Và làm ơn nói với họ nên đi theo Đại lộ Lang để đến đây, vì Đường Patterson hiện đang đóng cửa để sửa chữa.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6438, 5143, 38, 'What kind of business does the woman most likely work for?', 'A construction firm', 'A dental clinic', 'An appliance store', 'A post office', 'C', 'Question: What kind of business does the woman most likely work for? (Người phụ nữ nhiều khả năng làm việc cho loại doanh nghiệp nào?)
A: A construction firm (Một công ty xây dựng)
B: A dental clinic (Một phòng khám nha khoa)
C: An appliance store (Một cửa hàng thiết bị)
D: A post office (Một bưu điện)

Giải thích: Đáp án C là chính xác vì người phụ nữ giới thiệu cô ấy là Michelle từ Reynolds Appliances và đang nói về việc giao máy giặt, cho thấy cô ấy làm việc tại một cửa hàng thiết bị.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5144, 227, '2025/test3/audio/test3_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6439, 5144, 39, 'What does the man say he wants to do?', 'Add a service request', 'Reschedule a visit', 'Receive an invoice', 'Make a complaint', 'A', 'Question: What does the man say he wants to do? (Người đàn ông nói anh ấy muốn làm gì?)
A: Add a service request (Thêm một yêu cầu dịch vụ)
B: Reschedule a visit (Đổi lịch một cuộc hẹn)
C: Receive an invoice (Nhận một hóa đơn)
D: Make a complaint (Đưa ra một khiếu nại)

Giải thích: Đáp án A là chính xác vì người đàn ông nói rằng ban đầu anh ấy chỉ yêu cầu giao hàng, nhưng giờ muốn thêm dịch vụ lắp đặt máy (I originally requested delivery only, but I''m wondering if I can have the machine installed as well).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5145, 227, '2025/test3/audio/test3_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6440, 5145, 40, 'What does the man offer advice about?', 'Whom to contact', 'When to arrive', 'What samples to bring', 'Which road to take', 'D', 'Question: What does the man offer advice about? (Người đàn ông đưa ra lời khuyên về điều gì?)
A: Whom to contact (Nên liên hệ với ai)
B: When to arrive (Khi nào nên đến)
C: What samples to bring (Nên mang theo mẫu gì)
D: Which road to take (Nên đi đường nào)

Giải thích: Đáp án D là chính xác vì người đàn ông khuyên đội giao hàng nên đi theo Đại lộ Lang vì Đường Patterson đang đóng cửa để sửa chữa (they should take Lang Avenue to get here, as Patterson Street is currently closed for repairs).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5146, 227, '2025/test3/audio/test3_question_41_43.mp3', NULL, 'w-Am Walter, could you update me on the progress of our TV commercial for Marquez Athletics? The last news I heard was that you had finished editing it.
M-Cn We just held a feedback session with some customers, and they loved it. They thought the animated sequence was really impressive. They said the storyline was memorable as well.
w-Am I''m glad to hear that! It''s going to be the main part of the promotional campaign, so it''s important to get it right. So, how soon will it air?
M-Cn It''ll most likely get final approval at the management meeting, which is next Tuesday.', 'W-Am Walter, anh có thể cập nhật cho tôi về tiến độ quảng cáo truyền hình cho Marquez Athletics không? Tin tức cuối cùng tôi nghe được là anh đã hoàn thành việc biên tập nó.
M-Cn Chúng tôi vừa tổ chức một buổi lấy ý kiến phản hồi với một số khách hàng, và họ rất thích nó. Họ nghĩ phần hoạt hình thực sự ấn tượng. Họ còn nói cốt truyện cũng rất đáng nhớ.
W-Am Tôi rất vui khi nghe điều đó! Nó sẽ là phần chính của chiến dịch quảng cáo, nên việc làm đúng rất quan trọng. Vậy, bao giờ nó sẽ được phát sóng?
M-Cn Nó có thể sẽ được phê duyệt cuối cùng tại cuộc họp ban quản lý vào thứ Ba tới.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6441, 5146, 41, 'What is mainly being discussed?', 'A fund-raising campaign', 'A company policy', 'A workshop', 'An advertisement', 'D', 'Question: What is mainly being discussed? (Điều gì đang được thảo luận chủ yếu?)
A: A fund-raising campaign (Một chiến dịch gây quỹ)
B: A company policy (Một chính sách công ty)
C: A workshop (Một hội thảo)
D: An advertisement (Một quảng cáo)

Giải thích: Đáp án D là chính xác vì cuộc trò chuyện xoay quanh quảng cáo truyền hình (TV commercial) cho Marquez Athletics, phản hồi của khách hàng về nó và kế hoạch phát sóng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5147, 227, '2025/test3/audio/test3_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6442, 5147, 42, 'What good news does the man share?', 'Some customers were impressed', 'A task was completed early', 'Product sales have increased', 'The company received a grant', 'A', 'Question: What good news does the man share? (Người đàn ông chia sẻ tin tốt gì?)
A: Some customers were impressed (Một số khách hàng đã ấn tượng)
B: A task was completed early (Một nhiệm vụ đã hoàn thành sớm)
C: Product sales have increased (Doanh số sản phẩm đã tăng)
D: The company received a grant (Công ty đã nhận được tài trợ)

Giải thích: Đáp án A là chính xác vì người đàn ông chia sẻ rằng trong buổi lấy ý kiến phản hồi, khách hàng rất thích quảng cáo, đặc biệt ấn tượng với phần hoạt hình và cốt truyện (they loved it. They thought the animated sequence was really impressive. They said the storyline was memorable).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5148, 227, '2025/test3/audio/test3_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6443, 5148, 43, 'What will happen next Tuesday?', 'Some investors will visit', 'Some managers will meet', 'A winner will be announced', 'A business trip will begin', 'B', 'Question: What will happen next Tuesday? (Điều gì sẽ xảy ra vào thứ Ba tới?)
A: Some investors will visit (Một số nhà đầu tư sẽ đến thăm)
B: Some managers will meet (Một số nhà quản lý sẽ họp)
C: A winner will be announced (Một người chiến thắng sẽ được công bố)
D: A business trip will begin (Một chuyến công tác sẽ bắt đầu)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng quảng cáo sẽ được phê duyệt cuối cùng tại cuộc họp ban quản lý vào thứ Ba tới (get final approval at the management meeting, which is next Tuesday).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5149, 227, '2025/test3/audio/test3_question_44_46.mp3', NULL, 'M-Au Hi, Shawn. Hey, Debbie. I''m looking for Pamela, but I haven''t seen her in the office yet today. Do you know where she is?
w-am I think she had planned to take today off. Would you like me to open up the staff calendar and make sure?
M-Au Thanks, but I can do that. I was just asking because I know that Pamela drafts most of our press releases, and I need one for later today.
W-Am You should have Shawn help you with that. He has a degree in journalism.
M-Cn That''s right, I do. And I''ve got some time now if you want to talk about what you need.', 'M-Au Chào Shawn. Này, Debbie. Tôi đang tìm Pamela, nhưng hôm nay tôi chưa thấy cô ấy trong văn phòng. Các bạn có biết cô ấy ở đâu không?
W-Am Tôi nghĩ cô ấy đã lên kế hoạch nghỉ hôm nay. Anh có muốn tôi mở lịch nhân viên ra và kiểm tra không?
M-Au Cảm ơn, nhưng tôi có thể làm điều đó. Tôi chỉ hỏi vì tôi biết Pamela soạn thảo hầu hết các thông cáo báo chí của chúng ta, và tôi cần một cái cho chiều nay.
W-Am Anh nên nhờ Shawn giúp đỡ việc đó. Anh ấy có bằng báo chí.
M-Cn Đúng vậy. Và bây giờ tôi có thời gian nếu anh muốn nói về những gì anh cần.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6444, 5149, 44, 'What does the woman offer to do?', 'Wait for Pamela', 'Contact a coworker', 'Check a schedule', 'Proofread a document', 'C', 'Question: What does the woman offer to do? (Người phụ nữ đề nghị làm gì?)
A: Wait for Pamela (Đợi Pamela)
B: Contact a coworker (Liên hệ với đồng nghiệp)
C: Check a schedule (Kiểm tra lịch)
D: Proofread a document (Đọc soát lỗi tài liệu)

Giải thích: Đáp án C là chính xác vì người phụ nữ đề nghị mở lịch nhân viên để kiểm tra (Would you like me to open up the staff calendar and make sure?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5150, 227, '2025/test3/audio/test3_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6445, 5150, 45, 'What does Pamela usually do?', 'Write media announcements', 'Conduct performance evaluations', 'Make travel arrangements', 'Introduce new clients to the business', 'A', 'Question: What does Pamela usually do? (Pamela thường làm gì?)
A: Write media announcements (Viết thông báo truyền thông)
B: Conduct performance evaluations (Tiến hành đánh giá hiệu suất)
C: Make travel arrangements (Sắp xếp chuyến đi)
D: Introduce new clients to the business (Giới thiệu khách hàng mới với doanh nghiệp)

Giải thích: Đáp án A là chính xác vì trong đoạn hội thoại có đề cập rằng Pamela soạn thảo hầu hết các thông cáo báo chí của công ty (Pamela drafts most of our press releases).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5151, 227, '2025/test3/audio/test3_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6446, 5151, 46, 'According to the woman, why should Shawn help with a task?', 'He used to perform it regularly', 'He wants to learn new skills', 'He has a relevant degree', 'He has the lightest workload', 'C', 'Question: According to the woman, why should Shawn help with a task? (Theo người phụ nữ, tại sao Shawn nên giúp với một nhiệm vụ?)
A: He used to perform it regularly (Anh ấy thường xuyên thực hiện nó trước đây)
B: He wants to learn new skills (Anh ấy muốn học các kỹ năng mới)
C: He has a relevant degree (Anh ấy có bằng cấp liên quan)
D: He has the lightest workload (Anh ấy có khối lượng công việc nhẹ nhất)

Giải thích: Đáp án C là chính xác vì người phụ nữ gợi ý Shawn giúp đỡ vì anh ấy có bằng báo chí (He has a degree in journalism).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5152, 227, '2025/test3/audio/test3_question_47_49.mp3', NULL, 'w-Br Good morning, Mr. Jeffreys. I''m calling about the plans you sent for the B70 running shoes. I can confirm that our manufacturing plant can produce the goods for you, starting from next week.
M-cn I''m glad to hear that. I know there was an option to send the shoes overseas, to our warehouse in Singapore. How much would the delivery costs be?
w-Br It depends on the size of the order. I suggest taking advantage of our generous bulk discounts.', 'W-Br Chào buổi sáng, ông Jeffreys. Tôi gọi về kế hoạch ông đã gửi cho giày chạy B70. Tôi có thể xác nhận rằng nhà máy sản xuất của chúng tôi có thể sản xuất hàng hóa cho ông, bắt đầu từ tuần tới.
M-Cn Tôi rất vui khi nghe điều đó. Tôi biết có một lựa chọn gửi giày ra nước ngoài, đến kho của chúng tôi ở Singapore. Chi phí vận chuyển sẽ là bao nhiêu?
W-Br Nó phụ thuộc vào quy mô đơn hàng. Tôi đề xuất tận dụng các khoản giảm giá số lượng lớn hào phóng của chúng tôi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6447, 5152, 47, 'Where most likely does the woman work?', 'At a factory', 'At a department store', 'At a repair shop', 'At a consulting firm', 'A', 'Question: Where most likely does the woman work? (Người phụ nữ nhiều khả năng làm việc ở đâu?)
A: At a factory (Tại một nhà máy)
B: At a department store (Tại một cửa hàng bách hóa)
C: At a repair shop (Tại một cửa hàng sửa chữa)
D: At a consulting firm (Tại một công ty tư vấn)

Giải thích: Đáp án A là chính xác vì người phụ nữ nói về nhà máy sản xuất của họ có thể sản xuất giày cho khách hàng (our manufacturing plant can produce the goods for you).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5153, 227, '2025/test3/audio/test3_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6448, 5153, 48, 'What does the man inquire about?', 'A contract period', 'A color option', 'A discount offer', 'A shipping fee', 'D', 'Question: What does the man inquire about? (Người đàn ông hỏi về điều gì?)
A: A contract period (Thời hạn hợp đồng)
B: A color option (Lựa chọn màu sắc)
C: A discount offer (Đề nghị giảm giá)
D: A shipping fee (Phí vận chuyển)

Giải thích: Đáp án D là chính xác vì người đàn ông hỏi về chi phí vận chuyển giày đến kho ở Singapore (How much would the delivery costs be?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5154, 227, '2025/test3/audio/test3_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6449, 5154, 49, 'What does the woman recommend doing?', 'Making an in-person visit', 'Speaking to a supervisor', 'Changing a design', 'Placing a large order', 'D', 'Question: What does the woman recommend doing? (Người phụ nữ đề xuất làm gì?)
A: Making an in-person visit (Thăm trực tiếp)
B: Speaking to a supervisor (Nói chuyện với người giám sát)
C: Changing a design (Thay đổi thiết kế)
D: Placing a large order (Đặt đơn hàng lớn)

Giải thích: Đáp án D là chính xác vì người phụ nữ đề xuất tận dụng các khoản giảm giá cho đơn hàng số lượng lớn (I suggest taking advantage of our generous bulk discounts), ngụ ý rằng khách hàng nên đặt một đơn hàng lớn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5155, 227, '2025/test3/audio/test3_question_50_52.mp3', NULL, 'M-au Alright, now that you''re both here, let me make some introductions. This is Bethany Reeves, our new head librarian, and Clara Jackson, our new researcher.
W-Br Nice to meet you.
W-Am You, too. I''m excited that we''ll be working together.
M-Au Now, you''ll spend the morning together because there are lots of forms from the human resources department that you need to fill out. Then I''ll work with Bethany on plans for the summer reading program.
W-Br That sounds great. I ran the same kind of program at the Farmington branch, so I have some ideas to share.
w-Am Oh, how long were you at the Farmington branch, Bethany?
W-Br Lets see... Nearly eight years.', 'M-au Được rồi, giờ cả hai đều ở đây, để tôi giới thiệu. Đây là Bethany Reeves, trưởng thư viện mới của chúng ta, và Clara Jackson, nhà nghiên cứu mới của chúng ta.
W-Br Rất vui được gặp bạn.
W-Am Tôi cũng vậy. Tôi rất phấn khích vì chúng ta sẽ làm việc cùng nhau.
M-Au Giờ, các bạn sẽ dành buổi sáng cùng nhau vì có nhiều mẫu đơn từ phòng nhân sự mà các bạn cần điền. Sau đó tôi sẽ làm việc với Bethany về kế hoạch cho chương trình đọc sách mùa hè.
W-Br Nghe hay đấy. Tôi đã từng phụ trách cùng loại chương trình ở chi nhánh Farmington, nên tôi có một số ý tưởng để chia sẻ.
W-Am Ồ, bạn đã làm ở chi nhánh Farmington bao lâu rồi, Bethany?
W-Br Để xem... Gần tám năm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6450, 5155, 50, 'Where most likely are the speakers?', 'At a bookstore', 'At a warehouse', 'At a medical clinic', 'At a library', 'D', 'Question: Where most likely are the speakers? (Những người nói chuyện nhiều khả năng đang ở đâu?)
A: At a bookstore (Tại hiệu sách)
B: At a warehouse (Tại nhà kho)
C: At a medical clinic (Tại phòng khám)
D: At a library (Tại thư viện)

Giải thích: Đáp án D là chính xác vì trong đoạn hội thoại giới thiệu Bethany Reeves là trưởng thư viện mới (new head librarian), và họ thảo luận về chương trình đọc sách mùa hè (summer reading program) cũng như chi nhánh Farmington, cho thấy đây là một thư viện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5156, 227, '2025/test3/audio/test3_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6451, 5156, 51, 'According to the man, what will the women do in the morning?', 'Take a building tour', 'Complete some paperwork', 'Observe other colleagues', 'Read a user manual', 'B', 'Question: According to the man, what will the women do in the morning? (Theo người đàn ông, những người phụ nữ sẽ làm gì vào buổi sáng?)
A: Take a building tour (Tham quan tòa nhà)
B: Complete some paperwork (Hoàn thành một số giấy tờ)
C: Observe other colleagues (Quan sát đồng nghiệp khác)
D: Read a user manual (Đọc hướng dẫn sử dụng)

Giải thích: Đáp án B là chính xác vì người đàn ông nói rằng họ sẽ dành buổi sáng cùng nhau vì có nhiều mẫu đơn từ phòng nhân sự cần điền (there are lots of forms from the human resources department that you need to fill out).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5157, 227, '2025/test3/audio/test3_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6452, 5157, 52, 'What does Clara ask Bethany about?', 'The usefulness of some training', 'The number of participants in a program', 'The duration of her previous job', 'The reason she transferred branches', 'C', 'Question: What does Clara ask Bethany about? (Clara hỏi Bethany về điều gì?)
A: The usefulness of some training (Sự hữu ích của một số khóa đào tạo)
B: The number of participants in a program (Số lượng người tham gia trong một chương trình)
C: The duration of her previous job (Thời gian làm việc ở vị trí trước)
D: The reason she transferred branches (Lý do chuyển chi nhánh)

Giải thích: Đáp án C là chính xác vì Clara (W-Am) hỏi Bethany đã làm việc ở chi nhánh Farmington bao lâu (how long were you at the Farmington branch), và Bethany trả lời là gần tám năm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5158, 227, '2025/test3/audio/test3_question_53_55.mp3', NULL, 'M-Au Hi, I''m calling because I received my bill for September, and it was forty dollars more than I expected. I''m Gary Russo; account number 95039.
W-Am Let me check your account, Mr. Russo. Hmm it looks like you got some merchandise from us in September?
M-Au Yes, I upgraded to a new smartphone model. But I thought that was free for renewing my contract.
w-Am I''m afraid not. The cost is divided over the length of your contract. That''s why we advise customers to thoroughly read the contract so they understand the terms.
M-Au Hmm, I guess I''ll have to have another look at it.', 'M-Au Xin chào, tôi gọi vì tôi nhận được hóa đơn tháng 9 của mình, và nó cao hơn 40 đô la so với dự kiến. Tôi là Gary Russo; số tài khoản 95039.
W-Am Để tôi kiểm tra tài khoản của ông, ông Russo. Hmm có vẻ như ông đã mua một số hàng hóa từ chúng tôi trong tháng 9?
M-Au Vâng, tôi đã nâng cấp lên một mẫu điện thoại thông minh mới. Nhưng tôi tưởng việc đó miễn phí khi gia hạn hợp đồng.
W-Am Tôi e là không. Chi phí được chia nhỏ theo thời hạn hợp đồng của ông. Đó là lý do tại sao chúng tôi khuyên khách hàng đọc kỹ hợp đồng để hiểu rõ các điều khoản.
M-Au Hmm, tôi đoán tôi sẽ phải xem lại nó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6453, 5158, 53, 'What is the purpose of the call?', 'To change a phone number', 'To report a potential error', 'To pay an outstanding bill', 'To update an address', 'B', 'Question: What is the purpose of the call? (Mục đích của cuộc gọi là gì?)
A: To change a phone number (Để thay đổi số điện thoại)
B: To report a potential error (Để báo cáo một lỗi tiềm ẩn)
C: To pay an outstanding bill (Để thanh toán hóa đơn còn nợ)
D: To update an address (Để cập nhật địa chỉ)

Giải thích: Đáp án B là chính xác vì người đàn ông gọi điện để báo rằng hóa đơn tháng 9 cao hơn 40 đô la so với dự kiến (it was forty dollars more than I expected), ngụ ý rằng anh ấy nghĩ có lỗi trong hóa đơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5159, 227, '2025/test3/audio/test3_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6454, 5159, 54, 'What did the man do in September?', 'He took a trip overseas', 'He extended a warranty', 'He upgraded his phone', 'He downloaded a lot of files', 'C', 'Question: What did the man do in September? (Người đàn ông đã làm gì vào tháng 9?)
A: He took a trip overseas (Anh ấy đi nước ngoài)
B: He extended a warranty (Anh ấy gia hạn bảo hành)
C: He upgraded his phone (Anh ấy nâng cấp điện thoại)
D: He downloaded a lot of files (Anh ấy tải nhiều tập tin)

Giải thích: Đáp án C là chính xác vì người đàn ông nói rằng anh ấy đã nâng cấp lên một mẫu điện thoại thông minh mới (I upgraded to a new smartphone model).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5160, 227, '2025/test3/audio/test3_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6455, 5160, 55, 'According to the woman, what was the man advised to do?', 'Make a copy of a receipt', 'Keep a product''s packaging', 'Speak to a manager', 'Read an agreement carefully', 'D', 'Question: According to the woman, what was the man advised to do? (Theo người phụ nữ, người đàn ông đã được khuyên làm gì?)
A: Make a copy of a receipt (Sao chép một biên lai)
B: Keep a product''s packaging (Giữ bao bì sản phẩm)
C: Speak to a manager (Nói chuyện với người quản lý)
D: Read an agreement carefully (Đọc kỹ thỏa thuận)

Giải thích: Đáp án D là chính xác vì người phụ nữ nói rằng họ khuyên khách hàng đọc kỹ hợp đồng để hiểu rõ các điều khoản (we advise customers to thoroughly read the contract so they understand the terms).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5161, 227, '2025/test3/audio/test3_question_56_58.mp3', NULL, 'M-cn Hey, Annie. You opened your hair salon last week, right? How''s it going?
W-Br The first week has been stressful, but it''s exciting to finally achieve my dream. I haven''t had any customers review the salon yet, but I''m hoping to get some positive reviews soon.
M-cn I''m sure you will. You''re very talented.
w-Br Thank you. It''s a highly competitive industry, but I think my styles appeal to young professionals.
M-Cn I actually work with quite a few junior colleagues. I can tell them about your salon, if you want.
w-Br Oh, really? Actually... I have a stack of business cards.
M-cn l''d be happy to pass them out.', 'M-cn Này, Annie. Chị mở tiệm làm tóc tuần trước, đúng không? Mọi việc thế nào rồi?
W-Br Tuần đầu tiên khá căng thẳng, nhưng thật thú vị khi cuối cùng cũng đạt được ước mơ của mình. Tôi chưa có khách hàng nào đánh giá tiệm cả, nhưng tôi hy vọng sẽ sớm nhận được một số đánh giá tích cực.
M-cn Tôi chắc chắn là sẽ có thôi. Chị rất tài năng.
W-Br Cảm ơn anh. Đây là một ngành có tính cạnh tranh cao, nhưng tôi nghĩ phong cách của tôi sẽ hấp dẫn các chuyên gia trẻ.
M-Cn Tôi thực sự làm việc với khá nhiều đồng nghiệp trẻ. Tôi có thể nói với họ về tiệm của chị, nếu chị muốn.
W-Br Ồ, thật sao? Thực ra... Tôi có một xấp danh thiếp.
M-cn Tôi rất vui lòng phát chúng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6456, 5161, 56, 'What did the woman do last week?', 'She started her own business', 'She got a book published', 'She relocated to a new city', 'She was featured in an article', 'A', 'Question: What did the woman do last week? (Người phụ nữ đã làm gì tuần trước?)
A: She started her own business (Cô ấy bắt đầu kinh doanh riêng)
B: She got a book published (Cô ấy xuất bản một cuốn sách)
C: She relocated to a new city (Cô ấy chuyển đến một thành phố mới)
D: She was featured in an article (Cô ấy được giới thiệu trong một bài báo)

Giải thích: Đáp án A là chính xác vì ngay đầu đoạn hội thoại đề cập đến việc người phụ nữ đã mở tiệm làm tóc của mình tuần trước (You opened your hair salon last week).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5162, 227, '2025/test3/audio/test3_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6457, 5162, 57, 'What does the woman say she hopes to receive?', 'Some price estimates', 'Some favorable reviews', 'A local award', 'A bank loan', 'B', 'Question: What does the woman say she hopes to receive? (Người phụ nữ nói cô ấy hy vọng nhận được gì?)
A: Some price estimates (Một số báo giá)
B: Some favorable reviews (Một số đánh giá tích cực)
C: A local award (Một giải thưởng địa phương)
D: A bank loan (Một khoản vay ngân hàng)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói rằng cô ấy hy vọng sẽ sớm nhận được một số đánh giá tích cực (I''m hoping to get some positive reviews soon).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5163, 227, '2025/test3/audio/test3_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6458, 5163, 58, 'Why does the woman say, ''I have a stack of business cards''?', 'To ask for a favor', 'To cancel an order', 'To express concern', 'To correct an error', 'A', 'Question: Why does the woman say, ''I have a stack of business cards''? (Tại sao người phụ nữ nói ''Tôi có một xấp danh thiếp''?)
A: To ask for a favor (Để nhờ một việc)
B: To cancel an order (Để hủy một đơn hàng)
C: To express concern (Để bày tỏ lo lắng)
D: To correct an error (Để sửa một lỗi)

Giải thích: Đáp án A là chính xác vì người phụ nữ nói điều này sau khi người đàn ông đề nghị giới thiệu tiệm của cô ấy với đồng nghiệp trẻ, ngụ ý rằng cô ấy muốn nhờ anh ấy phát danh thiếp cho họ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5164, 227, '2025/test3/audio/test3_question_59_61.mp3', NULL, 'M-Au Hi, Ji-Min. I heard that you''ll be representing our company at the Automotive Trade Show this year.
w-Am Yes, that''s right! In fact, I''m trying to sign up on the Web site right now. But I''m having a little trouble...
M-Au Well, I did it last year. What''s the problem?
W-Am There are more participation options than I expected.
M-Au Well, we''ll be exhibiting, so scroll down to that section. OK, now you need to choose how large our company''s booth will be. That should be our manager''s decision. Did she give you that information already?
W-Am No I''ll go and ask her now. Thanks, Ravi!', 'M-Au Chào Ji-Min. Tôi nghe nói bạn sẽ đại diện công ty chúng ta tại Triển lãm Ô tô năm nay.
W-Am Vâng, đúng vậy! Thực tế, tôi đang cố gắng đăng ký trên trang web ngay bây giờ. Nhưng tôi đang gặp một chút rắc rối...
M-Au À, tôi đã làm điều đó năm ngoái. Vấn đề là gì?
W-Am Có nhiều lựa chọn tham gia hơn tôi mong đợi.
M-Au À, chúng ta sẽ trưng bày, vậy hãy cuộn xuống phần đó. OK, bây giờ bạn cần chọn kích thước gian hàng của công ty chúng ta. Đó nên là quyết định của người quản lý. Cô ấy đã cung cấp cho bạn thông tin đó chưa?
W-Am Chưa, tôi sẽ đi hỏi cô ấy ngay bây giờ. Cảm ơn Ravi!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6459, 5164, 59, 'What are the speakers discussing?', 'Submitting an annual report', 'Recruiting staff for a project', 'Taking an overseas business trip', 'Registering for an industry event', 'D', 'Question: What are the speakers discussing? (Những người nói chuyện đang thảo luận về điều gì?)
A: Submitting an annual report (Nộp báo cáo thường niên)
B: Recruiting staff for a project (Tuyển nhân viên cho một dự án)
C: Taking an overseas business trip (Thực hiện chuyến công tác nước ngoài)
D: Registering for an industry event (Đăng ký cho một sự kiện ngành)

Giải thích: Đáp án D là chính xác vì họ đang thảo luận về việc đăng ký tham gia Triển lãm Ô tô (Automotive Trade Show), và người phụ nữ đang cố gắng đăng ký trên trang web.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5165, 227, '2025/test3/audio/test3_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6460, 5165, 60, 'What does the man imply when he says, ''I did it last year''?', 'He knows some personnel well', 'An experience was valuable for his career', 'He can provide advice on a process', 'A responsibility should be given to someone else', 'C', 'Question: What does the man imply when he says, ''I did it last year''? (Người đàn ông ngụ ý gì khi nói ''Tôi đã làm điều đó năm ngoái''?)
A: He knows some personnel well (Anh ấy biết rõ một số nhân viên)
B: An experience was valuable for his career (Một kinh nghiệm đã có giá trị cho sự nghiệp của anh ấy)
C: He can provide advice on a process (Anh ấy có thể cung cấp lời khuyên về một quy trình)
D: A responsibility should be given to someone else (Một trách nhiệm nên được giao cho người khác)

Giải thích: Đáp án C là chính xác vì khi nói ''I did it last year'', người đàn ông đang ngụ ý rằng anh ấy có kinh nghiệm và có thể giúp hướng dẫn quy trình đăng ký, điều này được chứng minh qua việc anh ấy sau đó đã hướng dẫn người phụ nữ cách điền form.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5166, 227, '2025/test3/audio/test3_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6461, 5166, 61, 'What information will the woman ask a manager for?', 'A sales goal', 'A final budget', 'A preferred size', 'A departure time', 'C', 'Question: What information will the woman ask a manager for? (Người phụ nữ sẽ hỏi người quản lý thông tin gì?)
A: A sales goal (Mục tiêu bán hàng)
B: A final budget (Ngân sách cuối cùng)
C: A preferred size (Kích thước ưa thích)
D: A departure time (Thời gian khởi hành)

Giải thích: Đáp án C là chính xác vì người phụ nữ cần đi hỏi người quản lý về kích thước gian hàng của công ty (how large our company''s booth will be) vì đây là quyết định của người quản lý.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5167, 227, '2025/test3/audio/test3_question_62_64.mp3', '2025/test3/image/test3-p3-image-62.jpg', 'W-Br Thanks for helping me to plan the recruiting session for finding new software developers. I think we''re going to have a good turnout.
M-Cn I hope so. I''m going to order refreshments for fifty people. Does that sound about right?
w-Br Yes, but did you read the e-mail about caterers? We can only use ones that have been pre-approved.
M-cn Oh, I must have missed that. I''ll check it out, but while you''re here, why don''t we rehearse the presentation we''re giving at the event? That way, we can make sure it goes smoothly.', 'W-Br Cảm ơn anh đã giúp tôi lên kế hoạch cho buổi tuyển dụng để tìm các nhà phát triển phần mềm mới. Tôi nghĩ chúng ta sẽ có một số lượng người tham dự tốt.
M-Cn Tôi cũng hy vọng vậy. Tôi sẽ đặt đồ ăn nhẹ cho 50 người. Nghe có vẻ phù hợp không?
W-Br Vâng, nhưng anh đã đọc email về các nhà cung cấp dịch vụ ăn uống chưa? Chúng ta chỉ có thể sử dụng những công ty đã được phê duyệt trước.
M-Cn Ồ, tôi chắc đã bỏ lỡ điều đó. Tôi sẽ kiểm tra, nhưng trong khi chị đang ở đây, tại sao chúng ta không diễn tập bài thuyết trình sẽ trình bày tại sự kiện? Như vậy, chúng ta có thể đảm bảo nó diễn ra suôn sẻ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6462, 5167, 62, 'What are the speakers planning?', 'A recruitment event', 'A product launch', 'A food festival', 'A board meeting', 'A', 'Question: What are the speakers planning? (Những người nói chuyện đang lên kế hoạch gì?)
A: A recruitment event (Một sự kiện tuyển dụng)
B: A product launch (Một buổi ra mắt sản phẩm)
C: A food festival (Một lễ hội ẩm thực)
D: A board meeting (Một cuộc họp hội đồng)

Giải thích: Đáp án A là chính xác vì họ đang lên kế hoạch cho một buổi tuyển dụng để tìm các nhà phát triển phần mềm mới (recruiting session for finding new software developers).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5168, 227, '2025/test3/audio/test3_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6463, 5168, 63, 'Look at the graphic. Whose e-mail does the woman refer to?', 'Mr. Parsons''s', 'Mr. Martino''s', 'Ms. Landrum''s', 'Ms. Cordero''s', 'B', 'Question: Look at the graphic. Whose e-mail does the woman refer to? (Nhìn vào hình đồ họa. Email của ai mà người phụ nữ đề cập đến?)
A: Mr. Parsons''s (Email của ông Parsons)
B: Mr. Martino''s (Email của ông Martino)
C: Ms. Landrum''s (Email của bà Landrum)
D: Ms. Cordero''s (Email của bà Cordero)

Giải thích: Đáp án B là chính xác vì trong hình đồ họa cho thấy Roy Martino đã gửi email với tiêu đề Approved catering companies" (Các công ty cung cấp dịch vụ ăn uống đã được phê duyệt) và người phụ nữ đang nói về việc chỉ có thể sử dụng các nhà cung cấp dịch vụ ăn uống đã được phê duyệt trước."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5169, 227, '2025/test3/audio/test3_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6464, 5169, 64, 'What does the man suggest doing?', 'Contacting technical support', 'Practicing a presentation', 'Checking a budget', 'Reserving a room', 'B', 'Question: What does the man suggest doing? (Người đàn ông đề xuất làm gì?)
A: Contacting technical support (Liên hệ hỗ trợ kỹ thuật)
B: Practicing a presentation (Luyện tập thuyết trình)
C: Checking a budget (Kiểm tra ngân sách)
D: Reserving a room (Đặt phòng)

Giải thích: Đáp án B là chính xác vì cuối đoạn hội thoại, người đàn ông đề xuất diễn tập bài thuyết trình mà họ sẽ trình bày tại sự kiện (why don''t we rehearse the presentation we''re giving at the event?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5170, 227, '2025/test3/audio/test3_question_65_67.mp3', '2025/test3/image/test3-p3-image-65.jpg', 'M-Au Thanks for giving me a ride to the Worthington Electronics Trade Show, Rachel. I would have had to take the bus.
W-Am My pleasure. Anyway, my house is in your neighborhood, remember? It wasn''t out of my way.
M-Au Oh, right. But I still appreciate it. Do you know how long it will take to get to the event center? It''s on Ashford Street, right?
w-Am Yes, but the traffic report said there has been an accident on Ashford Street. We need to take exit sixteen. We can park at the south entrance.
M-Au Okay. Then I''d better text Benjamin and ask him to wait for us there instead of at the north entrance.
W-Am Sounds good!', 'M-Au Cảm ơn Rachel đã cho tôi đi nhờ xe đến Triển lãm Điện tử Worthington. Lẽ ra tôi đã phải đi xe buýt.
W-Am Không có gì. Dù sao thì, nhà tôi cũng ở trong khu phố của anh, nhớ không? Nó không nằm ngoài đường đi của tôi.
M-Au Ồ, đúng rồi. Nhưng tôi vẫn rất cảm kích. Chị có biết mất bao lâu để đến trung tâm sự kiện không? Nó ở đường Ashford, đúng không?
W-Am Vâng, nhưng báo cáo giao thông nói rằng đã có tai nạn trên đường Ashford. Chúng ta cần đi lối ra số mười sáu. Chúng ta có thể đậu xe ở lối vào phía nam.
M-Au Được rồi. Vậy tôi nên nhắn tin cho Benjamin và nhờ anh ấy đợi chúng ta ở đó thay vì ở lối vào phía bắc.
W-Am Nghe hay đấy!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6465, 5170, 65, 'What does the woman remind the man about?', 'She has attended the event before', 'She currently lives near the man', 'She is borrowing a company car', 'She has an office in the event center', 'B', 'Question: What does the woman remind the man about? (Người phụ nữ nhắc người đàn ông về điều gì?)
A: She has attended the event before (Cô ấy đã từng tham dự sự kiện này trước đây)
B: She currently lives near the man (Cô ấy hiện đang sống gần người đàn ông)
C: She is borrowing a company car (Cô ấy đang mượn xe công ty)
D: She has an office in the event center (Cô ấy có văn phòng trong trung tâm sự kiện)

Giải thích: Đáp án B là chính xác vì người phụ nữ nhắc người đàn ông rằng nhà cô ấy ở trong khu phố của anh ấy (my house is in your neighborhood, remember?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5171, 227, '2025/test3/audio/test3_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6466, 5171, 66, 'Look at the graphic. Which exit will the speakers use?', 'Oakridge Lane', 'Ashford Street', 'Powell Street', 'Yorkie Road', 'D', 'Question: Look at the graphic. Which exit will the speakers use? (Nhìn vào hình đồ họa. Những người nói chuyện sẽ sử dụng lối ra nào?)
A: Oakridge Lane (Đường Oakridge)
B: Ashford Street (Đường Ashford)
C: Powell Street (Đường Powell)
D: Yorkie Road (Đường Yorkie)

Giải thích: Đáp án D là chính xác vì người phụ nữ nói họ cần đi lối ra số mười sáu (We need to take exit sixteen), và trong hình đồ họa cho thấy Yorkie Road là Exit 16.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5172, 227, '2025/test3/audio/test3_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6467, 5172, 67, 'What will the man ask Benjamin to do?', 'Meet the speakers at a different entrance', 'Pick up some informational pamphlets', 'Save the speakers'' seats in the auditorium', 'Approve funds for a parking fee', 'A', 'Question: What will the man ask Benjamin to do? (Người đàn ông sẽ yêu cầu Benjamin làm gì?)
A: Meet the speakers at a different entrance (Gặp những người nói chuyện tại một lối vào khác)
B: Pick up some informational pamphlets (Lấy một số tờ rơi thông tin)
C: Save the speakers'' seats in the auditorium (Giữ chỗ ngồi cho những người nói chuyện trong khán phòng)
D: Approve funds for a parking fee (Phê duyệt kinh phí cho phí đỗ xe)

Giải thích: Đáp án A là chính xác vì người đàn ông nói anh ấy sẽ nhắn tin cho Benjamin và nhờ đợi họ ở lối vào phía nam thay vì ở lối vào phía bắc (I''d better text Benjamin and ask him to wait for us there instead of at the north entrance).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5173, 227, '2025/test3/audio/test3_question_68_70.mp3', '2025/test3/image/test3-p3-image-68.jpg', 'W-Br Hello. Some friends of mine are visiting from out of town next month and staying with me. I''d like my backyard to look its best, so l need some fertilizer.
M-Au Alright. Do you have a preference for the brand?
W-Br I''d like to try Hazel fertilizer, if you have it. Everyone says it''s very effective.
M-Au I was going to suggest that. Actually, I can give you a coupon for a discount on Hazel fertilizer. The more you buy, the more you''ll save.
W-Br Thank you! OK, I''ll get a second bag. Based on my yard''s size, it doesn''t make sense to get more than that.', 'W-Br Xin chào. Vài người bạn của tôi sẽ đến thăm từ nơi khác vào tháng sau và ở lại với tôi. Tôi muốn sân sau của mình trông đẹp nhất có thể, nên tôi cần một ít phân bón.
M-Au Được rồi. Chị có ưu tiên thương hiệu nào không?
W-Br Tôi muốn thử phân bón Hazel, nếu anh có. Mọi người nói nó rất hiệu quả.
M-Au Tôi cũng định gợi ý cái đó. Thực ra, tôi có thể đưa cho chị một phiếu giảm giá cho phân bón Hazel. Mua càng nhiều thì tiết kiệm càng nhiều.
W-Br Cảm ơn! OK, tôi sẽ lấy túi thứ hai. Dựa trên kích thước sân của tôi, việc mua nhiều hơn thế không có ý nghĩa.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6468, 5173, 68, 'What will the woman do next month?', 'Start a different job', 'Have some guests', 'Move to a new home', 'Teach a workshop', 'B', 'Question: What will the woman do next month? (Người phụ nữ sẽ làm gì vào tháng sau?)
A: Start a different job (Bắt đầu một công việc khác)
B: Have some guests (Có khách)
C: Move to a new home (Chuyển đến nhà mới)
D: Teach a workshop (Dạy một hội thảo)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói rằng một số người bạn của cô ấy sẽ đến thăm từ nơi khác vào tháng sau và ở lại với cô ấy (Some friends of mine are visiting from out of town next month and staying with me).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5174, 227, '2025/test3/audio/test3_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6469, 5174, 69, 'What does the woman say about Hazel fertilizer?', 'It is often sold out', 'It has a good reputation', 'It has the cheapest price', 'It is environmentally friendly', 'B', 'Question: What does the woman say about Hazel fertilizer? (Người phụ nữ nói gì về phân bón Hazel?)
A: It is often sold out (Nó thường xuyên hết hàng)
B: It has a good reputation (Nó có tiếng tốt)
C: It has the cheapest price (Nó có giá rẻ nhất)
D: It is environmentally friendly (Nó thân thiện với môi trường)

Giải thích: Đáp án B là chính xác vì người phụ nữ nói rằng mọi người nói nó rất hiệu quả (Everyone says it''s very effective), cho thấy phân bón này có tiếng tốt.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5175, 227, '2025/test3/audio/test3_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6470, 5175, 70, 'Look at the graphic. How much will the woman pay?', '$20.00', '$36.00', '$49.50', '$60.00', 'B', 'Question: Look at the graphic. How much will the woman pay? (Nhìn vào hình đồ họa. Người phụ nữ sẽ phải trả bao nhiêu tiền?)
A: $20.00
B: $36.00
C: $49.50
D: $60.00

Giải thích: Đáp án B là chính xác vì người phụ nữ nói cô ấy sẽ mua túi thứ hai (I''ll get a second bag), và trong hình đồ họa cho thấy giá cho 2 túi là $36.00.');;

-- Data for 2025 Test3 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5176, 228, '2025/test3/audio/test3_question_71_73.mp3', NULL, 'Are you looking for a way to reduce your stress and stay healthy? Working out is the key! At Highland Gym, we have a wide variety of equipment and classes to suit everyone''s interests and abilities. And our friendly staff is always on hand to answer questions and show you how to use the machines. We''ve recently extended our opening hours to make it even more convenient for our members. And, starting on November 3, we''ll be building an addition that will house a pool and more class space! Find out more about membership options by calling 555-0123. We hope to see you soon!', 'Bạn đang tìm kiếm cách để giảm căng thẳng và giữ gìn sức khỏe? Tập luyện chính là chìa khóa! Tại Highland Gym, chúng tôi có nhiều loại thiết bị và lớp học phù hợp với sở thích và khả năng của mọi người. Và đội ngũ nhân viên thân thiện của chúng tôi luôn sẵn sàng trả lời câu hỏi và hướng dẫn bạn cách sử dụng máy móc. Gần đây chúng tôi đã mở rộng giờ mở cửa để thuận tiện hơn cho các hội viên. Và, bắt đầu từ ngày 3 tháng 11, chúng tôi sẽ xây dựng thêm một khu vực sẽ có bể bơi và thêm không gian cho lớp học! Tìm hiểu thêm về các lựa chọn hội viên bằng cách gọi 555-0123. Chúng tôi hy vọng sớm gặp bạn!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6471, 5176, 71, 'What is the advertisement about?', 'A pharmacy', 'A dental clinic', 'A fitness center', 'A hotel', 'C', '[Dịch] Câu hỏi: Quảng cáo này nói về cái gì?
A: Một hiệu thuốc
B: Một phòng khám nha khoa
C: Một trung tâm thể hình
D: Một khách sạn

Đáp án C là chính xác vì quảng cáo nói về Highland Gym với các trang thiết bị tập luyện, các lớp học, và sẽ xây thêm bể bơi, rõ ràng đây là một trung tâm thể hình.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5177, 228, '2025/test3/audio/test3_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6472, 5177, 72, 'What has the business recently changed?', 'Its staff responsibilities', 'Its standard fees', 'Its cancellation policy', 'Its hours of operation', 'D', '[Dịch] Câu hỏi: Doanh nghiệp gần đây đã thay đổi điều gì?
A: Trách nhiệm của nhân viên
B: Phí tiêu chuẩn
C: Chính sách hủy
D: Giờ hoạt động

Đáp án D là chính xác vì trong đoạn có đề cập "We''ve recently extended our opening hours", nghĩa là họ vừa mới mở rộng giờ mở cửa của họ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5178, 228, '2025/test3/audio/test3_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6473, 5178, 73, 'What will happen on November 3?', 'A construction project will begin.', 'A prize drawing will be held.', 'A newsletter will be sent.', 'A new branch will open.', 'A', '[Dịch] Câu hỏi: Điều gì sẽ xảy ra vào ngày 3 tháng 11?
A: Một dự án xây dựng sẽ bắt đầu
B: Một cuộc rút thăm trúng thưởng sẽ được tổ chức
C: Một bản tin sẽ được gửi đi
D: Một chi nhánh mới sẽ mở cửa

Đáp án A là chính xác vì đoạn văn nêu rõ "starting on November 3, we''ll be building an addition", nghĩa là họ sẽ bắt đầu xây dựng thêm một khu vực mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5179, 228, '2025/test3/audio/test3_question_74_76.mp3', NULL, 'I called this meeting to finally discuss how we''ll restructure some of the work teams here at the office. As you know from my initial announcement of this plan, it''s meant to help employees better use their talents to contribute to the company''s goals. I''m sorry that you''ve had to wait longer than planned for the details-I''ve had several unexpected visits from clients this week. Uh, I''m passing out the new organizational chart now. You''ll notice that we plan to hire several more part-time workers, so that''ll make it easier to finish the workload your team has been assigned.', 'Tôi đã gọi cuộc họp này để cuối cùng thảo luận về cách chúng ta sẽ tái cơ cấu một số nhóm làm việc tại văn phòng. Như các bạn đã biết từ thông báo ban đầu của tôi về kế hoạch này, nó nhằm giúp nhân viên sử dụng tốt hơn tài năng của họ để đóng góp vào mục tiêu của công ty. Tôi xin lỗi vì các bạn đã phải đợi lâu hơn dự kiến để biết chi tiết - tôi đã có một số cuộc gặp không lên kế hoạch từ khách hàng trong tuần này. À, tôi đang phát sơ đồ tổ chức mới bây giờ. Các bạn sẽ thấy rằng chúng tôi có kế hoạch thuê thêm một số nhân viên bán thời gian, vì vậy điều đó sẽ giúp hoàn thành khối lượng công việc được giao cho nhóm của bạn dễ dàng hơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6474, 5179, 74, 'What is the speaker mainly discussing?', 'Launching a product', 'Relocating the office', 'Attracting new clients', 'Reorganizing some teams', 'D', '[Dịch] Câu hỏi: Người nói chủ yếu đang thảo luận về điều gì?
A: Ra mắt một sản phẩm
B: Di dời văn phòng
C: Thu hút khách hàng mới
D: Tái tổ chức một số nhóm

Đáp án D là chính xác vì ngay từ đầu người nói đã nêu rõ cuộc họp là để thảo luận về việc "restructure some of the work teams" (tái cơ cấu một số nhóm làm việc).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5180, 228, '2025/test3/audio/test3_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6475, 5180, 75, 'Why does the speaker say, "I''ve had several unexpected visits from clients this week"?', 'To issue an invitation', 'To offer an excuse', 'To express encouragement', 'To request assistance', 'B', '[Dịch] Câu hỏi: Tại sao người nói nói "Tôi đã có một số cuộc gặp không lên kế hoạch từ khách hàng trong tuần này"?
A: Để đưa ra lời mời
B: Để đưa ra một lời xin lỗi
C: Để thể hiện sự khuyến khích
D: Để yêu cầu hỗ trợ

Đáp án B là chính xác vì người nói dùng câu này để giải thích lý do tại sao mọi người phải đợi lâu hơn dự kiến để biết chi tiết ("had to wait longer than planned for the details").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5181, 228, '2025/test3/audio/test3_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6476, 5181, 76, 'According to the speaker, what will become easier for employees?', 'Communicating with colleagues', 'Accessing a database', 'Completing work assignments', 'Receiving performance bonuses', 'C', '[Dịch] Câu hỏi: Theo người nói, điều gì sẽ trở nên dễ dàng hơn cho nhân viên?
A: Giao tiếp với đồng nghiệp
B: Truy cập cơ sở dữ liệu
C: Hoàn thành công việc được giao
D: Nhận thưởng hiệu suất

Đáp án C là chính xác vì người nói cho biết việc thuê thêm nhân viên bán thời gian sẽ "make it easier to finish the workload", nghĩa là giúp việc hoàn thành khối lượng công việc dễ dàng hơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5182, 228, '2025/test3/audio/test3_question_77_79.mp3', NULL, 'Before we begin filming, I want to thank you all for agreeing to share the expertise you''ve gained during your time leading tours for our agency. We are certain that this video featuring your expert advice for new guides will be a valuable tool in our training program. Now, we''re going to film you all having a lively discussion on the topic, hopefully to get a range of viewpoints. You can see the recording area set up here. You''ll each wear a microphone that clips to your work vest. Why don''t you pick those up now? Michael has enough for everyone.', 'Trước khi chúng ta bắt đầu quay phim, tôi muốn cảm ơn tất cả các bạn đã đồng ý chia sẻ kinh nghiệm mà các bạn đã có được trong thời gian dẫn tour cho cơ quan của chúng ta. Chúng tôi chắc chắn rằng video này với những lời khuyên chuyên môn của các bạn dành cho các hướng dẫn viên mới sẽ là một công cụ có giá trị trong chương trình đào tạo của chúng ta. Bây giờ, chúng ta sẽ quay cảnh tất cả các bạn thảo luận sôi nổi về chủ đề này, hy vọng sẽ có được nhiều quan điểm khác nhau. Các bạn có thể thấy khu vực quay phim được thiết lập ở đây. Mỗi người sẽ đeo một micro gắn vào áo vest công việc của mình. Sao các bạn không lấy chúng ngay bây giờ? Michael có đủ cho mọi người.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6477, 5182, 77, 'Where does the speaker most likely work?', 'At a department store', 'At a moving service', 'At a tour company', 'At a commercial airline', 'C', '[Dịch] Câu hỏi: Người nói có khả năng làm việc ở đâu?
A: Tại một cửa hàng bách hóa
B: Tại một dịch vụ chuyển nhà
C: Tại một công ty du lịch
D: Tại một hãng hàng không

Đáp án C là chính xác vì đoạn văn đề cập đến việc dẫn tour ("leading tours") và hướng dẫn viên mới ("new guides"), cho thấy đây là một công ty du lịch.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5183, 228, '2025/test3/audio/test3_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6478, 5183, 78, 'What will be the topic of the video?', 'The history of the company', 'Current sales territories', 'Mandatory safety procedures', 'Tips for new employees', 'D', '[Dịch] Câu hỏi: Chủ đề của video sẽ là gì?
A: Lịch sử của công ty
B: Các khu vực bán hàng hiện tại
C: Quy trình an toàn bắt buộc
D: Lời khuyên cho nhân viên mới

Đáp án D là chính xác vì đoạn văn nêu rõ video sẽ bao gồm "expert advice for new guides" (lời khuyên chuyên môn cho các hướng dẫn viên mới).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5184, 228, '2025/test3/audio/test3_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6479, 5184, 79, 'What will the listeners probably do next?', 'Watch a demonstration', 'Pick up some equipment', 'Read a script', 'Set up some tables', 'B', '[Dịch] Câu hỏi: Người nghe có khả năng sẽ làm gì tiếp theo?
A: Xem một bài thị phạm
B: Lấy một số thiết bị
C: Đọc một kịch bản
D: Sắp xếp một số bàn

Đáp án B là chính xác vì người nói gợi ý "Why don''t you pick those up now?" khi đề cập đến việc lấy micro, và khẳng định Michael có đủ cho mọi người.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5185, 228, '2025/test3/audio/test3_question_80_82.mp3', NULL, 'Good evening, and thanks for coming to this fundraising dinner. There were supposed to be name cards at the tables, but the print shop used the wrong address. I hope our staff helped you to find your assigned seats. We had put a lot of thought into the seating plan. Anyway, we''re very thankful for the support you''ve given to the restoration project at the Kellerson Concert Hall. l''d like to give a special thanks to Stephanie Avera, who conducted all of the research about the building''s original condition and style. More information about that is on our Web site.', 'Chào buổi tối và cảm ơn quý vị đã đến dự bữa tối gây quỹ này. Lẽ ra phải có thẻ tên trên các bàn, nhưng cửa hàng in đã sử dụng sai địa chỉ. Tôi hy vọng nhân viên của chúng tôi đã giúp quý vị tìm được chỗ ngồi được chỉ định. Chúng tôi đã dành nhiều suy nghĩ cho kế hoạch sắp xếp chỗ ngồi. Dù sao thì, chúng tôi rất biết ơn sự ủng hộ của quý vị dành cho dự án trùng tu tại Phòng hòa nhạc Kellerson. Tôi muốn gửi lời cảm ơn đặc biệt đến Stephanie Avera, người đã thực hiện tất cả các nghiên cứu về tình trạng và phong cách ban đầu của tòa nhà. Thông tin thêm về điều đó có trên trang web của chúng tôi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6480, 5185, 80, 'Why does the speaker say, "the print shop used the wrong address"?', 'To ask for some suggestions', 'To apologize for a delay', 'To recommend canceling a contract', 'To explain some missing items', 'D', '[Dịch] Câu hỏi: Tại sao người nói nói "cửa hàng in đã sử dụng sai địa chỉ"?
A: Để xin một số đề xuất
B: Để xin lỗi về sự chậm trễ
C: Để đề xuất hủy hợp đồng
D: Để giải thích về một số vật phẩm bị thiếu

Đáp án D là chính xác vì người nói dùng câu này để giải thích lý do tại sao các thẻ tên không có trên bàn ("name cards at the tables").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5186, 228, '2025/test3/audio/test3_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6481, 5186, 81, 'What does the speaker say about the seating plan?', 'It does not need to be followed.', 'It was carefully considered.', 'It is the same every year.', 'It had guests added to it.', 'B', '[Dịch] Câu hỏi: Người nói nói gì về kế hoạch sắp xếp chỗ ngồi?
A: Nó không cần phải được tuân theo
B: Nó đã được cân nhắc kỹ lưỡng
C: Nó giống nhau mỗi năm
D: Nó đã có thêm khách được thêm vào

Đáp án B là chính xác vì người nói cho biết "We had put a lot of thought into the seating plan", nghĩa là họ đã dành nhiều suy nghĩ cho kế hoạch sắp xếp chỗ ngồi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5187, 228, '2025/test3/audio/test3_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6482, 5187, 82, 'Who does the speaker give a special thanks to?', 'A singer', 'A designer', 'A researcher', 'A building manager', 'C', '[Dịch] Câu hỏi: Người nói gửi lời cảm ơn đặc biệt đến ai?
A: Một ca sĩ
B: Một nhà thiết kế
C: Một nhà nghiên cứu
D: Một người quản lý tòa nhà

Đáp án C là chính xác vì người nói cảm ơn Stephanie Avera, người đã "conducted all of the research" (thực hiện tất cả các nghiên cứu) về tình trạng và phong cách ban đầu của tòa nhà.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5188, 228, '2025/test3/audio/test3_question_83_85.mp3', NULL, 'Hi, Carolyn, this is Logan from the Exeter Gallery. First, l''d like to tell you how excited I am that your exhibition is going so well. In fact, it''s been our most-visited event ever. Congratulations! We''d like to extend the duration of the exhibition for another month. Since photos of your work will appear in Art World Magazine in July, I think even more people will be interested in it after that. When you have time, you should visit the testimonials page of our Web site. I think you''ll enjoy seeing the positive comments people are leaving about your work.', 'Chào Carolyn, tôi là Logan từ Phòng trưng bày Exeter. Trước tiên, tôi muốn nói với bạn rằng tôi rất vui mừng khi triển lãm của bạn đang diễn ra rất tốt. Thực tế, nó là sự kiện được ghé thăm nhiều nhất của chúng tôi từ trước đến nay. Xin chúc mừng! Chúng tôi muốn gia hạn thời gian triển lãm thêm một tháng nữa. Vì ảnh tác phẩm của bạn sẽ xuất hiện trên Tạp chí Art World vào tháng 7, tôi nghĩ sẽ có nhiều người quan tâm hơn nữa sau đó. Khi bạn có thời gian, bạn nên ghé thăm trang lời chứng thực trên trang web của chúng tôi. Tôi nghĩ bạn sẽ thích thú khi thấy những bình luận tích cực mà mọi người đang để lại về tác phẩm của bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6483, 5188, 83, 'What does the speaker congratulate the listener for?', 'She was given an award.', 'She opened her own gallery.', 'Her paintings are selling quickly.', 'Her exhibition has been popular.', 'D', '[Dịch] Câu hỏi: Người nói chúc mừng người nghe vì điều gì?
A: Cô ấy đã được trao giải thưởng
B: Cô ấy đã mở phòng trưng bày riêng
C: Tranh của cô ấy bán chạy
D: Triển lãm của cô ấy đã được ưa chuộng

Đáp án D là chính xác vì người nói cho biết triển lãm "has been our most-visited event ever" (là sự kiện được ghé thăm nhiều nhất từ trước đến nay).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5189, 228, '2025/test3/audio/test3_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6484, 5189, 84, 'According to the speaker, what will happen in July?', 'A museum will shut down.', 'Copies of some artwork will go on sale.', 'Some art will be featured in a magazine.', 'A television interview will take place.', 'C', '[Dịch] Câu hỏi: Theo người nói, điều gì sẽ xảy ra vào tháng 7?
A: Một bảo tàng sẽ đóng cửa
B: Bản sao của một số tác phẩm nghệ thuật sẽ được bán
C: Một số tác phẩm nghệ thuật sẽ được giới thiệu trên tạp chí
D: Một cuộc phỏng vấn truyền hình sẽ diễn ra

Đáp án C là chính xác vì người nói cho biết "photos of your work will appear in Art World Magazine in July", nghĩa là ảnh tác phẩm sẽ xuất hiện trên Tạp chí Art World vào tháng 7.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5190, 228, '2025/test3/audio/test3_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6485, 5190, 85, 'Why should the listener visit a Web site?', 'To register for an event', 'To read some comments', 'To upload some photographs', 'To join a mailing list', 'B', '[Dịch] Câu hỏi: Tại sao người nghe nên ghé thăm một trang web?
A: Để đăng ký một sự kiện
B: Để đọc một số bình luận
C: Để tải lên một số ảnh
D: Để tham gia danh sách gửi thư

Đáp án B là chính xác vì người nói gợi ý người nghe ghé thăm trang lời chứng thực để xem "positive comments" (những bình luận tích cực) về tác phẩm của cô ấy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5191, 228, '2025/test3/audio/test3_question_86_88.mp3', NULL, 'Good afternoon, and thanks for listening to Better Bodies, the show that teaches you about taking good care of your health. My guest today is Dr. Max Ramirez, a food scientist working at the Kentwood Institute. He''s just completed some fascinating research on almonds. Did you know that eating almonds before bed helps you have better, more refreshing sleep? We''ll find out more about this and other discoveries from Dr. Ramirez''s research. And we''ll also be taking your questions live on the air. But first, let''s have a message from our sponsor.', 'Xin chào buổi chiều và cảm ơn quý vị đã lắng nghe Better Bodies, chương trình dạy bạn cách chăm sóc sức khỏe tốt. Khách mời hôm nay của tôi là Tiến sĩ Max Ramirez, một nhà khoa học thực phẩm làm việc tại Viện Kentwood. Ông vừa hoàn thành một số nghiên cứu thú vị về hạnh nhân. Bạn có biết rằng ăn hạnh nhân trước khi đi ngủ giúp bạn có giấc ngủ ngon và sảng khoái hơn không? Chúng ta sẽ tìm hiểu thêm về điều này và các khám phá khác từ nghiên cứu của Tiến sĩ Ramirez. Và chúng tôi cũng sẽ nhận câu hỏi của các bạn trực tiếp trên sóng. Nhưng trước hết, hãy nghe một thông điệp từ nhà tài trợ của chúng ta.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6486, 5191, 86, 'Where does the speaker most likely work?', 'At a research institute', 'At a radio station', 'At a manufacturing plant', 'At a grocery store', 'B', '[Dịch] Câu hỏi: Người nói có khả năng làm việc ở đâu?
A: Tại một viện nghiên cứu
B: Tại một đài phát thanh
C: Tại một nhà máy sản xuất
D: Tại một cửa hàng tạp hóa

Đáp án B là chính xác vì đây là một chương trình phát thanh (the show), người nói đang dẫn chương trình, sẽ phát sóng trực tiếp ("taking your questions live on the air") và có quảng cáo từ nhà tài trợ ("message from our sponsor").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5192, 228, '2025/test3/audio/test3_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6487, 5192, 87, 'What does Dr. Ramirez specialize in?', 'Hospital management', 'Audio production', 'Mechanical engineering', 'Food science', 'D', '[Dịch] Câu hỏi: Tiến sĩ Ramirez chuyên về lĩnh vực gì?
A: Quản lý bệnh viện
B: Sản xuất âm thanh
C: Kỹ thuật cơ khí
D: Khoa học thực phẩm

Đáp án D là chính xác vì trong đoạn hội thoại giới thiệu Dr. Ramirez là "a food scientist" (một nhà khoa học thực phẩm) đang làm việc tại Viện Kentwood.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5193, 228, '2025/test3/audio/test3_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6488, 5193, 88, 'What benefit of an item is mentioned?', 'It enables people to concentrate better.', 'It helps with weight loss efforts.', 'It can be stored for a long time.', 'It improves the quality of people''s sleep.', 'D', '[Dịch] Câu hỏi: Lợi ích nào của một món đồ được đề cập?
A: Nó giúp mọi người tập trung tốt hơn
B: Nó giúp nỗ lực giảm cân
C: Nó có thể được bảo quản trong thời gian dài
D: Nó cải thiện chất lượng giấc ngủ của mọi người

Đáp án D là chính xác vì đoạn hội thoại đề cập rằng "eating almonds before bed helps you have better, more refreshing sleep" (ăn hạnh nhân trước khi đi ngủ giúp bạn có giấc ngủ ngon và sảng khoái hơn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5194, 228, '2025/test3/audio/test3_question_89_91.mp3', NULL, 'Let''s get started, everyone. First, I''d like to report on sales of our newest wireless headphones, the BP-90. I''ve just reviewed the market analysis, and these headphones were the top seller in their category last month. We''ve never done this before. You should all be very proud. This is great timing because representatives from the Landry Group are visiting our offices next Monday. Their investment is essential to our operations, so we want to make a good impression. So, before you leave on Friday, don''t forget to make sure your desk and cubicle are tidy.', 'Hãy bắt đầu nào, mọi người. Đầu tiên, tôi muốn báo cáo về doanh số bán tai nghe không dây mới nhất của chúng ta, BP-90. Tôi vừa xem xét phân tích thị trường, và những tai nghe này là sản phẩm bán chạy nhất trong danh mục của chúng trong tháng trước. Chúng ta chưa bao giờ làm được điều này trước đây. Tất cả các bạn nên rất tự hào. Đây là thời điểm tuyệt vời vì các đại diện từ Tập đoàn Landry sẽ đến thăm văn phòng của chúng ta vào thứ Hai tới. Khoản đầu tư của họ rất cần thiết cho hoạt động của chúng ta, vì vậy chúng ta muốn tạo ấn tượng tốt. Vì vậy, trước khi về vào thứ Sáu, đừng quên đảm bảo bàn làm việc và khu vực làm việc của bạn gọn gàng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6489, 5194, 89, 'What does the speaker mean when he says, "We''ve never done this before"?', 'He can explain an error.', 'He wants to adjust a schedule.', 'He is nervous about a plan.', 'He is praising an accomplishment.', 'D', '[Dịch] Câu hỏi: Người nói có ý gì khi anh ấy nói "Chúng ta chưa bao giờ làm được điều này trước đây"?
A: Anh ấy có thể giải thích một lỗi
B: Anh ấy muốn điều chỉnh lịch trình
C: Anh ấy lo lắng về một kế hoạch
D: Anh ấy đang khen ngợi một thành tích

Đáp án D là chính xác vì câu này được nói sau khi thông báo tai nghe BP-90 là sản phẩm bán chạy nhất trong danh mục của nó tháng trước và tiếp theo là "You should all be very proud", cho thấy đây là lời khen ngợi về một thành tích chưa từng có.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5195, 228, '2025/test3/audio/test3_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6490, 5195, 90, 'What will happen at the company next Monday?', 'Some investors will visit.', 'A new executive will be hired', 'Some training sessions will take place.', 'A promotion will be announced.', 'A', '[Dịch] Câu hỏi: Điều gì sẽ xảy ra tại công ty vào thứ Hai tới?
A: Một số nhà đầu tư sẽ đến thăm
B: Một giám đốc điều hành mới sẽ được thuê
C: Một số buổi đào tạo sẽ diễn ra
D: Một sự thăng chức sẽ được thông báo

Đáp án A là chính xác vì đoạn hội thoại nêu rõ "representatives from the Landry Group are visiting our offices next Monday" và họ được mô tả là các nhà đầu tư quan trọng ("Their investment is essential").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5196, 228, '2025/test3/audio/test3_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6491, 5196, 91, 'What does the speaker remind the listeners to do?', 'Stay within a budget', 'Review some job duties', 'Clean up a workspace', 'Use a sign-up sheet', 'C', '[Dịch] Câu hỏi: Người nói nhắc nhở người nghe làm gì?
A: Giữ trong phạm vi ngân sách
B: Xem xét lại một số nhiệm vụ công việc
C: Dọn dẹp không gian làm việc
D: Sử dụng bảng đăng ký

Đáp án C là chính xác vì người nói nhắc nhở "make sure your desk and cubicle are tidy", nghĩa là đảm bảo bàn và khu vực làm việc gọn gàng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5197, 228, '2025/test3/audio/test3_question_92_94.mp3', NULL, 'It''s my pleasure to welcome you all to this dinner commemorating our twenty-fifth year in business. This is a big milestone for our law firm, and we continue to look for ways to grow and improve for the next twenty-five years. I would especially like to thank Kevin Diaz, the head of our IT department, who upgraded the security on our computers and other systems to ensure that our clients'' confidential documents would remain safe. This helped to attract several major clients. We''ll highlight other staff members'' contributions throughout the night, but first, let''s enjoy the delicious dishes that will be coming out shortly.', 'Tôi rất vui mừng được chào đón tất cả các bạn đến bữa tối kỷ niệm năm thứ hai mươi lăm hoạt động của chúng ta. Đây là một dấu mốc quan trọng đối với công ty luật của chúng ta, và chúng ta tiếp tục tìm kiếm cách phát triển và cải thiện cho hai mươi lăm năm tiếp theo. Tôi đặc biệt muốn cảm ơn Kevin Diaz, trưởng bộ phận IT của chúng ta, người đã nâng cấp bảo mật trên máy tính và các hệ thống khác để đảm bảo tài liệu bảo mật của khách hàng luôn an toàn. Điều này đã giúp thu hút một số khách hàng lớn. Chúng ta sẽ nêu bật những đóng góp của các nhân viên khác trong suốt đêm nay, nhưng trước tiên, hãy thưởng thức những món ăn ngon sẽ được phục vụ trong thời gian tới.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6492, 5197, 92, 'Why is the company holding an event?', 'To celebrate an anniversary', 'To promote a new product', 'To welcome new employees', 'To congratulate a department', 'A', '[Dịch] Câu hỏi: Tại sao công ty tổ chức sự kiện này?
A: Để kỷ niệm một dấu mốc
B: Để quảng bá một sản phẩm mới
C: Để chào đón nhân viên mới
D: Để chúc mừng một bộ phận

Đáp án A là chính xác vì đây là bữa tối kỷ niệm "twenty-fifth year in business" (25 năm hoạt động), được mô tả là "a big milestone" (một dấu mốc quan trọng) của công ty luật.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5198, 228, '2025/test3/audio/test3_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6493, 5198, 93, 'What does the speaker say about Mr. Diaz?', 'He designed a training program.', 'He oversaw a company expansion.', 'He improved some security measures.', 'He negotiated an important contract.', 'C', '[Dịch] Câu hỏi: Người nói nói gì về ông Diaz?
A: Ông ấy đã thiết kế một chương trình đào tạo
B: Ông ấy đã giám sát việc mở rộng công ty
C: Ông ấy đã cải thiện một số biện pháp an ninh
D: Ông ấy đã đàm phán một hợp đồng quan trọng

Đáp án C là chính xác vì người nói cho biết Kevin Diaz "upgraded the security on our computers and other systems" (nâng cấp bảo mật trên máy tính và các hệ thống khác).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5199, 228, '2025/test3/audio/test3_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6494, 5199, 94, 'According to the speaker, what will happen after a meal is served?', 'A group photo will be taken.', 'A series of videos will be shown.', 'Other workers will be recognized.', 'Messages from clients will be read.', 'C', '[Dịch] Câu hỏi: Theo người nói, điều gì sẽ xảy ra sau khi bữa ăn được phục vụ?
A: Một bức ảnh nhóm sẽ được chụp
B: Một loạt video sẽ được chiếu
C: Các nhân viên khác sẽ được ghi nhận
D: Tin nhắn từ khách hàng sẽ được đọc

Đáp án C là chính xác vì người nói tuyên bố "We''ll highlight other staff members'' contributions throughout the night" (Chúng ta sẽ nêu bật những đóng góp của các nhân viên khác trong suốt đêm nay).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5200, 228, '2025/test3/audio/test3_question_95_97.mp3', '2025/test3/image/test3-p4-image-95.jpg', 'I''d like to thank you once again for participating in this tour of the National Aviation Museum. I apologize that the tour did not include seeing the accessories worn by pilots. Unfortunately, that area will be closed for about ten days while some display cases are being replaced. If you have time after this tour, I highly recommend going to the two o''clock lecture. It''s in our event room, right next to the gift shop. There, Celia Watson, a photographer for the journal Flight Monthly, will be discussing her collection of photos of historical planes.', 'Tôi muốn cảm ơn quý vị một lần nữa vì đã tham gia chuyến tham quan Bảo tàng Hàng không Quốc gia này. Tôi xin lỗi vì chuyến tham quan không bao gồm việc xem các phụ kiện mà phi công sử dụng. Thật không may, khu vực đó sẽ đóng cửa khoảng mười ngày trong khi một số tủ trưng bày đang được thay thế. Nếu quý vị có thời gian sau chuyến tham quan này, tôi thực sự khuyên quý vị nên đến buổi thuyết trình lúc hai giờ. Nó được tổ chức trong phòng sự kiện của chúng tôi, ngay bên cạnh cửa hàng quà tặng. Ở đó, Celia Watson, một nhiếp ảnh gia của tạp chí Flight Monthly, sẽ thảo luận về bộ sưu tập ảnh máy bay lịch sử của cô ấy.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6495, 5200, 95, 'Look at the graphic. Which area is temporarily closed?', 'The East Wing', 'The West Wing', 'The North Wing', 'The Main Hall', 'B', '[Dịch] Câu hỏi: Nhìn vào hình. Khu vực nào tạm thời đóng cửa?
A: Khu vực Cánh Đông
B: Khu vực Cánh Tây
C: Khu vực Cánh Bắc
D: Sảnh Chính

Đáp án B là chính xác vì đoạn văn đề cập đến khu vực trưng bày "accessories worn by pilots" (phụ kiện phi công mang) đang đóng cửa. Nhìn vào sơ đồ, West Wing được đánh dấu là "Pilot Accessories" (Phụ kiện Phi công), chính là khu vực đang đóng cửa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5201, 228, '2025/test3/audio/test3_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6496, 5201, 96, 'What does the speaker suggest doing?', 'Keeping a receipt', 'Visiting a gift shop', 'Attending a talk', 'Taking a brochure', 'C', '[Dịch] Câu hỏi: Người nói đề xuất làm gì?
A: Giữ hóa đơn
B: Ghé thăm cửa hàng quà tặng
C: Tham dự một buổi nói chuyện
D: Lấy một tờ rơi

Đáp án C là chính xác vì người nói khuyến nghị "going to the two o''clock lecture" (đến buổi thuyết trình lúc hai giờ), nơi Celia Watson sẽ thảo luận về bộ sưu tập ảnh của cô ấy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5202, 228, '2025/test3/audio/test3_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6497, 5202, 97, 'Who is Celia Watson?', 'A professional photographer', 'A history professor', 'A film director', 'A commercial pilot', 'A', '[Dịch] Câu hỏi: Celia Watson là ai?
A: Một nhiếp ảnh gia chuyên nghiệp
B: Một giáo sư lịch sử
C: Một đạo diễn phim
D: Một phi công thương mại

Đáp án A là chính xác vì trong đoạn văn giới thiệu Celia Watson là "a photographer for the journal Flight Monthly" (một nhiếp ảnh gia của tạp chí Flight Monthly).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5203, 228, '2025/test3/audio/test3_question_98_100.mp3', '2025/test3/image/test3-p4-image-98.jpg', 'Hi, Mr. Davis. It''s Lacy. I wanted to give you an update on your appearance on the Entertainment Daily TV show. I''ve scheduled it for the day before your preview screening. That way, you''ll be able to promote both the film and that event during the interview. I''ve also proofread and fact-checked your speech for the awards banquet in New York. There are a few things that I think should be revised, so I''ll send you my notes about those later. I''ve reserved a room for you in New York, but wasn''t able to get your first choice of hotel. Unfortunately, there were no rooms available for that.', 'Chào ông Davis. Tôi là Lacy. Tôi muốn cập nhật cho ông về việc xuất hiện trên chương trình truyền hình Entertainment Daily. Tôi đã lên lịch vào ngày trước buổi chiếu thử của ông. Như vậy, ông sẽ có thể quảng bá cả bộ phim và sự kiện đó trong buổi phỏng vấn. Tôi cũng đã đọc và kiểm tra thông tin trong bài phát biểu của ông cho bữa tiệc trao giải ở New York. Có một vài điều tôi nghĩ nên được sửa đổi, vì vậy tôi sẽ gửi ghi chú của tôi về những điều đó sau. Tôi đã đặt phòng cho ông ở New York, nhưng không thể có được lựa chọn khách sạn đầu tiên của ông. Thật không may, không còn phòng trống nào cho việc đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6498, 5203, 98, 'Look at the graphic. For which day has the speaker scheduled a television appearance?', 'October 4', 'October 5', 'October 6', 'October 7', 'B', '[Dịch] Câu hỏi: Nhìn vào hình. Người nói đã lên lịch xuất hiện trên truyền hình vào ngày nào?
A: Ngày 4 tháng 10
B: Ngày 5 tháng 10
C: Ngày 6 tháng 10
D: Ngày 7 tháng 10

Đáp án B là chính xác vì người nói cho biết đã lên lịch buổi phỏng vấn vào "the day before your preview screening". Nhìn vào lịch, preview screening diễn ra vào ngày 6 tháng 10, vậy buổi phỏng vấn sẽ vào ngày 5 tháng 10.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5204, 228, '2025/test3/audio/test3_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6499, 5204, 99, 'What does the speaker say she will send?', 'Suggestions for revisions', 'Some driving directions', 'A confirmation number', 'A guest list', 'A', '[Dịch] Câu hỏi: Người nói nói cô ấy sẽ gửi gì?
A: Đề xuất cho các chỉnh sửa
B: Một số chỉ dẫn đường đi
C: Một số xác nhận
D: Danh sách khách mời

Đáp án A là chính xác vì người nói cho biết cô ấy sẽ gửi "notes about" những điều cần được sửa đổi trong bài phát biểu ("things that I think should be revised").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5205, 228, '2025/test3/audio/test3_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6500, 5205, 100, 'What problem does the speaker mention?', 'A hotel was fully booked.', 'No direct flights were available.', 'A fee has recently increased.', 'A building is difficult to find.', 'A', '[Dịch] Câu hỏi: Người nói đề cập đến vấn đề gì?
A: Một khách sạn đã kín phòng
B: Không có chuyến bay thẳng
C: Một khoản phí gần đây đã tăng
D: Một tòa nhà khó tìm

Đáp án A là chính xác vì người nói đề cập rằng cô ấy không thể đặt được khách sạn đầu tiên mà ông Davis chọn vì "there were no rooms available" (không còn phòng trống).');;

-- Data for 2025 Test3 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5206, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6501, 5206, 101, 'Mr. Johnston is taking online classes that will assist ----- in getting promoted.', 'his', 'he', 'him', 'himself', 'C', 'Đáp án C (him) là đúng vì các lý do sau:
1. Sau động từ "assist", ta cần một đại từ tân ngữ (object pronoun).
2. "Him" là đại từ tân ngữ phù hợp với ngôi thứ ba số ít nam giới (Mr. Johnston).
3. Cấu trúc "assist somebody in doing something" là cấu trúc chuẩn trong tiếng Anh.
4. Các đáp án khác không phù hợp: "his" là tính từ sở hữu, "he" là đại từ chủ ngữ, "himself" là đại từ phản thân.
Dịch câu hỏi: Ông Johnston đang học các khóa học trực tuyến sẽ giúp ông ấy được thăng chức.
Dịch đáp án:
A. his (tính từ sở hữu: của anh ấy)
B. he (đại từ chủ ngữ: anh ấy)
C. him (đại từ tân ngữ: anh ấy)
D. himself (đại từ phản thân: chính anh ấy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5207, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6502, 5207, 102, 'Attendees to the event can have their book ----- signed by the author.', 'personal', 'personally', 'personalize', 'personalizes', 'B', 'Đáp án B (personally) là đúng vì các lý do sau:
1. Cần một trạng từ bổ nghĩa cho quá trình ký sách.
2. "Personally" (trực tiếp/đích thân) là trạng từ thích hợp để mô tả cách thức tác giả ký sách.
3. Cấu trúc "have something + p.p + trạng từ" là cấu trúc phổ biến để mô tả cách thức một hành động được thực hiện.
4. Các đáp án khác không phù hợp: "personal" là tính từ, "personalize" và "personalizes" là động từ.
Dịch câu hỏi: Những người tham dự sự kiện có thể được tác giả đích thân ký sách của họ.
Dịch đáp án:
A. personal (tính từ: cá nhân)
B. personally (trạng từ: đích thân)
C. personalize (động từ: cá nhân hóa)
D. personalizes (động từ ngôi thứ 3 số ít: cá nhân hóa)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5208, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6503, 5208, 103, 'Readers of Ms. Alcorn''s column on money management appreciate her ---- financial advice.', 'thought', 'thoughts', 'thoughtfully', 'thoughtful', 'D', 'Đáp án D (thoughtful) là đúng vì các lý do sau:
1. Cần một tính từ để bổ nghĩa cho cụm danh từ "financial advice".
2. "Thoughtful" (chu đáo/sâu sắc) là tính từ thích hợp để mô tả lời khuyên tài chính.
3. Vị trí này cần một từ miêu tả chất lượng của lời khuyên.
4. Các đáp án khác không phù hợp: "thought" và "thoughts" là danh từ, "thoughtfully" là trạng từ.
Dịch câu hỏi: Độc giả của chuyên mục quản lý tài chính của cô Alcorn đánh giá cao những lời khuyên tài chính sâu sắc của cô ấy.
Dịch đáp án:
A. thought (danh từ: suy nghĩ)
B. thoughts (danh từ số nhiều: những suy nghĩ)
C. thoughtfully (trạng từ: một cách chu đáo)
D. thoughtful (tính từ: chu đáo/sâu sắc)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5209, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6504, 5209, 104, 'Prospective students are invited to learn more about the university''s programs by viewing its ----- course schedule.', 'detailed', 'detail', 'detailing', 'details', 'A', 'Đáp án A (detailed) là đúng vì các lý do sau:
1. Cần một tính từ để bổ nghĩa cho cụm danh từ "course schedule".
2. "Detailed" (chi tiết) là tính từ thích hợp để mô tả lịch học.
3. Tính từ này được đặt trước danh từ theo quy tắc trật tự từ trong tiếng Anh.
4. Các đáp án khác không phù hợp: "detail" là danh từ/động từ, "detailing" là động từ dạng -ing, "details" là danh từ số nhiều.
Dịch câu hỏi: Các sinh viên tiềm năng được mời tìm hiểu thêm về các chương trình của trường đại học bằng cách xem lịch học chi tiết của trường.
Dịch đáp án:
A. detailed (tính từ: chi tiết)
B. detail (danh từ: chi tiết)
C. detailing (động từ -ing: đang chi tiết hóa)
D. details (danh từ số nhiều: những chi tiết)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5210, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6505, 5210, 105, 'At Hartway Terrace, all dishes are prepared under the ----- of master chef Yoo-Jeong Jin.', 'style', 'opinion', 'attempt', 'supervision', 'D', 'Đáp án D (supervision) là đúng vì các lý do sau:
1. Cần một danh từ để hoàn thành cụm từ "under the ___ of" (dưới sự... của).
2. "Supervision" (giám sát) là danh từ thích hợp để chỉ việc đầu bếp trưởng quản lý việc chuẩn bị món ăn.
3. Cụm từ "under the supervision of" là cách diễn đạt chuẩn để chỉ ai đó chịu trách nhiệm giám sát.
4. Các đáp án khác không phù hợp về nghĩa: "style" (phong cách), "opinion" (ý kiến), "attempt" (nỗ lực).
Dịch câu hỏi: Tại Hartway Terrace, tất cả các món ăn được chuẩn bị dưới sự giám sát của đầu bếp trưởng Yoo-Jeong Jin.
Dịch đáp án:
A. style (danh từ: phong cách)
B. opinion (danh từ: ý kiến)
C. attempt (danh từ: nỗ lực)
D. supervision (danh từ: sự giám sát)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5211, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6506, 5211, 106, 'It is ----- that passengers be shown the safety briefing prior to the flight.', 'abundant', 'sudden', 'distinctive', 'imperative', 'D', 'Đáp án D (imperative) là đúng vì các lý do sau:
1. Cấu trúc "It is ___ that + mệnh đề" cần một tính từ chỉ sự cần thiết hoặc quan trọng.
2. "Imperative" (bắt buộc/cần thiết) là tính từ thích hợp để nhấn mạnh tầm quan trọng của việc hướng dẫn an toàn.
3. Khi nói về quy định an toàn, "imperative" thường được sử dụng để chỉ sự bắt buộc.
4. Các đáp án khác không phù hợp về nghĩa: "abundant" (phong phú), "sudden" (đột ngột), "distinctive" (đặc biệt).
Dịch câu hỏi: Điều bắt buộc là hành khách phải được xem hướng dẫn an toàn trước chuyến bay.
Dịch đáp án:
A. abundant (tính từ: phong phú)
B. sudden (tính từ: đột ngột)
C. distinctive (tính từ: đặc biệt)
D. imperative (tính từ: bắt buộc)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5212, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6507, 5212, 107, 'Contract negotiations with Murphy Supplies should be conducted ---- consideration for the lack of alternative suppliers.', 'by', 'with', 'so that', 'while', 'B', 'Đáp án B (with) là đúng vì các lý do sau:
1. Cần một giới từ để kết nối "conducted" và "consideration".
2. "With" là giới từ thích hợp để diễn tả cách thức hoặc thái độ trong việc thực hiện một hành động.
3. Cụm từ "with consideration for" là cách diễn đạt chuẩn để chỉ việc cân nhắc đến một yếu tố nào đó.
4. Các đáp án khác không phù hợp: "by" (bởi), "so that" (để mà), "while" (trong khi).
Dịch câu hỏi: Các cuộc đàm phán hợp đồng với Murphy Supplies nên được tiến hành với sự cân nhắc về việc thiếu các nhà cung cấp thay thế.
Dịch đáp án:
A. by (giới từ: bởi)
B. with (giới từ: với)
C. so that (liên từ: để mà)
D. while (liên từ: trong khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5213, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6508, 5213, 108, 'Peggy Amos was ----- by the director for creating the library''s popular "Future Entrepreneurs" lecture series.', 'intended', 'influenced', 'commended', 'allowed', 'C', 'Đáp án C (commended) là đúng vì các lý do sau:
1. Cần một động từ ở dạng quá khứ phân từ trong cấu trúc bị động.
2. "Commend" (khen ngợi) là động từ thích hợp để chỉ sự ghi nhận thành tích tích cực.
3. Việc được khen ngợi phù hợp với ngữ cảnh tạo ra một chuỗi bài giảng thành công.
4. Các đáp án khác không phù hợp về nghĩa: "intended" (dự định), "influenced" (bị ảnh hưởng), "allowed" (được phép).
Dịch câu hỏi: Peggy Amos đã được giám đốc khen ngợi vì đã tạo ra chuỗi bài giảng "Doanh nhân Tương lai" nổi tiếng của thư viện.
Dịch đáp án:
A. intended (quá khứ phân từ: dự định)
B. influenced (quá khứ phân từ: bị ảnh hưởng)
C. commended (quá khứ phân từ: được khen ngợi)
D. allowed (quá khứ phân từ: được phép)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5214, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6509, 5214, 109, 'Residential furnaces and boilers should undergo inspection ---- for safety reasons.', 'annually', 'overly', 'certainly', 'readily', 'A', 'Đáp án A (annually) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ tần suất để mô tả việc kiểm tra định kỳ.
2. "Annually" (hàng năm) là trạng từ thích hợp để chỉ việc kiểm tra được thực hiện một năm một lần.
3. Trong ngữ cảnh an toàn, việc kiểm tra định kỳ hàng năm là tiêu chuẩn phổ biến.
4. Các đáp án khác không phù hợp về nghĩa: "overly" (quá mức), "certainly" (chắc chắn), "readily" (dễ dàng).
Dịch câu hỏi: Lò sưởi và nồi hơi dân dụng nên được kiểm tra hàng năm vì lý do an toàn.
Dịch đáp án:
A. annually (trạng từ: hàng năm)
B. overly (trạng từ: quá mức)
C. certainly (trạng từ: chắc chắn)
D. readily (trạng từ: dễ dàng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5215, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6510, 5215, 110, 'To maintain client -----, the destruction of old files must be carried out carefully.', 'confiding', 'confidential', 'confidentiality', 'confidentially', 'C', 'Đáp án C (confidentiality) là đúng vì các lý do sau:
1. Cần một danh từ để làm tân ngữ của động từ "maintain".
2. "Confidentiality" (tính bảo mật) là danh từ chỉ việc giữ bí mật thông tin.
3. Đây là thuật ngữ chuyên môn phổ biến trong việc xử lý thông tin khách hàng.
4. Các đáp án khác không phù hợp: "confiding" (tin tưởng), "confidential" (bảo mật - tính từ), "confidentially" (một cách bảo mật - trạng từ).
Dịch câu hỏi: Để duy trì tính bảo mật của khách hàng, việc hủy các tập tin cũ phải được thực hiện cẩn thận.
Dịch đáp án:
A. confiding (động từ -ing: đang tin tưởng)
B. confidential (tính từ: bảo mật)
C. confidentiality (danh từ: tính bảo mật)
D. confidentially (trạng từ: một cách bảo mật)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5216, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6511, 5216, 111, 'The new ---- of the Home Health smartphone application features a list of exercise tips for beginners.', 'version', 'aspect', 'route', 'term', 'A', 'Đáp án A (version) là đúng vì các lý do sau:
1. Cần một danh từ chỉ phiên bản mới của ứng dụng.
2. "Version" (phiên bản) là thuật ngữ phổ biến trong lĩnh vực phần mềm để chỉ một bản cập nhật mới.
3. Danh từ này thường được dùng khi nói về các phiên bản phần mềm khác nhau.
4. Các đáp án khác không phù hợp về nghĩa: "aspect" (khía cạnh), "route" (lộ trình), "term" (thuật ngữ).
Dịch câu hỏi: Phiên bản mới của ứng dụng điện thoại thông minh Home Health có danh sách các mẹo tập thể dục cho người mới bắt đầu.
Dịch đáp án:
A. version (danh từ: phiên bản)
B. aspect (danh từ: khía cạnh)
C. route (danh từ: lộ trình)
D. term (danh từ: thuật ngữ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5217, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6512, 5217, 112, 'Ms. Webster''s retirement party was attended by many coworkers and even several former students of -----.', 'she', 'her', 'hers', 'herself', 'C', 'Đáp án C (hers) là đúng vì các lý do sau:
1. Vị trí này cần một đại từ sở hữu độc lập để thay thế cho "her students".
2. "Hers" là đại từ sở hữu độc lập của "her", có thể đứng một mình mà không cần danh từ theo sau.
3. Cấu trúc "students of hers" là cách diễn đạt chuẩn để chỉ học sinh thuộc về cô ấy.
4. Các đáp án khác không phù hợp: "she" là đại từ chủ ngữ, "her" là tính từ sở hữu cần danh từ theo sau, "herself" là đại từ phản thân.
Dịch câu hỏi: Buổi tiệc nghỉ hưu của cô Webster có sự tham dự của nhiều đồng nghiệp và thậm chí cả một số cựu học sinh của cô ấy.
Dịch đáp án:
A. she (đại từ nhân xưng: cô ấy)
B. her (tính từ sở hữu: của cô ấy)
C. hers (đại từ sở hữu: của cô ấy)
D. herself (đại từ phản thân: bản thân cô ấy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5218, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6513, 5218, 113, 'Several canopies were set up at the outdoor concert site at Radner Park in ---- of the rain.', 'atmosphere', 'proportion', 'anticipation', 'limitation', 'C', 'Đáp án C (anticipation) là đúng vì các lý do sau:
1. Cần một danh từ để hoàn thành cụm "in ___ of" (để dự phòng cho).
2. "Anticipation" (sự dự đoán/phòng ngừa) là danh từ thích hợp trong ngữ cảnh chuẩn bị cho thời tiết xấu.
3. Cụm từ "in anticipation of" là cách diễn đạt chuẩn để chỉ việc chuẩn bị trước cho điều gì đó.
4. Các đáp án khác không phù hợp về nghĩa: "atmosphere" (bầu không khí), "proportion" (tỷ lệ), "limitation" (giới hạn).
Dịch câu hỏi: Một số mái che đã được dựng lên tại địa điểm tổ chức buổi hòa nhạc ngoài trời ở Công viên Radner để phòng khi trời mưa.
Dịch đáp án:
A. atmosphere (danh từ: bầu không khí)
B. proportion (danh từ: tỷ lệ)
C. anticipation (danh từ: sự dự đoán/phòng ngừa)
D. limitation (danh từ: giới hạn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5219, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6514, 5219, 114, 'Employees who are ----- for exceeding their output goals are more likely to maintain a high level of productivity.', 'rewarded', 'reward', 'rewarding', 'rewards', 'A', 'Đáp án A (rewarded) là đúng vì các lý do sau:
1. Cấu trúc này ở dạng bị động "are + quá khứ phân từ".
2. "Rewarded" (được thưởng) là dạng quá khứ phân từ của động từ "reward".
3. Ngữ cảnh nói về nhân viên được thưởng vì vượt chỉ tiêu sản lượng.
4. Các đáp án khác không phù hợp về ngữ pháp: "reward" là động từ nguyên mẫu, "rewarding" là hiện tại phân từ, "rewards" là danh từ số nhiều.
Dịch câu hỏi: Những nhân viên được thưởng vì vượt mục tiêu sản lượng có nhiều khả năng duy trì mức năng suất cao.
Dịch đáp án:
A. rewarded (quá khứ phân từ: được thưởng)
B. reward (động từ nguyên mẫu: thưởng)
C. rewarding (hiện tại phân từ: đang thưởng)
D. rewards (danh từ số nhiều: phần thưởng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5220, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6515, 5220, 115, 'The user manual warns customers to keep the phone away from radiators and ovens because its components are ----- to heat.', 'sensitive', 'familiar', 'released', 'considerable', 'A', 'Đáp án A (sensitive) là đúng vì các lý do sau:
1. Cần một tính từ theo sau động từ "be" để mô tả đặc tính của linh kiện.
2. "Sensitive to" là cụm từ cố định chỉ tính nhạy cảm với điều gì đó.
3. Trong ngữ cảnh này, "sensitive to heat" chỉ linh kiện dễ bị ảnh hưởng bởi nhiệt.
4. Các đáp án khác không phù hợp về nghĩa: "familiar" (quen thuộc), "released" (được phát hành), "considerable" (đáng kể).
Dịch câu hỏi: Sách hướng dẫn sử dụng cảnh báo khách hàng giữ điện thoại tránh xa lò sưởi và lò nướng vì các linh kiện của nó nhạy cảm với nhiệt.
Dịch đáp án:
A. sensitive (tính từ: nhạy cảm)
B. familiar (tính từ: quen thuộc)
C. released (quá khứ phân từ: được phát hành)
D. considerable (tính từ: đáng kể)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5221, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6516, 5221, 116, 'The prescription must be collected tomorrow because the pharmacy has ---- closed for the day.', 'yet', 'too', 'already', 'hardly', 'C', 'Đáp án C (already) là đúng vì các lý do sau:
1. Cần một trạng từ đi với thì hiện tại hoàn thành (has + p.p).
2. "Already" (đã) là trạng từ thích hợp để chỉ một hành động đã hoàn thành.
3. Vị trí của "already" trong câu là chuẩn: đặt giữa trợ động từ "has" và động từ chính "closed".
4. Các đáp án khác không phù hợp: "yet" thường dùng trong câu phủ định/câu hỏi, "too" (quá), "hardly" (hầu như không).
Dịch câu hỏi: Đơn thuốc phải được lấy vào ngày mai vì hiệu thuốc đã đóng cửa trong ngày hôm nay.
Dịch đáp án:
A. yet (trạng từ: chưa)
B. too (trạng từ: quá)
C. already (trạng từ: đã)
D. hardly (trạng từ: hầu như không)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5222, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6517, 5222, 117, 'The volume of disposable items is ---- despite concerns about the impact on the environment.', 'grows', 'growing', 'grow', 'grown', 'B', 'Đáp án B (growing) là đúng vì các lý do sau:
1. Cấu trúc "is + V-ing" là thì hiện tại tiếp diễn.
2. "Growing" (đang tăng) là dạng tiếp diễn của động từ "grow".
3. Ngữ cảnh cho thấy một xu hướng đang diễn ra liên tục.
4. Các đáp án khác không phù hợp về ngữ pháp: "grows" là động từ ngôi thứ 3 số ít, "grow" là động từ nguyên mẫu, "grown" là quá khứ phân từ.
Dịch câu hỏi: Khối lượng các vật dụng dùng một lần đang tăng lên bất chấp những lo ngại về tác động đến môi trường.
Dịch đáp án:
A. grows (động từ thì hiện tại: tăng)
B. growing (hiện tại phân từ: đang tăng)
C. grow (động từ nguyên mẫu: tăng)
D. grown (quá khứ phân từ: đã tăng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5223, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6518, 5223, 118, 'The opening of the community center was only possible through the public''s ---- support.', 'generous', 'identical', 'bright', 'spacious', 'A', 'Đáp án A (generous) là đúng vì các lý do sau:
1. Cần một tính từ để bổ nghĩa cho danh từ "support".
2. "Generous" (hào phóng/rộng rãi) là tính từ thích hợp để mô tả sự ủng hộ từ cộng đồng.
3. Collocation "generous support" là cụm từ phổ biến chỉ sự ủng hộ mạnh mẽ.
4. Các đáp án khác không phù hợp về nghĩa: "identical" (giống hệt), "bright" (sáng sủa), "spacious" (rộng rãi - về không gian).
Dịch câu hỏi: Việc khai trương trung tâm cộng đồng chỉ có thể thực hiện được thông qua sự ủng hộ hào phóng của công chúng.
Dịch đáp án:
A. generous (tính từ: hào phóng)
B. identical (tính từ: giống hệt)
C. bright (tính từ: sáng sủa)
D. spacious (tính từ: rộng rãi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5224, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6519, 5224, 119, 'The new yoga mat manufactured by Elita, Inc., maintains its shape even ----- many years of use.', 'against', 'up', 'after', 'without', 'C', 'Đáp án C (after) là đúng vì các lý do sau:
1. Cần một giới từ để chỉ thời gian/khoảng thời gian.
2. "After" (sau) là giới từ thích hợp để chỉ một khoảng thời gian sử dụng.
3. Cấu trúc "even after" (ngay cả sau) được dùng để nhấn mạnh khả năng duy trì hình dạng sau thời gian dài.
4. Các đáp án khác không phù hợp: "against" (chống lại), "up" (lên), "without" (không có).
Dịch câu hỏi: Thảm yoga mới được sản xuất bởi Elita, Inc., giữ được hình dạng của nó ngay cả sau nhiều năm sử dụng.
Dịch đáp án:
A. against (giới từ: chống lại)
B. up (giới từ: lên)
C. after (giới từ: sau)
D. without (giới từ: không có)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5225, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6520, 5225, 120, 'The manufacturer offers a standard warranty on the dryer —-- three years.', 'upon', 'toward', 'about', 'for', 'D', 'Đáp án D (for) là đúng vì các lý do sau:
1. Cần một giới từ chỉ khoảng thời gian bảo hành.
2. "For" là giới từ thích hợp để chỉ thời gian kéo dài của bảo hành.
3. Cấu trúc "warranty for + thời gian" là cách diễn đạt chuẩn trong ngữ cảnh bảo hành.
4. Các đáp án khác không phù hợp: "upon" (khi), "toward" (hướng về), "about" (khoảng).
Dịch câu hỏi: Nhà sản xuất cung cấp bảo hành tiêu chuẩn cho máy sấy trong ba năm.
Dịch đáp án:
A. upon (giới từ: khi)
B. toward (giới từ: hướng về)
C. about (giới từ: khoảng)
D. for (giới từ: trong/đối với)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5226, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6521, 5226, 121, 'Mr. Otis has the right ----- of people skills and career experience to succeed in the role.', 'remedy', 'sequence', 'improvement', 'combination', 'D', 'Đáp án D (combination) là đúng vì các lý do sau:
1. Cần một danh từ chỉ sự kết hợp của hai yếu tố: kỹ năng giao tiếp và kinh nghiệm nghề nghiệp.
2. "Combination" (sự kết hợp) là danh từ thích hợp để chỉ việc phối hợp các yếu tố khác nhau.
3. Cấu trúc "combination of A and B" là cách diễn đạt chuẩn để nói về sự kết hợp của hai yếu tố.
4. Các đáp án khác không phù hợp về nghĩa: "remedy" (giải pháp), "sequence" (trình tự), "improvement" (sự cải thiện).
Dịch câu hỏi: Ông Otis có sự kết hợp phù hợp giữa kỹ năng giao tiếp và kinh nghiệm nghề nghiệp để thành công trong vai trò này.
Dịch đáp án:
A. remedy (danh từ: giải pháp)
B. sequence (danh từ: trình tự)
C. improvement (danh từ: sự cải thiện)
D. combination (danh từ: sự kết hợp)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5227, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6522, 5227, 122, 'The focus of the board members is ----- investors react to the news of the CEO''s retirement.', 'among', 'who', 'where', 'how', 'D', 'Đáp án D (how) là đúng vì các lý do sau:
1. Cần một trạng từ nghi vấn để dẫn dắt mệnh đề dolí về cách thức phản ứng của các nhà đầu tư.
2. "How" (như thế nào/cách thức) là trạng từ thích hợp để hỏi về cách thức.
3. Cấu trúc "focus is + how + mệnh đề" là cách diễn đạt chuẩn để nói về trọng tâm chú ý đến cách thức.
4. Các đáp án khác không phù hợp: "among" (giữa), "who" (ai), "where" (ở đâu).
Dịch câu hỏi: Trọng tâm của các thành viên hội đồng quản trị là cách các nhà đầu tư phản ứng với tin tức về việc nghỉ hưu của CEO.
Dịch đáp án:
A. among (giới từ: giữa)
B. who (đại từ nghi vấn: ai)
C. where (trạng từ nghi vấn: ở đâu)
D. how (trạng từ nghi vấn: như thế nào)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5228, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6523, 5228, 123, 'The program coordinator asked staff to circulate the volunteer recruitment post ------ using their personal social media accounts.', 'widest', 'widen', 'wider', 'widely', 'D', 'Đáp án D (widely) là đúng vì các lý do sau:
1. Cần một trạng từ bổ nghĩa cho động từ "circulate".
2. "Widely" (rộng rãi) là trạng từ thích hợp để chỉ cách thức phân phát thông tin.
3. Trạng từ này được tạo thành bằng cách thêm "-ly" vào tính từ "wide".
4. Các đáp án khác không phù hợp: "widest" là tính từ so sánh nhất, "widen" là động từ, "wider" là tính từ so sánh hơn.
Dịch câu hỏi: Điều phối viên chương trình yêu cầu nhân viên phổ biến rộng rãi bài đăng tuyển tình nguyện viên bằng cách sử dụng tài khoản mạng xã hội cá nhân của họ.
Dịch đáp án:
A. widest (tính từ so sánh nhất: rộng nhất)
B. widen (động từ: mở rộng)
C. wider (tính từ so sánh hơn: rộng hơn)
D. widely (trạng từ: rộng rãi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5229, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6524, 5229, 124, 'For the safety of everyone in the building, the area around the fire exit must remain ----- clear at all times.', 'perfect', 'perfectly', 'perfection', 'perfected', 'B', 'Đáp án B (perfectly) là đúng vì các lý do sau:
1. Cần một trạng từ để bổ nghĩa cho tính từ "clear".
2. "Perfectly" (hoàn toàn) là trạng từ thích hợp để nhấn mạnh mức độ thông thoáng.
3. Trạng từ này được dùng để nhấn mạnh sự cần thiết của việc giữ lối thoát hiểm luôn thông thoáng.
4. Các đáp án khác không phù hợp: "perfect" là tính từ, "perfection" là danh từ, "perfected" là quá khứ phân từ.
Dịch câu hỏi: Vì sự an toàn của mọi người trong tòa nhà, khu vực xung quanh lối thoát hiểm phải luôn được giữ hoàn toàn thông thoáng.
Dịch đáp án:
A. perfect (tính từ: hoàn hảo)
B. perfectly (trạng từ: hoàn toàn)
C. perfection (danh từ: sự hoàn hảo)
D. perfected (quá khứ phân từ: đã hoàn thiện)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5230, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6525, 5230, 125, 'The architect''s drawings for the structure differ greatly from the building that -----.', 'is constructing', 'constructed', 'was constructed', 'has constructed', 'C', 'Đáp án C (was constructed) là đúng vì các lý do sau:
1. Cần một động từ ở thể bị động quá khứ để chỉ tòa nhà đã được xây dựng.
2. "Was constructed" là dạng bị động của động từ "construct" ở thì quá khứ đơn.
3. Cấu trúc bị động được dùng vì tòa nhà là đối tượng được xây dựng (không phải chủ thể xây dựng).
4. Các đáp án khác không phù hợp: "is constructing" là chủ động hiện tại tiếp diễn, "constructed" là quá khứ phân từ, "has constructed" là chủ động hiện tại hoàn thành.
Dịch câu hỏi: Bản vẽ của kiến trúc sư cho công trình khác nhiều so với tòa nhà đã được xây dựng.
Dịch đáp án:
A. is constructing (đang xây dựng)
B. constructed (đã xây dựng)
C. was constructed (đã được xây dựng)
D. has constructed (đã xây dựng - hiện tại hoàn thành)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5231, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6526, 5231, 126, 'Benjamin has chosen new videoconferencing software for the training he will ------ remotely.', 'appear', 'conduct', 'participate', 'instruct', 'B', 'Đáp án B (conduct) là đúng vì các lý do sau:
1. Cần một động từ chỉ hành động tổ chức/điều hành một khóa đào tạo.
2. "Conduct" (tiến hành/tổ chức) là động từ thích hợp khi nói về việc thực hiện một khóa đào tạo.
3. Trong ngữ cảnh này, Benjamin là người tổ chức khóa đào tạo, không phải người tham gia.
4. Các đáp án khác không phù hợp về nghĩa: "appear" (xuất hiện), "participate" (tham gia), "instruct" (hướng dẫn).
Dịch câu hỏi: Benjamin đã chọn phần mềm họp trực tuyến mới cho khóa đào tạo mà anh ấy sẽ tổ chức từ xa.
Dịch đáp án:
A. appear (động từ: xuất hiện)
B. conduct (động từ: tiến hành/tổ chức)
C. participate (động từ: tham gia)
D. instruct (động từ: hướng dẫn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5232, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6527, 5232, 127, '----- audience members arrive at the theater, an usher will direct them to the correct seats.', 'Since', 'Until', 'Next', 'Once', 'D', 'Đáp án D (Once) là đúng vì các lý do sau:
1. Cần một liên từ chỉ thời gian để nối hai sự kiện có quan hệ trước sau.
2. "Once" (một khi/ngay khi) là liên từ thích hợp để chỉ một hành động sẽ xảy ra ngay sau hành động khác.
3. Cấu trúc "Once + mệnh đề hiện tại, + mệnh đề tương lai" là cấu trúc chuẩn trong trường hợp này.
4. Các đáp án khác không phù hợp: "Since" (kể từ khi), "Until" (cho đến khi), "Next" (tiếp theo).
Dịch câu hỏi: Ngay khi khán giả đến nhà hát, nhân viên hướng dẫn sẽ chỉ dẫn họ đến đúng chỗ ngồi.
Dịch đáp án:
A. Since (liên từ: kể từ khi)
B. Until (liên từ: cho đến khi)
C. Next (phó từ: tiếp theo)
D. Once (liên từ: một khi/ngay khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5233, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6528, 5233, 128, 'Performers ----- from the competition are encouraged to stay and watch the remainder of the show.', 'eliminating', 'are eliminated', 'eliminated', 'that eliminate', 'C', 'Đáp án C (eliminated) là đúng vì các lý do sau:
1. Cần một quá khứ phân từ để tạo thành mệnh đề rút gọn có ý nghĩa bị động.
2. "Eliminated" (bị loại) là quá khứ phân từ của động từ "eliminate".
3. Cấu trúc này tương đương với "performers who are eliminated" (những người biểu diễn bị loại).
4. Các đáp án khác không phù hợp: "eliminating" là hiện tại phân từ chủ động, "are eliminated" là động từ bị động đầy đủ, "that eliminate" là mệnh đề quan hệ chủ động.
Dịch câu hỏi: Những người biểu diễn bị loại khỏi cuộc thi được khuyến khích ở lại và xem phần còn lại của chương trình.
Dịch đáp án:
A. eliminating (hiện tại phân từ: đang loại)
B. are eliminated (bị động hiện tại: bị loại)
C. eliminated (quá khứ phân từ: đã bị loại)
D. that eliminate (mệnh đề quan hệ: mà loại)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5234, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6529, 5234, 129, 'Many commuters are enjoying shorter driving times ----- the expansion of Highway 5 is completed.', 'together with', 'now that', 'because of', 'in case', 'B', 'Đáp án B (now that) là đúng vì các lý do sau:
1. Cần một cụm từ nối chỉ mối quan hệ nhân quả giữa hai sự việc.
2. "Now that" (giờ đây khi) là cụm từ thích hợp để chỉ một kết quả xảy ra sau khi một điều kiện được hoàn thành.
3. Cấu trúc "now that + mệnh đề" diễn tả một tình huống mới dẫn đến kết quả tức thì.
4. Các đáp án khác không phù hợp: "together with" (cùng với), "because of" (bởi vì), "in case" (phòng khi).
Dịch câu hỏi: Nhiều người đi làm đang được tận hưởng thời gian lái xe ngắn hơn khi việc mở rộng Đường cao tốc 5 đã hoàn thành.
Dịch đáp án:
A. together with (cụm giới từ: cùng với)
B. now that (cụm liên từ: giờ đây khi)
C. because of (cụm giới từ: bởi vì)
D. in case (cụm từ: phòng khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5235, 229, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6530, 5235, 130, 'At the Rockford Apartment Complex, tenants may have to pay a fee if they ------ their lease agreement without sufficient notice.', 'prohibit', 'obstruct', 'enclose', 'terminate', 'D', 'Đáp án D (terminate) là đúng vì các lý do sau:
1. Cần một động từ chỉ hành động chấm dứt hợp đồng thuê nhà.
2. "Terminate" (chấm dứt) là động từ chính xác trong ngữ cảnh pháp lý về hợp đồng.
3. Cụm từ "terminate a lease agreement" là thuật ngữ chuẩn trong lĩnh vực bất động sản.
4. Các đáp án khác không phù hợp về nghĩa: "prohibit" (cấm), "obstruct" (cản trở), "enclose" (đính kèm).
Dịch câu hỏi: Tại Khu căn hộ Rockford, người thuê có thể phải trả phí nếu họ chấm dứt hợp đồng thuê mà không thông báo đầy đủ.
Dịch đáp án:
A. prohibit (động từ: cấm)
B. obstruct (động từ: cản trở)
C. enclose (động từ: đính kèm)
D. terminate (động từ: chấm dứt).');;

-- Data for 2025 Test3 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5236, 230, NULL, NULL, 'To: All Urias Data Staff
From: Gabriella Shaw
Subject: Staff appreciation
Date: April 15
For Urias Data''s annual staff appreciation event, we will take a group hike at Walpole National Park during business hours on Friday, April 25. We hope everyone will come out to enjoy a fun day of 131....... and getting to know each other better. Veronica Erikson is organizing a carpool so that employees 132....... rides to the site. If you are one of the drivers, you will be reimbursed for the fuel that you use.
We know that some of you have heavy workloads right now. 133........, you should not assume that this means you will be unable to attend the event. 134........ . If you have concerns in this area, please bring them to your supervisor.', 'Gửi: Tất cả nhân viên Urias Data
Từ: Gabriella Shaw
Chủ đề: Đánh giá cao nhân viên
Ngày: 15 tháng 4
Cho sự kiện đánh giá cao nhân viên thường niên của Urias Data, chúng ta sẽ có một chuyến đi bộ đường dài theo nhóm tại Công viên Quốc gia Walpole trong giờ làm việc vào thứ Sáu, ngày 25 tháng 4. Chúng tôi hy vọng mọi người sẽ tham gia để tận hưởng một ngày vui vẻ với việc tập thể dục và hiểu nhau hơn. Veronica Erikson đang tổ chức đi chung xe để nhân viên có thể chia sẻ phương tiện đến địa điểm. Nếu bạn là một trong những người lái xe, bạn sẽ được hoàn trả chi phí nhiên liệu đã sử dụng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6531, 5236, 131, NULL, 'exercise', 'music', 'education', 'volunteering', 'A', 'A. exercise (tập thể dục)
B. music (âm nhạc)
C. education (giáo dục)
D. volunteering (tình nguyện)
Đáp án đúng là A (exercise).
Giải thích:
''Exercise'' phù hợp nhất vì:
- Phù hợp với hoạt động đi bộ đường dài (hike)
- Kết hợp hợp lý với mục đích giao lưu (getting to know each other better)
- Là hoạt động phổ biến trong các sự kiện team building
Các đáp án khác không phù hợp:
''Music'' không liên quan đến hoạt động đi bộ đường dài
''Education'' không phù hợp với tính chất giải trí của sự kiện
''Volunteering'' không phù hợp với ngữ cảnh về sự kiện gắn kết nhân viên');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6532, 5236, 132, NULL, 'who shared', 'sharing', 'shares', 'can share', 'D', 'A. who shared (người đã chia sẻ)
B. sharing (đang chia sẻ)
C. shares (chia sẻ)
D. can share (có thể chia sẻ)
Đáp án đúng là D (can share).
Giải thích:
''Can share'' phù hợp nhất vì:
- Diễn tả khả năng/cơ hội chia sẻ phương tiện
- Mô tả mục đích của việc tổ chức đi chung xe
- Phù hợp với tình huống đang được sắp xếp
Các đáp án khác không phù hợp:
''Who shared'' - quá khứ không phù hợp với sự kiện tương lai
''Sharing'' - không diễn tả đầy đủ ý nghĩa về khả năng
''Shares'' - không phù hợp về thời gian và nghĩa');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6533, 5236, 133, NULL, 'Furthermore', 'Likewise', 'However', 'Otherwise', 'C', 'A. Furthermore (hơn nữa)
B. Likewise (tương tự)
C. However (tuy nhiên)
D. Otherwise (nếu không)
Đáp án đúng là C (However).
Giải thích:
''However'' phù hợp nhất vì:
- Thể hiện sự đối lập giữa việc có nhiều việc và vẫn có thể tham dự
- Liên kết logic với câu trước về khối lượng công việc lớn
- Mở đầu cho giải pháp về vấn đề công việc
Các đáp án khác không phù hợp:
''Furthermore'' không thể hiện được sự đối lập
''Likewise'' không phù hợp vì không có sự tương đồng
''Otherwise'' không phù hợp với ngữ cảnh này');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6534, 5236, 134, NULL, 'One day will be subtracted from your allowance of paid leave.', 'It is likely that a make-up session will be scheduled soon.', 'The deadlines of non-urgent projects can be extended.', 'A variety of convenience facilities are available at the park.', 'C', 'A. One day will be subtracted from your allowance of paid leave. (Một ngày sẽ được trừ vào số ngày nghỉ phép có lương của bạn)
B. It is likely that a make-up session will be scheduled soon. (Có thể sẽ có một buổi bù được lên lịch sớm)
C. The deadlines of non-urgent projects can be extended. (Thời hạn của các dự án không khẩn cấp có thể được gia hạn)
D. A variety of convenience facilities are available at the park. (Có nhiều tiện nghi tại công viên)
Đáp án đúng là C.
Giải thích:
Câu C phù hợp nhất vì:
- Trực tiếp giải quyết vấn đề về khối lượng công việc
- Đưa ra giải pháp cụ thể cho những người bận rộn
- Liên kết logic với nội dung về việc không nên từ chối tham gia
Các đáp án khác không phù hợp:
A: Không phù hợp với tinh thần khuyến khích tham gia
B: Không liên quan đến vấn đề công việc hiện tại
D: Không liên quan đến vấn đề về thời gian và công việc');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5237, 230, NULL, NULL, 'My first impression of McVay Accountants was positive. A representative responded quickly after I filled out a contact form requesting help with my small business''s taxes. Nevertheless, I 135......... an appointment with the firm again. My experience was that they do not show enough concern for 136........ I found no fewer than three errors in the tax return my accountant prepared for me. 137...... . What is more, it took several rounds of discussion and resending of documents before he figured out the sources of the issues and fixed them. In the future, I plan to 138........ a firm based on a recommendation from a friend or associate.', 'Ấn tượng đầu tiên của tôi về McVay Accountants là tích cực. Một đại diện đã phản hồi nhanh chóng sau khi tôi điền vào biểu mẫu liên hệ yêu cầu trợ giúp về thuế của doanh nghiệp nhỏ của tôi. Tuy nhiên, tôi 135......... một cuộc hẹn với công ty một lần nữa. Kinh nghiệm của tôi là họ không thể hiện đủ sự quan tâm đến 136........ Tôi đã tìm thấy không dưới ba lỗi trong tờ khai thuế mà kế toán của tôi đã chuẩn bị cho tôi. 137...... . Hơn nữa, phải mất nhiều vòng thảo luận và gửi lại tài liệu trước khi anh ấy tìm ra nguồn gốc của các vấn đề và khắc phục chúng. Trong tương lai, tôi dự định 138....... một công ty dựa trên lời giới thiệu từ một người bạn hoặc cộng sự.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6535, 5237, 135, NULL, 'will not be booked', 'was not booked', 'will not be booking', 'might not have booked', 'C', 'A. will not be booked (sẽ không được đặt)
B. was not booked (đã không được đặt)
C. will not be booking (sẽ không đặt)
D. might not have booked (có thể đã không đặt)
Đáp án đúng là C (will not be booking).
Giải thích:
''Will not be booking'' phù hợp nhất vì:
- Diễn tả quyết định không sử dụng dịch vụ trong tương lai
- Thể hiện hành động chủ động của người viết
- Phù hợp với ngữ cảnh về kế hoạch tương lai
Các đáp án khác không phù hợp:
''Will not be booked'' - thể bị động không phù hợp
''Was not booked'' - thì quá khứ không phù hợp với ý định tương lai
''Might not have booked'' - không phù hợp với quyết định chắc chắn của người viết');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6536, 5237, 136, NULL, 'accuracy', 'privacy', 'communication', 'diversity', 'A', 'A. accuracy (sự chính xác)
B. privacy (quyền riêng tư)
C. communication (giao tiếp)
D. diversity (sự đa dạng)
Đáp án đúng là A (accuracy).
Giải thích:
''Accuracy'' phù hợp nhất vì:
- Liên quan trực tiếp đến vấn đề có nhiều lỗi trong tờ khai thuế
- Là yếu tố quan trọng nhất trong công việc kế toán
- Phù hợp với ngữ cảnh về sự thiếu chuyên nghiệp
Các đáp án khác không phù hợp:
''Privacy'' không liên quan đến vấn đề sai sót
''Communication'' không phải vấn đề chính được đề cập
''Diversity'' không liên quan đến ngữ cảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6537, 5237, 137, NULL, 'This kind of delay is unacceptable.', 'It turned out that he had misplaced them.', 'There must be a more secure way to share files.', 'One could have cost me thousands of dollars.', 'D', 'A. This kind of delay is unacceptable. (Sự chậm trễ như vậy là không thể chấp nhận được)
B. It turned out that he had misplaced them. (Hóa ra anh ấy đã làm thất lạc chúng)
C. There must be a more secure way to share files. (Phải có cách an toàn hơn để chia sẻ tệp)
D. One could have cost me thousands of dollars. (Một lỗi có thể khiến tôi mất hàng nghìn đô la)
Đáp án đúng là D.
Giải thích:
Câu D phù hợp nhất vì:
- Nhấn mạnh mức độ nghiêm trọng của các lỗi
- Giải thích lý do tại sao sự thiếu chính xác là vấn đề lớn
- Phù hợp với bối cảnh về thuế và tài chính
Các đáp án khác không phù hợp:
A: Tập trung vào vấn đề thời gian thay vì lỗi
B: Không liên quan đến vấn đề chính về sai sót
C: Không liên quan đến vấn đề về độ chính xác');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6538, 5237, 138, NULL, 'develop', 'launch', 'select', 'expand', 'C', 'A. develop (phát triển)
B. launch (khởi động)
C. select (lựa chọn)
D. expand (mở rộng)
Đáp án đúng là C (select).
Giải thích:
''Select'' phù hợp nhất vì:
- Diễn tả hành động chọn công ty mới dựa trên giới thiệu
- Phù hợp với kế hoạch tương lai đã nêu
- Liên kết logic với việc không hài lòng với công ty hiện tại
Các đáp án khác không phù hợp:
''Develop'' không phù hợp với ngữ cảnh tìm công ty mới
''Launch'' không phù hợp với vai trò khách hàng
''Expand'' không phù hợp với ý định thay đổi công ty');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5238, 230, NULL, NULL, 'To: Samantha Vanetten < samantha@vanettenconsulting.com>
From: Phillip Lee plee@monroe-solutions.com
Subject: Inquiry
Date: March 2
Attachment: Monroe_Solutions
Dear, Ms. Vanetten,
I recently received a 139..... from my company for your seminar on establishing relationships with clients. I was initially hesitant about the event. This is because the content of other seminars I''ve attended has been either too basic or too technical. 140....... . Your talk was perfect for someone of my experience level. Our firm is interested in hiring you for a private session at our company. 141........ . Please let me know if you are available. I have attached a brochure 142........ our company''s services.
Warmest regards,
Phillip Lee', 'Gửi đến: Samantha Vanetten < samantha@vanettenconsulting.com>
Từ: Phillip Lee plee@monroe-solutions.com
Chủ đề: Yêu cầu
Ngày: 2 tháng 3
Đính kèm: Monroe_Solutions
Kính gửi, cô Vanetten,
Gần đây tôi đã nhận được 139..... từ công ty của tôi cho hội thảo của bạn về việc thiết lập mối quan hệ với khách hàng. Ban đầu tôi đã do dự về sự kiện này. Điều này là do nội dung của các hội thảo khác mà tôi đã tham dự hoặc quá cơ bản hoặc quá kỹ thuật. 140....... . Bài nói chuyện của bạn thật hoàn hảo cho một người có trình độ kinh nghiệm của tôi. Công ty chúng tôi quan tâm đến việc thuê bạn cho một phiên riêng tư tại công ty của chúng tôi. 141......... . Vui lòng cho tôi biết nếu bạn rảnh. Tôi đã đính kèm một tài liệu quảng cáo 142........ các dịch vụ của công ty chúng tôi.
Trân trọng nhất,
Phillip Lee');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6539, 5238, 139, NULL, 'deposit', 'subscription', 'ticket', 'venture', 'C', 'A. deposit (tiền đặt cọc)
B. subscription (đăng ký)
C. ticket (vé)
D. venture (mạo hiểm)
Đáp án đúng là C (ticket).
Giải thích:
''Ticket'' phù hợp nhất vì:
- Phù hợp với việc tham dự seminar
- Thường được công ty cung cấp cho nhân viên
- Phù hợp với ngữ cảnh về sự kiện đào tạo
Các đáp án khác không phù hợp:
''Deposit'' không phù hợp với việc tham dự hội thảo
''Subscription'' không phù hợp với sự kiện một lần
''Venture'' không liên quan đến ngữ cảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6540, 5238, 140, NULL, 'In other words', 'For instance', 'In contrast', 'To that end', 'C', 'A. In other words (nói cách khác)
B. For instance (ví dụ)
C. In contrast (ngược lại)
D. To that end (để đạt được điều đó)
Đáp án đúng là C (In contrast).
Giải thích:
''In contrast'' phù hợp nhất vì:
- Thể hiện sự đối lập giữa các hội thảo trước và hội thảo này
- Dẫn dắt đến nhận xét tích cực về hội thảo
- Kết nối logic giữa trải nghiệm không tốt trước đây và trải nghiệm tốt hiện tại
Các đáp án khác không phù hợp:
''In other words'' không thể hiện được sự đối lập
''For instance'' không phù hợp vì không đưa ra ví dụ
''To that end'' không phù hợp với ngữ cảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6541, 5238, 141, NULL, 'I hope that you found my suggestions helpful.', 'All thirty of our salespeople would be in attendance.', 'The auditorium''s sound system was also impressive.', 'We have received fewer client complaints since then.', 'B', 'A. I hope that you found my suggestions helpful. (Tôi hy vọng bạn thấy những gợi ý của tôi hữu ích)
B. All thirty of our salespeople would be in attendance. (Tất cả ba mươi nhân viên bán hàng của chúng tôi sẽ tham dự)
C. The auditorium''s sound system was also impressive. (Hệ thống âm thanh của hội trường cũng ấn tượng)
D. We have received fewer client complaints since then. (Chúng tôi đã nhận được ít khiếu nại của khách hàng hơn kể từ đó)
Đáp án đúng là B.
Giải thích:
Câu B phù hợp nhất vì:
- Cung cấp thông tin quan trọng về số lượng người tham dự
- Liên quan đến đề nghị thuê cho buổi đào tạo riêng
- Phù hợp với mục đích thư là thu xếp một buổi đào tạo cho công ty
Các đáp án khác không phù hợp:
A: Không phù hợp với vai trò người viết thư
C: Không liên quan đến mục đích chính của thư
D: Không phù hợp với thời điểm hiện tại');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6542, 5238, 142, NULL, 'being outlined', 'outlined these', 'is outlining', 'that outlines', 'D', 'A. being outlined (đang được phác thảo)
B. outlined these (đã phác thảo những)
C. is outlining (đang phác thảo)
D. that outlines (mô tả)
Đáp án đúng là D (that outlines).
Giải thích:
''That outlines'' phù hợp nhất vì:
- Là mệnh đề quan hệ bổ nghĩa cho ''brochure''
- Cấu trúc ngữ pháp đúng: danh từ + that + động từ
- Diễn tả mục đích của tài liệu đính kèm
Các đáp án khác không phù hợp:
''Being outlined'' - thể bị động không phù hợp
''Outlined these'' - cấu trúc ngữ pháp không đúng
''Is outlining'' - thì hiện tại tiếp diễn không phù hợp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5239, 230, NULL, NULL, 'The DC Analytics management team is aware that some files were permanently erased due to the recent system malfunction. We ask that you back up your work to external hard drives regularly. This will help us avoid a similar 143...... in the future.
Unfortunately, we are unable to use automatic cloud storage due to security issues. 144...... . You can sign up by contacting the IT office on extension 14. Each day at 4:45 P.M., the IT team 145....... an e-mail with a reminder about file backups. If this is too frequent for you, you can arrange 146...... the messages on a weekly basis instead.', 'Nhóm quản lý DC Analytics nhận thức được rằng một số tệp đã bị xóa vĩnh viễn do sự cố hệ thống gần đây. Chúng tôi yêu cầu bạn thường xuyên sao lưu công việc của mình vào ổ cứng ngoài. Điều này sẽ giúp chúng tôi tránh được 143...... tương tự trong tương lai.
Thật không may, chúng tôi không thể sử dụng lưu trữ đám mây tự động do các vấn đề bảo mật. 144...... . Bạn có thể đăng ký bằng cách liên hệ với văn phòng CNTT theo số máy lẻ 14. Mỗi ngày vào lúc 4:45 chiều, nhóm CNTT 145....... một e-mail nhắc nhở về việc sao lưu tệp. Nếu điều này quá thường xuyên đối với bạn, bạn có thể sắp xếp 146...... các tin nhắn hàng tuần để thay thế.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6543, 5239, 143, NULL, 'delay', 'loss', 'expense', 'importance', 'B', 'A. delay (sự chậm trễ)
B. loss (sự mất mát)
C. expense (chi phí)
D. importance (tầm quan trọng)
Đáp án đúng là B (loss).
Giải thích:
''Loss'' phù hợp nhất vì:
- Liên quan trực tiếp đến việc mất dữ liệu đã đề cập
- Phù hợp với ngữ cảnh về sao lưu để tránh mất dữ liệu
- Là hậu quả chính của sự cố hệ thống
Các đáp án khác không phù hợp:
''Delay'' không phản ánh mức độ nghiêm trọng của vấn đề
''Expense'' không liên quan đến vấn đề mất dữ liệu
''Importance'' không phù hợp với ngữ cảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6544, 5239, 144, NULL, 'Therefore, we are offering an alert system to help you remember.', 'Do not share these files with unauthorized personnel.', 'We will give a demonstration on how to use it next week.', 'Of course, your home computer uses the same software.', 'A', 'A. Therefore, we are offering an alert system to help you remember. (Do đó, chúng tôi đang cung cấp một hệ thống cảnh báo để giúp bạn nhớ)
B. Do not share these files with unauthorized personnel. (Không chia sẻ các tệp này với nhân viên không được phép)
C. We will give a demonstration on how to use it next week. (Chúng tôi sẽ hướng dẫn cách sử dụng nó vào tuần sau)
D. Of course, your home computer uses the same software. (Tất nhiên, máy tính ở nhà của bạn sử dụng cùng một phần mềm)
Đáp án đúng là A.
Giải thích:
Câu A phù hợp nhất vì:
- Kết nối logic với vấn đề không thể sử dụng cloud storage
- Đưa ra giải pháp thay thế
- Dẫn dắt đến thông tin về hệ thống nhắc nhở
Các đáp án khác không phù hợp:
B: Không liên quan đến vấn đề sao lưu
C: Chưa phù hợp về mặt thời gian
D: Không liên quan đến giải pháp được đề xuất');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6545, 5239, 145, NULL, 'sent', 'had been sending', 'will send', 'has sent', 'C', 'A. sent (đã gửi)
B. had been sending (đã đang gửi)
C. will send (sẽ gửi)
D. has sent (đã gửi)
Đáp án đúng là C (will send).
Giải thích:
''Will send'' phù hợp nhất vì:
- Diễn tả một kế hoạch/quy trình trong tương lai
- Phù hợp với việc mô tả hệ thống nhắc nhở mới
- Liên quan đến thời gian cụ thể hàng ngày (4:45 P.M.)
Các đáp án khác không phù hợp:
''Sent'' - quá khứ đơn không phù hợp với kế hoạch tương lai
''Had been sending'' - quá khứ hoàn thành tiếp diễn không phù hợp
''Has sent'' - hiện tại hoàn thành không phù hợp với kế hoạch tương lai');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6546, 5239, 146, NULL, 'receivable', 'receipt', 'receiving', 'to receive', 'D', 'A. receivable (có thể nhận)
B. receipt (biên nhận)
C. receiving (đang nhận)
D. to receive (nhận)
Đáp án đúng là D (to receive).
Giải thích:
''To receive'' phù hợp nhất vì:
- Cấu trúc ''arrange to do something'' là cụm động từ phổ biến
- Động từ nguyên mẫu phù hợp sau ''arrange''
- Diễn tả mục đích của việc sắp xếp
Các đáp án khác không phù hợp:
''Receivable'' là tính từ, không phù hợp
''Receipt'' là danh từ, không phù hợp
''Receiving'' dạng -ing không phù hợp sau ''arrange''');;

-- Data for 2025 Test3 Part 7
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5240, 231, NULL, NULL, 'Try our new product!
A Great way to Save Time
With its stainless-steel finish and hidden control panel, the Kemper 25 is an elegant addition to any household. It can wash a full load in as little as one hour—no more waiting for clean dishes! In addition to this speedy "One-Hour" setting, the Kemper 25 offers a "Normal" setting with high water efficiency, and a "Heavy" setting useful for items like greasy pots and pans. No matter which setting you choose, the heated drying system ensures your dishes will be table-ready at the end of the cycle. Even large dishes such as serving platters can be cleaned with ease thanks to the Kemper 25''s removable top rack. Visit your local Kemper dealership to learn more!', 'Hãy thử sản phẩm mới của chúng tôi!
Một cách tuyệt vời để tiết kiệm thời gian
Với lớp hoàn thiện bằng thép không gỉ và bảng điều khiển ẩn, Kemper 25 là một sự bổ sung sang trọng cho bất kỳ gia đình nào. Nó có thể giặt một mẻ đầy chỉ trong vòng một giờ - không còn phải đợi chờ bát đĩa sạch nữa! Ngoài cài đặt "Một giờ" nhanh chóng này, Kemper 25 còn cung cấp cài đặt "Bình thường" với hiệu suất nước cao và cài đặt "Nặng" hữu ích cho các vật dụng như nồi chảo có dầu mỡ. Bất kể bạn chọn cài đặt nào, hệ thống sấy khô bằng nhiệt đảm bảo bát đĩa của bạn sẽ sẵn sàng để lên bàn vào cuối chu kỳ. Thậm chí các món đồ lớn như đĩa phục vụ cũng có thể được làm sạch dễ dàng nhờ giá trên có thể tháo rời của Kemper 25. Hãy ghé thăm đại lý Kemper tại địa phương của bạn để tìm hiểu thêm!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6547, 5240, 147, 'What is the product description about?', 'An item of clothing', 'A kitchen appliance', 'A vacuum cleaner', 'A fitness machine', 'B', 'Đáp án đúng là B.
Giải thích:
Văn bản chứa nhiều chi tiết cụ thể về một thiết bị nhà bếp - máy rửa bát Kemper 25.
Bằng chứng 1: "wash a full load" và "clean dishes" - chức năng rửa bát đĩa.
Bằng chứng 2: "One-Hour setting", "Normal setting", "Heavy setting" - các chế độ rửa khác nhau.
Bằng chứng 3: "heated drying system" - hệ thống sấy khô, một tính năng đặc trưng của máy rửa bát.
Bằng chứng 4: "removable top rack" - giá để bát trên có thể tháo rời.
Bằng chứng 5: "serving platters" - khả năng rửa các đĩa lớn.
Tất cả các đặc điểm này là đặc trưng của một thiết bị nhà bếp, cụ thể là máy rửa bát.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Bài mô tả sản phẩm này nói về cái gì?
A. Một món đồ quần áo (danh từ chỉ vật dụng)
B. Một thiết bị nhà bếp (danh từ chỉ thiết bị)
C. Một máy hút bụi (danh từ chỉ thiết bị)
D. Một máy tập thể dục (danh từ chỉ thiết bị)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6548, 5240, 148, 'What is indicated about the product?', 'It is easy to keep clean', 'It uses energy efficiently', 'It has multiple noise settings', 'It has an adjustable structure', 'D', 'Đáp án đúng là D.
Giải thích:
Đoạn văn chỉ ra rõ ràng rằng sản phẩm có cấu trúc có thể điều chỉnh được.
Bằng chứng trực tiếp: "removable top rack" (giá trên có thể tháo rời).
Lời giải chi tiết:
1. Tính năng này được nhấn mạnh khi nói về khả năng rửa "large dishes such as serving platters" (các món đồ lớn như đĩa phục vụ).
2. Việc có thể tháo rời giá trên cho thấy cấu trúc linh hoạt, có thể điều chỉnh để phù hợp với các nhu cầu khác nhau.
3. Không có đề cập nào về độ ồn (loại trừ C).
4. Không có thông tin về hiệu quả năng lượng (loại trừ B).
5. Không đề cập đến việc dễ vệ sinh (loại trừ A).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về sản phẩm?
A. Nó dễ dàng giữ sạch (cụm từ mô tả tính chất)
B. Nó sử dụng năng lượng hiệu quả (cụm từ mô tả hiệu suất)
C. Nó có nhiều cài đặt độ ồn (cụm từ chỉ tính năng)
D. Nó có cấu trúc có thể điều chỉnh (cụm từ chỉ đặc điểm cấu tạo)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5241, 231, NULL, NULL, 'Bennett Mobile: Reimbursement Request Form Instructions
1. Write your name and employee number at the top of the form.
2. For each listed item, write a brief note about the reason for the spending.
3. Staple the relevant receipts to the form.
4. Have your manager sign the form and sign it yourself as well. Unsigned requests will not be processed.
5. To have the payment appear on your monthly paycheck on the 25th, submit the form by the 15th of the month.
If you make frequent purchases, you may be eligible to receive a credit card under Bennett Mobile''s account. Speak to the finance team to request approval.', 'Bennett Mobile: Hướng dẫn mẫu đơn yêu cầu hoàn tiền
1. Viết tên và số nhân viên của bạn ở đầu mẫu đơn.
2. Đối với mỗi mục được liệt kê, viết một ghi chú ngắn về lý do chi tiêu.
3. Ghim các biên lai liên quan vào mẫu đơn.
4. Yêu cầu người quản lý ký vào mẫu đơn và bạn cũng phải ký nữa. Các yêu cầu không có chữ ký sẽ không được xử lý.
5. Để khoản thanh toán xuất hiện trên phiếu lương hàng tháng vào ngày 25, hãy nộp mẫu đơn trước ngày 15 của tháng.
Nếu bạn thường xuyên mua sắm, bạn có thể đủ điều kiện nhận thẻ tín dụng theo tài khoản của Bennett Mobile. Hãy nói chuyện với nhóm tài chính để yêu cầu phê duyệt.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6549, 5241, 149, 'According to the instructions, what must be included on the form?', 'The employee''s phone number', 'The signature of a supervisor', 'A department number', 'A copy of an ID card', 'B', 'Đáp án đúng là B.
Giải thích:
Hướng dẫn nêu rõ yêu cầu bắt buộc về chữ ký của người giám sát.
Phân tích chi tiết:
1. Bằng chứng trực tiếp từ điểm 4: "Have your manager sign the form and sign it yourself as well."
2. Mức độ quan trọng được nhấn mạnh: "Unsigned requests will not be processed."
3. Các yêu cầu khác được liệt kê bao gồm:
   - Tên và số nhân viên (không phải số điện thoại)
   - Ghi chú về lý do chi tiêu
   - Đính kèm biên lai
4. Không có yêu cầu nào về:
   - Số điện thoại nhân viên (loại trừ A)
   - Số phòng ban (loại trừ C)
   - Bản sao thẻ ID (loại trừ D)

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo hướng dẫn, điều gì phải được bao gồm trong mẫu đơn?
A. Số điện thoại của nhân viên (danh từ chỉ thông tin liên lạc)
B. Chữ ký của người giám sát (danh từ chỉ xác nhận)
C. Số phòng ban (danh từ chỉ đơn vị)
D. Bản sao thẻ ID (danh từ chỉ giấy tờ)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6550, 5241, 150, 'What is indicated about the finance team members?', 'They can issue company credit cards', 'They need the form by the 25th of every month', 'They must approve all purchases in advance', 'They have recently changed a policy', 'A', 'Đáp án đúng là A.
Giải thích:
Văn bản chỉ ra rõ về quyền hạn của nhóm tài chính trong việc cấp thẻ tín dụng công ty.
Phân tích chi tiết:
1. Bằng chứng trực tiếp: "Speak to the finance team to request approval" cho việc nhận thẻ tín dụng công ty.
2. Bối cảnh: Việc này liên quan đến "receive a credit card under Bennett Mobile''s account".
3. Điều kiện tiên quyết: "If you make frequent purchases" - chỉ dành cho người thường xuyên mua sắm.
4. Các phương án khác không được đề cập:
   - Không có thông tin về việc cần mẫu đơn vào ngày 25 (loại trừ B)
   - Không đề cập đến việc phê duyệt trước mọi khoản mua (loại trừ C)
   - Không có thông tin về thay đổi chính sách (loại trừ D)

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về các thành viên nhóm tài chính?
A. Họ có thể cấp thẻ tín dụng công ty (cụm động từ chỉ quyền hạn)
B. Họ cần mẫu đơn vào ngày 25 hàng tháng (cụm từ chỉ thời hạn)
C. Họ phải phê duyệt tất cả các khoản mua trước (cụm động từ chỉ trách nhiệm)
D. Họ gần đây đã thay đổi một chính sách (cụm động từ chỉ hành động)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5242, 231, NULL, NULL, 'Receipt of Cash
No: 013394 Date: December 6
Recipient Details
Name: Thea Lemke
Department: Engineering
Extension: 345
Amount Dispensed: $150
Description: Meal allowance for a business trip to Atlanta (December 8-10) to perform the inspection of the Cayce Building and surrounding grounds.
Approved by: Steven Rivera
I agree that the above details are correct and that I have received the specified amount. I understand that I must provide records showing how it is spent and return any unused portions to the company.
Signature:
Thea Lemke', 'Biên lai tiền mặt
Số: 013394 Ngày: 6 tháng 12
Thông tin người nhận
Tên: Thea Lemke
Phòng ban: Kỹ thuật
Số máy lẻ: 345
Số tiền chi: $150
Mô tả: Phụ cấp ăn uống cho chuyến công tác đến Atlanta (8-10 tháng 12) để thực hiện việc kiểm tra Tòa nhà Cayce và khu vực xung quanh.
Phê duyệt bởi: Steven Rivera
Tôi đồng ý rằng các chi tiết trên là chính xác và tôi đã nhận được số tiền được chỉ định. Tôi hiểu rằng tôi phải cung cấp hồ sơ cho thấy cách chi tiêu và hoàn trả mọi phần không sử dụng cho công ty.
Chữ ký:
Thea Lemke');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6551, 5242, 151, 'What does Ms. Lemke plan to do in Atlanta?', 'Inspect a building', 'Negotiate a contract', 'Apply for a loan', 'Demonstrate a product', 'A', 'Đáp án đúng là A.
Giải thích:
Bằng chứng từ phần Description: "to perform the inspection of the Cayce Building and surrounding grounds".
Chuyến đi diễn ra từ 8-10/12.
Chi phí được cấp: $150 cho phụ cấp ăn uống.
Không có thông tin về đàm phán hợp đồng (B), nộp đơn vay (C), hay giới thiệu sản phẩm (D).
Phù hợp với việc Ms. Lemke thuộc phòng Kỹ thuật (Engineering).
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Lemke dự định làm gì ở Atlanta?
A. Kiểm tra một tòa nhà (cụm động từ chỉ nhiệm vụ kiểm tra)
B. Đàm phán một hợp đồng (cụm động từ chỉ hoạt động thương mại)
C. Nộp đơn xin vay (cụm động từ chỉ hoạt động tài chính)
D. Giới thiệu một sản phẩm (cụm động từ chỉ hoạt động marketing)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6552, 5242, 152, 'What does the receipt confirm?', 'Ms. Lemke''s enrollment in an association', 'Issuance of funds to Ms. Lemke', 'Ms. Lemke''s purchase of travel tickets', 'The loaning of equipment to Ms. Lemke', 'B', 'Đáp án đúng là B.
Giải thích:
Bằng chứng từ văn bản:
"Receipt of Cash" (Biên lai tiền mặt)
"Amount Dispensed: $150" (Số tiền chi: $150)
Xác nhận: "I have received the specified amount" (Tôi đã nhận được số tiền được chỉ định)
Không đề cập đến ghi danh hiệp hội (A), mua vé (C), hay mượn thiết bị (D).
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Biên lai xác nhận điều gì?
A. Việc Ms. Lemke ghi danh vào một hiệp hội (cụm danh từ chỉ hoạt động đăng ký)
B. Việc cấp phát tiền cho Ms. Lemke (cụm danh từ chỉ giao dịch tài chính)
C. Việc Ms. Lemke mua vé đi lại (cụm danh từ chỉ hoạt động mua sắm)
D. Việc cho Ms. Lemke mượn thiết bị (cụm danh từ chỉ hoạt động cho mượn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5243, 231, NULL, NULL, 'Nina Simpson [9:37 A.M.]
Hi, Anthony. Do we know what''s going on with the brand strategist position yet? I''ve had a few follow-up inquiries from the candidates we screened.
Anthony Winslow [9:38 A.M.]
I just spoke with Florence Gracey, the head of the marketing department. She doesn''t have time to sit down with everyone who passed the phone screen because she''ll be away on a business trip next week. So she wants to meet with them all at once.
Nina Simpson [9:39 A.M.]
Really? I don''t think that''s a good idea. It would be difficult to compare their answers to our questions, because some candidates would have extra time to come up with good responses. It would be better to put the process on hold for that week.
Anthony Winslow 9:40 A.M.]
That''s true. I''ll talk to Florence again and see how strongly she feels about her idea.', 'Nina Simpson [9:37 A.M.]
Chào Anthony. Chúng ta đã biết gì về vị trí chiến lược gia thương hiệu chưa? Tôi đã nhận được một số câu hỏi theo dõi từ các ứng viên mà chúng ta đã sàng lọc.
Anthony Winslow [9:38 A.M.]
Tôi vừa nói chuyện với Florence Gracey, trưởng phòng marketing. Cô ấy không có thời gian gặp riêng từng người đã vượt qua vòng phỏng vấn điện thoại vì cô ấy sẽ đi công tác vào tuần tới. Vì vậy cô ấy muốn gặp tất cả họ cùng một lúc.
Nina Simpson [9:39 A.M.]
Thật sao? Tôi không nghĩ đó là một ý kiến hay. Sẽ khó so sánh câu trả lời của họ cho các câu hỏi của chúng ta, vì một số ứng viên sẽ có thêm thời gian để nghĩ ra câu trả lời tốt. Tốt hơn là tạm dừng quy trình trong tuần đó.
Anthony Winslow [9:40 A.M.]
Đúng vậy. Tôi sẽ nói chuyện với Florence lần nữa và xem cô ấy nghĩ sao về ý tưởng của mình.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6553, 5243, 153, 'What does Ms. Gracey want to do?', 'Hold a group interview', 'Postpone her business trip', 'Hire a temporary worker', 'Take a marketing course', 'A', 'Đáp án đúng là A.
Giải thích:
Bằng chứng trực tiếp: "She wants to meet with them all at once"
Lý do: Không có thời gian gặp riêng từng người vì sắp đi công tác
Nina phản đối vì lo ngại về tính công bằng trong so sánh câu trả lời
Không đề cập đến hoãn công tác (B), thuê người tạm thời (C), hay học marketing (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Gracey muốn làm gì?
A. Tổ chức một cuộc phỏng vấn nhóm (cụm danh từ chỉ hoạt động tuyển dụng)
B. Hoãn chuyến công tác của cô ấy (cụm động từ chỉ thay đổi lịch trình)
C. Thuê một nhân viên tạm thời (cụm động từ chỉ hoạt động tuyển dụng)
D. Tham gia một khóa học marketing (cụm động từ chỉ hoạt động đào tạo)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6554, 5243, 154, 'At 9:40 A.M., what does Mr. Winslow most likely mean when he writes, "That''s true"?', 'He knows that a decision is not up to him', 'He agrees that Ms. Gracey has a busy schedule', 'He shares Ms. Simpson''s opinion of a job candidate', 'He thinks a hiring process should be paused', 'D', 'Đáp án đúng là D.
Giải thích:
Bằng chứng: Mr. Winslow nói "That''s true" ngay sau khi Nina đề xuất "put the process on hold"
He đồng ý với ý kiến tạm dừng quy trình tuyển dụng của Nina
Không liên quan đến quyền quyết định (A), lịch bận rộn của Ms. Gracey (B), hay ý kiến về ứng viên cụ thể (C)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 9:40 A.M., Mr. Winslow có ý gì khi viết "That''s true"?
A. Anh ấy biết rằng quyết định không phụ thuộc vào anh ấy (cụm động từ chỉ nhận thức)
B. Anh ấy đồng ý rằng Ms. Gracey có lịch trình bận rộn (cụm động từ chỉ sự đồng tình)
C. Anh ấy chia sẻ ý kiến của Ms. Simpson về một ứng viên (cụm động từ chỉ quan điểm)
D. Anh ấy nghĩ một quy trình tuyển dụng nên được tạm dừng (cụm động từ chỉ đề xuất)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5244, 231, NULL, NULL, 'VANDIVIA
Your gateway to freshness
New owner-operator Ernesto Stewart welcomes you to Vandivia!
Fresh Food
We grow delicious, organic produce for fine-dining restaurants, high-end supermarkets, and more. A new batch of free samples is offered every hour. At the end of your visit, don''t forget to take some more goodies home to cook with!
Fresh Air
Visitors are encouraged to join the bicycle tour of our grounds led by one of our employees. Take in our rustic architecture and the enticing scents of our vegetable patches and fruit orchards. The tour lasts about two hours and bicycles are provided.
Fresh Ideas
Vandivia holds daily workshops on growing herbs and organic gardening in our big red barn. Visitors may also be able to arrange a workshop on vegetarian cooking with Mr. Stewart, an award-winning chef, depending on his schedule.
The entrance fee is $20 per person and covers all the activities listed above. Our location is rather remote, so we recommend that drivers use a satellite navigation system to find us. Alternatively, we offer a $5 round-trip shuttle service from Wadena Station.
Visit www.vandivia.com for more information.', 'VANDIVIA
Cổng vào sự tươi mới của bạn
Chủ sở hữu - người điều hành mới Ernesto Stewart chào đón bạn đến với Vandivia!
Thực phẩm tươi
Chúng tôi trồng các sản phẩm hữu cơ ngon lành cho các nhà hàng cao cấp, siêu thị cao cấp và hơn thế nữa. Một loạt mẫu thử miễn phí mới được cung cấp mỗi giờ. Vào cuối chuyến thăm của bạn, đừng quên mang về nhà thêm một số món ngon để nấu ăn!
Không khí trong lành
Khách tham quan được khuyến khích tham gia tour xe đạp tham quan khuôn viên của chúng tôi do một trong những nhân viên của chúng tôi dẫn dắt. Hãy chiêm ngưỡng kiến trúc mộc mạc và hương thơm quyến rũ của các mảnh vườn rau và vườn cây ăn quả của chúng tôi. Tour kéo dài khoảng hai giờ và xe đạp được cung cấp.
Ý tưởng mới
Vandivia tổ chức các hội thảo hàng ngày về trồng thảo mộc và làm vườn hữu cơ trong nhà kho đỏ lớn của chúng tôi. Khách tham quan cũng có thể sắp xếp một hội thảo về nấu ăn chay với ông Stewart, một đầu bếp từng đoạt giải thưởng, tùy thuộc vào lịch trình của ông.
Phí vào cửa là 20$ mỗi người và bao gồm tất cả các hoạt động được liệt kê ở trên. Địa điểm của chúng tôi khá xa, vì vậy chúng tôi khuyên người lái xe nên sử dụng hệ thống dẫn đường vệ tinh để tìm chúng tôi. Ngoài ra, chúng tôi cung cấp dịch vụ đưa đón khứ hồi 5$ từ Ga Wadena.
Truy cập www.vandivia.com để biết thêm thông tin.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6555, 5244, 155, 'What most likely is Vandivia?', 'A farm', 'A restaurant', 'A beach resort', 'A national park', 'A', 'Đáp án đúng là A.
Giải thích:
Bằng chứng từ văn bản: "We grow delicious, organic produce" và "vegetable patches and fruit orchards"
Có các hoạt động điển hình của trang trại:
- Tour tham quan khu đất và vườn cây
- Hội thảo về trồng thảo mộc và làm vườn hữu cơ
- Cung cấp sản phẩm cho nhà hàng và siêu thị
Không phải nhà hàng (B), khu nghỉ dưỡng (C) hay công viên quốc gia (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Vandivia nhiều khả năng là gì?
A. Một trang trại (danh từ chỉ địa điểm nông nghiệp)
B. Một nhà hàng (danh từ chỉ địa điểm kinh doanh)
C. Một khu nghỉ dưỡng bãi biển (cụm danh từ chỉ địa điểm du lịch)
D. Một công viên quốc gia (cụm danh từ chỉ địa điểm công cộng)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6556, 5244, 156, 'What is indicated about Vandivia?', 'It has increased the charge for entry', 'It has been nominated for an award', 'It rents satellite navigation systems', 'It is under new management', 'D', 'Đáp án đúng là D.
Giải thích:
Bằng chứng trực tiếp từ đầu văn bản: "New owner-operator Ernesto Stewart welcomes you to Vandivia!"
Chứng tỏ Vandivia đang được quản lý bởi chủ sở hữu mới
Không có thông tin về:
- Tăng phí vào cửa (A)
- Được đề cử giải thưởng (B)
- Cho thuê hệ thống định vị (C)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Vandivia?
A. Nó đã tăng phí vào cửa (cụm động từ chỉ thay đổi giá)
B. Nó đã được đề cử giải thưởng (cụm động từ chỉ thành tích)
C. Nó cho thuê hệ thống định vị vệ tinh (cụm động từ chỉ dịch vụ)
D. Nó đang được quản lý mới (cụm động từ chỉ sự thay đổi quản lý)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6557, 5244, 157, 'What is available for an additional fee?', 'Transportation to a site', 'Product samples', 'Bicycle tours', 'Educational workshops', 'A', 'Đáp án đúng là A.
Giải thích:
Bằng chứng từ văn bản: "$5 round-trip shuttle service from Wadena Station"
Các dịch vụ khác đều miễn phí trong phí vào cửa $20:
- Mẫu sản phẩm (free samples)
- Tour xe đạp (bicycles are provided)
- Hội thảo (included in entrance fee)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì có sẵn với phí bổ sung?
A. Phương tiện đến địa điểm (cụm danh từ chỉ dịch vụ vận chuyển)
B. Mẫu sản phẩm (cụm danh từ chỉ hàng mẫu)
C. Tour xe đạp (cụm danh từ chỉ hoạt động tham quan)
D. Hội thảo giáo dục (cụm danh từ chỉ hoạt động học tập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5245, 231, NULL, NULL, 'MEMO
To: Coffee Max Staff
From: Adriana Clawson
Date: October 20
Subject: Special drinks
Dear Staff,
The holiday season is approaching! To get into the spirit and hopefully boost sales, I want to offer a temporary menu of holiday-themed drinks to Coffee Max customers.
Please help with this project by using the café''s slow periods to try to come up with a delicious and unique coffee drink. If you succeed, send me an e-mail outlining the ingredients and how to make it.
I will choose three drinks for our special menu. If yours is chosen, you will receive a $50 gift certificate to Eva Department Store, so you can shop right across the street before or after work.
The deadline for submissions is the end of the day on Sunday, October 30, and there are a few extra considerations to keep in mind. The drinks should not use too many costly ingredients, and if there are any ingredients that might be dangerous for customers with food allergies, include suggestions for substitutions. In addition, our staff must be able to make each drink quickly.
Thank you!
Adriana', 'MEMO
Đến: Nhân viên Coffee Max
Từ: Adriana Clawson
Ngày: 20 tháng 10
Chủ đề: Đồ uống đặc biệt
Nhân viên thân mến,
Mùa lễ hội đang đến gần! Để hòa vào không khí và hy vọng tăng doanh số, tôi muốn cung cấp một thực đơn tạm thời các đồ uống theo chủ đề ngày lễ cho khách hàng Coffee Max.
Vui lòng giúp dự án này bằng cách sử dụng thời gian vắng khách của quán để thử nghĩ ra một đồ uống cà phê ngon và độc đáo. Nếu thành công, hãy gửi cho tôi một email nêu rõ các thành phần và cách làm.
Tôi sẽ chọn ba đồ uống cho thực đơn đặc biệt của chúng ta. Nếu đồ uống của bạn được chọn, bạn sẽ nhận được phiếu quà tặng trị giá 50$ tại Cửa hàng Eva Department Store, vì vậy bạn có thể mua sắm ngay bên kia đường trước hoặc sau giờ làm việc.
Hạn chót nộp bài là cuối ngày Chủ nhật, 30 tháng 10, và có một vài cân nhắc bổ sung cần ghi nhớ. Đồ uống không nên sử dụng quá nhiều thành phần đắt tiền, và nếu có bất kỳ thành phần nào có thể nguy hiểm cho khách hàng bị dị ứng thực phẩm, hãy đưa ra đề xuất thay thế. Ngoài ra, nhân viên của chúng ta phải có khả năng làm mỗi đồ uống một cách nhanh chóng.
Cảm ơn!
Adriana');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6558, 5245, 158, 'Why was the memo written?', 'To describe changes to a drinks menu', 'To request recipe ideas from staff', 'To ask for referrals for temporary workers', 'To announce a holiday party', 'B', 'Đáp án đúng là B.
Giải thích:
Bằng chứng trực tiếp: "Please help... try to come up with a delicious and unique coffee drink"
Mục đích: Thu thập công thức đồ uống từ nhân viên cho thực đơn dịp lễ
Không phải để:
- Mô tả thay đổi thực đơn (A)
- Yêu cầu giới thiệu nhân viên tạm thời (C)
- Thông báo tiệc lễ (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tại sao bản ghi nhớ được viết?
A. Để mô tả các thay đổi đối với thực đơn đồ uống (cụm động từ chỉ mục đích thông báo)
B. Để yêu cầu ý tưởng công thức từ nhân viên (cụm động từ chỉ mục đích thu thập)
C. Để yêu cầu giới thiệu nhân viên tạm thời (cụm động từ chỉ mục đích tuyển dụng)
D. Để thông báo một bữa tiệc lễ (cụm động từ chỉ mục đích tổ chức)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6559, 5245, 159, 'What is indicated about Eva Department Store?', 'It is within walking distance of Coffee Max', 'It is holding a sales event', 'It gives discounts to Coffee Max employees', 'It will open its own coffee shop', 'A', 'Đáp án đúng là A.
Giải thích:
Bằng chứng từ văn bản: "shop right across the street before or after work"
Chỉ ra vị trí của Eva Department Store ngay đối diện Coffee Max
Không có thông tin về:
- Sự kiện giảm giá (B)
- Giảm giá cho nhân viên Coffee Max (C)
- Mở quán cà phê riêng (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Eva Department Store?
A. Nó nằm trong khoảng cách đi bộ từ Coffee Max (cụm động từ chỉ vị trí)
B. Nó đang tổ chức sự kiện giảm giá (cụm động từ chỉ hoạt động kinh doanh)
C. Nó giảm giá cho nhân viên Coffee Max (cụm động từ chỉ chính sách)
D. Nó sẽ mở quán cà phê riêng (cụm động từ chỉ kế hoạch)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6560, 5245, 160, 'What is NOT mentioned as a characteristic of some drinks?', 'They can be prepared in a short time', 'They are inexpensive to make', 'They do not include allergens', 'They share a seasonal theme', 'C', 'Đáp án đúng là C.
Giải thích:
Văn bản đề cập các đặc điểm:
- Thời gian pha chế nhanh: "make each drink quickly" (A)
- Chi phí thấp: "not use too many costly ingredients" (B)
- Theo chủ đề mùa: "holiday-themed drinks" (D)
Không đề cập việc không chứa chất gây dị ứng, chỉ yêu cầu có phương án thay thế: "include suggestions for substitutions"
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG được đề cập như một đặc điểm của một số đồ uống?
A. Chúng có thể được pha chế trong thời gian ngắn (cụm động từ chỉ tính chất)
B. Chúng không tốn kém để làm (cụm động từ chỉ chi phí)
C. Chúng không chứa chất gây dị ứng (cụm động từ chỉ thành phần)
D. Chúng có chung chủ đề theo mùa (cụm động từ chỉ đặc điểm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5246, 231, NULL, NULL, 'From: Krista Nocera
To: All Staff
Date: February 11
Re: Flooring
Dear Staff,
A crew from Trevino Contractors will visit our office this weekend to renovate the main hallway. — [1] -. Because of the location of the work, it won''t be necessary to move furniture or personal belongings in your office or other shared rooms. — [21 —.
However, if you need to work over the weekend, we ask that you do so remotely.
We understand that some of you need specialized software to complete your tasks, so please see David Rogowski in the IT department to request the use of a company laptop. - [3] -. If you plan to work late on Friday, please let the security team know if your car is by the Boyd Street entrance. - 14] -. The crew needs the first row of the lot clear to unload their materials on Saturday morning.
Thank you for your cooperation!
Krista Nocera', 'Từ: Krista Nocera
Đến: Tất cả nhân viên
Ngày: 11 tháng 2
Về: Sàn nhà
Nhân viên thân mến,
Một đội từ Nhà thầu Trevino sẽ đến văn phòng chúng ta cuối tuần này để cải tạo hành lang chính. — [1] -. Do vị trí công việc, sẽ không cần thiết phải di chuyển đồ đạc hoặc vật dụng cá nhân trong văn phòng của bạn hoặc các phòng chung khác. — [21 —.
Tuy nhiên, nếu bạn cần làm việc vào cuối tuần, chúng tôi yêu cầu bạn làm việc từ xa.
Chúng tôi hiểu rằng một số bạn cần phần mềm chuyên dụng để hoàn thành công việc, vì vậy vui lòng gặp David Rogowski ở phòng IT để yêu cầu sử dụng laptop của công ty. - [3] -. Nếu bạn dự định làm việc muộn vào thứ Sáu, vui lòng cho đội bảo vệ biết nếu xe của bạn đang ở lối vào đường Boyd. - 14] -. Đội thi công cần hàng đầu tiên của bãi đỗ xe trống để dỡ vật liệu vào sáng thứ Bảy.
Cảm ơn sự hợp tác của bạn!
Krista Nocera');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6561, 5246, 161, 'What should employees speak to Mr. Rogowski about?', 'Storing some personal items', 'Getting a software upgrade', 'Moving to a new office', 'Borrowing some equipment', 'D', 'Đáp án đúng là D.
Giải thích:
Bằng chứng từ văn bản: "see David Rogowski in the IT department to request the use of a company laptop"
Yêu cầu nhân viên gặp Mr. Rogowski để mượn laptop công ty khi cần làm việc từ xa
Không liên quan đến:
- Cất giữ đồ cá nhân (A)
- Nâng cấp phần mềm (B)
- Chuyển văn phòng (C)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Nhân viên nên nói chuyện với Mr. Rogowski về việc gì?
A. Cất giữ một số vật dụng cá nhân (cụm danh từ chỉ hoạt động bảo quản)
B. Nhận bản nâng cấp phần mềm (cụm danh từ chỉ hoạt động cập nhật)
C. Chuyển đến văn phòng mới (cụm động từ chỉ sự thay đổi)
D. Mượn một số thiết bị (cụm động từ chỉ hoạt động mượn đồ)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6562, 5246, 162, 'What is suggested about the Boyd Street entrance?', 'It will be locked by the security team', 'It faces heavy traffic', 'It is near a parking area', 'It has the building''s largest doors', 'C', 'Đáp án đúng là C.
Giải thích:
Bằng chứng từ văn bản:
"If your car is by the Boyd Street entrance"
"The crew needs the first row of the lot clear"
Những câu này chỉ ra rằng lối vào Boyd Street gần khu vực đỗ xe
Không có thông tin về:
- Việc khóa cửa (A)
- Tình trạng giao thông (B)
- Kích thước cửa (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về lối vào đường Boyd?
A. Nó sẽ bị khóa bởi đội bảo vệ (cụm động từ chỉ hành động)
B. Nó đối diện giao thông đông đúc (cụm động từ chỉ vị trí)
C. Nó ở gần khu vực đỗ xe (cụm động từ chỉ vị trí)
D. Nó có cửa lớn nhất của tòa nhà (cụm động từ chỉ đặc điểm)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6563, 5246, 163, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "The flooring will be replaced, and the walls will be repainted."', '[1]', '[2]', '[3]', '[4]', 'A', 'Đáp án đúng là A.
Giải thích:
Câu "The flooring will be replaced, and the walls will be repainted" nên được đặt ở vị trí [1] vì:
1. Nó mô tả chi tiết công việc sẽ được thực hiện ngay sau câu giới thiệu về việc đội thầu sẽ đến cải tạo
2. Nó cung cấp thông tin nền tảng trước khi đề cập đến việc không cần di chuyển đồ đạc
3. Các vị trí [2], [3], [4] không phù hợp vì sẽ làm gián đoạn luồng thông tin về hướng dẫn làm việc từ xa
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Câu "Sàn nhà sẽ được thay thế, và tường sẽ được sơn lại" phù hợp nhất với vị trí nào trong số các vị trí được đánh dấu [1], [2], [3] và [4]?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5247, 231, NULL, NULL, 'Springdale Connects
Are you a fashion designer? Use your talent to support your local community!
Springdale Connects, a locally based nonprofit organization, is holding a fashion show at the historic Medlin Theater to raise project funds. You can help by designing and sewing a special outfit for the event using the theme "Timeless Classics"
Tickets to the fashion show will be sold on our Web site and at various businesses throughout Springdale. The proceeds from the event will be used to purchase guitars, keyboards, trumpets, and more to be given to elderly people living in Springdale to form the town''s first-ever senior citizen band. This can help participants to learn a new skill and meet new people.
If you''d like to participate, please visit our Web site at www.springdaleconnects.org to find out the required submission date, the suggested clothing size, and a list of the accessories we can provide. There you can also submit a brief biography including your work and experience. This will be printed on the flyer that will be distributed to audience members when they arrive.', 'Springdale Kết nối
Bạn là nhà thiết kế thời trang? Hãy sử dụng tài năng của bạn để hỗ trợ cộng đồng địa phương!
Springdale Connects, một tổ chức phi lợi nhuận tại địa phương, đang tổ chức một buổi trình diễn thời trang tại Nhà hát Medlin lịch sử để gây quỹ cho dự án. Bạn có thể giúp bằng cách thiết kế và may một bộ trang phục đặc biệt cho sự kiện với chủ đề "Cổ điển Vượt thời gian"
Vé xem show thời trang sẽ được bán trên trang web của chúng tôi và tại các doanh nghiệp khắp Springdale. Số tiền thu được từ sự kiện sẽ được dùng để mua guitar, keyboard, kèn trumpet và nhiều nhạc cụ khác để tặng cho người cao tuổi sống tại Springdale để thành lập ban nhạc người cao tuổi đầu tiên của thị trấn. Điều này có thể giúp người tham gia học một kỹ năng mới và gặp gỡ những người mới.
Nếu bạn muốn tham gia, vui lòng truy cập trang web của chúng tôi tại www.springdaleconnects.org để tìm hiểu ngày nộp bài yêu cầu, kích thước quần áo được đề xuất và danh sách phụ kiện chúng tôi có thể cung cấp. Tại đó bạn cũng có thể gửi tiểu sử ngắn gọn bao gồm công việc và kinh nghiệm của bạn. Điều này sẽ được in trên tờ rơi sẽ được phát cho khán giả khi họ đến.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6564, 5247, 164, 'What does the notice ask people to do?', 'Provide items for a fundraising event', 'Become a member of a charity', 'Volunteer to set up a venue', 'Donate money to an organization', 'A', 'Đáp án đúng là A.
Giải thích:
Thông báo yêu cầu các nhà thiết kế thời trang "designing and sewing a special outfit" cho sự kiện gây quỹ
Cụ thể là show diễn thời trang tại nhà hát Medlin
Mục đích gây quỹ để mua nhạc cụ cho ban nhạc người cao tuổi
Không đề cập đến việc tham gia tổ chức từ thiện (B), tình nguyện viên (C) hay quyên góp tiền (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Thông báo yêu cầu mọi người làm gì?
A. Cung cấp vật phẩm cho sự kiện gây quỹ (cụm động từ chỉ hành động đóng góp)
B. Trở thành thành viên của tổ chức từ thiện (cụm động từ chỉ tư cách)
C. Tình nguyện thiết lập địa điểm (cụm động từ chỉ hoạt động hỗ trợ)
D. Quyên góp tiền cho một tổ chức (cụm động từ chỉ hoạt động tài chính)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6565, 5247, 165, 'What does Springdale Connects aim to do?', 'Host free fashion design courses', 'Help to restore a historic theater', 'Prepare and serve meals to elderly residents', 'Provide musical instruments to community members', 'D', 'Đáp án đúng là D.
Giải thích:
Mục tiêu rõ ràng trong văn bản: "purchase guitars, keyboards, trumpets... to be given to elderly people... to form the town''s first-ever senior citizen band"
Không phải tổ chức khóa học thời trang (A), phục hồi nhà hát (B) hay phục vụ bữa ăn (C)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Springdale Connects nhằm làm gì?
A. Tổ chức các khóa học thiết kế thời trang miễn phí (cụm động từ chỉ hoạt động đào tạo)
B. Giúp phục hồi một nhà hát lịch sử (cụm động từ chỉ hoạt động bảo tồn)
C. Chuẩn bị và phục vụ bữa ăn cho người cao tuổi (cụm động từ chỉ hoạt động phục vụ)
D. Cung cấp nhạc cụ cho thành viên cộng đồng (cụm động từ chỉ hoạt động hỗ trợ)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6566, 5247, 166, 'What is NOT indicated as information provided on the Web site?', 'A photo gallery', 'A deadline', 'Details on available accessories', 'Sizing recommendations', 'A', 'Đáp án đúng là A.
Giải thích:
Thông tin trên website bao gồm:
- Deadline: "required submission date"
- Chi tiết phụ kiện: "list of the accessories we can provide"
- Khuyến nghị size: "suggested clothing size"
Không đề cập đến thư viện ảnh
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG được chỉ ra là thông tin được cung cấp trên trang web?
A. Thư viện ảnh (cụm danh từ chỉ bộ sưu tập)
B. Thời hạn (danh từ chỉ mốc thời gian)
C. Chi tiết về phụ kiện có sẵn (cụm danh từ chỉ thông tin)
D. Khuyến nghị về kích cỡ (cụm danh từ chỉ hướng dẫn)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6567, 5247, 167, 'According to the notice, where will participants'' biographies be seen?', 'In an online newsletter', 'On a handout', 'On a Web site', 'On a notice in the lobby', 'B', 'Đáp án đúng là B.
Giải thích:
Văn bản nêu rõ: "printed on the flyer that will be distributed to audience members when they arrive"
Flyer (tờ rơi) là một dạng handout (tài liệu phát tay)
Không phải trên bản tin online (A), website (C) hay thông báo ở sảnh (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo thông báo, tiểu sử của người tham gia sẽ được thấy ở đâu?
A. Trong bản tin trực tuyến (cụm danh từ chỉ phương tiện)
B. Trên tài liệu phát tay (cụm danh từ chỉ vật phẩm)
C. Trên trang web (cụm danh từ chỉ nền tảng)
D. Trên thông báo ở sảnh (cụm danh từ chỉ vị trí)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5248, 231, NULL, NULL, 'Charles Vaughn [1:22 p.M.]
Good afternoon, everyone. I wanted to let you know that I still don''t have any news on the Hogan Tech event.
Heather Dengler [1:23 P.M.]
Nico Apparel wants to hire us for that same day.
Charles Vaughn [1:25 P.M.]
Then we''ll need to find out whether Hogan Tech has plans. We don''t have enough cooks and servers to do both. Hogan Tech is a bigger order, but I''d hate to turn down another client until we know for certain what''s going on.
Heather Dengler [1:26 p.M.]
I promised Nico Apparel that we would confirm either way by the end of the day.
Charles Vaughn [1:27 P.M.]
I see. I tried to get in touch with Daniel Garrett at Hogan Tech, but there was no answer at his office. Do we have another phone number for him?
Natasha Kopp [1:28 P.M.]
I''ve never needed one before. I''ll look into that.
Charles Vaughn [1:31 P.M.]
If we end up accepting the job from Nico Apparel, we''ll have to get the pricing estimate ready right away. We don''t want to seem disorganized. Heather, I''d like you to do that.
Natasha Kopp [1:34 p.M.]
Got it. I''ve forwarded that to you, Charles.
Charles Vaughn [1:42 P.M.]
Mr. Garrett said they''ve decided to use a different company instead. While he liked our menu suggestions, they wanted to use a company that specializes in vegetarian dishes. So, Heather, can you send me a finished file by 3 p.м.?
Heather Dengler [1:43 p.M.]
Yes, that''ll be enough time if I start now.', 'Charles Vaughn [1:22 chiều]
Chào buổi chiều mọi người. Tôi muốn cho các bạn biết rằng tôi vẫn chưa có tin tức gì về sự kiện của Hogan Tech.
Heather Dengler [1:23 chiều]
Nico Apparel muốn thuê chúng ta cho cùng ngày đó.
Charles Vaughn [1:25 chiều]
Vậy chúng ta cần tìm hiểu xem Hogan Tech có kế hoạch gì không. Chúng ta không có đủ đầu bếp và phục vụ để làm cả hai. Hogan Tech là đơn hàng lớn hơn, nhưng tôi không muốn từ chối một khách hàng khác cho đến khi chúng ta biết chắc chắn chuyện gì đang xảy ra.
Heather Dengler [1:26 chiều]
Tôi đã hứa với Nico Apparel rằng chúng ta sẽ xác nhận theo cách nào đó vào cuối ngày.
Charles Vaughn [1:27 chiều]
Tôi hiểu rồi. Tôi đã cố gắng liên lạc với Daniel Garrett tại Hogan Tech, nhưng không có ai trả lời tại văn phòng của anh ấy. Chúng ta có số điện thoại nào khác của anh ấy không?
Natasha Kopp [1:28 chiều]
Tôi chưa bao giờ cần một số nào khác trước đây. Tôi sẽ tìm hiểu điều đó.
Charles Vaughn [1:31 chiều]
Nếu chúng ta cuối cùng chấp nhận công việc từ Nico Apparel, chúng ta sẽ phải chuẩn bị báo giá ngay lập tức. Chúng ta không muốn có vẻ thiếu tổ chức. Heather, tôi muốn bạn làm điều đó.
Natasha Kopp [1:34 chiều]
Hiểu rồi. Tôi đã chuyển tiếp điều đó cho anh, Charles.
Charles Vaughn [1:42 chiều]
Ông Garrett nói họ đã quyết định sử dụng một công ty khác. Mặc dù ông ấy thích các đề xuất thực đơn của chúng ta, họ muốn sử dụng một công ty chuyên về các món chay. Vậy, Heather, bạn có thể gửi cho tôi file hoàn chỉnh trước 3 giờ chiều không?
Heather Dengler [1:43 chiều]
Vâng, sẽ đủ thời gian nếu tôi bắt đầu ngay bây giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6568, 5248, 168, 'Where most likely do the writers work?', 'At a catering company', 'At a graphic design firm', 'At a technology firm', 'At a clothing manufacturer', 'A', 'Đáp án đúng là A.
Giải thích:
Nhiều chi tiết chỉ ra đây là công ty cung cấp dịch vụ ẩm thực:
- Đề cập đến "cooks and servers"
- Thảo luận về "menu suggestions"
- Khách hàng chọn công ty khác vì "specializes in vegetarian dishes"
Không phải công ty thiết kế (B), công nghệ (C) hay sản xuất quần áo (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Những người viết nhiều khả năng làm việc ở đâu?
A. Tại một công ty cung cấp dịch vụ ăn uống (cụm danh từ chỉ loại hình doanh nghiệp)
B. Tại một công ty thiết kế đồ họa (cụm danh từ chỉ loại hình doanh nghiệp)
C. Tại một công ty công nghệ (cụm danh từ chỉ loại hình doanh nghiệp)
D. Tại một nhà sản xuất quần áo (cụm danh từ chỉ loại hình doanh nghiệp)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6569, 5248, 169, 'At 1:28 p.M., what does Ms. Kopp mean when she writes, "I''ll look into that"?', 'She will try to schedule a client visit', 'She will check a meeting space''s availability', 'She will search for some contact information', 'She will inquire about a fee', 'C', 'Đáp án đúng là C.
Giải thích:
Trước đó Charles hỏi "Do we have another phone number for him?"
Ms. Kopp trả lời "I''ll look into that" nghĩa là sẽ tìm số liên lạc khác
Không liên quan đến lịch hẹn (A), phòng họp (B) hay phí (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 1:28 chiều, Ms. Kopp có ý gì khi viết "I''ll look into that"?
A. Cô ấy sẽ cố gắng sắp xếp cuộc gặp khách hàng (cụm động từ chỉ hoạt động)
B. Cô ấy sẽ kiểm tra tình trạng phòng họp (cụm động từ chỉ việc xác minh)
C. Cô ấy sẽ tìm kiếm thông tin liên lạc (cụm động từ chỉ việc tìm kiếm)
D. Cô ấy sẽ hỏi về một khoản phí (cụm động từ chỉ việc thắc mắc)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6570, 5248, 170, 'What does Mr. Vaughn tell the other writers about?', 'When to arrive for an event', 'Why a decision was made', 'Who is representing Nico Apparel', 'Where to file a report', 'B', 'Đáp án đúng là B.
Giải thích:
Mr. Vaughn giải thích quyết định của Hogan Tech: "they''ve decided to use a different company... they wanted to use a company that specializes in vegetarian dishes"
Không liên quan đến thời gian đến (A), đại diện Nico Apparel (C), hay nơi nộp báo cáo (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mr. Vaughn nói với các nhân viên khác về điều gì?
A. Khi nào đến dự sự kiện (cụm từ chỉ thời gian)
B. Tại sao một quyết định được đưa ra (cụm từ chỉ lý do)
C. Ai đang đại diện cho Nico Apparel (cụm từ chỉ nhân sự)
D. Nơi nộp báo cáo (cụm từ chỉ địa điểm)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6571, 5248, 171, 'What will Ms. Dengler most likely do next?', 'Update a Web site', 'Prepare an estimate', 'Find a new supplier', 'Speak to Mr. Garrett', 'B', 'Đáp án đúng là B.
Giải thích:
Mr. Vaughn yêu cầu: "get the pricing estimate ready"
Ms. Dengler đồng ý làm ngay: "that''ll be enough time if I start now"
Không liên quan đến cập nhật website (A), tìm nhà cung cấp (C) hay nói chuyện với Mr. Garrett (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Dengler nhiều khả năng sẽ làm gì tiếp theo?
A. Cập nhật trang web (cụm động từ chỉ hoạt động kỹ thuật)
B. Chuẩn bị báo giá (cụm động từ chỉ hoạt động kinh doanh)
C. Tìm nhà cung cấp mới (cụm động từ chỉ hoạt động tìm kiếm)
D. Nói chuyện với ông Garrett (cụm động từ chỉ hoạt động giao tiếp)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5249, 231, NULL, NULL, 'Bulk of Difficult Sewer
Improvement Project Finished
STENDHAM (September 25)- Yesterday, the city of Stendham announced the conclusion of the first phase of the Lundgate Shore project.
Located on the west bank of the Garmine River, the shore is named for nearby Lundgate Bridge. The covered waterways that now sit there will stop excess sewage from spilling into the river by redirecting it into Clearway, Stendham''s enormous "sewage highway". — [1] —. The smooth completion of the phase is remarkable given the complex feats of engineering that were involved.
The most challenging part was the installation of the 3,700-tonne main channel. The Lundgate Shore is in a tidal area, and the river covers it completely at high tide. Bauright Group, the company responsible for Phase 1, decided to make use of this feature and float the pre-built channel into place. — [2] - "We had successfully used tidewater to move structures in other Clearway projects," Bauright chief engineer Nancy Majors explained. Still, the method required precise timing. The channel had to pass under Lundgate Bridge, so it could not be moved during high tide. - [3] -. On the other hand, if the move was done when the water level was too low, the channel might not float all the way to its correct position. Ms. Majors said her team completed the difficult task without incident thanks to "extremely careful planning."
Yesterday''s announcement also revealed that the simpler second phase of the project, which will be handled by Perriott, LLC, will end in November. — [4] —. Perriott will add a walking path, benches, and greenery to the public land above the new sewer structures.', 'Phần lớn hệ thống thoát nước khó khăn
Dự án cải tiến đã hoàn thành
STENDHAM (25 tháng 9)- Hôm qua, thành phố Stendham đã công bố kết thúc giai đoạn đầu tiên của dự án Lundgate Shore.
Nằm ở bờ tây của sông Garmine, bờ biển được đặt tên theo Cầu Lundgate gần đó. Các tuyến đường thủy có mái che hiện đang nằm ở đó sẽ ngăn nước thải dư thừa tràn ra sông bằng cách chuyển hướng nó vào Clearway, "đường cao tốc nước thải" khổng lồ của Stendham. — [1] —. Việc hoàn thành suôn sẻ của giai đoạn này là đáng chú ý với những kỳ công phức tạp của kỹ thuật liên quan.
Phần khó khăn nhất là lắp đặt kênh chính nặng 3.700 tấn. Bờ Lundgate nằm trong khu vực thủy triều, và dòng sông bao phủ hoàn toàn khi thủy triều lên. Bauright Group, công ty chịu trách nhiệm về Giai đoạn 1, đã quyết định sử dụng tính năng này và thả kênh được xây dựng sẵn vào vị trí. — [2] - "Chúng tôi đã sử dụng thành công nước thủy triều để di chuyển các cấu trúc trong các dự án Clearway khác", kỹ sư trưởng của Bauright Nancy Majors giải thích. Tuy nhiên, phương pháp này yêu cầu thời gian chính xác. Kênh phải đi qua dưới Cầu Lundgate, vì vậy nó không thể di chuyển khi thủy triều lên cao. - [3] -. Mặt khác, nếu việc di chuyển được thực hiện khi mực nước quá thấp, kênh có thể không nổi hết đến đúng vị trí của nó. Bà Majors cho biết nhóm của bà đã hoàn thành nhiệm vụ khó khăn mà không gặp sự cố nào nhờ "lập kế hoạch cực kỳ cẩn thận."
Thông báo ngày hôm qua cũng tiết lộ rằng giai đoạn thứ hai đơn giản hơn của dự án, sẽ do Perriott, LLC xử lý, sẽ kết thúc vào tháng 11. — [4] —. Perriott sẽ thêm một lối đi bộ, băng ghế và cây xanh vào đất công cộng phía trên các cấu trúc cống rãnh mới.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6572, 5249, 172, 'What problem is the Lundgate Shore project most likely intended to address?', 'Pollution of a river by wastewater', 'Excessive traffic on a highway', 'The deterioration of an old bridge', 'A lack of sewer service to some homes', 'A', 'Đáp án đúng là A.
Giải thích:
Văn bản chỉ ra vấn đề ô nhiễm sông do nước thải: "stop excess sewage from spilling into the river"
Giải pháp: chuyển hướng nước thải vào "sewage highway"
Không liên quan đến kẹt xe (B), cầu cũ (C) hay thiếu dịch vụ thoát nước (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Dự án Lundgate Shore nhiều khả năng nhằm giải quyết vấn đề gì?
A. Ô nhiễm sông do nước thải (cụm danh từ chỉ vấn đề môi trường)
B. Giao thông quá tải trên đường cao tốc (cụm danh từ chỉ vấn đề giao thông)
C. Sự xuống cấp của một cây cầu cũ (cụm danh từ chỉ vấn đề cơ sở hạ tầng)
D. Thiếu dịch vụ thoát nước cho một số nhà (cụm danh từ chỉ vấn đề dịch vụ)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6573, 5249, 173, 'What is suggested by Ms. Majors?', 'She often works on oceanfront structures', 'She was promoted due to her contributions to Clearway''s construction', 'She has overseen the largest project she has ever', 'She based a decision about the Lundgate Shore on past experiences', 'D', 'Đáp án đúng là D.
Giải thích:
Ms. Majors nói: "We had successfully used tidewater to move structures in other Clearway projects"
Chỉ ra quyết định sử dụng thủy triều dựa trên kinh nghiệm trước đây
Không đề cập đến việc thường xuyên làm việc với công trình ven biển (A), được thăng chức (B) hay đây là dự án lớn nhất (C)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý bởi Ms. Majors?
A. Cô ấy thường xuyên làm việc với các công trình ven biển (cụm động từ chỉ thói quen)
B. Cô ấy được thăng chức nhờ đóng góp vào việc xây dựng Clearway (cụm động từ chỉ thành tích)
C. Cô ấy đã giám sát dự án lớn nhất từ trước đến nay (cụm động từ chỉ quy mô)
D. Cô ấy đã đưa ra quyết định về Lundgate Shore dựa trên kinh nghiệm trước đây (cụm động từ chỉ cơ sở quyết định)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6574, 5249, 174, 'What is indicated about Perriot, LLC?', 'It is owned by Bauright Group', 'It will create a public leisure area', 'It is running behind schedule', 'It submitted a bid to carry out Phase 1', 'B', 'Đáp án đúng là B.
Giải thích:
Theo văn bản: "Perriott will add a walking path, benches, and greenery to the public land"
Đây là việc tạo không gian công cộng giải trí
Không có thông tin về việc thuộc Bauright Group (A), chậm tiến độ (C) hay đấu thầu giai đoạn 1 (D)
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Perriot, LLC?
A. Nó thuộc sở hữu của Bauright Group (cụm động từ chỉ quyền sở hữu)
B. Nó sẽ tạo ra một khu vui chơi công cộng (cụm động từ chỉ mục tiêu)
C. Nó đang chậm tiến độ (cụm động từ chỉ tình trạng)
D. Nó đã nộp hồ sơ thầu thực hiện Giai đoạn 1 (cụm động từ chỉ hoạt động đấu thầu)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6575, 5249, 175, 'In which of the positions marked [1], 12], 13], and [4] does the following sentence best belong? "Phase 1 finished on time and within budget."', '[1]', '[2]', '[3]', '[4]', 'A', 'Đáp án đúng là A.
Giải thích:
Câu "Phase 1 finished on time and within budget" nên đặt ở vị trí [1] vì:
1. Nối tiếp thông tin về hoàn thành giai đoạn 1
2. Đặt trước đánh giá "smooth completion... is remarkable"
3. Tạo mạch văn tự nhiên
Các vị trí khác không phù hợp do nằm giữa các nội dung khác
Dịch câu hỏi và các lựa chọn:
Câu hỏi: Câu "Giai đoạn 1 hoàn thành đúng thời hạn và trong ngân sách" nên thuộc vị trí nào trong số các vị trí được đánh dấu [1], [2], [3] và [4]?
A. [1] (vị trí đầu đoạn)
B. [2] (vị trí giữa đoạn 2)
C. [3] (vị trí giữa đoạn 3)
D. [4] (vị trí cuối đoạn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5250, 231, NULL, NULL, 'ALPHA LANDSCAPING SERVICES
www.alpha-landscaping.net
Alpha Landscaping Services can help you make the most of your outdoor space as well as add value to your property. Make a great outdoor space your family can enjoy or update the appearance of your commercial site. Our services are outlined below. All of our staff members must pass a rigorous safety course, much stricter than the industry standards, so you can be confident about working with us. Contact us at info@alpha-landscaping.net for a price quote.
MAINTENANCE
We can keep your garden looking its best with regular visits throughout the entire year. This includes mowing, trimming bushes and trees, and weeding. We are busiest from April to September, so book ahead to avoid disappointment. You can select from weekly, bi-weekly, or monthly visits.
RESET
Book a one-time visit to tackle a neglected garden and get it back into shape for you to care for easily. If your outdoor space is getting out of control, we can help you return it to its original condition.
DESIGN
Let one of our landscape artists design the garden of your dreams, no matter what your budget is. We''ll keep adjusting the plan until it''s just right. From lights and fountains to simple flower beds, we can make it happen. No garden is too big or too small for us to handle.
RENTAL
Unlike other businesses, we allow customers to rent our garden equipment without having one of our employees hired to use it. That means you can do the work yourself and save money. Each piece of machinery comes with a clear user manual.
===========
E-Mail message
To: info@alpha-landscaping.net
From: loriroth@thehomeinbox.com
Date: April 19
Subject: Services
To Whom It May Concern:
I''ve recently purchased a home in the Longmont neighborhood. Although I really enjoy gardening, this garden is too much for me to deal with initially. It hasn''t had any care in several years, so I''d like to have your crew visit once to help get everything in order. I already have the standard tools and equipment that you would need. The sooner you can visit, the better. My colleague at Seltice Enterprises, Alex Brooks, used your services at his home and recommended you highly.
Sincerely,
Lori Roth', 'DỊCH VỤ CẢNH QUAN ALPHA
www.alpha-landscaping.net
Dịch vụ Cảnh quan Alpha có thể giúp bạn tận dụng tối đa không gian ngoài trời cũng như tăng thêm giá trị cho tài sản của bạn. Tạo một không gian ngoài trời tuyệt vời mà gia đình bạn có thể tận hưởng hoặc cập nhật giao diện của trang web thương mại của bạn. Các dịch vụ của chúng tôi được nêu dưới đây. Tất cả nhân viên của chúng tôi phải vượt qua một khóa học an toàn nghiêm ngặt, nghiêm ngặt hơn nhiều so với các tiêu chuẩn của ngành, vì vậy bạn có thể tự tin khi làm việc với chúng tôi. Liên hệ với chúng tôi tại info@alpha-landscaping.net để được báo giá.
DUY TRÌ
Chúng tôi có thể giữ cho khu vườn của bạn trông đẹp nhất với các chuyến thăm thường xuyên trong suốt cả năm. Điều này bao gồm cắt cỏ, cắt tỉa bụi cây và cây cối, và làm cỏ. Chúng tôi bận rộn nhất từ tháng Tư đến tháng Chín, vì vậy hãy đặt trước để tránh thất vọng. Bạn có thể chọn từ các chuyến thăm hàng tuần, hai tuần một lần hoặc hàng tháng.
RESET
Đặt một chuyến thăm một lần để giải quyết một khu vườn bị bỏ quên và đưa nó trở lại hình dạng để bạn có thể chăm sóc dễ dàng. Nếu không gian ngoài trời của bạn vượt khỏi tầm kiểm soát, chúng tôi có thể giúp bạn đưa nó trở lại trạng thái ban đầu.
THIẾT KẾ
Hãy để một trong những nghệ sĩ cảnh quan của chúng tôi thiết kế khu vườn trong mơ của bạn, bất kể ngân sách của bạn là bao nhiêu. Chúng tôi sẽ tiếp tục điều chỉnh kế hoạch cho đến khi nó phù hợp. Từ đèn và đài phun nước đến những luống hoa đơn giản, chúng ta có thể biến nó thành hiện thực. Không có khu vườn nào là quá lớn hoặc quá nhỏ đối với chúng tôi.
CHO THUÊ
Không giống như các doanh nghiệp khác, chúng tôi cho phép khách hàng thuê thiết bị làm vườn của chúng tôi mà không cần thuê nhân viên của chúng tôi để sử dụng. Điều đó có nghĩa là bạn có thể tự mình làm việc và tiết kiệm tiền. Mỗi máy móc đi kèm với một hướng dẫn sử dụng rõ ràng.
============
Tin nhắn E-Mail
Gửi: info@alpha-landscaping.net
Từ: loriroth@thehomeinbox.com
Ngày: 19 tháng 4
Chủ đề: Dịch vụ
Đối với những ai có thể quan tâm:
Gần đây tôi đã mua một ngôi nhà ở khu phố Longmont. Mặc dù tôi thực sự thích làm vườn, nhưng ban đầu tôi không thể giải quyết được khu vườn này. Nó đã không có bất kỳ sự quan tâm nào trong vài năm, vì vậy tôi muốn có nhóm của bạn đến thăm một lần để giúp sắp xếp mọi thứ theo thứ tự. Tôi đã có các công cụ và thiết bị tiêu chuẩn mà bạn cần. Bạn có thể ghé thăm càng sớm thì càng tốt. Đồng nghiệp của tôi tại Seltice Enterprises, Alex Brooks, đã sử dụng dịch vụ của bạn tại nhà của anh ấy và rất khuyến khích bạn.
Thành thật,
Lori Roth');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6576, 5250, 176, 'In the brochure, the word "update" in paragraph 1, line 2, is closest in meaning to', 'modernize', 'inform', 'highlight', 'invest', 'A', 'Đáp án đúng là A (modernize).
Giải thích:
Trong ngữ cảnh của đoạn văn "update the appearance of your commercial site", từ "update" được sử dụng với ý nghĩa làm cho hiện đại hơn, cải thiện diện mạo của địa điểm thương mại.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Trong tờ rơi, từ "update" ở đoạn 1, dòng 2, có nghĩa gần nhất với:
A. Hiện đại hóa
B. Thông báo
C. Nhấn mạnh
D. Đầu tư');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6577, 5250, 177, 'What is NOT indicated about Alpha Landscaping Services?', 'It operates year-round', 'It works on gardens of any size', 'It is committed to safety', 'It is a family-owned business', 'D', 'Đáp án đúng là D (It is a family-owned business).
Giải thích:
Trong toàn bộ đoạn văn không có thông tin nào đề cập đến việc công ty thuộc sở hữu gia đình. Trong khi đó:
- Hoạt động quanh năm được đề cập trong phần MAINTENANCE: "regular visits throughout the entire year"
- Làm việc với mọi kích thước vườn được đề cập trong phần DESIGN: "No garden is too big or too small for us to handle"
- Cam kết về an toàn được đề cập: "All of our staff members must pass a rigorous safety course, much stricter than the industry standards"

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG được đề cập về Dịch vụ Cảnh quan Alpha?
A. Nó hoạt động quanh năm
B. Nó làm việc với vườn ở mọi kích thước
C. Nó cam kết về an toàn
D. Nó là doanh nghiệp gia đình');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6578, 5250, 178, 'According to the brochure, what is unique about the equipment in the Rental service?', 'It can be delivered for no additional fee', 'It does not require a company employee to use it', 'It is discounted for longer rental periods', 'It includes a training session on how to operate it', 'B', 'Đáp án đúng là B.
Giải thích:
Trong phần RENTAL có đoạn: "Unlike other businesses, we allow customers to rent our garden equipment without having one of our employees hired to use it" (Khác với các doanh nghiệp khác, chúng tôi cho phép khách hàng thuê thiết bị làm vườn mà không cần thuê nhân viên của chúng tôi để sử dụng). Điểm độc đáo này được nhấn mạnh bằng cụm "Unlike other businesses" cho thấy đây là điểm khác biệt với các công ty khác.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo tờ rơi, điều gì là độc đáo về thiết bị trong dịch vụ Cho thuê?
A. Nó có thể được giao miễn phí
B. Nó không yêu cầu nhân viên công ty để sử dụng
C. Nó được giảm giá cho thời gian thuê dài hơn
D. Nó bao gồm một buổi đào tạo về cách vận hành');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6579, 5250, 179, 'What service will Ms. Roth probably use?', 'Maintenance', 'Reset', 'Design', 'Rental', 'B', 'Đáp án đúng là B (Reset).
Giải thích:
Trong email của Ms. Roth, cô ấy viết: "It hasn''t had any care in several years, so I''d like to have your crew visit once to help get everything in order" (Khu vườn không được chăm sóc trong vài năm, vì vậy tôi muốn nhóm của bạn đến thăm một lần để giúp sắp xếp mọi thứ). Điều này hoàn toàn phù hợp với mô tả của dịch vụ RESET: "Book a one-time visit to tackle a neglected garden and get it back into shape" (Đặt lịch một lần thăm để giải quyết khu vườn bị bỏ bê và đưa nó trở lại hình dạng).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Roth có thể sẽ sử dụng dịch vụ nào?
A. Bảo trì
B. Làm mới
C. Thiết kế
D. Cho thuê');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6580, 5250, 180, 'What is suggested about Mr. Brooks?', 'He currently lives in the Longmont neighborhood', 'He is the former owner of Ms. Roth''s property', 'He is satisfied with Alpha Landscaping Services'' work', 'He used to work as a professional gardener', 'C', 'Đáp án đúng là C.
Giải thích:
Trong email, Ms. Roth viết: "Alex Brooks, used your services at his home and recommended you highly" (Alex Brooks đã sử dụng dịch vụ của các bạn tại nhà anh ấy và giới thiệu các bạn một cách nhiệt tình). Cụm "recommended you highly" cho thấy Mr. Brooks rất hài lòng với dịch vụ đến mức sẵn sàng giới thiệu cho người khác.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về Mr. Brooks?
A. Anh ấy hiện đang sống ở khu phố Longmont
B. Anh ấy là chủ sở hữu trước đây của căn nhà của Ms. Roth
C. Anh ấy hài lòng với công việc của Dịch vụ Cảnh quan Alpha
D. Anh ấy từng làm làm thợ làm vườn chuyên nghiệp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5251, 231, NULL, NULL, 'Medical World Magazine
July Issue
Creating a Calming Waiting Room
Attending a medical appointment provokes anxiety in many people. Follow the tips below to combat this issue by creating a relaxing space for your patients. This can foster a positive mindset in patients, easing built-up tension and making the appointment go more smoothly.
Color Choices and Wall Décor
* Use shades of blue or green to create a calming atmosphere.
* Decorate the walls with paintings in complementary colors, especially those with nature scenes.
* Restrict posters with medical information to those that are absolutely necessary.
Layout and Furniture
* Make sure the chairs and sofas have a soft covering to create a cozy and home-like feeling.
* Taller chairs are easy to get in and out of, which is useful for people with mobility issues.
* Use modular seating that can be moved into different configurations, as some people may visit alone and want privacy while others may come with family members and want to sit together.
Sounds
* Background music or nature sounds should be played at a low volume.
* Thick curtains can help to absorb sound and reduce echoes in a room.
Valued readers, we hope you have found these tips helpful. What would you like to learn about in future issues?
===========
Medical Word Magazine
Letters to the Editor
I would like to offer a correction to some information you provided about creating calming waiting rooms. While it is important for the furniture in a waiting room to be inviting and comfortable, this goal must not take precedence over health and safety considerations.
Upholstery that is soft and cloth-like can absorb fluids into the underlying cushion, making it difficult to disinfect.
A better option is furniture that is covered in vinyl. It is robust, lasting over ten years with heavy use, and can be wiped down quickly and easily to remove dirt and germs. The stylish and practical furniture made by my company, Free-Form Inc., uses vinyl with an antimicrobial surface, effectively reducing the spread of disease in medical settings.
Dominic McAlister', 'Tạp chí Medical World
Số tháng 7
Tạo phòng chờ yên tĩnh
Tham dự một cuộc hẹn khám bệnh khiến nhiều người lo lắng. Thực hiện theo các mẹo dưới đây để giải quyết vấn đề này bằng cách tạo ra một không gian thư giãn cho bệnh nhân của bạn. Điều này có thể thúc đẩy tư duy tích cực ở bệnh nhân, giảm bớt căng thẳng tích tụ và giúp cuộc hẹn diễn ra suôn sẻ hơn.
Lựa chọn màu sắc và trang trí tường
* Sử dụng các sắc thái của màu xanh lam hoặc xanh lá cây để tạo ra bầu không khí yên tĩnh.
* Trang trí tường bằng các bức tranh với các màu bổ sung, đặc biệt là những bức tranh có cảnh thiên nhiên.
* Hạn chế áp phích có thông tin y tế ở những thứ thực sự cần thiết.
Bố cục và nội thất
* Đảm bảo ghế và ghế sofa có lớp phủ mềm để tạo cảm giác ấm cúng và như ở nhà.
* Ghế cao hơn dễ dàng lên và ra, điều này rất hữu ích cho những người có vấn đề về vận động.
* Sử dụng chỗ ngồi mô-đun có thể Chuyển sang các cấu hình khác nhau, vì một số người có thể đến một mình và muốn có sự riêng tư trong khi những người khác có thể đi cùng với các thành viên trong gia đình và muốn ngồi cùng nhau.
Âm thanh
* Nhạc nền hoặc âm thanh thiên nhiên nên được phát ở âm lượng thấp.
* Rèm dày có thể giúp hấp thụ âm thanh và giảm tiếng vang trong phòng.
Các độc giả có giá trị, chúng tôi hy vọng bạn sẽ thấy những lời khuyên này hữu ích. Bạn muốn tìm hiểu điều gì trong các vấn đề trong tương lai? 
===========
Tạp chí Medical Word
Thư gửi Biên tập viên
Tôi muốn cung cấp một số sửa chữa cho một số thông tin bạn đã cung cấp về việc tạo phòng chờ bình tĩnh. Mặc dù điều quan trọng là đồ nội thất trong phòng chờ phải hấp dẫn và thoải mái, nhưng mục tiêu này không được ưu tiên hơn các cân nhắc về sức khỏe và an toàn.
Bọc mềm và giống như vải có thể hấp thụ chất lỏng vào đệm bên dưới, gây khó khăn cho việc khử trùng.
Một lựa chọn tốt hơn là đồ nội thất được bọc bằng nhựa vinyl. Nó chắc chắn, kéo dài hơn mười năm với việc sử dụng nhiều và có thể được lau sạch nhanh chóng và dễ dàng để loại bỏ bụi bẩn và vi trùng. Đồ nội thất thời trang và thiết thực được sản xuất bởi công ty của tôi, Free-Form Inc., sử dụng nhựa vinyl với bề mặt kháng khuẩn, làm giảm hiệu quả sự lây lan của bệnh tật trong các cơ sở y tế.
Dominic McAlister');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6581, 5251, 181, 'What is NOT a suggestion made in the article?', 'Keeping audio levels low', 'Improving mobility through chairs with wheels', 'Minimizing the use of medical posters', 'Including colors that have a relaxing effect', 'B', 'Đáp án đúng là B (Improving mobility through chairs with wheels).
Giải thích:
Trong bài báo không hề đề cập đến việc sử dụng ghế có bánh xe để cải thiện khả năng di chuyển. Các gợi ý được đề cập bao gồm:
- Giữ âm lượng thấp: "Background music or nature sounds should be played at a low volume"
- Hạn chế sử dụng poster y tế: "Restrict posters with medical information to those that are absolutely necessary"
- Sử dụng màu sắc tạo cảm giác thư giãn: "Use shades of blue or green to create a calming atmosphere"

Bài báo có đề cập đến ghế cao để dễ ngồi xuống và đứng lên ("Taller chairs are easy to get in and out of") nhưng không phải là ghế có bánh xe.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG phải là gợi ý được đề cập trong bài báo?
A. Giữ mức âm thanh thấp
B. Cải thiện khả năng di chuyển bằng ghế có bánh xe
C. Giảm thiểu việc sử dụng poster y tế
D. Bao gồm các màu sắc có tác dụng thư giãn');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6582, 5251, 182, 'Why is movable furniture mentioned?', 'Because more empty floor space may be needed on some days', 'Because the floor under the furniture should be cleaned daily', 'Because changing the layout periodically gives a fresh appearance', 'Because visitors may be in groups of different sizes', 'D', 'Đáp án đúng là D.
Giải thích:
Trong bài báo có đoạn: "Use modular seating that can be moved into different configurations, as some people may visit alone and want privacy while others may come with family members and want to sit together". Điều này chỉ rõ rằng nội thất có thể di chuyển được đề cập để phục vụ nhu cầu của các nhóm khách có số lượng khác nhau - một số người đến một mình và muốn riêng tư, trong khi những người khác đến cùng gia đình và muốn ngồi cùng nhau.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tại sao đề cập đến nội thất có thể di chuyển được?
A. Vì có thể cần thêm không gian sàn trống vào một số ngày
B. Vì sàn nhà dưới đồ nội thất nên được làm sạch hàng ngày
C. Vì thay đổi bố trí định kỳ tạo cảm giác mới mẻ
D. Vì khách có thể đến theo nhóm có kích thước khác nhau');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6583, 5251, 183, 'What is indicated about Medical World Magazine?', 'It is provided to hospitals at no charge', 'Its editors want topic suggestions from readers', 'It sells some of the products mentioned in its publications', 'Its owner is seeking new freelance writers', 'B', 'Đáp án đúng là B.
Giải thích:
Cuối bài có câu: "What would you like to learn about in future issues?" cho thấy biên tập viên muốn nhận đề xuất chủ đề từ độc giả.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Tạp chí Thế giới Y tế?
A. Miễn phí cho bệnh viện
B. Biên tập viên muốn đề xuất chủ đề từ độc giả
C. Bán sản phẩm được đề cập trong ấn phẩm
D. Chủ sở hữu tìm cộng tác viên mới');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6584, 5251, 184, 'What is most likely true about Mr. McAlister?', 'He previously worked at a medical clinic', 'He read the July edition of Medical World Magazine', 'He invented a new kind of textile', 'He spends a lot of time in waiting rooms', 'B', 'Đáp án đúng là B.
Giải thích:
Trong thư: "I would like to offer a correction to some information you provided about creating calming waiting rooms" cho thấy ông đã đọc số tháng 7 về phòng chờ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì nhiều khả năng đúng về ông McAlister?
A. Từng làm việc tại phòng khám
B. Đã đọc số tháng 7 của tạp chí
C. Phát minh loại vải mới
D. Dành nhiều thời gian trong phòng chờ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6585, 5251, 185, 'What is suggested about products from Free-Form Inc.?', 'They can be delivered quickly', 'They are made from recycled materials', 'They come with a ten-year warranty', 'They are easy to clean', 'D', 'Đáp án đúng là D.
Giải thích:
Thư viết về sản phẩm Free-Form Inc.: "can be wiped down quickly and easily to remove dirt and germs". Điều này chỉ ra sản phẩm dễ vệ sinh.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về sản phẩm Free-Form Inc.?
A. Giao hàng nhanh
B. Làm từ vật liệu tái chế
C. Bảo hành 10 năm
D. Dễ vệ sinh');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5252, 231, NULL, NULL, 'To: Chloe Willis
From: Steven Emery
Date: August 19
Subject: Wonder Luggage
Dear Ms. Willis,
It was a pleasure meeting you when I stopped in earlier today. As we discussed, I am looking for a new location for my luggage store. We are currently operating from a small retail unit in the Sandway Mall, but I would like to move to a larger space in its own building. A spacious display area is required, and on-site parking for customers would be a bonus. The maximum I prefer to spend on rent per month is $5,500.
I would like to have the business open at the new location by November 20, as that would allow our store to participate in the launch of Mizara''s new Eco-Max luggage line. Please let me know if you find anything that would suit my needs. I am avallable any day next week to view possible sites.
Warmest regards,
Steven Emery
Owner, Wonder Luggage
===========
To: Steven Emery
From: Chloe Willis
Date: August 20
Subject: Re: Wonder Luggage
Dear Mr. Emery,
I have done some research on retail units that would be appropriate for your business. Please see the list below and let me know if there are any that you would like to visit in person.
1. Address: 1258 Tolliver Street
Square Footage: 7,512 / Monthly Rent: $5,500
Notes: This unit was previously owned by a clothing store, and the display area has been recently renovated
2. Address: 908 Braxton Avenue
Square Footage: 8,940 / Monthly Rent: $5,000
Notes: The building owner requires the rental of the adjoining parking lot in a separate lease at $450 per month.
3. Address: 446 Cabell Street
Square Footage: 9,650 / Monthly Rent: $6,000
Notes: The foot traffic in this area is very high. There is a public parking area across the street.
Sincerely,
Chloe Willis
487-555-0149
============
Wonder Luggage Finds New Home
by Katheryn Clark
STRAFFORD (November 10)-Wonder Luggage —an independently owned business selling a range of suitcases, roller bags, carry-on luggage, and more-held its grand re-opening yesterday at its new location. Previously operating from the Sandway Mall, the store has found a new home at 908 Braxton Avenue. It is open daily from 9 A.M. to 8 P.M.
Most of the staff members remain the same, and they can advise customers on what sort of bag to purchase. Owner Steven Emery says that he is excited about the new location and that the store will continue to sell high-quality luggage that can endure rough handling.
Shoppers will love not only the products but also the atmosphere, as the new location has large windows, so it isn''t as dark as the mall unit. If you are looking for a long-lasting bag and excellent customer service, I highly recommend stopping by Wonder Luggage.', 'Gửi đến: Chloe Willis
Từ: Steven Emery
Ngày: 19 tháng 8
Chủ đề: Hành lý kỳ diệu
Cô Willis thân mến,
Rất vui được gặp bạn khi tôi ghé qua sớm hơn hôm nay. Như chúng ta đã thảo luận, tôi đang tìm một địa điểm mới cho cửa hàng hành lý của mình. Chúng tôi hiện đang hoạt động từ một đơn vị bán lẻ nhỏ ở Sandway Mall, nhưng tôi muốn chuyển đến một không gian lớn hơn trong tòa nhà riêng của nó. Cần có khu vực trưng bày rộng rãi và bãi đậu xe tại chỗ cho khách hàng sẽ là một phần thưởng. Mức tối đa tôi muốn chi cho tiền thuê mỗi tháng là 5.500 đô la.
Tôi muốn mở cửa kinh doanh tại địa điểm mới vào ngày 20 tháng 11, vì điều đó sẽ cho phép cửa hàng của chúng tôi tham gia vào việc ra mắt dòng hành lý Eco-Max mới của Mizara. Vui lòng cho tôi biết nếu bạn tìm thấy bất cứ điều gì phù hợp với nhu cầu của tôi. Tôi có thể vào bất kỳ ngày nào trong tuần tới để xem các địa điểm có thể.
Xin chào trân trọng nhất,
Steven Emery
Chủ sở hữu, Wonder Luggage
============
Gửi: Steven Emery
Từ: Chloe Willis
Ngày: 20 tháng 8
Chủ đề: Re: Wonder Luggage
Thưa ông Emery,
Tôi đã thực hiện một số nghiên cứu về các đơn vị bán lẻ phù hợp với doanh nghiệp của bạn. Vui lòng xem danh sách bên dưới và cho tôi biết nếu có bất kỳ điều gì mà bạn muốn ghé thăm trực tiếp.
1. Địa chỉ: 1258 Tolliver Street
Square Footage: 7.512 / Giá thuê hàng tháng: $5,500
Ghi chú: Căn hộ này trước đây thuộc sở hữu của một cửa hàng quần áo và khu vực trưng bày gần đây đã được cải tạo
2. Địa chỉ: 908 Đại lộ Braxton
Hình vuông: 8.940 / Tiền thuê hàng tháng: 5.000 đô la
Ghi chú: Chủ sở hữu tòa nhà yêu cầu thuê bãi đậu xe liền kề trong một hợp đồng thuê riêng với giá 450 đô la mỗi tháng.
3. Địa chỉ: 446 Phố Cabell
Lượng hình vuông: 9.650 / Tiền thuê hàng tháng: 6.000 đô la
Ghi chú: Lưu lượng người đi bộ trong khu vực này rất cao. Có một bãi đậu xe công cộng bên kia đường.
Trân trọng,
Chloe Willis
487-555-0149
============
Wonder Luggage Finds New Home
bởi Katheryn Clark
STRAFFORD (ngày 10 tháng 11)-Wonder Luggage — một doanh nghiệp thuộc sở hữu độc lập bán nhiều loại vali, túi lăn, hành lý xách tay, v.v.v. đã tổ chức khai trương lớn vào ngày hôm qua tại địa điểm mới. Trước đây hoạt động từ Trung tâm mua sắm Sandway, cửa hàng đã tìm thấy một ngôi nhà mới tại 908 Đại lộ Braxton. Cửa hàng mở cửa hàng ngày từ 9 giờ sáng đến 8 giờ tối.
Hầu hết các nhân viên vẫn giữ nguyên và họ có thể tư vấn cho khách hàng về loại túi nên mua. Chủ sở hữu Steven Emery nói rằng anh ấy rất vui mừng về địa điểm mới và cửa hàng sẽ tiếp tục bán hành lý chất lượng cao có thể chịu được việc xử lý thô bạo.
Những người mua sắm sẽ không chỉ yêu thích sản phẩm mà còn cả bầu không khí, vì địa điểm mới có cửa sổ lớn, vì vậy nó không tối tăm như đơn vị trung tâm mua sắm. Nếu bạn đang tìm kiếm một chiếc túi có tuổi thọ cao và dịch vụ khách hàng tuyệt vời, tôi thực sự khuyên bạn nên ghé qua Wonder Luggage.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6586, 5252, 186, 'Where most likely does Ms. Willis work?', 'At a luggage store', 'At a manufacturing facility', 'At a financial institution', 'At a real estate firm', 'D', 'Đáp án D.
Giải thích:
1. Ms. Willis thể hiện kiến thức chuyên môn về bất động sản thương mại: cung cấp thông tin chi tiết về "retail units" (mặt bằng bán lẻ)
2. Email của cô liệt kê nhiều thông tin đặc trưng của môi giới bất động sản:
- Diện tích cụ thể ("Square Footage: 7,512")
- Giá thuê chi tiết ("Monthly Rent: $5,500")
- Thông tin về bãi đậu xe và điều kiện thuê
- Lịch sử sử dụng ("previously owned by a clothing store")
- Đặc điểm khu vực ("foot traffic in this area is very high")
3. Cô ấy có thể sắp xếp xem mặt bằng: "let me know if there are any that you would like to visit in person"

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Willis nhiều khả năng làm việc ở đâu?
A. Cửa hàng hành lý
B. Cơ sở sản xuất
C. Tổ chức tài chính
D. Công ty bất động sản');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6587, 5252, 187, 'What is indicated about Wonder Luggage?', 'It pays a monthly rental fee of six thousand dollars', 'It has a one-year lease at its new site', 'It is the largest luggage store in the area', 'It reopened in time for a product launch', 'D', 'Đáp án D.
Giải thích:
1. Trong email đầu tiên, Mr. Emery nêu rõ mục tiêu thời gian: "I would like to have the business open at the new location by November 20, as that would allow our store to participate in the launch of Mizara''s new Eco-Max luggage line"
2. Bài báo xác nhận họ đã khai trương đúng hạn: "held its grand re-opening yesterday" vào ngày 10/11, trước thời hạn 20/11
3. Các phương án khác không có bằng chứng:
- Giá thuê thực tế là $5,000 + $450 cho bãi đỗ xe, không phải $6,000
- Không có thông tin về thời hạn hợp đồng thuê
- Không có so sánh về quy mô với các cửa hàng khác.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Wonder Luggage?
A. Trả phí thuê hàng tháng 6000 đô
B. Có hợp đồng thuê 1 năm tại địa điểm mới
C. Là cửa hàng hành lý lớn nhất khu vực
D. Mở cửa lại kịp đợt ra mắt sản phẩm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6588, 5252, 188, 'What is suggested about Mr. Emery?', 'He is also renting a parking area', 'He plans to open another branch', 'He did not renovate a display area', 'He is benefitting from heavy foot traffic', 'A', 'Đáp án A.
Giải thích:
1. Cửa hàng chọn địa chỉ 908 Braxton Avenue, được xác nhận trong bài báo: "the store has found a new home at 908 Braxton Avenue"
2. Theo thư của Ms. Willis, địa điểm này có điều kiện đặc biệt: "The building owner requires the rental of the adjoining parking lot in a separate lease at $450 per month"
3. Việc Mr. Emery chọn địa điểm này ngụ ý ông đã đồng ý điều kiện thuê thêm bãi đỗ xe
4. Các phương án khác không có bằng chứng hỗ trợ trong văn bản.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về ông Emery?
A. Ông ấy cũng thuê bãi đậu xe
B. Ông ấy dự định mở chi nhánh khác
C. Ông ấy không cải tạo khu trưng bày
D. Ông ấy được hưởng lợi từ lưu lượng người qua lại cao');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6589, 5252, 189, 'In the article, the word "endure" in paragraph 2, line 5, is closest in meaning to', 'withstand', 'meet', 'permit', 'continue', 'A', 'áp án A.
Giải thích:
1. Từ "endure" xuất hiện trong ngữ cảnh: "the store will continue to sell high-quality luggage that can endure rough handling"
2. "Endure rough handling" ở đây nói về khả năng chịu đựng việc bị xử lý thô bạo của hành lý
3. "Withstand" (chịu đựng được) là từ đồng nghĩa phù hợp nhất trong ngữ cảnh này
4. Các phương án khác không phù hợp:
- "meet" (đáp ứng): không phù hợp với "rough handling"
- "permit" (cho phép): không logic trong ngữ cảnh
- "continue" (tiếp tục): không thể dùng với "rough handling"

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Trong bài báo, từ "endure" gần nghĩa nhất với?
A. Chịu đựng được
B. Đáp ứng
C. Cho phép
D. Tiếp tục');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6590, 5252, 190, 'How is the new store different from the old store?', 'It has a more convenient location', 'It has a brighter interior', 'It has longer opening hours', 'It has a larger display space', 'B', 'Đáp án B.
Giải thích:
1. Bài báo trực tiếp so sánh độ sáng giữa hai cửa hàng: "the new location has large windows, so it isn''t as dark as the mall unit"
2. Không có thông tin so sánh về:
- Sự thuận tiện của vị trí
- Giờ mở cửa của cửa hàng cũ
- Không gian trưng bày (mặc dù cửa hàng mới lớn hơn, nhưng không rõ phần trưng bày)
3. Sự khác biệt về độ sáng được nhấn mạnh bởi:
- Địa điểm mới có "large windows" (cửa sổ lớn)
- So sánh trực tiếp "isn''t as dark as" (không tối như

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Cửa hàng mới khác gì so với cửa hàng cũ?
A. Có vị trí thuận tiện hơn
B. Có không gian bên trong sáng sủa hơn
C. Có giờ mở cửa dài hơn
D. Có không gian trưng bày lớn hơn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5253, 231, NULL, NULL, 'Foundation of Canadian Artists
The Foundation of Canadian Artists (FCA) is delighted to announce filmmaker Sunder Chadda as the winner of this year''s FCA Achievement Award. You are invited to attend a banquet celebrating Mr. Chadda''s work on Friday, 19 July, at 6:30 p.M., at the Irving Hotel in Toronto.
Mr. Chadda''s documentaries have entertained and educated audiences for the past decade. The award-winning documentary Flight follows the migration of Canadian geese, with footage gathered near Mr. Chadda''s hometown of Edmonton all the way to Santa Fe, New Mexico in the U.S. Pushed Out explores the effect of urbanization on the habitats of wolves. Mr. Chadda said that he made this film to emphasize how tough it is for these creatures to adapt to changes in their environment. Two Little Cubs centers on a polar bear raising her cubs. The film includes an interview with Helen Ortiz, a professor at Damon University.
Tickets for the event can be purchased online at www.fcartists.ca/events on or before 16 July. Admission includes a four-course dinner followed by entertainment featuring Josefina Adams. We have negotiated a special price on rooms at Irving Hotel for attendees (whether members or non-members) who plan to stay overnight in Toronto. In addition, those who sign up for the FCA newsletter can get a voucher for a free breakfast at the hotel.
===========
http://www.irvinghotel.ca
Special Rate for Event Attendees:
FCA Achievement Award Ceremony
Reserve a room at the Irving Hotel for the FCA Achievement Award Ceremony that will be held on July 19. Attendees to this event who stay for two nights or more can get 30% off the rate for any of our rooms! This gives you plenty of time to enjoy the event, which includes an after-dinner performance from a live band, and to spend some extra time in the beautiful city of Toronto. Our standard checkout time is 11 A.M., and guests can get an extended checkout time of noon for an additional $8.99. This fee is waived for members of the Irving Rewards Program. Make your booking no later than July 6 to take advantage of this offer.
===========
Irving Hotel, Toronto
Customer Receipt
Date: 22 July
Guest Name: Raymond Frazer
Payment: Credit Card XXXX-XXXX-XXXX-8509
Room: 327
Room Type: Deluxe
Check-in: 19 July, 2:43 p.M.
Check-out: 22 July, 11:55 A.M.
Room Fee: $220.00 x 3           $660.00
Extended checkout: $0.00     $0.00
Discount: 30% (FCA)               -$198.00
TOTAL:                                          $462.00
Thank you for your patronage!', '[Previous translation]');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6591, 5253, 191, 'What do all of Mr. Chadda''s listed films have in common?', 'They were filmed only in Canada', 'They have a wildlife theme', 'They received funding from the FCA', 'They feature interviews with professors', 'B', 'Đáp án B.
Giải thích:
1. Tất cả phim được liệt kê đều về động vật hoang dã:
- Flight: về chim ngỗng Canada ("follows the migration of Canadian geese")
- Pushed Out: về sói ("effect of urbanization on the habitats of wolves")
- Two Little Cubs: về gấu Bắc cực ("centers on a polar bear raising her cubs")
2. Các phương án khác không chính xác:
A. Flight được quay ở cả Canada và Mỹ ("from Edmonton all the way to Santa Fe, New Mexico in the U.S.")
C. Không có thông tin về nguồn tài trợ
D. Chỉ Two Little Cubs đề cập phỏng vấn giáo sư ("includes an interview with Helen Ortiz, a professor")

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì chung của tất cả phim được liệt kê của ông Chadda?
A. Chỉ được quay ở Canada
B. Có chủ đề về động vật hoang dã
C. Nhận tài trợ từ FCA
D. Có phỏng vấn giáo sư');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6592, 5253, 192, 'In the announcement, the word "tough" in paragraph 2, line 6, is closest in meaning to', 'powerful', 'stern', 'challenging', 'determined', 'C', 'Đáp án C.
Giải thích:
1. "Tough" xuất hiện trong ngữ cảnh: "to emphasize how tough it is for these creatures to adapt to changes in their environment"
2. Từ "tough" ở đây mô tả sự khó khăn của động vật trong việc thích nghi với môi trường thay đổi
3. "Challenging" (đầy thách thức, khó khăn) là từ đồng nghĩa phù hợp nhất
4. Các phương án khác không phù hợp:
- "powerful" (mạnh mẽ): không phù hợp khi nói về khó khăn thích nghi
- "stern" (nghiêm khắc): thường dùng cho tính cách
- "determined" (kiên quyết): mô tả thái độ, không phù hợp ngữ cảnh

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Trong thông báo, từ "tough" gần nghĩa nhất với:
A. Mạnh mẽ
B. Nghiêm khắc
C. Đầy thách thức
D. Kiên quyết');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6593, 5253, 193, 'What is indicated about customers receiving Irving Hotel''s special rate?', 'They will be offered a free breakfast', 'They must check in on July 16', 'They will occupy rooms on a certain floor', 'They must stay for a minimum of two nights', 'D', 'Đáp án D.
Giải thích:
1. Website khách sạn nêu rõ điều kiện: "Attendees to this event who stay for two nights or more can get 30% off the rate"
2. Điều này được xác nhận qua hóa đơn của Mr. Frazer:
- Ở 3 đêm (19-22 July)
- Nhận được giảm giá 30% ("Discount: 30% (FCA)")
3. Các phương án khác không chính xác:
A. Bữa sáng miễn phí chỉ dành cho người đăng ký nhận bản tin FCA
B. Không có yêu cầu nhận phòng ngày 16/7
C. Không có thông tin về tầng phòng cụ thể

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về khách hàng nhận giá đặc biệt của Khách sạn Irving?
A. Họ sẽ được phục vụ bữa sáng miễn phí
B. Họ phải nhận phòng vào ngày 16 tháng 7
C. Họ sẽ ở phòng trên một tầng nhất định
D. Họ phải ở tối thiểu hai đêm",');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6594, 5253, 194, 'Who most likely is Josefina Adams?', 'An event planner', 'A comedian', 'A musician', 'The FCA President', 'C', 'Đáp án C.
Giải thích:
1. Thông báo đề cập: "entertainment featuring Josefina Adams"
2. Website khách sạn xác nhận: "an after-dinner performance from a live band"
3. Kết hợp hai thông tin này cho thấy Josefina Adams nhiều khả năng là nhạc sĩ biểu diễn trong ban nhạc
4. Không có thông tin ủng hộ các vai trò khác:
- Không đề cập cô là người tổ chức sự kiện
- Không có thông tin về tiết mục hài
- Không có thông tin về vai trò lãnh đạo FCA

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Josefina Adams nhiều khả năng là ai?
A. Người tổ chức sự kiện
B. Diễn viên hài
C. Nhạc sĩ
D. Chủ tịch FCA');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6595, 5253, 195, 'What is suggested about Mr. Frazer?', 'He is a member of a rewards program', 'He signed up for a newsletter', 'He received a free room upgrade', 'He attended the event last year', 'A', ',"Đáp án A.
Giải thích:
1. Trong hóa đơn của Mr. Frazer:
- Có phí gia hạn thời gian trả phòng $0.00 (""Extended checkout: $0.00"")
- Thời gian trả phòng là 11:55 A.M., sau giờ trả phòng tiêu chuẩn 11 A.M.
2. Theo website khách sạn: ""guests can get an extended checkout time of noon for an additional $8.99. This fee is waived for members of the Irving Rewards Program""
3. Vì Mr. Frazer được miễn phí gia hạn, điều này gợi ý ông là thành viên chương trình khách hàng thân thiết
4. Không có bằng chứng cho các phương án khác:
- Không đề cập việc đăng ký bản tin
- Không có thông tin về nâng cấp phòng
- Không có dữ liệu về việc tham dự năm trước

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về ông Frazer?
A. Ông ấy là thành viên chương trình khách hàng thân thiết
B. Ông ấy đã đăng ký nhận bản tin
C. Ông ấy được nâng cấp phòng miễn phí
D. Ông ấy đã tham dự sự kiện năm ngoái"');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5254, 231, NULL, NULL, 'http://www.buildbusinessbest.com/workshops
HOME    OUR MISSION.    WORKSHOP.    MEMBERSHIP.     CONTACT
Get ready to take your business skills to the next level with a full day of workshops hosted by Build Business Best (BBB)! Our next workshop series will take place at the Oakridge Conference Center on Wednesday, April 22. All of our instructors are BBB members as well as experienced professionals. Hubert Wong is back with our most popular workshop on how to create a business plan, either for a new business or as an expansion of your existing business. We''ll also have workshops by Claire Ladner, Isaac Tineo, and Mei Han. Those will be followed by the last session, in which you''ll learn about conflict resolution through role-playing in small groups.
The fee for the entire day of workshops is $85, and this includes an on-site catered lunch. If you have any special dietary needs, please let us know in advance. Registration for BBB members opens on March 3 and for the general public on March 10. A link will be added to this page as well as the home page when rese tration is open.
============
E-Mail
To: Isaac Tineo <i.tineo@wdmail.com>
From: Darlene Mendoza <mendozad@buildbusinessbest.com>
Date: April 25
Subject: Survey response
Dear Mr. Tineo,
I''d like to thank you once again for agreeing to teach in our most recent workshop series.
We hope you will be able to contribute to one of our events again. I''ve attached a survey response for your reference. Many other students had similar remarks about your session on how to manage work-related stress in the workplace. As young professionals make up the majority of our participants, providing key skills to support their career success is very important. I am happy to send more comments once I have everything organized.
All the best,
Darlene Mendoza
Activity Coordinator, Build Business Best
=============
BBB Workshop Series Feedback Survey
Name: Felix Roland
Attendance Date: April 22
How likely are you to recommend BBB Workshops to others?
☒ Very Likely             ☐ Somewhat Likely            ☐ Not Likely
On a scale of 1 (Not Satisfied) to 5 (Very Satisfied), how would you rate the following categories?
Sign-Up Process: 4
Handouts: 4
Classroom Atmosphere: 2
Instructors'' Knowledge: 5
Workshop Timing: 5
Lunch: 5
Comments: Overall, I believe I learned a lot from these sessions, though I had to miss the last session due to being called away on an urgent work matter. I thought the workshop on managing stress related to work was the most helpful one. My only complaint was that the classroom was very hot. This was somewhat distracting at times.', 'http://www.buildbusinessbest.com/workshops
TRANG CHỦ SỨ MỆNH CỦA CHÚNG TÔI. HỘI THẢO. THÀNH VIÊN. LIÊN HỆ
Hãy sẵn sàng để nâng cao kỹ năng kinh doanh của bạn lên một tầm cao mới với các hội thảo kéo dài cả ngày do Build Business Best (BBB) tổ chức! Chuỗi hội thảo tiếp theo của chúng tôi sẽ diễn ra tại Trung tâm Hội nghị Oakridge vào thứ Tư, ngày 22 tháng Tư. Tất cả các giảng viên của chúng tôi đều là thành viên BBB cũng như các chuyên gia giàu kinh nghiệm. Hubert Wong đã trở lại với hội thảo phổ biến nhất của chúng tôi về cách tạo kế hoạch kinh doanh, cho một doanh nghiệp mới hoặc như một sự mở rộng của doanh nghiệp hiện tại của bạn. Chúng tôi cũng sẽ có các hội thảo của Claire Ladner, Isaac Tineo và Mei Han. Những điều đó sẽ được theo sau bởi phiên cuối cùng, trong đó bạn sẽ tìm hiểu về giải quyết xung đột thông qua đóng vai trong các nhóm nhỏ.
Phí cho cả ngày hội thảo là 85 đô la và bao gồm bữa trưa được phục vụ tại chỗ. Nếu bạn có bất kỳ nhu cầu chế độ ăn uống đặc biệt nào, vui lòng cho chúng tôi biết trước. Đăng ký cho các thành viên BBB bắt đầu vào ngày 3 tháng 3 và cho công chúng vào ngày 10 tháng 3. Một liên kết sẽ được thêm vào trang này cũng như trang chủ khi res tration được mở.
============
E-Mail
Gửi: Isaac Tineo <i.tineo@wdmail.com>
Từ: Darlene Mendoza <mendozad@buildbusinessbest.com>
Ngày: 25 tháng 4
Chủ đề: Trả lời khảo sát
Ông Tineo thân mến,
Tôi muốn cảm ơn ông một lần nữa vì đã đồng ý giảng dạy trong chuỗi hội thảo gần đây nhất của chúng tôi.
Chúng tôi hy vọng bạn sẽ có thể đóng góp cho một trong những sự kiện của chúng tôi một lần nữa. Tôi đã đính kèm một câu trả lời khảo sát để bạn tham khảo. Nhiều sinh viên khác đã có những nhận xét tương tự về buổi học của bạn về cách quản lý căng thẳng liên quan đến công việc tại nơi làm việc. Khi các chuyên gia trẻ chiếm phần lớn những người tham gia của chúng tôi, việc cung cấp các kỹ năng chính để hỗ trợ thành công trong sự nghiệp của họ là rất quan trọng. Tôi rất vui khi gửi thêm ý kiến khi tôi đã sắp xếp mọi thứ.
Tất cả những điều tốt đẹp nhất,
Darlene Mendoza
Điều phối viên hoạt động, Xây dựng doanh nghiệp tốt nhất
===============
Khảo sát phản hồi chuỗi hội thảo BBB
Tên: Felix Roland
Ngày tham dự: 22 tháng 4
Bạn có khả năng giới thiệu BBB Workshops cho người khác như thế nào? N☒ Rất có thể ☐ Có thể ☐ Không có khả năng xảy ra
Trên thang điểm từ 1 (Không hài lòng) đến 5 (Rất hài lòng), bạn đánh giá các danh mục sau như thế nào? 
Quy trình đăng ký: 4
Giấy tờ: 4
Bầu không khí lớp học: 2
Kiến thức của giảng viên: 5
Thời gian hội thảo: 5
Bữa trưa: 5
Nhận xét: Nhìn chung, tôi tin rằng tôi đã học được rất nhiều từ các buổi học này, mặc dù tôi đã phải bỏ lỡ buổi học cuối cùng do bị hủy vì một vấn đề công việc khẩn cấp. Tôi nghĩ hội thảo về quản lý căng thẳng liên quan đến công việc là hữu ích nhất. Khiếu nại duy nhất của tôi là lớp học rất nóng. Điều này đôi khi hơi mất tập trung.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6596, 5254, 196, 'What is indicated about the workshop series?', 'Some people can register earlier than others', 'BBB members are eligible for a discount', 'It will take place over several days', 'Its fee includes the cost of two meals', 'A', 'Đáp án A.
Giải thích:
1. Website nêu rõ hai thời điểm đăng ký khác nhau:
- "Registration for BBB members opens on March 3"
- "and for the general public on March 10"
2. Thành viên BBB được đăng ký sớm hơn công chúng 1 tuần
3. Các phương án khác không chính xác:
B. Không đề cập đến giảm giá cho thành viên
C. Chỉ diễn ra trong một ngày ("full day of workshops")
D. Chỉ bao gồm bữa trưa ("includes an on-site catered lunch")

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về chuỗi hội thảo?
A. Một số người có thể đăng ký sớm hơn những người khác
B. Thành viên BBB được giảm giá
C. Sẽ diễn ra trong nhiều ngày
D. Phí tham dự bao gồm chi phí hai bữa ăn');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6597, 5254, 197, 'Why did Ms. Mendoza send the e-mail?', 'To ask for a survey to be completed', 'To provide an instructor with feedback', 'To confirm the date of the next session', 'To suggest a new topic for instruction', 'B', 'Đáp án B.
Giải thích:
1. Ms. Mendoza gửi email để chia sẻ phản hồi với giảng viên:
- "I''ve attached a survey response for your reference"
- "Many other students had similar remarks about your session"
2. Mục đích rõ ràng là cung cấp phản hồi từ học viên cho Mr. Tineo
3. Không có bằng chứng cho các phương án khác:
- Không yêu cầu điền khảo sát
- Không xác nhận ngày họp
- Không đề xuất chủ đề mới

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tại sao bà Mendoza gửi email?
A. Để yêu cầu hoàn thành một khảo sát
B. Để cung cấp phản hồi cho giảng viên
C. Để xác nhận ngày của phiên tiếp theo
D. Để đề xuất một chủ đề giảng dạy mới');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6598, 5254, 198, 'In the e-mail, the phrase "make up" in paragraph 1, line 4, is closest in meaning to', 'fill', 'prepare', 'invent', 'comprise', 'D', 'Đáp án D.
Giải thích:
1. "Make up" xuất hiện trong câu: "As young professionals make up the majority of our participants"
2. Trong ngữ cảnh này, "make up" có nghĩa là "comprise" (chiếm, cấu thành)
3. Câu này nói rằng các chuyên gia trẻ chiếm đa số người tham gia
4. Các phương án khác không phù hợp:
- "fill" (lấp đầy)
- "prepare" (chuẩn bị)
- "invent" (phát minh)

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Trong email, cụm từ "make up" gần nghĩa nhất với?
A. Lấp đầy
B. Chuẩn bị
C. Phát minh
D. Cấu thành');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6599, 5254, 199, 'What is suggested about Mr. Roland?', 'He thought some noise was distracting', 'He has recommended the workshops to others', 'He did not participate in a role-play activity', 'He gave the handouts the top rating', 'C', 'Đáp án C.
Giải thích:
1. Mr. Roland không tham gia hoạt động đóng vai vì:
- Phiên cuối cùng là về giải quyết xung đột thông qua đóng vai ("conflict resolution through role-playing")
- Ông viết trong khảo sát: "had to miss the last session"
2. Các phương án khác không chính xác:
A. Ông phàn nàn về nhiệt độ, không phải tiếng ồn
B. Ông đánh dấu "Very Likely" cho khả năng giới thiệu, nhưng chưa thực sự giới thiệu
D. Ông cho handouts 4/5, không phải điểm cao nhất

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về ông Roland?
A. Ông nghĩ một số tiếng ồn gây mất tập trung
B. Ông đã giới thiệu hội thảo cho người khác
C. Ông không tham gia hoạt động đóng vai
D. Ông cho tài liệu phát tay điểm cao nhất');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6600, 5254, 200, 'Which instructor''s session did Mr. Roland find most helpful?', 'Hubert Wong', 'Claire Ladner', 'Isaac Tineo', 'Mei Han', 'C', 'Đáp án C.
Giải thích:
1. Trong khảo sát, Mr. Roland viết: "the workshop on managing stress related to work was the most helpful one"
2. Email của Ms. Mendoza cho thấy Isaac Tineo dạy về quản lý stress liên quan đến công việc: "your session on how to manage work-related stress in the workplace"
3. Do đó, phiên học Mr. Roland thấy hữu ích nhất là của Isaac Tineo

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Phiên học của giảng viên nào mà ông Roland thấy hữu ích nhất?
A. Hubert Wong
B. Claire Ladner
C. Isaac Tineo
D. Mei Han');;

