INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6601, 5255, 1, 'Look at the picture marked number one in your test book.', 'She''s putting on a pair of gloves.', 'She''s harvesting some fruit.', 'She''s holding a basket full of soil.', 'She''s watering some plants.', 'B', 'A Cô ấy đang đeo một đôi găng tay.
B Cô ấy đang thu hoạch một số trái cây.
C Cô ấy đang cầm một giỏ đầy đất.
