INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6602, 5256, 2, 'Look at the picture marked number two in your test book.', 'The man is connecting some sound equipment.', 'The man is playing a musical instrument.', 'The man is adjusting his headphones.', 'The man is singing into a microphone.', 'D', 'A Người đàn ông đang kết nối một số thiết bị âm thanh.
B Người đàn ông đang chơi một nhạc cụ.
