INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5257, 232, '2025/test4/audio/test4_question_3.mp3', '2025/test4/image/test4-image-3.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6603, 5257, 3, 'Look at the picture marked number three in your test book.', 'Trees are being planted next to a waterway.', 'The people are using exercise machines.', 'There are skyscrapers in the distance.', 'The woman is reaching down to tie her shoe.', 'C', 'A Cây đang được trồng bên cạnh một con mương.
B Những người đó đang sử dụng máy tập thể dục.
