INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6801, 5404, 1, 'Look at the picture marked number one in your test book.', 'He is delivering a package.', 'He is wrapping a container in paper.', 'He is looking into a cardboard box.', 'He is wiping off the surface of a kitchen table.', 'C', 'A Anh ấy đang giao một gói hàng.
B Anh ấy đang bọc một thùng hàng bằng giấy.
C Anh ấy đang nhìn vào một hộp các tông.
D Anh ấy đang lau sạch bề mặt của một chiếc bàn ăn.');;
