INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6803, 5406, 3, 'Look at the picture marked number three in your test book.', 'The man is plugging in a laptop.', 'The man is leaning against a wall.', 'One of the women is pointing at a binder.', 'One of the women is talking on a mobile phone.', 'D', 'A Người đàn ông đang cắm laptop vào ổ điện.
B Người đàn ông đang dựa vào một bức tường.
C Một trong những người phụ nữ đang chỉ vào một bìa tài liệu.
D Một trong những người phụ nữ đang nói chuyện trên điện thoại di động.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5407, 239, '2025/test5/audio/test5_question_4.mp3', '2025/test5/image/test5-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6804, 5407, 4, 'Look at the picture marked number four in your test book.', 'A woman is rolling up a hose.', 'Some water has been left in a bucket.', 'A woman is digging up flowers from the ground.', 'Some bushes have been planted outdoors.', 'D', 'A Một người phụ nữ đang cuộn một ống nước.
B Một ít nước đã được để lại trong một xô.
C Một người phụ nữ đang đào hoa từ dưới đất.
D Một số bụi cây đã được trồng ngoài trời.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5408, 239, '2025/test5/audio/test5_question_5.mp3', '2025/test5/image/test5-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6805, 5408, 5, 'Look at the picture marked number five in your test book.', 'One of the workers is hanging up a lab coat.', 'One of the workers is operating some laboratory equipment.', 'One of the workers is unpacking a microscope.', 'One of the workers is filling a glass bottle with a liquid.', 'B', 'A Một trong những công nhân đang treo một chiếc áo khoác phòng thí nghiệm.
B Một trong những công nhân đang vận hành một số thiết bị phòng thí nghiệm.
C Một trong những công nhân đang tháo gói một chiếc kính hiển vi.
D Một trong những công nhân đang đổ chất lỏng vào một chiếc chai thủy tinh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5409, 239, '2025/test5/audio/test5_question_6.mp3', '2025/test5/image/test5-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6806, 5409, 6, 'Look at the picture marked number six in your test book.', 'A waiting area is crowded with customers.', 'A television is mounted on the wall.', 'Some chairs are arranged in a circle.', 'Some windows are covered with curtains.', 'B', 'A Một khu vực chờ đang đông khách.
B Một chiếc tivi được gắn trên tường.
C Một số ghế được xếp thành vòng tròn.
D Một số cửa sổ được che phủ bằng rèm.');;

-- Data for 2025 Test5 Part 2
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5410, 240, '2025/test5/audio/test5_question_7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6807, 5410, 7, 'Why are you traveling to Melbourne next week?', 'Probably the international airport.', 'On an eight o''clock flight.', 'I have to inspect the manufacturing facility.', NULL, 'C', 'Câu hỏi: Tại sao bạn lại đi Melbourne vào tuần sau?"
A: "Chắc là sân bay quốc tế."
B: "Chuyến bay lúc tám giờ."
C: "Tôi phải kiểm tra cơ sở sản xuất."
Giải thích: Đáp án C đúng vì câu hỏi yêu cầu lý do chuyến đi, và đáp án C cho biết rõ mục đích chuyến đi là để kiểm tra cơ sở sản xuất."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5411, 240, '2025/test5/audio/test5_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6808, 5411, 8, 'Who will add graphics to the slides?', 'For the meeting with Bayne Enterprises.', 'Helen is in charge of that.', 'Download the new software package.', NULL, 'B', 'Câu hỏi: Ai sẽ thêm đồ họa vào các slide?"
A: "Dành cho cuộc họp với Bayne Enterprises."
B: "Helen phụ trách việc đó."
C: "Tải gói phần mềm mới."
Giải thích: Đáp án B đúng vì câu hỏi hỏi về ai sẽ làm việc này, và đáp án B chỉ rõ người phụ trách là Helen."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5412, 240, '2025/test5/audio/test5_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6809, 5412, 9, 'Where is the maintenance office?', 'At the end of the hallway.', 'Because the window is broken.', 'I think his name is Christopher.', NULL, 'A', 'Câu hỏi: Văn phòng bảo trì ở đâu?"
A: "Ở cuối hành lang."
B: "Vì cửa sổ bị hỏng."
C: "Tôi nghĩ tên anh ấy là Christopher."
Giải thích: Đáp án A đúng vì câu hỏi hỏi về vị trí văn phòng bảo trì, và đáp án A đưa ra vị trí cụ thể ở cuối hành lang."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5413, 240, '2025/test5/audio/test5_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6810, 5413, 10, 'Would you like to pay for your sofa in monthly installments?', 'Is there a leather one in stock?', 'Yes, that would be better.', 'My new two-bedroom apartment.', NULL, 'B', 'Câu hỏi: Bạn có muốn trả tiền cho chiếc ghế sofa của mình theo các khoản trả góp hàng tháng không?"
A: "Có một chiếc sofa da còn trong kho không?"
B: "Vâng, điều đó sẽ tốt hơn."
C: "Căn hộ hai phòng ngủ mới của tôi."
Giải thích: Đáp án B đúng vì câu hỏi về việc thanh toán trả góp, và đáp án B đồng ý với cách thanh toán trả góp hàng tháng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5414, 240, '2025/test5/audio/test5_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6811, 5414, 11, 'When will the security software be installed?', 'To reduce computer viruses.', 'A soft and durable fabric, please.', 'Probably later this month.', NULL, 'C', 'Câu hỏi: Khi nào phần mềm bảo mật sẽ được cài đặt?"
A: "Để giảm thiểu virus máy tính."
B: "Một loại vải mềm và bền, làm ơn."
C: "Có lẽ vào cuối tháng này."
Giải thích: Đáp án C đúng vì câu hỏi yêu cầu thời gian cài đặt phần mềm bảo mật, và đáp án C đưa ra dự đoán về thời gian."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5415, 240, '2025/test5/audio/test5_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6812, 5415, 12, 'Why has the annual company retreat been postponed?', 'Because the venue had been double-booked.', 'To the last weekend in July.', 'Everyone enjoyed the team-building activities.', NULL, 'A', 'Câu hỏi: Tại sao chuyến đi nghỉ mát hàng năm của công ty lại bị hoãn?"
A: "Vì địa điểm đã bị đặt chồng lên nhau."
B: "Đến cuối tuần cuối tháng Bảy."
C: "Mọi người đều thích các hoạt động xây dựng đội ngũ."
Giải thích: Đáp án A đúng vì câu hỏi về lý do hoãn, và đáp án A giải thích nguyên nhân do địa điểm bị đặt chồng lịch."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5416, 240, '2025/test5/audio/test5_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6813, 5416, 13, 'Does Ms. Bradford teach music classes online or just in person?', 'Preparing for a music recital.', 'Only in person, I think.', 'She plays the piano well.', NULL, 'B', 'Câu hỏi: Cô Bradford dạy các lớp học âm nhạc trực tuyến hay chỉ trực tiếp?"
A: "Chuẩn bị cho một buổi hòa tấu âm nhạc."
B: "Chỉ trực tiếp, tôi nghĩ vậy."
C: "Cô ấy chơi piano rất giỏi."
Giải thích: Đáp án B đúng vì câu hỏi yêu cầu về phương thức giảng dạy của cô Bradford, và đáp án B chỉ rõ cô ấy chỉ dạy trực tiếp."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5417, 240, '2025/test5/audio/test5_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6814, 5417, 14, 'What''s the fastest way to get to the new furniture outlet store downtown?', 'I''ll check the map application on my phone.', 'The deadline has already passed, unfortunately.', 'It had a lot of fantastic deals.', NULL, 'A', 'Câu hỏi: Cách nhanh nhất để đến cửa hàng đồ nội thất mới ở trung tâm thành phố là gì?"
A: "Tôi sẽ kiểm tra ứng dụng bản đồ trên điện thoại của mình."
B: "Hạn chót đã qua rồi, thật tiếc."
C: "Nó có rất nhiều ưu đãi tuyệt vời."
Giải thích: Đáp án A đúng vì câu hỏi về phương tiện di chuyển nhanh nhất, và đáp án A giải thích rằng sử dụng ứng dụng bản đồ trên điện thoại là cách tốt nhất."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5418, 240, '2025/test5/audio/test5_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6815, 5418, 15, 'Did you forget to order more disposable coffee cups in the large size?', 'They should have arrived earlier this week.', 'Oh, would you like milk or sugar?', 'Just sign the form at the bottom.', NULL, 'A', 'Câu hỏi: Bạn có quên đặt thêm cốc cà phê dùng một lần kích cỡ lớn không?"
A: "Chúng lẽ ra đã đến vào đầu tuần này."
B: "Ồ, bạn muốn sữa hay đường?"
C: "Chỉ cần ký vào mẫu đơn dưới cùng."
Giải thích: Đáp án A đúng vì câu hỏi về việc đặt thêm cốc cà phê, và đáp án A giải thích rằng chúng đáng ra đã được giao trong tuần này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5419, 240, '2025/test5/audio/test5_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6816, 5419, 16, 'How long does it take for the wallpaper glue to dry?', 'It comes in a variety of patterns.', 'The hallway and the largest bedroom.', 'I''ve never used this brand before.', NULL, 'C', 'Câu hỏi: Mất bao lâu để keo dán giấy dán tường khô?"
A: "Nó có nhiều mẫu mã khác nhau."
B: "Hành lang và phòng ngủ lớn nhất."
C: "Tôi chưa từng sử dụng thương hiệu này trước đây."
Giải thích: Đáp án C đúng vì câu hỏi về thời gian khô của keo dán tường, và đáp án C nói về việc chưa quen với sản phẩm, có thể ảnh hưởng đến thời gian khô."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5420, 240, '2025/test5/audio/test5_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6817, 5420, 17, 'Doesn''t this phone come with a free charger?', 'We charge an hourly rate.', 'No, she''s not here today.', 'You''re right let me find one.', NULL, 'C', 'Câu hỏi: Điện thoại này không đi kèm với bộ sạc miễn phí sao?
A. Chúng tôi tính phí theo giờ.
B. Không, hôm nay cô ấy không có ở đây.
C. Bạn nói đúng hãy để tôi tìm một cái.
Giải thích: Đáp án đúng là C vì câu hỏi về 1 bộ sạc đi kèm câu C trả lời cho việc nhân viên sẽ đi lấy bộ sạc cho người hỏi.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5421, 240, '2025/test5/audio/test5_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6818, 5421, 18, 'Who''s going to hang up the promotional banners?', 'No, he hasn''t gone there.', 'To advertise our upcoming show.', 'One of the interns can handle that.', NULL, 'C', 'Câu hỏi: Ai sẽ treo các biểu ngữ quảng cáo?"
A: "Không, anh ấy chưa đến đó."
B: "Để quảng cáo cho chương trình sắp tới của chúng ta."
C: "Một trong các thực tập sinh có thể làm việc đó."
Giải thích: Đáp án C đúng vì câu hỏi về ai sẽ thực hiện việc này, và đáp án C cho biết rằng một thực tập sinh sẽ làm công việc này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5422, 240, '2025/test5/audio/test5_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6819, 5422, 19, 'How do you change the machine''s power settings?', 'Because it might start to overheat.', 'There''s a helpful video online.', 'No, the power cables are down.', NULL, 'B', 'Câu hỏi: Làm thế nào để thay đổi cài đặt nguồn của máy?"
A: "Bởi vì nó có thể bắt đầu quá nhiệt."
B: "Có một video hữu ích trên mạng."
C: "Không, các dây nguồn đang bị ngắt."
Giải thích: Đáp án B đúng vì câu hỏi về cách thay đổi cài đặt nguồn, và đáp án B chỉ ra rằng có một video hướng dẫn hữu ích trực tuyến."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5423, 240, '2025/test5/audio/test5_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6820, 5423, 20, 'I''m ordering coffee for the team after lunch.', 'I''m in charge of the team.', 'Oh, I''m taking the afternoon off.', 'She ordered more copies of the book.', NULL, 'B', 'Câu hỏi: Tôi đang đặt cà phê cho nhóm sau bữa trưa."
A: "Tôi phụ trách nhóm."
B: "Ồ, tôi sẽ nghỉ buổi chiều."
C: "Cô ấy đã đặt thêm bản sao của cuốn sách."
Giải thích: Đáp án B đúng vì câu hỏi về việc đặt cà phê, và đáp án B nói rằng người này sẽ nghỉ buổi chiều, không liên quan đến việc đặt cà phê."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5424, 240, '2025/test5/audio/test5_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6821, 5424, 21, 'They''re planning to offer vegetarian dishes at the staff dinner, right?', 'I''d better check the menu again.', 'No, I''ve already had a meal.', 'I''ll help you wash them now.', NULL, 'A', 'Câu hỏi: Họ đang lên kế hoạch cung cấp các món ăn chay tại bữa tối nhân viên, phải không?"
A: "Tôi nên kiểm tra lại thực đơn."
B: "Không, tôi đã ăn rồi."
C: "Tôi sẽ giúp bạn rửa chúng ngay."
Giải thích: Đáp án A đúng vì câu hỏi về việc cung cấp món ăn chay, và đáp án A nói rằng người hỏi sẽ kiểm tra thực đơn để chắc chắn."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5425, 240, '2025/test5/audio/test5_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6822, 5425, 22, 'Oh, this website requires a password.', 'It''s quieter than usual.', 'The confidential financial records.', 'You can sign in as a guest.', NULL, 'C', 'Câu hỏi: Ồ, trang web này yêu cầu mật khẩu."
A: "Nó yên tĩnh hơn bình thường."
B: "Các hồ sơ tài chính mật."
C: "Bạn có thể đăng nhập với tư cách khách."
Giải thích: Đáp án C đúng vì câu hỏi về việc trang web yêu cầu mật khẩu, và đáp án C cho biết một cách để truy cập là đăng nhập như khách mà không cần mật khẩu."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5426, 240, '2025/test5/audio/test5_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6823, 5426, 23, 'What can I do to give back to the community?', 'Yes, there''s a 60-day return policy.', 'A population of about thirty thousand.', 'The library has some volunteer opportunities.', NULL, 'C', 'Câu hỏi: Tôi có thể làm gì để đóng góp lại cho cộng đồng?"
A: "Vâng, có chính sách trả hàng trong 60 ngày."
B: "Dân số khoảng ba mươi nghìn."
C: "Thư viện có một số cơ hội tình nguyện."
Giải thích: Đáp án C đúng vì câu hỏi yêu cầu hành động đóng góp cho cộng đồng, và đáp án C cung cấp cơ hội tình nguyện tại thư viện."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5427, 240, '2025/test5/audio/test5_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6824, 5427, 24, 'Can you move the podium further away from the room''s entrance?', 'Of course, no problem.', 'There''s room for luggage.', 'On the table, please.', NULL, 'A', 'Câu hỏi: Bạn có thể di chuyển bục phát biểu xa cửa phòng hơn không?"
A: "Tất nhiên, không vấn đề gì."
B: "Có chỗ để hành lý."
C: "Trên bàn, làm ơn."
Giải thích: Đáp án A đúng vì câu hỏi yêu cầu di chuyển bục phát biểu, và đáp án A đồng ý và khẳng định sẽ thực hiện yêu cầu này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5428, 240, '2025/test5/audio/test5_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6825, 5428, 25, 'Do we have any qualified applicants for the marketing position?', 'It''s a high-quality product.', 'He bought some office supplies.', 'I''ll speak to the recruiter again.', NULL, 'C', 'Câu hỏi: Chúng ta có ứng viên đủ tiêu chuẩn cho vị trí marketing không?"
A: "Đó là một sản phẩm chất lượng cao."
B: "Anh ấy đã mua một số đồ dùng văn phòng."
C: "Tôi sẽ nói chuyện với nhà tuyển dụng lần nữa."
Giải thích: Đáp án C đúng vì câu hỏi về ứng viên, và đáp án C nói rằng sẽ nói chuyện với nhà tuyển dụng để kiểm tra lại tình hình ứng viên."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5429, 240, '2025/test5/audio/test5_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6826, 5429, 26, 'I can be compensated for unused vacation days, right?', 'Yes, they had a wonderful time.', 'The procedure is not straightforward.', 'I haven''t selected a destination.', NULL, 'B', 'Câu hỏi: Tôi có thể được bồi thường cho những ngày nghỉ phép chưa sử dụng, đúng không?"
A: "Vâng, họ đã có một thời gian tuyệt vời."
B: "Quy trình này không đơn giản."
C: "Tôi chưa chọn điểm đến."
Giải thích: Đáp án B đúng vì câu hỏi về việc bồi thường cho nghỉ phép chưa sử dụng, và đáp án B chỉ ra rằng quy trình này khá phức tạp."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5430, 240, '2025/test5/audio/test5_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6827, 5430, 27, 'Where can I get my parking pass renewed for the company lot?', 'At least two weeks in advance.', 'No, there are plenty of spots available.', 'I don''t drive to work.', NULL, 'C', 'Câu hỏi: Tôi có thể gia hạn thẻ đỗ xe cho bãi đỗ xe công ty ở đâu?"
A: "Ít nhất là hai tuần trước."
B: "Không, có rất nhiều chỗ trống."
C: "Tôi không lái xe đi làm."
Giải thích: Đáp án C đúng vì câu hỏi về việc gia hạn thẻ đỗ xe, và đáp án C cho biết người này không lái xe đến nơi làm việc, nên không cần gia hạn thẻ."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5431, 240, '2025/test5/audio/test5_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6828, 5431, 28, 'When does the company usually conduct employee performance reviews?', 'We were impressed by the show.', 'Above average ratings.', 'Around the end of the fourth quarter.', NULL, 'C', 'Câu hỏi: Công ty thường thực hiện đánh giá hiệu suất nhân viên vào khi nào?"
A: "Chúng tôi đã ấn tượng với chương trình."
B: "Các đánh giá trên mức trung bình."
C: "Vào khoảng cuối quý bốn."
Giải thích: Đáp án C đúng vì câu hỏi về thời gian đánh giá hiệu suất, và đáp án C đưa ra thời điểm cụ thể vào cuối quý bốn."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5432, 240, '2025/test5/audio/test5_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6829, 5432, 29, 'To use the advanced hiking trail, can I go by myself, or do I need a guide?', 'The national park opens soon.', 'A gorgeous view from the top.', 'Sign up for a group hike.', NULL, 'C', 'Câu hỏi: Để sử dụng đường mòn leo núi nâng cao, tôi có thể đi một mình hay cần một hướng dẫn viên?"
A: "Công viên quốc gia sẽ mở cửa sớm."
B: "Một cảnh đẹp từ đỉnh núi."
C: "Đăng ký tham gia chuyến leo núi theo nhóm."
Giải thích: Đáp án C đúng vì câu hỏi về việc có thể đi một mình hay không, và đáp án C nói rằng cần phải đăng ký cho chuyến leo núi theo nhóm."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5433, 240, '2025/test5/audio/test5_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6830, 5433, 30, 'Can you forward me the itinerary for the trip overseas?', 'Sure, she oversees construction projects.', 'It has not been finalized yet.', 'A window seat, please.', NULL, 'B', 'Câu hỏi: Bạn có thể chuyển tiếp cho tôi lịch trình chuyến đi nước ngoài không?"
A: "Tất nhiên, cô ấy giám sát các dự án xây dựng."
B: "Nó vẫn chưa được hoàn thiện."
C: "Một chỗ ngồi bên cửa sổ, làm ơn."
Giải thích: Đáp án B đúng vì câu hỏi yêu cầu lịch trình chuyến đi, và đáp án B chỉ ra rằng lịch trình chưa được hoàn thiện."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5434, 240, '2025/test5/audio/test5_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6831, 5434, 31, 'Don''t the building''s doors lock automatically after nine P.M.?', 'He works at an automobile factory.', 'No, it''s not the most reliable system.', 'I like the building''s design.', NULL, 'B', 'Câu hỏi: Cửa của tòa nhà không tự động khóa sau 9 giờ tối sao?"
A: "Anh ấy làm việc tại một nhà máy ô tô."
B: "Không, hệ thống này không phải là hệ thống đáng tin cậy nhất."
C: "Tôi thích thiết kế của tòa nhà."
Giải thích: Đáp án B đúng vì câu hỏi về tính năng tự động khóa của cửa, và đáp án B chỉ ra rằng hệ thống khóa này không hoàn toàn đáng tin cậy."');;

-- Data for 2025 Test5 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5435, 241, '2025/test5/audio/test5_question_32_34.mp3', NULL, 'M-Au: Ms. Calvert, as you requested, I''ve just moved you to an earlier flight for your business trip to Manchester. You''re now departing at eight A.M. instead of ten-thirty.
W-Am: Thank you! That will be much better.
M-Au: Happy to help. And remember to bring along your company credit card for purchases while you''re away.
W-Am: Yes, of course. Oh, and does the hotel offer a shuttle from the airport? That would be easier than trying to figure out which public bus to take.', 'Nam: Cô Calvert, theo yêu cầu của cô, tôi vừa chuyển cô sang chuyến bay sớm hơn cho chuyến công tác đến Manchester. Bây giờ cô sẽ khởi hành lúc 8 giờ sáng thay vì 10 giờ 30.
Nữ: Cảm ơn anh! Như vậy sẽ tốt hơn nhiều.
Nam: Rất vui được giúp đỡ. Và nhớ mang theo thẻ tín dụng công ty cho các khoản chi tiêu khi cô đi nhé.
Nữ: Vâng, tất nhiên rồi. Ồ, và khách sạn có cung cấp xe đưa đón từ sân bay không? Điều đó sẽ dễ dàng hơn là cố gắng tìm hiểu xe buýt công cộng nào để đi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6832, 5435, 32, 'What did the man just do?', 'He selected a rental car', 'He changed a travel itinerary', 'He upgraded a hotel reservation', 'He approved some vacation time', 'B', 'Question: "What did the man just do?" (Người đàn ông vừa làm gì?)
A: He selected a rental car (Anh ấy đã chọn một chiếc xe thuê)
B: He changed a travel itinerary (Anh ấy đã thay đổi lịch trình chuyến đi)
C: He upgraded a hotel reservation (Anh ấy đã nâng cấp đặt phòng khách sạn)
D: He approved some vacation time (Anh ấy đã phê duyệt thời gian nghỉ phép)

Người đàn ông vừa thay đổi chuyến bay cho Ms. Calvert sang sớm hơn: "I''ve just moved you to an earlier flight... You''re now departing at eight A.M. instead of ten-thirty" (Tôi vừa chuyển chị sang chuyến bay sớm hơn... Bây giờ chị sẽ khởi hành lúc 8 giờ sáng thay vì 10 giờ 30).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5436, 241, '2025/test5/audio/test5_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6833, 5436, 33, 'What does the man remind the woman about?', 'Weighing her luggage carefully', 'Purchasing some travel insurance', 'Saving receipts for purchases', 'Bringing a company credit card', 'D', 'Question: "What does the man remind the woman about?" (Người đàn ông nhắc nhở người phụ nữ về điều gì?)
A: Weighing her luggage carefully (Cân hành lý cẩn thận)
B: Purchasing some travel insurance (Mua bảo hiểm du lịch)
C: Saving receipts for purchases (Giữ hóa đơn cho các khoản chi)
D: Bringing a company credit card (Mang theo thẻ tín dụng công ty)

Người đàn ông nhắc Ms. Calvert mang theo thẻ tín dụng công ty: "remember to bring along your company credit card for purchases while you''re away" (nhớ mang theo thẻ tín dụng công ty cho các khoản chi tiêu khi cô đi nhé).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5437, 241, '2025/test5/audio/test5_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6834, 5437, 34, 'What does the woman inquire about?', 'A job requirement', 'A dining establishment', 'A business center', 'A shuttle service', 'D', 'Question: "What does the woman inquire about?" (Người phụ nữ hỏi về điều gì?)
A: A job requirement (Một yêu cầu công việc)
B: A dining establishment (Một nhà hàng)
C: A business center (Một trung tâm doanh nghiệp)
D: A shuttle service (Một dịch vụ đưa đón)

Người phụ nữ hỏi về dịch vụ đưa đón của khách sạn từ sân bay: "does the hotel offer a shuttle from the airport?" (khách sạn có cung cấp xe đưa đón từ sân bay không?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5438, 241, '2025/test5/audio/test5_question_35_37.mp3', NULL, 'w-Br: Sean, I''m wondering if you have any ideas for improving the sales of our smart TV.
M-Cn: How about having employees show shoppers how to use the different features it has? Once people see how easy it is to use, I think they''ll want to buy it.
W-Br: Hmm... that''s a good idea, but there isn''t any room on the shop floor for people to gather to watch something like that. We would have to move some items around. Let''s go to that area now and see if we can adjust the layout.', 'Nữ: Sean, tôi tự hỏi anh có ý tưởng gì để cải thiện doanh số bán TV thông minh của chúng ta không.
Nam: Hay là để nhân viên chỉ cho người mua cách sử dụng các tính năng khác nhau của nó? Một khi mọi người thấy nó dễ sử dụng như thế nào, tôi nghĩ họ sẽ muốn mua nó.
Nữ: Hmm... đó là một ý kiến hay, nhưng không có chỗ trên sàn bán hàng cho mọi người tụ tập để xem cái gì đó như thế. Chúng ta sẽ phải di chuyển một số đồ xung quanh. Hãy đến khu vực đó ngay bây giờ và xem liệu chúng ta có thể điều chỉnh bố cục không.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6835, 5438, 35, 'What industry do the speakers most likely work in?', 'Finance', 'Publishing', 'Technology', 'Pharmaceutical', 'C', 'Question: "What industry do the speakers most likely work in?" (Những người nói chuyện nhiều khả năng làm việc trong ngành nào?)
A: Finance (Tài chính)
B: Publishing (Xuất bản)
C: Technology (Công nghệ)
D: Pharmaceutical (Dược phẩm)

Họ làm việc trong ngành công nghệ vì:
1. Họ bán smart TV (TV thông minh)
2. Thảo luận về việc trình diễn các tính năng của sản phẩm
3. Đây là sản phẩm điển hình của ngành công nghệ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5439, 241, '2025/test5/audio/test5_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6836, 5439, 36, 'What does the man suggest doing?', 'Consulting employees from other branches', 'Giving demonstrations in the store', 'Creating a smartphone application for customers', 'Featuring an item in a magazine advertisement', 'B', 'Question: "What does the man suggest doing?" (Người đàn ông đề xuất làm gì?)
A: Consulting employees from other branches (Tham khảo ý kiến nhân viên từ các chi nhánh khác)
B: Giving demonstrations in the store (Trình diễn trong cửa hàng)
C: Creating a smartphone application for customers (Tạo ứng dụng điện thoại cho khách hàng)
D: Featuring an item in a magazine advertisement (Giới thiệu sản phẩm trên quảng cáo tạp chí)

Người đàn ông đề xuất để nhân viên trình diễn cách sử dụng các tính năng cho khách hàng: "having employees show shoppers how to use the different features" (để nhân viên chỉ cho người mua cách sử dụng các tính năng khác nhau).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5440, 241, '2025/test5/audio/test5_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6837, 5440, 37, 'What is the woman worried about?', 'The business will relocate soon', 'The suggested plan will cost too much', 'An activity requires too much space', 'A room needs to be redecorated', 'C', 'Question: "What is the woman worried about?" (Người phụ nữ lo lắng về điều gì?)
A: The business will relocate soon (Doanh nghiệp sẽ sớm chuyển địa điểm)
B: The suggested plan will cost too much (Kế hoạch đề xuất sẽ tốn quá nhiều)
C: An activity requires too much space (Một hoạt động cần quá nhiều không gian)
D: A room needs to be redecorated (Một phòng cần được trang trí lại)

Người phụ nữ lo lắng về việc không có đủ không gian cho buổi trình diễn: "there isn''t any room on the shop floor for people to gather to watch something like that" (không có chỗ trên sàn bán hàng cho mọi người tụ tập để xem cái gì đó như thế).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5441, 241, '2025/test5/audio/test5_question_38_40.mp3', NULL, 'M-Au: Hi, Cassandra. This Friday, I want to do something special for Ms. Wilkins at our department meeting. As she just received a promotion last week, I''d like to order her a cake. Can you recommend a local bakery?
W-Br: Whenever I''m celebrating a special occasion, I use Maxwell Bakery. It''s located just a few doors down, opposite Marietta Pharmacy.
M-Au: Thanks! I just have to check these financial reports, and then I''ll stop by on my lunch break.', 'Nam: Chào Cassandra. Thứ Sáu này, tôi muốn làm điều gì đó đặc biệt cho cô Wilkins tại cuộc họp phòng của chúng ta. Vì cô ấy vừa được thăng chức tuần trước, tôi muốn đặt một cái bánh cho cô ấy. Bạn có thể giới thiệu một tiệm bánh địa phương không?
Nữ: Bất cứ khi nào tôi kỷ niệm một dịp đặc biệt, tôi đều sử dụng Tiệm bánh Maxwell. Nó nằm cách vài cửa hàng, đối diện với Hiệu thuốc Marietta.
Nam: Cảm ơn! Tôi chỉ cần kiểm tra những báo cáo tài chính này, và sau đó tôi sẽ ghé qua trong giờ nghỉ trưa.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6838, 5441, 38, 'Why does the man want to order a cake for Ms. Wilkins?', 'She has received an award', 'She will celebrate her birthday', 'She has recently been promoted', 'She will leave the company soon', 'C', 'Question: "Why does the man want to order a cake for Ms. Wilkins?" (Tại sao người đàn ông muốn đặt bánh cho Ms. Wilkins?)
A: She has received an award (Cô ấy đã nhận được giải thưởng)
B: She will celebrate her birthday (Cô ấy sẽ kỷ niệm sinh nhật)
C: She has recently been promoted (Cô ấy vừa được thăng chức)
D: She will leave the company soon (Cô ấy sẽ sớm rời công ty)

Người đàn ông muốn đặt bánh cho Ms. Wilkins vì cô ấy vừa được thăng chức tuần trước: "she just received a promotion last week" (cô ấy vừa được thăng chức tuần trước).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5442, 241, '2025/test5/audio/test5_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6839, 5442, 39, 'According to the woman, where is Maxwell Bakery?', 'Across from a pharmacy', 'Next to the office', 'In a shopping mall', 'Behind a bank', 'A', 'Question: "According to the woman, where is Maxwell Bakery?" (Theo người phụ nữ, Tiệm bánh Maxwell ở đâu?)
A: Across from a pharmacy (Đối diện một hiệu thuốc)
B: Next to the office (Cạnh văn phòng)
C: In a shopping mall (Trong một trung tâm mua sắm)
D: Behind a bank (Phía sau một ngân hàng)

Theo người phụ nữ, Tiệm bánh Maxwell nằm đối diện Hiệu thuốc Marietta: "opposite Marietta Pharmacy" (đối diện với Hiệu thuốc Marietta).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5443, 241, '2025/test5/audio/test5_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6840, 5443, 40, 'What does the man plan to do before taking a lunch break?', 'Ask Ms. Wilkins for a preference', 'Check a department''s budget', 'Set up a job interview', 'Review some documents', 'D', 'Question: "What does the man plan to do before taking a lunch break?" (Người đàn ông dự định làm gì trước khi nghỉ trưa?)
A: Ask Ms. Wilkins for a preference (Hỏi sở thích của Ms. Wilkins)
B: Check a department''s budget (Kiểm tra ngân sách phòng ban)
C: Set up a job interview (Sắp xếp một cuộc phỏng vấn việc làm)
D: Review some documents (Xem xét một số tài liệu)

Người đàn ông nói rằng anh ấy cần kiểm tra các báo cáo tài chính trước: "I just have to check these financial reports" (Tôi chỉ cần kiểm tra những báo cáo tài chính này).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5444, 241, '2025/test5/audio/test5_question_41_43.mp3', NULL, 'M-Au: Cheryl and Reiko, have you heard back from the city representative about the contract for our company to move their office items to the new site?
W-Am: Well, a committee has to make the decision, and we are not the only company they are looking at.
w-Br: Right. I spoke to Patricia Walsh, our point of contact, this morning, and she said they are accepting bids from some of our competitors.
M-Au: Hmm... this could be a big job. We could tell them we can throw in the shelf assembly service at no charge. That might make our package more attractive.', 'Nam: Cheryl và Reiko, các bạn đã nhận được phản hồi từ đại diện thành phố về hợp đồng cho công ty chúng ta chuyển đồ văn phòng của họ đến địa điểm mới chưa?
Nữ 1: À, một ủy ban phải đưa ra quyết định, và chúng ta không phải là công ty duy nhất họ đang xem xét.
Nữ 2: Đúng vậy. Tôi đã nói chuyện với Patricia Walsh, người liên hệ của chúng ta, sáng nay, và cô ấy nói họ đang nhận các đề xuất từ một số đối thủ của chúng ta.
Nam: Hmm... đây có thể là một công việc lớn. Chúng ta có thể nói với họ rằng chúng ta sẽ thêm dịch vụ lắp ráp kệ miễn phí. Điều đó có thể làm cho gói dịch vụ của chúng ta hấp dẫn hơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6841, 5444, 41, 'Where do the speakers most likely work?', 'At a real estate agency', 'At a cleaning service', 'At a moving company', 'At an architecture firm', 'C', 'Question: "Where do the speakers most likely work?" (Những người nói chuyện nhiều khả năng làm việc ở đâu?)
A: At a real estate agency (Tại một công ty bất động sản)
B: At a cleaning service (Tại một dịch vụ vệ sinh)
C: At a moving company (Tại một công ty chuyển nhà)
D: At an architecture firm (Tại một công ty kiến trúc)

Họ làm việc tại một công ty chuyển nhà vì:
1. Họ đang đấu thầu hợp đồng chuyển đồ văn phòng
2. Có thể cung cấp dịch vụ lắp ráp kệ
3. Thảo luận về việc chuyển đồ đạc đến địa điểm mới');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5445, 241, '2025/test5/audio/test5_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6842, 5445, 42, 'What problem do the women mention?', 'Some employees do not have enough experience', 'The area has been experiencing bad weather', 'A requested item is not currently available', 'Potential clients are considering other options', 'D', 'Question: "What problem do the women mention?" (Những người phụ nữ đề cập đến vấn đề gì?)
A: Some employees do not have enough experience (Một số nhân viên không có đủ kinh nghiệm)
B: The area has been experiencing bad weather (Khu vực đang gặp thời tiết xấu)
C: A requested item is not currently available (Một mặt hàng được yêu cầu hiện không có sẵn)
D: Potential clients are considering other options (Khách hàng tiềm năng đang xem xét các lựa chọn khác)

Những người phụ nữ đề cập đến việc công ty họ không phải là lựa chọn duy nhất và khách hàng đang nhận các đề xuất từ các đối thủ cạnh tranh: "we are not the only company they are looking at" và "they are accepting bids from some of our competitors".');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5446, 241, '2025/test5/audio/test5_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6843, 5446, 43, 'What does the man suggest doing?', 'Canceling a business contract', 'Offering a free service', 'Updating a software package', 'Extending a proposed deadline', 'B', 'Question: "What does the man suggest doing?" (Người đàn ông đề xuất làm gì?)
A: Canceling a business contract (Hủy một hợp đồng kinh doanh)
B: Offering a free service (Cung cấp một dịch vụ miễn phí)
C: Updating a software package (Cập nhật một gói phần mềm)
D: Extending a proposed deadline (Kéo dài thời hạn đề xuất)

Người đàn ông đề xuất cung cấp dịch vụ lắp ráp kệ miễn phí: "we can throw in the shelf assembly service at no charge" (chúng ta sẽ thêm dịch vụ lắp ráp kệ miễn phí).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5447, 241, '2025/test5/audio/test5_question_44_46.mp3', NULL, 'M-cn: Ms. Fleming, l''ve finished ironing the shirts for today.
W-Br: Great. And were you able to get the stain out of Mr. Morgan''s suit?
M-Cn: Yes. And I just need to put a few more clothes in bags for pickup tomorrow. That''ll be finished before closing time. That''s at seven o''clock, right?
w-Br: Yes, that''s correct.
M-Cn: Hmm... I know I''ve just transferred here, but I''m wondering why other branches of our business are open until nine o''clock and we''re not. Wouldn''t that be more convenient for customers?
w-Br: Well, there are not many apartment buildings around here. This neighborhood is empty after office hours.
M-Cn: That makes sense. Thanks! Now I won''t have to ask at tomorrow''s staff meeting.', 'Nam: Cô Fleming, tôi đã ủi xong áo sơ mi cho hôm nay.
Nữ: Tuyệt. Và anh đã tẩy được vết bẩn trên bộ com-lê của ông Morgan chưa?
Nam: Rồi. Và tôi chỉ cần cho thêm vài bộ quần áo vào túi để lấy vào ngày mai. Điều đó sẽ hoàn thành trước giờ đóng cửa. Đó là lúc 7 giờ, phải không?
Nữ: Vâng, đúng vậy.
Nam: Hmm... Tôi biết tôi vừa chuyển đến đây, nhưng tôi tự hỏi tại sao các chi nhánh khác của chúng ta mở cửa đến 9 giờ mà chúng ta thì không. Điều đó chẳng phải sẽ thuận tiện hơn cho khách hàng sao?
Nữ: À, không có nhiều tòa nhà căn hộ quanh đây. Khu vực này vắng vẻ sau giờ làm việc.
Nam: Điều đó có lý. Cảm ơn! Giờ tôi sẽ không phải hỏi trong cuộc họp nhân viên ngày mai nữa.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6844, 5447, 44, 'Where most likely are the speakers?', 'At a shipping company', 'At a clothing shop', 'At a fitness club', 'At a dry cleaner''s', 'D', 'Question: "Where most likely are the speakers?" (Những người nói chuyện nhiều khả năng ở đâu?)
A: At a shipping company (Tại một công ty vận chuyển)
B: At a clothing shop (Tại một cửa hàng quần áo)
C: At a fitness club (Tại một câu lạc bộ thể dục)
D: At a dry cleaner''s (Tại một tiệm giặt là)

Họ đang ở tiệm giặt là vì:
1. Thảo luận về việc ủi áo sơ mi
2. Tẩy vết bẩn trên bộ com-lê
3. Chuẩn bị quần áo cho khách lấy vào ngày mai');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5448, 241, '2025/test5/audio/test5_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6845, 5448, 45, 'Why does the woman say, "there are not many apartment buildings around here"?', 'To explain why a closing time is earlier', 'To suggest searching for a new home', 'To complain about a long commute', 'To apologize for a lack of available parking', 'A', 'Question: "Why does the woman say, ''there are not many apartment buildings around here''?" (Tại sao người phụ nữ nói "không có nhiều tòa nhà căn hộ quanh đây"?)
A: To explain why a closing time is earlier (Để giải thích tại sao thời gian đóng cửa sớm hơn)
B: To suggest searching for a new home (Để đề xuất tìm nhà mới)
C: To complain about a long commute (Để phàn nàn về quãng đường đi làm dài)
D: To apologize for a lack of available parking (Để xin lỗi về việc thiếu chỗ đậu xe)

Người phụ nữ đưa ra lý do này để giải thích tại sao chi nhánh họ đóng cửa sớm hơn (7 giờ thay vì 9 giờ) - vì khu vực này vắng vẻ sau giờ làm việc do không có nhiều dân cư.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5449, 241, '2025/test5/audio/test5_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6846, 5449, 46, 'What will happen tomorrow?', 'Staff evaluations will be carried out', 'Some employees will attend a meeting', 'A new company policy will go into effect', 'A staff member will transfer from another branch', 'B', 'Question: "What will happen tomorrow?" (Điều gì sẽ xảy ra vào ngày mai?)
A: Staff evaluations will be carried out (Đánh giá nhân viên sẽ được thực hiện)
B: Some employees will attend a meeting (Một số nhân viên sẽ tham dự một cuộc họp)
C: A new company policy will go into effect (Một chính sách công ty mới sẽ có hiệu lực)
D: A staff member will transfer from another branch (Một nhân viên sẽ chuyển từ chi nhánh khác)

Sẽ có cuộc họp nhân viên vào ngày mai, được đề cập trong câu: "tomorrow''s staff meeting" (cuộc họp nhân viên ngày mai).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5450, 241, '2025/test5/audio/test5_question_47_49.mp3', NULL, 'W-Br: Brennan Institute. How can I help you?
M-Cn: Hi, I''m a manager at Melville Sales. I''d like to book a private painting class for my team. There are seven people in our group, and we would prefer to come on June 5, in the afternoon.
W-Br: I''m very sorry, but we''ll be closed on June 5 because were having some damaged ceiling tiles fixed in our hallway.
M-cn: Oh, I see. Would you have anything available later that week?
W-Br: How about June 6 at three o''clock? Tammy Orozco could work with your group then.
M-Cn: That sounds good. What would be the fee per person?
w-Br: I''ll need to double-check that, so please wait on the line while I look it up.', 'Nữ: Viện Brennan. Tôi có thể giúp gì cho anh?
Nam: Chào, tôi là quản lý tại Melville Sales. Tôi muốn đặt một lớp học vẽ riêng cho đội của tôi. Có bảy người trong nhóm chúng tôi, và chúng tôi muốn đến vào ngày 5 tháng 6, vào buổi chiều.
Nữ: Tôi rất xin lỗi, nhưng chúng tôi sẽ đóng cửa vào ngày 5 tháng 6 vì chúng tôi đang sửa chữa một số tấm trần bị hư hỏng trong hành lang.
Nam: Ồ, tôi hiểu rồi. Các bạn có lịch nào khác trong tuần đó không?
Nữ: Vậy ngày 6 tháng 6 lúc 3 giờ thì sao? Tammy Orozco có thể làm việc với nhóm của anh lúc đó.
Nam: Nghe có vẻ ổn. Phí cho mỗi người là bao nhiêu?
Nữ: Tôi sẽ cần kiểm tra lại điều đó, vì vậy vui lòng giữ máy trong khi tôi tra cứu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6847, 5450, 47, 'Where does the woman work?', 'At a department store', 'At a law office', 'At a recruitment firm', 'At an art institute', 'D', 'Question: "Where does the woman work?" (Người phụ nữ làm việc ở đâu?)
A: At a department store (Tại một cửa hàng bách hóa)
B: At a law office (Tại một văn phòng luật)
C: At a recruitment firm (Tại một công ty tuyển dụng)
D: At an art institute (Tại một viện nghệ thuật)

Người phụ nữ làm việc tại Viện Brennan, một viện nghệ thuật cung cấp các lớp học vẽ: "Brennan Institute" và "private painting class" (lớp học vẽ riêng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5451, 241, '2025/test5/audio/test5_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6848, 5451, 48, 'Why is the man unable to use a service on June 5?', 'Some employees will be trained', 'Some tiles will be repaired', 'An entrance will be blocked', 'A schedule is already full', 'B', 'Question: "Why is the man unable to use a service on June 5?" (Tại sao người đàn ông không thể sử dụng dịch vụ vào ngày 5 tháng 6?)
A: Some employees will be trained (Một số nhân viên sẽ được đào tạo)
B: Some tiles will be repaired (Một số tấm lát sẽ được sửa chữa)
C: An entrance will be blocked (Một lối vào sẽ bị chặn)
D: A schedule is already full (Lịch đã kín)

Viện sẽ đóng cửa vào ngày 5 tháng 6 để sửa chữa các tấm trần bị hư hỏng: "we''ll be closed on June 5 because were having some damaged ceiling tiles fixed in our hallway" (chúng tôi sẽ đóng cửa vào ngày 5 tháng 6 vì chúng tôi đang sửa chữa một số tấm trần bị hư hỏng trong hành lang).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5452, 241, '2025/test5/audio/test5_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6849, 5452, 49, 'What will the man most likely do next?', 'Select a payment method', 'Provide a list of attendees', 'Confirm a mailing address', 'Wait for some information', 'D', 'Question: "What will the man most likely do next?" (Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?)
A: Select a payment method (Chọn phương thức thanh toán)
B: Provide a list of attendees (Cung cấp danh sách người tham dự)
C: Confirm a mailing address (Xác nhận địa chỉ gửi thư)
D: Wait for some information (Đợi một số thông tin)

Người đàn ông sẽ đợi trong khi người phụ nữ kiểm tra thông tin về phí: "please wait on the line while I look it up" (vui lòng giữ máy trong khi tôi tra cứu).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5453, 241, '2025/test5/audio/test5_question_50_52.mp3', NULL, 'Hi, Takeshi. Are you busy? Jasmine and I are having trouble getting supplies for our department.
I''ve got some time now. What''s going on?
When we try to place the order, it says there are insufficient funds.
Right. But we''re not requesting more than we usually do each quarter.
Well, all of us on the accounting team have been getting a lot of questions about this. Didn''t you get the memo saying that funds will be allocated monthly from now on? You probably exceeded the monthly budget.
Oh, we''ve been away on business. We''d better catch up on the e-mails and memos we missed now.', 'Xin chào, Takeshi. Anh có bận không? Jasmine và tôi đang gặp khó khăn trong việc đặt vật tư cho phòng ban của chúng tôi.
Tôi đang rảnh. Chuyện gì vậy?
Khi chúng tôi cố đặt hàng, hệ thống báo không đủ tiền.
Đúng vậy. Nhưng chúng ta không yêu cầu nhiều hơn mức thường đặt mỗi quý.
Vâng, tất cả chúng tôi trong nhóm kế toán đều nhận được nhiều câu hỏi về việc này. Các bạn không nhận được thông báo nói rằng từ giờ ngân sách sẽ được phân bổ theo tháng sao? Có lẽ các bạn đã vượt quá ngân sách tháng.
Ôi, chúng tôi đã đi công tác. Chúng tôi nên bắt kịp các email và thông báo đã bỏ lỡ ngay bây giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6850, 5453, 50, 'What problem are the speakers discussing?', 'An order for supplies is not being processed', 'An employee handbook is missing information', 'Some equipment has broken components', 'Some team members were not assigned tasks', 'A', 'Question: What problem are the speakers discussing? (Vấn đề gì đang được thảo luận bởi những người nói chuyện?)
A: An order for supplies is not being processed (Một đơn đặt hàng vật tư không được xử lý)
B: An employee handbook is missing information (Sổ tay nhân viên thiếu thông tin)
C: Some equipment has broken components (Một số thiết bị có các thành phần bị hỏng)
D: Some team members were not assigned tasks (Một số thành viên trong nhóm không được giao nhiệm vụ)

Giải thích: Đáp án A là chính xác vì trong đoạn hội thoại, Jasmine và người nói đang gặp vấn đề khi đặt hàng vật tư (having trouble getting supplies). Cụ thể, khi họ cố gắng đặt hàng thì hệ thống báo không đủ tiền (When we try to place the order, it says there are insufficient funds).
Lý do là do họ đã vượt quá ngân sách hàng tháng vì không biết rằng ngân sách giờ được phân bổ theo tháng thay vì theo quý như trước đây.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5454, 241, '2025/test5/audio/test5_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6851, 5454, 51, 'Who most likely is the man?', 'A product designer', 'A sales manager', 'A company accountant', 'A delivery person', 'C', 'Question: Who most likely is the man? (Người đàn ông trong đoạn hội thoại rất có thể là ai?)
A: A product designer (Một nhà thiết kế sản phẩm)
B: A sales manager (Một quản lý bán hàng)
C: A company accountant (Một kế toán viên của công ty)
D: A delivery person (Một người giao hàng)

Giải thích: Đáp án C là chính xác vì trong đoạn hội thoại, người đàn ông nói rằng all of us on the accounting team - tất cả chúng tôi trong nhóm kế toán, cho thấy anh ấy là một thành viên của đội ngũ kế toán của công ty.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5455, 241, '2025/test5/audio/test5_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6852, 5455, 52, 'What will the women most likely do next?', 'Update their computer passwords', 'Read some work-related messages', 'Depart for a business trip', 'Print a budget report', 'B', 'Question: What will the women most likely do next? (Những người phụ nữ sẽ làm gì tiếp theo?)
A: Update their computer passwords (Cập nhật mật khẩu máy tính)
B: Read some work-related messages (Đọc một số tin nhắn liên quan đến công việc)
C: Depart for a business trip (Khởi hành đi công tác)
D: Print a budget report (In báo cáo ngân sách)

Giải thích: Đáp án B là chính xác vì ở cuối đoạn hội thoại, các người phụ nữ nói We''d better catch up on the e-mails and memos we missed now - Chúng tôi nên bắt kịp các email và thông báo đã bỏ lỡ ngay bây giờ, cho thấy họ sẽ đọc các tin nhắn công việc mà họ đã bỏ lỡ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5456, 241, '2025/test5/audio/test5_question_53_55.mp3', NULL, 'Hi, Ms. Frazier. This is Ivan Ellis, the caterer who hosted the tasting event last week. You''re preparing for a company celebration, right?
Yes. Next month will be our company''s thirtieth anniversary, so we''re holding a dinner.
Great! I''m calling because we''ve added a few more appetizer options. If you''re still considering your menu, I''d love for you to try them.
We signed a contract with Newton Services.
Oh, I see. Well, I hope we can work together in the future.
Actually, it''s good that you called. We have an orientation session for employees this Thursday. Our lunch reservation was canceled, so I wonder if you can make a meal at the last minute.', 'Xin chào, bà Frazier. Tôi là Ivan Ellis, người làm ẩm thực đã tổ chức sự kiện nếm thử tuần trước. Bà đang chuẩn bị cho một buổi lễ kỷ niệm công ty, phải không?
Vâng. Tháng sau sẽ là kỷ niệm 30 năm thành lập công ty chúng tôi, vì vậy chúng tôi sẽ tổ chức một bữa tối.
Tuyệt! Tôi gọi vì chúng tôi đã thêm một vài lựa chọn món khai vị. Nếu bà vẫn đang cân nhắc thực đơn, tôi rất muốn bà thử chúng.
Chúng tôi đã ký hợp đồng với Newton Services.
Ôi, tôi hiểu rồi. Vâng, tôi hy vọng chúng ta có thể hợp tác trong tương lai.
Thực ra, thật tốt là anh đã gọi. Chúng tôi có một buổi định hướng cho nhân viên vào thứ Năm này. Đặt chỗ ăn trưa của chúng tôi đã bị hủy, vậy nên tôi tự hỏi liệu anh có thể chuẩn bị một bữa ăn vào phút cuối không.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6853, 5456, 53, 'Who is the man?', 'A caterer', 'A driver', 'A journalist', 'A florist', 'A', 'Question: Who is the man? (Người đàn ông là ai?)
A: A caterer (Một người làm ẩm thực)
B: A driver (Một tài xế)
C: A journalist (Một nhà báo)
D: A florist (Một người bán hoa)

Giải thích: Đáp án A là chính xác vì ngay từ đầu đoạn hội thoại, người đàn ông đã tự giới thiệu mình là Ivan Ellis, the caterer - người làm ẩm thực đã tổ chức sự kiện nếm thử tuần trước.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5457, 241, '2025/test5/audio/test5_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6854, 5457, 54, 'Why does the woman say, ''We signed a contract with Newton Services''?', 'To reject an offer', 'To apologize for a delay', 'To recommend a company', 'To reassure the man', 'A', 'Question: Why does the woman say, ''We signed a contract with Newton Services''? (Tại sao người phụ nữ nói ''Chúng tôi đã ký hợp đồng với Newton Services''?)
A: To reject an offer (Để từ chối một đề nghị)
B: To apologize for a delay (Để xin lỗi về sự chậm trễ)
C: To recommend a company (Để giới thiệu một công ty)
D: To reassure the man (Để trấn an người đàn ông)

Giải thích: Đáp án A là chính xác vì người phụ nữ đã nói câu này để từ chối đề nghị thử món khai vị mới của người đàn ông, bằng cách cho anh ấy biết họ đã ký hợp đồng với một công ty khác (Newton Services).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5458, 241, '2025/test5/audio/test5_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6855, 5458, 55, 'What does the woman ask the man to do?', 'Plan an orientation session', 'Fulfill a last-minute request', 'Suggest a day to meet', 'Provide a bulk discount', 'B', 'Question: What does the woman ask the man to do? (Người phụ nữ yêu cầu người đàn ông làm gì?)
A: Plan an orientation session (Lập kế hoạch cho một buổi định hướng)
B: Fulfill a last-minute request (Đáp ứng một yêu cầu vào phút cuối)
C: Suggest a day to meet (Đề xuất một ngày để gặp)
D: Provide a bulk discount (Cung cấp giảm giá số lượng lớn)

Giải thích: Đáp án B là chính xác vì ở cuối đoạn hội thoại, người phụ nữ yêu cầu người đàn ông chuẩn bị một bữa ăn vào phút cuối cho buổi định hướng vào thứ Năm (I wonder if you can make a meal at the last minute) sau khi đặt chỗ ăn trưa của họ bị hủy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5459, 241, '2025/test5/audio/test5_question_56_58.mp3', NULL, 'Thanks for seeing me today, Lucas. Our company is running into some problems with the building models for the documentary. Some scenes require a tower from a century ago, but the model is not ready yet.
Hmm... We have other models from previous projects, but I don''t think those will look authentic. They need to fit the period.
Actually, there is some room in the travel budget. We could shoot footage in person at a real structure.
That might be our only choice.
Could you do some research on the architecture of the time and see if anything in the area matches what we need?
Sure.', 'Cảm ơn anh đã gặp tôi hôm nay, Lucas. Công ty chúng tôi đang gặp một số vấn đề với mô hình tòa nhà cho bộ phim tài liệu. Một số cảnh cần một tòa tháp từ một thế kỷ trước, nhưng mô hình vẫn chưa sẵn sàng.
Hmm... Chúng ta có các mô hình khác từ các dự án trước, nhưng tôi không nghĩ chúng sẽ trông chân thực. Chúng cần phải phù hợp với thời kỳ đó.
Thực ra, trong ngân sách đi lại còn một chút dư. Chúng ta có thể quay cảnh trực tiếp tại một công trình thật.
Đó có thể là lựa chọn duy nhất của chúng ta.
Anh có thể nghiên cứu về kiến trúc của thời kỳ đó và xem liệu có gì trong khu vực phù hợp với những gì chúng ta cần không?
Được.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6856, 5459, 56, 'Which industry do the speakers most likely work in?', 'Interior design', 'Construction', 'Film production', 'Tourism', 'C', 'Question: Which industry do the speakers most likely work in? (Những người nói chuyện rất có thể làm việc trong ngành nào?)
A: Interior design (Thiết kế nội thất)
B: Construction (Xây dựng)
C: Film production (Sản xuất phim)
D: Tourism (Du lịch)

Giải thích: Đáp án C là chính xác vì trong đoạn hội thoại, họ đang thảo luận về việc làm mô hình tòa nhà cho một bộ phim tài liệu (building models for the documentary) và việc quay cảnh (shoot footage), cho thấy họ làm việc trong ngành sản xuất phim.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5460, 241, '2025/test5/audio/test5_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6857, 5460, 57, 'What is the man concerned about?', 'Saving space', 'Maintaining authenticity', 'Reducing expenses', 'Following regulations', 'B', 'Question: What is the man concerned about? (Người đàn ông lo lắng về điều gì?)
A: Saving space (Tiết kiệm không gian)
B: Maintaining authenticity (Duy trì tính chân thực)
C: Reducing expenses (Giảm chi phí)
D: Following regulations (Tuân thủ quy định)

Giải thích: Đáp án B là chính xác vì người đàn ông đã bày tỏ lo lắng về việc các mô hình cũ sẽ không trông chân thực (won''t look authentic) và cần phải phù hợp với thời kỳ đó (need to fit the period), cho thấy anh ấy quan tâm đến việc duy trì tính chân thực của cảnh quay.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5461, 241, '2025/test5/audio/test5_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6858, 5461, 58, 'What does the woman ask the man to do?', 'Look into hiring some temporary workers', 'Perform photo editing on some images', 'Research architecture in the area', 'Find some colors to match a logo', 'C', 'Question: What does the woman ask the man to do? (Người phụ nữ yêu cầu người đàn ông làm gì?)
A: Look into hiring some temporary workers (Tìm hiểu việc thuê một số nhân viên tạm thời)
B: Perform photo editing on some images (Thực hiện chỉnh sửa ảnh)
C: Research architecture in the area (Nghiên cứu kiến trúc trong khu vực)
D: Find some colors to match a logo (Tìm một số màu sắc để phù hợp với logo)

Giải thích: Đáp án C là chính xác vì trong đoạn hội thoại, người phụ nữ đã yêu cầu người đàn ông nghiên cứu về kiến trúc của thời kỳ đó và tìm kiếm các công trình phù hợp trong khu vực (Could you do some research on the architecture of the time and see if anything in the area matches what we need?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5462, 241, '2025/test5/audio/test5_question_59_61.mp3', NULL, 'Good morning, Ms. Hawthorne. Thanks for coming to give your feedback on our new line of cookware.
I think it will be fun. So, will I actually get a chance to cook with the items?
Yes. We have a test kitchen on the second floor. Before we go there, could you please put on this visitor ID badge? It will help our security team to know that you are supposed to be in the building.
Of course. Do you need me to do anything else?
We have your contact information, but we do need you to sign some non-disclosure forms. I''ve got them right here.', 'Chào buổi sáng, bà Hawthorne. Cảm ơn bà đã đến để đưa ra phản hồi về dòng sản phẩm đồ nấu ăn mới của chúng tôi.
Tôi nghĩ nó sẽ rất vui. Vậy, tôi có thực sự có cơ hội nấu ăn với những món đồ này không?
Vâng. Chúng tôi có một nhà bếp thử nghiệm ở tầng hai. Trước khi chúng ta đến đó, xin vui lòng đeo thẻ ID khách này vào? Nó sẽ giúp đội ngũ an ninh của chúng tôi biết rằng bà được phép có mặt trong tòa nhà.
Tất nhiên rồi. Anh cần tôi làm gì khác không?
Chúng tôi đã có thông tin liên lạc của bà, nhưng chúng tôi cần bà ký một số biểu mẫu bảo mật. Tôi có chúng ngay đây.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6859, 5462, 59, 'Why did the woman visit the man''s business?', 'To repair some cooking equipment', 'To share her opinions about products', 'To meet with some investors', 'To lead a business strategy seminar', 'B', 'Question: Why did the woman visit the man''s business? (Tại sao người phụ nữ đến thăm doanh nghiệp của người đàn ông?)
A: To repair some cooking equipment (Để sửa chữa một số thiết bị nấu ăn)
B: To share her opinions about products (Để chia sẻ ý kiến của cô ấy về sản phẩm)
C: To meet with some investors (Để gặp một số nhà đầu tư)
D: To lead a business strategy seminar (Để dẫn dắt một buổi hội thảo về chiến lược kinh doanh)

Giải thích: Đáp án B là chính xác vì ngay từ đầu đoạn hội thoại, người đàn ông đã cảm ơn người phụ nữ đã đến để đưa ra phản hồi về dòng sản phẩm đồ nấu ăn mới của họ (Thanks for coming to give your feedback on our new line of cookware).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5463, 241, '2025/test5/audio/test5_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6860, 5463, 60, 'What does the man ask the woman to put on?', 'A staff uniform', 'An ID badge', 'A safety vest', 'A hard hat', 'B', 'Question: What does the man ask the woman to put on? (Người đàn ông yêu cầu người phụ nữ đeo gì?)
A: A staff uniform (Đồng phục nhân viên)
B: An ID badge (Thẻ ID)
C: A safety vest (Áo khoác an toàn)
D: A hard hat (Mũ bảo hiểm)

Giải thích: Đáp án B là chính xác vì trong đoạn hội thoại, người đàn ông đã yêu cầu người phụ nữ đeo thẻ ID khách (could you please put on this visitor ID badge?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5464, 241, '2025/test5/audio/test5_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6861, 5464, 61, 'What will the woman probably do next?', 'Take a building tour', 'Enjoy a meal', 'Sign some paperwork', 'Provide her contact information', 'C', 'Question: What will the woman probably do next? (Người phụ nữ có thể sẽ làm gì tiếp theo?)
A: Take a building tour (Tham quan tòa nhà)
B: Enjoy a meal (Thưởng thức bữa ăn)
C: Sign some paperwork (Ký một số giấy tờ)
D: Provide her contact information (Cung cấp thông tin liên lạc)

Giải thích: Đáp án C là chính xác vì ở cuối đoạn hội thoại, người đàn ông nói rằng họ cần người phụ nữ ký một số biểu mẫu bảo mật (we do need you to sign some non-disclosure forms) và anh ấy đã có sẵn các biểu mẫu đó (I''ve got them right here).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5465, 241, '2025/test5/audio/test5_question_62_64.mp3', '2025/test5/image/test5-p3-image-62.jpg', 'Tae-Soo, I''m glad to run into you. I heard you hired an agency to develop an advertising campaign for the car dealership.
That''s right. I felt like professionals could help us reach new customers.
That makes sense. How far along in the development process are you?
They''ve just presented me with three potential concepts. Once I choose one, they''ll begin to finalize it.
I see. Well, let me know if you''d like me to look over them. I''d be very interested to see the agency''s work.
Sure, I''d appreciate your input. Today won''t work, though. The financing department needs me to sign off on their latest set of contracts.', 'Tae-Soo, tôi rất vui khi gặp anh. Tôi nghe nói anh đã thuê một công ty để phát triển chiến dịch quảng cáo cho đại lý xe hơi.
Đúng vậy. Tôi cảm thấy các chuyên gia có thể giúp chúng tôi tiếp cận khách hàng mới.
Điều đó hợp lý. Anh đã tiến hành được đến đâu trong quá trình phát triển?
Họ vừa trình bày cho tôi ba concept tiềm năng. Sau khi tôi chọn một cái, họ sẽ bắt đầu hoàn thiện nó.
Tôi hiểu rồi. Vậy, hãy cho tôi biết nếu anh muốn tôi xem qua chúng. Tôi rất quan tâm đến công việc của công ty quảng cáo.
Được, tôi đánh giá cao ý kiến của chị. Tuy nhiên, hôm nay thì không được. Phòng tài chính cần tôi ký một số hợp đồng mới nhất của họ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6862, 5465, 62, 'What is the conversation mainly about?', 'Hiring methods', 'Vehicle designs', 'Safety regulations', 'Marketing plans', 'D', 'Question: What is the conversation mainly about? (Cuộc trò chuyện chủ yếu nói về điều gì?)
A: Hiring methods (Phương pháp tuyển dụng)
B: Vehicle designs (Thiết kế xe)
C: Safety regulations (Quy định an toàn)
D: Marketing plans (Kế hoạch marketing)

Giải thích: Đáp án D là chính xác vì cuộc trò chuyện tập trung vào việc thuê một công ty quảng cáo để phát triển chiến dịch quảng cáo (develop an advertising campaign) cho đại lý xe hơi. Họ thảo luận về tiến trình phát triển và các concept tiềm năng, đây đều là các yếu tố của kế hoạch marketing.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5466, 241, '2025/test5/audio/test5_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6863, 5466, 63, 'Look at the graphic. What phase is the project currently in?', 'Phase 1', 'Phase 2', 'Phase 3', 'Phase 4', 'C', 'Question: Look at the graphic. What phase is the project currently in? (Nhìn vào hình đồ họa. Dự án hiện đang ở giai đoạn nào?)
A: Phase 1 (Giai đoạn 1)
B: Phase 2 (Giai đoạn 2)
C: Phase 3 (Giai đoạn 3)
D: Phase 4 (Giai đoạn 4)

Giải thích: Đáp án C là chính xác vì trong đoạn hội thoại, người đàn ông nói rằng công ty quảng cáo vừa trình bày cho anh ấy ba concept tiềm năng (They''ve just presented me with three potential concepts). Điều này tương ứng với Giai đoạn 3 trong hình đồ họa - Present options to clients (Trình bày các lựa chọn cho khách hàng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5467, 241, '2025/test5/audio/test5_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6864, 5467, 64, 'What does the man say he has to do today?', 'Arrange a quality inspection', 'Approve some legal agreements', 'Draft a financial report', 'Check the business''s inventory', 'B', 'Question: What does the man say he has to do today? (Người đàn ông nói anh ấy phải làm gì hôm nay?)
A: Arrange a quality inspection (Sắp xếp kiểm tra chất lượng)
B: Approve some legal agreements (Phê duyệt một số thỏa thuận pháp lý)
C: Draft a financial report (Soạn thảo báo cáo tài chính)
D: Check the business''s inventory (Kiểm tra hàng tồn kho của doanh nghiệp)

Giải thích: Đáp án B là chính xác vì cuối đoạn hội thoại, người đàn ông nói rằng phòng tài chính cần anh ấy ký một số hợp đồng mới nhất của họ (The financing department needs me to sign off on their latest set of contracts).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5468, 241, '2025/test5/audio/test5_question_65_67.mp3', '2025/test5/image/test5-p3-image-65.jpg', 'Do you have a minute, Blake? The ceremony to honor our top-performing employees is coming soon, and I''m designing the invitations. What do you think of this first draft?
Hmm... Everything looks fine, but I think the slideshow should start at the same time as the live music. It''s quite long, so we don''t want the event to run too late.
True. Any other suggestions?
You know, it''s not a very well-known venue. How about adding a line telling people how to get to the banquet hall by car?
Good idea. I''ll do that.', 'Anh có rảnh một phút không, Blake? Buổi lễ vinh danh các nhân viên có thành tích xuất sắc sắp đến, và tôi đang thiết kế thiệp mời. Anh nghĩ sao về bản nháp đầu tiên này?
Hmm... Mọi thứ có vẻ ổn, nhưng tôi nghĩ buổi chiếu slide nên bắt đầu cùng lúc với phần biểu diễn nhạc sống. Nó khá dài, nên chúng ta không muốn sự kiện kéo dài quá muộn.
Đúng vậy. Anh có đề xuất gì khác không?
Anh biết đấy, đó không phải là một địa điểm nổi tiếng. Hay là thêm một dòng chỉ dẫn mọi người cách đi đến phòng tiệc bằng xe hơi?
Ý kiến hay đấy. Tôi sẽ làm vậy.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6865, 5468, 65, 'What kind of event is being planned?', 'A coworker''s birthday celebration', 'A company awards ceremony', 'A new employee training session', 'A colleague''s retirement dinner', 'B', 'Question: What kind of event is being planned? (Sự kiện nào đang được lên kế hoạch?)
A: A coworker''s birthday celebration (Lễ kỷ niệm sinh nhật của đồng nghiệp)
B: A company awards ceremony (Lễ trao giải của công ty)
C: A new employee training session (Buổi đào tạo nhân viên mới)
D: A colleague''s retirement dinner (Bữa tối chia tay đồng nghiệp nghỉ hưu)

Giải thích: Đáp án B là chính xác vì ngay đầu đoạn hội thoại đề cập đến ceremony to honor our top-performing employees - buổi lễ vinh danh các nhân viên có thành tích xuất sắc, cho thấy đây là một buổi lễ trao giải của công ty.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5469, 241, '2025/test5/audio/test5_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6866, 5469, 66, 'Look at the graphic. What time does the man think the photo slideshow should begin?', 'At 6:30 P.M.', 'At 7:30 P.M.', 'At 8:30 P.M.', 'At 9:30 P.M.', 'C', 'Question: Look at the graphic. What time does the man think the photo slideshow should begin? (Nhìn vào hình đồ họa. Người đàn ông nghĩ buổi chiếu slide ảnh nên bắt đầu vào lúc mấy giờ?)
A: At 6:30 P.M. (Lúc 6:30 tối)
B: At 7:30 P.M. (Lúc 7:30 tối)
C: At 8:30 P.M. (Lúc 8:30 tối)
D: At 9:30 P.M. (Lúc 9:30 tối)

Giải thích: Đáp án C là chính xác vì người đàn ông nói rằng buổi chiếu slide nên bắt đầu cùng lúc với phần biểu diễn nhạc sống (the slideshow should start at the same time as the live music). Trong hình đồ họa cho thấy phần Live Music bắt đầu lúc 8:30 P.M.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5470, 241, '2025/test5/audio/test5_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6867, 5470, 67, 'What does the man suggest adding to the invitation?', 'A list of menu options', 'The venue''s phone number', 'Some driving directions', 'Some employees'' job titles', 'C', 'Question: What does the man suggest adding to the invitation? (Người đàn ông đề xuất thêm gì vào thiệp mời?)
A: A list of menu options (Danh sách các lựa chọn thực đơn)
B: The venue''s phone number (Số điện thoại của địa điểm)
C: Some driving directions (Một số chỉ dẫn đường đi)
D: Some employees'' job titles (Chức danh của một số nhân viên)

Giải thích: Đáp án C là chính xác vì người đàn ông đề xuất thêm một dòng chỉ dẫn cách đi đến phòng tiệc bằng xe hơi (How about adding a line telling people how to get to the banquet hall by car?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5471, 241, '2025/test5/audio/test5_question_68_70.mp3', '2025/test5/image/test5-p3-image-68.jpg', 'Hi, I got a call saying that there''s a problem with one of your air conditioning units. I''m here to fix that.
Oh, you arrived sooner than I expected. Do you need help bringing in your equipment?
Well, I''d like to take a look at it first to see what I''m dealing with.
Of course. It''s in Mr. Griffith''s office, which is the room nearest to the elevator, just past the copy room.
Thanks. Do I need to put on a visitor ID badge?
Yes, I''ve got one right here for you. Please don''t forget to drop it off with me when you leave.', 'Xin chào, tôi nhận được cuộc gọi nói rằng có vấn đề với một trong những máy điều hòa của các bạn. Tôi đến để sửa chữa.
Ôi, anh đến sớm hơn tôi mong đợi. Anh có cần giúp mang thiết bị vào không?
Vâng, tôi muốn xem qua nó trước để biết mình đang đối phó với vấn đề gì.
Tất nhiên. Nó ở trong văn phòng của ông Griffith, phòng gần thang máy nhất, ngay sau phòng photocopy.
Cảm ơn. Tôi có cần đeo thẻ ID khách không?
Vâng, tôi có một cái ngay đây cho anh. Xin đừng quên trả lại cho tôi khi anh rời đi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6868, 5471, 68, 'Why is the man visiting the business?', 'To pick up some brochures', 'To give a sales pitch', 'To sign a contract', 'To make a repair', 'D', 'Question: Why is the man visiting the business? (Tại sao người đàn ông đến thăm doanh nghiệp?)
A: To pick up some brochures (Để lấy một số tài liệu quảng cáo)
B: To give a sales pitch (Để thuyết trình bán hàng)
C: To sign a contract (Để ký hợp đồng)
D: To make a repair (Để sửa chữa)

Giải thích: Đáp án D là chính xác vì ngay đầu đoạn hội thoại, người đàn ông nói rằng anh ấy đến vì có vấn đề với một trong những máy điều hòa và anh ấy đến để sửa chữa (there''s a problem with one of your air conditioning units. I''m here to fix that).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5472, 241, '2025/test5/audio/test5_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6869, 5472, 69, 'Look at the graphic. Where does the woman direct the man to go?', 'Office 101', 'Office 102', 'Office 103', 'Copy room', 'C', 'Question: Look at the graphic. Where does the woman direct the man to go? (Nhìn vào hình đồ họa. Người phụ nữ chỉ dẫn người đàn ông đi đến đâu?)
A: Office 101 (Văn phòng 101)
B: Office 102 (Văn phòng 102)
C: Office 103 (Văn phòng 103)
D: Copy room (Phòng photocopy)

Giải thích: Đáp án C là chính xác vì người phụ nữ nói máy điều hòa nằm trong văn phòng của ông Griffith, là phòng gần thang máy nhất, ngay sau phòng photocopy (It''s in Mr. Griffith''s office, which is the room nearest to the elevator, just past the copy room). Nhìn vào sơ đồ, Office 103 là phòng duy nhất thỏa mãn điều kiện này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5473, 241, '2025/test5/audio/test5_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6870, 5473, 70, 'What does the woman ask the man to do?', 'Avoid using an elevator', 'Return a badge later', 'Leave his business card', 'Remove his outerwear', 'B', 'Question: What does the woman ask the man to do? (Người phụ nữ yêu cầu người đàn ông làm gì?)
A: Avoid using an elevator (Tránh sử dụng thang máy)
B: Return a badge later (Trả lại thẻ sau)
C: Leave his business card (Để lại danh thiếp)
D: Remove his outerwear (Cởi áo khoác ngoài)

Giải thích: Đáp án B là chính xác vì cuối đoạn hội thoại, người phụ nữ yêu cầu người đàn ông đừng quên trả lại thẻ ID khách khi rời đi (Please don''t forget to drop it off with me when you leave).');;

-- Data for 2025 Test5 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5474, 242, '2025/test5/audio/test5_question_71_73.mp3', NULL, 'The last thing I''d like to discuss today is ensuring the best quality while making our energy drinks and sodas here at Kinney Company. Before you add any ingredients, please make sure that they have not expired. We have recently received some outdated goods from our supplier, so we can''t let these get into our final products. And, if you do find anything that cannot be used, please place it in the yellow box in the main corridor. We would like to collect everything in the same place so we can make a return. Thank you for your cooperation.', 'Điều cuối cùng tôi muốn thảo luận hôm nay là đảm bảo chất lượng tốt nhất khi sản xuất nước tăng lực và nước ngọt tại Công ty Kinney. Trước khi thêm bất kỳ thành phần nào, vui lòng đảm bảo rằng chúng chưa hết hạn. Chúng tôi gần đây đã nhận được một số hàng hóa đã hết hạn từ nhà cung cấp, vì vậy chúng ta không thể để những thứ này lọt vào sản phẩm cuối cùng. Và nếu bạn tìm thấy bất cứ thứ gì không thể sử dụng được, vui lòng đặt nó vào hộp màu vàng ở hành lang chính. Chúng tôi muốn thu thập mọi thứ ở cùng một nơi để có thể trả lại.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6871, 5474, 71, 'What does the speaker''s company produce?', 'Exercise equipment', 'Light fixtures', 'Automobiles', 'Beverages', 'D', '[Dịch] Câu hỏi: Công ty của người nói sản xuất cái gì?
A: Thiết bị tập thể dục
B: Đèn chiếu sáng
C: Ô tô
D: Đồ uống

Đáp án D là chính xác vì đoạn văn đề cập rõ công ty sản xuất "energy drinks and sodas" (nước tăng lực và nước ngọt).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5475, 242, '2025/test5/audio/test5_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6872, 5475, 72, 'What does the speaker remind the listeners to do?', 'Check some expiration dates', 'Update their contact information', 'Review a purchasing agreement', 'Record their working hours', 'A', '[Dịch] Câu hỏi: Người nói nhắc nhở người nghe làm gì?
A: Kiểm tra một số ngày hết hạn
B: Cập nhật thông tin liên hệ
C: Xem xét thỏa thuận mua hàng
D: Ghi lại giờ làm việc

Đáp án A là chính xác vì người nói yêu cầu "make sure that they have not expired" (đảm bảo rằng chúng chưa hết hạn) khi nói về các thành phần nguyên liệu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5476, 242, '2025/test5/audio/test5_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6873, 5476, 73, 'What can be found in the main corridor?', 'A collection container', 'A box of tools', 'An order form', 'An employee directory', 'A', '[Dịch] Câu hỏi: Có thể tìm thấy gì ở hành lang chính?
A: Một thùng thu gom
B: Một hộp công cụ
C: Một mẫu đơn đặt hàng
D: Một danh bạ nhân viên

Đáp án A là chính xác vì đoạn văn đề cập đến "yellow box in the main corridor" (hộp màu vàng ở hành lang chính) được dùng để thu gom các mặt hàng không thể sử dụng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5477, 242, '2025/test5/audio/test5_question_74_76.mp3', NULL, 'Hi, Monica. I''ve arrived here at the community center. I''ve just set up the photo booth so I can take group shots of people attending the food festival. The organizers have assigned me a spot near the live band. I know you were worried that I wouldn''t be able to plug in all of the extra lights I brought, but I can see several power outlets. Anyway, I''m actually calling to remind you to put up the posting for the assistant photographer job today on the Web sites we discussed. We need to get that role filled as soon as possible.', 'Chào Monica. Tôi đã đến trung tâm cộng đồng. Tôi vừa thiết lập xong quầy chụp ảnh để có thể chụp ảnh nhóm của những người tham dự lễ hội ẩm thực. Ban tổ chức đã chỉ định cho tôi một vị trí gần ban nhạc sống. Tôi biết bạn đã lo lắng rằng tôi sẽ không thể cắm tất cả các đèn bổ sung mà tôi mang theo, nhưng tôi có thể thấy một số ổ cắm điện. Dù sao thì, tôi thực sự gọi để nhắc bạn đăng thông tin tuyển dụng vị trí phụ tá nhiếp ảnh gia hôm nay trên các trang web mà chúng ta đã thảo luận. Chúng ta cần điền vào vị trí đó càng sớm càng tốt.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6874, 5477, 74, 'What will the speaker do at the community center?', 'Serve some food samples', 'Give a public speech', 'Take people''s photographs', 'Advertise a family vacation', 'C', '[Dịch] Câu hỏi: Người nói sẽ làm gì tại trung tâm cộng đồng?
A: Phục vụ một số mẫu thức ăn
B: Phát biểu trước công chúng
C: Chụp ảnh mọi người
D: Quảng cáo kỳ nghỉ gia đình

Đáp án C là chính xác vì người nói cho biết họ đã thiết lập photo booth để "take group shots of people" (chụp ảnh nhóm mọi người) tại lễ hội ẩm thực.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5478, 242, '2025/test5/audio/test5_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6875, 5478, 75, 'Why does the speaker say, "I can see several power outlets"?', 'To reject an offer of assistance', 'To provide reassurance to the listener', 'To complain about an unfinished task', 'To ask for some clarification', 'B', '[Dịch] Câu hỏi: Tại sao người nói nói "Tôi có thể thấy một số ổ cắm điện"?
A: Để từ chối đề nghị giúp đỡ
B: Để trấn an người nghe
C: Để phàn nàn về một công việc chưa hoàn thành
D: Để yêu cầu làm rõ

Đáp án B là chính xác vì người nói đề cập điều này để trấn an Monica, người đã lo lắng về việc không thể cắm tất cả các đèn bổ sung ("you were worried that I wouldn''t be able to plug in all of the extra lights").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5479, 242, '2025/test5/audio/test5_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6876, 5479, 76, 'What does the speaker remind the listener to do?', 'Proofread some brochures', 'Post some information online', 'Fill out a reimbursement request', 'Renew a business license', 'B', '[Dịch] Câu hỏi: Người nói nhắc người nghe làm gì?
A: Đọc lại một số tờ rơi
B: Đăng một số thông tin trực tuyến
C: Điền vào yêu cầu hoàn tiền
D: Gia hạn giấy phép kinh doanh

Đáp án B là chính xác vì người nói nhắc Monica "put up the posting for the assistant photographer job today on the Web sites" (đăng thông tin tuyển dụng vị trí phụ tá nhiếp ảnh gia hôm nay trên các trang web).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5480, 242, '2025/test5/audio/test5_question_77_79.mp3', NULL, 'Thanks for tuning in to the business report on KRRT radio. Earlier this week, Rinehart Manufacturing moved its headquarters from New York to Boston. Rinehart Manufacturing is known for the refrigerators, washing machines, and dryers that it makes. A Rinehart spokesperson reported that the move allowed the company to expand and upgrade its facilities. To see the new building for yourself, visit Rinehart Manufacturing''s Web site, where you can browse the company''s online photo gallery.', 'Cảm ơn bạn đã theo dõi bản tin kinh doanh trên đài KRRT. Đầu tuần này, Rinehart Manufacturing đã chuyển trụ sở chính từ New York đến Boston. Rinehart Manufacturing được biết đến với các sản phẩm tủ lạnh, máy giặt và máy sấy mà họ sản xuất. Một phát ngôn viên của Rinehart cho biết việc di chuyển cho phép công ty mở rộng và nâng cấp cơ sở vật chất của mình. Để tự mình xem tòa nhà mới, hãy truy cập trang web của Rinehart Manufacturing, nơi bạn có thể duyệt qua thư viện ảnh trực tuyến của công ty.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6877, 5480, 77, 'What did Rinehart Manufacturing recently do?', 'It passed an annual factory safety inspection.', 'It changed the location of its headquarters.', 'It hired a new CEO to lead the company.', 'It introduced a popular new line of products.', 'B', '[Dịch] Câu hỏi: Rinehart Manufacturing gần đây đã làm gì?
A: Công ty đã vượt qua cuộc kiểm tra an toàn nhà máy hàng năm
B: Công ty đã thay đổi vị trí trụ sở chính
C: Công ty đã thuê CEO mới để lãnh đạo
D: Công ty đã giới thiệu dòng sản phẩm mới phổ biến

Đáp án B là chính xác vì đoạn văn nêu rõ "Rinehart Manufacturing moved its headquarters from New York to Boston" (Rinehart Manufacturing đã chuyển trụ sở chính từ New York đến Boston).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5481, 242, '2025/test5/audio/test5_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6878, 5481, 78, 'What kind of product does Rinehart Manufacturing make?', 'Tools', 'Automobiles', 'Clothing', 'Appliances', 'D', '[Dịch] Câu hỏi: Rinehart Manufacturing sản xuất loại sản phẩm gì?
A: Công cụ
B: Ô tô
C: Quần áo
D: Thiết bị gia dụng

Đáp án D là chính xác vì công ty được mô tả là sản xuất "refrigerators, washing machines, and dryers" (tủ lạnh, máy giặt và máy sấy), đây đều là các thiết bị gia dụng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5482, 242, '2025/test5/audio/test5_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6879, 5482, 79, 'What can the listeners find online?', 'Some job descriptions', 'Some driving directions', 'An updated staff directory', 'A collection of images', 'D', '[Dịch] Câu hỏi: Người nghe có thể tìm thấy gì trực tuyến?
A: Một số mô tả công việc
B: Một số chỉ đường
C: Danh bạ nhân viên đã cập nhật
D: Một bộ sưu tập hình ảnh

Đáp án D là chính xác vì đoạn văn cho biết người nghe có thể "browse the company''s online photo gallery" (duyệt qua thư viện ảnh trực tuyến của công ty) trên trang web của họ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5483, 242, '2025/test5/audio/test5_question_80_82.mp3', NULL, 'Thank you all for being here for today''s event. I would especially like to welcome city officials as well as one of our sponsors, Michael Rowley of Rowley Tech. I know I''m not alone in saying that this new library is essential for our community. In addition to books, magazines, and newspapers, we have a computer lab with twenty computers donated by Mr. Rowley''s shop. Now, before you start browsing, I''ve had pens custom-printed with the library''s hours of operation. Don''t forget to pick one up.', 'Cảm ơn tất cả các bạn đã có mặt tại sự kiện hôm nay. Tôi đặc biệt muốn chào đón các quan chức thành phố cũng như một trong những nhà tài trợ của chúng tôi, Michael Rowley của Rowley Tech. Tôi biết tôi không phải là người duy nhất nói rằng thư viện mới này là thiết yếu đối với cộng đồng của chúng ta. Ngoài sách, tạp chí và báo, chúng tôi có một phòng máy tính với hai mươi máy tính được tặng bởi cửa hàng của ông Rowley. Bây giờ, trước khi bắt đầu tham quan, tôi đã có những cây bút được in tùy chỉnh với giờ hoạt động của thư viện. Đừng quên lấy một cây.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6880, 5483, 80, 'What event is taking place?', 'A retirement party', 'A company picnic', 'A grand opening', 'A writing competition', 'C', '[Dịch] Câu hỏi: Sự kiện gì đang diễn ra?
A: Một buổi tiệc nghỉ hưu
B: Một buổi dã ngoại công ty
C: Một lễ khai trương
D: Một cuộc thi viết

Đáp án C là chính xác vì đây là sự kiện khai trương thư viện mới, được thể hiện qua việc người nói đề cập đến "this new library" và có sự hiện diện của các quan chức thành phố và nhà tài trợ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5484, 242, '2025/test5/audio/test5_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6881, 5484, 81, 'What kind of business does Mr. Rowley most likely own?', 'An electronics store', 'A clothing shop', 'A car dealership', 'An insurance company', 'A', '[Dịch] Câu hỏi: Ông Rowley có khả năng sở hữu loại doanh nghiệp gì?
A: Một cửa hàng điện tử
B: Một cửa hàng quần áo
C: Một đại lý ô tô
D: Một công ty bảo hiểm

Đáp án A là chính xác vì ông Rowley được giới thiệu từ "Rowley Tech" và cửa hàng của ông đã tặng hai mươi máy tính cho thư viện, cho thấy đây là một cửa hàng điện tử.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5485, 242, '2025/test5/audio/test5_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6882, 5485, 82, 'What has the speaker prepared for attendees?', 'Some tote bags', 'Some pens', 'Some business cards', 'Some printed calendars', 'B', '[Dịch] Câu hỏi: Người nói đã chuẩn bị gì cho người tham dự?
A: Một số túi xách
B: Một số bút
C: Một số danh thiếp
D: Một số lịch in

Đáp án B là chính xác vì người nói đề cập "I''ve had pens custom-printed with the library''s hours of operation" (Tôi đã có những cây bút được in tùy chỉnh với giờ hoạt động của thư viện).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5486, 242, '2025/test5/audio/test5_question_83_85.mp3', NULL, 'The last thing that I would like to talk about is our annual recruitment event. Just like last year, our gym will invite the public to take a tour of our facilities and learn about the exercise classes we offer. This is a great way to increase our membership. So far, three employees have volunteered to give tours. Five or six would be better. I''ll give you all the information you need, so please talk to me after this meeting if you can help. I know that some of you had ideas for what kinds of refreshments we should serve at the event. So, l''d like to take some time to hear those now.', 'Điều cuối cùng tôi muốn nói đến là sự kiện tuyển dụng thường niên của chúng ta. Giống như năm ngoái, phòng tập của chúng ta sẽ mời công chúng đến tham quan cơ sở vật chất và tìm hiểu về các lớp tập thể dục mà chúng ta cung cấp. Đây là một cách tuyệt vời để tăng số lượng hội viên. Cho đến nay, ba nhân viên đã tình nguyện dẫn tour. Năm hoặc sáu người sẽ tốt hơn. Tôi sẽ cung cấp cho các bạn tất cả thông tin cần thiết, vì vậy hãy nói chuyện với tôi sau cuộc họp này nếu bạn có thể giúp đỡ. Tôi biết một số bạn có ý tưởng về việc nên phục vụ những đồ ăn nhẹ gì tại sự kiện. Vì vậy, tôi muốn dành thời gian để nghe những ý kiến đó ngay bây giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6883, 5486, 83, 'Where do the listeners work?', 'At a fitness facility', 'At a clothing store', 'At a dental clinic', 'At a financial institution', 'A', '[Dịch] Câu hỏi: Người nghe làm việc ở đâu?
A: Tại một cơ sở thể dục
B: Tại một cửa hàng quần áo
C: Tại một phòng khám nha khoa
D: Tại một tổ chức tài chính

Đáp án A là chính xác vì đoạn văn đề cập họ làm việc tại một phòng tập ("our gym") và có các lớp tập thể dục ("exercise classes").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5487, 242, '2025/test5/audio/test5_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6884, 5487, 84, 'What does the speaker imply when she says, "Five or six would be better"?', 'The length of an event is too short.', 'A task requires more people.', 'More tables need to be set up.', 'Pages should be added to a tour brochure.', 'B', '[Dịch] Câu hỏi: Người nói ngụ ý gì khi cô ấy nói "Năm hoặc sáu người sẽ tốt hơn"?
A: Thời lượng của một sự kiện quá ngắn
B: Một nhiệm vụ cần thêm người
C: Cần phải thiết lập thêm bàn
D: Cần thêm trang vào tờ rơi hướng dẫn tour

Đáp án B là chính xác vì người nói đang đề cập đến việc cần thêm người tình nguyện dẫn tour, hiện tại chỉ có ba người đã tình nguyện ("three employees have volunteered to give tours").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5488, 242, '2025/test5/audio/test5_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6885, 5488, 85, 'What will the listeners probably do next?', 'Watch a sales presentation', 'Enjoy some free refreshments', 'Sign a membership contract', 'Share some of their suggestions', 'D', '[Dịch] Câu hỏi: Người nghe có khả năng sẽ làm gì tiếp theo?
A: Xem một bài thuyết trình bán hàng
B: Thưởng thức một số đồ ăn nhẹ miễn phí
C: Ký hợp đồng hội viên
D: Chia sẻ một số đề xuất của họ

Đáp án D là chính xác vì người nói kết thúc bằng việc muốn nghe ý kiến về đồ ăn nhẹ ("I''d like to take some time to hear those now"), cho thấy người nghe sẽ chia sẻ đề xuất của họ tiếp theo.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5489, 242, '2025/test5/audio/test5_question_86_88.mp3', NULL, 'Hi, Nicole. This is Eun-Seok. I''m calling about the meeting preparations for next Monday. First, I''d like to thank you for agreeing to speak to the board members about the specialty lab equipment with a voice command feature. I know that you were nervous about their reaction to the proposed investment, whether they think our company should be involved. Well, don''t forget that this device will be the first of its kind. Second, Carl can advise you about the approach you should take. He has worked directly with some of the members before, so his insights will be invaluable.', 'Chào Nicole. Tôi là Eun-Seok. Tôi gọi về việc chuẩn bị cho cuộc họp vào thứ Hai tới. Trước tiên, tôi muốn cảm ơn bạn đã đồng ý nói chuyện với các thành viên hội đồng về thiết bị phòng thí nghiệm đặc biệt với tính năng điều khiển bằng giọng nói. Tôi biết rằng bạn lo lắng về phản ứng của họ đối với khoản đầu tư được đề xuất, liệu họ có nghĩ rằng công ty chúng ta nên tham gia hay không. Chà, đừng quên rằng thiết bị này sẽ là thiết bị đầu tiên thuộc loại này. Thứ hai, Carl có thể tư vấn cho bạn về cách tiếp cận mà bạn nên thực hiện. Anh ấy đã từng làm việc trực tiếp với một số thành viên trước đây, vì vậy những hiểu biết của anh ấy sẽ vô cùng quý giá.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6886, 5489, 86, 'What is scheduled for next Monday?', 'A group interview session', 'A corporate board meeting', 'An annual factory inspection', 'An industry trade fair', 'B', '[Dịch] Câu hỏi: Điều gì được lên lịch vào thứ Hai tới?
A: Một buổi phỏng vấn nhóm
B: Một cuộc họp hội đồng công ty
C: Một cuộc kiểm tra nhà máy hàng năm
D: Một hội chợ thương mại ngành

Đáp án B là chính xác vì đoạn văn đề cập đến việc Nicole sẽ nói chuyện với "board members" (các thành viên hội đồng quản trị) về thiết bị phòng thí nghiệm đặc biệt.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5490, 242, '2025/test5/audio/test5_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6887, 5490, 87, 'Why does the speaker say, "this device will be the first of its kind"?', 'To express confidence in a proposal', 'To request more time for a project', 'To show concern about an investment', 'To correct an error in a business report', 'A', '[Dịch] Câu hỏi: Tại sao người nói nói "thiết bị này sẽ là thiết bị đầu tiên thuộc loại này"?
A: Để thể hiện sự tự tin vào một đề xuất
B: Để yêu cầu thêm thời gian cho một dự án
C: Để thể hiện sự lo ngại về một khoản đầu tư
D: Để sửa lỗi trong một báo cáo kinh doanh

Đáp án A là chính xác vì người nói dùng câu này để trấn an Nicole về tính độc đáo của thiết bị, thể hiện sự tự tin vào đề xuất đầu tư này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5491, 242, '2025/test5/audio/test5_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6888, 5491, 88, 'What does the speaker say about Carl?', 'He was involved in recruiting members.', 'He has given a demonstration for a device.', 'He will be the director of a project.', 'He can provide some helpful advice.', 'D', '[Dịch] Câu hỏi: Người nói nói gì về Carl?
A: Anh ấy đã tham gia tuyển dụng thành viên
B: Anh ấy đã thực hiện thị phạm cho một thiết bị
C: Anh ấy sẽ là giám đốc của một dự án
D: Anh ấy có thể đưa ra lời khuyên hữu ích

Đáp án D là chính xác vì người nói cho biết "Carl can advise you about the approach you should take" và nhấn mạnh rằng những hiểu biết của anh ấy sẽ rất quý giá.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5492, 242, '2025/test5/audio/test5_question_89_91.mp3', NULL, 'Good afternoon, everyone. I appreciate all of your hard work in helping customers find the right necklaces, rings, and bracelets to suit their style. Unfortunately, despite these efforts, our business is struggling due to several shops opening nearby. They sell very similar products to ours, though I believe our merchandise is of much better quality. I''m looking for ways to combat this problem. As an initial strategy, I''d like to give 10% off to first-time buyers. We can advertise this deal on social media. I hope it will attract more people to our store. Of course, if you have any other ideas that might help, please feel free to share them with me anytime.', 'Chào buổi chiều, mọi người. Tôi đánh giá cao tất cả nỗ lực của các bạn trong việc giúp khách hàng tìm những chiếc vòng cổ, nhẫn và vòng tay phù hợp với phong cách của họ. Thật không may, mặc dù có những nỗ lực này, doanh nghiệp của chúng ta đang gặp khó khăn do một số cửa hàng mở gần đây. Họ bán những sản phẩm rất giống với của chúng ta, mặc dù tôi tin rằng hàng hóa của chúng ta có chất lượng tốt hơn nhiều. Tôi đang tìm cách để đối phó với vấn đề này. Như một chiến lược ban đầu, tôi muốn giảm giá 10% cho người mua lần đầu. Chúng ta có thể quảng cáo ưu đãi này trên mạng xã hội. Tôi hy vọng nó sẽ thu hút thêm nhiều người đến cửa hàng của chúng ta. Tất nhiên, nếu bạn có bất kỳ ý tưởng nào khác có thể giúp ích, hãy thoải mái chia sẻ với tôi bất cứ lúc nào.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6889, 5492, 89, 'What kind of business does the speaker most likely work for?', 'A home improvement store', 'A flower shop', 'A jewelry store', 'A hair salon', 'C', '[Dịch] Câu hỏi: Người nói có khả năng làm việc cho loại doanh nghiệp nào?
A: Một cửa hàng cải thiện nhà cửa
B: Một cửa hàng hoa
C: Một cửa hàng trang sức
D: Một salon tóc

Đáp án C là chính xác vì đoạn văn đề cập đến việc bán "necklaces, rings, and bracelets" (vòng cổ, nhẫn và vòng tay), đây đều là các mặt hàng trang sức.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5493, 242, '2025/test5/audio/test5_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6890, 5493, 90, 'What is the speaker concerned about?', 'Several nearby roads will be closed.', 'Some merchandise was damaged in transit.', 'An advertising campaign was expensive.', 'Competition in the market has increased.', 'D', '[Dịch] Câu hỏi: Người nói lo lắng về điều gì?
A: Một số con đường gần đó sẽ bị đóng cửa
B: Một số hàng hóa đã bị hư hỏng trong quá trình vận chuyển
C: Một chiến dịch quảng cáo đã tốn kém
D: Sự cạnh tranh trên thị trường đã tăng lên

Đáp án D là chính xác vì người nói lo lắng về việc "several shops opening nearby" (một số cửa hàng mở gần đó) bán sản phẩm tương tự, làm tăng sự cạnh tranh.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5494, 242, '2025/test5/audio/test5_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6891, 5494, 91, 'What does the speaker say he will do?', 'Purchase more attractive display cases', 'Hire an experienced marketing consultant', 'Offer a discount to new customers', 'Provide free shipping on all orders', 'C', '[Dịch] Câu hỏi: Người nói nói anh ấy sẽ làm gì?
A: Mua thêm tủ trưng bày hấp dẫn
B: Thuê một chuyên gia tư vấn tiếp thị có kinh nghiệm
C: Cung cấp giảm giá cho khách hàng mới
D: Cung cấp giao hàng miễn phí cho tất cả đơn hàng

Đáp án C là chính xác vì người nói đề xuất "give 10% off to first-time buyers" (giảm giá 10% cho người mua lần đầu) như một chiến lược ban đầu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5495, 242, '2025/test5/audio/test5_question_92_94.mp3', NULL, 'Attention, please, warehouse employees. We have several large trucks arriving on Wednesday morning that must be unloaded quickly. Therefore, we need some of you to come in early that day, at 5:30 A.M. After your shift is over today, please stop by my office to let me know if you''re available. You''ll be paid the overtime rate for the additional hours. I know that some of you have signed up for the equipment repair workshop on Wednesday, but this task will be finished before then.', 'Chú ý, các nhân viên nhà kho. Chúng ta có một số xe tải lớn đến vào sáng thứ Tư cần được dỡ hàng nhanh chóng. Do đó, chúng tôi cần một số người trong các bạn đến sớm ngày hôm đó, lúc 5:30 sáng. Sau khi ca làm việc của bạn kết thúc hôm nay, vui lòng ghé qua văn phòng của tôi để cho tôi biết nếu bạn có thể tham gia. Bạn sẽ được trả lương làm thêm giờ cho những giờ bổ sung. Tôi biết một số bạn đã đăng ký tham gia hội thảo sửa chữa thiết bị vào thứ Tư, nhưng nhiệm vụ này sẽ hoàn thành trước đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6892, 5495, 92, 'Where is the announcement taking place?', 'At a repair shop', 'At a construction site', 'At an airport', 'At a warehouse', 'D', '[Dịch] Câu hỏi: Thông báo đang diễn ra ở đâu?
A: Tại một cửa hàng sửa chữa
B: Tại một công trường xây dựng
C: Tại một sân bay
D: Tại một nhà kho

Đáp án D là chính xác vì thông báo được gửi đến "warehouse employees" (nhân viên nhà kho) và nói về việc dỡ hàng từ nhiều xe tải lớn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5496, 242, '2025/test5/audio/test5_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6893, 5496, 93, 'Where should some listeners go after completing their shifts?', 'To the security desk', 'To the loading dock', 'To the speaker''s office', 'To the conference room', 'C', '[Dịch] Câu hỏi: Một số người nghe nên đi đâu sau khi hoàn thành ca làm việc của họ?
A: Đến bàn bảo vệ
B: Đến bến bốc dỡ hàng
C: Đến văn phòng của người nói
D: Đến phòng họp

Đáp án C là chính xác vì người nói yêu cầu "please stop by my office" (vui lòng ghé qua văn phòng của tôi) sau ca làm việc để báo cáo khả năng tham gia.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5497, 242, '2025/test5/audio/test5_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6894, 5497, 94, 'What will happen on Wednesday?', 'A training session will be held.', 'A new policy will be implemented.', 'Some electronic equipment will be purchased.', 'Some promotions will be announced.', 'A', '[Dịch] Câu hỏi: Điều gì sẽ xảy ra vào thứ Tư?
A: Một buổi đào tạo sẽ được tổ chức
B: Một chính sách mới sẽ được thực hiện
C: Một số thiết bị điện tử sẽ được mua
D: Một số thăng chức sẽ được thông báo

Đáp án A là chính xác vì đoạn văn đề cập đến "equipment repair workshop" (hội thảo sửa chữa thiết bị) sẽ diễn ra vào thứ Tư, đây là một buổi đào tạo.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5498, 242, '2025/test5/audio/test5_question_95_97.mp3', '2025/test5/image/test5-p4-image-95.jpg', 'I''d like to start today''s meeting of the event planning team with some happy news. Yesterday I got an e-mail from the company president about what a fun time she had at the picnic-so again, well done, everyone! Now, there''s been an update to our schedule. Mr. Kim has pushed his retirement back, so his party will now be November third. This is a problem, because Gwangju Grill is already booked for that evening. Damien, can you work with Mr. Kim to find another place we could hold the event?', 'Tôi muốn bắt đầu cuộc họp hôm nay của đội lập kế hoạch sự kiện với một số tin vui. Hôm qua tôi nhận được email từ chủ tịch công ty về việc bà ấy đã có thời gian vui vẻ tại buổi dã ngoại - vì vậy, một lần nữa, làm tốt lắm, mọi người! Bây giờ, đã có một cập nhật về lịch trình của chúng ta. Ông Kim đã hoãn việc nghỉ hưu của mình, vì vậy bữa tiệc của ông ấy sẽ là ngày 3 tháng 11. Đây là một vấn đề, bởi vì Nhà hàng Gwangju đã được đặt cho buổi tối hôm đó. Damien, bạn có thể làm việc với ông Kim để tìm một địa điểm khác mà chúng ta có thể tổ chức sự kiện không?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6895, 5498, 95, 'Why does the speaker praise the listeners?', 'Some invitations are attractive.', 'Some tasks were done in a short time.', 'The company saved some money.', 'An executive enjoyed an event.', 'D', '[Dịch] Câu hỏi: Tại sao người nói khen ngợi người nghe?
A: Một số thiệp mời rất đẹp
B: Một số nhiệm vụ được hoàn thành trong thời gian ngắn
C: Công ty đã tiết kiệm được tiền
D: Một giám đốc đã thích một sự kiện

Đáp án D là chính xác vì người nói đề cập đến email từ chủ tịch công ty nói về việc bà ấy đã có "a fun time at the picnic" (thời gian vui vẻ tại buổi dã ngoại).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5499, 242, '2025/test5/audio/test5_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6896, 5499, 96, 'Look at the graphic. Which date is no longer correct?', 'September 9', 'September 27', 'October 6', 'October 19', 'C', '[Dịch] Câu hỏi: Nhìn vào hình. Ngày nào không còn chính xác nữa?
A: Ngày 9 tháng 9
B: Ngày 27 tháng 9
C: Ngày 6 tháng 10
D: Ngày 19 tháng 10

Đáp án C là chính xác vì theo đoạn hội thoại, bữa tiệc nghỉ hưu (retirement party) của ông Kim đã được dời đến ngày 3 tháng 11, không còn diễn ra vào ngày 6 tháng 10 như trong lịch.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5500, 242, '2025/test5/audio/test5_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6897, 5500, 97, 'What does the speaker ask Damien to do with a coworker?', 'Choose a venue', 'Work on a presentation', 'Search for some decorations', 'Draft a guest list', 'A', '[Dịch] Câu hỏi: Người nói yêu cầu Damien làm gì với một đồng nghiệp?
A: Chọn một địa điểm
B: Làm việc trên một bài thuyết trình
C: Tìm kiếm một số đồ trang trí
D: Soạn danh sách khách

Đáp án A là chính xác vì người nói yêu cầu Damien "work with Mr. Kim to find another place" (làm việc với ông Kim để tìm một địa điểm khác) vì nhà hàng Gwangju đã được đặt.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5501, 242, '2025/test5/audio/test5_question_98_100.mp3', '2025/test5/image/test5-p4-image-98.jpg', 'Hello, Mr. Abner. This is Sylvia Clement. I wanted to let you know that I''ve finalized the paperwork for the construction of the extension for your house. I''ll send you a digital as well as a paper copy. Please remember that the thirty-five dollar fee has to be paid directly to the city through their Web site. We accept payment for the remaining fees by credit card over the phone or by bank transfer. Once the city approves your permit, we can begin the work. And don''t forget to try our complimentary consultation service. One of our designers can advise you on paint color options.', 'Xin chào, ông Abner. Tôi là Sylvia Clement. Tôi muốn cho ông biết rằng tôi đã hoàn tất giấy tờ cho việc xây dựng phần mở rộng nhà của ông. Tôi sẽ gửi cho ông bản điện tử cũng như bản giấy. Xin nhớ rằng khoản phí ba mươi lăm đô la phải được thanh toán trực tiếp cho thành phố thông qua trang web của họ. Chúng tôi chấp nhận thanh toán cho các khoản phí còn lại bằng thẻ tín dụng qua điện thoại hoặc chuyển khoản ngân hàng. Khi thành phố phê duyệt giấy phép của ông, chúng tôi có thể bắt đầu công việc. Và đừng quên thử dịch vụ tư vấn miễn phí của chúng tôi. Một trong những nhà thiết kế của chúng tôi có thể tư vấn cho ông về các lựa chọn màu sơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6898, 5501, 98, 'Who most likely is the speaker?', 'A real estate agent', 'A building contractor', 'A vehicle repair person', 'A corporate attorney', 'B', '[Dịch] Câu hỏi: Người nói có khả năng là ai?
A: Một môi giới bất động sản
B: Một nhà thầu xây dựng
C: Một người sửa chữa xe
D: Một luật sư doanh nghiệp

Đáp án B là chính xác vì người nói đang xử lý giấy tờ cho việc xây dựng phần mở rộng nhà ("construction of the extension") và đề cập đến dịch vụ tư vấn màu sơn, cho thấy đây là một nhà thầu xây dựng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5502, 242, '2025/test5/audio/test5_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6899, 5502, 99, 'Look at the graphic. Which fee must be paid online?', 'Deposit', 'Site assessment', 'Filing', 'Phase 1', 'C', '[Dịch] Câu hỏi: Nhìn vào hình. Khoản phí nào phải được thanh toán trực tuyến?
A: Tiền đặt cọc
B: Đánh giá địa điểm
C: Phí nộp hồ sơ
D: Giai đoạn 1

Đáp án C là chính xác vì trong đoạn hội thoại đề cập khoản phí $35 (tương ứng với khoản "Filing" trong bảng) phải được thanh toán trực tiếp cho thành phố qua trang web của họ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5503, 242, '2025/test5/audio/test5_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6900, 5503, 100, 'What service does the speaker tell the listener about?', 'A free color consultation', 'An extended warranty', 'An annual membership', 'An overnight delivery', 'A', '[Dịch] Câu hỏi: Người nói nói với người nghe về dịch vụ gì?
A: Một buổi tư vấn màu sắc miễn phí
B: Một bảo hành mở rộng
C: Một thẻ thành viên hàng năm
D: Một dịch vụ giao hàng qua đêm

Đáp án A là chính xác vì người nói đề cập đến "complimentary consultation service" (dịch vụ tư vấn miễn phí) nơi nhà thiết kế có thể tư vấn về các lựa chọn màu sơn.');;

-- Data for 2025 Test5 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5504, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6901, 5504, 101, 'The lunch special includes one sandwich along with a salad, fries, ----- a bowl of soup.', 'thus', 'or', 'for', 'nor', 'B', 'Đáp án B (or) là đúng vì các lý do sau:
1. Cần một liên từ để liệt kê các lựa chọn trong thực đơn.
2. "Or" là liên từ chỉ sự lựa chọn, thích hợp trong ngữ cảnh này.
3. Cấu trúc liệt kê "along with... and/or" là phổ biến trong tiếng Anh.
4. Các đáp án khác không phù hợp: "thus" (do đó), "for" (cho), "nor" (cũng không - chỉ dùng sau neither).
Dịch câu hỏi: Bữa trưa đặc biệt bao gồm một bánh sandwich cùng với salad, khoai tây chiên, hoặc một tô súp.
Dịch đáp án:
A. thus (phó từ: do đó)
B. or (liên từ: hoặc)
C. for (giới từ: cho)
D. nor (liên từ: cũng không)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5505, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6902, 5505, 102, 'Mr. Fletcher was transferred to another branch after ----- department was eliminated in the corporate restructuring.', 'he', 'him', 'his', 'himself', 'C', 'Đáp án C (his) là đúng vì các lý do sau:
1. Cần một tính từ sở hữu để chỉ phòng ban thuộc về Mr. Fletcher.
2. "His" là tính từ sở hữu đứng trước danh từ "department".
3. Cấu trúc "possessive adjective + noun" là cấu trúc phổ biến trong tiếng Anh.
4. Các đáp án khác không phù hợp: "he" (đại từ chủ ngữ), "him" (đại từ tân ngữ), "himself" (đại từ phản thân).
Dịch câu hỏi: Ông Fletcher được chuyển đến chi nhánh khác sau khi phòng ban của ông ấy bị loại bỏ trong quá trình tái cơ cấu công ty.
Dịch đáp án:
A. he (đại từ nhân xưng: anh ấy)
B. him (đại từ tân ngữ: anh ấy)
C. his (tính từ sở hữu: của anh ấy)
D. himself (đại từ phản thân: bản thân anh ấy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5506, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6903, 5506, 103, 'The tech team''s most ----- solution for the software issue will be used in the updated version of the program.', 'innovatively', 'innovates', 'innovative', 'innovation', 'C', 'Đáp án C (innovative) là đúng vì các lý do sau:
1. Cần một tính từ để bổ nghĩa cho danh từ "solution".
2. "Most + tính từ" tạo thành dạng so sánh nhất.
3. "Innovative" là tính từ chỉ tính sáng tạo, đổi mới.
4. Các đáp án khác không phù hợp: "innovatively" (trạng từ), "innovates" (động từ), "innovation" (danh từ).
Dịch câu hỏi: Giải pháp sáng tạo nhất của nhóm công nghệ cho vấn đề phần mềm sẽ được sử dụng trong phiên bản cập nhật của chương trình.
Dịch đáp án:
A. innovatively (trạng từ: một cách sáng tạo)
B. innovates (động từ: sáng tạo)
C. innovative (tính từ: sáng tạo)
D. innovation (danh từ: sự sáng tạo)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5507, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6904, 5507, 104, 'Attendees of the writing conference can ----- participate in workshops on a number of relevant topics.', 'activate', 'actively', 'activity', 'active', 'B', 'Đáp án B (actively) là đúng vì các lý do sau:
1. Cần một trạng từ để bổ nghĩa cho động từ "participate".
2. "Actively" là trạng từ chỉ cách thức tham gia tích cực.
3. Vị trí giữa can và động từ chính thường là trạng từ.
4. Các đáp án khác không phù hợp: "activate" (động từ), "activity" (danh từ), "active" (tính từ).
Dịch câu hỏi: Những người tham dự hội thảo viết có thể tích cực tham gia vào các workshop về nhiều chủ đề liên quan.
Dịch đáp án:
A. activate (động từ: kích hoạt)
B. actively (trạng từ: tích cực)
C. activity (danh từ: hoạt động)
D. active (tính từ: tích cực)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5508, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6905, 5508, 105, 'If an insured vehicle is involved in an accident, we will assess the ----- quickly, within three business days.', 'signal', 'claim', 'inventory', 'conflict', 'B', 'Đáp án B (claim) là đúng vì các lý do sau:
1. Cần một danh từ chỉ yêu cầu bồi thường bảo hiểm.
2. "Claim" là thuật ngữ phổ biến trong ngữ cảnh bảo hiểm.
3. Cụm từ "assess the claim" là cụm từ thông dụng trong lĩnh vực bảo hiểm.
4. Các đáp án khác không phù hợp về nghĩa: "signal" (tín hiệu), "inventory" (hàng tồn kho), "conflict" (xung đột).
Dịch câu hỏi: Nếu một phương tiện được bảo hiểm gặp tai nạn, chúng tôi sẽ đánh giá yêu cầu bồi thường nhanh chóng, trong vòng ba ngày làm việc.
Dịch đáp án:
A. signal (danh từ: tín hiệu)
B. claim (danh từ: yêu cầu bồi thường)
C. inventory (danh từ: hàng tồn kho)
D. conflict (danh từ: xung đột)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5509, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6906, 5509, 106, 'Problems with the air purifier may ----- either by incorrect storage or the use of the wrong filters.', 'realize', 'select', 'arise', 'indicate', 'C', 'Đáp án C (arise) là đúng vì các lý do sau:
1. Cần một động từ có nghĩa "phát sinh, nảy sinh".
2. "Arise" phù hợp với ngữ cảnh về vấn đề xuất hiện do nguyên nhân nào đó.
3. Cấu trúc "arise from/by" là cấu trúc phổ biến chỉ nguyên nhân.
4. Các đáp án khác không phù hợp về nghĩa: "realize" (nhận ra), "select" (lựa chọn), "indicate" (chỉ ra).
Dịch câu hỏi: Các vấn đề với máy lọc không khí có thể phát sinh do cất giữ không đúng cách hoặc sử dụng sai bộ lọc.
Dịch đáp án:
A. realize (động từ: nhận ra)
B. select (động từ: lựa chọn)
C. arise (động từ: phát sinh)
D. indicate (động từ: chỉ ra)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5510, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6907, 5510, 107, 'The university''s new ----- coordinator has streamlined the steps to reduce processing times.', 'admissions', 'admitted', 'admits', 'to admit', 'A', 'Đáp án A (admissions) là đúng vì các lý do sau:
1. Cần một danh từ để làm tính từ bổ nghĩa cho "coordinator".
2. "Admissions coordinator" là chức danh phổ biến trong trường học.
3. Danh từ có thể làm tính từ trong cụm danh từ ghép.
4. Các đáp án khác không phù hợp: "admitted" (quá khứ phân từ), "admits" (động từ), "to admit" (động từ nguyên mẫu).
Dịch câu hỏi: Điều phối viên tuyển sinh mới của trường đại học đã đơn giản hóa các bước để giảm thời gian xử lý.
Dịch đáp án:
A. admissions (danh từ: tuyển sinh)
B. admitted (quá khứ phân từ: được nhận vào)
C. admits (động từ: nhận vào)
D. to admit (động từ nguyên mẫu: để nhận vào)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5511, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6908, 5511, 108, 'Ms. Burke will encourage the staff to donate canned goods ----- she did during the holidays last year.', 'likewise', 'regarding', 'as', 'so', 'C', 'Đáp án C (as) là đúng vì các lý do sau:
1. Cần một liên từ so sánh cách thức.
2. "As" trong ngữ cảnh này có nghĩa "giống như".
3. Cấu trúc "as + subject + did" là cấu trúc so sánh thông dụng.
4. Các đáp án khác không phù hợp: "likewise" (tương tự), "regarding" (về), "so" (vì vậy).
Dịch câu hỏi: Cô Burke sẽ khuyến khích nhân viên quyên góp thực phẩm đóng hộp như cô ấy đã làm trong kỳ nghỉ năm ngoái.
Dịch đáp án:
A. likewise (phó từ: tương tự)
B. regarding (giới từ: về)
C. as (liên từ: như)
D. so (liên từ: vì vậy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5512, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6909, 5512, 109, 'The pharmacy''s medications and supplements must be ----- labeled.', 'clear', 'clarity', 'clearer', 'clearly', 'D', 'Đáp án D (clearly) là đúng vì các lý do sau:
1. Cần một trạng từ để bổ nghĩa cho động từ "labeled".
2. "Clearly" là trạng từ chỉ cách thức rõ ràng.
3. Cấu trúc "be + trạng từ + past participle" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp: "clear" (tính từ), "clarity" (danh từ), "clearer" (tính từ so sánh hơn).
Dịch câu hỏi: Thuốc và thực phẩm chức năng của hiệu thuốc phải được dán nhãn rõ ràng.
Dịch đáp án:
A. clear (tính từ: rõ ràng)
B. clarity (danh từ: sự rõ ràng)
C. clearer (tính từ so sánh hơn: rõ ràng hơn)
D. clearly (trạng từ: một cách rõ ràng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5513, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6910, 5513, 110, 'Bayside Financial has expanded its customer base by an impressive ninety percent ------ the past five years.', 'by', 'from', 'between', 'over', 'D', 'Đáp án D (over) là đúng vì các lý do sau:
1. Cần một giới từ chỉ khoảng thời gian.
2. "Over" được dùng để chỉ một khoảng thời gian liên tục.
3. Cấu trúc "over + time period" là cách diễn đạt thông dụng.
4. Các đáp án khác không phù hợp: "by" (bởi), "from" (từ), "between" (giữa).
Dịch câu hỏi: Bayside Financial đã mở rộng cơ sở khách hàng của mình một cách ấn tượng lên chín mươi phần trăm trong năm năm qua.
Dịch đáp án:
A. by (giới từ: bởi)
B. from (giới từ: từ)
C. between (giới từ: giữa)
D. over (giới từ: trong suốt)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5514, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6911, 5514, 111, 'You must assess all aspects of the properties before ----- which best suits your personal circumstances.', 'determines', 'to determine', 'determining', 'must determine', 'C', 'Đáp án C (determining) là đúng vì các lý do sau:
1. Cần một động từ dạng V-ing sau giới từ "before".
2. "Before + V-ing" là cấu trúc cố định trong tiếng Anh.
3. "Determining" là gerund (động từ dạng V-ing) phù hợp sau giới từ.
4. Các đáp án khác không phù hợp về cấu trúc: "determines" (động từ số ít), "to determine" (động từ nguyên mẫu), "must determine" (động từ khuyết thiếu).
Dịch câu hỏi: Bạn phải đánh giá tất cả các khía cạnh của các bất động sản trước khi xác định cái nào phù hợp nhất với hoàn cảnh cá nhân của bạn.
Dịch đáp án:
A. determines (động từ: xác định)
B. to determine (động từ nguyên mẫu: để xác định)
C. determining (động từ ing: việc xác định)
D. must determine (động từ khuyết thiếu: phải xác định)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5515, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6912, 5515, 112, 'FT Supplies'' headquarters building was ----- used as a ceramics factory because the surrounding area is rich in clay deposits.', 'to originate', 'originally', 'original', 'origins', 'B', 'Đáp án B (originally) là đúng vì các lý do sau:
1. Cần một trạng từ để chỉ tình trạng ban đầu của tòa nhà.
2. "Originally" là trạng từ có nghĩa "ban đầu, nguyên thủy".
3. Cấu trúc "was + trạng từ + past participle" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp: "to originate" (động từ nguyên mẫu), "original" (tính từ), "origins" (danh từ).
Dịch câu hỏi: Tòa nhà trụ sở chính của FT Supplies ban đầu được sử dụng làm nhà máy gốm sứ vì khu vực xung quanh giàu mỏ đất sét.
Dịch đáp án:
A. to originate (động từ nguyên mẫu: để bắt nguồn)
B. originally (trạng từ: ban đầu)
C. original (tính từ: nguyên bản)
D. origins (danh từ: nguồn gốc)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5516, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6913, 5516, 113, 'Every semester, Laurel Technical Institute offers online and in-person courses in an impressive ----- of fields.', 'effort', 'version', 'array', 'degree', 'C', 'Đáp án C (array) là đúng vì các lý do sau:
1. Cần một danh từ chỉ sự đa dạng, phong phú.
2. "Array" có nghĩa là "loạt, dãy, sự đa dạng".
3. Cụm từ "array of fields" là cách diễn đạt thông dụng chỉ nhiều lĩnh vực khác nhau.
4. Các đáp án khác không phù hợp về nghĩa: "effort" (nỗ lực), "version" (phiên bản), "degree" (bằng cấp).
Dịch câu hỏi: Mỗi học kỳ, Học viện Kỹ thuật Laurel cung cấp các khóa học trực tuyến và trực tiếp trong một loạt các lĩnh vực ấn tượng.
Dịch đáp án:
A. effort (danh từ: nỗ lực)
B. version (danh từ: phiên bản)
C. array (danh từ: loạt, dãy)
D. degree (danh từ: bằng cấp)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5517, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6914, 5517, 114, 'Many airline employees found learning the luggage tracking system difficult, but explaining it to passengers was an even ----- challenge.', 'hard', 'hardly', 'harder', 'hardest', 'C', 'Đáp án C (harder) là đúng vì các lý do sau:
1. Cần một tính từ so sánh hơn để so sánh hai thử thách.
2. "Even + tính từ so sánh hơn" diễn tả mức độ cao hơn.
3. "Harder" là dạng so sánh hơn của tính từ "hard".
4. Các đáp án khác không phù hợp: "hard" (tính từ nguyên thể), "hardly" (trạng từ), "hardest" (tính từ so sánh nhất).
Dịch câu hỏi: Nhiều nhân viên hàng không thấy việc học hệ thống theo dõi hành lý khó khăn, nhưng việc giải thích nó cho hành khách còn là một thử thách khó khăn hơn nữa.
Dịch đáp án:
A. hard (tính từ: khó)
B. hardly (trạng từ: hầu như không)
C. harder (tính từ so sánh hơn: khó hơn)
D. hardest (tính từ so sánh nhất: khó nhất)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5518, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6915, 5518, 115, 'Once the interns have completed their probation period, a manager at Camco will evaluate ----- one of them.', 'whole', 'each', 'full', 'total', 'B', 'Đáp án B (each) là đúng vì các lý do sau:
1. Cần một từ xác định để chỉ từng người một.
2. "Each" được dùng để chỉ từng cá nhân trong một nhóm.
3. "Each one" là cách diễn đạt phổ biến chỉ từng người/vật.
4. Các đáp án khác không phù hợp về nghĩa: "whole" (toàn bộ), "full" (đầy đủ), "total" (tổng).
Dịch câu hỏi: Một khi các thực tập sinh đã hoàn thành thời gian thử việc, một quản lý tại Camco sẽ đánh giá từng người một trong số họ.
Dịch đáp án:
A. whole (tính từ: toàn bộ)
B. each (từ xác định: mỗi)
C. full (tính từ: đầy đủ)
D. total (tính từ: tổng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5519, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6916, 5519, 116, 'The automated system allows us to respond ----- to basic customer inquiries and requests.', 'instantly', 'fondly', 'abundantly', 'curiously', 'A', 'Đáp án A (instantly) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ tốc độ phản hồi nhanh chóng.
2. "Instantly" có nghĩa là "ngay lập tức, tức thì".
3. Phù hợp với ngữ cảnh về hệ thống tự động phản hồi khách hàng.
4. Các đáp án khác không phù hợp về nghĩa: "fondly" (trìu mến), "abundantly" (dồi dào), "curiously" (tò mò).
Dịch câu hỏi: Hệ thống tự động cho phép chúng tôi phản hồi ngay lập tức các câu hỏi và yêu cầu cơ bản của khách hàng.
Dịch đáp án:
A. instantly (trạng từ: ngay lập tức)
B. fondly (trạng từ: trìu mến)
C. abundantly (trạng từ: dồi dào)
D. curiously (trạng từ: tò mò)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5520, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6917, 5520, 117, 'Morrison Automotive has confirmed the ----- of its accounting and finance departments due to extensive corporate growth.', 'separated', 'separate', 'separates', 'separation', 'D', 'Đáp án D (separation) là đúng vì các lý do sau:
1. Cần một danh từ sau mạo từ xác định "the".
2. "Separation" là danh từ chỉ sự tách biệt, phân chia.
3. Ngữ cảnh nói về việc tách các phòng ban trong công ty.
4. Các đáp án khác không phù hợp về từ loại: "separated" (quá khứ phân từ), "separate" (tính từ/động từ), "separates" (động từ số ít).
Dịch câu hỏi: Morrison Automotive đã xác nhận việc tách biệt các phòng kế toán và tài chính của mình do sự phát triển rộng rãi của công ty.
Dịch đáp án:
A. separated (quá khứ phân từ: đã tách biệt)
B. separate (tính từ: riêng biệt)
C. separates (động từ: tách biệt)
D. separation (danh từ: sự tách biệt)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5521, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6918, 5521, 118, 'The shopping mall kept the majority of its shops open ----- the renovation process because of working in phases.', 'while', 'prior to', 'throughout', 'along', 'C', 'Đáp án C (throughout) là đúng vì các lý do sau:
1. Cần một giới từ chỉ suốt quá trình diễn ra.
2. "Throughout" có nghĩa là "suốt, trong suốt".
3. Phù hợp với ngữ cảnh về việc duy trì hoạt động trong suốt quá trình cải tạo.
4. Các đáp án khác không phù hợp về nghĩa: "while" (trong khi), "prior to" (trước khi), "along" (dọc theo).
Dịch câu hỏi: Trung tâm mua sắm giữ phần lớn các cửa hàng mở cửa trong suốt quá trình cải tạo vì làm việc theo từng giai đoạn.
Dịch đáp án:
A. while (liên từ: trong khi)
B. prior to (cụm giới từ: trước khi)
C. throughout (giới từ: suốt, trong suốt)
D. along (giới từ: dọc theo)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5522, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6919, 5522, 119, 'The café, ----- caters to vegan and vegetarian diners, has received positive reviews so far.', 'whether', 'which', 'neither', 'it', 'B', 'Đáp án B (which) là đúng vì các lý do sau:
1. Cần một đại từ quan hệ để giới thiệu mệnh đề quan hệ không xác định.
2. "Which" dùng để thay thế cho danh từ chỉ vật (café).
3. Mệnh đề sau dấu phẩy là mệnh đề quan hệ không xác định, bổ sung thông tin.
4. Các đáp án khác không phù hợp: "whether" (liệu có), "neither" (không cái nào), "it" (nó).
Dịch câu hỏi: Quán café, nơi phục vụ thực khách ăn chay và thuần chay, đã nhận được những đánh giá tích cực cho đến nay.
Dịch đáp án:
A. whether (liên từ: liệu có)
B. which (đại từ quan hệ: cái mà)
C. neither (từ xác định: không cái nào)
D. it (đại từ: nó)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5523, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6920, 5523, 120, 'Angela Cruz, editor of the Newport Daily Herald, includes nothing but ----- facts in the newspaper''s articles.', 'intensive', 'competent', 'verifiable', 'economical', 'C', 'Đáp án C (verifiable) là đúng vì các lý do sau:
1. Cần một tính từ chỉ tính chất của sự kiện trong báo chí.
2. "Verifiable" có nghĩa là "có thể kiểm chứng được".
3. Phù hợp với ngữ cảnh về tính chuyên nghiệp trong báo chí.
4. Các đáp án khác không phù hợp về nghĩa: "intensive" (chuyên sâu), "competent" (có năng lực), "economical" (tiết kiệm).
Dịch câu hỏi: Angela Cruz, biên tập viên của Newport Daily Herald, chỉ đưa những sự kiện có thể kiểm chứng vào các bài báo của tờ báo.
Dịch đáp án:
A. intensive (tính từ: chuyên sâu)
B. competent (tính từ: có năng lực)
C. verifiable (tính từ: có thể kiểm chứng)
D. economical (tính từ: tiết kiệm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5524, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6921, 5524, 121, 'The judging panel can only consider art entries received ----- the designated period of June 28 to July 5.', 'above', 'except', 'among', 'within', 'D', 'Đáp án D (within) là đúng vì các lý do sau:
1. Cần một giới từ chỉ thời gian trong một khoảng thời gian xác định.
2. "Within" là giới từ có nghĩa "trong khoảng" phù hợp với thời gian cụ thể.
3. Cấu trúc "within + time period" là cách diễn đạt phổ biến chỉ khoảng thời gian.
4. Các đáp án khác không phù hợp: "above" (trên), "except" (ngoại trừ), "among" (giữa).
Dịch câu hỏi: Ban giám khảo chỉ có thể xem xét các tác phẩm nghệ thuật được nhận trong khoảng thời gian quy định từ 28 tháng 6 đến 5 tháng 7.
Dịch đáp án:
A. above (giới từ: trên)
B. except (giới từ: ngoại trừ)
C. among (giới từ: giữa)
D. within (giới từ: trong khoảng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5525, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6922, 5525, 122, 'Ms. Kirby is ----- filling out paperwork for a small business loan for her bakery.', 'how', 'lately', 'anywhere', 'currently', 'D', 'Đáp án D (currently) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ thời gian hiện tại.
2. "Currently" là trạng từ có nghĩa "hiện tại, đang".
3. Vị trí này cần một trạng từ để bổ sung thông tin về thời gian của hành động.
4. Các đáp án khác không phù hợp về nghĩa và ngữ cảnh: "how" (thế nào), "lately" (gần đây), "anywhere" (bất cứ đâu).
Dịch câu hỏi: Bà Kirby hiện đang điền đơn xin vay vốn kinh doanh nhỏ cho tiệm bánh của mình.
Dịch đáp án:
A. how (trạng từ: thế nào)
B. lately (trạng từ: gần đây)
C. anywhere (trạng từ: bất cứ đâu)
D. currently (trạng từ: hiện tại)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5526, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6923, 5526, 123, 'Dr. Charlotte Collins requires further funding to remain at the forefront of medical ----- in the field.', 'advanced', 'is advancing', 'advances', 'advancing', 'C', 'Đáp án C (advances) là đúng vì các lý do sau:
1. Cần một danh từ để hoàn thành cụm từ "medical ___".
2. "Advances" là danh từ số nhiều chỉ "những tiến bộ, phát triển".
3. Cụm từ "medical advances" là thuật ngữ phổ biến trong y học.
4. Các đáp án khác không phù hợp về từ loại: "advanced" (tính từ), "is advancing" (đang tiến bộ), "advancing" (đang tiến bộ).
Dịch câu hỏi: Tiến sĩ Charlotte Collins cần thêm tài trợ để duy trì vị trí hàng đầu về các tiến bộ y học trong lĩnh vực này.
Dịch đáp án:
A. advanced (tính từ: tiên tiến)
B. is advancing (động từ: đang tiến bộ)
C. advances (danh từ: những tiến bộ)
D. advancing (động từ: đang tiến bộ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5527, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6924, 5527, 124, 'Please take down the patio umbrellas today, as they are designed to ----- winds of up to twenty-five miles per hour only.', 'forbid', 'expose', 'occur', 'withstand', 'D', 'Đáp án D (withstand) là đúng vì các lý do sau:
1. Cần một động từ chỉ khả năng chống chịu.
2. "Withstand" có nghĩa là "chịu đựng được, chống chịu được".
3. Cấu trúc "withstand + something" diễn tả khả năng chống chịu một lực tác động.
4. Các đáp án khác không phù hợp về nghĩa: "forbid" (cấm), "expose" (phơi bày), "occur" (xảy ra).
Dịch câu hỏi: Hãy hạ những chiếc ô ở sân trong xuống hôm nay, vì chúng chỉ được thiết kế để chịu được gió có tốc độ lên đến 25 dặm một giờ.
Dịch đáp án:
A. forbid (động từ: cấm)
B. expose (động từ: phơi bày)
C. occur (động từ: xảy ra)
D. withstand (động từ: chống chịu)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5528, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6925, 5528, 125, 'The temporary workers that have been hired to assemble the trade fair booth will be ----- helpful to us.', 'enough', 'shortly', 'quite', 'than', 'C', 'Đáp án C (quite) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ mức độ để bổ nghĩa cho tính từ "helpful".
2. "Quite" là trạng từ chỉ mức độ "khá, rất".
3. Cấu trúc "quite + adjective" là cách diễn đạt phổ biến.
4. Các đáp án khác không phù hợp về ngữ pháp: "enough" (đủ - đứng sau tính từ), "shortly" (sắp), "than" (hơn).
Dịch câu hỏi: Những công nhân tạm thời được thuê để lắp ráp gian hàng hội chợ sẽ rất hữu ích cho chúng tôi.
Dịch đáp án:
A. enough (trạng từ: đủ)
B. shortly (trạng từ: sắp)
C. quite (trạng từ: rất)
D. than (liên từ: hơn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5529, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6926, 5529, 126, 'Book a room at Parkview Hotel to be looked after by our ----- staff during your stay.', 'optimal', 'former', 'attentive', 'potential', 'C', 'Đáp án C (attentive) là đúng vì các lý do sau:
1. Cần một tính từ mô tả tính chất tích cực của nhân viên.
2. "Attentive" có nghĩa là "chu đáo, tận tình".
3. Phù hợp với ngữ cảnh về dịch vụ khách sạn chất lượng.
4. Các đáp án khác không phù hợp về nghĩa: "optimal" (tối ưu), "former" (trước đây), "potential" (tiềm năng).
Dịch câu hỏi: Hãy đặt phòng tại Khách sạn Parkview để được đội ngũ nhân viên chu đáo của chúng tôi phục vụ trong thời gian lưu trú.
Dịch đáp án:
A. optimal (tính từ: tối ưu)
B. former (tính từ: trước đây)
C. attentive (tính từ: chu đáo)
D. potential (tính từ: tiềm năng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5530, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6927, 5530, 127, 'Hospital Director Owen Abbott expressed a desire to move ----- a more patient-centered approach to care.', 'toward', 'since', 'alongside', 'through', 'A', 'Đáp án A (toward) là đúng vì các lý do sau:
1. Cần một giới từ chỉ hướng di chuyển về một mục tiêu.
2. "Move toward" là cụm động từ chỉ sự chuyển động về một hướng hay mục tiêu.
3. Phù hợp với ngữ cảnh về việc thay đổi phương pháp chăm sóc.
4. Các đáp án khác không phù hợp: "since" (kể từ), "alongside" (bên cạnh), "through" (xuyên qua).
Dịch câu hỏi: Giám đốc Bệnh viện Owen Abbott bày tỏ mong muốn chuyển hướng sang phương pháp chăm sóc lấy bệnh nhân làm trung tâm.
Dịch đáp án:
A. toward (giới từ: hướng tới)
B. since (giới từ: kể từ)
C. alongside (giới từ: bên cạnh)
D. through (giới từ: xuyên qua)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5531, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6928, 5531, 128, 'Pinewell Supermarket''s customer loyalty program will continue ----- the target demographic is still participating in it.', 'as long as', 'in spite of', 'rather than', 'in order to', 'A', 'Đáp án A (as long as) là đúng vì các lý do sau:
1. Cần một cụm liên từ chỉ điều kiện thời gian.
2. "As long as" có nghĩa là "chừng nào còn, miễn là".
3. Cấu trúc này diễn tả mối quan hệ điều kiện giữa hai sự việc.
4. Các đáp án khác không phù hợp về nghĩa: "in spite of" (mặc dù), "rather than" (thay vì), "in order to" (để).
Dịch câu hỏi: Chương trình khách hàng thân thiết của Siêu thị Pinewell sẽ tiếp tục chừng nào nhóm khách hàng mục tiêu vẫn còn tham gia vào nó.
Dịch đáp án:
A. as long as (cụm liên từ: chừng nào còn)
B. in spite of (cụm giới từ: mặc dù)
C. rather than (cụm liên từ: thay vì)
D. in order to (cụm giới từ: để)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5532, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6929, 5532, 129, '----- of prevention methods over cutting-edge treatments may lead to better health outcomes.', 'Consumption', 'Prioritization', 'Destination', 'Intention', 'B', 'Đáp án B (Prioritization) là đúng vì các lý do sau:
1. Cần một danh từ chỉ sự ưu tiên hoặc xếp hạng.
2. "Prioritization" có nghĩa là "sự ưu tiên".
3. Ngữ cảnh nói về việc đặt phương pháp phòng ngừa lên trước phương pháp điều trị.
4. Các đáp án khác không phù hợp về nghĩa: "Consumption" (tiêu thụ), "Destination" (điểm đến), "Intention" (ý định).
Dịch câu hỏi: Việc ưu tiên các phương pháp phòng ngừa hơn các phương pháp điều trị tiên tiến có thể dẫn đến kết quả sức khỏe tốt hơn.
Dịch đáp án:
A. Consumption (danh từ: sự tiêu thụ)
B. Prioritization (danh từ: sự ưu tiên)
C. Destination (danh từ: điểm đến)
D. Intention (danh từ: ý định)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5533, 243, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6930, 5533, 130, 'All standard orders for banner printing will ----- until the express requests have been completed and shipped.', 'suspend', 'be suspended', 'have suspended', 'be suspending', 'B', 'Đáp án B (be suspended) là đúng vì các lý do sau:
1. Cần một động từ ở thể bị động tương lai.
2. "Will be suspended" là cấu trúc bị động tương lai chỉ việc sẽ bị hoãn lại.
3. Chủ ngữ "orders" là người/vật bị tác động nên cần dùng bị động.
4. Các đáp án khác không phù hợp: "suspend" (chủ động), "have suspended" (hoàn thành), "be suspending" (tiếp diễn).
Dịch câu hỏi: Tất cả các đơn đặt hàng in banner tiêu chuẩn sẽ bị hoãn lại cho đến khi các yêu cầu khẩn cấp được hoàn thành và vận chuyển.
Dịch đáp án:
A. suspend (động từ: hoãn lại)
B. be suspended (bị động: bị hoãn lại)
C. have suspended (hoàn thành: đã hoãn lại)
D. be suspending (tiếp diễn: đang hoãn lại)');;

-- Data for 2025 Test5 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5534, 244, NULL, NULL, 'From: hemrich@midlandmail.com
To: Itoscani@napoliballetschool.com
Date: September 26
Subject: Job opening
Attachment: Résumé_emrich
Dear Ms. Toscani,
I am contacting you with regard to the job advertisement you posted in the most recent issue of the Napoli Ballet School newsletter. I have a great deal of respect for your 131...... and many of my friends and acquaintances have taken lessons there. I would be 132..... to contribute to the site as a dance instructor.
I have worked with dancers of a wide range of ages and ability levels. 133......, I would be able to adjust my teaching style to perfectly suit students'' individual needs. Please find attached a copy of my résumé, which outlines my training and work history. 134........ . Should you have any questions, you can reach me at this address or at 555-3966. I hope to hear from you soon.
All the best,
Heather Emrich', 'Từ: hemrich@midlandmail.com
Đến: Itoscani@napoliballetschool.com
Ngày: 26 tháng 9
Chủ đề: Vị trí tuyển dụng
Đính kèm: Sơ yếu lý lịch_emrich
Kính gửi cô Toscani,
Tôi liên hệ với cô về thông báo tuyển dụng mà cô đã đăng trong số gần đây nhất của bản tin Trường Ballet Napoli. Tôi rất kính trọng 131...... của cô và nhiều bạn bè, người quen của tôi đã từng học ở đó. Tôi sẽ 132..... được đóng góp cho địa điểm này với tư cách là giảng viên dạy múa.
Tôi đã làm việc với các vũ công ở nhiều độ tuổi và trình độ khác nhau. 133......, tôi có thể điều chỉnh phong cách giảng dạy của mình để phù hợp hoàn hảo với nhu cầu cá nhân của học viên. Vui lòng xem bản sơ yếu lý lịch đính kèm, trong đó nêu rõ quá trình đào tạo và lịch sử công việc của tôi. 134........ . Nếu cô có bất kỳ câu hỏi nào, cô có thể liên hệ với tôi qua địa chỉ này hoặc số 555-3966. Tôi hy vọng sớm nhận được hồi âm từ cô.
Trân trọng,
Heather Emrich');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6931, 5534, 131, NULL, 'exhibition', 'institute', 'theater', 'store', 'B', 'A. exhibition (cuộc triển lãm - danh từ)
B. institute (học viện - danh từ)
C. theater (nhà hát - danh từ)
D. store (cửa hàng - danh từ)
Đáp án đúng là B (institute).
Giải thích:
1. Ngữ cảnh: Đây là email xin việc gửi đến "Napoli Ballet School" - một trường dạy múa ballet chuyên nghiệp
2. Cấu trúc ngữ pháp: "your + [danh từ]" chỉ sự sở hữu, cần điền một danh từ
3. Từ vựng: "Institute" phù hợp nhất vì:
- Là cơ sở giáo dục chuyên nghiệp
- Phù hợp với việc "nhiều bạn bè đã học tại đây"
- Thể hiện tính chất chuyên môn của trường dạy múa
4. Các phương án khác không phù hợp:
- "Exhibition" chỉ là nơi trưng bày tạm thời
- "Theater" là nơi biểu diễn, không phải nơi giảng dạy
- "Store" là cửa hàng, không liên quan đến giáo dục
5. Bằng chứng trong văn cảnh: "taken lessons there" (đã học ở đó) chỉ rõ đây là nơi giảng dạy');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6932, 5534, 132, NULL, 'delighting', 'delight', 'delights', 'delighted', 'D', 'A. delighting (đang vui mừng - hiện tại phân từ, V-ing)
B. delight (vui mừng - động từ nguyên mẫu)
C. delights (vui mừng - động từ ngôi thứ 3 số ít)
D. delighted (vui mừng - quá khứ phân từ, V3)
Đáp án đúng là D (delighted).
Giải thích:
1. Cấu trúc ngữ pháp: "would be + [tính từ/quá khứ phân từ]"
- Là cấu trúc diễn tả trạng thái giả định, cảm xúc
- Sau "be" cần một tính từ hoặc quá khứ phân từ làm tính từ
2. "Delighted" phù hợp nhất vì:
- Là quá khứ phân từ có thể dùng như tính từ
- Diễn tả cảm xúc "vui mừng" của người viết
- Thường dùng trong cấu trúc "be delighted to do something"
3. Các phương án khác không phù hợp vì:
- "Delighting" (V-ing) không thể theo sau "would be"
- "Delight" (V1) là động từ nguyên mẫu, không thể làm tính từ
- "Delights" (V-s) là động từ chia, không phù hợp sau "would be"
4. Ngữ cảnh: Người viết muốn thể hiện sự nhiệt tình với vị trí công việc');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6933, 5534, 133, NULL, 'Otherwise', 'In addition', 'Consequently', 'However', 'C', 'A. Otherwise (mặt khác - liên từ chỉ sự đối lập)
B. In addition (thêm vào đó - liên từ bổ sung)
C. Consequently (do đó - liên từ chỉ kết quả)
D. However (tuy nhiên - liên từ chỉ tương phản)
Đáp án đúng là C (Consequently).
Giải thích:
1. Ngữ cảnh: Có kinh nghiệm làm việc với nhiều vũ công ở các độ tuổi và trình độ khác nhau → có khả năng điều chỉnh phương pháp giảng dạy
2. "Consequently" phù hợp nhất vì:
- Diễn tả mối quan hệ nhân-quả trực tiếp
- Tăng tính thuyết phục của ứng viên
3. Các phương án khác không phù hợp vì:
- "Otherwise" chỉ sự đối lập không có ở đây
- "In addition" chỉ thông tin bổ sung, không phải kết quả
- "However" chỉ sự tương phản không tồn tại
4. Quy tắc ngữ pháp:
- Câu trước là nguyên nhân (kinh nghiệm làm việc)
- Câu sau là kết quả (khả năng điều chỉnh phương pháp)
- "Consequently" dùng để nối 2 ý có quan hệ nhân quả;');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6934, 5534, 134, NULL, 'I am happy to teach you how to prevent injuries when dancing.', 'To sign up for one of my classes, please download the app.', 'I learned a great deal from your dance class last month.', 'You can also view videos of my dancing at www.danceshowcase.com/emrich1.', 'D', 'A. Tôi rất vui được dạy bạn cách phòng tránh chấn thương khi nhảy múa (câu chưa đúng ngữ cảnh)
B. Để đăng ký một trong các lớp học của tôi, vui lòng tải ứng dụng (câu không phù hợp với tình huống xin việc)
C. Tôi đã học được rất nhiều từ lớp múa của bạn tháng trước (câu mâu thuẫn với ngữ cảnh)
D. Bạn cũng có thể xem các video múa của tôi tại www.danceshowcase.com/emrich1 (câu bổ sung thông tin về năng lực)
Đáp án đúng là D vì:
1. Ngữ cảnh:
- Đây là email xin việc
- Người viết đang cung cấp thông tin về năng lực bản thân
- Câu này nối tiếp việc đính kèm sơ yếu lý lịch
2. Cấu trúc câu:
- "You can also" thể hiện thông tin bổ sung
- Cung cấp link cụ thể để người tuyển dụng tham khảo
3. Mục đích:
- Tăng cường hồ sơ xin việc bằng bằng chứng thực tế
- Cho phép người tuyển dụng đánh giá kỹ năng thực tế
4. Các phương án khác không phù hợp vì:
- A: Chưa được nhận việc nên không thể dạy
- B: Chưa có lớp học nên không thể yêu cầu đăng ký
- C: Mâu thuẫn với việc mới xin việc lần đầu');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5535, 244, NULL, NULL, 'Rosen Hotel is offering a 30% discount on all deluxe rooms throughout March. This special 135..... is available to all guests who want to experience the luxury of our new rooms. 136...... with calming colors, our deluxe rooms are the perfect place to relax after a long day. 137....... come with a king-sized bed, kitchenette, spacious bathroom, and more. To make a reservation, visit www. rosen-hotel.com. Please note that a credit card is required for all bookings. 138........ . We look forward to welcoming you!', 'Khách sạn Rosen đang giảm giá 30% cho tất cả các phòng hạng sang trong suốt tháng Ba. 135..... đặc biệt này có sẵn cho tất cả khách muốn trải nghiệm sự sang trọng của các phòng mới của chúng tôi. 136...... với màu sắc nhẹ nhàng, các phòng hạng sang của chúng tôi là nơi hoàn hảo để thư giãn sau một ngày dài. 137....... đi kèm với giường cỡ king, bếp nhỏ, phòng tắm rộng rãi và nhiều tiện nghi khác. Để đặt phòng, hãy truy cập www.rosen-hotel.com. Xin lưu ý rằng thẻ tín dụng là bắt buộc cho tất cả các đặt phòng. 138........ . Chúng tôi mong được đón tiếp quý khách!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6935, 5535, 135, NULL, 'tour', 'performance', 'edition', 'rate', 'D', 'A. tour (chuyến tham quan - danh từ)
B. performance (buổi biểu diễn - danh từ)
C. edition (phiên bản - danh từ)
D. rate (giá - danh từ)
Đáp án đúng là D (rate).
Giải thích:
1. Ngữ cảnh:
- Đang nói về giảm giá phòng khách sạn (30% discount)
- "Special" + [danh từ] cần một từ liên quan đến giá cả
2. Cụm từ chuyên ngành:
- "Special rate" là thuật ngữ phổ biến trong ngành khách sạn
- Chỉ mức giá ưu đãi, khuyến mãi đặc biệt
3. Sự liên kết:
- Liên kết với "30% discount" ở câu trước
- Liên kết với nội dung về đặt phòng khách sạn
4. Các phương án khác không phù hợp vì:
- "Tour" chỉ chuyến tham quan, không liên quan đến giá cả
- "Performance" là buổi biểu diễn, không phù hợp ngữ cảnh
- "Edition" chỉ phiên bản, không dùng cho giá cả
5. Cấu trúc ngữ pháp:
- Cần một danh từ sau tính từ "special"
- "Rate" có thể kết hợp với "special" tạo cụm từ có nghĩa');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6936, 5535, 136, NULL, 'Decorating', 'To decorate', 'They decorated', 'Decorated', 'D', 'A. decorating (đang trang trí - hiện tại phân từ, V-ing)
B. to decorate (để trang trí - động từ nguyên mẫu, to V)
C. they decorated (họ đã trang trí - chủ ngữ + động từ quá khứ)
D. decorated (được trang trí - quá khứ phân từ, V3)
Đáp án đúng là D (Decorated).
Giải thích:
1. Cấu trúc ngữ pháp cần:
- Một phân từ mở đầu cho mệnh đề rút gọn
- Diễn tả trạng thái bị động của phòng
2. "Decorated" phù hợp nhất vì:
- Là quá khứ phân từ, có thể dùng làm tính từ
- Cấu trúc "decorated with" chỉ cách trang trí
- Diễn tả trạng thái hoàn thành của việc trang trí
3. Ngữ cảnh:
- Mô tả tính năng của phòng khách sạn
- "With calming colors" bổ nghĩa cho "decorated"
4. Các phương án khác không phù hợp vì:
- "Decorating" (V-ing) không thể bắt đầu mệnh đề rút gọn bị động
- "To decorate" không phù hợp vì không diễn tả trạng thái
- "They decorated" tạo thành một câu hoàn chỉnh, phá vỡ cấu trúc câu
5. Sự kết hợp từ vựng:
- "Decorated with" là cụm từ phổ biến trong mô tả nội thất
- Thể hiện sự hoàn thiện trong thiết kế');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6937, 5535, 137, NULL, 'They', 'Either', 'Whichever', 'Fewer', 'A', 'A. they (chúng - đại từ nhân xưng số nhiều)
B. either (một trong hai - đại từ chỉ định)
C. whichever (bất kỳ cái nào - đại từ quan hệ)
D. fewer (ít hơn - tính từ so sánh)
Đáp án đúng là A (They).
Giải thích:
1. Ngữ cảnh:
- Đang mô tả các phòng hạng sang (deluxe rooms)
- Cần một đại từ thay thế để tránh lặp lại "deluxe rooms"
2. Cấu trúc ngữ pháp:
- "They" là chủ ngữ của động từ "come with"
- Thay thế cho danh từ số nhiều "deluxe rooms"
3. Tính liên kết văn bản:
- Tham chiếu trở lại "deluxe rooms" ở câu trước
- Duy trì sự mạch lạc của đoạn văn
4. Các phương án khác không phù hợp vì:
- "Either" chỉ dùng cho hai lựa chọn, không phù hợp ngữ cảnh
- "Whichever" là đại từ quan hệ, không thể làm chủ ngữ ở đây
- "Fewer" là tính từ so sánh, không thể làm chủ ngữ
5. Quy tắc ngữ pháp:
- Danh từ số nhiều (rooms) cần đại từ số nhiều (they)
- Chủ ngữ phải là đại từ nhân xưng khi thay thế danh từ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6938, 5535, 138, NULL, 'Otherwise, a breakfast buffet is served daily from 6 A.M.', 'The charge will not be made until twenty-four hours before check-in.', 'Our staff aims to accommodate this request, if possible.', 'Many hotels in the city center have vacant rooms.', 'B', 'A. Otherwise, a breakfast buffet is served daily from 6 A.M. (câu thông báo về bữa sáng)
B. The charge will not be made until twenty-four hours before check-in. (câu về thời điểm thanh toán)
C. Our staff aims to accommodate this request, if possible. (câu về nỗ lực đáp ứng yêu cầu)
D. Many hotels in the city center have vacant rooms. (câu về tình trạng phòng trống)
Đáp án đúng là B.
Giải thích:
1. Ngữ cảnh:
- Đoạn văn đang đề cập đến việc đặt phòng và yêu cầu thẻ tín dụng
- Cần thông tin về quy trình thanh toán
2. Tính liên kết:
- Liên quan trực tiếp đến câu trước về yêu cầu thẻ tín dụng
- Giải thích thêm về cách xử lý thanh toán
3. Cấu trúc thông tin:
- "The charge" liên kết với việc sử dụng thẻ tín dụng
- "Until twenty-four hours before check-in" cung cấp thông tin thời gian cụ thể
4. Các phương án khác không phù hợp vì:
- A: Thông tin về bữa sáng không liên quan đến thanh toán
- C: Không rõ "this request" đề cập đến yêu cầu nào
- D: Thông tin về khách sạn khác không liên quan
5. Quy tắc viết quảng cáo:
- Cung cấp thông tin chi tiết về chính sách thanh toán
- Đảm bảo tính minh bạch cho khách hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5536, 244, NULL, NULL, 'To: Chloe Boyce <cboyce@merigoldcomm.com>
From: Arlington Sanitation Services <sanitation@arlington.gov>
Date: January 2
Subject: Missed collection
Dear Ms. Boyce,
Thank you for informing us 139...... the missed recycling collection at your property. We have a special team for short-notice pickups, which i have dispatched. 140......, you can rest assured that your recycling will be collected by 4 P.M. 141........ . Therefore, some crew members are not familiar with the routes. We are dedicated to providing efficient collection services of household waste and recyclables in Arlington, and your feedback helps us to 142....... this responsibility.
Sincerely,
Devin Sinha
Arlington Sanitation Services', '
Kính gửi cô Boyce,
Cảm ơn cô đã thông báo cho chúng tôi ....... về việc bỏ sót thu gom rác tái chế tại nhà cô. Chúng tôi có một đội đặc biệt cho các trường hợp cần thu gom gấp, mà tôi đã điều động. ......., cô có thể yên tâm rằng rác tái chế của cô sẽ được thu gom trước 4 giờ chiều. ....... Do đó, một số nhân viên không quen thuộc với các tuyến đường. Chúng tôi cam kết cung cấp dịch vụ thu gom rác thải sinh hoạt và rác tái chế hiệu quả ở Arlington, và phản hồi của cô giúp chúng tôi ....... trách nhiệm này.
Trân trọng,
Devin Sinha
Dịch vụ Vệ sinh Arlington');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6939, 5536, 139, NULL, 'with', 'until', 'about', 'into', 'C', 'A. with (với - giới từ)
B. until (cho đến - giới từ)
C. about (về - giới từ)
D. into (vào - giới từ)
Đáp án đúng là C (about).
Giải thích:
1. Cấu trúc ngữ pháp: "inform somebody about something"
2. "About" phù hợp vì:
- Dùng để giới thiệu chủ đề thông tin
- Thường đi với động từ "inform"
3. Các đáp án khác sai vì:
- "With" không dùng với "inform"
- "Until" chỉ thời gian, không phù hợp
- "Into" không đi với "inform"');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6940, 5536, 140, NULL, 'For instance', 'On the other hand', 'Apart from that', 'For this reason', 'D', 'A. For instance (ví dụ - cụm liên từ)
B. On the other hand (mặt khác - cụm liên từ)
C. Apart from that (ngoài ra - cụm liên từ)
D. For this reason (vì lý do này - cụm liên từ)
Đáp án đúng là D (For this reason).
Giải thích:
1. Ngữ cảnh:
- Câu trước nói về việc đã điều động đội thu gom đặc biệt
- Câu sau là kết quả trực tiếp của hành động này
2. "For this reason" phù hợp vì:
- Nối kết quả với nguyên nhân trước đó
- Thể hiện logic của việc đảm bảo thu gom
3. Các đáp án khác không phù hợp vì:
- "For instance" dùng để đưa ví dụ
- "On the other hand" chỉ sự tương phản
- "Apart from that" thêm thông tin độc lập');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6941, 5536, 141, NULL, 'Unfortunately, we cannot take items that have not been thoroughly cleaned.', 'You can also leave feedback on the city''s Web site.', 'Please find attached a schedule of recycling collection days.', 'Due to the holiday, we have replacement crews working most of this week.', 'D', 'A. Unfortunately, we cannot take items that have not been thoroughly cleaned. (thông báo về quy định vệ sinh)
B. You can also leave feedback on the city''s Web site. (thông tin về website)
C. Please find attached a schedule of recycling collection days. (lịch thu gom)
D. Due to the holiday, we have replacement crews working most of this week. (thông tin về nhân viên thay thế)
Đáp án đúng là D vì:
1. Tính liên kết:
- Giải thích lý do cho câu tiếp theo "some crew members are not familiar with the routes"
- Hợp lý với tình huống bỏ sót thu gom
2. Thông tin phù hợp với:
- Thời điểm (January 2 - sau kỳ nghỉ lễ)
- Vấn đề bỏ sót (do nhân viên mới)
3. Các đáp án khác không phù hợp vì:
- A không liên quan đến vấn đề bỏ sót
- B không giải thích được câu tiếp theo
- C không liên quan đến ngữ cảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6942, 5536, 142, NULL, 'fulfillment', 'fulfill', 'fulfilling', 'fulfilled', 'B', 'A. fulfillment (sự hoàn thành - danh từ)
B. fulfill (hoàn thành - động từ nguyên mẫu)
C. fulfilling (đang hoàn thành - hiện tại phân từ)
D. fulfilled (đã hoàn thành - quá khứ phân từ)
Đáp án đúng là B (fulfill).
Giải thích:
1. Cấu trúc ngữ pháp: "help + sb + (to) verb"
2. "Fulfill" phù hợp vì:
- Là động từ nguyên mẫu sau "help"
- Diễn tả mục tiêu cần đạt được
3. Các đáp án khác sai vì:
- "Fulfillment" là danh từ, không phù hợp
- "Fulfilling" là V-ing, không theo sau "help"
- "Fulfilled" là quá khứ phân từ, không phù hợp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5537, 244, NULL, NULL, 'To: All employees
From: Keith Voigt, Product Development Manager
Date: March 22
Subject: Luxe-7 handbag
Due to disappointing sales of our Luxe-7 leather handbag, we have decided to discontinue this item, effective immediately. Unfortunately, consumers found our ad campaign less 143....... than we expected. Additionally, the design did not stand out against its competitors. Moving forward, the design team will be given several 144........ outlined by our research team to help them create prototypes of new bags. 145........ . We believe the additional work that is being requested will be difficult 146...... beneficial.', 'Gửi đến: Tất cả nhân viên
Từ: Keith Voigt, Giám đốc phát triển sản phẩm
Ngày: 22 tháng 3
Chủ đề: Túi xách Luxe-7
Do doanh số bán hàng đáng thất vọng của túi xách da Luxe-7 của chúng tôi, chúng tôi đã quyết định ngừng sản xuất mặt hàng này, có hiệu lực ngay lập tức. Thật không may, người tiêu dùng nhận thấy chiến dịch quảng cáo của chúng tôi ít hơn 143....... so với dự kiến của chúng tôi. Ngoài ra, thiết kế không nổi bật so với các đối thủ cạnh tranh. Tiến về phía trước, nhóm thiết kế sẽ được cung cấp một số 144....... được nhóm nghiên cứu của chúng tôi phác thảo để giúp họ tạo ra các nguyên mẫu của những chiếc túi mới. 145........ . Chúng tôi tin rằng công việc bổ sung đang được yêu cầu sẽ khó khăn 146...... có lợi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6943, 5537, 143, NULL, 'gradual', 'compelling', 'repetitive', 'doubtful', 'B', 'A. gradual (dần dần - tính từ)
B. compelling (thuyết phục - tính từ)
C. repetitive (lặp đi lặp lại - tính từ)
D. doubtful (đáng ngờ - tính từ)
Đáp án đúng là B (compelling).
Giải thích:
1. Ngữ cảnh:
- Nói về chiến dịch quảng cáo không thành công
- Cần tính từ chỉ tính thuyết phục của quảng cáo
2. "Compelling" phù hợp vì:
- Mô tả sức thuyết phục, hấp dẫn
- Thường dùng đánh giá hiệu quả quảng cáo
3. Các đáp án khác không phù hợp vì:
- "Gradual" không liên quan đến quảng cáo
- "Repetitive" mang nghĩa tiêu cực
- "Doubtful" không phù hợp với ngữ cảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6944, 5537, 144, NULL, 'specifying', 'specification', 'specifications', 'specifies', 'C', 'A. specifying (việc chỉ rõ - danh động từ)
B. specification (thông số kỹ thuật - danh từ số ít)
C. specifications (các thông số kỹ thuật - danh từ số nhiều)
D. specifies (chỉ rõ - động từ)
Đáp án đúng là C (specifications).
Giải thích:
1. Ngữ cảnh:
- Cần danh từ sau từ "several"
- Nói về nhiều yêu cầu kỹ thuật
2. "Specifications" phù hợp vì:
- Là danh từ số nhiều sau "several"
- Chỉ các yêu cầu chi tiết từ team nghiên cứu
3. Các đáp án khác sai vì:
- "Specifying" là V-ing
- "Specification" là số ít
- "Specifies" là động từ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6945, 5537, 145, NULL, 'However, less expensive materials are available.', 'The commercial features examples of modern employees.', 'Following that, we will gather feedback from potential customers.', 'Your efforts helped to truly make a difference.', 'C', 'A. However, less expensive materials are available (thông tin về vật liệu)
B. The commercial features examples of modern employees (thông tin về quảng cáo)
C. Following that, we will gather feedback from potential customers (thông tin về khảo sát)
D. Your efforts helped to truly make a difference (lời cảm ơn)
Đáp án đúng là C vì:
1. Tính liên kết:
- Nối tiếp quy trình thiết kế mẫu mới
- Logic với việc cải thiện sản phẩm
2. Phù hợp với:
- Mục tiêu khắc phục thất bại
- Quy trình phát triển sản phẩm
3. Các đáp án khác không phù hợp vì:
- A không liên quan đến thiết kế mới
- B nói về quảng cáo cũ
- D không phù hợp ngữ cảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6946, 5537, 146, NULL, 'for', 'as', 'yet', 'if', 'C', 'A. for (cho - giới từ)
B. as (như - liên từ)
C. yet (nhưng - liên từ)
D. if (nếu - liên từ)
Đáp án đúng là C (yet).
Giải thích:
1. Cấu trúc ngữ pháp: "difficult yet beneficial"
2. "Yet" phù hợp vì:
- Nối 2 tính từ đối lập
- Thể hiện sự đối nghịch tích cực
3. Các đáp án khác sai vì:
- "For" không nối được 2 tính từ
- "As" không diễn tả được sự đối lập
- "If" không phù hợp về nghĩa');;

-- Data for 2025 Test5 Part 7
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5538, 245, NULL, NULL, 'To: Vayu Dhebar < dhebarv@quincy-inc.com>
From: Andre Longoria <andre1 @ wilmarrentals.com>
Date: April 13
Subject: Vehicle rental
Dear Ms. Dhebar,
Thank you for choosing Wilmar Rentals for your recent vehicle rental needs. To help us improve our customer service, we ask that you fill out a brief questionnaire to provide honest feedback about your experience. Simply click here and complete the online form. To show our appreciation for your participation, I will e-mail you a voucher that will allow you to extend your next rental by three days at no extra charge. This can be used anytime in the next 12 months.
Thank you for your patronage!
Andre Longoria
Customer Service, Wilmar Rentals', 'Gửi: Vayu Dhebar <dhebarv@quincy-inc.com>
Từ: Andre Longoria <andre1@wilmarrentals.com>
Ngày: 13 tháng 4
Chủ đề: Thuê xe
Thưa cô Dhebar,
Cảm ơn cô đã chọn Wilmar Rentals cho nhu cầu thuê xe gần đây của cô. Để giúp chúng tôi cải thiện dịch vụ khách hàng, chúng tôi yêu cầu cô điền vào một bảng câu hỏi ngắn để cung cấp phản hồi trung thực về trải nghiệm của cô. Chỉ cần nhấp vào đây và hoàn thành biểu mẫu trực tuyến. Để thể hiện sự cảm kích của chúng tôi đối với sự tham gia của cô, tôi sẽ gửi email cho cô một phiếu giảm giá cho phép cô gia hạn lần thuê tiếp theo thêm ba ngày mà không tính thêm phí. Phiếu này có thể được sử dụng bất cứ lúc nào trong 12 tháng tới.
Cảm ơn sự ủng hộ của cô!
Andre Longoria
Dịch vụ Khách hàng, Wilmar Rentals');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6947, 5538, 147, 'What does Mr. Longoria ask Ms. Dhebar to do?', 'Confirm her preferred vehicle size', 'Pay the remaining balance of a bill', 'Share her opinions about a service', 'Participate in a free workshop', 'C', 'Đáp án đúng là C.
Giải thích:
Trong email, Mr. Longoria yêu cầu: "we ask that you fill out a brief questionnaire to provide honest feedback about your experience" (chúng tôi yêu cầu bạn điền vào bảng câu hỏi ngắn để cung cấp phản hồi trung thực về trải nghiệm của bạn). Điều này trực tiếp khớp với đáp án C - chia sẻ ý kiến về dịch vụ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mr. Longoria yêu cầu Ms. Dhebar làm gì?
A. Xác nhận kích thước xe ưa thích
B. Thanh toán số dư còn lại của hóa đơn
C. Chia sẻ ý kiến về một dịch vụ
D. Tham gia một hội thảo miễn phí');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6948, 5538, 148, 'What does Mr. Longoria plan to do for Ms. Dhebar?', 'Meet her at a customer feedback session', 'Upgrade her vehicle to a larger size', 'Extend a one-year subscription at no cost', 'Provide a voucher for free rental days', 'D', 'Đáp án đúng là D.
Giải thích:
Trong email có đoạn: "I will e-mail you a voucher that will allow you to extend your next rental by three days at no extra charge" (tôi sẽ gửi email cho bạn một phiếu giảm giá cho phép bạn gia hạn lần thuê tiếp theo thêm ba ngày mà không tính thêm phí). Điều này chính xác với đáp án D - cung cấp phiếu giảm giá cho những ngày thuê miễn phí.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mr. Longoria dự định làm gì cho Ms. Dhebar?
A. Gặp cô ấy tại một buổi phản hồi của khách hàng
B. Nâng cấp xe của cô ấy lên kích thước lớn hơn
C. Gia hạn đăng ký một năm miễn phí
D. Cung cấp phiếu giảm giá cho những ngày thuê miễn phí');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5539, 245, NULL, NULL, 'Harry Alvarez [3:22 P.M.]
Good afternoon, and welcome to DC Interiors.
Cora Baldwin [3:23 P.M.]
Hi, my name is Cora Baldwin, and I''m having difficulty canceling some items.
& Harry Alvarez [3:24 P.M.]
Hi, Ms. Baldwin. Did you make your purchase online or through the app?
Cora Baldwin [3:25 P.M.]
Through my online account. I ordered the wrong color, so I need to cancel it. I don''t want to be charged for this because I already purchased replacements elsewhere.
Harry Alvarez [3:27 P.M.]
I understand. I can help you. It''s the purchase of three 10-liter cans of the Dark Forest latex paint, right? I can cancel the request and refund you.
Cora Baldwin [3:28 P.M.]
You got it.
Harry Alvarez [3:29 P.M.]
Alright. That cancellation has gone through. You should expect to see a refund of £53.85 on your credit card account in three to five working days. Can I help you with anything else?
Cora Baldwin [3:31 P.M.]
That''s all. Thank you!', 'Harry Alvarez [3:22 chiều]
Xin chào buổi chiều và chào mừng đến với DC Interiors.
Cora Baldwin [3:23 chiều]
Xin chào, tôi tên là Cora Baldwin, và tôi đang gặp khó khăn trong việc hủy một số mặt hàng.
Harry Alvarez [3:24 chiều]
Xin chào, cô Baldwin. Cô đã mua hàng trực tuyến hay qua ứng dụng?
Cora Baldwin [3:25 chiều]
Qua tài khoản trực tuyến của tôi. Tôi đã đặt nhầm màu, vì vậy tôi cần hủy nó. Tôi không muốn bị tính phí vì tôi đã mua hàng thay thế ở nơi khác.
Harry Alvarez [3:27 chiều]
Tôi hiểu rồi. Tôi có thể giúp cô. Đó là việc mua ba lon sơn latex Dark Forest 10 lít, đúng không? Tôi có thể hủy yêu cầu và hoàn tiền cho cô.
Cora Baldwin [3:28 chiều]
Đúng rồi.
Harry Alvarez [3:29 chiều]
Được rồi. Việc hủy đã được thực hiện. Cô sẽ nhận được khoản hoàn tiền £53.85 trong tài khoản thẻ tín dụng trong vòng ba đến năm ngày làm việc. Tôi có thể giúp gì thêm cho cô không?
Cora Baldwin [3:31 chiều]
Vậy thôi. Cảm ơn bạn!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6949, 5539, 149, 'What most likely is Mr. Alvarez''s job?', 'Customer service agent', 'Interior designer', 'Bank representative', 'Smartphone application developer', 'A', 'Đáp án đúng là A.
Giải thích:
Dựa vào cuộc hội thoại, Mr. Alvarez thể hiện vai trò là nhân viên dịch vụ khách hàng vì:
1. Anh ấy chào đón khách hàng đến với DC Interiors
2. Anh ấy có thể truy cập thông tin đơn hàng của khách
3. Anh ấy có khả năng hủy đơn hàng và xử lý hoàn tiền
4. Anh ấy sử dụng ngôn ngữ chuyên nghiệp và phong cách giao tiếp của nhân viên dịch vụ khách hàng

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Công việc của Mr. Alvarez nhiều khả năng là gì?
A. Nhân viên dịch vụ khách hàng
B. Nhà thiết kế nội thất
C. Đại diện ngân hàng
D. Nhà phát triển ứng dụng điện thoại thông minh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6950, 5539, 150, 'At 3:28 P.M., what does Ms. Baldwin most likely mean when she writes, "You got it"?', 'The business has an item in stock', 'She has already received a refund', 'Mr. Alvarez is referring to the correct order', 'She will contact the business within five days', 'C', 'Đáp án đúng là C.
Giải thích:
Khi Ms. Baldwin nói "You got it", cô ấy đang xác nhận rằng Mr. Alvarez đã đề cập đúng đơn hàng của cô (three 10-liter cans of the Dark Forest latex paint). Điều này được thể hiện trong ngữ cảnh của cuộc hội thoại khi Mr. Alvarez hỏi để xác nhận đơn hàng ("It''s the purchase of three 10-liter cans of the Dark Forest latex paint, right?") và Ms. Baldwin trả lời "You got it" để xác nhận.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 3:28 chiều, Ms. Baldwin có ý gì khi viết "You got it"?
A. Doanh nghiệp có sản phẩm trong kho
B. Cô ấy đã nhận được tiền hoàn lại
C. Mr. Alvarez đang đề cập đến đúng đơn hàng
D. Cô ấy sẽ liên hệ với doanh nghiệp trong vòng năm ngày');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5540, 245, NULL, NULL, 'Freshtime Cleaning Services
Serving Aurora, Huntington, and Durham for the past five years!
Available Monday to Saturday, 8 A.M. to 8 P.M., excluding national holidays.
Freshtime Cleaning Services provides top-notch cleaning to commercial properties. Our founder, Terry Nolan, is passionate about making your space clean and relaxing, and our dedicated team of cleaners is always thorough and careful. Whether you need a one-time deep clean, a weekly routine clean, or something else, we can help you. We use environmentally friendly cleaning products, and we are fully insured.
We are especially looking for new clients in need of cleaning between tenants. Call Jana Rogova at 555-8716 to discuss rates.', 'Dịch vụ Vệ sinh Freshtime
Phục vụ tại Aurora, Huntington và Durham trong 5 năm qua!
Làm việc từ Thứ Hai đến Thứ Bảy, 8 giờ sáng đến 8 giờ tối, trừ các ngày lễ quốc gia.
Dịch vụ Vệ sinh Freshtime cung cấp dịch vụ vệ sinh hàng đầu cho các cơ sở thương mại. Người sáng lập của chúng tôi, Terry Nolan, luôn đam mê làm cho không gian của bạn sạch sẽ và thư giãn, và đội ngũ nhân viên tận tâm của chúng tôi luôn kỹ lưỡng và cẩn thận. Cho dù bạn cần vệ sinh sâu một lần, vệ sinh định kỳ hàng tuần, hay điều gì khác, chúng tôi có thể giúp bạn. Chúng tôi sử dụng các sản phẩm vệ sinh thân thiện với môi trường và được bảo hiểm đầy đủ.
Chúng tôi đặc biệt đang tìm kiếm khách hàng mới cần dịch vụ vệ sinh giữa các đợt cho thuê. Gọi cho Jana Rogova theo số 555-8716 để thảo luận về giá cả.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6951, 5540, 151, 'What is true about Freshtime Cleaning Services?', 'It has been in business for more than a decade', 'It serves both homes and businesses', 'It operates in three different locations', 'It must be booked for multiple cleaning sessions', 'C', 'Đáp án đúng là C.
Giải thích:
Theo quảng cáo, Freshtime Cleaning Services hoạt động tại ba địa điểm: "Serving Aurora, Huntington, and Durham for the past five years!" (Phục vụ tại Aurora, Huntington và Durham trong 5 năm qua). Các đáp án khác không chính xác vì:
A. Công ty mới hoạt động 5 năm, không phải hơn một thập kỷ
B. Công ty chỉ phục vụ cho các cơ sở thương mại ("provides top-notch cleaning to commercial properties")
D. Công ty cung cấp cả dịch vụ một lần ("one-time deep clean")

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì đúng về Freshtime Cleaning Services?
A. Nó đã hoạt động kinh doanh hơn một thập kỷ
B. Nó phục vụ cả nhà ở và doanh nghiệp
C. Nó hoạt động tại ba địa điểm khác nhau
D. Nó phải được đặt cho nhiều phiên dọn dẹp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6952, 5540, 152, 'According to the advertisement, who should call Ms. Rogova?', 'Hotel guests', 'Cleaning supply wholesalers', 'Property owners', 'Part-time cleaners', 'C', 'Đáp án đúng là C.
Giải thích:
Theo quảng cáo: "We are especially looking for new clients in need of cleaning between tenants. Call Jana Rogova at 555-8716 to discuss rates" (Chúng tôi đặc biệt đang tìm kiếm khách hàng mới cần dịch vụ vệ sinh giữa các đợt cho thuê). Điều này cho thấy họ đang tìm kiếm chủ sở hữu bất động sản - những người cần dịch vụ vệ sinh giữa các đợt cho thuê.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo quảng cáo, ai nên gọi cho Ms. Rogova?
A. Khách sạn
B. Nhà bán buôn đồ vệ sinh
C. Chủ sở hữu bất động sản
D. Nhân viên vệ sinh bán thời gian');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5541, 245, NULL, NULL, 'TEMPORARY CLOSURE FOR INSTALLATION
Summary: Installation of playground equipment
Estimated re-opening date: May 17
Department in Charge:
New Haven Recreational Facilities
1756 Alvarez Street, Suite #32
New Haven, CT 06506
Contractor:
Pierson Services
305 Gordon Road
Woodbridge, CT 06525
Further information about the project can be found on the city''s Web site. Should you experience noise disturbances or other issues, please call 203-555-1771.', 'ĐÓNG CỬA TẠM THỜI ĐỂ LẮP ĐẶT
Tóm tắt: Lắp đặt thiết bị sân chơi
Ngày mở cửa lại dự kiến: 17 tháng 5
Bộ phận Phụ trách:
Cơ sở Giải trí New Haven
1756 Đường Alvarez, Suite #32
New Haven, CT 06506
Nhà thầu:
Dịch vụ Pierson
305 Đường Gordon
Woodbridge, CT 06525
Thông tin thêm về dự án có thể được tìm thấy trên trang web của thành phố. Nếu bạn gặp phải tiếng ồn hoặc các vấn đề khác, vui lòng gọi 203-555-1771.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6953, 5541, 153, 'Where would this sign most likely be posted?', 'Outside a private gym', 'In a commercial warehouse', 'At a public park', 'Above a department store shelf', 'C', 'Đáp án đúng là C.
Giải thích:
Biển báo này nhiều khả năng được đặt tại công viên công cộng vì:
1. Nội dung đề cập đến việc lắp đặt thiết bị sân chơi (Installation of playground equipment)
2. Bộ phận phụ trách là New Haven Recreational Facilities (Cơ sở Giải trí New Haven)
3. Có thông tin trên trang web của thành phố (city''s Web site)
Tất cả những điều này đều gợi ý đây là một không gian công cộng, cụ thể là công viên công cộng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Biển báo này nhiều khả năng được đặt ở đâu?
A. Bên ngoài phòng tập tư nhân
B. Trong kho thương mại
C. Tại công viên công cộng
D. Trên kệ cửa hàng bách hóa');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6954, 5541, 154, 'Why should people call the phone number on the sign?', 'To report missing items', 'To make a complaint', 'To donate some equipment', 'To inquire about a schedule', 'B', 'Đáp án đúng là B.
Giải thích:
Theo biển báo: "Should you experience noise disturbances or other issues, please call 203-555-1771" (Nếu bạn gặp phải tiếng ồn hoặc các vấn đề khác, vui lòng gọi 203-555-1771). Số điện thoại được cung cấp để người dân có thể gọi điện phàn nàn về tiếng ồn hoặc các vấn đề khác trong quá trình lắp đặt.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tại sao mọi người nên gọi số điện thoại trên biển báo?
A. Để báo cáo các vật dụng bị mất
B. Để khiếu nại
C. Để quyên góp thiết bị
D. Để hỏi về lịch trình');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5542, 245, NULL, NULL, 'On February 8, the Centennial Community Center will host an event for local job seekers. We are looking for people to donate their time to assist with one-on-one practice interviews. A background in human resources or management is preferred. The sessions will be audio recorded, and participants will be given a printout of the conversation so they can refer to it later. This event will greatly help participants who are seeking steady employment. Please contact Lara Harvey at 555-2904 for more information.', 'Vào ngày 8 tháng 2, Trung tâm Cộng đồng Centennial sẽ tổ chức một sự kiện cho người tìm việc địa phương. Chúng tôi đang tìm kiếm người sẵn sàng dành thời gian để hỗ trợ phỏng vấn thực hành một-một. Ưu tiên người có kinh nghiệm trong nhân sự hoặc quản lý. Các buổi phỏng vấn sẽ được ghi âm, và người tham gia sẽ được cung cấp bản in của cuộc trò chuyện để họ có thể tham khảo sau này. Sự kiện này sẽ giúp ích rất nhiều cho những người đang tìm kiếm việc làm ổn định. Vui lòng liên hệ Lara Harvey theo số 555-2904 để biết thêm thông tin.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6955, 5542, 155, 'What is the purpose of the information?', 'To raise money for a community center', 'To announce a policy change', 'To publicize a volunteer opportunity', 'To provide job interview tips', 'C', 'Đáp án đúng là C.
Giải thích:
Thông tin đang kêu gọi tình nguyện viên: "We are looking for people to donate their time to assist with one-on-one practice interviews" (Chúng tôi đang tìm kiếm người sẵn sàng dành thời gian để hỗ trợ phỏng vấn thực hành một-một). Đây rõ ràng là một cơ hội tình nguyện.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mục đích của thông tin này là gì?
A. Gây quỹ cho trung tâm cộng đồng
B. Thông báo thay đổi chính sách
C. Công bố cơ hội tình nguyện
D. Cung cấp lời khuyên phỏng vấn việc làm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6956, 5542, 156, 'According to the information, what will participants be able to do?', 'Apply for a management position', 'Record a welcome video', 'Meet local business owners', 'Receive a transcript', 'D', 'Đáp án đúng là D.
Giải thích:
Theo thông tin: "participants will be given a printout of the conversation so they can refer to it later" (người tham gia sẽ được cung cấp bản in của cuộc trò chuyện để họ có thể tham khảo sau này). Điều này đồng nghĩa với việc họ sẽ nhận được bản ghi (transcript) cuộc phỏng vấn.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo thông tin, người tham gia sẽ có thể làm gì?
A. Ứng tuyển vào vị trí quản lý
B. Ghi video chào mừng
C. Gặp gỡ các chủ doanh nghiệp địa phương
D. Nhận bản ghi');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6957, 5542, 157, 'The word "steady", in paragraph 1, line 6, is closest in meaning to', 'customary', 'durable', 'stable', 'persistent', 'C', 'Đáp án đúng là C.
Giải thích:
Từ "steady" trong cụm "steady employment" (việc làm ổn định) có nghĩa gần nhất với "stable" (ổn định). Trong ngữ cảnh tìm việc làm, "steady employment" đề cập đến công việc ổn định, lâu dài, không bấp bênh.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Từ "steady" trong đoạn 1, dòng 6, có nghĩa gần nhất với từ nào?
A. thông thường
B. bền bỉ
C. ổn định
D. kiên trì');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5543, 245, NULL, NULL, 'MEDINA VIRTUAL MAILBOXES
834 Stroude Road, Beamhurst
Phone: 070 5517 3713
Your mail is safe in our hands!
• You can keep the same virtual address even after you move.
* With our Standard Service, we will store your mail, including envelopes and packages requiring a signature. You will be notified by text whenever your mail is dropped off to us.
* With our Gold Service, we can also forward the mail daily, open and scan it, or shred it. Simply log in from any device with your secure customer code to view an initial scan of the front of each piece of mail. Then choose what further action we should take with it.
For this month only, enroll in our Gold Service to receive 25% off the first six months of your annual contract.', 'HỘP THƯ ẢO MEDINA
834 Đường Stroude, Beamhurst
Điện thoại: 070 5517 3713
Thư của bạn an toàn trong tay chúng tôi!
• Bạn có thể giữ cùng một địa chỉ ảo ngay cả sau khi chuyển nhà.
* Với Dịch vụ Tiêu chuẩn, chúng tôi sẽ lưu trữ thư của bạn, bao gồm cả phong bì và bưu kiện cần chữ ký. Bạn sẽ được thông báo qua tin nhắn bất cứ khi nào thư của bạn được gửi đến cho chúng tôi.
* Với Dịch vụ Vàng, chúng tôi cũng có thể chuyển tiếp thư hàng ngày, mở và quét nó, hoặc hủy nó. Chỉ cần đăng nhập từ bất kỳ thiết bị nào với mã khách hàng bảo mật của bạn để xem bản quét ban đầu mặt trước của từng thư. Sau đó chọn hành động tiếp theo chúng tôi nên thực hiện với nó.
Chỉ trong tháng này, đăng ký Dịch vụ Vàng để nhận giảm giá 25% cho sáu tháng đầu tiên của hợp đồng hàng năm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6958, 5543, 158, 'When does Medina Virtual Mailboxes send a notification to customers?', 'When it has forwarded some mail', 'When an item arrives at the site', 'When the subscription is about to expire', 'When a storage area is nearly full', 'B', 'Đáp án đúng là B.
Giải thích:
Theo quảng cáo dịch vụ Standard Service: "You will be notified by text whenever your mail is dropped off to us" (Bạn sẽ được thông báo qua tin nhắn bất cứ khi nào thư của bạn được gửi đến cho chúng tôi). Điều này chỉ ra rằng thông báo được gửi khi một món hàng đến địa điểm.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Khi nào Medina Virtual Mailboxes gửi thông báo cho khách hàng?
A. Khi họ đã chuyển tiếp thư
B. Khi một món hàng đến địa điểm
C. Khi đăng ký sắp hết hạn
D. Khi khu vực lưu trữ gần đầy');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6959, 5543, 159, 'What should customers do to choose what happens to their mail?', 'Log in with a secure code', 'Set the instructions in their contract', 'Call the company''s office', 'Send a text message to the business', 'A', 'Đáp án đúng là A.
Giải thích:
Theo mô tả dịch vụ Gold Service: "Simply log in from any device with your secure customer code to view an initial scan of the front of each piece of mail. Then choose what further action we should take with it" (Chỉ cần đăng nhập từ bất kỳ thiết bị nào với mã khách hàng bảo mật của bạn để xem bản quét ban đầu mặt trước của từng thư. Sau đó chọn hành động tiếp theo chúng tôi nên thực hiện với nó).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Khách hàng nên làm gì để chọn cách xử lý thư của họ?
A. Đăng nhập bằng mã bảo mật
B. Đặt hướng dẫn trong hợp đồng
C. Gọi điện cho văn phòng công ty
D. Gửi tin nhắn cho doanh nghiệp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6960, 5543, 160, 'How can customers be eligible for a discount?', 'By signing up for a premium service', 'By committing to a half-year contract', 'By downloading a voucher from the system', 'By paying for the service six months in advance', 'A', 'Đáp án đúng là A.
Giải thích:
Theo quảng cáo: "For this month only, enroll in our Gold Service to receive 25% off the first six months of your annual contract" (Chỉ trong tháng này, đăng ký Dịch vụ Vàng để nhận giảm giá 25% cho sáu tháng đầu tiên của hợp đồng hàng năm). Gold Service là dịch vụ cao cấp (premium service) và việc đăng ký dịch vụ này sẽ giúp khách hàng đủ điều kiện nhận giảm giá.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Làm thế nào khách hàng có thể đủ điều kiện nhận giảm giá?
A. Bằng cách đăng ký dịch vụ cao cấp
B. Bằng cách cam kết hợp đồng nửa năm
C. Bằng cách tải phiếu giảm giá từ hệ thống
D. Bằng cách thanh toán dịch vụ trước sáu tháng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5544, 245, NULL, NULL, 'Riverdale Bike Safety Day
Do you want to make sure your bicycle is safe to ride on the roads and trails?
Then don''t miss Riverdale Bike Safety Day at Sunrise Park on July 20 from 10 A.M. to 4 P.M.
Certified bicycle repair technicians will be on site to check your bicycle at no cost to you. They can perform basic maintenance and repairs such as fixing or replacing chains, adjusting seat heights, patching and filling flat tires, and checking brake cables. To save time, you can book a time slot in advance at Tony''s Bike Shop. Alternatively, simply stop by and wait in line.
Riverdale Bike Safety Day is made possible by the Meadowland Grant and sponsorship from Tony''s Bike Shop.
For more information, visit www.riverdalecommunity.org/bikesafety.', 'Ngày An toàn Xe đạp Riverdale
Bạn có muốn đảm bảo xe đạp của mình an toàn để đi trên đường và đường mòn không?
Vậy đừng bỏ lỡ Ngày An toàn Xe đạp Riverdale tại Công viên Sunrise vào ngày 20 tháng 7 từ 10 giờ sáng đến 4 giờ chiều.
Các kỹ thuật viên sửa xe đạp được chứng nhận sẽ có mặt tại chỗ để kiểm tra xe đạp của bạn mà không tính phí. Họ có thể thực hiện bảo trì và sửa chữa cơ bản như sửa hoặc thay thế xích, điều chỉnh độ cao yên xe, vá và bơm lốp xẹp, và kiểm tra cáp phanh. Để tiết kiệm thời gian, bạn có thể đặt lịch trước tại Cửa hàng Xe đạp Tony. Hoặc, chỉ cần ghé qua và xếp hàng chờ.
Ngày An toàn Xe đạp Riverdale được thực hiện nhờ Khoản tài trợ Meadowland và tài trợ từ Cửa hàng Xe đạp Tony.
Để biết thêm thông tin, hãy truy cập www.riverdalecommunity.org/bikesafety.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6961, 5544, 161, 'What is the purpose of the notice?', 'To announce the launch of a business', 'To explain some safety regulations', 'To promote a bike race', 'To advertise a free service', 'D', 'Đáp án đúng là D.
Giải thích:
Thông báo quảng cáo một dịch vụ miễn phí: "Certified bicycle repair technicians will be on site to check your bicycle at no cost to you" (Các kỹ thuật viên sửa xe đạp được chứng nhận sẽ có mặt tại chỗ để kiểm tra xe đạp của bạn mà không tính phí). Họ cung cấp dịch vụ bảo trì và sửa chữa cơ bản miễn phí.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mục đích của thông báo là gì?
A. Để thông báo về việc ra mắt một doanh nghiệp
B. Để giải thích một số quy định an toàn
C. Để quảng bá một cuộc đua xe đạp
D. Để quảng cáo một dịch vụ miễn phí');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6962, 5544, 162, 'What is expected to happen on July 20?', 'A new public bike trail will be opened', 'Air will be added to some bike tires', 'Participants will receive a certificate', 'Bicycles will be sold at a discount', 'B', 'Đáp án đúng là B.
Giải thích:
Theo thông báo, các kỹ thuật viên sẽ thực hiện các dịch vụ bảo trì cơ bản bao gồm "patching and filling flat tires" (vá và bơm lốp xẹp). Điều này có nghĩa là họ sẽ bơm không khí vào lốp xe đạp khi cần thiết.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được dự kiến sẽ xảy ra vào ngày 20 tháng 7?
A. Một đường đi xe đạp công cộng mới sẽ được mở
B. Không khí sẽ được bơm vào một số lốp xe đạp
C. Người tham gia sẽ nhận được chứng chỉ
D. Xe đạp sẽ được bán giảm giá');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6963, 5544, 163, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "Alternatively, simply stop by and wait in line."', '[1]', '[2]', '[3]', '[4]', 'C', 'Đáp án đúng là C.
Giải thích:
Câu "Alternatively, simply stop by and wait in line" (Hoặc, chỉ cần ghé qua và xếp hàng chờ) nên được đặt ở vị trí [3] vì:
1. Nó đi ngay sau câu "To save time, you can book a time slot in advance at Tony''s Bike Shop" (Để tiết kiệm thời gian, bạn có thể đặt lịch trước tại Cửa hàng Xe đạp Tony)
2. Từ "Alternatively" (Hoặc) cho thấy đây là một lựa chọn thay thế cho việc đặt lịch trước
3. Vị trí này tạo ra sự liên kết logic giữa hai phương án mà người dân có thể chọn: đặt lịch trước hoặc đến trực tiếp và chờ đợi

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Câu "Alternatively, simply stop by and wait in line" phù hợp nhất với vị trí nào trong số các vị trí được đánh dấu [1], [2], [3], và [4]?');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5545, 245, NULL, NULL, 'Aira Kasslin [1:23 P.M.] Good afternoon, Kengo and Tammy. I wanted to check how the testing of our new allergy medicine is going. It would be best to have this round completed by Wednesday because an inspector will be checking our equipment on Thursday.
Kengo Yoneda [1:24 P.M.] We have one more analysis to run, which should be finished today.
Aira Kasslin [1:25 p.M.] That''s a relief. That means we''ll be able to start recruiting for the clinical trials next Monday as scheduled. Do either of you have time to compile a list of local healthcare providers from the database?
Tammy Garza [1:27 P.M.] Sorry, Aira. I''m leaving tomorrow to attend the regional conference. I wouldn''t be able to start any new projects until next Tuesday.
Kengo Voneda [1:28 p.M.] I haven''t used that program, but I''m willing to try.
Aira Kasslin [1:31 P.M.] Thanks, Kengo! The software is a bit confusing to use at first, but there are clear instructions in the manual. I''ll ask the IT team for a copy.
Kengo Yoneda [1:32 p.M.] That would be really helpful.
Tammy Garza [1:33 P.M.] Actually, that''s not necessary. I have a printout in my desk. ''ll bring it to you after lunch.
Kengo Yoneda [1:36 P.M.] Alright. Thanks, Tammy.
Aira Kasslin [1:37 p.M.] Then everything is set. Thank you both for your hard work, and I look forward to reading your reports.', 'Aira Kasslin [1:23 chiều] Chào buổi chiều, Kengo và Tammy. Tôi muốn kiểm tra xem việc thử nghiệm thuốc chống dị ứng mới của chúng ta đang tiến triển như thế nào. Tốt nhất là hoàn thành đợt này vào thứ Tư vì một thanh tra viên sẽ kiểm tra thiết bị của chúng ta vào thứ Năm.
Kengo Yoneda [1:24 chiều] Chúng tôi còn một phân tích nữa cần chạy, dự kiến sẽ hoàn thành hôm nay.
Aira Kasslin [1:25 chiều] Thật nhẹ nhõm. Điều đó có nghĩa là chúng ta sẽ có thể bắt đầu tuyển người cho các thử nghiệm lâm sàng vào thứ Hai tuần sau như đã lên lịch. Một trong hai bạn có thời gian để tổng hợp danh sách các nhà cung cấp dịch vụ y tế địa phương từ cơ sở dữ liệu không?
Tammy Garza [1:27 chiều] Xin lỗi, Aira. Tôi sẽ đi dự hội nghị khu vực vào ngày mai. Tôi sẽ không thể bắt đầu bất kỳ dự án mới nào cho đến thứ Ba tuần sau.
Kengo Yoneda [1:28 chiều] Tôi chưa từng sử dụng chương trình đó, nhưng tôi sẵn sàng thử.
Aira Kasslin [1:31 chiều] Cảm ơn Kengo! Phần mềm hơi khó sử dụng lúc đầu, nhưng có hướng dẫn rõ ràng trong sách hướng dẫn. Tôi sẽ hỏi đội IT để lấy một bản.
Kengo Yoneda [1:32 chiều] Điều đó sẽ rất hữu ích.
Tammy Garza [1:33 chiều] Thực ra, điều đó không cần thiết. Tôi có một bản in trong bàn của tôi. Tôi sẽ mang nó cho bạn sau bữa trưa.
Kengo Yoneda [1:36 chiều] Được rồi. Cảm ơn Tammy.
Aira Kasslin [1:37 chiều] Vậy là mọi thứ đã sẵn sàng. Cảm ơn cả hai vì công việc chăm chỉ của các bạn, và tôi mong được đọc báo cáo của các bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6964, 5545, 164, 'For what type of business do the writers most likely work?', 'A supermarket chain', 'A software testing center', 'A dental clinic', 'A research laboratory', 'D', 'Đáp án đúng là D.
Giải thích:
Những chi tiết sau cho thấy họ làm việc trong phòng thí nghiệm nghiên cứu:
1. Họ đang thử nghiệm thuốc chống dị ứng mới ("testing of our new allergy medicine")
2. Có các cuộc thử nghiệm lâm sàng ("clinical trials")
3. Có thiết bị cần được kiểm tra
4. Họ tiến hành phân tích ("analysis")

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Những người trong đoạn hội thoại nhiều khả năng làm việc cho loại hình doanh nghiệp nào?
A. Chuỗi siêu thị
B. Trung tâm kiểm thử phần mềm
C. Phòng khám nha khoa
D. Phòng thí nghiệm nghiên cứu');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6965, 5545, 165, 'When will an inspection be carried out?', 'This Wednesday', 'This Thursday', 'Next Monday', 'Next Tuesday', 'B', 'Đáp án đúng là B.
Giải thích:
Theo đoạn hội thoại, Aira Kasslin nói: "It would be best to have this round completed by Wednesday because an inspector will be checking our equipment on Thursday" (Tốt nhất là hoàn thành đợt này vào thứ Tư vì một thanh tra viên sẽ kiểm tra thiết bị của chúng ta vào thứ Năm). Vì vậy, cuộc kiểm tra sẽ diễn ra vào thứ Năm.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Khi nào cuộc kiểm tra sẽ được tiến hành?
A. Thứ Tư này
B. Thứ Năm này
C. Thứ Hai tuần sau
D. Thứ Ba tuần sau');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6966, 5545, 166, 'What is indicated about Mr. Yoneda?', 'He is interested in attending a conference', 'He is not familiar with a software program', 'He had trouble accessing the database', 'He cannot take on any new projects', 'B', 'Đáp án đúng là B.
Giải thích:
Trong đoạn hội thoại, Mr. Yoneda nói: "I haven''t used that program, but I''m willing to try" (Tôi chưa từng sử dụng chương trình đó, nhưng tôi sẵn sàng thử). Điều này cho thấy ông ấy không quen với chương trình phần mềm được đề cập.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Mr. Yoneda?
A. Anh ấy quan tâm đến việc tham dự một hội nghị
B. Anh ấy không quen với một chương trình phần mềm
C. Anh ấy gặp khó khăn trong việc truy cập cơ sở dữ liệu
D. Anh ấy không thể nhận thêm dự án mới');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6967, 5545, 167, 'At 1:33 P.M., what does Ms. Garza most likely mean when she writes, "that''s not necessary"?', 'An assignment can be given to a different employee', 'Mr. Kasslin does not need to contact the IT team', 'She can attend a conference remotely this time', 'A manual''s instructions will be updated soon', 'B', 'Đáp án đúng là B.
Giải thích:
Khi Ms. Garza nói "that''s not necessary", cô ấy đang đáp lại việc Aira Kasslin nói sẽ hỏi đội IT để lấy bản sao sách hướng dẫn ("I''ll ask the IT team for a copy"). Ms. Garza nói điều đó không cần thiết vì cô ấy đã có bản in trong bàn ("I have a printout in my desk"). Do đó, cô ấy muốn nói rằng Aira Kasslin không cần phải liên hệ với đội IT.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 1:33 chiều, Ms. Garza có ý gì khi viết "that''s not necessary"?
A. Một nhiệm vụ có thể được giao cho một nhân viên khác
B. Anh Kasslin không cần liên hệ với đội IT
C. Cô ấy có thể tham dự hội nghị từ xa lần này
D. Hướng dẫn trong sách hướng dẫn sẽ sớm được cập nhật');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5546, 245, NULL, NULL, 'Royal Indigo to Give Brae Airlines a New Look
SYDNEY (17 February)-Brae Airlines has hired fashion house Royal Indigo to create new uniforms for the airline''s cabin crew.
The designs are expected to be approved in March, and from that point, it will take about three months before passengers see the new style on board.
Senior brand manager Teija Raita said the uniforms have remained the same for a decade and the change is part of the company''s brand redesign.
"We''re certain that Royal Indigo''s creativity will produce an iconic uniform that makes our brand memorable and gives us a fresh look," said Ms. Raita. "Until now, we have not had high-end brands supply our uniforms, so we are excited about this collaboration."
Ms. Raita has been with the company for less than a year, taking over from Ava Holloway last November and immediately seeing to renovating and improving Brae''s airport lounges in Sydney and Singapore.
She has also streamlined the company''s social media posts and commissioned a new logo, and she is now looking into working with nonprofit organizations related to travel.', 'Royal Indigo sẽ mang đến diện mạo mới cho Brae Airlines
SYDNEY (17 tháng 2) - Brae Airlines đã thuê nhà thời trang Royal Indigo để tạo ra đồng phục mới cho phi hành đoàn của hãng hàng không.
Các thiết kế dự kiến sẽ được phê duyệt vào tháng 3, và từ thời điểm đó sẽ mất khoảng ba tháng trước khi hành khách thấy kiểu dáng mới trên máy bay.
Giám đốc thương hiệu cấp cao Teija Raita cho biết đồng phục đã không thay đổi trong một thập kỷ và việc thay đổi này là một phần trong việc thiết kế lại thương hiệu của công ty.
"Chúng tôi tin chắc rằng sự sáng tạo của Royal Indigo sẽ tạo ra một đồng phục mang tính biểu tượng khiến thương hiệu của chúng tôi đáng nhớ và mang lại cho chúng tôi một diện mạo mới," Ms. Raita nói. "Cho đến nay, chúng tôi chưa từng có các thương hiệu cao cấp cung cấp đồng phục cho chúng tôi, vì vậy chúng tôi rất hào hứng về sự hợp tác này."
Ms. Raita đã làm việc tại công ty chưa đầy một năm, tiếp quản từ Ava Holloway vào tháng 11 năm ngoái và ngay lập tức chú trọng việc cải tạo và cải thiện phòng chờ sân bay của Brae tại Sydney và Singapore.
Cô ấy cũng đã tinh gọn các bài đăng trên mạng xã hội của công ty và đặt hàng một logo mới, và hiện cô ấy đang xem xét việc hợp tác với các tổ chức phi lợi nhuận liên quan đến du lịch.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6968, 5546, 168, 'When will the new uniforms most likely first be used?', 'In February', 'In March', 'In June', 'In November', 'C', 'Đáp án đúng là C.
Giải thích:
Theo bài báo, thiết kế dự kiến sẽ được phê duyệt vào tháng 3, và từ thời điểm đó sẽ mất khoảng ba tháng trước khi hành khách thấy kiểu dáng mới trên máy bay ("The designs are expected to be approved in March, and from that point, it will take about three months before passengers see the new style on board"). Vì vậy, đồng phục mới nhiều khả năng sẽ được sử dụng lần đầu vào tháng 6.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Khi nào đồng phục mới nhiều khả năng sẽ được sử dụng lần đầu?
A. Vào tháng 2
B. Vào tháng 3
C. Vào tháng 6
D. Vào tháng 11');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6969, 5546, 169, 'What does the article indicate about Brae Airlines'' partnership with Royal Indigo?', 'It is Brae Airlines'' first time working with a luxury brand', 'It is expected to last for at least ten years', 'It will only affect customers traveling in first class', 'It was finalized after three months of negotiation', 'A', 'Đáp án đúng là A.
Giải thích:
Theo phát biểu của Ms. Raita: "Until now, we have not had high-end brands supply our uniforms" (Cho đến nay, chúng tôi chưa từng có các thương hiệu cao cấp cung cấp đồng phục cho chúng tôi). Đây là lần đầu tiên Brae Airlines hợp tác với một thương hiệu cao cấp.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Bài báo chỉ ra điều gì về sự hợp tác giữa Brae Airlines và Royal Indigo?
A. Đây là lần đầu tiên Brae Airlines làm việc với một thương hiệu cao cấp
B. Dự kiến sẽ kéo dài ít nhất mười năm
C. Chỉ ảnh hưởng đến khách hàng đi hạng nhất
D. Được hoàn tất sau ba tháng đàm phán');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6970, 5546, 170, 'According to the article, who is Ms. Holloway?', 'A Brae Airlines senior analyst', 'The lead designer at Royal Indigo', 'A former Brae Airlines brand manager', 'The founder of Brae Airlines', 'C', 'Đáp án đúng là C.
Giải thích:
Theo bài báo: "Ms. Raita has been with the company for less than a year, taking over from Ava Holloway last November" (Ms. Raita đã làm việc tại công ty chưa đầy một năm, tiếp quản từ Ava Holloway vào tháng 11 năm ngoái). Do đó, Ms. Holloway là cựu quản lý thương hiệu của Brae Airlines.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo bài báo, ai là Ms. Holloway?
A. Một nhà phân tích cấp cao của Brae Airlines
B. Nhà thiết kế trưởng tại Royal Indigo
C. Cựu quản lý thương hiệu của Brae Airlines
D. Người sáng lập Brae Airlines');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6971, 5546, 171, 'What task did Ms. Raita complete first at Brae Airlines?', 'She had the airline''s logo updated', 'She improved the company''s social media presence', 'She moved the main office to Singapore', 'She had some airport lounges upgraded', 'D', 'Đáp án đúng là D.
Giải thích:
Theo bài báo, Ms. Raita "immediately seeing to renovating and improving Brae''s airport lounges in Sydney and Singapore" (ngay lập tức chú trọng việc cải tạo và cải thiện phòng chờ sân bay của Brae tại Sydney và Singapore) sau khi tiếp quản vị trí. Đây là nhiệm vụ đầu tiên được đề cập.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Nhiệm vụ nào Ms. Raita hoàn thành đầu tiên tại Brae Airlines?
A. Cô ấy đã cập nhật logo của hãng hàng không
B. Cô ấy cải thiện sự hiện diện trên mạng xã hội của công ty
C. Cô ấy chuyển trụ sở chính đến Singapore
D. Cô ấy đã nâng cấp một số phòng chờ sân bay');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5547, 245, NULL, NULL, '16 October
Daniel McGill
Page by Page Bookshop
477 Armory Street
Rochester, NY 14604
Dear Mr. McGill,
Grantham Publishing is seeking independent retailers to carry our latest work, Beneath the Surface. Having received rave reviews from literary critics, the novel brings its readers a unique combination of drama and science. Beneath the Surface examines what happens to broken and outdated computers and smartphones once they are no longer in use. Although it is a fictional account of a small town negatively affected by soil contamination at its local landfill, it contains factual information based on the latest research.
The two authors of Beneath the Surface are Nathaniel Lee, an environmental scientist, and Dr. Cecelia Sandoval, an ecology professor at Wilford University. Both are highly esteemed in their respective fields. Mr. Lee has been awarded the prestigious Caldwell Prize, and Dr. Sandoval is acclaimed for consulting tor an online educational program. I hey are making their publishing debut with Beneath the Surface and would be happy to sign some of the copies being sent to your store.
I can provide you with further details about Beneath the Surface anytime. I look forward to hearing from you.
All the best,
Zachary Wesley', '16 tháng 10
Daniel McGill
Hiệu sách Page by Page
477 Đường Armory
Rochester, NY 14604
Kính gửi ông McGill,
Nhà xuất bản Grantham đang tìm kiếm các nhà bán lẻ độc lập để phân phối tác phẩm mới nhất của chúng tôi, Beneath the Surface. Sau khi nhận được nhiều đánh giá tích cực từ các nhà phê bình văn học, tiểu thuyết mang đến cho độc giả sự kết hợp độc đáo giữa kịch tính và khoa học. Beneath the Surface khám phá những gì xảy ra với các máy tính và điện thoại thông minh hỏng và lỗi thời khi chúng không còn được sử dụng. Mặc dù đây là một câu chuyện hư cấu về một thị trấn nhỏ bị ảnh hưởng tiêu cực bởi ô nhiễm đất tại bãi rác địa phương, nó chứa thông tin thực tế dựa trên nghiên cứu mới nhất.
Hai tác giả của Beneath the Surface là Nathaniel Lee, một nhà khoa học môi trường, và Tiến sĩ Cecelia Sandoval, giáo sư sinh thái học tại Đại học Wilford. Cả hai đều được đánh giá cao trong lĩnh vực tương ứng của họ. Ông Lee đã được trao giải thưởng Caldwell danh giá, và Tiến sĩ Sandoval được khen ngợi vì tư vấn cho một chương trình giáo dục trực tuyến. Họ đang ra mắt xuất bản phẩm đầu tay với Beneath the Surface và sẽ rất vui lòng ký tặng một số bản sách được gửi đến cửa hàng của bạn.
Tôi có thể cung cấp cho bạn thêm chi tiết về Beneath the Surface bất cứ lúc nào. Tôi mong nhận được phản hồi từ bạn.
Trân trọng,
Zachary Wesley');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6972, 5547, 172, 'What does Mr. Wesley want to do?', 'Recruit judges for a writing contest', 'Improve the availability of a book for sale', 'Promote the grand opening of a bookshop', 'Hire a designer to create a book cover', 'B', 'Đáp án đúng là B.
Giải thích:
Mr. Wesley đang tìm kiếm các nhà bán lẻ độc lập để bán cuốn sách mới nhất của họ: "Grantham Publishing is seeking independent retailers to carry our latest work". Mục đích của ông là muốn tăng khả năng tiếp cận của cuốn sách đến độc giả thông qua việc mở rộng kênh phân phối.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mr. Wesley muốn làm gì?
A. Tuyển giám khảo cho một cuộc thi viết
B. Cải thiện khả năng tiếp cận của một cuốn sách để bán
C. Quảng bá việc khai trương một hiệu sách
D. Thuê nhà thiết kế để tạo bìa sách');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6973, 5547, 173, 'What is mentioned about Beneath the Surface?', 'It is available as a digital file for computers', 'It explores the disposal of old electronics', 'It has been nominated for an award', 'It is based on a critically acclaimed drama', 'B', 'Đáp án đúng là B.
Giải thích:
Theo thư, "Beneath the Surface examines what happens to broken and outdated computers and smartphones once they are no longer in use" (Beneath the Surface khám phá những gì xảy ra với các máy tính và điện thoại thông minh hỏng và lỗi thời khi chúng không còn được sử dụng). Cuốn sách tập trung vào việc xử lý các thiết bị điện tử cũ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được đề cập về Beneath the Surface?
A. Nó có sẵn dưới dạng tệp kỹ thuật số cho máy tính
B. Nó khám phá việc xử lý các thiết bị điện tử cũ
C. Nó đã được đề cử cho một giải thưởng
D. Nó dựa trên một vở kịch được đánh giá cao');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6974, 5547, 174, 'What is indicated about Mr. Lee and Dr. Sandoval?', 'They have collected soil samples', 'They will visit Mr. McGill''s store', 'They are first-time authors', 'They founded an online education platform', 'C', 'Đáp án đúng là C.
Giải thích:
Theo thư: "They are making their publishing debut with Beneath the Surface" (Họ đang ra mắt xuất bản phẩm đầu tay với Beneath the Surface). Điều này cho thấy họ là những tác giả lần đầu xuất bản.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về ông Lee và Tiến sĩ Sandoval?
A. Họ đã thu thập các mẫu đất
B. Họ sẽ đến thăm cửa hàng của ông McGill
C. Họ là những tác giả lần đầu
D. Họ đã thành lập một nền tảng giáo dục trực tuyến');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6975, 5547, 175, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "Both are highly esteemed in their respective fields."', '[1]', '[2]', '[3]', '[4]', 'C', 'Đáp án đúng là C.
Giải thích:
Câu "Both are highly esteemed in their respective fields" (Cả hai đều được đánh giá cao trong lĩnh vực tương ứng của họ) nên được đặt ở vị trí [3] vì:
1. Nó đi sau phần giới thiệu về hai tác giả và chuyên môn của họ
2. Nó dẫn dắt tự nhiên đến việc liệt kê thành tựu cụ thể của từng người (giải Caldwell của Lee và việc tư vấn cho chương trình giáo dục của Sandoval)

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Câu "Both are highly esteemed in their respective fields" phù hợp nhất với vị trí nào trong số các vị trí được đánh dấu [1], [2], [3], và [4]?
A. [1]
B. [2]
C. [3]
D. [4]');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5548, 245, NULL, NULL, 'www.gipomcon.com
GHI Production & Operations Management Conference
Call for Seminar Proposals
Goh Heavy Industries (GHI) will convene the first-ever GHI Production & Operations Management Conference on 21-22 June at the Singapore Convention Centre. We are calling for proposals from production and operations experts to lead seminars on their organizations'' successful actions in response to business challenges. The ideal seminar topic will relate to the conference theme of "Advances in the Age of Analytics," but other topics will also be accepted.
Proposals must be between 100 and 200 words long and accompanied by a summary of the submitter''s qualifications. Roughly 30 proposals will be chosen for presentation in seminar form if many more submissions are received, additional submitters may be invited to participate in themed 90-minute panel discussions instead. Submitters should be aware that proposals chosen for seminars must then be submitted to the Production & Operations Management Society (POMS) for approval so that each seminar will count as an hour of professional development for POMS members in attendance.
Please use this online form to submit your proposal to the conference''s organizing committee by 15 November.
==========
E-Mail message
From: Wei Chua
To: Leslie Briggs
Subject: Conference submission
Date: 11 December
Dear Ms. Briggs,
On behalf of the GHI Production & Operations Management Conference organizing committee, it is my pleasure to invite you to lead a seminar on your proposed topic, "Using Machine Learning to Optimize Backup Crew Scheduling in Airlines."
Please respond to this e-mail by 20 December to confirm your intention to participate in the conference. Once you do, I will send you information about how to begin the process of POMS accreditation.
Best,
Wei Chua
Organizing Committee
GHI Production & Operations Management Conference', 'www.gipomcon.com
Hội nghị Quản lý Sản xuất & Vận hành GHI
Thư mời Đề xuất Hội thảo
Goh Heavy Industries (GHI) sẽ tổ chức Hội nghị Quản lý Sản xuất & Vận hành GHI lần đầu tiên vào ngày 21-22 tháng 6 tại Trung tâm Hội nghị Singapore. Chúng tôi đang kêu gọi đề xuất từ các chuyên gia sản xuất và vận hành để dẫn dắt các hội thảo về những hành động thành công của tổ chức họ trong việc đối phó với các thách thức kinh doanh. Chủ đề hội thảo lý tưởng sẽ liên quan đến chủ đề hội nghị "Tiến bộ trong Kỷ nguyên Phân tích", nhưng các chủ đề khác cũng sẽ được chấp nhận.
Đề xuất phải dài từ 100 đến 200 từ và kèm theo tóm tắt về trình độ của người nộp. Khoảng 30 đề xuất sẽ được chọn để trình bày dưới dạng hội thảo nếu nhận được nhiều đề xuất hơn, những người nộp đơn bổ sung có thể được mời tham gia vào các cuộc thảo luận nhóm theo chủ đề kéo dài 90 phút thay thế. Người nộp đơn nên biết rằng các đề xuất được chọn cho hội thảo sau đó phải được nộp cho Hiệp hội Quản lý Sản xuất & Vận hành (POMS) để phê duyệt để mỗi hội thảo sẽ được tính là một giờ phát triển chuyên môn cho các thành viên POMS tham dự.
Vui lòng sử dụng biểu mẫu trực tuyến này để nộp đề xuất của bạn cho ủy ban tổ chức hội nghị trước ngày 15 tháng 11.
==========
Thư điện tử
Từ: Wei Chua
Đến: Leslie Briggs
Chủ đề: Nộp hội nghị
Ngày: 11 tháng 12
Kính gửi cô Briggs,
Thay mặt ủy ban tổ chức Hội nghị Quản lý Sản xuất & Vận hành GHI, tôi rất vui mừng được mời cô dẫn dắt một hội thảo về chủ đề đề xuất của cô, "Sử dụng Học máy để Tối ưu hóa Lập lịch Phi hành đoàn Dự phòng trong Hàng không".
Vui lòng trả lời email này trước ngày 20 tháng 12 để xác nhận ý định tham gia hội nghị của cô. Sau khi cô làm vậy, tôi sẽ gửi cho cô thông tin về cách bắt đầu quá trình chứng nhận POMS.
Trân trọng,
Wei Chua
Ủy ban Tổ chức
Hội nghị Quản lý Sản xuất & Vận hành GHI');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6976, 5548, 176, 'What type of organization is holding the conference?', 'A professional association', 'A national government agency', 'A university department', 'A manufacturing company', 'D', 'Đáp án đúng là D.
Giải thích:
Tổ chức tổ chức hội nghị là Goh Heavy Industries (GHI), một công ty sản xuất, như được thể hiện trong phần đầu thông báo: "Goh Heavy Industries (GHI) will convene the first-ever GHI Production & Operations Management Conference".

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Loại tổ chức nào đang tổ chức hội nghị?
A. Một hiệp hội chuyên nghiệp
B. Một cơ quan chính phủ quốc gia
C. Một khoa của trường đại học
D. Một công ty sản xuất');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6977, 5548, 177, 'What is NOT a requirement for seminar proposals?', 'They must describe actions taken by an organization', 'They must be of a certain length', 'They must be submitted by e-mail', 'They must come with information about the submitter', 'C', 'Đáp án đúng là C.
Giải thích:
Theo thông báo, các yêu cầu bắt buộc cho đề xuất hội thảo bao gồm:
- Mô tả hành động thành công của tổ chức
- Độ dài từ 100-200 từ
- Kèm theo tóm tắt trình độ của người nộp
Không có yêu cầu nào về việc phải nộp qua email. Thông báo nói "Please use this online form" (Vui lòng sử dụng biểu mẫu trực tuyến này).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG phải là yêu cầu cho đề xuất hội thảo?
A. Chúng phải mô tả hành động được thực hiện bởi một tổ chức
B. Chúng phải có độ dài nhất định
C. Chúng phải được nộp qua email
D. Chúng phải kèm theo thông tin về người nộp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6978, 5548, 178, 'According to the notice, what will some submitters be asked to do?', 'Join an alternative type of event', 'Contribute an article to a publication', 'Allow their presentation to be recorded', 'Arrive at the venue especially early', 'A', 'Đáp án đúng là A.
Giải thích:
Theo thông báo, nếu nhận được nhiều đề xuất hơn số lượng dự kiến, một số người nộp đơn có thể được mời tham gia vào các cuộc thảo luận nhóm thay thế: "if many more submissions are received, additional submitters may be invited to participate in themed 90-minute panel discussions instead".

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo thông báo, một số người nộp đơn sẽ được yêu cầu làm gì?
A. Tham gia một loại sự kiện thay thế
B. Đóng góp một bài viết cho ấn phẩm
C. Cho phép bài thuyết trình của họ được ghi lại
D. Đến địa điểm đặc biệt sớm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6979, 5548, 179, 'For how long will Ms. Briggs most likely appear in front of an audience at the conference?', '15 minutes', '30 minutes', 'One hour', '90 minutes', 'C', 'Đáp án đúng là C.
Giải thích:
Theo thông báo, mỗi hội thảo sẽ được tính là một giờ phát triển chuyên môn: "each seminar will count as an hour of professional development". Vì Ms. Briggs được mời dẫn dắt một hội thảo, cô ấy có thể sẽ xuất hiện trước khán giả trong một giờ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Briggs nhiều khả năng sẽ xuất hiện trước khán giả tại hội nghị trong bao lâu?
A. 15 phút
B. 30 phút
C. Một giờ
D. 90 phút');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6980, 5548, 180, 'What is suggested about Ms. Briggs?', 'She submitted more than one seminar proposal', 'She is responsible for managing an aircraft design process', 'She works for a company that is based in Singapore', 'She has used technology to address a staffing issue', 'D', 'Đáp án đúng là D.
Giải thích:
Dựa vào chủ đề hội thảo của Ms. Briggs: "Using Machine Learning to Optimize Backup Crew Scheduling in Airlines" (Sử dụng Học máy để Tối ưu hóa Lập lịch Phi hành đoàn Dự phòng trong Hàng không), có thể thấy cô ấy đã sử dụng công nghệ (học máy) để giải quyết vấn đề nhân sự (lập lịch phi hành đoàn dự phòng).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về Ms. Briggs?
A. Cô ấy đã nộp nhiều hơn một đề xuất hội thảo
B. Cô ấy chịu trách nhiệm quản lý quy trình thiết kế máy bay
C. Cô ấy làm việc cho một công ty có trụ sở tại Singapore
D. Cô ấy đã sử dụng công nghệ để giải quyết vấn đề nhân sự');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5549, 245, NULL, NULL, 'Home                 Our Products                      In the News                 Contact
Ocalox is at the forefront of manufacturing textile treatments. Our revolutionary products can be used on a wide range of fabrics, creating a waterproof layer that stops the absorption of water.
The application process is easy. A solution of Ocalox and warm water is prepared according to the instructions. The fabric is then soaked in the mixture for a duration of 20 minutes. Then, the fabric should be extended on a flat surface and left to air-dry for at least 6 hours. The item is then ready for use without further laundering.
Select the right high-performance treatment to address your specific needs:
Product Number        Quantity Options.             Formulated For
R350                              10L, 30L, 60L                    Clothing (breathable)
R370                              10L, 30L, 60L                    Outerwear (non-breathable)
T125                               10L, 30L                               Shoes and hiking boots
Contact our customer service line at 1-800-555-2626 to inquire about bulk rates.
=========
E-Mail message
To: customerservice@ocalox.com
From: chosusan@steltzermfg.com
Date: September 22
Subject: Product issue
Dear Customer Service Team:
We have been using your 125 product in our manufacturing process for the past six months.
Overall, we have been pleased with the results, and both customer feedback and quality-control testing have been positive.
However, recently we started noticing some kind of sticky substance remaining on the fabric''s surface after the drying time. The container is from the same batch as others that we used without any issues, so I think it may be a problem with the way we were storing the product. Could you please let me know how this should be done properly? I didn''t see any information about this matter in the instructions.
Many thanks,
Susan Cho
Steltzer Manufacturing', 'Trang chủ Sản phẩm của chúng tôi Trong Tin tức Liên hệ
Ocalox đi đầu trong sản xuất xử lý dệt may. Các sản phẩm mang tính cách mạng của chúng tôi có thể được sử dụng trên nhiều loại vải, tạo ra một lớp chống thấm nước ngăn chặn sự hấp thụ nước.
Quá trình ứng dụng rất dễ dàng. Một dung dịch Ocalox và nước ấm được chuẩn bị theo hướng dẫn. Vải sau đó được ngâm trong hỗn hợp trong khoảng thời gian 20 phút. Sau đó, vải nên được kéo dài trên một bề mặt phẳng và để khô trong không khí trong ít nhất 6 giờ. Sau đó, mặt hàng đã sẵn sàng để sử dụng mà không cần giặt thêm.
Chọn phương pháp xử lý hiệu suất cao phù hợp để giải quyết các nhu cầu cụ thể của bạn:
Tùy chọn số lượng số lượng sản phẩm. Công thức cho
R350 10L, 30L, 60L Quần áo (thoáng khí)
R370 10L, 30L, 60L Áo khoác ngoài (không thoáng khí)
Giày T125 10L, 30L và giày đi bộ đường dài
Liên hệ với đường dây dịch vụ khách hàng của chúng tôi theo số 1-800-555-2626 để hỏi về mức giá số lượng lớn.
=========
Tin nhắn qua email
Gửi: customerservice@ocalox.com
Từ: chosusan@steltzermfg.com
Ngày: 22 tháng 9
Chủ đề: Vấn đề sản phẩm
Kính gửi Đội ngũ dịch vụ khách hàng:
Chúng tôi đã sử dụng 125 của bạn Sản phẩm trong quá trình sản xuất của chúng tôi trong sáu tháng qua.
Nhìn chung, chúng tôi hài lòng với kết quả, và cả phản hồi của khách hàng và kiểm tra kiểm soát chất lượng đều tích cực.
Tuy nhiên, gần đây chúng tôi bắt đầu nhận thấy một số loại chất dính còn sót lại trên bề mặt vải sau thời gian sấy. Hộp đựng từ cùng một lô hàng khác mà chúng tôi đã sử dụng mà không có bất kỳ vấn đề gì, vì vậy tôi nghĩ đó có thể là vấn đề với cách chúng tôi lưu trữ sản phẩm. Bạn có thể vui lòng cho tôi biết việc này nên được thực hiện đúng cách như thế nào không? Tôi không thấy bất kỳ thông tin nào về vấn đề này trong hướng dẫn.
Cảm ơn bạn rất nhiều,
Susan Cho
Steltzer Manufacturing');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6981, 5549, 181, 'What are Ocalox''s products designed to do?', 'Make surface colors last longer', 'Improve the durability of fabric', 'Provide a barrier against moisture', 'Clean textiles gently and effectively', 'C', 'Đáp án đúng là C.
Giải thích:
Theo trang web, sản phẩm của Ocalox được thiết kế để "creating a waterproof layer that stops the absorption of water" (tạo một lớp chống thấm ngăn chặn sự hấp thụ nước). Điều này cho thấy sản phẩm được thiết kế để tạo ra một rào cản chống lại độ ẩm.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Sản phẩm của Ocalox được thiết kế để làm gì?
A. Làm cho màu bề mặt bền lâu hơn
B. Cải thiện độ bền của vải
C. Tạo rào cản chống lại độ ẩm
D. Làm sạch vải một cách nhẹ nhàng và hiệu quả');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6982, 5549, 182, 'On the Web page, the word "extended" in paragraph 2, line 3, is closest in meaning to', 'spread out', 'continued', 'put off', 'prolonged', 'A', 'Đáp án đúng là A.
Giải thích:
Trong ngữ cảnh "the fabric should be extended on a flat surface", từ "extended" có nghĩa là "spread out" (trải ra), chỉ hành động trải vải ra trên một bề mặt phẳng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Trên trang web, từ "extended" trong đoạn 2, dòng 3, có nghĩa gần nhất với từ nào?
A. trải ra
B. tiếp tục
C. trì hoãn
D. kéo dài');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6983, 5549, 183, 'What is suggested about Steltzer Manufacturing?', 'Its products failed a safety test', 'It was founded six months ago', 'It strives to use eco-friendly goods', 'It produces footwear commercially', 'D', 'Đáp án đúng là D.
Giải thích:
Steltzer Manufacturing sử dụng sản phẩm T125 của Ocalox trong quá trình sản xuất của họ, và theo trang web, T125 được công thức hóa cho "Shoes and hiking boots" (Giày và giày leo núi). Điều này gợi ý rằng công ty sản xuất giày dép thương mại.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về Steltzer Manufacturing?
A. Các sản phẩm của nó không đạt kiểm tra an toàn
B. Nó được thành lập cách đây sáu tháng
C. Nó cố gắng sử dụng hàng hóa thân thiện với môi trường
D. Nó sản xuất giày dép thương mại');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6984, 5549, 184, 'What is the purpose of Ms. Cho''s e-mail?', 'To request a copy of some instructions', 'To get information about storage', 'To cancel a supply contract', 'To request a replacement product', 'B', 'Đáp án đúng là B.
Giải thích:
Ms. Cho gửi email để hỏi về cách bảo quản sản phẩm đúng cách: "Could you please let me know how this should be done properly?" và "I think it may be a problem with the way we were storing the product". Mục đích của email là để lấy thông tin về cách bảo quản.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mục đích của email của Ms. Cho là gì?
A. Yêu cầu một bản sao hướng dẫn
B. Lấy thông tin về bảo quản
C. Hủy hợp đồng cung cấp
D. Yêu cầu sản phẩm thay thế');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6985, 5549, 185, 'What problem does Ms. Cho mention about her company''s manufacturing process?', 'A product has a strong odor', 'A residue is left behind', 'The drying time has increased', 'The fabric''s surface tears easily', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email của Ms. Cho, vấn đề họ gặp phải là "some kind of sticky substance remaining on the fabric''s surface after the drying time" (một loại chất dính còn sót lại trên bề mặt vải sau thời gian sấy khô). Đây là một vấn đề về chất dư (residue) còn lại trên vải.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Cho đề cập đến vấn đề gì về quy trình sản xuất của công ty cô ấy?
A. Một sản phẩm có mùi mạnh
B. Có chất dư còn sót lại
C. Thời gian sấy khô đã tăng lên
D. Bề mặt vải dễ rách');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5550, 245, NULL, NULL, 'SALINAS(3 March)—Atwell Power has finalized the sites for a large-scale renewable energy project in the region that would provide electricity to thousands of homes and businesses. The project will involve the installation of wind turbines at four locations. These sites have already been inspected for environmental considerations and have received the necessary permits from the state and federal governments. Atwell Power will construct the turbines and substations themselves, but construction of the transmission lines linking the electricity output to the distribution grid will be handled by a third party. A spokesperson said that Atwell Power''s project will create numerous jobs for highly skilled workers in the area, and it will begin advertising for these positions from early next month.
===========
Site.                          Number of Turbines               Annual Generation (per turbine)
Brunswick                           80                                     5.8 million kilowatt-hours
Crafton                                60                                     5.6 million kilowatt-hours
Ruckman Valley                 45                                     5.9 million kilowatt-hours
Valdosta.                              75                                     6.1 million kilowatt-hours
==========
To: Alison Huber <a.huber@atwellpower.com>
From: Guillermo Miranda <g.miranda@atwellpower.com>
Date: May 7
Subject: Wind turbine project
Dear Ms. Huber,
I''d like to follow up on the issue we discussed at last week''s meeting regarding the Crafton site. As the public roadways are not suitable for the transportation of our equipment, we will need to construct a temporary access road off of Highway 162.
Please note that due to the ground composition there, stability checks will need to be carried out once every three months rather than twice a year.
As for the outside contractor portion of the project, we have accepted a bid from Bassell Inc., and I will work on the contract this week.
I will update you again soon,
Guillermo Miranda', 'SALINAS (ngày 3 tháng 3)—Atwell Power đã hoàn thiện các địa điểm cho một dự án năng lượng tái tạo quy mô lớn trong khu vực sẽ cung cấp điện cho hàng ngàn hộ gia đình và doanh nghiệp. Dự án sẽ liên quan đến việc lắp đặt tuabin gió tại bốn địa điểm. Các địa điểm này đã được kiểm tra về các cân nhắc về môi trường và đã nhận được các giấy phép cần thiết từ chính quyền tiểu bang và liên bang. Atwell Power sẽ tự xây dựng các tuabin và trạm biến áp, nhưng việc xây dựng các đường dây truyền tải liên kết sản lượng điện với lưới phân phối sẽ do bên thứ ba xử lý. Một phát ngôn viên cho biết dự án của Atwell Power sẽ tạo ra nhiều việc làm cho các công nhân có tay nghề cao trong khu vực và sẽ bắt đầu quảng cáo cho các vị trí này từ đầu tháng tới.
=========
Trang web. Số lượng tuabin thế hệ hàng năm (mỗi tuabin)
Brunswick 80 5,8 triệu kilowatt-giờ
Crafton 60 5,6 triệu kilowatt-giờ
Thung lũng Ruckman 45 5,9 triệu kilowatt-giờ
Valdosta. 75 6,1 triệu kilowatt-giờ
==========
Gửi: Alison Huber <a.huber@atwellpower.com>
Từ: Guillermo Miranda <g.miranda@atwellpower.com>
Ngày: 7 tháng 5
Chủ đề: Dự án tuabin gió
Kính gửi cô Huber,
Tôi muốn theo dõi vấn đề chúng ta đã thảo luận tại cuộc họp tuần trước liên quan đến địa điểm Crafton. Vì các tuyến đường công cộng không phù hợp để vận chuyển thiết bị của chúng tôi, chúng tôi sẽ cần xây dựng một con đường tiếp cận tạm thời ngoài Quốc lộ 162.
Xin lưu ý rằng do thành phần mặt đất ở đó, việc kiểm tra độ ổn định sẽ cần được thực hiện ba tháng một lần thay vì hai lần một năm.
Đối với phần nhà thầu bên ngoài của dự án, chúng tôi đã chấp nhận hồ sơ dự thầu từ Bassell Inc. và tôi sẽ thực hiện hợp đồng trong tuần này.
Tôi sẽ cập nhật lại cho bạn sớm,
Guillermo Miranda');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6986, 5550, 186, 'What is indicated about Atwell Power?', 'It had several delays in its project plans', 'It has designed a new type of wind turbine', 'It will begin recruiting new employees in April', 'It had contested a decision by the federal government', 'C', 'Đáp án đúng là C.
Giải thích:
Theo bài viết: "it will begin advertising for these positions from early next month" (công ty sẽ bắt đầu quảng cáo cho các vị trí này từ đầu tháng tới). Vì bài viết được đề ngày 3 tháng 3, nên tuyển dụng sẽ bắt đầu vào tháng 4.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Atwell Power?
A. Nó có một số trì hoãn trong kế hoạch dự án
B. Nó đã thiết kế một loại tua-bin gió mới
C. Nó sẽ bắt đầu tuyển dụng nhân viên mới vào tháng 4
D. Nó đã phản đối một quyết định của chính phủ liên bang');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6987, 5550, 187, 'What site is expected to produce the most energy per turbine?', 'Brunswick', 'Crafton', 'Ruckman Valley', 'Valdosta', 'D', 'Đáp án đúng là D.
Giải thích:
Theo bảng dữ liệu, địa điểm Valdosta có mức sản xuất năng lượng hàng năm cao nhất cho mỗi tua-bin với 6.1 triệu kilowatt-giờ, so với:
- Brunswick: 5.8 triệu kilowatt-giờ
- Crafton: 5.6 triệu kilowatt-giờ
- Ruckman Valley: 5.9 triệu kilowatt-giờ

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Địa điểm nào dự kiến sẽ sản xuất nhiều năng lượng nhất trên mỗi tua-bin?
A. Brunswick
B. Crafton
C. Ruckman Valley
D. Valdosta');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6988, 5550, 188, 'Why did Mr. Miranda write the e-mail?', 'To request new equipment', 'To negotiate a contract', 'To propose a solution', 'To apologize for an error', 'C', 'Đáp án đúng là C.
Giải thích:
Mr. Miranda viết email để đề xuất giải pháp cho vấn đề về đường vận chuyển thiết bị tại địa điểm Crafton: "As the public roadways are not suitable for the transportation of our equipment, we will need to construct a temporary access road off of Highway 162" (Vì đường công cộng không phù hợp cho việc vận chuyển thiết bị của chúng ta, chúng ta sẽ cần xây dựng một con đường tạm thời từ Đường 162).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tại sao ông Miranda viết email?
A. Để yêu cầu thiết bị mới
B. Để đàm phán hợp đồng
C. Để đề xuất giải pháp
D. Để xin lỗi về một lỗi');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6989, 5550, 189, 'What task will Bassel Inc. most likely be responsible for?', 'Building lines to connect to the power grid', 'Inspecting proposed sites for environmental issues', 'Constructing a roadway linked to the highway', 'Assessing the safety of the project''s substations', 'A', 'Đáp án đúng là A.
Giải thích:
Theo bài viết, "construction of the transmission lines linking the electricity output to the distribution grid will be handled by a third party" (việc xây dựng đường dây truyền tải nối kết điện năng với lưới điện phân phối sẽ do một bên thứ ba thực hiện). Sau đó trong email đề cập "we have accepted a bid from Bassell Inc." (chúng tôi đã chấp nhận một đề nghị từ Bassell Inc.), cho thấy Bassell Inc. chính là bên thứ ba sẽ chịu trách nhiệm xây dựng đường dây kết nối với lưới điện.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Bassel Inc. nhiều khả năng sẽ chịu trách nhiệm cho nhiệm vụ nào?
A. Xây dựng đường dây kết nối với lưới điện
B. Kiểm tra các địa điểm đề xuất về vấn đề môi trường
C. Xây dựng đường kết nối với đường cao tốc
D. Đánh giá an toàn của các trạm biến áp của dự án');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6990, 5550, 190, 'How many turbines will have quarterly stability checks?', '45', '60', '75', '80', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email, các kiểm tra độ ổn định cần được thực hiện ba tháng một lần tại địa điểm Crafton. Theo bảng dữ liệu, Crafton có 60 tua-bin. Do đó, 60 tua-bin sẽ cần kiểm tra độ ổn định hàng quý.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Bao nhiêu tua-bin sẽ được kiểm tra độ ổn định hàng quý?
A. 45
B. 60
C. 75
D. 80');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5551, 245, NULL, NULL, 'E-Mail message
From: Sean Bellinger <sbellinger@zmail.ca>
To: Leo Wright < wright *1@kamet.ca>, Rosa Perez <perez*1@kamet.ca›
Date: May 14, 4:25 p.m.
Subject: A few points
Attachment: Kamet press release
Dear Mr. Wright and Ms. Perez,
I plan to add the information from your press release (attached) to the About Us page of your new Web site, so I wanted to make sure that everything is correct, including the contact information. Since you will launch an extensive advertising campaign for your business, it would be sensible to check the text before the site has a high volume of traffic.
As we discussed over the phone, the homepage is still loading slowly. I believe this is due to the animated clips on that page, which I think should be replaced with static images. You also requested that I show someone from your company how to use the credit card processing system. I can do that by video conference any afternoon this week at your convenience.
Sincerely,
Sean Bellinger
==========
Press Release
Contact: Nancy Rollins, 555-9275
Kamet, located on Cambridge Street opposite the Middleville Mall, is pleased to announce its grand opening on June 1. Kamet was founded by Lawrence Holt, who used to work in accounting but spent all of his free time outdoors, especially going on nature tours and climbing the world''s tallest peaks. He wanted to provide people like him with the best tents, backpacks, sleeping bags, and more, all at affordable prices.
Kamet brings you modern styles from designer Kenny Becerra, a law school graduate and former practicing attorney who had a career change later in life.
The opening day will feature complimentary refreshments, prize drawings, and product demonstrations. Summer is here, so stop in and stock up to make your time in the great outdoors comfortable and safe!
==========
E-Mail message
From: Leo Wright < wright_|@kamet.ca>
To: Sean Bellinger <sbellinger@zmail.ca>
Cc: Rosa Perez < perez_1@kamet.ca>
Date: May 15, 9:21 a.m.
Subject: RE: A few points
Hi Mr. Bellinger,
I''m glad you double-checked the text, as it looks like you are actually working from an earlier version of the press release. There was an error in that document because the career backgrounds of Lawrence Holt and Kenny Becerra were accidentally swapped. Ms. Perez will write new content for the About Us page based on the updated copy of the press release and send it to you later today.
Additionally, Joanne Ramsey can attend the video conference you suggested at 2 P.M. on June 9. She has worked with similar systems before, so I don''t think it will take long for her to familiarize herself with all of the features. And we appreciate that you will continue to be available to address any queries we may have after the site is live.
Warmest regards,
Leo Wright', 'E-mail
Từ: Sean Bellinger <sbellinger@zmail.ca>
Đến: Leo Wright <wright*1@kamet.ca>, Rosa Perez <perez*1@kamet.ca>
Ngày: 14 tháng 5, 4:25 chiều
Chủ đề: Một vài điểm
Đính kèm: Thông cáo báo chí Kamet
Kính gửi ông Wright và cô Perez,
Tôi dự định thêm thông tin từ thông cáo báo chí của bạn (đính kèm) vào trang Về Chúng tôi của trang web mới của bạn, vì vậy tôi muốn đảm bảo rằng mọi thứ đều chính xác, bao gồm cả thông tin liên hệ. Vì bạn sẽ khởi động một chiến dịch quảng cáo rộng rãi cho doanh nghiệp của mình, sẽ là hợp lý khi kiểm tra văn bản trước khi trang web có lượng truy cập cao.
Như chúng ta đã thảo luận qua điện thoại, trang chủ vẫn đang tải chậm. Tôi tin rằng điều này là do các clip động trên trang đó, mà tôi nghĩ nên được thay thế bằng hình ảnh tĩnh. Bạn cũng yêu cầu tôi hướng dẫn cho ai đó từ công ty của bạn cách sử dụng hệ thống xử lý thẻ tín dụng. Tôi có thể làm điều đó qua hội nghị video vào bất kỳ buổi chiều nào trong tuần này theo sự thuận tiện của bạn.
Trân trọng,
Sean Bellinger
============
Thông cáo báo chí
Liên hệ: Nancy Rollins, 555-9275
Kamet, nằm trên đường Cambridge đối diện Trung tâm mua sắm Middleville, vui mừng thông báo khai trương vào ngày 1 tháng 6. Kamet được thành lập bởi Lawrence Holt, người từng làm kế toán nhưng dành toàn bộ thời gian rảnh rỗi của mình ở ngoài trời, đặc biệt là tham gia các tour du lịch thiên nhiên và leo lên những đỉnh núi cao nhất thế giới. Anh ấy muốn cung cấp cho những người như anh ấy những chiếc lều, ba lô, túi ngủ, v.v. tốt nhất, tất cả đều có giá cả phải chăng.
Kamet mang đến cho bạn những phong cách hiện đại từ nhà thiết kế Kenny Becerra, một sinh viên tốt nghiệp trường luật và cựu luật sư hành nghề, người đã thay đổi nghề nghiệp sau này trong cuộc sống.
Ngày khai mạc sẽ có các món giải khát miễn phí, bản vẽ giải thưởng và trình diễn sản phẩm. Mùa hè đã đến, vì vậy hãy dừng lại và tích trữ để làm cho thời gian của bạn ở ngoài trời tuyệt vời thoải mái và an toàn! 
=========
Tin nhắn E-Mail
Từ: Leo Wright < wright_|@kamet.ca>
Gửi: Sean Bellinger <sbellinger@zmail.ca>
Cc: Rosa Perez < perez_1@kamet.ca>
Ngày: 15 tháng 5, 9:21 sáng
Chủ đề: RE: Một vài điểm
Xin chào Mr. Bellinger,
Tôi rất vui vì bạn đã kiểm tra lại văn bản, vì có vẻ như bạn đang thực sự làm việc từ phiên bản trước của thông cáo báo chí. Có một lỗi trong tài liệu đó vì nền tảng nghề nghiệp của Lawrence Holt và Kenny Becerra đã vô tình bị hoán đổi. Cô. Perez sẽ viết nội dung mới cho trang Giới thiệu dựa trên bản cập nhật của thông cáo báo chí và gửi cho bạn vào cuối ngày hôm nay.
Ngoài ra, Joanne Ramsey có thể tham dự hội nghị truyền hình mà bạn đề xuất vào lúc 2 giờ chiều ngày 9 tháng 6. Cô ấy đã từng làm việc với các hệ thống tương tự trước đây, vì vậy tôi không nghĩ rằng sẽ mất nhiều thời gian để cô ấy làm quen với tất cả các tính năng. Và chúng tôi đánh giá cao rằng bạn sẽ tiếp tục sẵn sàng giải quyết bất kỳ thắc mắc nào mà chúng tôi có thể có sau khi trang web hoạt động.
Trân trọng nhất,
Leo Wright');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6991, 5551, 191, 'Who most likely is Mr. Bellinger?', 'A professional photographer', 'An advertising executive', 'A freelance journalist', 'A Web designer', 'D', 'Đáp án đúng là D.
Giải thích:
Dựa vào nội dung email, Mr. Bellinger nhiều khả năng là một nhà thiết kế web vì:
1. Anh ấy đang làm việc trên trang web mới của Kamet
2. Anh ấy thảo luận về các vấn đề kỹ thuật như tốc độ tải trang và các clip động
3. Anh ấy sẽ hướng dẫn về hệ thống xử lý thẻ tín dụng

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ai nhiều khả năng là ông Bellinger?
A. Một nhiếp ảnh gia chuyên nghiệp
B. Một giám đốc quảng cáo
C. Một nhà báo tự do
D. Một nhà thiết kế web');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6992, 5551, 192, 'According to the first e-mail, what should be removed?', 'Blurry images', 'Some animation', 'A company logo', 'Contact information', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email đầu tiên, Mr. Bellinger đề xuất thay thế các clip động bằng hình ảnh tĩnh vì chúng làm trang web tải chậm: "the homepage is still loading slowly. I believe this is due to the animated clips on that page, which I think should be replaced with static images".

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo email đầu tiên, điều gì nên được loại bỏ?
A. Hình ảnh mờ
B. Một số hoạt ảnh
C. Logo công ty
D. Thông tin liên hệ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6993, 5551, 193, 'What type of business is Kamet?', 'A camping supplies store', 'A tour company', 'An outdoor performance facility', 'A landscaping service', 'A', 'Đáp án đúng là A.
Giải thích:
Theo thông cáo báo chí, Kamet cung cấp "the best tents, backpacks, sleeping bags, and more" (những chiếc lều, ba lô, túi ngủ tốt nhất và nhiều thứ khác). Điều này cho thấy đây là một cửa hàng bán đồ cắm trại.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Kamet là loại hình doanh nghiệp gì?
A. Một cửa hàng đồ cắm trại
B. Một công ty du lịch
C. Một cơ sở biểu diễn ngoài trời
D. Một dịch vụ làm vườn');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6994, 5551, 194, 'What will Ms. Ramsey do on June 9?', 'Open a credit card account', 'Learn about a payment system', 'Select some feature artwork', 'Visit Mr. Bellinger''s office', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email thứ hai, Ms. Ramsey sẽ tham gia hội nghị video để học cách sử dụng hệ thống xử lý thẻ tín dụng: "Joanne Ramsey can attend the video conference you suggested at 2 P.M. on June 9" và "I show someone from your company how to use the credit card processing system".

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Ramsey sẽ làm gì vào ngày 9 tháng 6?
A. Mở một tài khoản thẻ tín dụng
B. Tìm hiểu về hệ thống thanh toán
C. Chọn một số tác phẩm nghệ thuật đặc sắc
D. Đến thăm văn phòng của ông Bellinger');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6995, 5551, 195, 'What is true about Lawrence Holt?', 'He used to work as a lawyer', 'He has recently promoted Ms. Ramsey', 'He has a background in accounting', 'He will write some text for Mr. Bellinger', 'A', 'Đáp án đúng là A.
Giải thích:
Theo email thứ hai của Leo Wright, có một lỗi trong phiên bản thông cáo báo chí trước đó vì "the career backgrounds of Lawrence Holt and Kenny Becerra were accidentally swapped" (thông tin về nghề nghiệp của Lawrence Holt và Kenny Becerra đã vô tình bị hoán đổi). Becerra được mô tả là một cựu luật sư, do đó, đó thực sự là nghề nghiệp trước đây của Holt.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì đúng về Lawrence Holt?
A. Ông ấy từng làm việc như một luật sư
B. Ông ấy gần đây đã thăng chức cho Ms. Ramsey
C. Ông ấy có nền tảng về kế toán
D. Ông ấy sẽ viết một số văn bản cho ông Bellinger');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5552, 245, NULL, NULL, 'The Galindo C7 is an 1150-watt countertop microwave oven with a rotating turntable that can accommodate dishes of up to 13 inches in diameter. Its SmartCook technology can heat up five common foods like popcorn and chicken at pre-programmed power levels until its steam sensor determines that they are done, while the defrost feature makes it easy to thaw frozen foods.
==========
http://www.galindo.com/reviews
Reviewer: Kyla Townsend
Date posted: January 9
My parents gave me their four-year-old C7 microwave when I moved into my first apartment a few months ago. I have been using it a lot, because I eat Hansen ReadyMeals-those plastic bowls of food you put straight into the microwave— a few times a week.
Then, last week, the turntable stopped rotating. The microwave has a five-year warranty, so l called the closest certified Galindo repair service and set up an appointment. The technician said the drive motor will need to be replaced and asked to see my warranty.
He then looked at the name on it and said the agreement is no longer valid because it can''t be transferred between owners. Instead of being free, my repair will cost about $200, which is disappointing. I am posting this review to warn others who might not be aware of this condition of the warranty agreement.
==========
E-Mail message
To: Kyla Townsend <k.townsend@you-mail.com>
From: Grant Osborne < gosborne@galindo.com>
Subject: Galindo CT7
Date: January 10
Dear Ms. Townsend,
I am writing in regard to the review you posted on our Web site. As a member of the Galindo customer service team, I would like to clarify that the policy that warranties are non-transferable was introduced two years ago and does not apply to purchases made before then. I apologize for the difficulty you have experienced with your microwave''s functioning and with the service provided by our certified repair partner.
Customer satisfaction is of utmost importance to Galindo, so I would like to offer my assistance with resolving this issue. Please let me know the name of the company that you interacted with. I will reach out to its management and ensure that your repair is handled properly.
Regards,
Grant Osborne
Customer Service Representative', 'Galindo C7 là một lò vi sóng trên mặt bàn 1150 watt với bàn xoay có thể chứa các đĩa có đường kính lên đến 13 inch. Công nghệ SmartCook của nó có thể làm nóng năm loại thực phẩm phổ biến như bỏng ngô và thịt gà ở các mức năng lượng được lập trình sẵn cho đến khi cảm biến hơi nước xác định rằng chúng đã hoàn thành, trong khi tính năng rã đông giúp dễ dàng rã đông thực phẩm đông lạnh.
============
http://www.galindo.com/reviews
Người đánh giá: Kyla Townsend
Ngày đăng: 9 tháng 1
Bố mẹ tôi đã tặng tôi lò vi sóng C7 bốn năm tuổi của họ khi tôi chuyển đến căn hộ đầu tiên của mình vài tháng trước. Tôi đã sử dụng nó rất nhiều, bởi vì tôi ăn Hansen ReadyMeals - những bát thức ăn bằng nhựa mà bạn cho thẳng vào lò vi sóng - vài lần một tuần.
Sau đó, tuần trước, bàn xoay đã ngừng quay. Lò vi sóng được bảo hành năm năm, vì vậy tôi đã gọi cho dịch vụ sửa chữa Galindo được chứng nhận gần nhất và đặt lịch hẹn. Kỹ thuật viên nói rằng động cơ truyền động sẽ cần được thay thế và yêu cầu xem bảo hành của tôi.
Sau đó, anh ấy nhìn vào tên trên đó và nói rằng thỏa thuận không còn hiệu lực vì nó không thể được chuyển giao giữa các chủ sở hữu. Thay vì miễn phí, việc sửa chữa của tôi sẽ tốn khoảng 200 đô la, điều này thật đáng thất vọng. Tôi đăng bài đánh giá này để cảnh báo những người khác có thể không biết về điều kiện này của thỏa thuận bảo hành.
=========
Tin nhắn E-Mail
Gửi: Kyla Townsend <k.townsend@you-mail.com>
Từ: Grant Osborne < gosborne@galindo.com>
Chủ đề: Galindo CT7
Ngày: 10 tháng 1
Kính gửi cô Townsend,
Tôi đang viết liên quan đến bài đánh giá mà bạn đã đăng trên trang web của chúng tôi. Là một thành viên của nhóm dịch vụ khách hàng của Galindo, tôi muốn làm rõ rằng chính sách bảo hành không thể chuyển nhượng đã được giới thiệu cách đây hai năm và không áp dụng cho các giao dịch mua được thực hiện trước đó. Tôi xin lỗi vì những khó khăn mà bạn đã gặp phải với hoạt động của lò vi sóng và với dịch vụ được cung cấp bởi đối tác sửa chữa được chứng nhận của chúng tôi.
Sự hài lòng của khách hàng là điều quan trọng nhất đối với Galindo, vì vậy tôi muốn hỗ trợ giải quyết vấn đề này. Vui lòng cho tôi biết tên của công ty mà bạn đã tương tác. Tôi sẽ liên hệ với ban quản lý và đảm bảo rằng việc sửa chữa của bạn được xử lý đúng cách.
Xin trọng,
Grant Osborne
Đại diện dịch vụ khách hàng');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6996, 5552, 196, 'According to the product description, what is true about the Galindo CT7?', 'It features an interior light', 'It has the ability to sense steam', 'It is meant to be suspended over a cooktop', 'It comes in multiple color finishes', 'B', 'Đáp án đúng là B.
Giải thích:
Theo mô tả sản phẩm, Galindo C7 có công nghệ SmartCook với "steam sensor" (cảm biến hơi nước) để xác định khi nào thức ăn đã chín.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo mô tả sản phẩm, điều gì đúng về Galindo C7?
A. Nó có đèn bên trong
B. Nó có khả năng cảm biến hơi nước
C. Nó được thiết kế để treo trên bếp
D. Nó có nhiều màu sắc hoàn thiện');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6997, 5552, 197, 'What does Ms. Townsend indicate in her review about the C7 in her apartment?', 'She received it as a gift', 'It belongs to her landlord', 'She has owned it for four years', 'She bought it from a used goods store', 'A', 'Đáp án đúng là A.
Giải thích:
Theo đánh giá của Ms. Townsend: "My parents gave me their four-year-old C7 microwave" (Bố mẹ tôi đã cho tôi lò vi sóng C7 4 năm tuổi của họ). Điều này cho thấy cô ấy đã nhận nó như một món quà từ bố mẹ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Townsend cho biết điều gì về C7 trong căn hộ của cô ấy?
A. Cô ấy nhận nó như một món quà
B. Nó thuộc về chủ nhà của cô ấy
C. Cô ấy đã sở hữu nó được bốn năm
D. Cô ấy đã mua nó từ một cửa hàng đồ cũ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6998, 5552, 198, 'What is suggested about Hansen ReadyMeals?', 'They are sold frozen', 'They include a chicken dish', 'They should be heated for five minutes', 'They are no larger than 13 inches across', 'D', 'Đáp án đúng là D.
Giải thích:
Mô tả cho biết lò vi sóng có thể chứa đĩa có đường kính lên đến 13 inch. Vì Ms. Townsend có thể hâm nóng Hansen ReadyMeals trong lò vi sóng này, điều đó ngụ ý rằng các bát đựng thức ăn Hansen ReadyMeals không lớn hơn 13 inch.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về Hansen ReadyMeals?
A. Chúng được bán đông lạnh
B. Chúng bao gồm món gà
C. Chúng nên được hâm nóng trong năm phút
D. Chúng không lớn hơn 13 inch');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (6999, 5552, 199, 'What incorrect information did Ms. Townsend receive from a technician?', 'That the price of a certain replacement part is $200', 'That Galindo introduced a new company policy within the past year', 'That a malfunctioning drive motor is the most likely reason for her problem', 'That the warranty on her microwave had been invalidated', 'D', 'Đáp án đúng là D.
Giải thích:
Kỹ thuật viên đã sai khi nói bảo hành không còn hiệu lực vì không thể chuyển nhượng giữa các chủ sở hữu. Theo email của Mr. Osborne, chính sách bảo hành không thể chuyển nhượng chỉ được áp dụng cho các sản phẩm mua trong hai năm gần đây, không áp dụng cho các sản phẩm mua trước đó như lò vi sóng của Ms. Townsend.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Thông tin không chính xác nào Ms. Townsend nhận được từ kỹ thuật viên?
A. Giá của một bộ phận thay thế nhất định là 200 đô la
B. Galindo đã giới thiệu chính sách công ty mới trong năm qua
C. Động cơ truyền động bị hỏng là nguyên nhân có thể nhất cho vấn đề của cô ấy
D. Bảo hành cho lò vi sóng của cô ấy đã hết hiệu lực');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7000, 5552, 200, 'What is one piece of information Mr. Osborne asks Ms. Townsend for?', 'The name of a repair business', 'The model number of her product', 'The wording of a part of her warranty', 'The address of an appliance store', 'A', 'Đáp án đúng là A.
Giải thích:
Trong email, Mr. Osborne yêu cầu: "Please let me know the name of the company that you interacted with" (Vui lòng cho tôi biết tên công ty mà bạn đã tương tác). Ông ấy muốn biết tên của công ty sửa chữa để có thể liên hệ với ban quản lý của họ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Một thông tin mà ông Osborne yêu cầu Ms. Townsend cung cấp là gì?
A. Tên của một doanh nghiệp sửa chữa
B. Số model của sản phẩm của cô ấy
C. Lời văn của một phần bảo hành của cô ấy
D. Địa chỉ của một cửa hàng thiết bị');;

