INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7004, 5556, 4, 'Look at the picture marked number four in your test book.', 'Some of the shoes are lined up on the floor.', 'Clothing has been folded and stacked.', 'A handbag has been left on top of a basket.', 'Hats are being stored on some shelves.', 'A', 'A Một số đôi giày được xếp thành hàng trên sàn nhà.
