INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7005, 5557, 5, 'Look at the picture marked number five in your test book.', 'A moving van has been driven into a garage.', 'Boxes have been piled on a cart.', 'A sofa is being carried across a driveway.', 'Workers are unloading some packing materials.', 'C', 'A Một chiếc xe tải chuyển nhà đã được lái vào một nhà để xe.
