-- Data for 2025 Test6 Part 2
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5559, 247, '2025/test6/audio/test6_question_7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7007, 5559, 7, 'How did you like the book?', 'Around three hundred pages.', 'A friend recommended it.', 'The ending was surprising!', NULL, 'C', 'Câu hỏi: Bạn thấy cuốn sách như thế nào?"
A: "Khoảng ba trăm trang."
B: "Một người bạn đã giới thiệu nó."
C: "Cái kết thật bất ngờ!"
Giải thích: Đáp án C đúng vì câu hỏi yêu cầu đánh giá về cuốn sách, và "Cái kết thật bất ngờ" là một nhận xét thú vị về nội dung của sách."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5560, 247, '2025/test6/audio/test6_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7008, 5560, 8, 'Where is the security office?', 'For a visitor''s badge.', 'At the back of the lobby.', 'The security report is done.', NULL, 'B', 'Câu hỏi: Văn phòng bảo vệ ở đâu?"
A: "Để lấy thẻ khách."
B: "Ở phía sau sảnh."
C: "Báo cáo bảo mật đã xong."
Giải thích: Đáp án B đúng vì câu hỏi yêu cầu vị trí văn phòng bảo vệ, và "ở phía sau sảnh" là câu trả lời đúng cho vị trí này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5561, 247, '2025/test6/audio/test6_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7009, 5561, 9, 'What did you think of the orientation video?', 'On my first day at the company.', 'You can start recording at any time.', 'It had a lot of helpful information.', NULL, 'C', 'Câu hỏi: Bạn nghĩ sao về video hướng dẫn?"
A: "Vào ngày đầu tiên của tôi tại công ty."
B: "Bạn có thể bắt đầu ghi hình bất cứ lúc nào."
C: "Nó có rất nhiều thông tin hữu ích."
Giải thích: Đáp án C đúng vì câu hỏi về cảm nhận về video hướng dẫn, và đáp án C phản ánh sự hữu ích của thông tin trong video."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5562, 247, '2025/test6/audio/test6_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7010, 5562, 10, 'Should we ask Donna to give the product demonstration?', 'At the exposition in Seoul.', 'They only accept cash donations.', 'Yes, she''s great at public speaking.', NULL, 'C', 'Câu hỏi: Chúng ta có nên nhờ Donna thuyết trình về sản phẩm không?"
A: "Tại triển lãm ở Seoul."
B: "Họ chỉ nhận đóng góp bằng tiền mặt."
C: "Vâng, cô ấy rất giỏi thuyết trình công khai."
Giải thích: Đáp án C đúng vì câu hỏi về việc nhờ Donna thuyết trình, và đáp án C chỉ ra rằng Donna có khả năng thuyết trình tốt."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5563, 247, '2025/test6/audio/test6_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7011, 5563, 11, 'What is that interesting building across the river?', 'A concert hall.', 'Take Calhoun Bridge, please.', 'From the top floor.', NULL, 'A', 'Câu hỏi: Tòa nhà thú vị đó bên kia sông là gì?"
A: "Một hội trường hòa nhạc."
B: "Đi qua cầu Calhoun, làm ơn."
C: "Từ tầng trên cùng."
Giải thích: Đáp án A đúng vì câu hỏi yêu cầu xác định tòa nhà thú vị bên kia sông, và "một hội trường hòa nhạc" là một đặc điểm dễ nhận diện."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5564, 247, '2025/test6/audio/test6_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7012, 5564, 12, 'Will the clinic stay open while the road is being repaired?', 'Yes, we''ll be seeing patients.', 'It''s a load of disposable gloves.', 'Because of damage from heavy trucks.', NULL, 'A', 'Câu hỏi: Phòng khám có mở cửa trong khi con đường đang được sửa chữa không?"
A: "Vâng, chúng tôi vẫn sẽ tiếp nhận bệnh nhân."
B: "Đó là một đống găng tay dùng một lần."
C: "Vì thiệt hại từ những chiếc xe tải nặng."
Giải thích: Đáp án A đúng vì câu hỏi về việc phòng khám có mở cửa không trong quá trình sửa chữa, và đáp án A nói rõ phòng khám vẫn hoạt động bình thường."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5565, 247, '2025/test6/audio/test6_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7013, 5565, 13, 'When will the inspection take place?', 'Sometime this week.', 'The corner by the dishwashers.', 'No, I brought my own.', NULL, 'A', 'Câu hỏi: Khi nào cuộc kiểm tra sẽ diễn ra?"
A: "Vào một lúc nào đó trong tuần này."
B: "Ở góc gần máy rửa bát."
C: "Không, tôi đã mang theo của riêng tôi."
Giải thích: Đáp án A đúng vì câu hỏi yêu cầu thời gian diễn ra kiểm tra, và đáp án A đưa ra thời điểm không xác định trong tuần này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5566, 247, '2025/test6/audio/test6_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7014, 5566, 14, 'It''s going to start raining soon.', 'I''ll bring the sidewalk display inside.', 'Yes, that was a good start.', 'With a professional trainer.', NULL, 'A', 'Câu hỏi: Trời sắp mưa rồi."
A: "Tôi sẽ mang bảng trưng bày ra ngoài vào trong."
B: "Vâng, đó là một khởi đầu tốt."
C: "Với một huấn luyện viên chuyên nghiệp."
Giải thích: Đáp án A đúng vì câu hỏi về mưa sắp đến, và đáp án A đưa ra hành động thực tế là mang bảng trưng bày vào trong để tránh mưa."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5567, 247, '2025/test6/audio/test6_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7015, 5567, 15, 'Why did the candidate turn down our offer?', 'Yes, unfortunately.', 'He had already taken another job.', 'Do you want me to turn it up again?', NULL, 'B', 'Câu hỏi: Tại sao ứng viên từ chối lời đề nghị của chúng ta?"
A: "Vâng, thật tiếc."
B: "Anh ấy đã nhận một công việc khác."
C: "Bạn có muốn tôi bật lại không?"
Giải thích: Đáp án B đúng vì câu hỏi về lý do ứng viên từ chối, và đáp án B giải thích rõ ràng rằng ứng viên đã nhận công việc khác."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5568, 247, '2025/test6/audio/test6_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7016, 5568, 16, 'Which project is our crew working on next?', 'The concrete was already safe to walk on.', 'That''s not what I''ve heard.', 'The Miller family''s kitchen renovation.', NULL, 'C', 'Câu hỏi: Dự án nào là dự án tiếp theo mà nhóm của chúng ta làm?"
A: "Bê tông đã an toàn để đi lại."
B: "Đó không phải là điều tôi nghe được."
C: "Cải tạo nhà bếp của gia đình Miller."
Giải thích: Đáp án C đúng vì câu hỏi yêu cầu dự án tiếp theo, và đáp án C nói rõ rằng dự án tiếp theo là cải tạo nhà bếp của gia đình Miller."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5569, 247, '2025/test6/audio/test6_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7017, 5569, 17, 'Aren''t you supposed to be leaving for your business trip?', 'I already left it with the front desk.', 'Actually, it''s a very successful business.', 'My flight isn''t until seven P.M.', NULL, 'C', 'Câu hỏi: Chẳng phải bạn phải đi công tác rồi sao?"
A: "Tôi đã để nó lại ở quầy tiếp tân."
B: "Thực ra, đó là một doanh nghiệp rất thành công."
C: "Chuyến bay của tôi không phải đến bảy giờ tối."
Giải thích: Đáp án C đúng vì câu hỏi về việc đi công tác, và đáp án C giải thích rằng chuyến bay chưa cất cánh cho đến tối."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5570, 247, '2025/test6/audio/test6_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7018, 5570, 18, 'Why don''t we redesign our sandals this year?', 'This style is still selling pretty well.', 'She goes to the beach every summer.', 'A famous shoe designer.', NULL, 'A', 'Câu hỏi: Tại sao chúng ta không thiết kế lại đôi sandal của mình năm nay?"
A: "Phong cách này vẫn bán khá tốt."
B: "Cô ấy đi biển mỗi mùa hè."
C: "Một nhà thiết kế giày nổi tiếng."
Giải thích: Đáp án A đúng vì câu hỏi về việc thiết kế lại đôi sandal, và đáp án A nói rằng phong cách hiện tại vẫn bán tốt, nên không cần thay đổi."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5571, 247, '2025/test6/audio/test6_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7019, 5571, 19, 'How many buses will we need to take everyone to the retreat site?', 'No, you can''t park here on weekdays.', 'Over thirty miles away.', 'We have a hundred and twenty people on staff.', NULL, 'C', 'Câu hỏi: Chúng ta cần bao nhiêu xe buýt để đưa mọi người đến địa điểm hội thảo?
A: "Không, bạn không thể đỗ xe ở đây vào các ngày trong tuần."
B: "Hơn ba mươi dặm."
C: "Chúng ta có một trăm hai mươi người trong đội ngũ."
Giải thích: Đáp án C đúng vì câu hỏi hỏi về số lượng xe buýt cần thiết, và đáp án C cho biết số lượng người tham gia, từ đó suy ra số xe buýt cần thiết."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5572, 247, '2025/test6/audio/test6_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7020, 5572, 20, 'Are we giving our clients wall calendars or desk calendars this year?', 'I thought you ordered the gifts.', 'To show our appreciation for them.', 'No, not according to my calendar.', NULL, 'A', 'Câu hỏi: Chúng ta sẽ tặng cho khách hàng lịch treo tường hay lịch để bàn năm nay?"
A: "Tôi nghĩ bạn đã đặt quà."
B: "Để bày tỏ lòng biết ơn của chúng ta đối với họ."
C: "Không, không theo lịch của tôi."
Giải thích: Đáp án A đúng vì câu hỏi về việc chọn loại lịch, và đáp án A phản ánh sự nhầm lẫn về việc đặt quà."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5573, 247, '2025/test6/audio/test6_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7021, 5573, 21, 'Wasn''t that food festival postponed again?', 'It''s been pushed back to June.', 'Some of it was quite spicy.', 'I put one on the bulletin board.', NULL, 'A', 'Câu hỏi: Lễ hội ẩm thực đó lại bị hoãn sao?"
A: "Nó đã bị hoãn đến tháng Sáu."
B: "Một số món ăn khá cay."
C: "Tôi đã dán một cái lên bảng thông báo."
Giải thích: Đáp án A đúng vì câu hỏi về việc hoãn lễ hội ẩm thực, và đáp án A cho biết lễ hội đã bị dời lại đến tháng Sáu."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5574, 247, '2025/test6/audio/test6_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7022, 5574, 22, 'The office relocation is taking longer than we hoped.', 'We do have a lot of electronics to set up.', 'Our official logo.', 'I could cut a few words here.', NULL, 'A', 'Câu hỏi: Việc chuyển văn phòng đang mất nhiều thời gian hơn chúng ta mong đợi."
A: "Chúng ta thực sự có rất nhiều thiết bị điện tử phải lắp đặt."
B: "Logo chính thức của chúng ta."
C: "Tôi có thể cắt bớt một vài từ ở đây."
Giải thích: Đáp án A đúng vì câu hỏi về việc chuyển văn phòng chậm hơn dự tính, và đáp án A giải thích lý do là vì cần phải lắp đặt nhiều thiết bị điện tử."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5575, 247, '2025/test6/audio/test6_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7023, 5575, 23, 'Why did Mayor Shin call a press conference?', 'Just a few hours ago.', 'It''s been called that for years.', 'She''s announcing a new policy.', NULL, 'C', 'Câu hỏi: Tại sao thị trưởng Shin lại tổ chức một cuộc họp báo?"
A: "Vừa mới vài giờ trước."
B: "Nó đã được gọi như vậy trong nhiều năm."
C: "Cô ấy đang công bố một chính sách mới."
Giải thích: Đáp án C đúng vì câu hỏi về lý do họp báo, và đáp án C cho biết lý do là công bố chính sách mới."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5576, 247, '2025/test6/audio/test6_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7024, 5576, 24, 'The projector in that conference room is still out of order, isn''t it?', 'They should be in alphabetical order.', 'Just print out your presentation slides.', 'On a rolling cart outside the door.', NULL, 'B', 'Câu hỏi: Máy chiếu trong phòng hội thảo đó vẫn hỏng phải không?"
A: "Chúng phải được sắp xếp theo thứ tự bảng chữ cái."
B: "Chỉ cần in ra các trang trình bày của bạn."
C: "Trên một chiếc xe đẩy ngoài cửa."
Giải thích: Đáp án B đúng vì câu hỏi về máy chiếu hỏng, và đáp án B cho biết giải pháp tạm thời là in tài liệu ra để trình bày."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5577, 247, '2025/test6/audio/test6_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7025, 5577, 25, 'Who knows how to report a maintenance issue?', 'Some routine elevator maintenance.', 'Sheldon has done it before.', 'Yes, we have copies of every issue.', NULL, 'B', 'Câu hỏi: Ai biết cách báo cáo một vấn đề bảo trì?"
A: "Một số bảo trì thang máy định kỳ."
B: "Sheldon đã làm điều đó trước đây."
C: "Vâng, chúng tôi có bản sao của mọi vấn đề."
Giải thích: Đáp án B đúng vì câu hỏi hỏi về người biết cách báo cáo, và Sheldon đã từng làm điều đó trước đây."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5578, 247, '2025/test6/audio/test6_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7026, 5578, 26, 'Why is the exhibit on European painting closed?', 'There''s an art supply store on Martin Street.', 'Didn''t you read the notice at the museum entrance?', 'Yes, the very next room.', NULL, 'B', 'Câu hỏi: Tại sao triển lãm về hội họa châu Âu lại đóng cửa?"
A: "Có một cửa hàng cung cấp đồ nghệ thuật trên phố Martin."
B: "Bạn không đọc thông báo ở cửa bảo tàng sao?"
C: "Vâng, phòng bên cạnh."
Giải thích: Đáp án B đúng vì câu hỏi về lý do triển lãm đóng cửa, và đáp án B chỉ ra rằng thông báo tại cửa bảo tàng đã giải thích lý do."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5579, 247, '2025/test6/audio/test6_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7027, 5579, 27, 'When do you want to meet to sign the contract?', 'Yes, she sent out the agenda.', 'I believe that''s correct.', 'I''d like to see more apartments first.', NULL, 'C', 'Câu hỏi: Khi nào bạn muốn gặp để ký hợp đồng?"
A: "Vâng, cô ấy đã gửi lịch trình."
B: "Tôi tin là đúng."
C: "Tôi muốn xem thêm một số căn hộ trước."
Giải thích: Đáp án C đúng vì câu hỏi về thời gian ký hợp đồng, và đáp án C cho thấy người hỏi muốn xem thêm các căn hộ trước khi ký hợp đồng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5580, 247, '2025/test6/audio/test6_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7028, 5580, 28, 'What should I do with these old bank statements?', 'No, they really shouldn''t.', 'Put them through the shredder.', 'Once a year, in January.', NULL, 'B', 'Câu hỏi: Tôi nên làm gì với các bản sao sao kê ngân hàng cũ này?"
A: "Không, chúng thực sự không nên."
B: "Đưa chúng vào máy hủy tài liệu."
C: "Một lần mỗi năm, vào tháng Giêng."
Giải thích: Đáp án B đúng vì câu hỏi về việc xử lý các bản sao kê ngân hàng cũ, và đáp án B chỉ ra rằng cần phải hủy chúng để bảo vệ thông tin."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5581, 247, '2025/test6/audio/test6_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7029, 5581, 29, 'I''d be happy to pick up the executives at the airport.', 'We hired a car service.', 'Yes, a round-trip ticket.', 'Some shipments from overseas.', NULL, 'A', 'Câu hỏi: Tôi rất vui được đón các giám đốc điều hành ở sân bay."
A: "Chúng tôi đã thuê dịch vụ xe."
B: "Vâng, vé khứ hồi."
C: "Một số chuyến hàng từ nước ngoài."
Giải thích: Đáp án A đúng vì câu hỏi về việc đón giám đốc điều hành, và đáp án A cho biết công ty đã thuê dịch vụ xe để đón họ."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5582, 247, '2025/test6/audio/test6_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7030, 5582, 30, 'This credit card''s annual fee is quite high.', 'A monthly list of charges.', 'It offers great user rewards.', 'Let me get you a stepladder.', NULL, 'B', 'Câu hỏi: Phí thường niên của thẻ tín dụng này khá cao."
A: "Danh sách chi phí hàng tháng."
B: "Nó cung cấp nhiều phần thưởng hấp dẫn cho người dùng."
C: "Để tôi mang cho bạn một cái thang."
Giải thích: Đáp án B đúng vì câu hỏi về phí thẻ tín dụng, và đáp án B nói về phần thưởng hấp dẫn mà thẻ tín dụng mang lại."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5583, 247, '2025/test6/audio/test6_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7031, 5583, 31, 'Selma, could you order more file folders?', 'Yes, he filed the permit yesterday.', 'Tatsu found some extras in the cabinet.', 'One of our major shareholders.', NULL, 'B', 'Câu hỏi: Selma, bạn có thể đặt thêm kẹp tài liệu không?"
A: "Vâng, anh ấy đã nộp giấy phép hôm qua."
B: "Tatsu tìm thấy một số cái thừa trong tủ."
C: "Một trong những cổ đông lớn của chúng ta."
Giải thích: Đáp án B đúng vì câu hỏi về việc đặt thêm kẹp tài liệu, và đáp án B cho biết Tatsu đã tìm thấy một số kẹp tài liệu thừa trong tủ."');;

-- Data for 2025 Test6 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5584, 248, '2025/test6/audio/test6_question_32_34.mp3', NULL, 'M-Au: Hi, Kira, it''s Nate in Sales. I''m calling because I''m having a problem with the Conversa software program. I can get instant messages from other people, but my replies aren''t going through.
w-Br: Oh, I see. Have you tried updating the program? The latest version was released just this week.
M-Au: Yes, I just did that, but it didn''t help. I also tried restarting my computer.
w-Br: OK, then I''ll need to come over and take a look at your computer myself. Is now a good time?
M-Au: Now would be great. Thank you.', 'Nam: Chào Kira, Nate ở bộ phận Bán hàng đây. Tôi gọi vì đang gặp vấn đề với phần mềm Conversa. Tôi có thể nhận tin nhắn tức thời từ người khác, nhưng phản hồi của tôi không gửi đi được.
Nữ: Ồ, tôi hiểu rồi. Anh đã thử cập nhật chương trình chưa? Phiên bản mới nhất vừa được phát hành tuần này.
Nam: Vâng, tôi vừa làm điều đó, nhưng nó không giúp ích gì. Tôi cũng đã thử khởi động lại máy tính.
Nữ: OK, vậy tôi sẽ cần đến và xem máy tính của anh trực tiếp. Bây giờ có được không?
Nam: Bây giờ thì tuyệt. Cảm ơn chị.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7032, 5584, 32, 'Why is the man calling the woman?', 'To receive help with a technical issue', 'To ask her to make an announcement', 'To explain why he missed a meeting', 'To confirm that he read a message', 'A', 'Question: "Why is the man calling the woman?" (Tại sao người đàn ông gọi cho người phụ nữ?)
A: To receive help with a technical issue (Để nhận trợ giúp về vấn đề kỹ thuật)
B: To ask her to make an announcement (Để yêu cầu cô ấy thông báo)
C: To explain why he missed a meeting (Để giải thích vì sao anh ấy lỡ cuộc họp)
D: To confirm that he read a message (Để xác nhận anh ấy đã đọc tin nhắn)

Người đàn ông gọi để nhận trợ giúp về vấn đề kỹ thuật với phần mềm Conversa:
1. Anh ấy không thể gửi tin nhắn phản hồi
2. Đã thử cập nhật chương trình và khởi động lại máy tính nhưng không giải quyết được
3. Cần người phụ nữ đến xem trực tiếp máy tính');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5585, 248, '2025/test6/audio/test6_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7033, 5585, 33, 'What does the woman inform the man about?', 'A sales catalog has not been updated', 'A computer system is currently down', 'A request must be approved by a supervisor', 'A new version of some software is available', 'D', 'Question: "What does the woman inform the man about?" (Người phụ nữ thông báo cho người đàn ông về điều gì?)
A: A sales catalog has not been updated (Một danh mục bán hàng chưa được cập nhật)
B: A computer system is currently down (Một hệ thống máy tính hiện đang gặp sự cố)
C: A request must be approved by a supervisor (Một yêu cầu phải được giám sát viên phê duyệt)
D: A new version of some software is available (Một phiên bản mới của phần mềm đã có sẵn)

Người phụ nữ thông báo về việc phiên bản mới của phần mềm đã được phát hành: "The latest version was released just this week" (Phiên bản mới nhất vừa được phát hành tuần này).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5586, 248, '2025/test6/audio/test6_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7034, 5586, 34, 'What does the woman say she will have to do?', 'Wait until tomorrow to start a task', 'Look through a product manual', 'Visit the man''s workstation', 'Dispose of some equipment', 'C', 'Question: "What does the woman say she will have to do?" (Người phụ nữ nói cô ấy sẽ phải làm gì?)
A: Wait until tomorrow to start a task (Đợi đến ngày mai để bắt đầu một nhiệm vụ)
B: Look through a product manual (Xem qua sách hướng dẫn sản phẩm)
C: Visit the man''s workstation (Đến nơi làm việc của người đàn ông)
D: Dispose of some equipment (Vứt bỏ một số thiết bị)

Người phụ nữ nói rằng cô ấy sẽ phải đến xem máy tính của người đàn ông: "I''ll need to come over and take a look at your computer myself" (tôi sẽ cần đến và xem máy tính của anh trực tiếp).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5587, 248, '2025/test6/audio/test6_question_35_37.mp3', NULL, 'W-Am: Hi! Are you opening soon? I was just hoping to get a new set of brakes for my bike.
M-Cn: Yes, we''ve been open since nine! Let me know if you need help finding the right pair.
W-Am: Oh! Then I should let you know- the sign on the front doors says you''re closed.
M-cn: Ah, sorry about that. We often forget to turn that sign around when we come in in the mornings. I''ll go and fix that now.', 'Nữ: Chào! Các anh sắp mở cửa phải không? Tôi chỉ hy vọng mua được một bộ phanh mới cho xe đạp của tôi.
Nam: Vâng, chúng tôi đã mở cửa từ 9 giờ rồi! Hãy cho tôi biết nếu chị cần giúp tìm bộ phanh phù hợp.
Nữ: Ồ! Vậy tôi nên cho anh biết - biển hiệu ở cửa trước ghi là các anh đang đóng cửa.
Nam: À, xin lỗi về điều đó. Chúng tôi thường quên lật biển hiệu khi vào buổi sáng. Tôi sẽ đi sửa ngay bây giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7035, 5587, 35, 'What does the woman want to do?', 'Rent some bicycles', 'Purchase some parts', 'Check on a repair', 'Join a riding club', 'B', 'Question: "What does the woman want to do?" (Người phụ nữ muốn làm gì?)
A: Rent some bicycles (Thuê một số xe đạp)
B: Purchase some parts (Mua một số phụ tùng)
C: Check on a repair (Kiểm tra việc sửa chữa)
D: Join a riding club (Tham gia câu lạc bộ đạp xe)

Người phụ nữ muốn mua bộ phanh mới cho xe đạp của cô ấy: "I was just hoping to get a new set of brakes for my bike" (Tôi chỉ hy vọng mua được một bộ phanh mới cho xe đạp của tôi).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5588, 248, '2025/test6/audio/test6_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7036, 5588, 36, 'Why does the man apologize?', 'A message was not sent', 'A shelf was not restocked', 'The business is closed', 'A sign is wrong', 'D', 'Question: "Why does the man apologize?" (Tại sao người đàn ông xin lỗi?)
A: A message was not sent (Một tin nhắn không được gửi)
B: A shelf was not restocked (Một kệ không được bổ sung hàng)
C: The business is closed (Doanh nghiệp đang đóng cửa)
D: A sign is wrong (Một biển hiệu sai)

Người đàn ông xin lỗi vì biển hiệu ở cửa trước vẫn ghi là đóng cửa, mặc dù cửa hàng đã mở cửa: "We often forget to turn that sign around when we come in in the mornings" (Chúng tôi thường quên lật biển hiệu khi vào buổi sáng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5589, 248, '2025/test6/audio/test6_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7037, 5589, 37, 'What will the man most likely do next?', 'Go to the front entrance', 'Search a stockroom', 'Consult with a mechanic', 'Wait at a checkout counter', 'A', 'Question: "What will the man most likely do next?" (Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?)
A: Go to the front entrance (Đi đến lối vào phía trước)
B: Search a stockroom (Tìm kiếm trong kho)
C: Consult with a mechanic (Tham khảo ý kiến thợ máy)
D: Wait at a checkout counter (Đợi tại quầy thanh toán)

Người đàn ông nói sẽ đi sửa biển hiệu ngay: "I''ll go and fix that now" (Tôi sẽ đi sửa ngay bây giờ), điều này có nghĩa là anh ấy sẽ đi ra lối vào phía trước để lật biển hiệu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5590, 248, '2025/test6/audio/test6_question_38_40.mp3', NULL, 'W-Am: Worthington Print Shop. This is Darlene speaking.
M-Au: Hi, this is Pasquale Cafaro. I ordered custom T-shirts from your shop for the soccer tournament I''m putting together this month.
W-Am: OK, uh... our records show that all four boxes arrived yesterday. Is there a problem?
M-Au: Yes-shouldn''t there be five boxes? I didn''t get the size extra-small shirts that I ordered.
W-Am: Let me connect you with Sheila, the employee who filled your order. Please hold.
W-Br: Hi, Mr. Cafaro. Darlene told me about your issue. We often group smaller-quantity items together to cut down on the number of shipments. So try checking the bottom of the box of small-size T-shirts.', 'Nữ 1: Cửa hàng In ấn Worthington. Darlene xin nghe.
Nam: Chào, tôi là Pasquale Cafaro. Tôi đã đặt áo thun tùy chỉnh từ cửa hàng của các bạn cho giải đấu bóng đá mà tôi đang tổ chức tháng này.
Nữ 1: OK, ừm... hồ sơ của chúng tôi cho thấy tất cả bốn hộp đã đến hôm qua. Có vấn đề gì không?
Nam: Vâng - chẳng phải phải có năm hộp sao? Tôi không nhận được những chiếc áo cỡ rất nhỏ mà tôi đã đặt.
Nữ 1: Để tôi kết nối anh với Sheila, nhân viên đã xử lý đơn hàng của anh. Vui lòng đợi.
Nữ 2: Chào anh Cafaro. Darlene đã kể với tôi về vấn đề của anh. Chúng tôi thường gộp các mặt hàng có số lượng ít lại với nhau để giảm số lượng lô hàng. Vậy hãy thử kiểm tra đáy hộp của áo cỡ nhỏ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7038, 5590, 38, 'What is the man doing this month?', 'Taking a group vacation', 'Celebrating an anniversary', 'Putting up holiday decorations', 'Organizing an athletic event', 'D', 'Question: "What is the man doing this month?" (Người đàn ông đang làm gì tháng này?)
A: Taking a group vacation (Đi nghỉ theo nhóm)
B: Celebrating an anniversary (Tổ chức kỷ niệm)
C: Putting up holiday decorations (Trang trí ngày lễ)
D: Organizing an athletic event (Tổ chức sự kiện thể thao)

Người đàn ông đang tổ chức một giải đấu bóng đá: "I ordered custom T-shirts from your shop for the soccer tournament I''m putting together this month" (Tôi đã đặt áo thun tùy chỉnh từ cửa hàng của các bạn cho giải đấu bóng đá mà tôi đang tổ chức tháng này).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5591, 248, '2025/test6/audio/test6_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7039, 5591, 39, 'What concern does the man express?', 'His order arrived later than scheduled', 'A product is the wrong size', 'Some purchased items are missing', 'Some boxes broke open', 'C', 'Question: "What concern does the man express?" (Người đàn ông bày tỏ quan ngại gì?)
A: His order arrived later than scheduled (Đơn hàng của anh ấy đến trễ hơn dự kiến)
B: A product is the wrong size (Một sản phẩm sai kích cỡ)
C: Some purchased items are missing (Một số món hàng đã mua bị thiếu)
D: Some boxes broke open (Một số hộp bị vỡ)

Người đàn ông lo lắng về việc thiếu những chiếc áo cỡ rất nhỏ mà anh ấy đã đặt: "I didn''t get the size extra-small shirts that I ordered" (Tôi không nhận được những chiếc áo cỡ rất nhỏ mà tôi đã đặt).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5592, 248, '2025/test6/audio/test6_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7040, 5592, 40, 'What does Sheila explain to the man?', 'How to repair some damage', 'How shipments are packed', 'How to request a refund', 'How long a process took', 'B', 'Question: "What does Sheila explain to the man?" (Sheila giải thích gì cho người đàn ông?)
A: How to repair some damage (Cách sửa chữa hư hỏng)
B: How shipments are packed (Cách đóng gói hàng)
C: How to request a refund (Cách yêu cầu hoàn tiền)
D: How long a process took (Một quy trình mất bao lâu)

Sheila giải thích về cách họ đóng gói hàng: "We often group smaller-quantity items together to cut down on the number of shipments" (Chúng tôi thường gộp các mặt hàng có số lượng ít lại với nhau để giảm số lượng lô hàng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5593, 248, '2025/test6/audio/test6_question_41_43.mp3', NULL, 'M-Cn: Bernice, your team''s in charge of monitoring customer satisfaction with our products. How''s the response to the new packaging for our socks?
w-Br: Were seeing mostly positive mentions of it in online reviews. People appreciate that we got rid of the plastic fasteners in order to reduce plastic pollution. However, a few have complained that it''s harder to remove the thread loops that now hold the socks together.
M-n: OK. I''d like you to post replies to those reviews. Express sympathy for the customers'' frustration and then direct them to the page on our Web site that explains why we changed the packaging.', 'Nam: Bernice, đội của cô phụ trách theo dõi sự hài lòng của khách hàng với sản phẩm của chúng ta. Phản hồi về bao bì mới cho tất của chúng ta thế nào?
Nữ: Chúng tôi thấy phần lớn các đánh giá trực tuyến đều tích cực. Mọi người đánh giá cao việc chúng ta loại bỏ móc nhựa để giảm ô nhiễm nhựa. Tuy nhiên, một số người phàn nàn rằng giờ khó tháo vòng chỉ đang giữ tất lại với nhau hơn.
Nam: OK. Tôi muốn cô đăng phản hồi cho những đánh giá đó. Bày tỏ sự thông cảm với sự thất vọng của khách hàng và sau đó hướng họ đến trang web của chúng ta giải thích lý do tại sao chúng ta thay đổi bao bì.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7041, 5593, 41, 'What industry do the speakers work in?', 'Electronics', 'Cosmetics', 'Clothing', 'Pharmaceutical', 'C', 'Question: "What industry do the speakers work in?" (Những người nói chuyện làm việc trong ngành nào?)
A: Electronics (Điện tử)
B: Cosmetics (Mỹ phẩm)
C: Clothing (Quần áo)
D: Pharmaceutical (Dược phẩm)

Họ làm việc trong ngành quần áo vì:
1. Họ đang thảo luận về bao bì mới cho tất
2. Đề cập đến việc thay đổi từ móc nhựa sang dây để giữ tất
3. Đây là sản phẩm trong ngành may mặc');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5594, 248, '2025/test6/audio/test6_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7042, 5594, 42, 'Why did the company change its product packaging?', 'To make the packaging easier to remove', 'To prevent damage to some goods', 'To reduce production expenses', 'To become more environmentally friendly', 'D', 'Question: "Why did the company change its product packaging?" (Tại sao công ty thay đổi bao bì sản phẩm?)
A: To make the packaging easier to remove (Để làm cho bao bì dễ tháo hơn)
B: To prevent damage to some goods (Để ngăn ngừa hư hại cho một số hàng hóa)
C: To reduce production expenses (Để giảm chi phí sản xuất)
D: To become more environmentally friendly (Để trở nên thân thiện với môi trường hơn)

Công ty thay đổi bao bì để giảm ô nhiễm môi trường: "we got rid of the plastic fasteners in order to reduce plastic pollution" (chúng ta loại bỏ móc nhựa để giảm ô nhiễm nhựa).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5595, 248, '2025/test6/audio/test6_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7043, 5595, 43, 'What will the woman most likely do in her replies to some reviews?', 'Offer a one-time discount', 'Post a link to a Web page', 'Direct customers to a help line', 'Express gratitude for feedback', 'B', 'Question: "What will the woman most likely do in her replies to some reviews?" (Người phụ nữ nhiều khả năng sẽ làm gì trong phản hồi của mình cho một số đánh giá?)
A: Offer a one-time discount (Đưa ra giảm giá một lần)
B: Post a link to a Web page (Đăng một liên kết đến trang web)
C: Direct customers to a help line (Hướng khách hàng đến đường dây trợ giúp)
D: Express gratitude for feedback (Bày tỏ lòng biết ơn về phản hồi)

Người phụ nữ sẽ hướng khách hàng đến trang web giải thích về sự thay đổi: "direct them to the page on our Web site that explains why we changed the packaging" (hướng họ đến trang web của chúng ta giải thích lý do tại sao chúng ta thay đổi bao bì).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5596, 248, '2025/test6/audio/test6_question_44_46.mp3', NULL, 'W-Am: Min-Seok, thanks for suggesting that tagline for our ad campaign for the career consultancy. The clients love it.
M-Au: Glad to hear it! Oh, and Ms. West? I was just wondering_ are we going to have an end-of-the-year staff party in the office again this December?
W-Am: It''s a company tradition. Why wouldn''t we?
M-Au: A lot of employees are remote now.
W-Am: Oh, good point. But... some of those employees might enjoy the chance to see everyone in person again.
M-Au: That''s true.
W-Am: Well, now I''m also curious about what we''ll do. Next time I see the president, I''ll ask her what the plan for this year is.', 'Nữ: Min-Seok, cảm ơn vì đã đề xuất khẩu hiệu đó cho chiến dịch quảng cáo cho công ty tư vấn nghề nghiệp. Khách hàng rất thích nó.
Nam: Rất vui khi nghe điều đó! À, và cô West? Tôi chỉ đang thắc mắc_ chúng ta sẽ có tiệc cuối năm cho nhân viên tại văn phòng vào tháng 12 này như mọi khi chứ?
Nữ: Đó là truyền thống của công ty. Tại sao chúng ta lại không tổ chức?
Nam: Bây giờ có nhiều nhân viên làm việc từ xa.
Nữ: Ồ, ý kiến hay. Nhưng... một số nhân viên đó có thể sẽ thích cơ hội được gặp mọi người trực tiếp một lần nữa.
Nam: Đúng vậy.
Nữ: À, giờ tôi cũng tò mò về việc chúng ta sẽ làm gì. Lần sau khi gặp chủ tịch, tôi sẽ hỏi bà ấy kế hoạch cho năm nay là gì.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7044, 5596, 44, 'What type of business do the speakers most likely work at?', 'An advertising agency', 'An accounting firm', 'An insurance company', 'A career coaching service', 'A', 'Question: "What type of business do the speakers most likely work at?" (Những người nói chuyện nhiều khả năng làm việc tại loại hình doanh nghiệp nào?)
A: An advertising agency (Một công ty quảng cáo)
B: An accounting firm (Một công ty kế toán)
C: An insurance company (Một công ty bảo hiểm)
D: A career coaching service (Một dịch vụ tư vấn nghề nghiệp)

Họ làm việc tại một công ty quảng cáo vì:
1. Thảo luận về khẩu hiệu quảng cáo (tagline)
2. Đang thực hiện chiến dịch quảng cáo cho một công ty tư vấn nghề nghiệp
3. Đây là công việc điển hình của công ty quảng cáo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5597, 248, '2025/test6/audio/test6_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7045, 5597, 45, 'What does the man most likely mean when he says, "A lot of employees are remote now"?', 'Some office space could be used in a different way', 'A company event might not be well-attended', 'Fewer supplies will be needed for a break room', 'It will be difficult to train some new staff members', 'B', 'Question: "What does the man most likely mean when he says, ''A lot of employees are remote now''?" (Người đàn ông nhiều khả năng có ý gì khi nói "Bây giờ có nhiều nhân viên làm việc từ xa"?)
A: Some office space could be used in a different way (Một số không gian văn phòng có thể được sử dụng theo cách khác)
B: A company event might not be well-attended (Một sự kiện công ty có thể không có nhiều người tham dự)
C: Fewer supplies will be needed for a break room (Sẽ cần ít vật dụng hơn cho phòng nghỉ)
D: It will be difficult to train some new staff members (Sẽ khó đào tạo một số nhân viên mới)

Khi nói điều này, người đàn ông ngụ ý rằng buổi tiệc có thể sẽ không có nhiều người tham dự vì nhiều nhân viên làm việc từ xa. Đây là phản hồi cho câu hỏi về việc tổ chức tiệc cuối năm tại văn phòng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5598, 248, '2025/test6/audio/test6_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7046, 5598, 46, 'What does the woman decide to do?', 'Send out a survey', 'Plan a virtual celebration', 'Make revisions to a food order', 'Ask a question to an executive', 'D', 'Question: "What does the woman decide to do?" (Người phụ nữ quyết định làm gì?)
A: Send out a survey (Gửi một khảo sát)
B: Plan a virtual celebration (Lên kế hoạch cho buổi lễ kỷ niệm trực tuyến)
C: Make revisions to a food order (Sửa đổi đơn đặt thức ăn)
D: Ask a question to an executive (Hỏi một câu hỏi với người điều hành)

Người phụ nữ quyết định sẽ hỏi chủ tịch về kế hoạch: "Next time I see the president, I''ll ask her what the plan for this year is" (Lần sau khi gặp chủ tịch, tôi sẽ hỏi bà ấy kế hoạch cho năm nay là gì).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5599, 248, '2025/test6/audio/test6_question_47_49.mp3', NULL, 'M-Au: This construction exposition is really well-organized. I like how the vendors that sell the same types of products are placed near each other.
M-cn: Yeah, that''ll make it easy for us to talk to all the companies that sell site-clearing supplies. Let''s see... they''re in this block. Let''s start with this one.
w-Br: Good morning! What brings you to our booth today?
M-Au: We''re interested in hearing about your company''s heavy equipment for clearing land-like the large machines that cut up tree stumps.
w-Br: Sure. We have five stump cutters in our product lineup. Do you already know what kind of cutting power or wheel size you''ll want?', 'Nam 1: Triển lãm xây dựng này được tổ chức rất tốt. Tôi thích cách các nhà cung cấp bán cùng loại sản phẩm được đặt gần nhau.
Nam 2: Đúng vậy, điều đó sẽ giúp chúng ta dễ dàng nói chuyện với tất cả các công ty bán vật tư dọn dẹp công trường. Để xem... họ ở khu này. Hãy bắt đầu với gian hàng này.
Nữ: Chào buổi sáng! Điều gì đưa các anh đến gian hàng của chúng tôi hôm nay?
Nam 1: Chúng tôi quan tâm đến thiết bị hạng nặng để dọn dẹp đất đai của công ty các bạn - như những máy lớn dùng để cắt gốc cây.
Nữ: Được chứ. Chúng tôi có năm máy cắt gốc cây trong danh mục sản phẩm. Các anh đã biết mình muốn loại công suất cắt hoặc kích thước bánh xe nào chưa?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7047, 5599, 47, 'What do the men like about the exposition?', 'It lasts for several days', 'Its organizers are responsive', 'Its layout is convenient', 'It has many vendors', 'C', 'Question: "What do the men like about the exposition?" (Những người đàn ông thích điều gì về triển lãm?)
A: It lasts for several days (Nó kéo dài nhiều ngày)
B: Its organizers are responsive (Ban tổ chức phản hồi nhanh)
C: Its layout is convenient (Bố cục của nó thuận tiện)
D: It has many vendors (Nó có nhiều nhà cung cấp)

Họ thích cách bố trí các gian hàng thuận tiện: "I like how the vendors that sell the same types of products are placed near each other" (Tôi thích cách các nhà cung cấp bán cùng loại sản phẩm được đặt gần nhau).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5600, 248, '2025/test6/audio/test6_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7048, 5600, 48, 'What does the woman sell?', 'Heavy machinery', 'Building materials', 'Safety gear', 'Hand tools', 'A', 'Question: "What does the woman sell?" (Người phụ nữ bán gì?)
A: Heavy machinery (Máy móc hạng nặng)
B: Building materials (Vật liệu xây dựng)
C: Safety gear (Thiết bị an toàn)
D: Hand tools (Dụng cụ cầm tay)

Người phụ nữ bán máy móc hạng nặng, cụ thể là máy cắt gốc cây: "We have five stump cutters in our product lineup" (Chúng tôi có năm máy cắt gốc cây trong danh mục sản phẩm).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5601, 248, '2025/test6/audio/test6_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7049, 5601, 49, 'What does the woman ask the men about?', 'The brand of products they currently use', 'Their desired product specifications', 'The number of products they need', 'Their interest in a product demonstration', 'B', 'Question: "What does the woman ask the men about?" (Người phụ nữ hỏi những người đàn ông về điều gì?)
A: The brand of products they currently use (Thương hiệu sản phẩm họ đang sử dụng)
B: Their desired product specifications (Thông số kỹ thuật sản phẩm họ mong muốn)
C: The number of products they need (Số lượng sản phẩm họ cần)
D: Their interest in a product demonstration (Sự quan tâm của họ đến việc trình diễn sản phẩm)

Người phụ nữ hỏi về thông số kỹ thuật họ muốn: "Do you already know what kind of cutting power or wheel size you''ll want?" (Các anh đã biết mình muốn loại công suất cắt hoặc kích thước bánh xe nào chưa?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5602, 248, '2025/test6/audio/test6_question_50_52.mp3', NULL, 'M-Au: Good morning. I''ve just become the owner of a small apartment nearby, and I was wondering if your agency could help me list it for rental.
W-Am: Absolutely. Where is the apartment?
M-Au: In the building at 470 Boone Avenue, close to the elevated train line. In fact, the sound of the train passing by can be quite loud even with the windows closed. Will that be a big problem?
W-Am: No, we should still be able to find someone willing to live there. It does mean you probably won''t be able to collect a very high rent fee, though.', 'Nam: Chào buổi sáng. Tôi vừa trở thành chủ sở hữu một căn hộ nhỏ gần đây, và tôi tự hỏi liệu công ty của bạn có thể giúp tôi đăng cho thuê không.
Nữ: Tất nhiên rồi. Căn hộ ở đâu?
Nam: Trong tòa nhà số 470 đại lộ Boone, gần đường tàu trên cao. Thực tế, tiếng tàu đi qua có thể khá ồn ngay cả khi đóng cửa sổ. Điều đó có phải là vấn đề lớn không?
Nữ: Không, chúng tôi vẫn có thể tìm được người sẵn sàng sống ở đó. Tuy nhiên, điều đó có nghĩa là anh có thể sẽ không thu được tiền thuê cao.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7050, 5602, 50, 'What are the speakers mainly discussing?', 'Choosing a venue for a talk', 'Arranging renovations to a building', 'Becoming investors in a business', 'Finding a tenant for a property', 'D', 'Question: "What are the speakers mainly discussing?" (Những người nói chuyện chủ yếu thảo luận về điều gì?)
A: Choosing a venue for a talk (Chọn địa điểm cho một buổi nói chuyện)
B: Arranging renovations to a building (Sắp xếp việc cải tạo một tòa nhà)
C: Becoming investors in a business (Trở thành nhà đầu tư trong một doanh nghiệp)
D: Finding a tenant for a property (Tìm người thuê cho một bất động sản)

Họ đang thảo luận về việc cho thuê một căn hộ và tìm người thuê. Điều này được thể hiện qua việc người đàn ông muốn đăng cho thuê căn hộ mới mua của mình và người phụ nữ nói về khả năng tìm người thuê.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5603, 248, '2025/test6/audio/test6_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7051, 5603, 51, 'According to the man, what might cause a problem?', 'A lack of access to public transportation', 'A scheduling conflict', 'A disruptive noise', 'Confusion about some regulations', 'C', 'Question: "According to the man, what might cause a problem?" (Theo người đàn ông, điều gì có thể gây ra vấn đề?)
A: A lack of access to public transportation (Thiếu khả năng tiếp cận giao thông công cộng)
B: A scheduling conflict (Xung đột lịch trình)
C: A disruptive noise (Tiếng ồn gây phiền nhiễu)
D: Confusion about some regulations (Nhầm lẫn về một số quy định)

Người đàn ông lo ngại về tiếng ồn từ tàu đi qua: "the sound of the train passing by can be quite loud even with the windows closed" (tiếng tàu đi qua có thể khá ồn ngay cả khi đóng cửa sổ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5604, 248, '2025/test6/audio/test6_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7052, 5604, 52, 'What does the woman warn the man about?', 'Some earnings may be low', 'A manager may reject a proposal', 'It will take time to collect some data', 'A location may need to be changed', 'A', 'Question: "What does the woman warn the man about?" (Người phụ nữ cảnh báo người đàn ông về điều gì?)
A: Some earnings may be low (Thu nhập có thể thấp)
B: A manager may reject a proposal (Người quản lý có thể từ chối một đề xuất)
C: It will take time to collect some data (Sẽ mất thời gian để thu thập dữ liệu)
D: A location may need to be changed (Một địa điểm có thể cần được thay đổi)

Người phụ nữ cảnh báo rằng anh ấy có thể sẽ không thu được tiền thuê cao: "you probably won''t be able to collect a very high rent fee" (anh có thể sẽ không thu được tiền thuê cao).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5605, 248, '2025/test6/audio/test6_question_53_55.mp3', NULL, 'w-Br: Hi, Mr. Myers. Thank you for making time for this call. I''m excited to tell you more about how partnering with Sonore Group would benefit your company.
M-Au: I look forward to hearing it.
w-Br: So, what we''d like to do is buy the rights to several of your popular podcast series.
We would then re-record the series in French and release them to our subscribers here in France.
M-Au: I see. To be honest, we''ve also been contacted by another French distributor-Podtastique. Why should we choose your company over them?
W-Br: Well, they''re new to this area, whereas Sonore Group has been translating podcasts for the French-speaking market for over five years.', 'w-Br: Xin chào, ông Myers. Cảm ơn bạn đã dành thời gian cho cuộc gọi này. Tôi rất vui được cho bạn biết thêm về việc hợp tác với Tập đoàn Sonore sẽ mang lại lợi ích cho công ty của bạn như thế nào.
M-Au: Tôi rất mong được nghe nó.
w-Br: Vì vậy, những gì chúng tôi muốn làm là mua bản quyền đối với một số loạt podcast phổ biến của bạn.
Sau đó, chúng tôi sẽ thu âm lại loạt phim bằng tiếng Pháp và phát hành chúng cho những người đăng ký của chúng tôi ở Pháp.
M-Au: Tôi hiểu rồi. Thành thật mà nói, chúng tôi cũng đã được liên hệ bởi một nhà phân phối khác của Pháp-Podtastique. Tại sao chúng tôi nên chọn công ty của bạn thay vì họ? 
W-Br: Vâng, họ là người mới trong lĩnh vực này, trong khi Sonore Group đã dịch podcast cho thị trường nói tiếng Pháp trong hơn năm năm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7053, 5605, 53, 'Why is the woman calling the man?', 'To discuss a potential deal', 'To inquire about a job applicant', 'To announce a price change', 'To extend an event invitation', 'A', 'Question: "Why is the woman calling the man?" (Tại sao người phụ nữ gọi cho người đàn ông?)
A: To discuss a potential deal (Để thảo luận về một thỏa thuận tiềm năng)
B: To inquire about a job applicant (Để hỏi về một ứng viên việc làm)
C: To announce a price change (Để thông báo thay đổi giá)
D: To extend an event invitation (Để gửi lời mời sự kiện)

Người phụ nữ gọi để thảo luận về một thỏa thuận hợp tác tiềm năng giữa Sonore Group và công ty của ông Myers: "I''m excited to tell you more about how partnering with Sonore Group would benefit your company" (Tôi rất vui được nói thêm về cách hợp tác với Sonore Group sẽ có lợi cho công ty của ông).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5606, 248, '2025/test6/audio/test6_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7054, 5606, 54, 'What does the man''s company do?', 'International travel planning', 'Audio content creation', 'Foreign language education', 'Recording equipment manufacturing', 'B', 'Question: "What does the man''s company do?" (Công ty của người đàn ông làm gì?)
A: International travel planning (Lập kế hoạch du lịch quốc tế)
B: Audio content creation (Tạo nội dung âm thanh)
C: Foreign language education (Giáo dục ngoại ngữ)
D: Recording equipment manufacturing (Sản xuất thiết bị ghi âm)

Công ty của người đàn ông tạo nội dung âm thanh dưới dạng podcast: "buy the rights to several of your popular podcast series" (mua bản quyền một số series podcast phổ biến của ông).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5607, 248, '2025/test6/audio/test6_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7055, 5607, 55, 'What does the woman say about Sonore Group?', 'It has a large customer base', 'It has offices throughout the area', 'It has a lot of relevant experience', 'It has a prestigious certification', 'C', 'Question: "What does the woman say about Sonore Group?" (Người phụ nữ nói gì về Sonore Group?)
A: It has a large customer base (Nó có cơ sở khách hàng lớn)
B: It has offices throughout the area (Nó có văn phòng khắp khu vực)
C: It has a lot of relevant experience (Nó có nhiều kinh nghiệm liên quan)
D: It has a prestigious certification (Nó có chứng nhận uy tín)

Người phụ nữ nói rằng Sonore Group có nhiều kinh nghiệm trong việc dịch podcast cho thị trường nói tiếng Pháp: "Sonore Group has been translating podcasts for the French-speaking market for over five years" (Sonore Group đã dịch podcast cho thị trường nói tiếng Pháp hơn năm năm).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5608, 248, '2025/test6/audio/test6_question_56_58.mp3', NULL, 'M-cn: Ms. Chen, welcome! We really appreciate your agreeing to talk to our agricultural engineering students. They''re very eager to hear about one of the jobs open to them after graduation.
w-am: It''s my pleasure. I''ve really enjoyed working as an irrigation technician. And I know that the industry''s expected to keep adding jobs in the future, so it''s a great long-term career option.
M-Cn: Excellent. So, as I said in my e-mail, you''ll have thirty minutes to speak, and then there''ll be a fifteen-minute question-and-answer session. Oh, and would you be willing to share your e-mail address in case students have additional questions later?
w-Am: Sure, I''ll write it on this whiteboard.', 'M-cn: Cô Chen, chào mừng! Chúng tôi thực sự đánh giá cao việc bạn đồng ý nói chuyện với các sinh viên kỹ thuật nông nghiệp của chúng tôi. Họ rất háo hức được nghe về một trong những công việc mở ra cho họ sau khi tốt nghiệp.
w-am: Đó là niềm vui của tôi. Tôi thực sự thích làm kỹ thuật viên thủy lợi. Và tôi biết rằng ngành công nghiệp này dự kiến sẽ tiếp tục bổ sung việc làm trong tương lai, vì vậy đây là một lựa chọn nghề nghiệp dài hạn tuyệt vời.
M-Cn: Tuyệt vời. Vì vậy, như tôi đã nói trong e-mail của mình, bạn sẽ có ba mươi phút để nói, và sau đó sẽ có một phiên hỏi đáp kéo dài mười lăm phút. Ồ, và bạn có sẵn sàng chia sẻ địa chỉ email của mình trong trường hợp sinh viên có thêm câu hỏi sau này không? 
w-Am: Chắc chắn rồi, tôi sẽ viết nó lên bảng trắng này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7056, 5608, 56, 'Who most likely is the man?', 'A university employee', 'A television reporter', 'A public librarian', 'A newspaper editor', 'A', 'Question: "Who most likely is the man?" (Người đàn ông nhiều khả năng là ai?)
A: A university employee (Một nhân viên đại học)
B: A television reporter (Một phóng viên truyền hình)
C: A public librarian (Một thủ thư công cộng)
D: A newspaper editor (Một biên tập viên báo)

Người đàn ông nhiều khả năng là nhân viên đại học vì:
1. Anh ấy nói về "our agricultural engineering students" (sinh viên kỹ thuật nông nghiệp của chúng tôi)
2. Anh ấy tổ chức buổi nói chuyện cho sinh viên về cơ hội việc làm sau tốt nghiệp
3. Anh ấy sắp xếp thời gian cho bài thuyết trình và phần hỏi đáp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5609, 248, '2025/test6/audio/test6_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7057, 5609, 57, 'What does the woman mention about her industry?', 'It is not related to her degree', 'It is difficult to enter', 'It is predicted to grow', 'It has not existed for long', 'C', 'Question: "What does the woman mention about her industry?" (Người phụ nữ đề cập gì về ngành công nghiệp của cô ấy?)
A: It is not related to her degree (Nó không liên quan đến bằng cấp của cô ấy)
B: It is difficult to enter (Nó khó để tham gia)
C: It is predicted to grow (Nó được dự đoán sẽ phát triển)
D: It has not existed for long (Nó chưa tồn tại lâu)

Người phụ nữ nói rằng ngành này được dự đoán sẽ tiếp tục tạo thêm việc làm trong tương lai: "the industry''s expected to keep adding jobs in the future" (ngành này được kỳ vọng sẽ tiếp tục tạo thêm việc làm trong tương lai).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5610, 248, '2025/test6/audio/test6_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7058, 5610, 58, 'What does the woman agree to do?', 'Sign a consent form', 'Pose for a photograph', 'Write an opinion column', 'Provide some contact information', 'D', 'Question: "What does the woman agree to do?" (Người phụ nữ đồng ý làm gì?)
A: Sign a consent form (Ký vào mẫu đồng ý)
B: Pose for a photograph (Chụp ảnh)
C: Write an opinion column (Viết một cột ý kiến)
D: Provide some contact information (Cung cấp thông tin liên hệ)

Người phụ nữ đồng ý cung cấp địa chỉ email của mình để sinh viên có thể hỏi thêm câu hỏi sau này: "Sure, I''ll write it on this whiteboard" (Được chứ, tôi sẽ viết nó lên bảng trắng này).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5611, 248, '2025/test6/audio/test6_question_59_61.mp3', NULL, 'M-Cn: Hi, Ms. Newton? This is Dennis Hendricks calling from Powell Health. I''m sorry to tell you that Dr. Diaz has had to take a leave of absence because of an urgent family matter. He''ll be unavailable for the next month.
w-Br: Oh... so I won''t be able to have my knee surgery next week?
M-Cn: Well, we do have another surgeon who could perform the procedure as scheduled-Dr. Kelvin.
W-Br: Hmm... but Dr. Diaz is the best-rated surgeon in the area...
M-Cn: Sure, I understand. Then I''ll move your surgery date to early April. You should get a text message confirmation within a few minutes.', 'M-Cn: Xin chào, cô Newton? Đây là cuộc gọi của Dennis Hendricks từ Powell Health. Tôi rất tiếc phải nói với bạn rằng Tiến sĩ. Diaz đã phải nghỉ phép vì một vấn đề gia đình khẩn cấp. Anh ấy sẽ không có mặt trong tháng tới.
w-Br: Ồ... vậy là tôi sẽ không thể phẫu thuật đầu gối vào tuần tới? 
M-Cn: Vâng, chúng tôi có một bác sĩ phẫu thuật khác có thể thực hiện thủ thuật theo lịch trình-Tiến sĩ. Kelvin.
W-Br: Hmm... nhưng Tiến sĩ. Diaz là bác sĩ phẫu thuật được đánh giá cao nhất trong khu vực...
M-Cn: Chắc chắn rồi, tôi hiểu. Sau đó tôi sẽ dời ngày phẫu thuật của bạn sang đầu tháng Tư. Bạn sẽ nhận được xác nhận bằng tin nhắn văn bản trong vòng vài phút.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7059, 5611, 59, 'What problem does the man describe?', 'A colleague has gone on leave', 'A member of his family has been injured', 'A medication is not working', 'A speaker has canceled', 'A', 'Question: "What problem does the man describe?" (Người đàn ông mô tả vấn đề gì?)
A: A colleague has gone on leave (Một đồng nghiệp đã nghỉ phép)
B: A member of his family has been injured (Một thành viên gia đình anh ấy bị thương)
C: A medication is not working (Một loại thuốc không có tác dụng)
D: A speaker has canceled (Một diễn giả đã hủy)

Người đàn ông thông báo rằng Bác sĩ Diaz phải nghỉ phép vì việc gia đình khẩn cấp: "Dr. Diaz has had to take a leave of absence because of an urgent family matter" (Bác sĩ Diaz đã phải nghỉ phép vì việc gia đình khẩn cấp).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5612, 248, '2025/test6/audio/test6_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7060, 5612, 60, 'Why most likely does the woman say, "Dr. Diaz is the best-rated surgeon in the area"?', 'To show surprise', 'To refuse an offer', 'To make a suggestion', 'To complain about a decision', 'B', 'Question: "Why most likely does the woman say, ''Dr. Diaz is the best-rated surgeon in the area''?" (Tại sao người phụ nữ nhiều khả năng nói "Bác sĩ Diaz là bác sĩ phẫu thuật được đánh giá tốt nhất trong khu vực"?)
A: To show surprise (Để thể hiện sự ngạc nhiên)
B: To refuse an offer (Để từ chối một đề nghị)
C: To make a suggestion (Để đưa ra một đề xuất)
D: To complain about a decision (Để phàn nàn về một quyết định)

Người phụ nữ nói điều này để từ chối đề nghị được phẫu thuật bởi Bác sĩ Kelvin thay vì Bác sĩ Diaz, ngụ ý rằng cô ấy muốn đợi Bác sĩ Diaz trở lại.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5613, 248, '2025/test6/audio/test6_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7061, 5613, 61, 'What does the man say he will do next?', 'Update a Web site', 'Reschedule an appointment', 'Send a message to Dr. Diaz', 'Research a surgical procedure', 'B', 'Question: "What does the man say he will do next?" (Người đàn ông nói anh ấy sẽ làm gì tiếp theo?)
A: Update a Web site (Cập nhật trang web)
B: Reschedule an appointment (Đổi lịch hẹn)
C: Send a message to Dr. Diaz (Gửi tin nhắn cho Bác sĩ Diaz)
D: Research a surgical procedure (Nghiên cứu một quy trình phẫu thuật)

Người đàn ông nói rằng anh ấy sẽ dời ngày phẫu thuật sang đầu tháng 4: "I''ll move your surgery date to early April" (Tôi sẽ dời ngày phẫu thuật của chị sang đầu tháng 4).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5614, 248, '2025/test6/audio/test6_question_62_64.mp3', '2025/test6/image/test6-p3-image-62.jpg', 'M-Au: Anna, I''m thinking of buying one of these countertop refrigerators so that we can sell cold drinks.
w-Am: That''s a great idea. It''s been so hot and humid outside since last week.
M-Au: Exactly. Now, we don''t have that much counter space, so one of these tall fridges with three shelves would be best, right? But what''s this large block at the top of this one?
W-Am: It''s a display panel. You can put advertising there.
M-Au: Oh, we don''t need that. I''ll order this one instead.
w-Am: That seems like a good choice. And about the drinks-since we''re a pharmacy, I think we should only sell healthy ones, like sugar-free juices with lots of vitamins.', 'Nam: Anna, tôi đang nghĩ đến việc mua một trong những tủ lạnh để bàn này để chúng ta có thể bán đồ uống lạnh.
Nữ: Đó là một ý kiến hay. Trời đã nóng và ẩm bên ngoài kể từ tuần trước.
Nam: Đúng vậy. Bây giờ, chúng ta không có nhiều không gian trên quầy, vì vậy một trong những tủ lạnh cao với ba ngăn sẽ là tốt nhất, đúng không? Nhưng khối lớn ở trên cùng của cái này là gì?
Nữ: Đó là bảng hiển thị. Anh có thể đặt quảng cáo ở đó.
Nam: Ồ, chúng ta không cần cái đó. Tôi sẽ đặt cái này thay thế.
Nữ: Có vẻ là một lựa chọn tốt. Và về đồ uống - vì chúng ta là một hiệu thuốc, tôi nghĩ chúng ta chỉ nên bán những loại lành mạnh, như nước ép không đường với nhiều vitamin.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7062, 5614, 62, 'According to the woman, what happened recently?', 'A refrigerator broke down', 'The business''s sales decreased', 'New countertops were installed', 'The weather changed', 'D', 'Question: "According to the woman, what happened recently?" (Theo người phụ nữ, gần đây điều gì đã xảy ra?)
A: A refrigerator broke down (Một tủ lạnh bị hỏng)
B: The business''s sales decreased (Doanh số kinh doanh giảm)
C: New countertops were installed (Mặt quầy mới được lắp đặt)
D: The weather changed (Thời tiết thay đổi)

Người phụ nữ nói rằng thời tiết đã trở nên nóng và ẩm kể từ tuần trước: "It''s been so hot and humid outside since last week" (Trời đã nóng và ẩm bên ngoài kể từ tuần trước).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5615, 248, '2025/test6/audio/test6_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7063, 5615, 63, 'Look at the graphic. Which refrigerator will the man order?', '#2061', '#2077', '#2084', '#2095', 'C', 'Question: "Look at the graphic. Which refrigerator will the man order?" (Nhìn vào hình. Người đàn ông sẽ đặt tủ lạnh nào?)
A: #2061 (Mẫu 2061)
B: #2077 (Mẫu 2077)
C: #2084 (Mẫu 2084)
D: #2095 (Mẫu 2095)

Người đàn ông sẽ chọn mẫu #2084 vì:
1. Anh ấy cần tủ lạnh cao với ba ngăn
2. Không muốn có bảng hiển thị ở trên cùng
3. Theo ảnh, Mẫu #2084 đáp ứng các yêu cầu này: tall, thin, 3 shelves, swinging door và không có display part on top');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5616, 248, '2025/test6/audio/test6_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7064, 5616, 64, 'What does the woman suggest about some drinks?', 'They should be inexpensive', 'They should promote health', 'They should have a variety of flavors', 'They should come in small containers', 'B', 'Question: "What does the woman suggest about some drinks?" (Người phụ nữ đề xuất gì về đồ uống?)
A: They should be inexpensive (Chúng nên có giá rẻ)
B: They should promote health (Chúng nên tốt cho sức khỏe)
C: They should have a variety of flavors (Chúng nên có nhiều hương vị)
D: They should come in small containers (Chúng nên đựng trong hộp nhỏ)

Người phụ nữ đề xuất chỉ nên bán đồ uống lành mạnh vì họ là hiệu thuốc: "since we''re a pharmacy, I think we should only sell healthy ones, like sugar-free juices with lots of vitamins" (vì chúng ta là hiệu thuốc, tôi nghĩ chúng ta chỉ nên bán những loại lành mạnh, như nước ép không đường với nhiều vitamin).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5617, 248, '2025/test6/audio/test6_question_65_67.mp3', '2025/test6/image/test6-p3-image-65.jpg', 'M-Cn: Eun-Young, the orientation packets you made are great! They''re really going to help the firm''s new junior accountants get settled quickly. I especially like how you created the list of contents so it''s easy to check whether anything has been left out.
W-Br: Thanks! That''s something I learned in my first job in human resources. Orientations are an important introduction to the company. You have to plan carefully to make sure that all the necessary information is included.
M-cn: I agree. Uh, I did notice one issue with the packets, though- I''m afraid these directions for setting up a workstation will be a little confusing for the new hires. I suggest adding some visual aids, like equipment photos and screenshots.', 'Nam: Eun-Young, các gói tài liệu định hướng mà cô làm rất tuyệt! Chúng thực sự sẽ giúp các kế toán viên mới của công ty ổn định nhanh chóng. Tôi đặc biệt thích cách cô tạo danh sách nội dung để dễ dàng kiểm tra xem có thiếu gì không.
Nữ: Cảm ơn! Đó là điều tôi đã học được trong công việc đầu tiên của mình trong bộ phận nhân sự. Định hướng là một phần giới thiệu quan trọng về công ty. Bạn phải lên kế hoạch cẩn thận để đảm bảo rằng tất cả thông tin cần thiết được đưa vào.
Nam: Tôi đồng ý. À, tôi có nhận thấy một vấn đề với các gói tài liệu - tôi e rằng những hướng dẫn thiết lập nơi làm việc này sẽ hơi khó hiểu đối với nhân viên mới. Tôi đề xuất thêm một số công cụ trực quan, như ảnh thiết bị và ảnh chụp màn hình.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7065, 5617, 65, 'What kind of business do the speakers work for?', 'An accounting firm', 'A graphic design company', 'A translation service', 'A travel agency', 'A', 'Question: "What kind of business do the speakers work for?" (Những người nói chuyện làm việc cho loại hình doanh nghiệp nào?)
A: An accounting firm (Một công ty kế toán)
B: A graphic design company (Một công ty thiết kế đồ họa)
C: A translation service (Một dịch vụ dịch thuật)
D: A travel agency (Một đại lý du lịch)

Họ làm việc cho một công ty kế toán vì đoạn hội thoại đề cập đến việc chuẩn bị tài liệu định hướng cho "new junior accountants" (các kế toán viên mới).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5618, 248, '2025/test6/audio/test6_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7066, 5618, 66, 'What does the woman say she learned in a previous job?', 'How to set work performance goals', 'How to recruit talented job candidates', 'How to ensure an orientation is thorough', 'How to keep employee information confidential', 'C', 'Question: "What does the woman say she learned in a previous job?" (Người phụ nữ nói cô ấy đã học được gì trong công việc trước đây?)
A: How to set work performance goals (Cách đặt mục tiêu hiệu suất công việc)
B: How to recruit talented job candidates (Cách tuyển dụng ứng viên tài năng)
C: How to ensure an orientation is thorough (Cách đảm bảo định hướng được kỹ lưỡng)
D: How to keep employee information confidential (Cách giữ bí mật thông tin nhân viên)

Người phụ nữ nói rằng cô ấy đã học được tầm quan trọng của việc lập kế hoạch cẩn thận để đảm bảo định hướng bao gồm tất cả thông tin cần thiết: "You have to plan carefully to make sure that all the necessary information is included" (Bạn phải lên kế hoạch cẩn thận để đảm bảo rằng tất cả thông tin cần thiết được đưa vào).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5619, 248, '2025/test6/audio/test6_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7067, 5619, 67, 'Look at the graphic. Which item in the orientation packet does the man express concern about?', 'Item 2', 'Item 3', 'Item 4', 'Item 5', 'D', 'Question: "Look at the graphic. Which item in the orientation packet does the man express concern about?" (Nhìn vào hình. Người đàn ông bày tỏ lo ngại về mục nào trong gói tài liệu định hướng?)
A: Item 2 (Mục 2)
B: Item 3 (Mục 3)
C: Item 4 (Mục 4)
D: Item 5 (Mục 5)

Người đàn ông lo ngại về Item 5 (Workstation Setup Instructions - Hướng dẫn thiết lập nơi làm việc), "  I''m afraid these directions for setting up a workstation will be a little confusing for the new hires", đối chiếu với ảnh là Item 5.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5620, 248, '2025/test6/audio/test6_question_68_70.mp3', '2025/test6/image/test6-p3-image-68.jpg', 'M-cn: Good morning! How can I help you?
W-Am: Hi, I just finished checking out with one of your store''s self-service machines, but I see on my receipt that I made a mistake with one of the fruit items. I put in the wrong quantity for it.
M-Cn: I''m happy to fix that for you. Which item was it?
w-Am: This one here. There are three of them in the bag I picked up, so I entered "three," but this is not the price that was on the sign. I guess the bag is one unit.
M-Cn: Yes, that''s right. OK, I''ll refund the extra money you paid. May I have the credit card you used for the purchase?', 'Nam: Chào buổi sáng! Tôi có thể giúp gì cho bạn?
Nữ: Chào, tôi vừa thanh toán xong bằng một trong những máy tự phục vụ của cửa hàng các anh, nhưng tôi thấy trên hóa đơn rằng tôi đã mắc lỗi với một trong những mặt hàng trái cây. Tôi đã nhập sai số lượng của nó.
Nam: Tôi sẵn lòng sửa điều đó cho chị. Mặt hàng nào vậy?
Nữ: Mặt hàng này đây. Có ba cái trong túi tôi đã lấy, nên tôi đã nhập "ba", nhưng đây không phải là giá trên biển. Tôi đoán cả túi là một đơn vị.
Nam: Vâng, đúng vậy. OK, tôi sẽ hoàn lại số tiền thừa chị đã trả. Tôi có thể xin thẻ tín dụng chị đã dùng cho giao dịch không?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7068, 5620, 68, 'What problem does the woman describe?', 'A checkout machine is malfunctioning', 'An item''s quantity was entered incorrectly', 'An available discount was not applied', 'Some fruit is in poor condition', 'B', 'Question: "What problem does the woman describe?" (Người phụ nữ mô tả vấn đề gì?)
A: A checkout machine is malfunctioning (Máy thanh toán bị trục trặc)
B: An item''s quantity was entered incorrectly (Số lượng một mặt hàng được nhập sai)
C: An available discount was not applied (Một khuyến mãi có sẵn không được áp dụng)
D: Some fruit is in poor condition (Một số trái cây trong tình trạng không tốt)

Người phụ nữ mô tả việc cô ấy đã nhập sai số lượng một mặt hàng trái cây: "I made a mistake with one of the fruit items. I put in the wrong quantity for it" (tôi đã mắc lỗi với một trong những mặt hàng trái cây. Tôi đã nhập sai số lượng của nó).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5621, 248, '2025/test6/audio/test6_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7069, 5621, 69, 'Look at the graphic. Which amount will be partially refunded?', '$3.00', '$4.50', '$6.30', '$10.10', 'C', 'Question: "Look at the graphic. Which amount will be partially refunded?" (Nhìn vào hình. Số tiền nào sẽ được hoàn lại một phần?)
A: $3.00 (3 đô)
B: $4.50 (4,50 đô)
C: $6.30 (6,30 đô)
D: $10.10 (10,10 đô)

Số tiền $6.30 cho mặt hàng Avocados sẽ được hoàn lại một phần vì:
1. Người phụ nữ đã nhập số lượng 3, tương ứng trong hình là 6,30 đô.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5622, 248, '2025/test6/audio/test6_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7070, 5622, 70, 'What does the man ask the woman for?', 'A coupon code', 'A container of produce', 'A rewards card', 'A payment method', 'D', 'Question: "What does the man ask the woman for?" (Người đàn ông yêu cầu người phụ nữ cung cấp gì?)
A: A coupon code (Mã giảm giá)
B: A container of produce (Hộp đựng sản phẩm)
C: A rewards card (Thẻ tích điểm)
D: A payment method (Phương thức thanh toán)

Người đàn ông yêu cầu thẻ tín dụng mà người phụ nữ đã dùng cho giao dịch để hoàn tiền: "May I have the credit card you used for the purchase?" (Tôi có thể xin thẻ tín dụng chị đã dùng cho giao dịch không?)');;

-- Data for 2025 Test6 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5623, 249, '2025/test6/audio/test6_question_71_73.mp3', NULL, 'Hi, Ms. Bailey. It''s Diego Medero from Bader Motorcycles. Our company is having an issue that we''d like your professional legal advice on. Uh, I''ll give you the basics now. We''re concerned because another company, Rinford Services, recently adopted a logo that looks very similar to ours-a golden wing on top of the company name written in black letters. I''m sending you an e-mail with images of both so you can see for yourself. Now, you should know that Rinford is a shipping company, so it''s not one of our competitors. But we''d still prefer not to have our brands confused. Could you call me back to discuss our options for handling this matter? Thanks.', 'Chào cô Bailey. Tôi là Diego Medero từ Bader Motorcycles. Công ty chúng tôi đang gặp một vấn đề mà chúng tôi muốn nhận tư vấn pháp lý chuyên môn từ cô. À, tôi sẽ cho cô biết những điểm cơ bản ngay bây giờ. Chúng tôi lo ngại vì một công ty khác, Rinford Services, gần đây đã sử dụng một logo trông rất giống của chúng tôi - một cánh chim màu vàng phía trên tên công ty được viết bằng chữ đen. Tôi đang gửi cho cô một email với hình ảnh của cả hai để cô có thể tự xem. Bây giờ, cô nên biết rằng Rinford là một công ty vận chuyển, vì vậy họ không phải là một trong những đối thủ cạnh tranh của chúng tôi. Nhưng chúng tôi vẫn muốn tránh việc thương hiệu của chúng tôi bị nhầm lẫn. Cô có thể gọi lại cho tôi để thảo luận về các lựa chọn xử lý vấn đề này được không? Cảm ơn cô.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7071, 5623, 71, 'Who is the speaker calling?', 'A publicist', 'A graphic designer', 'A property manager', 'A corporate attorney', 'D', '[Dịch] Câu hỏi: Người nói đang gọi cho ai?
A: Một nhà quan hệ công chúng
B: Một nhà thiết kế đồ họa
C: Một người quản lý tài sản
D: Một luật sư doanh nghiệp

Đáp án D là chính xác vì người nói muốn nhận "professional legal advice" (tư vấn pháp lý chuyên nghiệp) về vấn đề logo của công ty, cho thấy Ms. Bailey là một luật sư doanh nghiệp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5624, 249, '2025/test6/audio/test6_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7072, 5624, 72, 'What is the speaker concerned about?', 'The terms of a contract', 'A building directory', 'A logo design', 'A shipping method', 'C', '[Dịch] Câu hỏi: Người nói lo lắng về điều gì?
A: Các điều khoản của một hợp đồng
B: Một danh bạ tòa nhà
C: Một thiết kế logo
D: Một phương thức vận chuyển

Đáp án C là chính xác vì người nói lo ngại về việc một công ty khác "adopted a logo that looks very similar to ours" (sử dụng một logo trông rất giống của họ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5625, 249, '2025/test6/audio/test6_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7073, 5625, 73, 'What does the speaker say about Rinford Services?', 'It is in a different field.', 'It was recently founded.', 'It is based overseas.', 'It is well-known.', 'A', '[Dịch] Câu hỏi: Người nói nói gì về Rinford Services?
A: Nó hoạt động trong một lĩnh vực khác
B: Nó mới được thành lập gần đây
C: Nó có trụ sở ở nước ngoài
D: Nó rất nổi tiếng

Đáp án A là chính xác vì người nói cho biết "Rinford is a shipping company, so it''s not one of our competitors" (Rinford là một công ty vận chuyển, vì vậy họ không phải là đối thủ cạnh tranh của chúng tôi), nghĩa là họ hoạt động trong một lĩnh vực khác.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5626, 249, '2025/test6/audio/test6_question_74_76.mp3', NULL, 'Are you planning to make some improvements to your home this fall? Make sure to stop by Barnett Brothers beforehand to pick up the supplies and equipment you''ll need. We carry everything from power tools to paint, and light fixtures to building materials. Not sure what to look for? We''re happy to help! Barnett Brothers is famous for the expert advice provided by our friendly floor staff. And, throughout October, we''ll be offering discounts on weatherproofing supplies to help you prepare your house for winter. Visit BarnettBrothers.com to learn more.', 'Bạn có dự định cải tạo nhà vào mùa thu này không? Hãy đảm bảo ghé thăm Barnett Brothers trước để lấy các vật tư và thiết bị bạn cần. Chúng tôi có mọi thứ từ công cụ điện đến sơn, và từ đèn đến vật liệu xây dựng. Không chắc chắn nên tìm gì? Chúng tôi rất vui được giúp đỡ! Barnett Brothers nổi tiếng với những lời khuyên chuyên môn được cung cấp bởi nhân viên thân thiện trên sàn bán hàng. Và, trong suốt tháng 10, chúng tôi sẽ cung cấp giảm giá cho các vật tư chống thấm để giúp bạn chuẩn bị nhà cửa cho mùa đông. Truy cập BarnettBrothers.com để tìm hiểu thêm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7074, 5626, 74, 'What most likely is being advertised?', 'A construction company', 'A real estate Web site', 'A hardware store', 'An interior design firm', 'C', '[Dịch] Câu hỏi: Thứ gì có khả năng đang được quảng cáo?
A: Một công ty xây dựng
B: Một trang web bất động sản
C: Một cửa hàng đồ phần cứng
D: Một công ty thiết kế nội thất

Đáp án C là chính xác vì đoạn quảng cáo nói về việc bán các vật tư và thiết bị ("supplies and equipment") như công cụ điện, sơn, đèn và vật liệu xây dựng, điều này đặc trưng cho một cửa hàng đồ phần cứng.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5627, 249, '2025/test6/audio/test6_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7075, 5627, 75, 'What is the business known for?', 'Its pricing', 'Its speed', 'Its creativity', 'Its customer service', 'D', '[Dịch] Câu hỏi: Doanh nghiệp này nổi tiếng về điều gì?
A: Giá cả của nó
B: Tốc độ của nó
C: Sự sáng tạo của nó
D: Dịch vụ khách hàng của nó

Đáp án D là chính xác vì quảng cáo nói rằng "Barnett Brothers is famous for the expert advice provided by our friendly floor staff" (Barnett Brothers nổi tiếng với những lời khuyên chuyên môn được cung cấp bởi nhân viên thân thiện).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5628, 249, '2025/test6/audio/test6_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7076, 5628, 76, 'What does the speaker say is on a Web site?', 'Hours of operation', 'Details about a sale', 'Pictures of houses', 'Positive reviews', 'B', '[Dịch] Câu hỏi: Người nói nói có gì trên trang web?
A: Giờ hoạt động
B: Chi tiết về đợt giảm giá
C: Hình ảnh của các ngôi nhà
D: Đánh giá tích cực

Đáp án B là chính xác vì sau khi đề cập đến việc giảm giá vật tư chống thấm, người nói hướng dẫn "Visit BarnettBrothers.com to learn more" (Truy cập BarnettBrothers.com để tìm hiểu thêm), ngụ ý rằng chi tiết về đợt giảm giá có trên trang web.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5629, 249, '2025/test6/audio/test6_question_77_79.mp3', NULL, 'Hi, Robin. This is Noah Adkins from Lakeside Dental. We''re looking forward to speaking to you about the hygienist position on Thursday. I''m calling to make sure you know that this first interview will just be a conversation about your skills and experience. You won''t be interacting with patients. There''s been some confusion about this among our other candidates. All right, then we''ll see you at two on Thursday. Oh, and-you should probably start heading over quite early. It can be hard to find parking around here.', 'Chào Robin. Tôi là Noah Adkins từ Nha khoa Lakeside. Chúng tôi mong được nói chuyện với bạn về vị trí vệ sinh răng miệng vào thứ Năm. Tôi gọi để đảm bảo bạn biết rằng cuộc phỏng vấn đầu tiên này chỉ là một cuộc trò chuyện về kỹ năng và kinh nghiệm của bạn. Bạn sẽ không tương tác với bệnh nhân. Đã có một số nhầm lẫn về điều này trong số các ứng viên khác của chúng tôi. Được rồi, vậy chúng tôi sẽ gặp bạn lúc hai giờ vào thứ Năm. Ồ, và - bạn có lẽ nên bắt đầu đi sớm. Có thể khó tìm chỗ đậu xe ở đây.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7077, 5629, 77, 'Where most likely does the speaker work?', 'At a hair salon', 'At a dentist''s office', 'At an auto repair shop', 'At a dry cleaning business', 'B', '[Dịch] Câu hỏi: Người nói có khả năng làm việc ở đâu?
A: Tại một salon tóc
B: Tại một phòng nha khoa
C: Tại một tiệm sửa xe
D: Tại một tiệm giặt khô

Đáp án B là chính xác vì người nói giới thiệu mình từ "Lakeside Dental" và đang thảo luận về vị trí vệ sinh răng miệng (hygienist position).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5630, 249, '2025/test6/audio/test6_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7078, 5630, 78, 'What is the speaker calling about?', 'An appliance delivery', 'A customer appointment', 'A safety inspection', 'A job interview', 'D', '[Dịch] Câu hỏi: Người nói đang gọi về việc gì?
A: Giao một thiết bị
B: Cuộc hẹn của khách hàng
C: Kiểm tra an toàn
D: Một cuộc phỏng vấn việc làm

Đáp án D là chính xác vì người nói đề cập đến "this first interview" (cuộc phỏng vấn đầu tiên này) và thảo luận về cách thức tiến hành.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5631, 249, '2025/test6/audio/test6_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7079, 5631, 79, 'Why does the speaker say, "It can be hard to find parking around here"?', 'To explain a recommendation', 'To justify an expense', 'To express doubt about a plan', 'To request patience with a delay', 'A', '[Dịch] Câu hỏi: Tại sao người nói nói "có thể khó tìm chỗ đậu xe ở đây"?
A: Để giải thích một khuyến nghị
B: Để biện minh cho một khoản chi phí
C: Để bày tỏ nghi ngờ về một kế hoạch
D: Để yêu cầu kiên nhẫn với sự chậm trễ

Đáp án A là chính xác vì người nói dùng điều này để giải thích tại sao họ khuyến nghị Robin "start heading over quite early" (bắt đầu đi sớm).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5632, 249, '2025/test6/audio/test6_question_80_82.mp3', NULL, 'Today''s episode of Tech Insider is for some of you who aren''t part of the technology industry yet, but want to be. Specifically, I''ll be talking about intensive courses in computer coding, and how to choose the one that best suits your goals and existing skills. These days, there are many options for coding courses. It''s important to carry out detailed research on several factors before enrolling. I''ll tell you what information you need to know and how to find it-with some help from my guest today. His name is Hinata Kondo, and he has written extensively about coding courses for TechNation.com and other sites. Hinata, welcome.', 'Tập hôm nay của Tech Insider dành cho những người trong số các bạn chưa là một phần của ngành công nghệ nhưng muốn tham gia. Cụ thể, tôi sẽ nói về các khóa học chuyên sâu về lập trình máy tính, và làm thế nào để chọn khóa học phù hợp nhất với mục tiêu và kỹ năng hiện có của bạn. Ngày nay, có nhiều lựa chọn cho các khóa học lập trình. Điều quan trọng là phải thực hiện nghiên cứu chi tiết về một số yếu tố trước khi đăng ký. Tôi sẽ cho bạn biết những thông tin bạn cần biết và cách tìm thông tin đó - với sự giúp đỡ từ khách mời hôm nay của tôi. Tên anh ấy là Hinata Kondo, và anh ấy đã viết rất nhiều về các khóa học lập trình cho TechNation.com và các trang web khác. Hinata, xin chào mừng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7080, 5632, 80, 'What is the focus of the episode?', 'Developing a mobile application', 'Taking advantage of a new technology', 'Selecting a training program', 'Evaluating job candidates', 'C', '[Dịch] Câu hỏi: Trọng tâm của tập này là gì?
A: Phát triển một ứng dụng di động
B: Tận dụng một công nghệ mới
C: Lựa chọn một chương trình đào tạo
D: Đánh giá ứng viên công việc

Đáp án C là chính xác vì tập này tập trung vào việc làm thế nào để chọn khóa học lập trình ("how to choose the one that best suits your goals") phù hợp nhất với mục tiêu và kỹ năng hiện có.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5633, 249, '2025/test6/audio/test6_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7081, 5633, 81, 'What does the speaker say is important?', 'Conducting thorough research', 'Specifying a set of goals', 'Joining an industry association', 'Asking others for recommendations', 'A', '[Dịch] Câu hỏi: Người nói nói điều gì là quan trọng?
A: Thực hiện nghiên cứu kỹ lưỡng
B: Xác định một bộ mục tiêu
C: Tham gia một hiệp hội ngành
D: Hỏi người khác về đề xuất

Đáp án A là chính xác vì người nói nhấn mạnh "It''s important to carry out detailed research on several factors before enrolling" (Điều quan trọng là phải thực hiện nghiên cứu chi tiết về một số yếu tố trước khi đăng ký).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5634, 249, '2025/test6/audio/test6_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7082, 5634, 82, 'Who most likely is Hinata Kondo?', 'A professional recruiter', 'An online journalist', 'A business consultant', 'A computer programmer', 'B', '[Dịch] Câu hỏi: Hinata Kondo có khả năng là ai?
A: Một nhà tuyển dụng chuyên nghiệp
B: Một nhà báo trực tuyến
C: Một chuyên gia tư vấn kinh doanh
D: Một lập trình viên máy tính

Đáp án B là chính xác vì đoạn văn cho biết ông ấy "has written extensively about coding courses for TechNation.com and other sites" (đã viết rất nhiều về các khóa học lập trình cho TechNation.com và các trang web khác).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5635, 249, '2025/test6/audio/test6_question_83_85.mp3', NULL, 'Welcome to today''s tour of Fox Canyon, one of the highlights of Hodges National Park. I''m Eric, your guide. I''ll also be driving the UTV, or utility terrain vehicle, that will take us to the canyon. It''s about a twenty-minute drive across the desert. You can take pictures and video along the way- just make sure to keep your seat belt fastened until we''ve come to a complete stop at the canyon. Also, for anyone who''s interested, I have a few copies of a park vegetation guide. It''s just one page, but it shows a lot of the trees, cacti, and wildflowers you''ll be able to see today.', 'Chào mừng đến với chuyến tham quan Fox Canyon hôm nay, một trong những điểm nổi bật của Công viên Quốc gia Hodges. Tôi là Eric, hướng dẫn viên của các bạn. Tôi cũng sẽ lái chiếc UTV, hay xe địa hình đa dụng, sẽ đưa chúng ta đến hẻm núi. Đó là một chuyến đi khoảng hai mươi phút qua sa mạc. Bạn có thể chụp ảnh và quay video dọc đường - chỉ cần đảm bảo thắt dây an toàn cho đến khi chúng ta dừng hoàn toàn tại hẻm núi. Ngoài ra, cho bất kỳ ai quan tâm, tôi có một vài bản hướng dẫn về thực vật trong công viên. Nó chỉ có một trang, nhưng nó cho thấy rất nhiều cây cối, xương rồng và hoa dại mà bạn sẽ có thể thấy hôm nay.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7083, 5635, 83, 'Where is the tour taking place?', 'At a city zoo', 'At a national park', 'At a vegetable farm', 'At a historical site', 'B', '[Dịch] Câu hỏi: Chuyến tham quan đang diễn ra ở đâu?
A: Tại một sở thú thành phố
B: Tại một công viên quốc gia
C: Tại một trang trại rau củ
D: Tại một di tích lịch sử

Đáp án B là chính xác vì người nói giới thiệu họ đang ở "Fox Canyon, one of the highlights of Hodges National Park" (Hẻm núi Fox, một trong những điểm nổi bật của Công viên Quốc gia Hodges).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5636, 249, '2025/test6/audio/test6_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7084, 5636, 84, 'What does the speaker tell the listeners to do during a drive?', 'Refrain from speaking', 'Handle some electronics carefully', 'Watch out for some animals', 'Leave their seat belts on', 'D', '[Dịch] Câu hỏi: Người nói bảo người nghe làm gì trong chuyến đi?
A: Không nói chuyện
B: Xử lý thiết bị điện tử cẩn thận
C: Để ý động vật
D: Giữ dây an toàn của họ

Đáp án D là chính xác vì người nói yêu cầu "keep your seat belt fastened until we''ve come to a complete stop" (giữ dây an toàn thắt chặt cho đến khi chúng ta dừng hoàn toàn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5637, 249, '2025/test6/audio/test6_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7085, 5637, 85, 'According to a speaker, what is shown on a handout?', 'A route map', 'Meal options', 'Operating instructions', 'Images of plants', 'D', '[Dịch] Câu hỏi: Theo người nói, cái gì được hiển thị trên tài liệu phát tay?
A: Một bản đồ lộ trình
B: Các lựa chọn bữa ăn
C: Hướng dẫn vận hành
D: Hình ảnh thực vật

Đáp án D là chính xác vì người nói đề cập đến "a park vegetation guide" (hướng dẫn về thực vật trong công viên) cho thấy "trees, cacti, and wildflowers" (cây cối, xương rồng và hoa dại).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5638, 249, '2025/test6/audio/test6_question_86_88.mp3', NULL, 'Thank you all for coming in early. As you know, our bookstore chain has been losing customers since Internet booksellers became popular. Management has come to the conclusion that what our stores need is a unique, local flavor-after all, you can''t get that online. So, headquarters just let us know that each location no longer has to follow strict guidelines about brand identity. We can make changes to our store''s interior and even inventory. Exciting, isn''t it? And please know that your input will be welcome. In fact, I''m going to form an "Improvements Committee." Those of you who have time should sign up.', 'Cảm ơn tất cả các bạn đã đến sớm. Như các bạn biết, chuỗi hiệu sách của chúng ta đã đang mất khách hàng kể từ khi các nhà bán sách trực tuyến trở nên phổ biến. Ban quản lý đã đi đến kết luận rằng điều mà các cửa hàng của chúng ta cần là một nét đặc trưng địa phương độc đáo - dù sao thì bạn cũng không thể có được điều đó trực tuyến. Vì vậy, trụ sở chính vừa cho chúng ta biết rằng mỗi địa điểm không còn phải tuân theo hướng dẫn nghiêm ngặt về nhận diện thương hiệu nữa. Chúng ta có thể thay đổi nội thất cửa hàng và thậm chí cả hàng tồn kho. Thú vị phải không? Và xin hãy biết rằng ý kiến đóng góp của các bạn sẽ được chào đón. Thực tế, tôi sẽ thành lập một "Ủy ban Cải tiến." Những ai trong số các bạn có thời gian nên đăng ký.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7086, 5638, 86, 'What does the speaker imply when she says, "you can''t get that online"?', 'It is becoming difficult to obtain some merchandise.', 'She is proud of the high-quality service provided at the store.', 'Some news has not been communicated to the public yet.', 'The company will differentiate itself from some competitors.', 'D', '[Dịch] Câu hỏi: Người nói ngụ ý gì khi cô ấy nói "bạn không thể có được điều đó trực tuyến"?
A: Đang trở nên khó khăn để có được một số hàng hóa
B: Cô ấy tự hào về dịch vụ chất lượng cao được cung cấp tại cửa hàng
C: Một số tin tức chưa được thông báo cho công chúng
D: Công ty sẽ tự phân biệt mình với một số đối thủ cạnh tranh

Đáp án D là chính xác vì người nói đề cập đến việc tạo ra "unique, local flavor" để phân biệt với các cửa hàng sách trực tuyến, đây là điều "you can''t get online".');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5639, 249, '2025/test6/audio/test6_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7087, 5639, 87, 'What is the main topic of the announcement?', 'A revision to a corporate policy', 'The relocation of a store branch', 'A search for a new supplier', 'The launch of a marketing campaign', 'A', '[Dịch] Câu hỏi: Chủ đề chính của thông báo là gì?
A: Một sửa đổi đối với chính sách công ty
B: Việc di dời một chi nhánh cửa hàng
C: Tìm kiếm một nhà cung cấp mới
D: Việc ra mắt một chiến dịch tiếp thị

Đáp án A là chính xác vì thông báo tập trung vào việc trụ sở chính đã thay đổi chính sách, cho phép các cửa hàng không còn phải tuân theo hướng dẫn nghiêm ngặt về nhận diện thương hiệu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5640, 249, '2025/test6/audio/test6_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7088, 5640, 88, 'What are some of the listeners asked to do?', 'Check some inventory', 'Visit some retail spaces', 'Join a committee', 'Set up a display', 'C', '[Dịch] Câu hỏi: Một số người nghe được yêu cầu làm gì?
A: Kiểm tra hàng tồn kho
B: Thăm một số không gian bán lẻ
C: Tham gia một ủy ban
D: Thiết lập một gian trưng bày

Đáp án C là chính xác vì người nói thông báo việc thành lập "Improvements Committee" và mời những người có thời gian đăng ký tham gia ("Those of you who have time should sign up").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5641, 249, '2025/test6/audio/test6_question_89_91.mp3', NULL, 'It''s great to see everyone gathered here to say goodbye to Angela Thorne. Our hotel has been lucky to have her as our head of human resources for the past five years. In that time, she did wonderful work in fostering a culture of transparency and teamwork here. Let''s hope that she can make a similar impact on our other locations as the new regional vice president of HR. Now, we''d usually present Angela with a gift at this point, but she''s asked that we give money to one of her favorite causes, animal welfare, instead. So, I''m proud to announce that I''ve sent a generous check to Herrick Animal Shelter.', 'Thật tuyệt khi thấy mọi người tụ họp ở đây để nói lời tạm biệt với Angela Thorne. Khách sạn của chúng ta đã may mắn có cô ấy làm trưởng phòng nhân sự trong năm năm qua. Trong thời gian đó, cô ấy đã làm việc tuyệt vời trong việc thúc đẩy văn hóa minh bạch và làm việc nhóm ở đây. Hãy hy vọng rằng cô ấy có thể tạo ra tác động tương tự tại các địa điểm khác của chúng ta với tư cách là phó chủ tịch khu vực mới về nhân sự. Bây giờ, thông thường chúng ta sẽ tặng Angela một món quà vào lúc này, nhưng cô ấy đã yêu cầu chúng ta tặng tiền cho một trong những mục đích yêu thích của cô ấy, phúc lợi động vật, thay vào đó. Vì vậy, tôi tự hào thông báo rằng tôi đã gửi một tấm séc hào phóng cho Trung tâm cứu trợ động vật Herrick.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7089, 5641, 89, 'What event is taking place?', 'A community fund-raiser', 'A going-away party', 'An awards dinner', 'A press conference', 'B', '[Dịch] Câu hỏi: Sự kiện gì đang diễn ra?
A: Một sự kiện gây quỹ cộng đồng
B: Một bữa tiệc chia tay
C: Một bữa tối trao giải
D: Một cuộc họp báo

Đáp án B là chính xác vì đây là sự kiện để "say goodbye to Angela Thorne" (nói lời tạm biệt với Angela Thorne) khi cô ấy rời vị trí hiện tại để đảm nhận vai trò mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5642, 249, '2025/test6/audio/test6_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7090, 5642, 90, 'What does the speaker praise Angela Thorne for?', 'Improving a workplace''s culture', 'Increasing awareness of a local issue', 'Forming an effective project team', 'Managing a budget wisely', 'A', '[Dịch] Câu hỏi: Người nói khen ngợi Angela Thorne về điều gì?
A: Cải thiện văn hóa nơi làm việc
B: Nâng cao nhận thức về một vấn đề địa phương
C: Thành lập một nhóm dự án hiệu quả
D: Quản lý ngân sách một cách khôn ngoan

Đáp án A là chính xác vì người nói khen ngợi cô ấy đã "fostering a culture of transparency and teamwork" (thúc đẩy văn hóa minh bạch và làm việc nhóm).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5643, 249, '2025/test6/audio/test6_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7091, 5643, 91, 'What does the speaker say he has done?', 'Prepared a visual presentation', 'Invited another person to speak', 'Made a charitable donation', 'Purchased a personal gift', 'C', '[Dịch] Câu hỏi: Người nói nói anh ấy đã làm gì?
A: Chuẩn bị một bài thuyết trình trực quan
B: Mời một người khác phát biểu
C: Thực hiện quyên góp từ thiện
D: Mua một món quà cá nhân

Đáp án C là chính xác vì người nói thông báo "I''ve sent a generous check to Herrick Animal Shelter" (tôi đã gửi một tấm séc hào phóng cho Trung tâm cứu trợ động vật Herrick).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5644, 249, '2025/test6/audio/test6_question_92_94.mp3', NULL, 'Since we''re speaking of plans for our new manufacturing plant, l''d like to bring up an idea I had. During my family vacation last week, we toured a chocolate factory, and the best part was an enclosed walkway that went right over the production floor. We could see everything that was going on, and we weren''t bothering the workers. I believe that people would be interested in seeing how our products are made-especially our baseballs and baseball gloves. Why don''t we include a walkway like that in the new plant and start offering tours? It seems to me like it wouldn''t be hard to have that feature added to the plans, but I''m not an architect.', 'Vì chúng ta đang nói về kế hoạch cho nhà máy sản xuất mới, tôi muốn nêu ra một ý tưởng tôi đã có. Trong kỳ nghỉ gia đình tuần trước, chúng tôi đã tham quan một nhà máy sô-cô-la, và phần hay nhất là một lối đi kín đi ngay phía trên sàn sản xuất. Chúng tôi có thể thấy mọi thứ đang diễn ra, và chúng tôi không làm phiền các công nhân. Tôi tin rằng mọi người sẽ quan tâm đến việc xem cách sản phẩm của chúng ta được làm ra - đặc biệt là bóng chày và găng tay bóng chày của chúng ta. Tại sao chúng ta không đưa một lối đi như vậy vào nhà máy mới và bắt đầu cung cấp các tour tham quan? Tôi nghĩ rằng sẽ không khó để thêm tính năng đó vào kế hoạch, nhưng tôi không phải là kiến trúc sư.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7092, 5644, 92, 'What did the speaker recently do?', 'She took a factory tour.', 'She read a journal article.', 'She spoke with some workers.', 'She hosted some visitors.', 'A', '[Dịch] Câu hỏi: Gần đây người nói đã làm gì?
A: Cô ấy đã đi tham quan một nhà máy
B: Cô ấy đã đọc một bài báo tạp chí
C: Cô ấy đã nói chuyện với một số công nhân
D: Cô ấy đã đón tiếp một số khách

Đáp án A là chính xác vì người nói đề cập rằng trong kỳ nghỉ tuần trước "we toured a chocolate factory" (chúng tôi đã tham quan một nhà máy sô-cô-la).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5645, 249, '2025/test6/audio/test6_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7093, 5645, 93, 'What does the speaker''s company make?', 'Musical instruments', 'Sporting goods', 'Snack foods', 'Wooden furniture', 'B', '[Dịch] Câu hỏi: Công ty của người nói sản xuất gì?
A: Nhạc cụ
B: Đồ dùng thể thao
C: Đồ ăn nhẹ
D: Đồ nội thất gỗ

Đáp án B là chính xác vì người nói đề cập đến việc sản xuất "baseballs and baseball gloves" (bóng chày và găng tay bóng chày), đây là các đồ dùng thể thao.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5646, 249, '2025/test6/audio/test6_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7094, 5646, 94, 'What does the speaker mean when she says, "I''m not an architect"?', 'She does not know if a proposal is reasonable.', 'She will need assistance with an assignment.', 'She is not interested in the details of a building plan.', 'She is concerned that the listeners have been misled.', 'A', '[Dịch] Câu hỏi: Người nói có ý gì khi cô ấy nói "Tôi không phải là kiến trúc sư"?
A: Cô ấy không biết liệu một đề xuất có hợp lý không
B: Cô ấy sẽ cần hỗ trợ với một nhiệm vụ
C: Cô ấy không quan tâm đến chi tiết của một bản vẽ tòa nhà
D: Cô ấy lo lắng rằng người nghe đã bị hiểu sai

Đáp án A là chính xác vì người nói dùng cụm từ này để thể hiện rằng cô ấy không chắc chắn về tính khả thi của việc thêm lối đi vào thiết kế nhà máy ("wouldn''t be hard to have that feature added to the plans").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5647, 249, '2025/test6/audio/test6_question_95_97.mp3', '2025/test6/image/test6-p4-image-95.jpg', 'Thank you all for coming to Venegas Fashion''s development day for store staff. Today you''ll have the chance to develop your skills as retail professionals and consider the futures of your careers. Uh, if you didn''t do so when you arrived, please sign in now by writing your name on the sheet near the door. We want to know who''s in attendance today. As you can see, we have four workshops scheduled. Each will last fifty minutes, except the four o''clock workshop. That will last just half an hour, so it will end around four-thirty. Now, I have a special guest to introduce. This is Yuko Ikeda, the company''s director of personnel for more than ten years. She would like to say a few words before we begin the first workshop.', 'Cảm ơn tất cả các bạn đã đến tham dự ngày phát triển dành cho nhân viên cửa hàng của Venegas Fashion. Hôm nay các bạn sẽ có cơ hội phát triển kỹ năng với tư cách là các chuyên gia bán lẻ và xem xét tương lai sự nghiệp của mình. À, nếu bạn chưa làm khi đến, vui lòng ký tên ngay bây giờ bằng cách viết tên của bạn vào tờ giấy gần cửa. Chúng tôi muốn biết ai đang tham dự hôm nay. Như các bạn có thể thấy, chúng ta có bốn hội thảo được lên lịch. Mỗi hội thảo sẽ kéo dài năm mươi phút, ngoại trừ hội thảo lúc bốn giờ. Hội thảo đó sẽ chỉ kéo dài nửa giờ, vì vậy nó sẽ kết thúc khoảng bốn giờ rưỡi. Bây giờ, tôi có một khách mời đặc biệt để giới thiệu. Đây là Yuko Ikeda, giám đốc nhân sự của công ty trong hơn mười năm. Cô ấy muốn nói vài lời trước khi chúng ta bắt đầu hội thảo đầu tiên.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7095, 5647, 95, 'What are the listeners asked to do?', 'Put on name tags', 'Silence their mobile phones', 'Sign an attendance sheet', 'Take their seats', 'C', '[Dịch] Câu hỏi: Người nghe được yêu cầu làm gì?
A: Đeo thẻ tên
B: Tắt điện thoại di động
C: Ký vào bảng điểm danh
D: Ngồi vào chỗ

Đáp án C là chính xác vì người nói yêu cầu "sign in now by writing your name on the sheet near the door" (ký tên ngay bây giờ bằng cách viết tên của bạn vào tờ giấy gần cửa).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5648, 249, '2025/test6/audio/test6_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7096, 5648, 96, 'Look at the graphic. Which workshop will be shorter than the others?', 'Introduction to Upcoming Products', 'Good Customer Service', 'How to Arrange Displays', 'Career Paths at Venegas Fashion', 'D', '[Dịch] Câu hỏi: Nhìn vào hình. Hội thảo nào sẽ ngắn hơn các hội thảo khác?
A: Giới thiệu về Sản phẩm Sắp tới
B: Dịch vụ Khách hàng Tốt
C: Cách Sắp xếp Trưng bày
D: Con đường Sự nghiệp tại Venegas Fashion

Đáp án D là chính xác vì người nói cho biết workshop lúc 4:00 sẽ chỉ kéo dài 30 phút thay vì 50 phút như các workshop khác, và nhìn vào lịch, "Career Paths at Venegas Fashion" là workshop diễn ra lúc 4:00.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5649, 249, '2025/test6/audio/test6_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7097, 5649, 97, 'According to the speaker, what will Ms. Ikeda do?', 'Make an audio recording', 'Give a short speech', 'Lead one of the workshops', 'Distribute an employee survey', 'B', '[Dịch] Câu hỏi: Theo người nói, bà Ikeda sẽ làm gì?
A: Thực hiện một bản ghi âm
B: Phát biểu ngắn
C: Dẫn dắt một trong các hội thảo
D: Phát một bản khảo sát nhân viên

Đáp án B là chính xác vì người nói cho biết Ms. Ikeda "would like to say a few words before we begin the first workshop" (muốn nói vài lời trước khi chúng ta bắt đầu hội thảo đầu tiên).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5650, 249, '2025/test6/audio/test6_question_98_100.mp3', '2025/test6/image/test6-p4-image-98.jpg', 'All right, everyone, I have the latest results from our customer exit survey-the one we ask them to take when they cancel our meal kit service. To make the survey easier to complete, we recently cut it down to just one question about their reason for canceling. I''m happy to say that this has resulted in a better response rate. So, what have we found out? Well, you''ll see here that a surprisingly high percentage of people are canceling because they''re not satisfied with the food. It seems we need new and better recipes. Perhaps we should try asking popular food bloggers to develop some, like other services have done. What do you all think of that idea?', 'Được rồi, mọi người, tôi có kết quả mới nhất từ cuộc khảo sát khách hàng rời đi - cuộc khảo sát mà chúng ta yêu cầu họ thực hiện khi họ hủy dịch vụ bộ đồ ăn của chúng ta. Để làm cho cuộc khảo sát dễ hoàn thành hơn, gần đây chúng tôi đã cắt giảm xuống chỉ còn một câu hỏi về lý do họ hủy. Tôi vui mừng nói rằng điều này đã dẫn đến tỷ lệ phản hồi tốt hơn. Vậy, chúng ta đã phát hiện ra điều gì? Chà, bạn sẽ thấy ở đây rằng một tỷ lệ đáng ngạc nhiên người hủy vì họ không hài lòng với đồ ăn. Có vẻ như chúng ta cần công thức nấu ăn mới và tốt hơn. Có lẽ chúng ta nên thử yêu cầu các blogger ẩm thực nổi tiếng phát triển một số, như các dịch vụ khác đã làm. Các bạn nghĩ gì về ý tưởng đó?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7098, 5650, 98, 'What does the speaker mention about the survey?', 'It has been simplified.', 'It does not receive many responses.', 'A question has been added to it.', 'It is delivered by e-mail.', 'A', '[Dịch] Câu hỏi: Người nói đề cập điều gì về cuộc khảo sát?
A: Nó đã được đơn giản hóa
B: Nó không nhận được nhiều phản hồi
C: Một câu hỏi đã được thêm vào
D: Nó được gửi qua email

Đáp án A là chính xác vì người nói cho biết họ "cut it down to just one question" (cắt giảm xuống còn một câu hỏi) để làm cho khảo sát dễ hoàn thành hơn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5651, 249, '2025/test6/audio/test6_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7099, 5651, 99, 'Look at the graphic. Which figure does the speaker call attention to?', '41%', '22%', '16%', '9%', 'B', '[Dịch] Câu hỏi: Nhìn vào biểu đồ. Người nói gọi sự chú ý đến con số nào?
A: 41%
B: 22%
C: 16%
D: 9%

Đáp án B là chính xác vì người nói nhấn mạnh đến tỷ lệ đáng ngạc nhiên của những người hủy vì không hài lòng với đồ ăn, và trong biểu đồ, 22% là phần "Did not like the food" (Không thích đồ ăn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5652, 249, '2025/test6/audio/test6_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7100, 5652, 100, 'What will the listeners most likely do next?', 'Divide into groups', 'Look at more data', 'Sample some food', 'Give their opinions', 'D', '[Dịch] Câu hỏi: Người nghe có khả năng sẽ làm gì tiếp theo?
A: Chia thành các nhóm
B: Xem thêm dữ liệu
C: Nếm thử một số đồ ăn
D: Đưa ra ý kiến của họ

Đáp án D là chính xác vì người nói kết thúc bằng câu hỏi "What do you all think of that idea?" (Các bạn nghĩ gì về ý tưởng đó?), cho thấy họ muốn lắng nghe ý kiến từ người nghe.');;

-- Data for 2025 Test6 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5653, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7101, 5653, 101, 'Testers report that the video game''s final level is somewhat -----.', 'frustrate', 'frustrating', 'frustration', 'frustrated', 'B', 'Đáp án B (frustrating) là đúng vì các lý do sau:
1. Cần một tính từ dạng V-ing để mô tả tính chất của level game.
2. "Frustrating" là tính từ chỉ tính chất gây thất vọng, khó chịu.
3. Cấu trúc "is + tính từ" diễn tả trạng thái của một sự vật.
4. Các đáp án khác không phù hợp: "frustrate" (động từ), "frustration" (danh từ), "frustrated" (tính từ bị động).
Dịch câu hỏi: Những người thử nghiệm báo cáo rằng màn chơi cuối cùng của trò chơi điện tử hơi gây thất vọng.
Dịch đáp án:
A. frustrate (động từ: làm thất vọng)
B. frustrating (tính từ chủ động: gây thất vọng)
C. frustration (danh từ: sự thất vọng)
D. frustrated (tính từ bị động: bị thất vọng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5654, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7102, 5654, 102, 'Marcus Siegler is attempting to develop a new ----- for predicting solar activity.', 'recognition', 'direction', 'method', 'opinion', 'C', 'Đáp án C (method) là đúng vì các lý do sau:
1. Cần một danh từ chỉ phương pháp, cách thức.
2. "Method" là danh từ chỉ phương pháp thực hiện một việc.
3. Cụm từ "method for + V-ing" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp về nghĩa: "recognition" (sự công nhận), "direction" (hướng), "opinion" (ý kiến).
Dịch câu hỏi: Marcus Siegler đang cố gắng phát triển một phương pháp mới để dự đoán hoạt động của mặt trời.
Dịch đáp án:
A. recognition (danh từ: sự công nhận)
B. direction (danh từ: hướng)
C. method (danh từ: phương pháp)
D. opinion (danh từ: ý kiến)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5655, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7103, 5655, 103, 'The university''s largest dormitory, Lugo Residence Hall, accommodates ----- 600 students.', 'enough', 'nearly', 'totally', 'more', 'B', 'Đáp án B (nearly) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ mức độ gần đạt đến một con số.
2. "Nearly" có nghĩa là "gần như, xấp xỉ".
3. "Nearly + số" là cách diễn đạt phổ biến chỉ số lượng gần đạt đến.
4. Các đáp án khác không phù hợp về nghĩa và cấu trúc: "enough" (đủ), "totally" (hoàn toàn), "more" (nhiều hơn).
Dịch câu hỏi: Ký túc xá lớn nhất của trường đại học, Lugo Residence Hall, có thể chứa gần 600 sinh viên.
Dịch đáp án:
A. enough (trạng từ: đủ)
B. nearly (trạng từ: gần như)
C. totally (trạng từ: hoàn toàn)
D. more (trạng từ: nhiều hơn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5656, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7104, 5656, 104, 'Ms. Chaney says her upcoming cookbook will feature only dishes made with —---obtainable ingredients.', 'easily', 'easy', 'ease', 'easier', 'A', 'Đáp án A (easily) là đúng vì các lý do sau:
1. Cần một trạng từ để bổ nghĩa cho tính từ "obtainable".
2. "Easily obtainable" là cụm từ chỉ "dễ dàng có được".
3. Trạng từ phải đứng trước tính từ để bổ nghĩa.
4. Các đáp án khác không phù hợp: "easy" (tính từ), "ease" (danh từ), "easier" (tính từ so sánh hơn).
Dịch câu hỏi: Cô Chaney nói rằng cuốn sách dạy nấu ăn sắp tới của cô sẽ chỉ giới thiệu các món ăn được làm từ những nguyên liệu dễ tìm.
Dịch đáp án:
A. easily (trạng từ: dễ dàng)
B. easy (tính từ: dễ dàng)
C. ease (danh từ: sự dễ dàng)
D. easier (tính từ so sánh hơn: dễ dàng hơn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5657, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7105, 5657, 105, 'Emi Tanaka is supposed to start work on Monday, —-- Human Resources has not finished drafting her contract.', 'once', 'with', 'still', 'but', 'D', 'Đáp án D (but) là đúng vì các lý do sau:
1. Cần một liên từ chỉ sự tương phản.
2. "But" là liên từ nối hai mệnh đề có ý nghĩa trái ngược nhau.
3. Hai mệnh đề trong câu này có sự tương phản: sắp bắt đầu làm việc / chưa hoàn thành hợp đồng.
4. Các đáp án khác không phù hợp: "once" (một khi), "with" (với), "still" (vẫn).
Dịch câu hỏi: Emi Tanaka được cho là sẽ bắt đầu làm việc vào thứ Hai, nhưng phòng Nhân sự vẫn chưa hoàn thành việc soạn thảo hợp đồng của cô ấy.
Dịch đáp án:
A. once (liên từ: một khi)
B. with (giới từ: với)
C. still (trạng từ: vẫn)
D. but (liên từ: nhưng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5658, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7106, 5658, 106, '----- the maintenance department immediately of any spills in the laboratory.', 'Notify', 'Notified', 'Notifying', 'Notification', 'A', 'Đáp án A (Notify) là đúng vì các lý do sau:
1. Cần một động từ nguyên thể để bắt đầu câu mệnh lệnh.
2. "Notify" là động từ có nghĩa "thông báo".
3. Câu mệnh lệnh trong tiếng Anh bắt đầu bằng động từ nguyên thể.
4. Các đáp án khác không phù hợp: "Notified" (quá khứ), "Notifying" (hiện tại phân từ), "Notification" (danh từ).
Dịch câu hỏi: Hãy thông báo ngay cho bộ phận bảo trì về bất kỳ sự cố tràn đổ nào trong phòng thí nghiệm.
Dịch đáp án:
A. Notify (động từ: thông báo)
B. Notified (động từ quá khứ: đã thông báo)
C. Notifying (động từ ing: đang thông báo)
D. Notification (danh từ: sự thông báo)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5659, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7107, 5659, 107, 'The interior designer used certain colors ----- to create a warm atmosphere in the café''s seating area.', 'strategy', 'strategic', 'strategically', 'more strategic', 'C', 'Đáp án C (strategically) là đúng vì các lý do sau:
1. Cần một trạng từ để mô tả cách thức sử dụng màu sắc.
2. "Strategically" là trạng từ có nghĩa "một cách có chiến lược".
3. Trạng từ bổ nghĩa cho động từ "used".
4. Các đáp án khác không phù hợp: "strategy" (danh từ), "strategic" (tính từ), "more strategic" (tính từ so sánh hơn).
Dịch câu hỏi: Nhà thiết kế nội thất đã sử dụng một số màu sắc nhất định một cách có chiến lược để tạo bầu không khí ấm cúng trong khu vực ghế ngồi của quán café.
Dịch đáp án:
A. strategy (danh từ: chiến lược)
B. strategic (tính từ: có tính chiến lược)
C. strategically (trạng từ: một cách có chiến lược)
D. more strategic (tính từ so sánh hơn: có tính chiến lược hơn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5660, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7108, 5660, 108, '----- can be done to recover your files, since they were deleted over one year ago.', 'Either', 'Nothing', 'Nobody', 'Another', 'B', 'Đáp án B (Nothing) là đúng vì các lý do sau:
1. Cần một đại từ phủ định làm chủ ngữ của câu.
2. "Nothing" là đại từ phủ định có nghĩa "không có gì".
3. Phù hợp với ngữ cảnh về việc không thể phục hồi file đã xóa.
4. Các đáp án khác không phù hợp: "Either" (một trong hai), "Nobody" (không ai), "Another" (cái khác).
Dịch câu hỏi: Không thể làm gì để khôi phục các tệp tin của bạn, vì chúng đã bị xóa hơn một năm trước.
Dịch đáp án:
A. Either (đại từ: một trong hai)
B. Nothing (đại từ: không có gì)
C. Nobody (đại từ: không ai)
D. Another (tính từ: khác)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5661, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7109, 5661, 109, 'Your meals with clients will be reimbursed by the company ----- you submit the original receipts.', 'as long as', 'whether', 'afterward', 'in case', 'A', 'Đáp án A (as long as) là đúng vì các lý do sau:
1. Cần một cụm liên từ chỉ điều kiện.
2. "As long as" có nghĩa là "miễn là, với điều kiện là".
3. Cấu trúc này diễn tả điều kiện cần thiết để được hoàn tiền.
4. Các đáp án khác không phù hợp: "whether" (liệu có), "afterward" (sau đó), "in case" (phòng khi).
Dịch câu hỏi: Các bữa ăn của bạn với khách hàng sẽ được công ty hoàn tiền miễn là bạn nộp hóa đơn gốc.
Dịch đáp án:
A. as long as (cụm liên từ: miễn là)
B. whether (liên từ: liệu có)
C. afterward (trạng từ: sau đó)
D. in case (cụm giới từ: phòng khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5662, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7110, 5662, 110, 'After some -----, the board of directors decided to declare a dividend.', 'deliberates', 'deliberated', 'deliberately', 'deliberation', 'D', 'Đáp án D (deliberation) là đúng vì các lý do sau:
1. Cần một danh từ sau "some".
2. "Deliberation" là danh từ có nghĩa "sự cân nhắc, thảo luận".
3. "Some + danh từ" là cấu trúc phổ biến trong tiếng Anh.
4. Các đáp án khác không phù hợp: "deliberates" (động từ), "deliberated" (quá khứ), "deliberately" (trạng từ).
Dịch câu hỏi: Sau một số cân nhắc, hội đồng quản trị đã quyết định công bố cổ tức.
Dịch đáp án:
A. deliberates (động từ: cân nhắc)
B. deliberated (động từ quá khứ: đã cân nhắc)
C. deliberately (trạng từ: một cách cố ý)
D. deliberation (danh từ: sự cân nhắc)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5663, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7111, 5663, 111, 'Although the workshop''s participants were ----- from Busan, there were a few people from other areas as well.', 'entirely', 'repeatedly', 'primarily', 'overly', 'C', 'Đáp án C (primarily) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ tính chất chủ yếu, phần lớn.
2. "Primarily" có nghĩa là "chủ yếu, phần lớn".
3. Phù hợp với ngữ cảnh có một số ít người từ nơi khác.
4. Các đáp án khác không phù hợp: "entirely" (hoàn toàn), "repeatedly" (lặp đi lặp lại), "overly" (quá mức).
Dịch câu hỏi: Mặc dù người tham dự hội thảo chủ yếu đến từ Busan, cũng có một vài người từ các khu vực khác.
Dịch đáp án:
A. entirely (trạng từ: hoàn toàn)
B. repeatedly (trạng từ: lặp đi lặp lại)
C. primarily (trạng từ: chủ yếu)
D. overly (trạng từ: quá mức)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5664, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7112, 5664, 112, 'Weller Tower is a popular destination for tourists, mainly ----- the stunning view from its observation deck.', 'now that', 'just as', 'together with', 'because of', 'D', 'Đáp án D (because of) là đúng vì các lý do sau:
1. Cần một cụm giới từ chỉ nguyên nhân.
2. "Because of + danh từ" diễn tả nguyên nhân của sự việc.
3. Phù hợp với ngữ cảnh giải thích lý do tháp Weller thu hút khách du lịch.
4. Các đáp án khác không phù hợp về nghĩa và cấu trúc: "now that" (bây giờ thì), "just as" (giống như), "together with" (cùng với).
Dịch câu hỏi: Tháp Weller là điểm đến phổ biến của khách du lịch, chủ yếu là vì quang cảnh tuyệt đẹp từ sân quan sát của nó.
Dịch đáp án:
A. now that (cụm liên từ: bây giờ thì)
B. just as (cụm liên từ: giống như)
C. together with (cụm giới từ: cùng với)
D. because of (cụm giới từ: bởi vì)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5665, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7113, 5665, 113, 'Renting construction machinery from a local supplier would be more ----- than having ours shipped to and from the site.', 'efficiencies', 'efficiency', 'efficient', 'efficiently', 'C', 'Đáp án C (efficient) là đúng vì các lý do sau:
1. Cần một tính từ sau "more" để tạo dạng so sánh hơn.
2. "Efficient" là tính từ có nghĩa "hiệu quả".
3. Cấu trúc "more + tính từ + than" dùng để so sánh.
4. Các đáp án khác không phù hợp: "efficiencies" (danh từ số nhiều), "efficiency" (danh từ), "efficiently" (trạng từ).
Dịch câu hỏi: Thuê máy móc xây dựng từ nhà cung cấp địa phương sẽ hiệu quả hơn là vận chuyển máy móc của chúng ta đến và đi từ công trường.
Dịch đáp án:
A. efficiencies (danh từ số nhiều: hiệu quả)
B. efficiency (danh từ: hiệu quả)
C. efficient (tính từ: hiệu quả)
D. efficiently (trạng từ: một cách hiệu quả)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5666, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7114, 5666, 114, 'To preserve the artwork, museums often keep pieces from their permanent collections in storage ----- putting them on display.', 'aside from', 'rather than', 'even if', 'not only', 'B', 'Đáp án B (rather than) là đúng vì các lý do sau:
1. Cần một cụm từ chỉ sự lựa chọn thay thế.
2. "Rather than" có nghĩa là "thay vì".
3. Cấu trúc "rather than + V-ing" diễn tả sự lựa chọn giữa hai hành động.
4. Các đáp án khác không phù hợp: "aside from" (ngoài ra), "even if" (ngay cả khi), "not only" (không chỉ).
Dịch câu hỏi: Để bảo quản tác phẩm nghệ thuật, các bảo tàng thường giữ các tác phẩm từ bộ sưu tập thường trực trong kho thay vì trưng bày chúng.
Dịch đáp án:
A. aside from (cụm giới từ: ngoài ra)
B. rather than (cụm liên từ: thay vì)
C. even if (cụm liên từ: ngay cả khi)
D. not only (cụm phó từ: không chỉ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5667, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7115, 5667, 115, 'According to the Cordell Pottery Exhibition''s Web site, the entry fee will be ------ for Cordell residents.', 'waives', 'waiving', 'waived', 'waivers', 'C', 'Đáp án C (waived) là đúng vì các lý do sau:
1. Cần một quá khứ phân từ để tạo thành thể bị động.
2. "Will be waived" là dạng tương lai bị động.
3. "Waived" có nghĩa là "được miễn".
4. Các đáp án khác không phù hợp: "waives" (động từ hiện tại), "waiving" (hiện tại phân từ), "waivers" (danh từ số nhiều).
Dịch câu hỏi: Theo trang web của Triển lãm Gốm Cordell, phí vào cửa sẽ được miễn cho cư dân Cordell.
Dịch đáp án:
A. waives (động từ: miễn)
B. waiving (động từ ing: đang miễn)
C. waived (quá khứ phân từ: được miễn)
D. waivers (danh từ: sự miễn giảm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5668, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7116, 5668, 116, 'Government ----- in science and technology research have been important drivers of innovation in recent decades.', 'invests', 'investments', 'investor', 'invested', 'B', 'Đáp án B (investments) là đúng vì các lý do sau:
1. Cần một danh từ số nhiều làm chủ ngữ của câu.
2. "Investments" là danh từ số nhiều chỉ "những khoản đầu tư".
3. Động từ "have been" chia số nhiều phù hợp với chủ ngữ số nhiều.
4. Các đáp án khác không phù hợp: "invests" (động từ), "investor" (danh từ số ít), "invested" (quá khứ phân từ).
Dịch câu hỏi: Các khoản đầu tư của chính phủ vào nghiên cứu khoa học và công nghệ đã là động lực quan trọng cho sự đổi mới trong những thập kỷ gần đây.
Dịch đáp án:
A. invests (động từ: đầu tư)
B. investments (danh từ số nhiều: những khoản đầu tư)
C. investor (danh từ: nhà đầu tư)
D. invested (quá khứ phân từ: được đầu tư)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5669, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7117, 5669, 117, 'Proceeds from the fund-raiser will go ----- resurfacing the running track in Brant Park.', 'toward', 'through', 'about', 'over', 'A', 'Đáp án A (toward) là đúng vì các lý do sau:
1. Cần một giới từ chỉ mục đích sử dụng tiền.
2. "Go toward" là cụm từ phổ biến chỉ việc tiền được dùng cho mục đích gì.
3. Phù hợp với ngữ cảnh về việc sử dụng tiền gây quỹ.
4. Các đáp án khác không phù hợp: "through" (qua), "about" (về), "over" (trên).
Dịch câu hỏi: Tiền thu được từ việc gây quỹ sẽ được dùng để lát lại đường chạy ở Công viên Brant.
Dịch đáp án:
A. toward (giới từ: hướng tới)
B. through (giới từ: qua)
C. about (giới từ: về)
D. over (giới từ: trên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5670, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7118, 5670, 118, 'While it was ----, many fans were still saddened by Liam Kuhn''s announcement of his retirement from professional tennis.', 'allowed', 'expected', 'reduced', 'answered', 'B', 'Đáp án B (expected) là đúng vì các lý do sau:
1. Cần một quá khứ phân từ để tạo thành câu bị động.
2. "Was expected" diễn tả việc được mong đợi, dự đoán trước.
3. Phù hợp với ngữ cảnh về phản ứng của người hâm mộ.
4. Các đáp án khác không phù hợp về nghĩa: "allowed" (được cho phép), "reduced" (giảm), "answered" (trả lời).
Dịch câu hỏi: Mặc dù điều này đã được dự đoán trước, nhiều người hâm mộ vẫn buồn trước thông báo giải nghệ khỏi quần vợt chuyên nghiệp của Liam Kuhn.
Dịch đáp án:
A. allowed (quá khứ phân từ: được cho phép)
B. expected (quá khứ phân từ: được mong đợi)
C. reduced (quá khứ phân từ: bị giảm)
D. answered (quá khứ phân từ: được trả lời)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5671, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7119, 5671, 119, 'Due to unusually low attendance at the festival, the organizers were left with an ------ of 200 promotional T-shirts.', 'excessive', 'exceeding', 'excess', 'exceeds', 'C', 'Đáp án C (excess) là đúng vì các lý do sau:
1. Cần một danh từ chỉ số lượng thừa.
2. "Excess" là danh từ có nghĩa "số lượng dư thừa".
3. Cấu trúc "an excess of + số lượng" là cách diễn đạt phổ biến.
4. Các đáp án khác không phù hợp: "excessive" (tính từ), "exceeding" (động từ ing), "exceeds" (động từ).
Dịch câu hỏi: Do lượng khách tham dự lễ hội thấp bất thường, ban tổ chức còn thừa 200 áo phông quảng cáo.
Dịch đáp án:
A. excessive (tính từ: quá mức)
B. exceeding (động từ ing: vượt quá)
C. excess (danh từ: số lượng thừa)
D. exceeds (động từ: vượt quá)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5672, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7120, 5672, 120, 'Under the new time-off policy, employees may ----- to receive pay in exchange for their unused vacation days.', 'opt', 'promise', 'afford', 'bother', 'A', 'Đáp án A (opt) là đúng vì các lý do sau:
1. Cần một động từ chỉ sự lựa chọn hoặc quyết định.
2. "Opt" là động từ có nghĩa "chọn, quyết định".
3. "Opt to do something" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp về nghĩa: "promise" (hứa), "afford" (có khả năng), "bother" (làm phiền).
Dịch câu hỏi: Theo chính sách nghỉ phép mới, nhân viên có thể chọn nhận tiền thay cho những ngày nghỉ chưa sử dụng.
Dịch đáp án:
A. opt (động từ: chọn)
B. promise (động từ: hứa)
C. afford (động từ: có khả năng)
D. bother (động từ: làm phiền)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5673, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7121, 5673, 121, 'Wipeout, a new comedy series, will be released on the network''s streaming platform 24 hours ------ its broadcast TV premiere.', 'in front', 'by then', 'close to', 'ahead of', 'D', 'Đáp án D (ahead of) là đúng vì các lý do sau:
1. Cần một cụm giới từ chỉ thời gian trước một sự kiện.
2. "Ahead of" có nghĩa là "trước" về mặt thời gian.
3. Phù hợp với ngữ cảnh về lịch phát hành.
4. Các đáp án khác không phù hợp: "in front" (phía trước - về không gian), "by then" (đến lúc đó), "close to" (gần với).
Dịch câu hỏi: Wipeout, một series hài mới, sẽ được phát hành trên nền tảng streaming của mạng lưới 24 giờ trước buổi ra mắt trên TV phát sóng.
Dịch đáp án:
A. in front (cụm giới từ: phía trước)
B. by then (cụm giới từ: đến lúc đó)
C. close to (cụm giới từ: gần với)
D. ahead of (cụm giới từ: trước)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5674, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7122, 5674, 122, 'The hiring committee believes that Ms. Ahmed''s skills would nicely complement ------ of the existing members of the team.', 'those', 'theirs', 'them', 'which', 'A', 'Đáp án A (those) là đúng vì các lý do sau:
1. Cần một đại từ chỉ định thay thế cho "skills".
2. "Those" là đại từ chỉ định số nhiều.
3. Cấu trúc "those of + noun" dùng để chỉ sở hữu.
4. Các đáp án khác không phù hợp: "theirs" (của họ), "them" (họ), "which" (cái mà).
Dịch câu hỏi: Ủy ban tuyển dụng tin rằng kỹ năng của bà Ahmed sẽ bổ sung tốt cho những kỹ năng của các thành viên hiện tại trong nhóm.
Dịch đáp án:
A. those (đại từ chỉ định: những cái đó)
B. theirs (đại từ sở hữu: của họ)
C. them (đại từ tân ngữ: họ)
D. which (đại từ quan hệ: cái mà)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5675, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7123, 5675, 123, 'With each purchase, our customers earn points that can be used to receive discounts on ------ orders.', 'approximate', 'subsequent', 'inevitable', 'gradual', 'B', 'Đáp án B (subsequent) là đúng vì các lý do sau:
1. Cần một tính từ chỉ những đơn hàng tiếp theo.
2. "Subsequent" có nghĩa là "tiếp theo, sau đó".
3. Phù hợp với ngữ cảnh về việc sử dụng điểm để giảm giá cho các đơn hàng sau.
4. Các đáp án khác không phù hợp: "approximate" (gần đúng), "inevitable" (không thể tránh khỏi), "gradual" (dần dần).
Dịch câu hỏi: Với mỗi lần mua hàng, khách hàng của chúng tôi tích lũy điểm có thể được sử dụng để nhận giảm giá cho các đơn hàng tiếp theo.
Dịch đáp án:
A. approximate (tính từ: gần đúng)
B. subsequent (tính từ: tiếp theo)
C. inevitable (tính từ: không thể tránh khỏi)
D. gradual (tính từ: dần dần)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5676, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7124, 5676, 124, 'Among the strawberries available at the farmer''s market, the ones sold by Calkin Farms are the -----.', 'flavors', 'flavorful', 'most flavorful', 'most flavorfully', 'C', 'Đáp án C (most flavorful) là đúng vì các lý do sau:
1. Cần dạng so sánh nhất của tính từ.
2. "Most + tính từ" là cấu trúc so sánh nhất.
3. So sánh với tất cả các loại dâu khác trong chợ.
4. Các đáp án khác không phù hợp: "flavors" (danh từ), "flavorful" (tính từ thường), "most flavorfully" (trạng từ so sánh nhất).
Dịch câu hỏi: Trong số các loại dâu tây có bán tại chợ nông sản, những quả được bán bởi Trang trại Calkin có hương vị thơm ngon nhất.
Dịch đáp án:
A. flavors (danh từ: hương vị)
B. flavorful (tính từ: thơm ngon)
C. most flavorful (tính từ so sánh nhất: thơm ngon nhất)
D. most flavorfully (trạng từ so sánh nhất: một cách thơm ngon nhất)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5677, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7125, 5677, 125, 'After paying the licensing fee, you will be ----- the right to use this image for commercial purposes.', 'enforced', 'advised', 'renewed', 'granted', 'D', 'Đáp án D (granted) là đúng vì các lý do sau:
1. Cần một quá khứ phân từ để tạo thành thể bị động.
2. "Be granted" có nghĩa là "được cấp, được ban cho".
3. Phù hợp với ngữ cảnh về việc cấp quyền sử dụng hình ảnh.
4. Các đáp án khác không phù hợp: "enforced" (thực thi), "advised" (được tư vấn), "renewed" (được gia hạn).
Dịch câu hỏi: Sau khi trả phí bản quyền, bạn sẽ được cấp quyền sử dụng hình ảnh này cho mục đích thương mại.
Dịch đáp án:
A. enforced (quá khứ phân từ: được thực thi)
B. advised (quá khứ phân từ: được tư vấn)
C. renewed (quá khứ phân từ: được gia hạn)
D. granted (quá khứ phân từ: được cấp)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5678, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7126, 5678, 126, 'Mr. Song ----- the market research study even before sales of our products began their recent decline.', 'was commissioned', 'is commissioning', 'to be commissioning', 'had commissioned', 'D', 'Đáp án D (had commissioned) là đúng vì các lý do sau:
1. Cần thì quá khứ hoàn thành để chỉ hành động xảy ra trước một thời điểm trong quá khứ.
2. "Had commissioned" diễn tả việc ủy quyền nghiên cứu xảy ra trước khi doanh số giảm.
3. Cấu trúc thì quá khứ hoàn thành (had + past participle) phù hợp với ngữ cảnh.
4. Các đáp án khác không phù hợp về thì: "was commissioned" (bị động quá khứ), "is commissioning" (hiện tại tiếp diễn), "to be commissioning" (nguyên mẫu).
Dịch câu hỏi: Ông Song đã ủy quyền nghiên cứu thị trường thậm chí trước khi doanh số sản phẩm của chúng tôi bắt đầu suy giảm gần đây.
Dịch đáp án:
A. was commissioned (bị động quá khứ: đã được ủy quyền)
B. is commissioning (hiện tại tiếp diễn: đang ủy quyền)
C. to be commissioning (nguyên mẫu: để ủy quyền)
D. had commissioned (quá khứ hoàn thành: đã ủy quyền)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5679, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7127, 5679, 127, 'Kenyon XN-30 sport sunglasses come with four ----- sets of lenses to suit a variety of lighting conditions.', 'instant', 'interchangeable', 'concentrated', 'relative', 'B', 'Đáp án B (interchangeable) là đúng vì các lý do sau:
1. Cần một tính từ chỉ khả năng thay thế, hoán đổi.
2. "Interchangeable" có nghĩa là "có thể thay thế cho nhau".
3. Phù hợp với ngữ cảnh về các bộ lens có thể thay đổi.
4. Các đáp án khác không phù hợp: "instant" (tức thì), "concentrated" (tập trung), "relative" (tương đối).
Dịch câu hỏi: Kính mát thể thao Kenyon XN-30 đi kèm với bốn bộ lens có thể thay thế cho nhau để phù hợp với nhiều điều kiện ánh sáng khác nhau.
Dịch đáp án:
A. instant (tính từ: tức thì)
B. interchangeable (tính từ: có thể thay thế)
C. concentrated (tính từ: tập trung)
D. relative (tính từ: tương đối)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5680, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7128, 5680, 128, 'With proper care, the shrubs planted along your walkway will ----- reach a height of three feet.', 'patiently', 'considerably', 'exactly', 'eventually', 'D', 'Đáp án D (eventually) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ thời gian trong tương lai.
2. "Eventually" có nghĩa là "cuối cùng thì, rốt cuộc".
3. Phù hợp với ngữ cảnh về sự phát triển dần dần của cây.
4. Các đáp án khác không phù hợp: "patiently" (kiên nhẫn), "considerably" (đáng kể), "exactly" (chính xác).
Dịch câu hỏi: Với sự chăm sóc đúng cách, những bụi cây được trồng dọc lối đi của bạn cuối cùng sẽ đạt đến chiều cao ba feet.
Dịch đáp án:
A. patiently (trạng từ: kiên nhẫn)
B. considerably (trạng từ: đáng kể)
C. exactly (trạng từ: chính xác)
D. eventually (trạng từ: cuối cùng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5681, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7129, 5681, 129, 'Although there is no maximum word limit for articles in our journal, we recommend that authors keep their manuscripts as ----- as possible.', 'accurate', 'orderly', 'distinctive', 'succinct', 'D', 'Đáp án D (succinct) là đúng vì các lý do sau:
1. Cần một tính từ chỉ sự ngắn gọn, súc tích.
2. "Succinct" có nghĩa là "súc tích, ngắn gọn".
3. Cấu trúc "as + tính từ + as possible" diễn tả mức độ tối đa có thể.
4. Các đáp án khác không phù hợp: "accurate" (chính xác), "orderly" (có trật tự), "distinctive" (đặc biệt).
Dịch câu hỏi: Mặc dù không có giới hạn từ tối đa cho các bài báo trong tạp chí của chúng tôi, chúng tôi khuyến nghị các tác giả giữ bản thảo của họ súc tích nhất có thể.
Dịch đáp án:
A. accurate (tính từ: chính xác)
B. orderly (tính từ: có trật tự)
C. distinctive (tính từ: đặc biệt)
D. succinct (tính từ: súc tích)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5682, 250, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7130, 5682, 130, 'The ability to pay close attention to detail is an important ----- that all medical translators must have.', 'trait', 'outcome', 'record', 'practice', 'A', 'Đáp án A (trait) là đúng vì các lý do sau:
1. Cần một danh từ chỉ đặc điểm, phẩm chất của con người.
2. "Trait" có nghĩa là "đặc điểm, nét tính cách".
3. Phù hợp với ngữ cảnh về phẩm chất cần thiết của người dịch thuật y khoa.
4. Các đáp án khác không phù hợp: "outcome" (kết quả), "record" (hồ sơ), "practice" (thực hành).
Dịch câu hỏi: Khả năng chú ý tỉ mỉ đến chi tiết là một đặc điểm quan trọng mà tất cả các biên dịch viên y khoa phải có.
Dịch đáp án:
A. trait (danh từ: đặc điểm)
B. outcome (danh từ: kết quả)
C. record (danh từ: hồ sơ)
D. practice (danh từ: thực hành)');;

-- Data for 2025 Test6 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5683, 251, NULL, NULL, 'http://www.ncgovparks.org/ufc
Urban Family Camping
The Nieves City Parks Department organizes urban family camping events so that local children can experience the fun of camping 131...... in their own city. At each campout, park rangers host a limited number of families for an overnight stay in one of Nieves''s beautiful parks. There is also usually an extra activity, such as a barbecue dinner, a ranger-led evening hike, or a session of storytelling around the campfire. To make participation widely accessible, the Parks Department even provides the tents and most other necessary items. 132........ .
The urban family camping 133...... is extremely popular. 134....... families are advised to sign up for their desired campout as soon as registration opens each spring.', 'Trang web Urban Family Camping
Sở Công viên Thành phố Nieves tổ chức các sự kiện cắm trại gia đình trong thành phố để trẻ em địa phương có thể trải nghiệm niềm vui cắm trại 131...... ngay tại thành phố của mình. Tại mỗi đợt cắm trại, kiểm lâm viên đón tiếp một số lượng gia đình giới hạn để ở lại qua đêm tại một trong những công viên xinh đẹp của Nieves. Thường cũng có một hoạt động bổ sung, như tiệc nướng BBQ, đi bộ đường dài buổi tối có hướng dẫn viên, hoặc kể chuyện quanh lửa trại. Để việc tham gia được dễ dàng hơn, Sở Công viên thậm chí còn cung cấp lều và hầu hết các vật dụng cần thiết khác. 132........ .
Chương trình cắm trại gia đình trong thành phố 133...... rất được ưa chuộng. 134....... các gia đình được khuyên đăng ký đợt cắm trại mong muốn ngay khi việc đăng ký mở ra mỗi mùa xuân.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7131, 5683, 131, NULL, 'there', 'like', 'just', 'right', 'D', 'A. there (ở đó - trạng từ chỉ nơi chốn)
B. like (như - giới từ)
C. just (chỉ - phó từ)
D. right (ngay - phó từ)
Đáp án đúng là D (right).
Giải thích:
1. Ngữ cảnh: "right in their own city" nhấn mạnh vị trí gần
2. "Right" phù hợp vì:
- Nhấn mạnh địa điểm ngay tại thành phố
- Kết hợp với "in" tạo cụm "right in"
3. Các đáp án khác không phù hợp vì:
- "There" thừa khi đã có "in their own city"
- "Like" không phù hợp về nghĩa
- "Just" không nhấn mạnh được vị trí');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7132, 5683, 132, NULL, 'All that each camper needs to bring is a sleeping bag and toiletries.', 'It also holds many daytime events for families at its parks.', 'Camping is a great way to foster a lifelong love of nature in children.', 'See the calendar below for the dates of all upcoming campouts.', 'A', 'A. All that each camper needs to bring is a sleeping bag and toiletries (Tất cả những gì mỗi người cắm trại cần mang là túi ngủ và đồ vệ sinh cá nhân)
B. It also holds many daytime events for families at its parks (Nó cũng tổ chức nhiều sự kiện ban ngày cho các gia đình tại các công viên)
C. Camping is a great way to foster a lifelong love of nature in children (Cắm trại là cách tuyệt vời để nuôi dưỡng tình yêu thiên nhiên suốt đời ở trẻ em)
D. See the calendar below for the dates of all upcoming campouts (Xem lịch bên dưới để biết ngày của tất cả các đợt cắm trại sắp tới)
Đáp án đúng là A vì:
1. Liên kết với câu trước về việc cung cấp thiết bị
2. Cung cấp thông tin cụ thể về những gì cần mang theo
3. Các đáp án khác không phù hợp vì:
- B không liên quan đến chủ đề thiết bị
- C là nhận xét chung chung
- D chưa phù hợp vị trí');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7133, 5683, 133, NULL, 'facility', 'leader', 'program', 'equipment', 'C', 'A. facility (cơ sở vật chất - danh từ)
B. leader (người lãnh đạo - danh từ)
C. program (chương trình - danh từ)
D. equipment (thiết bị - danh từ)
Đáp án đúng là C (program).
Giải thích:
1. Ngữ cảnh: Cần danh từ chỉ hoạt động tổng thể
2. "Program" phù hợp vì:
- Chỉ toàn bộ chương trình cắm trại
- Bao gồm các hoạt động đã nêu
3. Các đáp án khác không phù hợp:
- "Facility" chỉ nơi tổ chức
- "Leader" không phù hợp ngữ cảnh
- "Equipment" chỉ thiết bị');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7134, 5683, 134, NULL, 'Interested', 'Interesting', 'Interestingly', 'To interest', 'A', 'A. Interested (quan tâm - tính từ)
B. Interesting (thú vị - tính từ)
C. Interestingly (thú vị - trạng từ)
D. To interest (để thu hút - động từ nguyên mẫu)
Đáp án đúng là A (Interested).
Giải thích:
1. Cấu trúc: Cần tính từ bổ nghĩa cho "families"
2. "Interested" phù hợp vì:
- Mô tả các gia đình muốn tham gia
- Dùng làm tính từ trước danh từ
3. Các đáp án khác không phù hợp:
- "Interesting" là chủ động, không phù hợp
- "Interestingly" là trạng từ
- "To interest" là động từ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5684, 251, NULL, NULL, 'BURENNA (February 5)-Today, TCN Hospitality Group withdrew its proposal to build a combined conference center and hotel on Worth Street. The complex 135...... over 200 guest rooms and 70,000 square feet of conference space.
Burenna citizens voiced 136...... to the plan at an informational meeting last Thursday. Several residents expressed concern that the chosen site would be unable to handle a large increase in traffic. 137....... . The day after the meeting, three city council members also indicated that they would vote against the proposal.
According to its withdrawal statement, TCN has not given up on the idea of building a conference center and hotel complex in Burenna. 138......., the scale of the complex is likely to be more modest in any future proposals.', 'BURENNA (ngày 5 tháng 2) - Hôm nay, TCN Hospitality Group đã rút lại đề xuất xây dựng một trung tâm hội nghị và khách sạn kết hợp trên Phố Worth. Khu phức hợp 135...... hơn 200 phòng khách và 70.000 feet vuông không gian hội nghị.
Công dân Burenna đã lên tiếng 136...... cho kế hoạch tại một cuộc họp thông tin vào thứ Năm tuần trước. Một số cư dân bày tỏ lo ngại rằng địa điểm được chọn sẽ không thể xử lý sự gia tăng lưu lượng truy cập lớn. 137....... . Một ngày sau cuộc họp, ba thành viên hội đồng thành phố cũng cho biết họ sẽ bỏ phiếu chống lại đề xuất.
Theo tuyên bố rút lui, TCN đã không từ bỏ ý tưởng xây dựng một trung tâm hội nghị và khu phức hợp khách sạn ở Burenna. 138......., quy mô của khu phức hợp có thể sẽ khiêm tốn hơn trong bất kỳ đề xuất nào trong tương lai.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7135, 5684, 135, NULL, 'includes', 'will include', 'would have included', 'would include', 'C', 'A. includes (bao gồm - hiện tại đơn)
B. will include (sẽ bao gồm - tương lai đơn)
C. would have included (đáng lẽ đã bao gồm - điều kiện hoàn thành)
D. would include (sẽ bao gồm - điều kiện đơn)
Đáp án đúng là C (would have included).
Giải thích:
1. Ngữ cảnh: Đề xuất đã bị rút lại
2. "Would have included" phù hợp vì:
- Diễn tả điều không xảy ra trong quá khứ
- Phù hợp với việc dự án bị hủy
3. Các đáp án khác không phù hợp vì:
- "Includes" không phù hợp thời điểm
- "Will include" không thể xảy ra
- "Would include" thiếu tính hoàn thành');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7136, 5684, 136, NULL, 'difficulty', 'opposition', 'disapproval', 'obstruction', 'B', 'A. difficulty (khó khăn - danh từ)
B. opposition (sự phản đối - danh từ)
C. disapproval (sự không tán thành - danh từ)
D. obstruction (sự cản trở - danh từ)
Đáp án đúng là B (opposition).
Giải thích:
1. Ngữ cảnh: Phản ứng tiêu cực của người dân
2. "Opposition" phù hợp vì:
- Chỉ sự phản đối mạnh mẽ, tập thể
- Phù hợp với phản ứng của cộng đồng
3. Các đáp án khác không phù hợp vì:
- "Difficulty" quá nhẹ
- "Disapproval" thiếu tính tập thể
- "Obstruction" quá mạnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7137, 5684, 137, NULL, 'The location is the former home of Ellis Department Store.', 'Others objected to the city''s planned financial role in the project.', 'To accommodate it, Worth Street will be widened to six lanes.', 'TCN has opened major complexes in two other cities in recent years.', 'B', 'A. The location is the former home of Ellis Department Store (thông tin về vị trí cũ)
B. Others objected to the city''s planned financial role in the project (phản đối về tài chính)
C. To accommodate it, Worth Street will be widened to six lanes (kế hoạch mở rộng đường)
D. TCN has opened major complexes in two other cities in recent years (thông tin về dự án khác)
Đáp án đúng là B vì:
1. Bổ sung lý do phản đối thứ hai
2. Liên kết với mối quan ngại về giao thông
3. Các đáp án khác không phù hợp vì:
- A không liên quan đến phản đối
- C là giải pháp chưa được đề cập
- D không liên quan đến vấn đề');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7138, 5684, 138, NULL, 'However', 'Similarly', 'In fact', 'Instead', 'A', 'A. However (tuy nhiên - liên từ)
B. Similarly (tương tự - trạng từ)
C. In fact (thực tế - cụm từ)
D. Instead (thay vào đó - trạng từ)
Đáp án đúng là A (However).
Giải thích:
1. Ngữ cảnh: Tương phản giữa hai ý
2. "However" phù hợp vì:
- Nối hai ý đối lập
- TCN vẫn muốn xây nhưng quy mô nhỏ hơn
3. Các đáp án khác không phù hợp vì:
- "Similarly" không thể hiện được sự thay đổi
- "In fact" không diễn tả được tương phản
- "Instead" không phù hợp ngữ cảnh');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5685, 251, NULL, NULL, 'Attention, Penny''s Grill staff:
The restaurant will be getting a new point-of-sale and order management system next week. Technicians will come on our weekly day off, Monday, to do the installation and 139...... our managers how to use the system. Dana and Ivan will then lead simultaneous training sessions for all dining room and kitchen staff on Tuesday morning. 140......... . We need to get started that early in order to ensure that employees working normal shifts on Tuesday are fully prepared by the time lunch service 141..... at 11.
Please let Dana know promptly if you are unavailable on Tuesday morning. We may arrange 142..... training sessions if necessary.', 'Thông báo, nhân viên Penny''s Grill:
Nhà hàng sẽ có hệ thống quản lý điểm bán hàng và đơn hàng mới vào tuần tới. Các kỹ thuật viên sẽ đến vào ngày nghỉ hàng tuần của chúng ta, thứ Hai, để lắp đặt và 139...... các quản lý của chúng ta cách sử dụng hệ thống. Dana và Ivan sau đó sẽ dẫn dắt các buổi đào tạo đồng thời cho tất cả nhân viên phòng ăn và nhà bếp vào sáng thứ Ba. 140......... . Chúng ta cần bắt đầu sớm như vậy để đảm bảo rằng nhân viên làm ca thông thường vào thứ Ba được chuẩn bị đầy đủ trước khi dịch vụ bữa trưa 141..... lúc 11 giờ.
Vui lòng cho Dana biết ngay nếu bạn không thể tham gia vào sáng thứ Ba. Chúng tôi có thể sắp xếp các buổi đào tạo 142..... nếu cần thiết.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7139, 5685, 139, NULL, 'support', 'teach', 'explain', 'introduce', 'B', 'A. support (hỗ trợ - động từ)
B. teach (dạy - động từ)
C. explain (giải thích - động từ)
D. introduce (giới thiệu - động từ)
Đáp án đúng là B (teach).
Giải thích:
1. Cấu trúc: "teach somebody how to do something"
2. "Teach" phù hợp vì:
- Diễn tả việc hướng dẫn chi tiết
- Thường dùng với "how to"
3. Các đáp án khác không phù hợp vì:
- "Support" không đi với "how to"
- "Explain" ít chính thức hơn
- "Introduce" quá hời hợt');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7140, 5685, 140, NULL, 'Fortunately, the system is largely similar to our current one.', 'Likewise, the servers must learn to input orders on tablets.', 'They will update the relevant sections of our handbook as well.', 'Everyone has been scheduled for a special shift at 8 A.M.', 'D', 'A. Fortunately, the system is largely similar to our current one (thông tin về độ tương đồng)
B. Likewise, the servers must learn to input orders on tablets (thông tin về nhiệm vụ)
C. They will update the relevant sections of our handbook as well (thông tin về cập nhật tài liệu)
D. Everyone has been scheduled for a special shift at 8 A.M. (thông tin về lịch làm việc)
Đáp án đúng là D vì:
1. Phù hợp với mạch văn về đào tạo
2. Cung cấp thông tin cụ thể về thời gian
3. Các đáp án khác không phù hợp vì:
- A không liên quan đến việc đào tạo
- B và C là thông tin phụ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7141, 5685, 141, NULL, 'begins', 'to begin', 'beginning', 'that begins', 'A', 'A. begins (bắt đầu - động từ hiện tại đơn)
B. to begin (để bắt đầu - động từ nguyên mẫu)
C. beginning (bắt đầu - danh động từ)
D. that begins (mà bắt đầu - mệnh đề quan hệ)
Đáp án đúng là A (begins).
Giải thích:
1. Cấu trúc: Mệnh đề thời gian với "by the time"
2. "Begins" phù hợp vì:
- Là động từ chính trong mệnh đề
- Thì hiện tại đơn cho lịch trình
3. Các đáp án khác không phù hợp về ngữ pháp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7142, 5685, 142, NULL, 'regular', 'internal', 'additional', 'advanced', 'C', 'A. regular (thường xuyên - tính từ)
B. internal (nội bộ - tính từ)
C. additional (bổ sung - tính từ)
D. advanced (nâng cao - tính từ)
Đáp án đúng là C (additional).
Giải thích:
1. Ngữ cảnh:
- Đang nói về việc sắp xếp thêm buổi đào tạo
- Dành cho nhân viên không thể tham gia buổi chính
2. "Additional" phù hợp nhất vì:
- Là tính từ chỉ sự bổ sung, thêm vào cái đã có
- Thường dùng trong các tình huống cần thêm lịch, buổi học
- Phù hợp với mục đích tổ chức thêm buổi cho người vắng mặt
3. Các đáp án khác không phù hợp vì:
- "Regular" (thường xuyên) không phải là buổi bổ sung
- "Internal" (nội bộ) không cần thiết vì đã hiển nhiên là cho nhân viên
- "Advanced" (nâng cao) không phù hợp vì cùng một nội dung đào tạo
4. Cấu trúc ngữ pháp:
- Cần một tính từ bổ nghĩa cho cụm "training sessions"
- "Additional training sessions" là cụm từ phổ biến trong bối cảnh đào tạo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5686, 251, NULL, NULL, 'From: <enewsletter@pattersonlibrary.org>
To: Noel Higgins <n.higgins@yow-mail.com>
Subject: Patterson Public Library
Date: September 19
Dear Patron,
Thank you for joining the mailing list for the Patterson Public Library''s electronic newsletter. We are excited to begin updating you about important changes, upcoming events, and services on offer at the library.
As the newsletter is published twice per month, you should receive your first issue within three weeks. 143....... . If you do not begin receiving the newsletter as expected, please contact our help desk staff at 555-0166. Requests to change your preferred receiving address or be removed from the mailing list can also be directed to 144...... .
Would you like to hear more from the library? We also publish Patterson''s Picks, a monthly e-mail that features book 145..... from our librarians. Visit www.patterson ibrary.org/pp to 146...... .', 'Từ: <enewsletter@pattersonlibrary.org>
Đến: Noel Higgins <n.higgins@yow-mail.com>
Chủ đề: Thư viện Công cộng Patterson
Ngày: 19 tháng 9
Kính gửi Độc giả,
Cảm ơn bạn đã tham gia danh sách gửi thư cho bản tin điện tử của Thư viện Công cộng Patterson. Chúng tôi rất vui mừng được bắt đầu cập nhật cho bạn về những thay đổi quan trọng, sự kiện sắp tới và các dịch vụ được cung cấp tại thư viện.
Vì bản tin được xuất bản hai lần mỗi tháng, bạn sẽ nhận được số đầu tiên trong vòng ba tuần. 143....... . Nếu bạn không bắt đầu nhận được bản tin như dự kiến, vui lòng liên hệ với nhân viên bộ phận trợ giúp của chúng tôi theo số 555-0166. Yêu cầu thay đổi địa chỉ nhận ưu tiên của bạn hoặc xóa khỏi danh sách gửi thư cũng có thể được chuyển đến 144...... .
Bạn có muốn nghe thêm từ thư viện không? Chúng tôi cũng xuất bản Patterson''s Picks, một email hàng tháng giới thiệu sách 145..... từ các thủ thư của chúng tôi. Truy cập www.pattersonlibrary.org/pp để 146...... .');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7143, 5686, 143, NULL, 'We put a lot of care into crafting the contents.', 'Our readership ranges from teenagers to retirees.', 'Each issue will be sent via e-mail to this address.', 'Previous issues are available on our Web site.', 'C', 'A. We put a lot of care into crafting the contents (chúng tôi rất chú trọng đến việc tạo nội dung - câu khẳng định)
B. Our readership ranges from teenagers to retirees (độc giả của chúng tôi từ thiếu niên đến người về hưu - thông tin về độc giả)
C. Each issue will be sent via e-mail to this address (mỗi số sẽ được gửi qua email đến địa chỉ này - thông tin về phương thức gửi)
D. Previous issues are available on our Web site (các số trước có sẵn trên trang web - thông tin về số cũ)
Đáp án đúng là C vì:
1. Ngữ cảnh:
- Đang nói về việc gửi bản tin cho người đăng ký mới
- Cần thông tin về cách thức nhận bản tin
2. "Each issue will be sent via e-mail" phù hợp vì:
- Cung cấp thông tin cụ thể về phương thức gửi
- Xác nhận địa chỉ email sẽ nhận bản tin
- Liên kết với câu trước về thời gian nhận số đầu tiên
3. Các đáp án khác không phù hợp vì:
- A nói về nội dung, chưa cần thiết ở đây
- B là thông tin không liên quan đến việc gửi nhận
- D không quan trọng với độc giả mới
4. Tính liên kết văn bản:
- Thông tin về email phù hợp với ngữ cảnh đăng ký
- Giúp người đọc biết cách nhận bản tin');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7144, 5686, 144, NULL, 'me', 'him', 'one', 'them', 'D', 'A. me (tôi - đại từ nhân xưng ngôi thứ nhất số ít)
B. him (anh ấy - đại từ nhân xưng ngôi thứ ba số ít)
C. one (một người - đại từ bất định)
D. them (họ - đại từ nhân xưng ngôi thứ ba số nhiều)
Đáp án đúng là D (them).
Giải thích:
1. Ngữ cảnh:
- Đề cập đến việc chuyển các yêu cầu đến nhân viên help desk
- "Help desk staff" là chủ thể được thay thế
2. "Them" phù hợp nhất vì:
- Là đại từ số nhiều thay thế cho nhóm nhân viên
- Tham chiếu đến "help desk staff" đã đề cập trước đó
- Giữ tính chuyên nghiệp trong giao tiếp
3. Các đáp án khác không phù hợp vì:
- "Me" mang tính cá nhân, không phù hợp văn phong công việc
- "Him" là số ít, không thể thay thế cho nhóm nhân viên
- "One" không dùng để thay thế cho một nhóm người cụ thể
4. Quy tắc ngữ pháp:
- Đại từ phải phù hợp về số với danh từ được thay thế
- "Staff" là danh từ tập hợp, cần đại từ số nhiều');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7145, 5686, 145, NULL, 'recommends', 'recommended', 'recommendation', 'recommendations', 'D', 'A. recommends (giới thiệu - động từ hiện tại đơn, ngôi thứ 3 số ít)
B. recommended (được giới thiệu - quá khứ phân từ/động từ quá khứ)
C. recommendation (lời giới thiệu - danh từ số ít)
D. recommendations (những lời giới thiệu - danh từ số nhiều)
Đáp án đúng là D (recommendations).
Giải thích:
1. Cấu trúc ngữ pháp:
- Cần một danh từ sau "book" để tạo cụm danh từ
- "Book recommendations" là cụm từ hoàn chỉnh, phổ biến
2. "Recommendations" phù hợp nhất vì:
- Là danh từ số nhiều, chỉ nhiều lời giới thiệu sách
- Phản ánh việc có nhiều sách được giới thiệu
- Thường dùng trong ngữ cảnh thư viện và sách
3. Các đáp án khác không phù hợp vì:
- "Recommends" là động từ, không thể đứng sau danh từ
- "Recommended" là tính từ/động từ, không phù hợp ngữ cảnh
- "Recommendation" số ít, không phù hợp với thực tế nhiều sách
4. Tính liên kết nội dung:
- Phù hợp với bản tin hàng tháng về sách
- Thể hiện đặc điểm của dịch vụ "Patterson''s Picks"');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7146, 5686, 146, NULL, 'donate', 'subscribe', 'volunteer', 'enter', 'B', 'A. donate (quyên góp - động từ)
B. subscribe (đăng ký - động từ)
C. volunteer (tình nguyện - động từ)
D. enter (tham gia - động từ)
Đáp án đúng là B (subscribe).
Giải thích:
1. Ngữ cảnh:
- Mời độc giả đăng ký thêm dịch vụ của thư viện
- Liên quan đến việc nhận thông tin định kỳ
2. "Subscribe" phù hợp nhất vì:
- Là động từ chuyên dụng cho việc đăng ký dịch vụ thông tin
- Thường dùng cho các dịch vụ định kỳ như bản tin, tạp chí
- Phù hợp với tính chất của "Patterson''s Picks"
3. Các đáp án khác không phù hợp vì:
- "Donate" không liên quan đến việc nhận thông tin
- "Volunteer" không phù hợp với ngữ cảnh đăng ký dịch vụ
- "Enter" quá chung chung, không chuyên dụng cho đăng ký
4. Cấu trúc ngữ pháp và thành ngữ:
- "Subscribe to" là cụm động từ thường dùng
- Website thường dùng "subscribe" cho các dịch vụ newsletter');;

-- Data for 2025 Test6 Part 7
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5687, 252, NULL, NULL, 'The Dominica Advanced Steam Iron includes an auto-clean system to keep the water tank and steam vents free of mineral buildup.
To use this feature, begin by filling the water tank. Plug in the iron, and turn the steam dial to the highest setting. After allowing the iron to heat up for two minutes, unplug it. Hold the iron face down over a sink and press the "Auto-Clean" button. Hot water and steam will be released through the steam vents. Continue holding down the button until the tank has been completely emptied.', 'Bàn ủi hơi nước Dominica Advanced bao gồm hệ thống tự động làm sạch để giữ cho bình chứa nước và lỗ thông hơi không bị tích tụ khoáng chất.
Để sử dụng tính năng này, hãy bắt đầu bằng cách đổ đầy bình chứa nước. Cắm bàn ủi và xoay mặt số hơi nước về cài đặt cao nhất. Sau khi để bàn ủi nóng lên trong hai phút, hãy rút phích cắm. Giữ bàn ủi úp xuống trên bồn rửa và nhấn nút "Tự động làm sạch". Nước nóng và hơi nước sẽ được giải phóng qua các lỗ thông hơi. Tiếp tục giữ nút cho đến khi bể được làm trống hoàn toàn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7147, 5687, 147, 'Where would the information most likely be found?', 'In a print advertisement', 'In an online customer review', 'In a notice on a company''s Web site', 'On a page of a product manual', 'D', 'Đáp án đúng là D.
Giải thích:
Văn bản cung cấp hướng dẫn chi tiết từng bước về cách sử dụng tính năng tự động làm sạch, điều này điển hình cho sách hướng dẫn sử dụng sản phẩm.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Thông tin này nhiều khả năng được tìm thấy ở đâu?
A. Trong một quảng cáo in
B. Trong đánh giá của khách hàng trực tuyến
C. Trong thông báo trên trang web của công ty
D. Trên một trang của sách hướng dẫn sản phẩm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7148, 5687, 148, 'What is indicated about the auto-cleaning process?', 'It takes approximately two minutes', 'It involves a particular cleaning fluid', 'It requires the use of an electrical outlet', 'The iron should not be touched while it is taking place', 'C', 'Đáp án đúng là C.
Giải thích:
Theo hướng dẫn, quy trình yêu cầu cắm bàn ủi vào ổ điện: "Plug in the iron" để làm nóng trong hai phút trước khi bắt đầu quá trình tự làm sạch.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về quy trình tự động làm sạch?
A. Nó mất khoảng hai phút
B. Nó liên quan đến một loại chất tẩy rửa đặc biệt
C. Nó yêu cầu sử dụng ổ cắm điện
D. Không nên chạm vào bàn ủi trong quá trình này');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5688, 252, NULL, NULL, 'Cape Town Entrepreneurship Hall of Fame
The Rondebosch University Centre for Innovation (RUCI) is seeking nominations of local business leaders for induction into the Cape Town Entrepreneurship Hall of Fame. The honour is meant to recognise the achievements of the city''s business community and inspire the next generation of entrepreneurs. Past inductees include Willem Van Rooyen, Imka Kabera, and Grant Twigg. This year, the RUCI will choose ten nominees for induction at a ceremony planned for 14 June.
To be considered, nominees must:
Be the CEO of a private or public company headquartered in the City of Cape Town
Have held that position at the time of the company''s founding and for no fewer than three years in total
Have shown outstanding abilities in one or more of the following areas: innovation, profitability, employment generation, other positive community impact
Visit www.ronu.ac.za/ruci/ctehf to download the nomination form.
Submissions must be made by 5 p.M. on 1 May.', 'Đại sảnh Danh vọng Doanh nhân Cape Town
Trung tâm Đổi mới Đại học Rondebosch (RUCI) đang tìm kiếm các đề cử của các nhà lãnh đạo doanh nghiệp địa phương để giới thiệu vào Đại sảnh Danh vọng Doanh nhân Cape Town. Vinh dự này nhằm ghi nhận những thành tựu của cộng đồng doanh nghiệp thành phố và truyền cảm hứng cho thế hệ doanh nhân tiếp theo. Những người được giới thiệu trước đây bao gồm Willem Van Rooyen, Imka Kabera và Grant Twigg. Năm nay, RUCI sẽ chọn mười ứng cử viên để giới thiệu tại một buổi lễ được lên kế hoạch vào ngày 14 tháng Sáu.
Để được xem xét, những người được đề cử phải:
Là Giám đốc điều hành của một công ty tư nhân hoặc đại chúng có trụ sở tại Thành phố Cape TownĐã giữ vị trí đó tại thời điểm thành lập công ty và tổng cộng không dưới ba năm
Đã thể hiện khả năng xuất sắc trong một hoặc nhiều lĩnh vực sau: đổi mới, lợi nhuận, tạo việc làm, tác động tích cực khác đến cộng đồng
 Truy cập www.ronu.ac.za/ruci/ctehf để tải xuống mẫu đề cử.
Bài nộp phải được thực hiện trước 5 giờ chiều ngày 1 tháng 5.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7149, 5688, 149, 'What information is included in the announcement?', 'What benefits Hall of Fame members receive', 'What the purpose of the Hall of Fame is', 'Where nominations should be submitted', 'Who is allowed to submit a nomination', 'B', 'Đáp án đúng là B.
Giải thích:
Thông báo nêu rõ mục đích của Hall of Fame là "to recognise the achievements of the city''s business community and inspire the next generation of entrepreneurs" (để ghi nhận thành tựu của cộng đồng doanh nghiệp thành phố và truyền cảm hứng cho thế hệ doanh nhân tiếp theo).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Thông tin nào được bao gồm trong thông báo?
A. Những lợi ích mà thành viên Hall of Fame nhận được
B. Mục đích của Hall of Fame là gì
C. Nơi nộp đề cử
D. Ai được phép nộp đề cử');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7150, 5688, 150, 'What can be concluded about Ms. Kabera?', 'She was a CEO for at least three years', 'She graduated from Rondebosch University', 'She will attend a special event in June', 'She is a past employee of the RUCI', 'A', 'Đáp án đúng là A.
Giải thích:
Ms. Kabera được liệt kê là một trong những người được vinh danh trước đây. Để được vinh danh, người được đề cử phải là CEO trong ít nhất ba năm. Do đó, có thể kết luận Ms. Kabera đã từng là CEO trong ít nhất ba năm.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì có thể kết luận về Ms. Kabera?
A. Cô ấy đã là CEO trong ít nhất ba năm
B. Cô ấy tốt nghiệp từ Đại học Rondebosch
C. Cô ấy sẽ tham dự một sự kiện đặc biệt vào tháng 6
D. Cô ấy là cựu nhân viên của RUCI');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7151, 5688, 151, 'What is most likely NOT an accomplishment that would qualify a nominee for consideration?', 'Creating a large number of new jobs', 'Increasing a company''s net profits', 'Achieving high rates of customer satisfaction', 'Developing an original type of product', 'C', 'Đáp án đúng là C.
Giải thích:
Theo thông báo, người được đề cử phải thể hiện khả năng xuất sắc trong một hoặc nhiều lĩnh vực sau: đổi mới, lợi nhuận, tạo việc làm, tác động tích cực khác đến cộng đồng. Tỷ lệ hài lòng của khách hàng cao không được liệt kê trong các tiêu chí này.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì nhiều khả năng KHÔNG phải là thành tích đủ điều kiện cho một ứng viên được xem xét?
A. Tạo ra số lượng lớn việc làm mới
B. Tăng lợi nhuận ròng của công ty
C. Đạt tỷ lệ hài lòng của khách hàng cao
D. Phát triển một loại sản phẩm độc đáo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5689, 252, NULL, NULL, 'Titanium Gym
450 Third Street, Creville 555-0177
25% Off a 3-month Membership
Present this coupon upon sign-up to receive three months of membership at Titanium Gym for just $135! Members are entitled to a monthly session with a certified personal trainer and unlimited access to classes including kickboxing, aerobics, and Pilates.
Offer available only to new members. Sign-up fee not included. Membership period must begin by March 31.', 'Titanium Gym
450 Third Street, Creville 555-0177
Giảm 25% cho tư cách thành viên 3 tháng
Trình bày phiếu giảm giá này khi đăng ký để nhận ba tháng tư cách thành viên tại Titanium Gym chỉ với 135 đô la! Các thành viên được hưởng một buổi học hàng tháng với một huấn luyện viên cá nhân được chứng nhận và quyền truy cập không giới hạn vào các lớp học bao gồm kickboxing, thể dục nhịp điệu và Pilates.
Ưng đãi chỉ dành cho các thành viên mới. Không bao gồm phí đăng ký. Thời gian thành viên phải bắt đầu trước ngày 31 tháng Ba.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7152, 5689, 152, 'According to the coupon, what is a benefit of Titanium Gym membership?', 'A yearly health evaluation', 'Access to special fitness equipment', 'The ability to take a variety of classes', 'Unlimited personal training sessions', 'C', 'Đáp án đúng là C.
Giải thích:
Theo phiếu giảm giá, thành viên được "unlimited access to classes including kickboxing, aerobics, and Pilates" (quyền truy cập không giới hạn vào các lớp học bao gồm kickboxing, aerobics và Pilates).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo phiếu giảm giá, lợi ích nào của tư cách thành viên Titanium Gym?
A. Đánh giá sức khỏe hàng năm
B. Tiếp cận thiết bị tập thể dục đặc biệt
C. Khả năng tham gia nhiều loại lớp học
D. Không giới hạn các buổi huấn luyện cá nhân');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7153, 5689, 153, 'What is true about the coupon?', 'Its user will be required to pay a sign-up fee', 'It is targeted toward people whose membership ends in April', 'It is valid for three months from the date of issue', 'Its user will receive a discount of $135', 'A', 'Đáp án đúng là A.
Giải thích:
Phiếu giảm giá nêu rõ "Sign-up fee not included" (Phí đăng ký không được tính), nghĩa là người sử dụng phiếu giảm giá vẫn phải trả phí đăng ký.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì đúng về phiếu giảm giá?
A. Người dùng sẽ phải trả phí đăng ký
B. Nó nhắm đến những người có tư cách thành viên kết thúc vào tháng 4
C. Nó có hiệu lực trong ba tháng kể từ ngày phát hành
D. Người dùng sẽ nhận được giảm giá 135 đô la');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5690, 252, NULL, NULL, 'Curtis Dawson [11:31 A.M.]
Misako, our van has broken down in Kloss, and the mechanic says the repairs will take at least four hours.
Misako Endo [11:33 A.M.]
Oh no! Well, we need to make sure our customers still get the experience they''ve paid for. You''re taking six people to Galvin Falls for the afternoon, right?
Curtis Dawson [11:34 A.M.]
That''s right. And we''re supposed to have lunch in Medford.
Misako Endo [11:35 A.M.]
OK. Do you think you could find a place to eat in Kloss instead? While you were doing that, I could rent another van from a local agency and have it driven over to you.
Curtis Dawson [11:36 A.M.]
Oh, we''re right near Kloss Shopping Center. Thanks, Misako! I''ll text you the exact address once we get settled.', 'Curtis Dawson [11:31 sáng]
Misako, xe tải của chúng tôi đã bị hỏng ở Kloss, và thợ máy nói rằng việc sửa chữa sẽ mất ít nhất bốn giờ.
Misako Endo [11:33 sáng]
Ôi không! Chà, chúng ta cần đảm bảo rằng khách hàng của chúng ta vẫn có được trải nghiệm mà họ đã trả tiền. Bạn sẽ đưa sáu người đến Thác Galvin vào buổi chiều, phải không? 
Curtis Dawson [11:34 sáng]
Đúng vậy. Và chúng ta phải ăn trưa ở Medford.
Misako Endo [11:35 sáng]
OK. Bạn có nghĩ rằng bạn có thể tìm một nơi để ăn ở Kloss thay thế không? Trong khi bạn đang làm điều đó, tôi có thể thuê một chiếc xe tải khác từ một đại lý địa phương và lái nó đến chỗ bạn.
Curtis Dawson [11:36 sáng]
Ồ, chúng tôi đang ở ngay gần Trung tâm mua sắm Kloss. Cảm ơn, Misako! Tôi sẽ nhắn tin cho bạn địa chỉ chính xác sau khi chúng ta ổn định.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7154, 5690, 154, 'What kind of business do the writers most likely work for?', 'A tour operator', 'A car rental agency', 'A food delivery business', 'An auto repair shop', 'A', 'Đáp án đúng là A.
Giải thích:
Đoạn hội thoại liên quan đến việc đưa khách đi tham quan ("taking six people to Galvin Falls"), điều này cho thấy đây là một công ty điều hành tour du lịch.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Những người viết nhiều khả năng làm việc cho loại hình doanh nghiệp nào?
A. Một công ty điều hành tour du lịch
B. Một đại lý cho thuê xe
C. Một doanh nghiệp giao đồ ăn
D. Một tiệm sửa xe');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7155, 5690, 155, 'At 11:36 A.M., what does Mr. Dawson most likely mean when he writes, "we''re right near Kloss Shopping Center''"?', 'It will not be difficult to find parking for a van', 'There are many dining options nearby', 'Ms. Endo is not far from his location', 'He is only slightly behind schedule', 'B', 'Đáp án đúng là B.
Giải thích:
Khi Ms. Endo đề xuất tìm chỗ ăn ở Kloss, Mr. Dawson trả lời "we''re right near Kloss Shopping Center", ám chỉ rằng có nhiều lựa chọn về nhà hàng gần đó vì họ đang ở gần trung tâm mua sắm.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 11:36 sáng, ông Dawson có ý gì khi viết "chúng tôi đang ở ngay gần Trung tâm mua sắm Kloss"?
A. Sẽ không khó để tìm chỗ đậu xe van
B. Có nhiều lựa chọn ăn uống gần đó
C. Cô Endo không ở xa vị trí của ông
D. Ông chỉ bị trễ một chút so với lịch trình');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5691, 252, NULL, NULL, 'Nature Monthly
One-Day Workshop on Scientific Writing for Aspiring Contributors
9:00 A.M. - Welcome and Introductions
9:30 A.M. - What Makes a Great Paper?
Introduction of three well-written papers accepted for publication in the journal and breakdown of their characteristics
10:15 A.M. - Break
10:30 A.M. - Mastering the Basics
Overview of the ideal structure of Nature Monthly papers and tips on what to include in each section to impress our editors
11:30 A.M. - The "Face" of Your Paper
Explanation of how to write a title and abstract that are compelling, brief, and informative
12:30 P.M. - Lunch
1:30 P.M. - Effective Display Items
Guide to determining when a table, figure, or other visual aid is needed and ensuring it is clear and impactful
2:30 P.M. - Live Edit Session
One-on-one meeting with an editor who will review a paper submitted in advance by the participant
3:15 P.M. - Q&A and Feedback', 'Nature Monthly
Hội thảo một ngày về viết khoa học dành cho những người đóng góp đầy tham vọng
9:00 sáng - Chào mừng và giới thiệu
9:30 sáng - Điều gì tạo nên một bài báo tuyệt vời? 
Giới thiệu ba bài báo được viết tốt được chấp nhận để xuất bản trên tạp chí và phân tích các đặc điểm của chúng
10:15 sáng - Nghỉ giải lao
10:30 sáng - Nắm vững những điều cơ bản
Tổng quan về cấu trúc lý tưởng của các bài báo hàng tháng của Nature và các mẹo về những gì cần đưa vào mỗi phần để gây ấn tượng với các biên tập viên của chúng tôi
11:30 sáng - "Khuôn mặt" của bài báo của bạn
Giải thích cách viết tiêu đề và tóm tắt hấp dẫn, ngắn gọn và nhiều thông tin
12:30 chiều - Bữa trưa
1:30 chiều - Hiển thị các mục hiệu quả
Hướng dẫn xác định khi nào cần một bảng, hình hoặc công cụ hỗ trợ trực quan khác và đảm bảo nó rõ ràng và có tác động
2:30 chiều - Phiên chỉnh sửa trực tiếp
Cuộc họp trực tiếp với Một biên tập viên sẽ xem xét một bài báo được gửi trước bởi người tham gia
3:15 chiều - Hỏi & Đáp và Phản hồi');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7156, 5691, 156, 'What is most likely true about participants in the workshop?', 'They will give editorial advice on each other''s papers', 'They hope to have their writing published in Nature Monthly', 'They submitted information on their backgrounds beforehand', 'They are currently attending university to study science', 'B', 'Đáp án đúng là B.
Giải thích:
Các phần của hội thảo tập trung vào cách viết bài báo khoa học để được đăng trên Nature Monthly, với các chủ đề như cấu trúc lý tưởng, cách gây ấn tượng với biên tập viên. Điều này cho thấy người tham gia hy vọng được xuất bản bài viết của họ trên Nature Monthly.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì nhiều khả năng đúng về người tham gia hội thảo?
A. Họ sẽ đưa ra lời khuyên biên tập về bài viết của nhau
B. Họ hy vọng có bài viết được xuất bản trên Nature Monthly
C. Họ đã nộp thông tin về nền tảng của họ trước đó
D. Họ hiện đang theo học đại học để nghiên cứu khoa học');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7157, 5691, 157, 'When would participants most likely learn how to design a chart?', 'Between 9:30 A.M. and 10:15 A.M.', 'Between 10:30 A.M. and 11:30 A.M.', 'Between 11:30 A.M. and 12:30 P.M.', 'Between 1:30 p.M. and 2:30 P.M.', 'D', 'Đáp án đúng là D.
Giải thích:
Theo lịch trình, từ 1:30 PM đến 2:30 PM là phần "Effective Display Items" (Các mục trình bày hiệu quả), hướng dẫn cách xác định khi nào cần bảng, hình vẽ hoặc hỗ trợ trực quan khác. Đây là thời điểm người tham gia sẽ học cách thiết kế biểu đồ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Khi nào người tham gia nhiều khả năng học cách thiết kế biểu đồ?
A. Giữa 9:30 sáng và 10:15 sáng
B. Giữa 10:30 sáng và 11:30 sáng
C. Giữa 11:30 sáng và 12:30 chiều
D. Giữa 1:30 chiều và 2:30 chiều');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5692, 252, NULL, NULL, 'http://www.alcornphotographers.com/news
Alcorn Photographers is proud to announce that we now offer aerial photography via drone. This technology is an excellent way to showcase your client''s home, apartment complex, or commercial space. Shooting the front, side, or rear of the building from a few dozen feet above the ground gives potential buyers a better sense of its scale and surroundings.
As with our other outdoor services, Alcorn Photographers will not charge for aerial photography shoots that must be canceled due to poor weather. We are also happy to schedule sessions at twilight to take advantage of the flattering lighting created by the setting sun.
Prices for aerial photography start at $200 for five images and increase with the number of photos desired.', 'http://www.alcornphotographers.com/news
Alcorn Photographers tự hào thông báo rằng chúng tôi hiện đang cung cấp dịch vụ chụp ảnh trên không bằng máy bay không người lái. Công nghệ này là một cách tuyệt vời để giới thiệu nhà, khu chung cư hoặc không gian thương mại của khách hàng của bạn. Chụp mặt trước, mặt bên hoặc mặt sau của tòa nhà từ độ cao vài chục feet so với mặt đất giúp người mua tiềm năng cảm nhận rõ hơn về quy mô và môi trường xung quanh.
Như với các dịch vụ ngoài trời khác của chúng tôi, Nhiếp ảnh gia Alcorn sẽ không tính phí cho các buổi chụp ảnh trên không phải bị hủy do thời tiết xấu. Chúng tôi cũng sẵn lòng lên lịch các buổi chụp vào lúc hoàng hôn để tận dụng ánh sáng tâng bốc được tạo ra bởi mặt trời lặn.
Giá chụp ảnh trên không bắt đầu từ 200 đô la cho năm hình ảnh và tăng theo số lượng ảnh mong muốn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7158, 5692, 158, 'For whom is the information most likely intended?', 'Property owners', 'Drone operators', 'Aspiring photographers', 'Real estate agents', 'D', 'Đáp án đúng là D.
Giải thích:
Thông tin đề cập đến việc "showcase your client''s home" và "potential buyers", cho thấy đối tượng mục tiêu là các đại lý bất động sản - những người cần hình ảnh để quảng cáo bất động sản cho khách hàng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Thông tin này nhiều khả năng dành cho ai?
A. Chủ sở hữu bất động sản
B. Người điều khiển drone
C. Nhiếp ảnh gia tập sự
D. Đại lý bất động sản');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7159, 5692, 159, 'According to the Web page, what are customers charged more for?', 'Having photographs taken via drone', 'Canceling a photo shoot on short notice', 'Holding a photo shoot in the evening', 'Requesting additional photographs', 'D', 'Đáp án đúng là D.
Giải thích:
Theo trang web, "Prices for aerial photography start at $200 for five images and increase with the number of photos desired" (Giá chụp ảnh trên không bắt đầu từ 200 đô la cho năm ảnh và tăng theo số lượng ảnh mong muốn). Điều này cho thấy khách hàng phải trả thêm tiền khi yêu cầu thêm ảnh.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo trang web, khách hàng bị tính phí nhiều hơn cho việc gì?
A. Chụp ảnh bằng drone
B. Hủy buổi chụp ảnh vào phút chót
C. Tổ chức buổi chụp ảnh vào buổi tối
D. Yêu cầu thêm ảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7160, 5692, 160, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "In addition, photographs taken from a hundred feet directly overhead can be used to show a property''s full layout."', '[1]', '[2]', '[3]', '[4]', 'B', 'Đáp án đúng là B.
Giải thích:
Câu "In addition, photographs taken from a hundred feet directly overhead can be used to show a property''s full layout" nên được đặt ở vị trí [2] vì:
1. Nó bổ sung thêm một ứng dụng khác của chụp ảnh trên không
2. Nó liên quan trực tiếp đến đoạn trước về việc chụp ảnh từ độ cao để thể hiện quy mô và môi trường xung quanh

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Câu "Ngoài ra, những bức ảnh chụp từ độ cao một trăm feet trực tiếp phía trên có thể được sử dụng để thể hiện bố cục đầy đủ của bất động sản" phù hợp nhất với vị trí nào trong số các vị trí được đánh dấu [1], [2], [3], và [4]?
A. [1]
B. [2]
C. [3]
D. [4]');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5693, 252, NULL, NULL, 'E-Mail message
From: Patricia Chilton
To: All staff
Subject: Overtime policy
Date: December 2
Dear staff,
I really appreciate the hard work you''re doing to prepare for our upcoming symposium. I know that it can be a struggle to keep up with the extra workload it involves.
That said, I''d like to remind you that our employee handbook strictly prohibits working more than 40 hours per week without getting approval from a supervisor beforehand. We''re legally required to pay you at a higher rate for any overtime hours, and as a nonprofit organization, we don''t have the resources to cover extra expenses in this area.
If you''re unable to complete an assignment within your regular hours, you must leave it to your supervisor to decide whether to allow overtime work or to push the deadline back. Going forward, failure to follow this policy will be reflected in your performance evaluation.
Thank you.
Patricia Chilton
Executive Director
Proactive Network for Women in Engineering', 'Tin nhắn E-Mail
Từ: Patricia Chilton
Gửi đến: Tất cả nhân viên
Chủ đề: Chính sách làm thêm giờ
Ngày: 2 tháng 12
Nhân viên thân mến,
Tôi thực sự đánh giá cao công việc khó khăn mà các bạn đang làm để chuẩn bị cho hội nghị chuyên đề sắp tới của chúng tôi. Tôi biết rằng có thể là một cuộc đấu tranh để theo kịp khối lượng công việc bổ sung liên quan.
Điều đó nói rằng, tôi muốn nhắc bạn rằng sổ tay nhân viên của chúng tôi nghiêm cấm làm việc hơn 40 giờ mỗi tuần mà không có sự chấp thuận trước của người giám sát. Chúng tôi được yêu cầu về mặt pháp lý phải trả cho bạn mức lương cao hơn cho bất kỳ giờ làm thêm nào và là một tổ chức phi lợi nhuận, chúng tôi không có đủ nguồn lực để trang trải các chi phí bổ sung trong lĩnh vực này.
Nếu bạn không thể hoàn thành bài tập trong giờ làm việc thông thường của mình, bạn phải để người giám sát quyết định xem có nên cho phép làm thêm giờ hay lùi thời hạn. Trong tương lai, việc không tuân thủ chính sách này sẽ được phản ánh trong đánh giá hiệu suất của bạn.
Cảm ơn bạn.
Patricia Chilton
Giám đốc điều hành
Mạng lưới chủ động dành cho phụ nữ trong ngành kỹ thuật');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7161, 5693, 161, 'What most likely caused Ms. Chilton to send the e-mail?', 'Preparations for an event have fallen behind schedule', 'There has been a change in laws regarding compensation', 'Employees have been working overtime without permission', 'Some staff members missed an information session', 'C', 'Đáp án đúng là C.
Giải thích:
Ms. Chilton nhấn mạnh chính sách làm thêm giờ và cần phải có sự chấp thuận của giám sát viên trước khi làm thêm giờ. Điều này cho thấy nhân viên đã làm thêm giờ mà không xin phép.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì nhiều khả năng khiến Ms. Chilton gửi email?
A. Chuẩn bị cho một sự kiện đã bị chậm tiến độ
B. Đã có thay đổi trong luật về thù lao
C. Nhân viên đã làm thêm giờ mà không có sự cho phép
D. Một số nhân viên đã bỏ lỡ một buổi thông tin');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7162, 5693, 162, 'What is indicated about the Proactive Network for Women in Engineering?', 'It has a limited budget for payroll', 'It organizes an annual symposium', 'Its workers regularly receive pay raises', 'Its legal department is very busy', 'A', 'Đáp án đúng là A.
Giải thích:
Theo email, tổ chức này là "nonprofit organization" và "we don''t have the resources to cover extra expenses" (chúng tôi không có nguồn lực để chi trả các chi phí phát sinh). Điều này cho thấy họ có ngân sách hạn chế cho việc trả lương.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Mạng lưới Chủ động cho Phụ nữ trong Kỹ thuật?
A. Nó có ngân sách hạn chế cho việc trả lương
B. Nó tổ chức một hội thảo hàng năm
C. Nhân viên của nó thường xuyên được tăng lương
D. Phòng pháp lý của nó rất bận rộn');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7163, 5693, 163, 'According to the e-mail, what consequence will staff face for breaking a rule?', 'Losing the perk of flexible working hours', 'Becoming ineligible for promotion to supervisor', 'Receiving assignments that are less desirable', 'Earning a worse performance review', 'D', 'Đáp án đúng là D.
Giải thích:
Email nêu rõ "failure to follow this policy will be reflected in your performance evaluation" (không tuân thủ chính sách này sẽ được phản ánh trong đánh giá hiệu suất).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo email, nhân viên sẽ phải đối mặt với hậu quả gì khi vi phạm quy định?
A. Mất đặc quyền giờ làm việc linh hoạt
B. Không đủ điều kiện để thăng chức thành giám sát viên
C. Nhận các nhiệm vụ kém hấp dẫn hơn
D. Nhận được đánh giá hiệu suất kém hơn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5694, 252, NULL, NULL, '10 March
Kwang-Hoon Choi
233 Conner Street
Edinburgh EH3 8DN
Dear Mr. Choi,
On behalf of the Polwarth Community Garden Committee, I am excited to invite you back for another year of tending greenery together. This year''s growing season begins on 3 April, and there are some changes to the garden''s rules that you should be aware of.
First, to ensure the fair distribution of labour, it is now mandatory for all members to spend at least 10 hours annually doing the volunteer work necessary to keep the garden running. Fulfillment of this requirement will be tracked through a system on the garden''s Web site. I will provide more information about this shortly.
Second, due to the long waiting list for our garden, this will be the final year that any household is allowed to have more than one plot. If your household has multiple plots, please notify the committee of which one you wish to keep and make certain the others are in suitable shape for reassignment at the end of the season.
Also, as usual, I ask that you check the bulletin board in the tool shed frequently for news and updates. Thank you, and I look forward to seeing you in the garden!
Sincerely,
Irvin Townsend, Chair Polwarth Community Garden Committee', 'Ngày 10 tháng 3
Kwang-Hoon Choi
233 Conner Street
Edinburgh EH3 8DN
Ông Choi thân mến,
Thay mặt Ủy ban Vườn Cộng đồng Polwarth, tôi rất vui mừng được mời ông trở lại để cùng nhau chăm sóc cây xanh thêm một năm nữa. Mùa trồng trọt năm nay bắt đầu vào ngày 3 tháng 4 và có một số thay đổi đối với các quy tắc của khu vườn mà bạn nên biết.
Đầu tiên, để đảm bảo phân phối lao động công bằng, bây giờ tất cả các thành viên bắt buộc phải dành ít nhất 10 giờ mỗi năm để làm công việc tình nguyện cần thiết để giữ cho khu vườn hoạt động. Hoàn thành yêu cầu này sẽ được theo dõi thông qua một hệ thống trên trang web của khu vườn. Tôi sẽ sớm cung cấp thêm thông tin về điều này.
Thứ hai, do danh sách chờ đợi dài cho khu vườn của chúng tôi, đây sẽ là năm cuối cùng mà bất kỳ hộ gia đình nào cũng được phép có nhiều hơn một lô đất. Nếu hộ gia đình bạn có nhiều lô đất, vui lòng thông báo cho ủy ban về việc bạn muốn giữ cái nào và đảm bảo những mảnh đất khác có hình dạng phù hợp để phân công lại vào cuối mùa.
Ngoài ra, như thường lệ, tôi yêu cầu bạn kiểm tra bảng thông báo trong nhà kho công cụ thường xuyên để biết tin tức và cập nhật. Cảm ơn bạn, và tôi mong được gặp bạn trong vườn! 
Trân trọng,
Irvin Townsend, Chủ tịch Ủy ban Vườn Cộng đồng Polwarth');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7164, 5694, 164, 'What is one purpose of the letter?', 'To describe a new benefit of membership', 'To announce a change to a start date', 'To seek volunteers for an event', 'To welcome a returning member', 'D', 'Đáp án đúng là D.
Giải thích:
Lá thư mời Mr. Choi quay lại "invite you back for another year of tending greenery together", cho thấy mục đích là chào đón một thành viên cũ quay lại.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Một mục đích của bức thư là gì?
A. Mô tả một lợi ích mới của tư cách thành viên
B. Thông báo thay đổi ngày bắt đầu
C. Tìm kiếm tình nguyện viên cho một sự kiện
D. Chào đón một thành viên quay lại');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7165, 5694, 165, 'According to the letter, what will an online system be used for?', 'Reporting news about the garden', 'Keeping track of some tools', 'Redistributing some pieces of land', 'Recording some work hours', 'D', 'Đáp án đúng là D.
Giải thích:
Theo thư, "Fulfillment of this requirement will be tracked through a system on the garden''s Web site" (Việc hoàn thành yêu cầu này sẽ được theo dõi thông qua một hệ thống trên trang web của vườn). Yêu cầu ở đây là 10 giờ làm việc tình nguyện hàng năm.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo thư, hệ thống trực tuyến sẽ được sử dụng để làm gì?
A. Báo cáo tin tức về khu vườn
B. Theo dõi một số công cụ
C. Phân phối lại một số mảnh đất
D. Ghi lại số giờ làm việc');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7166, 5694, 166, 'What is implied about Polwarth Community Garden?', 'It does not have enough plots to meet demand', 'There is a diagram of its plots on display in a storage shed', 'Its plots must be assigned to a different household each year', 'The borders of its plots will be redrawn next year', 'A', 'Đáp án đúng là A.
Giải thích:
Thư đề cập đến "the long waiting list for our garden" (danh sách chờ dài cho khu vườn của chúng tôi) và hạn chế mỗi hộ gia đình chỉ được có một lô đất, cho thấy không có đủ lô đất để đáp ứng nhu cầu.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được ngụ ý về Vườn Cộng đồng Polwarth?
A. Nó không có đủ lô đất để đáp ứng nhu cầu
B. Có một sơ đồ các lô đất được trưng bày trong nhà kho
C. Các lô đất của nó phải được chỉ định cho một hộ gia đình khác mỗi năm
D. Ranh giới các lô đất của nó sẽ được vẽ lại vào năm sau');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7167, 5694, 167, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "Typical tasks include weed removal and cleaning the tool shed."', '[1]', '[2]', '[3]', '[4]', 'B', 'Đáp án đúng là B.
Giải thích:
Câu "Typical tasks include weed removal and cleaning the tool shed" nên được đặt ở vị trí [2] vì nó giải thích về các công việc tình nguyện mà thành viên phải làm trong 10 giờ hàng năm được đề cập trong đoạn trước đó.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Câu "Các công việc điển hình bao gồm nhổ cỏ dại và dọn dẹp nhà kho dụng cụ" phù hợp nhất với vị trí nào trong số các vị trí được đánh dấu [1], [2], [3], và [4]?
A. [1]
B. [2]
C. [3]
D. [4]');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5695, 252, NULL, NULL, 'HRTA Project On Track for Summer Hitchert Regional Transit Agency (HRTA) has reached another milestone in the process of adding enhanced-accessibility trains to its light-rail fleet. On January 7, HRTA staff began trial operation of the trains on the Gold and Green lines in order to discover and eliminate any issues before their deployment at the start of summer. To minimize inconvenience to transport users, the trains are being run only between the hours of 8 p.M. and 4 A.M. and are marked with large "Test Train" stickers to prevent people from boarding. Spreading rapidly to metropolitan areas across the country following their debut in Fonseca, the trains boast low, stair-free entrances, automatically-contrölled ramps, and other features that make them more accessible to passengers with disabilities.', 'Dự án HRTA trên đường đua cho mùa hè Cơ quan giao thông khu vực Hitchert (HRTA) đã đạt được một cột mốc quan trọng khác trong quá trình bổ sung các chuyến tàu có khả năng tiếp cận nâng cao vào đội tàu đường sắt nhẹ của mình. Vào ngày 7 tháng 1, nhân viên HRTA đã bắt đầu vận hành thử nghiệm các đoàn tàu trên các tuyến Vàng và Xanh để phát hiện và loại bỏ mọi vấn đề trước khi triển khai vào đầu mùa hè. Để giảm thiểu sự bất tiện cho người sử dụng phương tiện giao thông, các chuyến tàu chỉ được chạy trong khoảng thời gian từ 8 giờ tối đến 4 giờ sáng và được đánh dấu bằng nhãn dán "Tày thử nghiệm" lớn để ngăn mọi người lên tàu. Lan rộng nhanh chóng đến các khu vực đô thị trên khắp đất nước sau khi ra mắt tại Fonseca, các chuyến tàu tự hào có lối vào thấp, không có cầu thang, đường dốc tự động điều khiên và các tính năng khác giúp hành khách khuyết tật dễ tiếp cận hơn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7168, 5695, 168, 'What is HRTA preparing to do?', 'Introduce a new type of train', 'Expand nighttime service', 'Connect two railway lines', 'Increase the accessibility of its stations', 'A', 'Đáp án đúng là A.
Giải thích:
Bài báo đề cập đến việc HRTA đang thử nghiệm tàu mới có khả năng tiếp cận nâng cao (enhanced-accessibility trains) trước khi triển khai vào đầu mùa hè.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: HRTA đang chuẩn bị làm gì?
A. Giới thiệu một loại tàu mới
B. Mở rộng dịch vụ ban đêm
C. Kết nối hai tuyến đường sắt
D. Tăng khả năng tiếp cận của các ga');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7169, 5695, 169, 'According to the article, what will continue to happen until summer begins?', 'Some trains will be tested', 'Some staff will receive training', 'Transport users will be surveyed', 'Construction will be carried out', 'A', 'Đáp án đúng là A.
Giải thích:
Theo bài báo, việc thử nghiệm tàu sẽ tiếp tục cho đến khi triển khai vào đầu mùa hè: "trial operation of the trains... in order to discover and eliminate any issues before their deployment at the start of summer".

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo bài báo, điều gì sẽ tiếp tục xảy ra cho đến khi mùa hè bắt đầu?
A. Một số tàu sẽ được thử nghiệm
B. Một số nhân viên sẽ được đào tạo
C. Người dùng giao thông sẽ được khảo sát
D. Việc xây dựng sẽ được thực hiện');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7170, 5695, 170, 'What is suggested about trains with stickers on them?', 'They only stop at two stations', 'They do not carry passengers yet', 'They have completed an inspection', 'They will be taken out of service soon', 'B', 'Đáp án đúng là B.
Giải thích:
Bài báo nói rằng tàu được dán nhãn "Test Train" để ngăn người dân lên tàu: "marked with large ''Test Train'' stickers to prevent people from boarding", cho thấy những tàu này chưa chở khách.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về những tàu có dán nhãn?
A. Chúng chỉ dừng ở hai ga
B. Chúng chưa chở hành khách
C. Chúng đã hoàn thành kiểm tra
D. Chúng sẽ sớm ngừng hoạt động');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7171, 5695, 171, 'Why does the writer mention Fonseca?', 'HRTA staff visited it for research', 'It is the site of a production plant', 'It was the first place to adopt a technology', 'The size of its population is similar to Hitchert''s', 'C', 'Đáp án đúng là C.
Giải thích:
Bài báo đề cập Fonseca như nơi đầu tiên sử dụng loại tàu này: "following their debut in Fonseca" (sau khi ra mắt ở Fonseca).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tại sao tác giả đề cập đến Fonseca?
A. Nhân viên HRTA đã đến đó để nghiên cứu
B. Đó là địa điểm của nhà máy sản xuất
C. Đó là nơi đầu tiên áp dụng một công nghệ
D. Quy mô dân số của nó tương tự như Hitchert');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5696, 252, NULL, NULL, 'Michelle Garnier [10:04 A.M.] Hi, all. I just finished looking over the exit surveys from the summer interns.
Dominick Perkins [10:05 A.M.] Any surprising results?
Michelle Garnier [10:07 A.M.] Yes—they felt that we gave them too many low-level duties. They wanted to spend more time researching investment opportunities and helping us pitch them to clients.
Tina Osborne [10:08 A.M.] Really? We made such an effort to involve them in that kind of work. Maybe we need to be clearer during the application process about the scope of the internships.
Michelle Garnier [10:09 A.M.] That''s a good idea. Anyway, the feedback on our mentoring and the networking opportunities was quite good, at least.
Dominick Perkins [10:10 A.M.] Michelle, I''d be interested in seeing more of the results. When would be a good time to drop by your office?
Michelle Garnier [10:11 A.M.] Oh, we''ll have a review meeting in a few days. I''ll put it on your calendars this afternoon.
Dominick Perkins [10:12 A.M.] Great.
Michelle Garnier [10:13 A.M.] That reminds me— before the meeting, please decide whether you''d recommend recruiting your interns after their graduations. Human Resources wants to make a note in their personnel files for easy reference.
Tina Osborne [10:14 A.M.] Do they really just want a "yes" or "no"? I think future hiring managers would prefer an overview of each person''s strengths and weaknesses.
Michelle Garnier [10:14 A.M.] Good point. ''ll try to find out more.', 'Michelle Garnier [10:04 sáng] Xin chào, tất cả. Tôi vừa xem xong các cuộc khảo sát xuất cảnh từ các thực tập sinh mùa hè.
Dominick Perkins [10:05 sáng] Có kết quả đáng ngạc nhiên nào không? 
Michelle Garnier [10:07 Sáng] Đúng vậy—họ cảm thấy rằng chúng tôi giao cho họ quá nhiều nhiệm vụ cấp thấp. Họ muốn dành nhiều thời gian hơn để nghiên cứu các cơ hội đầu tư và giúp chúng tôi giới thiệu chúng cho khách hàng.
Tina Osborne [10:08 sáng] Thật sao? Chúng tôi đã nỗ lực rất nhiều để lôi kéo họ vào loại công việc đó. Có lẽ chúng ta cần phải rõ ràng hơn trong quá trình đăng ký về phạm vi thực tập.
Michelle Garnier [10:09 sáng] Đó là một ý kiến hay. Dù sao đi nữa, phản hồi về việc cố vấn và các cơ hội kết nối của chúng tôi cũng khá tốt, ít nhất.
Dominick Perkins [10:10 sáng] Michelle, tôi rất muốn xem thêm kết quả. Khi nào là thời điểm thích hợp để ghé qua văn phòng của bạn? 
Michelle Garnier [10:11 sáng] Ồ, chúng ta sẽ có một cuộc họp đánh giá trong vài ngày nữa. Tôi sẽ ghi nó vào lịch của bạn vào chiều nay.
Dominick Perkins [10:12 sáng] Tuyệt vời.
Michelle Garnier [10:13 sáng] Điều đó nhắc nhở tôi - trước cuộc họp, vui lòng quyết định xem bạn có đề xuất tuyển dụng thực tập sinh của mình sau khi họ tốt nghiệp hay không. Nhân sự muốn ghi chú vào hồ sơ nhân sự của họ để dễ dàng tham khảo.
Tina Osborne [10:14 sáng] Họ thực sự chỉ muốn một "có" hay "không"? Tôi nghĩ rằng các nhà quản lý tuyển dụng trong tương lai sẽ thích tổng quan về điểm mạnh và điểm yếu của mỗi người.
Michelle Garnier [10:14 sáng] Quan điểm tốt. ''sẽ cố gắng tìm hiểu thêm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7172, 5696, 172, 'In what field do the writers most likely work?', 'Insurance sales', 'Staff recruitment', 'Wealth management', 'Healthcare research', 'C', 'Đáp án đúng là C.
Giải thích:
Trong đoạn hội thoại, các thực tập sinh muốn "researching investment opportunities and helping us pitch them to clients" (nghiên cứu cơ hội đầu tư và giúp chào mời cho khách hàng). Điều này cho thấy họ làm việc trong lĩnh vực quản lý tài sản.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Những người viết nhiều khả năng làm việc trong lĩnh vực nào?
A. Bán bảo hiểm
B. Tuyển dụng nhân sự
C. Quản lý tài sản
D. Nghiên cứu y tế');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7173, 5696, 173, 'What is NOT mentioned as a topic covered in the survey given to the interns?', 'The internship application process', 'The tasks they were assigned', 'The mentorship provided by the writers', 'Their opportunities to make professional connections', 'A', 'Đáp án đúng là A.
Giải thích:
Các chủ đề được đề cập trong khảo sát bao gồm:
- Nhiệm vụ được giao (low-level duties)
- Sự cố vấn (mentoring)
- Cơ hội kết nối (networking opportunities)
Quy trình ứng tuyển thực tập không được đề cập là một chủ đề trong khảo sát.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG được đề cập là chủ đề trong khảo sát dành cho thực tập sinh?
A. Quy trình ứng tuyển thực tập
B. Nhiệm vụ họ được giao
C. Sự cố vấn được cung cấp bởi người viết
D. Cơ hội kết nối chuyên nghiệp của họ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7174, 5696, 174, 'At 10:11 A.M., what does Ms. Garnier most likely mean when she writes, "we''ll have a review meeting in a few days"?', 'Mr. Perkins will be introduced to some staff members', 'There is no need for Mr. Perkins to bring a document to her', 'Mr. Perkins should wait to learn some information', 'Mr. Perkins will have time to prepare for a discussion', 'C', 'Đáp án đúng là C.
Giải thích:
Khi Mr. Perkins muốn xem kết quả khảo sát và hỏi khi nào có thể ghé văn phòng, Ms. Garnier trả lời rằng sẽ có cuộc họp đánh giá trong vài ngày tới. Điều này ngụ ý rằng Mr. Perkins nên đợi đến cuộc họp để biết thông tin.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 10:11 sáng, Ms. Garnier có ý gì khi viết "chúng ta sẽ có cuộc họp đánh giá trong vài ngày"?
A. Ông Perkins sẽ được giới thiệu với một số nhân viên
B. Không cần ông Perkins mang tài liệu đến cho cô ấy
C. Ông Perkins nên đợi để biết một số thông tin
D. Ông Perkins sẽ có thời gian chuẩn bị cho cuộc thảo luận');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7175, 5696, 175, 'What most likely is Ms. Osborne''s concern about the information requested by Human Resources?', 'It will take considerable effort to gather', 'It is not detailed enough to be useful', 'It should not be accessible to other employees', 'It may no longer be accurate in the future', 'B', 'Đáp án đúng là B.
Giải thích:
Ms. Osborne cho rằng một câu trả lời đơn giản "có" hoặc "không" về việc tuyển dụng thực tập sinh là không đủ chi tiết. Cô ấy nghĩ rằng các quản lý tuyển dụng trong tương lai sẽ thích xem tổng quan về điểm mạnh và điểm yếu của mỗi người hơn.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mối quan ngại của Ms. Osborne về thông tin mà Nhân sự yêu cầu nhiều khả năng là gì?
A. Sẽ mất nhiều công sức để thu thập
B. Không đủ chi tiết để hữu ích
C. Không nên cho nhân viên khác tiếp cận
D. Có thể không còn chính xác trong tương lai');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5697, 252, NULL, NULL, 'DISTRICT SALES MANAGER
Eason Technologies, a premier provider of energy-efficient air-conditioning systems for offices and retail facilities, is seeking a sales manager for our southwest district. The position is based in Barrow.
 Responsibilities:
* overseeing the activities of the district sales team
* identifying potential customers and acquiring their business
* forecasting and tracking sales accurately
* monitoring customer satisfaction to ensure retention
 Required qualifications:
* a degree in business or a technical field
* five years of experience in a sales leadership role
* excellent public speaking skills
* willingness to travel frequently
To apply, send your résumé and a cover letter to hiring@easontech. com.
=========
E-Mail message
From: So-Won Na
To: Brandon Fisher
Subject: Potential candidate
Date: January. 30
Hello Brandon,
I wanted to let you know about someone who may be a good candidate for the southwest district sales manager position. His name is Edgar Malone, and he''s a sales representative at Levya Corporation. We became friends after running into each other at trade shows around the country. I saw him give sales pitches a couple of times at them, and he''s very good at it. I believe he''s been at Levya for at least five years and has a degree in mechanical engineering.
Shall I send him an e-mail sharing the job advertisement and suggesting that he apply?
Best,
So-Won', 'QUẢN LÝ BÁN HÀNG QUẬN
Eason Technologies, nhà cung cấp hàng đầu các hệ thống điều hòa không khí tiết kiệm năng lượng cho các văn phòng và cơ sở bán lẻ, đang tìm kiếm một giám đốc bán hàng cho quận phía tây nam của chúng tôi. Vị trí này có trụ sở tại Barrow.
 Trách nhiệm:
* giám sát các hoạt động của nhóm bán hàng quận
* xác định khách hàng tiềm năng và có được doanh nghiệp của họ
* dự báo và theo dõi doanh số bán hàng một cách chính xác
* giám sát sự hài lòng của khách hàng để đảm bảo giữ chân
 Trình độ chuyên môn bắt buộc:
* bằng cấp về kinh doanh hoặc lĩnh vực kỹ thuật
* năm năm kinh nghiệm trong vai trò lãnh đạo bán hàng
* kỹ năng nói trước công chúng xuất sắc
* sẵn sàng đi lại thường xuyên
Để nộp đơn, hãy gửi sơ yếu lý lịch và thư xin việc đến hiring@easontech. com.
=========
Tin nhắn E-Mail
Từ: So-Won Na
Gửi: Brandon Fisher
Chủ đề: Ứng viên tiềm năng
Ngày: Vị trí. Tên anh ấy là Edgar Malone, và anh ấy là đại diện bán hàng tại Levya Corporation. Chúng tôi trở thành bạn bè sau khi tình cờ gặp nhau tại các triển lãm thương mại trên khắp đất nước. Tôi đã thấy anh ấy thuyết trình bán hàng một vài lần với họ, và anh ấy rất giỏi trong việc đó. Tôi tin rằng anh ấy đã làm việc tại Levya ít nhất năm năm và có bằng kỹ sư cơ khí.
Tôi có nên gửi cho anh ấy một e-mail chia sẻ quảng cáo việc làm và đề nghị anh ấy nộp đơn không? 
Tốt nhất,
So-Won');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7176, 5697, 176, 'What is suggested about Eason Technologies?', 'It sells its products to other businesses', 'It designs technology that produces renewable energy', 'It recently created a new sales district', 'It is headquartered in Barrow', 'A', 'Đáp án đúng là A.
Giải thích:
Công ty được mô tả là nhà cung cấp hệ thống điều hòa không khí tiết kiệm năng lượng cho văn phòng và cơ sở bán lẻ, cho thấy họ bán sản phẩm cho các doanh nghiệp khác.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về Eason Technologies?
A. Công ty bán sản phẩm cho các doanh nghiệp khác
B. Công ty thiết kế công nghệ tạo ra năng lượng tái tạo
C. Công ty vừa tạo ra một khu vực bán hàng mới
D. Công ty có trụ sở tại Barrow');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7177, 5697, 177, 'What is one responsibility of the position?', 'Monitoring competitors'' pricing', 'Cooperating with marketing staff', 'Correctly predicting sales revenues', 'Proposing potential new products', 'C', 'Đáp án đúng là C.
Giải thích:
Theo danh sách trách nhiệm công việc, một trong những nhiệm vụ là "forecasting and tracking sales accurately" (dự báo và theo dõi doanh số chính xác).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Một trách nhiệm của vị trí này là gì?
A. Theo dõi giá của đối thủ cạnh tranh
B. Hợp tác với nhân viên marketing
C. Dự đoán doanh thu bán hàng chính xác
D. Đề xuất sản phẩm mới tiềm năng');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7178, 5697, 178, 'What does Ms. Na explain in the e-mail?', 'How long she has known Mr. Malone', 'Where she saw the job advertisement', 'How she became acquainted with Mr. Malone', 'Why Mr. Malone might be interested in changing jobs', 'C', 'Đáp án đúng là C.
Giải thích:
Ms. Na giải thích cô ấy quen biết Mr. Malone như thế nào: "We became friends after running into each other at trade shows around the country" (Chúng tôi trở thành bạn sau khi gặp nhau tại các hội chợ thương mại khắp đất nước).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Na giải thích điều gì trong email?
A. Cô ấy đã biết ông Malone bao lâu
B. Cô ấy thấy quảng cáo việc làm ở đâu
C. Cô ấy làm quen với ông Malone như thế nào
D. Tại sao ông Malone có thể quan tâm đến việc thay đổi công việc');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7179, 5697, 179, 'From Ms. Na''s description, what position requirement might Mr. Malone NOT possess?', 'A degree in a suitable field', 'The necessary work experience', 'Excellent public speaking ability', 'A tolerance for frequent travel', 'B', 'Đáp án đúng là B.
Giải thích:
Yêu cầu công việc cần 5 năm kinh nghiệm ở vị trí lãnh đạo bán hàng, nhưng Ms. Na chỉ nói Mr. Malone là đại diện bán hàng ("sales representative") tại Levya, không đề cập đến vai trò lãnh đạo.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Từ mô tả của Ms. Na, yêu cầu vị trí nào Mr. Malone có thể KHÔNG có?
A. Một bằng cấp phù hợp
B. Kinh nghiệm làm việc cần thiết
C. Khả năng nói trước công chúng xuất sắc
D. Chấp nhận đi lại thường xuyên');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7180, 5697, 180, 'In the e-mail, the word "sharing" in paragraph 1, line 6, is closest in meaning to', 'dividing', 'informing', 'expressing', 'delivering', 'D', 'Đáp án đúng là D.
Giải thích:
Từ "sharing" trong ngữ cảnh "sharing the job advertisement" có nghĩa gần nhất với "delivering" (chuyển, gửi) - gửi thông tin quảng cáo việc làm cho Mr. Malone.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Trong email, từ "sharing" ở đoạn 1, dòng 6, có nghĩa gần nhất với từ nào?
A. chia sẻ
B. thông báo
C. bày tỏ
D. chuyển gửi');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5698, 252, NULL, NULL, 'Scrap Saver
Tired of dealing with your business''s food waste? Whether you run a restaurant or a café, a hotel or a catering company, Scrap Saver has the solution to your problem.
Since the separate disposal of commercial food waste became mandated by law last year, a growing number of businesses have turned to us for disposal of their cooking scraps and leftover food products. We provide cheap, convenient pickup and transport of these materials to our facilities, where they are converted into alternative fuels and organic fertilizer. Clients simply collect the food waste in one of our free storage bins or their own until the designated pickup time, which can be scheduled as frequently as needed.
Scrap Saver offers removal of all types of food packaging for reasonable handling fees, and we can even provide bulk transportation services for business that create more than three tons of waste per week.
Visit www.scrapsaver.com to learn more!
=========
E-Mail message
From: Margaret Ross <mross@scrapsaver.com>
To: Jake Pierce <jake.pierce@babybudfood.com>
Subject: Information about Scrap Saver
Date: November 14
Dear Mr. Pierce,
Thank you for contacting us on behalf of Babybud Food Corporation. It''s my pleasure to answer the questions you asked in the online form you filled out.
Our rate is $0.26 per liter of food waste, plus there''s a distance-based pickup fee that would be $11.00 per visit given your company''s location. You wouldn''t be charged handling fees, and there''s no additional cost for weekend pickups. Billing is done at the end of each calendar month.
Please don''t hesitate to reply to this e-mail or call me at 555-0189 if you have additional questions or are ready to engage Scrap Saver''s services.
Sincerely,
Margaret Ross
Sales Representative
Scrap Saver, Incorporated', 'Scrap Saver
Mệt mỏi vì xử lý chất thải thực phẩm của doanh nghiệp bạn? Cho dù bạn điều hành một nhà hàng hay quán cà phê, một khách sạn hay một công ty phục vụ ăn uống, Scrap Saver đều có giải pháp cho vấn đề của bạn.
Kể từ khi việc xử lý riêng chất thải thực phẩm thương mại được bắt buộc theo luật vào năm ngoái, ngày càng có nhiều doanh nghiệp đã tìm đến chúng tôi để xử lý phế liệu nấu ăn và các sản phẩm thực phẩm còn sót lại của họ. Chúng tôi cung cấp dịch vụ nhận và vận chuyển các vật liệu này với giá rẻ, thuận tiện đến các cơ sở của chúng tôi, nơi chúng được chuyển đổi thành nhiên liệu thay thế và phân bón hữu cơ. Khách hàng chỉ cần thu gom chất thải thực phẩm trong một trong các thùng lưu trữ miễn phí của chúng tôi hoặc của riêng họ cho đến thời gian nhận hàng được chỉ định, có thể được lên lịch thường xuyên khi cần thiết.
Scrap Saver cung cấp dịch vụ loại bỏ tất cả các loại bao bì thực phẩm với phí xử lý hợp lý và chúng tôi thậm chí có thể cung cấp dịch vụ vận chuyển số lượng lớn cho doanh nghiệp tạo ra hơn ba tấn chất thải mỗi tuần.
Truy cập www.scrapsaver.com để tìm hiểu thêm! 
=========
Tin nhắn E-Mail
Từ: Margaret Ross <mross@scrapsaver.com>
Gửi: Jake Pierce <jake.pierce@babybudfood.com>
Chủ đề: Thông tin về Scrap Saver
Ngày: 14 tháng 11
Kính gửi ông Pierce,
Cảm ơn bạn đã liên hệ với chúng tôi thay mặt cho Tập đoàn Thực phẩm Babybud. Tôi rất hân hạnh được trả lời các câu hỏi mà bạn đã hỏi trong biểu mẫu trực tuyến mà bạn đã điền.
Mức giá của chúng tôi là 0,26 đô la cho mỗi lít chất thải thực phẩm, cộng với phí nhận hàng dựa trên khoảng cách sẽ là 11,00 đô la cho mỗi lần truy cập do vị trí của công ty bạn. Bạn sẽ không bị tính phí xử lý và không có chi phí bổ sung cho việc nhận hàng vào cuối tuần. Việc thanh toán được thực hiện vào cuối mỗi tháng dương lịch.
Xin đừng ngần ngại trả lời e-mail này hoặc gọi cho tôi theo số 555-0189 nếu bạn có thêm câu hỏi hoặc sẵn sàng tham gia các dịch vụ của Scrap Saver.
Trân trọng,
Margaret Ross
Đại diện bán hàng
Scrap Saver, Incorporated');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7181, 5698, 181, 'What is mentioned about commercial food waste?', 'It is growing in volume each year', 'It is harmful to the environment', 'It is generated mostly by restaurants', 'It was the subject of a recent regulation', 'D', 'Đáp án đúng là D.
Giải thích:
Theo quảng cáo, "the separate disposal of commercial food waste became mandated by law last year" (việc xử lý rác thải thực phẩm thương mại riêng biệt đã trở thành yêu cầu bắt buộc theo luật năm ngoái).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được đề cập về rác thải thực phẩm thương mại?
A. Nó đang tăng về khối lượng mỗi năm
B. Nó có hại cho môi trường
C. Nó chủ yếu được tạo ra bởi nhà hàng
D. Nó là đối tượng của một quy định gần đây');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7182, 5698, 182, 'What does the advertisement suggest about Scrap Saver?', 'It operates waste processing facilities', 'It plans to expand the variety of materials it transports', 'It gives clients advice on reducing waste', 'Its delivery trucks run on alternative fuels', 'A', 'Đáp án đúng là A.
Giải thích:
Quảng cáo đề cập "transport of these materials to our facilities, where they are converted into alternative fuels and organic fertilizer" (vận chuyển các vật liệu này đến cơ sở của chúng tôi, nơi chúng được chuyển đổi thành nhiên liệu thay thế và phân bón hữu cơ), cho thấy công ty vận hành các cơ sở xử lý chất thải.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Quảng cáo gợi ý điều gì về Scrap Saver?
A. Nó vận hành các cơ sở xử lý chất thải
B. Nó có kế hoạch mở rộng các loại vật liệu vận chuyển
C. Nó tư vấn cho khách hàng về giảm thiểu chất thải
D. Xe tải của nó chạy bằng nhiên liệu thay thế');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7183, 5698, 183, 'In the e-mail, the word "given" in paragraph 2, line 2, is closest in meaning to', 'regarding', 'considering', 'specified', 'assigned', 'B', 'Đáp án đúng là B.
Giải thích:
Từ "given" trong câu "given your company''s location" có nghĩa là "considering" (xét đến, khi xét đến) vị trí công ty của bạn.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Trong email, từ "given" ở đoạn 2, dòng 2, có nghĩa gần nhất với từ nào?
A. về
B. xét đến
C. được chỉ định
D. được giao');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7184, 5698, 184, 'According to the e-mail, what does Scrap Saver most likely do once per month?', 'Adjust a service rate', 'Replace a storage container', 'Calculate a total number of liters', 'Confirm the desired pickup frequency', 'C', 'Đáp án đúng là C.
Giải thích:
Theo email, "Billing is done at the end of each calendar month" (Lập hóa đơn được thực hiện vào cuối mỗi tháng). Vì giá được tính theo lít ($0.26 per liter), công ty cần tính tổng số lít để lập hóa đơn.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo email, điều gì Scrap Saver nhiều khả năng làm một lần mỗi tháng?
A. Điều chỉnh mức phí dịch vụ
B. Thay thế thùng chứa
C. Tính tổng số lít
D. Xác nhận tần suất thu gom mong muốn');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7185, 5698, 185, 'What can be concluded about Babybud Food Corporation?', 'It has more than one manufacturing location', 'It does not plan to send packaged food to Scrap Saver', 'It produces multiple tons of food waste per week', 'It has not used a food waste disposal service previously', 'B', 'Đáp án đúng là B.
Giải thích:
Trong email báo giá, Ms. Ross nói "You wouldn''t be charged handling fees" (Bạn sẽ không bị tính phí xử lý). Vì Scrap Saver tính phí xử lý cho việc thu gom bao bì thực phẩm, điều này ngụ ý rằng Babybud Food Corporation không có kế hoạch gửi thực phẩm đóng gói.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì có thể kết luận về Tập đoàn Thực phẩm Babybud?
A. Nó có nhiều hơn một địa điểm sản xuất
B. Nó không có kế hoạch gửi thực phẩm đóng gói cho Scrap Saver
C. Nó tạo ra nhiều tấn rác thải thực phẩm mỗi tuần
D. Nó chưa từng sử dụng dịch vụ xử lý rác thải thực phẩm trước đây');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5699, 252, NULL, NULL, 'http://www.creativekates.com
Creative Kate''s
Creative Kate''s is an arts and crafts supplies store run by creative people for our fellow makers. We have everything you need to create beautiful and unique paintings, quilts, jewelry, scrapbooks, and more. Looking for inspiration? Check out this page to see what our staff and patrons have made with materials sold at our store!
Our store is organized into the following four sections for customer convenience:
Section A (Aisles 1-3)
supplies for dressmaking, other sewing projects, and knitting
Section B (Aisles 4-5)
general crafting products such as beads, stamps, glue, and colored paper
Section C (Aisle 6)
painting and drawing supplies
Section D (Aisles 7-8)
organization and storage solutions, home and seasonal décor
==========
NOTICE
Attention, Customers!
Creative Kate''s will soon begin offering in-store classes on various arts and crafts! Please excuse any dust or noise created as we replace part of our fabric aisles with the class space. And don''t forget to look for more information on our classes in the weeks to come!
Also, please be aware that our self-service checkout machines do not accept cash. If you wish to make a cash purchase, visit a staffed register.
Thank you.
==========
http://www.shoppingcritic.com/reviews/creativekates
Reviewer: Etsuji Chiba
Posted: June 4
I had a very positive experience at Creative Kate''s. I was putting together a private party at a hotel when my clients decided at the last minute that the staff there hadn''t made the venue look festive enough. I ran over to Creative Kate''s and explained the situation to the first employee I saw.
She led me to the holiday decorations and quickly suggested a few suitable products. The prices were very reasonable, and after I''d put the items up in the venue, the atmosphere really did become much warmer and more cheerful. Thanks for your help, Creative Kates!', 'http://www.creativekates.com
Creative Kate''s
Creative Kate''s là một cửa hàng cung cấp nghệ thuật và thủ công do những người sáng tạo điều hành cho các nhà sản xuất đồng nghiệp của chúng tôi. Chúng tôi có mọi thứ bạn cần để tạo ra những bức tranh, chăn bông, đồ trang sức, sổ lưu niệm đẹp và độc đáo, v.v. Tìm kiếm cảm hứng? Hãy xem trang này để xem nhân viên và khách hàng quen của chúng tôi đã làm gì với các vật liệu được bán tại cửa hàng của chúng tôi! 
Cửa hàng của chúng tôi được chia thành bốn phần sau để thuận tiện cho khách hàng:
Phần A (Lối đi 1-3)
Đồ dùng cho may mặc, các dự án may khác và đan lát
Phần B (Lối đi 4-5)
Các sản phẩm thủ công chung như hạt cườm, tem, keo và giấy màu
Phần C (Lối 6)
Đồ dùng vẽ và vẽ tranh
Phần D (Lối 7-8)
Giải pháp tổ chức và lưu trữ, trang trí nhà và theo mùa
============
THÔNG BÁO
Chú ý, Khách hàng! 
Creative Kate''s sẽ sớm bắt đầu cung cấp các lớp học tại cửa hàng về các nghệ thuật và thủ công khác nhau! Vui lòng tha thứ cho bất kỳ bụi hoặc tiếng ồn nào được tạo ra khi chúng tôi thay thế một phần lối đi bằng vải của chúng tôi bằng không gian lớp học. Và đừng quên tìm kiếm thêm thông tin về các lớp học của chúng tôi trong những tuần tới! 
Ngoài ra, xin lưu ý rằng các máy thanh toán tự phục vụ của chúng tôi không chấp nhận tiền mặt. Nếu bạn muốn mua bằng tiền mặt, hãy truy cập quầy đăng ký có nhân viên.
Cảm ơn bạn.
============
http://www.shoppingcritic.com/reviews/creativekates
Người đánh giá: Etsuji Chiba
Đã đăng: ngày 4 tháng 6
Tôi đã có trải nghiệm rất tích cực tại Creative Kate''s. Tôi đang tổ chức một bữa tiệc riêng tại một khách sạn thì khách hàng của tôi quyết định vào phút cuối rằng nhân viên ở đó đã không làm cho địa điểm trông đủ lễ hội. Tôi chạy đến Creative Kate''s và giải thích tình hình cho nhân viên đầu tiên mà tôi gặp.
Cô ấy dẫn tôi đến cửa hàng trang trí ngày lễ và nhanh chóng đề xuất một vài sản phẩm phù hợp. Giá cả rất hợp lý, và sau khi tôi đặt các món đồ lên địa điểm, bầu không khí thực sự trở nên ấm áp và vui vẻ hơn nhiều. Cảm ơn sự giúp đỡ của bạn, Creative Kates!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7186, 5699, 186, 'What does the Web page indicate about the store''s Web site?', 'It lists the major brands that the store carries', 'It displays images of works created by customers', 'It provides instructions for independent craft projects', 'It includes profiles of some staff members', 'B', 'Đáp án đúng là B.
Giải thích:
Trang web đề cập "Check out this page to see what our staff and patrons have made with materials sold at our store" (Xem trang này để thấy những gì nhân viên và khách hàng của chúng tôi đã làm với vật liệu bán tại cửa hàng).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Trang web cho biết gì về trang web của cửa hàng?
A. Nó liệt kê các thương hiệu chính mà cửa hàng bán
B. Nó hiển thị hình ảnh tác phẩm được tạo ra bởi khách hàng
C. Nó cung cấp hướng dẫn cho các dự án thủ công độc lập
D. Nó bao gồm hồ sơ của một số nhân viên');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7187, 5699, 187, 'What does the notice suggest about Creative Kate''s?', 'It will begin selling a new type of product', 'It has automated part of the shopping process', 'It is seeking replacement instructors for some classes', 'It no longer allows customers to pay with cash', 'C', 'Đáp án đúng là C.
Giải thích:
Thông báo cho biết cửa hàng sẽ bắt đầu cung cấp các lớp học về nghệ thuật và thủ công tại cửa hàng, điều này gợi ý họ đang tìm kiếm giảng viên thay thế cho một số lớp học.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Thông báo gợi ý điều gì về Creative Kate''s?
A. Nó sẽ bắt đầu bán một loại sản phẩm mới
B. Nó đã tự động hóa một phần quá trình mua sắm
C. Nó đang tìm kiếm giảng viên thay thế cho một số lớp học
D. Nó không còn cho phép khách hàng thanh toán bằng tiền mặt');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7188, 5699, 188, 'Which area of Creative Kate''s will be reduced in size?', 'Section A', 'Section B', 'Section C', 'Section D', 'A', 'Đáp án đúng là A.
Giải thích:
Thông báo nói họ sẽ thay thế một phần khu vực vải vóc (fabric aisles) để làm không gian lớp học. Theo bố trí cửa hàng, Section A (Aisles 1-3) chứa vật liệu may mặc và may vá, vì vậy đây là khu vực sẽ bị giảm kích thước.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Khu vực nào của Creative Kate''s sẽ bị giảm kích thước?
A. Khu vực A
B. Khu vực B
C. Khu vực C
D. Khu vực D');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7189, 5699, 189, 'What most likely is Mr. Chiba''s job?', 'Hotel manager', 'Art instructor', 'Interior designer', 'Event planner', 'D', 'Đáp án đúng là D.
Giải thích:
Mr. Chiba đề cập đến việc tổ chức một buổi tiệc riêng tại khách sạn cho khách hàng của mình ("putting together a private party at a hotel" và "my clients"), điều này cho thấy anh ấy là một người tổ chức sự kiện.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Công việc của ông Chiba nhiều khả năng là gì?
A. Quản lý khách sạn
B. Giảng viên nghệ thuật
C. Nhà thiết kế nội thất
D. Người tổ chức sự kiện');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7190, 5699, 190, 'What is implied about Mr. Chiba?', 'He watched a demonstration led by an employee', 'He took advantage of a seasonal discount offer', 'He purchased goods from an aisle in Section D', 'He first visited the store to attend a celebration', 'C', 'Đáp án đúng là C.
Giải thích:
Nhân viên dẫn Mr. Chiba đến khu vực trang trí ngày lễ (holiday decorations), và theo bố trí cửa hàng, trang trí theo mùa nằm trong Section D (Aisles 7-8). Do đó, ông ấy đã mua hàng từ một lối đi trong Section D.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được ngụ ý về ông Chiba?
A. Ông ấy đã xem một buổi trình diễn do nhân viên dẫn dắt
B. Ông ấy đã tận dụng ưu đãi giảm giá theo mùa
C. Ông ấy đã mua hàng từ một lối đi trong Khu vực D
D. Ông ấy lần đầu đến cửa hàng để tham dự một lễ kỷ niệm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5700, 252, NULL, NULL, 'From: Carmen Avila <c.avila@keenmaninc.com>
To: Andrew Foster <a.foster@keenmaninc.com>
Subject: Hardeston trip
Date: September 9
Hello Andrew,
I''ve finished researching travel options for your visit to the Hardeston factory next month, and I''m happy to say that there are Rubin Air flights departing quite close to your desired times for both parts of the trip. How does this itinerary sound?
Monday, October 11
Depart Colburn: 9:20 A.M.
Arrive in Hardeston: 12:15 P.M.
Thursday, October 14
Depart Hardeston: 4:00 P.M.
Arrive Colburn: 6:45 P.M.
Please note that both flights use Hardeston Regional Airport, as it''s much closer than Hardeston-Molkis International to the company''s preferred hotel, the Mezzine Suites in eastern Hardeston. If these flights are acceptable, I will finalize the bookings immediately, using the same frequent flyer account information you provided to me before your trip in July.
Also, you might want a rental car to get around in because taxi service in the area is unreliable and ride-sharing apps were recently banned. Let me know if you''d like me to reserve one.
Best,
Carmen
===========
From: Andrew Foster <a.foster@keenmaninc.com>
To: Carmen Avila <c.avila@keenmaninc.com>
Subject: Re: Hardeston trip
Date: September 10
Hi Carmen,
Thank you for the information and advice, but can you hold off on making any bookings for a few days? I''m considering whether to invite a colleague along on the trip. He''s the new product manager for our handheld vacuum cleaner, and it may be helpful to show him where it''s made and introduce the manufacturing team. I''ll update you once the matter has been settled.
—Andrew
==========
MATTOX
Reservation Number: 2023944
Booking Details
Vehicle: Mireles Lyrica Sedan
Pickup: Monday, October 11, 12:45 P.M.
Hardeston Regional Airport Branch
Return: Thursday, October 14, 3:00 P.M.
Hardeston Regional Airport Branch
Driver Information
Name: Andrew Foster
Contact: 555-0184 (mobile)
Additional Authorized Driver: Rajesh Banik
Additional Information
Corporate Account Number: 45587 (Keenman Incorporated)', 'Từ: Carmen Avila <c.avila@keenmaninc.com>
Gửi: Andrew Foster <a.foster@keenmaninc.com>
Chủ đề: Chuyến đi Hardeston
Ngày: 9 tháng 9
Xin chào Andrew,
Tôi đã hoàn thành việc nghiên cứu các lựa chọn du lịch cho chuyến thăm của bạn đến nhà máy Hardeston vào tháng tới và tôi rất vui khi nói rằng có các chuyến bay của Rubin Air khởi hành khá gần với thời gian mong muốn của bạn cho cả hai phần của chuyến đi. Hành trình này nghe như thế nào? 
Thứ Hai, ngày 11 tháng 10
Khởi hành từ Colburn: 9:20 sáng
Đến đến Hardeston: 12:15 chiều
Thứ Năm, ngày 14 tháng 10
Khởi hành từ Hardeston: 4:00 chiều
Đến đến Colburn: 6:45 chiều
Xin lưu ý rằng cả hai chuyến bay đều sử dụng Sân bay Khu vực Hardeston, vì nó gần hơn nhiều so với Sân bay Quốc tế Hardeston-Molkis đến khách sạn ưa thích của công ty, Mezzine Suites ở phía đông Hardeston. Nếu những chuyến bay này được chấp nhận, tôi sẽ hoàn tất việc đặt chỗ ngay lập tức, sử dụng cùng thông tin tài khoản khách hàng thường xuyên mà bạn đã cung cấp cho tôi trước chuyến đi của bạn vào tháng Bảy.
Ngoài ra, bạn có thể muốn thuê một chiếc xe hơi để đi lại vì dịch vụ taxi trong khu vực không đáng tin cậy và các ứng dụng đi chung xe gần đây đã bị cấm. Hãy cho tôi biết nếu bạn muốn tôi đặt một cái.
Tốt nhất,
Carmen
===========
Từ: Andrew Foster <a.foster@keenmaninc.com>
Gửi: Carmen Avila <c.avila@keenmaninc.com>
Chủ đề: Re: Chuyến đi Hardeston
Ngày: 10 tháng 9
Xin chào Carmen,
Cảm ơn bạn đã cung cấp thông tin và lời khuyên, nhưng bạn có thể trì hoãn việc đặt chỗ trong vài ngày không? Tôi đang cân nhắc có nên mời một đồng nghiệp đi cùng trong chuyến đi hay không. Anh ấy là giám đốc sản phẩm mới cho máy hút bụi cầm tay của chúng tôi, và có thể hữu ích khi chỉ cho anh ấy nơi nó được sản xuất và giới thiệu đội ngũ sản xuất. Tôi sẽ cập nhật cho bạn khi vấn đề đã được giải quyết.
—Andrew
============
MATTOX
Số đặt chỗ: 2023944
Chi tiết đặt chỗ
Xe: Mireles Lyrica Sedan
Đón: Thứ Hai, ngày 11 tháng 10, 12:45 chiều.
Chi nhánh sân bay khu vực Hardeston
Trả lại: Thứ Năm, ngày 14 tháng 10, 3:00 chiều
Chi nhánh sân bay khu vực Hardeston
Thông tin tài xế
Tên: Andrew Foster
Liên hệ: 555-0184 (di động)
Tài xế được ủy quyền bổ sung: Rajesh Banik
Thông tin bổ sung
Số tài khoản công ty: 45587 (Keenman Incorporated)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7191, 5700, 191, 'What is indicated about Hardeston Regional Airport?', 'It is not the only airport near the city', 'It has a reputation for punctual departures', 'It is currently undergoing renovations', 'It is not served frequently by Rubin Air', 'A', 'Đáp án đúng là A.
Giải thích:
Theo email của Carmen Avila, có đề cập đến hai sân bay: "both flights use Hardeston Regional Airport, as it''s much closer than Hardeston-Molkis International" (cả hai chuyến bay đều sử dụng sân bay Hardeston Regional, vì nó gần hơn nhiều so với sân bay Quốc tế Hardeston-Molkis). Điều này chỉ ra rằng Hardeston Regional Airport không phải là sân bay duy nhất gần thành phố.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về sân bay Hardeston Regional?
A. Nó không phải là sân bay duy nhất gần thành phố
B. Nó có danh tiếng về khởi hành đúng giờ
C. Nó hiện đang được tu sửa
D. Nó không thường xuyên được phục vụ bởi Rubin Air;');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7192, 5700, 192, 'What is suggested about Mr. Foster?', 'He was recently promoted to a managerial position', 'He visited Hardeston in July', 'He has taken a trip planned by Ms. Avila before', 'He stated a preference for a certain hotel', 'C', 'Đáp án đúng là C.
Giải thích:
Trong email, Ms. Avila đề cập sẽ sử dụng "the same frequent flyer account information you provided to me before your trip in July" (thông tin tài khoản khách hàng thân thiết bạn đã cung cấp cho tôi trước chuyến đi tháng 7), cho thấy cô ấy đã từng lên kế hoạch cho chuyến đi trước đây của Mr. Foster.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về ông Foster?
A. Ông ấy gần đây đã được thăng chức lên vị trí quản lý
B. Ông ấy đã đến thăm Hardeston vào tháng 7
C. Ông ấy đã từng đi chuyến công tác do cô Avila lên kế hoạch
D. Ông ấy đã nêu sở thích về một khách sạn nhất định;');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7193, 5700, 193, 'Where most likely does Mr. Foster work?', 'At an automobile manufacturer', 'At an appliance company', 'At an aircraft design firm', 'At a home furnishings business', 'B', 'Đáp án đúng là B.
Giải thích:
Trong email thứ hai, Mr. Foster đề cập đến "product manager for our handheld vacuum cleaner" (quản lý sản phẩm máy hút bụi cầm tay), cho thấy ông ấy làm việc cho một công ty thiết bị gia dụng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ông Foster nhiều khả năng làm việc ở đâu?
A. Tại một nhà sản xuất ô tô
B. Tại một công ty thiết bị gia dụng
C. Tại một công ty thiết kế máy bay
D. Tại một doanh nghiệp nội thất gia đình');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7194, 5700, 194, 'What did Mr. Foster most likely do in response to advice?', 'He chose different lodgings', 'He joined an airline loyalty program', 'He downloaded a mobile app', 'He requested a rental vehicle', 'D', 'Đáp án đúng là D.
Giải thích:
Ms. Avila khuyên về việc thuê xe vì dịch vụ taxi không đáng tin cậy và ứng dụng đi chung xe đã bị cấm. Biểu mẫu đặt xe từ Mattox cho thấy Mr. Foster đã làm theo lời khuyên này và yêu cầu thuê xe.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ông Foster nhiều khả năng đã làm gì để đáp lại lời khuyên?
A. Ông ấy đã chọn chỗ ở khác
B. Ông ấy đã tham gia chương trình khách hàng thân thiết của hãng hàng không
C. Ông ấy đã tải một ứng dụng di động
D. Ông ấy đã yêu cầu thuê xe');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7195, 5700, 195, 'Based on the form, what can be concluded about Mr. Foster?', 'He will be picked up at a transportation hub', 'He asked a coworker to accompany him', 'He decided to extend the length of his stay', 'He will pay an expense with his personal credit card', 'B', 'Đáp án đúng là B.
Giải thích:
Trong biểu mẫu đặt xe có thêm người lái xe được ủy quyền là Rajesh Banik, cho thấy Mr. Foster đã mời đồng nghiệp đi cùng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Dựa trên biểu mẫu, điều gì có thể kết luận về ông Foster?
A. Ông ấy sẽ được đón tại một trung tâm giao thông
B. Ông ấy đã yêu cầu một đồng nghiệp đi cùng
C. Ông ấy quyết định kéo dài thời gian lưu trú
D. Ông ấy sẽ thanh toán chi phí bằng thẻ tín dụng cá nhân');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5701, 252, NULL, NULL, 'http://www.kolkataxyz.in/bambootableware
Kolkata XYZ Bamboo Tableware
For over 15 years, Kolkata XYZ has used bamboo grown right here in West Bengal to make plates, cups, utensils, and other dining necessities. Read on to learn just a few of the many beneficial characteristics of bamboo tableware.
1. Sustainable - Bamboo is very environmentally friendly. Bamboo plants are a renewable resource, and when your bamboo tableware is no longer useable, it can be recycled or composted.
2. Chemical-Free - Bamboo plants require no pesticides to grow, and the manufacturing process for our tableware involves heat and pressure, not artificial chemicals.
3. Durable - Bamboo tableware is difficult to break and, though some care must be taken, it can be heated in the microwave, stored in the freezer, and washed in the dishwasher without damage.
4. Lightweight - Bamboo is lighter than most tableware materials, making it an excellent choice for families with young children. This also means that our products are very affordable to ship.
5. Versatile Style - Bamboo''s neutral wood tones, which we highlight in simple, clean shapes, serve as an elegant complement to a wide range of color and design schemes.
==========
To: Deepa Sanyal
From:  Sikha Lahiri
Date: 7 October
Subject: Bamboo utensils
Dear Ms. Sanyal,
It was a pleasure to speak with you at last week''s trade show. I found your points about the environmental advantages of your company''s bamboo tableware very persuasive. So, I have decided that your travel utensil set will make an excellent thank-you gift for the Gir Society''s donors, who care deeply about the Earth.
You mentioned that there are several options for the set''s carrying case. Could you provide me with details about them? I am particularly interested in comparing their prices (as I prefer an affordable option) and finding the one that causes the least damage to our planet.
Sincerely,
Sikha Lahiri
The Gir Society
==========
**To:** Sikha Lahiri
**From:** Deepa Sanyal
**Date:** 8 October
**Subject:** Re: Bamboo utensils
Dear Ms. Lahiri,
Thank you for your e-mail. Below is a comparison of the available types of carrying cases for the travel utensil set.
**Case**                                                                      **Unit price**            **Environmental harm**
Hard plastic case with snap-lock closure  $1.45                     High
Cotton pouch with snap buttons                  $1.70                     Low
Nylon zippered case                                          $2.10                     Medium
Canvas roll-up bag with tie straps              $2.95                     Low
Please note that a minimum order of 50 units is required. Also, whichever type of case you choose, we would be happy to add your organization''s logo and some lettering, such as a thank-you message to your donors, though this will involve an additional fee.
I hope to hear from you again soon.
Sincerely, Deepa Sanyal Kolkata XYZ', 'http://www.kolkataxyz.in/bambootableware
Kolkata XYZ Bamboo Tableware
Trong hơn 15 năm, Kolkata XYZ đã sử dụng tre được trồng ngay tại Tây Bengal để làm đĩa, cốc, đồ dùng và các nhu yếu phẩm ăn uống khác. Đọc tiếp để tìm hiểu một vài trong số nhiều đặc điểm có lợi của bộ đồ ăn bằng tre.
1. Bền vững - Tre rất thân thiện với môi trường. Cây tre là một nguồn tài nguyên tái tạo và khi bộ đồ ăn bằng tre của bạn không còn sử dụng được nữa, nó có thể được tái chế hoặc ủ phân.
2. Không chứa hóa chất - Cây tre không cần thuốc trừ sâu để phát triển và quy trình sản xuất bộ đồ ăn của chúng tôi liên quan đến nhiệt và áp suất, không phải hóa chất nhân tạo.
3. Bền bỉ - Bộ đồ ăn bằng tre rất khó vỡ và mặc dù phải cẩn thận, nó có thể được làm nóng trong lò vi sóng, bảo quản trong tủ đông và rửa trong máy rửa chén mà không bị hư hại.
4. Nhẹ - Tre nhẹ hơn hầu hết các vật liệu bộ đồ ăn, khiến nó trở thành một lựa chọn tuyệt vời cho các gia đình có trẻ nhỏ. Điều này cũng có nghĩa là các sản phẩm của chúng tôi rất phải chăng để vận chuyển.
5. Phong cách linh hoạt - Tông màu gỗ trung tính của tre, mà chúng tôi làm nổi bật trong các hình dạng đơn giản, sạch sẽ, phục vụ như một sự bổ sung thanh lịch cho một loạt các phối màu và thiết kế.
=========
Gửi: Deepa Sanyal
Từ: Sikha Lahiri
Ngày: 7 tháng 10
Chủ đề: Đồ dùng tre
Kính gửi cô Sanyal,
Rất vui được nói chuyện với bạn tại triển lãm thương mại tuần trước. Tôi thấy quan điểm của bạn về lợi thế môi trường của bộ đồ ăn bằng tre của công ty bạn rất thuyết phục. Vì vậy, tôi đã quyết định rằng bộ dụng cụ du lịch của bạn sẽ là một món quà cảm ơn tuyệt vời cho các nhà tài trợ của Gir Society, những người quan tâm sâu sắc đến Trái đất.
Bạn đã đề cập rằng có một số lựa chọn cho hộp đựng của bộ. Bạn có thể cung cấp cho tôi thông tin chi tiết về chúng không? Tôi đặc biệt quan tâm đến việc so sánh giá của họ (vì tôi thích một lựa chọn giá cả phải chăng) và tìm ra một lựa chọn ít gây thiệt hại nhất cho hành tinh của chúng ta.
Trân trọng,
Sikha Lahiri
Hiệp hội Gir
============
**Gửi:** Sikha Lahiri
**Từ:** Deepa Sanyal
**Ngày:** 8 tháng 10
**Chủ đề:** Re: Đồ dùng tre
Kính gửi cô Lahiri,
Cảm ơn e-mail của bạn. Dưới đây là so sánh các loại hộp đựng có sẵn cho bộ dụng cụ du lịch.
**Hộp** **Đơn giá** **Tác hại môi trường**
Cứng Hộp nhựa có khóa snap-lock $1,45 Túi cotton cao
Túi cotton có nút snap $1,70 Low
Hộp nylon có khóa kéo $2.10 Trung bình
Túi cuộn vải có dây buộc $2.95 Thấp
Xin lưu ý rằng yêu cầu đặt hàng tối thiểu 50 chiếc. Ngoài ra, bất kể bạn chọn loại trường hợp nào, chúng tôi rất sẵn lòng thêm logo tổ chức của bạn và một số chữ cái, chẳng hạn như tin nhắn cảm ơn đến các nhà tài trợ của bạn, mặc dù điều này sẽ liên quan đến một khoản phí bổ sung.
Tôi hy vọng sớm nhận được phản hồi từ bạn.
Trân trọng, Deepa Sanyal Kolkata XYZ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7196, 5701, 196, 'What is indicated about Kolkata XYZ?', 'It also sells children''s toys', 'It imports bamboo from abroad', 'Its primary customers are frequent travelers', 'Its tableware can be used in kitchen appliances', 'D', 'Đáp án đúng là D.
Giải thích:
