INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7201, 5702, 1, 'Look at the picture marked number one in your test book.', 'The man is carrying pieces of wood.', 'The man is charging a power tool.', 'The man is assembling some furniture.', 'The man is cleaning up a workshop.', 'C', 'A Người đàn ông đang mang những mảnh gỗ.
B Người đàn ông đang sạc một công cụ điện.
C Người đàn ông đang lắp ráp một số đồ nội thất.
D Người đàn ông đang dọn dẹp một xưởng làm việc.');;
