INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7202, 5703, 2, 'Look at the picture marked number two in your test book.', 'Some people are gathered on a balcony.', 'Someone is polishing the sliding doors.', 'Some tree branches have been trimmed.', 'Some outdoor railings have been removed.', 'A', 'A Một số người đang tụ tập trên ban công.
B Ai đó đang đánh bóng những cánh cửa trượt.
