INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5705, 253, '2025/test7/audio/test7_question_4.mp3', '2025/test7/image/test7-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7204, 5705, 4, 'Look at the picture marked number four in your test book.', 'A wheel is being stored in a cabinet.', 'The man is sitting on a bench outdoors.', 'A tree has fallen across a bike path.', 'The man is inspecting a wheel.', 'D', 'A Một chiếc bánh xe đang được cất trong tủ.
B Người đàn ông đang ngồi trên một chiếc ghế dài ngoài trời.
