INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5706, 253, '2025/test7/audio/test7_question_5.mp3', '2025/test7/image/test7-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7205, 5706, 5, 'Look at the picture marked number five in your test book.', 'Some artwork is hanging on a wall.', 'Reading materials have been left on a sofa.', 'Some windows are being installed.', 'Some potted plants have fallen on the floor.', 'A', 'A Một số tác phẩm nghệ thuật đang treo trên tường.
B Vật liệu đọc đã bị để lại trên một chiếc ghế sofa.
C Một số cửa sổ đang được lắp đặt.
D Một số cây trồng trong chậu đã rơi xuống sàn nhà.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5707, 253, '2025/test7/audio/test7_question_6.mp3', '2025/test7/image/test7-image-6.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7206, 5707, 6, 'Look at the picture marked number six in your test book.', 'There are some restaurant menus stacked in a pile.', 'There''s an awning stretching over a walkway.', 'He is wiping his hands on his apron.', 'He''s spraying water on the pavement.', 'B', 'A Một số thực đơn nhà hàng được xếp chồng lên nhau.
B Có một mái hiên kéo dài trên lối đi bộ.
C Anh ấy đang lau tay vào chiếc tạp dề của mình.
D Anh ấy đang xịt nước lên vỉa hè.');;

-- Data for 2025 Test7 Part 2
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5708, 254, '2025/test7/audio/test7_question_7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7207, 5708, 7, 'You get your dry cleaning delivered, don''t you?', 'Please make sure it is completely dry.', 'We clean the floor after closing time.', 'Yes, once in a while.', NULL, 'C', 'Câu hỏi: Bạn có nhận đồ giặt khô giao tận nhà không?"
A: "Vui lòng đảm bảo rằng nó đã khô hoàn toàn."
B: "Chúng tôi dọn vệ sinh sàn sau giờ đóng cửa."
C: "Vâng, thỉnh thoảng thôi."
Giải thích: Đáp án C đúng vì câu hỏi về việc nhận đồ giặt khô, và đáp án C cho biết đó là việc làm thỉnh thoảng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5709, 254, '2025/test7/audio/test7_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7208, 5709, 8, 'Did you get your business cards from the printing department yet?', 'No, they''ve had numerous requests lately.', 'Alright, that looks much better actually.', 'A shipment of toner.', NULL, 'A', 'Câu hỏi: Bạn đã nhận được danh thiếp từ phòng in chưa?"
A: "Không, họ đã nhận được rất nhiều yêu cầu gần đây."
B: "Được rồi, trông thực sự tốt hơn."
C: "Một lô hàng mực in."
Giải thích: Đáp án A đúng vì câu hỏi về việc nhận danh thiếp, và đáp án A nói về việc phòng in có rất nhiều yêu cầu nên việc hoàn thành bị chậm."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5710, 254, '2025/test7/audio/test7_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7209, 5710, 9, 'Why was the ferry service canceled today?', 'Because the high winds are causing rough waters.', 'Let''s take the earliest journey that we can.', 'From the observation deck, I think.', NULL, 'A', 'Câu hỏi: Tại sao dịch vụ phà bị hủy hôm nay?"
A: "Vì gió mạnh đang tạo ra sóng lớn."
B: "Chúng ta hãy đi chuyến sớm nhất mà chúng ta có thể."
C: "Từ đài quan sát, tôi nghĩ vậy."
Giải thích: Đáp án A đúng vì câu hỏi về lý do hủy dịch vụ phà, và đáp án A giải thích rằng gió mạnh gây ra sóng lớn làm phà không thể hoạt động."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5711, 254, '2025/test7/audio/test7_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7210, 5711, 10, 'How often can we request office supplies for the team?', 'No, I''m not surprised at all.', 'Mainly staples and paper clips.', 'You''re allowed to do it every month.', NULL, 'C', 'Câu hỏi: Chúng ta có thể yêu cầu vật tư văn phòng cho nhóm bao lâu một lần?"
A: "Không, tôi không ngạc nhiên chút nào."
B: "Chủ yếu là kẹp giấy và ghim giấy."
C: "Bạn được phép yêu cầu mỗi tháng một lần."
Giải thích: Đáp án C đúng vì câu hỏi về tần suất yêu cầu vật tư văn phòng, và đáp án C chỉ ra rằng vật tư có thể được yêu cầu mỗi tháng một lần."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5712, 254, '2025/test7/audio/test7_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7211, 5712, 11, 'When are you giving your speech at the conference?', 'The timetable hasn''t been finalized.', 'At least one hour, including questions.', 'A speech about literacy rates.', NULL, 'A', 'Câu hỏi: Khi nào bạn sẽ phát biểu tại hội nghị?"
A: "Lịch trình vẫn chưa được hoàn thiện."
B: "Ít nhất một giờ, bao gồm cả phần hỏi đáp."
C: "Một bài phát biểu về tỷ lệ biết chữ."
Giải thích: Đáp án A đúng vì câu hỏi về thời gian phát biểu, và đáp án A cho biết lịch trình phát biểu chưa được xác nhận."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5713, 254, '2025/test7/audio/test7_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7212, 5713, 12, 'Have you emptied the boxes that arrived from the vendor?', 'Is this box large enough?', 'Yes, the contents are unpacked and organized.', 'I can pour you another one.', NULL, 'B', 'Câu hỏi: Bạn đã dỡ các hộp đến từ nhà cung cấp chưa?"
A: "Cái hộp này có đủ lớn không?"
B: "Vâng, các vật phẩm đã được dỡ ra và sắp xếp."
C: "Tôi có thể rót thêm cho bạn một ly nữa."
Giải thích: Đáp án B đúng vì câu hỏi về việc dỡ đồ trong các hộp, và đáp án B xác nhận các vật phẩm đã được sắp xếp."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5714, 254, '2025/test7/audio/test7_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7213, 5714, 13, 'Would you like to try the online photo-editing software?', 'Did you wait in the line?', 'Sure, I''ll make some time for that.', 'Images from our company retreat.', NULL, 'B', 'Câu hỏi: Bạn có muốn thử phần mềm chỉnh sửa ảnh trực tuyến không?"
A: "Bạn có đợi trong hàng không?"
B: "Chắc chắn, tôi sẽ dành chút thời gian cho việc đó."
C: "Những hình ảnh từ chuyến nghỉ dưỡng của công ty chúng ta."
Giải thích: Đáp án B đúng vì câu hỏi về việc thử phần mềm chỉnh sửa ảnh, và đáp án B cho biết người trả lời sẽ dành thời gian để thử phần mềm."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5715, 254, '2025/test7/audio/test7_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7214, 5715, 14, 'Don''t we need a navigation system for the rental car?', 'The station is closed for repairs.', 'The standard size should be suitable.', 'No, I''m familiar with the city.', NULL, 'C', 'Câu hỏi: Chúng ta có cần hệ thống định vị cho chiếc xe thuê không?"
A: "Trạm đã đóng cửa để sửa chữa."
B: "Kích thước tiêu chuẩn sẽ phù hợp."
C: "Không, tôi quen thuộc với thành phố này."
Giải thích: Đáp án C đúng vì câu hỏi về việc có cần hệ thống định vị, và đáp án C cho biết người hỏi đã quen thuộc với thành phố nên không cần sử dụng hệ thống định vị."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5716, 254, '2025/test7/audio/test7_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7215, 5716, 15, 'Could you check that the door to the side entrance has been secured?', 'Would you rather I checked all of them?', 'They were printed earlier this morning.', 'A master key for the whole building.', NULL, 'A', 'Câu hỏi: Bạn có thể kiểm tra cửa vào bên hông đã được khóa chưa?"
A: "Bạn muốn tôi kiểm tra tất cả các cửa không?"
B: "Chúng đã được in vào sáng nay."
C: "Một chìa khóa chính cho toàn bộ tòa nhà."
Giải thích: Đáp án A đúng vì câu hỏi về việc kiểm tra cửa, và đáp án A gợi ý kiểm tra tất cả các cửa nếu cần."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5717, 254, '2025/test7/audio/test7_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7216, 5717, 16, 'I can return the items for a full refund, right?', 'Yes, within thirty days.', 'A seat for my return flight.', 'I think that''s a good price.', NULL, 'A', 'Câu hỏi: Tôi có thể trả lại các món hàng để hoàn tiền đầy đủ phải không?"
A: "Vâng, trong vòng ba mươi ngày."
B: "Một chỗ ngồi cho chuyến bay về của tôi."
C: "Tôi nghĩ đó là một mức giá hợp lý."
Giải thích: Đáp án A đúng vì câu hỏi về việc trả lại hàng và nhận hoàn tiền, và đáp án A chỉ ra rằng việc hoàn tiền có thể thực hiện trong vòng ba mươi ngày."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5718, 254, '2025/test7/audio/test7_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7217, 5718, 17, 'What''s the fee for the hotel''s breakfast buffet?', 'Every morning from 6 A.M.', 'Coffee and tea are included.', 'It''s free with a one-night stay or more.', NULL, 'C', 'Câu hỏi: Phí cho bữa sáng buffet của khách sạn là bao nhiêu?"
A: "Mỗi sáng từ 6 giờ sáng."
B: "Cà phê và trà đã được bao gồm."
C: "Nó miễn phí nếu bạn ở một đêm hoặc lâu hơn."
Giải thích: Đáp án C đúng vì câu hỏi về phí bữa sáng và đáp án C cho biết bữa sáng miễn phí khi lưu trú từ một đêm trở lên."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5719, 254, '2025/test7/audio/test7_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7218, 5719, 18, 'Is the office''s new air conditioning system quiet?', 'Poor weather conditions are expected.', 'I didn''t even notice it was on.', 'Yes, he''s fitting in well.', NULL, 'B', 'Câu hỏi: Hệ thống điều hòa mới của văn phòng có êm không?"
A: "Dự báo thời tiết xấu."
B: "Tôi thậm chí không nhận thấy nó đang hoạt động."
C: "Vâng, anh ấy đang hòa nhập tốt."
Giải thích: Đáp án B đúng vì câu hỏi về tiếng ồn của điều hòa, và đáp án B cho biết người trả lời không nhận thấy điều hòa đang hoạt động."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5720, 254, '2025/test7/audio/test7_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7219, 5720, 19, 'Where can I get some colored paper for printing?', 'The payment is collected by bank transfer.', 'Only department managers can place supply orders.', 'The printer frequently runs out of ink.', NULL, 'B', 'Câu hỏi: Tôi có thể mua giấy màu để in ở đâu?"
A: "Thanh toán được thực hiện qua chuyển khoản ngân hàng."
B: "Chỉ có các trưởng phòng mới có thể đặt hàng vật tư."
C: "Máy in thường xuyên hết mực."
Giải thích: Đáp án B đúng vì câu hỏi về việc mua giấy màu, và đáp án B nói về quyền hạn của các trưởng phòng trong việc đặt hàng vật tư."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5721, 254, '2025/test7/audio/test7_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7220, 5721, 20, 'Would you like some black tea or coffee after your meal?', 'It''s too late to have caffeine.', 'Because the café is well known.', 'Yes, I''m feeling quite full.', NULL, 'A', 'Câu hỏi: Bạn có muốn trà đen hay cà phê sau bữa ăn không?"
A: "Muộn rồi nên tôi không muốn dùng caffein."
B: "Vì quán cà phê rất nổi tiếng."
C: "Vâng, tôi cảm thấy khá no."
Giải thích: Đáp án A đúng vì câu hỏi về trà hoặc cà phê sau bữa ăn, và đáp án A cho biết người trả lời không muốn uống caffein vì đã muộn."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5722, 254, '2025/test7/audio/test7_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7221, 5722, 21, 'How do I renew my newspaper subscription?', 'Thanks for showing me the article.', 'No later than the last day of April.', 'You should contact the customer service team.', NULL, 'C', 'Câu hỏi: Làm thế nào để tôi gia hạn đăng ký báo?"
A: "Cảm ơn bạn đã chỉ cho tôi bài viết."
B: "Không muộn hơn ngày cuối cùng của tháng 4."
C: "Bạn nên liên hệ với đội ngũ dịch vụ khách hàng."
Giải thích: Đáp án C đúng vì câu hỏi về gia hạn đăng ký báo và đáp án C gợi ý liên hệ với bộ phận chăm sóc khách hàng để gia hạn."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5723, 254, '2025/test7/audio/test7_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7222, 5723, 22, 'Your department will undergo a financial audit next month.', 'Five thousand dollars is enough.', 'The bookkeeping is well organized, thankfully.', 'I wasn''t able to attend it.', NULL, 'B', 'Câu hỏi: Phòng của bạn sẽ được kiểm toán tài chính vào tháng tới, phải không?"
A: "Năm nghìn đô la là đủ."
B: "Sổ sách kế toán được tổ chức tốt, thật may mắn."
C: "Tôi đã không thể tham gia."
Giải thích: Đáp án B đúng vì câu hỏi về kiểm toán tài chính và đáp án B xác nhận rằng công tác kế toán của phòng đã được chuẩn bị tốt cho cuộc kiểm toán."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5724, 254, '2025/test7/audio/test7_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7223, 5724, 23, 'Would you like to help select the recipients of the employee awards?', 'Sure, I know the staff members well.', 'Every year in late December.', 'The newly elected vice president.', NULL, 'A', 'Câu hỏi: Bạn có muốn giúp chọn người nhận giải thưởng nhân viên không?"
A: "Chắc chắn, tôi biết các thành viên trong nhóm rất rõ."
B: "Mỗi năm vào cuối tháng 12."
C: "Phó chủ tịch mới được bầu."
Giải thích: Đáp án A đúng vì câu hỏi về việc chọn người nhận giải thưởng và đáp án A cho biết người trả lời quen biết rõ các thành viên trong nhóm, vì vậy có thể giúp đỡ trong việc chọn lựa."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5725, 254, '2025/test7/audio/test7_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7224, 5725, 24, 'How about renting a private venue for the welcome reception?', 'I''m afraid we''ve got a tight budget.', 'It says it can be renewed annually.', 'Sure, I''ve decorated the space.', NULL, 'A', 'Câu hỏi: Làm sao nếu chúng ta thuê một địa điểm riêng cho buổi tiếp đón?"
A: "Tôi e rằng chúng ta có ngân sách hạn chế."
B: "Nó nói có thể gia hạn hàng năm."
C: "Chắc chắn, tôi đã trang trí không gian."
Giải thích: Đáp án A đúng vì câu hỏi về việc thuê địa điểm cho buổi tiếp đón, và đáp án A cho biết ngân sách của nhóm bị hạn chế nên việc thuê một địa điểm riêng có thể gặp khó khăn."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5726, 254, '2025/test7/audio/test7_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7225, 5726, 25, 'Who''s setting up the conference room on Monday?', 'All of the board members are invited.', 'The meeting ran long, I''m afraid.', 'I''m working from home that entire week.', NULL, 'C', 'Câu hỏi: Ai sẽ chuẩn bị phòng họp vào thứ Hai?"
A: "Tất cả các thành viên hội đồng quản trị đều được mời."
B: "Cuộc họp đã kéo dài, tôi e rằng."
C: "Tôi sẽ làm việc tại nhà suốt tuần đó."
Giải thích: Đáp án C đúng vì câu hỏi về việc chuẩn bị phòng họp, và đáp án C cho biết người trả lời sẽ làm việc tại nhà, nên sẽ không tham gia vào việc chuẩn bị."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5727, 254, '2025/test7/audio/test7_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7226, 5727, 26, 'Isn''t the portfolio supposed to be provided in digital form?', 'This is a promising business opportunity.', 'Yes, I''m working on the electronic copy.', 'We should digitize the patient records.', NULL, 'B', 'Câu hỏi: Bản hồ sơ không phải được cung cấp dưới dạng kỹ thuật số sao?"
A: "Đây là một cơ hội kinh doanh triển vọng."
B: "Vâng, tôi đang làm việc trên bản sao điện tử."
C: "Chúng ta nên số hóa hồ sơ bệnh nhân."
Giải thích: Đáp án B đúng vì câu hỏi về việc hồ sơ phải được cung cấp dưới dạng kỹ thuật số, và đáp án B cho biết người trả lời đang làm việc trên bản sao điện tử."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5728, 254, '2025/test7/audio/test7_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7227, 5728, 27, 'Don''t you sell these hiking boots in brown?', 'The cell phones are a good price.', 'There''s a high level of customer satisfaction.', 'We''re restocking that section later this week.', NULL, 'C', 'Câu hỏi: Bạn không bán đôi ủng đi bộ này màu nâu sao?"
A: "Các điện thoại di động có giá tốt."
B: "Mức độ hài lòng của khách hàng rất cao."
C: "Chúng tôi sẽ nhập thêm hàng cho khu vực này vào cuối tuần này."
Giải thích: Đáp án C đúng vì câu hỏi về việc bán đôi ủng đi bộ màu nâu, và đáp án C cho biết khu vực bán sản phẩm này sẽ được nhập thêm hàng vào cuối tuần."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5729, 254, '2025/test7/audio/test7_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7228, 5729, 28, 'Should we get a one-year subscription for the software or pay monthly?', 'She downloaded the files.', 'Last year, in June.', 'Monthly, at first.', NULL, 'C', 'Câu hỏi: Chúng ta nên mua gói đăng ký phần mềm một năm hay trả tiền hàng tháng?"
A: "Cô ấy đã tải các tệp xuống."
B: "Vào năm ngoái, vào tháng 6."
C: "Trả tiền hàng tháng, lúc đầu."
Giải thích: Đáp án C đúng vì câu hỏi về việc đăng ký phần mềm, và đáp án C cho biết sẽ trả tiền hàng tháng trong giai đoạn đầu."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5730, 254, '2025/test7/audio/test7_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7229, 5730, 29, 'Ellie designed the invitations for the networking luncheon, didn''t she?', 'The system is working again.', 'I''m grateful to be invited.', 'Actually, one of the interns did.', NULL, 'C', 'Câu hỏi: Ellie đã thiết kế thiệp mời cho bữa tiệc kết nối, phải không?"
A: "Hệ thống đã hoạt động trở lại."
B: "Tôi rất biết ơn vì đã được mời."
C: "Thực ra, một trong những thực tập sinh đã làm."
Giải thích: Đáp án C đúng vì câu hỏi về việc thiết kế thiệp mời, và đáp án C cho biết thực tế là một thực tập sinh đã thực hiện công việc đó."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5731, 254, '2025/test7/audio/test7_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7230, 5731, 30, 'These containers should have been cleared from the loading dock.', 'I thought that they were meant to be refilled.', 'No thanks, I still have a good deal of space.', 'The contract contains sensitive information.', NULL, 'A', 'Câu hỏi: Những thùng chứa này lẽ ra phải được dọn dẹp khỏi bến bốc dỡ rồi." 
A: "Tôi tưởng chúng phải được làm đầy lại." 
B: "Không cảm ơn, tôi vẫn còn nhiều không gian." 
C: "Hợp đồng chứa thông tin nhạy cảm." 
Giải thích: Đáp án A đúng vì câu hỏi về việc dọn dẹp bến bốc dỡ, và đáp án A giải thích rằng người trả lời nghĩ rằng những thùng chứa đó cần được làm đầy lại thay vì dọn đi."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5732, 254, '2025/test7/audio/test7_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7231, 5732, 31, 'Who will be in charge of testing the health-monitoring equipment?', 'On the first few days of each month.', 'Yes, I was impressed with its functionality.', 'The chief engineer oversees all aspects of the project.', NULL, 'C', 'Câu hỏi: Ai sẽ chịu trách nhiệm kiểm tra thiết bị giám sát sức khỏe?"
A: "Vào những ngày đầu tháng mỗi tháng."
B: "Vâng, tôi ấn tượng với chức năng của nó."
C: "Kỹ sư trưởng sẽ giám sát mọi khía cạnh của dự án."
Giải thích: Đáp án C đúng vì câu hỏi về người chịu trách nhiệm kiểm tra thiết bị giám sát sức khỏe, và đáp án C cho biết kỹ sư trưởng sẽ giám sát mọi khía cạnh của dự án."');;

-- Data for 2025 Test7 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5733, 255, '2025/test7/audio/test7_question_32_34.mp3', NULL, 'W-Br: Thank you for calling Monroe Art Museum. How can I help you?
M-cn: Hello. I work for Home Hearted, which helps build affordable housing for low-income families. We are looking for a site for our charity''s annual fundraiser, and we''re interested in the museum.
w-Br: Well, we recently held a private event like that here, but... um, one of our paintings was scratched. I''m worried that would happen at another event.
M-Cn: I understand, but it would be a fairly small group.
w-Br: I see. Well, you would be welcome to put forward a written proposal to our board of directors. Their approval would be required for an after-hours event.', 'Nữ: Cảm ơn vì đã gọi đến Bảo tàng Nghệ thuật Monroe. Tôi có thể giúp gì cho anh?
Nam: Xin chào. Tôi làm việc cho Home Hearted, tổ chức giúp xây dựng nhà ở giá rẻ cho các gia đình có thu nhập thấp. Chúng tôi đang tìm kiếm địa điểm cho sự kiện gây quỹ thường niên của tổ chức từ thiện, và chúng tôi quan tâm đến bảo tàng.
Nữ: À, gần đây chúng tôi đã tổ chức một sự kiện riêng tư như vậy ở đây, nhưng... ừm, một trong những bức tranh của chúng tôi đã bị xước. Tôi lo lắng điều đó sẽ xảy ra tại một sự kiện khác.
Nam: Tôi hiểu, nhưng đó sẽ là một nhóm khá nhỏ.
Nữ: Tôi hiểu. À, anh có thể nộp một đề xuất bằng văn bản cho hội đồng quản trị của chúng tôi. Sự chấp thuận của họ sẽ được yêu cầu cho một sự kiện ngoài giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7232, 5733, 32, 'Where does the man most likely work?', 'At a real estate company', 'At an art auction house', 'At a non-profit organization', 'At a financial institution', 'C', 'Question: "Where does the man most likely work?" (Người đàn ông nhiều khả năng làm việc ở đâu?)
A: At a real estate company (Tại một công ty bất động sản)
B: At an art auction house (Tại một nhà đấu giá nghệ thuật)
C: At a non-profit organization (Tại một tổ chức phi lợi nhuận)
D: At a financial institution (Tại một tổ chức tài chính)

Người đàn ông làm việc tại một tổ chức phi lợi nhuận vì:
1. Anh ấy làm việc cho Home Hearted - một tổ chức từ thiện giúp xây dựng nhà ở giá rẻ cho các gia đình có thu nhập thấp
2. Họ đang tìm địa điểm cho sự kiện gây quỹ thường niên của tổ chức từ thiện');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5734, 255, '2025/test7/audio/test7_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7233, 5734, 33, 'What does the woman express concern about?', 'The lack of after-hours staff', 'The risk of damage to items', 'The cost of hosting an event', 'The timeline for getting approval', 'B', 'Question: "What does the woman express concern about?" (Người phụ nữ bày tỏ lo ngại về điều gì?)
A: The lack of after-hours staff (Thiếu nhân viên ngoài giờ)
B: The risk of damage to items (Nguy cơ hư hại đồ vật)
C: The cost of hosting an event (Chi phí tổ chức sự kiện)
D: The timeline for getting approval (Thời gian để được phê duyệt)

Người phụ nữ lo ngại về nguy cơ hư hại các tác phẩm nghệ thuật, điều này được thể hiện khi cô ấy nói về việc một bức tranh đã bị xước trong một sự kiện trước đó: "one of our paintings was scratched. I''m worried that would happen at another event" (một trong những bức tranh của chúng tôi đã bị xước. Tôi lo lắng điều đó sẽ xảy ra tại một sự kiện khác).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5735, 255, '2025/test7/audio/test7_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7234, 5735, 34, 'What does the woman suggest that the man do?', 'Decorate a room', 'Review the museum''s policies', 'Submit a proposal', 'Attend a board meeting', 'C', 'Question: "What does the woman suggest that the man do?" (Người phụ nữ đề xuất người đàn ông làm gì?)
A: Decorate a room (Trang trí một phòng)
B: Review the museum''s policies (Xem xét các chính sách của bảo tàng)
C: Submit a proposal (Nộp một đề xuất)
D: Attend a board meeting (Tham dự cuộc họp hội đồng)

Người phụ nữ đề xuất người đàn ông nộp đề xuất bằng văn bản cho hội đồng quản trị: "you would be welcome to put forward a written proposal to our board of directors" (anh có thể nộp một đề xuất bằng văn bản cho hội đồng quản trị của chúng tôi).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5736, 255, '2025/test7/audio/test7_question_35_37.mp3', NULL, 'M-Cn: Welcome to Bradberry Luggage. Can I help you find anything?
w-Am: Hi. I''m flying to Seoul for work next week, so l need to get a new suitcase.
M-cn: I can help you find something. What size did you have in mind?
w-Am: Well, I like the size of the one displayed by the entrance. But the pattern is too bold for my taste.
M-cn: No problem. That particular model is also available in solid black, navy blue, or red. It has spinner wheels that can move three hundred sixty degrees, and the handle is retractable.
W-Am: That sounds great. It''s on sale for one hundred forty dollars, right?
M-Cn: Yes, that''s right. And that price includes a two-year warranty on all parts.', 'Nam: Chào mừng đến với Bradberry Luggage. Tôi có thể giúp bạn tìm gì không?
Nữ: Chào. Tôi sẽ bay đến Seoul để làm việc vào tuần sau, nên tôi cần mua một chiếc vali mới.
Nam: Tôi có thể giúp bạn tìm cái gì đó. Bạn đang nghĩ đến kích thước nào?
Nữ: À, tôi thích kích thước của cái được trưng bày ở lối vào. Nhưng họa tiết quá nổi bật so với sở thích của tôi.
Nam: Không vấn đề gì. Mẫu đó cũng có sẵn màu đen trơn, xanh navy, hoặc đỏ. Nó có bánh xe xoay được 360 độ, và tay cầm có thể thu vào.
Nữ: Nghe hay đấy. Nó đang giảm giá còn một trăm bốn mươi đô la, phải không?
Nam: Vâng, đúng vậy. Và giá đó bao gồm bảo hành hai năm cho tất cả các bộ phận.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7235, 5736, 35, 'What does the woman need a suitcase for?', 'A family trip', 'A friend''s birthday', 'A business trip', 'A house move', 'C', 'Question: "What does the woman need a suitcase for?" (Người phụ nữ cần vali cho việc gì?)
A: A family trip (Một chuyến đi gia đình)
B: A friend''s birthday (Sinh nhật một người bạn)
C: A business trip (Một chuyến công tác)
D: A house move (Chuyển nhà)

Người phụ nữ cần vali cho một chuyến công tác đến Seoul: "I''m flying to Seoul for work next week" (Tôi sẽ bay đến Seoul để làm việc vào tuần sau).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5737, 255, '2025/test7/audio/test7_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7236, 5737, 36, 'What does the woman dislike about the display suitcase?', 'Its size', 'Its pattern', 'Its price', 'Its fabric', 'B', 'Question: "What does the woman dislike about the display suitcase?" (Người phụ nữ không thích điều gì về chiếc vali trưng bày?)
A: Its size (Kích thước của nó)
B: Its pattern (Họa tiết của nó)
C: Its price (Giá của nó)
D: Its fabric (Chất liệu của nó)

Người phụ nữ không thích họa tiết của chiếc vali vì quá nổi bật: "the pattern is too bold for my taste" (họa tiết quá nổi bật so với sở thích của tôi).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5738, 255, '2025/test7/audio/test7_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7237, 5738, 37, 'According to the man, what is included in the price?', 'Spare wheels', 'A tracking device', 'Free shipping', 'A warranty', 'D', 'Question: "According to the man, what is included in the price?" (Theo người đàn ông, giá đã bao gồm gì?)
A: Spare wheels (Bánh xe dự phòng)
B: A tracking device (Thiết bị theo dõi)
C: Free shipping (Miễn phí vận chuyển)
D: A warranty (Bảo hành)

Theo người đàn ông, giá đã bao gồm bảo hành hai năm cho tất cả các bộ phận: "that price includes a two-year warranty on all parts" (giá đó bao gồm bảo hành hai năm cho tất cả các bộ phận).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5739, 255, '2025/test7/audio/test7_question_38_40.mp3', NULL, 'W-Am: Theo, have you finalized the schedule for the employee retreat next month?
M-Au: l''ve been really busy, so l''ve just started working on it.
W-am: That''s great, actually. I would like to put something on the schedule for the first day, August 4. It''s a quiz game to help employees work together and get to know each other. I don''t mind hosting it and coming up with the questions that we''ll need.
M-au: That sounds like fun. Could you just let me know about how long that will take? Then I''ll make sure to leave enough time for it.', 'Nữ: Theo, anh đã hoàn thành lịch cho kỳ nghỉ dưỡng của nhân viên tháng sau chưa?
Nam: Tôi đã rất bận, nên tôi vừa mới bắt đầu làm việc với nó.
Nữ: Thật ra điều đó tốt đấy. Tôi muốn đưa một thứ vào lịch cho ngày đầu tiên, ngày 4 tháng 8. Đó là một trò chơi đố vui để giúp nhân viên làm việc cùng nhau và hiểu nhau hơn. Tôi không ngại tổ chức nó và nghĩ ra những câu hỏi mà chúng ta sẽ cần.
Nam: Nghe vui đấy. Chị có thể cho tôi biết nó sẽ mất bao lâu không? Sau đó tôi sẽ đảm bảo để đủ thời gian cho nó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7238, 5739, 38, 'What task is the man in charge of?', 'Organizing a trade fair schedule', 'Planning a staff retreat', 'Analyzing customer feedback', 'Recruiting new company employees', 'B', 'Question: "What task is the man in charge of?" (Người đàn ông phụ trách nhiệm vụ gì?)
A: Organizing a trade fair schedule (Tổ chức lịch hội chợ thương mại)
B: Planning a staff retreat (Lên kế hoạch cho kỳ nghỉ dưỡng của nhân viên)
C: Analyzing customer feedback (Phân tích phản hồi của khách hàng)
D: Recruiting new company employees (Tuyển dụng nhân viên mới cho công ty)

Người đàn ông đang phụ trách việc lên lịch cho kỳ nghỉ dưỡng của nhân viên vào tháng sau, được thấy qua câu hỏi của người phụ nữ: "have you finalized the schedule for the employee retreat next month?" (anh đã hoàn thành lịch cho kỳ nghỉ dưỡng của nhân viên tháng sau chưa?)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5740, 255, '2025/test7/audio/test7_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7239, 5740, 39, 'What does the woman want to do on August 4?', 'Give out achievement awards', 'Introduce some new products', 'Lead a team-building activity', 'Answer questions from the staff', 'C', 'Question: "What does the woman want to do on August 4?" (Người phụ nữ muốn làm gì vào ngày 4 tháng 8?)
A: Give out achievement awards (Trao giải thưởng thành tích)
B: Introduce some new products (Giới thiệu một số sản phẩm mới)
C: Lead a team-building activity (Dẫn dắt hoạt động xây dựng đội nhóm)
D: Answer questions from the staff (Trả lời câu hỏi từ nhân viên)

Người phụ nữ muốn tổ chức một trò chơi đố vui để xây dựng đội nhóm: "It''s a quiz game to help employees work together and get to know each other" (Đó là một trò chơi đố vui để giúp nhân viên làm việc cùng nhau và hiểu nhau hơn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5741, 255, '2025/test7/audio/test7_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7240, 5741, 40, 'What is the woman asked to do?', 'Review employee performance', 'Check a list of attendees', 'Give a welcome address', 'Provide a time estimate', 'D', 'Question: "What is the woman asked to do?" (Người phụ nữ được yêu cầu làm gì?)
A: Review employee performance (Đánh giá hiệu suất nhân viên)
B: Check a list of attendees (Kiểm tra danh sách người tham dự)
C: Give a welcome address (Đọc bài phát biểu chào mừng)
D: Provide a time estimate (Cung cấp ước tính thời gian)

Người phụ nữ được yêu cầu cho biết hoạt động sẽ mất bao lâu: "Could you just let me know about how long that will take?" (Chị có thể cho tôi biết nó sẽ mất bao lâu không?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5742, 255, '2025/test7/audio/test7_question_41_43.mp3', NULL, 'W-Br: Hi, it''s Lucy from the Sales Department. I need some equipment for the meeting with the prospective investors from Milan on Thursday at 1 P.M.
M-Cn: Of course. What do you need?
w-Br: Just a laptop and projector, please. We''ll start at 1 P.M.
M-Cn: Alright. I can set the computer up for you. Do you need any special software installed?
w-Br: I don''t think so. l''ll just have a slideshow presentation saved on an external hard drive. Can I give that to you on Thursday morning?
M-cn: Sure. I''ll make sure everything''s working in advance.', 'Nữ: Chào, Lucy từ Phòng Bán hàng đây. Tôi cần một số thiết bị cho cuộc họp với các nhà đầu tư tiềm năng từ Milan vào thứ Năm lúc 1 giờ chiều.
Nam: Được chứ. Chị cần gì?
Nữ: Chỉ cần một laptop và máy chiếu thôi. Chúng tôi sẽ bắt đầu lúc 1 giờ chiều.
Nam: Được rồi. Tôi có thể cài đặt máy tính cho chị. Chị có cần cài đặt phần mềm đặc biệt nào không?
Nữ: Tôi không nghĩ vậy. Tôi sẽ chỉ có một bài thuyết trình slideshow được lưu trên ổ cứng di động. Tôi có thể đưa nó cho anh vào sáng thứ Năm được không?
Nam: Được. Tôi sẽ đảm bảo mọi thứ hoạt động trước.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7241, 5742, 41, 'What does the woman have to prepare for?', 'A session to test new products', 'An inspection by a government official', 'A visit from potential investors', 'A training workshop for employees', 'C', 'Question: "What does the woman have to prepare for?" (Người phụ nữ phải chuẩn bị cho điều gì?)
A: A session to test new products (Một buổi kiểm tra sản phẩm mới)
B: An inspection by a government official (Một cuộc kiểm tra của viên chức chính phủ)
C: A visit from potential investors (Một cuộc thăm từ các nhà đầu tư tiềm năng)
D: A training workshop for employees (Một hội thảo đào tạo cho nhân viên)

Người phụ nữ phải chuẩn bị cho cuộc họp với các nhà đầu tư tiềm năng từ Milan: "the meeting with the prospective investors from Milan" (cuộc họp với các nhà đầu tư tiềm năng từ Milan).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5743, 255, '2025/test7/audio/test7_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7242, 5743, 42, 'Who most likely is the man?', 'A company owner', 'A computer technician', 'A financial advisor', 'A sales director', 'B', 'Question: "Who most likely is the man?" (Người đàn ông nhiều khả năng là ai?)
A: A company owner (Một chủ doanh nghiệp)
B: A computer technician (Một kỹ thuật viên máy tính)
C: A financial advisor (Một cố vấn tài chính)
D: A sales director (Một giám đốc bán hàng)

Người đàn ông nhiều khả năng là kỹ thuật viên máy tính vì:
1. Anh ấy phụ trách việc cài đặt thiết bị máy tính và máy chiếu
2. Anh ấy hỏi về nhu cầu cài đặt phần mềm đặc biệt
3. Anh ấy sẽ đảm bảo mọi thứ hoạt động trước khi cuộc họp diễn ra');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5744, 255, '2025/test7/audio/test7_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7243, 5744, 43, 'What does the woman plan to give the man on Thursday morning?', 'A hard drive', 'A meeting agenda', 'A lunch menu', 'A cost estimate', 'A', 'Question: "What does the woman plan to give the man on Thursday morning?" (Người phụ nữ dự định đưa gì cho người đàn ông vào sáng thứ Năm?)
A: A hard drive (Một ổ cứng)
B: A meeting agenda (Một chương trình họp)
C: A lunch menu (Một thực đơn bữa trưa)
D: A cost estimate (Một bản ước tính chi phí)

Người phụ nữ dự định đưa ổ cứng di động chứa bài thuyết trình của cô ấy vào sáng thứ Năm: "a slideshow presentation saved on an external hard drive. Can I give that to you on Thursday morning?" (một bài thuyết trình slideshow được lưu trên ổ cứng di động. Tôi có thể đưa nó cho anh vào sáng thứ Năm được không?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5745, 255, '2025/test7/audio/test7_question_44_46.mp3', NULL, 'W-Br: Hi, Taichi. Are you finding the new sales summary forms confusing? They require a lot more information about the details for each product, like adding the energy usage for our toasters and blenders.
M-Au: Right. I thought I could get most of those details from the database, but it''s incomplete. I had to ask my team leader to push back the due date for this assignment.
w-Br: Did you really? You''re always so prompt with your work.
M-Au: Well, this is too time-consuming. I think we need to bring this up with one of the managers.
W-Br: Ms. Adkins is always willing to listen. I just saw her go into her office.', 'Nữ: Chào Taichi. Anh có thấy các biểu mẫu tổng kết bán hàng mới gây nhầm lẫn không? Chúng yêu cầu nhiều thông tin hơn về chi tiết cho từng sản phẩm, như thêm mức tiêu thụ năng lượng cho máy nướng bánh mì và máy xay sinh tố của chúng ta.
Nam: Đúng vậy. Tôi nghĩ tôi có thể lấy hầu hết những chi tiết đó từ cơ sở dữ liệu, nhưng nó không đầy đủ. Tôi phải yêu cầu trưởng nhóm của tôi gia hạn thời hạn cho nhiệm vụ này.
Nữ: Anh làm vậy thật sao? Anh luôn luôn làm việc rất đúng hạn.
Nam: À, việc này tốn quá nhiều thời gian. Tôi nghĩ chúng ta cần đề cập việc này với một trong những quản lý.
Nữ: Cô Adkins luôn sẵn sàng lắng nghe. Tôi vừa thấy cô ấy vào văn phòng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7244, 5745, 44, 'What kind of product does the speakers'' company most likely sell?', 'Gardening equipment', 'Casual clothing', 'Kitchen appliances', 'Light fixtures', 'C', 'Question: "What kind of product does the speakers'' company most likely sell?" (Công ty của những người nói chuyện nhiều khả năng bán loại sản phẩm gì?)
A: Gardening equipment (Thiết bị làm vườn)
B: Casual clothing (Quần áo thường ngày)
C: Kitchen appliances (Thiết bị nhà bếp)
D: Light fixtures (Đèn chiếu sáng)

Công ty bán các thiết bị nhà bếp vì:
1. Họ đề cập đến máy nướng bánh mì (toasters)
2. Họ đề cập đến máy xay sinh tố (blenders)
3. Cần cung cấp thông tin về mức tiêu thụ năng lượng của các thiết bị này');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5746, 255, '2025/test7/audio/test7_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7245, 5746, 45, 'Why is the woman surprised?', 'The man could not access a database', 'The man requested a deadline extension', 'The price of some items has changed', 'Some devices use a lot of energy', 'B', 'Question: "Why is the woman surprised?" (Tại sao người phụ nữ ngạc nhiên?)
A: The man could not access a database (Người đàn ông không thể truy cập cơ sở dữ liệu)
B: The man requested a deadline extension (Người đàn ông yêu cầu gia hạn thời hạn)
C: The price of some items has changed (Giá của một số mặt hàng đã thay đổi)
D: Some devices use a lot of energy (Một số thiết bị tiêu thụ nhiều năng lượng)

Người phụ nữ ngạc nhiên vì người đàn ông yêu cầu gia hạn thời hạn, điều này khác thường vì anh ấy luôn làm việc đúng hạn: "Did you really? You''re always so prompt with your work" (Anh làm vậy thật sao? Anh luôn luôn làm việc rất đúng hạn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5747, 255, '2025/test7/audio/test7_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7246, 5747, 46, 'Why does the woman say, "I just saw her go into her office"?', 'To suggest discussing an issue with a supervisor', 'To indicate that a meeting has finished early', 'To express disagreement about an absence', 'To confirm that a task has been completed', 'A', 'Question: "Why does the woman say, ''I just saw her go into her office''?" (Tại sao người phụ nữ nói "Tôi vừa thấy cô ấy vào văn phòng"?)
A: To suggest discussing an issue with a supervisor (Để đề xuất thảo luận một vấn đề với người giám sát)
B: To indicate that a meeting has finished early (Để chỉ ra rằng một cuộc họp đã kết thúc sớm)
C: To express disagreement about an absence (Để bày tỏ sự không đồng ý về việc vắng mặt)
D: To confirm that a task has been completed (Để xác nhận một nhiệm vụ đã hoàn thành)

Người phụ nữ nói điều này để gợi ý rằng họ có thể gặp Ms. Adkins ngay bây giờ để thảo luận về vấn đề. Điều này được ngụ ý sau khi:
1. Người đàn ông nói họ cần đề cập vấn đề với quản lý
2. Người phụ nữ nói "Ms. Adkins is always willing to listen" (Cô Adkins luôn sẵn sàng lắng nghe)
3. Và sau đó thông báo cô ấy vừa vào văn phòng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5748, 255, '2025/test7/audio/test7_question_47_49.mp3', NULL, 'M-AU: I wanted to ask you about the hair products we sell. They''re... Oh, sorry, Michelle. You''re in the middle of something.
W-Am: These reports are not urgent.
M-Au: Okay, great. Well, when I was dusting our display stand by the window, I noticed that some of the shampoo has turned a strange color.
W-Am: Hmm... our hair salon customers haven''t been buying it, so it''s been sitting in the sun for a long time. It''s probably unusable now, unfortunately.
M-Au: Then we should probably relocate the stand to somewhere out of the light. It would be more noticeable near the reception desk anyway.', 'Nam: Tôi muốn hỏi chị về các sản phẩm chăm sóc tóc chúng ta bán. Chúng... Ồ, xin lỗi Michelle. Chị đang bận việc gì đó.
Nữ: Những báo cáo này không khẩn cấp.
Nam: Okay, tốt quá. À, khi tôi đang lau bụi giá trưng bày gần cửa sổ, tôi nhận thấy một số dầu gội đã chuyển sang màu lạ.
Nữ: Hmm... khách hàng từ salon tóc không mua nó, nên nó đã phơi nắng quá lâu. Có lẽ giờ không thể sử dụng được nữa, thật đáng tiếc.
Nam: Vậy thì chúng ta nên di chuyển giá trưng bày đến chỗ nào đó tránh ánh sáng. Dù sao nó cũng sẽ dễ nhận thấy hơn gần quầy lễ tân.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7247, 5748, 47, 'What does the woman imply when she says, "These reports are not urgent"?', 'She wants to rearrange a schedule', 'She does not need the man''s assistance', 'She can respond to a question', 'She plans to take a day off', 'C', 'Question: "What does the woman imply when she says, ''These reports are not urgent''?" (Người phụ nữ ngụ ý gì khi nói "Những báo cáo này không khẩn cấp"?)
A: She wants to rearrange a schedule (Cô ấy muốn sắp xếp lại lịch)
B: She does not need the man''s assistance (Cô ấy không cần sự giúp đỡ của người đàn ông)
C: She can respond to a question (Cô ấy có thể trả lời câu hỏi)
D: She plans to take a day off (Cô ấy dự định nghỉ một ngày)

Khi nói "These reports are not urgent", người phụ nữ ngụ ý rằng cô ấy có thể dừng việc làm báo cáo để trả lời câu hỏi của người đàn ông vì báo cáo không khẩn cấp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5749, 255, '2025/test7/audio/test7_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7248, 5749, 48, 'What did the man notice about some shampoo?', 'Its bottles have cracked', 'Its labels are faded', 'Its appearance has changed', 'Its ingredients are harmful', 'C', 'Question: "What did the man notice about some shampoo?" (Người đàn ông nhận thấy điều gì về một số dầu gội?)
A: Its bottles have cracked (Chai của nó đã bị nứt)
B: Its labels are faded (Nhãn của nó đã bị phai)
C: Its appearance has changed (Diện mạo của nó đã thay đổi)
D: Its ingredients are harmful (Thành phần của nó có hại)

Người đàn ông nhận thấy dầu gội đã chuyển sang màu lạ: "some of the shampoo has turned a strange color" (một số dầu gội đã chuyển sang màu lạ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5750, 255, '2025/test7/audio/test7_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7249, 5750, 49, 'What does the man suggest that the business do in the future?', 'Move items to a different place', 'Offer discounts to customers', 'Hire a full-time receptionist', 'Use a more reliable supplier', 'A', 'Question: "What does the man suggest that the business do in the future?" (Người đàn ông đề xuất doanh nghiệp làm gì trong tương lai?)
A: Move items to a different place (Di chuyển đồ đến một vị trí khác)
B: Offer discounts to customers (Đưa ra giảm giá cho khách hàng)
C: Hire a full-time receptionist (Thuê một lễ tân toàn thời gian)
D: Use a more reliable supplier (Sử dụng một nhà cung cấp đáng tin cậy hơn)

Người đàn ông đề xuất di chuyển giá trưng bày đến vị trí không có ánh sáng mặt trời: "we should probably relocate the stand to somewhere out of the light" (chúng ta nên di chuyển giá trưng bày đến chỗ nào đó tránh ánh sáng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5751, 255, '2025/test7/audio/test7_question_50_52.mp3', NULL, 'M-Au: Excuse me, could you please help me find Amy Ogren''s novel entitled Daybreak is Calling?
W-Br: Actually, the book just came out, but the library hasn''t been able to order it yet. We are waiting for our finance committee to decide the budget for this quarter before we can place the next book order.
M-Au: Oh, what a shame. I was hoping to check it out today.
w-Br: I''m sorry for the inconvenience. We don''t have a waiting list, but updates are in the library''s monthly newsletter. You can register for it for free.', 'Nam: Xin lỗi, bạn có thể giúp tôi tìm cuốn tiểu thuyết Daybreak is Calling của Amy Ogren không?
Nữ: Thực ra, cuốn sách vừa mới phát hành, nhưng thư viện chưa thể đặt mua nó. Chúng tôi đang đợi ủy ban tài chính quyết định ngân sách cho quý này trước khi có thể đặt đơn sách tiếp theo.
Nam: Ồ, thật đáng tiếc. Tôi đã hy vọng mượn nó hôm nay.
Nữ: Tôi xin lỗi vì sự bất tiện. Chúng tôi không có danh sách chờ, nhưng các cập nhật có trong bản tin hàng tháng của thư viện. Anh có thể đăng ký miễn phí.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7250, 5751, 50, 'Who most likely is Amy Ogren?', 'An author', 'A librarian', 'A painter', 'A reporter', 'A', 'Question: "Who most likely is Amy Ogren?" (Amy Ogren nhiều khả năng là ai?)
A: An author (Một tác giả)
B: A librarian (Một thủ thư)
C: A painter (Một họa sĩ)
D: A reporter (Một phóng viên)

Amy Ogren là một tác giả vì:
1. Được đề cập đến cùng với cuốn tiểu thuyết "Daybreak is Calling"
2. Cuốn sách vừa mới phát hành: "the book just came out"
3. Thư viện chưa thể đặt mua cuốn sách');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5752, 255, '2025/test7/audio/test7_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7251, 5752, 51, 'What does the woman mention about a committee?', 'It is recruiting new members', 'It has rejected an order', 'It must finalize a budget', 'It meets every quarter', 'C', 'Question: "What does the woman mention about a committee?" (Người phụ nữ đề cập gì về một ủy ban?)
A: It is recruiting new members (Nó đang tuyển thành viên mới)
B: It has rejected an order (Nó đã từ chối một đơn hàng)
C: It must finalize a budget (Nó phải hoàn tất ngân sách)
D: It meets every quarter (Nó họp mỗi quý)

Người phụ nữ nói rằng họ đang đợi ủy ban tài chính quyết định ngân sách cho quý này: "waiting for our finance committee to decide the budget for this quarter" (đang đợi ủy ban tài chính quyết định ngân sách cho quý này).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5753, 255, '2025/test7/audio/test7_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7252, 5753, 52, 'What does the woman suggest doing?', 'Joining a waiting list', 'Signing up for a newsletter', 'Attending a monthly talk', 'Participating in a book club', 'B', 'Question: "What does the woman suggest doing?" (Người phụ nữ đề xuất làm gì?)
A: Joining a waiting list (Tham gia danh sách chờ)
B: Signing up for a newsletter (Đăng ký bản tin)
C: Attending a monthly talk (Tham dự buổi nói chuyện hàng tháng)
D: Participating in a book club (Tham gia câu lạc bộ sách)

Người phụ nữ đề xuất đăng ký bản tin hàng tháng của thư viện: "updates are in the library''s monthly newsletter. You can register for it for free" (các cập nhật có trong bản tin hàng tháng của thư viện. Anh có thể đăng ký miễn phí).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5754, 255, '2025/test7/audio/test7_question_53_55.mp3', NULL, 'M-cn: Well, Ms. Harper, your business plan looks excellent. Based on the sales projections, I think i can approve you for your business loan within a few weeks.
W-Am: That''s good news, but... um, I didn''t realize it would take that long. I thought I would have the funds within a few days.
M-Cn: I''m sorry. The person who booked this appointment should have gone over the estimated timeline in more detail.
wAm: That''s okay. I understand.
M-cn: Ms. Flores, is there anything else we need?
w-Br: Actually, yes. Ms. Harper, you mentioned that you recently moved, so could you please fill out these forms with the address of where we should send everything? That''ll prevent delays.
W-Am: Of course.', 'Nam: À, cô Harper, kế hoạch kinh doanh của cô rất xuất sắc. Dựa trên dự báo doanh số, tôi nghĩ tôi có thể phê duyệt khoản vay kinh doanh cho cô trong vài tuần tới.
Nữ 1: Đó là tin tốt, nhưng... ừm, tôi không nhận ra là nó sẽ mất lâu như vậy. Tôi nghĩ tôi sẽ có tiền trong vài ngày.
Nam: Tôi xin lỗi. Người đã đặt lịch hẹn này lẽ ra nên giải thích chi tiết hơn về thời gian dự kiến.
Nữ 1: Không sao. Tôi hiểu.
Nam: Cô Flores, chúng ta còn cần gì nữa không?
Nữ 2: Thực ra, có. Cô Harper, cô đã đề cập rằng cô vừa chuyển nhà, vậy cô có thể điền vào những mẫu này với địa chỉ nơi chúng tôi nên gửi mọi thứ được không? Điều đó sẽ tránh bị chậm trễ.
Nữ 1: Tất nhiên rồi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7253, 5754, 53, 'Who is the man?', 'A politician', 'A banker', 'A lawyer', 'A journalist', 'B', 'Question: "Who is the man?" (Người đàn ông là ai?)
A: A politician (Một chính trị gia)
B: A banker (Một nhân viên ngân hàng)
C: A lawyer (Một luật sư)
D: A journalist (Một nhà báo)

Người đàn ông là nhân viên ngân hàng vì:
1. Anh ấy đang xem xét và phê duyệt khoản vay kinh doanh dựa trên kế hoạch kinh doanh
2. Thảo luận về thời gian giải ngân khoản vay
3. Các thủ tục và quy trình liên quan đến hoạt động ngân hàng');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5755, 255, '2025/test7/audio/test7_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7254, 5755, 54, 'Why does the man apologize?', 'A cost will be higher than expected', 'A timeline was not explained well', 'Some staff members are absent', 'Some services are no longer available', 'B', 'Question: "Why does the man apologize?" (Tại sao người đàn ông xin lỗi?)
A: A cost will be higher than expected (Chi phí sẽ cao hơn dự kiến)
B: A timeline was not explained well (Thời gian không được giải thích rõ)
C: Some staff members are absent (Một số nhân viên vắng mặt)
D: Some services are no longer available (Một số dịch vụ không còn nữa)

Người đàn ông xin lỗi vì người đặt lịch hẹn đã không giải thích chi tiết về thời gian dự kiến: "The person who booked this appointment should have gone over the estimated timeline in more detail" (Người đã đặt lịch hẹn này lẽ ra nên giải thích chi tiết hơn về thời gian dự kiến).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5756, 255, '2025/test7/audio/test7_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7255, 5756, 55, 'Why should Ms. Harper complete some paperwork?', 'To apply for a temporary position', 'To update her mailing address', 'To use an express service', 'To open a new account', 'B', 'Question: "Why should Ms. Harper complete some paperwork?" (Tại sao Ms. Harper nên điền một số giấy tờ?)
A: To apply for a temporary position (Để ứng tuyển vị trí tạm thời)
B: To update her mailing address (Để cập nhật địa chỉ gửi thư)
C: To use an express service (Để sử dụng dịch vụ nhanh)
D: To open a new account (Để mở tài khoản mới)

Ms. Harper cần điền giấy tờ để cập nhật địa chỉ mới vì cô ấy vừa chuyển nhà: "you mentioned that you recently moved, so could you please fill out these forms with the address of where we should send everything?" (cô đã đề cập rằng cô vừa chuyển nhà, vậy cô có thể điền vào những mẫu này với địa chỉ nơi chúng tôi nên gửi mọi thứ được không?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5757, 255, '2025/test7/audio/test7_question_56_58.mp3', NULL, 'W-Am: Thanks for stopping by, Calvin. As I''m sure you know, Jan Eckles will be moved to the London branch at the beginning of June. As a result, we have an opening for a field sales executive. Do you know anyone who would be suitable for the role?
M-cn: That would be a great opportunity. I have a few colleagues that I could recommend. However, does the person need a degree or any specific qualifications?
w-Am: A business degree is preferred but experience counts for a lot. And the position has a lot of benefits, like a company car and generous commission payments.', 'Nữ: Cảm ơn vì đã ghé qua, Calvin. Như tôi chắc anh đã biết, Jan Eckles sẽ được chuyển đến chi nhánh London vào đầu tháng 6. Do đó, chúng ta có một vị trí trống cho chức danh chuyên viên bán hàng thực địa. Anh có biết ai phù hợp cho vị trí này không?
Nam: Đó sẽ là một cơ hội tuyệt vời. Tôi có một vài đồng nghiệp mà tôi có thể giới thiệu. Tuy nhiên, người đó có cần bằng cấp hoặc bất kỳ bằng cấp cụ thể nào không?
Nữ: Bằng kinh doanh được ưu tiên nhưng kinh nghiệm cũng rất quan trọng. Và vị trí này có nhiều phúc lợi, như xe công ty và hoa hồng hậu hĩnh.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7256, 5757, 56, 'What will happen in June?', 'A product will go on the market', 'A new office will open overseas', 'A branch will undergo renovations', 'A staff member will be transferred', 'D', 'Question: "What will happen in June?" (Điều gì sẽ xảy ra vào tháng 6?)
A: A product will go on the market (Một sản phẩm sẽ ra mắt thị trường)
B: A new office will open overseas (Một văn phòng mới sẽ mở ở nước ngoài)
C: A branch will undergo renovations (Một chi nhánh sẽ được cải tạo)
D: A staff member will be transferred (Một nhân viên sẽ được chuyển công tác)

Vào tháng 6, Jan Eckles sẽ được chuyển đến chi nhánh London: "Jan Eckles will be moved to the London branch at the beginning of June" (Jan Eckles sẽ được chuyển đến chi nhánh London vào đầu tháng 6).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5758, 255, '2025/test7/audio/test7_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7257, 5758, 57, 'What does the man want to know about?', 'When an assignment must be submitted', 'Where he should upload a file', 'Who will be leading a project', 'What is required for a position', 'D', 'Question: "What does the man want to know about?" (Người đàn ông muốn biết về điều gì?)
A: When an assignment must be submitted (Khi nào phải nộp một bài tập)
B: Where he should upload a file (Nơi anh ấy nên tải lên một tập tin)
C: Who will be leading a project (Ai sẽ lãnh đạo một dự án)
D: What is required for a position (Những yêu cầu cho một vị trí)

Người đàn ông muốn biết về yêu cầu bằng cấp và trình độ cho vị trí: "does the person need a degree or any specific qualifications?" (người đó có cần bằng cấp hoặc bất kỳ bằng cấp cụ thể nào không?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5759, 255, '2025/test7/audio/test7_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7258, 5759, 58, 'What does the woman say the company will provide?', 'Paid vacation days', 'On-site meals', 'A work vehicle', 'A credit card', 'C', 'Question: "What does the woman say the company will provide?" (Người phụ nữ nói công ty sẽ cung cấp gì?)
A: Paid vacation days (Ngày nghỉ có lương)
B: On-site meals (Bữa ăn tại chỗ)
C: A work vehicle (Xe công ty)
D: A credit card (Thẻ tín dụng)

Người phụ nữ nói rằng vị trí này có phúc lợi bao gồm xe công ty: "the position has a lot of benefits, like a company car" (vị trí này có nhiều phúc lợi, như xe công ty).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5760, 255, '2025/test7/audio/test7_question_59_61.mp3', NULL, 'M-Cn: Hey, Elena! I heard that your team won the bid to design the bridge over Broadbeck River. That''s amazing! Congratulations!
w-Br: Thanks, Jorge. This project will be fantastic exposure for our firm. And once the bridge is in use, it will significantly cut down on commuting times for people in the area.
M-Cn: That''s true. When will you start working on it?
w-Br: I''m not quite sure. But I can ask Eric, our team leader. He''ll know... Eric, when will the Broadbeck River project begin?
M-Au: Well, that depends on how long it takes to measure the site initially. We''re still waiting on that information.', 'Nam 1: Này, Elena! Tôi nghe nói đội của chị đã thắng thầu thiết kế cầu qua sông Broadbeck. Thật tuyệt vời! Chúc mừng!
Nữ: Cảm ơn, Jorge. Dự án này sẽ là cơ hội tuyệt vời để công ty chúng ta được biết đến. Và một khi cây cầu được sử dụng, nó sẽ giảm đáng kể thời gian di chuyển cho người dân trong khu vực.
Nam 1: Đúng vậy. Khi nào chị sẽ bắt đầu làm việc với nó?
Nữ: Tôi không hoàn toàn chắc chắn. Nhưng tôi có thể hỏi Eric, trưởng nhóm của chúng tôi. Anh ấy sẽ biết... Eric, khi nào dự án sông Broadbeck sẽ bắt đầu?
Nam 2: À, điều đó phụ thuộc vào việc mất bao lâu để đo đạc địa điểm ban đầu. Chúng tôi vẫn đang đợi thông tin đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7259, 5760, 59, 'What industry do the speakers most likely work in?', 'Architecture', 'Tourism', 'Agriculture', 'Electronics', 'A', 'Question: "What industry do the speakers most likely work in?" (Những người nói chuyện nhiều khả năng làm việc trong ngành nào?)
A: Architecture (Kiến trúc)
B: Tourism (Du lịch)
C: Agriculture (Nông nghiệp)
D: Electronics (Điện tử)

Họ làm việc trong ngành kiến trúc vì:
1. Đội của họ thắng thầu thiết kế cầu
2. Họ đề cập đến dự án xây dựng cầu qua sông
3. Cần đo đạc địa điểm trước khi bắt đầu dự án');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5761, 255, '2025/test7/audio/test7_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7260, 5761, 60, 'What does the woman say a project will do in the area?', 'Protect historic buildings', 'Promote local businesses', 'Reduce travel times', 'Increase tax revenue', 'C', 'Question: "What does the woman say a project will do in the area?" (Người phụ nữ nói dự án sẽ làm gì cho khu vực?)
A: Protect historic buildings (Bảo vệ các tòa nhà lịch sử)
B: Promote local businesses (Thúc đẩy kinh doanh địa phương)
C: Reduce travel times (Giảm thời gian di chuyển)
D: Increase tax revenue (Tăng thu ngân sách)

Người phụ nữ nói rằng cây cầu sẽ giảm thời gian di chuyển cho người dân trong khu vực: "it will significantly cut down on commuting times for people in the area" (nó sẽ giảm đáng kể thời gian di chuyển cho người dân trong khu vực).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5762, 255, '2025/test7/audio/test7_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7261, 5762, 61, 'What does Eric say needs to happen?', 'Equipment needs to be rented', 'Materials need to be delivered', 'A team leader needs to be selected', 'Measurements need to be taken', 'D', 'Question: "What does Eric say needs to happen?" (Eric nói cần làm gì?)
A: Equipment needs to be rented (Cần thuê thiết bị)
B: Materials need to be delivered (Cần giao vật liệu)
C: A team leader needs to be selected (Cần chọn trưởng nhóm)
D: Measurements need to be taken (Cần thực hiện đo đạc)

Eric nói rằng họ cần đo đạc địa điểm ban đầu và đang đợi thông tin về việc đó: "that depends on how long it takes to measure the site initially. We''re still waiting on that information" (điều đó phụ thuộc vào việc mất bao lâu để đo đạc địa điểm ban đầu. Chúng tôi vẫn đang đợi thông tin đó).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5763, 255, '2025/test7/audio/test7_question_62_64.mp3', '2025/test7/image/test7-p3-image-62.jpg', 'M-cn: Hi, Louise! How''s your first day at our warehouse going?
w-Am: Oh hi, Mr. Okada. I think it''s going well. I''m taking care to pack each product securely, so it won''t get damaged during shipping.
M-cn: That''s good to hear! Just don''t forget that your packing speed is important, too.
W-Am: Right, I won''t. Actually, I have a question related to that-are we allowed to rearrange our packing stations? I''m left-handed, so I could work a little faster if the tape were on that side of this shelf.
M-Cn: Sure_ go ahead and swap it with the labels.
And I see you''re almost out of the wide packing tape. Do you know how to get more?
W-Am: Yes, my supervisor showed me where the supplies are stored.', 'Nam: Chào Louise! Ngày đầu tiên ở kho hàng của chúng tôi thế nào?
Nữ: Ồ chào ông Okada. Tôi nghĩ mọi thứ đều ổn. Tôi đang cẩn thận đóng gói từng sản phẩm một cách an toàn, để nó không bị hư hỏng trong quá trình vận chuyển.
Nam: Nghe hay đấy! Chỉ đừng quên rằng tốc độ đóng gói của cô cũng quan trọng.
Nữ: Vâng, tôi sẽ không quên. Thực ra, tôi có một câu hỏi liên quan đến điều đó - chúng tôi có được phép sắp xếp lại trạm đóng gói không? Tôi thuận tay trái, vì vậy tôi có thể làm việc nhanh hơn một chút nếu băng dính ở phía đó của kệ.
Nam: Được chứ, cứ đổi chỗ nó với nhãn.
Và tôi thấy cô gần hết băng dính đóng gói rộng rồi. Cô có biết lấy thêm ở đâu không?
Nữ: Vâng, giám sát viên của tôi đã chỉ cho tôi nơi lưu trữ vật tư.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7262, 5763, 62, 'Where does the conversation take place?', 'At a gift shop', 'At a warehouse', 'At an office-supply store', 'At a post office', 'B', 'Question: "Where does the conversation take place?" (Cuộc trò chuyện diễn ra ở đâu?)
A: At a gift shop (Tại một cửa hàng quà tặng)
B: At a warehouse (Tại một kho hàng)
C: At an office-supply store (Tại một cửa hàng văn phòng phẩm)
D: At a post office (Tại một bưu điện)

Cuộc trò chuyện diễn ra tại kho hàng vì:
1. Đây là ngày đầu tiên của Louise tại "warehouse"
2. Cô ấy đang làm công việc đóng gói sản phẩm
3. Có đề cập đến trạm đóng gói và vật tư đóng gói');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5764, 255, '2025/test7/audio/test7_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7263, 5764, 63, 'Look at the graphic. Where will the tape be moved to?', 'To section 1', 'To section 2', 'To section 3', 'To section 4', 'A', 'Question: "Look at the graphic. Where will the tape be moved to?" (Nhìn vào hình. Băng dính sẽ được chuyển đến đâu?)
A: To section 1 (Đến phần 1)
B: To section 2 (Đến phần 2)
C: To section 3 (Đến phần 3)
D: To section 4 (Đến phần 4)

Băng dính sẽ được chuyển đến Section 1 (phần nhãn) vì:
1. Người phụ nữ muốn di chuyển băng dính sang bên trái (thuận tay trái của cô ấy)
2. Ông Okada nói: "swap it with the labels" (đổi chỗ nó với nhãn)
3. Trong hình, Section 1 là khu vực nhãn (Labels)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5765, 255, '2025/test7/audio/test7_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7264, 5765, 64, 'What does the woman say her supervisor did for her?', 'Let her borrow an item', 'Showed her a storage area', 'Approved a special request', 'Packed some large boxes', 'B', 'Question: "What does the woman say her supervisor did for her?" (Người phụ nữ nói giám sát viên của cô ấy đã làm gì cho cô ấy?)
A: Let her borrow an item (Cho cô ấy mượn một món đồ)
B: Showed her a storage area (Chỉ cho cô ấy khu vực lưu trữ)
C: Approved a special request (Phê duyệt một yêu cầu đặc biệt)
D: Packed some large boxes (Đóng gói một số hộp lớn)

Người phụ nữ nói rằng giám sát viên đã chỉ cho cô ấy nơi lưu trữ vật tư: "my supervisor showed me where the supplies are stored" (giám sát viên của tôi đã chỉ cho tôi nơi lưu trữ vật tư).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5766, 255, '2025/test7/audio/test7_question_65_67.mp3', '2025/test7/image/test7-p3-image-65.jpg', 'M-Au: Ms. Provost, the last few dinner guests are heading out now. I''m going to start packing up, unless you need anything else.
w-Br: No, thanks. It''s all fine. I hope you got a lot of great shots of the guests and the different parts of the event.
M-Au: I certainly did, and I can send you some sample images within the next few days. Also, I''m very sorry that I didn''t remember to bring some of the props from my studio.
W-Br: Don''t worry about that. This is a historic hotel, so it''s just gorgeous inside. We had plenty of different backdrops to use.', 'Nam: Thưa cô Provost, những vị khách cuối cùng đang rời đi. Tôi sẽ bắt đầu thu dọn, trừ khi cô cần gì thêm.
Nữ: Không, cảm ơn. Mọi thứ đều ổn. Tôi hy vọng anh đã có nhiều bức ảnh đẹp về khách và các phần khác nhau của sự kiện.
Nam: Chắc chắn rồi, và tôi có thể gửi cho cô một số hình mẫu trong vài ngày tới. Ngoài ra, tôi rất xin lỗi vì đã không nhớ mang theo một số đạo cụ từ studio của tôi.
Nữ: Đừng lo về điều đó. Đây là một khách sạn lịch sử, nên bên trong rất tuyệt đẹp. Chúng ta có rất nhiều phông nền khác nhau để sử dụng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7265, 5766, 65, 'Look at the graphic. What was the fee for the services provided by the man?', '$8,175', '$1,750', '$1,200', '$680', 'C', 'Question: "Look at the graphic. What was the fee for the services provided by the man?" (Nhìn vào hình. Phí dịch vụ của người đàn ông là bao nhiêu?)
A: $8,175 (8,175 đô)
B: $1,750 (1,750 đô)
C: $1,200 (1,200 đô)
D: $680 (680 đô)

Theo bảng giá trong hình, chi phí cho dịch vụ chụp ảnh (Photography) là $1,200. Từ cuộc đối thoại, chúng ta biết người đàn ông là nhiếp ảnh gia vì anh ấy nói về việc chụp ảnh khách và gửi hình mẫu.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5767, 255, '2025/test7/audio/test7_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7266, 5767, 66, 'Why does the man apologize to the woman?', 'He did not answer a phone call', 'Some items were forgotten', 'A start time was delayed', 'An invoice contained an error', 'B', 'Question: "Why does the man apologize to the woman?" (Tại sao người đàn ông xin lỗi người phụ nữ?)
A: He did not answer a phone call (Anh ấy không trả lời điện thoại)
B: Some items were forgotten (Một số đồ vật bị quên)
C: A start time was delayed (Thời gian bắt đầu bị trễ)
D: An invoice contained an error (Hóa đơn có lỗi)

Người đàn ông xin lỗi vì đã quên mang theo đạo cụ từ studio: "I''m very sorry that I didn''t remember to bring some of the props from my studio" (tôi rất xin lỗi vì đã không nhớ mang theo một số đạo cụ từ studio của tôi).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5768, 255, '2025/test7/audio/test7_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7267, 5768, 67, 'What does the woman like about the hotel?', 'It has affordable rental rates', 'It has a beautiful interior', 'It is near a major roadway', 'It has several meeting spaces', 'B', 'Question: "What does the woman like about the hotel?" (Người phụ nữ thích điều gì về khách sạn?)
A: It has affordable rental rates (Nó có giá thuê phải chăng)
B: It has a beautiful interior (Nó có nội thất đẹp)
C: It is near a major roadway (Nó gần đường chính)
D: It has several meeting spaces (Nó có nhiều phòng họp)

Người phụ nữ thích khách sạn vì nó có nội thất đẹp, được thể hiện qua câu: "This is a historic hotel, so it''s just gorgeous inside" (Đây là một khách sạn lịch sử, nên bên trong rất tuyệt đẹp).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5769, 255, '2025/test7/audio/test7_question_68_70.mp3', '2025/test7/image/test7-p3-image-68.jpg', 'W-Am: Hi, Edward. Do you want to go to the Greenway Jazz Band concert this Saturday? I have an extra ticket.
M-Au: This Saturday? That''s surprising! I thought the show was on Friday. I tried to get tickets, but they were sold out.
W-Am: They decided to add another show for Saturday because of the high demand. And the seats I got aren''t too bad. They''re far from the stage, but they''re in the middle section.
M-Au: I''d love to go. Thank you so much!
w-Am: Fantastic! I actually couldn''t have gone to the Friday show anyway because my friend is showing her paintings at the Dolby Gallery, and Friday is the opening night.', 'Nữ: Chào Edward. Anh có muốn đi xem concert của ban nhạc Greenway Jazz vào thứ Bảy này không? Tôi có một vé dư.
Nam: Thứ Bảy này ư? Thật ngạc nhiên! Tôi tưởng buổi diễn là vào thứ Sáu. Tôi đã cố mua vé nhưng chúng đã bán hết.
Nữ: Họ quyết định thêm một buổi diễn vào thứ Bảy vì nhu cầu cao. Và chỗ ngồi tôi có không tệ lắm. Chúng hơi xa sân khấu, nhưng ở khu vực giữa.
Nam: Tôi rất muốn đi. Cảm ơn chị rất nhiều!
Nữ: Tuyệt vời! Thực ra tôi cũng không thể đi buổi diễn thứ Sáu vì bạn tôi đang trưng bày tranh tại Phòng trưng bày Dolby, và thứ Sáu là đêm khai mạc.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7268, 5769, 68, 'What is the man surprised about?', 'The woman has joined a jazz band', 'A group is offering a second performance', 'The price of some tickets has changed', 'A new venue for an event was announced', 'B', 'Question: "What is the man surprised about?" (Người đàn ông ngạc nhiên về điều gì?)
A: The woman has joined a jazz band (Người phụ nữ đã tham gia một ban nhạc jazz)
B: A group is offering a second performance (Một nhóm đang tổ chức buổi diễn thứ hai)
C: The price of some tickets has changed (Giá của một số vé đã thay đổi)
D: A new venue for an event was announced (Một địa điểm mới cho sự kiện đã được thông báo)

Người đàn ông ngạc nhiên khi biết có thêm một buổi biểu diễn vào thứ Bảy. Ban đầu anh ấy nghĩ chỉ có buổi diễn vào thứ Sáu và đã bị bán hết vé, nhưng họ đã thêm một buổi diễn thứ hai vào thứ Bảy do nhu cầu cao: "They decided to add another show for Saturday because of the high demand".');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5770, 255, '2025/test7/audio/test7_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7269, 5770, 69, 'Look at the graphic. For which section does the woman have tickets?', 'Section A', 'Section B', 'Section C', 'Section D', 'C', 'Question: "Look at the graphic. For which section does the woman have tickets?" (Nhìn vào hình. Người phụ nữ có vé cho khu vực nào?)
A: Section A (Khu vực A)
B: Section B (Khu vực B)
C: Section C (Khu vực C)
D: Section D (Khu vực D)

Người phụ nữ có vé ở Section C vì:
1. Cô ấy nói ghế ngồi "far from the stage" (xa sân khấu)
2. Nhưng ở "middle section" (khu vực giữa)
3. Trong sơ đồ, Section C là khu vực ở giữa và xa sân khấu nhất');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5771, 255, '2025/test7/audio/test7_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7270, 5771, 70, 'What will the woman do this Friday?', 'Help her friend move', 'Attend an art exhibition', 'Host a holiday party', 'Do some home repair tasks', 'B', 'Question: "What will the woman do this Friday?" (Người phụ nữ sẽ làm gì vào thứ Sáu này?)
A: Help her friend move (Giúp bạn chuyển nhà)
B: Attend an art exhibition (Tham dự triển lãm nghệ thuật)
C: Host a holiday party (Tổ chức tiệc nghỉ lễ)
D: Do some home repair tasks (Làm một số việc sửa chữa nhà)

Người phụ nữ sẽ tham dự triển lãm nghệ thuật vào thứ Sáu vì cô ấy nói: "my friend is showing her paintings at the Dolby Gallery, and Friday is the opening night" (bạn tôi đang trưng bày tranh tại Phòng trưng bày Dolby, và thứ Sáu là đêm khai mạc).');;

-- Data for 2025 Test7 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5772, 256, '2025/test7/audio/test7_question_71_73.mp3', NULL, 'May I have your attention, please? Now that the orchestra has completed the first half of its performance, it is time for intermission. You probably noticed that some of the stage lights were flickering, and we will try to get these repaired during intermission. We are sorry for any inconvenience or discomfort. By way of apology, please come to the box office on your way out to receive a coupon for ten percent off your next ticket purchase. Thank you for your understanding.', 'Xin cho phép tôi có được sự chú ý của quý vị. Bây giờ dàn nhạc đã hoàn thành nửa đầu buổi biểu diễn của họ, đã đến giờ nghỉ giải lao. Có lẽ quý vị đã nhận thấy một số đèn sân khấu bị nhấp nháy, và chúng tôi sẽ cố gắng sửa chữa chúng trong giờ giải lao. Chúng tôi xin lỗi vì bất kỳ sự bất tiện hoặc khó chịu nào. Để bày tỏ lời xin lỗi, vui lòng đến quầy bán vé trên đường ra để nhận phiếu giảm giá mười phần trăm cho lần mua vé tiếp theo của quý vị. Cảm ơn sự thông cảm của quý vị.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7271, 5772, 71, 'Where is the announcement taking place?', 'At a public library', 'At a history museum', 'At a concert hall', 'At a sports stadium', 'C', '[Dịch] Câu hỏi: Thông báo đang diễn ra ở đâu?
A: Tại một thư viện công cộng
B: Tại một bảo tàng lịch sử
C: Tại một phòng hòa nhạc
D: Tại một sân vận động

Đáp án C là chính xác vì thông báo đề cập đến dàn nhạc (orchestra) đang biểu diễn và có đèn sân khấu (stage lights), cho thấy đây là một phòng hòa nhạc.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5773, 256, '2025/test7/audio/test7_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7272, 5773, 72, 'Why does the speaker apologize to the listeners?', 'Some lights were malfunctioning.', 'The building is hotter than usual.', 'An event began later than scheduled.', 'Some tickets had a misprint.', 'A', '[Dịch] Câu hỏi: Tại sao người nói xin lỗi người nghe?
A: Một số đèn hoạt động không bình thường
B: Tòa nhà nóng hơn bình thường
C: Một sự kiện bắt đầu trễ hơn dự kiến
D: Một số vé bị in sai

Đáp án A là chính xác vì người nói xin lỗi vì "stage lights were flickering" (đèn sân khấu bị nhấp nháy).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5774, 256, '2025/test7/audio/test7_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7273, 5774, 73, 'What is offered to the listeners?', 'A discount coupon', 'A partial refund', 'A complimentary beverage', 'A gift shop voucher', 'A', '[Dịch] Câu hỏi: Điều gì được đề nghị cho người nghe?
A: Một phiếu giảm giá
B: Một khoản hoàn tiền một phần
C: Một đồ uống miễn phí
D: Một phiếu mua hàng tại cửa hàng quà tặng

Đáp án A là chính xác vì người nói đề nghị "a coupon for ten percent off your next ticket purchase" (phiếu giảm giá mười phần trăm cho lần mua vé tiếp theo).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5775, 256, '2025/test7/audio/test7_question_74_76.mp3', NULL, 'Hi, this is Melanie Chong. I booked an appointment with Dr. Sharma for my annual checkup and teeth cleaning for Wednesday. Unfortunately, that day doesn''t work for me anymore. I need to change it to a later date due to an unexpected trip for my job. Is there anything available on Friday? Also, l''ve recently changed the insurance company I use, so I''m wondering about the best way to give you their details. Please call me back at 555-3944.', 'Chào, tôi là Melanie Chong. Tôi đã đặt lịch hẹn với Bác sĩ Sharma để kiểm tra sức khỏe răng miệng hàng năm và vệ sinh răng vào thứ Tư. Thật không may, ngày đó không còn phù hợp với tôi nữa. Tôi cần thay đổi sang một ngày sau đó do có chuyến công tác không lường trước. Có lịch nào trống vào thứ Sáu không? Ngoài ra, tôi gần đây đã thay đổi công ty bảo hiểm tôi sử dụng, vì vậy tôi tự hỏi cách tốt nhất để cung cấp cho các bạn thông tin chi tiết của họ. Vui lòng gọi lại cho tôi theo số 555-3944.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7274, 5775, 74, 'What type of business is the speaker most likely calling?', 'An employment agency', 'A vehicle repair shop', 'A dental office', 'A hair salon', 'C', '[Dịch] Câu hỏi: Người nói có khả năng đang gọi cho loại doanh nghiệp nào?
A: Một công ty tuyển dụng
B: Một tiệm sửa xe
C: Một phòng nha khoa
D: Một salon tóc

Đáp án C là chính xác vì người nói đề cập đến cuộc hẹn với Dr. Sharma để "annual checkup and teeth cleaning" (kiểm tra sức khỏe răng miệng hàng năm và vệ sinh răng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5776, 256, '2025/test7/audio/test7_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7275, 5776, 75, 'What does the speaker mention about her appointment?', 'It was booked with the wrong person.', 'It has to be postponed.', 'It must be at another branch.', 'It includes a new customer discount.', 'B', '[Dịch] Câu hỏi: Người nói đề cập gì về cuộc hẹn của cô ấy?
A: Nó đã được đặt với người sai
B: Nó phải được hoãn lại
C: Nó phải ở một chi nhánh khác
D: Nó bao gồm giảm giá cho khách hàng mới

Đáp án B là chính xác vì người nói cho biết ngày đã đặt không còn phù hợp và cần thay đổi sang một ngày sau ("need to change it to a later date").');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5777, 256, '2025/test7/audio/test7_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7276, 5777, 76, 'What does the speaker want to find out about?', 'Taking public transportation', 'Updating insurance information', 'Receiving an employee discount', 'Handling unexpected charges', 'B', '[Dịch] Câu hỏi: Người nói muốn tìm hiểu về điều gì?
A: Sử dụng phương tiện công cộng
B: Cập nhật thông tin bảo hiểm
C: Nhận giảm giá nhân viên
D: Xử lý các khoản phí không mong đợi

Đáp án B là chính xác vì người nói muốn biết "the best way to give you their details" (cách tốt nhất để cung cấp thông tin chi tiết) về công ty bảo hiểm mới của cô ấy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5778, 256, '2025/test7/audio/test7_question_77_79.mp3', NULL, 'Do you want to experience all that Irvine Bay has to offer? Then book a tour with Wonderful Waves! Our boats depart daily at 9 A.M. and 4 P.M., with our launch site conveniently located near the Boone Street parking area. During the tour, we''ll take you by boat to all of the top sites in the area. Everyone will receive a catered lunch or dinner upon returning from the tour, and we serve free sodas and bottled water on the boat. And for the month of April, you can book online to get an exclusive offer of 15% off for parties of five or more.', 'Bạn có muốn trải nghiệm tất cả những gì Vịnh Irvine có thể mang lại? Hãy đặt một tour với Wonderful Waves! Thuyền của chúng tôi khởi hành hàng ngày lúc 9 giờ sáng và 4 giờ chiều, với điểm khởi hành thuận tiện nằm gần khu vực đỗ xe đường Boone. Trong chuyến tham quan, chúng tôi sẽ đưa bạn bằng thuyền đến tất cả các địa điểm hàng đầu trong khu vực. Mọi người sẽ nhận được bữa trưa hoặc bữa tối được phục vụ khi trở về từ chuyến tham quan, và chúng tôi phục vụ nước ngọt và nước đóng chai miễn phí trên thuyền. Và trong tháng 4, bạn có thể đặt trực tuyến để nhận ưu đãi độc quyền giảm 15% cho nhóm từ năm người trở lên.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7277, 5778, 77, 'What is the advertisement about?', 'An art festival', 'A museum tour', 'A boat ride', 'A holiday parade', 'C', '[Dịch] Câu hỏi: Quảng cáo này nói về cái gì?
A: Một lễ hội nghệ thuật
B: Một tour tham quan bảo tàng
C: Một chuyến đi thuyền
D: Một cuộc diễu hành ngày lễ

Đáp án C là chính xác vì quảng cáo nói về các chuyến tham quan bằng thuyền ("boats depart daily") của công ty Wonderful Waves.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5779, 256, '2025/test7/audio/test7_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7278, 5779, 78, 'What will participants be given?', 'A tote bag', 'A prepared meal', 'A group photograph', 'An area map', 'B', '[Dịch] Câu hỏi: Người tham gia sẽ được nhận gì?
A: Một túi xách
B: Một bữa ăn đã chuẩn bị sẵn
C: Một bức ảnh nhóm
D: Một bản đồ khu vực

Đáp án B là chính xác vì quảng cáo nêu rõ "everyone will receive a catered lunch or dinner upon returning from the tour" (mọi người sẽ nhận được bữa trưa hoặc bữa tối được phục vụ khi trở về từ chuyến tham quan).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5780, 256, '2025/test7/audio/test7_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7279, 5780, 79, 'What does the speaker say can be done on a Web site?', 'Accessing a group discount', 'Viewing videos of the area', 'Making a dinner reservation', 'Watching a safety video', 'A', '[Dịch] Câu hỏi: Người nói nói có thể làm gì trên trang web?
A: Truy cập giảm giá nhóm
B: Xem video về khu vực
C: Đặt chỗ ăn tối
D: Xem video an toàn

Đáp án A là chính xác vì người nói cho biết "you can book online to get an exclusive offer of 15% off for parties of five or more" (bạn có thể đặt trực tuyến để nhận ưu đãi độc quyền giảm 15% cho nhóm từ năm người trở lên).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5781, 256, '2025/test7/audio/test7_question_80_82.mp3', NULL, 'This is Mindy Harper, head of the R&D division at the Nashville branch. I''m calling about our rechargeable battery project. I know that you are not able to commute to our branch, but your supervisor said that you would be willing to do the project on the days that you work from home. Normally, we don''t allow that, but we know that you''re highly experienced. So, please call me back so that we can make the necessary arrangements. We would need to figure out what day you could begin the project. Thanks a lot!', 'Đây là Mindy Harper, trưởng bộ phận R&D tại chi nhánh Nashville. Tôi gọi về dự án pin sạc của chúng ta. Tôi biết rằng bạn không thể di chuyển đến chi nhánh của chúng tôi, nhưng người giám sát của bạn nói rằng bạn sẽ sẵn sàng thực hiện dự án vào những ngày bạn làm việc tại nhà. Thông thường, chúng tôi không cho phép điều đó, nhưng chúng tôi biết rằng bạn rất có kinh nghiệm. Vì vậy, vui lòng gọi lại cho tôi để chúng ta có thể thu xếp những việc cần thiết. Chúng ta cần tìm ra ngày nào bạn có thể bắt đầu dự án. Cảm ơn bạn rất nhiều!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7280, 5781, 80, 'Which department does the speaker work in?', 'Human resources', 'Building maintenance', 'Research and development', 'Information technology', 'C', '[Dịch] Câu hỏi: Người nói làm việc ở phòng ban nào?
A: Nhân sự
B: Bảo trì tòa nhà
C: Nghiên cứu và phát triển
D: Công nghệ thông tin

Đáp án C là chính xác vì người nói giới thiệu mình là "head of the R&D division" (trưởng bộ phận R&D - Nghiên cứu và Phát triển).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5782, 256, '2025/test7/audio/test7_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7281, 5782, 81, 'Why does the speaker say, "we know that you''re highly experienced"?', 'To explain the reason for a promotion', 'To accept a request for a pay raise', 'To show understanding of a busy schedule', 'To approve working remotely for a task', 'D', '[Dịch] Câu hỏi: Tại sao người nói nói "chúng tôi biết rằng bạn rất có kinh nghiệm"?
A: Để giải thích lý do cho một sự thăng chức
B: Để chấp nhận yêu cầu tăng lương
C: Để thể hiện sự thấu hiểu về lịch trình bận rộn
D: Để phê duyệt làm việc từ xa cho một nhiệm vụ

Đáp án D là chính xác vì người nói dùng điều này để giải thích tại sao họ chấp nhận cho phép làm việc tại nhà, điều mà thông thường họ không cho phép.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5783, 256, '2025/test7/audio/test7_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7282, 5783, 82, 'What does the speaker want to discuss with the listener?', 'A start date.', 'A payment method', 'Some necessary tools', 'Some coworkers'' skills', 'A', '[Dịch] Câu hỏi: Người nói muốn thảo luận điều gì với người nghe?
A: Một ngày bắt đầu
B: Một phương thức thanh toán
C: Một số công cụ cần thiết
D: Kỹ năng của một số đồng nghiệp

Đáp án A là chính xác vì người nói nêu rõ "We would need to figure out what day you could begin the project" (Chúng ta cần tìm ra ngày nào bạn có thể bắt đầu dự án).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5784, 256, '2025/test7/audio/test7_question_83_85.mp3', NULL, 'Welcome to Gilbert International''s fifth annual conference on preventative medicine. Last year we had nearly five hundred people in attendance at the venue, but you''ll notice we have about half as much this year. Well, for the first time ever, we''ve added an online option. Now, the first talk will begin in just a moment. And, if you''ve signed up for an afternoon workshop, just make sure you confirm which room you''re going to. Our staff can direct you if needed.', 'Chào mừng đến với hội nghị thường niên lần thứ năm về y học dự phòng của Gilbert International. Năm ngoái chúng ta có gần năm trăm người tham dự tại địa điểm, nhưng bạn sẽ nhận thấy chúng ta có khoảng một nửa số đó trong năm nay. À, lần đầu tiên, chúng tôi đã thêm một lựa chọn trực tuyến. Bây giờ, bài nói đầu tiên sẽ bắt đầu trong giây lát. Và, nếu bạn đã đăng ký tham gia hội thảo buổi chiều, chỉ cần đảm bảo bạn xác nhận phòng bạn sẽ đến. Nhân viên của chúng tôi có thể hướng dẫn bạn nếu cần.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7283, 5784, 83, 'What kind of event is taking place?', 'A product launch', 'A group interview session', 'A medical conference', 'A film festival', 'C', '[Dịch] Câu hỏi: Loại sự kiện nào đang diễn ra?
A: Một buổi ra mắt sản phẩm
B: Một buổi phỏng vấn nhóm
C: Một hội nghị y tế
D: Một liên hoan phim

Đáp án C là chính xác vì đây là "conference on preventative medicine" (hội nghị về y học dự phòng) của Gilbert International.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5785, 256, '2025/test7/audio/test7_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7284, 5785, 84, 'Why does the speaker say, "we''ve added an online option"?', 'To encourage listeners to make a purchase', 'To apologize for some technical difficulties', 'To demonstrate that listeners'' ideas are being used', 'To explain why a group is smaller in size', 'D', '[Dịch] Câu hỏi: Tại sao người nói nói "chúng tôi đã thêm một lựa chọn trực tuyến"?
A: Để khuyến khích người nghe mua hàng
B: Để xin lỗi về một số khó khăn kỹ thuật
C: Để chứng minh rằng ý kiến của người nghe đang được sử dụng
D: Để giải thích tại sao một nhóm nhỏ hơn về quy mô

Đáp án D là chính xác vì người nói dùng điều này để giải thích tại sao số lượng người tham dự tại địa điểm chỉ bằng một nửa năm ngoái.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5786, 256, '2025/test7/audio/test7_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7285, 5786, 85, 'What are the listeners asked to do?', 'Turn off their phones temporarily', 'Check the locations of some activities', 'Complete a form to provide feedback', 'Wear a name tag during the event', 'B', '[Dịch] Câu hỏi: Người nghe được yêu cầu làm gì?
A: Tắt điện thoại tạm thời
B: Kiểm tra địa điểm của một số hoạt động
C: Điền vào mẫu để cung cấp phản hồi
D: Đeo thẻ tên trong suốt sự kiện

Đáp án B là chính xác vì người nói yêu cầu những người đăng ký hội thảo buổi chiều "make sure you confirm which room you''re going to" (đảm bảo xác nhận phòng bạn sẽ đến).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5787, 256, '2025/test7/audio/test7_question_86_88.mp3', NULL, 'Thank you for stopping by our booth at the expo! We''re thrilled to introduce our new line of kitchen flooring today. It looks like wood, but it is actually made of plastic. With our unique design, you can get the look and feel of wood, but this new plastic is much tougher. Even after years of walking on it, it will still look like new. There are a variety of shades to choose from. I''ll pass out our catalog now, which shows everything we sell and the color options that are available.', 'Cảm ơn bạn đã ghé qua gian hàng của chúng tôi tại triển lãm! Chúng tôi rất vui được giới thiệu dòng sàn nhà bếp mới của chúng tôi hôm nay. Nó trông giống như gỗ, nhưng thực tế được làm từ nhựa. Với thiết kế độc đáo của chúng tôi, bạn có thể có được vẻ ngoài và cảm giác của gỗ, nhưng loại nhựa mới này bền hơn nhiều. Ngay cả sau nhiều năm đi lại trên nó, nó vẫn sẽ trông như mới. Có nhiều màu sắc để lựa chọn. Tôi sẽ phát catalog của chúng tôi ngay bây giờ, nó cho thấy tất cả những gì chúng tôi bán và các lựa chọn màu sắc có sẵn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7286, 5787, 86, 'What kind of business does the speaker work for?', 'A package delivery service', 'A computer software distributor', 'A fashion design company', 'A flooring manufacturer', 'D', '[Dịch] Câu hỏi: Người nói làm việc cho loại doanh nghiệp nào?
A: Một dịch vụ giao hàng
B: Một nhà phân phối phần mềm máy tính
C: Một công ty thiết kế thời trang
D: Một nhà sản xuất sàn nhà

Đáp án D là chính xác vì người nói đang giới thiệu "new line of kitchen flooring" (dòng sàn nhà bếp mới) và thảo luận về các đặc điểm của sản phẩm này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5788, 256, '2025/test7/audio/test7_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7287, 5788, 87, 'What advantage of the new material does the speaker mention?', 'It is very durable.', 'It is inexpensive.', 'It is available in many sizes.', 'It is good for the environment.', 'A', '[Dịch] Câu hỏi: Người nói đề cập đến ưu điểm gì của vật liệu mới?
A: Nó rất bền
B: Nó không đắt
C: Nó có sẵn nhiều kích cỡ
D: Nó tốt cho môi trường

Đáp án A là chính xác vì người nói nhấn mạnh rằng loại nhựa mới này "much tougher" (bền hơn nhiều) và "even after years of walking on it, it will still look like new" (ngay cả sau nhiều năm đi lại trên nó, nó vẫn sẽ trông như mới).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5789, 256, '2025/test7/audio/test7_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7288, 5789, 88, 'What will the speaker do next?', 'Respond to listeners'' questions', 'Distribute a product catalog', 'Show the listeners a chart', 'Introduce one of her colleagues', 'B', '[Dịch] Câu hỏi: Người nói sẽ làm gì tiếp theo?
A: Trả lời câu hỏi của người nghe
B: Phát một catalog sản phẩm
C: Cho người nghe xem một biểu đồ
D: Giới thiệu một trong những đồng nghiệp của cô ấy

Đáp án B là chính xác vì người nói tuyên bố "I''ll pass out our catalog now" (Tôi sẽ phát catalog của chúng tôi ngay bây giờ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5790, 256, '2025/test7/audio/test7_question_89_91.mp3', NULL, 'You''re listening to Community Corner on Radio 22. On Saturday, June 29, the town''s annual cooking contest will take place at Blossom Hall. Even if you don''t make anything, don''t forget that attendees get to try the food after the judging is completed. There will be plenty to go around. There are several categories for entry, including stews, grilled meat, pasta, and more. Tomorrow, the event''s planner, Ayako Yano, will visit the studio to share the details about the entry requirements. She''ll also let us know what prizes will be given to the winners of the event, which I''m sure everyone will want to hear about. Be sure to tune in!', 'Bạn đang nghe Community Corner trên Radio 22. Vào thứ Bảy, ngày 29 tháng 6, cuộc thi nấu ăn thường niên của thị trấn sẽ diễn ra tại Blossom Hall. Ngay cả khi bạn không nấu món gì, đừng quên rằng những người tham dự sẽ được nếm thử đồ ăn sau khi việc chấm giải hoàn thành. Sẽ có rất nhiều đồ ăn cho mọi người. Có nhiều hạng mục để tham gia, bao gồm món hầm, thịt nướng, mì ống và nhiều món khác. Ngày mai, người tổ chức sự kiện, Ayako Yano, sẽ đến phòng thu để chia sẻ chi tiết về các yêu cầu tham gia. Cô ấy cũng sẽ cho chúng ta biết những giải thưởng nào sẽ được trao cho người chiến thắng của sự kiện, điều mà tôi chắc chắn mọi người sẽ muốn nghe về. Hãy nhớ theo dõi!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7289, 5790, 89, 'What event does the speaker mention?', 'A comedy show', 'A graduation ceremony', 'A theater performance', 'A cooking competition', 'D', '[Dịch] Câu hỏi: Người nói đề cập đến sự kiện gì?
A: Một buổi biểu diễn hài
B: Một lễ tốt nghiệp
C: Một buổi biểu diễn sân khấu
D: Một cuộc thi nấu ăn

Đáp án D là chính xác vì người nói đang thông báo về "the town''s annual cooking contest" (cuộc thi nấu ăn thường niên của thị trấn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5791, 256, '2025/test7/audio/test7_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7290, 5791, 90, 'Why does the speaker say, "There will be plenty to go around"?', 'To ask people to be patient when receiving items', 'To confirm that the selected venue is large enough', 'To explain that tickets will probably not sell out', 'To encourage the listeners to attend an event', 'D', '[Dịch] Câu hỏi: Tại sao người nói nói "Sẽ có rất nhiều để đi vòng quanh"?
A: Để yêu cầu mọi người kiên nhẫn khi nhận đồ
B: Để xác nhận địa điểm được chọn đủ lớn
C: Để giải thích rằng vé có thể sẽ không bán hết
D: Để khuyến khích người nghe tham dự sự kiện

Đáp án D là chính xác vì người nói dùng cụm từ này để nhấn mạnh rằng sẽ có nhiều đồ ăn cho mọi người nếm thử, như một cách khuyến khích mọi người tham dự sự kiện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5792, 256, '2025/test7/audio/test7_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7291, 5792, 91, 'What will happen tomorrow?', 'An enrollment period will begin.', 'A discount on tickets will be offered.', 'A Web site will be launched.', 'A list of prizes will be announced.', 'D', '[Dịch] Câu hỏi: Điều gì sẽ xảy ra vào ngày mai?
A: Một thời kỳ ghi danh sẽ bắt đầu
B: Một ưu đãi giảm giá vé sẽ được đưa ra
C: Một trang web sẽ được ra mắt
D: Một danh sách giải thưởng sẽ được công bố

Đáp án D là chính xác vì người nói cho biết Ayako Yano "will let us know what prizes will be given to the winners" (sẽ cho chúng ta biết những giải thưởng nào sẽ được trao cho người chiến thắng) vào ngày mai.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5793, 256, '2025/test7/audio/test7_question_92_94.mp3', NULL, 'Good morning, everyone. The Flynn City Planning Committee is pleased to announce the approval of a project to build twenty-five miles of bicycle lanes in our city. We hope this will encourage people to get more exercise, which is good for their overall health. Upon completion of the project, we will run a series of advertisements to inform out-of-town visitors about the new bicycle lanes. Thanks to mainly using existing roadways, the lanes will be open by August, and next year we will evaluate the success of the project to see if further expansion of the network is justified.', 'Chào buổi sáng, mọi người. Ủy ban Quy hoạch Thành phố Flynn rất vui mừng thông báo việc phê duyệt dự án xây dựng hai mươi lăm dặm làn đường dành cho xe đạp trong thành phố của chúng ta. Chúng tôi hy vọng điều này sẽ khuyến khích mọi người tập thể dục nhiều hơn, điều này tốt cho sức khỏe tổng thể của họ. Sau khi hoàn thành dự án, chúng tôi sẽ thực hiện một loạt quảng cáo để thông báo cho khách từ ngoài thành phố về các làn đường xe đạp mới. Nhờ chủ yếu sử dụng các con đường hiện có, các làn đường sẽ được mở vào tháng Tám, và năm sau chúng tôi sẽ đánh giá sự thành công của dự án để xem liệu việc mở rộng thêm mạng lưới có được chứng minh là hợp lý hay không.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7292, 5793, 92, 'According to the speaker, what is the purpose of the project?', 'To cut public spending', 'To promote a healthy habit', 'To reduce road accidents', 'To attract more businesses', 'B', '[Dịch] Câu hỏi: Theo người nói, mục đích của dự án là gì?
A: Để cắt giảm chi tiêu công
B: Để thúc đẩy thói quen lành mạnh
C: Để giảm tai nạn giao thông
D: Để thu hút thêm doanh nghiệp

Đáp án B là chính xác vì người nói cho biết họ hy vọng dự án sẽ "encourage people to get more exercise, which is good for their overall health" (khuyến khích mọi người tập thể dục nhiều hơn, điều này tốt cho sức khỏe tổng thể của họ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5794, 256, '2025/test7/audio/test7_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7293, 5794, 93, 'Who will be targeted in an ad campaign?', 'Students', 'Business owners', 'Tourists', 'Prospective investors', 'C', '[Dịch] Câu hỏi: Ai sẽ là đối tượng mục tiêu trong chiến dịch quảng cáo?
A: Học sinh
B: Chủ doanh nghiệp
C: Du khách
D: Các nhà đầu tư tiềm năng

Đáp án C là chính xác vì người nói cho biết họ sẽ chạy quảng cáo để "inform out-of-town visitors" (thông báo cho khách từ ngoài thành phố) về các làn đường xe đạp mới.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5795, 256, '2025/test7/audio/test7_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7294, 5795, 94, 'What will happen next year?', 'A communication network will be upgraded.', 'An assessment will be carried out.', 'Voters will elect a new mayor.', 'The city will host a bicycle race.', 'B', '[Dịch] Câu hỏi: Điều gì sẽ xảy ra vào năm sau?
A: Một mạng lưới truyền thông sẽ được nâng cấp
B: Một đánh giá sẽ được thực hiện
C: Cử tri sẽ bầu một thị trưởng mới
D: Thành phố sẽ tổ chức một cuộc đua xe đạp

Đáp án B là chính xác vì người nói cho biết "next year we will evaluate the success of the project" (năm sau chúng tôi sẽ đánh giá sự thành công của dự án).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5796, 256, '2025/test7/audio/test7_question_95_97.mp3', '2025/test7/image/test7-p4-image-95.jpg', 'Hello, Ms. Nakano. This is Damon Arroyo at Pruitt Insurance. I''m calling about the workshop on sales techniques that you''ll be conducting at our office. Some staff from another branch are going to join, so the total number of participants will now be eighteen. Also, can you let me know your car''s license plate number? I need it to request your parking permit from our business complex''s parking office. With a permit, you''ll be able to park in the visitors'' lot between the Hastings Building and the Levine Building, instead of on the street.', 'Xin chào, cô Nakano. Tôi là Damon Arroyo từ Bảo hiểm Pruitt. Tôi gọi về buổi hội thảo về kỹ thuật bán hàng mà cô sẽ tiến hành tại văn phòng chúng tôi. Một số nhân viên từ chi nhánh khác sẽ tham gia, vì vậy tổng số người tham gia bây giờ sẽ là mười tám. Ngoài ra, cô có thể cho tôi biết biển số xe của cô được không? Tôi cần nó để yêu cầu giấy phép đỗ xe từ văn phòng bãi đỗ xe của khu phức hợp kinh doanh của chúng tôi. Với giấy phép, cô sẽ có thể đỗ xe ở bãi đỗ xe dành cho khách giữa Tòa nhà Hastings và Tòa nhà Levine, thay vì trên đường phố.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7295, 5796, 95, 'Who most likely is the listener?', 'A potential customer', 'A corporate trainer', 'A truck driver', 'A repair technician', 'B', '[Dịch] Câu hỏi: Người nghe có khả năng là ai?
A: Một khách hàng tiềm năng
B: Một người đào tạo doanh nghiệp
C: Một tài xế xe tải
D: Một kỹ thuật viên sửa chữa

Đáp án B là chính xác vì người nghe (Ms. Nakano) sẽ tiến hành "workshop on sales techniques" (hội thảo về kỹ thuật bán hàng), điều này cho thấy cô ấy là một người đào tạo doanh nghiệp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5797, 256, '2025/test7/audio/test7_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7296, 5797, 96, 'What should the listener inform the speaker of?', 'Her technology needs', 'Her meal preference', 'Her vehicle information', 'Her expected arrival time', 'C', '[Dịch] Câu hỏi: Người nghe nên thông báo cho người nói về điều gì?
A: Nhu cầu công nghệ của cô ấy
B: Sở thích bữa ăn của cô ấy
C: Thông tin phương tiện của cô ấy
D: Thời gian đến dự kiến của cô ấy

Đáp án C là chính xác vì người nói yêu cầu "car''s license plate number" (biển số xe) của người nghe để xin giấy phép đỗ xe.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5798, 256, '2025/test7/audio/test7_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7297, 5798, 97, 'Look at the graphic. According to the speaker, where can visitors with parking permits park?', 'In Lot A', 'In Lot B', 'In Lot C', 'Along Stone Street', 'A', '[Dịch] Câu hỏi: Nhìn vào hình. Theo người nói, khách có giấy phép đỗ xe có thể đỗ xe ở đâu?
A: Tại Bãi A
B: Tại Bãi B
C: Tại Bãi C
D: Dọc đường Stone

Đáp án A là chính xác vì người nói cho biết có thể đỗ xe "between the Hastings Building and the Levine Building" (giữa Tòa nhà Hastings và Tòa nhà Levine), và nhìn vào bản đồ, Lot A nằm giữa hai tòa nhà này.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5799, 256, '2025/test7/audio/test7_question_98_100.mp3', '2025/test7/image/test7-p4-image-98.jpg', 'Thanks for tuning in to Daily Steps with Amish Punja. In each episode, I welcome a new guest to share the latest advice on staying fit and healthy. Our two-hundredth episode will be broadcast on March 16. To celebrate this milestone, we are giving away a number of great prizes. For a chance to win, simply register for the drawing on our Web site. The winners will be announced on March 16. Alright, now, I would like to welcome Maya Mendoza to the studio. I''m sure you''ll find her comments useful.', 'Cảm ơn bạn đã theo dõi Daily Steps cùng Amish Punja. Trong mỗi tập, tôi chào đón một khách mời mới để chia sẻ lời khuyên mới nhất về việc giữ gìn sức khỏe và thể hình. Tập thứ hai trăm của chúng tôi sẽ được phát sóng vào ngày 16 tháng 3. Để kỷ niệm cột mốc này, chúng tôi sẽ tặng một số giải thưởng tuyệt vời. Để có cơ hội thắng giải, chỉ cần đăng ký rút thăm trên trang web của chúng tôi. Người thắng giải sẽ được công bố vào ngày 16 tháng 3. Được rồi, bây giờ, tôi muốn chào đón Maya Mendoza đến với phòng thu. Tôi chắc chắn bạn sẽ thấy những bình luận của cô ấy hữu ích.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7298, 5799, 98, 'Why are guests included on the radio show?', 'To offer financial advice', 'To talk about business opportunities', 'To provide health tips', 'To discuss a hospital expansion', 'C', '[Dịch] Câu hỏi: Tại sao các khách mời được đưa vào chương trình radio?
A: Để đưa ra lời khuyên tài chính
B: Để nói về cơ hội kinh doanh
C: Để cung cấp lời khuyên về sức khỏe
D: Để thảo luận về việc mở rộng bệnh viện

Đáp án C là chính xác vì người nói cho biết khách mời được mời đến để "share the latest advice on staying fit and healthy" (chia sẻ lời khuyên mới nhất về việc giữ gìn sức khỏe và thể hình).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5800, 256, '2025/test7/audio/test7_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7299, 5800, 99, 'According to the speaker, what can listeners do on a Web site?', 'Read product reviews from the host', 'Enter an upcoming prize drawing', 'Download full episodes of the show', 'Get guests'' contact details', 'B', '[Dịch] Câu hỏi: Theo người nói, người nghe có thể làm gì trên trang web?
A: Đọc đánh giá sản phẩm từ người dẫn chương trình
B: Tham gia rút thăm trúng thưởng sắp tới
C: Tải về các tập đầy đủ của chương trình
D: Lấy thông tin liên hệ của khách mời

Đáp án B là chính xác vì người nói cho biết để có cơ hội thắng giải, người nghe cần "register for the drawing on our Web site" (đăng ký rút thăm trên trang web của chúng tôi).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5801, 256, '2025/test7/audio/test7_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7300, 5801, 100, 'Look at the graphic. When is this episode being broadcast?', 'On Monday', 'On Tuesday', 'On Wednesday', 'On Thursday', 'B', '[Dịch] Câu hỏi: Nhìn vào hình. Tập này được phát sóng khi nào?
A: Vào thứ Hai
B: Vào thứ Ba
C: Vào thứ Tư
D: Vào thứ Năm

Đáp án B là chính xác vì Maya Mendoza, người vừa được giới thiệu trong tập này, xuất hiện trong lịch phỏng vấn vào ngày thứ Ba.');;

-- Data for 2025 Test7 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5802, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7301, 5802, 101, 'Since the weather has been unusually cold, expect ----- heating system to be used more often.', 'us', 'our', 'ours', 'ourselves', 'B', 'Đáp án B (our) là đúng vì các lý do sau:
1. Cần một tính từ sở hữu để xác định chủ sở hữu của "heating system".
2. "Our" là tính từ sở hữu đứng trước danh từ.
3. Cấu trúc "tính từ sở hữu + danh từ" là cấu trúc phổ biến trong tiếng Anh.
4. Các đáp án khác không phù hợp: "us" (đại từ nhân xưng), "ours" (đại từ sở hữu), "ourselves" (đại từ phản thân).
Dịch câu hỏi: Vì thời tiết đã trở nên lạnh bất thường, hãy chuẩn bị cho hệ thống sưởi của chúng ta được sử dụng thường xuyên hơn.
Dịch đáp án:
A. us (đại từ nhân xưng: chúng tôi)
B. our (tính từ sở hữu: của chúng tôi)
C. ours (đại từ sở hữu: cái của chúng tôi)
D. ourselves (đại từ phản thân: chính chúng tôi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5803, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7302, 5803, 102, 'Austin Inc. strictly prohibits the sharing of ----- memos and other company correspondence.', 'internalization', 'internalize', 'internally', 'internal', 'D', 'Đáp án D (internal) là đúng vì các lý do sau:
1. Cần một tính từ để mô tả loại bản ghi nhớ.
2. "Internal" là tính từ có nghĩa "nội bộ".
3. "Internal memos" là cụm từ phổ biến trong môi trường doanh nghiệp.
4. Các đáp án khác không phù hợp: "internalization" (danh từ), "internalize" (động từ), "internally" (trạng từ).
Dịch câu hỏi: Austin Inc. nghiêm cấm việc chia sẻ các bản ghi nhớ nội bộ và thư từ công ty khác.
Dịch đáp án:
A. internalization (danh từ: sự nội bộ hóa)
B. internalize (động từ: nội bộ hóa)
C. internally (trạng từ: một cách nội bộ)
D. internal (tính từ: nội bộ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5804, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7303, 5804, 103, 'Segal Bay visitors enjoy using the path ----- the coast to take in the sea air.', 'regarding', 'along', 'except', 'under', 'B', 'Đáp án B (along) là đúng vì các lý do sau:
1. Cần một giới từ chỉ vị trí hoặc hướng đi.
2. "Along" là giới từ có nghĩa "dọc theo".
3. "Along the coast" là cụm từ phổ biến chỉ vị trí dọc bờ biển.
4. Các đáp án khác không phù hợp: "regarding" (về), "except" (ngoại trừ), "under" (dưới).
Dịch câu hỏi: Khách thăm quan Vịnh Segal thích sử dụng con đường dọc theo bờ biển để hít thở không khí biển.
Dịch đáp án:
A. regarding (giới từ: về)
B. along (giới từ: dọc theo)
C. except (giới từ: ngoại trừ)
D. under (giới từ: dưới)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5805, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7304, 5805, 104, 'The firm has reduced its waste ----  various recycling programs and strict policies.', 'through', 'onto', 'as', 'to', 'A', 'Đáp án A (through) là đúng vì các lý do sau:
1. Cần một giới từ chỉ phương tiện hoặc cách thức.
2. "Through" là giới từ có nghĩa "thông qua".
3. Cấu trúc "through + noun" diễn tả phương tiện để đạt được kết quả.
4. Các đáp án khác không phù hợp: "onto" (lên trên), "as" (như là), "to" (đến).
Dịch câu hỏi: Công ty đã giảm chất thải của mình thông qua các chương trình tái chế và chính sách nghiêm ngặt.
Dịch đáp án:
A. through (giới từ: thông qua)
B. onto (giới từ: lên trên)
C. as (giới từ/liên từ: như là)
D. to (giới từ: đến)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5806, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7305, 5806, 105, 'The medications are ----- tested to ensure compliance with safety regulations.', 'conveniently', 'tightly', 'rigorously', 'approximately', 'C', 'Đáp án C (rigorously) là đúng vì các lý do sau:
1. Cần một trạng từ mô tả cách thức kiểm tra thuốc.
2. "Rigorously" có nghĩa là "nghiêm ngặt, kỹ lưỡng".
3. Phù hợp với ngữ cảnh về quy định an toàn trong ngành dược.
4. Các đáp án khác không phù hợp: "conveniently" (thuận tiện), "tightly" (chặt chẽ), "approximately" (xấp xỉ).
Dịch câu hỏi: Các loại thuốc được kiểm tra nghiêm ngặt để đảm bảo tuân thủ các quy định về an toàn.
Dịch đáp án:
A. conveniently (trạng từ: thuận tiện)
B. tightly (trạng từ: chặt chẽ)
C. rigorously (trạng từ: nghiêm ngặt)
D. approximately (trạng từ: xấp xỉ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5807, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7306, 5807, 106, 'Ms. Bracken would like ----- the diligent efforts of her team at the upcoming staff get-together.', 'recognizing', 'recognition', 'to recognize', 'having recognized', 'C', 'Đáp án C (to recognize) là đúng vì các lý do sau:
1. Cần một động từ nguyên mẫu sau "would like".
2. Cấu trúc "would like + to V" là cấu trúc phổ biến để diễn tả mong muốn.
3. "To recognize" là động từ nguyên mẫu phù hợp với cấu trúc này.
4. Các đáp án khác không phù hợp: "recognizing" (V-ing), "recognition" (danh từ), "having recognized" (hoàn thành).
Dịch câu hỏi: Bà Bracken muốn ghi nhận những nỗ lực chăm chỉ của đội nhóm mình tại buổi gặp mặt nhân viên sắp tới.
Dịch đáp án:
A. recognizing (động từ ing: đang ghi nhận)
B. recognition (danh từ: sự ghi nhận)
C. to recognize (động từ nguyên mẫu: để ghi nhận)
D. having recognized (động từ hoàn thành: đã ghi nhận)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5808, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7307, 5808, 107, 'After ----- several major market fluctuations accurately, Ms. Kimball gained popularity as a financial adviser.', 'prediction', 'predict', 'predicted', 'predicting', 'D', 'Đáp án D (predicting) là đúng vì các lý do sau:
1. Cần một động từ dạng V-ing sau giới từ "after".
2. "After + V-ing" là cấu trúc chỉ một hành động xảy ra trước một hành động khác.
3. Cấu trúc này phổ biến trong tiếng Anh để diễn tả trình tự thời gian.
4. Các đáp án khác không phù hợp: "prediction" (danh từ), "predict" (động từ nguyên thể), "predicted" (quá khứ).
Dịch câu hỏi: Sau khi dự đoán chính xác một số biến động lớn của thị trường, bà Kimball đã trở nên nổi tiếng với tư cách là một cố vấn tài chính.
Dịch đáp án:
A. prediction (danh từ: sự dự đoán)
B. predict (động từ: dự đoán)
C. predicted (động từ quá khứ: đã dự đoán)
D. predicting (động từ ing: việc dự đoán)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5809, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7308, 5809, 108, 'Any international bank transfers requested ----- 3 P.м. will be made before closing time.', 'just', 'later', 'by', 'than', 'C', 'Đáp án C (by) là đúng vì các lý do sau:
1. Cần một giới từ chỉ thời hạn.
2. "By + thời gian" là cụm từ chỉ thời hạn cuối cùng.
3. Phù hợp với ngữ cảnh về thời hạn thực hiện giao dịch ngân hàng.
4. Các đáp án khác không phù hợp: "just" (vừa mới), "later" (sau này), "than" (hơn).
Dịch câu hỏi: Bất kỳ giao dịch chuyển tiền quốc tế nào được yêu cầu trước 3 giờ chiều sẽ được thực hiện trước giờ đóng cửa.
Dịch đáp án:
A. just (trạng từ: vừa mới)
B. later (trạng từ: sau này)
C. by (giới từ: trước)
D. than (liên từ: hơn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5810, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7309, 5810, 109, 'When working on a crucial assignment, it may be better to ----- the deadline rather than rush the work.', 'approve', 'expire', 'adjust', 'observe', 'C', 'Đáp án C (adjust) là đúng vì các lý do sau:
1. Cần một động từ có nghĩa điều chỉnh hoặc thay đổi.
2. "Adjust the deadline" có nghĩa là điều chỉnh thời hạn.
3. Phù hợp với ngữ cảnh về việc không vội vàng để đảm bảo chất lượng công việc.
4. Các đáp án khác không phù hợp: "approve" (phê duyệt), "expire" (hết hạn), "observe" (quan sát).
Dịch câu hỏi: Khi làm việc với một nhiệm vụ quan trọng, có thể tốt hơn là điều chỉnh thời hạn thay vì vội vàng làm việc.
Dịch đáp án:
A. approve (động từ: phê duyệt)
B. expire (động từ: hết hạn)
C. adjust (động từ: điều chỉnh)
D. observe (động từ: quan sát)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5811, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7310, 5811, 110, 'Any apparel that includes custom images provided by the customer cannot be returned ----- it has been printed.', 'although', 'after', 'as a result', 'despite', 'B', 'Đáp án B (after) là đúng vì các lý do sau:
1. Cần một liên từ chỉ thời gian.
2. "After" là liên từ chỉ thời điểm sau khi một việc xảy ra.
3. Phù hợp với ngữ cảnh về chính sách trả hàng sau khi in.
4. Các đáp án khác không phù hợp: "although" (mặc dù), "as a result" (kết quả là), "despite" (mặc dù).
Dịch câu hỏi: Bất kỳ quần áo nào có hình ảnh tùy chỉnh do khách hàng cung cấp đều không thể trả lại sau khi đã được in.
Dịch đáp án:
A. although (liên từ: mặc dù)
B. after (liên từ: sau khi)
C. as a result (cụm từ: kết quả là)
D. despite (giới từ: mặc dù)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5812, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7311, 5812, 111, 'Thanks to sales ----- in our newest region, we have surpassed targets by fifty percent.', 'had gained', 'are gained', 'to gain', 'gains', 'D', 'Đáp án D (gains) là đúng vì các lý do sau:
1. Cần một danh từ để làm chủ ngữ.
2. "Sales gains" là cụm danh từ chỉ sự tăng trưởng doanh số.
3. Phù hợp với cấu trúc "thanks to + noun".
4. Các đáp án khác không phù hợp về cấu trúc: "had gained" (quá khứ hoàn thành), "are gained" (hiện tại bị động), "to gain" (động từ nguyên mẫu).
Dịch câu hỏi: Nhờ có sự tăng trưởng doanh số ở khu vực mới nhất của chúng tôi, chúng tôi đã vượt mục tiêu năm mươi phần trăm.
Dịch đáp án:
A. had gained (quá khứ hoàn thành: đã đạt được)
B. are gained (hiện tại bị động: được đạt được)
C. to gain (động từ nguyên mẫu: để đạt được)
D. gains (danh từ: sự tăng trưởng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5813, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7312, 5813, 112, 'The highly encrypted storage system at Grendale Inc. is ideal for a ----- document or file.', 'sensitive', 'sensation', 'sense', 'sensitivity', 'A', 'Đáp án A (sensitive) là đúng vì các lý do sau:
1. Cần một tính từ để mô tả loại tài liệu hoặc tệp tin.
2. "Sensitive" là tính từ có nghĩa "nhạy cảm, bí mật".
3. "Sensitive document" là cụm từ phổ biến chỉ tài liệu quan trọng, cần bảo mật.
4. Các đáp án khác không phù hợp: "sensation" (danh từ: cảm giác), "sense" (danh từ/động từ: ý nghĩa/cảm nhận), "sensitivity" (danh từ: độ nhạy cảm).
Dịch câu hỏi: Hệ thống lưu trữ được mã hóa cao tại Grendale Inc. lý tưởng cho tài liệu hoặc tệp tin nhạy cảm.
Dịch đáp án:
A. sensitive (tính từ: nhạy cảm)
B. sensation (danh từ: cảm giác)
C. sense (danh từ: ý nghĩa)
D. sensitivity (danh từ: độ nhạy cảm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5814, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7313, 5814, 113, 'There was severe weather over the weekend, ----- attendance at the conference was still high.', 'nor', 'so', 'but', 'for', 'C', 'Đáp án C (but) là đúng vì các lý do sau:
1. Cần một liên từ chỉ sự tương phản.
2. "But" là liên từ phối hợp diễn tả sự trái ngược.
3. Nối hai mệnh đề có ý nghĩa đối lập (thời tiết xấu/số người tham dự cao).
4. Các đáp án khác không phù hợp: "nor" (cũng không), "so" (vì vậy), "for" (vì).
Dịch câu hỏi: Thời tiết rất xấu vào cuối tuần, nhưng số người tham dự hội nghị vẫn cao.
Dịch đáp án:
A. nor (liên từ: cũng không)
B. so (liên từ: vì vậy)
C. but (liên từ: nhưng)
D. for (giới từ: cho/vì)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5815, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7314, 5815, 114, 'The posters in the movie theater''s display windows are ---- changed.', 'regular', 'regularly', 'regularizing', 'more regular', 'B', 'Đáp án B (regularly) là đúng vì các lý do sau:
1. Cần một trạng từ để bổ nghĩa cho động từ "changed".
2. "Regularly" là trạng từ chỉ tần suất thường xuyên, đều đặn.
3. Động từ "changed" ở thể bị động cần trạng từ bổ nghĩa.
4. Các đáp án khác không phù hợp: "regular" (tính từ), "regularizing" (động từ ing), "more regular" (tính từ so sánh hơn).
Dịch câu hỏi: Các áp phích trong cửa sổ trưng bày của rạp chiếu phim được thay đổi thường xuyên.
Dịch đáp án:
A. regular (tính từ: thường xuyên)
B. regularly (trạng từ: một cách thường xuyên)
C. regularizing (động từ ing: đang làm cho đều đặn)
D. more regular (tính từ so sánh hơn: thường xuyên hơn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5816, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7315, 5816, 115, 'The office staff at Warwick International are encouraged to avoid sitting for ----- periods of time.', 'fierce', 'adjusted', 'aware', 'extended', 'D', 'Đáp án D (extended) là đúng vì các lý do sau:
1. Cần một tính từ để mô tả khoảng thời gian.
2. "Extended periods" là cụm từ chỉ khoảng thời gian kéo dài.
3. Phù hợp với ngữ cảnh về sức khỏe văn phòng.
4. Các đáp án khác không phù hợp: "fierce" (dữ dội), "adjusted" (điều chỉnh), "aware" (nhận thức).
Dịch câu hỏi: Nhân viên văn phòng tại Warwick International được khuyến khích tránh ngồi trong thời gian kéo dài.
Dịch đáp án:
A. fierce (tính từ: dữ dội)
B. adjusted (tính từ: được điều chỉnh)
C. aware (tính từ: nhận thức)
D. extended (tính từ: kéo dài)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5817, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7316, 5817, 116, 'To minimize -----, please refrain from asking questions while the presentation is still underway.', 'to interrupt', 'interruptions', 'interrupt', 'interrupted', 'B', 'Đáp án B (interruptions) là đúng vì các lý do sau:
1. Cần một danh từ làm tân ngữ của động từ "minimize".
2. "Interruptions" là danh từ số nhiều chỉ sự gián đoạn.
3. Cấu trúc "minimize + danh từ" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp: "to interrupt" (động từ nguyên mẫu), "interrupt" (động từ), "interrupted" (quá khứ phân từ).
Dịch câu hỏi: Để giảm thiểu sự gián đoạn, vui lòng không đặt câu hỏi khi bài thuyết trình vẫn đang diễn ra.
Dịch đáp án:
A. to interrupt (động từ nguyên mẫu: để ngắt)
B. interruptions (danh từ số nhiều: những sự gián đoạn)
C. interrupt (động từ: ngắt)
D. interrupted (quá khứ phân từ: bị gián đoạn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5818, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7317, 5818, 117, 'Applicants for the position will not proceed in the screening process ----- their credentials have been confirmed.', 'also', 'even', 'besides', 'until', 'D', 'Đáp án D (until) là đúng vì các lý do sau:
1. Cần một liên từ chỉ thời gian.
2. "Until" là liên từ chỉ cho đến khi một điều kiện được thỏa mãn.
3. Phù hợp với ngữ cảnh về quy trình tuyển dụng.
4. Các đáp án khác không phù hợp: "also" (cũng), "even" (thậm chí), "besides" (bên cạnh đó).
Dịch câu hỏi: Các ứng viên cho vị trí sẽ không tiếp tục trong quy trình sàng lọc cho đến khi thông tin của họ được xác nhận.
Dịch đáp án:
A. also (trạng từ: cũng)
B. even (trạng từ: thậm chí)
C. besides (giới từ: bên cạnh)
D. until (liên từ: cho đến khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5819, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7318, 5819, 118, 'Due to an unexpected malfunction with the aircraft''s warning lights, passengers were not able to ---- until 8 p.M.', 'accommodate', 'appear', 'facilitate', 'board', 'D', 'Đáp án D (board) là đúng vì các lý do sau:
1. Cần một động từ chỉ hành động lên máy bay.
2. "Board" là động từ có nghĩa "lên tàu/máy bay".
3. Phù hợp với ngữ cảnh về hành khách và máy bay.
4. Các đáp án khác không phù hợp: "accommodate" (thu xếp), "appear" (xuất hiện), "facilitate" (tạo điều kiện).
Dịch câu hỏi: Do sự cố bất ngờ với đèn cảnh báo của máy bay, hành khách không thể lên máy bay cho đến 8 giờ tối.
Dịch đáp án:
A. accommodate (động từ: thu xếp)
B. appear (động từ: xuất hiện)
C. facilitate (động từ: tạo điều kiện)
D. board (động từ: lên tàu/máy bay)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5820, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7319, 5820, 119, 'The Wilson Technical Institute is recruiting faculty members who feel ----- about their subjects.', 'careful', 'passionate', 'responsible', 'welcome', 'B', 'Đáp án B (passionate) là đúng vì các lý do sau:
1. Cần một tính từ mô tả cảm xúc tích cực về môn học.
2. "Passionate" có nghĩa là "đam mê, nhiệt huyết".
3. Cấu trúc "feel passionate about" là cụm từ phổ biến chỉ sự đam mê với điều gì.
4. Các đáp án khác không phù hợp: "careful" (cẩn thận), "responsible" (có trách nhiệm), "welcome" (được chào đón).
Dịch câu hỏi: Học viện Kỹ thuật Wilson đang tuyển dụng các giảng viên có đam mê với môn học của họ.
Dịch đáp án:
A. careful (tính từ: cẩn thận)
B. passionate (tính từ: đam mê)
C. responsible (tính từ: có trách nhiệm)
D. welcome (tính từ: được chào đón)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5821, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7320, 5821, 120, 'Mr. Santiago will ---- the various options for updating the layout of the office.', 'be assessing', 'assessed', 'assessment', 'to assess', 'A', 'Đáp án A (be assessing) là đúng vì các lý do sau:
1. Cần một động từ ở thì tương lai tiếp diễn.
2. "Will be assessing" diễn tả hành động đánh giá sẽ diễn ra trong tương lai.
3. Thì tương lai tiếp diễn phù hợp với ngữ cảnh về kế hoạch trong tương lai.
4. Các đáp án khác không phù hợp: "assessed" (quá khứ), "assessment" (danh từ), "to assess" (động từ nguyên mẫu).
Dịch câu hỏi: Ông Santiago sẽ đánh giá các phương án cập nhật bố cục văn phòng.
Dịch đáp án:
A. be assessing (tương lai tiếp diễn: sẽ đánh giá)
B. assessed (quá khứ: đã đánh giá)
C. assessment (danh từ: sự đánh giá)
D. to assess (động từ nguyên mẫu: để đánh giá)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5822, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7321, 5822, 121, 'The noise levels inside the office complex are surprisingly low for being located on ----- a busy road.', 'still', 'such', 'soon', 'nearby', 'B', 'Đáp án B (such) là đúng vì các lý do sau:
1. Cần một từ xác định để nhấn mạnh tính chất của "busy road".
2. "Such + a/an + tính từ + danh từ" là cấu trúc nhấn mạnh.
3. Phù hợp với việc mô tả mức độ đông đúc của con đường.
4. Các đáp án khác không phù hợp: "still" (vẫn), "soon" (sớm), "nearby" (gần đó).
Dịch câu hỏi: Mức độ ồn bên trong khu văn phòng đáng ngạc nhiên là thấp dù được đặt trên một con đường rất đông đúc như vậy.
Dịch đáp án:
A. still (trạng từ: vẫn)
B. such (từ xác định: như vậy)
C. soon (trạng từ: sớm)
D. nearby (tính từ: gần đó)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5823, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7322, 5823, 122, 'Mechanics at the Harper Garage must ----- operate the necessary equipment without assistance.', 'influentially', 'significantly', 'enormously', 'proficiently', 'D', 'Đáp án D (proficiently) là đúng vì các lý do sau:
1. Cần một trạng từ mô tả cách thức vận hành thiết bị.
2. "Proficiently" có nghĩa là "thành thạo, chuyên nghiệp".
3. Phù hợp với yêu cầu về kỹ năng của thợ máy.
4. Các đáp án khác không phù hợp: "influentially" (có ảnh hưởng), "significantly" (đáng kể), "enormously" (to lớn).
Dịch câu hỏi: Các thợ máy tại Gara Harper phải vận hành thiết bị cần thiết một cách thành thạo mà không cần hỗ trợ.
Dịch đáp án:
A. influentially (trạng từ: có ảnh hưởng)
B. significantly (trạng từ: đáng kể)
C. enormously (trạng từ: to lớn)
D. proficiently (trạng từ: thành thạo)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5824, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7323, 5824, 123, 'On account of the installation of advanced laser equipment, the plant has tripled in ----- for its output.', 'quantity', 'economy', 'portion', 'permission', 'A', 'Đáp án A (quantity) là đúng vì các lý do sau:
1. Cần một danh từ chỉ số lượng sản xuất.
2. "Quantity" là danh từ chỉ số lượng, khối lượng.
3. Phù hợp với ngữ cảnh về sự tăng trưởng sản xuất.
4. Các đáp án khác không phù hợp: "economy" (kinh tế), "portion" (phần), "permission" (sự cho phép).
Dịch câu hỏi: Do việc lắp đặt thiết bị laser tiên tiến, nhà máy đã tăng gấp ba lần về số lượng sản xuất.
Dịch đáp án:
A. quantity (danh từ: số lượng)
B. economy (danh từ: kinh tế)
C. portion (danh từ: phần)
D. permission (danh từ: sự cho phép)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5825, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7324, 5825, 124, 'Mr. Huntley explained that it is difficult to ----- cohesive teams in today''s job climate owing to labor shortages.', 'assemble', 'surpass', 'distribute', 'succeed', 'A', 'Đáp án A (assemble) là đúng vì các lý do sau:
1. Cần một động từ nguyên mẫu có nghĩa "tập hợp, xây dựng".
2. "Assemble teams" là cụm từ phổ biến trong quản lý nhân sự.
3. Phù hợp với ngữ cảnh về việc xây dựng đội nhóm trong điều kiện thiếu nhân lực.
4. Các đáp án khác không phù hợp: "surpass" (vượt qua), "distribute" (phân phối), "succeed" (thành công).
Dịch câu hỏi: Ông Huntley giải thích rằng khó để tập hợp các đội nhóm gắn kết trong môi trường công việc hiện nay do thiếu lao động.
Dịch đáp án:
A. assemble (động từ: tập hợp, xây dựng)
B. surpass (động từ: vượt qua)
C. distribute (động từ: phân phối)
D. succeed (động từ: thành công)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5826, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7325, 5826, 125, 'Flint Vehicle Rentals charges an additional fee for insurance ---- drivers are fully covered by their own policy.', 'rather', 'if', 'unless', 'yet', 'C', 'Đáp án C (unless) là đúng vì các lý do sau:
1. Cần một liên từ điều kiện phủ định.
2. "Unless" có nghĩa là "trừ khi, nếu không".
3. Diễn tả trường hợp ngoại lệ không phải trả phí bảo hiểm bổ sung.
4. Các đáp án khác không phù hợp: "rather" (thay vào đó), "if" (nếu), "yet" (tuy nhiên).
Dịch câu hỏi: Flint Vehicle Rentals tính phí bảo hiểm bổ sung trừ khi người lái xe được bảo hiểm đầy đủ bởi chính sách của họ.
Dịch đáp án:
A. rather (trạng từ: thay vào đó)
B. if (liên từ: nếu)
C. unless (liên từ: trừ khi)
D. yet (liên từ: tuy nhiên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5827, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7326, 5827, 126, 'The state''s legislation does not allow businesses to make cash ----- to candidates.', 'contribute', 'contributions', 'contributes', 'contributed', 'B', 'Đáp án B (contributions) là đúng vì các lý do sau:
1. Cần một danh từ sau "cash" để tạo thành cụm danh từ ghép.
2. "Cash contributions" là cụm từ chỉ đóng góp bằng tiền mặt.
3. Phù hợp với ngữ cảnh về quy định pháp luật.
4. Các đáp án khác không phù hợp: "contribute" (động từ), "contributes" (động từ số ít), "contributed" (quá khứ phân từ).
Dịch câu hỏi: Luật pháp của tiểu bang không cho phép các doanh nghiệp thực hiện đóng góp bằng tiền mặt cho các ứng cử viên.
Dịch đáp án:
A. contribute (động từ: đóng góp)
B. contributions (danh từ số nhiều: những đóng góp)
C. contributes (động từ số ít: đóng góp)
D. contributed (quá khứ phân từ: đã đóng góp)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5828, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7327, 5828, 127, 'Even though Lakeland Bank''s branches have expanded across the country, most of ----- administrative offices are in the northwest.', 'this', 'whose', 'her', 'its', 'D', 'Đáp án D (its) là đúng vì các lý do sau:
1. Cần một tính từ sở hữu chỉ sở hữu của ngân hàng.
2. "Its" là tính từ sở hữu dùng cho vật/tổ chức.
3. Đề cập đến các văn phòng hành chính của ngân hàng.
4. Các đáp án khác không phù hợp: "this" (này), "whose" (của ai), "her" (của cô ấy).
Dịch câu hỏi: Mặc dù các chi nhánh của Ngân hàng Lakeland đã mở rộng trên khắp đất nước, hầu hết các văn phòng hành chính của nó đều ở phía tây bắc.
Dịch đáp án:
A. this (đại từ chỉ định: này)
B. whose (đại từ quan hệ: của ai)
C. her (tính từ sở hữu: của cô ấy)
D. its (tính từ sở hữu: của nó)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5829, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7328, 5829, 128, '----- temporarily closing the highway for repairs, planners decided to use partial closures and work in phases.', 'Wherever', 'Instead of', 'Promptly', 'Now that', 'B', 'Đáp án B (Instead of) là đúng vì các lý do sau:
1. Cần một cụm giới từ chỉ sự thay thế.
2. "Instead of + V-ing" là cấu trúc chỉ lựa chọn thay thế.
3. Diễn tả việc chọn phương án khác thay vì đóng cửa hoàn toàn.
4. Các đáp án khác không phù hợp: "Wherever" (bất cứ đâu), "Promptly" (nhanh chóng), "Now that" (bây giờ khi).
Dịch câu hỏi: Thay vì đóng cửa đường cao tốc tạm thời để sửa chữa, các nhà quy hoạch quyết định sử dụng phương án đóng cửa một phần và làm việc theo từng giai đoạn.
Dịch đáp án:
A. Wherever (trạng từ: bất cứ đâu)
B. Instead of (cụm giới từ: thay vì)
C. Promptly (trạng từ: nhanh chóng)
D. Now that (cụm liên từ: bây giờ khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5830, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7329, 5830, 129, 'Ivy Restaurant has special ingredients to replace meat --—- dairy products in its dishes to make them vegan-friendly.', 'in addition', 'yet', 'when', 'as well as', 'D', 'Đáp án D (as well as) là đúng vì các lý do sau:
1. Cần một cụm từ nối liệt kê.
2. "As well as" có nghĩa là "cũng như" dùng để thêm thông tin.
3. Nối hai loại thực phẩm cần thay thế: thịt và các sản phẩm từ sữa.
4. Các đáp án khác không phù hợp: "in addition" (thêm vào), "yet" (tuy nhiên), "when" (khi).
Dịch câu hỏi: Nhà hàng Ivy có các nguyên liệu đặc biệt để thay thế thịt cũng như các sản phẩm từ sữa trong các món ăn của họ để làm chúng phù hợp với người ăn chay.
Dịch đáp án:
A. in addition (cụm từ: thêm vào)
B. yet (liên từ: tuy nhiên)
C. when (liên từ: khi)
D. as well as (cụm từ: cũng như)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5831, 257, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7330, 5831, 130, 'Ms. Baek has focused —--- on digital art for commercial campaigns for multinational corporations.', 'surprisingly', 'frankly', 'presently', 'primarily', 'D', 'Đáp án D (primarily) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ mức độ tập trung chính yếu.
2. "Primarily" có nghĩa là "chủ yếu, chính yếu".
3. Phù hợp với ngữ cảnh về lĩnh vực chuyên môn chính.
4. Các đáp án khác không phù hợp: "surprisingly" (đáng ngạc nhiên), "frankly" (thẳng thắn), "presently" (hiện tại).
Dịch câu hỏi: Bà Baek đã tập trung chủ yếu vào nghệ thuật kỹ thuật số cho các chiến dịch thương mại của các tập đoàn đa quốc gia.
Dịch đáp án:
A. surprisingly (trạng từ: đáng ngạc nhiên)
B. frankly (trạng từ: thẳng thắn)
C. presently (trạng từ: hiện tại)
D. primarily (trạng từ: chủ yếu)');;

-- Data for 2025 Test7 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5832, 258, NULL, NULL, 'Dear Ms. Rogers,
Thank you for your interest in booking a private tour of our chocolate factory for your work colleagues. Please note that certain sections of the production line are not available to the public. 131....... . However, there is still a lot to see. We show all tour participants an 132...... video. It will teach you about the history of our company. This 133...... lasts approximately twenty minutes and can be at the beginning or the end of the tour.
Please let 134...... know what date you plan to attend and how many people will be in your group.
We hope you will have an enjoyable time!
Warmest regards,
Clayton Pemberton, Administrator
Bylee Chocolate Factory', 'Kính gửi cô Rogers,
Cảm ơn sự quan tâm của cô đến việc đặt tour tham quan riêng nhà máy chocolate của chúng tôi cho đồng nghiệp. Xin lưu ý rằng một số khu vực của dây chuyền sản xuất không mở cửa cho công chúng. 131....... . Tuy nhiên, vẫn còn nhiều thứ để xem. Chúng tôi chiếu cho tất cả người tham gia tour một video 132...... . Nó sẽ dạy bạn về lịch sử công ty chúng tôi. 133...... này kéo dài khoảng hai mươi phút và có thể ở đầu hoặc cuối tour.
Vui lòng cho 134...... biết ngày bạn dự định tham dự và số người trong nhóm của bạn.
Chúng tôi hy vọng bạn sẽ có thời gian thú vị!
Trân trọng,
Clayton Pemberton, Quản trị viên
Nhà máy Chocolate Bylee');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7331, 5832, 131, NULL, 'The ticket is valid only for the date specified.', 'In the event of a cancellation, we will send your items back.', 'We cannot change this due to food regulations.', 'Each one is led by a knowledgeable member of staff.', 'C', 'A. The ticket is valid only for the date specified (vé chỉ có giá trị cho ngày quy định)
B. In the event of a cancellation, we will send your items back (trong trường hợp hủy, chúng tôi sẽ gửi lại đồ của bạn)
C. We cannot change this due to food regulations (chúng tôi không thể thay đổi điều này do quy định về thực phẩm)
D. Each one is led by a knowledgeable member of staff (mỗi tour được dẫn dắt bởi một nhân viên có kinh nghiệm)
Đáp án đúng là C vì:
1. Ngữ cảnh: 
- Đang nói về khu vực sản xuất không mở cửa cho công chúng
- Cần giải thích lý do không thể thay đổi quy định này
2. "We cannot change this due to food regulations" phù hợp vì:
- Liên kết trực tiếp với câu trước về hạn chế tham quan
- Quy định về thực phẩm là lý do hợp lý cho nhà máy sản xuất chocolate
3. Các đáp án khác không phù hợp vì:
- A không liên quan đến việc hạn chế tham quan
- B nói về việc hủy tour, không liên quan
- D không giải thích được lý do hạn chế');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7332, 5832, 132, NULL, 'eager', 'artistic', 'informative', 'abundant', 'C', 'A. eager (háo hức - tính từ)
B. artistic (nghệ thuật - tính từ)
C. informative (cung cấp thông tin - tính từ)
D. abundant (phong phú - tính từ)
Đáp án đúng là C (informative).
Giải thích:
1. Ngữ cảnh:
- Video về lịch sử công ty
- Mục đích giáo dục, cung cấp thông tin
2. "Informative" phù hợp nhất vì:
- Mô tả video mang tính giáo dục, thông tin
- Phù hợp với câu tiếp theo "teach you about the history"
3. Các đáp án khác không phù hợp vì:
- "Eager" không dùng để mô tả video
- "Artistic" không phải mục đích chính của video lịch sử
- "Abundant" không phù hợp với video giới thiệu');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7333, 5832, 133, NULL, 'treatment', 'provision', 'trip', 'viewing', 'D', 'A. treatment (sự điều trị - danh từ)
B. provision (sự cung cấp - danh từ)
C. trip (chuyến đi - danh từ)
D. viewing (buổi xem - danh từ)
Đáp án đúng là D (viewing).
Giải thích:
1. Ngữ cảnh:
- Đề cập đến việc xem video
- Kéo dài 20 phút
2. "Viewing" phù hợp nhất vì:
- Là danh từ chỉ hoạt động xem
- Thường dùng cho việc xem video, phim
- Phù hợp với thời lượng được đề cập
3. Các đáp án khác không phù hợp vì:
- "Treatment" không liên quan đến xem video
- "Provision" không đúng ngữ cảnh
- "Trip" chỉ cả chuyến đi, không phải việc xem video');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7334, 5832, 134, NULL, 'each', 'him', 'they', 'us', 'D', 'A. each (mỗi người - đại từ)
B. him (anh ấy - đại từ)
C. they (họ - đại từ)
D. us (chúng tôi - đại từ)
Đáp án đúng là D (us).
Giải thích:
1. Ngữ cảnh:
- Thư từ công ty gửi khách
- Yêu cầu thông tin đặt tour
2. "Us" phù hợp nhất vì:
- Đại diện cho công ty/nhân viên
- Giọng văn chuyên nghiệp
- Phù hợp với thư từ công việc
3. Các đáp án khác không phù hợp vì:
- "Each" không phù hợp ngữ cảnh
- "Him" quá riêng tư, không chuyên nghiệp
- "They" không chỉ được người nhận cụ thể');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5833, 258, NULL, NULL, 'NOTICE TO TENANTS
In 135..... to numerous requests from tenants, Gresham Apartments will be renovating its on-site fitness center from March 6 to 27. 136..... we are carrying out the work, the exercise equipment and the room itself will be off limits to all tenants, so you will need to make other arrangements to maintain your fitness routine.
We 137....... any inconvenience the project may cause, and we appreciate your patience. 138....... .
The Gresham Apartments Management Team', 'THÔNG BÁO CHO NGƯỜI THUÊ
Để 135..... với nhiều yêu cầu từ người thuê, Chung cư Gresham sẽ cải tạo trung tâm thể dục tại chỗ từ ngày 6 đến 27 tháng 3. 136..... chúng tôi tiến hành công việc, thiết bị tập thể dục và chính căn phòng sẽ bị cấm đối với tất cả người thuê, vì vậy bạn sẽ cần sắp xếp cách khác để duy trì thói quen tập thể dục của mình.
Chúng tôi 137....... bất kỳ sự bất tiện nào mà dự án có thể gây ra, và chúng tôi đánh giá cao sự kiên nhẫn của bạn. 138....... .
Ban Quản lý Chung cư Gresham');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7335, 5833, 135, NULL, 'responded', 'responder', 'response', 'respond', 'C', 'A. responded (đã phản hồi - động từ quá khứ)
B. responder (người phản hồi - danh từ)
C. response (sự phản hồi - danh từ)
D. respond (phản hồi - động từ)
Đáp án đúng là C (response).
Giải thích:
1. Cấu trúc: "In + [danh từ]"
2. "Response" phù hợp nhất vì:
- Là danh từ, phù hợp sau "in"
- Chỉ sự phản hồi với yêu cầu
3. Các đáp án khác không phù hợp vì:
- "Responded" là động từ quá khứ
- "Responder" chỉ người phản hồi
- "Respond" là động từ nguyên mẫu');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7336, 5833, 136, NULL, 'Whereas', 'However', 'During', 'While', 'D', 'A. Whereas (trong khi - liên từ đối lập)
B. However (tuy nhiên - liên từ đối lập)
C. During (trong - giới từ)
D. While (trong khi - liên từ thời gian)
Đáp án đúng là D (while).
Giải thích:
1. Ngữ cảnh:
- Nói về thời gian diễn ra việc sửa chữa
- Cần liên từ chỉ thời gian diễn ra đồng thời
2. "While" phù hợp nhất vì:
- Chỉ thời gian diễn ra song song
- Dùng để nối hai sự kiện cùng lúc
3. Các đáp án khác không phù hợp vì:
- "Whereas" chỉ sự đối lập
- "However" chỉ sự tương phản
- "During" là giới từ, cần danh từ');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7337, 5833, 137, NULL, 'tolerate', 'apologize', 'regret', 'encounter', 'C', 'A. tolerate (chịu đựng - động từ)
B. apologize for (xin lỗi về - động từ)
C. regret (lấy làm tiếc về - động từ)
D. encounter (gặp phải - động từ)
Đáp án đúng là C (regret).
Giải thích:
1. Ngữ cảnh:
- Công ty muốn thể hiện sự thông cảm
- Gây bất tiện cho người thuê
2. "Regret" phù hợp nhất vì:
- Thể hiện sự tiếc nuối chuyên nghiệp
- Thường dùng trong thông báo công việc
3. Các đáp án khác không phù hợp vì:
- "Tolerate" không thể hiện sự thông cảm
- "Apologize" quá mức cho tình huống
- "Encounter" không phù hợp ngữ cảnh');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7338, 5833, 138, NULL, 'Please show your ID or apartment key at the door.', 'If you are interested in viewing a two-bedroom unit, call us anytime.', 'We are confident that the finished result will be worth the hassle.', 'Thank you for dealing with this problem promptly.', 'C', 'A. Please show your ID or apartment key at the door (Vui lòng xuất trình ID hoặc chìa khóa căn hộ tại cửa)
B. If you are interested in viewing a two-bedroom unit, call us anytime (Nếu bạn quan tâm đến việc xem căn hộ hai phòng ngủ, hãy gọi cho chúng tôi bất cứ lúc nào)
C. We are confident that the finished result will be worth the hassle (Chúng tôi tin tưởng rằng kết quả cuối cùng sẽ xứng đáng với sự phiền phức)
D. Thank you for dealing with this problem promptly (Cảm ơn bạn đã xử lý vấn đề này kịp thời)
Đáp án đúng là C vì:
1. Ngữ cảnh:
- Sau khi nói về sự bất tiện
- Cần đưa ra lời hứa/cam kết
2. Câu này phù hợp vì:
- Thể hiện kết quả tích cực
- An ủi người thuê về sự bất tiện
3. Các đáp án khác không phù hợp vì:
- A không liên quan đến việc sửa chữa
- B là thông tin về cho thuê
- D không hợp lý trong tình huống này');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5834, 258, NULL, NULL, 'To: Kahoda Naidu
From: info@vistapharmacy.com
Date: April 24
Subject: New Vista Pharmacy branch!
Dear Mr. Naidu,
The staff at Vista Pharmacy is 139...... to announce that we will open a second branch to better serve our customers. The branch will be located at 905 Victoria Street. As with our original site, the new branch will offer a comprehensive list of services beyond filling prescriptions. 140......... . The Victoria Street branch also has a drive-up window.
At the window or inside, you can stop by anytime during our business hours 141....... your medicine. As always, we can answer any questions you may have about what your 142....... prescribed to you. We look forward to serving you!
Warmest regards,
The Vista Pharmacy Team', 'Đến: Kahoda Naidu
Từ: info@vistapharmacy.com
Ngày: 24/4
Chủ đề: Chi nhánh mới của Nhà thuốc Vista!
Kính gửi ông Naidu,
Nhân viên tại Nhà thuốc Vista 139...... thông báo rằng chúng tôi sẽ mở chi nhánh thứ hai để phục vụ khách hàng tốt hơn. Chi nhánh sẽ được đặt tại 905 Đường Victoria. Giống như cơ sở gốc, chi nhánh mới sẽ cung cấp danh sách dịch vụ toàn diện ngoài việc cấp thuốc theo đơn. 140......... . Chi nhánh Đường Victoria cũng có cửa sổ drive-up.
Tại cửa sổ hoặc bên trong, bạn có thể ghé qua bất cứ lúc nào trong giờ làm việc để 141....... thuốc của bạn. Như mọi khi, chúng tôi có thể trả lời bất kỳ câu hỏi nào bạn có thể có về những gì 142....... kê đơn cho bạn. Chúng tôi mong được phục vụ bạn!
Trân trọng,
Đội ngũ Nhà thuốc Vista');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7339, 5834, 139, NULL, 'delightful', 'delighted', 'delightfully', 'delights', 'B', 'A. delightful (vui vẻ - tính từ)
B. delighted (vui mừng - tính từ)
C. delightfully (một cách vui vẻ - trạng từ)
D. delights (làm vui mừng - động từ)
Đáp án đúng là B (delighted).
Giải thích:
1. Ngữ cảnh: Email thông báo tin vui về chi nhánh mới
2. Cấu trúc: "be + [tính từ] + to + V"
3. "Delighted" phù hợp vì:
- Là tính từ chỉ cảm xúc sau "be"
- Cấu trúc "be delighted to announce" phổ biến trong thông báo chính thức
4. Các đáp án khác không phù hợp vì:
- "Delightful" không dùng trong cấu trúc này
- "Delightfully" là trạng từ, không theo sau "be"
- "Delights" là động từ, sai cấu trúc');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7340, 5834, 140, NULL, 'Many of them have symptoms that may be uncomfortable.', 'These include collecting unwanted medication for safe disposal.', 'We can hold it for you for up to ten business days.', 'The renovations will make the counter more accessible.', 'B', 'A. Many of them have symptoms that may be uncomfortable (Nhiều người trong số họ có triệu chứng có thể khó chịu)
B. These include collecting unwanted medication for safe disposal (Những dịch vụ này bao gồm thu gom thuốc không mong muốn để xử lý an toàn)
C. We can hold it for you for up to ten business days (Chúng tôi có thể giữ nó cho bạn đến mười ngày làm việc)
D. The renovations will make the counter more accessible (Việc cải tạo sẽ làm cho quầy dễ tiếp cận hơn)
Đáp án đúng là B vì:
1. Ngữ cảnh: Liệt kê dịch vụ bổ sung ngoài cấp thuốc
2. "These include..." phù hợp vì:
- Trực tiếp liên kết với "comprehensive list of services"
- Đưa ra ví dụ cụ thể về dịch vụ
3. Các đáp án khác không liên quan đến chủ đề dịch vụ đang đề cập');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7341, 5834, 141, NULL, 'to collect', 'being collected', 'collected', 'collecting', 'A', 'A. to collect (để lấy - động từ nguyên mẫu)
B. being collected (đang được lấy - bị động)
C. collected (được lấy - quá khứ phân từ)
D. collecting (đang lấy - V-ing)
Đáp án đúng là A (to collect).
Giải thích:
1. Cấu trúc: "stop by + to + V" (ghé qua để làm gì)
2. "To collect" phù hợp vì:
- Chỉ mục đích của việc ghé qua
- Dùng động từ nguyên mẫu sau "to"
3. Các đáp án khác sai vì không phù hợp cấu trúc ngữ pháp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7342, 5834, 142, NULL, 'supervisor', 'patient', 'colleague', 'physician', 'D', 'A. supervisor (người giám sát - danh từ)
B. patient (bệnh nhân - danh từ)
C. colleague (đồng nghiệp - danh từ)
D. physician (bác sĩ - danh từ)
Đáp án đúng là D (physician).
Giải thích:
1. Ngữ cảnh: Nói về người kê đơn thuốc
2. "Physician" phù hợp vì:
- Là người có thẩm quyền kê đơn thuốc
- Phù hợp với bối cảnh nhà thuốc
3. Các đáp án khác không phù hợp vì không có quyền kê đơn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5835, 258, NULL, NULL, 'I recently found some old photographs that belonged to my grandmother, and I wanted to get them restored as 143........ as possible to the original shots. A colleague of mine suggested Clover Photos in the Greenwood neighborhood. Carlene, the shop''s owner, was helpful in explaining my options and assisting me with choosing the level of service that was right for me. She completed the restoration and framing in just three days 144........ it is the busy season. The pictures look fantastic. 145........ .
Carlene is highly experienced. She is a 146........ photo editor. I cannot recommend her highly enough.
Ida Briggs, Bristol', 'Gần đây tôi đã tìm thấy một số bức ảnh cũ thuộc về bà tôi, và tôi muốn chúng được khôi phục lại thành 143....... càng tốt so với những bức ảnh gốc. Một đồng nghiệp của tôi đã đề xuất Clover Photos trong khu phố Greenwood. Carlene, chủ cửa hàng, rất hữu ích trong việc giải thích các lựa chọn của tôi và hỗ trợ tôi lựa chọn mức độ dịch vụ phù hợp với tôi. Cô ấy đã hoàn thành việc phục hồi và đóng khung chỉ trong ba ngày 144........ đó là mùa bận rộn. Những bức ảnh trông thật tuyệt vời. 145........ .
Carlene có nhiều kinh nghiệm. Cô ấy là một biên tập viên ảnh 146........ Tôi không thể giới thiệu cô ấy đủ.
Ida Briggs, Bristol');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7343, 5835, 143, NULL, 'closest', 'closely', 'closer', 'closeness', 'B', 'A. closest (gần nhất - tính từ so sánh nhất)
B. closely (gần gũi - trạng từ)
C. closer (gần hơn - tính từ so sánh hơn)
D. closeness (sự gần gũi - danh từ)
Đáp án đúng là B (closely).
Giải thích:
1. Cấu trúc: "as + [trạng từ] + as possible"
2. "Closely" phù hợp vì:
- Là trạng từ, phù hợp cấu trúc so sánh
- Diễn tả mức độ giống với ảnh gốc
3. Các đáp án khác sai về ngữ pháp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7344, 5835, 144, NULL, 'not only', 'such as', 'so that', 'even though', 'D', 'A. not only (không chỉ - cụm liên từ)
B. such as (chẳng hạn như - cụm giới từ)
C. so that (để mà - cụm liên từ)
D. even though (mặc dù - cụm liên từ)
Đáp án đúng là D (even though).
Giải thích:
1. Ngữ cảnh: Tương phản giữa mùa bận rộn và thời gian hoàn thành nhanh
2. "Even though" phù hợp vì:
- Nối hai ý đối lập
- Nhấn mạnh thành tích phục vụ
3. Các đáp án khác không thể hiện được sự đối lập');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7345, 5835, 145, NULL, 'At least the delivery times are reliable.', 'I am an amateur photographer myself.', 'She used to own a gallery.', 'The frame''s quality is amazing too.', 'D', 'A. At least the delivery times are reliable (Ít nhất thời gian giao hàng đáng tin cậy)
B. I am an amateur photographer myself (Tôi là nhiếp ảnh gia nghiệp dư)
C. She used to own a gallery (Cô ấy từng sở hữu một phòng trưng bày)
D. The frame''s quality is amazing too (Chất lượng khung cũng tuyệt vời)
Đáp án đúng là D vì:
1. Liên kết với câu trước về chất lượng ảnh
2. Bổ sung thông tin về sản phẩm
3. Các đáp án khác không liên quan trực tiếp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7346, 5835, 146, NULL, 'talented', 'best', 'fortunate', 'voluntary', 'A', 'A. talented (tài năng - tính từ)
B. best (giỏi nhất - tính từ)
C. fortunate (may mắn - tính từ)
D. voluntary (tự nguyện - tính từ)
Đáp án đúng là A (talented).
Giải thích:
1. Ngữ cảnh: Đánh giá năng lực chuyên môn
2. "Talented" phù hợp vì:
- Mô tả kỹ năng và tài năng
- Phù hợp với nghề biên tập ảnh
3. Các đáp án khác không phù hợp để đánh giá chuyên môn');;

-- Data for 2025 Test7 Part 7
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5836, 259, NULL, NULL, 'Shine Education is seeking friendly and enthusiastic instructors to teach multilingual students aged 5 to 11 on our platform. We have developed a fun and interesting curriculum, so all of the lesson planning has been done for you. And as you will be exclusively using English, communicating in a foreign language is unnecessary. All you need is a positive attitude, a laptop, and a sound and stable Internet connection.
Position highlights:
No work on holidays, and bonus pay on weekends.
Ultimate flexibility-open classes only when you want to.
Fast payment-get paid by bank transfer every week.
Find out more at shineeduwow.com/apply.', 'Shine Education đang tìm kiếm các giảng viên thân thiện và nhiệt tình để dạy học sinh đa ngôn ngữ từ 5 đến 11 tuổi trên nền tảng của chúng tôi. Chúng tôi đã phát triển một chương trình giảng dạy vui nhộn và thú vị, vì vậy tất cả các kế hoạch bài học đã được thực hiện cho bạn. Và vì bạn sẽ chỉ sử dụng tiếng Anh, giao tiếp bằng ngoại ngữ là không cần thiết. Tất cả những gì bạn cần là một thái độ tích cực, một máy tính xách tay và kết nối Internet âm thanh và ổn định.
Điểm nổi bật của vị trí:
Không làm việc vào ngày lễ và trả tiền thưởng vào cuối tuần.
Tính linh hoạt tối ưu-chỉ mở các lớp học khi bạn muốn.
Thanh toán nhanh-được thanh toán bằng chuyển khoản ngân hàng mỗi tuần.
Tìm hiểu thêm tại shineeduwow.com/apply.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7347, 5836, 147, 'What requirement is expected of all applicants?', 'A reliable method for getting online', 'Graduation from a four-year university', 'Previous experience in education', 'Samples of lesson plans they have developed', 'A', 'Đáp án đúng là A.
Giải thích:
Trong thông báo tuyển dụng có đoạn "All you need is a positive attitude, a laptop, and a sound and stable Internet connection" (Tất cả những gì bạn cần là thái độ tích cực, một laptop và kết nối Internet ổn định). Điều này chỉ ra rằng một phương thức kết nối online đáng tin cậy là yêu cầu bắt buộc.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Yêu cầu nào được mong đợi từ tất cả ứng viên?
A. Một phương thức kết nối online đáng tin cậy (đáp án đúng)
B. Tốt nghiệp đại học 4 năm
C. Kinh nghiệm giảng dạy trước đây
D. Các mẫu giáo án đã phát triển');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7348, 5836, 148, 'What is true about the position?', 'It includes working with children and adults', 'It is only suitable for multilingual people', 'It allows workers to set their schedule', 'It involves teaching on weekends and holidays', 'C', 'Đáp án đúng là C.
Giải thích:
Thông báo tuyển dụng có đề cập "Ultimate flexibility-open classes only when you want to" (Tính linh hoạt tối đa - chỉ mở lớp khi bạn muốn). Điều này cho thấy người làm việc có thể tự sắp xếp lịch làm việc của mình.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì đúng về vị trí công việc này?
A. Bao gồm làm việc với cả trẻ em và người lớn
B. Chỉ phù hợp với người đa ngôn ngữ
C. Cho phép người làm việc tự sắp xếp lịch làm việc (đáp án đúng)
D. Liên quan đến việc dạy vào cuối tuần và ngày lễ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5837, 259, NULL, NULL, 'http://www.kennonhotel.co.uk
An Announcement from Rosalie Willis, CEO of Kennon Hotel
Helpline: 1-800-555-9056
Many of our valued customers have been affected by the computer glitch that caused rooms at our hotel to be double-booked. We assure you that we are doing everything we can to minimize the negative effects of the situation. Customers whom we are not able to accommodate at our site will be booked at nearby hotels in rooms of equivalent or greater size and quality, still paying only the originally quoted rate. In addition, customers usually must cancel at least 48 hours before their scheduled check-in time to avoid being charged for the first night''s stay. For the next three weeks, this will be changed to 24 hours.', 'http://www.kennonhotel.co.uk
Thông báo từ Rosalie Willis, Giám đốc điều hành Khách sạn Kennon
Đường dây nóng: 1-800-555-9056
Nhiều khách hàng thân thiết của chúng tôi đã bị ảnh hưởng bởi sự cố máy tính khiến các phòng tại khách sạn của chúng tôi bị đặt trùng. Chúng tôi đảm bảo rằng chúng tôi đang làm mọi thứ có thể để giảm thiểu tác động tiêu cực của tình huống này. Những khách hàng mà chúng tôi không thể phục vụ tại cơ sở của mình sẽ được đặt phòng tại các khách sạn lân cận với phòng có kích thước và chất lượng tương đương hoặc tốt hơn, vẫn chỉ phải trả mức giá đã báo ban đầu. Ngoài ra, thông thường khách hàng phải hủy ít nhất 48 giờ trước thời gian nhận phòng dự kiến để tránh bị tính phí đêm đầu tiên. Trong ba tuần tới, thời gian này sẽ được thay đổi thành 24 giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7349, 5837, 149, 'What is the purpose of the announcement?', 'To explain measures to resolve a problem', 'To introduce a newly opened hotel', 'To promote discounted rates to loyal customers', 'To encourage customers to use a reservation system', 'A', 'Đáp án đúng là A.
Giải thích:
Thông báo đề cập đến một sự cố máy tính khiến phòng bị đặt trùng và giải thích các biện pháp khắc phục như: đặt phòng cho khách ở các khách sạn lân cận với chất lượng tương đương hoặc tốt hơn, giữ nguyên giá ban đầu, và thay đổi thời hạn hủy phòng từ 48 giờ xuống 24 giờ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mục đích của thông báo là gì?
A. Giải thích các biện pháp để giải quyết vấn đề (đáp án đúng)
B. Giới thiệu một khách sạn mới mở
C. Quảng cáo giá ưu đãi cho khách hàng thân thiết
D. Khuyến khích khách hàng sử dụng hệ thống đặt phòng');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7350, 5837, 150, 'According to Ms. Willis, what has the hotel changed temporarily?', 'The fee for staying more than one night', 'The deadline for canceling at no charge', 'The hours of operation for a helpline', 'The wait time for checking in to the hotel', 'B', 'Đáp án đúng là B.
Giải thích:
Theo thông báo, "customers usually must cancel at least 48 hours before their scheduled check-in time to avoid being charged for the first night''s stay. For the next three weeks, this will be changed to 24 hours" (thông thường khách hàng phải hủy ít nhất 48 giờ trước giờ nhận phòng để tránh bị tính phí đêm đầu tiên. Trong ba tuần tới, thời gian này sẽ được thay đổi thành 24 giờ).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo bà Willis, khách sạn đã thay đổi tạm thời điều gì?
A. Phí cho việc ở nhiều hơn một đêm
B. Thời hạn hủy phòng không mất phí (đáp án đúng)
C. Giờ hoạt động của đường dây nóng
D. Thời gian chờ để nhận phòng khách sạn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5838, 259, NULL, NULL, 'SOIL CONTAMINATION REPORT                          April 5
Client: Gould Manufacturing
Testing Performed By: Soil-Check Solutions
Testing Dates: March 3, May 5, July 2, September 5
Process: Samples were collected from various points at Site 1 (Lancaster), Site 2 (Canton), and Site 3 (Brockway) at a depth of 6 cm and 10 cm. The soil was tested for contaminants, and the levels were compared to assess changes over time. Following the initial test, micro-organisms were introduced at all sites.
Preliminary Findings and Recommended Actions: Contamination levels at Site 1 dropped significantly. No further action is needed. At Site 2, a soil stabilization formula should be injected into the ground. This will dry into a hardened solid, which can then be removed by specialized equipment.
Micro-organisms should be reapplied. At Site 3, the grass and shrubs should be pulled from the soil, and micro-organisms should be reapplied.', 'BÁO CÁO Ô NHIỄM ĐẤT                          Ngày 5 tháng 4
Khách hàng: Gould Manufacturing
Kiểm tra được thực hiện bởi: Soil-Check Solutions
Ngày kiểm tra: 3 tháng 3, 5 tháng 5, 2 tháng 7, 5 tháng 9
Quy trình: Các mẫu được thu thập từ nhiều điểm tại Địa điểm 1 (Lancaster), Địa điểm 2 (Canton), và Địa điểm 3 (Brockway) ở độ sâu 6 cm và 10 cm. Đất được kiểm tra các chất gây ô nhiễm, và các mức độ được so sánh để đánh giá sự thay đổi theo thời gian. Sau lần kiểm tra ban đầu, vi sinh vật đã được đưa vào tất cả các địa điểm.
Kết quả sơ bộ và Hành động đề xuất: Mức độ ô nhiễm tại Địa điểm 1 giảm đáng kể. Không cần thêm hành động nào. Tại Địa điểm 2, một công thức ổn định đất nên được bơm vào đất. Điều này sẽ khô thành chất rắn cứng, sau đó có thể được loại bỏ bằng thiết bị chuyên dụng.
Vi sinh vật nên được áp dụng lại. Tại Địa điểm 3, cỏ và cây bụi nên được kéo ra khỏi đất, và vi sinh vật nên được áp dụng lại.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7351, 5838, 151, 'What is true about the soil testing?', 'It fulfilled a requirement set by the government', 'It was carried out by full-time Gould Manufacturing staff', 'It mainly focused on the Canton site', 'It had gaps between the collection days', 'D', 'Đáp án đúng là D.
Giải thích:
Báo cáo cho thấy các ngày lấy mẫu là March 3, May 5, July 2, September 5, có khoảng cách thời gian giữa các ngày thu thập mẫu.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì đúng về việc kiểm tra đất?
A. Nó đáp ứng yêu cầu của chính phủ
B. Nó được thực hiện bởi nhân viên toàn thời gian của Gould Manufacturing
C. Nó chủ yếu tập trung vào địa điểm Canton
D. Nó có khoảng cách giữa các ngày thu thập mẫu (đáp án đúng)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7352, 5838, 152, 'What action is recommended for Gould Manufacturing?', 'Taking soil from a depth of more than ten centimeters', 'Injecting a formula into the soil at Lancaster', 'Ceasing micro-organism treatment at Canton', 'Removing plants at Brockway', 'D', 'Đáp án đúng là D.
Giải thích:
Theo báo cáo, tại Địa điểm 3 (Brockway), "the grass and shrubs should be pulled from the soil" (cỏ và cây bụi nên được kéo ra khỏi đất).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Hành động nào được đề xuất cho Gould Manufacturing?
A. Lấy đất từ độ sâu hơn mười centimeter
B. Bơm một công thức vào đất tại Lancaster
C. Ngừng xử lý vi sinh vật tại Canton
D. Loại bỏ thực vật tại Brockway (đáp án đúng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5839, 259, NULL, NULL, 'Mason Nguyen [10:27 A.M.]
Hi, Eva. l''ve just e-mailed you the presentation slides for our meeting with Lyndon Enterprises. It outlines how we can help them manage regulations when selling their goods abroad. Did you receive it?
Eva Salazar [10:28 A.M.]
I''m just opening it now. Is this the finished version?
Mason Nguyen [10:29 A.M.]
No. I was wondering if you could put in some statistics on slides 4
through 6.
Eva Salazar [10:30 A.M.]
Sure thing. Do you need me to prepare anything else for it?
Mason Nguyen [10:31 A.M.]
Maybe we should include information about the steps for port registration, as Lyndon Enterprises plans to bring goods into the country as well.
Eva Salazar [10:33 A.M.]
That might be a good idea. Let me check what you have and get back to you.', 'Mason Nguyen [10:27 sáng]
Chào Eva. Tôi vừa gửi email cho bạn các slide thuyết trình cho cuộc họp với Lyndon Enterprises. Nó phác thảo cách chúng ta có thể giúp họ quản lý các quy định khi bán hàng ở nước ngoài. Bạn đã nhận được chưa?
Eva Salazar [10:28 sáng]
Tôi đang mở nó ngay bây giờ. Đây là phiên bản hoàn chỉnh phải không?
Mason Nguyen [10:29 sáng]
Không. Tôi tự hỏi liệu bạn có thể thêm một số thống kê vào các slide 4 đến 6.
Eva Salazar [10:30 sáng]
Đương nhiên rồi. Bạn có cần tôi chuẩn bị thêm gì cho nó không?
Mason Nguyen [10:31 sáng]
Có lẽ chúng ta nên thêm thông tin về các bước đăng ký cảng, vì Lyndon Enterprises cũng có kế hoạch đưa hàng hóa vào nước này.
Eva Salazar [10:33 sáng]
Đó có thể là một ý kiến hay. Để tôi kiểm tra những gì bạn có và phản hồi lại cho bạn.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7353, 5839, 153, 'At 10:30 A.M., what does Ms. Salazar most likely mean when she writes, "Sure thing"?', 'She is willing to contact Lyndon Enterprises'' staff members', 'She can add numerical information to a presentation file', 'She is happy to attend a meeting in Mr. Nguyen''s place', 'She plans to stay at work later than usual today', 'B', 'Đáp án đúng là B.
Giải thích:
Trong đoạn hội thoại, trước đó Mr. Nguyen đã yêu cầu "I was wondering if you could put in some statistics on slides 4 through 6" (Tôi tự hỏi liệu bạn có thể thêm một số thống kê vào các slide 4 đến 6 không). Khi Ms. Salazar trả lời "Sure thing", cô ấy đang đồng ý với yêu cầu thêm thông tin số liệu vào file thuyết trình.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 10:30 sáng, Ms. Salazar có ý gì khi viết "Sure thing"?
A. Cô ấy sẵn sàng liên hệ với nhân viên của Lyndon Enterprises
B. Cô ấy có thể thêm thông tin số liệu vào file thuyết trình (đáp án đúng)
C. Cô ấy vui lòng tham dự cuộc họp thay cho Mr. Nguyen
D. Cô ấy dự định ở lại làm việc muộn hơn bình thường hôm nay');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7354, 5839, 154, 'What kind of work do the writers most likely do?', 'Computer programming', 'Safety inspections', 'Market analysis', 'Import-export services', 'D', 'Đáp án đúng là D.
Giải thích:
Trong cuộc trò chuyện, họ thảo luận về việc giúp Lyndon Enterprises "manage regulations when selling their goods abroad" (quản lý các quy định khi bán hàng ở nước ngoài) và "port registration" (đăng ký cảng) để đưa hàng hóa vào nước này. Những nội dung này cho thấy họ làm việc trong lĩnh vực dịch vụ xuất nhập khẩu.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Những người viết có khả năng làm công việc gì?
A. Lập trình máy tính
B. Kiểm tra an toàn
C. Phân tích thị trường
D. Dịch vụ xuất nhập khẩu (đáp án đúng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5840, 259, NULL, NULL, 'E-Mail message
To: ztaheri@larabeemail.com
From: parksoomin@civilengconf.com
Date: August 3
Subject: Civil Engineering Conference
Dear Mr. Taheri,
It was wonderful to speak with you today, and I am pleased that you have accepted our invitation to attend the 50th Annual Civil Engineering Conference, which takes place from November 5 to 8 in Atlanta. We were greatly disappointed that you were unable to share your expertise in your presentation last year, as the events on the final day of the conference were called off due to severe weather. Our attendance is up by nearly 100 compared to last year, so we are using the largest room, Navarro Hall. It has a capacity of 250, and we expect it to be full. We have you booked for the morning of the second day.
As you make your preparations, please keep in mind that the talk should be a maximum of 120 minutes. You will have standard presentation equipment at your disposal, but if you require anything else, please let me know.
Best,
Soomin Park
Event Coordinator, Civil Engineering Conference', 'Email
Đến: ztaheri@larabeemail.com
Từ: parksoomin@civilengconf.com
Ngày: 3 tháng 8
Chủ đề: Hội nghị Kỹ thuật Dân dụng
Kính gửi ông Taheri,
Thật tuyệt khi được nói chuyện với ông hôm nay, và tôi rất vui khi ông đã chấp nhận lời mời tham dự Hội nghị Kỹ thuật Dân dụng Thường niên lần thứ 50, diễn ra từ ngày 5 đến 8 tháng 11 tại Atlanta. Chúng tôi rất thất vọng khi ông đã không thể chia sẻ chuyên môn trong bài thuyết trình năm ngoái, vì các sự kiện vào ngày cuối cùng của hội nghị đã bị hủy do thời tiết xấu. Số người tham dự của chúng tôi tăng gần 100 người so với năm ngoái, vì vậy chúng tôi sử dụng phòng lớn nhất, Hội trường Navarro. Nó có sức chứa 250 người, và chúng tôi dự kiến sẽ kín chỗ. Chúng tôi đã đặt cho ông vào buổi sáng của ngày thứ hai.
Khi chuẩn bị, xin hãy lưu ý rằng bài nói chuyện nên tối đa 120 phút. Ông sẽ có các thiết bị thuyết trình tiêu chuẩn để sử dụng, nhưng nếu cần thêm bất cứ thứ gì khác, xin hãy cho tôi biết.
Trân trọng,
Soomin Park
Điều phối viên Sự kiện, Hội nghị Kỹ thuật Dân dụng');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7355, 5840, 155, 'What is suggested about Mr. Taheri''s previous presentation for the conference?', 'It suffered from some technical malfunctions', 'It was canceled by event organizers', 'It was given in Navarro Hall', 'It received good reviews from participants', 'B', 'Đáp án đúng là B.
Giải thích:
Trong email có đoạn "you were unable to share your expertise in your presentation last year, as the events on the final day of the conference were called off due to severe weather" (bạn đã không thể chia sẻ chuyên môn trong bài thuyết trình năm ngoái, vì các sự kiện vào ngày cuối cùng của hội nghị đã bị hủy do thời tiết xấu).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về bài thuyết trình trước đây của ông Taheri tại hội nghị?
A. Nó gặp một số trục trặc kỹ thuật
B. Nó đã bị hủy bởi ban tổ chức sự kiện (đáp án đúng)
C. Nó được trình bày tại Hội trường Navarro
D. Nó nhận được đánh giá tốt từ người tham dự');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7356, 5840, 156, 'Approximately how many participants are expected at the event?', '50', '100', '120', '250', 'D', 'Đáp án đúng là D.
Giải thích:
Trong email có đoạn "It has a capacity of 250, and we expect it to be full" (Nó có sức chứa 250 người, và chúng tôi dự kiến sẽ kín chỗ). Điều này cho thấy số người tham dự dự kiến là khoảng 250 người.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Dự kiến có bao nhiêu người tham dự sự kiện?
A. 50
B. 100
C. 120
D. 250 (đáp án đúng)');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7357, 5840, 157, 'For when has a time slot been reserved for Mr. Taheri''s talk?', 'November 5', 'November 6', 'November 7', 'November 8', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email, hội nghị diễn ra từ ngày 5-8 tháng 11, và "We have you booked for the morning of the second day" (Chúng tôi đã đặt cho ông vào buổi sáng của ngày thứ hai). Ngày thứ hai của hội nghị là ngày 6 tháng 11.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Thời gian nào đã được đặt cho bài nói chuyện của ông Taheri?
A. Ngày 5 tháng 11
B. Ngày 6 tháng 11 (đáp án đúng)
C. Ngày 7 tháng 11
D. Ngày 8 tháng 11');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5841, 259, NULL, NULL, 'New Chapter for City Hall
(Jan. 20)—ETB has won the bid for the expansion project at City Hall, which will add 90,000 square feet of space. — [1] —. The work will be covered partially by the general budget, with the remaining funding coming from federal grants. — [2] —. ETB has invited a local community club, the Hampton Historic Society, to advise on the project due to the historical significance of City Hall. - [31 —. The additional wing will house a much-needed larger conference room and twelve offices. - [4] -. Visit the ETB Web site for further details.', 'Chương mới cho Tòa thị chính
(Ngày 20 tháng 1)—ETB đã thắng thầu dự án mở rộng tại Tòa thị chính, dự án sẽ thêm 90,000 feet vuông không gian. — [1] —. Công việc sẽ được tài trợ một phần từ ngân sách chung, phần còn lại đến từ các khoản tài trợ liên bang. — [2] —. ETB đã mời một câu lạc bộ cộng đồng địa phương, Hội Lịch sử Hampton, để tư vấn về dự án do tầm quan trọng về mặt lịch sử của Tòa thị chính. - [3] -. Khu vực bổ sung sẽ có một phòng họp lớn hơn rất cần thiết và mười hai văn phòng. - [4] -. Truy cập trang web của ETB để biết thêm chi tiết.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7358, 5841, 158, 'What kind of business most likely is ETB?', 'A financial institution', 'A community club', 'A construction company', 'A real estate firm', 'C', 'Đáp án đúng là C.
Giải thích:
Theo bài báo, ETB đã thắng thầu dự án mở rộng Tòa thị chính ("ETB has won the bid for the expansion project at City Hall") và sẽ xây dựng thêm không gian 90,000 feet vuông. Việc tham gia đấu thầu và thực hiện dự án xây dựng cho thấy ETB là một công ty xây dựng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: ETB có khả năng là loại doanh nghiệp gì?
A. Một tổ chức tài chính
B. Một câu lạc bộ cộng đồng
C. Một công ty xây dựng (đáp án đúng)
D. Một công ty bất động sản');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7359, 5841, 159, 'What is suggested about City Hall?', 'Scheduled changes to it will probably be postponed', 'It currently cannot accommodate large meetings', 'An individual has made a financial donation to it', 'It has ninety thousand square feet of space in total', 'B', 'Đáp án đúng là B.
Giải thích:
Bài báo đề cập "The additional wing will house a much-needed larger conference room" (Khu vực bổ sung sẽ có một phòng họp lớn hơn rất cần thiết). Cụm từ "much-needed" cho thấy hiện tại Tòa thị chính không thể đáp ứng các cuộc họp lớn.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về Tòa thị chính?
A. Những thay đổi đã lên lịch có thể sẽ bị hoãn lại
B. Hiện tại nó không thể đáp ứng các cuộc họp lớn (đáp án đúng)
C. Một cá nhân đã tài trợ tài chính cho nó
D. Nó có tổng cộng chín mươi nghìn feet vuông không gian');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7360, 5841, 160, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "Some will be used by the newly formed Consumer Affairs Division."', '[1]', '[2]', '[3]', '[4]', 'D', 'Đáp án đúng là D.
Giải thích:
Câu "Some will be used by the newly formed Consumer Affairs Division" (Một số sẽ được sử dụng bởi Phòng Quan hệ Người tiêu dùng mới thành lập) phù hợp nhất ở vị trí [4] vì:
1. Nó liên quan trực tiếp đến câu trước đó nói về "twelve offices" (mười hai văn phòng)
2. Từ "Some" ở đây ám chỉ một số trong số các văn phòng đó
3. Vị trí này tạo ra sự liên kết logic giữa việc có thêm văn phòng và mục đích sử dụng của chúng

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Câu "Một số sẽ được sử dụng bởi Phòng Quan hệ Người tiêu dùng mới thành lập" phù hợp nhất ở vị trí nào trong số các vị trí được đánh dấu [1], [2], [3], và [4]?
A. [1]
B. [2]
C. [3]
D. [4] (đáp án đúng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5842, 259, NULL, NULL, 'UTICA INC.
Thank you for your patronage!
We hope you will enjoy all the amazing features that Utica''s TX-8 model has to offer. This is one of the most fuel-efficient vehicles on the market, and it comes equipped with the latest technological advances. The automatic emergency braking system helps to improve safety for both you and your passengers, and the adaptive cruise control function monitors your distance from other objects and makes adjustments accordingly.
For further assistance from the Utica Inc. team, why not download our new smartphone application? You can chat with customer service staff or technicians 24 hours a day, 7 days a week. The app has a map that shows the nearest gas stations along with up-to-the-minute pricing information. It even allows you to check your fuel level and get an estimate of its range.
At Utica Inc., we don''t just follow the trend  we lead with our own style and approach.', 'UTICA INC.
Cảm ơn bạn đã ủng hộ! 
Chúng tôi hy vọng bạn sẽ thích tất cả các tính năng tuyệt vời mà mẫu TX-8 của Utica mang lại. Đây là một trong những phương tiện tiết kiệm nhiên liệu nhất trên thị trường và nó được trang bị những tiến bộ công nghệ mới nhất. Hệ thống phanh khẩn cấp tự động giúp cải thiện sự an toàn cho cả bạn và hành khách của bạn, và chức năng kiểm soát hành trình thích ứng giám sát khoảng cách của bạn với các đối tượng khác và thực hiện các điều chỉnh cho phù hợp.
Để được hỗ trợ thêm từ nhóm Utica Inc., tại sao không tải xuống ứng dụng điện thoại thông minh mới của chúng tôi? Bạn có thể trò chuyện với nhân viên dịch vụ khách hàng hoặc kỹ thuật viên 24 giờ một ngày, 7 ngày một tuần. Ứng dụng có bản đồ hiển thị các trạm xăng gần nhất cùng với thông tin giá cập nhật từng phút. Nó thậm chí còn cho phép bạn kiểm tra mức nhiên liệu của mình và ước tính phạm vi của nó.
Tại Utica Inc., chúng tôi không chỉ đi theo xu hướng mà chúng tôi dẫn đầu với phong cách và cách tiếp cận của riêng mình.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7361, 5842, 161, 'In what field does Utica Inc. operate?', 'Building security', 'Automotive manufacturing', 'Software distribution', 'Fuel production', 'B', 'Đáp án đúng là B.
Giải thích:
Văn bản đề cập đến "TX-8 model", "fuel-efficient vehicles", "automatic emergency braking system", "passengers", và "adaptive cruise control" - đều là các thuật ngữ liên quan đến sản xuất ô tô.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Utica Inc. hoạt động trong lĩnh vực nào?
A. An ninh tòa nhà
B. Sản xuất ô tô (đáp án đúng)
C. Phân phối phần mềm
D. Sản xuất nhiên liệu');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5843, 259, NULL, NULL, 'Thank you for your patronage!
We hope you will enjoy all the amazing features that Utica''s TX-8 model has to offer. This is one of the most fuel-efficient vehicles on the market, and it comes equipped with the latest technological advances. The automatic emergency braking system helps to improve safety for both you and your passengers, and the adaptive cruise control function monitors your distance from other objects and makes adjustments accordingly.
For further assistance from the Utica Inc. team, why not download our new smartphone application? You can chat with customer service staff or technicians 24 hours a day, 7 days a week. The app has a map that shows the nearest gas stations along with up-to-the-minute pricing information. It even allows you to check your fuel level and get an estimate of its range.
At Utica Inc., we don''t just follow the trend  we lead with our own style and approach.', 'Cảm ơn vì sự ủng hộ của bạn!
Chúng tôi hy vọng bạn sẽ thích thú với tất cả các tính năng tuyệt vời mà mẫu TX-8 của Utica mang lại. Đây là một trong những phương tiện tiết kiệm nhiên liệu nhất trên thị trường và được trang bị những tiến bộ công nghệ mới nhất. Hệ thống phanh khẩn cấp tự động giúp cải thiện an toàn cho cả bạn và hành khách, và chức năng kiểm soát hành trình thích ứng theo dõi khoảng cách của bạn với các vật thể khác và điều chỉnh phù hợp.
Để được hỗ trợ thêm từ đội ngũ Utica Inc., tại sao không tải ứng dụng điện thoại thông minh mới của chúng tôi? Bạn có thể trò chuyện với nhân viên dịch vụ khách hàng hoặc kỹ thuật viên 24 giờ một ngày, 7 ngày một tuần. Ứng dụng có bản đồ hiển thị các trạm xăng gần nhất cùng với thông tin giá cập nhật theo thời gian thực. Nó thậm chí còn cho phép bạn kiểm tra mức nhiên liệu và ước tính phạm vi của nó.
Tại Utica Inc., chúng tôi không chỉ theo xu hướng  chúng tôi dẫn đầu với phong cách và cách tiếp cận riêng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7362, 5843, 161, 'In what field does Utica Inc. operate?', 'Building security', 'Automotive manufacturing', 'Software distribution', 'Fuel production', 'B', 'Đáp án đúng là B.
Giải thích:
Bài văn có nhiều chi tiết chứng minh Utica Inc. hoạt động trong lĩnh vực sản xuất ô tô:
- Đề cập đến "TX-8 model" và các tính năng của xe như "fuel-efficient vehicles" (xe tiết kiệm nhiên liệu)
- Có các tính năng an toàn như "automatic emergency braking system" (hệ thống phanh khẩn cấp tự động)
- Có "adaptive cruise control" (kiểm soát hành trình thích ứng)

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Utica Inc. hoạt động trong lĩnh vực nào?
A. An ninh tòa nhà
B. Sản xuất ô tô
C. Phân phối phần mềm
D. Sản xuất nhiên liệu');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7363, 5843, 162, 'What does the new Utica Inc. smartphone application allow users to do?', 'Check for recalls and safety-related reports', 'Learn about special offers before other customers', 'Track product shipments in real time', 'Compare prices at different businesses', 'D', 'Đáp án đúng là D.
Giải thích:
Theo đoạn văn, ứng dụng có "a map that shows the nearest gas stations along with up-to-the-minute pricing information" (bản đồ hiển thị các trạm xăng gần nhất cùng với thông tin giá cập nhật), cho phép người dùng so sánh giá cả tại các doanh nghiệp khác nhau.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ứng dụng điện thoại thông minh mới của Utica Inc. cho phép người dùng làm gì?
A. Kiểm tra các đợt thu hồi và báo cáo liên quan đến an toàn
B. Tìm hiểu về các ưu đãi đặc biệt trước khách hàng khác
C. Theo dõi việc vận chuyển sản phẩm theo thời gian thực
D. So sánh giá cả tại các doanh nghiệp khác nhau');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7364, 5843, 163, 'The word "follow" in paragraph 3, line 1, is closest in meaning to', 'stick to', 'accompany', 'guide', 'replace', 'A', 'Đáp án đúng là A.
Giải thích:
Trong câu "we don''t just follow the trend", từ "follow" có nghĩa là "stick to" (bám theo, tuân theo). Câu này nhấn mạnh rằng công ty không chỉ đơn thuần làm theo xu hướng mà còn dẫn đầu với phong cách riêng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Từ "follow" trong đoạn 3, dòng 1, có nghĩa gần nhất với?
A. Bám theo, tuân theo
B. Đi cùng
C. Hướng dẫn
D. Thay thế');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5844, 259, NULL, NULL, 'On behalf of the Youth Music Program (YMP), I would like to express our appreciation for your volunteering for our organization. Without the dedication and hard work of people like you, we could not achieve our common goals and have such a profound positive effect on communities throughout Germany. YMP helps young people cultivate a lifelong love of music, and share the joy of music with others, enhancing well-being and social cohesion. In just two years, we have expanded the number of program centers to twenty-three. Guided by our new executive director, Wayne Kastner, we expect this trend to continue.
Among the many exciting changes on the horizon, we are delighted to partner with Himmel Music, the country''s largest supplier of musical instruments. Himmel Music will donate instruments to our organization as well as assist in our quarterly fundraising events.
To celebrate working with Himmel Music, we are holding a contest to create a slogan to represent the joint efforts of this new relationship. All YMP participants, staff, and volunteers are urged to share their ideas. The best one will be selected by a committee, and the winner will receive a $250 Himmel Music gift certificate. More information about the contest will be included in our monthly newsletter, so be sure to watch for it.', 'Thay mặt Chương trình Âm nhạc Thanh niên (YMP), tôi muốn bày tỏ sự cảm kích của chúng tôi về việc bạn tình nguyện cho tổ chức của chúng tôi. Không có sự cống hiến và làm việc chăm chỉ của những người như bạn, chúng tôi không thể đạt được các mục tiêu chung và có tác động tích cực sâu sắc đến các cộng đồng trên khắp nước Đức. YMP giúp người trẻ vun đắp tình yêu âm nhạc suốt đời, và chia sẻ niềm vui âm nhạc với người khác, nâng cao sức khỏe và gắn kết xã hội. Chỉ trong hai năm, chúng tôi đã mở rộng số lượng trung tâm chương trình lên hai mươi ba. Dưới sự dẫn dắt của giám đốc điều hành mới Wayne Kastner, chúng tôi kỳ vọng xu hướng này sẽ tiếp tục.
Trong số nhiều thay đổi thú vị sắp tới, chúng tôi rất vui mừng được hợp tác với Himmel Music, nhà cung cấp nhạc cụ lớn nhất của đất nước. Himmel Music sẽ tặng nhạc cụ cho tổ chức của chúng tôi cũng như hỗ trợ trong các sự kiện gây quỹ hàng quý của chúng tôi.
Để kỷ niệm việc hợp tác với Himmel Music, chúng tôi đang tổ chức một cuộc thi để tạo ra một khẩu hiệu đại diện cho những nỗ lực chung của mối quan hệ mới này. Tất cả người tham gia YMP, nhân viên và tình nguyện viên được khuyến khích chia sẻ ý tưởng của họ. Ý tưởng hay nhất sẽ được một ủy ban lựa chọn, và người chiến thắng sẽ nhận được phiếu quà tặng trị giá 250$ của Himmel Music. Thông tin chi tiết về cuộc thi sẽ được đưa vào bản tin hàng tháng của chúng tôi, vì vậy hãy chắc chắn theo dõi nó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7365, 5844, 164, 'What is one purpose of the letter?', 'To make a request for donations', 'To announce a new partnership', 'To explain an organization''s name change', 'To extend an invitation to a musical performance', 'B', 'Đáp án đúng là B.
Giải thích:
Lá thư thông báo về việc hợp tác mới giữa YMP và Himmel Music: "we are delighted to partner with Himmel Music, the country''s largest supplier of musical instruments" (chúng tôi rất vui mừng được hợp tác với Himmel Music, nhà cung cấp nhạc cụ lớn nhất của đất nước).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Một trong những mục đích của lá thư là gì?
A. Yêu cầu quyên góp
B. Thông báo về một quan hệ đối tác mới
C. Giải thích về việc thay đổi tên tổ chức
D. Gửi lời mời đến một buổi biểu diễn âm nhạc');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7366, 5844, 165, 'The word "common" in paragraph 1, line 3, is closest in meaning to', 'mutual', 'popular', 'intended', 'ordinary', 'A', 'Đáp án đúng là A.
Giải thích:
Trong cụm "common goals" (mục tiêu chung), từ "common" có nghĩa là "mutual" (chung, cùng chia sẻ). Từ này được sử dụng để chỉ những mục tiêu mà tất cả mọi người trong tổ chức cùng chia sẻ và hướng đến.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Từ "common" trong đoạn 1, dòng 3, có nghĩa gần nhất với?
A. Chung, cùng chia sẻ
B. Phổ biến
C. Dự định
D. Thông thường');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7367, 5844, 166, 'What is suggested about Mr. Holtzmann?', 'He is encouraged to submit a slogan.', 'He has been nominated for an award.', 'He will be given a music store gift card.', 'He was a founding member of YMP.', 'A', 'Đáp án đúng là A.
Giải thích:
Theo thư, "All YMP participants, staff, and volunteers are urged to share their ideas" (Tất cả người tham gia YMP, nhân viên và tình nguyện viên được khuyến khích chia sẻ ý tưởng của họ). Vì Mr. Holtzmann là tình nguyện viên của YMP (được đề cập ở đầu thư), nên ông cũng được khuyến khích gửi khẩu hiệu dự thi.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về ông Holtzmann?
A. Ông được khuyến khích gửi khẩu hiệu dự thi
B. Ông đã được đề cử cho một giải thưởng
C. Ông sẽ được tặng thẻ quà tặng của cửa hàng nhạc cụ
D. Ông là thành viên sáng lập của YMP');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7368, 5844, 167, 'What is NOT indicated about the YMP?', 'It holds fundraising events four times a year.', 'It has experienced rapid growth.', 'It is the country''s largest youth organization.', 'It has recently changed its leadership.', 'C', 'Đáp án đúng là C.
Giải thích:
Đoạn văn không hề đề cập đến việc YMP là tổ chức thanh niên lớn nhất của đất nước. Trong khi đó:
- YMP tổ chức sự kiện gây quỹ hàng quý (quarterly fundraising events)
- YMP đã phát triển nhanh chóng (mở rộng lên 23 trung tâm chỉ trong 2 năm)
- YMP có giám đốc điều hành mới là Wayne Kastner

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG được đề cập về YMP?
A. Nó tổ chức các sự kiện gây quỹ bốn lần một năm
B. Nó đã trải qua sự tăng trưởng nhanh chóng
C. Nó là tổ chức thanh niên lớn nhất của đất nước
D. Nó gần đây đã thay đổi ban lãnh đạo');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5845, 259, NULL, NULL, 'Yurino Saiki 1:54 P.M.
What did you think of the applicant Ruby Fleming?
Aziz Miri 1:55 P.M.
She really impressed me in the interview. I think her artwork would be a great addition to our children''s series.
Yurino Saiki 1:56 P.M.
If we hire her, I thought Levi could teach her how to use our on-site file-sharing program.
It wouldn''t be software she''s worked with before. Levi, would that be an issue for you?
Aziz Miri 1:57 P.M.
Of everyone we''ve interviewed, I think she would be the best fit for the team.
Levi Weiler 1:58 P.M.
Of course not.
Yurino Saiki 2:00 P.M.
Thanks a lot! I also see from her cover letter that she has built up a following on social media.
Levi Weiler 2:01 P.M.
That would help to boost sales. So, are we ready to make her a job offer?
Aziz Miri 2:02 P.M.
Mr. Gilliam wants to have a follow-up interview by teleconference first to talk about how she might handle the role. He says it''s essential that the person can cope with being assigned numerous tasks.
Yurino Saiki 2:04 P.M.
Aziz, are you setting up that meeting?
Aziz Miri 2:05 P.M.
Yes, I''ll take care of everything.', 'Yurino Saiki 1:54 chiều
Bạn nghĩ gì về ứng viên Ruby Fleming?
Aziz Miri 1:55 chiều
Cô ấy thực sự gây ấn tượng với tôi trong cuộc phỏng vấn. Tôi nghĩ tác phẩm nghệ thuật của cô ấy sẽ là một bổ sung tuyệt vời cho loạt sách thiếu nhi của chúng ta.
Yurino Saiki 1:56 chiều
Nếu chúng ta thuê cô ấy, tôi nghĩ Levi có thể dạy cô ấy cách sử dụng chương trình chia sẻ tệp tại chỗ của chúng ta.
Đó sẽ là phần mềm mà cô ấy chưa từng làm việc trước đây. Levi, điều đó có phải vấn đề với anh không?
Aziz Miri 1:57 chiều
Trong số tất cả những người chúng ta đã phỏng vấn, tôi nghĩ cô ấy sẽ là người phù hợp nhất với đội ngũ.
Levi Weiler 1:58 chiều
Tất nhiên là không.
Yurino Saiki 2:00 chiều
Cảm ơn nhiều! Tôi cũng thấy từ thư xin việc của cô ấy rằng cô ấy đã xây dựng được một lượng người theo dõi trên mạng xã hội.
Levi Weiler 2:01 chiều
Điều đó sẽ giúp thúc đẩy doanh số. Vậy, chúng ta đã sẵn sàng đưa ra đề nghị công việc cho cô ấy chưa?
Aziz Miri 2:02 chiều
Ông Gilliam muốn có một cuộc phỏng vấn tiếp theo qua teleconference trước để nói về cách cô ấy có thể xử lý vai trò này. Ông ấy nói rằng điều cần thiết là người đó có thể đối phó với việc được giao nhiều nhiệm vụ.
Yurino Saiki 2:04 chiều
Aziz, anh có đang sắp xếp cuộc họp đó không?
Aziz Miri 2:05 chiều
Vâng, tôi sẽ lo liệu mọi thứ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7369, 5845, 168, 'Where do the writers most likely work?', 'At an employment recruitment firm', 'At a children''s clothing store', 'At a book publisher', 'At a movie theater', 'C', 'Đáp án đúng là C.
Giải thích:
Có nhiều chi tiết cho thấy họ làm việc tại nhà xuất bản sách:
- Đề cập đến "artwork would be a great addition to our children''s series" (tác phẩm nghệ thuật sẽ là một bổ sung tuyệt vời cho loạt sách thiếu nhi của chúng tôi)
- Thảo luận về việc tìm kiếm người có thể vẽ minh họa cho sách thiếu nhi
- Đề cập đến việc bán hàng (sales) và người theo dõi trên mạng xã hội có thể giúp tăng doanh số

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Những người viết có khả năng làm việc ở đâu nhất?
A. Tại công ty tuyển dụng nhân sự
B. Tại cửa hàng quần áo trẻ em
C. Tại nhà xuất bản sách
D. Tại rạp chiếu phim');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7370, 5845, 169, 'At 1:58 P.M., what does Mr. Weiler most likely mean when he writes, "Of course not"?', 'He is willing to provide some training.', 'He can accommodate an interview schedule.', 'He will not miss an important deadline.', 'He is not ready to make a decision yet.', 'A', 'Đáp án đúng là A.
Giải thích:
Câu trả lời "Of course not" của Mr. Weiler là phản hồi cho câu hỏi "would that be an issue for you?" về việc dạy Ruby Fleming sử dụng phần mềm chia sẻ tập tin. "Of course not" ở đây có nghĩa là ông ấy sẵn sàng đào tạo cô ấy.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Lúc 1:58 chiều, Mr. Weiler có khả năng muốn nói gì khi viết "Tất nhiên là không"?
A. Anh ấy sẵn sàng cung cấp một số đào tạo
B. Anh ấy có thể điều chỉnh lịch phỏng vấn
C. Anh ấy sẽ không bỏ lỡ một thời hạn quan trọng
D. Anh ấy chưa sẵn sàng đưa ra quyết định');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7371, 5845, 170, 'What is indicated about Ms. Fleming?', 'She already has her own fan base.', 'She currently works for a social media company.', 'She will cover shifts while Mr. Weiler is on leave.', 'She prefers to discuss matters by teleconference.', 'A', 'Đáp án đúng là A.
Giải thích:
Theo đoạn hội thoại, "she has built up a following on social media" (cô ấy đã xây dựng được một lượng người theo dõi trên mạng xã hội), cho thấy cô ấy đã có lượng người hâm mộ riêng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về Ms. Fleming?
A. Cô ấy đã có lượng người hâm mộ riêng
B. Cô ấy hiện đang làm việc cho một công ty mạng xã hội
C. Cô ấy sẽ thay ca trong khi Mr. Weiler nghỉ phép
D. Cô ấy thích thảo luận qua teleconference');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7372, 5845, 171, 'According to the discussion, what does Mr. Gilliam think is critical to the open position?', 'The ability to deal with several assignments efficiently', 'A collaborative approach to work projects', 'Dedication to improving customer service', 'Experience working with many software programs', 'A', 'Đáp án đúng là A.
Giải thích:
Theo đoạn hội thoại, Mr. Gilliam nói rằng "it''s essential that the person can cope with being assigned numerous tasks" (điều cần thiết là người đó có thể đối phó với việc được giao nhiều nhiệm vụ), cho thấy khả năng xử lý hiệu quả nhiều nhiệm vụ là yếu tố quan trọng.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Theo cuộc thảo luận, điều gì mà Mr. Gilliam cho là quan trọng đối với vị trí đang tuyển?
A. Khả năng xử lý hiệu quả nhiều nhiệm vụ
B. Cách tiếp cận hợp tác trong các dự án công việc
C. Sự tận tâm trong việc cải thiện dịch vụ khách hàng
D. Kinh nghiệm làm việc với nhiều chương trình phần mềm');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5846, 259, NULL, NULL, 'To: Holly Grenier < grenierh@duvalmail.com>
From: Bryce Jarvis <b.jarvis@literaryquarterly.com>
Date: August 15
Subject: RE: Submission for upcoming edition
Attachment: Iquarterly_guidelines
Dear Ms. Grenier,
Thank you for your interest in submitting your work to be considered for publication in Literary Quarterly. Please note that we charge a nonrefundable submission fee of $5.00 for each piece of work, which does not affect whether or not the piece is published.
Along with the main text, you should include a paragraph that briefly describes your work. — [2] —. This will help us to assess the suitability of your writing for our magazine when we review your submission. If you subscribe to the magazine, you will have a better understanding of our preferences.
Also, as we exclusively consider texts that have never been published elsewhere, your submission should not have been shared with other publishers previously. Prior to submitting your work, please read the attached guidelines carefully and follow the style and layout precisely. There is a sample essay included for your reference. — 3] -.
We are always in need of short stories, but we receive an overwhelming amount of poetry. So, please understand that even excellent manuscripts may be rejected due to the high volume, and we hope this will not discourage you. — [4] -.
We wish you the best of luck with your submission,
Bryce Jarvis', 'Gửi: Holly Grenier < grenierh@duvalmail.com>
Từ: Bryce Jarvis <b.jarvis@literaryquarterly.com>
Ngày: 15 tháng 8
Chủ đề: Trả lời: Nộp bài cho ấn phẩm sắp tới
Tệp đính kèm: Hướng dẫn_quý
Kính gửi Ms. Grenier,
Cảm ơn sự quan tâm của bạn trong việc nộp tác phẩm để được xem xét xuất bản trên Literary Quarterly. Xin lưu ý rằng chúng tôi tính phí nộp bài không hoàn lại là $5.00 cho mỗi tác phẩm, điều này không ảnh hưởng đến việc tác phẩm có được xuất bản hay không.
Cùng với văn bản chính, bạn nên bao gồm một đoạn văn mô tả ngắn gọn về tác phẩm của bạn. — [2] —. Điều này sẽ giúp chúng tôi đánh giá sự phù hợp của bài viết của bạn cho tạp chí khi chúng tôi xem xét bài nộp của bạn. Nếu bạn đăng ký tạp chí, bạn sẽ hiểu rõ hơn về sở thích của chúng tôi.
Ngoài ra, vì chúng tôi chỉ xem xét các văn bản chưa từng được xuất bản ở nơi khác, bài nộp của bạn không nên đã được chia sẻ với các nhà xuất bản khác trước đó. Trước khi nộp tác phẩm của bạn, vui lòng đọc kỹ hướng dẫn đính kèm và tuân theo phong cách và bố cục một cách chính xác. Có một bài luận mẫu được đính kèm để bạn tham khảo. — [3] -.
Chúng tôi luôn cần truyện ngắn, nhưng chúng tôi nhận được quá nhiều thơ. Vì vậy, xin hãy hiểu rằng ngay cả những bản thảo xuất sắc cũng có thể bị từ chối do số lượng lớn, và chúng tôi hy vọng điều này sẽ không làm bạn nản lòng. — [4] -.
Chúc bạn may mắn với bài nộp của mình,
Bryce Jarvis');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7373, 5846, 172, 'What is suggested about Literary Quarterly?', 'Its main texts are usually produced by in-house writers.', 'It solely publishes work being made public for the first time.', 'Its management is considering publishing editions more frequently.', 'It only contacts writers whose submissions have been accepted.', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email, "we exclusively consider texts that have never been published elsewhere" (chúng tôi chỉ xem xét các văn bản chưa từng được xuất bản ở nơi khác), cho thấy tạp chí chỉ xuất bản những tác phẩm được công bố lần đầu tiên.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về Literary Quarterly?
A. Các văn bản chính thường được sản xuất bởi các nhà văn nội bộ
B. Nó chỉ xuất bản tác phẩm được công bố lần đầu tiên
C. Ban quản lý đang xem xét xuất bản các ấn phẩm thường xuyên hơn
D. Nó chỉ liên hệ với các nhà văn có bài viết được chấp nhận');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7374, 5846, 173, 'What is NOT mentioned as a requirement for making a submission?', 'Paying a one-time fee', 'Providing a short description', 'Subscribing to the magazine', 'Formatting the work in a specific way', 'C', 'Đáp án đúng là C.
Giải thích:
Trong email không đề cập việc bắt buộc phải đăng ký tạp chí. Email chỉ nói "If you subscribe to the magazine, you will have a better understanding of our preferences" (Nếu bạn đăng ký tạp chí, bạn sẽ hiểu rõ hơn về sở thích của chúng tôi), đây chỉ là gợi ý không phải yêu cầu.

Các yêu cầu được đề cập bao gồm:
- Trả phí nộp bài $5.00 (paying a one-time fee)
- Cung cấp mô tả ngắn (providing a short description)
- Định dạng theo hướng dẫn cụ thể (formatting the work in a specific way)

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG được đề cập như một yêu cầu khi nộp bài?
A. Trả phí một lần
B. Cung cấp mô tả ngắn
C. Đăng ký tạp chí
D. Định dạng tác phẩm theo cách cụ thể');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7375, 5846, 174, 'What is Ms. Grenier most likely interested in writing?', 'Poetry', 'Short stories', 'Essays', 'Book reviews', 'A', 'Đáp án đúng là A.
Giải thích:
Email đề cập rằng "we receive an overwhelming amount of poetry" (chúng tôi nhận được quá nhiều thơ) và cảnh báo rằng "even excellent manuscripts may be rejected due to the high volume" (ngay cả những bản thảo xuất sắc cũng có thể bị từ chối do số lượng lớn). Việc đề cập cụ thể đến thơ và cảnh báo về số lượng lớn gợi ý rằng Ms. Grenier có khả năng muốn nộp thơ.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Ms. Grenier có khả năng quan tâm đến việc viết gì nhất?
A. Thơ
B. Truyện ngắn
C. Bài luận
D. Bài đánh giá sách');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7376, 5846, 175, 'In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? "Be sure to include relevant information that will be important in the initial screening process."', '[1]', '[2]', '[3]', '[4]', 'B', 'Đáp án đúng là B.
Giải thích:
Câu "Be sure to include relevant information that will be important in the initial screening process" (Hãy chắc chắn bao gồm thông tin liên quan sẽ quan trọng trong quá trình sàng lọc ban đầu) phù hợp nhất ở vị trí [2] vì:
- Nó liên quan trực tiếp đến yêu cầu về việc cung cấp đoạn mô tả tác phẩm
- Nó giải thích thêm về mục đích của việc cung cấp thông tin này (để sàng lọc ban đầu)
- Nó phù hợp với ngữ cảnh của đoạn này, nơi đang nói về các yêu cầu nộp bài

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Câu "Hãy chắc chắn bao gồm thông tin liên quan sẽ quan trọng trong quá trình sàng lọc ban đầu" phù hợp nhất ở vị trí nào trong số các vị trí được đánh dấu [1], [2], [3], và [4]?
A. [1]
B. [2]
C. [3]
D. [4]');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5847, 259, NULL, NULL, 'http://www.junctiontours.ca
Make your trip to Toronto memorable with help from Junction Tours!
We offer a variety of tour packages to suit everyone''s tastes.
Tour 1: Full-day tour for sports fans! Take a tour of Rogers Centre and the Hockey Hall of Fame. You may even spot your favorite player! Lunch provided.
Tour 2: Full-day hop-on, hop-off tour for visiting all of Toronto''s major tourist attractions. Board the bus anywhere on the circuit and get off at the places that interest you most. Stay as long as you like at each site!
Tour 3: Half-day tour of the best shopping sites that Toronto has to offer. Participants get exclusive discounts at the Eaton Centre.
Tour 4: Full-day Toronto Island tour with a scenic ferry ride that will give you amazing views of the Toronto skyline. Lunch provided.
Tour 5: Half-day tour of the CN Tower, Toronto''s most iconic building. Get your camera ready for the highest observation platform in the Western Hemisphere!
All of our tours are available daily, excluding national holidays. Participants can meet at our downtown office or we can pick you up from the Emery Hotel or Hotel Cruz at no extra charge. Meals are not included unless otherwise specified.
==========
Winston Hart ★★★★★
→ Review of Junction Tours
The booking process for Junction Tours was straightforward, and I was kept well informed about all related details along the way. I was really impressed with the thorough preparations of our tour guide, Stephen. I started feeling seasick while crossing the water, due to rough waves. Stephen took me up to the deck for some fresh air and gave me some chilled bottled water. He was also extremely knowledgeable about Toronto''s history and amenities.
We wanted to bring home some Toronto-themed gifts to help us remember our trip, and Stephen made some very helpful suggestions about what to buy and where. We had so much fun meeting other participants in our group, including a family that was visiting all the way from Japan.
The only downside of this tour was that the portion size for the lunch was quite small. Despite this, I would highly recommend Junction Tours to everyone.', 'http://www.junctiontours.ca
Làm cho chuyến đi của bạn đến Toronto trở nên đáng nhớ với sự trợ giúp từ Junction Tours! 
Chúng tôi cung cấp nhiều gói tour du lịch phù hợp với sở thích của mọi người.
Tour 1: Tour trọn ngày dành cho người hâm mộ thể thao! Tham quan Trung tâm Rogers và Đại sảnh Danh vọng Khúc côn cầu. Bạn thậm chí có thể phát hiện ra người chơi yêu thích của mình! Bữa trưa được cung cấp.
Tour 2: Tour hop-on, hop-off cả ngày để tham quan tất cả các điểm du lịch chính của Toronto. Lên xe buýt ở bất cứ đâu trên đường đua và xuống ở những nơi bạn quan tâm nhất. Ở lại bao lâu tùy thích tại mỗi trang web! 
Tour 3: Tour nửa ngày đến các địa điểm mua sắm tốt nhất mà Toronto cung cấp. Những người tham gia được giảm giá độc quyền tại Trung tâm Eaton.
Tour 4: Chuyến tham quan Đảo Toronto cả ngày với chuyến đi phà ngắm cảnh sẽ mang đến cho bạn tầm nhìn tuyệt vời ra đường chân trời Toronto. Bữa trưa được cung cấp.
Tour 5: Tour nửa ngày đến Tháp CN, tòa nhà mang tính biểu tượng nhất của Toronto. Chuẩn bị sẵn máy ảnh của bạn cho nền tảng quan sát cao nhất ở Tây bán cầu! 
Tất cả các tour du lịch của chúng tôi đều hoạt động hàng ngày, trừ các ngày lễ quốc gia. Những người tham gia có thể gặp nhau tại văn phòng trung tâm thành phố của chúng tôi hoặc chúng tôi có thể đón bạn từ Khách sạn Emery hoặc Khách sạn Cruz mà không phải trả thêm phí. Các bữa ăn không được bao gồm trừ khi có quy định khác.
============
Winston Hart ★★★★★
→ Đánh giá về Junction Tours
Quy trình đặt chỗ cho Junction Tours rất đơn giản và tôi đã được thông báo đầy đủ về tất cả các chi tiết liên quan trên đường đi. Tôi thực sự ấn tượng với sự chuẩn bị kỹ lưỡng của hướng dẫn viên du lịch của chúng tôi, Stephen. Tôi bắt đầu cảm thấy say sóng khi vượt mặt nước, do những con sóng dữ dội. Stephen đưa tôi lên boong tàu để hít thở không khí trong lành và đưa cho tôi một ít nước đóng chai ướp lạnh. Anh ấy cũng cực kỳ hiểu biết về lịch sử và các tiện nghi của Toronto.
Chúng tôi muốn mang về nhà một số món quà theo chủ đề Toronto để giúp chúng tôi ghi nhớ chuyến đi của mình, và Stephen đã đưa ra một số gợi ý rất hữu ích về những gì nên mua và ở đâu. Chúng tôi đã rất vui khi gặp gỡ những người tham gia khác trong nhóm của chúng tôi, bao gồm cả một gia đình đã đến thăm từ Nhật Bản.
Hếu điểm duy nhất của chuyến tham quan này là kích thước khẩu phần cho bữa trưa khá nhỏ. Mặc dù vậy, tôi rất muốn giới thiệu Junction Tours cho mọi người.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7377, 5847, 176, 'How is Tour 2 different from the rest of the tours?', 'Its participants can go at their own pace.', 'Its attractions are famous in Toronto.', 'It lasts for a full day.', 'It includes help from a tour guide.', 'A', 'Đáp án đúng là A.
Giải thích:
Tour 2 khác biệt vì cho phép du khách tự do điều chỉnh thời gian: "get off at the places that interest you most. Stay as long as you like at each site!" (xuống xe ở những địa điểm bạn quan tâm nhất và ở lại bao lâu tùy thích).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tour 2 khác với các tour còn lại như thế nào?
A. Người tham gia có thể đi theo nhịp độ riêng của họ
B. Các điểm tham quan của nó nổi tiếng ở Toronto
C. Nó kéo dài cả ngày
D. Nó có sự hỗ trợ của hướng dẫn viên');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7378, 5847, 177, 'What is included in all tour packages?', 'Lunch on the tour day', 'Storage of participants'' luggage', 'Transportation from certain hotels', 'A visit to the CN Tower', 'C', 'Đáp án đúng là C.
Giải thích:
Theo mô tả, tất cả các tour đều bao gồm dịch vụ đưa đón từ một số khách sạn nhất định: "we can pick you up from the Emery Hotel or Hotel Cruz at no extra charge" (chúng tôi có thể đón bạn từ Khách sạn Emery hoặc Khách sạn Cruz mà không tính thêm phí).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được bao gồm trong tất cả các gói tour?
A. Bữa trưa trong ngày tour
B. Lưu trữ hành lý của người tham gia
C. Đưa đón từ một số khách sạn nhất định
D. Thăm quan Tháp CN');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7379, 5847, 178, 'Which tour did Mr. Hart most likely take?', 'Tour 1', 'Tour 3', 'Tour 4', 'Tour 5', 'C', 'Đáp án đúng là C.
Giải thích:
Mr. Hart có khả năng đã tham gia Tour 4 (Tour đảo Toronto) vì:
- Ông ấy đề cập đến việc bị say sóng khi đi qua vùng nước: "feeling seasick while crossing the water"
- Tour 4 là tour duy nhất có chuyến đi phà: "with a scenic ferry ride"
- Ông ấy nhắc đến bữa trưa, và Tour 4 có bao gồm bữa trưa: "Lunch provided"

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mr. Hart có khả năng đã tham gia tour nào?
A. Tour 1
B. Tour 3
C. Tour 4
D. Tour 5');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7380, 5847, 179, 'What does the review suggest about Stephen?', 'He can speak Japanese.', 'He has a history degree.', 'He was born in Toronto.', 'He gave advice on souvenirs.', 'D', 'Đáp án đúng là D.
Giải thích:
Bài đánh giá cho thấy Stephen đã đưa ra lời khuyên về quà lưu niệm: "Stephen made some very helpful suggestions about what to buy and where" (Stephen đã đưa ra những gợi ý rất hữu ích về việc nên mua gì và mua ở đâu).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Bài đánh giá gợi ý điều gì về Stephen?
A. Anh ấy có thể nói tiếng Nhật
B. Anh ấy có bằng cấp về lịch sử
C. Anh ấy sinh ra ở Toronto
D. Anh ấy đưa ra lời khuyên về quà lưu niệm');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7381, 5847, 180, 'Why was Mr. Hart dissatisfied with part of the tour?', 'The guide was disorganized.', 'A meal was small.', 'The area was crowded.', 'A schedule was not followed.', 'B', 'Đáp án đúng là B.
Giải thích:
Theo bài đánh giá, Mr. Hart không hài lòng với khẩu phần ăn trưa nhỏ: "the portion size for the lunch was quite small" (khẩu phần ăn trưa khá nhỏ).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tại sao Mr. Hart không hài lòng với một phần của tour?
A. Hướng dẫn viên không có tổ chức
B. Một bữa ăn nhỏ
C. Khu vực đông đúc
D. Lịch trình không được tuân thủ');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5848, 259, NULL, NULL, 'To: Bradely Jackson <bjackson@cambridgestar.com>
From: promotions@moonlight-bedding.com
Date: February 10
Subject: Grab a bedding bargain!
Dear Customer:
Don''t miss Moonlight Bedding''s Annual Clearance Sale, which starts tomorrow! It''s the perfect time to stock up on sheets, pillowcases, and mattress covers. Normally we hold our sale for just one week, but we''re running it for two weeks this year, from February 11 to 24. A wide range of patterns, colors, and fabric types is available. And whether you have a small twin bed, a king-sized bed, or anything in between, we''re sure you''ll find something you love. Anyone who places an order on the first day of the sale will receive a free 50 ml. bottle of our new Lavender Sleep Spray, so be sure to shop tomorrow and use code THX05. In addition, customers who spend $50 or more will receive free shipping. The inventory in our online catalog is available only while supplies last.
We hope to serve you soon!
Billy Elwood
Promotions Team, Moonlight Bedding
Please note: This e-mail has been sent to customers who have made frequent purchases in the past year. You can unsubscribe at any time.
==========
To: bjackson@cambridgestar.com
From: orders@moonlight-bedding.com
Date: February 11
Subject: Order confirmation
Dear Mr. Jackson,
Thank you for participating in Moonlight Bedding''s Annual Clearance Sale! Your items will be shipped within three business days.
Item#.           Description.                                              Quantity.                   Total
3950      Blue checkered sheet set (queen).                    1                         $15.99
3210       Blue checkered pillowcase (set of 2).               1                         $3.75
9442.     Beige flat sheet (queen).                                      2                        $13.98
8674.     Blue flat sheet (twin).                                            1                         $4.95
1041.      Lavender sleep spray (promo: THX05).           1                         $0.00
                                                                                                               Subtotal: $38.67
                                                                                                        Shipping fee: $5.00
                                                                                                                      Total: $43.67
Please note that the items in this order are subject to a stricter return policy than regular purchases.
Be sure to visit our Web site again soon, as we release new patterns frequently!', 'Gửi: Bradely Jackson <bjackson@cambridgestar.com>
Từ: promotions@moonlight-bedding.com
Ngày: 10 tháng 2
Chủ đề: Nhanh tay với ưu đãi đồ giường!
Kính gửi Quý khách:
Đừng bỏ lỡ Đợt Giảm Giá Hàng Năm của Moonlight Bedding, bắt đầu vào ngày mai! Đây là thời điểm hoàn hảo để tích trữ ga trải giường, vỏ gối và tấm bọc nệm. Thông thường chúng tôi tổ chức giảm giá chỉ một tuần, nhưng năm nay chúng tôi sẽ kéo dài hai tuần, từ ngày 11 đến 24 tháng 2. Có sẵn nhiều loại mẫu mã, màu sắc và chất liệu vải. Và dù bạn có giường đơn nhỏ, giường cỡ king hoặc bất kỳ kích thước nào ở giữa, chúng tôi chắc chắn bạn sẽ tìm thấy thứ bạn thích. Bất kỳ ai đặt hàng vào ngày đầu tiên của đợt giảm giá sẽ nhận được một chai xịt Lavender Sleep Spray 50ml miễn phí, vì vậy hãy nhớ mua sắm vào ngày mai và sử dụng mã THX05. Ngoài ra, khách hàng chi tiêu từ $50 trở lên sẽ được miễn phí vận chuyển. Hàng tồn kho trong catalog trực tuyến của chúng tôi chỉ có sẵn khi còn hàng.
Chúng tôi hy vọng sớm được phục vụ bạn!
Billy Elwood
Đội Khuyến mãi, Moonlight Bedding
Lưu ý: Email này được gửi đến khách hàng đã mua hàng thường xuyên trong năm qua. Bạn có thể hủy đăng ký bất cứ lúc nào.
==========
Gửi: bjackson@cambridgestar.com
Từ: orders@moonlight-bedding.com
Ngày: 11 tháng 2
Chủ đề: Xác nhận đơn hàng
Kính gửi Mr. Jackson,
Cảm ơn bạn đã tham gia Đợt Giảm Giá Hàng Năm của Moonlight Bedding! Các mặt hàng của bạn sẽ được vận chuyển trong vòng ba ngày làm việc.
Mã SP.           Mô tả.                                              Số lượng.                   Tổng
3950      Bộ ga carô màu xanh (cỡ queen).                    1                         $15.99
3210       Vỏ gối carô màu xanh (bộ 2 cái).               1                         $3.75
9442.     Ga phẳng màu be (cỡ queen).                                      2                        $13.98
8674.     Ga phẳng màu xanh (cỡ twin).                                            1                         $4.95
1041.      Xịt Lavender sleep (khuyến mãi: THX05).           1                         $0.00
                                                                                                               Tổng phụ: $38.67
                                                                                                        Phí vận chuyển: $5.00
                                                                                                                      Tổng: $43.67
Xin lưu ý rằng các mặt hàng trong đơn hàng này tuân theo chính sách đổi trả nghiêm ngặt hơn so với các đơn hàng thông thường.
Hãy nhớ ghé thăm trang web của chúng tôi sớm, vì chúng tôi thường xuyên ra mắt các mẫu mới!');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7382, 5848, 181, 'Why does Mr. Elwood recommend placing an order on February 11?', 'To be sent a product catalog', 'To avoid long shipping times', 'To receive a bonus gift', 'To try a new bedding pattern', 'C', 'Đáp án đúng là C.
Giải thích:
Mr. Elwood khuyến khích đặt hàng vào ngày 11 tháng 2 vì đó là ngày đầu tiên của đợt giảm giá và khách hàng sẽ nhận được quà tặng miễn phí: "Anyone who places an order on the first day of the sale will receive a free 50 ml. bottle of our new Lavender Sleep Spray" (Bất kỳ ai đặt hàng vào ngày đầu tiên của đợt giảm giá sẽ nhận được một chai xịt Lavender Sleep Spray 50ml miễn phí).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Tại sao Mr. Elwood khuyến khích đặt hàng vào ngày 11 tháng 2?
A. Để được gửi catalog sản phẩm
B. Để tránh thời gian vận chuyển dài
C. Để nhận quà tặng thêm
D. Để thử một mẫu ga trải giường mới');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7383, 5848, 182, 'What is suggested about Mr. Jackson?', 'He is a regular Moonlight Bedding customer.', 'He owns a king-sized bed.', 'He only purchases bedding in a certain color.', 'He will receive his goods on February 12.', 'A', 'Đáp án đúng là A.
Giải thích:
Email ghi chú rằng "This e-mail has been sent to customers who have made frequent purchases in the past year" (Email này được gửi đến khách hàng đã mua hàng thường xuyên trong năm qua). Vì Mr. Jackson nhận được email này, điều đó cho thấy ông ấy là khách hàng thường xuyên của Moonlight Bedding.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được gợi ý về Mr. Jackson?
A. Ông ấy là khách hàng thường xuyên của Moonlight Bedding
B. Ông ấy có giường cỡ king
C. Ông ấy chỉ mua đồ giường một màu nhất định
D. Ông ấy sẽ nhận hàng vào ngày 12 tháng 2');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7384, 5848, 183, 'What is indicated about the items in Mr. Jackson''s order?', 'They can be exchanged for any reason.', 'They all have a checkered pattern.', 'They may arrive in separate boxes.', 'They follow different return policy guidelines.', 'D', 'Đáp án đúng là D.
Giải thích:
Theo email xác nhận đơn hàng: "the items in this order are subject to a stricter return policy than regular purchases" (các mặt hàng trong đơn hàng này tuân theo chính sách đổi trả nghiêm ngặt hơn so với các đơn hàng thông thường).

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì được chỉ ra về các mặt hàng trong đơn hàng của Mr. Jackson?
A. Chúng có thể được đổi trả vì bất kỳ lý do gì
B. Tất cả đều có họa tiết carô
C. Chúng có thể được giao trong các hộp riêng biệt
D. Chúng tuân theo các hướng dẫn chính sách đổi trả khác');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7385, 5848, 184, 'How could Mr. Jackson have taken advantage of a special promotion?', 'By writing a product review', 'By spending more on his order', 'By ordering on a different day', 'By trying some newly released merchandise', 'B', 'Đáp án đúng là B.
Giải thích:
Theo email, "customers who spend $50 or more will receive free shipping" (khách hàng chi tiêu từ $50 trở lên sẽ được miễn phí vận chuyển). Đơn hàng của Mr. Jackson chỉ có tổng phụ là $38.67, nếu ông ấy chi tiêu thêm để đạt $50, ông ấy đã có thể được miễn phí vận chuyển $5.00.

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Mr. Jackson có thể đã tận dụng khuyến mãi đặc biệt bằng cách nào?
A. Bằng cách viết đánh giá sản phẩm
B. Bằng cách chi tiêu nhiều hơn cho đơn hàng
C. Bằng cách đặt hàng vào một ngày khác
D. Bằng cách thử một số hàng hóa mới ra mắt');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7386, 5848, 185, 'What is NOT true about Moonlight Bedding?', 'It provides bedding in different sizes.', 'It changes its inventory regularly.', 'It sells curtains to match its bedding.', 'Its clearance sale is longer this year.', 'C', 'Đáp án đúng là C.
Giải thích:
Không có thông tin nào đề cập đến việc Moonlight Bedding bán rèm cửa để phù hợp với đồ giường. Trong khi đó:
- Công ty cung cấp đồ giường nhiều kích cỡ khác nhau (twin, queen, king)
- Công ty thường xuyên thay đổi mẫu mã ("we release new patterns frequently")
- Đợt giảm giá năm nay kéo dài hơn ("Normally we hold our sale for just one week, but we''re running it for two weeks this year")

Dịch câu hỏi và các lựa chọn:
Câu hỏi: Điều gì KHÔNG đúng về Moonlight Bedding?
A. Nó cung cấp đồ giường với các kích cỡ khác nhau
B. Nó thay đổi hàng tồn kho thường xuyên
C. Nó bán rèm cửa để phù hợp với đồ giường
D. Đợt giảm giá của nó kéo dài hơn năm nay');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5849, 259, NULL, NULL, 'From: k.wells@rivera-grill.com
To: service@boisvertsuppliers.com
Date: October 16
Subject: Plates (Item #L8916)
Hello,
I''ve been making a series of upgrades to our restaurant''s interior under the direction of our new proprietor, and I ordered a new set of dishes from your company as part of these improvements. Unfortunately, when the order arrived this morning, I was disappointed to see that no fewer than 11 of the Lund Square Dinner Plates (Item #L8916) had cracks, chips, or both.
I must ask that Boisvert Suppliers send 11 undamaged plates of the same type at no additional charge, and expedite the shipment so that it arrives by Wednesday. It is not fair to expect us to wait another two weeks for useable plates. If you cannot meet this deadline, please refund the cost of two packs of the plates so that I can take our business elsewhere.
Kenneth Wells, General Manager
Rivera Grill
