INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7403, 5853, 2, 'Look at the picture marked number two in your test book.', 'The counter is covered with gardening tools.', 'Some potted plants are being watered.', 'Some baskets are lined up against the wall.', 'A floral arrangement is being assembled.', 'D', 'A Quầy được phủ đầy dụng cụ làm vườn.
