INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5855, 260, '2025/test8/audio/test8_question_4.mp3', '2025/test8/image/test8-image-4.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7405, 5855, 4, 'Look at the picture marked number four in your test book.', 'A hotel employee is assisting a guest.', 'Some luggage is being organized on a cart.', 'A light fixture has been suspended over a desk.', 'Some travelers are standing in front of an elevator.', 'C', 'A Một nhân viên khách sạn đang hỗ trợ một khách.
B Một số hành lý đang được sắp xếp trên một xe đẩy.
