INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5856, 260, '2025/test8/audio/test8_question_5.mp3', '2025/test8/image/test8-image-5.jpg', NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7406, 5856, 5, 'Look at the picture marked number five in your test book.', 'One of the men is holding a kitchen knife.', 'One of the men is stacking bowls in a sink.', 'Food is being cooked on a stove.', 'They''re sorting vegetables into containers.', 'A', 'A Một trong những người đàn ông đang cầm một con dao bếp.
B Một trong những người đàn ông đang xếp bát vào bồn rửa.
