INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7407, 5857, 6, 'Look at the picture marked number six in your test book.', 'A toolbox has been left open.', 'Rolls of fabric are propped against a wall.', 'Some power cords have been plugged in.', 'Machines have been set up at a construction site.', 'C', 'A Một hộp dụng cụ đã bị để mở.
B Những cuộn vải được dựa vào tường.
C Một số dây điện đã được cắm vào.
D Các máy móc đã được lắp đặt tại công trường xây dựng.');;

-- Data for 2025 Test8 Part 2
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5858, 261, '2025/test8/audio/test8_question_7.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7408, 5858, 7, 'When will the new water cooler be delivered?', 'Later this week.', 'The employee lounge.', 'Eight degrees Celsius.', NULL, 'A', 'Câu hỏi: Khi nào máy làm mát nước mới sẽ được giao?"
A: "Vào cuối tuần này."
B: "Phòng nghỉ của nhân viên."
C: "Tám độ C."
Giải thích: Đáp án A đúng vì câu hỏi về việc giao máy làm mát nước và đáp án A cho biết thời gian giao hàng là vào cuối tuần này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5859, 261, '2025/test8/audio/test8_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7409, 5859, 8, 'Can you post the job advertisement?', 'Sure, I''ll do that this afternoon.', 'She saw our billboards.', 'Some advice on interviewing.', NULL, 'A', 'Câu hỏi: Bạn có thể đăng quảng cáo tuyển dụng không?"
A: "Chắc chắn, tôi sẽ làm việc đó vào chiều nay."
B: "Cô ấy đã thấy bảng quảng cáo của chúng ta."
C: "Một số lời khuyên về phỏng vấn."
Giải thích: Đáp án A đúng vì câu hỏi yêu cầu đăng quảng cáo tuyển dụng và đáp án A cho biết người trả lời sẽ làm việc đó vào chiều nay."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5860, 261, '2025/test8/audio/test8_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7410, 5860, 9, 'What pieces will the orchestra perform?', 'The concert hall by the harbor.', 'The program is on its Web site.', 'Yes, for the first time in years.', NULL, 'B', 'Câu hỏi: Dàn nhạc sẽ biểu diễn những tác phẩm nào?"
A: "Hội trường hòa nhạc bên bến cảng."
B: "Chương trình có trên trang web của họ."
C: "Vâng, lần đầu tiên sau nhiều năm."
Giải thích: Đáp án B đúng vì câu hỏi về các tác phẩm mà dàn nhạc sẽ biểu diễn và đáp án B cho biết thông tin về chương trình có thể được tìm thấy trên trang web của dàn nhạc."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5861, 261, '2025/test8/audio/test8_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7411, 5861, 10, 'Why did we switch paper suppliers?', 'Newspaper subscriptions.', 'It controls the hallway lights.', 'Because we needed to cut expenses.', NULL, 'C', 'Câu hỏi: Tại sao chúng ta lại thay đổi nhà cung cấp giấy?"
A: "Đăng ký báo."
B: "Nó điều khiển đèn hành lang."
C: "Vì chúng ta cần cắt giảm chi phí."
Giải thích: Đáp án C đúng vì câu hỏi về lý do thay đổi nhà cung cấp giấy và đáp án C cho biết mục đích là để cắt giảm chi phí."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5862, 261, '2025/test8/audio/test8_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7412, 5862, 11, 'The prototype has been completed, right?', 'Yes, I believe so.', 'The next competition.', 'Let''s talk more then.', NULL, 'A', 'Câu hỏi: Mẫu thử đã được hoàn thành, phải không?"
A: "Vâng, tôi nghĩ là đã xong."
B: "Cuộc thi tiếp theo."
C: "Hãy nói thêm về điều đó sau."
Giải thích: Đáp án A đúng vì câu hỏi xác nhận việc hoàn thành mẫu thử và đáp án A xác nhận rằng người trả lời tin rằng mẫu thử đã hoàn thành."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5863, 261, '2025/test8/audio/test8_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7413, 5863, 12, 'Where could I get a haircut?', 'On Thursday evening.', 'I like the salon on Pine Street.', 'Tina might have some extras.', NULL, 'B', 'Câu hỏi: Tôi có thể cắt tóc ở đâu?"
A: "Vào tối thứ Năm."
B: "Tôi thích tiệm làm tóc trên phố Pine."
C: "Tina có thể có một số chiếc cắt tóc thừa."
Giải thích: Đáp án B đúng vì câu hỏi tìm kiếm nơi cắt tóc và đáp án B đề xuất tiệm làm tóc trên phố Pine."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5864, 261, '2025/test8/audio/test8_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7414, 5864, 13, 'How many brochures should I bring to the exposition?', 'That''s a question for Ethan.', 'By five P.M. the day before.', 'Yes, I just registered.', NULL, 'A', 'Câu hỏi: Tôi nên mang bao nhiêu tờ rơi đến triển lãm?"
A: "Đó là câu hỏi dành cho Ethan."
B: "Trước 5 giờ chiều ngày hôm trước."
C: "Vâng, tôi vừa đăng ký."
Giải thích: Đáp án A đúng vì câu hỏi về số lượng tờ rơi cần mang đến triển lãm và đáp án A chỉ ra rằng người trả lời không biết và người có thể trả lời là Ethan."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5865, 261, '2025/test8/audio/test8_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7415, 5865, 14, 'Did you make your time-off request in person or over e-mail?', 'I''ve decided to work from home instead.', 'I''m interested in personal training.', 'Please delete messages over one year old.', NULL, 'A', 'Câu hỏi: Bạn đã yêu cầu nghỉ phép trực tiếp hay qua email?"
A: "Tôi đã quyết định làm việc từ xa thay thế."
B: "Tôi quan tâm đến việc huấn luyện cá nhân."
C: "Vui lòng xóa các tin nhắn đã quá một năm."
Giải thích: Đáp án A đúng vì câu hỏi yêu cầu về phương thức yêu cầu nghỉ phép và đáp án A cho biết người trả lời đã chọn làm việc từ xa thay vì yêu cầu nghỉ phép."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5866, 261, '2025/test8/audio/test8_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7416, 5866, 15, 'This rental fee includes utilities, doesn''t it?', 'Only electricity and gas.', 'The property''s owner.', 'No, it''s still on the market.', NULL, 'A', 'Câu hỏi: Phí thuê này có bao gồm các tiện ích không?"
A: "Chỉ điện và gas."
B: "Chủ sở hữu tài sản."
C: "Không, nó vẫn còn trên thị trường."
Giải thích: Đáp án A đúng vì câu hỏi về phí thuê và đáp án A cho biết phí thuê chỉ bao gồm điện và gas, không bao gồm các tiện ích khác."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5867, 261, '2025/test8/audio/test8_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7417, 5867, 16, 'Don''t we have to mail the party invitations?', 'A book of stamps.', 'Do you host other types of events?', 'Thank you for reminding me.', NULL, 'C', 'Câu hỏi: Chúng ta không phải gửi thiệp mời dự tiệc sao?"
A: "Một cuốn sổ tem."
B: "Bạn có tổ chức các loại sự kiện khác không?"
C: "Cảm ơn bạn đã nhắc nhở tôi."
Giải thích: Đáp án C đúng vì câu hỏi về việc gửi thiệp mời dự tiệc và đáp án C cho biết người trả lời cảm ơn vì được nhắc nhở về việc này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5868, 261, '2025/test8/audio/test8_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7418, 5868, 17, 'Who''s coming to the four P.M. meeting?', 'I only took two.', 'Kenji won''t be able to make it.', 'A special project.', NULL, 'B', 'Câu hỏi: Ai sẽ tham gia cuộc họp vào lúc 4 giờ chiều?"
A: "Tôi chỉ lấy hai cái."
B: "Kenji sẽ không thể tham gia."
C: "Một dự án đặc biệt."
Giải thích: Đáp án B đúng vì câu hỏi về người tham gia cuộc họp và đáp án B thông báo rằng Kenji sẽ không thể tham gia cuộc họp."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5869, 261, '2025/test8/audio/test8_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7419, 5869, 18, 'Should we all attend the presentation?', 'Here''s my attendance certificate.', 'No presents, please.', 'It''s not mandatory.', NULL, 'C', 'Câu hỏi: Tất cả chúng ta có nên tham dự buổi thuyết trình không?"
A: "Đây là chứng nhận tham dự của tôi."
B: "Không cần quà."
C: "Không bắt buộc."
Giải thích: Đáp án C đúng vì câu hỏi về việc tham gia thuyết trình và đáp án C cho biết việc tham gia không bắt buộc."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5870, 261, '2025/test8/audio/test8_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7420, 5870, 19, 'How many study participants do you have?', 'I could use a few more!', 'A short survey.', 'It''s for one of my university courses.', NULL, 'A', 'Câu hỏi: Bạn có bao nhiêu người tham gia nghiên cứu?"
A: "Tôi cần thêm một vài người nữa!"
B: "Một cuộc khảo sát ngắn."
C: "Nó là cho một trong các khóa học của tôi tại trường đại học."
Giải thích: Đáp án A đúng vì câu hỏi yêu cầu số lượng người tham gia nghiên cứu, và đáp án A cho biết người trả lời cần thêm vài người tham gia."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5871, 261, '2025/test8/audio/test8_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7421, 5871, 20, 'Are you planning on buying a new tractor or a used one?', 'I''d prefer a specialized contractor.', 'No, not immediately.', 'Well, I have a limited budget.', NULL, 'C', 'Câu hỏi: Bạn có kế hoạch mua một chiếc máy kéo mới hay cũ không?"
A: "Tôi sẽ chọn một nhà thầu chuyên biệt."
B: "Không, không phải ngay lập tức."
C: "Tôi có một ngân sách hạn chế."
Giải thích: Đáp án C đúng vì câu hỏi về việc mua máy kéo và đáp án C cho biết người trả lời có ngân sách hạn chế, có thể ảnh hưởng đến quyết định mua."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5872, 261, '2025/test8/audio/test8_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7422, 5872, 21, 'Who''s leading the networking workshop for the interns?', 'No, I''m not a member of the organization.', 'That''s been postponed to August.', 'You can use the network to share files.', NULL, 'B', 'Câu hỏi: Ai sẽ dẫn dắt buổi hội thảo kết nối cho các thực tập sinh?"
A: "Không, tôi không phải là thành viên của tổ chức."
B: "Buổi hội thảo đã bị hoãn đến tháng Tám."
C: "Bạn có thể sử dụng mạng để chia sẻ tệp."
Giải thích: Đáp án B đúng vì câu hỏi về người dẫn dắt buổi hội thảo và đáp án B cho biết buổi hội thảo đã bị hoãn lại."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5873, 261, '2025/test8/audio/test8_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7423, 5873, 22, 'Could you tell me where the reference books are kept?', 'Any of the librarians.', 'They certainly are.', 'The shelves on your left.', NULL, 'C', 'Câu hỏi: Bạn có thể chỉ tôi nơi giữ sách tham khảo không?"
A: "Bất kỳ thư viện nào cũng có thể giúp."
B: "Chắc chắn rồi."
C: "Các kệ sách bên tay trái của bạn."
Giải thích: Đáp án C đúng vì câu hỏi về vị trí sách tham khảo và đáp án C chỉ rõ vị trí của các kệ sách bên tay trái."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5874, 261, '2025/test8/audio/test8_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7424, 5874, 23, 'What''s your store''s policy on refunds?', 'We stock several major brands.', 'You have to show your original receipt.', 'I have access to more funds.', NULL, 'B', 'Câu hỏi: Chính sách của cửa hàng bạn về hoàn tiền là gì?"
A: "Chúng tôi có bán một số thương hiệu lớn."
B: "Bạn cần phải có biên lai gốc để hoàn tiền."
C: "Tôi có quyền truy cập vào nhiều quỹ hơn."
Giải thích: Đáp án B đúng vì câu hỏi về chính sách hoàn tiền và đáp án B giải thích rằng bạn cần phải có biên lai gốc để được hoàn tiền."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5875, 261, '2025/test8/audio/test8_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7425, 5875, 24, 'All the information in the staff directory is up-to-date, isn''t it?', 'OK, I''ll mark the event dates on the calendar.', 'Some extension numbers may have changed.', 'The first line on the form is for your job title.', NULL, 'B', 'Câu hỏi: Tất cả thông tin trong danh bạ nhân viên đều được cập nhật, phải không?"
A: "Được rồi, tôi sẽ đánh dấu các ngày sự kiện trên lịch."
B: "Một số số nội bộ có thể đã thay đổi."
C: "Dòng đầu tiên trên mẫu là cho chức danh công việc của bạn."
Giải thích: Đáp án B đúng vì câu hỏi về thông tin trong danh bạ nhân viên và đáp án B giải thích rằng có thể đã có sự thay đổi trong số nội bộ."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5876, 261, '2025/test8/audio/test8_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7426, 5876, 25, 'When does the market research report need to be submitted?', 'A promising product idea, usually.', 'The director keeps moving the deadline.', 'Yes, I can see that.', NULL, 'B', 'Câu hỏi: Khi nào báo cáo nghiên cứu thị trường cần được nộp?"
A: "Một ý tưởng sản phẩm triển vọng, thường thì."
B: "Giám đốc cứ dời thời hạn nộp báo cáo."
C: "Vâng, tôi có thể thấy điều đó."
Giải thích: Đáp án B đúng vì câu hỏi về thời hạn nộp báo cáo và đáp án B cho biết giám đốc liên tục dời thời hạn nộp báo cáo."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5877, 261, '2025/test8/audio/test8_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7427, 5877, 26, 'There''s a refreshments table in the hallway.', 'I''m still full from breakfast.', 'He reserved a table for six.', 'The conference organizers.', NULL, 'A', 'Câu hỏi: Có một bàn đồ uống nhẹ trong hành lang." 
A: "Tôi vẫn cảm thấy no sau bữa sáng."
B: "Anh ấy đã đặt bàn cho sáu người."
C: "Những người tổ chức hội nghị."
Giải thích: Đáp án A đúng vì câu hỏi về việc có bàn đồ uống nhẹ và đáp án A cho biết người trả lời vẫn cảm thấy no sau bữa sáng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5878, 261, '2025/test8/audio/test8_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7428, 5878, 27, 'Why don''t we share a taxi to the airport?', 'At the entrance to the terminal.', 'Last year''s tax forms.', 'Would there be room for Na-Young, too?', NULL, 'C', 'Câu hỏi: Tại sao chúng ta không cùng đi taxi đến sân bay?"
A: "Tại cổng vào của nhà ga."
B: "Các mẫu thuế của năm ngoái."
C: "Liệu có chỗ cho Na-Young không?"
Giải thích: Đáp án C đúng vì câu hỏi về việc chia sẻ taxi và đáp án C hỏi về việc có đủ chỗ cho Na-Young trong taxi hay không."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5879, 261, '2025/test8/audio/test8_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7429, 5879, 28, 'Have you decided what you''re going to do with your annual bonus?', 'It''s the last Friday of the month.', 'I think she''s going to the parking lot.', 'I''m putting it in my savings account.', NULL, 'C', 'Câu hỏi: Bạn đã quyết định sẽ làm gì với khoản tiền thưởng hàng năm của mình chưa?"
A: "Đó là ngày thứ Sáu cuối cùng của tháng."
B: "Tôi nghĩ cô ấy đang đến bãi đậu xe."
C: "Tôi sẽ gửi vào tài khoản tiết kiệm của mình."
Giải thích: Đáp án C đúng vì câu hỏi về việc sử dụng tiền thưởng hàng năm và đáp án C cho biết người trả lời sẽ gửi vào tài khoản tiết kiệm."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5880, 261, '2025/test8/audio/test8_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7430, 5880, 29, 'Should I visit a pharmacy or a health food store to get vitamin supplements?', 'Supermarkets sell them, too.', 'The recommended amount.', 'Your updated medical records.', NULL, 'A', 'Câu hỏi: Tôi nên đến hiệu thuốc hay cửa hàng thực phẩm chức năng để mua bổ sung vitamin?"
A: "Cả siêu thị cũng bán chúng."
B: "Lượng vitamin được khuyến nghị."
C: "Hồ sơ y tế cập nhật của bạn."
Giải thích: Đáp án A đúng vì câu hỏi về nơi mua bổ sung vitamin và đáp án A đề xuất rằng bạn có thể mua tại siêu thị."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5881, 261, '2025/test8/audio/test8_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7431, 5881, 30, 'The video needs to be uploaded to social media today.', 'It was quite informative.', 'We haven''t added the music yet.', 'I mostly watch TV programs.', NULL, 'B', 'Câu hỏi: Video này cần được tải lên mạng xã hội hôm nay." 
A: "Nó khá thông tin."
B: "Chúng tôi chưa thêm nhạc."
C: "Tôi chủ yếu xem các chương trình truyền hình."
Giải thích: Đáp án B đúng vì câu hỏi về việc tải video lên mạng xã hội và đáp án B chỉ ra rằng video chưa được thêm nhạc, nên chưa thể tải lên."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5882, 261, '2025/test8/audio/test8_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7432, 5882, 31, 'Why does Leonard have so many plants in his office?', 'No, you don''t have to anymore.', 'Try this scheduling app for smartphones.', 'Everyone gets to decorate their own space.', NULL, 'C', 'Câu hỏi: Tại sao Leonard lại có nhiều cây trong văn phòng của mình?"
A: "Không, bạn không cần phải làm vậy nữa."
B: "Hãy thử ứng dụng lập lịch cho điện thoại thông minh."
C: "Mỗi người có thể trang trí không gian của mình."
Giải thích: Đáp án C đúng vì câu hỏi về lý do Leonard có nhiều cây trong văn phòng và đáp án C cho biết rằng mỗi người đều có thể trang trí không gian làm việc của mình."');;

-- Data for 2025 Test8 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5883, 262, '2025/test8/audio/test8_question_32_34.mp3', NULL, 'w-Am: Matteo, the waiting list for our custom-made shoes is now over six months long.
M-Au: Ever since that musician was photographed wearing a pair, we''ve had more business than we could handle.
w-Am: I was thinking it might be time to hire one or two employees to help us work a little faster.
M-Au: OK... I''m just worried that the quality of our shoes could suffer, since new workers probably won''t be as skilled as we are.
w-Am: Well, we could start by only giving them the easiest jobs, like polishing the finished shoes.
M-Au: Yes, that could work. Let''s write out everything involved in the process, from start to finish. That will make it easy to see which tasks could be delegated.', 'Nữ: Matteo, danh sách chờ đợi cho giày đặt riêng của chúng ta giờ đã kéo dài hơn sáu tháng.
Nam: Kể từ khi ca sĩ đó được chụp ảnh đi một đôi, chúng ta có nhiều đơn hàng hơn khả năng xử lý.
Nữ: Tôi nghĩ có lẽ đã đến lúc thuê một hoặc hai nhân viên để giúp chúng ta làm việc nhanh hơn một chút.
Nam: OK... Tôi chỉ lo lắng rằng chất lượng giày của chúng ta có thể bị ảnh hưởng, vì những nhân viên mới có thể không thành thạo như chúng ta.
Nữ: À, chúng ta có thể bắt đầu bằng cách chỉ giao cho họ những công việc dễ nhất, như đánh bóng giày đã hoàn thành.
Nam: Vâng, điều đó có thể được. Hãy viết ra tất cả các công đoạn trong quy trình, từ đầu đến cuối. Điều đó sẽ giúp dễ dàng thấy được những nhiệm vụ nào có thể giao phó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7433, 5883, 32, 'What are the speakers discussing?', 'Appointing a spokesperson', 'Relocating a storefront', 'Postponing some repairs', 'Meeting customer demand', 'D', 'Question: "What are the speakers discussing?" (Những người nói chuyện đang thảo luận về điều gì?)
A: Appointing a spokesperson (Bổ nhiệm người phát ngôn)
B: Relocating a storefront (Di dời mặt tiền cửa hàng)
C: Postponing some repairs (Hoãn một số sửa chữa)
D: Meeting customer demand (Đáp ứng nhu cầu khách hàng)

Họ đang thảo luận về cách đáp ứng nhu cầu khách hàng vì:
1. Danh sách chờ đợi giày đặt riêng đã kéo dài hơn 6 tháng
2. Họ có nhiều đơn hàng hơn có thể xử lý
3. Họ đang cân nhắc thuê thêm nhân viên để làm việc nhanh hơn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5884, 262, '2025/test8/audio/test8_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7434, 5884, 33, 'What is the man concerned about?', 'Paying for some expenses', 'Unpredictable market trends', 'Inconvenience to employees', 'A decrease in product quality', 'D', 'Question: "What is the man concerned about?" (Người đàn ông lo lắng về điều gì?)
A: Paying for some expenses (Chi trả một số chi phí)
B: Unpredictable market trends (Xu hướng thị trường không thể dự đoán)
C: Inconvenience to employees (Sự bất tiện cho nhân viên)
D: A decrease in product quality (Sự suy giảm chất lượng sản phẩm)

Người đàn ông lo lắng về việc chất lượng giày có thể bị ảnh hưởng khi thuê nhân viên mới: "I''m just worried that the quality of our shoes could suffer, since new workers probably won''t be as skilled as we are" (Tôi chỉ lo lắng rằng chất lượng giày của chúng ta có thể bị ảnh hưởng, vì những nhân viên mới có thể không thành thạo như chúng ta).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5885, 262, '2025/test8/audio/test8_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7435, 5885, 34, 'What does the man suggest doing?', 'Listing the steps of a process', 'Determining a budget limit', 'Involving staff in a decision', 'Attending an upcoming event', 'A', 'Question: "What does the man suggest doing?" (Người đàn ông đề xuất làm gì?)
A: Listing the steps of a process (Liệt kê các bước của một quy trình)
B: Determining a budget limit (Xác định giới hạn ngân sách)
C: Involving staff in a decision (Để nhân viên tham gia vào quyết định)
D: Attending an upcoming event (Tham dự một sự kiện sắp tới)

Người đàn ông đề xuất viết ra tất cả các bước trong quy trình: "Let''s write out everything involved in the process, from start to finish" (Hãy viết ra tất cả các công đoạn trong quy trình, từ đầu đến cuối).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5886, 262, '2025/test8/audio/test8_question_35_37.mp3', NULL, 'M-Cn: Patricia, do you have any pasta meals left? I just handed out my last one, but there are a lot of people left to serve.
w-Br: Sorry, I''m out too. I guess the new meal uptake prediction software isn''t working very well.
M-cn: No kidding. There''s going to be a lot of disappointed passengers at the back of the plane. We should give them some extra snacks to make up for it.
w-Br: That''s a good idea. I''ll try to memorize where the people who ask for pasta are sitting, so that I can bring them something later.', 'Nam: Patricia, chị còn suất mì ống nào không? Tôi vừa phát suất cuối cùng, nhưng còn nhiều người cần phục vụ.
Nữ: Xin lỗi, tôi cũng hết rồi. Tôi đoán phần mềm dự đoán suất ăn mới không hoạt động tốt lắm.
Nam: Đúng vậy. Sẽ có nhiều hành khách thất vọng ở phía sau máy bay. Chúng ta nên đưa cho họ một số đồ ăn nhẹ để bù đắp.
Nữ: Đó là ý kiến hay. Tôi sẽ cố gắng ghi nhớ vị trí ngồi của những người yêu cầu mì ống, để tôi có thể mang cho họ thứ gì đó sau.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7436, 5886, 35, 'What problem does the man report?', 'He has run out of some meals', 'He is unfamiliar with some software', 'An Internet connection is slow', 'Some utensils are missing', 'A', 'Question: "What problem does the man report?" (Người đàn ông báo cáo vấn đề gì?)
A: He has run out of some meals (Anh ấy đã hết một số suất ăn)
B: He is unfamiliar with some software (Anh ấy không quen với một phần mềm)
C: An Internet connection is slow (Kết nối Internet chậm)
D: Some utensils are missing (Thiếu một số dụng cụ)

Người đàn ông báo cáo rằng anh ấy đã hết suất mì ống để phục vụ: "I just handed out my last one, but there are a lot of people left to serve" (Tôi vừa phát suất cuối cùng, nhưng còn nhiều người cần phục vụ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5887, 262, '2025/test8/audio/test8_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7437, 5887, 36, 'Who most likely are the speakers?', 'Caterers', 'Tour guides', 'Flight attendants', 'Conference organizers', 'C', 'Question: "Who most likely are the speakers?" (Những người nói chuyện nhiều khả năng là ai?)
A: Caterers (Nhân viên phục vụ tiệc)
B: Tour guides (Hướng dẫn viên du lịch)
C: Flight attendants (Tiếp viên hàng không)
D: Conference organizers (Người tổ chức hội nghị)

Họ là tiếp viên hàng không vì:
1. Họ phục vụ suất ăn trên máy bay
2. Đề cập đến "passengers at the back of the plane" (hành khách ở phía sau máy bay)
3. Họ thảo luận về phần mềm dự đoán suất ăn cho chuyến bay');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5888, 262, '2025/test8/audio/test8_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7438, 5888, 37, 'What does the woman say she will try to do?', 'Inform some coworkers', 'Remember some seat locations', 'Find an extra box of supplies', 'Reset an electronic device', 'B', 'Question: "What does the woman say she will try to do?" (Người phụ nữ nói cô ấy sẽ cố gắng làm gì?)
A: Inform some coworkers (Thông báo cho một số đồng nghiệp)
B: Remember some seat locations (Ghi nhớ một số vị trí ghế)
C: Find an extra box of supplies (Tìm thêm một hộp vật tư)
D: Reset an electronic device (Khởi động lại một thiết bị điện tử)

Người phụ nữ nói cô ấy sẽ cố gắng ghi nhớ vị trí ngồi của những người yêu cầu mì ống: "I''ll try to memorize where the people who ask for pasta are sitting" (Tôi sẽ cố gắng ghi nhớ vị trí ngồi của những người yêu cầu mì ống).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5889, 262, '2025/test8/audio/test8_question_38_40.mp3', NULL, 'M-Au: Welcome to Sungshin Leather. Would you like help finding anything?
w-Br: Yes, I''m interested in buying a briefcase for my new job. I like how they have more carrying space than most handbags. My files would fit in there more easily.
M-Au: OK. This one here-the Wilkes Elite-is very popular with our female customers.
w-Br: Hmm... I see it doesn''t have a separate compartment for a laptop. I wouldn''t feel comfortable carrying my laptop in this.
M-Au: Well, you could buy a soft laptop cover to use inside the briefcase. That would provide enough protection.', 'Nam: Chào mừng đến với Sungshin Leather. Bạn có muốn được giúp tìm gì không?
Nữ: Vâng, tôi quan tâm đến việc mua một cặp tài liệu cho công việc mới của tôi. Tôi thích việc chúng có không gian đựng nhiều hơn hầu hết các túi xách. Các tập tài liệu của tôi sẽ vừa vặn hơn trong đó.
Nam: OK. Cái này đây - Wilkes Elite - rất được ưa chuộng bởi khách hàng nữ của chúng tôi.
Nữ: Hmm... Tôi thấy nó không có ngăn riêng cho laptop. Tôi sẽ không cảm thấy thoải mái khi mang laptop trong cái này.
Nam: À, bạn có thể mua một bao đựng laptop mềm để sử dụng bên trong cặp. Điều đó sẽ cung cấp đủ sự bảo vệ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7439, 5889, 38, 'Who most likely is the man?', 'A market researcher', 'A cleaning professional', 'A sales associate', 'A business journalist', 'C', 'Question: "Who most likely is the man?" (Người đàn ông nhiều khả năng là ai?)
A: A market researcher (Một nhà nghiên cứu thị trường)
B: A cleaning professional (Một chuyên gia vệ sinh)
C: A sales associate (Một nhân viên bán hàng)
D: A business journalist (Một nhà báo kinh doanh)

Người đàn ông là nhân viên bán hàng vì:
1. Anh ấy chào đón khách tại cửa hàng đồ da Sungshin
2. Anh ấy hỏi khách có cần giúp tìm gì không
3. Anh ấy giới thiệu và đề xuất sản phẩm cho khách');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5890, 262, '2025/test8/audio/test8_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7440, 5890, 39, 'What does the woman say she likes about a briefcase?', 'Its durable material', 'Its large capacity', 'Its attractive color', 'Its reasonable price', 'B', 'Question: "What does the woman say she likes about a briefcase?" (Người phụ nữ nói cô ấy thích điều gì về cặp tài liệu?)
A: Its durable material (Chất liệu bền của nó)
B: Its large capacity (Sức chứa lớn của nó)
C: Its attractive color (Màu sắc hấp dẫn của nó)
D: Its reasonable price (Giá cả hợp lý của nó)

Người phụ nữ nói cô ấy thích cặp tài liệu vì có không gian đựng nhiều hơn: "they have more carrying space than most handbags" (chúng có không gian đựng nhiều hơn hầu hết các túi xách).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5891, 262, '2025/test8/audio/test8_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7441, 5891, 40, 'What does the man recommend doing?', 'Purchasing an extra item', 'Visiting a special Web site', 'Speaking with his colleague', 'Trying out several briefcases', 'A', 'Question: "What does the man recommend doing?" (Người đàn ông đề xuất làm gì?)
A: Purchasing an extra item (Mua thêm một món đồ)
B: Visiting a special Web site (Truy cập một trang web đặc biệt)
C: Speaking with his colleague (Nói chuyện với đồng nghiệp của anh ấy)
D: Trying out several briefcases (Thử một số cặp tài liệu)

Người đàn ông đề xuất mua thêm một bao đựng laptop mềm: "you could buy a soft laptop cover to use inside the briefcase" (bạn có thể mua một bao đựng laptop mềm để sử dụng bên trong cặp).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5892, 262, '2025/test8/audio/test8_question_41_43.mp3', NULL, 'M-cn: Uh oh... I don''t see our bus listed on this sign.
M-Au: Really? But the hotel clerk said it passes by here.
M-Cn: Excuse me, ma''am, can we catch Bus 403 here?
w-Am: I''m not sure, but I could use the transportation app on my phone to find out.
M-Au: That would be great.
W-Am: OK... Oh, it stops at that platform in the middle of the street. And the next one''s in fifteen minutes.
M-Cn: Ah! Thank you. Well, Min-Jae, we''re going to be a little late to dinner. You''d better ask your friend to order for us.
M-Au: Yes, lI message him.', 'Nam 1: Ôi... Tôi không thấy xe buýt của chúng ta được liệt kê trên bảng này.
Nam 2: Thật sao? Nhưng nhân viên khách sạn nói nó đi qua đây.
Nam 1: Xin lỗi, thưa bà, chúng tôi có thể bắt xe buýt 403 ở đây không?
Nữ: Tôi không chắc, nhưng tôi có thể dùng ứng dụng giao thông trên điện thoại để tìm hiểu.
Nam 2: Như vậy thì tốt quá.
Nữ: OK... Ồ, nó dừng ở sân ga giữa đường kia. Và chuyến tiếp theo sẽ đến trong mười lăm phút.
Nam 1: Ah! Cảm ơn. À, Min-Jae, chúng ta sẽ đến bữa tối hơi muộn. Cậu nên nhắn bạn cậu gọi món cho chúng ta.
Nam 2: Vâng, tôi sẽ nhắn tin cho anh ấy.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7442, 5892, 41, 'Where does the conversation most likely take place?', 'On a train', 'At a bus stop', 'At a taxi stand', 'In an elevator', 'B', 'Question: "Where does the conversation most likely take place?" (Cuộc trò chuyện nhiều khả năng diễn ra ở đâu?)
A: On a train (Trên tàu)
B: At a bus stop (Tại trạm xe buýt)
C: At a taxi stand (Tại bến taxi)
D: In an elevator (Trong thang máy)

Cuộc trò chuyện diễn ra tại trạm xe buýt vì:
1. Họ đang tìm xe buýt số 403
2. Họ đang xem bảng hiệu lịch xe buýt
3. Được xác nhận là xe dừng ở sân ga giữa đường');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5893, 262, '2025/test8/audio/test8_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7443, 5893, 42, 'What does the woman offer to do?', 'Drive to a destination', 'Check a mobile app', 'Make a phone call', 'Draw a map', 'B', 'Question: "What does the woman offer to do?" (Người phụ nữ đề nghị làm gì?)
A: Drive to a destination (Lái xe đến một điểm đến)
B: Check a mobile app (Kiểm tra một ứng dụng di động)
C: Make a phone call (Gọi điện thoại)
D: Draw a map (Vẽ một bản đồ)

Người phụ nữ đề nghị sử dụng ứng dụng giao thông trên điện thoại để kiểm tra: "I could use the transportation app on my phone to find out" (tôi có thể dùng ứng dụng giao thông trên điện thoại để tìm hiểu).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5894, 262, '2025/test8/audio/test8_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7444, 5894, 43, 'What will Min-Jae ask his friend to do?', 'Stand outside a venue', 'Buy tickets for a show', 'Choose dishes for a meal', 'Confirm a street''s name', 'C', 'Question: "What will Min-Jae ask his friend to do?" (Min-Jae sẽ yêu cầu bạn của anh ấy làm gì?)
A: Stand outside a venue (Đứng bên ngoài địa điểm)
B: Buy tickets for a show (Mua vé cho một buổi diễn)
C: Choose dishes for a meal (Chọn món cho bữa ăn)
D: Confirm a street''s name (Xác nhận tên đường)

Min-Jae sẽ nhắn bạn gọi món cho họ vì họ sẽ đến muộn: "You''d better ask your friend to order for us" (Cậu nên nhắn bạn cậu gọi món cho chúng ta).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5895, 262, '2025/test8/audio/test8_question_44_46.mp3', NULL, 'M-Au: Nora, I heard you went to a seminar yesterday-how was it? Did you pick up anything that''ll be useful for the Bradbury project?
w-Br: No, but some of the information might come in handy in the future. The topic was designing lightweight bridges. We learned the latest recommendations for materials and structural forms.
M-Au: Interesting! I know some people find our continuing education requirements annoying, but I always enjoy fulfilling them. Oh, and you know you have to write an attendance report, right?
w-Br: Yes, but... this is my first time writing one.
M-Au: Gilberto on the compliance team can walk you through it.', 'Nam: Nora, tôi nghe nói chị đã đi dự hội thảo hôm qua - nó thế nào? Chị có học được điều gì hữu ích cho dự án Bradbury không?
Nữ: Không, nhưng một số thông tin có thể hữu ích trong tương lai. Chủ đề là thiết kế cầu nhẹ. Chúng tôi đã học các khuyến nghị mới nhất về vật liệu và hình thức kết cấu.
Nam: Thú vị! Tôi biết một số người thấy các yêu cầu giáo dục liên tục của chúng ta khó chịu, nhưng tôi luôn thích hoàn thành chúng. Ồ, và chị biết là chị phải viết báo cáo tham dự, đúng không?
Nữ: Vâng, nhưng... đây là lần đầu tiên tôi viết cái này.
Nam: Gilberto ở nhóm tuân thủ có thể hướng dẫn chị.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7445, 5895, 44, 'What did the woman do yesterday?', 'She drafted a project proposal', 'She applied for a mentorship program', 'She finished conducting some research', 'She took a professional development seminar', 'D', 'Question: "What did the woman do yesterday?" (Người phụ nữ đã làm gì hôm qua?)
A: She drafted a project proposal (Cô ấy soạn một đề xuất dự án)
B: She applied for a mentorship program (Cô ấy đăng ký chương trình cố vấn)
C: She finished conducting some research (Cô ấy hoàn thành một số nghiên cứu)
D: She took a professional development seminar (Cô ấy tham dự một hội thảo phát triển chuyên môn)

Người phụ nữ đã tham dự một hội thảo về thiết kế cầu nhẹ: "The topic was designing lightweight bridges. We learned the latest recommendations for materials and structural forms" (Chủ đề là thiết kế cầu nhẹ. Chúng tôi đã học các khuyến nghị mới nhất về vật liệu và hình thức kết cấu).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5896, 262, '2025/test8/audio/test8_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7446, 5896, 45, 'What kind of business do the speakers most likely work for?', 'An employment agency', 'A publishing company', 'An engineering firm', 'A financial institution', 'C', 'Question: "What kind of business do the speakers most likely work for?" (Những người nói chuyện nhiều khả năng làm việc cho loại hình doanh nghiệp nào?)
A: An employment agency (Một công ty tuyển dụng)
B: A publishing company (Một công ty xuất bản)
C: An engineering firm (Một công ty kỹ thuật)
D: A financial institution (Một tổ chức tài chính)

Họ làm việc cho một công ty kỹ thuật vì:
1. Họ tham dự hội thảo về thiết kế cầu
2. Thảo luận về vật liệu và hình thức kết cấu
3. Đề cập đến dự án có tính kỹ thuật (Bradbury project)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5897, 262, '2025/test8/audio/test8_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7447, 5897, 46, 'What does the woman say, "this is my first time writing one"?', 'To express excitement', 'To request some assistance', 'To complain about an assignment', 'To explain some mistakes', 'B', 'Question: "What does the woman say, ''this is my first time writing one''?" (Tại sao người phụ nữ nói "đây là lần đầu tiên tôi viết cái này"?)
A: To express excitement (Để bày tỏ sự phấn khích)
B: To request some assistance (Để yêu cầu sự giúp đỡ)
C: To complain about an assignment (Để phàn nàn về một nhiệm vụ)
D: To explain some mistakes (Để giải thích một số lỗi)

Người phụ nữ nói câu này để ngầm yêu cầu sự giúp đỡ vì chưa từng viết báo cáo tham dự trước đây. Người đàn ông hiểu ý này và đề xuất Gilberto có thể hướng dẫn cô ấy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5898, 262, '2025/test8/audio/test8_question_47_49.mp3', NULL, 'w-Br: Whew, that was a busy morning, wasn''t it? Hi, I''m Etsuko Mori. I run the Mori''s Berries booth at this farmer''s market. Could I chat with you for a moment about your business''s booth?
M-Cn: Sure. I could use a break from loading these produce crates.
w-Br: Well, I''m very impressed by this beautiful "Blackbird Farms" banner you''ve started hanging over the booth recently.
M-Cn: Thank you! It wasn''t cheap, but it seems to be worth the expense-weve had considerably more customers since putting it up.
w-Br: Oh, really? That''s what I wanted to ask about. I''m considering making a similar investment.
M-cn: Well, we were very happy with the print shop we used. Would you like its name?', 'Nữ: Phù, sáng nay bận rộn thật, phải không? Chào, tôi là Etsuko Mori. Tôi điều hành quầy Mori''s Berries tại chợ nông sản này. Tôi có thể nói chuyện với anh một lát về quầy kinh doanh của anh được không?
Nam: Được chứ. Tôi cũng cần nghỉ giải lao sau khi chuyển những thùng sản phẩm này.
Nữ: À, tôi rất ấn tượng với biển hiệu "Blackbird Farms" đẹp mà anh mới treo trên quầy gần đây.
Nam: Cảm ơn! Nó không rẻ, nhưng có vẻ đáng giá - chúng tôi có nhiều khách hàng hơn đáng kể kể từ khi treo nó lên.
Nữ: Ồ, thật sao? Đó là điều tôi muốn hỏi. Tôi đang cân nhắc đầu tư tương tự.
Nam: À, chúng tôi rất hài lòng với cửa hàng in ấn mà chúng tôi đã sử dụng. Chị có muốn biết tên không?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7448, 5898, 47, 'What industry do the speakers most likely work in?', 'Agriculture', 'Hospitality', 'Electronics', 'Construction', 'A', 'Question: "What industry do the speakers most likely work in?" (Những người nói chuyện nhiều khả năng làm việc trong ngành nào?)
A: Agriculture (Nông nghiệp)
B: Hospitality (Khách sạn nhà hàng)
C: Electronics (Điện tử)
D: Construction (Xây dựng)

Họ làm việc trong ngành nông nghiệp vì:
1. Người phụ nữ điều hành quầy trái cây Mori''s Berries
2. Người đàn ông đến từ Blackbird Farms
3. Họ bán hàng tại chợ nông sản
4. Đề cập đến việc chuyển các thùng sản phẩm nông sản');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5899, 262, '2025/test8/audio/test8_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7449, 5899, 48, 'What does the woman say about a business recently?', 'An executive retired', 'A Web site was upgraded', 'A new sign was put on display', 'A famous product was discontinued', 'C', 'Question: "What does the woman say about a business recently?" (Người phụ nữ nói gì về một doanh nghiệp gần đây?)
A: An executive retired (Một giám đốc đã nghỉ hưu)
B: A Web site was upgraded (Một trang web đã được nâng cấp)
C: A new sign was put on display (Một biển hiệu mới đã được trưng bày)
D: A famous product was discontinued (Một sản phẩm nổi tiếng đã ngừng sản xuất)

Người phụ nữ đề cập đến việc Blackbird Farms mới treo một biển hiệu đẹp: "this beautiful ''Blackbird Farms'' banner you''ve started hanging over the booth recently" (biển hiệu "Blackbird Farms" đẹp mà anh mới treo trên quầy gần đây).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5900, 262, '2025/test8/audio/test8_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7450, 5900, 49, 'What does the man offer the woman?', 'Some printouts', 'Some samples', 'A special discount', 'A business referral', 'D', 'Question: "What does the man offer the woman?" (Người đàn ông đề nghị gì cho người phụ nữ?)
A: Some printouts (Một số bản in)
B: Some samples (Một số mẫu)
C: A special discount (Một ưu đãi đặc biệt)
D: A business referral (Một giới thiệu doanh nghiệp)

Người đàn ông đề nghị cung cấp tên của cửa hàng in ấn mà họ đã sử dụng: "we were very happy with the print shop we used. Would you like its name?" (chúng tôi rất hài lòng với cửa hàng in ấn mà chúng tôi đã sử dụng. Chị có muốn biết tên không?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5901, 262, '2025/test8/audio/test8_question_50_52.mp3', NULL, 'W-Am: Alvin, what''s your opinion on the big change that the owner told us about this morning?
M-Au: I was late to work today.
w-Am: Ah, I didn''t realize that. Well, she''s going to hire a Spanish-speaking driving instructor so that we can expand our customer base.
M-Au: Interesting! Hmm...my only concern would be the level of customer service we could provide to Spanish-speaking students. Because of the language barrier, our office staff wouldn''t be able to do things like answering their inquiries.', 'Nữ: Alvin, ý kiến của anh về thay đổi lớn mà chủ doanh nghiệp đã nói với chúng ta sáng nay là gì?
Nam: Hôm nay tôi đi làm muộn.
Nữ: À, tôi không biết điều đó. Vâng, bà ấy sẽ thuê một giáo viên dạy lái xe nói tiếng Tây Ban Nha để chúng ta có thể mở rộng cơ sở khách hàng.
Nam: Thú vị! Hmm... mối quan ngại duy nhất của tôi là mức độ dịch vụ khách hàng mà chúng ta có thể cung cấp cho học viên nói tiếng Tây Ban Nha. Vì rào cản ngôn ngữ, nhân viên văn phòng của chúng ta sẽ không thể làm những việc như trả lời thắc mắc của họ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7451, 5901, 50, 'What does the man mean when he says, "I was late to work today"?', 'He has not met a new colleague yet', 'He was negatively affected by a change', 'He was not present for an announcement', 'He is behind schedule on an assignment', 'C', 'Question: "What does the man mean when he says, ''I was late to work today''?" (Người đàn ông có ý gì khi nói "Hôm nay tôi đi làm muộn"?)
A: He has not met a new colleague yet (Anh ấy chưa gặp đồng nghiệp mới)
B: He was negatively affected by a change (Anh ấy bị ảnh hưởng tiêu cực bởi một thay đổi)
C: He was not present for an announcement (Anh ấy đã không có mặt khi có thông báo)
D: He is behind schedule on an assignment (Anh ấy bị trễ tiến độ một nhiệm vụ)

Khi nói "I was late to work today", người đàn ông ngụ ý rằng anh ấy đã không có mặt khi chủ doanh nghiệp thông báo về thay đổi lớn vào buổi sáng. Điều này được xác nhận khi người phụ nữ phải giải thích lại nội dung thông báo cho anh ấy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5902, 262, '2025/test8/audio/test8_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7452, 5902, 51, 'Where do the speakers most likely work?', 'At a driving school', 'At a recording studio', 'At a translation firm', 'At a medical clinic', 'A', 'Question: "Where do the speakers most likely work?" (Những người nói chuyện nhiều khả năng làm việc ở đâu?)
A: At a driving school (Tại một trường dạy lái xe)
B: At a recording studio (Tại một studio ghi âm)
C: At a translation firm (Tại một công ty dịch thuật)
D: At a medical clinic (Tại một phòng khám)

Họ làm việc tại một trường dạy lái xe vì:
1. Họ thảo luận về việc thuê một giáo viên dạy lái xe nói tiếng Tây Ban Nha
2. Có đề cập đến học viên (students)
3. Muốn mở rộng cơ sở khách hàng bằng cách phục vụ thêm nhóm khách hàng nói tiếng Tây Ban Nha');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5903, 262, '2025/test8/audio/test8_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7453, 5903, 52, 'What does the man say he is worried about?', 'Hiring too many workers', 'Obtaining enough supplies', 'Offering poor customer service', 'Revising some materials quickly', 'C', 'Question: "What does the man say he is worried about?" (Người đàn ông nói anh ấy lo lắng về điều gì?)
A: Hiring too many workers (Thuê quá nhiều nhân viên)
B: Obtaining enough supplies (Có đủ vật tư)
C: Offering poor customer service (Cung cấp dịch vụ khách hàng kém)
D: Revising some materials quickly (Sửa đổi tài liệu nhanh chóng)

Người đàn ông lo lắng về chất lượng dịch vụ khách hàng dành cho học viên nói tiếng Tây Ban Nha: "my only concern would be the level of customer service we could provide to Spanish-speaking students" vì rào cản ngôn ngữ sẽ khiến nhân viên văn phòng không thể trả lời thắc mắc của họ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5904, 262, '2025/test8/audio/test8_question_53_55.mp3', NULL, 'M-cn: OK, Yoo-Jin and Sheryl. You''ve now learned how to use our factory''s machines to make fabric. Today, we''re going to talk about what to do to keep them in good condition.
w-Am: We''re supposed to apply oil to some of the parts before each shift, right?
w-Br: Oh yes-because the oil keeps those parts from grinding against each other.
M-Cn: That''s correct. But it''s important to note that the parts will eventually wear out anyway. So another important task is inspecting them to determine whether they should be replaced.
W-Am: How will we be able to tell if they''re worn out?
M-cn: Well, let''s start with the cutter component. Here''re some photos of its blade taken a few weeks apart. Tell me what differences you see between them.', 'Nam: OK, Yoo-Jin và Sheryl. Bây giờ các bạn đã học cách sử dụng máy móc trong nhà máy của chúng ta để làm vải. Hôm nay, chúng ta sẽ nói về những việc cần làm để giữ chúng trong tình trạng tốt.
Nữ 1: Chúng ta phải bôi dầu vào một số bộ phận trước mỗi ca làm việc, đúng không?
Nữ 2: Ồ đúng vậy - bởi vì dầu giúp những bộ phận đó không bị ma sát với nhau.
Nam: Đúng vậy. Nhưng điều quan trọng cần lưu ý là các bộ phận cuối cùng vẫn sẽ bị mòn. Vì vậy một nhiệm vụ quan trọng khác là kiểm tra chúng để xác định xem có nên thay thế không.
Nữ 1: Làm sao chúng tôi có thể biết nếu chúng bị mòn?
Nam: Được rồi, hãy bắt đầu với bộ phận cắt. Đây là một số ảnh của lưỡi cắt được chụp cách nhau vài tuần. Hãy nói cho tôi biết những khác biệt các bạn thấy giữa chúng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7454, 5904, 53, 'What industry are the women training to work in?', 'Fashion retail', 'Laundry services', 'Clothing alteration', 'Textile manufacturing', 'D', 'Question: "What industry are the women training to work in?" (Những người phụ nữ đang được đào tạo để làm việc trong ngành nào?)
A: Fashion retail (Bán lẻ thời trang)
B: Laundry services (Dịch vụ giặt là)
C: Clothing alteration (Sửa đổi quần áo)
D: Textile manufacturing (Sản xuất dệt may)

Họ đang được đào tạo trong ngành sản xuất dệt may vì:
1. Họ đang học cách sử dụng máy móc trong nhà máy để làm vải
2. Thảo luận về bảo dưỡng máy và các bộ phận như lưỡi cắt
3. Đang trong môi trường sản xuất công nghiệp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5905, 262, '2025/test8/audio/test8_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7455, 5905, 54, 'What are the speakers mainly discussing?', 'Customer complaints', 'Equipment maintenance', 'Workspace layouts', 'Shift scheduling', 'B', 'Question: "What are the speakers mainly discussing?" (Những người nói chuyện đang thảo luận chủ yếu về điều gì?)
A: Customer complaints (Khiếu nại của khách hàng)
B: Equipment maintenance (Bảo dưỡng thiết bị)
C: Workspace layouts (Bố trí không gian làm việc)
D: Shift scheduling (Lên lịch ca làm việc)

Họ đang thảo luận về bảo dưỡng thiết bị, bao gồm:
1. Bôi dầu các bộ phận trước mỗi ca
2. Kiểm tra độ mòn của các bộ phận
3. Xác định thời điểm cần thay thế bộ phận');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5906, 262, '2025/test8/audio/test8_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7456, 5906, 55, 'What will the women do next?', 'Practice a procedure', 'Watch a demonstration', 'Read some instructions', 'Look at some photographs', 'D', 'Question: "What will the women do next?" (Những người phụ nữ sẽ làm gì tiếp theo?)
A: Practice a procedure (Thực hành một quy trình)
B: Watch a demonstration (Xem một bài thị phạm)
C: Read some instructions (Đọc một số hướng dẫn)
D: Look at some photographs (Xem một số bức ảnh)

Người phụ nữ sẽ xem và so sánh các bức ảnh về lưỡi cắt được chụp cách nhau vài tuần: "Here''re some photos of its blade taken a few weeks apart. Tell me what differences you see between them" (Đây là một số ảnh của lưỡi cắt được chụp cách nhau vài tuần. Hãy nói cho tôi biết những khác biệt các bạn thấy giữa chúng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5907, 262, '2025/test8/audio/test8_question_56_58.mp3', NULL, 'w-Am: Hello, Mr. Brock. This is Julia Bailey from Bailey Antiques. I''m calling about the appraisal service you requested. Would Wednesday at four P.M. work for you?
M-Au: Yes, I can be home then.
w-Am: Excellent. When we finish this call, please send me your address by text message.
M-Au: OK, but l''ll include some directions too, because our house can be hard to find the first time.
W-Am: I see. Oh, and along with your antiques, don''t forget to prepare any documentation you have for the age or authenticity of the items.', 'Nữ: Xin chào, ông Brock. Tôi là Julia Bailey từ Bailey Antiques. Tôi gọi về dịch vụ định giá mà ông đã yêu cầu. Thứ Tư lúc 4 giờ chiều có được không?
Nam: Vâng, lúc đó tôi có thể ở nhà.
Nữ: Tuyệt. Khi chúng ta kết thúc cuộc gọi này, xin vui lòng gửi cho tôi địa chỉ của ông qua tin nhắn.
Nam: OK, nhưng tôi sẽ kèm theo cả chỉ dẫn đường đi, vì nhà chúng tôi có thể khó tìm trong lần đầu tiên.
Nữ: Tôi hiểu. À, và cùng với đồ cổ của ông, đừng quên chuẩn bị bất kỳ tài liệu nào ông có về tuổi hoặc tính xác thực của các món đồ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7457, 5907, 56, 'Why is the woman calling the man?', 'To discuss a payment', 'To arrange a consultation', 'To provide an order update', 'To follow up on some feedback', 'B', 'Question: "Why is the woman calling the man?" (Tại sao người phụ nữ gọi cho người đàn ông?)
A: To discuss a payment (Để thảo luận về thanh toán)
B: To arrange a consultation (Để sắp xếp một buổi tư vấn)
C: To provide an order update (Để cập nhật về đơn hàng)
D: To follow up on some feedback (Để theo dõi phản hồi)

Người phụ nữ gọi để sắp xếp lịch hẹn đánh giá đồ cổ: "I''m calling about the appraisal service you requested. Would Wednesday at four P.M. work for you?" (Tôi gọi về dịch vụ định giá mà ông đã yêu cầu. Thứ Tư lúc 4 giờ chiều có được không?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5908, 262, '2025/test8/audio/test8_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7458, 5908, 57, 'What information does the woman ask the man to send her?', 'A home address', 'A credit card number', 'Design preferences', 'Space measurements', 'A', 'Question: "What information does the woman ask the man to send her?" (Người phụ nữ yêu cầu người đàn ông gửi thông tin gì cho cô ấy?)
A: A home address (Địa chỉ nhà)
B: A credit card number (Số thẻ tín dụng)
C: Design preferences (Sở thích thiết kế)
D: Space measurements (Kích thước không gian)

Người phụ nữ yêu cầu người đàn ông gửi địa chỉ nhà qua tin nhắn: "please send me your address by text message" (xin vui lòng gửi cho tôi địa chỉ của ông qua tin nhắn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5909, 262, '2025/test8/audio/test8_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7459, 5909, 58, 'What does the woman remind the man to do?', 'Move any parked vehicles', 'Prepare some paperwork', 'Complete a transaction', 'Check his mail frequently', 'B', 'Question: "What does the woman remind the man to do?" (Người phụ nữ nhắc người đàn ông làm gì?)
A: Move any parked vehicles (Di chuyển các phương tiện đang đậu)
B: Prepare some paperwork (Chuẩn bị một số giấy tờ)
C: Complete a transaction (Hoàn thành một giao dịch)
D: Check his mail frequently (Kiểm tra thư thường xuyên)

Người phụ nữ nhắc người đàn ông chuẩn bị tài liệu về tuổi và tính xác thực của các món đồ cổ: "don''t forget to prepare any documentation you have for the age or authenticity of the items" (đừng quên chuẩn bị bất kỳ tài liệu nào ông có về tuổi hoặc tính xác thực của các món đồ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5910, 262, '2025/test8/audio/test8_question_59_61.mp3', NULL, 'M-cn: Denniston Historic Estate visitors'' assistance.
w-Br: Hi, I''m hoping to visit the estate, but I can''t seem to reserve a tour spot through your Web site. Nothing happens when I click the green button.
M-Cn: Are you using Exult to access our site? If so, you need to uncheck the box next to the address bar. Otherwise, the program won''t allow pop-up windows.
w-Br: OK... yes, that solved the problem. Thank you!
Oh, and just to check-the tour will include a visit to the estate''s guest cottage, right?
M-cn: Yes, near the end.
w-Br: Good. A client asked me to use the cottage''s style as inspiration while redecorating his house, so I really need to see it.', 'Nam: Bộ phận hỗ trợ khách tham quan Di sản Lịch sử Denniston.
Nữ: Chào, tôi hy vọng được tham quan khu di sản, nhưng dường như tôi không thể đặt chỗ tham quan qua trang web của các bạn. Không có gì xảy ra khi tôi nhấp vào nút xanh.
Nam: Bạn có đang sử dụng Exult để truy cập trang web của chúng tôi không? Nếu vậy, bạn cần bỏ chọn ô bên cạnh thanh địa chỉ. Nếu không, chương trình sẽ không cho phép cửa sổ pop-up.
Nữ: OK... vâng, điều đó đã giải quyết vấn đề. Cảm ơn!
À, và chỉ để kiểm tra - chuyến tham quan sẽ bao gồm việc thăm nhà khách của khu di sản, đúng không?
Nam: Vâng, gần cuối chuyến tham quan.
Nữ: Tốt. Một khách hàng yêu cầu tôi sử dụng phong cách của nhà khách làm nguồn cảm hứng khi trang trí lại nhà của anh ấy, vì vậy tôi thực sự cần xem nó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7460, 5910, 59, 'Why is the woman calling?', 'She is disappointed with a virtual tour', 'She found inaccurate information on a Web site', 'She cannot make a reservation online', 'She did not receive a confirmation e-mail', 'C', 'Question: "Why is the woman calling?" (Tại sao người phụ nữ gọi điện?)
A: She is disappointed with a virtual tour (Cô ấy thất vọng về tour ảo)
B: She found inaccurate information on a Web site (Cô ấy tìm thấy thông tin không chính xác trên trang web)
C: She cannot make a reservation online (Cô ấy không thể đặt chỗ trực tuyến)
D: She did not receive a confirmation e-mail (Cô ấy không nhận được email xác nhận)

Người phụ nữ gọi điện vì không thể đặt chỗ tham quan qua trang web: "I can''t seem to reserve a tour spot through your Web site. Nothing happens when I click the green button" (Tôi dường như không thể đặt chỗ tham quan qua trang web của các bạn. Không có gì xảy ra khi tôi nhấp vào nút xanh).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5911, 262, '2025/test8/audio/test8_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7461, 5911, 60, 'What does the man tell the woman about?', 'An improvement project', 'A computer program setting', 'A membership requirement', 'A cancellation policy', 'B', 'Question: "What does the man tell the woman about?" (Người đàn ông nói với người phụ nữ về điều gì?)
A: An improvement project (Một dự án cải thiện)
B: A computer program setting (Một cài đặt chương trình máy tính)
C: A membership requirement (Một yêu cầu thành viên)
D: A cancellation policy (Một chính sách hủy)

Người đàn ông hướng dẫn người phụ nữ về cài đặt chương trình Exult: "you need to uncheck the box next to the address bar. Otherwise, the program won''t allow pop-up windows" (bạn cần bỏ chọn ô bên cạnh thanh địa chỉ. Nếu không, chương trình sẽ không cho phép cửa sổ pop-up).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5912, 262, '2025/test8/audio/test8_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7462, 5912, 61, 'What most likely is the woman''s job?', 'Historian', 'Landscaper', 'Interior decorator', 'Event planner', 'C', 'Question: "What most likely is the woman''s job?" (Người phụ nữ nhiều khả năng làm nghề gì?)
A: Historian (Nhà sử học)
B: Landscaper (Nhà thiết kế cảnh quan)
C: Interior decorator (Nhà thiết kế nội thất)
D: Event planner (Người tổ chức sự kiện)

Người phụ nữ nhiều khả năng là nhà thiết kế nội thất vì:
1. Một khách hàng yêu cầu cô ấy lấy cảm hứng từ phong cách nhà khách để trang trí lại nhà: "A client asked me to use the cottage''s style as inspiration while redecorating his house"
2. Cô ấy cần xem nhà khách để phục vụ cho công việc thiết kế');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5913, 262, '2025/test8/audio/test8_question_62_64.mp3', '2025/test8/image/test8-p3-image-62.jpg', 'M-Au: Fredericks Photography, Akio speaking.
w-Am: Hi, I''m interested in getting some new acting headshots taken. I don''t think my current photos give a good sense of my abilities as an actress.
M-Au: Our photographers can certainly work with you to get some shots you''re happy with. How many different images do you want?
W-Am: Four should be enough. And just digital files, please.
M-Au: Alright. Uh, I''ll need to book your studio session for over an hour... I see an opening on Thursday at three.
W-Am: Perfect. Oh, and do you provide hair and makeup services? If so, l''d like to book those as well.', 'Nam: Fredericks Photography, Akio xin nghe.
Nữ: Chào, tôi quan tâm đến việc chụp ảnh headshots mới cho diễn xuất. Tôi nghĩ những bức ảnh hiện tại của tôi không thể hiện tốt khả năng diễn xuất của tôi.
Nam: Các nhiếp ảnh gia của chúng tôi chắc chắn có thể làm việc với chị để có những bức ảnh chị hài lòng. Chị muốn bao nhiêu ảnh khác nhau?
Nữ: Bốn ảnh là đủ. Và chỉ cần file kỹ thuật số thôi.
Nam: Được rồi. À, tôi sẽ cần đặt lịch chụp studio của chị hơn một giờ... Tôi thấy có lịch trống vào thứ Năm lúc 3 giờ.
Nữ: Hoàn hảo. À, và các anh có cung cấp dịch vụ làm tóc và trang điểm không? Nếu có, tôi muốn đặt cả những dịch vụ đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7463, 5913, 62, 'What field does the woman work in?', 'Photography', 'Entertainment', 'Real estate', 'Law', 'B', 'Question: "What field does the woman work in?" (Người phụ nữ làm việc trong lĩnh vực nào?)
A: Photography (Nhiếp ảnh)
B: Entertainment (Giải trí)
C: Real estate (Bất động sản)
D: Law (Luật)

Người phụ nữ làm việc trong lĩnh vực giải trí vì:
1. Cô ấy là một diễn viên: "my abilities as an actress"
2. Cô ấy muốn chụp ảnh headshots mới cho công việc diễn xuất
3. Headshots là loại ảnh chân dung thường được sử dụng trong ngành giải trí');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5914, 262, '2025/test8/audio/test8_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7464, 5914, 63, 'Look at the graphic. How much will the woman pay for her photo package?', '$100', '$190', '$270', '$340', 'D', 'Question: "Look at the graphic. How much will the woman pay for her photo package?" (Nhìn vào hình. Người phụ nữ sẽ trả bao nhiêu tiền cho gói chụp ảnh của cô ấy?)
A: $100 (100 đô)
B: $190 (190 đô)
C: $270 (270 đô)
D: $340 (340 đô)

Theo bảng giá trong hình, gói chụp 4 ảnh với thời gian chụp 75 phút có giá $340. Người phụ nữ đã yêu cầu "Four should be enough" (Bốn ảnh là đủ) và người đàn ông nói cần đặt lịch hơn một giờ.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5915, 262, '2025/test8/audio/test8_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7465, 5915, 64, 'What does the woman ask the man about?', 'Additional services', 'Payment methods', 'A wait time', 'A clothing choice', 'A', 'Question: "What does the woman ask the man about?" (Người phụ nữ hỏi người đàn ông về điều gì?)
A: Additional services (Các dịch vụ bổ sung)
B: Payment methods (Phương thức thanh toán)
C: A wait time (Thời gian chờ đợi)
D: A clothing choice (Lựa chọn trang phục)

Người phụ nữ hỏi về dịch vụ làm tóc và trang điểm bổ sung: "do you provide hair and makeup services? If so, l''d like to book those as well" (các anh có cung cấp dịch vụ làm tóc và trang điểm không? Nếu có, tôi muốn đặt cả những dịch vụ đó).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5916, 262, '2025/test8/audio/test8_question_65_67.mp3', '2025/test8/image/test8-p3-image-65.jpg', 'M-Cn: Thanks for agreeing to come in on your usual day off, Amber.
w-Br: No problem. I understand that it takes a lot of effort to get the store ready for holidays like this one.
M-cn: Right. So, I made a list of what we need to get done today. Here it is.
w-Br: Hmm... making an attractive window display is important, right? Why don''t you focus on that while I tackle these other tasks?
M-cn: OK, but I need the new holiday merchandise to put into the display, so I''ll unpack that first.
w-Br: Got it. And- before we start, why don''t I put on some music for us to listen to?', 'Nam: Cảm ơn vì đã đồng ý đến làm vào ngày nghỉ thường lệ của em, Amber.
Nữ: Không sao đâu. Em hiểu rằng cần rất nhiều nỗ lực để chuẩn bị cửa hàng cho những ngày lễ như thế này.
Nam: Đúng vậy. Vì vậy, anh đã lập danh sách những việc chúng ta cần làm hôm nay. Đây này.
Nữ: Hmm... việc tạo ra một cửa sổ trưng bày hấp dẫn là quan trọng, đúng không? Sao anh không tập trung vào việc đó trong khi em giải quyết những nhiệm vụ khác này?
Nam: OK, nhưng anh cần hàng hóa mới cho ngày lễ để đặt vào phần trưng bày, vì vậy anh sẽ mở hàng trước.
Nữ: Hiểu rồi. Và - trước khi chúng ta bắt đầu, sao em không bật nhạc cho chúng ta nghe nhỉ?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7466, 5916, 65, 'Why did the man ask the woman to work today?', 'A lot of customers are expected today', 'He wants to teach her how to do a task', 'Another worker had to take a day off', 'They need to prepare the store for a holiday', 'D', 'Question: "Why did the man ask the woman to work today?" (Tại sao người đàn ông nhờ người phụ nữ đi làm hôm nay?)
A: A lot of customers are expected today (Hôm nay dự kiến có nhiều khách hàng)
B: He wants to teach her how to do a task (Anh ấy muốn dạy cô ấy cách làm một nhiệm vụ)
C: Another worker had to take a day off (Một nhân viên khác phải nghỉ làm)
D: They need to prepare the store for a holiday (Họ cần chuẩn bị cửa hàng cho một ngày lễ)

Họ cần chuẩn bị cửa hàng cho ngày lễ, được thể hiện qua:
1. Người phụ nữ nói: "it takes a lot of effort to get the store ready for holidays like this one"
2. Có đề cập đến "new holiday merchandise" (hàng hóa mới cho ngày lễ)
3. Cần trang trí cửa sổ trưng bày mới');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5917, 262, '2025/test8/audio/test8_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7467, 5917, 66, 'Look at the graphic. Which task will the man do first?', 'Task 1', 'Task 2', 'Task 3', 'Task 4', 'B', 'Question: "Look at the graphic. Which task will the man do first?" (Nhìn vào hình. Người đàn ông sẽ làm nhiệm vụ nào đầu tiên?)
A: Task 1 (Nhiệm vụ 1)
B: Task 2 (Nhiệm vụ 2)
C: Task 3 (Nhiệm vụ 3)
D: Task 4 (Nhiệm vụ 4)

Người đàn ông sẽ làm Nhiệm vụ 2 (mở hàng mới) đầu tiên vì anh ấy nói: "I need the new holiday merchandise to put into the display, so I''ll unpack that first" (anh cần hàng hóa mới cho ngày lễ để đặt vào phần trưng bày, vì vậy anh sẽ mở hàng trước).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5918, 262, '2025/test8/audio/test8_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7468, 5918, 67, 'What does the woman suggest doing before they start?', 'Buying some refreshments', 'Opening the windows', 'Turning on some music', 'Putting on gloves', 'C', 'Question: "What does the woman suggest doing before they start?" (Người phụ nữ đề xuất làm gì trước khi họ bắt đầu?)
A: Buying some refreshments (Mua đồ giải khát)
B: Opening the windows (Mở cửa sổ)
C: Turning on some music (Bật nhạc)
D: Putting on gloves (Đeo găng tay)

Người phụ nữ đề xuất bật nhạc trước khi họ bắt đầu làm việc: "why don''t I put on some music for us to listen to?" (sao em không bật nhạc cho chúng ta nghe nhỉ?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5919, 262, '2025/test8/audio/test8_question_68_70.mp3', '2025/test8/image/test8-p3-image-68.jpg', 'M-Cn: Welcome to Upshaw Hotel. Are you checking in?
W-Am: No, I''m here to have dinner with a business associate who''s staying with you. But my mobile phone''s out of power. Would you mind calling her and letting her know I''ve arrived? She''s in Room 306.
M-Cn: Sure. Could you give me your name? I''l need to tell her who''s waiting for her in the lobby.
W-Am: Oh, actually, we''re eating in your restaurant, so ask her to meet me there. And my name''s Lydia Fisher.', 'Nam: Chào mừng đến với Khách sạn Upshaw. Chị check-in phải không?
Nữ: Không, tôi đến đây để ăn tối với một đối tác kinh doanh đang ở tại khách sạn của các anh. Nhưng điện thoại di động của tôi hết pin. Anh có thể gọi cho cô ấy và cho cô ấy biết tôi đã đến được không? Cô ấy ở Phòng 306.
Nam: Được. Chị có thể cho tôi biết tên của chị không? Tôi cần nói cho cô ấy biết ai đang đợi cô ấy ở sảnh.
Nữ: Ồ, thực ra, chúng tôi sẽ ăn ở nhà hàng của các anh, vậy hãy nhờ cô ấy gặp tôi ở đó. Và tên tôi là Lydia Fisher.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7469, 5919, 68, 'Why has the woman come to the hotel?', 'For a job interview', 'For a business dinner', 'For an equipment repair', 'For an overnight stay', 'B', 'Question: "Why has the woman come to the hotel?" (Tại sao người phụ nữ đến khách sạn?)
A: For a job interview (Để phỏng vấn việc làm)
B: For a business dinner (Để ăn tối với đối tác)
C: For an equipment repair (Để sửa thiết bị)
D: For an overnight stay (Để ở qua đêm)

Người phụ nữ đến khách sạn để ăn tối với một đối tác kinh doanh: "I''m here to have dinner with a business associate who''s staying with you" (Tôi đến đây để ăn tối với một đối tác kinh doanh đang ở tại khách sạn của các anh).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5920, 262, '2025/test8/audio/test8_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7470, 5920, 69, 'Who does the man agree to contact?', 'A current guest', 'A maintenance supervisor', 'A parking attendant', 'A hotel manager', 'A', 'Question: "Who does the man agree to contact?" (Người đàn ông đồng ý liên hệ với ai?)
A: A current guest (Một khách đang ở)
B: A maintenance supervisor (Một giám sát bảo trì)
C: A parking attendant (Một nhân viên đỗ xe)
D: A hotel manager (Một quản lý khách sạn)

Người đàn ông đồng ý liên hệ với một khách đang ở tại phòng 306: "She''s in Room 306" và anh ấy nói "I''ll need to tell her who''s waiting for her" (Tôi cần nói cho cô ấy biết ai đang đợi).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5921, 262, '2025/test8/audio/test8_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7471, 5921, 70, 'Look at the graphic. Which floor will the woman most likely go to next?', 'Floor 1', 'Floor 2', 'Floor 3', 'Floor 4', 'B', 'Question: "Look at the graphic. Which floor will the woman most likely go to next?" (Nhìn vào hình. Người phụ nữ nhiều khả năng sẽ đi đến tầng nào tiếp theo?)
A: Floor 1 (Tầng 1)
B: Floor 2 (Tầng 2)
C: Floor 3 (Tầng 3)
D: Floor 4 (Tầng 4)

Người phụ nữ sẽ đến Tầng 2 vì:
1. Tầng 2 là nhà hàng theo sơ đồ khách sạn
2. Cô ấy nói sẽ ăn tối ở nhà hàng của khách sạn: "we''re eating in your restaurant"
3. Cô ấy yêu cầu đối tác gặp cô ấy ở đó');;

-- Data for 2025 Test8 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5922, 263, '2025/test8/audio/test8_question_71_73.mp3', NULL, 'First, I want to thank Wenston Bookstore for holding this reading. It''s always a pleasure to come here and introduce my books to this enthusiastic audience. I''m especially excited to be bringing you this one. It''s titled Write for Yourself, and it''s a collection of helpful tips I''ve picked up over the decades. While it''s mainly for aspiring writers, I think my fans will also enjoy its insights into the creation of some of my stories. Alright, let''s dive in. Here''s an excerpt from the introduction.', 'Trước tiên, tôi muốn cảm ơn Hiệu sách Wenston đã tổ chức buổi đọc này. Thật luôn là niềm vui khi đến đây và giới thiệu sách của tôi cho khán giả nhiệt tình này. Tôi đặc biệt phấn khích được mang đến cho các bạn cuốn sách này. Nó có tựa đề là Write for Yourself (Viết cho Chính Mình), và nó là một tập hợp các lời khuyên hữu ích mà tôi đã thu thập được qua nhiều thập kỷ. Mặc dù nó chủ yếu dành cho những người muốn trở thành nhà văn, tôi nghĩ những người hâm mộ của tôi cũng sẽ thích những hiểu biết sâu sắc về quá trình sáng tạo một số câu chuyện của tôi. Được rồi, hãy bắt đầu nào. Đây là một đoạn trích từ phần giới thiệu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7472, 5922, 71, 'Who most likely is the speaker?', 'An author', 'A bookstore clerk', 'A university professor', 'A museum guide', 'A', '[Dịch] Câu hỏi: Người nói có khả năng là ai?
A: Một tác giả
B: Một nhân viên hiệu sách
C: Một giáo sư đại học
D: Một hướng dẫn viên bảo tàng

Đáp án A là chính xác vì người nói đang giới thiệu "my books" (sách của tôi) và nói về quá trình sáng tác của mình, cho thấy đây là một tác giả.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5923, 263, '2025/test8/audio/test8_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7473, 5923, 72, 'What does the speaker mention about the book?', 'It is unusually old.', 'It is in good condition.', 'It contains useful advice.', 'It is very popular.', 'C', '[Dịch] Câu hỏi: Người nói đề cập điều gì về cuốn sách?
A: Nó cực kỳ cũ
B: Nó trong tình trạng tốt
C: Nó chứa lời khuyên hữu ích
D: Nó rất phổ biến

Đáp án C là chính xác vì người nói mô tả cuốn sách là "a collection of helpful tips" (một tập hợp các lời khuyên hữu ích).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5924, 263, '2025/test8/audio/test8_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7474, 5924, 73, 'What will the listeners do next?', 'Look at some shelves', 'Ask some questions', 'Introduce themselves', 'Listen to a reading', 'D', '[Dịch] Câu hỏi: Người nghe sẽ làm gì tiếp theo?
A: Nhìn vào một số kệ sách
B: Đặt một số câu hỏi
C: Tự giới thiệu bản thân
D: Nghe đọc sách

Đáp án D là chính xác vì người nói kết thúc bằng "Here''s an excerpt from the introduction" (Đây là một đoạn trích từ phần giới thiệu), cho thấy người nghe sắp được nghe một đoạn đọc từ cuốn sách.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5925, 263, '2025/test8/audio/test8_question_74_76.mp3', NULL, 'I know you''re all tired from a long day in your collection trucks, but I want to address an issue that some of you have asked about. For those who don''t know-from next year, city residents will be required to set their trash out for us in plastic or metal bins. Now, you''re right to be concerned that this change will make your job harder. The cans will be heavier to lift than the plastic bags you''re used to. But don''t worry-within a few months, we''re going to get new trucks that can empty the bins automatically.', 'Tôi biết tất cả các bạn đều mệt mỏi sau một ngày dài trên xe thu gom, nhưng tôi muốn đề cập đến một vấn đề mà một số bạn đã hỏi. Đối với những ai chưa biết - từ năm sau, cư dân thành phố sẽ phải để rác ra cho chúng ta trong các thùng nhựa hoặc thùng kim loại. Bây giờ, các bạn lo lắng rằng thay đổi này sẽ làm công việc của các bạn khó khăn hơn là đúng. Các thùng sẽ nặng hơn để nâng so với túi nhựa mà các bạn đã quen. Nhưng đừng lo - trong vòng vài tháng, chúng ta sẽ có xe mới có thể đổ thùng rác tự động.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7475, 5925, 74, 'Where does the speaker most likely work?', 'A chemical factory', 'A vegetable farm', 'An auto-mechanic shop', 'A waste disposal company', 'D', '[Dịch] Câu hỏi: Người nói có khả năng làm việc ở đâu?
A: Một nhà máy hóa chất
B: Một trang trại rau củ
C: Một tiệm sửa xe
D: Một công ty xử lý rác thải

Đáp án D là chính xác vì người nói đề cập đến "collection trucks" (xe thu gom) và thảo luận về việc thu gom rác từ thùng rác của cư dân thành phố.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5926, 263, '2025/test8/audio/test8_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7476, 5926, 75, 'What problem does the speaker mention?', 'A cost has increased.', 'A regulation has changed.', 'A contract has been canceled.', 'A vehicle has broken down.', 'B', '[Dịch] Câu hỏi: Người nói đề cập đến vấn đề gì?
A: Một chi phí đã tăng
B: Một quy định đã thay đổi
C: Một hợp đồng đã bị hủy
D: Một phương tiện đã bị hỏng

Đáp án B là chính xác vì người nói đề cập đến quy định mới yêu cầu "city residents will be required to set their trash out for us in plastic or metal bins" (cư dân thành phố sẽ phải để rác trong các thùng nhựa hoặc kim loại).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5927, 263, '2025/test8/audio/test8_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7477, 5927, 76, 'What does the speaker reassure the listeners about?', 'A difficult task will be temporary.', 'Extra compensation will be offered.', 'There will still be work available.', 'They will be able to vote on a proposal.', 'A', '[Dịch] Câu hỏi: Người nói trấn an người nghe về điều gì?
A: Một nhiệm vụ khó khăn sẽ chỉ là tạm thời
B: Sẽ được đề nghị thêm thù lao
C: Vẫn sẽ có công việc
D: Họ sẽ có thể bỏ phiếu về một đề xuất

Đáp án A là chính xác vì người nói trấn an rằng mặc dù việc nâng thùng rác sẽ khó khăn hơn, nhưng "within a few months, we''re going to get new trucks that can empty the bins automatically" (trong vòng vài tháng, họ sẽ có xe mới có thể đổ thùng rác tự động).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5928, 263, '2025/test8/audio/test8_question_77_79.mp3', NULL, 'In local news, the town council will meet tonight to discuss the plan to build an apartment complex on Stiltner Road. The developer has proposed a four-story building containing thirty-two apartments and surrounded by a parking lot. The plan has been criticized because of the proposed building site, which borders the woods at the base of Bluft Mountain. Citizens who live on the opposite side of Stiltner Road are concerned that the complex will lower the value of their homes by blocking this attractive view.', 'Trong tin tức địa phương, hội đồng thị trấn sẽ họp tối nay để thảo luận về kế hoạch xây dựng một khu chung cư trên đường Stiltner. Nhà phát triển đã đề xuất một tòa nhà bốn tầng chứa ba mươi hai căn hộ và được bao quanh bởi một bãi đỗ xe. Kế hoạch đã bị phê bình vì địa điểm xây dựng được đề xuất, nơi giáp ranh với khu rừng ở chân núi Bluft. Những công dân sống ở phía đối diện của đường Stiltner lo ngại rằng khu chung cư sẽ làm giảm giá trị nhà của họ bằng cách chặn khung cảnh đẹp này.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7478, 5928, 77, 'What kind of building is being planned?', 'A hospital', 'A train station', 'A manufacturing plant', 'An apartment complex', 'D', '[Dịch] Câu hỏi: Loại tòa nhà nào đang được lên kế hoạch?
A: Một bệnh viện
B: Một nhà ga xe lửa
C: Một nhà máy sản xuất
D: Một khu chung cư

Đáp án D là chính xác vì đoạn văn nói về kế hoạch xây dựng "apartment complex" (khu chung cư) với "thirty-two apartments" (ba mươi hai căn hộ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5929, 263, '2025/test8/audio/test8_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7479, 5929, 78, 'According to the speaker, what is near the proposed building site?', 'A retail district', 'A nature area', 'A primary school', 'A major highway', 'B', '[Dịch] Câu hỏi: Theo người nói, cái gì ở gần địa điểm xây dựng được đề xuất?
A: Một khu vực bán lẻ
B: Một khu vực tự nhiên
C: Một trường tiểu học
D: Một đường cao tốc chính

Đáp án B là chính xác vì đoạn văn cho biết địa điểm xây dựng "borders the woods at the base of Bluft Mountain" (giáp ranh với khu rừng ở chân núi Bluft).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5930, 263, '2025/test8/audio/test8_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7480, 5930, 79, 'What does the speaker say some citizens are concerned about?', 'Effects on wildlife', 'An increase in noise', 'A decline in property values', 'Worsening of road traffic', 'C', '[Dịch] Câu hỏi: Người nói nói một số công dân lo ngại về điều gì?
A: Ảnh hưởng đến động vật hoang dã
B: Sự gia tăng tiếng ồn
C: Sự sụt giảm giá trị bất động sản
D: Sự xấu đi của giao thông đường bộ

Đáp án C là chính xác vì đoạn văn nêu rõ các công dân lo ngại rằng khu chung cư sẽ "lower the value of their homes" (làm giảm giá trị nhà của họ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5931, 263, '2025/test8/audio/test8_question_80_82.mp3', NULL, 'The quarterly meeting of our board of directors is coming up next month. As the last one of the fiscal year, a major item on the agenda will be the budget for the upcoming year. Please send me your estimates of your department''s annual expenses soon so that I can start putting our proposal together. I''ll e-mail all of you the template later today. It has some of the most common expense types, plus space to add others as needed.', 'Cuộc họp quý của hội đồng quản trị của chúng ta sẽ diễn ra vào tháng tới. Là cuộc họp cuối cùng của năm tài chính, một mục quan trọng trong chương trình nghị sự sẽ là ngân sách cho năm tới. Vui lòng gửi cho tôi ước tính chi phí hàng năm của phòng ban của bạn sớm để tôi có thể bắt đầu tập hợp đề xuất của chúng ta. Tôi sẽ gửi email cho tất cả các bạn mẫu sau hôm nay. Nó có một số loại chi phí phổ biến nhất, cộng thêm không gian để thêm các khoản khác khi cần thiết.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7481, 5931, 80, 'What type of event will take place next month?', 'A board meeting', 'An office renovation', 'An industry conference', 'A branch opening', 'A', '[Dịch] Câu hỏi: Loại sự kiện nào sẽ diễn ra vào tháng tới?
A: Một cuộc họp hội đồng quản trị
B: Một cuộc cải tạo văn phòng
C: Một hội nghị ngành
D: Một lễ khai trương chi nhánh

Đáp án A là chính xác vì đoạn văn đề cập đến "quarterly meeting of our board of directors" (cuộc họp quý của hội đồng quản trị của chúng ta).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5932, 263, '2025/test8/audio/test8_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7482, 5932, 81, 'What does the speaker tell the listeners to do?', 'Practice giving a presentation', 'Distribute surveys to their staff', 'Submit some budget figures', 'Arrange their own transportation', 'C', '[Dịch] Câu hỏi: Người nói bảo người nghe làm gì?
A: Thực hành thuyết trình
B: Phân phát khảo sát cho nhân viên của họ
C: Nộp một số con số ngân sách
D: Sắp xếp phương tiện đi lại của riêng họ

Đáp án C là chính xác vì người nói yêu cầu "send me your estimates of your department''s annual expenses" (gửi cho tôi ước tính chi phí hàng năm của phòng ban của bạn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5933, 263, '2025/test8/audio/test8_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7483, 5933, 82, 'What will the speaker send the listeners?', 'A catalog', 'A template', 'An agenda', 'A floor plan', 'B', '[Dịch] Câu hỏi: Người nói sẽ gửi gì cho người nghe?
A: Một danh mục
B: Một mẫu biểu
C: Một chương trình nghị sự
D: Một bản vẽ mặt bằng

Đáp án B là chính xác vì người nói cho biết "I''ll e-mail all of you the template" (Tôi sẽ gửi email cho tất cả các bạn mẫu biểu).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5934, 263, '2025/test8/audio/test8_question_83_85.mp3', NULL, 'Are you a jobseeker in the Covington region? Join the team at Covington Reef, the city''s first indoor water park! Before our launch in October, we''re looking to fill roles in dozens of areas, from ticket-taking to maintenance and accounting. And this isn''t seasonal work like you''d find at other water parks-the Reef will be open year-round! This is a great opportunity. Come to our hiring fair on September first to learn more.', 'Bạn có phải là người tìm việc ở khu vực Covington không? Hãy tham gia đội ngũ tại Covington Reef, công viên nước trong nhà đầu tiên của thành phố! Trước khi khai trương vào tháng 10, chúng tôi đang tìm kiếm người để điền vào các vị trí trong hàng chục lĩnh vực, từ bán vé đến bảo trì và kế toán. Và đây không phải là công việc theo mùa như bạn thường thấy ở các công viên nước khác - Reef sẽ mở cửa quanh năm! Đây là một cơ hội tuyệt vời. Hãy đến hội chợ tuyển dụng của chúng tôi vào ngày 1 tháng 9 để tìm hiểu thêm.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7484, 5934, 83, 'What kind of business is recruiting employees?', 'An amusement park', 'A shopping mall', 'A sports stadium', 'A convention center', 'A', '[Dịch] Câu hỏi: Loại doanh nghiệp nào đang tuyển nhân viên?
A: Một công viên giải trí
B: Một trung tâm mua sắm
C: Một sân vận động
D: Một trung tâm hội nghị

Đáp án A là chính xác vì Covington Reef được mô tả là "indoor water park" (công viên nước trong nhà), đây là một loại công viên giải trí.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5935, 263, '2025/test8/audio/test8_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7485, 5935, 84, 'What does the speaker imply when she says, "the Reef will be open year-round"?', 'Many workers will be needed.', 'The jobs are not suitable for students.', 'Applications will be accepted at any time.', 'The positions are relatively stable.', 'D', '[Dịch] Câu hỏi: Người nói ngụ ý gì khi cô ấy nói "Reef sẽ mở cửa quanh năm"?
A: Sẽ cần nhiều công nhân
B: Công việc không phù hợp với sinh viên
C: Đơn xin việc sẽ được chấp nhận bất cứ lúc nào
D: Các vị trí tương đối ổn định

Đáp án D là chính xác vì người nói đang so sánh với "seasonal work" (công việc theo mùa) ở các công viên nước khác, ngụ ý rằng các vị trí này sẽ ổn định hơn vì công viên hoạt động quanh năm.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5936, 263, '2025/test8/audio/test8_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7486, 5936, 85, 'What should interested listeners do?', 'Fill out a form online', 'Attend a recruiting event', 'E-mail some documents', 'Call an information line', 'B', '[Dịch] Câu hỏi: Những người nghe quan tâm nên làm gì?
A: Điền vào một mẫu đơn trực tuyến
B: Tham dự một sự kiện tuyển dụng
C: Gửi email một số tài liệu
D: Gọi đến một đường dây thông tin

Đáp án B là chính xác vì người nói mời những người quan tâm "Come to our hiring fair on September first" (Đến hội chợ tuyển dụng của chúng tôi vào ngày 1 tháng 9).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5937, 263, '2025/test8/audio/test8_question_86_88.mp3', NULL, 'The rapid expansion of our workforce has caused some difficulties for all of us here at Vindall Incorporated. The most serious one has been the lack of space in our office. The workplace consultant we hired suggested allowing remote work a couple of days per week, and that change has certainly helped. And setting up the technology to make that possible was no easy thing, so thanks to the IT department for that. I also appreciate everyone''s willingness to share their desks. Now we''re considering converting one of the conference rooms into another block of desks. That may seem risky, but the same consultant recommended it, and-we don''t have a lot of meetings.', 'Việc mở rộng nhanh chóng lực lượng lao động đã gây ra một số khó khăn cho tất cả chúng ta tại Vindall Incorporated. Vấn đề nghiêm trọng nhất là thiếu không gian trong văn phòng của chúng ta. Chuyên gia tư vấn nơi làm việc mà chúng tôi thuê đã đề xuất cho phép làm việc từ xa vài ngày mỗi tuần, và thay đổi đó chắc chắn đã giúp ích. Và việc thiết lập công nghệ để làm điều đó có thể không phải là điều dễ dàng, vì vậy cảm ơn phòng IT về điều đó. Tôi cũng đánh giá cao sự sẵn lòng chia sẻ bàn làm việc của mọi người. Bây giờ chúng tôi đang cân nhắc chuyển đổi một trong các phòng họp thành một khu vực bàn làm việc khác. Điều đó có vẻ rủi ro, nhưng cùng một chuyên gia tư vấn đã đề xuất nó, và - chúng ta không có nhiều cuộc họp.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7487, 5937, 86, 'What problem does the speaker''s company have?', 'Declining sales', 'A staffing shortage', 'Limited office space', 'Outdated equipment', 'C', '[Dịch] Câu hỏi: Công ty của người nói gặp vấn đề gì?
A: Doanh số giảm
B: Thiếu nhân viên
C: Không gian văn phòng hạn chế
D: Thiết bị lạc hậu

Đáp án C là chính xác vì người nói nói rằng "the most serious one has been the lack of space in our office" (vấn đề nghiêm trọng nhất là thiếu không gian trong văn phòng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5938, 263, '2025/test8/audio/test8_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7488, 5938, 87, 'Why does the speaker thank the IT department?', 'It provided technology for remote work.', 'It agreed to move to another location.', 'It recovered some employees'' lost data.', 'It discovered an issue with some software.', 'A', '[Dịch] Câu hỏi: Tại sao người nói cảm ơn phòng IT?
A: Họ đã cung cấp công nghệ cho làm việc từ xa
B: Họ đã đồng ý chuyển đến một địa điểm khác
C: Họ đã khôi phục một số dữ liệu bị mất của nhân viên
D: Họ đã phát hiện một vấn đề với một số phần mềm

Đáp án A là chính xác vì người nói cảm ơn phòng IT vì "setting up the technology to make that [remote work] possible" (thiết lập công nghệ để làm việc từ xa có thể thực hiện được).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5939, 263, '2025/test8/audio/test8_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7489, 5939, 88, 'Why does the speaker say, "we don''t have a lot of meetings"?', 'To encourage the listeners to speak now', 'To announce a change in business practices', 'To express concern about a company''s culture', 'To support an expert''s recommendation', 'D', '[Dịch] Câu hỏi: Tại sao người nói nói "chúng ta không có nhiều cuộc họp"?
A: Để khuyến khích người nghe nói ngay bây giờ
B: Để thông báo một thay đổi trong thực tiễn kinh doanh
C: Để bày tỏ lo ngại về văn hóa của một công ty
D: Để ủng hộ khuyến nghị của một chuyên gia

Đáp án D là chính xác vì người nói sử dụng điều này để ủng hộ đề xuất của chuyên gia tư vấn về việc chuyển đổi phòng họp thành không gian làm việc, bởi vì công ty không tổ chức nhiều cuộc họp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5940, 263, '2025/test8/audio/test8_question_89_91.mp3', NULL, 'Welcome back to Around Town, the show where we explore Harsville. Our last segment today will be a treat for viewers who love animals. I''m going to introduce you to a unique local business called Kitty Corner. It''s a café on Blake Street-but that''s not all. Kitty Corner is also home to more than ten cats that customers are invited to pet and play with. It''s the perfect place to spend an afternoon if you''re someone who loves cats but can''t keep them yourself. Now, in just a moment, we''ll have the company''s founder join us to share more about Kitty Corner. This segment is live, so visit our Web site right now to send in questions you''d like me to ask her.', 'Chào mừng quay trở lại Around Town, chương trình khám phá Harsville. Phân đoạn cuối cùng hôm nay sẽ là một món quà dành cho những khán giả yêu động vật. Tôi sẽ giới thiệu cho bạn một doanh nghiệp địa phương độc đáo có tên là Kitty Corner. Đó là một quán café trên đường Blake - nhưng không chỉ có vậy. Kitty Corner cũng là nhà của hơn mười con mèo mà khách hàng được mời vuốt ve và chơi đùa cùng. Đây là nơi hoàn hảo để dành buổi chiều nếu bạn là người yêu mèo nhưng không thể nuôi chúng. Bây giờ, trong giây lát, chúng ta sẽ có người sáng lập công ty tham gia để chia sẻ thêm về Kitty Corner. Phân đoạn này được phát trực tiếp, vì vậy hãy truy cập trang web của chúng tôi ngay bây giờ để gửi câu hỏi bạn muốn tôi hỏi cô ấy.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7490, 5940, 89, 'Who is the speaker?', 'A town official', 'A television host', 'A company spokesperson', 'A radio producer', 'B', '[Dịch] Câu hỏi: Người nói là ai?
A: Một viên chức thị trấn
B: Một người dẫn chương trình truyền hình
C: Một người phát ngôn công ty
D: Một nhà sản xuất radio

Đáp án B là chính xác vì người nói đang dẫn chương trình "Around Town" và đề cập đến "viewers" (người xem) và "live segment" (phân đoạn trực tiếp), cho thấy đây là một người dẫn chương trình truyền hình.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5941, 263, '2025/test8/audio/test8_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7491, 5941, 90, 'What does the business do for its customers?', 'It provides short-term care for their cats.', 'It shares reviews of local veterinary clinics.', 'It builds custom play structures for their pets.', 'It gives them an opportunity to interact with animals.', 'D', '[Dịch] Câu hỏi: Doanh nghiệp này làm gì cho khách hàng?
A: Nó cung cấp dịch vụ chăm sóc ngắn hạn cho mèo của họ
B: Nó chia sẻ đánh giá về các phòng khám thú y địa phương
C: Nó xây dựng các cấu trúc chơi tùy chỉnh cho thú cưng của họ
D: Nó cho họ cơ hội tương tác với động vật

Đáp án D là chính xác vì quán café cho phép khách hàng "pet and play with" (vuốt ve và chơi đùa) với các con mèo sống tại đó.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5942, 263, '2025/test8/audio/test8_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7492, 5942, 91, 'What can the listeners do on a Web site?', 'Suggest interview questions', 'Post videos of themselves', 'Request a service consultation', 'Submit a job application', 'A', '[Dịch] Câu hỏi: Người nghe có thể làm gì trên trang web?
A: Đề xuất câu hỏi phỏng vấn
B: Đăng video về bản thân
C: Yêu cầu tư vấn dịch vụ
D: Nộp đơn xin việc

Đáp án A là chính xác vì người nói mời khán giả "send in questions you''d like me to ask her" (gửi câu hỏi bạn muốn tôi hỏi cô ấy) trên trang web.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5943, 263, '2025/test8/audio/test8_question_92_94.mp3', NULL, 'Good morning, everyone. I''ve just set the date for our organization''s annual fund-raising dinner and auction. It will take place on the evening of May fifteenth. Now, I usually have you all reach out to local businesses about donating items for the auction, but I don''t think that''s necessary anymore. Last year we actually had to refuse a few businesses. I''ll just call up some of our previous donors. However, your help will still be needed for physical tasks like setup and cleanup of the venue. So please don''t make any other plans for the days around the event.', 'Chào buổi sáng, mọi người. Tôi vừa ấn định ngày cho bữa tối gây quỹ và đấu giá thường niên của tổ chức chúng ta. Nó sẽ diễn ra vào tối ngày 15 tháng 5. Bây giờ, tôi thường yêu cầu tất cả các bạn liên hệ với các doanh nghiệp địa phương về việc quyên góp vật phẩm cho đấu giá, nhưng tôi không nghĩ điều đó còn cần thiết nữa. Năm ngoái chúng ta thực sự đã phải từ chối một vài doanh nghiệp. Tôi sẽ chỉ gọi một số nhà tài trợ trước đây của chúng ta. Tuy nhiên, chúng tôi vẫn sẽ cần sự giúp đỡ của các bạn cho các công việc thể lực như thiết lập và dọn dẹp địa điểm. Vì vậy, xin đừng lên kế hoạch nào khác cho những ngày xung quanh sự kiện.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7493, 5943, 92, 'What is being announced?', 'A trade show', 'A park cleanup', 'A charity dinner', 'An outdoor festival', 'C', '[Dịch] Câu hỏi: Điều gì đang được thông báo?
A: Một hội chợ thương mại
B: Một buổi dọn dẹp công viên
C: Một bữa tối từ thiện
D: Một lễ hội ngoài trời

Đáp án C là chính xác vì người nói thông báo về "annual fund-raising dinner and auction" (bữa tối gây quỹ và đấu giá thường niên), đây là một sự kiện từ thiện.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5944, 263, '2025/test8/audio/test8_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7494, 5944, 93, 'What does the speaker imply when she says, "Last year we actually had to refuse a few businesses"?', 'Many organizations want to participate.', 'A submission deadline must be followed.', 'Some registration materials were not complete.', 'The same recruitment strategy should be used again.', 'A', '[Dịch] Câu hỏi: Người nói ngụ ý gì khi cô ấy nói "Năm ngoái chúng ta thực sự đã phải từ chối một vài doanh nghiệp"?
A: Nhiều tổ chức muốn tham gia
B: Một thời hạn nộp phải được tuân thủ
C: Một số tài liệu đăng ký không hoàn chỉnh
D: Cùng một chiến lược tuyển dụng nên được sử dụng lại

Đáp án A là chính xác vì người nói dùng điều này để cho thấy họ có quá nhiều doanh nghiệp muốn quyên góp đến nỗi phải từ chối một số, nên không cần tìm thêm nhà tài trợ nữa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5945, 263, '2025/test8/audio/test8_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7495, 5945, 94, 'What are the listeners asked to do?', 'Keep some messages short', 'Keep their records organized', 'Keep some information confidential', 'Keep their schedules clear', 'D', '[Dịch] Câu hỏi: Người nghe được yêu cầu làm gì?
A: Giữ một số tin nhắn ngắn gọn
B: Giữ hồ sơ của họ có tổ chức
C: Giữ một số thông tin bí mật
D: Giữ lịch trình của họ trống

Đáp án D là chính xác vì người nói yêu cầu "don''t make any other plans for the days around the event" (đừng lên kế hoạch nào khác cho những ngày xung quanh sự kiện).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5946, 263, '2025/test8/audio/test8_question_95_97.mp3', '2025/test8/image/test8-p4-image-95.jpg', 'Good morning. I''m Lindsey Reed, one of the organizers of the Maresville Cake Bake-Off. I really appreciate you giving your time and effort to help the town put on this competition. As you know, it''s not just a fun event for the community but also a major tourist attraction that brings in a lot of money for local businesses. Now, what your group will be doing first is handling on-site registration of bake-off contestants. Here''s the form that you''ll give them. Early registration has ended, so don''t let anyone check that box. Also, please draw older contestants'' attention to the "Senior" category, which is a new option this year.', 'Chào buổi sáng. Tôi là Lindsey Reed, một trong những người tổ chức Cuộc thi làm bánh Maresville. Tôi thực sự đánh giá cao việc các bạn dành thời gian và công sức để giúp thị trấn tổ chức cuộc thi này. Như các bạn biết, đây không chỉ là một sự kiện vui vẻ cho cộng đồng mà còn là một điểm thu hút du lịch lớn mang lại nhiều tiền cho các doanh nghiệp địa phương. Bây giờ, điều mà nhóm của các bạn sẽ làm đầu tiên là xử lý đăng ký tại chỗ của thí sinh tham gia cuộc thi. Đây là mẫu đơn mà các bạn sẽ đưa cho họ. Đăng ký sớm đã kết thúc, vì vậy đừng để ai đánh dấu vào ô đó. Ngoài ra, xin vui lòng hướng sự chú ý của thí sinh lớn tuổi đến hạng mục "Senior", đây là một lựa chọn mới trong năm nay.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7496, 5946, 95, 'What is the speaker organizing?', 'An art class', 'A nature hike', 'A bicycle race', 'A baking contest', 'D', '[Dịch] Câu hỏi: Người nói đang tổ chức cái gì?
A: Một lớp nghệ thuật
B: Một chuyến đi bộ đường dài
C: Một cuộc đua xe đạp
D: Một cuộc thi nấu ăn

Đáp án D là chính xác vì người nói giới thiệu mình là một trong những người tổ chức của "Maresville Cake Bake-Off" (Cuộc thi làm bánh Maresville).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5947, 263, '2025/test8/audio/test8_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7497, 5947, 96, 'What does the speaker thank the listeners for?', 'Being patient during a delay', 'Volunteering to support the event', 'Completing registration in advance', 'Giving feedback on a past event', 'B', '[Dịch] Câu hỏi: Người nói cảm ơn người nghe vì điều gì?
A: Kiên nhẫn trong thời gian trì hoãn
B: Tình nguyện hỗ trợ sự kiện
C: Hoàn thành đăng ký trước
D: Đưa ra phản hồi về một sự kiện trong quá khứ

Đáp án B là chính xác vì người nói cảm ơn họ "giving your time and effort to help the town put on this competition" (dành thời gian và công sức để giúp thị trấn tổ chức cuộc thi này).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5948, 263, '2025/test8/audio/test8_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7498, 5948, 97, 'Look at the graphic. Which amount has been newly added?', '$10', '$16', '$20', '$25', 'C', '[Dịch] Câu hỏi: Nhìn vào hình. Số tiền nào mới được thêm vào?
A: 10 đô la
B: 16 đô la
C: 20 đô la
D: 25 đô la

Đáp án C là chính xác vì người nói nói rằng hạng mục "Senior" là "a new option this year" (một lựa chọn mới trong năm nay). Trong hình, tương ứng với số tiền 20 đô la.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5949, 263, '2025/test8/audio/test8_question_98_100.mp3', '2025/test8/image/test8-p4-image-98.jpg', 'Hi, it''s Sayuri. Thanks for sending me the schedule for the community center''s Italian cooking classes. I agree that it would be fun to take them together. I''m quite interested in learning to make all of these dishes-except meatballs. You know I''m not a fan of meat! I wonder if I''ll still have to pay for that class even though I won''t attend it, or if they charge separately for each class. That information doesn''t seem to be on the schedule. I''ll call the community center and find out.', 'Chào, tôi là Sayuri. Cảm ơn bạn đã gửi cho tôi lịch học các lớp nấu ăn Ý tại trung tâm cộng đồng. Tôi đồng ý rằng sẽ rất vui khi cùng học những lớp này. Tôi khá quan tâm đến việc học làm tất cả các món này - ngoại trừ thịt viên. Bạn biết tôi không thích thịt mà! Tôi tự hỏi liệu tôi vẫn phải trả tiền cho lớp học đó mặc dù tôi sẽ không tham dự, hay họ tính phí riêng cho từng lớp. Thông tin đó dường như không có trong lịch học. Tôi sẽ gọi cho trung tâm cộng đồng và tìm hiểu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7499, 5949, 98, 'Look at the graphic. On which date will the speaker skip a class?', 'October 2', 'October 9', 'October 16', 'October 23', 'B', '[Dịch] Câu hỏi: Nhìn vào hình. Vào ngày nào người nói sẽ bỏ lớp học?
A: Ngày 2 tháng 10
B: Ngày 9 tháng 10
C: Ngày 16 tháng 10
D: Ngày 23 tháng 10

Đáp án B là chính xác vì người nói không thích thịt ("I''m not a fan of meat") và trong hình, ngày 9 tháng 10 là lớp học làm "Classic Meatballs" (thịt viên cổ điển).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5950, 263, '2025/test8/audio/test8_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7500, 5950, 99, 'What is the speaker unsure about?', 'Whether some classes are already full', 'What time the classes will end', 'Who will teach each class', 'How the class fees are charged', 'D', '[Dịch] Câu hỏi: Người nói không chắc chắn về điều gì?
A: Liệu một số lớp đã đầy chưa
B: Lớp học sẽ kết thúc lúc mấy giờ
C: Ai sẽ dạy từng lớp
D: Cách tính học phí như thế nào

Đáp án D là chính xác vì người nói tự hỏi "if I''ll still have to pay for that class even though I won''t attend it, or if they charge separately for each class" (liệu tôi vẫn phải trả tiền cho lớp đó mặc dù tôi sẽ không tham dự, hay họ tính phí riêng cho từng lớp).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5951, 263, '2025/test8/audio/test8_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7501, 5951, 100, 'What will the speaker most likely do next?', 'Complete a registration form', 'Wait for a call from the listener', 'Contact the community center', 'Read some lists of ingredients', 'C', '[Dịch] Câu hỏi: Người nói có khả năng sẽ làm gì tiếp theo?
A: Hoàn thành một mẫu đơn đăng ký
B: Đợi cuộc gọi từ người nghe
C: Liên hệ với trung tâm cộng đồng
D: Đọc một số danh sách nguyên liệu

Đáp án C là chính xác vì người nói kết thúc bằng "I''ll call the community center and find out" (Tôi sẽ gọi cho trung tâm cộng đồng và tìm hiểu).');;

-- Data for 2025 Test8 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5952, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7502, 5952, 101, 'Mount Teide is Spain''s only peak that ----- above 3,500 meters.', 'rise', 'rises', 'to rise', 'rising', 'B', 'Đáp án B (rises) là đúng vì các lý do sau:
1. Cần một động từ chia ở ngôi thứ 3 số ít.
2. Chủ ngữ là "peak" (số ít) nên động từ phải chia ở ngôi thứ 3 số ít.
3. "Rises" là dạng đúng của động từ "rise" ở hiện tại đơn, ngôi thứ 3 số ít.
4. Các đáp án khác không phù hợp: "rise" (động từ nguyên thể), "to rise" (động từ nguyên mẫu), "rising" (hiện tại phân từ).
Dịch câu hỏi: Núi Teide là đỉnh núi duy nhất của Tây Ban Nha cao hơn 3.500 mét.
Dịch đáp án:
A. rise (động từ nguyên thể: vươn lên)
B. rises (động từ số ít: vươn lên)
C. to rise (động từ nguyên mẫu: để vươn lên)
D. rising (động từ ing: đang vươn lên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5953, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7503, 5953, 102, 'Aspiring chefs should equip ----- with a high-quality set of kitchen knives.', 'they', 'themselves', 'their own', 'their', 'B', 'Đáp án B (themselves) là đúng vì các lý do sau:
1. Cần một đại từ phản thân.
2. "Equip oneself with" là cụm động từ phản thân.
3. Diễn tả việc tự trang bị cho bản thân.
4. Các đáp án khác không phù hợp: "they" (đại từ nhân xưng), "their own" (sở hữu), "their" (tính từ sở hữu).
Dịch câu hỏi: Các đầu bếp khao khát thành công nên trang bị cho mình một bộ dao nhà bếp chất lượng cao.
Dịch đáp án:
A. they (đại từ nhân xưng: họ)
B. themselves (đại từ phản thân: bản thân họ)
C. their own (từ sở hữu: của riêng họ)
D. their (tính từ sở hữu: của họ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5954, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7504, 5954, 103, 'Mr. Hayashi has the ----- career history out of the entire advisory committee.', 'long', 'length', 'longer', 'longest', 'D', 'Đáp án D (longest) là đúng vì các lý do sau:
1. Cần một tính từ ở dạng so sánh nhất.
2. So sánh với tất cả các thành viên khác trong ủy ban.
3. "The + tính từ so sánh nhất" là cấu trúc so sánh nhất.
4. Các đáp án khác không phù hợp: "long" (dài), "length" (độ dài), "longer" (dài hơn).
Dịch câu hỏi: Ông Hayashi có lịch sử sự nghiệp lâu dài nhất trong toàn bộ ủy ban cố vấn.
Dịch đáp án:
A. long (tính từ: dài)
B. length (danh từ: độ dài)
C. longer (tính từ so sánh hơn: dài hơn)
D. longest (tính từ so sánh nhất: dài nhất)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5955, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7505, 5955, 104, 'All of Wester Apartments'' amenities, ------ the fitness center, are available to tenants at no extra charge.', 'sometimes', 'including', 'just as', 'also', 'B', 'Đáp án B (including) là đúng vì các lý do sau:
1. Cần một giới từ để thêm thông tin bổ sung.
2. "Including" dùng để liệt kê một phần của tổng thể.
3. Trong câu này, trung tâm thể dục là một trong các tiện nghi.
4. Các đáp án khác không phù hợp: "sometimes" (đôi khi), "just as" (giống như), "also" (cũng).
Dịch câu hỏi: Tất cả các tiện nghi của Wester Apartments, bao gồm cả trung tâm thể dục, đều có sẵn cho người thuê mà không tính thêm phí.
Dịch đáp án:
A. sometimes (trạng từ: đôi khi)
B. including (giới từ: bao gồm)
C. just as (cụm từ: giống như)
D. also (trạng từ: cũng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5956, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7506, 5956, 105, 'Clients appreciate that Ms. Caro is ----- incorrect about market trends.', 'rarely', 'yet', 'apart', 'far', 'A', 'Đáp án A (rarely) là đúng vì các lý do sau:
1. Cần một trạng từ tần suất.
2. "Rarely" có nghĩa là "hiếm khi".
3. Diễn tả tần suất sai sót thấp trong nhận định về xu hướng thị trường.
4. Các đáp án khác không phù hợp: "yet" (vẫn), "apart" (tách biệt), "far" (xa).
Dịch câu hỏi: Khách hàng đánh giá cao việc bà Caro hiếm khi sai về xu hướng thị trường.
Dịch đáp án:
A. rarely (trạng từ: hiếm khi)
B. yet (trạng từ: vẫn)
C. apart (trạng từ: tách biệt)
D. far (trạng từ: xa)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5957, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7507, 5957, 106, 'Our library is an affiliate of Fowler Science Online, —-- library patrons can access its interactive lessons for free.', 'once', 'how', 'then', 'so', 'D', 'Đáp án D (so) là đúng vì các lý do sau:
1. Cần một liên từ nối kết quả.
2. "So" là liên từ chỉ kết quả.
3. Diễn tả mối quan hệ nguyên nhân-kết quả: là chi nhánh nên được truy cập miễn phí.
4. Các đáp án khác không phù hợp: "once" (một khi), "how" (thế nào), "then" (sau đó).
Dịch câu hỏi: Thư viện của chúng tôi là một chi nhánh của Fowler Science Online, vì vậy độc giả thư viện có thể truy cập các bài học tương tác của nó miễn phí.
Dịch đáp án:
A. once (liên từ: một khi)
B. how (trạng từ: thế nào)
C. then (trạng từ: sau đó)
D. so (liên từ: vì vậy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5958, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7508, 5958, 107, 'The CEO''s speech presented a comprehensive ----- for the company''s future.', 'measure', 'collection', 'vision', 'deadline', 'C', 'Đáp án C (vision) là đúng vì các lý do sau:
1. Cần một danh từ chỉ tầm nhìn, viễn cảnh.
2. "Vision" là danh từ chỉ tầm nhìn tương lai.
3. "Comprehensive vision" là cụm từ phổ biến trong ngữ cảnh kinh doanh.
4. Các đáp án khác không phù hợp: "measure" (biện pháp), "collection" (bộ sưu tập), "deadline" (thời hạn).
Dịch câu hỏi: Bài phát biểu của CEO đã trình bày một tầm nhìn toàn diện cho tương lai của công ty.
Dịch đáp án:
A. measure (danh từ: biện pháp)
B. collection (danh từ: bộ sưu tập)
C. vision (danh từ: tầm nhìn)
D. deadline (danh từ: thời hạn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5959, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7509, 5959, 108, 'Only authorized staff are allowed inside the Council Chamber, ----- when there is a public meeting.', 'during', 'given', 'between', 'except', 'D', 'Đáp án D (except) là đúng vì các lý do sau:
1. Cần một giới từ chỉ ngoại lệ.
2. "Except" có nghĩa là "ngoại trừ".
3. Diễn tả trường hợp ngoại lệ của quy định.
4. Các đáp án khác không phù hợp: "during" (trong khi), "given" (được cho), "between" (giữa).
Dịch câu hỏi: Chỉ nhân viên được ủy quyền mới được phép vào Phòng Hội đồng, ngoại trừ khi có cuộc họp công khai.
Dịch đáp án:
A. during (giới từ: trong khi)
B. given (quá khứ phân từ: được cho)
C. between (giới từ: giữa)
D. except (giới từ: ngoại trừ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5960, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7510, 5960, 109, 'Organizations supported by the Alba Foundation must submit annual grant reports for -----.', 'evaluate', 'evaluates', 'evaluation', 'evaluative', 'C', 'Đáp án C (evaluation) là đúng vì các lý do sau:
1. Cần một danh từ sau giới từ "for".
2. "For evaluation" là cụm từ chỉ mục đích.
3. "Submit reports for evaluation" là cụm từ phổ biến trong ngữ cảnh báo cáo.
4. Các đáp án khác không phù hợp: "evaluate" (động từ), "evaluates" (động từ số ít), "evaluative" (tính từ).
Dịch câu hỏi: Các tổ chức được Alba Foundation hỗ trợ phải nộp báo cáo tài trợ hàng năm để đánh giá.
Dịch đáp án:
A. evaluate (động từ: đánh giá)
B. evaluates (động từ: đánh giá)
C. evaluation (danh từ: sự đánh giá)
D. evaluative (tính từ: đánh giá)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5961, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7511, 5961, 110, 'Employees occupying shared offices are expected to be ----- of coworkers'' needs for privacy.', 'mindful', 'willing', 'reasonable', 'independent', 'A', 'Đáp án A (mindful) là đúng vì các lý do sau:
1. Cần một tính từ chỉ sự quan tâm, để ý.
2. "Mindful of" là cụm từ có nghĩa "để ý đến, quan tâm đến".
3. Phù hợp với ngữ cảnh về sự tôn trọng quyền riêng tư.
4. Các đáp án khác không phù hợp: "willing" (sẵn lòng), "reasonable" (hợp lý), "independent" (độc lập).
Dịch câu hỏi: Nhân viên làm việc trong văn phòng chung được kỳ vọng sẽ quan tâm đến nhu cầu riêng tư của đồng nghiệp.
Dịch đáp án:
A. mindful (tính từ: quan tâm đến)
B. willing (tính từ: sẵn lòng)
C. reasonable (tính từ: hợp lý)
D. independent (tính từ: độc lập)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5962, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7512, 5962, 111, 'Graduates of our certification program usually —-- quickly to the working world.', 'adapt', 'adapts', 'adapting', 'is adapted', 'A', 'Đáp án A (adapt) là đúng vì các lý do sau:
1. Cần một động từ ở dạng nguyên thể.
2. Chủ ngữ số nhiều (Graduates) cần động từ số nhiều.
3. "Adapt to" là cụm động từ có nghĩa "thích nghi với".
4. Các đáp án khác không phù hợp: "adapts" (số ít), "adapting" (V-ing), "is adapted" (bị động).
Dịch câu hỏi: Những người tốt nghiệp chương trình chứng chỉ của chúng tôi thường thích nghi nhanh chóng với thế giới công việc.
Dịch đáp án:
A. adapt (động từ: thích nghi)
B. adapts (động từ số ít: thích nghi)
C. adapting (động từ ing: đang thích nghi)
D. is adapted (bị động: được thích nghi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5963, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7513, 5963, 112, 'Internships are of ---- interest to students hoping to improve their résumés.', 'relevant', 'great', 'farthest', 'minimal', 'B', 'Đáp án B (great) là đúng vì các lý do sau:
1. Cần một tính từ chỉ mức độ quan tâm.
2. "Of great interest" là cụm từ cố định chỉ sự quan tâm cao.
3. Phù hợp với ngữ cảnh về tầm quan trọng của thực tập.
4. Các đáp án khác không phù hợp: "relevant" (liên quan), "farthest" (xa nhất), "minimal" (tối thiểu).
Dịch câu hỏi: Thực tập là điều rất được quan tâm đối với sinh viên hy vọng cải thiện sơ yếu lý lịch của họ.
Dịch đáp án:
A. relevant (tính từ: liên quan)
B. great (tính từ: lớn)
C. farthest (tính từ: xa nhất)
D. minimal (tính từ: tối thiểu)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5964, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7514, 5964, 113, 'To communicate traffic conditions in a simple way, our app assigns colors to roads ---- their levels of congestion.', 'adjacent to', 'such as', 'based on', 'instead of', 'C', 'Đáp án C (based on) là đúng vì các lý do sau:
1. Cần một cụm giới từ chỉ sự dựa trên căn cứ nào đó.
2. "Based on" có nghĩa là "dựa trên, căn cứ vào".
3. Phù hợp với ngữ cảnh về việc gán màu dựa trên mức độ tắc nghẽn.
4. Các đáp án khác không phù hợp: "adjacent to" (gần kề), "such as" (chẳng hạn như), "instead of" (thay vì).
Dịch câu hỏi: Để truyền đạt tình trạng giao thông một cách đơn giản, ứng dụng của chúng tôi gán màu cho các con đường dựa trên mức độ tắc nghẽn của chúng.
Dịch đáp án:
A. adjacent to (cụm giới từ: gần kề)
B. such as (cụm từ: chẳng hạn như)
C. based on (cụm giới từ: dựa trên)
D. instead of (cụm giới từ: thay vì)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5965, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7515, 5965, 114, '----- of the two dessert options suggested by the caterer require refrigeration.', 'Every', 'Those', 'Nothing', 'Neither', 'D', 'Đáp án D (Neither) là đúng vì các lý do sau:
1. Cần một từ phủ định khi nói về hai thứ.
2. "Neither" được dùng để phủ định cả hai trong hai thứ.
3. Động từ "require" chia số nhiều vì là chủ ngữ kép.
4. Các đáp án khác không phù hợp: "Every" (mỗi), "Those" (những), "Nothing" (không gì).
Dịch câu hỏi: Không món nào trong hai lựa chọn tráng miệng được đề xuất bởi nhà cung cấp thức ăn cần bảo quản lạnh.
Dịch đáp án:
A. Every (từ xác định: mỗi)
B. Those (đại từ chỉ định: những)
C. Nothing (đại từ: không gì)
D. Neither (từ xác định: không... nào)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5966, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7516, 5966, 115, '----- the end of the tour, participants will have the opportunity to purchase photos taken by our photographer.', 'Without', 'Since', 'At', 'About', 'C', 'Đáp án C (At) là đúng vì các lý do sau:
1. Cần một giới từ chỉ thời điểm cụ thể.
2. "At the end of" là cụm từ cố định chỉ thời điểm cuối.
3. Phù hợp với ngữ cảnh về thời điểm kết thúc tour.
4. Các đáp án khác không phù hợp: "Without" (không có), "Since" (kể từ), "About" (về).
Dịch câu hỏi: Vào cuối chuyến tham quan, người tham gia sẽ có cơ hội mua những bức ảnh được chụp bởi nhiếp ảnh gia của chúng tôi.
Dịch đáp án:
A. Without (giới từ: không có)
B. Since (giới từ: kể từ)
C. At (giới từ: tại)
D. About (giới từ: về)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5967, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7517, 5967, 116, 'Construction work on Snead Tower will soon -----, since new funding has been secured.', 'ensure', 'resume', 'resolve', 'maintain', 'B', 'Đáp án B (resume) là đúng vì các lý do sau:
1. Cần một động từ có nghĩa "tiếp tục lại".
2. "Resume" có nghĩa là "tiếp tục lại sau khi tạm dừng".
3. Phù hợp với ngữ cảnh về việc có kinh phí mới.
4. Các đáp án khác không phù hợp: "ensure" (đảm bảo), "resolve" (giải quyết), "maintain" (duy trì).
Dịch câu hỏi: Công trình xây dựng tại Tháp Snead sẽ sớm tiếp tục, vì nguồn tài trợ mới đã được đảm bảo.
Dịch đáp án:
A. ensure (động từ: đảm bảo)
B. resume (động từ: tiếp tục lại)
C. resolve (động từ: giải quyết)
D. maintain (động từ: duy trì)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5968, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7518, 5968, 117, 'A pay statement must be issued ----- the employee has not worked during the pay period in question.', 'even if', 'other than', 'promptly', 'still', 'A', 'Đáp án A (even if) là đúng vì các lý do sau:
1. Cần một cụm liên từ biểu thị nhượng bộ.
2. "Even if" có nghĩa là "ngay cả khi".
3. Diễn tả việc phải làm bất kể điều kiện.
4. Các đáp án khác không phù hợp: "other than" (khác với), "promptly" (nhanh chóng), "still" (vẫn).
Dịch câu hỏi: Một bảng lương phải được phát hành ngay cả khi nhân viên không làm việc trong kỳ lương đang xét.
Dịch đáp án:
A. even if (cụm liên từ: ngay cả khi)
B. other than (cụm từ: khác với)
C. promptly (trạng từ: nhanh chóng)
D. still (trạng từ: vẫn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5969, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7519, 5969, 118, 'Training participants will be asked to take a quiz online —--- after watching the final video.', 'directly', 'direct', 'directed', 'direction', 'A', 'Đáp án A (directly) là đúng vì các lý do sau:
1. Cần một trạng từ bổ nghĩa cho thời gian.
2. "Directly after" có nghĩa là "ngay sau".
3. Phù hợp với ngữ cảnh về trình tự thời gian.
4. Các đáp án khác không phù hợp: "direct" (trực tiếp - tính từ), "directed" (đã hướng dẫn), "direction" (hướng).
Dịch câu hỏi: Người tham gia đào tạo sẽ được yêu cầu làm bài kiểm tra trực tuyến ngay sau khi xem video cuối cùng.
Dịch đáp án:
A. directly (trạng từ: trực tiếp)
B. direct (tính từ: trực tiếp)
C. directed (quá khứ phân từ: được hướng dẫn)
D. direction (danh từ: hướng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5970, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7520, 5970, 119, 'Focus group leaders should —-- from expressing their personal opinions to the group.', 'refuse', 'refrain', 'escape', 'prevent', 'B', 'Đáp án B (refrain) là đúng vì các lý do sau:
1. Cần một động từ có nghĩa "kiềm chế, tránh".
2. "Refrain from" là cụm động từ cố định.
3. Phù hợp với ngữ cảnh về việc giữ khách quan trong nhóm thảo luận.
4. Các đáp án khác không phù hợp: "refuse" (từ chối), "escape" (thoát), "prevent" (ngăn chặn).
Dịch câu hỏi: Người điều hành nhóm thảo luận trọng tâm nên kiềm chế việc bày tỏ ý kiến cá nhân với nhóm.
Dịch đáp án:
A. refuse (động từ: từ chối)
B. refrain (động từ: kiềm chế)
C. escape (động từ: thoát)
D. prevent (động từ: ngăn chặn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5971, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7521, 5971, 120, 'Dr. Jeong''s award-winning research has enhanced the ----- of her department.', 'arrangement', 'permission', 'reputation', 'belief', 'C', 'Đáp án C (reputation) là đúng vì các lý do sau:
1. Cần một danh từ chỉ danh tiếng, uy tín.
2. "Enhance reputation" là cụm từ phổ biến.
3. Phù hợp với ngữ cảnh về nghiên cứu đoạt giải.
4. Các đáp án khác không phù hợp: "arrangement" (sắp xếp), "permission" (sự cho phép), "belief" (niềm tin).
Dịch câu hỏi: Nghiên cứu đoạt giải của Tiến sĩ Jeong đã nâng cao danh tiếng của khoa của bà.
Dịch đáp án:
A. arrangement (danh từ: sự sắp xếp)
B. permission (danh từ: sự cho phép)
C. reputation (danh từ: danh tiếng)
D. belief (danh từ: niềm tin)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5972, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7522, 5972, 121, 'Because the quartz countertops are its most popular -----, Earlstone features them on its home page.', 'productively', 'productive', 'produces', 'products', 'D', 'Đáp án D (products) là đúng vì các lý do sau:
1. Cần một danh từ số nhiều chỉ sản phẩm.
2. "Popular products" là cụm từ chỉ sản phẩm phổ biến.
3. Phù hợp với ngữ cảnh về việc quảng bá sản phẩm.
4. Các đáp án khác không phù hợp: "productively" (có hiệu quả), "productive" (hiệu quả), "produces" (sản xuất).
Dịch câu hỏi: Vì mặt bàn thạch anh là sản phẩm phổ biến nhất của họ, Earlstone giới thiệu chúng trên trang chủ của mình.
Dịch đáp án:
A. productively (trạng từ: có năng suất)
B. productive (tính từ: có năng suất)
C. produces (động từ: sản xuất)
D. products (danh từ: sản phẩm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5973, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7523, 5973, 122, '---- Byrd Industries lowers its project bid, we will most likely hire Newlane Contractors for the renovation.', 'Further', 'Unless', 'Hopefully', 'Meanwhile', 'B', 'Đáp án B (Unless) là đúng vì các lý do sau:
1. Cần một liên từ chỉ điều kiện phủ định.
2. "Unless" có nghĩa là "trừ khi, nếu không".
3. Diễn tả điều kiện để thay đổi quyết định.
4. Các đáp án khác không phù hợp: "Further" (thêm nữa), "Hopefully" (hy vọng là), "Meanwhile" (trong khi đó).
Dịch câu hỏi: Trừ khi Byrd Industries hạ giá thầu dự án, chúng tôi rất có thể sẽ thuê Newlane Contractors cho việc cải tạo.
Dịch đáp án:
A. Further (trạng từ: thêm nữa)
B. Unless (liên từ: trừ khi)
C. Hopefully (trạng từ: hy vọng là)
D. Meanwhile (trạng từ: trong khi đó)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5974, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7524, 5974, 123, 'Once the passengers -----, the cabin crew will close the aircraft''s doors.', 'boarded', 'are boarding', 'have boarded', 'to board', 'C', 'Đáp án C (have boarded) là đúng vì các lý do sau:
1. Cần một động từ ở thì hiện tại hoàn thành.
2. "Once + present perfect" diễn tả hành động hoàn thành trước một hành động tương lai.
3. Phù hợp với trình tự thời gian: lên máy bay xong mới đóng cửa.
4. Các đáp án khác không phù hợp: "boarded" (quá khứ), "are boarding" (hiện tại tiếp diễn), "to board" (nguyên mẫu).
Dịch câu hỏi: Một khi hành khách đã lên máy bay xong, phi hành đoàn sẽ đóng cửa máy bay.
Dịch đáp án:
A. boarded (quá khứ đơn: đã lên)
B. are boarding (hiện tại tiếp diễn: đang lên)
C. have boarded (hiện tại hoàn thành: đã lên xong)
D. to board (động từ nguyên mẫu: để lên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5975, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7525, 5975, 124, 'Carden Motors is seeking a technician who is ----- at repairing faulty transmissions.', 'expert', 'experts', 'expertly', 'expertise', 'A', 'Đáp án A (expert) là đúng vì các lý do sau:
1. Cần một tính từ chỉ sự thành thạo.
2. "Expert at" là cụm từ chỉ sự chuyên môn trong một lĩnh vực.
3. Phù hợp với ngữ cảnh về kỹ năng sửa chữa.
4. Các đáp án khác không phù hợp: "experts" (danh từ số nhiều), "expertly" (trạng từ), "expertise" (danh từ).
Dịch câu hỏi: Carden Motors đang tìm kiếm một kỹ thuật viên thành thạo trong việc sửa chữa hộp số bị lỗi.
Dịch đáp án:
A. expert (tính từ: thành thạo)
B. experts (danh từ số nhiều: chuyên gia)
C. expertly (trạng từ: một cách thành thạo)
D. expertise (danh từ: chuyên môn)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5976, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7526, 5976, 125, 'In a recent interview, Sarah Fusco admitted she now regrets her ------ decision to leave the music industry.', 'impulsive', 'boldest', 'unexpectedly', 'occasional', 'A', 'Đáp án A (impulsive) là đúng vì các lý do sau:
1. Cần một tính từ mô tả quyết định.
2. "Impulsive decision" là cụm từ chỉ quyết định bốc đồng.
3. Phù hợp với ngữ cảnh về sự hối tiếc sau này.
4. Các đáp án khác không phù hợp: "boldest" (táo bạo nhất), "unexpectedly" (bất ngờ - trạng từ), "occasional" (thỉnh thoảng).
Dịch câu hỏi: Trong một cuộc phỏng vấn gần đây, Sarah Fusco thừa nhận giờ đây cô ấy hối tiếc về quyết định bốc đồng rời khỏi ngành công nghiệp âm nhạc.
Dịch đáp án:
A. impulsive (tính từ: bốc đồng)
B. boldest (tính từ so sánh nhất: táo bạo nhất)
C. unexpectedly (trạng từ: bất ngờ)
D. occasional (tính từ: thỉnh thoảng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5977, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7527, 5977, 126, 'Mr. Lin was —-- to circulating memos electronically until his colleagues pointed out it would save money.', 'accustomed', 'receptive', 'limited', 'opposed', 'D', 'Đáp án D (opposed) là đúng vì các lý do sau:
1. Cần một tính từ chỉ sự phản đối.
2. "Be opposed to" là cụm từ cố định có nghĩa "phản đối".
3. Phù hợp với ngữ cảnh về thái độ ban đầu với việc gửi memo điện tử.
4. Các đáp án khác không phù hợp: "accustomed" (quen với), "receptive" (dễ tiếp thu), "limited" (hạn chế).
Dịch câu hỏi: Ông Lin đã phản đối việc lưu hành bản ghi nhớ dưới dạng điện tử cho đến khi đồng nghiệp chỉ ra rằng nó sẽ tiết kiệm tiền.
Dịch đáp án:
A. accustomed (tính từ: quen với)
B. receptive (tính từ: dễ tiếp thu)
C. limited (tính từ: hạn chế)
D. opposed (tính từ: phản đối)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5978, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7528, 5978, 127, 'Strunk Group''s top-selling fertilizer, Ultra Green, ----- increases the amount of nutrients in poor soil.', 'considers', 'considerable', 'consideration', 'considerably', 'D', 'Đáp án D (considerably) là đúng vì các lý do sau:
1. Cần một trạng từ bổ nghĩa cho động từ "increases".
2. "Considerably" có nghĩa là "đáng kể".
3. Diễn tả mức độ tăng dưỡng chất trong đất.
4. Các đáp án khác không phù hợp: "considers" (động từ), "considerable" (tính từ), "consideration" (danh từ).
Dịch câu hỏi: Phân bón bán chạy nhất của Tập đoàn Strunk, Ultra Green, tăng đáng kể lượng dưỡng chất trong đất nghèo.
Dịch đáp án:
A. considers (động từ: xem xét)
B. considerable (tính từ: đáng kể)
C. consideration (danh từ: sự xem xét)
D. considerably (trạng từ: đáng kể)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5979, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7529, 5979, 128, 'Amateurs and professionals ----- are using Illustria for graphic design projects.', 'almost', 'rather', 'alike', 'most', 'C', 'Đáp án C (alike) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ sự giống nhau.
2. "Alike" có nghĩa là "như nhau, giống nhau".
3. Phù hợp với ngữ cảnh về việc cả hai nhóm đều sử dụng phần mềm.
4. Các đáp án khác không phù hợp: "almost" (gần như), "rather" (thà), "most" (nhất).
Dịch câu hỏi: Cả người nghiệp dư và chuyên nghiệp đều đang sử dụng Illustria cho các dự án thiết kế đồ họa.
Dịch đáp án:
A. almost (trạng từ: gần như)
B. rather (trạng từ: thà)
C. alike (trạng từ: như nhau)
D. most (trạng từ: nhất)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5980, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7530, 5980, 129, 'The paintings have been arranged ---- in order to show how Mr. Guerra''s style changed over the course of his career.', 'rightfully', 'prominently', 'increasingly', 'chronologically', 'D', 'Đáp án D (chronologically) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ cách sắp xếp theo thời gian.
2. "Chronologically" có nghĩa là "theo trình tự thời gian".
3. Phù hợp với mục đích thể hiện sự phát triển phong cách qua thời gian.
4. Các đáp án khác không phù hợp: "rightfully" (chính đáng), "prominently" (nổi bật), "increasingly" (ngày càng).
Dịch câu hỏi: Các bức tranh được sắp xếp theo trình tự thời gian để cho thấy phong cách của ông Guerra đã thay đổi như thế nào trong suốt sự nghiệp của ông.
Dịch đáp án:
A. rightfully (trạng từ: chính đáng)
B. prominently (trạng từ: nổi bật)
C. increasingly (trạng từ: ngày càng)
D. chronologically (trạng từ: theo trình tự thời gian)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (5981, 264, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7531, 5981, 130, 'The travel ----- is allocated to assist with meals, taxi fares, and any other expenses incurred during your trip.', 'documentation', 'allowance', 'itinerary', 'insurance', 'B', 'Đáp án B (allowance) là đúng vì các lý do sau:
1. Cần một danh từ chỉ khoản tiền được cấp.
2. "Travel allowance" là cụm từ chỉ khoản phụ cấp đi lại.
3. Phù hợp với ngữ cảnh về chi phí ăn uống và đi lại.
4. Các đáp án khác không phù hợp: "documentation" (tài liệu), "itinerary" (lịch trình), "insurance" (bảo hiểm).
Dịch câu hỏi: Phụ cấp đi lại được phân bổ để hỗ trợ các bữa ăn, tiền taxi và bất kỳ chi phí nào khác phát sinh trong chuyến đi của bạn.
Dịch đáp án:
A. documentation (danh từ: tài liệu)
B. allowance (danh từ: phụ cấp)
C. itinerary (danh từ: lịch trình)
D. insurance (danh từ: bảo hiểm)');;

