INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7608, 6007, 7, 'When can we pick up the building permit?', 'I just submitted the application.', 'No more than six months.', 'His boss gave him permission.', NULL, 'A', 'Câu hỏi: Khi nào chúng ta có thể nhận giấy phép xây dựng?"
A: "Tôi vừa nộp đơn xin giấy phép."
B: "Không quá sáu tháng."
C: "Sếp của anh ấy đã cho phép."
Giải thích: Đáp án A đúng vì câu hỏi hỏi về thời gian nhận giấy phép xây dựng, và đáp án A cho biết việc nộp đơn là bước đầu tiên."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6008, 268, '2025/test9/audio/test9_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7609, 6008, 8, 'Do you want anything from the convenience store?', 'That''s a great business idea.', 'A bottle of water would be nice.', 'Where are they stored?', NULL, 'B', 'Câu hỏi: Bạn có muốn mua gì từ cửa hàng tiện lợi không?"
A: "Đó là một ý tưởng kinh doanh tuyệt vời."
B: "Một chai nước sẽ rất tốt."
C: "Chúng được lưu trữ ở đâu?"
Giải thích: Đáp án B đúng vì câu hỏi về việc mua gì từ cửa hàng tiện lợi và đáp án B là một câu trả lời hợp lý."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6009, 268, '2025/test9/audio/test9_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7610, 6009, 9, 'Would you like to sign up for our loyalty program?', 'I don''t shop here very often.', 'A beautiful design.', 'I like that TV program, too.', NULL, 'A', 'Câu hỏi: Bạn có muốn đăng ký chương trình khách hàng thân thiết của chúng tôi không?"
A: "Tôi không mua sắm ở đây thường xuyên."
B: "Một thiết kế đẹp."
C: "Tôi cũng thích chương trình truyền hình đó."
Giải thích: Đáp án A đúng vì câu hỏi về việc tham gia chương trình khách hàng thân thiết và đáp án A cho biết người trả lời không thường xuyên mua sắm tại cửa hàng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6010, 268, '2025/test9/audio/test9_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7611, 6010, 10, 'Thank you for writing a recommendation for me.', 'It was my pleasure.', 'I ride it to work each morning.', 'They might have extras.', NULL, 'A', 'Câu hỏi: Cảm ơn bạn vì đã viết thư giới thiệu cho tôi." 
A: "Rất vui được giúp đỡ."
B: "Tôi đi làm bằng xe đạp mỗi sáng."
C: "Họ có thể có thêm các bản sao."
Giải thích: Đáp án A đúng vì câu hỏi là lời cảm ơn về việc viết thư giới thiệu và đáp án A thể hiện sự lịch sự và niềm vui khi được giúp đỡ."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6011, 268, '2025/test9/audio/test9_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7612, 6011, 11, 'Is the university library open to the public?', 'They''re studying for a test.', 'The keys are in the director''s office.', 'Only its general collection is.', NULL, 'C', 'Câu hỏi: Thư viện trường đại học có mở cửa cho công chúng không?"
A: "Họ đang ôn bài cho kỳ thi."
B: "Chìa khóa ở văn phòng giám đốc."
C: "Chỉ có bộ sưu tập chung là mở cửa cho công chúng."
Giải thích: Đáp án C đúng vì câu hỏi hỏi về việc thư viện có mở cửa cho công chúng và đáp án C chỉ rõ thư viện chỉ mở cửa cho bộ sưu tập chung."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6012, 268, '2025/test9/audio/test9_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7613, 6012, 12, 'When is this airport the busiest?', 'OK, we''ll hire a few more people.', 'I can''t remember her name.', 'It varies from year to year.', NULL, 'C', 'Câu hỏi: Khi nào sân bay này đông nhất?"
A: "Được rồi, chúng ta sẽ thuê thêm vài người."
B: "Tôi không nhớ tên cô ấy."
C: "Nó thay đổi từ năm này qua năm khác."
Giải thích: Đáp án C đúng vì câu hỏi hỏi về thời điểm sân bay đông đúc nhất và đáp án C cho biết thời gian cao điểm có thể thay đổi hàng năm."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6013, 268, '2025/test9/audio/test9_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7614, 6013, 13, 'Are there any good restaurants near the conference center?', 'Just a salad for me, please.', 'You''d be better off going downtown.', 'The panel discussions are popular.', NULL, 'B', 'Câu hỏi: Có nhà hàng nào tốt gần trung tâm hội nghị không?"
A: "Chỉ một ít rau trộn thôi, cảm ơn."
B: "Bạn nên đi vào khu trung tâm thì tốt hơn."
C: "Các buổi thảo luận nhóm rất phổ biến."
Giải thích: Đáp án B đúng vì câu hỏi hỏi về các nhà hàng gần trung tâm hội nghị và đáp án B gợi ý rằng khu trung tâm có nhiều lựa chọn ăn uống tốt hơn."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6014, 268, '2025/test9/audio/test9_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7615, 6014, 14, 'Your company is based in Toronto, right?', 'Do you have flowers to put in this vase?', 'I''ll call a real estate agent today.', 'Actually, our headquarters are in Montreal.', NULL, 'C', 'Câu hỏi: Công ty của bạn có trụ sở tại Toronto phải không?"
A: "Bạn có hoa để bỏ vào bình này không?"
B: "Tôi sẽ gọi một đại lý bất động sản hôm nay."
C: "Thực ra, trụ sở của chúng tôi ở Montreal."
Giải thích: Đáp án C đúng vì câu hỏi hỏi về trụ sở công ty và đáp án C sửa lại thông tin về địa điểm trụ sở thực tế của công ty."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6015, 268, '2025/test9/audio/test9_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7616, 6015, 15, 'What should I bring to my first appointment?', 'Your insurance card is the most important thing.', 'To get a doctor''s opinion on my elbow injury.', 'As soon as we have an opening.', NULL, 'A', 'Câu hỏi: Tôi nên mang gì đến buổi hẹn đầu tiên?"
A: "Thẻ bảo hiểm của bạn là điều quan trọng nhất."
B: "Để nhận ý kiến từ bác sĩ về chấn thương khuỷu tay của tôi."
C: "Ngay khi chúng tôi có lịch trống."
Giải thích: Đáp án A đúng vì câu hỏi về việc chuẩn bị cho buổi hẹn và đáp án A cho biết thẻ bảo hiểm là thứ quan trọng nhất cần mang theo."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6016, 268, '2025/test9/audio/test9_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7617, 6016, 16, 'How many items are there on today''s agenda?', 'A new schedule for our team.', 'It should be a quick meeting.', 'They were, I think.', NULL, 'B', 'Câu hỏi: Có bao nhiêu mục trong lịch trình hôm nay?"
A: "Lịch trình mới cho nhóm của chúng ta."
B: "Nó nên là một cuộc họp nhanh chóng."
C: "Chúng đã có rồi, tôi nghĩ thế."
Giải thích: Đáp án B đúng vì câu hỏi về số lượng mục trong lịch trình và đáp án B cho biết cuộc họp hôm nay sẽ diễn ra nhanh chóng, cho thấy có ít mục trong lịch trình."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6017, 268, '2025/test9/audio/test9_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7618, 6017, 17, 'I''ve found some job candidates who meet your requirements.', 'That''s excellent news!', 'An interview and a skill test.', 'But I like my current job.', NULL, 'A', 'Câu hỏi: Tôi đã tìm thấy một số ứng viên phù hợp với yêu cầu của bạn." 
A: "Đó là tin tuyệt vời!"
B: "Một cuộc phỏng vấn và bài kiểm tra kỹ năng."
C: "Nhưng tôi thích công việc hiện tại của mình."
Giải thích: Đáp án A đúng vì câu hỏi về việc tìm kiếm ứng viên và đáp án A thể hiện sự vui mừng về tin tức tốt này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6018, 268, '2025/test9/audio/test9_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7619, 6018, 18, 'Where''s the taxi we ordered?', 'I haven''t heard any complaints.', 'At the bottom of your receipt.', 'This is the middle of rush hour.', NULL, 'C', 'Câu hỏi: Taxi mà chúng ta đã đặt đâu rồi?"
A: "Tôi chưa nghe thấy bất kỳ phàn nàn nào."
B: "Ở dưới cùng của biên lai của bạn."
C: "Đây là giờ cao điểm."
Giải thích: Đáp án C đúng vì câu hỏi về vị trí của taxi và đáp án C chỉ ra rằng đây là giờ cao điểm, có thể là lý do taxi chưa đến kịp."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6019, 268, '2025/test9/audio/test9_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7620, 6019, 19, 'Isn''t this year''s workshop a little longer than usual?', 'Usually new employees.', 'Yes, the instructor has added some content.', 'I had to visit a few different stores.', NULL, 'B', 'Câu hỏi: Workshop năm nay có dài hơn bình thường một chút không?"
A: "Thường thì là các nhân viên mới."
B: "Vâng, giảng viên đã thêm một số nội dung."
C: "Tôi đã phải thăm một vài cửa hàng khác nhau."
Giải thích: Đáp án B đúng vì câu hỏi về thời gian của workshop và đáp án B cho biết lý do là giảng viên đã thêm nội dung."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6020, 268, '2025/test9/audio/test9_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7621, 6020, 20, 'Would you rather take a tour or just explore the museum on our own?', 'No, I live in the area.', 'I''d love to take a few home.', 'Let''s look around by ourselves first.', NULL, 'C', 'Câu hỏi: Bạn muốn tham gia tour hay tự mình khám phá bảo tàng?"
A: "Không, tôi sống ở khu vực này."
B: "Tôi rất muốn mang một vài món về nhà."
C: "Chúng ta hãy tự khám phá trước." 
Giải thích: Đáp án C đúng vì câu hỏi về việc lựa chọn giữa tham gia tour và tự khám phá bảo tàng, và đáp án C là một câu trả lời hợp lý để khám phá trước."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6021, 268, '2025/test9/audio/test9_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7622, 6021, 21, 'You''re announcing the price increase to our clients, aren''t you?', 'Oh, was that decision finalized?', 'Our hiring announcement has a lot of views.', 'I''ll look for a good place to display our prize.', NULL, 'A', 'Câu hỏi: Bạn sẽ thông báo về việc tăng giá cho khách hàng phải không?"
A: "Ô, quyết định đó đã được xác nhận chưa?"
B: "Thông báo tuyển dụng của chúng ta có rất nhiều lượt xem."
C: "Tôi sẽ tìm một địa điểm tốt để trưng bày giải thưởng của chúng ta."
Giải thích: Đáp án A đúng vì câu hỏi về việc thông báo về tăng giá và đáp án A hỏi về việc quyết định đã được xác nhận hay chưa."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6022, 268, '2025/test9/audio/test9_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7623, 6022, 22, 'Why are all my photographs out of focus?', 'If we can find the time for it.', 'I''m good with cameras.', 'Coffee helps me focus.', NULL, 'B', 'Câu hỏi: Tại sao tất cả những bức ảnh của tôi lại mờ?"
A: "Nếu chúng ta có thể tìm thời gian cho việc đó."
B: "Tôi giỏi với máy ảnh."
C: "Cà phê giúp tôi tập trung."
Giải thích: Đáp án B đúng vì câu hỏi về việc tại sao các bức ảnh mờ và đáp án B chỉ ra rằng người trả lời giỏi với máy ảnh, ngụ ý rằng có thể xử lý được vấn đề này."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6023, 268, '2025/test9/audio/test9_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7624, 6023, 23, 'Where did you get your travel mug?', 'A client sent our team some thank-you gifts.', 'Thanks for reminding me!', 'No, not much - I don''t like to fly.', NULL, 'A', 'Câu hỏi: Bạn lấy cốc du lịch của mình ở đâu?"
A: "Một khách hàng đã gửi tặng đội ngũ của chúng tôi một số quà cảm ơn."
B: "Cảm ơn bạn đã nhắc tôi!"
C: "Không, không nhiều - tôi không thích đi máy bay."
Giải thích: Đáp án A đúng vì câu hỏi hỏi về nguồn gốc của chiếc cốc và đáp án A cho biết nó là món quà từ một khách hàng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6024, 268, '2025/test9/audio/test9_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7625, 6024, 24, 'Why aren''t you inviting local businesses to sponsor the festival?', 'Tickets are available online.', 'Six months in advance.', 'Medrano Fashions is a local company.', NULL, 'C', 'Câu hỏi: Tại sao bạn không mời các doanh nghiệp địa phương tài trợ cho lễ hội?"
A: "Vé có sẵn online."
B: "Sáu tháng trước."
C: "Medrano Fashions là một công ty địa phương."
Giải thích: Đáp án C đúng vì câu hỏi về lý do không mời các doanh nghiệp địa phương và đáp án C đưa ra một công ty địa phương."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6025, 268, '2025/test9/audio/test9_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7626, 6025, 25, 'The floor tile shipment has arrived.', 'It has twelve floors.', 'OK, send the forklifts over.', 'The lobby renovation.', NULL, 'B', 'Câu hỏi: Lô gạch sàn đã đến chưa?"
A: "Nó có mười hai tầng."
B: "Được rồi, gửi xe nâng qua."
C: "Việc cải tạo sảnh."
Giải thích: Đáp án B đúng vì câu hỏi về việc lô gạch sàn và đáp án B là phản hồi hợp lý khi có lô hàng đến, cần sử dụng xe nâng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6026, 268, '2025/test9/audio/test9_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7627, 6026, 26, 'What are the main ingredients of this dish?', 'No, the maintenance work is finished now.', 'It was canceled yesterday.', 'The menu only lists names and prices.', NULL, 'C', 'Câu hỏi: Các nguyên liệu chính của món ăn này là gì?"
A: "Không, công việc bảo trì đã hoàn thành rồi."
B: "Nó đã bị hủy hôm qua."
C: "Thực đơn chỉ liệt kê tên và giá."
Giải thích: Đáp án C đúng vì câu hỏi về các thành phần của món ăn và đáp án C cho biết thực đơn chỉ liệt kê tên và giá mà không cung cấp thông tin chi tiết về nguyên liệu."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6027, 268, '2025/test9/audio/test9_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7628, 6027, 27, 'Who from our department volunteered to help with the holiday party?', 'Yes, the decorations have been ordered.', 'An all-day parking pass.', 'I''d already booked my vacation for that week.', NULL, 'C', 'Câu hỏi: Ai trong phòng ban của chúng ta đã tình nguyện giúp đỡ với buổi tiệc lễ hội?"
A: "Vâng, những món trang trí đã được đặt."
B: "Một thẻ đậu xe cả ngày."
C: "Tôi đã đặt kỳ nghỉ của mình cho tuần đó."
Giải thích: Đáp án C đúng vì câu hỏi hỏi về ai tình nguyện giúp đỡ và đáp án C cho biết người trả lời đã đặt kỳ nghỉ của mình, ám chỉ họ không thể tham gia."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6028, 268, '2025/test9/audio/test9_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7629, 6028, 28, 'Shouldn''t we schedule a time to practice our presentation?', 'A successful medical practice.', 'I''ll grab my calendar.', 'The large conference room is nice.', NULL, 'B', 'Câu hỏi: Chúng ta không nên lên lịch thời gian để luyện tập bài thuyết trình sao?"
A: "Một phòng khám y tế thành công."
B: "Tôi sẽ lấy lịch của mình."
C: "Phòng họp lớn rất đẹp."
Giải thích: Đáp án B đúng vì câu hỏi về việc luyện tập bài thuyết trình và đáp án B là một cách phù hợp để lên lịch."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6029, 268, '2025/test9/audio/test9_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7630, 6029, 29, 'Where can I find the outdoor swimming pool?', 'Yes, I watched the championship on TV.', 'Our seasonal facilities aren''t open yet.', 'Mostly families with young children.', NULL, 'B', 'Câu hỏi: Tôi có thể tìm bể bơi ngoài trời ở đâu?"
A: "Vâng, tôi đã xem trận chung kết trên TV."
B: "Các cơ sở mùa vụ của chúng tôi chưa mở cửa." 
C: "Chủ yếu là các gia đình có trẻ em nhỏ."
Giải thích: Đáp án B đúng vì câu hỏi về việc tìm bể bơi ngoài trời và đáp án B cho biết các cơ sở mùa vụ chưa mở cửa."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6030, 268, '2025/test9/audio/test9_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7631, 6030, 30, 'Don''t you usually work weekend shifts?', 'Samantha called in sick today.', 'On the counter next to the register.', 'I have a monthly membership.', NULL, 'A', 'Câu hỏi: Bạn không thường làm ca cuối tuần sao?"
A: "Samantha gọi điện báo ốm hôm nay."
B: "Ở trên quầy gần máy tính tiền."
C: "Tôi có thẻ hội viên tháng."
Giải thích: Đáp án A đúng vì câu hỏi về ca làm việc cuối tuần và đáp án A trả lời bằng lý do người trả lời không làm việc cuối tuần."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6031, 268, '2025/test9/audio/test9_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7632, 6031, 31, 'Who can I talk to about a problem with my company laptop?', 'Tech help requests must be made electronically.', 'No, I haven''t downloaded it yet.', 'In the top drawer of the filing cabinet.', NULL, 'A', 'Câu hỏi: Tôi có thể nói chuyện với ai về vấn đề với máy tính xách tay công ty?"
A: "Yêu cầu trợ giúp kỹ thuật phải được gửi điện tử."
B: "Không, tôi chưa tải nó xuống."
C: "Ở ngăn kéo trên cùng của tủ hồ sơ."
Giải thích: Đáp án A đúng vì câu hỏi về việc báo cáo vấn đề với máy tính và đáp án A chỉ rõ rằng yêu cầu trợ giúp kỹ thuật phải thực hiện qua điện tử."');;

-- Data for 2025 Test9 Part 3
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6032, 269, '2025/test9/audio/test9_question_32_34.mp3', NULL, 'W-Br: Hi, l''m Paula Gutierrez, and I''m here to pick up a custom cake order. It''s vanilla-flavored and should be decorated with frosting in the shape of roses.
M-Cn: Yes, here''s your order. Let me remove the lid of the box so you can confirm that the message is correct.
W-Br: It''s perfect, as always. I appreciate that I can count on the staff here to do a great job.
M-Cn: Thank you. Now, it sounds like you''re a regular customer- would you still like one of these cards with transport and storage instructions for the cake?
W-Br: Sure, just in case.', 'Nữ: Chào, tôi là Paula Gutierrez, và tôi đến để lấy đơn đặt bánh riêng. Đó là bánh vị vanilla và được trang trí bằng kem hình hoa hồng.
Nam: Vâng, đây là đơn hàng của chị. Để tôi mở nắp hộp ra để chị có thể xác nhận thông điệp đã đúng chưa.
Nữ: Nó hoàn hảo, như mọi khi. Tôi đánh giá cao việc tôi có thể tin tưởng nhân viên ở đây làm việc tốt.
Nam: Cảm ơn chị. Giờ, nghe có vẻ chị là khách hàng thường xuyên - chị vẫn muốn một trong những tấm thẻ có hướng dẫn vận chuyển và bảo quản bánh chứ?
Nữ: Vâng, để phòng khi cần.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7633, 6032, 32, 'Where does the man most likely work?', 'At a bakery', 'At a florist shop', 'At a jewelry store', 'At a tailor shop', 'A', 'Question: "Where does the man most likely work?" (Người đàn ông nhiều khả năng làm việc ở đâu?)
A: At a bakery (Tại một tiệm bánh)
B: At a florist shop (Tại một cửa hàng hoa)
C: At a jewelry store (Tại một cửa hàng trang sức)
D: At a tailor shop (Tại một tiệm may)

Người đàn ông làm việc tại một tiệm bánh vì:
1. Khách hàng đến lấy bánh đặt riêng (custom cake order)
2. Bánh được trang trí bằng kem hình hoa hồng
3. Có thẻ hướng dẫn vận chuyển và bảo quản bánh');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6033, 269, '2025/test9/audio/test9_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7634, 6033, 33, 'What does the woman like about the business?', 'Its fast service', 'Its friendly staff', 'Its high-quality work', 'Its reasonable pricing', 'C', 'Question: "What does the woman like about the business?" (Người phụ nữ thích điều gì ở doanh nghiệp này?)
A: Its fast service (Dịch vụ nhanh chóng)
B: Its friendly staff (Nhân viên thân thiện)
C: Its high-quality work (Công việc chất lượng cao)
D: Its reasonable pricing (Giá cả hợp lý)

Người phụ nữ đánh giá cao chất lượng công việc của tiệm bánh. Cô ấy nói: "I appreciate that I can count on the staff here to do a great job" (Tôi đánh giá cao việc tôi có thể tin tưởng nhân viên ở đây làm việc tốt).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6034, 269, '2025/test9/audio/test9_question_32_34.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7635, 6034, 34, 'What does the woman accept from the man?', 'A receipt', 'Some samples', 'A discount coupon', 'Some instructions', 'D', 'Question: "What does the woman accept from the man?" (Người phụ nữ nhận gì từ người đàn ông?)
A: A receipt (Một hóa đơn)
B: Some samples (Một số mẫu)
C: A discount coupon (Một phiếu giảm giá)
D: Some instructions (Một số hướng dẫn)

Người phụ nữ nhận thẻ hướng dẫn vận chuyển và bảo quản bánh từ người đàn ông. Khi được hỏi "would you still like one of these cards with transport and storage instructions for the cake?" (chị vẫn muốn một trong những tấm thẻ có hướng dẫn vận chuyển và bảo quản bánh chứ?), cô ấy đồng ý "Sure, just in case" (Vâng, để phòng khi cần).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6035, 269, '2025/test9/audio/test9_question_35_37.mp3', NULL, 'M-Au: Excuse me, I''ve made my decision. l''ll take this tablet computer-the one that comes with the free carrying case.
W-Am: OK, I''ll ring you up... Oh, l''m so sorry, but we''ve just given out the last carrying case we had in stock. You can still get one, but you''ll have to wait a few days.
M-Au: I don''t live nearby. Will I have to come back here?
W-Am: No-if you give me your address, I can have it shipped to you at no charge.
M-Au: Thanks, that''d be great.', 'Nam: Xin lỗi, tôi đã quyết định rồi. Tôi sẽ lấy máy tính bảng này - cái đi kèm với túi đựng miễn phí.
Nữ: OK, để tôi tính tiền... Ồ, tôi rất xin lỗi, nhưng chúng tôi vừa phát hết túi đựng cuối cùng trong kho. Anh vẫn có thể nhận được một cái, nhưng sẽ phải đợi vài ngày.
Nam: Tôi không sống gần đây. Tôi có phải quay lại đây không?
Nữ: Không - nếu anh cho tôi địa chỉ, tôi có thể gửi nó đến cho anh miễn phí.
Nam: Cảm ơn, tuyệt quá.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7636, 6035, 35, 'Where does the conversation most likely take place?', 'At a print shop', 'At a repair shop', 'At an electronics store', 'At a sporting goods store', 'C', 'Question: "Where does the conversation most likely take place?" (Cuộc đối thoại nhiều khả năng diễn ra ở đâu?)
A: At a print shop (Tại một cửa hàng in ấn)
B: At a repair shop (Tại một cửa hàng sửa chữa)
C: At an electronics store (Tại một cửa hàng điện tử)
D: At a sporting goods store (Tại một cửa hàng đồ thể thao)

Cuộc đối thoại diễn ra tại một cửa hàng điện tử vì:
1. Khách hàng đang mua máy tính bảng (tablet computer)
2. Có chương trình tặng kèm túi đựng máy tính
3. Đây là những sản phẩm điển hình của cửa hàng điện tử');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6036, 269, '2025/test9/audio/test9_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7637, 6036, 36, 'Why does the woman apologize?', 'A product is out of stock', 'A computer is not working', 'An employee is absent', 'A sales promotion has ended', 'A', 'Question: "Why does the woman apologize?" (Tại sao người phụ nữ xin lỗi?)
A: A product is out of stock (Một sản phẩm đã hết hàng)
B: A computer is not working (Một máy tính không hoạt động)
C: An employee is absent (Một nhân viên vắng mặt)
D: A sales promotion has ended (Một chương trình khuyến mãi đã kết thúc)

Người phụ nữ xin lỗi vì cửa hàng đã hết túi đựng máy tính trong kho: "we''ve just given out the last carrying case we had in stock" (chúng tôi vừa phát hết túi đựng cuối cùng trong kho).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6037, 269, '2025/test9/audio/test9_question_35_37.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7638, 6037, 37, 'What does the woman offer to do for the man?', 'Take a message', 'Restart a device', 'Check a storage room', 'Ship an item to him', 'D', 'Question: "What does the woman offer to do for the man?" (Người phụ nữ đề nghị làm gì cho người đàn ông?)
A: Take a message (Nhận tin nhắn)
B: Restart a device (Khởi động lại thiết bị)
C: Kiểm tra phòng lưu trữ
D: Ship an item to him (Gửi một món hàng cho anh ấy)

Người phụ nữ đề nghị gửi túi đựng đến địa chỉ của người đàn ông miễn phí: "if you give me your address, I can have it shipped to you at no charge" (nếu anh cho tôi địa chỉ, tôi có thể gửi nó đến cho anh miễn phí).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6038, 269, '2025/test9/audio/test9_question_38_40.mp3', NULL, 'w-Br: OK, Mr. Crane, I''ll turn my computer screen around so you can see this online listing. I think this property would be a great location for your café.
M-Au: Oh, that is a nice place. What charming architecture.
w-Br: Yes, that''s what I thought. It''s nine hundred square feet, and the location is... fifteen hundred Fogle Bay Road.
M-Au: Oh... that''s pretty far outside of town.
w-Br: Sure, that''s true. Alright, then there''s another promising option on Grant Street. Let me take a moment to find it.
M-Au: Grant Street? Is that neighborhood within my budget?
W-Br: It''s not as expensive as you might think.', 'Nữ: OK, anh Crane, tôi sẽ xoay màn hình máy tính để anh có thể xem danh sách trực tuyến này. Tôi nghĩ địa điểm này sẽ là một vị trí tuyệt vời cho quán cà phê của anh.
Nam: Ồ, đó là một nơi đẹp. Kiến trúc thật quyến rũ.
Nữ: Vâng, đó là điều tôi nghĩ. Nó rộng chín trăm feet vuông, và địa chỉ là... một nghìn năm trăm đường Fogle Bay.
Nam: Ồ... điều đó khá xa trung tâm thành phố.
Nữ: Đúng vậy, điều đó đúng. Được rồi, vậy còn một lựa chọn đầy hứa hẹn khác trên đường Grant. Để tôi mất một chút thời gian để tìm nó.
Nam: Đường Grant? Khu vực đó có nằm trong ngân sách của tôi không?
Nữ: Nó không đắt như anh nghĩ đâu.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7639, 6038, 38, 'What does the woman show the man?', 'A city map', 'A business card', 'A Web page', 'A brochure', 'C', 'Question: "What does the woman show the man?" (Người phụ nữ cho người đàn ông xem gì?)
A: A city map (Một bản đồ thành phố)
B: A business card (Một danh thiếp)
C: A Web page (Một trang web)
D: A brochure (Một tờ rơi)

Người phụ nữ cho người đàn ông xem một danh sách bất động sản trực tuyến trên màn hình máy tính của cô ấy: "I''ll turn my computer screen around so you can see this online listing" (Tôi sẽ xoay màn hình máy tính để anh có thể xem danh sách trực tuyến này).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6039, 269, '2025/test9/audio/test9_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7640, 6039, 39, 'Why does the man say, "that''s pretty far outside of town"?', 'To ask for help with a move', 'To reject a suggested property', 'To point out misinformation in a listing', 'To express concern about an appointment time', 'B', 'Question: "Why does the man say, ''that''s pretty far outside of town''?" (Tại sao người đàn ông nói "điều đó khá xa trung tâm thành phố"?)
A: To ask for help with a move (Để xin giúp đỡ về việc chuyển nhà)
B: To reject a suggested property (Để từ chối một bất động sản được đề xuất)
C: To point out misinformation in a listing (Để chỉ ra thông tin sai trong danh sách)
D: To express concern about an appointment time (Để bày tỏ lo ngại về thời gian hẹn)

Người đàn ông nói câu này để từ chối địa điểm được đề xuất vì nó quá xa trung tâm thành phố. Sau đó, người phụ nữ cũng đồng ý: "Sure, that''s true" và đề xuất một địa điểm khác trên đường Grant.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6040, 269, '2025/test9/audio/test9_question_38_40.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7641, 6040, 40, 'What does the man ask about?', 'An area''s affordability', 'A parking facility', 'A building''s condition', 'A person''s availability', 'A', 'Question: "What does the man ask about?" (Người đàn ông hỏi về điều gì?)
A: An area''s affordability (Khả năng chi trả cho một khu vực)
B: A parking facility (Bãi đậu xe)
C: A building''s condition (Tình trạng của tòa nhà)
D: A person''s availability (Sự sẵn có của một người)

Người đàn ông hỏi về khả năng chi trả cho khu vực đường Grant: "Is that neighborhood within my budget?" (Khu vực đó có nằm trong ngân sách của tôi không?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6041, 269, '2025/test9/audio/test9_question_41_43.mp3', NULL, 'M-cn: Mayumi, do you think that the city mayor''s proposal to ban disposable coffee cups would be a good discussion topic for my advanced English classes?
w-Br: Yes, but- keep in mind that most people have misunderstood that proposal. They don''t realize that it''s only non-recyclable cups that would be banned.
M-cn: Oh, I didn''t actually realize that. l''d better research the details of the proposal before I start my lesson planning.', 'Nam: Mayumi, bạn có nghĩ rằng đề xuất của thị trưởng thành phố về việc cấm cốc cà phê dùng một lần sẽ là một chủ đề thảo luận tốt cho các lớp tiếng Anh nâng cao của tôi không?
Nữ: Có, nhưng - hãy nhớ rằng hầu hết mọi người đã hiểu sai đề xuất đó. Họ không nhận ra rằng nó chỉ cấm những cốc không thể tái chế.
Nam: Ồ, tôi thực sự không nhận ra điều đó. Tôi nên nghiên cứu chi tiết về đề xuất trước khi bắt đầu lập kế hoạch bài giảng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7642, 6041, 41, 'Who most likely is the man?', 'A city official', 'A café owner', 'A language teacher', 'A newspaper reporter', 'C', 'Question: "Who most likely is the man?" (Người đàn ông nhiều khả năng là ai?)
A: A city official (Một viên chức thành phố)
B: A café owner (Một chủ quán cà phê)
C: A language teacher (Một giáo viên ngôn ngữ)
D: A newspaper reporter (Một phóng viên báo chí)

Người đàn ông nhiều khả năng là một giáo viên dạy tiếng Anh vì:
1. Anh ấy đề cập đến "my advanced English classes" (lớp tiếng Anh nâng cao của tôi)
2. Anh ấy đang tìm chủ đề thảo luận cho lớp học
3. Anh ấy nói về việc lập kế hoạch bài giảng: "before I start my lesson planning" (trước khi tôi bắt đầu lập kế hoạch bài giảng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6042, 269, '2025/test9/audio/test9_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7643, 6042, 42, 'What does the woman say about a proposal?', 'It will go into effect next year', 'It is misunderstood by the public', 'It will be expensive to implement', 'It was inspired by laws in other cities', 'B', 'Question: "What does the woman say about a proposal?" (Người phụ nữ nói gì về một đề xuất?)
A: It will go into effect next year (Nó sẽ có hiệu lực vào năm tới)
B: It is misunderstood by the public (Nó bị công chúng hiểu sai)
C: It will be expensive to implement (Nó sẽ tốn kém để thực hiện)
D: It was inspired by laws in other cities (Nó được lấy cảm hứng từ luật ở các thành phố khác)

Người phụ nữ chỉ ra rằng công chúng đã hiểu sai đề xuất: "most people have misunderstood that proposal. They don''t realize that it''s only non-recyclable cups that would be banned" (hầu hết mọi người đã hiểu sai đề xuất đó. Họ không nhận ra rằng nó chỉ cấm những cốc không thể tái chế).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6043, 269, '2025/test9/audio/test9_question_41_43.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7644, 6043, 43, 'What does the man decide to do?', 'Join a volunteer group', 'Revise a timeline', 'Post on social media', 'Conduct some research', 'D', 'Question: "What does the man decide to do?" (Người đàn ông quyết định làm gì?)
A: Join a volunteer group (Tham gia một nhóm tình nguyện)
B: Revise a timeline (Sửa đổi thời gian biểu)
C: Post on social media (Đăng trên mạng xã hội)
D: Conduct some research (Thực hiện một số nghiên cứu)

Người đàn ông quyết định sẽ nghiên cứu thêm về chi tiết của đề xuất: "I''d better research the details of the proposal before I start my lesson planning" (Tôi nên nghiên cứu chi tiết về đề xuất trước khi bắt đầu lập kế hoạch bài giảng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6044, 269, '2025/test9/audio/test9_question_44_46.mp3', NULL, 'w-Br: Mr. Gordon, there''s something wrong with one of the washing machines. Water started leaking from it after I put in a load of bedsheets from Craddock Hotel.
M-Au: Which machine is it?
w-Br: This one. I turned it off.
M-Au: Oh, it''s probably because of the supply hose. I unscrewed the hoses on this row of machines last night to clear out their intake filters. I must not have reconnected this one tightly enough. I''ll fix it.
w-Br: Oh, OK. Would you like me to mop up this water? It''s making the floor slippery.', 'Nữ: Anh Gordon, có vấn đề với một trong những máy giặt. Nước bắt đầu rò rỉ từ nó sau khi tôi cho vào một mẻ ga trải giường từ Khách sạn Craddock.
Nam: Máy nào vậy?
Nữ: Máy này. Tôi đã tắt nó rồi.
Nam: Ồ, có lẽ là do ống cấp nước. Tôi đã tháo các ống trên dãy máy này tối qua để vệ sinh bộ lọc nạp. Chắc tôi đã không kết nối lại cái này đủ chặt. Tôi sẽ sửa nó.
Nữ: Ồ, vâng. Anh có muốn tôi lau nước này không? Nó đang làm sàn nhà trơn trượt.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7645, 6044, 44, 'Where do the speakers most likely work?', 'In a laundry facility', 'In an appliance store', 'In a medical center', 'In a hotel kitchen', 'A', 'Question: "Where do the speakers most likely work?" (Những người nói chuyện nhiều khả năng làm việc ở đâu?)
A: In a laundry facility (Trong một cơ sở giặt ủi)
B: In an appliance store (Trong một cửa hàng thiết bị)
C: In a medical center (Trong một trung tâm y tế)
D: In a hotel kitchen (Trong một nhà bếp khách sạn)

Họ làm việc tại một cơ sở giặt ủi vì:
1. Họ đang giặt ga trải giường từ Khách sạn Craddock: "a load of bedsheets from Craddock Hotel"
2. Có nhiều máy giặt được sắp xếp thành hàng: "hoses on this row of machines"
3. Đây là một cơ sở chuyên giặt ủi cho khách sạn');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6045, 269, '2025/test9/audio/test9_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7646, 6045, 45, 'According to the man, what probably caused a problem?', 'A setting was not adjusted', 'A material is not water-resistant', 'A part was not connected properly', 'A power outage occurred last night', 'C', 'Question: "According to the man, what probably caused a problem?" (Theo người đàn ông, điều gì có thể đã gây ra vấn đề?)
A: A setting was not adjusted (Một cài đặt không được điều chỉnh)
B: A material is not water-resistant (Một vật liệu không chống thấm nước)
C: A part was not connected properly (Một bộ phận không được kết nối đúng cách)
D: A power outage occurred last night (Mất điện xảy ra tối qua)

Theo người đàn ông, vấn đề là do ống cấp nước không được kết nối lại đủ chặt: "I must not have reconnected this one tightly enough" (Chắc tôi đã không kết nối lại cái này đủ chặt).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6046, 269, '2025/test9/audio/test9_question_44_46.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7647, 6046, 46, 'What does the woman offer to do?', 'Clean up a hazard', 'Schedule a training', 'Locate a warranty', 'Call a repair person', 'A', 'Question: "What does the woman offer to do?" (Người phụ nữ đề nghị làm gì?)
A: Clean up a hazard (Dọn dẹp một mối nguy hiểm)
B: Schedule a training (Lên lịch đào tạo)
C: Locate a warranty (Tìm giấy bảo hành)
D: Call a repair person (Gọi thợ sửa chữa)

Người phụ nữ đề nghị lau dọn nước tràn ra sàn vì nó gây nguy hiểm: "Would you like me to mop up this water? It''s making the floor slippery" (Anh có muốn tôi lau nước này không? Nó đang làm sàn nhà trơn trượt).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6047, 269, '2025/test9/audio/test9_question_47_49.mp3', NULL, 'W-Am: Can you believe we''ve been leading this book club for a year now? How do the two of you feel about the way it''s going?
M-Au: Actually, Dan and I were talking the other day, and-we''re a little frustrated. It seems like we can''t have an in-depth discussion because the majority of people don''t finish the book. We''d like to make it a rule that members have to read the whole book in order to participate in the meeting.
M-cn: Right. But we''re also worried that if we did that, some meetings would only have three or four participants.
w-Am: Yes, we don''t want to lose members. Hmm... what about dividing the books into multiple sections? People would be more likely to finish the reading if it were just a few chapters.', 'Nữ: Các bạn có tin là chúng ta đã điều hành câu lạc bộ sách này được một năm rồi không? Hai bạn cảm thấy thế nào về cách nó đang diễn ra?
Nam 1: Thực ra, Dan và tôi đã nói chuyện hôm nọ, và - chúng tôi hơi thất vọng. Có vẻ như chúng ta không thể có cuộc thảo luận sâu vì đa số người không đọc xong sách. Chúng tôi muốn đặt ra quy tắc là thành viên phải đọc hết sách để được tham gia cuộc họp.
Nam 2: Đúng vậy. Nhưng chúng tôi cũng lo lắng rằng nếu làm vậy, một số cuộc họp sẽ chỉ có ba hoặc bốn người tham gia.
Nữ: Vâng, chúng ta không muốn mất thành viên. Hmm... còn việc chia sách thành nhiều phần thì sao? Mọi người sẽ có nhiều khả năng đọc xong hơn nếu chỉ là một vài chương.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7648, 6047, 47, 'What do members of the speakers'' club do together?', 'Discuss books', 'Play a sport', 'Take photographs', 'Make handicrafts', 'A', 'Question: "What do members of the speakers'' club do together?" (Các thành viên của câu lạc bộ làm gì cùng nhau?)
A: Discuss books (Thảo luận sách)
B: Play a sport (Chơi thể thao)
C: Take photographs (Chụp ảnh)
D: Make handicrafts (Làm đồ thủ công)

Đây là một câu lạc bộ sách, nơi các thành viên cùng nhau thảo luận về sách. Điều này được thể hiện qua:
1. "leading this book club" (điều hành câu lạc bộ sách này)
2. "can''t have an in-depth discussion because the majority of people don''t finish the book" (không thể có cuộc thảo luận sâu vì đa số người không đọc xong sách)
3. Đề xuất yêu cầu đọc hết sách để tham gia cuộc họp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6048, 269, '2025/test9/audio/test9_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7649, 6048, 48, 'What is the conversation mainly about?', 'A learning opportunity', 'A change in leadership', 'A promotional campaign', 'A requirement for members', 'D', 'Question: "What is the conversation mainly about?" (Cuộc trò chuyện chủ yếu về điều gì?)
A: A learning opportunity (Một cơ hội học tập)
B: A change in leadership (Một sự thay đổi trong lãnh đạo)
C: A promotional campaign (Một chiến dịch quảng bá)
D: A requirement for members (Một yêu cầu cho thành viên)

Cuộc trò chuyện chủ yếu về việc thảo luận một yêu cầu mới cho thành viên:
1. Đề xuất quy tắc bắt buộc đọc hết sách để tham gia: "members have to read the whole book in order to participate"
2. Thảo luận về tác động của yêu cầu này đến số lượng người tham gia
3. Tìm giải pháp thay thế để không mất thành viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6049, 269, '2025/test9/audio/test9_question_47_49.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7650, 6049, 49, 'What are the men concerned about?', 'Covering an additional expense', 'Having too few participants', 'Transporting some supplies', 'Giving incorrect time estimates', 'B', 'Question: "What are the men concerned about?" (Những người đàn ông lo lắng về điều gì?)
A: Covering an additional expense (Chi trả một khoản chi phí bổ sung)
B: Having too few participants (Có quá ít người tham gia)
C: Transporting some supplies (Vận chuyển một số vật tư)
D: Giving incorrect time estimates (Đưa ra ước tính thời gian không chính xác)

Những người đàn ông lo lắng về việc sẽ có quá ít người tham gia nếu áp dụng quy tắc mới: "if we did that, some meetings would only have three or four participants" (nếu làm vậy, một số cuộc họp sẽ chỉ có ba hoặc bốn người tham gia).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6050, 269, '2025/test9/audio/test9_question_50_52.mp3', NULL, 'W-Br: Hello, Mr. Joo? This is Shannon Nichols from Nason Professionals. We''re a staffing agency based in Flintwood.
M-Au: Hi, Ms. Nichols. What can I do for you today?
w-Br: Well, I see that you''re the head of human resources for VNX Technology. I''d like to tell you about the benefits of hiring Nason to fill vacancies at your company.
M-Au: Oh, I might be interested, but I don''t have time to talk now.
w-Br: I understand. May I have your e-mail address, so that I can send you a list of our service rates? You could look over it when you''re free.', 'Nữ: Xin chào, anh Joo? Tôi là Shannon Nichols từ Nason Professionals. Chúng tôi là một công ty tuyển dụng có trụ sở tại Flintwood.
Nam: Chào, chị Nichols. Tôi có thể giúp gì cho chị hôm nay?
Nữ: Vâng, tôi thấy anh là trưởng phòng nhân sự của VNX Technology. Tôi muốn nói với anh về những lợi ích của việc thuê Nason để tuyển dụng nhân sự cho công ty anh.
Nam: Ồ, tôi có thể quan tâm, nhưng tôi không có thời gian nói chuyện bây giờ.
Nữ: Tôi hiểu. Tôi có thể xin địa chỉ email của anh được không, để tôi có thể gửi cho anh danh sách mức phí dịch vụ của chúng tôi? Anh có thể xem qua khi rảnh.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7651, 6050, 50, 'What type of business does the woman work for?', 'A department store', 'An insurance company', 'An employment agency', 'A landscaping firm', 'C', 'Question: "What type of business does the woman work for?" (Người phụ nữ làm việc cho loại hình doanh nghiệp nào?)
A: A department store (Một cửa hàng bách hóa)
B: An insurance company (Một công ty bảo hiểm)
C: An employment agency (Một công ty tuyển dụng)
D: A landscaping firm (Một công ty thiết kế cảnh quan)

Người phụ nữ làm việc cho một công ty tuyển dụng vì:
1. Cô ấy giới thiệu công ty là "staffing agency" (công ty tuyển dụng)
2. Cô ấy muốn giới thiệu về lợi ích của việc thuê công ty họ để tuyển dụng: "benefits of hiring Nason to fill vacancies"
3. Cô ấy đang nói chuyện với giám đốc nhân sự của một công ty khác');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6051, 269, '2025/test9/audio/test9_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7652, 6051, 51, 'Why is the woman calling the man?', 'To advertise a business', 'To arrange a workshop', 'To offer him a job', 'To inquire about a loan', 'A', 'Question: "Why is the woman calling the man?" (Tại sao người phụ nữ gọi cho người đàn ông?)
A: To advertise a business (Để quảng cáo một doanh nghiệp)
B: To arrange a workshop (Để sắp xếp một hội thảo)
C: To offer him a job (Để đề nghị anh ấy một công việc)
D: To inquire about a loan (Để hỏi về một khoản vay)

Người phụ nữ gọi điện để quảng cáo dịch vụ của công ty cô ấy: "I''d like to tell you about the benefits of hiring Nason to fill vacancies at your company" (Tôi muốn nói với anh về những lợi ích của việc thuê Nason để tuyển dụng nhân sự cho công ty anh).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6052, 269, '2025/test9/audio/test9_question_50_52.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7653, 6052, 52, 'What document does the woman mention?', 'An agreement', 'A résumé', 'A rates sheet', 'A client testimonial', 'C', 'Question: "What document does the woman mention?" (Người phụ nữ đề cập đến tài liệu gì?)
A: An agreement (Một thỏa thuận)
B: A résumé (Một hồ sơ)
C: A rates sheet (Một bảng giá)
D: A client testimonial (Một lời chứng thực của khách hàng)

Người phụ nữ đề cập đến việc gửi bảng giá dịch vụ qua email: "send you a list of our service rates" (gửi cho anh danh sách mức phí dịch vụ của chúng tôi).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6053, 269, '2025/test9/audio/test9_question_53_55.mp3', NULL, 'W-Am: Cedric, do you know much about our travel reimbursement system? I submitted the receipts for my visit to the Guangdong factory last month, and the company still hasn''t paid me back.
M-cn: Oh, I haven''t been on a work trip in years, so l''ve forgotten how everything works. But you know... the employee handbook is very detailed.
W-Am: Oh, right! Thanks, I''ll take a look.
M-Cn: No problem. And that reminds me- l''m sorry, but I seem to have lost my copy of your report on that factory. Could you e-mail me a digital version?', 'Nữ: Cedric, anh có biết nhiều về hệ thống hoàn tiền đi lại của chúng ta không? Tôi đã nộp hóa đơn cho chuyến thăm nhà máy Guangdong tháng trước, và công ty vẫn chưa trả lại tiền cho tôi.
Nam: Ồ, tôi đã không đi công tác nhiều năm rồi, nên tôi đã quên mọi thứ hoạt động như thế nào. Nhưng bạn biết đấy... sổ tay nhân viên có rất nhiều chi tiết.
Nữ: Ồ, đúng rồi! Cảm ơn, tôi sẽ xem qua.
Nam: Không có gì. Và điều đó nhắc tôi - xin lỗi, nhưng có vẻ như tôi đã làm mất bản sao báo cáo của bạn về nhà máy đó. Bạn có thể gửi email cho tôi một bản kỹ thuật số được không?');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7654, 6053, 53, 'What problem does the woman describe?', 'A receipt is missing some information', 'A reimbursement has not been issued', 'Some travel plans have not been completed', 'The budget for a trip is very limited', 'B', 'Question: "What problem does the woman describe?" (Người phụ nữ mô tả vấn đề gì?)
A: A receipt is missing some information (Một hóa đơn thiếu một số thông tin)
B: A reimbursement has not been issued (Một khoản hoàn tiền chưa được chi trả)
C: Some travel plans have not been completed (Một số kế hoạch đi lại chưa hoàn thành)
D: The budget for a trip is very limited (Ngân sách cho một chuyến đi rất hạn chế)

Người phụ nữ mô tả vấn đề chưa được hoàn tiền cho chuyến công tác: "the company still hasn''t paid me back" (công ty vẫn chưa trả lại tiền cho tôi) sau khi cô ấy đã nộp hóa đơn cho chuyến thăm nhà máy Guangdong tháng trước.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6054, 269, '2025/test9/audio/test9_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7655, 6054, 54, 'Why does the man say, "the employee handbook is very detailed"?', 'To give a recommendation', 'To decline an offer', 'To indicate frustration', 'To praise an accomplishment', 'A', 'Question: "Why does the man say, ''the employee handbook is very detailed''?" (Tại sao người đàn ông nói "sổ tay nhân viên có rất nhiều chi tiết"?)
A: To give a recommendation (Để đưa ra một khuyến nghị)
B: To decline an offer (Để từ chối một đề nghị)
C: To indicate frustration (Để thể hiện sự thất vọng)
D: To praise an accomplishment (Để khen ngợi một thành tựu)

Người đàn ông đề xuất người phụ nữ tham khảo sổ tay nhân viên vì:
1. Anh ấy không thể giúp trực tiếp: "I haven''t been on a work trip in years" (tôi đã không đi công tác nhiều năm rồi)
2. Anh ấy gợi ý sổ tay nhân viên như một nguồn thông tin hữu ích để giải quyết vấn đề của cô ấy');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6055, 269, '2025/test9/audio/test9_question_53_55.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7656, 6055, 55, 'Why does the man apologize?', 'He forgot to process a request', 'He did not read an e-mail carefully', 'He is not allowed to discuss an issue', 'He has misplaced a report', 'D', 'Question: "Why does the man apologize?" (Tại sao người đàn ông xin lỗi?)
A: He forgot to process a request (Anh ấy quên xử lý một yêu cầu)
B: He did not read an e-mail carefully (Anh ấy không đọc kỹ một email)
C: He is not allowed to discuss an issue (Anh ấy không được phép thảo luận về một vấn đề)
D: He has misplaced a report (Anh ấy đã làm mất một báo cáo)
');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6056, 269, '2025/test9/audio/test9_question_56_58.mp3', NULL, 'M-Au: Julie, the representative from Quigley Movers came by this morning to discuss using the windows for our move, right? What did he say?
W-Am: Unfortunately, the space next to our side of the building is too narrow for their equipment. So we won''t be able to get our metalworking machinery out through the windows.
w-Br: That''s disappointing. Then we''ll have to postpone our move to the new studio, right?
M-Au: We shouldn''t have to do that just because the freight elevator is out of order. I think we should check our lease agreement. There may be a clause in there that requires the landlord to fix the elevators promptly.', 'Nam: Julie, đại diện từ Quigley Movers đã ghé qua sáng nay để thảo luận về việc sử dụng cửa sổ cho việc chuyển đồ của chúng ta, phải không? Anh ấy nói gì?
Nữ 1: Không may là, khoảng trống bên cạnh tòa nhà của chúng ta quá hẹp cho thiết bị của họ. Vì vậy chúng ta sẽ không thể đưa máy móc gia công kim loại ra ngoài qua cửa sổ được.
Nữ 2: Thật đáng thất vọng. Vậy chúng ta sẽ phải hoãn việc chuyển đến xưởng mới, phải không?
Nam: Chúng ta không nên làm vậy chỉ vì thang máy chở hàng đang hỏng. Tôi nghĩ chúng ta nên kiểm tra hợp đồng thuê. Có thể có điều khoản yêu cầu chủ nhà sửa thang máy nhanh chóng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7657, 6056, 56, 'Who visited the speakers'' workplace this morning?', 'A property appraiser', 'A safety inspector', 'A building contractor', 'A moving company agent', 'D', 'Question: "Who visited the speakers'' workplace this morning?" (Ai đã đến thăm nơi làm việc của những người nói chuyện sáng nay?)
A: A property appraiser (Một người định giá bất động sản)
B: A safety inspector (Một thanh tra an toàn)
C: A building contractor (Một nhà thầu xây dựng)
D: A moving company agent (Một đại diện công ty chuyển nhà)

Đại diện từ công ty chuyển nhà Quigley Movers đã đến thăm: "the representative from Quigley Movers came by this morning" (đại diện từ Quigley Movers đã ghé qua sáng nay).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6057, 269, '2025/test9/audio/test9_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7658, 6057, 57, 'What problem does Julie mention?', 'A window was installed incorrectly', 'A permit has not been approved', 'Some machinery has been disassembled', 'A space is not wide enough for some equipment', 'D', 'Question: "What problem does Julie mention?" (Julie đề cập đến vấn đề gì?)
A: A window was installed incorrectly (Một cửa sổ được lắp đặt không đúng cách)
B: A permit has not been approved (Một giấy phép chưa được phê duyệt)
C: Some machinery has been disassembled (Một số máy móc đã được tháo rời)
D: A space is not wide enough for some equipment (Một khoảng trống không đủ rộng cho một số thiết bị)

Julie nói rằng khoảng trống bên cạnh tòa nhà quá hẹp cho thiết bị của công ty chuyển nhà: "the space next to our side of the building is too narrow for their equipment" (khoảng trống bên cạnh tòa nhà của chúng ta quá hẹp cho thiết bị của họ).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6058, 269, '2025/test9/audio/test9_question_56_58.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7659, 6058, 58, 'What does the man suggest doing?', 'Reviewing a contract', 'Postponing a start date', 'Taking some measurements', 'Seeking another opinion', 'A', 'Question: "What does the man suggest doing?" (Người đàn ông đề xuất làm gì?)
A: Reviewing a contract (Xem xét lại hợp đồng)
B: Postponing a start date (Hoãn ngày bắt đầu)
C: Taking some measurements (Đo đạc)
D: Seeking another opinion (Tìm kiếm ý kiến khác)

Người đàn ông đề xuất kiểm tra hợp đồng thuê: "we should check our lease agreement" (chúng ta nên kiểm tra hợp đồng thuê) để xem có điều khoản nào yêu cầu chủ nhà phải sửa thang máy nhanh chóng không.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6059, 269, '2025/test9/audio/test9_question_59_61.mp3', NULL, 'M-Cn: Hi, Hyo-Min. Do you have a moment? The finance department just got the payment request from Jenkins Mining.
w-Am: And you''re wondering why I decided to place an order with a second iron supplier?
M-Cn: Yes_ has there been a problem with the supplier you usually purchase our iron from?
W-Am: No, but these days it''s wise to have more than one source for important materials. That way, a shortage at one supplier won''t cause a critical disruption to our business. It''s part of a practice called "supply-chain diversification."
M-cn: Oh, that makes sense. Where did you hear about it? I''d like to learn more.
W-Am: My favorite business Web site has published articles about it. I''ll send you the links.', 'Nam: Chào Hyo-Min. Bạn có rảnh không? Phòng tài chính vừa nhận được yêu cầu thanh toán từ Jenkins Mining.
Nữ: Và anh đang thắc mắc tại sao tôi quyết định đặt hàng với nhà cung cấp sắt thứ hai?
Nam: Vâng, có vấn đề gì với nhà cung cấp mà bạn thường mua sắt của chúng ta không?
Nữ: Không, nhưng những ngày này việc có nhiều hơn một nguồn cung cấp cho các vật liệu quan trọng là khôn ngoan. Như vậy, việc thiếu hàng ở một nhà cung cấp sẽ không gây gián đoạn nghiêm trọng cho hoạt động kinh doanh của chúng ta. Đó là một phần của thực hành gọi là "đa dạng hóa chuỗi cung ứng".
Nam: Ồ, điều đó có lý. Bạn nghe về nó ở đâu vậy? Tôi muốn tìm hiểu thêm.
Nữ: Trang web kinh doanh yêu thích của tôi đã xuất bản các bài viết về nó. Tôi sẽ gửi cho anh các đường link.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7660, 6059, 59, 'What is the purpose of the man''s visit?', 'To complete a process', 'To thank a colleague', 'To announce a visitor', 'To ask about a decision', 'D', 'Question: "What is the purpose of the man''s visit?" (Mục đích chuyến thăm của người đàn ông là gì?)
A: To complete a process (Để hoàn thành một quy trình)
B: To thank a colleague (Để cảm ơn đồng nghiệp)
C: To announce a visitor (Để thông báo về một khách thăm)
D: To ask about a decision (Để hỏi về một quyết định)

Người đàn ông đến để hỏi về quyết định đặt hàng với nhà cung cấp sắt thứ hai: "you''re wondering why I decided to place an order with a second iron supplier?" (anh đang thắc mắc tại sao tôi quyết định đặt hàng với nhà cung cấp sắt thứ hai?).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6060, 269, '2025/test9/audio/test9_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7661, 6060, 60, 'What department does the woman most likely work in?', 'Human Resources', 'Purchasing', 'Marketing', 'Technical Support', 'B', 'Question: "What department does the woman most likely work in?" (Người phụ nữ nhiều khả năng làm việc ở phòng ban nào?)
A: Human Resources (Nhân sự)
B: Purchasing (Mua hàng)
C: Marketing (Marketing)
D: Technical Support (Hỗ trợ kỹ thuật)

Người phụ nữ làm việc ở phòng Mua hàng vì:
1. Cô ấy ra quyết định về việc đặt hàng với nhà cung cấp
2. Cô ấy thảo luận về chiến lược mua hàng và đa dạng hóa nguồn cung cấp
3. Cô ấy có quyền quyết định về việc chọn nhà cung cấp vật liệu');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6061, 269, '2025/test9/audio/test9_question_59_61.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7662, 6061, 61, 'What does the woman say she will do?', 'Share some Web site links', 'Cancel a supply order', 'Practice a presentation', 'Dispose of some documents', 'A', 'Question: "What does the woman say she will do?" (Người phụ nữ nói cô ấy sẽ làm gì?)
A: Share some Web site links (Chia sẻ một số đường link trang web)
B: Cancel a supply order (Hủy một đơn đặt hàng)
C: Practice a presentation (Luyện tập một bài thuyết trình)
D: Dispose of some documents (Xử lý một số tài liệu)

Người phụ nữ nói rằng cô ấy sẽ gửi các đường link bài viết cho người đàn ông: "I''ll send you the links" (Tôi sẽ gửi cho anh các đường link).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6062, 269, '2025/test9/audio/test9_question_62_64.mp3', '2025/test9/image/test9-p3-image-62.jpg', 'M-cn: Good morning, Sanford Tower Facilities Office. How can I help you?
W-Am: Hi, this is Teresa Strauss from Fairview Logistics.
M-cn: Ah, yes. I''ve just ordered your nameplate for the business directory. I hope you''re getting settled in well.
w-Am: We are, thanks, except that the heating system isn''t working.
M-Cn: I can send a technician right now. It''s Suite 102, right?
W-Am: That''s right. And we still need our passes for the underground parking area. I plan to collect those after lunch.
M-Cn: That''s fine. They''ll be ready by then.', 'Nam: Chào buổi sáng, Văn phòng Cơ sở vật chất Tháp Sanford. Tôi có thể giúp gì cho bạn?
Nữ: Chào, tôi là Teresa Strauss từ Fairview Logistics.
Nam: À, vâng. Tôi vừa đặt bảng tên của các bạn cho danh mục doanh nghiệp. Tôi hy vọng các bạn đang ổn định tốt.
Nữ: Chúng tôi ổn, cảm ơn anh, ngoại trừ việc hệ thống sưởi không hoạt động.
Nam: Tôi có thể gửi kỹ thuật viên đến ngay bây giờ. Phòng 102, đúng không?
Nữ: Đúng vậy. Và chúng tôi vẫn cần thẻ ra vào bãi đậu xe ngầm. Tôi dự định lấy chúng sau bữa trưa.
Nam: Được thôi. Chúng sẽ sẵn sàng vào lúc đó.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7663, 6062, 62, 'Who most likely is the man?', 'A construction worker', 'A safety inspector', 'A facilities manager', 'A computer technician', 'C', 'Question: "Who most likely is the man?" (Người đàn ông nhiều khả năng là ai?)
A: A construction worker (Một công nhân xây dựng)
B: A safety inspector (Một thanh tra an toàn)
C: A facilities manager (Một quản lý cơ sở vật chất)
D: A computer technician (Một kỹ thuật viên máy tính)

Người đàn ông là quản lý cơ sở vật chất vì:
1. Anh ấy trả lời điện thoại tại Văn phòng Cơ sở vật chất Tháp Sanford
2. Anh ấy có thẩm quyền gửi kỹ thuật viên đến sửa hệ thống sưởi
3. Anh ấy xử lý các vấn đề về bảng tên doanh nghiệp và thẻ đậu xe');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6063, 269, '2025/test9/audio/test9_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7664, 6063, 63, 'Look at the graphic. Which business name will be changed?', 'Tabor Sales', 'Ace Publishing', 'Norris Inc.', 'EG Interior Designs', 'B', 'Question: "Look at the graphic. Which business name will be changed?" (Nhìn vào hình. Tên doanh nghiệp nào sẽ được thay đổi?)
A: Tabor Sales (Tabor Sales)
B: Ace Publishing (Ace Publishing)
C: Norris Inc. (Norris Inc.)
D: EG Interior Designs (EG Interior Designs)

Bảng tên doanh nghiệp của Ace Publishing tại phòng 102 sẽ được thay đổi vì:
1. Trong đoạn hội thoại, người đàn ông nói đã đặt bảng tên mới cho Fairview Logistics
2. Fairview Logistics đang ở phòng 102 (được xác nhận trong đoạn hội thoại)
3. Trong hình, phòng 102 hiện đang là Ace Publishing');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6064, 269, '2025/test9/audio/test9_question_62_64.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7665, 6064, 64, 'What does the woman say she will do this afternoon?', 'Wait to greet a visitor', 'Move in some furniture', 'Pick up some parking passes', 'Order some business cards', 'C', 'Question: "What does the woman say she will do this afternoon?" (Người phụ nữ nói cô ấy sẽ làm gì vào buổi chiều?)
A: Wait to greet a visitor (Đợi chào đón khách)
B: Move in some furniture (Chuyển đồ đạc vào)
C: Pick up some parking passes (Lấy thẻ đậu xe)
D: Order some business cards (Đặt danh thiếp)

Người phụ nữ nói rằng cô ấy sẽ lấy thẻ ra vào bãi đậu xe sau bữa trưa: "I plan to collect those [parking passes] after lunch" (Tôi dự định lấy chúng [thẻ đậu xe] sau bữa trưa).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6065, 269, '2025/test9/audio/test9_question_65_67.mp3', '2025/test9/image/test9-p3-image-65.jpg', 'M-Au: Welcome to Sandia Beauty Salon. How can I help you?
W-Am: Hi, I''m Janice Simms. I have an appointment for a manicure at eleven. I booked it yesterday over the phone.
M-Au: Ah, Ms. Simms! I''m the person you spoke with.
W-Am: Oh, I see! Well, thank you again for fitting me in. Like I said yesterday, I''ve been suddenly scheduled to interview for a bank teller position this afternoon, and it''s important to have well-manicured hands in that kind of work.
M-Au: Yes, good luck. Now, can I get you a cup of tea while you wait?
w-Am: I''d like that, thank you.', 'Nam: Chào mừng đến với Salon Sandia Beauty. Tôi có thể giúp gì cho bạn?
Nữ: Chào, tôi là Janice Simms. Tôi có hẹn làm móng tay lúc 11 giờ. Tôi đã đặt lịch qua điện thoại hôm qua.
Nam: À, cô Simms! Tôi là người đã nói chuyện với cô.
Nữ: Ồ, tôi hiểu rồi! À, cảm ơn anh một lần nữa đã sắp xếp cho tôi. Như tôi đã nói hôm qua, tôi vừa được lên lịch phỏng vấn cho vị trí giao dịch viên ngân hàng chiều nay, và việc có bàn tay được chăm sóc móng tốt là quan trọng trong công việc đó.
Nam: Vâng, chúc may mắn. Giờ, tôi có thể mang cho cô một tách trà trong lúc đợi không?
Nữ: Tôi thích điều đó, cảm ơn anh.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7666, 6065, 65, 'Look at the graphic. How much will the woman pay for her service?', '$60', '$50', '$40', '$30', 'D', 'Question: "Look at the graphic. How much will the woman pay for her service?" (Nhìn vào hình. Người phụ nữ sẽ trả bao nhiêu tiền cho dịch vụ của cô ấy?)
A: $60 (60 đô)
B: $50 (50 đô)
C: $40 (40 đô)
D: $30 (30 đô)

Theo bảng giá dịch vụ trong hình, dịch vụ làm móng tay (manicure) có giá $30. Người phụ nữ đến để làm móng tay nên cô ấy sẽ trả $30.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6066, 269, '2025/test9/audio/test9_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7667, 6066, 66, 'What event is the woman going to participate in later?', 'A photo shoot', 'An award ceremony', 'A press conference', 'A job interview', 'D', 'Question: "What event is the woman going to participate in later?" (Người phụ nữ sẽ tham gia sự kiện gì sau đó?)
A: A photo shoot (Một buổi chụp ảnh)
B: An award ceremony (Một buổi lễ trao giải)
C: A press conference (Một cuộc họp báo)
D: A job interview (Một cuộc phỏng vấn việc làm)

Người phụ nữ sẽ tham gia phỏng vấn cho vị trí giao dịch viên ngân hàng vào buổi chiều: "I''ve been suddenly scheduled to interview for a bank teller position this afternoon" (Tôi vừa được lên lịch phỏng vấn cho vị trí giao dịch viên ngân hàng chiều nay).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6067, 269, '2025/test9/audio/test9_question_65_67.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7668, 6067, 67, 'What will the man most likely do next?', 'Look for a colleague', 'Put out some magazines', 'Prepare a beverage', 'Accept a payment', 'C', 'Question: "What will the man most likely do next?" (Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?)
A: Look for a colleague (Tìm một đồng nghiệp)
B: Put out some magazines (Đặt ra một số tạp chí)
C: Prepare a beverage (Chuẩn bị đồ uống)
D: Accept a payment (Nhận thanh toán)

Người đàn ông sẽ chuẩn bị trà cho người phụ nữ vì:
1. Anh ấy hỏi: "can I get you a cup of tea while you wait?" (tôi có thể mang cho cô một tách trà trong lúc đợi không?)
2. Người phụ nữ đồng ý: "I''d like that" (Tôi thích điều đó).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6068, 269, '2025/test9/audio/test9_question_68_70.mp3', '2025/test9/image/test9-p3-image-68.jpg', 'w-Am: Hi Nasir, it''s Elizabeth. I''m on my way to Springtown Hotel to meet with some potential clients, and I just realized that I forgot the USB stick with my presentation on it. Could you drive it over here?
M-Cn: Right now? Oh... uh, OK.
w-Am: Thank you so much. I''m really sorry for the inconvenience. I should have checked my bag more carefully before I left the office this morning.
M-cn: It''s alright. I''ve left important stuff at the office before, too. So, where''s your USB stick?
W-Am: If you go to my workstation, you''ll see two drawer units under the desk. The USB''s in the top drawer of the one on the right. It''s bright green.', 'Nữ: Chào Nasir, Elizabeth đây. Tôi đang trên đường đến Khách sạn Springtown để gặp một số khách hàng tiềm năng, và tôi vừa nhận ra rằng tôi quên USB có bài thuyết trình của tôi trên đó. Anh có thể lái xe mang nó đến đây được không?
Nam: Ngay bây giờ? Ồ... ừ, OK.
Nữ: Cảm ơn anh rất nhiều. Tôi thực sự xin lỗi vì sự bất tiện này. Lẽ ra tôi nên kiểm tra túi kỹ hơn trước khi rời văn phòng sáng nay.
Nam: Không sao đâu. Tôi cũng từng để quên đồ quan trọng ở văn phòng. Vậy, USB của chị ở đâu?
Nữ: Nếu anh đến chỗ làm việc của tôi, anh sẽ thấy hai bộ ngăn kéo dưới bàn. USB ở trong ngăn kéo trên cùng của bộ bên phải. Nó màu xanh lá cây sáng.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7669, 6068, 68, 'Why is the woman away from the office?', 'For an industry conference', 'For a client meeting', 'For a property inspection', 'For a doctor''s appointment', 'B', 'Question: "Why is the woman away from the office?" (Tại sao người phụ nữ không có mặt ở văn phòng?)
A: For an industry conference (Cho một hội nghị ngành)
B: For a client meeting (Cho một cuộc họp với khách hàng)
C: For a property inspection (Cho một cuộc kiểm tra tài sản)
D: For a doctor''s appointment (Cho một cuộc hẹn với bác sĩ)

Người phụ nữ đang trên đường đến Khách sạn Springtown để gặp các khách hàng tiềm năng: "I''m on my way to Springtown Hotel to meet with some potential clients" (Tôi đang trên đường đến Khách sạn Springtown để gặp một số khách hàng tiềm năng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6069, 269, '2025/test9/audio/test9_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7670, 6069, 69, 'What does the man say to reassure the woman?', 'He is not very busy today', 'He knows a project is important', 'He has made similar mistakes', 'He is familiar with a location', 'C', 'Question: "What does the man say to reassure the woman?" (Người đàn ông nói gì để trấn an người phụ nữ?)
A: He is not very busy today (Anh ấy không bận lắm hôm nay)
B: He knows a project is important (Anh ấy biết một dự án là quan trọng)
C: He has made similar mistakes (Anh ấy đã từng mắc lỗi tương tự)
D: He is familiar with a location (Anh ấy quen thuộc với một địa điểm)

Người đàn ông nói rằng anh ấy cũng từng quên đồ quan trọng ở văn phòng để trấn an người phụ nữ: "I''ve left important stuff at the office before, too" (Tôi cũng từng để quên đồ quan trọng ở văn phòng).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6070, 269, '2025/test9/audio/test9_question_68_70.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7671, 6070, 70, 'Look at the graphic. Where should the man look for an item?', 'In drawer A', 'In drawer B', 'In drawer C', 'In drawer D', 'C', 'Question: "Look at the graphic. Where should the man look for an item?" (Nhìn vào hình. Người đàn ông nên tìm đồ ở đâu?)
A: In drawer A (Trong ngăn kéo A)
B: In drawer B (Trong ngăn kéo B)
C: In drawer C (Trong ngăn kéo C)
D: In drawer D (Trong ngăn kéo D)

Người đàn ông nên tìm trong ngăn kéo C vì:
1. Người phụ nữ nói USB ở trong ngăn kéo trên cùng của bộ bên phải
2. Trong hình, ngăn kéo C là ngăn kéo trên cùng của bộ bên phải.');;

-- Data for 2025 Test9 Part 4
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6071, 270, '2025/test9/audio/test9_question_71_73.mp3', NULL, 'Hello, Ms. Young, this is Frank Davis with FS London. I''m calling to let you know that you''re a finalist for our organization''s Rising Star Award. Your supervisor nominated you. Our judges were quite impressed by her description of the savings that your accounting work has created for your company. If you''re interested, the next step is a meeting with the judges'' committee to discuss your accomplishments. I''m sending you an invitation by e-mail right now.', 'Xin chào, cô Young, tôi là Frank Davis từ FS London. Tôi gọi để cho cô biết rằng cô là một ứng viên chung cuộc cho giải Ngôi Sao Đang Lên của tổ chức chúng tôi. Người giám sát của cô đã đề cử cô. Ban giám khảo của chúng tôi rất ấn tượng với mô tả của cô ấy về các khoản tiết kiệm mà công việc kế toán của cô đã tạo ra cho công ty. Nếu cô quan tâm, bước tiếp theo là một cuộc họp với ủy ban giám khảo để thảo luận về thành tích của cô. Tôi đang gửi cho cô một lời mời qua email ngay bây giờ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7672, 6071, 71, 'What is the main purpose of the call?', 'To suggest applying for a promotion', 'To confirm a biographical detail for an article', 'To tell the listener that she is an award candidate', 'To thank the listener for joining a committee', 'C', '[Dịch] Câu hỏi: Mục đích chính của cuộc gọi là gì?
A: Để đề xuất ứng tuyển thăng chức
B: Để xác nhận một chi tiết tiểu sử cho một bài báo
C: Để nói với người nghe rằng cô ấy là ứng viên giải thưởng
D: Để cảm ơn người nghe vì đã tham gia một ủy ban

Đáp án C là chính xác vì người nói gọi để thông báo rằng Ms. Young là "a finalist for our organization''s Rising Star Award" (một ứng viên chung cuộc cho giải Ngôi Sao Đang Lên).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6072, 270, '2025/test9/audio/test9_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7673, 6072, 72, 'What field does the listener work in?', 'Shipping', 'Education', 'Advertising', 'Finance', 'D', '[Dịch] Câu hỏi: Người nghe làm việc trong lĩnh vực gì?
A: Vận chuyển
B: Giáo dục
C: Quảng cáo
D: Tài chính

Đáp án D là chính xác vì đoạn hội thoại đề cập đến "accounting work" (công việc kế toán) của người nghe, cho thấy cô ấy làm việc trong lĩnh vực tài chính.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6073, 270, '2025/test9/audio/test9_question_71_73.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7674, 6073, 73, 'What is the listener invited to do?', 'Attend a meeting', 'Browse a Web site', 'Submit a work sample', 'Refer a coworker', 'A', '[Dịch] Câu hỏi: Người nghe được mời làm gì?
A: Tham dự một cuộc họp
B: Duyệt một trang web
C: Nộp một mẫu công việc
D: Giới thiệu một đồng nghiệp

Đáp án A là chính xác vì người nói cho biết "the next step is a meeting with the judges'' committee" (bước tiếp theo là một cuộc họp với ủy ban giám khảo) và đang gửi lời mời qua email.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6074, 270, '2025/test9/audio/test9_question_74_76.mp3', NULL, 'All residents of Holton are invited to Tillsby Park this Saturday for "Tacos for Tillsby," a benefit to raise money for updates to the park. The Holton Parks Foundation will be selling delicious taco lunches from eleven until supplies run out. Attendees can also enjoy performances from several local bands. Visit the foundation''s Web site for event details and to see computer-generated images of what the park will look like after the improvements.', 'Tất cả cư dân Holton được mời đến Công viên Tillsby vào thứ Bảy này cho "Tacos for Tillsby", một sự kiện gây quỹ để quyên tiền cho việc nâng cấp công viên. Quỹ Công viên Holton sẽ bán bữa trưa taco ngon từ mười một giờ cho đến khi hết hàng. Người tham dự cũng có thể thưởng thức các buổi biểu diễn từ một số ban nhạc địa phương. Truy cập trang web của quỹ để biết chi tiết sự kiện và xem hình ảnh được tạo bởi máy tính về diện mạo của công viên sau khi được cải thiện.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7675, 6074, 74, 'What is being advertised?', 'A store opening', 'A park cleanup', 'A sports competition', 'A community fund-raiser', 'D', '[Dịch] Câu hỏi: Điều gì đang được quảng cáo?
A: Lễ khai trương cửa hàng
B: Dọn dẹp công viên
C: Một cuộc thi thể thao
D: Một sự kiện gây quỹ cộng đồng

Đáp án D là chính xác vì đây là một "benefit to raise money for updates to the park" (sự kiện gây quỹ để quyên tiền nâng cấp công viên).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6075, 270, '2025/test9/audio/test9_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7676, 6075, 75, 'What will happen during the event?', 'A street will be closed to vehicles.', 'A government official will give a speech.', 'Some of the attendees will win prizes.', 'Musical performances will take place.', 'D', '[Dịch] Câu hỏi: Điều gì sẽ xảy ra trong sự kiện?
A: Một con đường sẽ bị cấm xe cộ
B: Một viên chức chính phủ sẽ phát biểu
C: Một số người tham dự sẽ thắng giải
D: Các buổi biểu diễn âm nhạc sẽ diễn ra

Đáp án D là chính xác vì đoạn văn nêu rõ "Attendees can also enjoy performances from several local bands" (Người tham dự cũng có thể thưởng thức các buổi biểu diễn từ một số ban nhạc địa phương).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6076, 270, '2025/test9/audio/test9_question_74_76.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7677, 6076, 76, 'What does the speaker say the listeners can do on a Web site?', 'Make a donation', 'Complete a registration', 'View some images', 'Cast some votes', 'C', '[Dịch] Câu hỏi: Người nói nói người nghe có thể làm gì trên trang web?
A: Thực hiện quyên góp
B: Hoàn thành đăng ký
C: Xem một số hình ảnh
D: Bỏ phiếu

Đáp án C là chính xác vì người nói mời mọi người truy cập trang web để "see computer-generated images of what the park will look like" (xem hình ảnh được tạo bởi máy tính về diện mạo của công viên).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6077, 270, '2025/test9/audio/test9_question_77_79.mp3', NULL, 'Welcome back to the new and improved Womack Theater! It''s wonderful that so many of you have returned to work here. And I apologize, again, for the wait. I know that some of you expected that the renovations wouldn''t take so long. But you have to remember-this building was built over seventy years ago. We couldn''t have predicted all of the issues that came up. Anyway, now we''re back and ready to put on some great shows! Let''s start this re-training session with a tour. Leave your coats and bags on the table here, and follow me.', 'Chào mừng trở lại với Nhà hát Womack mới và được cải thiện! Thật tuyệt vời khi rất nhiều người trong số các bạn đã quay trở lại làm việc tại đây. Và tôi xin lỗi, một lần nữa, vì đã phải chờ đợi. Tôi biết một số bạn mong đợi rằng việc cải tạo sẽ không mất nhiều thời gian như vậy. Nhưng bạn phải nhớ rằng - tòa nhà này đã được xây dựng cách đây hơn bảy mươi năm. Chúng tôi không thể dự đoán được tất cả các vấn đề phát sinh. Dù sao thì, bây giờ chúng ta đã trở lại và sẵn sàng tổ chức một số buổi biểu diễn tuyệt vời! Hãy bắt đầu buổi đào tạo lại này với một chuyến tham quan. Để áo khoác và túi của bạn trên bàn ở đây, và đi theo tôi.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7678, 6077, 77, 'Where do the listeners work?', 'At a theater', 'At a television studio', 'At a university library', 'At a bank', 'A', '[Dịch] Câu hỏi: Người nghe làm việc ở đâu?
A: Tại một nhà hát
B: Tại một studio truyền hình
C: Tại một thư viện đại học
D: Tại một ngân hàng

Đáp án A là chính xác vì người nói chào đón nhân viên quay trở lại "Womack Theater" sau khi cải tạo.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6078, 270, '2025/test9/audio/test9_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7679, 6078, 78, 'What does the speaker imply when she says, "this building was built over 70 years ago"?', 'The facility lacks some amenities.', 'The building is a local landmark.', 'A renovation project was difficult.', 'An organization should relocate soon.', 'C', '[Dịch] Câu hỏi: Người nói ngụ ý gì khi cô ấy nói "tòa nhà này đã được xây dựng cách đây hơn 70 năm"?
A: Cơ sở thiếu một số tiện nghi
B: Tòa nhà là một địa danh địa phương
C: Một dự án cải tạo gặp khó khăn
D: Một tổ chức nên di dời sớm

Đáp án C là chính xác vì người nói dùng điều này để giải thích tại sao việc cải tạo mất nhiều thời gian hơn dự kiến, vì tuổi của tòa nhà khiến họ gặp nhiều vấn đề không lường trước được.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6079, 270, '2025/test9/audio/test9_question_77_79.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7680, 6079, 79, 'What does the speaker ask the listeners to do?', 'Rearrange some furniture', 'Put down their belongings', 'Take copies of a handout', 'Silence their mobile phones', 'B', '[Dịch] Câu hỏi: Người nói yêu cầu người nghe làm gì?
A: Sắp xếp lại một số đồ đạc
B: Để đồ đạc của họ xuống
C: Lấy bản sao của một tài liệu phát tay
D: Tắt điện thoại di động

Đáp án B là chính xác vì người nói yêu cầu "Leave your coats and bags on the table here" (Để áo khoác và túi của bạn trên bàn ở đây).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6080, 270, '2025/test9/audio/test9_question_80_82.mp3', NULL, 'Hi, Emily. It''s Daoming. I''m calling about the video that we''re making for the company Web site. I''m reviewing the audio file now. As you requested, I used a speech generating computer program to create the voiceover narration, and for the most part, it sounds pretty good. Except the program has a hard time pronouncing names correctly. I can fix the mispronounced names with my sound editing software, but it''ll take all day. For our next project, we should probably just hire a professional voice actor again.', 'Chào Emily. Tôi là Daoming. Tôi gọi về video mà chúng ta đang làm cho trang web công ty. Tôi đang xem xét tập tin âm thanh. Như bạn yêu cầu, tôi đã sử dụng một chương trình máy tính tạo giọng nói để tạo lời thoại, và phần lớn, nó nghe khá tốt. Ngoại trừ chương trình gặp khó khăn trong việc phát âm tên chính xác. Tôi có thể sửa các tên bị phát âm sai bằng phần mềm chỉnh sửa âm thanh của tôi, nhưng nó sẽ mất cả ngày. Cho dự án tiếp theo của chúng ta, có lẽ chúng ta nên thuê một diễn viên lồng tiếng chuyên nghiệp một lần nữa.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7681, 6080, 80, 'What is the speaker reviewing?', 'A video script', 'A research paper', 'A slide presentation', 'An audio file', 'D', '[Dịch] Câu hỏi: Người nói đang xem xét cái gì?
A: Một kịch bản video
B: Một bài nghiên cứu
C: Một bài thuyết trình slide
D: Một tập tin âm thanh

Đáp án D là chính xác vì người nói cho biết "I''m reviewing the audio file now" (Tôi đang xem xét tập tin âm thanh).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6081, 270, '2025/test9/audio/test9_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7682, 6081, 81, 'According to the speaker, what caused a problem?', 'Some names', 'Some visual aids', 'A password requirement', 'A formatting choice', 'A', '[Dịch] Câu hỏi: Theo người nói, điều gì đã gây ra vấn đề?
A: Một số tên
B: Một số phương tiện trực quan
C: Một yêu cầu mật khẩu
D: Một lựa chọn định dạng

Đáp án A là chính xác vì người nói cho biết chương trình "has a hard time pronouncing names correctly" (gặp khó khăn trong việc phát âm tên chính xác).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6082, 270, '2025/test9/audio/test9_question_80_82.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7683, 6082, 82, 'What does the speaker recommend doing in the future?', 'Reading a manual', 'Hiring a specialist', 'Marking any changes', 'Upgrading some equipment', 'B', '[Dịch] Câu hỏi: Người nói đề xuất làm gì trong tương lai?
A: Đọc một hướng dẫn sử dụng
B: Thuê một chuyên gia
C: Đánh dấu bất kỳ thay đổi nào
D: Nâng cấp một số thiết bị

Đáp án B là chính xác vì người nói đề xuất "hire a professional voice actor again" (thuê một diễn viên lồng tiếng chuyên nghiệp một lần nữa).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6083, 270, '2025/test9/audio/test9_question_83_85.mp3', NULL, 'Can I have your attention? I''m Marianne Cross, the manager here at Hudson Fitness Center. I''m sorry to tell you that the eight P.M. cycling class has been canceled due to a dangling light fixture in the studio. An electrician is coming tomorrow to put it back into place. As for tonight-there is an aerobics class at 8:15. It''s in Room Two, for those who are interested. Also, as a token of apology, you will all receive a coupon for a free smoothie through the Hudson Fitness Center app. Check your smartphone in a few minutes to make sure it has come through.', 'Xin chú ý? Tôi là Marianne Cross, người quản lý tại Trung tâm Thể hình Hudson. Tôi xin lỗi phải thông báo rằng lớp đạp xe lúc 8 giờ tối đã bị hủy do một đèn treo bị lỏng trong phòng tập. Một thợ điện sẽ đến vào ngày mai để đặt nó lại vào vị trí. Còn về tối nay - có một lớp thể dục nhịp điệu lúc 8:15. Nó ở Phòng Hai, cho những ai quan tâm. Ngoài ra, như một dấu hiệu xin lỗi, tất cả các bạn sẽ nhận được một phiếu giảm giá cho một ly sinh tố miễn phí thông qua ứng dụng Trung tâm Thể hình Hudson. Kiểm tra điện thoại thông minh của bạn trong vài phút nữa để đảm bảo nó đã được gửi đến.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7684, 6083, 83, 'Why is the cycling class canceled?', 'A staffing issue', 'A lack of participants', 'A scheduling conflict', 'A maintenance problem', 'D', '[Dịch] Câu hỏi: Tại sao lớp đạp xe bị hủy?
A: Một vấn đề về nhân sự
B: Thiếu người tham gia
C: Một xung đột lịch trình
D: Một vấn đề bảo trì

Đáp án D là chính xác vì lớp học bị hủy "due to a dangling light fixture" (do một đèn treo bị lỏng) và cần thợ điện đến sửa chữa vào ngày mai.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6084, 270, '2025/test9/audio/test9_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7685, 6084, 84, 'Why does the speaker say, "there is an aerobics class at 8:15"?', 'To explain a refusal', 'To propose an alternative', 'To complain about a timetable', 'To request some assistance', 'B', '[Dịch] Câu hỏi: Tại sao người nói nói "có một lớp thể dục nhịp điệu lúc 8:15"?
A: Để giải thích một sự từ chối
B: Để đề xuất một phương án thay thế
C: Để phàn nàn về một lịch trình
D: Để yêu cầu một số hỗ trợ

Đáp án B là chính xác vì người nói đề cập đến lớp thể dục nhịp điệu như một lựa chọn thay thế cho những người đã định tham gia lớp đạp xe bị hủy.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6085, 270, '2025/test9/audio/test9_question_83_85.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7686, 6085, 85, 'What are the listeners asked to check?', 'A list of rules', 'A membership card', 'An electronic device', 'A floor plan', 'C', '[Dịch] Câu hỏi: Người nghe được yêu cầu kiểm tra cái gì?
A: Một danh sách quy tắc
B: Một thẻ thành viên
C: Một thiết bị điện tử
D: Một bản vẽ mặt bằng

Đáp án C là chính xác vì người nói yêu cầu "Check your smartphone in a few minutes" (Kiểm tra điện thoại thông minh của bạn trong vài phút) để đảm bảo phiếu giảm giá đã được gửi đến.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6086, 270, '2025/test9/audio/test9_question_86_88.mp3', NULL, 'Good morning. I''d like to start by thanking the distinguished members of the Nayona news media for joining me to hear this important announcement. Our hospital has just secured thirty-two million dollars in funding to spend on a major expansion. We will be extending the south wing of the building by one thousand square meters and equipping this space with state-of-the-art medical imaging technology. Once it''s finished sometime next year, patients will be able to receive imaging services right here in Nayona instead of traveling hours away.', 'Chào buổi sáng. Tôi muốn bắt đầu bằng việc cảm ơn các thành viên đáng kính của truyền thông Nayona đã tham gia để nghe thông báo quan trọng này. Bệnh viện của chúng tôi vừa đảm bảo được ba mươi hai triệu đô la tài trợ để chi cho một dự án mở rộng lớn. Chúng tôi sẽ mở rộng cánh nam của tòa nhà thêm một nghìn mét vuông và trang bị không gian này với công nghệ chẩn đoán hình ảnh hiện đại nhất. Một khi nó được hoàn thành vào năm sau, bệnh nhân sẽ có thể nhận dịch vụ chẩn đoán hình ảnh ngay tại đây ở Nayona thay vì phải đi xa hàng giờ đồng hồ.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7687, 6086, 86, 'Where is the speech most likely being given?', 'At a trade show', 'At a press conference', 'At a shareholder meeting', 'At a welcome reception', 'B', '[Dịch] Câu hỏi: Bài phát biểu có khả năng đang được đưa ra ở đâu?
A: Tại một hội chợ thương mại
B: Tại một cuộc họp báo
C: Tại một cuộc họp cổ đông
D: Tại một buổi tiếp đón

Đáp án B là chính xác vì người nói cảm ơn "members of the Nayona news media" (các thành viên truyền thông Nayona) và đang đưa ra một thông báo quan trọng, cho thấy đây là một cuộc họp báo.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6087, 270, '2025/test9/audio/test9_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7688, 6087, 87, 'What industry does the speaker most likely work in?', 'Law', 'Energy', 'Health care', 'Technology', 'C', '[Dịch] Câu hỏi: Người nói có khả năng làm việc trong ngành nào?
A: Luật
B: Năng lượng
C: Chăm sóc sức khỏe
D: Công nghệ

Đáp án C là chính xác vì người nói đang thông báo về việc mở rộng bệnh viện ("our hospital") và các dịch vụ y tế.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6088, 270, '2025/test9/audio/test9_question_86_88.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7689, 6088, 88, 'What will the speaker''s business do next year?', 'Begin offering new services', 'Acquire one of its competitors', 'Conduct some market research', 'Discontinue an employee program', 'A', '[Dịch] Câu hỏi: Doanh nghiệp của người nói sẽ làm gì vào năm sau?
A: Bắt đầu cung cấp dịch vụ mới
B: Mua lại một trong những đối thủ cạnh tranh
C: Tiến hành một số nghiên cứu thị trường
D: Ngừng một chương trình nhân viên

Đáp án A là chính xác vì người nói cho biết một khi dự án hoàn thành vào năm sau, họ sẽ bắt đầu cung cấp "imaging services" (dịch vụ chẩn đoán hình ảnh) tại địa phương.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6089, 270, '2025/test9/audio/test9_question_89_91.mp3', NULL, 'Management has decided that our performance review process this year will include peer evaluations. So instead of just receiving a review from your manager, you''ll also exchange evaluations with several coworkers. We hope this will give everyone a fuller understanding of their strengths and areas for improvement. However, the effectiveness of the system does depend on the quality of the feedback given, so please be honest in your reviews. Uh, each employee will be allowed to choose their peer reviewers. We''ll be issuing the selection guidelines soon so that you can start thinking about your choices.', 'Ban quản lý đã quyết định rằng quy trình đánh giá hiệu suất năm nay của chúng ta sẽ bao gồm đánh giá từ đồng nghiệp. Vì vậy, thay vì chỉ nhận đánh giá từ người quản lý của bạn, bạn cũng sẽ trao đổi đánh giá với một số đồng nghiệp. Chúng tôi hy vọng điều này sẽ giúp mọi người hiểu đầy đủ hơn về điểm mạnh và những lĩnh vực cần cải thiện của họ. Tuy nhiên, hiệu quả của hệ thống phụ thuộc vào chất lượng phản hồi được đưa ra, vì vậy hãy trung thực trong đánh giá của bạn. À, mỗi nhân viên sẽ được phép chọn người đánh giá đồng nghiệp của họ. Chúng tôi sẽ sớm ban hành hướng dẫn lựa chọn để bạn có thể bắt đầu suy nghĩ về lựa chọn của mình.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7690, 6089, 89, 'What is the announcement about?', 'The arrival of new workers', 'A change in a company practice', 'The customer reviews for a product', 'A decision about the yearly budget', 'B', '[Dịch] Câu hỏi: Thông báo này nói về điều gì?
A: Sự đến của những nhân viên mới
B: Một thay đổi trong thực tiễn công ty
C: Đánh giá của khách hàng về một sản phẩm
D: Một quyết định về ngân sách hàng năm

Đáp án B là chính xác vì thông báo đề cập đến việc thay đổi quy trình đánh giá hiệu suất của công ty bằng cách thêm đánh giá từ đồng nghiệp.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6090, 270, '2025/test9/audio/test9_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7691, 6090, 90, 'What does the speaker encourage the listeners to do?', 'Take detailed notes', 'Volunteer for an event', 'Speak to their managers', 'Give honest feedback', 'D', '[Dịch] Câu hỏi: Người nói khuyến khích người nghe làm gì?
A: Ghi chú chi tiết
B: Tình nguyện cho một sự kiện
C: Nói chuyện với người quản lý của họ
D: Đưa ra phản hồi trung thực

Đáp án D là chính xác vì người nói nhấn mạnh "please be honest in your reviews" (hãy trung thực trong đánh giá của bạn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6091, 270, '2025/test9/audio/test9_question_89_91.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7692, 6091, 91, 'What does the company plan to do soon?', 'Reorganize a space', 'Conduct some testing', 'Send out some guidelines', 'Finalize a schedule', 'C', '[Dịch] Câu hỏi: Công ty dự định sẽ làm gì sớm?
A: Tổ chức lại một không gian
B: Tiến hành một số kiểm tra
C: Gửi ra một số hướng dẫn
D: Hoàn thiện một lịch trình

Đáp án C là chính xác vì người nói cho biết "We''ll be issuing the selection guidelines soon" (Chúng tôi sẽ sớm ban hành hướng dẫn lựa chọn).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6092, 270, '2025/test9/audio/test9_question_92_94.mp3', NULL, 'At last week''s meeting we determined that our second store will have the same layout as our first. Since then, I''ve secured supply contracts for most of the merchandise it will stock, including the plants, gardening tools, and soil. I''ve also been looking into display racks and similar items, but an issue has come up there. For branding purposes, it would be good for the product category signs to look the same as those at our first store. However, we''ve received complaints that those signs are hard to read. I think we should have our new print shop draw up some alternatives. Don''t worry-I''ll make sure they know that the new location is supposed to open next month.', 'Trong cuộc họp tuần trước, chúng ta đã xác định rằng cửa hàng thứ hai của chúng ta sẽ có cùng bố cục với cửa hàng đầu tiên. Kể từ đó, tôi đã đảm bảo hợp đồng cung cấp cho hầu hết hàng hóa sẽ bán, bao gồm cây cối, dụng cụ làm vườn và đất. Tôi cũng đã tìm hiểu về giá trưng bày và các vật dụng tương tự, nhưng đã xuất hiện một vấn đề. Vì mục đích thương hiệu, sẽ tốt nếu các biển danh mục sản phẩm trông giống như những biển ở cửa hàng đầu tiên của chúng ta. Tuy nhiên, chúng tôi đã nhận được phàn nàn rằng những biển đó khó đọc. Tôi nghĩ chúng ta nên để xưởng in mới vẽ một số phương án thay thế. Đừng lo lắng - tôi sẽ đảm bảo họ biết rằng địa điểm mới dự kiến sẽ mở cửa vào tháng tới.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7693, 6092, 92, 'Where do the listeners most likely work?', 'At a garden center', 'At a real estate firm', 'At a car-rental company', 'At a grocery store', 'A', '[Dịch] Câu hỏi: Người nghe có khả năng làm việc ở đâu?
A: Tại một trung tâm vườn
B: Tại một công ty bất động sản
C: Tại một công ty cho thuê xe
D: Tại một cửa hàng tạp hóa

Đáp án A là chính xác vì đoạn văn đề cập đến việc bán "plants, gardening tools, and soil" (cây cối, dụng cụ làm vườn và đất), đây là những mặt hàng điển hình của một trung tâm vườn.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6093, 270, '2025/test9/audio/test9_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7694, 6093, 93, 'What has the business received complaints about?', 'The availability of its inventory', 'The design of its signage', 'The length of its operating hours', 'The restrictions of its loyalty program', 'B', '[Dịch] Câu hỏi: Doanh nghiệp đã nhận được phàn nàn về điều gì?
A: Sự sẵn có của hàng tồn kho
B: Thiết kế biển hiệu của nó
C: Thời gian hoạt động của nó
D: Các hạn chế của chương trình khách hàng thân thiết

Đáp án B là chính xác vì đoạn văn nói rằng "we''ve received complaints that those signs are hard to read" (chúng tôi đã nhận được phàn nàn rằng những biển đó khó đọc).');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6094, 270, '2025/test9/audio/test9_question_92_94.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7695, 6094, 94, 'What does the speaker mean when she says, "the new location is supposed to open next month"?', 'A business is doing well.', 'Some staff members will be busy.', 'An announcement should be made later.', 'Some work should be completed quickly.', 'D', '[Dịch] Câu hỏi: Người nói có ý gì khi cô ấy nói "địa điểm mới dự kiến sẽ mở cửa vào tháng tới"?
A: Một doanh nghiệp đang hoạt động tốt
B: Một số nhân viên sẽ bận rộn
C: Một thông báo nên được đưa ra sau
D: Một số công việc nên được hoàn thành nhanh chóng

Đáp án D là chính xác vì người nói dùng câu này để nhấn mạnh rằng công việc thiết kế biển hiệu cần được hoàn thành nhanh chóng trước khi cửa hàng mới mở cửa.');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6095, 270, '2025/test9/audio/test9_question_95_97.mp3', '2025/test9/image/test9-p4-image-95.jpg', 'At today''s staff meeting, l''d like to inform you about a few changes we''ll be making here at the Worley Theater. First, we will be renovating a section of the north wing in October. That will make space for a small coffee shop. Second, please check out this chart of our sales in the gift shop last month. Now, weve just started selling T-shirts, and those are doing well. But take a look at this item we only sold fifteen last month. So, I''d like to take some time now to discuss it further, as we either need to improve its sales or possibly replace it with something else.', 'Tại cuộc họp nhân viên hôm nay, tôi muốn thông báo về một vài thay đổi chúng ta sẽ thực hiện tại Nhà hát Worley. Đầu tiên, chúng ta sẽ cải tạo một phần của khu vực phía bắc vào tháng 10. Điều đó sẽ tạo không gian cho một quán cà phê nhỏ. Thứ hai, hãy xem biểu đồ về doanh số bán hàng của cửa hàng quà tặng tháng trước. Hiện tại, chúng ta mới bắt đầu bán áo phông, và chúng đang bán chạy. Nhưng hãy nhìn vào mặt hàng này, chúng ta chỉ bán được 15 cái tháng trước. Vì vậy, tôi muốn dành thời gian bây giờ để thảo luận thêm về nó, vì chúng ta cần cải thiện doanh số hoặc có thể thay thế nó bằng thứ khác.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7696, 6095, 95, 'Who most likely is the speaker?', 'An interior designer', 'A coffee shop owner', 'A graphic artist', 'A theater manager', 'D', '[Dịch]
Câu hỏi: Ai là người nói nhiều khả năng nhất?
A: Nhà thiết kế nội thất
B: Chủ quán cà phê
C: Họa sĩ đồ họa
D: Người quản lý nhà hát

Đáp án D là chính xác vì:
1. Người nói sử dụng cụm từ "we''ll be making here at the Worley Theater" cho thấy họ có quyền quyết định về các thay đổi tại nhà hát
2. Người nói thảo luận về nhiều khía cạnh quản lý:
- Quyết định cải tạo không gian ("renovating a section of the north wing")
- Theo dõi và phân tích doanh số bán hàng của cửa hàng quà tặng
- Có quyền quyết định về việc cải thiện doanh số hoặc thay thế sản phẩm
3. Ngữ cảnh là cuộc họp nhân viên ("staff meeting"), và người có thẩm quyền tổ chức cuộc họp này phải là người quản lý');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6096, 270, '2025/test9/audio/test9_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7697, 6096, 96, 'What will take place in October?', 'An annual community festival', 'A building renovation project', 'An official press conference', 'An employee sales contest', 'B', '[Dịch]
Câu hỏi: Điều gì sẽ diễn ra vào tháng 10?
A: Lễ hội cộng đồng thường niên
B: Dự án cải tạo công trình
C: Cuộc họp báo chính thức
D: Cuộc thi doanh số nhân viên

Đáp án B là chính xác vì:
1. Trong đoạn văn có đề cập rõ ràng: "we will be renovating a section of the north wing in October"
2. Mục đích của việc cải tạo được nêu rõ: "That will make space for a small coffee shop"
3. Đây là một trong những thay đổi chính được thông báo trong cuộc họp nhân viên');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6097, 270, '2025/test9/audio/test9_question_95_97.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7698, 6097, 97, 'Look at the graphic. Which type of item does the speaker want to discuss further?', 'T-shirts', 'Postcards', 'Calendars', 'Coffee mugs', 'C', '[Dịch]
Câu hỏi: Nhìn vào biểu đồ. Mặt hàng nào người nói muốn thảo luận thêm?
A: Áo phông
B: Bưu thiếp
C: Lịch
D: Cốc cà phê

Đáp án C là chính xác vì:
1. Trong văn bản, người nói đề cập: "take a look at this item we only sold fifteen last month"
2. Khi xem biểu đồ, mặt hàng Calendars (lịch) có doanh số thấp nhất, chỉ 15 cái
3. Người nói muốn thảo luận về mặt hàng này vì doanh số kém và cần cải thiện hoặc thay thế');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6098, 270, '2025/test9/audio/test9_question_98_100.mp3', '2025/test9/image/test9-p4-image-98.jpg', 'Hi, everyone. I''m Joyce McGuire, and I''m so excited to be leading today''s excursion for Whiterose Travel. Blakely is a charming town, and we''ll see some incredible views of the coast on the train ride over. Now, I have your tickets, so you can just look around the train station until it''s time to board. At 8:50, let''s meet in that corner between the platforms entrance and the café. Oh, and there might be a slight change to our itinerary if this rain doesn''t stop. I''ll pull up the forecast on my mobile phone now, so that I can let you know when we meet up again.', 'Xin chào mọi người. Tôi là Joyce McGuire, và tôi rất vui mừng được dẫn đầu chuyến tham quan hôm nay cho Whiterose Travel. Blakely là một thị trấn quyến rũ, và chúng ta sẽ ngắm nhìn những khung cảnh tuyệt đẹp của bờ biển trên chuyến tàu đến đó. Bây giờ, tôi đã có vé của các bạn, vì vậy các bạn có thể đi dạo quanh nhà ga cho đến khi đến giờ lên tàu. Lúc 8:50, hãy gặp nhau ở góc giữa lối vào sân ga và quán cà phê. À, và có thể sẽ có một chút thay đổi trong lịch trình nếu cơn mưa này không dừng lại. Tôi sẽ kiểm tra dự báo thời tiết trên điện thoại ngay bây giờ, để có thể thông báo cho các bạn khi chúng ta gặp lại nhau.');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7699, 6098, 98, 'Who most likely is the speaker?', 'A ticket agent', 'A tour guide', 'A train conductor', 'A maintenance supervisor', 'B', '[Dịch]
Câu hỏi: Ai là người nói nhiều khả năng nhất?
A: Nhân viên bán vé
B: Hướng dẫn viên du lịch
C: Nhân viên điều khiển tàu
D: Nhân viên bảo trì

Đáp án B là chính xác vì:
1. Người nói tự giới thiệu: "I''m Joyce McGuire, and I''m so excited to be leading today''s excursion for Whiterose Travel"
2. Các nhiệm vụ của người nói phù hợp với hướng dẫn viên:
- Nắm giữ vé cho cả nhóm ("I have your tickets")
- Tổ chức điểm gặp ("let''s meet in that corner")
- Có khả năng điều chỉnh lịch trình
3. Đây là một chuyến tham quan có tổ chức của công ty du lịch Whiterose Travel');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6099, 270, '2025/test9/audio/test9_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7700, 6099, 99, 'Look at the graphic. What will the listeners meet in front of?', 'The ticket windows', 'The lockers', 'The convenience store', 'The café', 'B', '[Dịch]
Câu hỏi: Nhìn vào sơ đồ. Người nghe sẽ gặp nhau trước cái gì?
A: Quầy bán vé
B: Tủ khóa
C: Cửa hàng tiện lợi
D: Quán cà phê

Đáp án B là chính xác vì:
1. Trong văn bản, người nói xác định điểm gặp: "let''s meet in that corner between the platforms entrance and the café"
2. Khi xem sơ đồ, vị trí góc giữa lối vào sân ga và quán cà phê nằm ngay trước khu vực tủ khóa (Lockers)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6100, 270, '2025/test9/audio/test9_question_98_100.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7701, 6100, 100, 'What will the speaker do next?', 'Post a written notice', 'Check a weather forecast', 'Distribute an itinerary', 'Make a phone call', 'B', '[Dịch]
Câu hỏi: Người nói sẽ làm gì tiếp theo?
A: Đăng thông báo bằng văn bản
B: Kiểm tra dự báo thời tiết
C: Phân phát lịch trình
D: Thực hiện cuộc gọi điện thoại

Đáp án B là chính xác vì:
1. Trong văn bản, người nói tuyên bố rõ ràng: "I''ll pull up the forecast on my mobile phone now"
2. Việc kiểm tra thời tiết là cần thiết vì:
- Trời đang mưa ("if this rain doesn''t stop")
- Có thể phải thay đổi lịch trình
3. Người nói cần thông tin này để thông báo cho nhóm khi gặp lại');;

-- Data for 2025 Test9 Part 5
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6101, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7702, 6101, 101, 'One purpose of the Librarian Association''s blog is to bring new and ---- ideas to members'' attention.', 'diversify', 'diversely', 'diverse', 'diversity', 'C', 'Đáp án C (diverse) là đúng vì các lý do sau:
1. Cần một tính từ để bổ nghĩa cho danh từ "ideas".
2. "Diverse" là tính từ có nghĩa "đa dạng, phong phú".
3. Cấu trúc "new and diverse" là cặp tính từ song song bổ nghĩa cho danh từ.
4. Các đáp án khác không phù hợp: "diversify" (động từ), "diversely" (trạng từ), "diversity" (danh từ).
Dịch câu hỏi: Một mục đích của blog của Hiệp hội Thư viện là mang những ý tưởng mới và đa dạng đến sự chú ý của các thành viên.
Dịch đáp án:
A. diversify (động từ: đa dạng hóa)
B. diversely (trạng từ: một cách đa dạng)
C. diverse (tính từ: đa dạng)
D. diversity (danh từ: sự đa dạng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6102, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7703, 6102, 102, 'Our restaurant has served over 70,000 hamburgers ----- opening in March.', 'within', 'besides', 'since', 'past', 'C', 'Đáp án C (since) là đúng vì các lý do sau:
1. Cần một giới từ chỉ thời gian kể từ một điểm bắt đầu.
2. "Since" dùng để chỉ thời điểm bắt đầu.
3. Cấu trúc "since + thời điểm" diễn tả khoảng thời gian từ lúc bắt đầu đến hiện tại.
4. Các đáp án khác không phù hợp: "within" (trong vòng), "besides" (bên cạnh), "past" (qua).
Dịch câu hỏi: Nhà hàng của chúng tôi đã phục vụ hơn 70.000 hamburger kể từ khi khai trương vào tháng Ba.
Dịch đáp án:
A. within (giới từ: trong vòng)
B. besides (giới từ: bên cạnh)
C. since (giới từ: kể từ)
D. past (giới từ: qua)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6103, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7704, 6103, 103, 'The new customer service staff are finally knowledgeable ----- about our appliances to give troubleshooting advice to customers.', 'even', 'enough', 'much', 'already', 'B', 'Đáp án B (enough) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ mức độ đủ.
2. "Enough" đứng sau tính từ để chỉ mức độ đủ để làm gì đó.
3. Cấu trúc "adjective + enough + to do something" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp: "even" (thậm chí), "much" (nhiều), "already" (đã).
Dịch câu hỏi: Nhân viên dịch vụ khách hàng mới cuối cùng đã có đủ kiến thức về các thiết bị của chúng tôi để đưa ra lời khuyên xử lý sự cố cho khách hàng.
Dịch đáp án:
A. even (trạng từ: thậm chí)
B. enough (trạng từ: đủ)
C. much (trạng từ: nhiều)
D. already (trạng từ: đã)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6104, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7705, 6104, 104, 'IT department workers must respond promptly to colleagues'' technical support -----.', 'requesting', 'will request', 'requested', 'requests', 'D', 'Đáp án D (requests) là đúng vì các lý do sau:
1. Cần một danh từ làm tân ngữ của giới từ "to".
2. "Requests" là danh từ số nhiều chỉ yêu cầu, đề nghị.
3. Phù hợp với ngữ cảnh về hỗ trợ kỹ thuật.
4. Các đáp án khác không phù hợp: "requesting" (động từ ing), "will request" (tương lai), "requested" (quá khứ).
Dịch câu hỏi: Nhân viên phòng IT phải phản hồi nhanh chóng các yêu cầu hỗ trợ kỹ thuật của đồng nghiệp.
Dịch đáp án:
A. requesting (động từ ing: đang yêu cầu)
B. will request (tương lai: sẽ yêu cầu)
C. requested (quá khứ: đã yêu cầu)
D. requests (danh từ số nhiều: những yêu cầu)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6105, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7706, 6105, 105, 'The intern will work ----- the direction of the senior communications officer.', 'on', 'under', 'for', 'as', 'B', 'Đáp án B (under) là đúng vì các lý do sau:
1. Cần một giới từ chỉ sự chỉ đạo, giám sát.
2. "Under the direction of" là cụm từ cố định chỉ việc làm việc dưới sự hướng dẫn.
3. Phù hợp với mối quan hệ giữa thực tập sinh và cấp trên.
4. Các đáp án khác không phù hợp: "on" (trên), "for" (cho), "as" (như).
Dịch câu hỏi: Thực tập sinh sẽ làm việc dưới sự chỉ đạo của cán bộ truyền thông cao cấp.
Dịch đáp án:
A. on (giới từ: trên)
B. under (giới từ: dưới)
C. for (giới từ: cho)
D. as (giới từ: như)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6106, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7707, 6106, 106, 'Ms. Velling instructed —-- who need additional office supplies to send her a list of items by e-mail.', 'these', 'they', 'those', 'them', 'C', 'Đáp án C (those) là đúng vì các lý do sau:
1. Cần một đại từ chỉ định làm chủ ngữ.
2. "Those who" là cụm từ chỉ "những người mà".
3. Cấu trúc "those + who + verb" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp: "these" (những cái này), "they" (họ), "them" (họ-tân ngữ).
Dịch câu hỏi: Bà Velling đã hướng dẫn những người cần thêm văn phòng phẩm gửi cho bà ấy danh sách các vật phẩm qua email.
Dịch đáp án:
A. these (đại từ chỉ định: những cái này)
B. they (đại từ nhân xưng: họ)
C. those (đại từ chỉ định: những người)
D. them (đại từ tân ngữ: họ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6107, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7708, 6107, 107, 'Because of new city ordinances, operating a business in Sanderton has become ----- difficult.', 'increasingly', 'increased', 'increase', 'increasing', 'A', 'Đáp án A (increasingly) là đúng vì các lý do sau:
1. Cần một trạng từ bổ nghĩa cho tính từ "difficult".
2. "Increasingly" có nghĩa là "ngày càng".
3. Cấu trúc "become increasingly + adjective" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp: "increased" (tăng - quá khứ), "increase" (tăng - động từ), "increasing" (đang tăng).
Dịch câu hỏi: Do các quy định mới của thành phố, việc điều hành kinh doanh ở Sanderton đã trở nên ngày càng khó khăn.
Dịch đáp án:
A. increasingly (trạng từ: ngày càng)
B. increased (quá khứ phân từ: đã tăng)
C. increase (động từ: tăng)
D. increasing (hiện tại phân từ: đang tăng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6108, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7709, 6108, 108, 'The botanical gardens have played an ------ part in the recent rise in tourism to Moriva.', 'extending', 'extensive', 'extension', 'extensively', 'B', 'Đáp án B (extensive) là đúng vì các lý do sau:
1. Cần một tính từ để bổ nghĩa cho danh từ "part".
2. "Extensive" có nghĩa là "rộng lớn, quan trọng".
3. "Play an extensive part" là cụm từ chỉ vai trò quan trọng.
4. Các đáp án khác không phù hợp: "extending" (mở rộng), "extension" (sự mở rộng), "extensively" (rộng rãi).
Dịch câu hỏi: Vườn thực vật đã đóng một vai trò quan trọng trong sự gia tăng gần đây về du lịch đến Moriva.
Dịch đáp án:
A. extending (động từ ing: đang mở rộng)
B. extensive (tính từ: rộng lớn)
C. extension (danh từ: sự mở rộng)
D. extensively (trạng từ: rộng rãi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6109, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7710, 6109, 109, 'Each Ainsville Fire Department inspector will no longer ----- in a single area of fire prevention.', 'special', 'specialize', 'specialization', 'specially', 'B', 'Đáp án B (specialize) là đúng vì các lý do sau:
1. Cần một động từ chỉ sự chuyên môn hóa.
2. "Specialize in" là cụm động từ có nghĩa "chuyên môn hóa trong".
3. Chủ ngữ số ít (each inspector) cần động từ nguyên thể.
4. Các đáp án khác không phù hợp: "special" (đặc biệt - tính từ), "specialization" (sự chuyên môn hóa), "specially" (đặc biệt - trạng từ).
Dịch câu hỏi: Mỗi thanh tra viên của Sở Cứu hỏa Ainsville sẽ không còn chuyên môn hóa trong một lĩnh vực phòng cháy duy nhất.
Dịch đáp án:
A. special (tính từ: đặc biệt)
B. specialize (động từ: chuyên môn hóa)
C. specialization (danh từ: sự chuyên môn hóa)
D. specially (trạng từ: đặc biệt)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6110, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7711, 6110, 110, 'Ms. Lewis has been tasked with ----- the results of our recently completed survey.', 'summarizing', 'performing', 'improving', 'achieving', 'A', 'Đáp án A (summarizing) là đúng vì các lý do sau:
1. Cần một động từ ing sau giới từ "with".
2. "Task with + V-ing" là cấu trúc chỉ nhiệm vụ được giao.
3. "Summarize results" là cụm từ phổ biến trong ngữ cảnh báo cáo.
4. Các đáp án khác không phù hợp về nghĩa: "performing" (thực hiện), "improving" (cải thiện), "achieving" (đạt được).
Dịch câu hỏi: Bà Lewis đã được giao nhiệm vụ tổng hợp kết quả cuộc khảo sát gần đây đã hoàn thành của chúng tôi.
Dịch đáp án:
A. summarizing (động từ ing: tổng hợp)
B. performing (động từ ing: thực hiện)
C. improving (động từ ing: cải thiện)
D. achieving (động từ ing: đạt được)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6111, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7712, 6111, 111, 'Gatewood Corporation currently ---- employees from discussing their work or the company on social media.', 'forbid', 'forbids', 'forbidding', 'forbidden', 'B', 'Đáp án B (forbids) là đúng vì các lý do sau:
1. Cần một động từ chia ở ngôi thứ 3 số ít.
2. Chủ ngữ "Gatewood Corporation" là danh từ số ít.
3. "Forbid someone from doing something" là cấu trúc phổ biến.
4. Các đáp án khác không phù hợp: "forbid" (nguyên mẫu), "forbidding" (V-ing), "forbidden" (quá khứ phân từ).
Dịch câu hỏi: Tập đoàn Gatewood hiện cấm nhân viên thảo luận về công việc hoặc công ty của họ trên mạng xã hội.
Dịch đáp án:
A. forbid (động từ nguyên thể: cấm)
B. forbids (động từ số ít: cấm)
C. forbidding (động từ ing: đang cấm)
D. forbidden (quá khứ phân từ: bị cấm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6112, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7713, 6112, 112, 'The latest version of the Flamio headphones is identical to the previous one ---- some decorative elements.', 'added', 'prior to', 'regardless', 'aside from', 'D', 'Đáp án D (aside from) là đúng vì các lý do sau:
1. Cần một cụm giới từ chỉ sự ngoại trừ.
2. "Aside from" có nghĩa là "ngoại trừ, trừ".
3. Diễn tả sự giống nhau giữa hai phiên bản, chỉ khác về trang trí.
4. Các đáp án khác không phù hợp: "added" (thêm vào), "prior to" (trước), "regardless" (bất kể).
Dịch câu hỏi: Phiên bản mới nhất của tai nghe Flamio giống hệt phiên bản trước đó ngoại trừ một số yếu tố trang trí.
Dịch đáp án:
A. added (động từ quá khứ: thêm vào)
B. prior to (cụm giới từ: trước)
C. regardless (phó từ: bất kể)
D. aside from (cụm giới từ: ngoại trừ)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6113, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7714, 6113, 113, 'A copy of the meeting notes should be sent to Mr. Won, -- is currently visiting the Hong Kong office.', 'who', 'his', 'that', 'another', 'A', 'Đáp án A (who) là đúng vì các lý do sau:
1. Cần một đại từ quan hệ để liên kết mệnh đề chỉ người.
2. "Who" là đại từ quan hệ dùng cho người.
3. Mệnh đề sau dấu phẩy là mệnh đề không hạn định.
4. Các đáp án khác không phù hợp: "his" (tính từ sở hữu), "that" (không dùng sau dấu phẩy), "another" (khác).
Dịch câu hỏi: Một bản ghi chép cuộc họp nên được gửi cho ông Won, người hiện đang thăm văn phòng Hong Kong.
Dịch đáp án:
A. who (đại từ quan hệ: người mà)
B. his (tính từ sở hữu: của ông ấy)
C. that (đại từ quan hệ: mà)
D. another (tính từ: khác)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6114, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7715, 6114, 114, 'The noise issue with the Traction G20 truck was ----- once the cross bars on the roof rack were adjusted.', 'resolve', 'resolving', 'resolution', 'resolved', 'D', 'Đáp án D (resolved) là đúng vì các lý do sau:
1. Cần một quá khứ phân từ để tạo thành thể bị động.
2. "Was resolved" là thể bị động quá khứ đơn.
3. Diễn tả vấn đề đã được giải quyết.
4. Các đáp án khác không phù hợp: "resolve" (giải quyết), "resolving" (đang giải quyết), "resolution" (giải pháp).
Dịch câu hỏi: Vấn đề về tiếng ồn của xe tải Traction G20 đã được giải quyết một khi các thanh chéo trên giá nóc được điều chỉnh.
Dịch đáp án:
A. resolve (động từ: giải quyết)
B. resolving (động từ ing: đang giải quyết)
C. resolution (danh từ: giải pháp)
D. resolved (quá khứ phân từ: đã giải quyết)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6115, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7716, 6115, 115, 'The goal of the negotiations is to find a solution that will be ------ to both parties.', 'agreeing', 'agreeable', 'agreeably', 'to agree', 'B', 'Đáp án B (agreeable) là đúng vì các lý do sau:
1. Cần một tính từ sau động từ "be".
2. "Agreeable to" có nghĩa là "có thể chấp nhận được đối với".
3. Diễn tả một giải pháp mà cả hai bên có thể chấp nhận.
4. Các đáp án khác không phù hợp: "agreeing" (đồng ý), "agreeably" (đồng thuận), "to agree" (để đồng ý).
Dịch câu hỏi: Mục tiêu của các cuộc đàm phán là tìm ra một giải pháp có thể chấp nhận được đối với cả hai bên.
Dịch đáp án:
A. agreeing (động từ ing: đang đồng ý)
B. agreeable (tính từ: có thể chấp nhận được)
C. agreeably (trạng từ: một cách đồng thuận)
D. to agree (động từ nguyên mẫu: để đồng ý)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6116, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7717, 6116, 116, '--—- buying computer hardware, companies with changeable needs should use technology rental services.', 'Whenever', 'Depending on', 'Instead of', 'However', 'C', 'Đáp án C (Instead of) là đúng vì các lý do sau:
1. Cần một cụm giới từ chỉ sự thay thế.
2. "Instead of + V-ing" diễn tả sự lựa chọn thay thế.
3. Phù hợp với ngữ cảnh về việc thuê thay vì mua.
4. Các đáp án khác không phù hợp: "Whenever" (bất cứ khi nào), "Depending on" (phụ thuộc vào), "However" (tuy nhiên).
Dịch câu hỏi: Thay vì mua phần cứng máy tính, các công ty có nhu cầu thay đổi nên sử dụng dịch vụ thuê công nghệ.
Dịch đáp án:
A. Whenever (phó từ: bất cứ khi nào)
B. Depending on (cụm giới từ: phụ thuộc vào)
C. Instead of (cụm giới từ: thay vì)
D. However (phó từ: tuy nhiên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6117, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7718, 6117, 117, 'The drop in our average product rating is ----- a temporary consequence of the packaging redesign.', 'simple', 'simpler', 'simplest', 'simply', 'D', 'Đáp án D (simply) là đúng vì các lý do sau:
1. Cần một trạng từ bổ nghĩa cho cả câu.
2. "Simply" có nghĩa là "đơn giản là, chỉ là".
3. Diễn tả một giải thích đơn giản cho hiện tượng.
4. Các đáp án khác không phù hợp: "simple" (đơn giản - tính từ), "simpler" (đơn giản hơn), "simplest" (đơn giản nhất).
Dịch câu hỏi: Sự sụt giảm trong đánh giá sản phẩm trung bình của chúng tôi đơn giản chỉ là hệ quả tạm thời của việc thiết kế lại bao bì.
Dịch đáp án:
A. simple (tính từ: đơn giản)
B. simpler (tính từ so sánh hơn: đơn giản hơn)
C. simplest (tính từ so sánh nhất: đơn giản nhất)
D. simply (trạng từ: đơn giản là)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6118, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7719, 6118, 118, 'An airline representative will contact you ---- your luggage has been located by a member of our staff.', 'at first', 'in case', 'rather than', 'as soon as', 'D', 'Đáp án D (as soon as) là đúng vì các lý do sau:
1. Cần một cụm từ chỉ thời gian ngay lập tức.
2. "As soon as" có nghĩa là "ngay khi".
3. Diễn tả hành động sẽ được thực hiện ngay lập tức sau một điều kiện.
4. Các đáp án khác không phù hợp: "at first" (lúc đầu), "in case" (phòng khi), "rather than" (thay vì).
Dịch câu hỏi: Một đại diện hãng hàng không sẽ liên hệ với bạn ngay khi hành lý của bạn được một nhân viên của chúng tôi tìm thấy.
Dịch đáp án:
A. at first (cụm từ: lúc đầu)
B. in case (cụm từ: phòng khi)
C. rather than (cụm từ: thay vì)
D. as soon as (cụm từ: ngay khi)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6119, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7720, 6119, 119, 'The space adjacent to Leland Florist is available to be ----- by a new tenant.', 'enclosed', 'leased', 'permitted', 'preoccupied', 'B', 'Đáp án B (leased) là đúng vì các lý do sau:
1. Cần một quá khứ phân từ chỉ việc cho thuê.
2. "To be leased" là cụm động từ bị động chỉ việc được thuê.
3. Phù hợp với ngữ cảnh về không gian cho thuê.
4. Các đáp án khác không phù hợp: "enclosed" (bao bọc), "permitted" (cho phép), "preoccupied" (bận tâm).
Dịch câu hỏi: Không gian liền kề với cửa hàng hoa Leland có sẵn để được thuê bởi một người thuê mới.
Dịch đáp án:
A. enclosed (quá khứ phân từ: được bao bọc)
B. leased (quá khứ phân từ: được thuê)
C. permitted (quá khứ phân từ: được cho phép)
D. preoccupied (quá khứ phân từ: bị bận tâm)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6120, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7721, 6120, 120, 'Each year, the - of the Barnes Engineering Conference pose for a commemorative group photo.', 'organizing', 'organizational', 'organization', 'organizers', 'D', 'Đáp án D (organizers) là đúng vì các lý do sau:
1. Cần một danh từ chỉ người làm chủ ngữ.
2. "Organizers" là danh từ chỉ người tổ chức.
3. Số nhiều phù hợp với động từ "pose".
4. Các đáp án khác không phù hợp: "organizing" (đang tổ chức), "organizational" (thuộc tổ chức), "organization" (tổ chức).
Dịch câu hỏi: Mỗi năm, những người tổ chức Hội nghị Kỹ thuật Barnes chụp một bức ảnh nhóm kỷ niệm.
Dịch đáp án:
A. organizing (động từ ing: đang tổ chức)
B. organizational (tính từ: thuộc tổ chức)
C. organization (danh từ: tổ chức)
D. organizers (danh từ: người tổ chức)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6121, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7722, 6121, 121, 'For offices, we recommend plants that grow well in ----- conditions such as low lighting and inconsistent watering.', 'dense', 'adverse', 'skeptical', 'durable', 'B', 'Đáp án B (adverse) là đúng vì các lý do sau:
1. Cần một tính từ mô tả điều kiện không thuận lợi.
2. "Adverse conditions" là cụm từ chỉ điều kiện bất lợi.
3. Phù hợp với ngữ cảnh về ánh sáng yếu và tưới nước không đều.
4. Các đáp án khác không phù hợp: "dense" (dày đặc), "skeptical" (hoài nghi), "durable" (bền).
Dịch câu hỏi: Đối với văn phòng, chúng tôi khuyến nghị các loại cây phát triển tốt trong điều kiện bất lợi như ánh sáng yếu và tưới nước không đều.
Dịch đáp án:
A. dense (tính từ: dày đặc)
B. adverse (tính từ: bất lợi)
C. skeptical (tính từ: hoài nghi)
D. durable (tính từ: bền)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6122, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7723, 6122, 122, 'For its next performance, on December 11, the Peltier Symphony will be led by acclaimed ----- Misaki Ogawa.', 'conduct', 'conducts', 'conductor', 'conducting', 'C', 'Đáp án C (conductor) là đúng vì các lý do sau:
1. Cần một danh từ chỉ người.
2. "Acclaimed conductor" là cụm từ chỉ nhạc trưởng nổi tiếng.
3. Danh từ phù hợp để chỉ chức danh trước tên người.
4. Các đáp án khác không phù hợp: "conduct" (chỉ huy), "conducts" (chỉ huy - động từ), "conducting" (đang chỉ huy).
Dịch câu hỏi: Cho buổi biểu diễn tiếp theo, vào ngày 11 tháng 12, dàn nhạc giao hưởng Peltier sẽ được dẫn dắt bởi nhạc trưởng nổi tiếng Misaki Ogawa.
Dịch đáp án:
A. conduct (động từ: chỉ huy)
B. conducts (động từ số ít: chỉ huy)
C. conductor (danh từ: nhạc trưởng)
D. conducting (động từ ing: đang chỉ huy)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6123, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7724, 6123, 123, 'Desirable parking spaces ----- the city are being converted to electric vehicle charging stations.', 'out of', 'next to', 'throughout', 'along', 'C', 'Đáp án C (throughout) là đúng vì các lý do sau:
1. Cần một giới từ chỉ sự phân bố khắp nơi.
2. "Throughout" có nghĩa là "khắp, trên khắp".
3. Diễn tả việc chuyển đổi diễn ra ở nhiều nơi trong thành phố.
4. Các đáp án khác không phù hợp: "out of" (ra khỏi), "next to" (bên cạnh), "along" (dọc theo).
Dịch câu hỏi: Các chỗ đậu xe đắc địa khắp thành phố đang được chuyển đổi thành trạm sạc xe điện.
Dịch đáp án:
A. out of (cụm giới từ: ra khỏi)
B. next to (cụm giới từ: bên cạnh)
C. throughout (giới từ: khắp)
D. along (giới từ: dọc theo)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6124, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7725, 6124, 124, 'TGN Bank has received industry —-- for its Vista Credit Card, which offers its holders excellent rewards for a low annual fee.', 'regulation', 'demand', 'reputation', 'recognition', 'D', 'Đáp án D (recognition) là đúng vì các lý do sau:
1. Cần một danh từ chỉ sự công nhận, ghi nhận.
2. "Industry recognition" là cụm từ chỉ sự công nhận từ ngành.
3. Phù hợp với ngữ cảnh tích cực về thẻ tín dụng.
4. Các đáp án khác không phù hợp: "regulation" (quy định), "demand" (nhu cầu), "reputation" (danh tiếng).
Dịch câu hỏi: Ngân hàng TGN đã nhận được sự công nhận của ngành đối với thẻ tín dụng Vista của họ, thẻ mang lại phần thưởng tuyệt vời cho chủ thẻ với phí thường niên thấp.
Dịch đáp án:
A. regulation (danh từ: quy định)
B. demand (danh từ: nhu cầu)
C. reputation (danh từ: danh tiếng)
D. recognition (danh từ: sự công nhận)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6125, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7726, 6125, 125, 'If your store is poorly stocked or disorganized when prospective customers visit, they may choose to shop -----.', 'apart', 'seldom', 'otherwise', 'elsewhere', 'D', 'Đáp án D (elsewhere) là đúng vì các lý do sau:
1. Cần một trạng từ chỉ địa điểm khác.
2. "Shop elsewhere" có nghĩa là "mua sắm ở nơi khác".
3. Phù hợp với ngữ cảnh về việc khách hàng có thể chọn cửa hàng khác.
4. Các đáp án khác không phù hợp: "apart" (tách ra), "seldom" (hiếm khi), "otherwise" (nếu không thì).
Dịch câu hỏi: Nếu cửa hàng của bạn thiếu hàng hoặc không được tổ chức tốt khi khách hàng tiềm năng đến thăm, họ có thể chọn mua sắm ở nơi khác.
Dịch đáp án:
A. apart (trạng từ: tách ra)
B. seldom (trạng từ: hiếm khi)
C. otherwise (trạng từ: nếu không thì)
D. elsewhere (trạng từ: ở nơi khác)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6126, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7727, 6126, 126, 'The company returned to ----- after raising prices for its services.', 'profitability', 'advantage', 'performance', 'priority', 'A', 'Đáp án A (profitability) là đúng vì các lý do sau:
1. Cần một danh từ chỉ khả năng sinh lời.
2. "Return to profitability" là cụm từ chỉ việc trở lại có lãi.
3. Phù hợp với ngữ cảnh về việc tăng giá dịch vụ.
4. Các đáp án khác không phù hợp: "advantage" (lợi thế), "performance" (hiệu suất), "priority" (ưu tiên).
Dịch câu hỏi: Công ty đã trở lại có lãi sau khi tăng giá các dịch vụ của mình.
Dịch đáp án:
A. profitability (danh từ: khả năng sinh lời)
B. advantage (danh từ: lợi thế)
C. performance (danh từ: hiệu suất)
D. priority (danh từ: ưu tiên)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6127, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7728, 6127, 127, 'The dress code should be posted in a prominent spot in the employee lounge so that ----- can see it.', 'everyone', 'either', 'few', 'whomever', 'A', 'Đáp án A (everyone) là đúng vì các lý do sau:
1. Cần một đại từ chỉ tất cả mọi người.
2. "So that everyone can" là cấu trúc chỉ mục đích cho tất cả mọi người.
3. Phù hợp với ngữ cảnh về quy định cần mọi người biết.
4. Các đáp án khác không phù hợp: "either" (một trong hai), "few" (ít), "whomever" (bất kỳ ai - tân ngữ).
Dịch câu hỏi: Quy định trang phục nên được dán ở vị trí dễ thấy trong phòng nghỉ của nhân viên để mọi người có thể nhìn thấy.
Dịch đáp án:
A. everyone (đại từ: mọi người)
B. either (từ xác định: một trong hai)
C. few (từ xác định: ít)
D. whomever (đại từ: bất kỳ ai)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6128, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7729, 6128, 128, 'Maxwell Publishing''s textbooks include a list of ---- materials teachers can use to broaden students'' understanding of each topic.', 'deliberate', 'superfluous', 'supplemental', 'approximate', 'C', 'Đáp án C (supplemental) là đúng vì các lý do sau:
1. Cần một tính từ chỉ tài liệu bổ sung.
2. "Supplemental materials" là cụm từ chỉ tài liệu bổ trợ.
3. Phù hợp với mục đích mở rộng hiểu biết của học sinh.
4. Các đáp án khác không phù hợp: "deliberate" (cố ý), "superfluous" (thừa), "approximate" (gần đúng).
Dịch câu hỏi: Sách giáo khoa của Nhà xuất bản Maxwell bao gồm danh sách các tài liệu bổ trợ mà giáo viên có thể sử dụng để mở rộng hiểu biết của học sinh về mỗi chủ đề.
Dịch đáp án:
A. deliberate (tính từ: cố ý)
B. superfluous (tính từ: thừa)
C. supplemental (tính từ: bổ trợ)
D. approximate (tính từ: gần đúng)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6129, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7730, 6129, 129, 'The two films opening this week are both so highly anticipated that it is unclear ----- one will sell the most tickets.', 'which', 'other', 'because', 'about', 'A', 'Đáp án A (which) là đúng vì các lý do sau:
1. Cần một đại từ nghi vấn để chỉ sự lựa chọn.
2. "Which one" dùng để hỏi về một trong số các lựa chọn.
3. Phù hợp với ngữ cảnh so sánh giữa hai bộ phim.
4. Các đáp án khác không phù hợp: "other" (khác), "because" (bởi vì), "about" (về).
Dịch câu hỏi: Hai bộ phim ra mắt tuần này đều được mong đợi cao đến nỗi không rõ bộ phim nào sẽ bán được nhiều vé nhất.
Dịch đáp án:
A. which (đại từ nghi vấn: cái nào)
B. other (tính từ: khác)
C. because (liên từ: bởi vì)
D. about (giới từ: về)');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6130, 271, NULL, NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7731, 6130, 130, 'Current ----- suggest that clothing will overtake footwear as our top revenue-generating category sometime this year.', 'trends', 'designs', 'guidelines', 'advertisements', 'A', 'Đáp án A (trends) là đúng vì các lý do sau:
1. Cần một danh từ chỉ xu hướng.
2. "Current trends" là cụm từ chỉ xu hướng hiện tại.
3. Phù hợp với ngữ cảnh về dự đoán tương lai.
4. Các đáp án khác không phù hợp: "designs" (thiết kế), "guidelines" (hướng dẫn), "advertisements" (quảng cáo).
Dịch câu hỏi: Xu hướng hiện tại cho thấy quần áo sẽ vượt qua giày dép để trở thành danh mục tạo doanh thu hàng đầu của chúng tôi trong năm nay.
Dịch đáp án:
A. trends (danh từ: xu hướng)
B. designs (danh từ: thiết kế)
C. guidelines (danh từ: hướng dẫn)
D. advertisements (danh từ: quảng cáo)');;

-- Data for 2025 Test9 Part 6
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6131, 272, NULL, NULL, 'The redesign of Wheeler Corporation''s headquarters resulted in the removal of over 40 paintings from our hallways and offices. Management 131....... to allow employees to purchase this surplus artwork at reasonable prices through a private online auction. Visit the link at the bottom of this notice to view the available items. 132..... may be submitted through the same site between 9 A.M. on May 5 and 7 P.M. on May 9. Once the auction ends, the winning employees will receive an e-mail with instructions 133....... payment and pick-up. 134....... . All proceeds from the auction will go to a local children''s charity.
www.auctionhelper.com/49321', 'Việc thiết kế lại trụ sở của Tập đoàn Wheeler dẫn đến việc di dời hơn 40 bức tranh từ hành lang và văn phòng của chúng tôi. Ban quản lý 131....... cho phép nhân viên mua các tác phẩm nghệ thuật thừa này với giá hợp lý thông qua đấu giá trực tuyến riêng. Truy cập liên kết ở cuối thông báo này để xem các mặt hàng có sẵn. 132..... có thể được gửi qua cùng một trang web từ 9 giờ sáng ngày 5 tháng 5 đến 7 giờ tối ngày 9 tháng 5. Khi kết thúc đấu giá, nhân viên trúng thầu sẽ nhận được email hướng dẫn 133....... thanh toán và nhận hàng. 134....... . Tất cả tiền thu được từ đấu giá sẽ được quyên góp cho quỹ từ thiện trẻ em địa phương.
www.auctionhelper.com/49321');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7732, 6131, 131, NULL, 'decision', 'to decide', 'has decided', 'deciding', 'C', 'A. decision (quyết định - danh từ)
B. to decide (để quyết định - động từ nguyên mẫu)
C. has decided (đã quyết định - động từ hiện tại hoàn thành)
D. deciding (đang quyết định - hiện tại phân từ)
Đáp án đúng là C (has decided) vì:
1. Ngữ cảnh: Quyết định đã được đưa ra và có hiệu lực
2. "Has decided" phù hợp vì:
- Thì hiện tại hoàn thành chỉ quyết định gần đây
- Kết quả vẫn còn hiệu lực (cho phép mua tranh)
3. Các đáp án khác không phù hợp về ngữ pháp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7733, 6131, 132, NULL, 'Pieces', 'Donations', 'Nominations', 'Bids', 'D', 'A. Pieces (các tác phẩm - danh từ)
B. Donations (đóng góp - danh từ)
C. Nominations (đề cử - danh từ)
D. Bids (các lượt đặt giá - danh từ)
Đáp án đúng là D (Bids) vì:
1. Ngữ cảnh: Phiên đấu giá trực tuyến
2. "Bids" phù hợp vì:
- Là thuật ngữ chuyên dùng trong đấu giá
- Chỉ các lượt trả giá của người tham gia
3. Các đáp án khác không phù hợp với hoạt động đấu giá');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7734, 6131, 133, NULL, 'given', 'concerning', 'during', 'plus', 'B', 'A. given (được cho - quá khứ phân từ)
B. concerning (liên quan đến - giới từ)
C. during (trong - giới từ)
D. plus (cộng với - liên từ)
Đáp án đúng là B (concerning) vì:
1. Ngữ cảnh: Email hướng dẫn về thanh toán và nhận hàng
2. "Concerning" phù hợp vì:
- Chỉ nội dung liên quan đến việc cần hướng dẫn
- Kết nối "instructions" với "payment and pick-up"
3. Các giới từ khác không tạo được nghĩa phù hợp');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7735, 6131, 134, NULL, 'If you have not received one yet, check your spam filter.', 'Paintings must then be collected by 5 P.M. on May 16.', 'Wheeler Corporation is located at 390 Cranford Street.', 'Three winners will be chosen from among the submissions.', 'B', 'A. If you have not received one yet, check your spam filter (Nếu bạn chưa nhận được, hãy kiểm tra bộ lọc spam)
B. Paintings must then be collected by 5 P.M. on May 16 (Tranh phải được nhận trước 5 giờ chiều ngày 16 tháng 5)
C. Wheeler Corporation is located at 390 Cranford Street (Tập đoàn Wheeler tọa lạc tại 390 Đường Cranford)
D. Three winners will be chosen from among the submissions (Ba người chiến thắng sẽ được chọn từ các lượt đặt giá)
Đáp án đúng là B vì:
1. Liên kết logic với việc nhận hàng
2. Cung cấp thông tin quan trọng về thời hạn
3. Các đáp án khác không liên quan đến quy trình đấu giá');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6132, 272, NULL, NULL, 'To: Klein Print Shop Staff
From: Leslie Klein
Subject: Document shredding
Date: January 18
Dear Staff:
I''m proud to announce that Neil and I have obtained a professional 135...... in secure document destruction from the National Data Management Association. We''re 136...... authorized to shred documents classified by the government as containing sensitive information. In the past, you were told to refer government customers 137...... other businesses for this service. 138...... .
Finally, if we consistently receive high volumes of work, I may consider paying for some of you to receive this qualification as well.
Leslie Klein
Owner & Operator
Klein Print Shop', 'Gửi đến: Nhân viên cửa hàng in Klein
Từ: Leslie Klein
Chủ đề: hủy tài liệu
Ngày: 18 tháng 1
Kính gửi Nhân viên:
Tôi tự hào thông báo rằng Neil và tôi đã nhận được chứng chỉ chuyên nghiệp 135...... trong việc hủy tài liệu an toàn từ Hiệp hội Quản lý Dữ liệu Quốc gia. Chúng tôi là 136...... được ủy quyền băm nhỏ các tài liệu được chính phủ phân loại là chứa thông tin nhạy cảm. Trước đây, bạn được yêu cầu giới thiệu khách hàng chính phủ 137...... các doanh nghiệp khác cho dịch vụ này. 138...... .
Cuối cùng, nếu chúng tôi liên tục nhận được khối lượng công việc lớn, tôi có thể cân nhắc trả tiền cho một số bạn để nhận được bằng cấp này.
Leslie Klein
Chủ sở hữu & Nhà điều hành
Cửa hàng in Klein');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7736, 6132, 135, NULL, 'certifies', 'certifiable', 'certification', 'is certified', 'C', 'A. certifies (chứng nhận - động từ)
B. certifiable (có thể chứng nhận - tính từ)
C. certification (chứng chỉ - danh từ)
D. is certified (được chứng nhận - bị động)
Đáp án đúng là C (certification) vì:
1. Ngữ cảnh: Nhận được chứng chỉ chuyên môn
2. "Certification" phù hợp vì:
- Là danh từ sau "professional"
- Chỉ văn bằng/chứng chỉ chính thức
3. Các đáp án khác không phù hợp cấu trúc');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7737, 6132, 136, NULL, 'still', 'now', 'almost', 'just', 'B', 'A. still (vẫn còn - trạng từ)
B. now (bây giờ - trạng từ)
C. almost (gần như - trạng từ)
D. just (vừa mới - trạng từ)
Đáp án đúng là B (now) vì:
1. Thể hiện thay đổi từ quá khứ đến hiện tại
2. Phản ánh thẩm quyền mới có được
3. Các trạng từ khác không phù hợp với ý nghĩa thay đổi tình trạng');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7738, 6132, 137, NULL, 'to', 'of', 'with', 'among', 'A', 'A. to (đến - giới từ)
B. of (của - giới từ)
C. with (với - giới từ)
D. among (giữa - giới từ)
Đáp án đúng là A (to) vì:
1. Cấu trúc "refer somebody to something"
2. Chỉ hướng giới thiệu khách hàng
3. Các giới từ khác không tạo cụm động từ đúng nghĩa');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7739, 6132, 138, NULL, 'This will no longer be our policy.', 'This work is not especially profitable.', 'Pricing information will be posted on the wall.', 'Customers may also shred their own documents.', 'A', 'A. This will no longer be our policy (Đây sẽ không còn là chính sách của chúng ta nữa)
B. This work is not especially profitable (Công việc này không đặc biệt có lãi)
C. Pricing information will be posted on the wall (Thông tin giá cả sẽ được dán trên tường)
D. Customers may also shred their own documents (Khách hàng cũng có thể tự hủy tài liệu)
Đáp án đúng là A vì:
1. Thông báo thay đổi chính sách cũ
2. Liên kết với thẩm quyền mới
3. Các đáp án khác không phù hợp ngữ cảnh');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6133, 272, NULL, NULL, 'To: Eun-Sook Yoo
From: Earl Fowler
Subject: Notice
Date: August 23
Dear Dr. Yoo,
I am writing to give you official notice that I am resigning from my position as Hillside Clinic''s office manager. My final day will be Friday, September 21. I hope this will allow you plenty of time to find my 139...... . If you are able to hire him or her before I go, I would be happy to handle the training. 140......, I will create detailed documentation about my work processes and make it available to everyone on the shared network. 141....... . Finally, I would like to express my gratitude to you for providing such 142...... support and leadership over the last five years. It was a pleasure to act as your office manager. I wish you and Hillside Clinic the best in the future.
Sincerely,
Earl Fowler', 'Gửi đến: Eun-Sook Yoo
Từ: Earl Fowler
Chủ đề: Thông báo
Ngày: 23 tháng 8
Tiến sĩ thân mến. Yoo,
Tôi viết thư này để thông báo chính thức cho bạn rằng tôi sẽ từ chức quản lý văn phòng của Hillside Clinic. Ngày cuối cùng của tôi sẽ là thứ Sáu, ngày 21 tháng Chín. Tôi hy vọng điều này sẽ cho phép bạn có nhiều thời gian để tìm 139 của tôi...... . Nếu bạn có thể thuê anh ấy hoặc cô ấy trước khi tôi đi, tôi sẽ rất vui khi xử lý việc đào tạo. 140......, Tôi sẽ tạo tài liệu chi tiết về quy trình làm việc của mình và cung cấp cho mọi người trên mạng được chia sẻ. 141....... . Cuối cùng, tôi muốn bày tỏ lòng biết ơn của mình đến bạn vì đã cung cấp 142...... hỗ trợ và lãnh đạo như vậy trong năm năm qua. Thật là một niềm vui khi được đóng vai trò là người quản lý văn phòng của bạn. Tôi chúc bạn và Phòng khám Hillside những điều tốt đẹp nhất trong tương lai.
Trân trọng,
Earl Fowler');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7740, 6133, 139, NULL, 'funding', 'records', 'belongings', 'replacement', 'D', 'A. funding (nguồn vốn - danh từ)
B. records (hồ sơ - danh từ)
C. belongings (đồ đạc - danh từ)
D. replacement (người thay thế - danh từ)
Đáp án đúng là D (replacement) vì:
1. Ngữ cảnh: Thư từ chức, cần tìm người thay thế
2. "Replacement" phù hợp vì:
- Chỉ người sẽ đảm nhận vị trí sau khi nghỉ
- Liên kết với việc đào tạo người mới
3. Các đáp án khác không liên quan đến nhân sự thay thế');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7741, 6133, 140, NULL, 'In any case', 'On the contrary', 'For example', 'As always', 'A', 'A. In any case (dù thế nào đi nữa - cụm từ nối)
B. On the contrary (trái lại - cụm từ nối)
C. For example (ví dụ - cụm từ nối)
D. As always (như mọi khi - cụm từ nối)
Đáp án đúng là A (In any case) vì:
1. Chuyển ý sang phương án dự phòng
2. Liên kết hai phương án bàn giao công việc
3. Các cụm từ khác không thể hiện được mối quan hệ logic này');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7742, 6133, 141, NULL, 'It is important to me to ease the transition for our staff and patients.', 'This is also the fastest way for you to share documents with me.', 'Most of my time is spent sourcing our medical and office supplies.', 'I usually start trainings for new hires by introducing the clinic''s history.', 'A', 'A. It is important to me to ease the transition for our staff and patients (Việc tạo điều kiện thuận lợi cho quá trình chuyển giao đối với nhân viên và bệnh nhân là điều quan trọng đối với tôi)
B. This is also the fastest way for you to share documents with me (Đây cũng là cách nhanh nhất để bạn chia sẻ tài liệu với tôi)
C. Most of my time is spent sourcing our medical and office supplies (Phần lớn thời gian của tôi dành cho việc tìm nguồn cung cấp vật tư y tế và văn phòng)
D. I usually start trainings for new hires by introducing the clinic''s history (Tôi thường bắt đầu đào tạo nhân viên mới bằng việc giới thiệu lịch sử phòng khám)
Đáp án đúng là A vì:
1. Thể hiện trách nhiệm trong bàn giao
2. Phù hợp với mục đích viết tài liệu hướng dẫn
3. Các đáp án khác không liên quan đến việc chuyển giao');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7743, 6133, 142, NULL, 'exception', 'exceptions', 'exceptional', 'exceptionally', 'C', 'A. exception (ngoại lệ - danh từ số ít)
B. exceptions (ngoại lệ - danh từ số nhiều)
C. exceptional (xuất sắc - tính từ)
D. exceptionally (xuất sắc - trạng từ)
Đáp án đúng là C (exceptional) vì:
1. Cấu trúc: "such + [tính từ] + danh từ"
2. Thể hiện sự đánh giá cao về sự hỗ trợ
3. Các dạng khác của từ không phù hợp về ngữ pháp');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6134, 272, NULL, NULL, 'BERLIN (16 March)-Harbinger Studios has held HarCon, a convention centered on its online games, each November in Berlin for the past 16 years. 143....... the event''s continued popularity, the company has canceled this year''s HarCon in favor of several smaller events in various cities. A post on Harbinger''s Web site explains that this format is better 144...... to this momentous year for the company. Two of its game franchises will mark major anniversaries of their initial releases, while a third is launching a widely anticipated expansion pack. 145........ .
However, the post also emphasizes that HarCon will return next year, reassuring readers that "Harbinger is well aware of how much this 146...... means to our fans."', 'BERLIN (16/3) - Harbinger Studios đã tổ chức HarCon, một hội nghị tập trung vào các trò chơi trực tuyến của họ, mỗi tháng 11 ở Berlin trong 16 năm qua. 143....... sự kiện vẫn được ưa chuộng, công ty đã hủy HarCon năm nay để ủng hộ một số sự kiện nhỏ hơn ở nhiều thành phố khác nhau. Một bài đăng trên trang web của Harbinger giải thích rằng định dạng này 144...... hơn cho năm quan trọng này của công ty. Hai thương hiệu trò chơi của họ sẽ đánh dấu những cột mốc kỷ niệm quan trọng kể từ khi phát hành ban đầu, trong khi một trò chơi thứ ba đang ra mắt gói mở rộng được mong đợi rộng rãi. 145........ .
Tuy nhiên, bài đăng cũng nhấn mạnh rằng HarCon sẽ trở lại vào năm tới, trấn an độc giả rằng "Harbinger rất hiểu 146...... này có ý nghĩa như thế nào đối với người hâm mộ của chúng tôi."');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7744, 6134, 143, NULL, 'Due to', 'Despite', 'Although', 'Along with', 'B', 'A. Due to (do - cụm giới từ)
B. Despite (mặc dù - giới từ)
C. Although (mặc dù - liên từ)
D. Along with (cùng với - cụm giới từ)
Đáp án đúng là B (Despite).
Giải thích:
1. Ngữ cảnh: Công ty hủy sự kiện HarCon mặc dù sự kiện vẫn được ưa chuộng
2. "Despite" phù hợp nhất vì:
- Là giới từ chỉ sự đối lập
- Kết hợp với danh từ "popularity"
- Thể hiện quyết định bất ngờ của công ty
3. Các đáp án khác không phù hợp vì:
- "Due to" chỉ nguyên nhân, không phải đối lập
- "Although" là liên từ, không thể kết hợp trực tiếp với danh từ
- "Along with" không thể hiện được sự đối lập
4. Cấu trúc ngữ pháp:
- "Despite + noun/noun phrase"
- Không dùng "despite" với mệnh đề');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7745, 6134, 144, NULL, 'suitability', 'suitable', 'suited', 'suitably', 'C', 'A. suitability (sự phù hợp - danh từ)
B. suitable (thích hợp - tính từ)
C. suited (phù hợp - quá khứ phân từ làm tính từ)
D. suitably (một cách phù hợp - trạng từ)
Đáp án đúng là C (suited).
Giải thích:
1. Cấu trúc: "be + suited + to + something"
2. "Suited" phù hợp nhất vì:
- Là tính từ sau động từ "is"
- Kết hợp với "to" tạo cụm từ hoàn chỉnh
- Diễn tả sự phù hợp giữa định dạng mới và dịp đặc biệt
3. Các đáp án khác không phù hợp vì:
- "Suitability" là danh từ, không dùng sau "is better"
- "Suitable" không kết hợp với "to"
- "Suitably" là trạng từ, không thể theo sau "is"
4. Ngữ pháp:
- "Better suited to" là cấu trúc so sánh hơn
- Thường dùng trong văn phong trang trọng');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7746, 6134, 145, NULL, 'Harbinger even makes several popular mobile applications.', 'Development of entirely new games is no longer its focus.', 'The company plans to celebrate these milestones separately.', 'Large events are often exponentially more costly to organize.', 'C', 'A. Harbinger even makes several popular mobile applications (Harbinger thậm chí còn tạo ra một số ứng dụng di động phổ biến)
B. Development of entirely new games is no longer its focus (Phát triển trò chơi hoàn toàn mới không còn là trọng tâm)
C. The company plans to celebrate these milestones separately (Công ty có kế hoạch kỷ niệm những cột mốc này một cách riêng biệt)
D. Large events are often exponentially more costly to organize (Các sự kiện lớn thường tốn kém hơn nhiều để tổ chức)
Đáp án đúng là C vì:
1. Ngữ cảnh:
- Nói về lý do tổ chức nhiều sự kiện nhỏ
- Có nhiều cột mốc quan trọng cần kỷ niệm
2. Câu C phù hợp nhất vì:
- Giải thích lý do chọn format mới
- Liên kết với việc tổ chức nhiều sự kiện nhỏ
- Phù hợp với chiến lược marketing
3. Các đáp án khác không phù hợp vì:
- A không liên quan đến chủ đề sự kiện
- B không giải thích được việc đổi format
- D không phải lý do chính của quyết định');;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7747, 6134, 146, NULL, 'award', 'product', 'character', 'gathering', 'D', 'A. award (giải thưởng - danh từ)
B. product (sản phẩm - danh từ)
C. character (nhân vật - danh từ)
D. gathering (sự kiện tập trung - danh từ)
Đáp án đúng là D (gathering).
Giải thích:
1. Ngữ cảnh:
- Đề cập đến HarCon
- Nhấn mạnh tầm quan trọng với fan
2. "Gathering" phù hợp nhất vì:
- Chỉ sự kiện tập trung đông người
- Thay thế cho từ "convention" đã dùng
- Thể hiện tính cộng đồng của sự kiện
3. Các đáp án khác không phù hợp vì:
- "Award" không liên quan đến hội nghị game
- "Product" không phải là điều đang đề cập
- "Character" không phù hợp ngữ cảnh
4. Tham chiếu:
- "This gathering" tham chiếu trực tiếp đến HarCon
- Nhấn mạnh giá trị tinh thần của sự kiện với fan');;

-- Data for 2025 Test9 Part 7
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6135, 273, NULL, NULL, 'www.prillenhome.com
Giraffe toy organizer shelving unit
