INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7808, 6156, 7, 'When does your flight leave?', 'About four hours from now.', 'From the international terminal.', 'On a direct flight.', NULL, 'A', 'Câu hỏi: Chuyến bay của bạn cất cánh lúc mấy giờ?"
A: "Khoảng bốn giờ nữa."
B: "Từ khu vực quốc tế."
C: "Một chuyến bay thẳng."
Giải thích: Đáp án A đúng vì câu hỏi hỏi về thời gian chuyến bay và đáp án A nói rằng chuyến bay sẽ khởi hành sau khoảng bốn giờ."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6157, 275, '2025/test10/audio/test10_question_8.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7809, 6157, 8, 'How much do you charge for carpet cleaning?', 'At least twice a year.', 'There are mud stains near the entrance.', 'It depends on the size of the space.', NULL, 'C', 'Câu hỏi: Bạn tính phí bao nhiêu cho việc vệ sinh thảm?"
A: "Ít nhất hai lần một năm."
B: "Có những vết bùn gần cửa ra vào."
C: "Phí tùy thuộc vào kích thước không gian."
Giải thích: Đáp án C đúng vì câu hỏi về giá cả dịch vụ vệ sinh thảm và đáp án C cho biết phí sẽ thay đổi tùy thuộc vào kích thước không gian."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6158, 275, '2025/test10/audio/test10_question_9.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7810, 6158, 9, 'Do you want to try those shoes on?', 'An upcoming hike.', 'No, I''m just looking.', 'I''ll have the lunch special.', NULL, 'B', 'Câu hỏi: Bạn có muốn thử đôi giày đó không?"
A: "Một chuyến đi bộ sắp tới."
B: "Không, tôi chỉ đang nhìn thôi."
C: "Tôi sẽ gọi món đặc biệt cho bữa trưa."
Giải thích: Đáp án B đúng vì câu hỏi là về thử giày và đáp án B trả lời rằng người hỏi chỉ đang nhìn mà không có ý định thử giày."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6159, 275, '2025/test10/audio/test10_question_10.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7811, 6159, 10, 'Who can I talk to about home financing?', 'No, I don''t have a finance degree.', 'Very competitive interest rates.', 'One of our loan officers.', NULL, 'C', 'Câu hỏi: Tôi có thể nói chuyện với ai về tài chính nhà ở?"
A: "Không, tôi không có bằng tài chính."
B: "Lãi suất rất cạnh tranh."
C: "Một trong các nhân viên cho vay của chúng tôi."
Giải thích: Đáp án C đúng vì câu hỏi về tài chính nhà ở và đáp án C chỉ ra rằng có thể nói chuyện với một nhân viên cho vay."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6160, 275, '2025/test10/audio/test10_question_11.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7812, 6160, 11, 'What should I do with these bottles of water?', 'Put one in front of each chair.', 'A decorative water fountain.', 'That''s OK-these plants are fake.', NULL, 'A', 'Câu hỏi: Tôi nên làm gì với những chai nước này?"
A: "Đặt một chai ở mỗi ghế."
B: "Một đài phun nước trang trí."
C: "Không sao, những cây này là giả."
Giải thích: Đáp án A đúng vì câu hỏi về cách xử lý chai nước và đáp án A đề xuất đặt một chai ở mỗi ghế."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6161, 275, '2025/test10/audio/test10_question_12.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7813, 6161, 12, 'How was the basketball game?', 'I see why it''s such a popular sport.', 'The outdoor courts at Campbell Park.', 'That sounds fun, thanks.', NULL, 'A', 'Câu hỏi: Trận đấu bóng rổ như thế nào?"
A: "Tôi hiểu tại sao nó lại là một môn thể thao phổ biến như vậy."
B: "Các sân ngoài trời ở Campbell Park."
C: "Nghe có vẻ vui, cảm ơn."
Giải thích: Đáp án A đúng vì câu hỏi về trận bóng rổ và đáp án A nói rằng người trả lời hiểu được lý do môn thể thao này rất phổ biến."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6162, 275, '2025/test10/audio/test10_question_13.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7814, 6162, 13, 'The conference runs through Sunday, doesn''t it?', 'The organizing committee.', 'No, it ends on Saturday.', 'I prefer cycling to running.', NULL, 'B', 'Câu hỏi: Hội nghị này kéo dài đến Chủ nhật, phải không?"
A: "Ủy ban tổ chức."
B: "Không, nó kết thúc vào thứ Bảy."
C: "Tôi thích đạp xe hơn chạy bộ."
Giải thích: Đáp án B đúng vì câu hỏi về thời gian kết thúc của hội nghị và đáp án B xác nhận hội nghị kết thúc vào thứ Bảy."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6163, 275, '2025/test10/audio/test10_question_14.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7815, 6163, 14, 'Why is the elevator blocked off?', 'For some maintenance work.', 'On the eleventh floor.', 'Sorry, it''s farther than I thought.', NULL, 'A', 'Câu hỏi: Tại sao thang máy bị chặn?"
A: "Vì công việc bảo trì."
B: "Ở tầng mười một."
C: "Xin lỗi, nó xa hơn tôi nghĩ."
Giải thích: Đáp án A đúng vì câu hỏi về lý do thang máy bị chặn và đáp án A đưa ra lý do là công việc bảo trì."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6164, 275, '2025/test10/audio/test10_question_15.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7816, 6164, 15, 'Where can I buy a pair of wireless headphones?', 'I get my produce at the farmers market.', 'She usually calls my mobile phone.', 'Jameson Electronics sells them.', NULL, 'C', 'Câu hỏi: Tôi có thể mua tai nghe không dây ở đâu?"
A: "Tôi mua thực phẩm tại chợ nông sản."
B: "Cô ấy thường gọi vào điện thoại di động của tôi."
C: "Jameson Electronics bán chúng."
Giải thích: Đáp án C đúng vì câu hỏi về việc mua tai nghe không dây và đáp án C cung cấp địa điểm nơi bán chúng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6165, 275, '2025/test10/audio/test10_question_16.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7817, 6165, 16, 'I can just submit my expense report next week, right?', 'I can save a couple for you.', 'Yes, but your reimbursement will take longer.', 'No, it''s going to be on your left.', NULL, 'B', 'Câu hỏi: Tôi có thể nộp báo cáo chi tiêu của mình vào tuần sau được không?"
A: "Tôi có thể tiết kiệm vài cái cho bạn."
B: "Vâng, nhưng khoản hoàn trả của bạn sẽ mất nhiều thời gian hơn."
C: "Không, nó sẽ ở bên trái bạn."
Giải thích: Đáp án B đúng vì câu hỏi về việc nộp báo cáo và đáp án B xác nhận có thể nộp nhưng sẽ mất thời gian lâu hơn để hoàn trả."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6166, 275, '2025/test10/audio/test10_question_17.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7818, 6166, 17, 'Are you looking for a part-time or full-time position?', 'I can only work twenty hours per week.', 'Right, a new physician.', 'There''s a clock on the back wall.', NULL, 'A', 'Câu hỏi: Bạn đang tìm kiếm công việc bán thời gian hay toàn thời gian?"
A: "Tôi chỉ có thể làm việc hai mươi giờ mỗi tuần."
B: "Đúng rồi, một bác sĩ mới."
C: "Có một chiếc đồng hồ ở phía sau tường."
Giải thích: Đáp án A đúng vì câu hỏi về loại công việc và đáp án A cho biết người trả lời có thể làm việc bán thời gian."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6167, 275, '2025/test10/audio/test10_question_18.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7819, 6167, 18, 'Can you help me change my log-on password?', 'The corporate account.', 'Sorry, I have to call a client back.', 'Don''t worry-I''m sure you passed.', NULL, 'B', 'Câu hỏi: Bạn có thể giúp tôi thay đổi mật khẩu đăng nhập không?"
A: "Tài khoản công ty."
B: "Xin lỗi, tôi phải gọi lại cho khách hàng."
C: "Đừng lo, tôi chắc là bạn đã vượt qua."
Giải thích: Đáp án B đúng vì câu hỏi về thay đổi mật khẩu và đáp án B cho biết người trả lời phải gọi lại cho khách hàng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6168, 275, '2025/test10/audio/test10_question_19.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7820, 6168, 19, 'Why are we being required to use new scheduling software?', 'Management hasn''t explained the decision yet.', 'OK, I''ll make sure I have the updated version.', 'The activation code is on the receipt.', NULL, 'A', 'Câu hỏi: Tại sao chúng ta phải sử dụng phần mềm lên lịch mới?"
A: "Ban giám đốc vẫn chưa giải thích quyết định."
B: "Được rồi, tôi sẽ đảm bảo tôi có phiên bản cập nhật."
C: "Mã kích hoạt nằm trên biên lai."
Giải thích: Đáp án A đúng vì câu hỏi về lý do sử dụng phần mềm mới và đáp án A cho biết ban giám đốc vẫn chưa giải thích lý do."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6169, 275, '2025/test10/audio/test10_question_20.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7821, 6169, 20, 'Which brand makes the best washing machines?', 'No, they''re manufactured abroad.', 'Yeh-Joon is the appliance expert.', 'The hotel offers laundry services.', NULL, 'B', 'Câu hỏi: Hãng nào sản xuất máy giặt tốt nhất?"
A: "Không, chúng được sản xuất ở nước ngoài."
B: "Yeh-Joon là chuyên gia về thiết bị gia dụng."
C: "Khách sạn cung cấp dịch vụ giặt là."
Giải thích: Đáp án B đúng vì câu hỏi về thương hiệu máy giặt và đáp án B chỉ ra rằng Yeh-Joon là chuyên gia về thiết bị gia dụng, nên sẽ biết thương hiệu tốt."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6170, 275, '2025/test10/audio/test10_question_21.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7822, 6170, 21, 'Don''t you have any apartments available in the next month?', 'Yes, she''s taking some time off.', 'On a shelf in the storage room.', 'No, none of our current leases end that soon.', NULL, 'C', 'Câu hỏi: Bạn có căn hộ nào trống trong tháng tới không?"
A: "Vâng, cô ấy đang nghỉ phép một chút."
B: "Trên kệ trong phòng lưu trữ."
C: "Không, không có hợp đồng nào hết hạn sớm như vậy."
Giải thích: Đáp án C đúng vì câu hỏi về căn hộ trống và đáp án C cho biết không có hợp đồng nào hết hạn trong tháng tới."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6171, 275, '2025/test10/audio/test10_question_22.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7823, 6171, 22, 'I left my umbrella in the taxi!', 'The tax isn''t included.', 'He''s planning to rent a car.', 'We have extras at the office.', NULL, 'C', 'Câu hỏi: Tôi để quên dù trong taxi!"
A: "Thuế không bao gồm."
B: "Anh ấy định thuê xe."
C: "Chúng tôi có dù dự phòng tại văn phòng."
Giải thích: Đáp án C đúng vì câu hỏi về việc để quên dù và đáp án C cho biết văn phòng có dù dự phòng."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6172, 275, '2025/test10/audio/test10_question_23.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7824, 6172, 23, 'When can we expect the contest winners to be announced?', 'A professional announcer.', 'The judging is in its final stages.', 'I always bring my own.', NULL, 'B', 'Câu hỏi: Khi nào chúng ta có thể mong đợi người chiến thắng cuộc thi được công bố?"
A: "Một người thông báo chuyên nghiệp."
B: "Cuộc thi đang ở giai đoạn chấm điểm cuối cùng."
C: "Tôi luôn mang theo của mình."
Giải thích: Đáp án B đúng vì câu hỏi về thời gian công bố người chiến thắng và đáp án B cho biết cuộc thi đang ở giai đoạn chấm điểm cuối."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6173, 275, '2025/test10/audio/test10_question_24.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7825, 6173, 24, 'Where do we put old ink cartridges?', 'Tom just left for the recycling center.', 'Every three months.', 'Sure, you can put in a request.', NULL, 'A', 'Câu hỏi: Chúng ta để các hộp mực cũ ở đâu?"
A: "Tom vừa rời đi để đến trung tâm tái chế."
B: "Mỗi ba tháng."
C: "Chắc chắn, bạn có thể yêu cầu."
Giải thích: Đáp án A đúng vì câu hỏi về nơi bỏ hộp mực cũ và đáp án A chỉ ra rằng Tom đã đi đến trung tâm tái chế."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6174, 275, '2025/test10/audio/test10_question_25.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7826, 6174, 25, 'We should consider replacing our packaging machine.', 'I already printed the welcome packets.', 'All of our recyclable waste.', 'The repairs are getting more expensive.', NULL, 'C', 'Câu hỏi: Chúng ta nên xem xét thay thế máy đóng gói của mình." 
A: "Tôi đã in các gói chào mừng."
B: "Tất cả các loại rác thải có thể tái chế của chúng tôi."
C: "Việc sửa chữa đang trở nên đắt đỏ hơn."
Giải thích: Đáp án C đúng vì câu hỏi về việc thay thế máy và đáp án C nói rằng việc sửa chữa đang ngày càng tốn kém."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6175, 275, '2025/test10/audio/test10_question_26.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7827, 6175, 26, 'Will my account be suspended if I use my credit card abroad?', 'Have you reactivated your phone service?', 'Not if you let us know about your trip in advance.', 'You can view your credit card bill on our Web site.', NULL, 'B', 'Câu hỏi: Tài khoản của tôi có bị đình chỉ nếu tôi sử dụng thẻ tín dụng ở nước ngoài không?"
A: "Bạn đã kích hoạt lại dịch vụ điện thoại của mình chưa?"
B: "Không nếu bạn thông báo chuyến đi của mình trước."
C: "Bạn có thể xem hóa đơn thẻ tín dụng trên trang web của chúng tôi."
Giải thích: Đáp án B đúng vì câu hỏi về việc sử dụng thẻ tín dụng ở nước ngoài và đáp án B xác nhận rằng nếu thông báo trước chuyến đi, tài khoản sẽ không bị đình chỉ."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6176, 275, '2025/test10/audio/test10_question_27.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7828, 6176, 27, 'Aren''t you going to attend the database training?', 'The database administrator.', 'I missed the registration deadline.', 'I thought you didn''t like taking the train.', NULL, 'B', 'Câu hỏi: Bạn không tham gia khóa đào tạo cơ sở dữ liệu sao?"
A: "Quản trị viên cơ sở dữ liệu."
B: "Tôi đã bỏ lỡ hạn đăng ký."
C: "Tôi nghĩ bạn không thích đi tàu."
Giải thích: Đáp án B đúng vì câu hỏi về việc tham gia đào tạo và đáp án B cho biết người trả lời đã bỏ lỡ hạn đăng ký."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6177, 275, '2025/test10/audio/test10_question_28.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7829, 6177, 28, 'Can you send me the budget proposal for the relocation?', 'The disposable cups cost much less.', 'Are there other locations?', 'It should be in your inbox.', NULL, 'C', 'Câu hỏi: Bạn có thể gửi cho tôi đề xuất ngân sách cho việc di dời không?"
A: "Những cốc dùng một lần rẻ hơn nhiều."
B: "Có những địa điểm khác không?"
C: "Nó nên có trong hộp thư đến của bạn."
Giải thích: Đáp án C đúng vì câu hỏi yêu cầu đề xuất ngân sách và đáp án C chỉ ra rằng người trả lời nên đã gửi tài liệu qua email."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6178, 275, '2025/test10/audio/test10_question_29.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7830, 6178, 29, 'Do you want to hold the focus group meetings this week or next week?', 'Samples of each product.', 'There''s no reason to wait.', 'The third-floor conference room.', NULL, 'B', 'Câu hỏi: Bạn muốn tổ chức các cuộc họp nhóm tập trung vào tuần này hay tuần sau?"
A: "Mẫu của mỗi sản phẩm."
B: "Không có lý do gì để chờ đợi."
C: "Phòng hội nghị ở tầng ba."
Giải thích: Đáp án B đúng vì câu hỏi về thời gian họp và đáp án B nói rằng không cần phải chờ đợi, ám chỉ họ có thể tổ chức ngay."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6179, 275, '2025/test10/audio/test10_question_30.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7831, 6179, 30, 'Who was the graphic designer for the event T-shirts?', 'For the staff or attendees?', 'We signed the agreement.', 'That''s a lot of exhibitors.', NULL, 'A', 'Câu hỏi: Ai là nhà thiết kế đồ họa cho áo phông sự kiện?"
A: "Dành cho nhân viên hay người tham gia?"
B: "Chúng tôi đã ký hợp đồng."
C: "Đó là rất nhiều nhà triển lãm."
Giải thích: Đáp án A đúng vì câu hỏi hỏi về người thiết kế áo phông cho sự kiện và đáp án A hỏi về người thiết kế cho nhân viên hay người tham gia."');;
INSERT INTO question_groups (id, test_part_id, audio_url, image_url, passage_text, transcript) VALUES (6180, 275, '2025/test10/audio/test10_question_31.mp3', NULL, NULL, NULL);;
INSERT INTO questions (id, question_group_id, question_number, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES (7832, 6180, 31, 'It''s a long drive to the convention center from here.', 'No, it''s hosting an award ceremony.', 'I prefer to save my files to a hard drive.', 'We can use the time to discuss our presentation.', NULL, 'C', 'Câu hỏi: Đây là một chuyến đi dài đến trung tâm hội nghị từ đây." 
A: "Không, trung tâm đang tổ chức lễ trao giải."
B: "Tôi thích lưu trữ các tệp của mình vào ổ cứng."
C: "Chúng ta có thể sử dụng thời gian để thảo luận về bài thuyết trình của mình."
Giải thích: Đáp án C đúng vì câu hỏi về việc đi đến trung tâm hội nghị và đáp án C đưa ra một cách sử dụng thời gian hiệu quả để thảo luận."');;

